INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yatısı', 'gece-yatisi-ethem-vayvayli-ic5bn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamanında dağların ıslak yamacında

Taşları yastık eder gece yatısında

Düşlere yorgan olur koyun ardıcı da

Yıldızlarla mehtaba uçuşur giderdik

Gözlerimiz ağustosa aşık misali

Bağrımıza dökülür yıldızların vebali

Dokunur dudaklarımıza ıslak zerdali

Hasretine yanarak tutuşur giderdik

Çobanlarla sürüleri bir ederdik

Patates gömer küle, sütten içerdik

Ayın ışığında taşa taş dikerdik

Loçiye takılır kırılır giderdik

Hafiften uyku inerse göz önüne

Sarardı koyunlar bizi ak yününe

Yükü binince gecenin kuşluk dengine

Dökülür yollara toz olur giderdik

Çeketi atardık çadırın yanına

mavi çaydanlıklarda nane çayıyla

Ekmeği banardık yoğurdun yağına

Ekini biçmeye gülüşür giderdik

Gayri gurbette konuşuruz bunları

Buram buram kokar memleket bağları

Aşamaz olmuşuz yufka çığırları

Dam boyu karlarla kapışır giderdik

(30 Eylül ''96, İstanbul)', 'Zamanında dağların ıslak yamacında Taşları yastık eder gece yatısında Düşlere yorgan olur koyun ardıcı da Yıldızlarla mehtaba uçuşur giderdi...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gece-yatisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin Gelmeyişi Ağlatır Beni', 'sesin-gelmeyisi-aglatir-beni-ethem-vayvayli-22gen', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sinede bir duygu dağlatır beni

Sesin gelmeyişi ağlatır beni

Tutsak ellerimden kesecekler beni

Prangalı ayağıma kapanır ağlarım

Gelip kapıma dayandıklarından beri

Kollarıma kelepçe taktıklarından beri

Gözlerini gözlerime dikdiklerinden beri

Kanayan bileklerime yaslanır ağlarım

Gözlerim yoruldu yoluna bakmaktan

Gelmediğim dünyaya geldiğim andan

Sarardı sonbaharım habersiz hazandan

Dökülen yapraklara bakar ağlarım

Nazlı nazlı gül goncaya dönünce

kapılarında gamlı horozlar ötünce

Ocağı da duman duman tütünce

Çıkar pencereye seyreder ağlarım

Son gecede dileğini al yanımdan

Kim umut bekler bilmem Vayvaylı''dan

Çekip omuzlarımı hücre duvarından

Gözgöze gelince dayanamaz ağlarım

(12 Mart ''94, Konya)', 'Sinede bir duygu dağlatır beni Sesin gelmeyişi ağlatır beni Tutsak ellerimden kesecekler beni Prangalı ayağıma kapanır ağlarım Gelip kapıma ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sesin-gelmeyisi-aglatir-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Ayrılık', 'zor-ayrilik-ethem-vayvayli-bg2hw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daracık bir andı

Bir kapı önü

Vurdun açtın sen 

Bizim kapımızı

Bir ömür geçti

Güzel aşkınla

Seni alıp gittiler

Ağladım ardından

Sordum dostlara

Gelmedi dediler

Senden başkasını

Sevmedi dediler

Döküldü duvardan

Bütün resimler

N''eyleyim sevdimse

Suçum bu mu benim? 

(Bahar 2000, Ankara)', 'Daracık bir andı Bir kapı önü Vurdun açtın sen  Bizim kapımızı Bir ömür geçti Güzel aşkınla Seni alıp gittiler Ağladım ardından Sordum dostl...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zor-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Sensizim', 'seninle-sensizim-gunes-kara-mkwzg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adını taşlara yazdım

Hergün geçtiğim yollarda

Gecelerboyu sabahladığımda

Yapayalnız sensiz

Sessiz ve ağlamaklı

Pencereden baktığımda

Karşımda duran SEN''i

Unutamıyorum...

Resmini aklıma çizdim

Aynaya her baktığımda

Senin hayalin durur karşımda

Ellerimi uzatıp dokunmak isterim

Ulaşmam mümkün olmadan

Ellerim buz gibi cama dokunurken

Uzaklaşıp giden SEN''i

Unutamıyorum....

Kalbimi sevginle doldurdum

Bir pınar gibi taştığında

Hasretin bir çığ gibi büyür

Sen her aklıma geldiğinde

Aramak isteyipte arayamadığım

Hasretinle yanıp tutuştuğum

Sesini delice duymak istediğim SEN''i

Unutamıyorum...

Rüyalarıma seni koydum

Uykusuz geçen gecelerin ardından

Yorgun düşüp uyuduğumda

Bir sen varsın, birde hasretin

Gelmeni çok istediğimde

Sürpriz yapıp geleceğini

Tekrar göreceğimi düşlediğim SEN''i

Unutamıyorum....', 'Adını taşlara yazdım Hergün geçtiğim yollarda Gecelerboyu sabahladığımda Yapayalnız sensiz Sessiz ve ağlamaklı Pencereden baktığımda Karşımd...', ARRAY['Türk Edebiyatı','Şiir','Güneş Kara']::text[], 8.5, '{"poet":"Güneş Kara","poet_slug":"gunes-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/seninle-sensizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Av Sonrası İtibarımız', 'av-sonrasi-i-tibarimiz-ethem-vayvayli-9gubc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tundra iklim toprakları gibi

Dudaklarımızda kalan itibar

Sineye çekilen üç-dört yaşlarında

Bir çocuktu hayatımızdaki kar

Memleket yollarından ırayan

Çıplak sırtların ak entarisi kar

Üzerinde tavşan izleri

Ömrü bitiren acı intihar

Uzayınca dağlara tüfek sesleri

Ardıç altlarına düşer üveyk kuşları

Göle değmiş iplik gibi titretir yeri

Kara serilen mermi kovanları

Omuzlardan sızar tavşan kanları

Filelerde yaban ördekleri, göl kuşları

Ve sürer gider hayata inhirâm

Dağların aklında kalır genç adamlar

Her dalına beyaz şapka takılır çamların

Hetik ihtilaliyle kapanır tavşan izleri

Kurşunlarla oynaşır kuş tüyleri

Baharla gelir dağlara istiklâl

Sönmüş ne anlamı var eski hayatın

Her güz göle döküler hürmüz ışıklar

Dizlere kadar kar, adam boyu gam

Ilık bir kanla alınır hayattan intikâm

Her av sonrasında

Avucuma toplanır bütün avcılar

Tundra iklim toprakları gibi

Dudaklarında kalan itibar

(27 Temmuz ''97, Göksun)', 'Tundra iklim toprakları gibi Dudaklarımızda kalan itibar Sineye çekilen üç-dört yaşlarında Bir çocuktu hayatımızdaki kar Memleket yollarında...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/av-sonrasi-itibarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutursun! Deyişine', 'unutursun-deyisine-nurullah-genc-qx0zb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Unutursun! ” deyişine

unutmak, yıldızların ciğerine saplanan

bir lâle yaprağına gömmektir sevgiliyi

unutmak, bir kaktüsün küllerinde ansızın

alevli bir tapınak eylemektir sevgiyi

unutmak, semendere zehir sunmaktır, gülüm

taş dolu yüreklerin lügatinde bulursun

unutmak, sessizliğe yine kanmaktır, gülüm

unutulursa şair, sen de unutulursun

bir dağın bir kuyuya tıhum ektiği yerde

balığın yüzgecinden irin döktüğü yerde

kralın, kölelerin emrinde yürüdüğü

geminin bir köpükte okyanus aradığı

ay’ın arzı terkedip gökte durduğu ândaa

serseri bir kurşunun ay’ı vurduğu ânda

başını ellerinin arasına al ve dur

işte o lahza gülüm, bu can seni unutur

unutmak, bir saatin kırılan camlarında

zamanı çürüterek öldürmektir sevgiyi

unutmak, bayramlığı giydirilen çocuğun

aldatılan göğsünde vurmaktır sevgiliyi

unutmak, bir ülkenin tozlu kaldırımlarında

taşlara boğdurmaktır yağız atlı yiğidi

unutmak, susturmaktır yolların ayrımında

şairlere can veren muhteşem bir ağıdı

unutmak, koparmaktır çiçekleri dalından

sisli bir yalnızlığın ekseninde bulursun

unutmak, ayırmaktır arıları balından

unutulursa şair, sen de unutulursun', '“Unutursun! ” deyişine unutmak, yıldızların ciğerine saplanan bir lâle yaprağına gömmektir sevgiliyi unutmak, bir kaktüsün küllerinde ansızı...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/unutursun-deyisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım oğlum', 'canim-oglum-gunes-kara-28hff', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyaya geldiğinde

Mutluluğun tadını tattıran

El bebek, gül bebek büyüttüğüm

Canım, canım oğlum benim

Yüreğimden bir parçasın

Gurbet aldı götürdü seni

Yuvamızdan uçtun gittin

Canım, canım oğlum benim

Bir yıl daha geçti  gideli

Uçağa binip gittiğinde

İçimden bir şey koptu sanki

Canım, canım oğlum benim

Uzaklardan sesini duyduğumda

Özlemin daha da büyür

Gelmeni beklediğim

Canım, canım oğlum benim', 'Dünyaya geldiğinde Mutluluğun tadını tattıran El bebek, gül bebek büyüttüğüm Canım, canım oğlum benim Yüreğimden bir parçasın Gurbet aldı gö...', ARRAY['Türk Edebiyatı','Şiir','Güneş Kara']::text[], 8.5, '{"poet":"Güneş Kara","poet_slug":"gunes-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canim-oglum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-ethem-vayvayli-6en11', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elâ gözlerinde büyüyen figürânın

Bir temaşâlık suya düşmez mi? 

Seyrini eyledim başında turnanın

Bir de bizim ellerden gelip geçmez mi? 

Çıngılı eskalarda yanarken ateşim

Dumanı uzardı kara ardıçlığa

Hasretin elinde geldi dönme haberim

Özlemle birlikte varsam kocaoluğa

Biter mi dağlarında kınalı kekliğin

Olmadı gönlünü benden esirgediğin

Düğünyurdun, dölekyazın, ağgediğin

Bir temaşalık suya düşmez mi? 

(24 Ağustos ''97, KÇ)', 'Elâ gözlerinde büyüyen figürânın Bir temaşâlık suya düşmez mi?  Seyrini eyledim başında turnanın Bir de bizim ellerden gelip geçmez mi?  Çın...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/memleketim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendisine', 'kendisine-nurullah-genc-vg17x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendisine

Sen ey şehrin yerlisi, cesur, kararlı mühür

Sen ey inatçi kıskanç, alçak gönüllü ve hür

Karanlık geceleri korkutsa da günahım

Kızlar Kayası gibi dikilip kaldı âhım

Sefere çıkanların tatlı rüyâsı mısın

Rûhumun cellâdı mı, yoksa hülyâsı mısın

Konuşursun, sözlerin dâre çeker canımı

Susarsın, çâresizlik büyütür isyânımı

Siyaha boyanınca, kanatlanır mı yürek

Hangi harfin başını beliyor şimdi melek

Kasîde, hangi şehrin âşiyânında güzel

Bulutlu havalarda parlayan aydır gazel

Yine mest, yine sarhoş bahçendeki mumyalar

Canlanıyor taşların kalbinde sardunyalar

Fildişinden heykel mi taşıyorsun elinde

Yine bir raksın mumu yanıyor gözlerinde

En hâkî denizini verdim sana ömrümün

Dilediğince yıkan sularında gönlümün

Sürmek mi istiyorsun masal arabasını

Getireyim kapına devlerin en hasını

Ölümsüz meyvesini sundum hayal bağının

Dehâsında bulmuşum seni yalnızlığımın

Celî bir kavis miydin, sokuldun yüreğime

Hattı hümayununla sultan oldun evime

Hendeseyi titretir endâmın ley-ü nehâr

Bu aşkı destan gibi yazıyor fırtınalar

Yüzündeki çizgiler kûfî midir sülüs mü

Aradığın define İrem mi Endülüs mü

Sen ey yardım sevenim, ruhumu derde saldın

Yalnızlığım ağlarken gülenim, nerde kaldın

Azimli bir yüreğin yorgun kimyasın da mı

Sevda denklemlerinin memnû dünyasında mı

Her pazartesi âhım kapında helâk olur

Her Cuma karanlığın kuşları leylâk olur

Kâşifin benim gülüm, görmediğin yine ben

Bilseydin sana benden bakanı görünmeden

Anlardın; her macera tende rü’yet gibidir

Oysa sende gördüğüm, sana gurbet gibidir

Utangaç bir merhamet saklıyorsun sesinde

Sahraya dönüyorum baharın ötesinde

Gizlice bir nikahtır o arzuhal, o kâmet

Sensizlik, yollarımda bir değil, bin kıyamet

Bu tebessüm rüya mı, bu istifham uğru mu

Âh bir çoğaltabilsem yüreğinde ruhumu

Bilmezsin ayrılığın ağı kokan dilini

Hâtıra bırak bana oyalı mendilini

Ege uygarlığı çağrıştıran tarihin

Asya’nın bağrı kadar muammalı ve derin

Arı sütü damlarken kaygan kirpiklerinden

Görünmez bir mürekkep akar iliklerinden

Yüreğin, âh yüreğin bir hüzün lâlesi mi

Masallar ülkesinde Zengibar kalesi mi

Kapısına bir türlü varamadım, a gülüm

Hudutlarında bile duramadım, a gülüm

İpeğimi elimden aldı pusathâneler

Bulamaz kaybedilen nûn’u rasathaneler

Hummalı bir kovanda bal yapan arı mısın

Hayatımın ansızın kopan damarı mısın

Paslandı buzdağları ortasında çeliğim

Gözlerinden hatıra kaldı kekemeliğim

Kervanında kaybolan bir bezirgân gibiyim

Kaktüslerin diline düşen figân gibiyim

Her köşede bir meddâh anlatıyor âhımı

Bilmiyor, kirpiğinden almışım siyahımı

Uğrunda, kralların bahtı solsaydı, gülüm

Amerika, yolunda kurban olsaydı, gülüm

Bir Kafkas figüründe bulurdum son izini

Efeler diyârına çevirirdim yüzünü

Eşkıyâ vurgunudur seni benden ayırmak

Çalıkuşunu yakan bir rüyayı haykırmak

Gölgelere gecenin künhünü hatırlatır

Ayrılıklar bazen de gölgeleri ağlatır

Sükûnla savaşıyor hislerim kıyasıya

Sevdiğini bilirim uykuyu doyasıya

Süslenmek istiyorsan, ruhumu boynuna tak

Bu firûze özgürlük yalnız senin olacak

Bastığın her hücremde otuz sekiz çizgi var

Baktığım her duruşun muammalı bir duvar

Suskunluğun taş gibi, gülüşün berrak değil

Neden vivien kokar baharın, leylâk değil

Gözlerin bir zamanlar toprağın sahibiydi

Bakışların bir tutam gül yaprağı gibiydi

İnsanlar kıvranırken ejderlerin ağında

Ceylan gibi yürürdün bir hayal sokağında

Yine de, yokluğumun em şüpheli çağıydın

Tenhâlarda ağlayan bir okul kaçağıydın

Karanlık korkutamaz gülüm seni, vururum

Kâtil yüzlü cinlerin karşısında dururum

Yeter ki, o nâzenîn kalbin emir buyursun

Kâinat yıkılsa da yüreğimde uyursun', 'Kendisine Sen ey şehrin yerlisi, cesur, kararlı mühür Sen ey inatçi kıskanç, alçak gönüllü ve hür Karanlık geceleri korkutsa da günahım Kızl...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/kendisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Kuşları', 'gonlumun-kuslari-ethem-vayvayli-t1z3z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlümün akşamında büyüyen ışıltılar

Bir köy çobanının getirdiği mantuvardı

Yanımda babamdan kalan martılar

Annem için gürbüz bülbüller şakırdı

Gönlüm uzardı aşkın yaylasından uzaklara

Gölgesi fistan olurdu orman kulelerinin

Yangın öncesi yonca ekilen tarlalara

Yorgun kırlangıçlar hergün konardı

Gönlüm uçardı al-beyaz kanatlarında

Aşkı taşıyan palaz kekliklerinin

Sepelenirdi yağmur mor dudaklarına

Gözlerimi uykuya gövel ördek kapardı', 'Gönlümün akşamında büyüyen ışıltılar Bir köy çobanının getirdiği mantuvardı Yanımda babamdan kalan martılar Annem için gürbüz bülbüller şakı...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonlumun-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün Yılları', 'surgun-yillari-ethem-vayvayli-1zhsb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdilik burdayız memleket için

Zamanı gelirse çekeriz halayı

Biz çayını içerken mavi demliğin

Abdallar vurur oturak havayı

Sevdamı sakladım ardıç kovuğuna

Yaramı bıraktım kamalk sakızına

Sazımı uzattım şeytanın kızına

Bu memlekette, bu memlekette

(28 Ağustos ''97)', 'Şimdilik burdayız memleket için Zamanı gelirse çekeriz halayı Biz çayını içerken mavi demliğin Abdallar vurur oturak havayı Sevdamı sakladım...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/surgun-yillari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toroslar''da Beklenen Yağmurlar', 'toroslar-da-beklenen-yagmurlar-ethem-vayvayli-t63wl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur ne taraftan gelse iyidir

Orta Akdeniz Balkanlar...

Nerde bir ceylan sesi duysam

Yüreğimin orasıdır Toroslar

Kıvrım kırık derelerinde

Üç yaban ördeği gezer

Üç sıkımlık barutum olsa

Bir zıkımlık aşk getirseler

Derin şarlakların dibinden

Seyhan''a ulanan ırmakların birinden

Yağmur ne taraftan gelirse gelsin

Mazgaç''ın başlarında gezerim

Hep yanımdaydı parkem, börküm

Ateş üstünde kaynardı yüreğim

Böğürtlenlerle yanyana

Her sabah köylülerle

Kınalıyı, taşgözağını aşardım

Hatırladığım yarımsalı, çilpiliyi

Bir yol bağlamazdı karadağa

Ben bu ucundayım Toroslar''ın

Yağmur ne taraftan gelse iyidir

Orta Akdeniz Balkanlar...

Kersen çadırımın müstâkbel yeridir

Yüreğim ne ıslanır ne yanar

Bir ocak üstünde kaynar da kaynar

(03 Eylül ''97, İstanbul)', 'Yağmur ne taraftan gelse iyidir Orta Akdeniz Balkanlar... Nerde bir ceylan sesi duysam Yüreğimin orasıdır Toroslar Kıvrım kırık derelerinde ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/toroslar-da-beklenen-yagmurlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadığım Zaman', 'yasadigim-zaman-ethem-vayvayli-yo19q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin alacan içine gizlenmiş

Nerde, ne zaman

Uyurken kumsalda karıncalar

Çıkarıverir de atarsın sakladıklarını

Işmar etme de ankadan sana kalmış

Zincire vurulu harflerle kurduğun kaosta

Cep boyu bir aynada sırra dalarken

Masmavi gökyüzü özlüyorum diye diye

Nasılda satıyordun bizi karanlıklara

Özgür fantazilerin bileklerinden tutarak

Boşanmış teyyarelerin kanadından

Bir gemiye dolarak gelmiştin kumsala

Nasıl da bahsetmiştin kuşlardan

Hala sakladığın yakut taşın altında

Yetmiş ele rastlasam ve alsam

Kanayan dudaklarımıza ankadan

Arta kalır mı manefesto sadakati

Ve gelip geçerken Vezneciler^''de

Aldığım bütün otobüslerin saati

Toplar mı hayatı bu ince defterde

Gezerdim sokaklarında, kıyı uçlarında

Çırpıntı götürmez yüreğimde hafakanlar

Badire çarpıklıklarla şehir şahir

insan mı, tapınak mı, bir hercâi

Hayvanlar aleminden çıkrık sesi eşliğinde

Bir suluboya tablosunda serçeler

Gözleri sürmeli anız güvercinleri

Hepsininde alacası tüylerini süsler

Ama neyleyim yaşadığım zaman

Senin alacan içine gizlenmiş

(05 Eylül ''97, İstanbul)', 'Senin alacan içine gizlenmiş Nerde, ne zaman Uyurken kumsalda karıncalar Çıkarıverir de atarsın sakladıklarını Işmar etme de ankadan sana ka...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yasadigim-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Günü', 'guz-gunu-ethem-vayvayli-f4lix', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi mevsim güze sarktı

Kırağı üçgülü kapattı

Benden sana uçar gider

Yapraklar da yele kaldı

Bahçelerde sır çocuklar

Ceviz karaltıda tavlar

Uzar da uzar geceler

İtler yokluğuna havlar

Bir boğunak yağmur çöker

Leylekler denizi geçer

Bizlere de gitmek düşer

Ela gözler hasret çeker

(15 Eylül ''97, İstanbul)', 'Şimdi mevsim güze sarktı Kırağı üçgülü kapattı Benden sana uçar gider Yapraklar da yele kaldı Bahçelerde sır çocuklar Ceviz karaltıda tavlar...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/guz-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tırpan Köşkündeki Güneş', 'tirpan-koskundeki-gunes-ethem-vayvayli-grf70', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinde gevelenen ölümde kaldım

Elâdan siyaha dönen fırtına benimkisi

Bir metre denizde avlanan balıkçı.

Yüreğim var yaşamak arzuhalinde

Tırnaklarında terkettiğim toprağın

Bir tırpan köşkü üzerinde oturan

Güneşi konuşmuştu dudakları

Çen çen bana ve bengisuya

Hasret doğan kalbimin çocukları

Elinde mürekep, ilmek ve yıldız

Beklerdi pınar başında kuşlarını

Çil kanatlarından sarkan bulut

Konaklarından boşalan söyleviydi kalbimin

İmbiklerinden dökülen kan pıhtısının

Özgülünden doğardı güneş

(08 Ekim ''97, İstanbul)', 'Gözlerinde gevelenen ölümde kaldım Elâdan siyaha dönen fırtına benimkisi Bir metre denizde avlanan balıkçı. Yüreğim var yaşamak arzuhalinde ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tirpan-koskundeki-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asuman Donanması', 'asuman-donanmasi-ethem-vayvayli-c3l0k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte yıkansa bu orman

Tarihin derinlik yağmurlarıyla

Yeniden yükselse asuman

Dağların ince ruhlaryla

...

***

Ebede sabırsız kaldık

Bir an evvel tüketsek rüyayı

Cebimize karşılıksız aldık

Asumandan aşkı ve hayayı

Ricat sesi dudağımızdaki

Götürülen Hallac''ın kelimeleri

Kızardı yanağımızdaki

Gök ve ateşin mor gülleri

...

***

Nemlendi hükümdarın dudağı

Barış çağırdı güvercinler

Göklerde sevginin adı

Tarih ne derin inler! 

(27 Aralık ''97, İst.)', 'İşte yıkansa bu orman Tarihin derinlik yağmurlarıyla Yeniden yükselse asuman Dağların ince ruhlaryla ... *** Ebede sabırsız kaldık Bir an ev...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/asuman-donanmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Dünya Bizimleydi', 'hani-dunya-bizimleydi-umit-akyildiz-3mimf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hani dünya bizimleydi, kol kanat olmuştu

hani sevda gönüllerimizde fidan olmuştu

hani dertler, gülüp geçerek yalan olmuştu

dünya değil mahfeden, gelecek korkularımız

masallardaki gibi başlamıştı sevdamız 

ellerimiz ayrılmaz, gözlerimiz yanar 

bir yığın dertle doldu, umutlu günlerimiz

güneş batmaz, yalan doğmaz, aşk yanar', 'hani dünya bizimleydi, kol kanat olmuştu hani sevda gönüllerimizde fidan olmuştu hani dertler, gülüp geçerek yalan olmuştu dünya değil mahfe...', ARRAY['Türk Edebiyatı','Şiir','Ümit Akyıldız']::text[], 8.5, '{"poet":"Ümit Akyıldız","poet_slug":"umit-akyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hani-dunya-bizimleydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Sakini', 'koy-sakini-mahmut-oflaz-jr6o4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya Köyününün

 ekvator mahallesinde

 oturuyorum

Kutuplardaki komşularıma 

her akşam pişirdiğim yemekten 

veriyorum

    2002Adapazarı', 'Dünya Köyününün  ekvator mahallesinde  oturuyorum Kutuplardaki komşularıma  her akşam pişirdiğim yemekten  veriyorum     2002Adapazarı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Oflaz']::text[], 8.5, '{"poet":"Mahmut Oflaz","poet_slug":"mahmut-oflaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/koy-sakini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sinek', 'kara-sinek-mahmut-oflaz-oeykn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.....Kara sinek

Döner durur etrafımda

gider gelir

birdaha birdaha

toslar.

2001Aydın', '.....Kara sinek Döner durur etrafımda gider gelir birdaha birdaha toslar. 2001Aydın...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Oflaz']::text[], 8.5, '{"poet":"Mahmut Oflaz","poet_slug":"mahmut-oflaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kara-sinek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar', 'kadinlar-sinan-yunak-eawmb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kızlar büyür kadın olur

kadınlar büyür aşık olur

beni sana aşık eden de kadınlardır

sen büyürsün beni terkedersin

şehir büyür bana ihanet eder

ben küçülme krizlerine girerim

duvarların boyalarını sökerim 

eskiye dönebilme umuduyla

büyümek sancılıdır

-yaşamak kadar ağır değilse de-

kızlar kadın olurken bir de

gözyaşların hediyedir geçmişe

uğruna o güzel kumral kızların

kadınların

(İstanbul 2002)', 'Kızlar büyür kadın olur kadınlar büyür aşık olur beni sana aşık eden de kadınlardır sen büyürsün beni terkedersin şehir büyür bana ihanet ed...', ARRAY['Türk Edebiyatı','Şiir','Sinan Yunak']::text[], 8.5, '{"poet":"Sinan Yunak","poet_slug":"sinan-yunak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kadinlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kitabı', 'ask-kitabi-ahmet-selcuk-i-lkan-sgt3e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne olur söyleyin sevenler bana

Ayrılmak kanun mu aşk kitabında

Elele tutuşup gülmeden daha

Terketmek kanun mu aşk kitabında

Ümitlerim kırıldı bitti

Hayallerim yıkıldı gitti

Bu dert beni benden etti

Sevdim sevdim bak ne hale geldim

Her seven sonunda düşüyor derde

Bu aşk kitabının yazanı nerde

Bir aşık inandı çok sevdi diye

Terketmek kanun mu aşk kitabında', 'Ne olur söyleyin sevenler bana Ayrılmak kanun mu aşk kitabında Elele tutuşup gülmeden daha Terketmek kanun mu aşk kitabında Ümitlerim kırıld...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-kitabi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Buradayım', 'senin-i-cin-buradayim-ahmet-selcuk-i-lkan-n1akt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde bir ümit var onun için burdayım, 

Belki gelirsin diye senin için burdayım

Vakit çok geç olsa da gönlüm mahzun kalsa da, 

Yine aynı masada senin için burdayım

Burada izlerin var

Islanmış gözlerin var

Verdiğin sözlerin var

Onun için burdayım

İnan ki sensiz canım mutluluğa düşmanım, 

Affet beni pişmanım demek için burdayım

Elini elime alıp öylece bir an kalıp, 

Sana son kez sarılıp ölmek için burdayım

Burada izlerin var...', 'İçimde bir ümit var onun için burdayım,  Belki gelirsin diye senin için burdayım Vakit çok geç olsa da gönlüm mahzun kalsa da,  Yine aynı ma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senin-icin-buradayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımız Eski Bir Roman', 'askimiz-eski-bir-roman-ahmet-selcuk-i-lkan-761f1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbimde arama eski yerini

Sen gözümden akan sele karıştın

İstesem de artık sevemem seni

Hasret rüzgarına yele karıştın

Seninle aşkımız eski bir roman

Yandı sayfaları külüdür kalan

Sevgilim herşeyim sendin bir zaman

Ne yazık sonunda ele karıştın

Kırılan kalbim var dinmez bir kini

Ömrümce sürecek aşka yemini

Kavuşmak imkansız artık sevgilim

Dönüşü olmayan yola karıştın', 'Kalbimde arama eski yerini Sen gözümden akan sele karıştın İstesem de artık sevemem seni Hasret rüzgarına yele karıştın Seninle aşkımız eski...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askimiz-eski-bir-roman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sibernetik', 'sibernetik-turgut-uyar-3fjmh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'üç kere üç dokuz eder

bilirsin

birin karesi birdir

kare kökü de

..........
..........', 'üç kere üç dokuz eder bilirsin birin karesi birdir kare kökü de .......... .............', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sibernetik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
