INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüthüt', 'huthut-behcet-necatigil-2zjwm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sanki düğün olmuştur

Sevmiş, sevilmiş, yenmiş, yenilmiş

Çekmiş, çektirmiş

Oyun hüzün olmuştur.

Düştür doğaldır içlenme', 'Sanki düğün olmuştur Sevmiş, sevilmiş, yenmiş, yenilmiş Çekmiş, çektirmiş Oyun hüzün olmuştur. Düştür doğaldır içlenme...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/huthut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanış Yapılar', 'tanis-yapilar-behcet-necatigil-83fvd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidecek ilk gençlikte

Çalmak istediğin kapı zilleri

Denk getirip bindiğin taşıtlar

Ters yönlerde akşam üzerleri', 'Gidecek ilk gençlikte Çalmak istediğin kapı zilleri Denk getirip bindiğin taşıtlar Ters yönlerde akşam üzerleri...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tanis-yapilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Uzun Kayalarda', 'o-uzun-kayalarda-sair-pravda-3ibda', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''...O uzun kayalarda kırmızı bir bayrak gibiydi günlerimiz....

      Korkunç ve cesur 

           ve gülümseyen bir çocuk gibi masum.....

    Uzun yelkenliler geçti, 

        biz kıyıdan el sallarken 

                  köpüklü dalgalara...

   Ve güverteden uzanan bir yeşil sevdaydı 

            umutlarımız.....

    Şimdi bir rıhtımda, 

          ayaklarımızı sarkıtmış 

                  suya, 

            dondurma yemeyi düşlüyoruz

                kış ortasında.....

    Geçen günlerin vedası omuzlarımızda, 

           gelecek günlerin sevdası ise, 

                 posta kutumuzda.... 

   Veda ederken akşamın karanlığı, 

                 günün ilk ışıklarına, 

                      mendilimi sallıyorum ben de, 

                              kırlangıç kuşlarına....

      Yeni bir rıhtıma usul usul yaklaşırken

                  beyaz bir boğaz vapuru, 

                                 adımımı atıyorum 

                                         usulca, 

                                               yeni bir yaşantıya.... 

                                                          20 Eylül 2001

                                                            22,27', '''...O uzun kayalarda kırmızı bir bayrak gibiydi günlerimiz....       Korkunç ve cesur             ve gülümseyen bir çocuk gibi masum.....   ...', ARRAY['Türk Edebiyatı','Şiir','Şair Pravda']::text[], 8.5, '{"poet":"Şair Pravda","poet_slug":"sair-pravda","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/o-uzun-kayalarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yaratılabilir mi', 'ask-yaratilabilir-mi-sair-pravda-hkmfe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sonsuz kargaşalığın içinde, 

        bir yürek var ulaşamadığım.

Bir yürek var kapısını her çaldığımda, 

       sadece çemberini bulduğum.

Oyalı bir yazma gibi günlerim, 

     örmekle sonsuza ulaştığım, 

Günlük konuşmalar içinde gözbebeklerim

     her anında sevdayı özlediğim.

yılları geriye sarsamda, 

    bilemiyorum

AŞK YENİDEN YARATILABİLİR Mİ', 'Bu sonsuz kargaşalığın içinde,          bir yürek var ulaşamadığım. Bir yürek var kapısını her çaldığımda,         sadece çemberini bulduğum...', ARRAY['Türk Edebiyatı','Şiir','Şair Pravda']::text[], 8.5, '{"poet":"Şair Pravda","poet_slug":"sair-pravda","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-yaratilabilir-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrenin Türküsü', 'evrenin-turkusu-sair-pravda-9q7m5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''....En tatlı şarkıları

          biz yarattık, 

             en güzel aşk şiirlerini biz yazdık....

     Bir  yudum su damlacığından

            evrenin sonsuz boşluğunda

                 salıncaklar   kurduk....

      Otururken kücücük odalarımızda, 

          sıcacık kahvelerimizi yudumladık.

    Oysa o gün, 

        evlerimizin küçük cam ekranlarında, 

            akvaryumdan birden bire

                  mavi bir denize atlayan

                    balıklar gibi, 

      sonsuz  boşluğa atlayan  insanları gördük........

     Bu evrenin papatya kokulu sokaklarında, 

          ellerinde rengarenk balonlarla, 

            hep beraber şarkı söyleyen çocuklar olabilirdik oysa.

     Usul usul dolanırken mavi dünyamız

          bu koca boşlukta, 

                yüreklerimizi

                   hep kanla, vahşetle donattık.

     Artık bu şarkının nakaratını değiştirelim, 

           ve her sabah uyandığımızda, 

                vivaldinin o yumuşak ilkbahar şarkısıyla

                    uzak diyardaki dostlarımıza

                       mendil sallayalım....

                                         14 Eylül 2001

                                             18,53', '''....En tatlı şarkıları           biz yarattık,               en güzel aşk şiirlerini biz yazdık....      Bir  yudum su damlacığından       ...', ARRAY['Türk Edebiyatı','Şiir','Şair Pravda']::text[], 8.5, '{"poet":"Şair Pravda","poet_slug":"sair-pravda","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/evrenin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Eylül Gülümseyişi', 'bir-eylul-gulumseyisi-sair-pravda-9otyl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''...Bir eylül sabahının sessizliğindeydi dünya, 

          Güneşin mahmur bakışlı ışıkları 

                           bizim parmaklarımızı okşarken, 

      Bir bülbülün şakımasını hissetti  dudaklarım, 

             Sevgiyle sunulan bir kelime günaydını duyarken.....

      Yumuşak bir ezgiyle geçsin gülümsemelerimiz

            Ve hoyrat bakışlar  uzak kalsınlar

                   pencerelerimizin pervazlarından......

.

     Eylül şarkılarıyla sana

           el sallıyorum uzak bir pencereden

                  gözbebeklerini yeşil bir yaprağa değdirdiğinde

                                                                  görebilirsin..... ''

                                                  11 Eylül  2001

                                                         09,07', '''...Bir eylül sabahının sessizliğindeydi dünya,            Güneşin mahmur bakışlı ışıkları                             bizim parmaklarımızı ...', ARRAY['Türk Edebiyatı','Şiir','Şair Pravda']::text[], 8.5, '{"poet":"Şair Pravda","poet_slug":"sair-pravda","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-eylul-gulumseyisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-sair-pravda-zxmdq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnız bir İstanbul akşamındayım, 

     Gökyüzünün sessiz maviliği

     Usulca karanlıklara gömülüyor.....

     Bir martı kanatlarını çırpıyor

     Uzun bir  yelkenin uçuşan kanatlarında......

    Gözlerimi tam da güneşin elveda dediği noktaya uzatıyorum....

    Kızımla hayal kurduğumuz uzun bir kuleyi seyrediyorum

    Sessizce Eyfel kulesine benzettiğimiz.......

  Ellerim bir menekşenin kadife kanatlarını okşuyor.....

Yüreğimde sıcacık bir selamla sana uzanıyorum......

 Şimdi marmaranın mavi suları Egenin tatlı akışına karışacak.....

 Ben ise sizin yüreğinize karışacağım saniyeleri sayacağım..........

 Bir demet dağ lalesi ile

  Size  hasretimi ve istanbulun pembe akşamlarını gönderiyorum...... 

 

                                                    14 Ağustos 2001

                                                            Pravda', 'Yalnız bir İstanbul akşamındayım,       Gökyüzünün sessiz maviliği      Usulca karanlıklara gömülüyor.....      Bir martı kanatlarını çırpıy...', ARRAY['Türk Edebiyatı','Şiir','Şair Pravda']::text[], 8.5, '{"poet":"Şair Pravda","poet_slug":"sair-pravda","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Camdan Bir Küre', 'sevda-camdan-bir-kure-sair-pravda-rergv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda camdan bir küre, 

                            içinde minik bir kar bulutu, 

                      Gözlerim mavi bir meneviş, 

                            içinde sevdiğim adam, 

                      Yüreğim kırık bir ayna, 

                            içinde burukluğum.

                       Beynimi açıyorum  ortasından, 

                           düşüncelerim saçılıyor yerlere, 

                       Bir gözyaşı yuvarlanıyor dudaklarıma

                           yılların örgüsünden süzülen....

                       Bir hasret yolculuğu ömrümüz, 

                          Ulaştığını sandıkça

                              daha ne kadar az yol aldığını anladığın, 

                       Bir garip çelişki bu sevda, 

                        büyüdükçe başkalarıyla paylaşıldığın....

                                                   4 eylül 2001', 'Sevda camdan bir küre,                              içinde minik bir kar bulutu,                        Gözlerim mavi bir meneviş,          ...', ARRAY['Türk Edebiyatı','Şiir','Şair Pravda']::text[], 8.5, '{"poet":"Şair Pravda","poet_slug":"sair-pravda","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevda-camdan-bir-kure-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuzey Rüzgarlarındaki Meneviş', 'kuzey-ruzgarlarindaki-menevis-sair-pravda-nk1jb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''...Kuzey rüzgarları taşıdı seni bana

            dün gece...

    Uzun bir gemici direğinde sallanan

            beyaz bir güvercin gibi

                huzurlu ve mutluydu yüreğim...., 

    Gökyüzünde yıldızlar dansediyordu, 

            sessiz bir vivaldi müziğinin

                       mor karanlıkları dolaşan ezgilerinde......

   Bir gençlik pınarının ışıldayan taneleri, 

             bizim beyaz saçlarımızda takılı artık....

   Yüreklerimizin kıpırtılarında yakalayabiliriz ama

             Evrenin  genç çırpınışlarını...

   Hoşgeldin  umutlu yüreğim, hoşgeldin, 

            yüreğime, gözbebeklerime

                sevdayı ve umudu verdin....''

                                10 Eylül 2001', '''...Kuzey rüzgarları taşıdı seni bana             dün gece...     Uzun bir gemici direğinde sallanan             beyaz bir güvercin gibi    ...', ARRAY['Türk Edebiyatı','Şiir','Şair Pravda']::text[], 8.5, '{"poet":"Şair Pravda","poet_slug":"sair-pravda","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kuzey-ruzgarlarindaki-menevis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bilmek', 'seni-bilmek-sair-pravda-1xiv3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni, sevdalarından biliyorum

Dumanlı kış akşamlarının

                     Uzak sabahlarından

Dudakların mahzun bir gülümseyişi taşıdılar

                                                 Hep bir yerlere doğru

Ellerinden biliyorum senin duygularını

        Uzanıp ta yukarda ki güneşe doğru

                 Akarsu dinginliğiyle insanlara sunuşundan

Yüreğin, yansıması ışıltılı bir buluttu

                 Dalgalanan bir denizin kıyılarında

Ve sen şimdi

Çok uzaklarda

      Bir şehrin sokaklarında

             Biraz öfke, biraz umut ve dirençsin

                                         Benim damarlarımda

Ve kocaman bir ayrılık sepetinden çıkan

        Gücenik duruşlu bir şenlik çocuğu.', 'Seni, sevdalarından biliyorum Dumanlı kış akşamlarının                      Uzak sabahlarından Dudakların mahzun bir gülümseyişi taşıdılar  ...', ARRAY['Türk Edebiyatı','Şiir','Şair Pravda']::text[], 8.5, '{"poet":"Şair Pravda","poet_slug":"sair-pravda","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-bilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
