INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Non Dolet 3', 'non-dolet-3-husrev-hatemi-j5otm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gesi bağlarında dolanıyor

Ve yitirdiklerimi, yitirmediklerimi, 

Aranıyorum...

Çünkü insanlar arasında engel, 

Yalnız dağlar değildir; 

Bazı anılar, bazı ölülerle sağlar, 

Göz önündekileri bile

Ayırabilir bizden.

Gesi Bağları, bazan Taksim

Bazan Limmat kıyıları, 

Bazan Berlin veyâ başka şehir, 

Olabilir...

Ben bugün beynimin Gesi bağlarında, 

Bir tek selâmına göneniyorum; 

Selâm geliyor arasıra Ölümden, 

Senden bir ses geldiği yok.', 'Gesi bağlarında dolanıyor Ve yitirdiklerimi, yitirmediklerimi,  Aranıyorum... Çünkü insanlar arasında engel,  Yalnız dağlar değildir;  Bazı ...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/non-dolet-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vermeyecegim', 'vermeyecegim-nil-duman-2xh8x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vermeyecegim

Birgün gelecek o güneşi tutup

Alacagım battıgı yerden.

Gerekirse dogdugu yerdebatıracagım yinede

Senin o güzel kalbinin kırılmasına

Yüzünden bir damla yaşın süzülmesine

asla izin vermiyecegim.', 'Vermeyecegim Birgün gelecek o güneşi tutup Alacagım battıgı yerden. Gerekirse dogdugu yerdebatıracagım yinede Senin o güzel kalbinin kırılma...', ARRAY['Türk Edebiyatı','Şiir','Nil Duman']::text[], 8.5, '{"poet":"Nil Duman","poet_slug":"nil-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/vermeyecegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sofistike', 'sofistike-kemal-taskin-8kk0j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'az önce yanımdaydın  (yansızlığımda) 

anlamsızlığ-ım-  varmış

uzaklardan gelen

           (yaşanmış) 

bir bitmezlik öyküsü yazıyor(um) 

şimdi ki

günsüz günlerimde! 

güneşi görmediğim geceyi kardeş

bildiğim süresiz  sürelerde; 

'' descartes'' olmak istiyorum! 

sofistike (aşk)  hep içimde

çıkmıyor! 

rehin dışarı-

bir kurşunluk ömrüm

var. arkama bakamıyorum? 

korkuyorum! 

korkuyorum! 

sonra herşey-in-      (in)     olmadığı

it''çe yaşam(ım)  devam ediyor...

YALANDAN! ..', 'az önce yanımdaydın  (yansızlığımda)  anlamsızlığ-ım-  varmış uzaklardan gelen            (yaşanmış)  bir bitmezlik öyküsü yazıyor(um)  şimd...', ARRAY['Türk Edebiyatı','Şiir','Kemal Taşkın']::text[], 8.5, '{"poet":"Kemal Taşkın","poet_slug":"kemal-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sofistike-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim İşte', 'o-benim-i-ste-umit-yasar-oguzcan-asx26', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biraz kül, biraz duman, 

O benim işte...

Kerem misali yanan, 

O benim işte...

İnanma gözlerine ben ben değilim

Beni sevdiğin zaman, 

O benim işte...', 'Biraz kül, biraz duman,  O benim işte... Kerem misali yanan,  O benim işte... İnanma gözlerine ben ben değilim Beni sevdiğin zaman,  O benim...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/o-benim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgara Kapılma', 'ruzgara-kapilma-huseyin-yurttas-ahaeq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir daha rüzgara kapilma

Öyle ucusmasin eteklerin

Küllerim savrulur birden

Sonra seni de tutusturur alevlerim

Bir daha rüzgara kapilma

Öyle toprak gibi dirilmesin tenin

Tohum olup serpilirim

Bulutlari da indirme

Bütün filmleri yakan o bembeyaz tenine

Önce ben eririm

Söyle günese

Cekilsin kirpiklerinden

Satasmasin kulaklarinin altindaki sari tüylere

Her hal-ü karda

Dövüsebilirim senin icin', 'Bir daha rüzgara kapilma Öyle ucusmasin eteklerin Küllerim savrulur birden Sonra seni de tutusturur alevlerim Bir daha rüzgara kapilma Öyle ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Yurttaş']::text[], 8.5, '{"poet":"Hüseyin Yurttaş","poet_slug":"huseyin-yurttas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruzgara-kapilma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Benden Önce', 'senden-benden-once-umit-yasar-oguzcan-9aehu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum da; bir bakıma senden öncesi yok gibi bir şey 

Çünkü senden önceki yıllar, sana hazırladı beni 

Senden önce tanıdığım kişiler, seni bulduğum zaman değerini daha iyi 

anlayabilmem için birer sebepten başka bir şey değillerdi 

Sensiz anılarım seninle geçen bir günün anısı yanında o kadar kuru ve cılız ki! 

Uzun yıllar amansız bir ölüşün içinde çalkalanıp durdum 

Bir trendim; küçücük istasyonlardan geçtim, sonunda sana varmak icin 

Bir gemiydim; irili ufaklı limanlara uğradım, bir gün senin limanına gelmek icin 

Bir yoldum; nice insanlar çiğnedi beni Şimdi ayaklarının temasındaki hazzı daha iyi anlıyorum. 

Bir kitaptım; beni okudular, fakat anlayan çıkmadı 

Yıllarca seni bekledi sayfalarım, okuyasın diye 

Yokluğunda bir kadehtim ben, 

Türlü içkilerle doldurup ağızlarına boşalttılar beni 

Yere çarptılar kırılmadım, duvara vurdular parçalanmadım 

Bir gün içime senin güzelliğinin dolacağını bildiğim için 

Dudaklarının değdiği her yerde bir ölümsüzlük ateşinin yanacağına inandığım için 

Gör, bir kadehin nasıl sarhoş olduğunu. 

Şimdi sarhoşum ben 

Kurşun askerler, bebekler, oyuncaklar vardı senden önce 

Durup durup aldanmalar vardı, aldığını geri vermeyen aynalar vardı 

Hep karanlığa açılan pencereler, ardında iğrenç yaratıkların yaşadığı büyük 

kapılar vardı 

Şehirler gördüm; sokaklarında bir toz bulutuydu yaşamak 

Çarşılarında fazilet kiloyla satılır, namus metreyle alınırdı 

Evlerinde yanyana yaşardı insanlarla hayvanlar 

Sabahları yalan girerdi pencerelerinden ışık yerine 

Akşamlar pis bir koku gibi gelir, geceler bir hışım gibi çökerdi o şehirlerin üstüne 

Her evde bir çocuk ağlardı ve her gün bir çocuk ölürdü sıtmadan. 

Gündüzleri erkekler kahvelerinde okey oynar, kadınlar bakraçla su taşırdı 

Gece olunca yataklar utanırdı yataklığından, duvarların yüzü kızarırdı 

Eller ve ayaklar bütün gece kirli bulaşıklar gibi yıkanmayı beklerdi 

Şehirler gördüm ben.. 

Sefaletin utanç olmadığı şehirler gördüm 

Bencilliklerin birer apartman gibi yükseldiği ve şereflerin çamurlara 

düştüğü şehirler gördüm 

yaptığını anlamıyordu 

Balolarda, şölenlerde kötü bir oyundu yaşamak.

Kadınlar elmaslarıyla ölçüyorlardı güzelliklerini 

Erkekler banka cüzdanlarıyla değerliydiler 

Ne şehirler gördüm ben.. 

Tiyatrolarında, sinemalarında aldanışlarımız, utançlarımız oynanırdı 

Meyhanelerinde kirli ve renkli sulardı içilen. 

Mavileşmiş bir köhne zamandı. 

Çeşitli tuzaklarla doluydu her sokağı. 

Büyük arenalara benzeyen sokaklarında kan ve zulüm kokardı. 

Bir semtinde parfüm kokularıydı havaya karışan.

Bir semti amonyak kokardı. 

Ve nice insanlar gördüm ben. 

Alışkın elleri kötülük etmeden duramazdı. 

Yalan söylemeden edemezdi dudakları. 

Gurur kötü dikilmiş bir elbiseydi üzerlerinde.

Boş kovalar gibi ses verirlerdi dokunulduğu zaman.

Nice insanlar gördüm ben. 

Bir yoksula en küçük bir iyiliği yapmaktan çekinen, 

fakat bir gecenin cömert bir saatinde onbinleri, 

yüzbinleri vahşi bir zevkle kaybeden insanlar gördüm.

Din adamları aldatılacak bir kadın, ırzına geçilecek bir çocuk arıyordu mabetlerinde.

Zenginliklerine daha sömürülecek insanlar gerekti.

Ben yüzü jiletle kesilmiş kötü adamlar gördüm ve ben her sabah yüzünü traş ettiği jilet kadar para etmeyen daha kötü adamlar gördüm.

En adi kıskançlıklar gördüm, kavgalar, zulümler, iskenceler, en ucuzundan kirli çamaşırlar, paçavralar, çamurlar, irinler, çirkefler gördüm.

Seni tanıyıncaya kadar dinlediğim çatlak sesli bir plaktı, berbat bir filmdi seyrettiğim.

Seni görünceye kadar kötülükten yana ne varsa tanıdım, çirkinlikten yana ne varsa gördüm.

Tut ki bir kum çölündeydim, kızgın bir güneşin altında susuzluktan çatladı dudaklarım.

Şimdi senin dupduru kaynağına eğilip su içerken varlığının paha biçilmez değerini daha iyi anlıyorum.

Yokluğunu bu kadar derinden tatmasaydım, varlığının eşsiz anlamına varamazdım.

Tut ki yıllarca süren bir geceydi senden öncesi. 

Güneşsiz aysız, yıldızsız bir gökyüzüydü. 

Kupkuru bir eski deniz kalıntısıydı. 

Çekilmiş bir nehir yatağıydı. 

Senden önce bir gün seni bulmak ümidiydi beni yaşatan.

Tohumun yeşermek işin yağmuru, çiçeğin açmak için güneşi beklediği gibi bekledim seni.

Nasıl bir nehir denize kavuşmak için uzak mesafelerden çağlaya çağlaya gelirse; işte ben de öyle geldim senin denizlerine.

Senden öncesi uzun, uğultulu bir arayıştı, kudurmus bir çalkantıydı. 

Yokluğun öyle bir uçurumdu ki; yeryüzündeki bütün uçurumları uç uca eklesek, yokluğunun yanında bir nokta gibi kalırdı. 

Bütün girdaplar bir araya gelse; varlığının derinliğine yaklaşamaz şimdi. 

Senden önceki yıllardan sana kendimi getiriyorum. 

Yokluğunu tatmış, her yerde seni bir rüzgarcasına aramış ve vahşi, büyük bir nehircesine sana koşmuş bir ben var şimdi karşında. 

Arındım bütün kötülüklerden sana geldim. 

Seni yarınlara götüreceğim, gel; 

yaşanmamış zamanlara, erişilmemiş hazlara götüreceğim seni. 

İnan ki ne senden öncesi vardı, ne de 

benden öncesi.', 'Düşünüyorum da; bir bakıma senden öncesi yok gibi bir şey  Çünkü senden önceki yıllar, sana hazırladı beni  Senden önce tanıdığım kişiler, s...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/senden-benden-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Geceler', 'beyaz-geceler-ethem-vayvayli-nshh2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'beyaz gecelerde

zambak içinde

keskin uğursuzluk içinde

kaşlarındaki alıngan tav

aşkın yakarışı içinde

sevginin aşkı içinde

beni yanından sav

beyaz gecelerde

uzun bacaklarında

tükenirken alev sarmaşığı

bıcağın saplanışına

yön ver dudaklarınla

gece boyunca

gizi içilmiş sözcüklerinle

beyaz gecelerde

(2000, Ankara)', 'beyaz gecelerde zambak içinde keskin uğursuzluk içinde kaşlarındaki alıngan tav aşkın yakarışı içinde sevginin aşkı içinde beni yanından sav...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beyaz-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Zamanların Kaçış Teorileri', 'yitik-zamanlarin-kacis-teorileri-deger-ulas-turan-rtw0x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-I- 

Kucakla hadi ellerindeki ölü çocukları, 

Sımsıkı varlığında, 

Bomboş bir gülüş bırak masum yüzlerine.

Ve yitirilmiş bir ana yüreği, 

Sarsın bedenlerini... 

Ay susar yüzündeki derin kraterlerinde, 

Koştukça her adım bir boşluk, 

İnsanlık için küçük 

Ve sevgi için büyük bir kaçış olmalı bu... 

Sonra bir vadinin kıyısında bulmalısın, 

Kaybettiğin bütün, 

Kaybolan hiç, 

Sessiz bir veda hazırlamalısın. 

Bu yitirdiğin yağmurların, 

Sel gibi boşalan zamanlarına. 

Bir kayıp bıraktıysak, 

Nice sen, nice öfke... 

Bulduysak hiçler vadisinin 

Boğulan sesi, 

Nice ölüm, 

Kaçışların nice yarın... 

Tutsak bir uçurum kuşu düşündüğün, 

Özgürlükten bahsediyordun, 

Daha dün, 

Şimdi bugün... 

Ölüler zamansız bıraktı kanatları, 

Çırpındığın bir kaçış, 

Teori artık umutların... 

Yankısı sensin yarınlara uzanan, 

Yankısı bir yürek... 

Ellerinde kırık kanatların, 

Ellerin kan... 

Ve yitik zamanların uzun kaçışları. 

Ellerinde kanayan bir teori, 

Beni senden, 

Seni benden; 

Zamansız yitirdiğim. 

Dile benden bütün kaçışları, 

Dile yalnız ve yoksul bir çocuk yüreğiyle... 

Bu zaman içinde bir kayıp, 

Bu sevdanın tutsak çocuklarından dile mutluluğu... 

Sonra göm bu çocukları, 

Kokusu sinmeli toprağa... 

Filizleri aydın yüzünde yeniden, 

Kaçış teorileri... 

Yitirilecek yeniden, 

Bir zaman bu kaçışlarda.

-II- 

Ve sen hep bir vadinin kenarında, 

Beklerken yarınları... 

Yeni bir asır vuracak yüreğinden. 

Yeni olan sadece asırken, 

Özlediğin ne varsa, 

Topraktan, kilden, 

Bir umut... 

Ve beni çağırdığında yüreğinin vadisine, 

Sesin bir hayalin yalnız, 

Çaresiz, çocuk suretini taşıyacak yarınlara... 

Sen her özlediğinde, 

Çocukluğumu çalmış olacaksın... 

Filizlerinde bir aydın gülüş unutacaksın... 

Umarsız bir kaçışın, 

Anlamsız teorisinde bulacaksın kaçışlarını... 

Gerisi hep uçurum, 

Hep teori yarına uzanan ellerin... 

Her kaçış bir yarın sevdası, 

Gerçek olan, 

Yalan bir sevdanın, 

Anlamsız kaçış teorileri... 

Sen sevdayı böyle yitireceksin, 

Hiç bulamayacağın o vadi kıyısında, 

Belki bir uçurum kenarında, 

Yeniden boşluğa uzanacak ellerin... 

Ve ben kaçışlarındaki yitik umutların teorisini çözmüş olacağım... 

Sen sevda diye sayıklarken... 

Umutlar çoktan vadileri aşmış olacak, 

Yeni bir asra uzanacak, 

Gömülen çocukların ölümsüz kökleri... 

Yeni bir aydınlıkta, 

Yine bir hayat anlam bulacak 

Ve adı olmayan teorilerin, 

Gerçek zamanlarında 

Hep saklı kalacak.', '-I-  Kucakla hadi ellerindeki ölü çocukları,  Sımsıkı varlığında,  Bomboş bir gülüş bırak masum yüzlerine. Ve yitirilmiş bir ana yüreği,  Sa...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/yitik-zamanlarin-kacis-teorileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gül', 'ey-gul-ethem-vayvayli-72y04', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi sularda sürgün

Pembe övgünün resmi

Ey gül! 

Senin sesin bu ses mi? 

(03 Ocak ''98, İstanbul)', 'Şimdi sularda sürgün Pembe övgünün resmi Ey gül!  Senin sesin bu ses mi?  (03 Ocak ''98, İstanbul)...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ey-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Sonrası Yapraklar', 'sonbahar-sonrasi-yapraklar-ethem-vayvayli-t2x85', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne olur beni sevginin en katranında

Sonbahar sonrası yaprak gibi unutun

Çığ yuvarlasın üzerimden çocuklar

Sımsıcak bahar güneşi ile kurutun

Ne olur beni yalnızlığın son odasında

Gökte dağılan kar topu gibi unutun

Yürüsün üzerimden zemheri takvimler

Aklınızda bir uğursuz gün gibi tutun

Ne olur beni sevdanın en eskisinde

Güzgünü, ikindi üstü gibi unutun

Otursun güneş  tırpan köşkü üstünde

Kesilip atılan tırnaklar gibi unutun

Yıkansın ellerimiz koyu gölgenin altında

Bakır ibrikten dökülen sulara tutun

Özlemin getirdiği akşamların hatırına

Güllere dökülen sular gibi unutun

Ne olur beni al yayla pampallarıyla

Ardıç kovuğunda arı gibi uyutun

Güneş doğsun batsın hergün yamaçlarında

Çiçeklere bade bir kır gibi unutun

Ne olur beni çamlığın kese yollarından

Geçen ol vefasız nazlı yâr gibi unutun

Dökülmesin aşk üveykin kanatlarından

Çığlığımı denizde duyar gibi unutun

(30 Ocak ''98, KÇ)', 'Ne olur beni sevginin en katranında Sonbahar sonrası yaprak gibi unutun Çığ yuvarlasın üzerimden çocuklar Sımsıcak bahar güneşi ile kurutun ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sonbahar-sonrasi-yapraklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Tırnak Kadar Ümit', 'i-cimde-tirnak-kadar-umit-ethem-vayvayli-3vmov', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I.

nasıl da bulut çöküyordu gözlerime

içimde tırnak kadar ümit

sanki gemi batmıştı ufkun içine

gökyüzünde sular girmişti birbirine

gülümsüyordu karşımda dere yatağı

kalbimi kesip yarmıştı ortadan

yıldızların oyuncak dükkanı olmuştu

içime çöken koyu karanlık gecede

II.

n''aparsın hülyanın böylesini

böylesi yarımyamalak aşkları

kuşların kırmızı gagalarındaki

koyu yeşil göveldek gerlerini

ey çiçeği sarı olan otluk

ekin tarlalarında turaç avladım

dizlerimde kocaman yokluk

kapı kapı dolaştım

809 Şubat ''98, İstanbul)', 'I. nasıl da bulut çöküyordu gözlerime içimde tırnak kadar ümit sanki gemi batmıştı ufkun içine gökyüzünde sular girmişti birbirine gülümsüyo...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/icimde-tirnak-kadar-umit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Hayat', 'yeni-bir-hayat-ethem-vayvayli-e6cox', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-vadideki zambak''a-

Bütün denizler efsun dağıtıyordu

Kollarımda ölmemem için gelecek

Herşey yıldız çığırına doğru

Ne çabuk: bitecek! ...

Umut şövalyelerinde aradık yüzler

Bu bizim dervişler, bizim erler

Salkımsöğüt uykularında

Bir çocuk: Gülecek! ...

Nasıl hala yaprak kümelerinde

Titrek gölgeler doğum gürülder

Bir zambak kanatlanır içimden

Bir umut: Gelecek! ...

Sanki vadiler içinde kumlardayım

Bir ulu şahinlikte, bir uçurumdayım

Kalbim funda burçlarında

Bir çubuk: İncecik! ...

Gözyaşım içinde söndü yıldızlar

Yollarım düşlerine uzar da uzar

Yeniden edilse bana merhamet

Bir hayat: Gencecik! ...

(19 Mart ''98, İstanbul)', '-vadideki zambak''a- Bütün denizler efsun dağıtıyordu Kollarımda ölmemem için gelecek Herşey yıldız çığırına doğru Ne çabuk: bitecek! ... Umu...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yeni-bir-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hâr Bahçesi', 'h-r-bahcesi-ethem-vayvayli-3ocix', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu hüsnüzâna duram kaçılam

Hâr bahçesinden atâş kaçıram

Gül şehrâyine kanat açılam

Dillerin bezmine divâneyim yâr

Demet çiçeğim kıra ekilem

Zülfün telinde kara kekilem

Can pazarında dâra çekilem

Güllerin birine divâneyim yâr

Dost akranınan şora duruşam

Ne konuştuysam hora konuşam

Yâr ağlamamış çorak olmuşam

Jâle-i eşkine divâneyim yâr

(29 Mart ''98,22: 40, İstanbul)', 'Bu hüsnüzâna duram kaçılam Hâr bahçesinden atâş kaçıram Gül şehrâyine kanat açılam Dillerin bezmine divâneyim yâr Demet çiçeğim kıra ekilem ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/har-bahcesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-yavuz-turhan-hcudk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerimde sen, 

yüreğimde sevdan yansıyor.

       Bir güneş tutulması gibi, 

yeniden sıcaklığına kavuşmak istiyorum.

       Seni özlüyorum...

       Seni istiyorum...

       Haydi! çık gel sırların içinden.

yeniden tut ellerimi.

       Saçlarım savrulurken rüzgarınla, 

kavur dudaklarımı....', 'Gözlerimde sen,  yüreğimde sevdan yansıyor.        Bir güneş tutulması gibi,  yeniden sıcaklığına kavuşmak istiyorum.        Seni özlüyorum....', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sir-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dâr Ağacı Gözlerindeki Mor Halkalar', 'd-r-agaci-gozlerindeki-mor-halkalar-ethem-vayvayli-0fj2k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevenim olsun isterdim

Umutlarım olsun, dikenim olsun

Çiçek götürmedim giderken yüreğe

Camlar tıkırdamaz, kilitler çevrik olsun

Kalemlerin devrik cümle kurmasını

Bakışların ağlamasını öğrendim

Gözlerinden sökülen mor halkayı

Kanlı gözlerime gemledim

Işıklar hıçkırır anladım

Kalbim Mevlânanın tekkesindeyken

Dudaklarım Dadaloğlu''na ilişti

Onsuz olacak şey miydi? 

Ona ağlamamasını 

Bu günlerinde geçeceğini söyledim

Hıçkırıkları ışığı kıstı

Kalkıp köze yaslandım

Ağlama dedim ateş beni yakacak

Hayat beni sana koymayacak

Dâr ağacı gözlerindeki mor halkalar

Beni çiçek getirmedim diye asacak

(17 Nisan ''98, İstanbul)', 'Bir sevenim olsun isterdim Umutlarım olsun, dikenim olsun Çiçek götürmedim giderken yüreğe Camlar tıkırdamaz, kilitler çevrik olsun Kalemler...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dar-agaci-gozlerindeki-mor-halkalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerçekimi', 'yercekimi-yavuz-turhan-y88i3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öfkemi sessizliğimle, 

yüzüne vuruyorum.

           En güzel sözlerimi: 

yine yalnızlığıma söyleyeceğim.

           İklimleri karışmış, 

yörüngesinden fırlamış bir 

                           gezegen gibi, 

savruluyorum boşlukta.

            Şimdi, hangi yerçekimi

zincir vurur? 

nasırlaşmış ellerimi taşıyan 

yorgun bileklerime...

             Sen git...

yıldız olsun adın geceye.

ardına bile bakma...

              Düşersem, bir karadeliğe, 

Ve cesaret edipte, 

girip bulursa biri beni, 

               Belki; bir isim koyar yitirilmişliğime...

(Kızıl Deniz''e teşekkür.)', 'Öfkemi sessizliğimle,  yüzüne vuruyorum.            En güzel sözlerimi:  yine yalnızlığıma söyleyeceğim.            İklimleri karışmış,  yör...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yercekimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yağmurdan Sonra Seveceğim', 'seni-yagmurdan-sonra-sevecegim-ugur-arslan-ix79m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi git..

Say ki, seninle içinden sevda geçen bir türkü söylemedik.. Say ki, gece mektuplarını, en güzel aşk şiirlerini beraber ezberlemedik.. 

Say ki, sevda trenini kaçırdığım durakta bir süre beraber beklemedik.. 

Sen git.. 

Ben gelemem bu yürekle.. 

Ya da kal.. 

Eylül yağmurlarını bekle.. 

Seni yağmurdan sonra seveceğim.. 

Saçlarıma ak düşmemiş halimle.. 

Sen yaşlardayken.. 

Onsekizimde, yirmimde.. 

Seni yağmurdan sonra seveceğim.. 

Kaldırımların ıslak ve temiz haliyle.. 

Yaşlı yüzüm delikanlı yüreğimle.. 

Seni yağmurdan sonra seveceğim.. 

Aşksız geçen onca yılı yakacağım.. 

Sevda alevinde kendi ellerimle... 

Şimdi git..

Say ki, seninle sahildeki çardakta hiç dondurma yemedik..

Say ki, oturup konuştuğun yaşlı ve yabancı bir adamdı.. 

Ve sevdadan hiç söz etmedik.. 

Say ki, hiç gülmedik.. 

Aynı şeyleri sevmedik.. 

Ve yağmurdan sonra beraber yürümedik.. 

Seni yağmurdan sonra seveceğim.. 

Kimse bilmeyecek, herkesten gizleyeceğim.. 

Yağmurdan sonraki toprak kokusu olacak havada.. 

Seninle gökkuşağının altından geçeceğim.. 

Seni yağmurdan sonra seveceğim.. 

Ve seni sevdiğimi kimseye söylemeyeceğim.. 

Belki bu dünya gözüyle gördüğüm son yağmur olacak.. 

Islak kaldırımlarda sırılsıklam yürüyeceğim.. 

Ben seni yağmurdan sonra seveceğim.. 

Ve bir gün ölürsem yeşil gözlerinde öleceğim.....', 'Şimdi git.. Say ki, seninle içinden sevda geçen bir türkü söylemedik.. Say ki, gece mektuplarını, en güzel aşk şiirlerini beraber ezberlemed...', ARRAY['Türk Edebiyatı','Şiir','Uğur Arslan']::text[], 8.5, '{"poet":"Uğur Arslan","poet_slug":"ugur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/seni-yagmurdan-sonra-sevecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildik Şarkılar Çalınmaz Olur', 'bildik-sarkilar-calinmaz-olur-ethem-vayvayli-h692x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tarlalarda güzün sarı firez olur

Bir derde düştüm ölümüm tez olur

Yağmur yağar eşikler geçilmez olur

Ne olur bir de sen ağlatma yâr beni

Yasak mahpuslardan sorulmaz olur

Dostlarım haklıyı korumaz olur

Bu virân yurtta da kalınmaz olur

Ne olur bir de sen ağlatma yâr beni

Karakuşlar kurdu ulutmaz olur

Dalgalar sahili uyutmaz olur

Yanar özgülüm de su yutmaz olur

Ne olur bir de sen ağlatma yâr beni

Göğe erer başlar görünmez olur

Öl deyince beyler ölünmez olur

Eğri odunsuz ocak tütmez olur

Ne olur bir de sen ağlatma yâr beni

VAYVAYLI''m kendince avunmaz olur

Bildik şarkılar da çalınmaz olur

Tabutum sırtlarda taşınmaz olur

Ne olur bir de sen ağlatma yâr beni

(18 Nisan ''98, İstanbul)', 'Tarlalarda güzün sarı firez olur Bir derde düştüm ölümüm tez olur Yağmur yağar eşikler geçilmez olur Ne olur bir de sen ağlatma yâr beni Yas...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bildik-sarkilar-calinmaz-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Bu', 'ayrilik-bu-ethem-vayvayli-o4q43', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benim mavi denizime

ne zaman ürkek ceylanlar gibi

girmeyi düşünüyorsun? 

su çırpıntıları okşasa yüzünü

umutla dönsen yeniden köyüne

kırgın yürekler döner

kırık bilekler biter

kuşlar su içer

ama ayrılık bu ceylanım

insanlık biter bu bitmez

kan akar ırmaklar, tarih silinmez

çağlardan çıkmaz kan izi

sen yine de

gir benim mavi denizime

ağlaşalım sırtsırta

dizdize.

(20 Nisan ''98, istanbul)', 'benim mavi denizime ne zaman ürkek ceylanlar gibi girmeyi düşünüyorsun?  su çırpıntıları okşasa yüzünü umutla dönsen yeniden köyüne kırgın y...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayrilik-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madalyon', 'madalyon-ramazan-hakan-ayhan-jvk0f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen aşkın bir yüzü

Ben aşkın bir yüzü

bir de gökyüzü

Yıldızlar, hayaller falan filan

Bir şişe dibine dayamışız göğsümüzü

Bir mahsunluk sarmış yüzümü 

Ölüm gelse sakilik yapabilir miyim de

Her ne kadar kaybetmesek de özümüzü 

Ne kargalar ne de çakallar yer ölümüzü', 'Sen aşkın bir yüzü Ben aşkın bir yüzü bir de gökyüzü Yıldızlar, hayaller falan filan Bir şişe dibine dayamışız göğsümüzü Bir mahsunluk sarmı...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Hakan Ayhan']::text[], 8.5, '{"poet":"Ramazan Hakan Ayhan","poet_slug":"ramazan-hakan-ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/madalyon-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin Yine Kan', 'yuregin-yine-kan-ethem-vayvayli-ytmvu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklardan gördüm şavkın tonunu

Goriot Baba şarkı söylüyordu

Çocuk erken yaşta gülümsüyordu

Bıldırcın sofrasını andıran

Yüreğin yine kan; kas, katı kan

Kalender dimağındaki monarşist heceler

Babâli caddelerinde hüküm sürerken

Gündüzün gökyüzüne karanlık kükrerken

Zeliha''nın hor bakışını andıran

Yüreğin yine kan; kas, katı kan

Cesaret evveli düşürdüğün sıvalar

Bir kadehin sessizliğini ovalarsa

Ufku bir mitralyöz alevi kovalarsa

Hacın''ın katliamını andıran

Yüreğin yine kan; kas, katı kan

Kimsesiz denizde sensiz bir adam vardı

senden önce kıyısına çıkan adam vardı

Babalımı çek, cehennemlik kadam vardı

Güldevri dikenlerini andıran

Yüreğin yine kan; kas, katı kan

(02 Mayıs ''98, İstanbul)', 'Uzaklardan gördüm şavkın tonunu Goriot Baba şarkı söylüyordu Çocuk erken yaşta gülümsüyordu Bıldırcın sofrasını andıran Yüreğin yine kan; ka...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yuregin-yine-kan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşle Uyanmak', 'gunesle-uyanmak-ethem-vayvayli-jzbbf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki ağlamamak gerekiyordu

Yeni doğmuş güneşle uyanmak

Gözlerimizi utkulu güne kırpmak

Pembe şafaklarında o sabahların

Hüzne dönüşen mor akşamlarda

Ne acılar üstüsteydi

Aman ağlatmayın devi! 

(11 Mayıs ''98, İstanbul)', 'Belki ağlamamak gerekiyordu Yeni doğmuş güneşle uyanmak Gözlerimizi utkulu güne kırpmak Pembe şafaklarında o sabahların Hüzne dönüşen mor ak...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunesle-uyanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Sazlık Akşamlarda Kadındı Heryanın', 'i-nce-sazlik-aksamlarda-kadindi-heryanin-ethem-vayvayli-kuq4j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'biliyorsun 

ince sazlık akşamlarda

yorgunsam eğer 

bu türküyü söylerdik

hem naz değmemişti saçlarına

hem alıngan düşüp

yıkılmazdı dikbaşlı kirpiklerin

aslında kadındı omuzların

polattı gerdanın

oysa bir salıncak ipi gibiydi 

her yanın

seni

selvi gölgelerinde

beş taş oynarken

yanarken derelerde

ıhlamur çiçeği

günbatımlarını kaçıran gök

serpilmişken ayaklarımıza

sevdim! 

biliyorsun.

(2001, İstanbul)', 'biliyorsun  ince sazlık akşamlarda yorgunsam eğer  bu türküyü söylerdik hem naz değmemişti saçlarına hem alıngan düşüp yıkılmazdı dikbaşlı k...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ince-sazlik-aksamlarda-kadindi-heryanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyküler Buldum Yalnızlıkta', 'oykuler-buldum-yalnizlikta-ethem-vayvayli-87pgv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çok mu ümitsiz yaşarım

bilemem ama

gördüğüm filmler hep ıssız

az oyuncu paylaşır

hayattaki perdeyi

ellerim düş yorgunu şakaklarımda

çıkıp gitmek isterim

bu dağbaşı hayatını

ben istedim, 

ben kapattım

evimin dumanlar yükselen bacasını

ben kazıyıp attım

kapımdaki ayak izlerini

öyküler buldum yalnızlıkta

asırlarca anlatılıp durmuş

biri beni en güzel anlatan

dağbaşlarının öyküsünü

konuştukça çoğalır yalnızlığım

sustukça çoğalır

gözlerim senin gittiğin boşlukta

gitti gidecek daha ne var derim

ayrılığı ben istedim

ben çektim güzgöçünün başını

dökülürken dut yaprakalrı

ben uzattıp ellerimi

ağlayıp titrerken dudaklar...

(11 Mayıs 2000, Ankara)', 'çok mu ümitsiz yaşarım bilemem ama gördüğüm filmler hep ıssız az oyuncu paylaşır hayattaki perdeyi ellerim düş yorgunu şakaklarımda çıkıp gi...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/oykuler-buldum-yalnizlikta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanık Rengi Anılar', 'yanik-rengi-anilar-ethem-vayvayli-ll9ze', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni ne çok özlemişim

Paslı kapı seslerinde

Ağlamaklı resmin kalmış

Sakladığım defterimde

(07 Mayıs ''00, Ankara)', 'Seni ne çok özlemişim Paslı kapı seslerinde Ağlamaklı resmin kalmış Sakladığım defterimde (07 Mayıs ''00, Ankara)...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yanik-rengi-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günüm', 'dogum-gunum-ethem-vayvayli-8qf6i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'saçaklardan üşüyünce düşer

yağmur damlaları

gül tohumları

doğumu umarak

saçılır

kınalı kadın ellerinden toprağa

ay yarım kalmış

güftelerini tamamlamak için doğar

hergün biraz daha büyük

gök ona kuçak açar, onu sever

bulut onu kıskanır, kanatlarını serer önüne

alev bir kızın yanaklarında

nar gibi kızarır

su, ceylanın parmaklarında

ahenkleşir, fısıldaşır

çocuklar şehval çiçekleri toplamaya uğraşır

sarmaşıkların çığlık atttığı vadilerde

ben neden doğmuşum

bilmiyorum! 

(23 Nisan ''00, Ankara)', 'saçaklardan üşüyünce düşer yağmur damlaları gül tohumları doğumu umarak saçılır kınalı kadın ellerinden toprağa ay yarım kalmış güftelerini ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dogum-gunum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklarında Ölmek İstedim', 'sokaklarinda-olmek-i-stedim-ethem-vayvayli-wgwxo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben o sokaklarda

berrak gölgeler aradım

ürkek karınca göçlerinde

ayak seslerini kokladım

seni bulmuş gibi adımladım

sana varmış gibi durdum

şehrin günebakan çiçeklerine

serçe kuşları dadanmış

o berrak gölgelerin

boşalttığı sokaklarda

seni kaybetmiş gibi kaldım

senden kopmuş gibi korktum

hayat sende, arzu sende

iyi olmak senin dileklerinde

varolmak senin, yaşamak senin

ölmek senin sokaklarında

ben o sokakların

resimler astım duvarlarına

perdeler çektim karanlık gecelerine

yağmuraltında gözlerinle

vuruşmak, ölmek istedim

(Nisan ''00, Ankara)', 'ben o sokaklarda berrak gölgeler aradım ürkek karınca göçlerinde ayak seslerini kokladım seni bulmuş gibi adımladım sana varmış gibi durdum ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sokaklarinda-olmek-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında Gülmek İşin Aslı', 'aslinda-gulmek-i-sin-asli-ethem-vayvayli-lc2rk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ağlamak

mutlu eder bizi

ağlamak

erdirir başımızı

göğe

ağlamak

tatlı bir elle uyandırır

bizi uykumuzdan

ağlamak

sabahlara kadar ağlamak

yormaz kalbimizi

kör etmez gözlerimizi

ağlamak

kucak dolusu gülle

durur kapımızın önünde her sabah

güleryüzlü, taptaze

neşemizi paylaşır

yarıya böler günlerimizi

ayağımız daha sağlam basar yere

ağlamak

duyurur içimizdeki sesi

ağlamak açar kapı sürgülerimizi

dolar içerimize sevgi

ağlamak

götürür bizi

cesaretle

sevgilinin

gözlerinin içine.

(08 Nisan ''00, Ankara)', 'ağlamak mutlu eder bizi ağlamak erdirir başımızı göğe ağlamak tatlı bir elle uyandırır bizi uykumuzdan ağlamak sabahlara kadar ağlamak yorma...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aslinda-gulmek-isin-asli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Altında Yaşam', 'gunesin-altinda-yasam-ethem-vayvayli-vk1nw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I.

kasaba neden yağmalandı, ahbab? 

vergiler ödenmedi mi? 

boyun eğerek geçilmedi mi, 

güneşin altından? 

renkler çoşkun köpükleriyle, 

okşamadı mı saçlarınızı? 

kasaba neden yağmalandı, ahbab? 

II.

Şimdi durun gitmeyin

Halatları geri bağla, ahbab! 

kapıları açık tut çaycı

sabahlara, akşamlara kadar kalalım

uzaklara gitmaya ne gerek

bu topraklarda güneşle doğduk

ve altından geçtik boyun eğerek

bu topraklar bizim! 

kalalım burda, zaman geçmez artık

yaşlanmayız geceleri boyarız beyaza

görmez bir resmimizi diğer bir resmimiz

karşı gelmeyiz hükümete

renkler çoşkun köpükleriyle okşar saçlarımızı

kalalım burda zaman geçmez artık

(05 Nisan ''00, Ankara)', 'I. kasaba neden yağmalandı, ahbab?  vergiler ödenmedi mi?  boyun eğerek geçilmedi mi,  güneşin altından?  renkler çoşkun köpükleriyle,  okşa...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gunesin-altinda-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şarkı Tutturup Gittim Nihâl', 'bir-sarki-tutturup-gittim-nih-l-ethem-vayvayli-tnwei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'göç yorgunu leyleklerin dalgın bakışlarıyla

deniz berraklığında bir kemana vurdum parmaklarımı

''aldırma sinemde bir sızı var'' diye de içten bir şarkı

tutturdum gittim nihâl

bu sabah kalkar kalkmaz yaptım bunları

saçlarıma bakar bakmaz anlasana

hatırladın değil mi ne kadar büyüdüğümüzü

en az seni sevebilecek kadar nihâl

bir suçum olduğunu biliyorsun ve bazen

en acı mevsim fotoğraflarıyla doluyorsun odama

sen odamdayken yaptım tüm bunları ben

sana dokunmamak için nihân

dokunduğumda yıkılıyorsun ağlayarak

baktığımda boğuluyorsun berraklığın ortasında

işte seni çağırarak ve senden kaçarak

bir şarkı tutturdum gittim nihâl

bu şarkı bizim şarkımızdı

çocukluğumuzu kuşlarla bölüştüğümüz akşamların

alevde açan utangaç çiçeklerimizin

ve sıcacık denizde yüzen gözbebelerimizin şarkısıydı

söyledim ve sustum nihâl

sen hiç dinlemedin ki! ...

(11 Ocak ''00, Kıztaşı, İstanbul)', 'göç yorgunu leyleklerin dalgın bakışlarıyla deniz berraklığında bir kemana vurdum parmaklarımı ''aldırma sinemde bir sızı var'' diye de içten ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-sarki-tutturup-gittim-nihal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Gözler', 'yesil-gozler-hasan-ozemek-gc10l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevdaya tutkun bu yorgun yüreğim, 

Çok yıllar eskittim bu sevda uğruna, 

Yeşil gözlerin unutulur mu bir tanem, 

Beynime yüreğime nakşettim o güzel gözlerini, 

Artık esiri olamam bir başka sevdanın, 

Her yıl bir sarı gül saklıyorum senin için, 

Saklıyorum yılların sevgisini yüreğimde, 

Bekliyorum yeşil gözlerini...

Bekliyorum hasretimi dindirecek o günü...', 'Bir sevdaya tutkun bu yorgun yüreğim,  Çok yıllar eskittim bu sevda uğruna,  Yeşil gözlerin unutulur mu bir tanem,  Beynime yüreğime nakşett...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yesil-gozler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksullaşan Zaman', 'yoksullasan-zaman-ethem-vayvayli-5z239', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgili nüveyla, herşey bir duman

Gözyaşlarım sele dolduğu zaman

Yık göçünü bana kınalı kervan

Güz geldi de yine kalmadı kimsem

Yaz karları erir çoşar dereler

Sen gelmezsen bu dert beni pareler

Yıllar yılı tatlı idi yareler

Artık verem oldu kalmadı kimsem

çal kavalı derdi koca ihtiyar

Turnalar sürüyü çeker her bahar

Yağar obalara diz boyu kar

Kapandı kapılar kimsem kalmadı

(2000, Ankara)', 'Sevgili nüveyla, herşey bir duman Gözyaşlarım sele dolduğu zaman Yık göçünü bana kınalı kervan Güz geldi de yine kalmadı kimsem Yaz karları ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoksullasan-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-hasan-ozemek-m6wtq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensizliğin bilmem kaçıncı yıldönümü, 

Yine dostlarımla kutluyorum bu balıkçı meyhanesinde, 

Bir eğreti masa köşede, 

O benim masam, 

Örtüsü lekeli durur hep..

Bir ucuz şarap kadehte, 

Mumlar yanmaz yıldönümlerinde..

Duvarda tozlanmış bir tablo, 

Ağ çeken balıkçılar..

Kırmızı bir lamba var tavanda..

Dostlarla beraber bu balıkçı meyhanesinde..

Bir yıldönümü daha kutlanıyor, 

Sensizliğe kalkıyor kadehler..

Alışmak kolay olmadı ama, 

Alıştım sensizliği de...

Unutmak var ya unutmak..

Unutmaya da bir alışsam...

O zaman bulacağım yeni aşkı......', 'Sensizliğin bilmem kaçıncı yıldönümü,  Yine dostlarımla kutluyorum bu balıkçı meyhanesinde,  Bir eğreti masa köşede,  O benim masam,  Örtüsü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayat-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teselli', 'teselli-hasan-ozemek-ki4u6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnız bir gecede, gecenin sessizliği..

Bir köpek havlıyor iki sokak ötede..

Gecenin sessizliği bozuluyor, 

Gökyüzünde yıldızlar sıra sıra, 

Saymaya çalışıyorum..olmuyor, 

En iyisi hepsini bir torbaya doldurmak, 

Bir bekçi düdüğü çalıyor uzunca..

Senin gidişin sensizliği getirdi sanıyordum..

Yanılmışım.

Gecelerde dostlar var..

Yakınlarda bir bekçi...

İki sokak ötede bir köpek, 

Ve bir torba yıldızım var....', 'Yalnız bir gecede, gecenin sessizliği.. Bir köpek havlıyor iki sokak ötede.. Gecenin sessizliği bozuluyor,  Gökyüzünde yıldızlar sıra sıra, ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/teselli-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıyorum', 'kaciyorum-hasan-ozemek-oc5a0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden kaçıyorum çok uzaklara, 

Aşkından sevginden...

Kaçtıkça yaklaşıyorum, 

Yaklaştıkça korkuyorum sevginden, 

Senden kopamıyorum işte..

Yağmur yağıyor, kırçiçekleri sırılsıklam, 

Kırçiçekleri öylesine sevinçli ve mutlu..

Ben yağmuru sevmiyorum, 

Siyah saçlarından süzülürken güzeldi yağmur, 

Oysa yalnızım, 

Yeşili bile sevemiyorum yalnızken, 

Gözlerin bende uzakta, 

Senden kaçıyorum....kaçıyorum..

Ama kaçtıkça yaklaşıyorum korktuğum aşka...', 'Senden kaçıyorum çok uzaklara,  Aşkından sevginden... Kaçtıkça yaklaşıyorum,  Yaklaştıkça korkuyorum sevginden,  Senden kopamıyorum işte.. Y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaciyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama Ümitlerim', 'yasama-umitlerim-ethem-vayvayli-fpos5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilemiyorum, doğduğum toprağı seviyorum

Güldüğüm sabahı ve tonca yalnızlığı

Islayıp kuruttuğun yağlıcan çiçeklerini

Sonsuz ve ılık şarkıları, dikenli gülleri

Varolmayı ve hasreti seviyorum

Sulara dökülen akşam üveyklerini

Alacakaranlıklardan damlayan yağmuru

göüsünden akan kanı, vurulduğunda

Tilki deliği önünde sabahlayan avcıları

Çareyi ve soğuyan iklimlerin canlılığını

Kutsal kitaplarda yazan insan anlığını

ve kurtarılmış, fethedilmiş toprakları

Senin gibi seviyorum

Bir de alabacaklı ekin başağını

Tepeleri çapraz kuşatan taş sıralarını

Ovaları birbirinden ayıran ara yolları

Ayak izlerini ve sabah andlarını

Elbet sevginin içtenliğini, soğukkanlılığını

Çığlıkların mahpus ve hür olabildiği kırları

Suların akışkan ve yorgun düştüğü ırmakları

Seni alev gibi saran gelincik tarlalarını

Yonca yeşilini, başak sarısını, yaprak kızıllığını

Seni sever gibi seviyorum

(08 Haziran ''00, Ankara)', 'Bilemiyorum, doğduğum toprağı seviyorum Güldüğüm sabahı ve tonca yalnızlığı Islayıp kuruttuğun yağlıcan çiçeklerini Sonsuz ve ılık şarkıları...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yasama-umitlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-huseyin-taha-t5le8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sende gittin ya, 

Ömrüm bitti.

Neden, nereye diyemeden, 

Gitme, kal diyemeden gittin.

Oysa dünyamda

Bir sen kalmıştın, 

Bir sendin hayattan beklentim, 

Umudumdun, 

Gitmek zorundamıydın, 

Bilmem ama

Sende gittin ya, 

Ömrüm bitti.

Anlarsın işte, 

Bir sendin.

Gözlerinin mavisiydi denizim, 

Saçlarının sarısıydı ekinim, 

Oksijenimdi teninin kokusu.

Yani sevdiğimdin, 

İlham perim, 

Bulgur aşım, 

İçtiğim suyum, 

Damarlarımdaki kanımdın.

Sende gittin ya, 

Ömrüm bitti.

Bu son şiirim, 

Bu son seslenişim hayata.

Belki dönersin bir gün, 

Ulaşırsa bu kağıt sana, 

Vasiyetimdir, 

Bir ömür sakla.

Bilirsin

Dayanamam ağlamana

Ama bir kerecik ağla, 

Benim için ağla, 

Mezarımın başında, 

Göz yaşların dökülsün toprağıma, 

Söndürsün yüreğimin ateşini, 

Yaşarken olmasada, 

Doyayım aşka! 

Elveda...', 'Sende gittin ya,  Ömrüm bitti. Neden, nereye diyemeden,  Gitme, kal diyemeden gittin. Oysa dünyamda Bir sen kalmıştın,  Bir sendin hayattan ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/elveda-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-huseyin-taha-spr2q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben; 

Yalnızlık kuyusuna düşmüş bir yusuf, 

Kanadı kırık doğmuş, hiç uçamamış bir kuşum, 

Ben; 

Gözlerinden fırat akan bir varoş, 

Yüreginde fırtınalar kopan bir okyanusum, 

Ben; 

Kutuplarda, imkansızda açmış bir gül, 

Güneş görmemiş, baharında solmuşum.

Ben; 

Gök yüzünün derinliklerinde bir yıldız, 

Geceleri azad, gündüzlerde yok olmaya mahkum olmuşum.

Ben; 

Şehir denen yerlerin sokaklarında, 

Dost, dost diye gezen mecnun olmuşum.

Ben; 

Bir kelebeğin peşine düşüp, 

Gerçeği dağlarda bulmuşum.

Ben; 

Genelde bir davulcu olup, 

Tokmağı hep kendi kafasına vurmuşum.

Siz Görmesenizde! 

Siz Bilemesenizde..

Ben Yaşıyorum...', 'Ben;  Yalnızlık kuyusuna düşmüş bir yusuf,  Kanadı kırık doğmuş, hiç uçamamış bir kuşum,  Ben;  Gözlerinden fırat akan bir varoş,  Yüreginde...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-huseyin-taha-3f0pf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüzün demir atmış içime, 

Ümitle yelken açamıyor yüreğim.

Batmak korkusu mahvediyor beynimi, 

Yeniden, yine sevemiyorum ben.

Ağzım yanmış bir kere, 

Terkedilmiş, kahredilmişim ya, 

Yüreğim sökülmüş, uçurumdan itilmişim ya, 

Doğrulamıyor, toparlanamıyorum ben.

Giyemiyorum artık mavi takım elbiseyi, 

Sevda ıslığı öttüremiyor dudağım, 

Bir güzele bakamıyor gözlerim, şöyle yeşil yeşil, 

Aşık olmayı beceremiyorum ben.

Diyemiyorum kendime sen bir devsin, 

Diyemiyorum dediği gibi yükü ağırdır devin, 

Sökemiyorum kabusu içimden, 

Yaşamayı beceremiyorum ben...', 'Hüzün demir atmış içime,  Ümitle yelken açamıyor yüreğim. Batmak korkusu mahvediyor beynimi,  Yeniden, yine sevemiyorum ben. Ağzım yanmış bi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olmuyor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-huseyin-taha-a655b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güle bülbül ne kadar yakışıyorsa, 

Sanada öyle yakışıyor gülmek.

Karanlık boşluğu nasıl süsküyorsa yıldızlar, 

Senide öyle süslüyor gamzelerin.

Sen hüzünlüysen eğer, 

Şimşekler çakıyor beynimde, 

Sis çöküyor geceme, 

Ne yıldızlar kalıyor, 

Ne mehtap, 

Nede bende hayat.

Gülmelisin; 

Gülesin ki; 

Işık olsun dişlerin, 

Gülesin ki; 

Mehtap olsun gözlerin, 

Gülesin ki; 

Aydınlansın karanlık dünya, 

Hayat versin, can olsun bedene.

Hadi! 

Gül artık can...', 'Güle bülbül ne kadar yakışıyorsa,  Sanada öyle yakışıyor gülmek. Karanlık boşluğu nasıl süsküyorsa yıldızlar,  Senide öyle süslüyor gamzeler...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gulumse-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-huseyin-taha-q5xbt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Keşke çocuk olsaydım sevdiğin, 

Şefkatli avuçların okşasaydı saçlarımı, 

Sen hayal ülkenden masallar anlatırken, 

Usulca uyusaydım dizlerinde.

Keşke gözlük olsaydım yorgun gözlerindeki, 

Daha net göstere bilseydim sana papatyaları, 

Büyük bir hazla dolaşırken gönül bahçelerinde, 

Görseydin ezdiğin papatyanın yaprağındaki beni.

Keşke sol omuzundaki meleğin olsaydım, 

Sana hiç günah yazmasaydım, yanmasaydın, 

Ulu olsaydım bağışlasaydım seni, 

Cennetim olsaydıda koysaydım.

Keşke kusursuz olsaydım, pişmanlık duymasaydım, 

Gönlünce yaşatsaydım seni, ağlatmasaydım, 

Keşke, keşkeler olmasaydı, isteseydim olsaydı, 

Keşke sen yanımda olsaydın...', 'Keşke çocuk olsaydım sevdiğin,  Şefkatli avuçların okşasaydı saçlarımı,  Sen hayal ülkenden masallar anlatırken,  Usulca uyusaydım dizlerind...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/keske-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kahretsin', 'kahretsin-huseyin-taha-ca466', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sabah 

Bir başka havam, 

Kusura bakma kalamam.

O biçim takım elbisem, 

Cılalanmış kunduram.

Kahretsin! 

Bu gün yine çok yakışıklıyım, 

Gibi bir tebessüm, 

Aynadan bana yansıyan.

Çıkmışım yola, 

Herkes bana bakıyor ya, 

Dudağımda ıslık, 

Cüzdanımda aylık, 

Zulamda cıgaram, 

Ve aklımda sen, 

Elimde bir demet karanfil, 

Yarın yapamayacak olsamda, 

Bu gün yakacağım çıranı bil...

Dedim ya; 

Bu gün yerinde fiyakam, 

Dert anlatmam, 

Keder saçmam, 

İnan bu gün seni ağlatmam, 

O biçim takım elbisem, 

Cılalanmış kunduram, 

Zulamda cıgaram, 

Cebimde param, 

Bu gün her şey tamam, 

Bu gün bir başka havam...', 'Bu sabah  Bir başka havam,  Kusura bakma kalamam. O biçim takım elbisem,  Cılalanmış kunduram. Kahretsin!  Bu gün yine çok yakışıklıyım,  Gi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kahretsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-huseyin-taha-zvkf4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şiiri sana yazıyorum ana, 

Her şair şiir yazar ama

Olmayan analarına, 

Yürekleri yanar ana

Sesini duyamadıklarına, 

Dizlerinde yatamadıklarına, 

Göz yaşları yüreklerine akar ana.

Sen yanımdasın ana, 

Merhametli avuçlarında yüzüm.

Dizlerinde uyuyorum ana, 

Bağrına yaslanıyorum, 

Doyasıya sarıyorum, 

Hiç ağlamıyorum

Çünki benim anam var, 

Dualar ediyorum Allah''a

Şükürler ediyorum 

Benim anam var, 

Sende dua et ana, 

Anası olmayanlara, 

Adına şiirler yazılamayan analara, 

Dua et ana.

Çok üzüyorum seni, 

Farkındayım ana

Üzmek istemiyorum seni ama

Kul hata yapar ana, 

Beni bağışla, 

Bağışla ana...', 'Bu şiiri sana yazıyorum ana,  Her şair şiir yazar ama Olmayan analarına,  Yürekleri yanar ana Sesini duyamadıklarına,  Dizlerinde yatamadıkl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ana-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amatörüz', 'amatoruz-ramazan-hakan-ayhan-d1a1y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir uykuda

Bir kuytuda bıraktın gittin

O gün büyüklüğündü çarptığın suratıma

Ben de kalabalık oluyorum işte o tenhalara

Zaman tırnaklarıyla çiziyor gözlerini

Ve zaman ortaklarıyla siliyor izlerini

Kendini kaybettiğin zaman buldun sen kendini

kendimi kaybettiğim zaman da sen bulmuştun beni

uzun bir hikaye bu

ve başıboş bir kinaye bu

eğer hala anlatamıyorsa kendini

belki kırık bir sevcdadır işin konusu

sonunda sabahları suratına çarpar kesik alkol kokusu

anlattığım anlamadığın

aslında hayata nazır amatörlüğümüz

aradan yıllar geçti ama

biz hala çengelin altına nokta koyuyoruz

çabalamak nafile güzelim güzelliğim

bu yıl eksiği de amatörüz

artık uzatmak gereksiz

artık uzamak gerekli

bilirsin yüzsüzlüğümü

hadi bir elveda fırlatta suratıma

belki bir gün bir yerlerde yine görüşürüz', 'Bir uykuda Bir kuytuda bıraktın gittin O gün büyüklüğündü çarptığın suratıma Ben de kalabalık oluyorum işte o tenhalara Zaman tırnaklarıyla ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Hakan Ayhan']::text[], 8.5, '{"poet":"Ramazan Hakan Ayhan","poet_slug":"ramazan-hakan-ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/amatoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Gülüm Anlat', 'anlat-gulum-anlat-huseyin-taha-086yp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlat gülüm anlat

Aydınlat beni, 

Yalanlar diz yine

Her zamanki gibi mavimsi, 

Birde buse kondur yüzüme

Beni mahveden türden olsun, 

Hiç bozuntuya verme, 

Ben inanıyor olayım

Sen inandırıyorsun san, 

Öylece dalayım

Baktıkça kaybolayım gözlerinde, 

Sonra, bırak saçlarını rüzgara okşasın

Ben dokunamadım doyasıya

Bari onlarla dalgalansın.

Sokul şöyle birazda yanıma, 

Usulca! ..

Sevda türküleri söyle yine

Beni adına adatsın, 

Kanayım sözlerine

Olmayacağını bile bile, 

Batmasın istersen güneş

Akşam olmasın de, 

Bizi ayıran otobüs hiç gelmesin de, 

Seni seviyorum demeyide sakın unutma, 

Her zamanki gibi

Sıradan ve yüreğin sızlamadan...

Al işte

Tüm ipler elinde

Saf ve aptal bir aşık

Tam karşında duruyorum, 

Onca hatana rağmen

Seni yine affediyorum, 

Yine aldatsanda

Kalbimi sana veriyorum, 

İster at, ister sat

Ama bir kez olsun

Gözlerime kalbinle bak

Ve ardından yüreğime ak, 

Acılarımdan bir damlacık

Sende tat...', 'Anlat gülüm anlat Aydınlat beni,  Yalanlar diz yine Her zamanki gibi mavimsi,  Birde buse kondur yüzüme Beni mahveden türden olsun,  Hiç boz...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/anlat-gulum-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal Öylece', 'kal-oylece-huseyin-taha-vko4n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak gözlerime, 

Yüreğime giden pencereden.

Gitme diye feryat eden, 

Duy sesini kalbimin, 

Kal öylece.

Yine gece olsun, 

Bakışalım pencerelerden.

Lambalar sönük gizlice, 

Farketmesin kimse bizi.

Gözlerimiz konuşsun sadece

Ve bekle, 

Çıkacak birazdan mehtap, 

Bırakma beni yalnızlığa.

Biliyorum yasaksın bana, 

Bende sana

Ama ölümüm uğruna olsun.

Çıkalım bu gece semaya, 

Yürüyelim saman yolunda, 

Sığınalım kuytu bir yıldıza, 

Damla damla içelim aşkı, 

Bitmesin birden, 

Güneş doğmasın hiç, 

Herkes uyusun dünyada, 

Biz sevişelim delice.

Yasak olan ne varsa, 

Hepsini yapalım bu gece...', 'Bak gözlerime,  Yüreğime giden pencereden. Gitme diye feryat eden,  Duy sesini kalbimin,  Kal öylece. Yine gece olsun,  Bakışalım pencereler...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kal-oylece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-huseyin-taha-nhhdb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boşluk

Ufku sonsuz bir boşluk, 

Hiç bir şey değil hayat, 

Gözlerin ellerin hiç bir şey.

Bomboş dünya döner, 

İnsanlar, caddeler, evler yok.

Rüzgar, yapraklar yalan.

Aslında ıslatmıyor yağmur, 

Deniz boğmuyor insanı.

Boğazın manzarası bir rüya, 

Senden geriye kalan, 

Hayalin yalan, rüyam yalan, 

Sende yalansın.

Bir kemik torbası bende kalan, 

Gülmeyi unutan, 

Her saniye ağlayan, 

Bir damla yaş çıkmayan, 

Gözlerim yalan.

Ruhu sende kalan, 

Cesetimde yalan.

Öyle bir boşluk ki; 

Çıkılması imkansız bir kuyu.

Kapattım gözlerimi, 

Bir şeyler yazan, 

Elimdeki kalem yalan.

Yazılanlarda yalan.

Birazdan doğacak olan, 

Güneşte yalan.

Yalan olan, 

Tüm yalanlarda yalan.

Boşlukta kalan

...İnsan...', 'Boşluk Ufku sonsuz bir boşluk,  Hiç bir şey değil hayat,  Gözlerin ellerin hiç bir şey. Bomboş dünya döner,  İnsanlar, caddeler, evler yok. ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taha']::text[], 8.5, '{"poet":"Hüseyin Taha","poet_slug":"huseyin-taha","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bosluk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kını Toprağa Verdik Kılıç Şimdi Daha Keskin', 'bir-kini-topraga-verdik-kilic-simdi-daha-keskin-mustafa-i-slamoglu-04o73', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sure sure işlemişler göğsünü tavusumun 

adresime çıkartılmış baharagöz değmişler 

gün vurdukça hatırana, daralıyor nefesim 

öylesine bin acıya tahammül etse de 

bu cevre tahammül etmez göğüs kafesim 

aşk iğnesi, yürek oltası 

sakalının tellerine değmiş olmak için rüzgar 

bugün daha bir telaşlı 

bugün ekmek yapmıyor annem 

çün soframız hüzün kaplı 

bu ne göç ediştir bre, bune acı uçuştur 

kırılmıştır hala çırpar serçemin kanatları 

can bir yana, ten bir yana 

vurulduktan sonra baba gördüm koşan atları 

Yasin yelesinde bin Hıra saklı 

sağrısında kan damlıyor izlerinin üstüne 

ardından yankılanıyor hasretin hoyratları 

vurmasınlar 

vurmasınlar söyle 

vurmasınlar söyle baba şaha kalkan atları 

(Haziran 1989)', 'sure sure işlemişler göğsünü tavusumun  adresime çıkartılmış baharagöz değmişler  gün vurdukça hatırana, daralıyor nefesim  öylesine bin acı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İslamoğlu']::text[], 8.5, '{"poet":"Mustafa İslamoğlu","poet_slug":"mustafa-i-slamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-kini-topraga-verdik-kilic-simdi-daha-keskin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Dağları Sevmiştim', 'ben-daglari-sevmistim-mustafa-yildiz-2-i95pf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oy gülüm! 

Ben dağları sevmiştim

Ölümüne

Dört yanım orman

Dört yanımda pusu

Kuş sesleri değil

Kurşun sesleri duyulan

Dağları sevmiştim 

Ölümüne

Oy gülüm! 

Ben dağları sevmiştim

Ölümüne

Dört yanımda duman

Dört yanım sis

Her kayanın ardından

Bir çift göz değil

Bir çift namlu parlayan

Dağları sevmiştim 

Ölümüne

Oy gülüm! 

Ben ki ölümü

Bir namluda saklanan

Bir çift kurşundan beklerken

Bir gece 

Gözleri namlu değil

Gözleri nemli

Bir ceylan indi dağdan

Ve ben vuruldum

Ah! Bilemezdim

Ölümün, 

Gözleri namlu değil

Gözleri nemli

Bir ceylanın 

Bakışından olacağını

Oy gülüm! 

Meğer ki her dağ 

Bir ceylan saklarmış

Ve anladım ki dağ

Ceylanı varsa dağmış', 'Oy gülüm!  Ben dağları sevmiştim Ölümüne Dört yanım orman Dört yanımda pusu Kuş sesleri değil Kurşun sesleri duyulan Dağları sevmiştim  Ölüm...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız 2']::text[], 8.5, '{"poet":"Mustafa Yıldız 2","poet_slug":"mustafa-yildiz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ben-daglari-sevmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençliğim', 'gencligim-kemal-lacin-a2wde', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir baktım kendime

Gençligim gitmiş elden

Tekrar geri dönmez gençligim

Gençligim gençligim offff

Bırakın bir bizi

Bizde yaşayalım şu yalan dünyada

Zaten felek silesini vurmuş bize

Vurmuş bize vurmuş bize  oy 

5.7.1986

  Bursa', 'Bir baktım kendime Gençligim gitmiş elden Tekrar geri dönmez gençligim Gençligim gençligim offff Bırakın bir bizi Bizde yaşayalım şu yalan d...', ARRAY['Türk Edebiyatı','Şiir','Kemal Laçin']::text[], 8.5, '{"poet":"Kemal Laçin","poet_slug":"kemal-lacin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gencligim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum Buralardan', 'gidiyorum-buralardan-hayrettin-tarhan-dh592', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidiyorum artık buralardan

Sorma sakın sebebini bana

Binlerce buket bırakıyorum

Yaşanan mutlu günlerden sana

Kolay değil bu zamansız gidiş

Bu belki hayattaki son bitiş

Aşkta, varlıktan yokluğa geçiş

Çok zor bunları anlatmak sana

Zorda olsa bir gün unuturum

Susup ta kaderime yanarım

Gerçek huzuru çok zor bulurum

Mutluluk versin yarınlar sana...', 'Gidiyorum artık buralardan Sorma sakın sebebini bana Binlerce buket bırakıyorum Yaşanan mutlu günlerden sana Kolay değil bu zamansız gidiş B...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidiyorum-buralardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gömdük Sevdayı', 'gomduk-sevdayi-hayrettin-tarhan-8euv4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Issız bir seherde başladı bu yolculuk

Türküleşmiş iklimlerde öğrendik biz sevdayı

Umut denizlerinde sürdü tutsaklığımız

Çile sahillerine gömdük sonunda sevdayı

Tez soldu sevdanın nuru gözlerimizde

Denizin çığlıklarına kattık feryatlarımızı

Tükenmeyen çocukça özlemlerimizle

Yakamozlarla süsledik sevdalarımızı

Şehrin soluk gün batımı akşamlarında

Bir yaşama türküsü var dudaklarımızda

Biz bu masum zamanın en acımasızlığında

Yüreklerimize sinsice gömdük sevdayı', 'Issız bir seherde başladı bu yolculuk Türküleşmiş iklimlerde öğrendik biz sevdayı Umut denizlerinde sürdü tutsaklığımız Çile sahillerine göm...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gomduk-sevdayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhule Kalkan Gemi', 'mechule-kalkan-gemi-hayrettin-tarhan-ni19f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gemi kalkmakta limandan

Yolcuları ise çileli

El sallayan yok arkasından

Meçhule yolculuğu belli.

Yalnızlık kokuyor rıhtımlar

Hasret çöreklenmiş içimde

Huzur vermese de akşamlar

Sevdan yaşamakta içimde

Hayal değil gerçeğin kendi

Yıkılıyor bende umutlar

Sensizliğe kalkıyor bu gemi

Acı devşirecek yarınlar.', 'Bir gemi kalkmakta limandan Yolcuları ise çileli El sallayan yok arkasından Meçhule yolculuğu belli. Yalnızlık kokuyor rıhtımlar Hasret çöre...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mechule-kalkan-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Türküsü', 'kus-turkusu-behcet-necatigil-x3c13', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vurur gurbetteki kuş pencere pervazına

Şefkatli bir ekmek kırıntısı

İyi kalpli bir kız

Al git, al git, al git! 

Sevgi mi, yankı mı, kıyı
..........
..........', 'Vurur gurbetteki kuş pencere pervazına Şefkatli bir ekmek kırıntısı İyi kalpli bir kız Al git, al git, al git!  Sevgi mi, yankı mı, kıyı ......', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kus-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-hayrettin-tarhan-ujanl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne umutlar bıraktık sokaklarda

Bazen öfkeli bazen suskunduk biz

Hayaller kurduk biten akşamlarda

Sevdaya küskün aşka kırgındık biz.

Varılmaz sandığımız zamanlarda

Kurudu karanfiller dallarında

Uçsuz bucaksız sevda ovasında

Kadere küskün aşka kırgındık biz.

Tuzak kurunca hazan yolumuza

Bir damla yaş düştü avcumuza 

Anladık yasak konmuş aşkımıza

Sonunda hayata da küstük biz.', 'Ne umutlar bıraktık sokaklarda Bazen öfkeli bazen suskunduk biz Hayaller kurduk biten akşamlarda Sevdaya küskün aşka kırgındık biz. Varılmaz...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşere Kaldı', 'mahsere-kaldi-hayrettin-tarhan-o5jjy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Var mı hiç dünyada böyle çok seven

Sensin kıymetini bilmeyip giden

Sevdayı hor görüp ihanet eden

Seninle hesabım mahşere kaldı

Ömrümde açan tek güldün; kurudun

Bir zamanlar canıma can olurdun

Üç günlük dünyada neden unuttun? 

Seninle hesabım mahşere kaldı.

Yalan sevdayla gelmeseydin bana

Sevmek değil can verirdim yoluna

Dönüp geri bakmasan da arkana

Seninle hesabım mahşere kaldı.', 'Var mı hiç dünyada böyle çok seven Sensin kıymetini bilmeyip giden Sevdayı hor görüp ihanet eden Seninle hesabım mahşere kaldı Ömrümde açan ...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mahsere-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deştin Yaramı', 'destin-yarami-hayrettin-tarhan-j4duf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıkıp ta karşıma deştin yaramı

Hayal dünyasında yaşıyordum ben

Yazılmış anlıma bahtı karalı

Nasıl mutlu sevenler şaşarım ben.

Görmedim huzuru doğuştan körüm

Derde benzemiyor çektiğim zulüm

Böyle mi olurmuş sevince ölüm

Çile dünyasında yaşıyorum ben.

Bulunmuyor çare umutlar yasta 

Sevdiğimden beri yüreğim hasta

Ne düşünür ki eller bu hususta

Kaderime yanıp yaşıyorum ben.', 'Çıkıp ta karşıma deştin yaramı Hayal dünyasında yaşıyordum ben Yazılmış anlıma bahtı karalı Nasıl mutlu sevenler şaşarım ben. Görmedim huzur...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/destin-yarami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BENİ', 'beni-hayrettin-tarhan-xzepv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BENİ

Erince ömrüm son demine

Kar suyuyla yıkayın beni

Bir karış toprağın içine

Karanfillerle gömün beni

Üşütürüm diye korkmayın

Duayla uğurlayın beni

Geçse de zaman unutmayın

Şiirlerimle anın beni

İsteyen övsün hiç durmadan

İsteyen her gün yersin beni

Tek vasiyetim insanlardan 

Kurutmayın karanfillerimi.', 'BENİ Erince ömrüm son demine Kar suyuyla yıkayın beni Bir karış toprağın içine Karanfillerle gömün beni Üşütürüm diye korkmayın Duayla uğurl...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-hayrettin-tarhan-samf3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her anımda hüzün hasret dolusun

Gözümde çağlayan akar su musun

Bırak göz yaşlarım biraz kurusun

Çekilmez bir azap gibisin gurbet

Taşımaz bedenim hazan yükünü

Sevdada başladı yaprak dökümü

Biraz kulak ver de dinle öykümü

Sen benim başıma belasın gurbet

Ne gelir ki elden kalmışım naçar

Umutlar uzaktan gülüp te geçer

Dost bildiklerim se görünce kaçar

Kanayan yaramda bıçaksın gurbet

Memleket sorarsan adı dilimde

Geçmişin acısı azap gönlümde

Hakkımda ne dersen aynen seninde

Yaşarken öldüren ecelsin gurbet.', 'Her anımda hüzün hasret dolusun Gözümde çağlayan akar su musun Bırak göz yaşlarım biraz kurusun Çekilmez bir azap gibisin gurbet Taşımaz bed...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurbet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Bıraktır Gerimize', 'ne-biraktir-gerimize-hayrettin-tarhan-8sa3b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar yılı boşuna mı yürüdük 

Nihayet bir arpa boyu ömürde

Gün geldi ağladık gün geldi güldük

Söyle kalan neydi ellerimizde

Gecelerden gündüze aktık durduk

Bilemedik ki biz neye tutkunduk

Acıya da hasrete de yutkunduk

Söyle kalan neydi ellerimizde

Anladık buymuş işte kaderimiz

İsyan kime, kime ne söyleriz

Sustu, söylemez oldu dillerimiz

Binlerce ah bıraktık gerimizde', 'Yıllar yılı boşuna mı yürüdük  Nihayet bir arpa boyu ömürde Gün geldi ağladık gün geldi güldük Söyle kalan neydi ellerimizde Gecelerden günd...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-biraktir-gerimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tıpkısının Aynısı', 'tipkisinin-aynisi-sair-astor-nzz3y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün perşembe 

Yarın ise cuma 

Ondan sonra ki gün ise cumartesi

Ve daha sonra ki günde pazar

Pazardan sonra pazartesi gelecek

Pazartesi bittikten sonra salı

Çarşamba salıdan sonra 

Ve ondan sonra gene başladığım yerde olucam

Yani hep sayıkladığım, olduğum yerde kalıcam

Yani ben hep ben gibi olucam

Ve sizde beni ben gibi görüceksiniz hep', 'Bugün perşembe  Yarın ise cuma  Ondan sonra ki gün ise cumartesi Ve daha sonra ki günde pazar Pazardan sonra pazartesi gelecek Pazartesi bit...', ARRAY['Türk Edebiyatı','Şiir','Şair Astor']::text[], 8.5, '{"poet":"Şair Astor","poet_slug":"sair-astor","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tipkisinin-aynisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-selva-zeyveli-p5anb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dört mevsim yaşanırdı memleketimde 

Temiz yaratılmış fıtratta lekenin

Aykırı durduğunu insanda 

Düşünmek için mi nedir 

Ya da kefeni hatırlatmak için sanki 

Her yer beyazlar giyerdi bir mevsim 

Kayardı çocuklar karda 

Karlar kadar saf temiz dugularla 

Güneş gülümseyen yüzünü gösterdiğinde 

Damlardaki saçaklar erirken damla damla 

Eşlik ederdi bulutlar nice gönüllerdeki hüzne ye de umuda 

Nisan yağmurlarıyla beraber 

Bir anda coşar, birden durulurdu yürekler 

Tomurcuklanan ağaçlar gibi 

Tomur tomur şükürle, umutla doluydu kalpler 

Yeniden yaratılışı temsil için belki 

Bu kez, çıplak dalları sarardı çiçekler. 

Uçururdu kırlarda çocuklar 

Gökte özgürlükle buluşan uçurtmalar 

Yeşile döndüğünde dallar 

Olmaya başlardı artık kaysılar 

İyice ısınınca havalar 

Dolgunlaşırdı pancarlar sararırdı başaklar 

Gün tam tepedeyken 

Hasada hazırlanırdı insanlar 

Gerçek hasadı hatırlamalı 

Ona da hazırlanmalı kullar 

Oynardı çocuklar sularda 

Oynardı bir oyun bir oyalanmayla hayatla 

Ve bir mevsim sararırken yapraklar 

Bir sonun, 

Gerçekte bir başlangıcın arefesinde 

Lahuti bir nağmeyle 

Ayrılığa türkü yakardı rüzgarlar 

Solgun çehresini gizlemek için 

Bukez güneşe yaşmak olurdu bulutlar 

Bereketli topraklar 

Düşlerini başka bahara ertelese de 

Hazanı yaşamaktan kaçamazdı gene de 

Oynardı çocuklar bağlarda 

Oynardı raksederek düşen yapraklarla 

Gökte yıldızlar 

Daha bir parlak dönerdi feleklerinde 

Ve ay her çocuğu takip ederdi 

Ortak olurdu hayallerine 

Horaz sesleriyle harmanlanan ezanlar 

Çağırırdı seherlerde mescitlere 

Böyleydi memleketim... 

Ya şimdi 

Öpülüyor mu bayramlarda büyüklerin elleri 

Hatırlıyor mu evlatlar vefakar anneleri 

Büyütüyor mu anneler nice Battal Gazileri 

Karpuz çatlatıyor mu buz gibi pınarları 

Pekmez yapılıyor mu hala güzel dutları... 

İyisi kötüsüne 

Alimi cahiline galip gelen memleketim 

Elveda diyelim tüm ayrık otlarına 

Ve merhaba diyoruz tüm güzel coşkulara.', 'Dört mevsim yaşanırdı memleketimde  Temiz yaratılmış fıtratta lekenin Aykırı durduğunu insanda  Düşünmek için mi nedir  Ya da kefeni hatırla...', ARRAY['Türk Edebiyatı','Şiir','Selva Zeyveli']::text[], 8.5, '{"poet":"Selva Zeyveli","poet_slug":"selva-zeyveli","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/memleketim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Ucuyla Bakıla İstasyon Ve Akşam', 'goz-ucuyla-bakila-i-stasyon-ve-aksam-mustafa-yavuzyilmaz-bvtof', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göz ucuyla bakılan istasyon ve akşam, 

Biraz mağrur ve haddini bilmeyerek

Uzanıp dokundu elime; titreyerek

Kadehten dudağa akarcasına

Dudaktan teni yakıp

Camlardan kayan, kanayan yağmur gibi susarcasına bir

     sessizlikle

Öğrendi terk edilmeyi

Adını heceleyerek

Ve bütün yakamozlardan af dileyerek; düştü

Yüreğimin son kalesi...', 'Göz ucuyla bakılan istasyon ve akşam,  Biraz mağrur ve haddini bilmeyerek Uzanıp dokundu elime; titreyerek Kadehten dudağa akarcasına Dudakt...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yavuzyılmaz']::text[], 8.5, '{"poet":"Mustafa Yavuzyılmaz","poet_slug":"mustafa-yavuzyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/goz-ucuyla-bakila-istasyon-ve-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerle Yollarımız Ayrılmış Çoktan', 'gunlerle-yollarimiz-ayrilmis-coktan-mustafa-yavuzyilmaz-je33p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günlerle yollarımız ayrılmış çoktan

Sadece gece hüküm sürer dualarımızda

Ve dudaklarımıza kapatılmıştır; o mahrem

o gül

Kurusada solmaz

Bağışlayın yanıklarını güneşin

Takılırsam birgün peşinize, 

Hiç olmadık bir yerde olur olmaz

Basmayın; çünkü gölgeler hiç ölü doğmaz!', 'Günlerle yollarımız ayrılmış çoktan Sadece gece hüküm sürer dualarımızda Ve dudaklarımıza kapatılmıştır; o mahrem o gül Kurusada solmaz Bağı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yavuzyılmaz']::text[], 8.5, '{"poet":"Mustafa Yavuzyılmaz","poet_slug":"mustafa-yavuzyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gunlerle-yollarimiz-ayrilmis-coktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar...', 'bir-zamanlar-binay-donmez-x364e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar mutluydum! 

Aynı masallardaki gibi umutlarım pembe, 

düşlerim beyazdı...

Gözlerim bu kadar yaşa tanık olmazdı.

Avuntularım yersiz, nasıl dönebilirim geçmişe, 

ya da nasıl gidebilirim buralardan? 

Bir zamanlar mutluydum! 

İnsanlara hiç ağlamazmış gibi görünmeyi becerebilirdim.

Özletirdim aşkımı, özlerdim! 

Nasıl aşık olabilirim ki tekrar? 

tekrar nasıl sevebilirim hayatı, aşkı, suyu, toprağı? 

Yüzeye varır mıyım diye hiç bu kadar kara kara düşünmezdim

Hep bir el hayal ederdim, beni çekip çıkaran! 

Bulmuşken nasıl kaybettim o eli hiç bilmiyorum...

Bir zamanlar mutluydum! 

Başımı dayadığım bir babam, 

yüreğimi paylaştığım bir ateş vardı bağrımda.

Ama bir zamanlar!', 'Bir zamanlar mutluydum!  Aynı masallardaki gibi umutlarım pembe,  düşlerim beyazdı... Gözlerim bu kadar yaşa tanık olmazdı. Avuntularım yers...', ARRAY['Türk Edebiyatı','Şiir','Binay Dönmez']::text[], 8.5, '{"poet":"Binay Dönmez","poet_slug":"binay-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-zamanlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünceye Dek', 'olunceye-dek-orhan-arslan-2igli', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'cok mu deger verdim sana? 

yazik! 

sana mi, 

yoksa bana mi? 

martilar duysun hüzünlü sarkilarimi, 

dalgalar vursun, 

koparsin icimdeki aciyi, 

sen bahtiyar olasin diye. 

korkma, 

birdaha cikmam karsina, 

bulamazsin beni bu mekanlarda. 

bicareyim, 

bilmenem dogru mu yaptigim. 

destanlar yazacaktim, 

efsane olacakti gönüllere masal. 

geride kalan, 

ruhsuz bir beden. 

garip hallere düsmüsüm. 

heyhat, 

heba oldu cektigim elemler, 

ibret olsun diye, 

bu satirlar. 

gülistan oldu bana mezar, 

kopardigim güller icinde, 

elimde bir bardak zehir, 

dilimde senin ismin hece hece.', 'cok mu deger verdim sana?  yazik!  sana mi,  yoksa bana mi?  martilar duysun hüzünlü sarkilarimi,  dalgalar vursun,  koparsin icimdeki aciyi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Arslan']::text[], 8.5, '{"poet":"Orhan Arslan","poet_slug":"orhan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olunceye-dek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Said-i simin', 'said-i-simin-orhan-arslan-i0z34', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'said-i simin nedir bilirmisin? 

ay isiginda, su üzerinde 

gümüsten uzun bir kol gibi 

uzanan isikli yol. 

iste sen benim o isikli yolumsun. 

zifiri karanligimi aydinlatan, 

hayatima anlam veren isiksin. 

yanimda olmasan bile, 

var olusun yeter bana.', 'said-i simin nedir bilirmisin?  ay isiginda, su üzerinde  gümüsten uzun bir kol gibi  uzanan isikli yol.  iste sen benim o isikli yolumsun. ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Arslan']::text[], 8.5, '{"poet":"Orhan Arslan","poet_slug":"orhan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/said-i-simin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Kar', 'sicak-kar-senol-altiok-z8586', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kar yağdı caddelere

Gelinlik giydi şehir

Lapa lapa ısıttı

Üşüyen şu kalbimi

El ele tutuştular

Beyazlanmış ağaçlar

Hep birlikte söylediler

Mutluluk şarkısını

O beyaz örtü altında

Sıcacık oldu toprak

Yeni bir hayat için

Kapattı gözleri

Kefenle örtülünce

Titreyen şu bedenler

Sonsuzlukta açacak

Kapanan gözlerini', 'Kar yağdı caddelere Gelinlik giydi şehir Lapa lapa ısıttı Üşüyen şu kalbimi El ele tutuştular Beyazlanmış ağaçlar Hep birlikte söylediler Mu...', ARRAY['Türk Edebiyatı','Şiir','Şenol Altıok']::text[], 8.5, '{"poet":"Şenol Altıok","poet_slug":"senol-altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sicak-kar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoy Lu-Lu', 'hoy-lu-lu-orhan-veli-kanik-0r80o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İsterim benim de acaip isimleri

Hiç duyulmamış zenci arkadaşlarım olsun.

Onlarla Madagaskar limanlarından

Çin''e kadar yolculuk yapmak isterim.

İsterim içlerinde bir tanesi

Vapurun güvertesinde yıldızlara karşı

''Hoy lu-lu'' şarkısını söylesin her gece.

Ve bir gün ansızın bir tanesine

Rastgelmek isterim

Paris''te...', 'İsterim benim de acaip isimleri Hiç duyulmamış zenci arkadaşlarım olsun. Onlarla Madagaskar limanlarından Çin''e kadar yolculuk yapmak isteri...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hoy-lu-lu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİRİAM''A SON SÖZLER', 'mi-ri-am-a-son-sozler-david-herbert-lawrence-pjg7n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'MIRIAM''A SON SÖZLER

Seninki huysuz bir acı, 

       Oysa benim de yüzüm kara; 

Sevgin köklüydü, eksiksizdi senin, 

Benimki güneşe doğru büyüyen

      Tutkusuydu çiçeğin.

Beni araştırıp tanıyacak güçteydin, 

      Tomurcuklarımı bir bir açacak; 

Çektin uykulardan aldın ruhumu, 

Acıyı duyar ettin --

      O zaman tökezledim? 

Koyun koyuna sevemedim seni, 

      Sevmeyi istediysem de.

Öpüştük, belki de öpüşmemeliydik.

Boyun eğdin, kendimizi son bir denedik, 

      Beceremedik.

Sen yalnız dayandın, böylece

      Çökerttin usta direncimi.

Okşamamla titremedi hiç tenin; 

Bu yüzden gereken son ince acıyı da

      Sana çektiremedim.

Güzelsin, alımlısın

      Ama donuk ve tutuksun etinde; 

      İçine işleyebilseydim eğer

O dikenli acının olaca şiddetiyle, 

      Işıyan bir ağ çıkardı belki

Renkli bir pencere gibi; tenini

     Yakıp geçti en güzel ateş, 

Kurtardı çürümekteb, arıtıp

Kutsadı onu yeni bir duyarlıkla.

     Ama kim alır şimdi seni yeniden? 

Kim yakıp kurtarabilir seni

     Etinin ölümünden, çürümesinden? 

Artık söndüğüne göre benim de içimin ateşi, 

Hangi erkek eğilir sürüp çıkarmak için

     Etinde haykıran çarmıhı şimdi? 

Sessiz, nerdeyse güzel bir şey yüzü, 

     Baktıkça utanıyorum, 

Seni bütün yalımların içinden

Kurtarıp çıkarak kadar

     Amansız olmalıydım.', 'MIRIAM''A SON SÖZLER Seninki huysuz bir acı,         Oysa benim de yüzüm kara;  Sevgin köklüydü, eksiksizdi senin,  Benimki güneşe doğru büyü...', ARRAY['Türk Edebiyatı','Şiir','David Herbert Lawrence']::text[], 8.5, '{"poet":"David Herbert Lawrence","poet_slug":"david-herbert-lawrence","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/miriam-a-son-sozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PİYANO', 'pi-yano-david-herbert-lawrence-8wmnz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akşamın alacakaranlığında, yavaşça bir kadın

  şarkı söylüyor bana; 

Ve geçmiş yılların ötesinde, piyanonun altında

  oturmuş

Tınlayan tellerin gürültüsü içinde gülümseyerek

  şarkı söyleyen bir annenin

Pedallara yerleşmiş küçücük ayaklarını okşayan

  bir çocuğu canlandırıyor gözümde.

Şarkının esrikliğiyle, elimde olmadan, 

Kapılıp gidiyorum geçmişe, içim ezilerek özlüyorum

Evdeki o Pazar akşamlarına dönmeyi, dışarda kış

Ve sıcak salonda söylediğimiz ilahiler, piyano

  eşliğinde.

Artık boşuna şarkıcının kendini kapıp koyvermesi

Ve koca siyah piyanonun coşması. Çocukluk günlerimin

Büyüsüne kapıldım yeniden, koskoca bir adam olduğumu

  unutup

Anıların selinde, bir çocuk gibi ağlıyorum geçmişin

  özlemiyle.', 'Akşamın alacakaranlığında, yavaşça bir kadın   şarkı söylüyor bana;  Ve geçmiş yılların ötesinde, piyanonun altında   oturmuş Tınlayan telle...', ARRAY['Türk Edebiyatı','Şiir','David Herbert Lawrence']::text[], 8.5, '{"poet":"David Herbert Lawrence","poet_slug":"david-herbert-lawrence","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/piyano-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Gülleri Severim', 'siyah-gulleri-severim-belgin-kistavul-blt1k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SİYAH GÜLLER.........

Bilirsin siyah gülleri severim

Nedendir bilmem alışıla gelmiş şeyleri sevmem

Farklı olan şeyleri severim, 

Dün akşam eve dönerken bir sarı gül aldım kendime

Senin sevdiklerinden, kokladım saatlerce, 

Sonra her zaman yaptığım gibi 

Duvara ters astım onu, öyle kurutmayı seviyorum bilirsin

Tek bir yaprağı bile dökülmüyor kururken

Alışkanlıklarımda değişik sanırım kendim gibi

Sonra camın önüne oturdum karanlıkta dışarıyı seyrettim

Bilirsin ben ışık yakmayı da sevmem

Mum ışınla aydınlansın isterim ev daha çok hoşuma gider, 

Yanlızlığımla ben başbaşa kahvemizi içeriz, 

Yağmurda bize eşlik eder sessizce cama vurur, 

Rüzgarda kemanın çalar en sevdiğim müzik namelerini

Hayal ederim, böyle bir sessizlikte hiç ney dinledin mi..? 

O kadar huzur verir ki inanamazsın 

Bambaşka bir dünyada bulurum kendimi birden

Hiç bir şey düşünmem, geçmişe ve geleceğe dair

Karalarım defterime aklıma gelenleri

Hiç bir şey mutlu edemez yanlızlığım kadar beni........B.K', 'SİYAH GÜLLER......... Bilirsin siyah gülleri severim Nedendir bilmem alışıla gelmiş şeyleri sevmem Farklı olan şeyleri severim,  Dün akşam e...', ARRAY['Türk Edebiyatı','Şiir','Belgin Kistavul']::text[], 8.5, '{"poet":"Belgin Kistavul","poet_slug":"belgin-kistavul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/siyah-gulleri-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret Bile Etmiyorum', 'nefret-bile-etmiyorum-belgin-kistavul-pamgp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'NEFRET BİLE DUYMUYORUM

Bir gün kesişirse yollarımız bir yerde

Sakın çekinme konuşmak için

Benim sana nefretim yok; 

Çünkü nefrette sevgiden doğar

Bel ki bana anlatacağın çok şey vardır, 

Belki de yalnızca birkaç kelime

Seni yine dinlerim sessizce

Bilirsin sırdaşımdır, iyi bir omuz

Ama sakın eskiyi anlatma bana

Beni ne kadar sevdiğini, pişmanlıklarını falan

Ben o defteri çoktan kapattım.......

Kalbimin anahtarını da denize attım

Dostça seviyorum, herkesi ve her şeyi

Bu arada aklıma gelmişken

Sende kalan diğer yarımı istiyorum geri

Bir bütün olmak istiyorum artık, 

Bana ait hiç bir şey kalmamalı sende

Ne bir hatıra ne de ufak bir anı

Beni seven bir kadın var diye sakın düşünme artık..B.K.', 'NEFRET BİLE DUYMUYORUM Bir gün kesişirse yollarımız bir yerde Sakın çekinme konuşmak için Benim sana nefretim yok;  Çünkü nefrette sevgiden ...', ARRAY['Türk Edebiyatı','Şiir','Belgin Kistavul']::text[], 8.5, '{"poet":"Belgin Kistavul","poet_slug":"belgin-kistavul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nefret-bile-etmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam oldu İstanbul''da', 'aksam-oldu-i-stanbul-da-belgin-kistavul-yda8l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak yine akşam oldu İstanbul’da 

Bir gün daha bitti ağır ve sessiz

Hayat defterinden bir sayfa daha çevirdim

Her günün yeni şeyler öğrettiğini bildiğimden

Bugün’ de defterime güzel notlar aldım

Ağır, ağır yağmur çiselemekte şimdi

İnsanlar sağa, sola kaçışırken

Ben yürüyeceğim bilmediğim bir yöne doğru

Seviyorum yağmuru ve yere düşüp halkalar oluşturmasını

Bir cam kıyısında otururken cama vuruşunu

Ayrı bir mutluluk veriyor bana

Kimsenin olmadığı sokakları keşfetmek, ağır, ağır ıslanarak yürümek

İçine sindire sindire  havayı solumak; 

Bazen de yağmurla birlikte ağlamak

Göz yaşlarını saklamak herkesten

Ya da avuçlarını açıp ala bildiğine ıslanmak 

İçinin titrediğini hissetmek..........(belgin)', 'Bak yine akşam oldu İstanbul’da  Bir gün daha bitti ağır ve sessiz Hayat defterinden bir sayfa daha çevirdim Her günün yeni şeyler öğrettiği...', ARRAY['Türk Edebiyatı','Şiir','Belgin Kistavul']::text[], 8.5, '{"poet":"Belgin Kistavul","poet_slug":"belgin-kistavul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aksam-oldu-istanbul-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kadar Zor Değil mi..?', 'ne-kadar-zor-degil-mi-belgin-kistavul-mnzyj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar zordur kabullenmek değil mi..? 

En kötü darbeleri nedense hep sevdiklerimizden yeriz..

Bir şeyler takılır boğazımıza sanki o an yutkunamayız; 

Biz bunu hak etmedik deriz..

Hayat bize neden bu kadar acımasız diye isyan ederiz..

Oysa acımaz olan hayat değildir, 

Sevdiklerimiz ve değer verdiklerimizdir

Gecenin alaca karanlığına ve sessizliğinde düşünürken

Bir sigara yakarız uykumuz kaçar birden

Kendimizle yüz yüze geliriz

Artılar eksiler beynimizde döner

Hata ararız kendimizde bizimde hatalarımız vardır tabii

Kimse dört dörtlük ve  mükemmel olamaz

Ama eksiler artılardan daha fazladır

Hep bir şeyler alıp götürmüştür bizden ama fark ederek ama fark etmeden

Gene bir umut, bir çaba bir şeyler yapmak isteriz 

Kendimizce ama olmaz

Düşünürüz bir an o yada, onlar benim onu, yada onları düşündüğüm gibi düşünüyor mu diye

İçimizdeki sessiz ses bize söyler; 

Düşünseydi,  düşünselerdi böyle üzülürmüydün..? 

Gecenin alaca karanlığına sigara üstüne sigara yakıp söndürürmüydün..? 

Acı bir tebessüm sarar yüzümüzü

Sonra ağır, ağır kalkarız yerimizden 

En güzel olan yanlızlığımız deriz çünkü; o asla bizi üzmez ve terk etmez.......B.K.', 'Ne kadar zordur kabullenmek değil mi..?  En kötü darbeleri nedense hep sevdiklerimizden yeriz.. Bir şeyler takılır boğazımıza sanki o an yut...', ARRAY['Türk Edebiyatı','Şiir','Belgin Kistavul']::text[], 8.5, '{"poet":"Belgin Kistavul","poet_slug":"belgin-kistavul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-kadar-zor-degil-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Öyle Kalsın', 'birak-oyle-kalsin-belgin-kistavul-2hytk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BIRAK BÖYLE KALSIN

Bir gün karşılaşsan benim hiç ummadığın bir yerde

Beni keşfede bilir misin..? 

Dindire bilir misin ruhumdaki derin sessizliği

Acılarımı, hüzünlerimi bölüşüp 

Bir çay bardağı çayı, bir simidi paylaşır mısın 

Benimle salaş bir çay bahçesin de

Buz tutmuş yüreğimi, ısıtır mısın yüreğindeki sevgiyle

Sevmeyi baştan öğretebilir misin bana.? 

Yalansız ve riyasız

Yoksa çok zor deyip vazmı geçersin........

Doğru haklısın sende başaramazsın bunu; 

Bundandır benim kimseyi sevmeyişlerim, görmezlikten gelişlerim

Gerçek sevginin kaybolduğuna inanışlarım

Yok böyle kalsın bırak keşfetme beni

Uzak kalsın her şey eskisi gibi

Ben yanlızlığıma  tutkunum yanlızlığımı seviyorum

O hiçbir zaman üzmüyor beni yaralamıyor

Ne zaman istesem yanımda ne zaman istesem benle

O ve ben mutluyuz birlikte...B.K.', 'BIRAK BÖYLE KALSIN Bir gün karşılaşsan benim hiç ummadığın bir yerde Beni keşfede bilir misin..?  Dindire bilir misin ruhumdaki derin sessiz...', ARRAY['Türk Edebiyatı','Şiir','Belgin Kistavul']::text[], 8.5, '{"poet":"Belgin Kistavul","poet_slug":"belgin-kistavul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birak-oyle-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemim Gönlümedir', 'sitemim-gonlumedir-arif-aydin-2n80b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sitemim varken üşüyen yüreğimi ısıtmayan güneşedir

sitemim baharda sevgi yağmurları dökemeyen bulutadır

sitemim bahçeler dolusu kokunu taşımayan rüzgaradır

sitemim hasretiyle yanan volkanımı kor eden gönlümedir.', 'sitemim varken üşüyen yüreğimi ısıtmayan güneşedir sitemim baharda sevgi yağmurları dökemeyen bulutadır sitemim bahçeler dolusu kokunu taşım...', ARRAY['Türk Edebiyatı','Şiir','Arif aydın']::text[], 8.5, '{"poet":"Arif aydın","poet_slug":"arif-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sitemim-gonlumedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Şimdi', 'gonul-simdi-arif-aydin-9327x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir muhabbetin zamanıdır, gönül şimdi

ney sustu, mey döküldü, gönül aç şimdi

canandan beklerken güzel nameleri

bülbül sustu, dudu sustu, gönül sustu şimdi', 'Bir muhabbetin zamanıdır, gönül şimdi ney sustu, mey döküldü, gönül aç şimdi canandan beklerken güzel nameleri bülbül sustu, dudu sustu, gön...', ARRAY['Türk Edebiyatı','Şiir','Arif aydın']::text[], 8.5, '{"poet":"Arif aydın","poet_slug":"arif-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gonul-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piç Aşklar', 'pic-asklar-metehan-selcuk-fjlx1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşklar eriyor, Aralık akşamlarında

Aşklar piç oğlan doğurur; 

Kimliği belirsiz bakışlarda

Uçurumda şimdi sevdalar

Dehliz yok artık.

Görünürde, 

Görünmeyen sevdalar

Yıpratır sokakları.

Her öpücük fotoğraf karesi

Karesi kalmayacak dünyanın

Az öpüşün çocuklar

Anlamı yitecek sevdaların', 'Aşklar eriyor, Aralık akşamlarında Aşklar piç oğlan doğurur;  Kimliği belirsiz bakışlarda Uçurumda şimdi sevdalar Dehliz yok artık. Görünürd...', ARRAY['Türk Edebiyatı','Şiir','Metehan Selçuk']::text[], 8.5, '{"poet":"Metehan Selçuk","poet_slug":"metehan-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/pic-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Yağıyordu', 'yagmur-yagiyordu-metehan-selcuk-p5ois', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyordu 

Tüm şehir saçlarında ıslanırdı

Sen tutup saçlarınla oynardın

Sacının her telinde 

Çocukları severdin 

Çingene mahallerinde

Gözlerin 

Yağmur yüklü bulutların 

Ardına dalardı (saklanırdı)

Selamlardın tüm çingeneleri 

Her kaçırışında  gözlerini 

Her bulut patlamasında 

Kaybolurdun

Bir buse kondururdun geceye

Geçmişe dudak bükerdin

Yalnızlığı yaşardın.', 'Yağmur yağıyordu  Tüm şehir saçlarında ıslanırdı Sen tutup saçlarınla oynardın Sacının her telinde  Çocukları severdin  Çingene mahallerinde...', ARRAY['Türk Edebiyatı','Şiir','Metehan Selçuk']::text[], 8.5, '{"poet":"Metehan Selçuk","poet_slug":"metehan-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-yagiyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cetrefil Yolculuk', 'cetrefil-yolculuk-metehan-selcuk-c816b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çetrefil bir yolculuk 

Ayağı kayar yıldızımın 

Garibim, 

Mahzunluğun yüzünden okunur

Kırılır dalı fındığının 

	Elpençe durmuş bir hayat 

		Bana sunulan

			İçine kapanır kapılar', 'Çetrefil bir yolculuk  Ayağı kayar yıldızımın  Garibim,  Mahzunluğun yüzünden okunur Kırılır dalı fındığının  	Elpençe durmuş bir hayat  		B...', ARRAY['Türk Edebiyatı','Şiir','Metehan Selçuk']::text[], 8.5, '{"poet":"Metehan Selçuk","poet_slug":"metehan-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cetrefil-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün Beni', 'dusun-beni-omer-avsar-7h49q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çicege baktıgında

Bir kuşun cıvıltısında

Bir isyanın ortasında

Beni düşün sevgilim o anda

Yalnızlıgının arkadaşlıgında

Yatagının baş ucunda

Gecelerin ayazında

Beni düşün sevgilim o anda

Koynundaki resmime baktıgında

Gelmiyecek dedigin anda

Kırıp zincirleri koşacagım sana

Beni düşün sevgilim o anda', 'Bir çicege baktıgında Bir kuşun cıvıltısında Bir isyanın ortasında Beni düşün sevgilim o anda Yalnızlıgının arkadaşlıgında Yatagının baş ucu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dusun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklentiler', 'beklentiler-omer-avsar-f4bbu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökkuşagının renkleri ugramazmı içime

cıvıl cıvıl öten kuşlar gelmezmi sesime

kocaman bir bulut almazmı beni üstüne

Hayalimde bile sorarım kendi  kendime

Çocuklarım olmayacakmı baba diyen

Yoldaşım yokmu koynuna alıveren

Memleket uzakta her an aklıma gelen

Ölürmüyüm yoksa bunları görmeden

Yolun bittigi yerde beni bekleyen

Düşledigim zamanda geliveren

Sanki narin vede nazlı bir kardelen

Olsun isterim gönlümde yeşeren', 'Gökkuşagının renkleri ugramazmı içime cıvıl cıvıl öten kuşlar gelmezmi sesime kocaman bir bulut almazmı beni üstüne Hayalimde bile sorarım k...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklentiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alev', 'alev-suna-gunes-67yk2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mumun alevi...

mumun öksüz ve hüzünlü dumanı, 

kırmızı bir umudun üzerinde dansediyor. 

bir sağa bir sola... 

ben cekiyorum alevi bedenime. 

o ise yitirilmis sevdaların anısına, 

gözlerime salıyor mavi ısıgını 

sarımtırak anılarımı bedenlerle sarmalıyor. 

ben şarkı söylüyorum mumun alevine, 

o kendini savuruyor. 

uzun bir aşk düşünde, 

eşlik ediyor bana 

bir aşağı bir yukarı... 

mumun alevi söyle bana, neden bu kadar kızılsın? 

alır mısın kızıllıgına beni, 

yakar mısın odalarımızı, 

götürür müsün sevdiğimin yanına? 

sabahları akşamları... 

hey mumun çıplak ve masum dumanı, 

dansedelim seninle! ! ...', 'mumun alevi... mumun öksüz ve hüzünlü dumanı,  kırmızı bir umudun üzerinde dansediyor.  bir sağa bir sola...  ben cekiyorum alevi bedenime. ...', ARRAY['Türk Edebiyatı','Şiir','Suna Güneş']::text[], 8.5, '{"poet":"Suna Güneş","poet_slug":"suna-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alev-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce İnce Rüya Yağıyordu', 'i-nce-i-nce-ruya-yagiyordu-ramazan-hakan-ayhan-un71w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnce ince dünya yağıyordu üstümüze

İnce ince bir rüya yağıyordu üstümüze

Biz ise birbirimize bakıp gülüyorduk halimize

Ve alt yazılar geçiyordu ekranlardan

Yoğun kar tağışı nedeniyle... diye

ince ince kar yağıyordu üstümüze

ince ince aşk yağıyordu üstümüze

sanki bugün insanlar gülmek istiyordu

sanki gülüp ölmek istiyordu öylece

zaman ise 

sıcak bir salep kadar güzel kokuyordu geçtikçe

ince ince kar yağıyordu üstümüze

ince ince aşk yağıyordu üstümüze

ve alt yazılar geçiyordu ekranlardan 

yoğun kar yağışı nedeniyle... diye

kardan adamlar kardan kadınlar 

kardan çocuklar vardı her yerde

ince ince kar yağıyordu üstümüze

ince ince aşk yağıyordu üstümüze', 'İnce ince dünya yağıyordu üstümüze İnce ince bir rüya yağıyordu üstümüze Biz ise birbirimize bakıp gülüyorduk halimize Ve alt yazılar geçiyo...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Hakan Ayhan']::text[], 8.5, '{"poet":"Ramazan Hakan Ayhan","poet_slug":"ramazan-hakan-ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ince-ince-ruya-yagiyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ARKADAŞ (kaybolan sevda)', 'arkadas-kaybolan-sevda-fatih-gunaydin-5qakb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlümü karartmaya çalışırken kara bulutlar, 

kalbimin perdesini aralamaya çalışıyordu.şafağın ışıkları.

    ve sen düştün aklımın derinliklerine ARKADAŞ.

 sebebi oldun şamdanların altında içilen sigaranın, 

                                                  masumca akan gözyaşının....

    Gel tez elden, yoldaşı ol hayellerin, 

    Gelde bir kor düşür yüreğime.

 Garip bir düşüncenin kör kuyusunda kaybolalım

        ve dönmeyelim savaşmayı öğrenmeden.......

Biliyorsun ARKADAŞ, içimizdeki sevdayı aradık hep, 

belki dağların sessizliğinde, belki yalnızlıkta, 

belkide yorgun bir ihtiyarın yüzündeki çizgilerinde bulduk...

         Ve hep korktuk kaybetmekten, 

         zincirler vurduk kimi zaman.

         Nedense dert oldu içimize........                              

  zamanın kaybolan çizgisinde, taşınmaz bir yük oldu, 

ne aklımız erdi, nede gücümüz yetti onu söküp atmaya

hep yuttuk biçare konuşmak istediklerimizi

ve midemize oturdu isyanın pisliği, 

meçhul evlerin bacaları kusarken kirli isini, 

biz atamadık nefretimizi ARKADAŞ....

    savaşmak ne güzeldir sevdanın uğruna ve yara almak defalarca...

    bir olmak ARKADAŞ, azad etmek sevdalarımızı dağlara

Ve bulmak için mülteci bir aşkı, 

inadına atmak kendimizi dağlara

olağan gücünle bağırmak, kurtulmak kinden, nefretten.

    Ve biz arkadaş, bu duygularla isyan karası gözlerle bakalım dağlara, 

belki onlar anlar bizi, onlar barındırır SEVDA MİLİYANLARI nı

         sahipte çıkarlar........

büyüklüğüdür belkide onları böylesine cesur,               

merhametli yapan

Biz dağlardan öğrenelim gerçekleri, 

yüreklerimizde oldumu onlar gibi, 

 çıkarız garip bir düşüncenin kör kuyusundan, 

  savaşırız erkekçesine, kazanırız elbet, 

    sevdamız temiz, yüreklerimiz DAĞ gibi oldukça kazanırız.

ne boyun eğeriz namerte, nede ucuza satarız aşklarımızı.

 Evet ARKADAŞ, ne Aşk en yüce değer, 

                               nede sevgili en değerli

Savaşmak güzel sevdaların uğruna.ve kazanmak tabi, 

      Ve ARKADAŞ bir yaz orucunun iftarında, 

kanakana içmek ECEL ŞERBETİNİ.................', 'Gönlümü karartmaya çalışırken kara bulutlar,  kalbimin perdesini aralamaya çalışıyordu.şafağın ışıkları.     ve sen düştün aklımın derinlikl...', ARRAY['Türk Edebiyatı','Şiir','Fatih Günaydın']::text[], 8.5, '{"poet":"Fatih Günaydın","poet_slug":"fatih-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/arkadas-kaybolan-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebim Yıllar', 'sebebim-yillar-fatih-cinar-d1lu6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bitirdiniz beni düşen her takvim yaprağında

ulu bir dağ idim başıma yağdırdınız karlar

yalnız bir tekne idim battım hırçın dalganızda

fırtınam siz oldunuz yıktınız beni yıllar

şimdi bir titreklik var sesimde

artık gecelerimi süslemiyor rüyalar

ellerimde kırışıklar çizgiler var yüzümde

aynada felaketim oldunuz ihtiyarlattınız beni yıllar

aldınız benden acımadan canım olan yarimi

yüreğime indirdiniz matemden sağanaklar

içirdiniz zorbalıkla acının şerbetini

kadehte şarap oldunuz ayyaş ettiniz beni yıllar

yelkovanı mutsuzluğun saatinde durdurdunuz

yaşattınız zamansız kederli dakikalar

evinize misafir oldum yalanları sundunuz

evsahibi siz oldunuz ağırladınız beni yıllar

bazen beni yargısız mahpuslara attınız

üzerime örttünüz demirden parmaklıklar

ellerime kelepçe ayağıma pranga taktınız

celladım siz oldunuz astınız beni yıllar

yaktınız yırttınız isyankar şiirlerimi

bana okutturdunuz kömürden kara sayfalar

kuruttunuz benim deli çağlayan nehirlerimi

barajım siz oldunuz kestiniz suyumu yıllar

son nefesimde oldunuz kelime-i şehadet

kimi zaman lanetler okudunuz kimi zaman dualar

bazen dudağımda sigara bazen elimde şerbet

soframa bereket oldunuz doyurdunuz beni yıllar

en sonunda bana beyaz kefeni giydirdiniz

üzerime serptiniz kara kara topraklar

hakkınızı helal edin bana yarenlik ettiniz

tabutum siz oldunuz taşıdınız beni yıllar

sebebim siz oldunuız öldürdünüz beni yıllar', 'bitirdiniz beni düşen her takvim yaprağında ulu bir dağ idim başıma yağdırdınız karlar yalnız bir tekne idim battım hırçın dalganızda fırtın...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sebebim-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Numaralı Konçerto', 'uc-numarali-koncerto-ahmet-altan-p82g3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vazgeçemeyeceğim kadar kıymetli değil benim hayatım, ben şanslı olanlardanım, hayatımdan daha kıymetli bir şeylerim var benim, öyle altı imzalı boş mukaveleler taşımıyorum koynumda, hayatım karşılığında anlaşmalar yapmıyorum.

Çıplak ayaklarının altında keskin pürtüklükayalıkları, her seferinde ''belki de bu son''diyerek hissedip kendini bir uçurumdan aşağıya, bir avuç gözüken denize bırakan Amazonlar''ın o yabani çocukları gibi korkudan ürpererek bırakırım kendimi uçurumlara.

Siz bir sonsuza doğru düşmeyi bilmiyorsunuz, sonuncu kez olup olmadığını bilmeden ciğerlerinize doldurduğunuz geniş bir solukla, gözleriniz serin bir rüzgarla yanarken, dimdik korkuyla ve şehvetle titreyerek bir uçuruma uçmayı bilmiyorsunuz siz.

Hayatınız kıymetli, hayatınızdan daha kıymetli bir şeyiniz yok çünkü.

Koynunuzda altı imzalı boş mukaveleler taşıyorsunuz, küçük bir kumarbazın işaretli kağıtları dağıttığı gibi dağıtıyorsunuz onları ve her seferinde kaybediyorsunuz bütün küçük kumarbazlar gibi.

Siz o filmi gördünüz mü? 

Hayatından geleceğinden, ailesinden ve aklından vazgeçmek pahasına o ''üç numaralı konçerto''yu çalan piyanistin filmini gördünüzmü siz? 

Rachmaninov''un ''üç numaralı piyano konçertosunu'' Rachmaninov''un önünde çalıp o ünlü Rus kompozitöre, ''çalarken ruhuma dokundunuz''dedirten ve sol kolunu bir felce kaptırıp sakat kalan hocasının, ''piyano bir canavardır, onu denetleyemezsen yutar seni'' dediği genç piyanistin, bir canavar tarafından yutulmayı göze alarak ''üç numaralı konçertoyu'' çalmak için ihtirasla titremesini seyrettiniz mi? 

Hazırlıksız ve kırılgan bir ruhun taşıyamayacağı kadar büyük bir duygusal coşku gerektiren bu parçayı çalarken, yanlış sevgilerle örselenmiş ruhunu ortaya koyan o piyanistin, dünyanın en zor piyano parçası denilen konçertoyu çalabilmek için sağlığını, geleceğini ve bütün hatını tehlikeye atmasını aptalca bulmadan önce, bir insan neden hayatını bir piyano parçası çalmak için tehlikeye atar diye sordunuz mu? Gizlilerde bir yerde böyle bir soru saklıyor musunuz; bir gün lazım olur da belki sorarım diye, hayatınızn bir bölümünde böyle bir soru hazırlayıp koydunuz mu bir yanınıza? 

Siyah smokini, bağlı olduğu baştan bağımsız ayrı bir canlı gibi kıvır kıvır uçuşan saçları ve kalın gözlükleriyle piyanonun başına gelip parçayı çalmadan önce gözlüklerini çıkartarak keskin bir bıçak gibi simsiyah parıldayan piyanonun üstüne koyan genç çocuğun, dokunduğu her notayla geleceğinden ve hayatından bir parçayı tuşlara bıraktığı o konserde, olağanüstü bir duyarlılıkla çaldığı parçanın bitiminde kendisini ayakta alkışlayan kalabalığın önünde selam verirken yıkılıp kalıvermesini görmelisiniz.

Bir insanın hayatından kıymetli ne var ki, onun uğruna, bir piyano parçası için hayatını veriyor diye sormalısınız.

Ruhunda ve aklında ne varsa, hepsini son katresine kadar ''üç numaralı konçertonun''ışıltılı tınılarına terk eden çocuğun zaten kırılgan olan iç dünyasının, bir zümrüdüanka yumurtası gibi çatlayıp kendi içindeki büyülü kuşun üstüne çökmesini ve çocuğun o parçayı çaldıktan sonra on yedi yılını akıl hastanelerinde geçirmesini anlamak zor, eğer hayatınızda daha kıymetli birşey yoksa.

Sizin hayatınızda çalmak için uğruna hayatınızı vereceğiniz bir ''konçerto''yok mu? 

''İşte bunun için yakarım geleceğimi'' dediğiniz bir parça bulunmuyor mu repertuarınızda? 

Yoksa eğer bu, hayatınızda hayatınızdan daha kıymetli bir şey bulunmuyor demektir.

Kolay anlaşmalar yaparsınız o zaman.Budalalar karşısında susar, zorbalar karşısında eğilirsiniz.

Koşumları yalandan, kırbacı çıkarcılıktan yapılmış arabalara koşulursunuz siz de.

''Hayır''demeyi unutursunuz.

Herkese dağıtısınız o lanet olasıca boş mukavelelerinizi.

Katiller efendiniz olur, sahtekarlar padişahlık taslar size, kulaklarınız artık hiçbir müziği duymaz, ruhunuz kayalara çarpıp terk edilmiş eski bir gemi gibi yosunlanıp çürümeye koyulur ve ortak bayağılıkların içinde atarsınız kulaçlarınızı.

Ve inanın, hayat, içi boşaldıkça ağırlaşır.Taşınması zor bir yük olur.

O boşluğu saklamak için siz de başlarsınız yalanlara, ne kadar boşalırsa hayatınız o kadar çok yalan söyler, cakalanırsınız ve boş bir hayatı taşımanın aslında nasılda büyük bir akıllılık olduğunu anlatmaya koyulursunuz.

Biliyormusunuz, romantiklerin sonuncu büyüğü denilen Rachmaninov, besteciliğinin yanı sıra çok da önemli bir piyano virtüözüydü, çocuk yaşında saraylarda konserler vermeye başlamıştı.Dokuz yaşındayken gittiği bir asilzade konağında çaldığı bir parçanın orta yerinde daha etkileyici olmak için esas çarpıcı akoru basmadan önce ellerini tuşların üstünden kaldırıp biran beklemişti ve o sırada müzikten pek de anlamayan yaşlı bir kontes çocuğun parçayı unuttuğunu sanıp şefkatli bir sesle, ''istersen daha iyi bildiğin birşey çal'' demişti.

Daha iyi bildiğiniz birşey çalmak istermisiniz yaşlı konteslerin şefkatine sığınıp? Yoksa müzikten anlamayanların şefkatini reddedebilecek misiniz? 

Uğruna geleceğinizi mahvedeceğiniz, akıl hastanelerine, hapishanelere, sefaletlere düşeceğiniz bir ''üç numaralı konçertonuz'' var mı? 

''Ben bunu çalacağım''dediğiniz bir parça.''Bunu çalacağım ve başka da birşey çalmayacağım''dediğiniz bir konçerto için kamaşıyor mu yüreğiniz, parmaklarınız kıpır kıpır oynaşıyormu içinizde? 

''Hayat bir canavardır, onu denetleyemezsen yutar seni'' deyip vuruyormusunuz hayatın akorlarına, konçertonun bir ucundan girip öbür ucundan ter içinde ve çıldırarak çıkıyor musunuz? 

Vazgeçemeyeceğim kadar kıymetli değil benim hayatım, ben şanslı olanlardanım, hayatımdan daha kıymetli bir şeylerim var benim.

Bir yazı, bir aşk, bir isyan.

Belkide bu son kez diyerek Amazon''un o yabanıl çocukları gibi her yanımda kayaların keskin pürtüklerini hissederek bırakacağım kendimi bir uçurumun dibinde küçücük gözüken denize, gözlerim rüzgardan yanacak ve şehvetle titreyecek içim.Suya çarptığımda ince bir ok gibisaplanacağım derinlerine ve eğer çıkabilirsem yeniden suyun üstüne, ıslak sakallarımla gülümseyeceğim ve edepsiz bir oğlan çocuğu gibi övüneceğim size ''hayatımda daha kıymetli şeylerim var'' diye.

Şayet sizde gülümserseniz, çırılçıplak ve baştan aşağıya ıslak tutacağım ellerinizi, ''çalın''diyeceğim, ''çalın şu üç numaralı konçertoyu''.

Bir uçurumdan uçarak basacaksınız tuşlara.Ter içinde ve çıldırmanın kenarında dolaşarak, sevişir gibi hayatı yakıp bir hayatı doğuracaksınız.

Bütün mukaveleleriniz parça parça olup kuş tüyleri gibi savrulacak havaya.

Hayatla yaptığınız bütün anlaşmaları yırttığınızda ve ''başka birşey çalmayı''reddettiğiniz de, işte o zaman anlayacaksınız belki de hayatın ne olduğunu.

Ve piyanistin, bir canavarı yutup çıldıran o çocuğun, niye o ''üç numaralı konçertoyu''çaldığını.', 'Vazgeçemeyeceğim kadar kıymetli değil benim hayatım, ben şanslı olanlardanım, hayatımdan daha kıymetli bir şeylerim var benim, öyle altı imz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altan']::text[], 8.5, '{"poet":"Ahmet Altan","poet_slug":"ahmet-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/uc-numarali-koncerto-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgu Geceleri', 'sorgu-geceleri-fatih-gunaydin-vmq74', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne firardayım bu gece, 

      nede isyanlarda! 

.............sorgudayım, içine gömüldüğüm karanlıkta.

Ağlamak çözüm değil, ağlayamamak kalpsizlik değildi 

                                                                       sorgu gecelerinde.

Yan çizdim mertliğe, ayıp ettim kendime, 

     Ve yanlışı ben yaptım bir gecenin boşluğunda.

  Bulamadım bir cevap çıkmazı olmaz sorulara.

     Ben benden uzak, 

 ve önümde hissedilmesi güç bir yığın tuzak........

Tekrar tekrar geldi sorular

biçare cevapsız kaldılar.

   susmak acı veriyor, konuşmak felakete gebe kalıyordu

ve ben en bende olduğum gün gene yanlış yapıyordum 

                                                 doğrulara inat.................

Ama ne gelir elden, hangi yalvarış gelir dilden, 

dudaklarımdaki son istek bilmem nasıl kabul olur.

 ya ben uçacağım renkli yolun karanlık uçurumundan, 

ve bir daha hiç olmayacağım, 

ya tutacak bir el, alacak beni, kurtaracak...............

 belki çektiğim son acı olacak bu

Ama ihanet etmeyeceğim benliğime, 

erkekçesine akacak göz yaşlarım, 

yıldızlara inat bakacağım gökyüzüne, 

haykıracağım başım semada, 

belki anlamayacaklar beni, 

ama ben mutlu olacağım.

          Ben bendenuzak olduğum gece, 

          kendime hesap soracağım, 

          ve hesabımı kendim verecek, 

          erkekçesine AĞLAYACAĞIM...............', 'Ne firardayım bu gece,        nede isyanlarda!  .............sorgudayım, içine gömüldüğüm karanlıkta. Ağlamak çözüm değil, ağlayamamak kalps...', ARRAY['Türk Edebiyatı','Şiir','Fatih Günaydın']::text[], 8.5, '{"poet":"Fatih Günaydın","poet_slug":"fatih-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sorgu-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmez', 'degmez-hikmet-tugrul-tekeli-f8b5b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her taraf kapkaranlık

Kulaklatımda bir uğuldama

Yüreğimde elemli bir bakışın izi

Tüm çabama rağmen göremiyorum

İçimi saran bu korkunç duygu, 

Önüne geçemiyorum

Korkuyorum

Her taraf kapkaranlık

Sanki tutacak biri kolumdan 

Sarsacak beni

Kıpırdayamıyorum

Yüreğim delice çarpıyor

Hayalin bile azap verirken, 

Pişmanlık ok gibi vuruyor şakaklarıma

Ölüyorum

Kulaklarım da bir uğuldama

Sesini duyuyorum

Biçare uzanmışım yollarına, 

Umut bekliyorum

Karanlık sokaklarda açmışım ellerimi, 

Kaybettiğim ışığı dileniyorum

Haykırışım kaplıyor sessizliği

Yankılanıyor sokaklarda

Açmıyor yüreğinin perdesini

Sonsuzluğun zindanında 

Usulca ağlıyorum

Ve biliyorum

Ölümün ve yüreğimin değerini', 'Her taraf kapkaranlık Kulaklatımda bir uğuldama Yüreğimde elemli bir bakışın izi Tüm çabama rağmen göremiyorum İçimi saran bu korkunç duygu,...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/degmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan Olmayacaksın', 'unutulan-olmayacaksin-i-smail-acarkan-pdtge', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum ey sevgili

Başkasını sevsen de seviyorum seni

Sen beni unutsan da 

Bende unutulan olmayacaksın

Dilersen hiç gülümseme bana

Ama ben herzaman yüzünde tebessüm olacağım.

Rengini al götür istersen hayatımın

Ama ben senin rüyalarını bile en güzel renklerle süsleyeceğim

Duydum ki başkasına gülümsüyor, elini tutuyormuşsun

Buna üzüldüğümü sanma.

Ama dikkat et seni ağlatmasınlar.

Senden ayrılırken ağlıyorsam da

Sana tekrar bana gel demiyorum inan

İstersen gel.Sen mutlu olacaksan gel.

***

Sen nesin? 

Bir hiçmisin? 

Beni benden aln, kalbimi bunca hasret bırakıp kaybolan

Sen değilmisin? 

Çağırsam, gel desem, tut ellerimi, 

Sarılsam yüreğine desem, biliyorum gelmezsin.

Ama en hüzünlü anlarımda yüzümü tebessümle süsleyende sensin...

Beni üzme diyorum ya birtanem...

Aslında biliyorum, sen beni üzmezsin...

Sitemliyim sana...istiyorum seni...anla! ...', 'Seni seviyorum ey sevgili Başkasını sevsen de seviyorum seni Sen beni unutsan da  Bende unutulan olmayacaksın Dilersen hiç gülümseme bana Am...', ARRAY['Türk Edebiyatı','Şiir','İsmail Acarkan']::text[], 8.5, '{"poet":"İsmail Acarkan","poet_slug":"i-smail-acarkan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/unutulan-olmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-refik-recep-pelit-kmzy4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan 

İnsanız ya işte, 

İnsan olmasına, 

Dünyadan Bihaber, 

Yaşar Dururuz.

Kaybedince Farkına varır 

Görmeyi akıl edemez, 

Çölde, Deryada, 

Arar dururuz.

Gözümüzün önündedirde, 

Kaybettiğimiz, 

Farkına bile varamaz, 

Sorar Dururuz.

Gözlerimiz vardır ya, 

Göremeyiz hiç bir şeyi 

Körüzdürde aslında, 

Bakar Dururuz.

Güneşin anlında bile 

Geceyi Yaşar, 

Mumlar Elimizde, 

Kala Kalırız.

Anlamak istemeyiz 

Anladık Sanırız, 

Ahkam Keser, 

Döner Dururuz.

Aşık olur, Severiz

Kıymet bilmez, 

Kaybederiz, Ardı sıra, 

Ağlar Dururuz.

Özleriz, 

Hasret kalır, Sevdalanır 

Aşk Ateşi ile 

Yanar Dururuz.

Bakmanın aslında, 

Görmek olmadığını, 

Anlayamayız da, 

Kainatın bu Haline, 

Şaşar Dururuz.

İnsanız ya işte Faniyiz, 

Baki sanır kendimizi, 

İnanmayız ölüme.

Toprak Atılınca üstümüze

Pişman olur herşeye

Kıvranır Dururuz....!', 'İnsan  İnsanız ya işte,  İnsan olmasına,  Dünyadan Bihaber,  Yaşar Dururuz. Kaybedince Farkına varır  Görmeyi akıl edemez,  Çölde, Deryada, ...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/insan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Gözlerinin Rengi Olayım', 'birak-gozlerinin-rengi-olayim-i-smail-acarkan-nbiug', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Beni seviyormusun? 

-...! ! 

-Tamam sen sevme ben seveyim.

Sen tutan olma ellerimi

Ama ellerime de yasak koyma.

Tamam öpmek istemiyorsan öpme.Ben öpeyim.

Ama alev alev dudaklarımla yakarsam bedenini; 

Ne olur sitem etme...

Tamam sen seviyorum deme.Ben seveyim.

Ama ne olur sevgime sınırlar koyma.

''Seni seviyorum''diyorum''özledim''diyorum.

''Biliyormusun bunları''diyorum

Yok birtanem bilmiyorsun.

Ah bir bilsen.

Bir seviyorum desen..

Hasretin dudaklarından dudaklarıma aksa...

Çiçekler bir başka açar.

Bir başka türlü eser rüzgarlar inan.

Ama ah bir tanem biliyorum.

Sevsen de söylemezsin.

Ölsen de hissettirmezsin

Ah sevgilim

Bilsem sen nesin!', '-Beni seviyormusun?  -...! !  -Tamam sen sevme ben seveyim. Sen tutan olma ellerimi Ama ellerime de yasak koyma. Tamam öpmek istemiyorsan öp...', ARRAY['Türk Edebiyatı','Şiir','İsmail Acarkan']::text[], 8.5, '{"poet":"İsmail Acarkan","poet_slug":"i-smail-acarkan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/birak-gozlerinin-rengi-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçilmiş Tövbe', 'vazgecilmis-tovbe-arzu-zor-42bh4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kutsal kitaba yemin gibi öğrendim aşka el sürmemeyi

Kaç gözyaşıyla dualadım kendimi

Kaç meleği şahit ettim

kaç yemine ruh verdim

Kaç tövbeye adak yüreğimde

Hatırlamadığım zamanların namazlarını kılarken

İtaati bilen aşklar yarattım

Böyle bir yangını hayal etmeden

Kaç lambayı kırdım içimde ben

Bir kurgu, bir yanılgı

Bir yaşanmayan bir olmayan

Islak bir alev

Böyle bir yangın bırakır mı ardından

İçimde bir cehennem yanıyor

Bir okyanus kaynıyor

Bir aşkım, bir kurşunum

Benim siyah vahşi atlarım

Çocuklarım

Burada herkes yanıyor

Tüm günahkar kullar gibi

Ben gidiyorum ardıma bakmadan

Kimseyi kurtarmadan', 'Kutsal kitaba yemin gibi öğrendim aşka el sürmemeyi Kaç gözyaşıyla dualadım kendimi Kaç meleği şahit ettim kaç yemine ruh verdim Kaç tövbeye...', ARRAY['Türk Edebiyatı','Şiir','Arzu Zor']::text[], 8.5, '{"poet":"Arzu Zor","poet_slug":"arzu-zor","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/vazgecilmis-tovbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Modern Zamanlar', 'modern-zamanlar-arzu-zor-dhtcp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Modern zamanların aşığıyım ben

Aşkı hiç tanımayan 

Bir kalp atışı ömrü kadar aşkı ağırlayan

Teğet geçen

Alelacele sevgilere talip bir dünyaya aidim ben. 

Kendine emanetten korkan bir hayatın figürü

Daha kolay kıyan

Daha kolay unutan

Daha kolay yalanlayan

Modern zamanların aşığıyım ben.

Yüreği titreyince aşkı ıskalayan.

Hani olmazlara taliptim  ya ben

Rüzgarı tutmak

Güneşi ısıtmak

Güne adını yazmak

Yalan! 

Ölmek için bile enerjiye ihtiyaç duyan

Modern zamanın yalancı serserisi

Kapandayım 

Ben modern zamanların aşığıyım 

Kör bir yüreğin dilsiz sevgilisi

Öylesine bir aşık 

Öylesine bir sevgili

Öylesine bir yaşam

tüm zamanlara emanet bırakılan

Sonsuza kadar emanette kalacak olan

Modern zamanların aşk hikayesi', 'Modern zamanların aşığıyım ben Aşkı hiç tanımayan  Bir kalp atışı ömrü kadar aşkı ağırlayan Teğet geçen Alelacele sevgilere talip bir dünyay...', ARRAY['Türk Edebiyatı','Şiir','Arzu Zor']::text[], 8.5, '{"poet":"Arzu Zor","poet_slug":"arzu-zor","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/modern-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '3Ben Sevdim mi Ölümüne Severim', '3ben-sevdim-mi-olumune-severim-nurten-altinok-9qwgb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hoşgeldiniz 

                      

Ben Sevdim mi Ölümüne Severim

Bu nasıl bir kaçış 

Elle tutulur bir rüya gibi yaşadım seni

Bir rüya gibi indi gök avuçlarıma

Göğsüne sığındığım

Batık bir gemi gibi yerinden memnun

Demirlerimi sana attığım limanımdın

Dilim oldun kalemimde

Dize dize çözüldüğüm

Gözüm oldun

Kör gecelerimde güneşi bestelediğim

Umudum oldun uçurum eteklerinde

Yüreğine tutunduğum

Gözyaşım oldun isyanlarımda

Kadınlığımda kıskançlığım

Yalnızlığımda 

Bir idam mangası tüm çıkmazlarıma

Dünüm oldun

Bugünüm oldun

Eksik kalan yaşanmamışlarımda

Balta girmemiş orman gibi saf

Sevgilerimi sergiledim avuçlarına

Yarınlarıma açılacak kapıların tüm

Anahtarlarını bağışladım sana

Sevdim seni

Kadınca duygularımın coşkusuyla

Yaşanmamış özlemlerimin adına

Sevdim seni

Yer gök şahidim

Tanrı adına

Sevdim seni

Karınca kararınca

Değil

Sevdim seni

K A D I N C A

Anlayabiliyor musun 

Adam gibi sen de

Sevebiliyor musun? 

Ben sevdim mi ölümüne severim

Ölümüne severim

Umut hep içimde

Hep benimle

Bu yürek zannettiğin kadar zayıf değil

Bakma aynalardaki görüntüye

Aldanma yalancı gülüşlerdeki sahte ilgiye

Kanma ''''seviyorum''''diye 

Etrafında pervane geçinenlere

Kaç kişi sana gecelerden çığlık oldu

Kaç kişi sana çiy damlasından sevgi dokudu

Kaç kişi kanat oldu rüzgarlarına

Kaç kişi dua umutlarına

Sevdim seni / denizle tuz gibi

Sevdim seni / hamurla maya gibi

Sevdim seni / bulutla yağmur gibi 

Torağın yağmuru sevdiği gibi

Topraktaki koku gibi 

Taze ekmek gibi

Ve de

Sevdim seni

Canım gibi

Ben sevdim mi canına severim

Ölümüne severim

Ölümüne...

Ben Sevdim mi Ölümüne Severim

Bu nasıl bir kaçış 

Elle tutulur bir rüya gibi yaşadım seni

Bir rüya gibi indi gök avuçlarıma

Göğsüne sığındığım

Batık bir gemi gibi yerinden memnun

Demirlerimi sana attığım limanımdın

Dilim oldun kalemimde

Dize dize çözüldüğüm

Gözüm oldun

Kör gecelerimde güneşi bestelediğim

Umudum oldun uçurum eteklerinde

Yüreğine tutunduğum

Gözyaşım oldun isyanlarımda

Kadınlığımda kıskançlığım

Yalnızlığımda 

Bir idam mangası tüm çıkmazlarıma

Dünüm oldun

Bugünüm oldun

Eksik kalan yaşanmamışlarımda

Balta girmemiş orman gibi saf

Sevgilerimi sergiledim avuçlarına

Yarınlarıma açılacak kapıların tüm

Anahtarlarını bağışladım sana

Sevdim seni

Kadınca duygularımın coşkusuyla

Yaşanmamış özlemlerimin adına

Sevdim seni

Yer gök şahidim

Tanrı adına

Sevdim seni

Karınca kararınca değil

Sevdim seni

K A D I N C A

Anlayabiliyor musun? 

Adam gibi sen de

Sevebiliyor musun? 

Ben sevdim mi ölümüne severim

Ölümüne severim

Umut hep içimde

Hep benimle

Bu yürek zannettiğin kadar zayıf değil

Bakma aynalardaki görüntüye

Aldanma yalancı gülüşlerdeki sahte ilgiye

Kanma ''''seviyorum''''diye 

Etrafında pervane geçinenlere

Kaç kişi sana gecelerden çığlık oldu

Kaç kişi sana çiy damlasından sevgi dokudu

Kaç kişi kanat oldu rüzgârlarına

Kaç kişi dua umutlarına

Sevdim seni / denizde tuz gibi

Sevdim seni / hamurda maya gibi

Sevdim seni / bulutta yağmur gibi 

Torağın yağmuru sevdiği gibi

Topraktaki koku gibi 

Taze ekmek gibi

Ve de

Sevdim seni

Canım gibi

Ben sevdim mi canına severim

Ölümüne severim

Ölümüne...

Nurten Altınok

I4.0I.20I2

ESENYURT

Güncelleme', 'Hoşgeldiniz                         Ben Sevdim mi Ölümüne Severim Bu nasıl bir kaçış  Elle tutulur bir rüya gibi yaşadım seni Bir rüya gibi ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":130,"source_url":"https://www.antoloji.com/3ben-sevdim-mi-olumune-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgüven', 'ozguven-erol-sen-lqpx8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar yılı düşünürsün yaşam amacını

Bazen kızarsın hayata dünyaya insanlara

İsyan edersin yaşanan olumsuzluklara

Yada kahkalarla gülersin güzel olaylara

Tuhaf şey şu insanoğlu

Neden kızgınsın bu kadar

Hayata dünyaya ve insanlara

Yaşanmış sahte sevgilere, dünyaya hayata

Kandırılmış sahte sevgilere, hayata, dünyaya

Bakarsın yıllara

Yarattığın kendine ait dünyana

Sen yarattın bunları kendi ellerinle isteyerek

Hepsini hakettin bazen feda etsende maddi veya manevi

Gerçekler

Hiç kaçmamışsın gerçeklerden

Yaptığın hata, yaşattığın ve yaşadığın sevgiden kaçmamışsın

Değer verdiğini yüceltmişsin karşılıksız......

Mantık

Mantıkla halletmeye çalışmışsın herşeyi kendince

Duygular ve sevgiler mantıkla son bulmuş gerektiğinde

Sevenlere duyulan hisler devam etsede kalpte.......

Güven

Sonunda seni gerçekten karşılıksız sevenlerin

Sonunda sana gerçekten güvenenler

Bekleyenler umut edenler kazanmış

Bir kere daha '' İYİ Kİ '' demişsin...........

11.01.2002', 'Yıllar yılı düşünürsün yaşam amacını Bazen kızarsın hayata dünyaya insanlara İsyan edersin yaşanan olumsuzluklara Yada kahkalarla gülersin g...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ozguven-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-arslan-alp-syj03', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum, 

Hayalin geldiğinde gözlerimin önüne

Susmak bilmiyor içimdeki ses; 

Seni seviyorum..! 

Seni seviyorum..! 

Seni seviyorum..! 

Seni seviyorum..! 

.........

Aralık 2001, İzmir', 'Seni düşünüyorum,  Hayalin geldiğinde gözlerimin önüne Susmak bilmiyor içimdeki ses;  Seni seviyorum..!  Seni seviyorum..!  Seni seviyorum.....', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-seviyorum-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeli', 'sevmeli-arslan-alp-bq1op', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Devir başka devir, 

Üstü kağıttan şatolar

Altı çamurdan yollar

Sadece seni seviyorum demekle olmuyor

Sadece sevmekle de...

O zaman ne işin var

Sevmeyeceksen bu dünyada

Demezler mi adama? 

Şubat 2001, İzmir', 'Devir başka devir,  Üstü kağıttan şatolar Altı çamurdan yollar Sadece seni seviyorum demekle olmuyor Sadece sevmekle de... O zaman ne işin v...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevmeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyayı sevmiyorum', 'dunyayi-sevmiyorum-erol-sen-g8uuh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar birer birer geçerken neler yaşanıyor

Acılar, sevinçler hepsi bizim için

Şimdi geri dönüp baktım

Anlamsız bir sürü yaşanmışlık

Mutluyken dönüp bakılmayan sevinçler

Arkada bırakılması istenen acılar

Küçümsenen sevimli güzel günler......

Çocukluk ve gençlik yıllarını yaşayan tüm insanlar

Olgunlaşınca şöyle bir bakıyor

Kırlaşmış sevimli saçlarına utanmadan....

Rüzgar her yıl başka türlü esiyor......

29.01.2001', 'Yıllar birer birer geçerken neler yaşanıyor Acılar, sevinçler hepsi bizim için Şimdi geri dönüp baktım Anlamsız bir sürü yaşanmışlık Mutluyk...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dunyayi-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller de soluyor canımcım', 'guller-de-soluyor-canimcim-erol-sen-345mz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğanın kuralı böyle

Bütün güller solacak elbet bir gün

Ömrümüz de sona erecek

Bir hoş seda bırakabilmek büyük mutluluk

Ufak minik sevimli bir hatıra hatırlansa bile......

16.02.2001', 'Doğanın kuralı böyle Bütün güller solacak elbet bir gün Ömrümüz de sona erecek Bir hoş seda bırakabilmek büyük mutluluk Ufak minik sevimli b...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guller-de-soluyor-canimcim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-arslan-alp-df86s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hava biraz rüzgarlı

Güneş hafiften ısıtıyor tenimi

Ve ben Karşıyaka sahilde

Beraberce oturduğumuz ağacın

                                        altındayım; 

Yalnızım

Hiç olmadığım kadar.

9 Şubat 2001, İzmir', 'Hava biraz rüzgarlı Güneş hafiften ısıtıyor tenimi Ve ben Karşıyaka sahilde Beraberce oturduğumuz ağacın                                    ...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yarısı Uyanmak', 'gece-yarisi-uyanmak-arslan-alp-0zc2p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gece yarısı 

Uykundan uyanmak 

Hiç hoş değil..

Sebebi 

Sevdiğinin 

Tatlı hayalinden 

Başkaysa

25 Ocak 2001, İzmir', 'Bir gece yarısı  Uykundan uyanmak  Hiç hoş değil.. Sebebi  Sevdiğinin  Tatlı hayalinden  Başkaysa 25 Ocak 2001, İzmir...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gece-yarisi-uyanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki İhtiyar', 'i-ki-i-htiyar-arslan-alp-ais2v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki ihtiyar gördüm, 

Karşıdan karşıya geçiyorlardı..

Kollarında hırkalar, 

             serinlikten korumak için 

                                yaşlanan kemiklerini..

Elele tutuşmuşlar, 

             ısıtmak için

                          yüreklerindeki sevgilerini..

Yüzlerinde yılların mutluluğu

              gözlerinde mutluluğun kırışıklıkları...

İki güzel insan....

              yüzlerinde yüzümüz, ellerinde sıcaklığımız vardı..

seni seviyorum..! 

14 Eylül 2001, İzmir', 'İki ihtiyar gördüm,  Karşıdan karşıya geçiyorlardı.. Kollarında hırkalar,               serinlikten korumak için                            ...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iki-ihtiyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-arslan-alp-6co9q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceleri çok severim, 

Gökyüzünde işim var sabaha kadar.

Bir tanesini bile kaçırmamam lazım, 

Düşen yıldızların.

Dileğim gerçekleşene kadar..

Aralık 2001, İzmir', 'Geceleri çok severim,  Gökyüzünde işim var sabaha kadar. Bir tanesini bile kaçırmamam lazım,  Düşen yıldızların. Dileğim gerçekleşene kadar....', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/geceler-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreği Yalnız', 'yuregi-yalniz-levent-umit-temiz-m2iu6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şiir dinledim

Yüreği yalnız bir dosttan

Unutulacak kadar eski

Hiç unutulmayacak kadar güzel

Ve bir şiir okudum

Basit

Sade

Küçük

Bir aşka özel

Beğenmedi nedense

Gözlerine baktım

Yüreğini gördüm

Bomboştu

Alabildiğine

(Merhaba)', 'Bir şiir dinledim Yüreği yalnız bir dosttan Unutulacak kadar eski Hiç unutulmayacak kadar güzel Ve bir şiir okudum Basit Sade Küçük Bir aşka...', ARRAY['Türk Edebiyatı','Şiir','Levent Ümit Temiz']::text[], 8.5, '{"poet":"Levent Ümit Temiz","poet_slug":"levent-umit-temiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuregi-yalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Dünyam', 'sen-ve-dunyam-arslan-alp-6zmni', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kıyametler kopuyor 

	dışarılarda bir yerde

Tıpkı yüreğimde 

	koptuğu gibi.

Mutlu olduğum bir dünya var

	rüyalarla bezenmiş

Ve sen

O rüyalarda ki 

	tek güneşsin.   

12 Eylül 2001, İzmir', 'Kıyametler kopuyor  	dışarılarda bir yerde Tıpkı yüreğimde  	koptuğu gibi. Mutlu olduğum bir dünya var 	rüyalarla bezenmiş Ve sen O rüyalard...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ve-dunyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanık Bırakmadım', 'tanik-birakmadim-umit-ozgur-torun-d7bue', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne söylenecek bir söz

Ne yakılacak bir bahar kalmış.

Tesadüfen sahte ışıklara düşmüş akşamda, 

ödünç verilmiş bir çift göz ve dağılmış bir bulut karşısında 

utanırım yaralarımdan; bana onca şiiri yazdırandan.

Artık korkmuyorum açılır gibi durur kapılar ardında görülen

yarı açık rüyalardan, 

hep o eski ağıtları kuşanan kasım yağmurlarından ya da

seni bana taşıyan her tesadüf damladan.

suçluyum yaralardan; büyük harfle başladığım her nakarattan, 

altını çizdiğim her kelimeden, 

her gece vakti kopardığım gelinciklerden

suçluyum ama: 

Kalemlerimi kırdım, 

bütün şairleri unuttum, 

hiç tanık bırakmadım ardımda...', 'Ne söylenecek bir söz Ne yakılacak bir bahar kalmış. Tesadüfen sahte ışıklara düşmüş akşamda,  ödünç verilmiş bir çift göz ve dağılmış bir b...', ARRAY['Türk Edebiyatı','Şiir','Ümit Özgür Torun']::text[], 8.5, '{"poet":"Ümit Özgür Torun","poet_slug":"umit-ozgur-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tanik-birakmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Ak Kağıt Şu Kara Kalem', 'su-ak-kagit-su-kara-kalem-emirhan-oguz-9d9jt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şairler size ben

hep kandan karanfillerden 

söz ettimse bağışlayın

-ama ölenler vardı, usulca gün ışırken

ve rüzgarda sallanıyordu durmaksızın

karla ağırlaşmış bir selvi dalı

Kardeşler / size ben 

yosun tutmuş bir demirden 

söz ettimse anımsayın

-sokaklarınızda devriyeler gezerken

birileri vardı alnını ayaza yaslayıp

susturulduğunuz türküleri söyleyen

Çocuklar / size ben

kuş ıslığı uykunuzda kara düşlerden

söz ettimse kınamayın

-ne bir şeytan uçurtmasıydı haşarı şaşkın

ne de benekli bir balonu uçuruyordu dünya

insanlar ölüyordu, barışı düşünürken

Anneler / size ben

acıdan özlemlerden

söz ettimse bağışlayın

-ellerinizin izi tel örgüye sinerken

ıslanmış mendilini ısırıyordu bir kadın

ülkemin yüzü geçiyordu gözlerinizden

Şu ak kağıt şu kara kalem

unutmaz belleği, yaşadığımız tanıklığın

yazıtsız gömüt taşı, bir pusula, bir teşhis tutanağı

yazılmamış şeyler vardır/ben

acıyla eğileceğim yüzünüze

                             

                             susmayın', 'Şairler size ben hep kandan karanfillerden  söz ettimse bağışlayın -ama ölenler vardı, usulca gün ışırken ve rüzgarda sallanıyordu durmaksız...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Oğuz']::text[], 8.5, '{"poet":"Emirhan Oğuz","poet_slug":"emirhan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/su-ak-kagit-su-kara-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sen Olmuşum', 'ben-sen-olmusum-i-brahim-i-ncigulcan-exeu8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni bomboş bir kadeh gibi bırakıp gitme

Ben sen olmuşum artık: Beni bana benzetme.......', 'Beni bomboş bir kadeh gibi bırakıp gitme Ben sen olmuşum artık: Beni bana benzetme..........', ARRAY['Türk Edebiyatı','Şiir','İbrahim İncigülcan']::text[], 8.5, '{"poet":"İbrahim İncigülcan","poet_slug":"i-brahim-i-ncigulcan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ben-sen-olmusum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niğde''den', 'nigde-den-umit-yasar-oguzcan-ndwnj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evimden karlı dağlar görünür Niğde''de

Baktıkça hüzünlenir, efkarlanırım

Sığmaz bu dağlara kaderim, sığmaz

Dayanılır dert değil bu Tanrım

Niğde bir taş yığını, toprak yığını

Bir gök var burada denize benzer

Ben denizlerin aşığı adam

Bana uzak denizler

Evimizin önünde pazar kurulur her hafta

Ben ecelle can pazarlığındayım

Günlerimi aydınlatan güneş değil

Karanlık gecelerin en karanlığındayım

Gönlümde eser rüzgarları Niğde''nin

Bir gariplik çöker üstüme her akşam

Düşündükçe ağlamak gelir içimden

Ağlayamam

Penceremden kimsesiz mezarlar görünür

Ve karşıda ağaçlar içinden tren yolu geçer

Sahillere, sahillere doğru trenler

Dolu dopdolu geçer

Velhasıl bir garip adamım ki Niğde''de

Ömrümüm otuzuncu, evimin beşinci katındayım

Sormayın günlerimin nasıl geçtiğini

Başka sefere anlatayım', 'Evimden karlı dağlar görünür Niğde''de Baktıkça hüzünlenir, efkarlanırım Sığmaz bu dağlara kaderim, sığmaz Dayanılır dert değil bu Tanrım Niğ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nigde-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orada', 'orada-umit-yasar-oguzcan-c8bo5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Orada ben varım

Göklerde, baktığın yerde

Yıldız yıldız

Orada ben varım

Yürüdüğün yerde

Yapayalnız

Orada ben varım

Uyuduğun yerde, yanında

Kıpırtısız

Orada ben varım

Sevdiğin, sevildiğin yerde

Yalansız

Orada ben varım

Vurulmuş, kanlar içinde

Cansız

Orada ben varım

Bir mezar taşının altında

Ipıssız

Orada ben varım

Orada

Sensiz', 'Orada ben varım Göklerde, baktığın yerde Yıldız yıldız Orada ben varım Yürüdüğün yerde Yapayalnız Orada ben varım Uyuduğun yerde, yanında Kı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/orada-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Geliş', 'yeniden-gelis-umit-yasar-oguzcan-toc7u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutup saçlarımdan sürükleyen kim? 

Çeken ne denizlere doğru beni? 

Varlığını yaşamak bildiğim

Alevden eller mi, o kor gözler mi? 

Bir dudak mı tutuşturan kanımı

O çılgın geceler boyunca? 

O ateş yığını saçlar mı

Yakan avuçlarımı, tutunca? 

Bu dalıp dalıp gitmeler neden? 

Neden bir alev tasta kaynayıp

Her gün yenilenmek, eksilmeden? 

Sonsuzluğa doğru bir yükseliş midir bu? 

Söyle ey sevgiyle dolup taşan yürek

Dünyaya yeniden geliş midir bu?', 'Tutup saçlarımdan sürükleyen kim?  Çeken ne denizlere doğru beni?  Varlığını yaşamak bildiğim Alevden eller mi, o kor gözler mi?  Bir dudak ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yeniden-gelis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlarda', 'yarinlarda-umit-yasar-oguzcan-s75fj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi uzaklarda evinde uyuyor olmalısın

Gördüğün, düşlerin en güzelidir yavrum

Saçların dağılmıştır yastığın üzerine

Göğsün hafifçe açılmıştır, biliyorum

Kimbilir nasıl geçmiştir akşam saatleri, gece

Gözlerin nasıl da koyulaşmıştır hüzünden

Duvarlar üzerine yıkılmıştır birer birer

Bensiz bir gün daha eksilmiştir ömründen

Kitaplar, plaklar, şunlar, bunlar hepsi boş

Severken kolay değil avunmak, baksana

Yine kör karanlığında bir gecenin

Oturmuş özlem şiirleri yazıyorum sana

Dudaklarını anımsıyorum ekmekten sudan aziz

Ellerini anımsıyorum saçlarımda sevecen

Sonra gözlerin, dupduru, yalansız, kuytu

Seni andıkça bir imbat esiyor Ege''den

Yaşanacak yıllarımız olmalı diyorum seninle

Uyuyacaksan kollarımda uyumalısın

Vaktin olursa sevişmekten deli gibi

Başını omuzlarıma koymalısın

En güzel sözcüklerle, öpüşlerle, şiirlerle

Sana sevgimi anlatmalıyım uzun uzun

Pencereden gökyüzü görünmeli, yıldızlar

Tek tanığı olmalı mutluluğumuzun

Uyanmalısın doğan günle birlikte

Yeniden sevişmeye durmalıyız, yeniden

Ve yepyeni bir dünya yaratmalıyız

Her anı aşktan, mutluluktan, sevgiden', 'Şimdi uzaklarda evinde uyuyor olmalısın Gördüğün, düşlerin en güzelidir yavrum Saçların dağılmıştır yastığın üzerine Göğsün hafifçe açılmışt...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yarinlarda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığı Kadınların', 'yalnizligi-kadinlarin-umit-yasar-oguzcan-5mlhz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlığı kadınların, üşümüş, yorgun

Bir elin sallanışı açık pencerelerden

Anlatır aşkın güzelliğini uzun uzun

Kalan hatıralarla geçmiş gecelerden

Hep o eller ağlayan karşısında aynaların

Hep o çileli yüz, o bekleyen dudaklar

Bir ses kulaklarında: Belki yarın, belki yarın

Sonra yeni bir sabah, yine bomboş sokaklar

Beklemek... Yalnızlığı kadınların büyük

Pencerelerde, kapılarda, evlerde, odalarda

Ve soğuk yataklarda mahzun, kırık dökük

Bazen mağrur gözleri bir noktaya dalar da

Ansızın bir ateş basar solgun yanaklarını

Batırırlar kalplerine ince, uzun parmaklarını', 'Yalnızlığı kadınların, üşümüş, yorgun Bir elin sallanışı açık pencerelerden Anlatır aşkın güzelliğini uzun uzun Kalan hatıralarla geçmiş gec...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizligi-kadinlarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa Sone', 'yalnizliga-sone-umit-yasar-oguzcan-zr0ga', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşin akşam hüzünle battığı

Karşıdaki karlı dağlar yalnız

Düşe yaprak, esen rüzgar yalnız

İnsanda ölümün yalnızlığı

Yalnız düşünceler paramparça

Yalnız hatıralar kırık dökük

Yalnızlık zor, yalnızlık büyük

İnsanın yalnızlığı bambaşka

Dünyada yalnız olmayan ne var

Yer altında ölüler, gökte yıldız

Denizlerde yelkenliler yalnız

Ve insan yalnız tanrılar kadar

Üzerinde ümitle yaşadığımız

Dünyaya sığmıyor yalnızlığımız', 'Güneşin akşam hüzünle battığı Karşıdaki karlı dağlar yalnız Düşe yaprak, esen rüzgar yalnız İnsanda ölümün yalnızlığı Yalnız düşünceler para...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizliga-sone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın', 'aglayacaksin-erol-erkan-j2srk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün batarken bir akşam üstü 

Ben geleceğim aklına ''AĞLAYACAKSIN''

Tatlı bir rüzgar esecek saçlarına

Ben geleceğim aklına ''AĞLAYACAKSIN''

Adımı anmaya varmazsa dilin

Boşver calışma hatırlamaya 

Nasılsa bir akşam tatlı rüyanda

Ben geleceğim aklına ''AĞLAYACAKSIN''

Gün gelirde oturursan nikah masasına

Mutluluk hayaliyle atarsan bir imza 

Daha yapacağın ilk dansında

Ben geleceğim aklına ''AĞLAYACAKSIN''

Yabancı kollar sarılırsa boynuna

Onun dudakları dokunursa sana

Onun olacağın tam o sırada 

Ben geleceğim aklına ''AĞLAYACAKSIN''.', 'Gün batarken bir akşam üstü  Ben geleceğim aklına ''AĞLAYACAKSIN'' Tatlı bir rüzgar esecek saçlarına Ben geleceğim aklına ''AĞLAYACAKSIN'' Adımı...', ARRAY['Türk Edebiyatı','Şiir','Erol Erkan']::text[], 8.5, '{"poet":"Erol Erkan","poet_slug":"erol-erkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglayacaksin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey İzmir', 'hey-i-zmir-hasan-yasar-tqjos', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HEY İZMİR 

hey 

sen 

özlemeye doyamadığım şehir. 

ne güzelliğiyle böbürlendiğin kızlarını 

ne de bok kokan kıyılarını. 

ne konak’ını özledim 

ne de karşıyaka’nı be güzel izmir. 

yine de 

haydi kırma suyunu içmiş bu adamı 

                                            be ılıcak şehir. 

al yasemin kokulu bornova sokaklarını 

al geçmiş geçmiş parıldayan 

duvarları ege kokulu rum evlerini 

                                                  gel. 

bak 

laf olsun diye değil bu şiir 

aşksızım 

yalnızım 

ve üşüyorum 

naz etme haydi gel 

bu gece rüyama gir...', 'HEY İZMİR  hey  sen  özlemeye doyamadığım şehir.  ne güzelliğiyle böbürlendiğin kızlarını  ne de bok kokan kıyılarını.  ne konak’ını özledim...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hey-izmir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KORKULUK ''Can Baba'' ya', 'korkuluk-can-baba-ya-hasan-yasar-n6s57', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.........................................................................................can yücel''e

KORKULUK

korkuluk

sanılsa da 

günebakanların

arasında, 

saltanat sallamayan, 

imgeleriyle

krallara korku salan, 

dik başlı

bi komutandır

o

şiir alayının başında...', '.........................................................................................can yücel''e KORKULUK korkuluk sanılsa da  günebakan...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/korkuluk-can-baba-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-hasan-yasar-969dl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her başka duyguda

başka renk alan

                    gözlerinin 

resmini yapıyorum yalnızleyin; 

çiçekli mahzunluğunu 

            ısıtsın diye 

            yoksul pencere önlerinin...

şiirini yazmak için ıkınıyorum 

bende bıraktığın hercai duyguların; 

ellerinde uçurtma olsun

bir gün olsun sevinsin

yüzü gülsün diye 

        çingene çocuklarının...', 'her başka duyguda başka renk alan                     gözlerinin  resmini yapıyorum yalnızleyin;  çiçekli mahzunluğunu              ısıtsın ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istiyorum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kılpayı Mutluluklar', 'kilpayi-mutluluklar-hasan-yasar-kggwl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kılpayı                            

mutluluklar

kursağımda kaldı.                     

sus payı                            

verilen

kremalı çıtır sevinçlerin                                  

tadı damağımda.                      

bu yüzden işte                      

bu yüzden                          

çocuklaşmam                                          

arasıra...', 'kılpayı                             mutluluklar kursağımda kaldı.                      sus payı                             verilen kremalı ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kilpayi-mutluluklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Tanrıçası', 'ay-tanricasi-levent-umit-temiz-2r3pe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Harabeler arasından yükselir

gizemli bir aşkın ülkesi

Rüzgarda bir fısıltıdır

Yüreğini arayan genç bir

çobanın sesi

Bu sahillerde derler ki

Derin olur 

Yıldızlı gecelerin uykusu

Kimse bilmez 

Ne zaman başlamış

Bu garip aşkın öyküsü

Kumsalda dolaşan 

bir ay tanrıçası

Çalar kaçarmış her gece

Uyuyan bir yalnız yüreği', 'Harabeler arasından yükselir gizemli bir aşkın ülkesi Rüzgarda bir fısıltıdır Yüreğini arayan genç bir çobanın sesi Bu sahillerde derler ki ...', ARRAY['Türk Edebiyatı','Şiir','Levent Ümit Temiz']::text[], 8.5, '{"poet":"Levent Ümit Temiz","poet_slug":"levent-umit-temiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ay-tanricasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki de', 'belki-de-emel-kocer-gur-y9wbp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Belki; 

Yalnızca sesteki tınıydı 

Beni çeken

Lacivert suların kucağına 

Kalbimin kuytularında

Uyuttuğum

Sinsice kanayan yokluğundu

Belki de; 

Kimbilir belki; 

Onulmaz aşkların acısıydı

Duyduğum

Bir martının havalanışında

Belki de sendin

Yanımdaki; 

Yalnız, uykusuz gecelerimin

Tek dayanağı

RÜYALARIMDA...', 'Belki;  Yalnızca sesteki tınıydı  Beni çeken Lacivert suların kucağına  Kalbimin kuytularında Uyuttuğum Sinsice kanayan yokluğundu Belki de;...', ARRAY['Türk Edebiyatı','Şiir','Emel Koçer Gür']::text[], 8.5, '{"poet":"Emel Koçer Gür","poet_slug":"emel-kocer-gur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/belki-de-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Çocuk', 'ben-ve-cocuk-meryem-yildirim-0gk8z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben ve Çocuk

Kocaman bir çığlıkla susuyordu, 

Telefon kulubesinin önünde.

O susuyor kimse duymuyordu.

Görenler vardı elbette.

Kimileri de noel alışverişinde.

Ağlayamayan gözlere mendil satıyordu..! 

“Birmilyona bir mendil olmaz”

Diyecek kadar tok

Tamamını bir kişiye satmayacak kadar onurluydu! 

Onurluydu çocuk, şerefsizdi kaldırımlar, 

Şerefliydi çocuk, açtı onursuz sokaklar...! 

En az gözyaşlarım kadar masumdu, 

En az kirliydim onun elleri kadar.

Ben içimdeki vicdanı susturmaya çalışıyor, 

O vicdanı bağıranları körüklüyordu.

Masumiyeti kadar çıplaktı ayakları, 

Çığlıkların tersine haykırıyordu bakışları.

Onun ayakları donuyor, 

Benim yüreğim yanıyordu.

Basmadı ayaklarıyla yüreğime, 

Değdirmedi donan buzluğu içimdeki ateşe.

O kirli elleriyle temiz mendiller, 

Ben temiz dudaklarımla kirli cümleler satıyordum.

O bir lokma ekmek için, 

Bense hayallerim için uğraşıyordum.

Bende tüm mendilleri alacak kadar para, 

Onda yetmeyeceğini bilecek kadar zeka! 

Biliyordu tüm mendillerin temizleyemeyeceğini! 

Biliyordu ve tamamını satmıyordu.

Kocaman bir çığlıkla susuyorsu çocuk

Ve bağırıyordu duyanlara, 

Bir çocuk boyunu aşarcasına.

“ekmek böyle kazanılır onurlu ve şereflice”

Ayaklar buz tutmuş, yürek ateşler içinde

Gırtlaktan geçerken helalince...! 

“Biz onların gözlerine ve kulaklarına mühür vurduk”

Dediği gibi Hakk’ın

Duymayanlar vardı elbette...!', 'Ben ve Çocuk Kocaman bir çığlıkla susuyordu,  Telefon kulubesinin önünde. O susuyor kimse duymuyordu. Görenler vardı elbette. Kimileri de no...', ARRAY['Türk Edebiyatı','Şiir','Meryem Yıldırım']::text[], 8.5, '{"poet":"Meryem Yıldırım","poet_slug":"meryem-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ben-ve-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıksız Şiir', 'basliksiz-siir-meryem-yildirim-f0le4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat kitabında noktalı bir virgülüm; 

Manalı bir açıklaması olmayan.

Yada bir aşk şarkısının mısrasıyım, 

Nakaratında anlamsızlaşan.

Ruhumun azılı canavarıyım, 

Girilmez levhasına inat gaza basan.

Serseri bir düşünce, 

Meyhanede ezan sesini yudumlayan.

Kazanılmış bir ödül töreniyim

Tipi yüzünden iptal olunan.

Çalışkan bir öğrenciyim oysa, 

O tek dersi bir türlü anlayamayan.

demirden bir yüreğim, 

Kendi cenazesinde ağlamayan.

Camdan bir kalp yada, 

Çocuk tebessümünde buğulanan.

İflah olmaz bir militanım, 

Özgürlük diye bağıran, 

Tek cezaevi benim oysa! 

İçinde gardiyanı bulunmayan.

Akıllanmaz bir deliyim, 

Kaldırımlara inat ip üstünde yürüyen.

Otobanlar dururken, 

Çıkmaz sokaklara giren.', 'Hayat kitabında noktalı bir virgülüm;  Manalı bir açıklaması olmayan. Yada bir aşk şarkısının mısrasıyım,  Nakaratında anlamsızlaşan. Ruhumu...', ARRAY['Türk Edebiyatı','Şiir','Meryem Yıldırım']::text[], 8.5, '{"poet":"Meryem Yıldırım","poet_slug":"meryem-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/basliksiz-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen-2', 'sen-2-fulya-tasangil-aydin-on4oa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni uğurluyorum artık yaşamımdan

Hiç sevgilim olmadan

                Sevdiğim olan seni

Yüzünü hiç görmediğim

Gözlerine hiç bakmadığım

Kokusunu bir kez bile

         İçime çekmediğim seni  uğurluyorum                          

Uğurlar olsun....

Kollarında gözlerimi 

                 Bir kez olsun kapatmadığım sevdiğim....', 'Seni uğurluyorum artık yaşamımdan Hiç sevgilim olmadan                 Sevdiğim olan seni Yüzünü hiç görmediğim Gözlerine hiç bakmadığım Kok...', ARRAY['Türk Edebiyatı','Şiir','Fulya Taşangil Aydın']::text[], 8.5, '{"poet":"Fulya Taşangil Aydın","poet_slug":"fulya-tasangil-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek', 'bilmek-sair-nesimim-qspf8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmek

Senin bildiğini ben, 

Benim bildiğimi sen bilirsin..

Bazen olur ki..

Beni sen, 

Seni, ben bilirim...', 'Bilmek Senin bildiğini ben,  Benim bildiğimi sen bilirsin.. Bazen olur ki.. Beni sen,  Seni, ben bilirim......', ARRAY['Türk Edebiyatı','Şiir','Şair Nesimim']::text[], 8.5, '{"poet":"Şair Nesimim","poet_slug":"sair-nesimim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarsın', 'aglarsin-cemal-safi-c65kx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırdığın kadehte kalan ömrümden, 

Ağlarsın içtiğin yılları bilsen.

Hicrinle sararıp solan ömrümden, 

Ağlarsın biçtiğin dalları bilsen.

Sefiller gücünü bende sınadı, 

Kimi kaçık dedi, kimi bunadı; 

Berdûş eleştirdi, sarhoş kınadı, 

Ağlarsın düştüğüm dilleri bilsen.

Ar ettim sakladım uğraşlarımı, 

Haberdâr etmedim sırdaşlarımı.

Gizlemek isterken gözyaşlarımı, 

Ağlarsın seçtiğim yolları bilsen.

Felsefe böyledir dîvânelerde, 

Teselli aranır bahanelerde, 

Bir kadeh mey için meyhânelerde, 

Ağlarsın döktüğüm dilleri bilsen.

Ateşe su dedim göz göre göre, 

Aklım zavallıydı duyguma göre, 

Bahtına şükretti Mecnûn bin kere, 

Ağlarsın düştüğüm çölleri bilsen.', 'Kırdığın kadehte kalan ömrümden,  Ağlarsın içtiğin yılları bilsen. Hicrinle sararıp solan ömrümden,  Ağlarsın biçtiğin dalları bilsen. Sefil...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aglarsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Incimsinnnnnnn''''? ?', 'benim-incimsinnnnnnn-emrullah-erdinc-r7y1g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen kalbimin derinliklerinde sizlayan kor atesimsin. 

Sen benim bekledigim arzumsun sen osun. 

Ruhumun derinliklerindeki yankimsin. 

Kumral saclarinin kokusunu hasretle bekledigimsin. 

Sen benim vatanim istanbulum denizim tasim topragimsin.

Sen benim uzaklardaki erisilmez hasretimsin.

Ya sen nesin sen biliyormusun? 

Benim gözumde ruhumda, afroditten de guzel,  benim, incimsinnnnnnn''''? ? ..', 'Sen kalbimin derinliklerinde sizlayan kor atesimsin.  Sen benim bekledigim arzumsun sen osun.  Ruhumun derinliklerindeki yankimsin.  Kumral ...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benim-incimsinnnnnnn-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Da Vazgeç', 'ya-da-vazgec-ozer-bal-f3g4y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her şeyi isteyebilirsin

seninse

olacaktır.

imkansızı dene

belki

ihtimaldir.', 'her şeyi isteyebilirsin seninse olacaktır. imkansızı dene belki ihtimaldir....', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ya-da-vazgec-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Bedeli', 'sevginin-bedeli-oguz-atalay-o4k8l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Manasız gözlerle bakıyorum boşluğa, 

Elveda sevdiğim! Gidiyorum sonsuza.

Bir de hayata küstüm, daldım umutsuzluğa.

Elveda sevdiğim! Gidiyorum sonsuza

Ben seni çok sevdim, sen sevmesen de beni, 

Çıkarıp atamadım virane yüreğimi, 

Beklemek zor geliyor sevgiyi, sevilmeyi, 

ölüme uğurluyorsun ellerinle beni.

Seven ben, fakat ödeyen de benim bedeli, 

Nice cefalar çekti, şu garibin bedeni.

Çok defalar ağladım, sevdiğim düşünüp seni, 

Uzaklardasın yine, bilmiyorsun halimi.

Ne toprak ne taş ne de su...

Azrail kurmuş çok yakında bir pusu.

Titriyor ellerim, çekiyorum tetiği, 

Gidiyorum Mahşere, bırakıp kederleri.

                                                          

                                                            (11.01.2002) 

                                                        Saat: 03: 00', 'Manasız gözlerle bakıyorum boşluğa,  Elveda sevdiğim! Gidiyorum sonsuza. Bir de hayata küstüm, daldım umutsuzluğa. Elveda sevdiğim! Gidiyoru...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Atalay']::text[], 8.5, '{"poet":"Oğuz Atalay","poet_slug":"oguz-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevginin-bedeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Ağaçları', 'eylul-agaclari-guray-erarslan-9m1cp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin yüzünde eksilen benim canımın çıkmış yarısı

Son yürek atışımı sana verdimdi uzaksız

Adımın yanına esip gelen rüzgar 

Eylüldede  böyle eserdi

Bir yanımız sevebilmekti çığlıksız, 

ufuklarda astımlı çoçuklarca.

Bir yanımızda güneşin elleri, 

ve sen eylül ağaçlarında.

Giderken unutma bir yanımız', 'Senin yüzünde eksilen benim canımın çıkmış yarısı Son yürek atışımı sana verdimdi uzaksız Adımın yanına esip gelen rüzgar  Eylüldede  böyle ...', ARRAY['Türk Edebiyatı','Şiir','Güray Erarslan']::text[], 8.5, '{"poet":"Güray Erarslan","poet_slug":"guray-erarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eylul-agaclari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Toprak', 'eski-toprak-fatih-kisaparmak-2e3f8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski Bir Dost

`Hastanede yatıyormuş salim ` dedi

Hemen koştum ziyarete

`Cok ağrıyor kolum`dedi

Dedi ve düştü

Eski toprak tükenmişti

`Bitti benim yolum`dedi

Gözlerimiz nemlenmişti

`Gayrı yakın ölüm`dedi

Onu en son yalnız gördüm

Ağlıyordu mendil verdim 

Arzun varmı diye sordum

`Oğlum`dedi`Oğlum`dedi

Emrin varmı diye sordum

    `Oğlum`dedi

     Dedi ve sustu

`Birkac kitap birde sazım işte bütün malım`dedi

`Nerden düştüm pencesine bu hastalık Zalım`dedi

`Evladım aldı gitti hayırsızmış gülüm`dedi

`Ölüm birşey değil ama bu ayrılık Zulüm`dedi

`Ölüm bieşey değil ama bu hasretlik Zalım`dedi

Onu en son yalnız gördüm 

Ağlıyordu mendil verdim

Arzun varmı diye sordum

`Oğlum`dedi`Oğlum`dedi

Emrin varmı diye sordum

     `Oğlum`dedi

      Dedi ve sustu', 'Eski Bir Dost `Hastanede yatıyormuş salim ` dedi Hemen koştum ziyarete `Cok ağrıyor kolum`dedi Dedi ve düştü Eski toprak tükenmişti `Bitti b...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kısaparmak']::text[], 8.5, '{"poet":"Fatih Kısaparmak","poet_slug":"fatih-kisaparmak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/eski-toprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime Bu Feryad', 'kendime-bu-feryad-ahmet-riza-korkut-ctmvs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen, hoyrat dağların sessiz rüzgarı

Karlı ovaların sinsi kartalı

Korkuyormusun, 

Üşüyormusun, 

Ağlıyormusun yoksa...

Bir soğuk odan var belki

Belki hiç ısınmaz ellerin

Sabahın ayazı vurur şakağına

Kurşun yağar yüreğine

Bir bir zincire vururlar seni

Belki elinde değil

Belki yakıyor seni bu sevda

Belki O bile duymaz feryadını

Susuyormusun...

Hani sen bir sevda neferiydin

Hani sen deniz feneriydin

Hani yıkılmazdın, yılmazdın

Bağrına taş basar Ağlamazdın

Sırtından vursalar dönüpte bakmazdın

Dururdun dimdik öylece

Dururdun tüm benliğince

Düşüyormusun...

Ey sessiz rüzgar

Bakma bana öyle; 

Bir bitişin perdesi kapanıyor gözlerinde

Bir hayatın sorgusu veriliyor...

Yanıyorsun be eriyorsun

Farkındamısın bilmem

Sen, sen artık bitiyorsun

Bu sevdanı hiçe sayıp

Gidiyorsun...

Sen, hoyrat dağların sessiz rüzgarı, 

Karlı ovaların sinsi kartalı

Ölüyorsun 

Ölüyorsun

Ölüyorsun...

............', 'Sen, hoyrat dağların sessiz rüzgarı Karlı ovaların sinsi kartalı Korkuyormusun,  Üşüyormusun,  Ağlıyormusun yoksa... Bir soğuk odan var belk...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Rıza Korkut']::text[], 8.5, '{"poet":"Ahmet Rıza Korkut","poet_slug":"ahmet-riza-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kendime-bu-feryad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Kötü Şiir', 'en-kotu-siir-ahmet-ulukaya-o685e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizden söylemesi

Dileyen okusun

Yazılanların en kötüsüdür bu şiir

Çamdan kavaktan bahseder

İnsan dururken', 'Bizden söylemesi Dileyen okusun Yazılanların en kötüsüdür bu şiir Çamdan kavaktan bahseder İnsan dururken...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ulukaya']::text[], 8.5, '{"poet":"Ahmet Ulukaya","poet_slug":"ahmet-ulukaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/en-kotu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara Sokaklar', 'ara-sokaklar-ahmet-ulukaya-hsvqe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aydınlığın bittiği yerde

Ara sokaklar başlar

Islak, yorgun ve aç

Terk edilmişler mahşeri

Korkunç felaket girdabı

Aç köpekler, tenezzül etmezler

Ekmeksiz, kemiksiz

Rezil sokaklar

Gölgesinden farksızların yolu

O yol ki, hür dünyada

Tutsak yaşayan

Sefillerin çıplak ayak izleriyle dolu

Ara sokaklar

Yalnızlar, umutsuzlar diyarı

Cılız boyunlarında yoksulluk zinciri

Gönülleri bir dilim ekmek

Özlemiyle buruk

Ölümden kurtuluş bekleyenlerin evi

Ara sokaklar, yaşayanların cehennemi', 'Aydınlığın bittiği yerde Ara sokaklar başlar Islak, yorgun ve aç Terk edilmişler mahşeri Korkunç felaket girdabı Aç köpekler, tenezzül etmez...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ulukaya']::text[], 8.5, '{"poet":"Ahmet Ulukaya","poet_slug":"ahmet-ulukaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ara-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanıma', 'vatanima-ali-hallac-0sd06', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ey kendi ormanında kayıp sanılan ceylan

kadere terkedilmiş, unutulmuşsun sanma

bütün gelecek senin, aydınlık senin inan

özgürlük vaad eden ben hazırım arkanda.

ahum, canım, vatanım; önünü açacağım

uygarlık yolunda birlikte koşacağım

bilim meşalesiyle ışıklar saçacağım

mutluluk vaad eden ben hazırım arkanda.

tarihten ibret alıp, izinden ataların

sapmadım, asla sapmam ne bugün ne de yarın

bilincine varıpta dürüstçe çalışmanın

zenginlik vaad eden ben hazırım arkanda.

yol belli yordam belli, başkası aranır mı

birliğe muhtaç iken hiç düşman olunur mu

dünya hızla giderken geride kalınır mı

yükseliş vaad eden ben hazırım arkanda.

ben hiçbir zaman yılmaz, Atatürk''ün nesliyim

ben barışın bekçisi, zaferler neferiyim

adıma ülkü derler, özgürlük eseriyim

sakın yok zannetme hiç, ben hazırım arkanda.

Ali HALLAÇ

[email protected]', 'ey kendi ormanında kayıp sanılan ceylan kadere terkedilmiş, unutulmuşsun sanma bütün gelecek senin, aydınlık senin inan özgürlük vaad eden b...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/vatanima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsiz Fırtına', 'sebepsiz-firtina-ozan-kaymak-hx2o4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sebepsiz fırtınalar eser içimde, 

Serin ve yalnız akşamlarda.

Kimse bilmez; 

Nerden çıktı, 

Nerden gelip, nereye gidiyor.

Eser sadece

Kimsesiz yollar onundur artık, 

Hüküm sürer serserice.

Felek çarkını döndürürken miskin evlerde, 

O geçer gider  sessizce.

Gider de dönmez geriye, 

Geçmiş yetişemez gölgesine.

Kuşlardır tek dostu yükseklerde, 

Mekanik yaratıklar gelip geçse de...

Onlar programlı, işleri acele.

Bir şehre iner yorgun gecelerde, 

Gider gelir de aynı hecelerde, 

Söyleyemez, kalır içinde...

O malum kelime.

Harabe kalpler kalınca arkasında, 

Buğulu camlara yazılır adı, 

Aşk dolu öfke sözleri arasında.

Akşam olurken yalnız kasabada, 

Gölgesi düşer karlı dağlara, 

Gözleri yüksek ufuklarda.

Eser geçer sebepsiz fırtına.', 'Sebepsiz fırtınalar eser içimde,  Serin ve yalnız akşamlarda. Kimse bilmez;  Nerden çıktı,  Nerden gelip, nereye gidiyor. Eser sadece Kimses...', ARRAY['Türk Edebiyatı','Şiir','Ozan Kaymak']::text[], 8.5, '{"poet":"Ozan Kaymak","poet_slug":"ozan-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sebepsiz-firtina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Külleri Eskimiş Bir Sonbahar', 'kulleri-eskimis-bir-sonbahar-ali-haydar-cakta-lif3y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzağa

-Çarp gönlünü ko savrulsun bu tarumar aşklara-

                                                                 Y.Odabaşı

I.

/Hep efkara bulandı yalnızlığın yüzü

ve hep ayrılıkları saydı gökyüzü.../

Kim bilir, bir daha ne zaman

yüreğim böyle ağırken

ömrümün hangi sağanağında 

böyle susar gözlerim 

böyle yangın kalır ellerim.

II.

/Geceye ayak sesleri yürürken

ıslak bir gülüş geçerdi teninden.../

Kendi zamanını kirleten

ışıklar altında

düş kırığı hüzünler

taşırdı koynunda

ve ne zaman

dokunsam ellerine

kanatları ıslak bir serçe

gelip konardı gözlerine.

III.

/Özlemin yüzüne keder düşünce

tutuşur içimde eskimiş bir kül.../

Bir kızın dudağından

içilen bir tütün gibi

dağılırken geceye bulutlar

tutar, 

yollara bırakırdı gözlerini

eğilip öperdim yaşlarını.

canım acırdı.

Sonra 

yağmurlar susardı.

O giderdi.

Mahçup bir çocuk gibi

                              giderdi.

İçimde 

yoksul bir sonbahar

                          kanardı.

IV.

/Yalnızdım...

kayıp bir şehir kadar yalnız...

                                -bilmediniz.../

Dönme dedim yüzünü

o rüzgar seni ağlatır.

Dedi

    Ey yüreği su yüzlü çocuk

    rüzgara değer elim, kanatlanır

    aşka değer yüzüm, alazlanır

    her aşk bir aldanıştır

    güne değer, talazlanır.

Sonra

yeni gelen her günle

ayaza kaldım

içimde

külleri eskimiş bir sonbahar.', 'Uzağa -Çarp gönlünü ko savrulsun bu tarumar aşklara-                                                                  Y.Odabaşı I. /Hep efka...', ARRAY['Türk Edebiyatı','Şiir','Ali Haydar Çakta']::text[], 8.5, '{"poet":"Ali Haydar Çakta","poet_slug":"ali-haydar-cakta","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kulleri-eskimis-bir-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zıtlığın hikmeti', 'zitligin-hikmeti-mehmet-tan-0awwq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşam ve ölüm

Zengin ve fakir

Güçlü ve zayıf

Sevgi ve nefret

Bu bir isyan değil tanrım

Ama nedir bu zıtlıktaki hikmet?', 'Yaşam ve ölüm Zengin ve fakir Güçlü ve zayıf Sevgi ve nefret Bu bir isyan değil tanrım Ama nedir bu zıtlıktaki hikmet?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zitligin-hikmeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilir misin', 'sen-bilir-misin-suheyla-guler-erden-d6dyk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilir misin nasıl ağlar şu yürek, 

Nasıl biner çile üstüne çile, 

Nasıl ağlanır, nasıl yaşanır, 

Bir sabaha başka sabah nasıl eklenir, 

Sen bilir misin? ? 

Sen anlar mısın, nesin, neredesin, 

Duyar mısın konduğunu gözyaşımın üstüne 

Acımasız hayatın, acımasız saçları, 

Nasıl karışır düzen, nasıl yaşanır 

Sen bilir misin? ? 

Duyar mısın ağladığını denizin, 

Tomurcuklanır da düşer misin avuçlarıma, 

Bir başka duyguyla yanar mı için, 

Yoluna kattığın, bitirdiğin kim, 

Sen bilir misin? ? 

Üşür, titrer ılık bir sevda duyar mısın, 

Bir adımlık gurbette neden beklersin, 

Sen gelsen de, açsa bağrımda gonca, 

Gözümden sakınırım, saklarım seni inan, 

Sen bilir misin? ?', 'Bilir misin nasıl ağlar şu yürek,  Nasıl biner çile üstüne çile,  Nasıl ağlanır, nasıl yaşanır,  Bir sabaha başka sabah nasıl eklenir,  Sen ...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Güler Erden']::text[], 8.5, '{"poet":"Süheyla Güler Erden","poet_slug":"suheyla-guler-erden","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-bilir-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İhtilalimdin Benim', 'sen-i-htilalimdin-benim-suheyla-guler-erden-rji51', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.Sen benim ihtilalim oldun.

Yaşadığım en acı darbeden geriye kaldın.

Asla kül olmadan, asla gün gibi batmadan. 

Çocukluğumun kirli, paslı aynasından bana gülen.

Sevincim, üzüntüm, karım, zararım oldun.

Asla yıkmadan, asla yakmadan. 

Gençliğimin tozlu, buzlu yollarında 

iki el iki yürektin.

Sen ergenliğimin zekası, sefası, cefası, yolu, yordamıydın.

Asla çiğnemeden, asla incitmeden. 

ve şimdi..ve dün..ve bugün..Sen yoksun.

Geride toz duman bir şehir, kilometrelerce  yol, 

hatta uzanırsam tutabileceğim 

dört duvarın kilometrelerce ötesindesin. 

Bana SEVDİĞİM TEK TÜK KADINLARDAN BİRİSİN diyen.

Ben tek tük''tüm ama sen tek''tin. 

Çünkü sen üç evremin miladıydın. 

Çünkü sen İHTİLALİMDİN..', '.Sen benim ihtilalim oldun. Yaşadığım en acı darbeden geriye kaldın. Asla kül olmadan, asla gün gibi batmadan.  Çocukluğumun kirli, paslı ay...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Güler Erden']::text[], 8.5, '{"poet":"Süheyla Güler Erden","poet_slug":"suheyla-guler-erden","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-ihtilalimdin-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttuğum Gün', 'unuttugum-gun-suheyla-guler-erden-1dp8d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni unutacağım gün, 

Duman tütmeyecek bacam. 

Donacak parmaklarım.. 

Türkü söylemeyeceğim. 

Yas tutacağım bir ömür, 

Gökyüzü gözlerimden akacak. 

Ağlayacağım... 

Seni unutacağım gün, 

Ben olmayacağım. 

Ellerim olmayacak teninde gezen, 

Türkülerimde olmayacak, 

Seninle ağlayan. 

Bil ki güller solacak ve belki de 

Ölümüne ölüm olacak. 

Seni unutacağım gün, 

Yarılacak gökler yarıdan 

Kopacak iğrenç çığlıklar. 

Ve ne sen, ne ben, ne ikimiz, 

Olmayacağız o an.. 

Duymayacağız bu felaketi. 

Çünkü ben seni, sen beni, 

Unutmayacağız hiç bir zaman... 

(Gülnisan''dan)', 'Seni unutacağım gün,  Duman tütmeyecek bacam.  Donacak parmaklarım..  Türkü söylemeyeceğim.  Yas tutacağım bir ömür,  Gökyüzü gözlerimden ak...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Güler Erden']::text[], 8.5, '{"poet":"Süheyla Güler Erden","poet_slug":"suheyla-guler-erden","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unuttugum-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın', 'anlarsin-suheyla-guler-erden-1kp38', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz karanlık gecelere, 

Biz yasak meyvalardık. 

Biz her yerde, her yanda 

Sabah diye uyanandık. 

Nazar gelmesin diye, 

Köşe bucak saklanandık. 

Ben seni sevdim nasıl, 

Hem de nasıl bilirsin. 

Ben seni tenhalarda, 

Ben yaşamlarda sevdim. 

Ben seni her anımda, 

Ve her yanımda sevdim. 

Biz nehir sandık yağmurları, 

Yıldız sandık ocakları, aşları. 

Biz yasak dünyaların. 

Biz yasak aşklarıydık. 

Bilirdin vazgeçilmez 

Sevda yollarındaydık.. 

(Gülnisan''dan)', 'Biz karanlık gecelere,  Biz yasak meyvalardık.  Biz her yerde, her yanda  Sabah diye uyanandık.  Nazar gelmesin diye,  Köşe bucak saklanandı...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Güler Erden']::text[], 8.5, '{"poet":"Süheyla Güler Erden","poet_slug":"suheyla-guler-erden","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anlarsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hercai', 'hercai-suheyla-guler-erden-k5lc4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bu şehirden, 

Her gittiğinde. 

Hep ağladım ben, 

Hercai menekşe. 

Ve hüzün salar yüreğim. 

Kırmızı gelincikler gibi, 

Üşür güzelliklerim. 

Ve benim dudağımdaki 

Senin gülüşün. 

Senin nefesin, 

Yüreğimdeki. 

Gözlerimle yaşam diye 

Baktığım. 

Senin sevdan üzerimdeki.', 'Sen bu şehirden,  Her gittiğinde.  Hep ağladım ben,  Hercai menekşe.  Ve hüzün salar yüreğim.  Kırmızı gelincikler gibi,  Üşür güzelliklerim...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Güler Erden']::text[], 8.5, '{"poet":"Süheyla Güler Erden","poet_slug":"suheyla-guler-erden","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hercai-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar', 'umutlar-hanimsah-tekeli-jpsd4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki imkansızdı ama

Umutlarım vardı

Renksiz, solgun, ölü umutlar

Aşkın kördüğüm olduğu anda

Kalbimde coşan umutlar...', 'Belki imkansızdı ama Umutlarım vardı Renksiz, solgun, ölü umutlar Aşkın kördüğüm olduğu anda Kalbimde coşan umutlar......', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/umutlar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur..! !', 'ne-olur-suheyla-guler-erden-rkycs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerimin daldığı yerde 

Görün ne olur. 

Sana saklı yüreğime, 

Gömül ne olur. 

Sen benim bir yarımsın, 

Diğer yarım seni bekler, 

Dön ne olur.. 

Şafak söktü gün ağardı, 

Gör ne olur. 

Ağladı eller yalnızlığıma 

Bir ıslık tüter dudaklarımın 

Kanayan çatlak yuvalarında 

Dokun ne olur.. 

Ve gün ağarır şafakla 

Yorgun gölgeler titreşir. 

Bir yarım aşk, bir yarım yara 

Akşamı bekler ellerim 

Gel ne olur..', 'Gözlerimin daldığı yerde  Görün ne olur.  Sana saklı yüreğime,  Gömül ne olur.  Sen benim bir yarımsın,  Diğer yarım seni bekler,  Dön ne ol...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Güler Erden']::text[], 8.5, '{"poet":"Süheyla Güler Erden","poet_slug":"suheyla-guler-erden","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-olur-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Anlıyor musun?', 'beni-anliyor-musun-niyazi-cetiner-3ysel', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazmak istedim, 

Kalemimin ucu kırıldığı zaman. 

Bir şarkı söylemek istedim, 

Nağmeler boğazıma dizildiği zaman. 

Sessiz bir köşede ağlamak istedim, 

Yağmurlar yağmadığı zaman.

Seni onlara anlatmak istedim, 

Vakit gece yarısı olduğu zaman, 

Ölmek istedim sevgilim ölmek, 

Sen doğduğun zaman...', 'Bir şiir yazmak istedim,  Kalemimin ucu kırıldığı zaman.  Bir şarkı söylemek istedim,  Nağmeler boğazıma dizildiği zaman.  Sessiz bir köşede...', ARRAY['Türk Edebiyatı','Şiir','Niyazi Çetiner']::text[], 8.5, '{"poet":"Niyazi Çetiner","poet_slug":"niyazi-cetiner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beni-anliyor-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Paylaşacaktın', 'hani-paylasacaktin-nurullah-genc-n6zbe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani paylaşacaktın benimle

Hani deniz en derin yurdumuz olacaktı

Hani konsun diyordun kalbimize martılar

Hani avuçlarımız yağmurla dolacaktı

Hani kartallar gibi kanatlanıp doruğa

Hani bölüşecektik mevsimleri

Neden yine bin parça eyledin resimleri

Hani gök, nerde ufuk, neden sustu dalgalar

Ayaklarımda yine bu zalim prangalar...', 'Hani paylaşacaktın benimle Hani deniz en derin yurdumuz olacaktı Hani konsun diyordun kalbimize martılar Hani avuçlarımız yağmurla dolacaktı...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hani-paylasacaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-yildiz-dost-qms32', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kotu kader dıyecek, 

Boynumu bukecegım, 

Acılarım dostum olacak, 

Hep senın, mutlu olmanı dıleyecegım...', 'Kotu kader dıyecek,  Boynumu bukecegım,  Acılarım dostum olacak,  Hep senın, mutlu olmanı dıleyecegım......', ARRAY['Türk Edebiyatı','Şiir','Yıldız Dost']::text[], 8.5, '{"poet":"Yıldız Dost","poet_slug":"yildiz-dost","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hasret-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-turabi-turan-ib1d9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sen kaldın yitirmediğim      

                               bırak gölgeni             

                                    rüzgar savursun

Ateşler içinde beklerken, yarını

                                geçmişine gül

                                                o sensin

Vazgeçilmez

Bir ben kaldım yitirmediğin

                              bırak yüreğini

                                     yağmur ıslatsın

Sancılar içinde beklerken, doğumları

                               bırak gözlerine

                                      gökkuşağı dolsun

                                                           o benim 

kararlı 

Bir sen kaldın biriktirdiğim

                               bırak ellerin

                                        yeşili sarsın

Dilindeki yaralardan beslenirken, kelimeler

                                sevdana açıl

                                              o benim

Alınyazın            

(ocak 2002  Muş)', 'Bir sen kaldın yitirmediğim                                      bırak gölgeni                                                  rüzgar savur...', ARRAY['Türk Edebiyatı','Şiir','Turabi Turan']::text[], 8.5, '{"poet":"Turabi Turan","poet_slug":"turabi-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/birak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-demet-atasoy-0ows9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ah ankara derken birden...

   onu sevmişken canım kadar...

   özlemişken...

   yanıp tutuşurken...

   nereye geldim..

   şuan kimleyim..

   özlemişim umurundamı derken..

   sensizliğe alışmışken...

   unutturuyormu yoksa seni...

   küçükte olsa bu şehir..

   benden aldı kocaman bir beni..

   özlettirmedi seni...

   özleyemedim bile...', 'ah ankara derken birden...    onu sevmişken canım kadar...    özlemişken...    yanıp tutuşurken...    nereye geldim..    şuan kimleyim..    ...', ARRAY['Türk Edebiyatı','Şiir','Demet Atasoy']::text[], 8.5, '{"poet":"Demet Atasoy","poet_slug":"demet-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ankara-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hercaı sevgılı', 'hercai-sevgili-yildiz-dost-z94be', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dunyanın sonu degılkı, 

Sevmıyorsan...

Kıyamet kopmazkı, 

Istemıyorsan...

Zorla guzellık olmazkı, 

Uzak dur, benden sevmıyorsan...

Sanmakı, herseyım sensın, 

Yasayabılırımkı, 

Sensızde...  Ben...

Kendıne cok guvenme boyle, 

Bırgun yuregını yanlız hıssedersen, 

Mutsuz olup uzulekalırsın ınan, 

Son pısmanlık fayda vermez, 

Haberın olsun, hercaı...

Yalnız kalırsın

Asksız, sevgısız ve enkotusu Bensız...', 'Dunyanın sonu degılkı,  Sevmıyorsan... Kıyamet kopmazkı,  Istemıyorsan... Zorla guzellık olmazkı,  Uzak dur, benden sevmıyorsan... Sanmakı, ...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Dost']::text[], 8.5, '{"poet":"Yıldız Dost","poet_slug":"yildiz-dost","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hercai-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-tolga-yilmaz-0h82k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Demek gitmek istiyorsun, git! 

Görüşmek üzere diyorsun. 

Geri döneceğim diyorsun.

Peki öyle olsun.

Ama, 

Yarın öyle bir bakacağım ki gözlerine hasretle, 

Öyle bir sarılacağım ki boynuna sevgiyle, 

Sen bile korkacaksın yalnızlığımdan...

Haydi durma, git artık git!', 'Demek gitmek istiyorsun, git!  Görüşmek üzere diyorsun.  Geri döneceğim diyorsun. Peki öyle olsun. Ama,  Yarın öyle bir bakacağım ki gözleri...', ARRAY['Türk Edebiyatı','Şiir','Tolga Yılmaz']::text[], 8.5, '{"poet":"Tolga Yılmaz","poet_slug":"tolga-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/git-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Erken', 'cok-erken-bedir-koker-nfdi2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göç eden lacivert kuşları aramak için 

ayrılıyorum ülkemden

sana uğramak bir ihtimal sadece

belki esir düşerim bir düşüne

ıhtırmadan, kestiremediğim yanlarımla

başlarım söze.

Sana doğru üç kere öleceğim

akşama yakın bir vakitte

eskittiğim yollar satılıktır

geri dönmem için ülkeme

kanıttır seraplar susuzluğuma.

Sancaksızım yani tanımsızım radarlara

beni kör dilenciler farkeder

ve evlerine koşan çocuklar

hangi yanlarım uysallaşacak bilmem

güneş battığında, 

tozlu gözlerimle dalınca.', 'Göç eden lacivert kuşları aramak için  ayrılıyorum ülkemden sana uğramak bir ihtimal sadece belki esir düşerim bir düşüne ıhtırmadan, kestir...', ARRAY['Türk Edebiyatı','Şiir','Bedir Köker']::text[], 8.5, '{"poet":"Bedir Köker","poet_slug":"bedir-koker","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cok-erken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman ve Gemi', 'zaman-ve-gemi-deniz-feneri-0wsxo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam istanbul yine ben 

Hani her akşam sabaha kadar içen

Berduş var ya kimsesiz

Tanıdın mı? 

Garson bak buraya

Benim dostlarım nerede

Getirsen artık

Özlemişlerdir..

Hadi canım nerde! 

Ne güzel demiş Tanju Okan 

Benim en iyi dostum içkim sigaram 

Onlarda terkederdi olmasaydı param

Niye özlesinler ki...? 

Kadehde durduğu gibi de durmuyor meret

Hani bir kız sevmiştim ya 

Ondan önce içemezdim bu kadar

Öyle bir çarptı ki onun gidişi

Artık hiç birşey çarpamaz beni

Hey garson bak! 

Bak bir gemi geçiyor boğazdan

Gecenin karanlığında o sakin suyu yararak

Geç gemi geç 

Kimbilir hangi limanda bekleyenlerin var

Geç zaman geç 

Bizi bekleyenler var', 'Selam istanbul yine ben  Hani her akşam sabaha kadar içen Berduş var ya kimsesiz Tanıdın mı?  Garson bak buraya Benim dostlarım nerede Getir...', ARRAY['Türk Edebiyatı','Şiir','Deniz Feneri']::text[], 8.5, '{"poet":"Deniz Feneri","poet_slug":"deniz-feneri","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zaman-ve-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgede Aşk', 'golgede-ask-can-kara-dyitw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski Bir şarkının

Saklanarak arkasına

Kendi halinden yorgundu aşk

Ve siz daha cesurdunuz

Ki

En büyük intikamdı gölgeler

Tarihi aşkla kanatan kuşatmalar vardı

Siz surlarında kılıçtan geçirilirken

Çok cesurdunuz

Daha da eskiterek şarkıları

Gölgesine saklanıyordu aşk

Ve biz biliyorduk

Gölgede büyümezdi aşk', 'Eski Bir şarkının Saklanarak arkasına Kendi halinden yorgundu aşk Ve siz daha cesurdunuz Ki En büyük intikamdı gölgeler Tarihi aşkla kanatan...', ARRAY['Türk Edebiyatı','Şiir','Can Kara']::text[], 8.5, '{"poet":"Can Kara","poet_slug":"can-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/golgede-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-can-kara-7rm9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen olmasan

Gözlerin olmasa

Umut bu kadar hırçın

Aşk bu kadar sarhoş

Ve ben 

Bu kadar deli

Beklermiydim seni', 'Sen olmasan Gözlerin olmasa Umut bu kadar hırçın Aşk bu kadar sarhoş Ve ben  Bu kadar deli Beklermiydim seni...', ARRAY['Türk Edebiyatı','Şiir','Can Kara']::text[], 8.5, '{"poet":"Can Kara","poet_slug":"can-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yaz Bana', 'bir-siir-yaz-bana-bora-zihni-6ui7e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir yazdın mı sen hayatında  hiç? 

Hiç gizleyip yüreğine sığdıramadığın duygularını

Mısralara dizdiğin, 

Okurken onu düşünüp 

Çaresizliğine  ağladığın oldu mu? 

Bir şiir yaz bana  ne olur? 

Yaz ki anla beni.

Anla sevgimin çaresizliğini.

Anla sevgisiz şiir yazılamayacağını.

Anla Tayfanın seni ne kadar sevdiğini.', 'Şiir yazdın mı sen hayatında  hiç?  Hiç gizleyip yüreğine sığdıramadığın duygularını Mısralara dizdiğin,  Okurken onu düşünüp  Çaresizliğine...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-siir-yaz-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç Dikin', 'agac-dikin-abdulkadir-guler-qg4uw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün derste öğretmenim, 

‘Birer ağaç dikin’ dedi.

‘Benden size olsun öğüt, 

Gelecekte bu ağacın

Meyvesini biçin’ dedi.

Ertesi gün bir bahçede, 

Kürek kazma çapa elde, 

Çukur açtık sıra ile.

Emir verdi öğretmenim, 

‘Fidanları dikin’ dedi.

Yıllar sonra bir bahçede, 

Buluşmuştuk öğretmenle, 

Son kez daha vurguladı, 

Ağaç orman hepsi sizin, 

‘Kesmeyiniz sakın’ dedi.

Herkes bunu anlamalı, 

Genç ihtiyar kavramalı, 

Ağaç orman yurdun malı, 

Gölgesinde her ağacın

‘Soğuk sular için’ dedi.

Abdülkadir GÜLER', 'Bir gün derste öğretmenim,  ‘Birer ağaç dikin’ dedi. ‘Benden size olsun öğüt,  Gelecekte bu ağacın Meyvesini biçin’ dedi. Ertesi gün bir bah...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Güler']::text[], 8.5, '{"poet":"Abdülkadir Güler","poet_slug":"abdulkadir-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/agac-dikin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Rengi Ela', 'askin-rengi-ela-can-kara-jpru3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey aşk

Binlerce gemi yakarak

Dönüşü olmayan akşamlardı

Bıraktığın ardında

Ki

Yalnız ve sarhoş

Sorgulayarak kendini

Yargılanmadan mahkum edildin

Uçurumlardan savrulur o renk

En yalın halinde 

Ela sen bakarken aşktır

Ve ben en acemi halimle

Kendime saklarım 

Bakışlarını', 'Ey aşk Binlerce gemi yakarak Dönüşü olmayan akşamlardı Bıraktığın ardında Ki Yalnız ve sarhoş Sorgulayarak kendini Yargılanmadan mahkum edil...', ARRAY['Türk Edebiyatı','Şiir','Can Kara']::text[], 8.5, '{"poet":"Can Kara","poet_slug":"can-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askin-rengi-ela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Oğlan', 'bizim-oglan-kemal-yilmaz-bzcel', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beşi bitirdi bizim oğlan

Aman okusun Kemal efendi, 

Okusun. 

Ağaya olmasın çoban.

Sarı inek bölünmez ki dörde, 

El kadarcık kıraç tarla, 

Derman mı olur derde.

Bizim oğlan okusun

Ayağımı yer yakar benim, 

Başımı gün yakar öğretmenim, 

Bizim oğlan okusun.

Paşa olsun desem olmaz, 

Doktor okuluna gidemez, 

Öğretmenlik nesine yetmez...

Yılda on iki harman, 

Aylığın alsın gölgede oturduk yerden, 

Birazda bizim oğlan.

Ağanın kızı olsun mu oğlana hayran, 

Oku, kurbanın olam

Oku bizim oğlan.

M. Kemal YILMAZ', 'Beşi bitirdi bizim oğlan Aman okusun Kemal efendi,  Okusun.  Ağaya olmasın çoban. Sarı inek bölünmez ki dörde,  El kadarcık kıraç tarla,  De...', ARRAY['Türk Edebiyatı','Şiir','Kemal Yılmaz']::text[], 8.5, '{"poet":"Kemal Yılmaz","poet_slug":"kemal-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bizim-oglan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Sevgimiz', 'bizim-sevgimiz-ensar-cevval-f0f9h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz Anadolu''nun sert ikliminde

acımasız rüzgara yüzüdönük yürüdük.

Biz gelinlik kız boyu soğuk beyazlarda

yalınayak, bağrıaçık yürüdük.

bacasında değil; odasında duman tüten

kireç kokulu ocaklarda büyüdük.

bir palto''yu, bir ceket''i, ayakkabıyı

yedi kardeş yıllarca değişip giydik

tahta masalarda lamba ışığında ders çalışıp

aynı masada yemeğimizi yedik

Biz paylaşmayı, sevgiyi.kardeşliği

büyük yüreklerde küçülüp

küçük yüreklerde büyümeyi öğrendik

yatağımızı, elbisemizi, defter ve kalemimizi

kimi zaman duygularımızı.gözyaşlarımızı

tanrı misafiri ile soframızı

sofra kırıntılarını kuşlarla paylaşmayı öğrendik.

Aldırma(!)  sert, maço mizacımıza

bizim mayamız serttir.toprağımız gibi

göz pınarımız taştan örülü sur gibi

lakin yüreğimize dokunursa çocuk elleri

yaş dolmuşsa bir ananın, yetimin gözleri

surları çamur yapmayı öğrendik

Bizim yüreğimiz kocaman, sanki bir umman

gemileri kucaklayan koca bir liman

sanki Ağrı, zirvesi hep duman

seversek, eğer seversek gerçekten

karşımızdaki varsın olsun sonsuz asuman

onu da alır kucaklar bu koca liman...

Ensar CEVVAL', 'Biz Anadolu''nun sert ikliminde acımasız rüzgara yüzüdönük yürüdük. Biz gelinlik kız boyu soğuk beyazlarda yalınayak, bağrıaçık yürüdük. baca...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bizim-sevgimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-ahmet-hamdi-tanpinar-buetd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu akşam rüyamda Leylâ''yı gördüm, 

Derdini ağlarken yanan bir muma; 

İpek saçlarını elimle ördüm, 

Ve bir kemend gibi taktım boynuma, 

Bu akşam rüyamda 
..........
..........', 'Bu akşam rüyamda Leylâ''yı gördüm,  Derdini ağlarken yanan bir muma;  İpek saçlarını elimle ördüm,  Ve bir kemend gibi taktım boynuma,  Bu ak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hamdi Tanpınar']::text[], 8.5, '{"poet":"Ahmet Hamdi Tanpınar","poet_slug":"ahmet-hamdi-tanpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/leyla-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeğim', 'cicegim-sait-ferhat-ozmen-a48ux', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönül bahçemin tek gülü olsaydın sen		

(ki tek çiçeğisin) 	

Seni koklamak düşerdi bana			    Ki sadece bakmak yetti.					

Oysa ben sana doymak isterdim, 					

Özlemek değil.					

Ve seni sevmek isterdim					

Sevgimden korkmak değil.					

Haykırmak isterdim dağlara taşlara çağlarcasına					

Sevdim ve bu sevgi benim! ! !', 'Gönül bahçemin tek gülü olsaydın sen		 (ki tek çiçeğisin) 	 Seni koklamak düşerdi bana			    Ki sadece bakmak yetti.					 Oysa ben sana doym...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cicegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar mı Ben mi', 'kuslar-mi-ben-mi-sait-ferhat-ozmen-8cdup', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuş olmak isterdim ben.				

Özgürce uçmak, 				

Seçebilmek isterdim....				

Oysa ne kuşum ne özgür.				

Ama mutluyum yinede				

Çünkü hala biliyorum				

Hem ne istediğimi				

Hem de ne kadar sevdiğimi.				

				

Biliyorum şimdi kuşlar ben olmak isterdi....', 'Kuş olmak isterdim ben.				 Özgürce uçmak, 				 Seçebilmek isterdim....				 Oysa ne kuşum ne özgür.				 Ama mutluyum yinede				 Çünkü hala b...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kuslar-mi-ben-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geçti', 'cok-gecti-sait-ferhat-ozmen-94k03', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sevmeyi bilirim derdim 					

Çünkü ben hep dolu doluya severdim					

Hep sevdim hep sevilmek istedim					

Hep bırakılan oldum kızdım sevgilerime sevdiklerime					

Ne bileydim sadece kendim için sevdiğimi					

Sevdiğimi, beni seveni mutlu edemediğimi					

Sonra anladım niye beni bırakıp gittiklerini					

Ama geçti, hatta çok ama çok geçti....', 'Ben sevmeyi bilirim derdim 					 Çünkü ben hep dolu doluya severdim					 Hep sevdim hep sevilmek istedim					 Hep bırakılan oldum kızdım sev...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cok-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Suyu Sızmakta', 'kar-suyu-sizmakta-akif-kurtulus-w5gwt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'can çekişen aşkları da vurmalı 

vurmalı  '' sıradan bir intihar '' süsü vermeli 

                             18-19 Mayıs 1982 Bursa 

eski fotoğraflarda bıraktığım bir yuvarlanışım vardı

kurumuş eğreltilerden yazla gölgelenmiş ellerine

uzun bir kış yaşadım, yaşlı çizgiler yakıştırdım alnıma

kaşım kirpiğim geçilmez oldu kırağılardan

yaşım durmadan arttı savrulduğum tipilerle

diplerine aklar bıraktım sakalarım uzadıkça 

gittikçe uzaklaştırıyorum göğsümü yanaklarından

parmaklarım uymuyor anılarla parlattığım yüzüklere

yokediyorum birden tutuşabilecek yerlerimi

uzun bir kış yaşadım, kar suyu sızmakta tırnaklarımdan', 'can çekişen aşkları da vurmalı  vurmalı  '' sıradan bir intihar '' süsü vermeli                               18-19 Mayıs 1982 Bursa  eski fot...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kar-suyu-sizmakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Uzanan Şiir', 'kendine-uzanan-siir-deger-ulas-turan-jdvkc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şehir uzakken diğerine, 

Seni oradan tutmak isterdi yüreğim, 

Acılara inat... 

Bir çiçeğin tohumlarını sunarken sana, 

Doğumlarıyla yeniden gülmeli hayat... 

Her şey değişmeli 

Ve önce acılardan başlanmalı, 

Sonra bizden... 

Ben gördüm 

Yaşadığım coğrafyada, 

İçimde var tohumları sana getirdim, 

Alır mısın? 

Bir gülüş içinde ne acılar büyüttü 

Ve sen güle gülüşünü verdin, 

Sonra yaprağı kanadı gülün, 

Dikenleri senden sonra yok... 

Ve suyla karıştığı anlar, 

Yitirdi o kokusunu toprak... 

Anlamakmış şimdi, 

Gerçek gibi yalanları... 

Hayatı saklayıp bizden, 

İnsanı bir dehlize attılar, 

Bul şimdi kendini... 

Gir o dehlizin içine, 

Bak orda suretin, 

Gerçek orda 

Her şey orda. 

Aşklar, ayrılıklar… 

Saklandığın her şey. 

Belki gerçek bir kış... 

Burası mavi üstü bir mazi, 

Yaşıyorum geçmiş gibi. 

Al tut geçmişi sana getirdim, 

Hepsi temiz, 

Yıkadım arındırdım her şeyi. 

Bir hayalet misali üstüne sindiğim bu toprak belki, 

Belki sen, 

Belki ben, 

Ne olursa... 

Bir çiçek belki 

Karda açan kardelen misali. 

Beni anlıyorsun artık sen... 

Merak ediyorsan hala gerçeği 

Ve hep merak ediyorsan o çiçeği, 

Asi oluşlarını özlüyorsan, 

Ben gördüm yaşadığım coğrafyada... 

İçimde var tohumları 

Sana getirdim 

Alır mısın? 

Şiirler asla tatlı olmaz sevdiğim, 

Buna inan... 

Fark; 

İçindeki acı iksirindedir, 

Hayat gibi... 

Sen okursun bal olur, 

Yazarken bana düşer baldıran acısı. 

Ve hep merak ediyorsan acıları, 

Baldıran tadını... 

Ben gördüm yaşadığım coğrafyada... 

İçimde var acısı, 

Sana getirdim, 

Alır mısın?', 'Bir şehir uzakken diğerine,  Seni oradan tutmak isterdi yüreğim,  Acılara inat...  Bir çiçeğin tohumlarını sunarken sana,  Doğumlarıyla yeni...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/kendine-uzanan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olmuşuz', 'ne-olmusuz-yalcin-ergun-q0dlh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakışlarla eriyip, sözlerle şekillendik

Gülüşlerle serpilip, sohbetle filizlendik

Şarkılarla ağlayıp, şiirlerle dillendik

Dost olduk o gün senle, el’den de öte

Gönüllerden akışlar yavaş yavaş başladı, 

Kalplerde heyecanlar, aniden telaşladı

İçimiz temizlendi, kötülüğü dışladı

Can olduk o gün senle, dost’tan da öte

Sonrası bir acayip oluverdik ikimiz, 

Görmeden duramadık, birini diğerimiz

Hepten doruğa çıktı, gizli kalan sevgimiz

Yâr olduk o gün senle, can’dan da öte

Geldi geçti seneler, bitti bütün hevesler

Kalmadı o duygular, sınırsızca istekler

Her gün  bir şeyler çıktı, ayrılığa davetler

El olduk o gün senle, hepsinden öte...

Yalçın Ergün / 14.08.1995', 'Bakışlarla eriyip, sözlerle şekillendik Gülüşlerle serpilip, sohbetle filizlendik Şarkılarla ağlayıp, şiirlerle dillendik Dost olduk o gün s...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-olmusuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sömestr', 'somestr-yalcin-ergun-azao4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir dönem geldi geçti, çocuktum bağımsızdım

Savaş, seviş, iyi, kötü, her şeye duyarsızdım

Düşene güler düşünce ağlar, öyle ki pervasızdım

Her çocuk gibi ben de günahsız, riyasızdım

Bir dönem geldi geçti, gençtim vurdumduymazdım

Asiydim hem hırçındım, hislere gem vurdurmazdım

Bazen mahzun olsam da, çoğu gün hiç durmazdım

Her genç gibi ben de, aşıktım şiir yazdım

Bir dönem geldi geçti, askerdim hemen kaynaştım

Bazı günler oynaştım, bazı günler ağlaştım

Kim bilir ki kaç kere canla başla savaştım

Her asker gibi bende, mutlu sona ulaştım

Şimdi bir dönem geldi, nedir tam bilemedim

Askıda kaldım zaten, bu budur diyemedim

Serde erkeklik var ya, hiç yardım dilemedim

Ne sevdim ne sevildim, şefkati göremedim...

Yalçın  Ergün / 14.08.1995', 'Bir dönem geldi geçti, çocuktum bağımsızdım Savaş, seviş, iyi, kötü, her şeye duyarsızdım Düşene güler düşünce ağlar, öyle ki pervasızdım He...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/somestr-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahları Ve Akşamları Okumak İçin', 'sabahlari-ve-aksamlari-okumak-i-cin-bertolt-brecht-32yqz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdiğim

Dedi ki bana,

Sen bana lazımsın

Onun için

Kolluyorum kendimi

Yoluma dikkat ediyorum ve

Korkuyorum her yağmur damlasından

Beni ezecek diye

1937', 'Sevdiğim Dedi ki bana, Sen bana lazımsın Onun için Kolluyorum kendimi Yoluma dikkat ediyorum ve Korkuyorum her yağmur damlasından Beni ezece...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sabahlari-ve-aksamlari-okumak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaziyet', 'vaziyet-yalcin-ergun-53lqa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalgaların içinde savrulan bir sal gibi

Altüst olmuş yüreğim, yaşayıp gidiyorum

Rüzgarın karşısında sallanan bir dal gibi

Çaresizlik içinde, çürüyüp bitiyorum

Seher vakti bülbülün ahenkli sesi gibi

Bütün gün kulağımda, sesini duyuyorum

Utanarak verilen sevda busesi gibi

Resmine bir öpücük konduruyorum

Issız ormanlardaki derin sessizlik gibi

Bir başıma öylece, düşünüp susuyorum

Bir yavru ceylandaki sonsuz eşsizlik gibi

Ara sıra kaybolup, köşeme pusuyorum

Yalçın Ergün / 16.08.1995', 'Dalgaların içinde savrulan bir sal gibi Altüst olmuş yüreğim, yaşayıp gidiyorum Rüzgarın karşısında sallanan bir dal gibi Çaresizlik içinde,...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vaziyet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görürüm Ama', 'gorurum-ama-yalcin-ergun-yuli1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen gökyüzünün derinliğinde

Bazen de denizlerin enginliğinde

Kimi gün, bir çocuk şirinliğinde

Öylesine nihayetsiz, görürüm seni

Bazen hayatın ta kendisinde

Bazen de hayalin toz pembesinde

Kimi gün, nehirlerin köpürmesinde

Öylesine tutulmaz, görürüm seni

Bazen terazinin hak kefesinde

Bazen de odamın dört kafesinde

Kimi gün, ölümün sık nefesinde

Öylesine yakın, görürüm seni

Bazen yüreğimin içerisinde

Bazen de zihnimin sır perdesinde

Kimi gün, her şeyin en gerisinde

Öylesine anlamsız, görürüm seni

Bazen sonsuzluğun bilinmezinde

Bazen de düşüncenin denilmezinde

Kimi gün, meselenin çözülmezinde

Öylesine istemsiz, görürüm seni

Bazen her dakika, her an durmadan

Bazen de günlerce ufka varmadan

Kimi gün, çılgın gibi hiç yorulmadan 

Öylesine coşkulu, görürüm seni

Ve bazen güzelim seni görmeden

Hayatın anlamını bilmek isterim

Hiç boyun eğmeden, ödün vermeden

Öylesine sessiz ölmek isterim...

24.08.1995', 'Bazen gökyüzünün derinliğinde Bazen de denizlerin enginliğinde Kimi gün, bir çocuk şirinliğinde Öylesine nihayetsiz, görürüm seni Bazen haya...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gorurum-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Bir Dörtlük', 'sadece-bir-dortluk-yalcin-ergun-jd54w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen, olmadık yerde atar, insanların tepesi

Beklenmeden, ansızın dolar günah kesesi

Böyle durumlar için, şöyle der ki ceddimiz; 

*Tezekten terazinin, boktan olur kefesi

05.09.1995', 'Bazen, olmadık yerde atar, insanların tepesi Beklenmeden, ansızın dolar günah kesesi Böyle durumlar için, şöyle der ki ceddimiz;  *Tezekten ...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sadece-bir-dortluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar 1', 'sevgiliye-mektuplar-1-yalcin-ergun-r2df0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece rüyamda yine seni gördüm, 

Dün gece gördüğüm gibi

Ve biliyorum ki; yarında sen olacaksın düşlerimde

Her zaman olduğun gibi

Yine seni bulacağım sabah aynaya baktığımda

Her sabah bulduğum gibi

Ve yüzümü yıkarken avucumda ki suda seni hayal edeceğim

Vuracağım yüzüme, buz gibi

Kahvaltı ederken çayıma seni atacağım şeker diye

Zeytin tanelerini gözlerin, peyniri tenin sanacağım

Bir dilim ekmeği aşkın sayacağım, öylesi kutsal

Peşinden ilk sigaramı içeceğim, buram buram sen

Düşeceğim yollara sana rastlarım diye, 

İşyerinde bulacağım seni, bilgisayar şifremde bile

Gelen her evrakı mektubun sanıp

Açınca yıkılacağım, hep bile bile

Bir gazete alacağım elime, seni okuyor gibi

Her resimde senden bir benzerlik bulacağım	

Her makalede sanki seni yaşayıp

Aşkımın hikayesini yeniden tasarlayacağım

Yine akşam olacak, içimdeki hüzünle birlikte

Yavaş yavaş kararacak ortalık, gözbebeğim de öyle

Ama yine bir umut olacak içimde, çünkü sabahlar devam edecek

Ömür vefa ettiğince belki, böyle sürüp gidecek

Ama ben her bahar senin sıcaklığını duyacağım kemiklerimde

Yeni yeni aşık oluyormuş gibi seveceğim delice

Ve her kokladığım kır çiçeğinde seni

Her gördüğüm kelebekte nefesini hissedeceğim

Benim ne ilgime ki hazan gelmiş mevsime

Bana ne sanki ağaç yaprağın dökse

Sanki umurumda mı, sonbaharlar da bitse

Nasılsa kar yağacak, içim beyazlanacak

Üstelik dün akşam Macarları da yendik

Adeta Osmanlı’da sefer varmışçasına

Ve sevindim, senin de sevineceğini düşünerek

Öylece masumâne, öylece coşkulu ve umutla gülümseyerek

Görüşmek ümidiyle...

07.09.1995', 'Bu gece rüyamda yine seni gördüm,  Dün gece gördüğüm gibi Ve biliyorum ki; yarında sen olacaksın düşlerimde Her zaman olduğun gibi Yine seni...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar 2', 'sevgiliye-mektuplar-2-yalcin-ergun-vvuu6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba, gonca gülüm...

Yunus balığının tebessümü gibi hâz veren

Ceylanın göz süzmesi kadar cezbeden

Ve bülbülün şakıması gibi eşsiz duygulardan, merhaba

Yine bir güne başladım sensiz ve yalnız

İçimdeki duyguların bile varlığından habersiz

Hatta her gün yolun karşısında bekleyen kızın

Bakışlarını bile umursamaksızın, çaresiz

Yine aynı süreç, yine aynı düşünce

Aldığım nefes, içtiğim su hep aynı

Oysa değişmeli artık bazı şeyler

Belki düşünceler, belki kavramlar yahut dünyalar

Senin için döktüğüm yaşlar, seni hissettiğim her an

Yazdığım her şiir ve söylediğim her söz

Helal olsun yoluna, öyle ki; 

Anandan emdiğin ak süt misali

Hiç bir şey anlamadım, doğduğumdan bu güne

Oysa ki ne çok şeyi bilirim sanıyordum

Hayatı, ölümü, insanı ve seni biliyorum diyorken

Kendimden bile haberim yokmuş meğerse

Nitekim böylece geçip gidiyor ömür, 

Sevginin mertçesi, yaşamın erkekçesi

En harbisi dostluğun, koyusu muhabbetin

Gönülden merhametin, şeytandan da zulmetin

Kediye nankör diyen insanoğlunun

Kardeşinden yediği kazığa ne demeli? 

Evladın babasına sarf ettiği sözleri

Sindirip de içine nasıl ki hazmetmeli? 

Hoşçakal...

15.09.1995', 'Merhaba, gonca gülüm... Yunus balığının tebessümü gibi hâz veren Ceylanın göz süzmesi kadar cezbeden Ve bülbülün şakıması gibi eşsiz duygula...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pardon', 'pardon-yalcin-ergun-urqoe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özür dilerim, binlerce kere...

Hakkım olmadan sana kızdığım için

Hayat düzenini bozduğum için

Her gün mahallende tozduğum için

Özür dilerim, kabul etmesen bile

Sana bunca şiiri yazdığım için

Ne sana ne kendime bir kez sormadan, 

Seni deliler gibi, sevdiğim için

Özür dilerim, istemesen de

Gece gündüz seni, düşlediğim için

Kalbime resmini işlediğim için

O gün konuşurken, titrediğim için

Özür dilerim, kimseye danışmadan

Duygularımı düşünmeden açtığım için

Herkese kem gözle baktığım için

Kendimi boşluğa attığım için

Özür dilerim, tüm özürlerden

Onları bu kadar tuttuğum için

Gururu onura kattığım için

Her an daha çıkmaza saptığım için

Özür dilerim, bütün dünyadan

Bin kere, yüz bin kere sövdüğüm için

Başımla toprağını dövdüğüm için

İçimde kenetlenen kördüğüm için

Özür dilerim, bir sebep aramadan

Herkesi kendim gibi sandığım için

Bütün yalanlara kandığım için

Yapayalnız ortada kaldığım için

Ve özür dilerim, özüroğluözür

Yemediğim meyvelerden, içmediğim pınarlardan

Kedilerden, köpeklerden ve diğer hayvanlardan

Dağlardan, taşlardan... Özür diliyorum, haddim olmadan...

25.09.1995', 'Özür dilerim, binlerce kere... Hakkım olmadan sana kızdığım için Hayat düzenini bozduğum için Her gün mahallende tozduğum için Özür dilerim,...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/pardon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Ki', 'ne-zaman-ki-yalcin-ergun-ysxg0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman ki, sağlam bir zemin bulsam

Ayaklarım bir türlü yere basmadı

Ne zaman ki, bir yere sağlamca bassam

Çürüyüp çökmeyen yeri kalmadı

Ne zaman ki, birini arkadaş sansam

Sırtıma bir bıçak haince girdi

Ne zaman ki, ben de şeytanlık yapsam

Tektük can dostlarıma zararlar geldi

Ne zaman ki, birini delice sevsem

Her zaman sonu hüsranla bitti

Ne zaman ki, hatayla birisi beni sevse

Ümidini yitirip meçhule gitti...

26.09.1995', 'Ne zaman ki, sağlam bir zemin bulsam Ayaklarım bir türlü yere basmadı Ne zaman ki, bir yere sağlamca bassam Çürüyüp çökmeyen yeri kalmadı Ne...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-zaman-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar 3', 'sevgiliye-mektuplar-3-yalcin-ergun-ssmm8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elveda ve merhabayı bir sunacağım sana

Ama üzülme yahut sevinme son mektubum diye

Seni rahat bırakacağımı sanma sakın

Ne rüyalarında, ne yaşantında, ne de başka bir zamanda

Sadece bitip tükenmek bilmeyen ızdırapların

Ve nihayetsiz arzuların eşiğinden dönüşü müjdeler bu karar

Öylesine. Yalnız kalmak istediğimi söylemeye cüreti

Herkese bir elveda demenin rahatlığını anlatır

Belki bir ay, iki yıl veya üç gün sonra

Cayacağım fikrimden ve sana yine yazacağım

Her zaman ki gibi olacak yine

Ben yazacağım, senin haberin bile olmayacak 

Ama diyorum ki; ya bu mektupları görürsen

Kızarsan bana, haddine mi dersen beni sevmek

Ya da sevinirsen kendi adına, gururlanırsan

Ben neymişim meğerse dersen, kibirle

Sırf ama sırf bu yüzden sen mektuplarımı

Ben de seni görmüyorum, istemsizce

Oysa ki, geçen bunca yılın ardından bir merhabaya, 

Ömrün yarısını vermeye hazır olduğumu bile bile

Canını sıktım galiba, yoksa ben mi sıkıldım

Bunu bilemiyorum, ama bildiğim bir şey var

Seni her zaman sevdim ve dahi seveceğim

Dedim ya yakandayım, lahzanın binde biri...

25.10.1995', 'Elveda ve merhabayı bir sunacağım sana Ama üzülme yahut sevinme son mektubum diye Seni rahat bırakacağımı sanma sakın Ne rüyalarında, ne yaş...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu', 'suclu-yalcin-ergun-ed7qa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçüktüm, küçücük. Babaannem vardı; 

Canımla bir bildiğim, nihayetsiz sevdiğim

Beni el bebek büyütmüş, dizinde uyutmuştu

Artık yok, uzun yıllar oldu rahmete erişeli

Sorardı arada bir, “ben ölünce ağlar mısın? ” diye

Bilmem derdim, ağlarım herhalde. Ağlar mıydım? 

Ağlamadım, belki ağlayamadığım belki de anlayamadığım için

Sadece koltuk döşemelerini yırtabildim, anlamsız bir sinirle

Fakat; bir defa kucaklayıp, canım annem

Yanağımı yanağına koyup da, babacığım diyemediğim

Ve bir kez olsun hatamı kabullenip, özrümü dilemediğim

Yıkılası bir gururla yaşıyorum. Nafile.

Suçluyum; Yalnızca daralınca, korkup da panikleyince aklıma gelen

Yalnızca o anlarda kendi kendimi kandırdığım

Allah’ım affet diye yalvardığım, tövbeler ettiğim için

Ve yine aynı tövbeleri peşinden bozduğum için

Suçluyorum kendimi, en ağır ithamlarla

Bir tarafımsa; savunuyor kendimi, umursamaz tavırla

Ama suçluyum, hem de en suçlu

Sevdiğime bile, bir defa seni seviyorum demediğim için

Oysa ki; ne kadar da çok istedim

Canım annem, canım babam deyip de, 

Sevgilime “seni çok ama çok seviyorum”

Demeyi. Olmadı, olmayacak, böyle devam ederse...

14.11.1995', 'Küçüktüm, küçücük. Babaannem vardı;  Canımla bir bildiğim, nihayetsiz sevdiğim Beni el bebek büyütmüş, dizinde uyutmuştu Artık yok, uzun yıl...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/suclu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Sözü', 'buyuk-sozu-yalcin-ergun-068dg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göz görmezse, gönül tahammül eder derler

Gel gör ki; gönül gözüm uyuşmaz bu deyişle

Böyle gelmiş bu dünya, böyle de gider derler

Ama varmaz bir yere, hiçbir şey bu gidişle

Önce söz gümüş ise, sükut altın diyerek

Hep sineye çekiyor, öylece susuyorum

Sonra, ağlamayana meme vermezler deyip; 

Olanca nefretimi bir anda kusuyorum

Ak akçe kara gün için, saklayalım diyerek

Ne var ne yok, hepsini yastık altına attım

Lâkin dünya malları dünyada kalır deyip; 

Günümü gün ederek, en son ceketi sattım...

04.12.1995', 'Göz görmezse, gönül tahammül eder derler Gel gör ki; gönül gözüm uyuşmaz bu deyişle Böyle gelmiş bu dünya, böyle de gider derler Ama varmaz ...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/buyuk-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '19 Nolu Sone', '19-nolu-sone-bertolt-brecht-ahsm9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızca benden kaçma yeter

Boş sözler de etsen duymak istiyorum seni

Sağır olsan gönlüm sözlerini ister

Dilsiz olsan gördüğünü.

Kör olsam, seni görmek isterdim

Sen yanımda yol gösterici oldun

Uzun yolun daha yarısı bile aşılmadı

Bir düşün içinde yaşadığımız karanlığı

''Bırak beni yaralıyım'' desen de boşa

Görevden dönülmez, yalnızca ertelenir

Başka bir yerde değil, yalnızca burda

Bilirsin özgür değildir gereksinilen kimse

Gönlüm her şeyden önce seni ister

Biz de diyebilirim, ben yerine.', 'Yalnızca benden kaçma yeter Boş sözler de etsen duymak istiyorum seni Sağır olsan gönlüm sözlerini ister Dilsiz olsan gördüğünü. Kör olsam, ...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/19-nolu-sone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anatomi', 'anatomi-yalcin-ergun-4i13b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir inadım kaldı eskiyip değişmeyen, 

Bir de kahrolası gururum.

Kelepir bir hayatla, ucube bir dünya arasında

Gidip gelen eski bir taka misali yaşarım, yaşamaksa

Zaten karanlık geceler misâli bahtım

Ve loş odalar gibi şansım var diye diye, düşmedim mi bu hallere? 

Düştüm ya! ... Hem de tepe taklak, kıç üstü

Öyleyse? Hâla nedir bu kibir, ne bu tafra ve bu naz? 

Kime anlatıyorum ki bunları? Kendime mi? Hayır, ben zaten biliyorum

Size mi? Ne mümkün, zaten size ne ki benden...

Bazen kendimi düşler ülkesinde yaşayan bir figüran

Veya beyin tokluğuna çalışan, bir gariban sanmam niye? 

Sahi ne anlatacaktım da unuttum ki? Soru işaretleriyle dolu

Onlarca satır... Ne diyor, ya da ne anlatmaya çalışıyor? 

Çok ama çok şey var gizemlerin altında yatan

Aslına gelirsek anlatılan, kocaman bir boşluk, tıpatıp zihnim gibi

Ne eski hikayeler, ne süslü kinayeler anlatamaz derdimi

Zaten derdim dert değil, yalnız gönül avuntusudur.

Yaptığım hataları, yalanlarla boyayıp

Kendimi kandırmamın nihai sonucudur

Uzunca zaman olmuş, bir şiir yazmayalı

İyi mi kötü mü bilmem, ama bitiyor işte

Belki aşkımın, belki de kendimin anatomisi

Yazdıklarım, bildiklerim, hissettiklerim. Belki...

14.05.1996', 'Bir inadım kaldı eskiyip değişmeyen,  Bir de kahrolası gururum. Kelepir bir hayatla, ucube bir dünya arasında Gidip gelen eski bir taka misa...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anatomi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matematik', 'matematik-yalcin-ergun-isgiz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölü toprağı serpilmiş gibi üstüme, 

Öylesine bitkin, öylesi de yorgunum

Sanki tüm sıkıntılar dolmuş gibi içime, 

Öylesine dalgın, öylesi de durgunum

Almış kendi başımı, meçhule gidiyorken

Düşünmem, düşünemem... Nelere mâl olacak

Kahrolmak ne kelime, kendime zulm ederken

Kim bilir ki ardımda, nice güller solacak

Oysa ki bu safsata, veya bitmez kargaşa

Bir silkinsem bitecek, yüreğimden göçecek

Fakat beynimin içindeki çözülmeyen karmaşa

Ya ölümü ya da; öldürmeyi seçecek

Yapıp da pişman olduğum onlarca işin, 

Ardından en fazla üç-beş gün ah! çekmişim

Ama yapamayıp da yandığım birkaç şeyin

Peşinden yıllar yılı, derde keder ekmişim

Kimi gün coşup, taşıp daldığım hülyaları

Azat buzat diyerek, gökyüzüne salmışım

Bazen de titreyerek gördüğüm kabusları

Bir kalemde çizip, sessizliğe dalmışım

Her ne kadar iyilik yapmayı istesem de, 

Arada bir ben de kör şeytana uymuşum

Hataların ardından özür dilemesem de, 

Vicdan muhasebesinde daim hicap duymuşum...

18.07.1996', 'Ölü toprağı serpilmiş gibi üstüme,  Öylesine bitkin, öylesi de yorgunum Sanki tüm sıkıntılar dolmuş gibi içime,  Öylesine dalgın, öylesi de ...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/matematik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olacağa Bakın', 'olacaga-bakin-yalcin-ergun-e8n43', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir dürtü, bir dokunuş. Belki de uyandıracak beni 

Belki anlayacağım her şeyi, bir anda olup bitenleri

Ve duyacağım. Duyulmaması gereken şeyleri

Üzüleceğim, üzülmenin kârını ömrümle ödeyerek

Fakat hiç yılmadan mücadelemde, yine yükleneceğim

Birer birer dertlerin üzerine gideceğim, 

Diş ağrım bile vazgeçiremeyecek beni bu işten

Buldukça budakları, açacağım gözümü

Yine yaşayacağım her şeye rağmen, 

Yine taşıyacağım, aşkı içimde ben

Yaklaşacağım insanlara, tıpkı dünkü gibi

Onlar bana nasıl yaklaştıysa, sinsi ve...

Ve sarhoş olacağım, mutluluğun verdiği hoşlukla

Gülüp eğlenip çatlatacağım, çekemeyenleri

Kıskandıracağım dostları! Ve bil cümlesini

Sonra yine dalacağım eski günlerime, karanlık sularıma

Ama yapacağım göreceksin be kendim

Sen istemesen de, ben yine yapacağım

Sevineceğim hallerine, seninkine dahi

Sonra da ağlayacağım, göz yaşlarımla boğulurcasına

Bir gün kıvranacağım acı ile, onu da tınlamayacağım

Çünkü ölüm, acı ile ecelden ibaret değil sadece

Belki bir kurtuluş, belki de kaçış sonsuzluğun tenine

Ve tepelerden bakıp bakıp güleceğim, tüm olup bitenlere...

14.09.1996', 'Bir dürtü, bir dokunuş. Belki de uyandıracak beni  Belki anlayacağım her şeyi, bir anda olup bitenleri Ve duyacağım. Duyulmaması gereken şey...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olacaga-bakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatır İçin', 'hatir-i-cin-yalcin-ergun-fcux8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kavurucu sıcakta bir serinlik, akıp gider

Yanağımdan dudağıma doğru, usulca

Bazen de bir rehavet, bunaltır yakar içimi

Kara kışın ortasında, buz tutmuşken kulağım

Sade ve sakin, ama benim olan bir hayat bu

Kim ne derse desin, fark etmez ki

Yaşayan da benim, yaşanan da

Numunelik bana mahsus değildir, artık anladım

Sahte gülüşlerimin altında ezilen bir yorgun yürek, 

Yorgun yüreğimin içindeyse, mahzun bir sevda

Yatar yıllardır süren esaret hayatını

Prangasız, zincirsiz, hücresiz ve yapyalnız

Şeytanlar dolaşıp dururken başucumda

Sallanır şakul gibi argın bitik yüreğim

Tutunacak bir dostu hayal edip dururken

Sahipsizlik sarar, baştan aşağı beni

Sonra beliren bir hayal, baştan sona sen

Yakılıp, yıkılıp toz olan umutlarımla birlikte

Sevincinle, hüznünle gelirsin bana

Rüyayla karışık, umarsız ve tutarsız

Ama yaşamın rengini sezebiliyorum her şeye rağmen

Duyabiliyorum, kuşların sesini ve kokusunu humusun

Ve en önemlisi; Gülebiliyorum arsızca, korkusuzca

Sevebiliyorum, sevdiğimi, sevebildiğimce

Bu yüzden ki, yaşıyorum tüm güzellikleri

İstesem de, istemesem de yaşamayı

Bir kaç umut ya da insan adına

Belki bir bayrak, bir avuç toprak uğruna...

05.10.1996', 'Kavurucu sıcakta bir serinlik, akıp gider Yanağımdan dudağıma doğru, usulca Bazen de bir rehavet, bunaltır yakar içimi Kara kışın ortasında,...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hatir-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Defa', 'i-lk-defa-aykut-yakup-gultekin-3ct6t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazıyorum ilk defa kendime, 

İlk defa kendime bir dünya kuruyorum, 

Ve ilk defa yazarken ağlamıyorum, 

Kaçmıyorum artık kendimden, 

Geceleri gözlerimi rahat kapatıyorum, 

Ve bir şiir yazıyorum ilk defa, 

İlk defa susuyorum! ...

Bir şiir yazıyorum ilk defa, 

İlk defa içimde bir savaş yok, 

İlk defa, düşmüyorum sanki sonsuz bir karanlığa, 

İçimde ‘ben’ suskun, 

Öldü sanıyorum oysa, 

Ve ilk defa, 

Ve ilk defa yazarken gülüyorum! ...

Bir şiir yazıyorum ilk defa, 

Yüreğimdeki yaramdan kan sızmıyor, 

Anlamsız gözlerle bakıyorum hayata, 

Hayat bana anlamsız gözlerle bakıyor, 

Yüreğimi mi yitirdim diyorum? 

Ve ilk defa sensiz, 

Ve ilk defa yüreksiz bir şiir yazıyorum...', 'Bir şiir yazıyorum ilk defa kendime,  İlk defa kendime bir dünya kuruyorum,  Ve ilk defa yazarken ağlamıyorum,  Kaçmıyorum artık kendimden, ...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ilk-defa-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıyordum', 'kaciyordum-aykut-yakup-gultekin-cmx9l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kendimden kaçışım ilk değil, 

İlk değil böyle çaresizliğim, 

Bin kere yemin ettim, 

Bin kere geri döndüm, 

Bitti dedim kendime, 

Yaşanmadan hayallerim, 

Oysa bitiremedim, 

Bu kendimden kaçışım ilk değildi, 

İlk değildi pişmanlığım, 

İlk değildi yitirdiğim, 

İlk değildi kaybettiğim, 

Oysa çaresizim, 

Kaçıyordum doludizgin kendimden, 

Bilsin istemiyordum kimsesizliğimi, 

Kendim bile, 

Dinletemezdim ki benliğime, 

Anlatamazdım ki yüreğime, 

Oysa böyle olsun istemedim, 

Böyle bitmesin sevgim, 

Ve yüreğimde değerin, 

Ama yitirdim...

Duygularım kaybetti tüm gücünü, 

Ve mantığım haykırmadaydı, 

Bitmişliğin karanlığını, 

Ve karanlığın ızdırabını, 

Önce seni kaybetmiştim ya! 

Sonrada yüreğimi...

Issız uçurumlarda...', 'Bu kendimden kaçışım ilk değil,  İlk değil böyle çaresizliğim,  Bin kere yemin ettim,  Bin kere geri döndüm,  Bitti dedim kendime,  Yaşanmad...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kaciyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otogar', 'otogar-aykut-yakup-gultekin-njlwr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bağırıyor içimde duygular, 

Ve otogarda çocuklar, 

Boyayalım abiler, ablalar, 

Parlasın ayakkabılar, 

Haydi binin artık yolcular, 

Yolculuk var, 

Geçilsin asfaltlar, 

Çizgiler, lambalar, 

Yansın farlar, 

Açılsın karanlıklar, 

Hayırlı yolculuklar, 

Söndü lambalar, 

Galiba bir film var, 

Dönüyorum, camın dışında tarlalar, 

Ve camda yansılar, 

Yansılarda adamlar....

Ve uyuyorum hülyalar, 

Yarım kalıyorlar, 

Kornalar çalıyorlar, 

Evet yine otogar, 

Geçmiş olsun yolcular, 

Geçmiş olsun...', 'Bağırıyor içimde duygular,  Ve otogarda çocuklar,  Boyayalım abiler, ablalar,  Parlasın ayakkabılar,  Haydi binin artık yolcular,  Yolculuk ...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/otogar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oysa', 'oysa-aykut-yakup-gultekin-yyeng', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oysa sen yoktun yanımda, 

Gökyüzü kızardı bana, 

Dağlar bile alay ederdi alaborasıyla, 

Oturup ağladığımda, 

Aşkımıza.....

Göz yaşlarım parlardı ay ışığında, 

Yıldızlara meydan okurdu, 

Yumruklarım olanca hıncını dökerdi duvarlara, 

Ve kalemim anlatırdı, 

Yalnızlığımı, 

İnsanlara.......', 'Oysa sen yoktun yanımda,  Gökyüzü kızardı bana,  Dağlar bile alay ederdi alaborasıyla,  Oturup ağladığımda,  Aşkımıza..... Göz yaşlarım parl...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oysa-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Bedeli', 'sevginin-bedeli-aykut-yakup-gultekin-ij6wt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çaresizlik nedir bilir misin? 

Bilir misin kimsesizliği? 

Hani oturur ağlarsın bir köşede, 

Hani şiirler yazarsın kimsesizliğine, 

Ve açılan her kapı sesinde, 

Bir umut filizlenir yüreğinde, 

Bir sevgi, 

Ve hayal kırıklıklarıyla biter tüm masalların sonu, 

Olmasa da göz yaşları yağmurların, 

Olmasa da baharların, 

Tüm mevsimler yar olur sana, 

Tüm yollar şiirlere çıkıyordur oysa, 

Güneş başka bir şiiri kalıplandırır yüreğinde, 

Kar başka bir şiiri, 

Tüm mevsimler şiirlere çıkar unutma, 

Unutma tüm sevgiler gönülde gizli, 

Ve gözyaşlarıdır süzülen yanaklarda, 

Gözyaşlarıdır sevginin bedeli....', 'Çaresizlik nedir bilir misin?  Bilir misin kimsesizliği?  Hani oturur ağlarsın bir köşede,  Hani şiirler yazarsın kimsesizliğine,  Ve açılan...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevginin-bedeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemedim', 'soyleyemedim-aykut-yakup-gultekin-7c7za', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sokaklarda esiyor soğuk bir rüzgar, 

Özlemimi arttırıyor siyah gözlerin, 

Gecikiyor hayalimdeki o ılık bahar, 

Gözlerim arıyor hala, nerdesin? 

Yalana gömüldü karanlık dünyam, 

Lalelere zambaklara gözyaşı düştü, 

Neden? Nasıl? Diye bir kere sorsam, 

İçimde yüreğim kendime küstü.

Ellerimde umudum, gözümde yaş var, 

Yitirilmiş hayale açık kucağım, 

Kayboldu özlediğim o ılık bahar, 

Belki de bir tufan gibi patlayacağım.

Eskiye hasretle bakıyor gözüm, 

Mazi apayrı bir dünya içimde, 

Görünen bedenimi toprağa gömün, 

Ruhum bedenime isyan içinde.

Ey kaybolan umut, yiten rüyalar, 

Dönün ve bakın bir kez geriye, 

Nerde kaldı nerde o hatıralar, 

Dönüverdik çaresiz bir ölüye.

İsyan yüreğimi sarmış kaplamış, 

Mateme boyanmış bütün mavera, 

Ne varsa kalanlardan hep parçalanmış, 

Yüreklerimizi sarmış bir derin yara.

Tuzaklara düşmemek istedikçe biz, 

Ufkumuzu kaplamış kızıl şeytanlar, 

Ve en nihayetinde yitip gitmişiz, 

Anlamamış ardımızda kalanlar.

Rüyalarda kalmış büyük sevgimiz, 

Nerede yanlışlar nerede hata? 

Tüm bunların çözümleri bizde demişiz, 

Ve dönmüşüz istemeden tekrar hayata.

 Anlaşılmadan bitmiş bütün ömrümüz, 

Meltemde savrulan yaprak olmuşuz, 

Ve soluvermiş bir gün gülümüz, 

Gülümüzle beraber bizde solmuşuz...', 'Sokaklarda esiyor soğuk bir rüzgar,  Özlemimi arttırıyor siyah gözlerin,  Gecikiyor hayalimdeki o ılık bahar,  Gözlerim arıyor hala, nerdesi...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/soyleyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözüm Yok', 'sozum-yok-aykut-yakup-gultekin-p7spy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söyleyecek sözüm yok, 

“Seni seviyorum”dan başka, 

Zaten anlayan da yok, 

Yalnızım bu hayatta.

“Şimdi galiba sende, 

Gidiyorsun ellere, 

Beni bırakıp böyle, 

Ne olursun dur gitme! ”

Diyemem biliyorsun, 

Ve bende biliyorum, 

Bu satırları asla okumayacaksın, 

Okusan da anlamayacaksın.......', 'Söyleyecek sözüm yok,  “Seni seviyorum”dan başka,  Zaten anlayan da yok,  Yalnızım bu hayatta. “Şimdi galiba sende,  Gidiyorsun ellere,  Ben...', ARRAY['Türk Edebiyatı','Şiir','Aykut Yakup Gültekin']::text[], 8.5, '{"poet":"Aykut Yakup Gültekin","poet_slug":"aykut-yakup-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sozum-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Kız', 'guzel-kiz-gokhan-oktem-pcjkb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel kız çok güzelsin

Güzel kelimesi kadar

Her gün batımı sessizliği

Her gurup sarhoşluğu

Her tan ağarışı

Karışır toprak kokusuna

Karışır senin kokuna...

Can verir cemreye 

Doğanın her taze baharda uyanışına

Can verir güzelliğin her canda bir can arayışına...

Güzel kız çok güzelsin

Sevda kelimesi kadar

Her sevdada atan bir yüreksin

Her yürekte saklı bir sevda...

Körpe çığlıklar kadar doğal

Hazin iç çekişler kadar içli

Hüznün ıslaklığı kadar nemli

Ve göz yaşları kadar masumsun

O göz yaşlarında kaybolan hatıralarda...



Güzel kız çok güzelsin

Güzelsin her aşka pusu akşamlarda

Sahipsiz duygularımda çaresiz 

Ararım sende saklı bir parça

Ufka kilit gözlerle

Düşerim kendi yalnızlığıma

Tatmak için bir tatlı sıcaklık 

O can alıcı bakışlarında 

Sende ararım sessizliğimi

Serzenişlerimin suskunluğunda 

Sakın ha, sakın dökme göz yaşlarını

Göz yaşların içime dökülür sonra

Güzel kız çok güzelsin

Benim olmadığın karar...

					

(İstanbul,09,04,2001)', 'Güzel kız çok güzelsin Güzel kelimesi kadar Her gün batımı sessizliği Her gurup sarhoşluğu Her tan ağarışı Karışır toprak kokusuna Karışır s...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/guzel-kiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alamadı Aklımdan Geceler Seni', 'alamadi-aklimdan-geceler-seni-golge-gezgini-zp4bw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alamadı aklımdan geceler seni 

Ne kapanan perdeler nede kahpe lambalar

Gitmedi gözümden gözlerin 

İzuvarların çizdiği yol gibi 

Çiziliyor yüzün karanlıkta

Mauzer yatağında gibi patlıyor şafaklar gözümde

Koca dağların ekremli duruşları gibi 

Duruyor gözlerimde gözlerin, 

Alamadı aklımdan geceler seni..

Dilimde heceleri isminin, bir bir içimden söylerim 

Simitçi bir çocuk gibi utangaç ama gönülden 

Unutamam ekmek gibi nan gibi seni

Yine akşam olur ve yine lambalar yanar 

Yüzün yine aynada sanki 

Gözlerin hep aynı yerde

Gözlerimde.

Mehmetçik gibi siperde hasret sanki

Vuslatı düşlerim zafer anında bile

Miğferimin içinde aklım 

Aklımın içinde sen 

Ve karanlık yine 

Yine bir gece 

Ve aynı hikaye 

Balkon, düşünceler, 

Gözlerin, gülüşün, 

Hasret ve uykusuzluk.

Vuslatı bekler yine yürek

Alamadı aklımdan geceler seni.

Dilimde heceleri isminin utana sıkıla söylerim.

Gözlerin yine aynı yerde gözlerimde 

Utana sıkıla bakarım kendime..', 'Alamadı aklımdan geceler seni  Ne kapanan perdeler nede kahpe lambalar Gitmedi gözümden gözlerin  İzuvarların çizdiği yol gibi  Çiziliyor yü...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/alamadi-aklimdan-geceler-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anmama Sebep', 'seni-anmama-sebep-gokhan-oktem-2lnnr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi zaman şiire çalar gözlerin

Bir gün batımı kadar güzel ve eşsiz

Ve ay ışığı kadar sessiz...

Seni anmama sebep 

Zamansız ve sebepsiz aklımı çalan

Sorgularıma asılı kalan

Suallerimdeki muamma...

Seni anmama sebep

Sen değilsin aslında...

Bir sensizlik acı veriyor bana

Bir de üstüme çöken gölgen

Yırtıverse diyorum söyle bir bakışıyla

Ufkuma bir kabus gibi çöken karanlıkları

Kimi zaman şiire çalan 

Bir gün batımı kadar güzel ve eşsiz

Ve ay ışığı kadar sessiz

O ay ışığı saçan gözlerin...

Seni bana bağlayan aşk değil artık

Beni senden ayıran şey neyse o... 

21.12.1998 - İstanbul', 'Kimi zaman şiire çalar gözlerin Bir gün batımı kadar güzel ve eşsiz Ve ay ışığı kadar sessiz... Seni anmama sebep  Zamansız ve sebepsiz aklı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-anmama-sebep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ben Yarattım', 'seni-ben-yarattim-gokhan-oktem-vgww1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana hep söylemek isteyip de söyleyemediğim

Kara sevdalara tutulmuşken içimde gizlediğim 

Bir saklı sevda suskunluğunda içli içli

İçime akıttığım göz yaşlarımsın

Sen 

Sen olduğun kadar 

Bende saklısın

Bir içim sigara dumanında içime çektiğim 

Ruhumda titreyen bir hazin ezgisin

Sana sen olduğun için değil bu sevgim

İçimde sevmeye duyduğum özlemsin

Sen sen olduğun kadar 

Bende saklısın

Üstüne doğduğum bu toprak, bu coğrafya, bu kültür

Bu hayat ve bu ölüm

Yaşatır yüz yılların  gizini, 

Tükenmişliğe isyan bayrağını çeken 

Her yürekte bir haykırış dizesi

Saklı sevdalarda yüklüdür, 

Yitik sevdaların gizemi.... 

Sen sen olduğun kadar

Bende saklısın

Seni ben yarattım

Benden ibaretsin

Her seslenişte yakar, 

İçime akar gözlerin

Buğulu bakışlarında gizli, 

Söylenmemiş sözlerim

Sanma ki sen korkularımdan ibaretsin

Bütün albeninle sen

İçimi akıttığım şiirlerimden bir parçasın

Parçalarımdan bir bütün

Özlemlerimde saklı hayallerin

Sen hayallerimle ödediğim bir bedelsin

Seni ben yarattım

Benden ibaretsin, 

Yaşanmamışlıklarımı  yüklerim sana, 

Yitik aşklarımı...

Terkedilmişliklerimde sus pus  sevda mırıltılarım, 

Susuşlarımda gizlenen bir nedensin 

Bilmezsin, bilemezsin, 

Sen sen olmaktan öte bensin

Sen benim ulaşılmazımsın aslında

Susma güzelliğin kaybolur sonra

Erken gelen bir yaz sabahında 

Odamda, 

Loş bir ışıkla aydınlanan dört duvar arasında

Savaşırken kendi yalnızlığımla

Seni ben yarattım uzak umutlarımda

Doğarken ilk çığlığı attığım günden beri

Beslerim yüreğimde bu körpe sevgiyi, 

İsterim hiç büyümeyesin...

Ama bilesin, 

Seni ben yarattım

Benden ibaretsin... 		

(İstanbul,21,04,2001)', 'Sana hep söylemek isteyip de söyleyemediğim Kara sevdalara tutulmuşken içimde gizlediğim  Bir saklı sevda suskunluğunda içli içli İçime akıt...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/seni-ben-yarattim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sus', 'sen-sus-gokhan-oktem-sreb9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen sus ben sana şarkılar söyleyeceğim 

Dağlardan, 

Uzak diyarların seslerini üfleyeceğim 

Parmak aralarından

Sen sus ben sana titrek bakışlar getireceğim 

Kara kışların ardından

Hüzne gebe dalışlarda kaybolmuş, 						                 Ürkek, 

Gizli dokunuşlarımla ıslanan yüreğinde

Hercai bir sevgi tüttüreceğim

Sen sus ben sana daha neler getireceğim...

(İstanbul,17,07,1999)', 'Sen sus ben sana şarkılar söyleyeceğim  Dağlardan,  Uzak diyarların seslerini üfleyeceğim  Parmak aralarından Sen sus ben sana titrek bakışl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-sus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binyılların Türküsüdür Bu Gülüm', 'binyillarin-turkusudur-bu-gulum-golge-gezgini-hy8xi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bin yılların türküsüdür bu içimdeki

İçimdeki bir aş, sevda, bir aşktır 

Toprağa atsam kardelen olur fışkırır dağlarda

Bir merdiven misali tırmanmaya çalışıyorum mahpusum 

Kadrimi görürüm duvarda ki yürüyüşlerimde

İsmi belirsiz bir yolcuyum.

İsyanım sabahlara, tan yerini 

Gökten ayıran, kızlııarı mavi yapan 

Güneşe..

Binyılların türküsü bu 

Acı acı esnemekte içimde 

Kadrini bilmez duvarlarda yürümekteyim 

İsmi belirsiz bir yolcu gibi

Yalan dünyaya arşın arşın sevda ektim, 

Görmedim huzur mahpustan öte bir garip gardiyan 

Başımda, çıkmıyor aklımdan yalanın aziz türküsü

Binyılların türküsündeyim ölüme denk yaşamdan öte

Dilimin ucunda inceden bir sızı

Kulağımda çingene mastikası

Bir saçımı yolarım isyandan bir misvak ısırırım

KalmdI aklım kardelen filizlerinde 

Bir kış bekler benim gibi pusuda

Ölüm kokar sokaklar sanki bir lambanın altında mahpus dünya

Ne kader yalanı bu nede zindan bir şiir

Bu binyılların türküsüdür gülüm ağlamaklı

Ana kucağından kopan gurbetlerin en tatlı türküsü

Sıcak aşın buharından aynada kalan 

Ufacık buhuların süzülüşüdür bu yavaş yavaş 

Bu ateşli ve acılı bir türküdür gülüm bin yıllardır.

Bu bir sevdadır gülüm, çam ağacının yanında ki ufacık kardelenin 

Kocaman kartaneleri ile savaşıdır gülüm.

Binyılların türküsüdür bu gülüm.', 'Bin yılların türküsüdür bu içimdeki İçimdeki bir aş, sevda, bir aşktır  Toprağa atsam kardelen olur fışkırır dağlarda Bir merdiven misali tı...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/binyillarin-turkusudur-bu-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlusun', 'suclusun-gokhan-oktem-gc02s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kara kaşlarından sen suçlusun

Suçlusun maviş gözlerinden sen

Sıcak bakışların deldi bağrımı

Sığmaz oldu yüreğim kabına

Yüreğim bendini yıkan bir sel oldu

Yüreğim yürek oldu.....

(İskenderun,10,07,1997)', 'Kara kaşlarından sen suçlusun Suçlusun maviş gözlerinden sen Sıcak bakışların deldi bağrımı Sığmaz oldu yüreğim kabına Yüreğim bendini yıkan...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/suclusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne İçin Ölmek Gerek', 'ne-i-cin-olmek-gerek-golge-gezgini-nda3u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağlarım pınarlara dolanmış, 

Aklı çeşmelerde suların, 

Sakin dünyanın kurbağaları ve bir sinek, 

Doğa hayat yaşam, 

Ne için ölmek gerek?', 'Dağlarım pınarlara dolanmış,  Aklı çeşmelerde suların,  Sakin dünyanın kurbağaları ve bir sinek,  Doğa hayat yaşam,  Ne için ölmek gerek?...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ne-icin-olmek-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Arayış Hikayesi', 'bir-arayis-hikayesi-gokhan-oktem-8ae7c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soluğum tükeniyor

Zifiri karanlıklar akıyor yüreğime...

Yokluğun; bıçak yarası

Yokluğun; bahtım karası

Yokluğun sonsuzluklarda sonum

En ateşli başlangıçlarda külüm

Umut deryasında batan gemim

Sorgularda suskunluklarım

Belli belirsiz dalışlarım

Amaçsız yürüyüşlerim

Neden, ne zaman, nerede olduğunu hiç bilmediğim

Düşünüşlerim

	Düşünüşlerim

		Düşünüşlerim...

Yokluğun; alışamamışlıklarım, 

Alışkanlıklarımdan kopamayışlarım, 

Unuttuklarımdaki hatırlayışlarım...

Yokluğun; ardı arkası kesilmez sapışlarım

Arayışlarım

Kaçışlarım

Zifiri karanlıklar ortasında 

Sönen bir mum gibi kalışlarım....

Yokluğun; kaş çatışlarım, 

Yüz asışlarım

Soğuk bir tene dokunuşlarım

Bir bahar sabahı apansız yaprak döküşlerim

Deryalar ortasında susuz kalışlarım

Güneşe karşı üşüyüşlerim...

Yokluğun; azalışlarım

Menzile varamayışlarım

Uykuya dalamamışlarım

Karanlıklar ortasında nefes nefese kalışlarım...

Yokluğun; yalnız kalamayışlarım

İçime bakamayışlarım

Kendimi bulamayışlarım...

Yokluğun; yok oluşlarım...

Soluğum tükeniyor,  	

			Belli...

Zaman akıp gidiyor, 

			Çaresiz...

Bir ayrılık şarkısında bulmuştum seni

Bir hüzün sabahı aldın başını gittin! ...

	Sorgusuz sualsizliklerim

	Ümitli ümitsizliklerim

	En hoyrat şafaklarda bekleyişlerim oldun...

	En umutsuz gecelerin ardından, 

	Hep bir cılız sesleniş arayıp durdum

							Uzaklardan...

	Bir sevda mırıltısı

	Bir belli belirsiz çığlık çarpar diye kulaklarıma, 

	Ne pusular kurdum hain geceye...

Yendi karanlık korkumu nihayet yürekten sevişlerim...

Yoğurdu gecelerimi yenilişlerim ve yenişlerim

Lakin, işte o zaman başladı soruşlarımda 

                                                         Cevap arayışlarım! 

Ve neden..., niçin...lerle sürdü sorgulayışlarım...

Dedim! ... Yarınlara kalan umutlarımızsa sadece

Ve yarınlar en amansız umut tacirleriyse eğer

Ne kıymet-i harbiyesi kalır

Bu ardı arkası kesilmez, 

Bu dipsiz 

Bu amansız, 

Bu hain zifiri karanlıklarda bekleyişlerin? ...

Soluğum tükeniyor...

Zifiri karanlıklar akıyor yüreğime

Derken! ...

Yırtıyor karanlıkları bir ses: 

		İçimden

			En derinlerden...

Ve başlıyor bitmez titreyişlerim

Sarsıyor ruhumu bilmeyişlerimdeki bilişlerim

Ve yeniden başlıyor soluk alışlarımdaki kalp atışlarım

Ve açıyor yüreğimin penceresini

En mutlak tükenmişliklerimdeki yeniden doğuşlarım

Ve sarıyor ruhumu heyecanıyla

Yeni bir hayata tap taze başlayışlarım...

	Ve artık anlıyorum ki, 

		 Yokluğunla başlamış meğer

Benim varoluşlarım...

(İstanbul,05,06,1998)', 'Soluğum tükeniyor Zifiri karanlıklar akıyor yüreğime... Yokluğun; bıçak yarası Yokluğun; bahtım karası Yokluğun sonsuzluklarda sonum En ateş...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/bir-arayis-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizlemezsin', 'bizlemezsin-gokhan-oktem-md0b3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerime değmesin sakın, iz kalır silemezsin

Bir kılıç yarasında yüreğim kanar, hükmünü süremezsin...

Tutkulu aşkım hicran ateşiyle  yanar, söndüremezsin

Nasıl hasretim sana bir bilsen,  bilemezsin...

(İstanbul,01,11,2000)', 'Gözlerin gözlerime değmesin sakın, iz kalır silemezsin Bir kılıç yarasında yüreğim kanar, hükmünü süremezsin... Tutkulu aşkım hicran ateşiyl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bizlemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeli mi?', 'olmeli-mi-golge-gezgini-e97vc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evet yine ben neden şaşırdın? 

Ezilen ben unutulan ben dağların yarılası tutmuş içimde

Kan ter içinde bir şafak

Unutulan türküler ezgiler gibimi hayatım 

Sendemi unutacaktın 

Hani zaferimiz hani sigaranın ilk dumanı için kavgamız

Nerde aslan yürekli yarim 

Yinemi ben yıkıldım allahım

Mazlum ahlar içindemi ömrüm sürecek

Duvardaki kalbin üstünümü karalasam

Ölsemmi acaba kahrettiğim hayatımda

Yanmalımı nar gibi yoksa bir simitçi fırınında

Yine isyanlarlamı yaşamalı yoksa

Zambaklarla dolu bir tarlada gül yada lale mi aramalı

Ölmelimi acınası dünyada yoksa

Kanatsız atlamalımı bir dağdan 

Kucaklarına gökyüzünün yada bulutların

Delmelimi hiç aklımdan çıkmayan düşündüklerimi 

Yok etmek için beynimi

Bir kurşundan mı medet ummalı yoksa

Yada küçücük bir fincanda çaymı içmeli bir bahar sabahı

Minicik çocukların seslerinimi dinlemeli herhangi bir parkta

Yarimin yüzünümü çizmeli buhulu bir aynada 

Mutlu olmak için bahanelermi aramalı

Bağırıp çağırmadan narinmi olmalı insanlara

En iyisi uyumalı

Ne ölüm güldürür beni

Nede gülüm öldürür beni

Kahpe yaşamalı sanırım 

Ardına bakmadan gamsız olmalı

Yedi tepeden yedi gül koparmalı

Her birinin yapraklarını yolmalı

Dikenlerini koparmalı

Ve yine kahretmeli hayata ve aşka

Kahretmeli insanlara sevdaya

Ölmeli ölmeli....', 'Evet yine ben neden şaşırdın?  Ezilen ben unutulan ben dağların yarılası tutmuş içimde Kan ter içinde bir şafak Unutulan türküler ezgiler gi...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/olmeli-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey', 'hey-sair-mahcubat-ejgrv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'özlemini hatirimdan çıkarmadığım hey

düşünüyorum bir bakışına muhtaç kalmışım

gözkapaklarını yumup açışına susamışım

kipriğinin bir telini dahi unutmadığım hey

yürürken endamlar süzülenim hey

ellerinde bulduğum merhamete aşığım

senle her attığım adıma maşuğum

zerafetini hafızama kazıdığım hey

kaşlarının siyahını sevdiğim hey

gönlüme bıraktığın ateş ile kavruldum

saçlarının telleri ucunda sevdana savruldum

siyahı beyazına yakışanım hey

gönül hanemin sultanı hey

güzelliğinin hükmüne ram olmuşum

canın içinde hissettiğin cana dem olmuşum

canan olup başımı döndürenim hey

kelamının tadına doyamadığım hey

muhabbetle yönelen gönlüne meyletmişim

sen konuşurken her halini sevmişim

sukut cevherini altın eyleyenim hey

ayrılığın en zorunu yaşadığım hey

vuslatına giden yola bakakalmışım

sana kavuşmayı dualarıma katmışım

matem ilan ettiğim yokluğunla durduğum hey...', 'özlemini hatirimdan çıkarmadığım hey düşünüyorum bir bakışına muhtaç kalmışım gözkapaklarını yumup açışına susamışım kipriğinin bir telini d...', ARRAY['Türk Edebiyatı','Şiir','Şair Mahcubat']::text[], 8.5, '{"poet":"Şair Mahcubat","poet_slug":"sair-mahcubat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hey-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben, Zaman ve Bir Yitik Sevda', 'ben-zaman-ve-bir-yitik-sevda-gokhan-oktem-d954q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nice bekleyişleri damıtır sabrın süzgeci   

Sabra bulanır içli iç çekişlerin merhameti

Ben yine sevdadan yana tavrımı koydum

Sensizliklerimle suçladım kendimi

Yüreğime düşen kor bir kuyruklu yıldızdı sevdan

Gözlerimden akıyor saman yolları

Buğulu gaz bulutlarında geziniyorum, 

Saman yolunun peşine takılmış serseri meteorlar gibi

“Beni yine sevda yerimden vurdu zaman”

Zaman boşluğunda zamansız kaldım

Ki zamansızlığa açılırdı bütün yollarım

Ben sevdayı sensizlikte tanıdım

Yüreğe söz geçirmeyi kolay sanırdım

Sevdayı inkar edince, tutarsız

Sevda ne demekmiş, anladım

Beni en köhne yerimden vurdu zaman

El değmemiş sevdalara açılırdı yüreğim

Ve bir yalnız İstanbul akşamıydı terkedilmişliğim

Terkedilmişliğimde sakladım korkularımı

Ben ki sevdaya uzak yaşadım

Beni sevda kurşunuyla vurdu zaman

Ki zamansızlığa açılırdı bütün yollarım

Sana el değmemiş bir sevdanın ilk dokunuşlarını gönderiyorum

Tükenmişliğimden arta kalan fersiz parmaklarımla

Gezinir durur kelemim kağıdın kirli coğrafyasında 

Her susuş bir çığlıktır.

Her çığlık bir okyanus...

Aslolan sessizliktir der bilge, 

Ses ise, titreşimlerin onu bölmesidir...

Bütün gizlerimi aralıyorum sana

Tanıman mühim değil

Bilmen de öyle

Ben kendimce sahipsiz günah çıkarıyorum...



Beni umuda erken seviye geç kalmışlığımla vurdu zaman

Bütün bekleyişlerim  anlamsız

Bütün varışlarım zamansız

Açılışlarımsa tabansız artık

Bir yaban sevdaya yamandım 

Serden geçtim sevdalara dadandım

Ağlamak çözüm değil susmakta öyle

					Anladım...

Yitik bir aşkın son dizeleri bunlar, 

Taşımak kolay değil kırılmış umutları...

Her sevda yarım kalır, her yanım bir sevdadır

Ayrılış bir yarımı tescil etmektir artık

Yarım dışarıda kalır,  yarım gider kaybolur

Samimi bir itiraf, belki geç belki değil

Gerçeğin ta kendisi, kendi gerçekliğimin

Ardına saklanmaksa zinhar değil emelim

Beni sende bıraktım. Yitiğim sende artık.

(İstanbul,21,04,2001)

[email protected]', 'Nice bekleyişleri damıtır sabrın süzgeci    Sabra bulanır içli iç çekişlerin merhameti Ben yine sevdadan yana tavrımı koydum Sensizlikleriml...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ben-zaman-ve-bir-yitik-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın adı', 'askimin-adi-sair-mahcubat-qii2i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hasert bakışlarımla yazdığım satırlarımın

kiminde tebessümünü istedim kiminde arzularını

gelişim oldu sana yazdıklarım birtanem

senle söyleşim senle gülüşüm oldu yazılarım

belki vuslatın gölgesiydi bana we sana yansıyan

hiç doyurmayan belki hep aç bırakan

hep sonrasına aç hep sonrasına.

vakitler vardı senle olan diriliş gibi

hayatın başlangıcı ve bitişine bir isim 

açlığın sonuna doğru çeken bir koku gibi

yazış sana varış sana, aşkımın adı', 'hasert bakışlarımla yazdığım satırlarımın kiminde tebessümünü istedim kiminde arzularını gelişim oldu sana yazdıklarım birtanem senle söyleş...', ARRAY['Türk Edebiyatı','Şiir','Şair Mahcubat']::text[], 8.5, '{"poet":"Şair Mahcubat","poet_slug":"sair-mahcubat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askimin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk da Yanar Kimi Zaman', 'ask-da-yanar-kimi-zaman-gokhan-oktem-oikej', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk da yanar kimi zaman

Hüznün kızıla boyanır 

Hıçkırıklar düğümlenir boğazına ilmek ilmek

Çeksen çektiğinle kalır

Aşk da yanar kimi zaman

Bakışların tutsaklığınca ıslanır

Katmer katmer tutkulardan geriye 

Dilinde bir kekre tat kalır

Aşk da yanar kimi zaman 

Ruhun suskunluğunca yenik

Gönlün hoyratlığınca ürkek

Ve tüm arayışlarınca tepkisiz

Tükenmişliğinden öte

Bir ezik sükut kalır

Aşk da yanar kimi zaman

Nicedir bekleyişlerince umarsız

Umutlarınca küheylan

Yaşanmamışlıklarınca sabırsız

Ve iç çekişlerince küllenmiş

Bir yanık aşk ’a son söz,  ah... kalır

 					

(İstanbul,13,08,1999)', 'Aşk da yanar kimi zaman Hüznün kızıla boyanır  Hıçkırıklar düğümlenir boğazına ilmek ilmek Çeksen çektiğinle kalır Aşk da yanar kimi zaman B...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-da-yanar-kimi-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün Islaklığı', 'huznun-islakligi-gokhan-oktem-bjjp9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüznümü ıslatan göz yaşlarım mıdır, 

Kaybolan masumiyetim mi yoksa...? 

Sırça köşklerde beslediğim sevgim nerede şimdi...? 

Yozlaşmış tutkularımda kaybolan kimliğim midir, 

Aşkın ardı arkası gelmez arayış ve sapışlarında...? 

Yoksa gri tonlara bulanan siluetim mi..., 

Bu bildik ben içindeki bilmedik ben...

Ve derin bakışlarımın derinliklerindeki serzenişlerim...? 

Geçmişim ne bir özlem barındırır ne de geri dönüşler.

Hüznüme kaynaklık eder tek bir de muamma benliğime

Kanayan yaralarım çoktan kapandı lakin

Yaraya kan düşmeyi görsün bir kez

Tövbekar değilim tekrar sevmeye

Aşkı da reddedemem tümüyle

Ama şöyle daha usturuplu sevmeli insan 

Tepkisel değil de şöyle

İçeriğince ilkesel olmalı....

Ve bir kapı açık kalmalı daim

Başka yaşamlara dalma imkanı barındıran 

Özde sorgulamalı kendini insan ve bu mümkün olmalı

Ön yargılardan uzak, özle barışık 

Ve sınırsız...

Aşkla ateşlenen bir birliktelik

Sevgiyle perçimlenmeli 

Ve saygıyla yücelmeli

Sağlam zeminlerde ayakları yere basmalı her an

Sonra dengeli olmalı aşk özünde

Aldığı kadar vermeli en az

Ve bu alıp vermeler özveriden uzak

Tümüyle gönülden olmalı

Ve en güzel anlarda bile

Bir kapı açık kalmalı daim

Başka yaşamlara dalma imkanı barındıran....

Bağlılıklar ayrılıklarla güçlenir ya da ayrılıklarla çözülür gider

Bağımlılıktan uzak bir bağlılık

Ayrılıklarla mümkün olur ancak

İhtiyaçtan çok özlem barındırıyorsa bir ayrılık

Ne mutlu...

Yoksa mutlak ihtiyaç mutlak bağımlılık içerir

Ve bağımlılıktan ibaretse bir birliktelik

Ne hazin...

Her şeyi değiştiren zaman

Değiştirdi beni de elbet bilinçli ya da bilinçsizce

Direndiği noktada tutarlı

Tutarlı olduğu noktada dirençli oluyor insan

Ve akıp giden zamana inat

Değişim kıskacında değişmemek idiyse de ki  niyetim

Belki de kaybetmediğim tek şey, samimiyetim.....

(İstanbul,26,04,1999)', 'Hüznümü ıslatan göz yaşlarım mıdır,  Kaybolan masumiyetim mi yoksa...?  Sırça köşklerde beslediğim sevgim nerede şimdi...?  Yozlaşmış tutkul...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/huznun-islakligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-muhsin-demircioglu-u6u83', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hele uşaq iken nece xoşbextdim, 

Me''sum gülüşlerim bitmezdi anam.

İsti qucağından ayrı düşende 

Me''sum körpen rahatlıq bilmezdi anam.

Nece gözel idi uşaq illerim

Herkesi güldüren o şirin dilim

Hamını candan seven uşaqlıq sevgim

Göresen bir daha dönermi anam? 

Yox idi yalnızlığım ne sıxıntı telaşım

Qohum qonşu uşaqları ve oyuncaqlardı yoldaşım

Sizlerdiniz baş tacım candan sirdaşım

Sizin tek sirdaşım bir daha olarmı anam? 

Amma hedd-i büluğ çağı, heyatın sıxıntıları, 

Yalnızlıq, qeriblik, kimsesizlik anları, 

Bu yalnızlıqda seni xatırlayan zamanları

Gözlerimden axan seli tuta bileremmi anam? 

Yoxdur ki seven bir kimsen, açıb derdini deyesen

Yoxdur derdinden anlayan özüne sirdaş edesen

Derdimi deyecek, yardım umacaq 

Ürek dostu bularammı göresen anam? 

Verdiyin nesihetlere emel etmedim, 

Gösterdiyin doğru yolla getmedim, 

Amma indi diz çökürem önünde anam

Verilmeyecek borcunu sen halal eyle bize 

Müqessirem, bağışla, kesme duaların anam..', 'Hele uşaq iken nece xoşbextdim,  Me''sum gülüşlerim bitmezdi anam. İsti qucağından ayrı düşende  Me''sum körpen rahatlıq bilmezdi anam. Nece g...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Demirçioğlu']::text[], 8.5, '{"poet":"Muhsin Demirçioğlu","poet_slug":"muhsin-demircioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anam-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık ve 14 Kasım', 'ayrilik-ve-14-kasim-gokhan-oktem-glz99', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün Kasımın 14’ü

Bir dört bir de Kasım

Ruhuma tütsüdü acılarım yasım

Ben buradayım; bu yaban şehirde 

Sen uzaklardasın...

Bu gün Kasımın 14’ü 

Özgürlüğün adı bu gün

Adı doğum adı teskere

Ne büyük bir  rastlantı 

Ne talihsiz bir kader...

Doğum hayattır diyorlar

Teskere ikinci bir doğum

Oysa sen doğum sancıları çekerken

Ruhum ölüme oruca yatmış

Bilmek, anlamak,  kabullenmek

Sessiz, boynu bükük kabulleniş...

Varlığını sevmek kadar yokluğuna alışmak

Unutmak unutmaya çalışmak...

Yürek parçalamak, yaraya tuz basmak

Hıçkırmak, ağlamak, hafifleyip susmak 

Ama hep düşünmek, düşünmek, düşünmek

Sessizliğin ortasında düşüncelere dalıp 	

			Kaybolup gitmek...

Yokluğunun ayırdında 

		Varlığını düşünmek

			Var olmak ya da yok olmak; 

Ayrılık! ...; 

Varlıkla yokluk arasında ki o ince çizgide uzayıp gitmek...

Bilmek 

	Anlamak

		Hissetmek

			Sezmek

				Ama kabullenmemek, kabullenememek...

Aklım yüreğime uzak

		Yüreğime yabancı

Yüreğin konuştuğu dil 

		Akla yabancı

İkilemler yumağı ruhumu bölmüş

O ruhum ki özde benim ama bana yabancı...

Bu gün Kasımın 14’ü

Ayrılığın şarkısını söylüyor ağaçlar; 

Havada asılı kalmış; 

Ritim bozuk

	Melodiler belirsiz...

Mevsimidir ama her nedense rüzgar isteksiz

Yazdan kalan bir sonbahar sabahı

Bir garip ki sorma sonbahara yabancı

Bizleri dışardan birileri

	Yani bizim dışımızda 

		Bize uzak

			Bize yabancı...! 

Ama, hayır belki de 

Bize yakın

	Bizden biri 

		Biz 

			İçimizdeki biz...! 

Uzak ya da yakın 

	Bizden biri ya da bize yabancı

Ama bilen, 

	Duyan, 

		Gören, 

			Belirleyen, 

Ama, hep susan 

Varlığın ve yokluğun bütünleştiği şey 

Ve her şeyiyle 

Bu bütünlük içinde kaybolan

	Bir güç veya güçler yumağı bizi yöneten

Doğumla ölümü birleştirip adına rastlantı diyen 

Var ama yokken

Yok ama varken 

Belirsizliğe bürünen

Boyutlar ötesi

Ya da tüm boyutlarda biraz var olan

Her şey ama hiçbir şey

Hiçbir şey ama her şey

Ama sezilerde beliren

Duygularda büyüyen 

İçimizde ama bizden uzak

Bir güç ya da güçler yumağı 

Bilen, 

	Duyan, 

		Gören, 

			Belirleyen

				Ama  hep susan

Varlığın ve yokluğun bütünleştiği şey

Ama,  her şeyiyle bu bütünlük içerisinde kaybolan 

Bir güç ya da güçler yumağı bizi yöneten

Doğumla ölümü birleştirip 

Adına rastlantı diyen...! 

Ama hayır! ...Hayır...

Milyon kere milyonda kere bir 

O da senin doğum günün benim teskere günüme mi denk gelir...? 

İşte burada inancımdır köpüren

Beni alıp bu dünyadan götüren

Bir yaradan bir mutlak güç

Ya da adı her neyse

		Rastlantıya bırakmayacak kadar odur işi iyi bilen...

Bu gün Kasımın 14’ü

Bir dört bir de Kasım

Ruhuma tütsüdü acılarım, yasım

Ben buradayım, bu yaban şehirde

Sen uzaklardasın

Buna ayrılık diyorlar... Ayırdında mısın...? 

(Mersin,18,11,1997)', 'Bu gün Kasımın 14’ü Bir dört bir de Kasım Ruhuma tütsüdü acılarım yasım Ben buradayım; bu yaban şehirde  Sen uzaklardasın... Bu gün Kasımın ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/ayrilik-ve-14-kasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-gokhan-oktem-j9k2f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yalnızlık girdabında savrulur ruhum neden

Ne yapsam zevk alamam teklik hiçliğe beden

Bahar kışı kovalar, gece gündüze nispet

Benimse yalnızlığım bildiğim tek müebbet

Nedendir arayışım, bir mutlak bilinmezi

Yaralar yüreğimi yalnızlığın sentezi

Çok yokuşlar tırmandım hayat merdiveninde

Sebebi aşkım oldu, düştüm her seferinde 

Çok hayatlar tanıdım, her kaçış bir hikaye

Vuslata giden yolda, sevdam üstüme paye

Fakat edince inkar yüreğimde sevdayı

Kendi elimle yıktım kurduğum savunmayı

Aklım yüreğime uzak yüreğime yabancı

Ruhumda kabarıyor bitmek bilmez bir sancı

Her seçiş bir vazgeçiş demekmiş anlaşılan

Zamanın süzgecinde acılar elde kalan

Her aşk barındırırmış bir hayal kırıklığı

Sade zaman çözermiş bunca karışıklığı

Sabır, sabır ya sabır, sevdaya tek çaredir

Sevdaya düşen gönül  heyhat, pare paredir

Çivi çiviyi söker deseler de beyhude

Hep eskisi aranır her yeni sevgilide

Bir de bakarsın ki yıllar kalmış geride

İçin için yanıyor, yara üstünde perde

Kor alevler zamanla iz bırakır içerden

En ince dokunuşta yankı gelir derinden

İlk aşk, ilk sevdadır, ruhun en masum yanı

Bir daha tadılması hiç mümkün olmayanı

Hayat birazda böyle, her çıkış bir iniştir

Dengede kalabilmek bence en mühim iştir

Her bitiş bir başlangıç barındırır içinde

Umuda yelken açmak, değişik bir biçimde

Yeni başlangıçların nüvesi yeni aşklar

Her yeni limana varınca yine başlar

Değişimi barındıran hayatı özümsemek

Her koşulda hayatı bu bilinç ile sevmek

Bir çiçeği koklamak, bir kuşa eşlik etmek

O seslerde derinden bir senfoni dinlemek

Sevda yaşamdır, sevmek yaşamak hele

Yaşamak ve yaşatmaktır, işte bütün mesele

(İstanbul,21,04,2001)', 'Bir yalnızlık girdabında savrulur ruhum neden Ne yapsam zevk alamam teklik hiçliğe beden Bahar kışı kovalar, gece gündüze nispet Benimse yal...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gazel-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerime Dokunma', 'hayallerime-dokunma-gokhan-oktem-zximk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sus rahat bırak hayallerimi, hayallerime dokunma! 

Belki savruluyorlar çırpısızca, kendi çaplarında

Belki ayakları yere basmıyor, başı bulutlarda

Yine de onlar benim hayallerim, hayallerime dokunma! 

Farz et gören gözüm kör, duyan kulağım sağır

Farz et dokunuşlarım algılamaktan aciz

Farz et burnum kapalı, dilim ağzımda hapis

Ne kalırdı geriye hayallerimden başka

Bırak sürsün hükmünü, ruhum tenim içinde 

Algıda sınır beden, kemiğim et içinde...

Fakat hayaller başka, onların sınırı yok, 

Sonsuzluğu yaşatır, sonlu madde içinde...

Bırak kalsın tek vücut, kanatsız uçar belki

Ama yine de uçar, varlığım var oldukça.

Sus ve sessizliğe terk et sahneyi, 

Ve bırak! ... onlar benim hayallerim 

Hayallerime dokunma! ...

(İstanbul,10,07,1998)', 'Sus rahat bırak hayallerimi, hayallerime dokunma!  Belki savruluyorlar çırpısızca, kendi çaplarında Belki ayakları yere basmıyor, başı bulut...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayallerime-dokunma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Şey', 'zor-sey-gokhan-oktem-7qd6c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zor şey aşık olmak, aşkına birebir karşılık bulmak

Zor şey boylu boyunca sevdalı bir yaşam 

Zor şey bir ömür severek yaşamak

Çok zor şey kendini bilmek ve sevdayı yaşatmak

Çünkü zor şeydir kavramak bir apaçık gerçeği

Sevda yaşamdır....Sevmek yaşamak.........

(İstanbul,20,02,1998)', 'Zor şey aşık olmak, aşkına birebir karşılık bulmak Zor şey boylu boyunca sevdalı bir yaşam  Zor şey bir ömür severek yaşamak Çok zor şey ken...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zor-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanla Vals', 'zamanla-vals-gokhan-oktem-afwnz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hey asılsız zaman

Nasıl da vefasız çıktın

Adını hiç bilmediğim yerlerde

Ve hiç verilmemiş bir randevuyu bekler gibi

Hep seni bekleyip durdum...

Yaşarken bilmez idim neden yaşadığımı

Nereden gelip nereye gittiğimi

Bilmekte istemezdim doğrusu

Kaldıramayacak idiysem bir gerçeği

Ve hazır değildiysem ben, ben değilken karşılaşmaya

Bilinmezliğe sığındım kendi öz dünyamda ki

Ey en yüce bilge

Ey en asılsız mahluk

Ve ey en kart orospu; zaman

Artık biliyorum ben de

Her şey bir sende güzel, acı da sevinç de aynı kervanda yolcu

Hep bir anlam arayıp durdum akıp giderken bir sana tutunarak

Amaçlar edindim ufkum çapımda belki biraz daha büyüğünden

Direndim zorbaya dim dik, eğildim şefkatle önünde iyiliğin

Ve hep sorguladım tüm bildik bilmedik beni

Anlatmaya ne hacet

Zaten bilirsin sen de beni benden de iyi

Fakat, ben de elbet bilirim, bilirim seni bir o kadar

Bunca birlikteliğimiz var; yoldaşım, yol arkadaşım

Sen değil misin o doymak bilmeyen mahluk

Sen değil misin o uslanmaz hırsız

Tanrının verdiğini yüzsüzce her an çalan 

Ve ardında

Çakıl taşları gibi bir yıkıntı bırakan

Sen değil misin o en şuh orospu

Kim bilir daha böyle kimlerin kanına girdin

O sonsuz boşluğunda kainat sallanırken

O herkese, ilk yaz gibi taze gelen koynuna

Kim bilir benden başka daha kimleri soktun

Ey sonsuz eksenine şehvet saçan fahişe

Kırıta, kırıta ağını daha kimlere ördün...

Ama ah neyleyim ki, 

Her ne kadar bilsem de senin çirkin yüzünü

Varlığıma ölçüsün, 

Birliğim sana muhtaç

Bir cebri müşterekte 

Senin koynun bana ev

Ve nasıl olursa olsun

Evim yuvamdır benim,  ben evimi severim....	

(İstanbul,23,02,1999)', 'Hey asılsız zaman Nasıl da vefasız çıktın Adını hiç bilmediğim yerlerde Ve hiç verilmemiş bir randevuyu bekler gibi Hep seni bekleyip durdum...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/zamanla-vals-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı Hayaller', 'sevdali-hayaller-gokhan-oktem-24p7t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdam hayallerimde tutsak

En hayal sevdalarımda 

Sevdalarımdaki hayallerime sevdalanmışım

Sonsuz gök, 

Engin deniz, 

Ve gözlerinde çakan bir çoban yıldızı

Gülüm, sonsuzluğu senin gözlerinde tatmışım

Ben doğarken çığlıklarımı 

Meğer, en uzak umutlarımdan almışım.

(İstanbul,08,03,1999)', 'Sevdam hayallerimde tutsak En hayal sevdalarımda  Sevdalarımdaki hayallerime sevdalanmışım Sonsuz gök,  Engin deniz,  Ve gözlerinde çakan bi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdali-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçsel Serzeniş', 'i-csel-serzenis-gokhan-oktem-liav6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana elimi uzatıyorum canım taa uzaklardan

Parmaklarımın ucunda atıyor kalbim şu an...

Geç kalınmış bir açılımın serzenişi bu

Tutunca hissedeceğin

Hissedince kavrayacağın

Yüreğimin derinliklerinde çırpınan o ürkek kuşun 

Kanat çırpışlarında ki  ahenksizliği...

Sana elimi uzatıyorum canım

Bir duygu seli bu avuç içimin sıcaklığında dışa vuran, 

Islaklığınca boşalan iç çekişlerimin hıçkırıklarına boğulan

Katmerli samimiyetimle yıkarak duvarları

Sana taa yüreğimden kopan 

Elimi uzatıyorum.....

Sana elimi uzatıyorum canım

Parmaklarımın her hareketinde duyduğun o ses

Katmer, katmer acıları soğrumuş

Bir körpe yüreğin sesi

Ve o elin getirdiğini rüzgar sanma

O en körpe yürekte kopan fırtınanın nefesi....

Sana elimi uzatıyorum canım

Sanki yüzyıllar gerisinden 

En esirgenmiş duyguların

En köhne kurallarını yıkarak

Bir yeni başlangıcın müjdecisi

Beklenmeyen bir postacının eliyle uzattığı o

Beyaz üstüne düşen siyah gölgeleri gönderiyorum...

Sana elimi uzatıyorum canım

Parmak uçlarımda parlayan yüreğimin güneşi

Ve o güneşi besleyen otomlar değil

Kalbimin her tek atışında çoğalan

Sevgimin ta kendisi.....

(İstanbul,26,03,1999)', 'Sana elimi uzatıyorum canım taa uzaklardan Parmaklarımın ucunda atıyor kalbim şu an... Geç kalınmış bir açılımın serzenişi bu Tutunca hissed...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/icsel-serzenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-gokhan-oktem-4vcg8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşin denizi kucakladığı

Denizin güneşi kutsadığı yer 

Gözlerin...! 

Gözlerinde parlıyor güneş 

Evvel zaman hiç parlamadığı kadar

Ve gözlerinde buldu rengini deniz 

Deniz olalı beri

Gözlerin; 

	Pırıltısı güneş	

	Mavisi deniz

		Güneş ve deniz

		Ve o, 

Canımın içi 

Gözlerin....! 

(İskenderun,15,05,1997)', 'Güneşin denizi kucakladığı Denizin güneşi kutsadığı yer  Gözlerin...!  Gözlerinde parlıyor güneş  Evvel zaman hiç parlamadığı kadar Ve gözle...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozlerin-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamoz Gözlerin', 'yakamoz-gozlerin-gokhan-oktem-2x558', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mavi gözlüm kaybolayım maviliklerinin derinliklerinde

Deniz gözlüm boğulayım buğulu gözlerinin içinde

Deniz mavisi gözlerinde mavi yolculuklara yelken açıp

Gözlerin mavisi denizi bir renk cümbüşünde bulayım

Yakamoz vakti sorayım derken seni parıldayan güneşe

Gözlerin parıltısında kaybolan güneşi göreyim

Ve gök kuşağının altından geçerken denizi ve güneşi 

Dipsiz maviliklerinde yanan yakamoz gözlerine kurban edeyim

İki gözüm bil ki ben sevda yüklü bir yüreğim

Ve İsterim ki gözlerin gözlerime deydiğinde öleyim.......

(İskenderun,10,08,1997)', 'Mavi gözlüm kaybolayım maviliklerinin derinliklerinde Deniz gözlüm boğulayım buğulu gözlerinin içinde Deniz mavisi gözlerinde mavi yolculukl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yakamoz-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Saçları', 'gecenin-saclari-abdulkadir-karaman-la8fr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece saçlarını yaydı gözlere

Aradı gülleri ısrarla, güller

Hüzünlü kâlbini çözdü tellere

İnledi hâlinden, inledi teller. 

Güfteler gözyaşı, beste figandı

Nağmeler tutuştu, makamlar yandı

Sonbahardı mevsim, iklim nisandı

Telleri şefkatle okşadı eller. 

Issızlık her yana taşan nehirdi 

Sessizlik hislerde gizli sihirdi

Umutlar sevinçti, hasret zehirdi

Hayaller ufkunda korken emeller. 

02/01/02', 'Gece saçlarını yaydı gözlere Aradı gülleri ısrarla, güller Hüzünlü kâlbini çözdü tellere İnledi hâlinden, inledi teller.  Güfteler gözyaşı, ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gecenin-saclari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muamma', 'muamma-gokhan-oktem-fhnqq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne gezersin ey serseri salya sümük, ensemde

Bulanıksın, yapış yapış göze gelmez bir demde

Neye niyet neye kısmet neye hikmet bilmezsin

Zemheri bu, puslu gece, ayaz gezer tepende

Ne vakitli ne vakitsiz bir zamanlı zamansız

Paha etmez bir pahasız, boysuz poslu, anlamsız

Serden serpe, senli bensiz, bir acayip, tanımsız

Yürek bölük, yollar ayrı ey umarlı umarsız

Ne başı ne sonundayız, yarısındayız ömrün 

Yarım elma gönül alma armutları unutma

Kinin ruhuna kilit gururunsa bahane

Dön kendi ruhuna bak çelişkiyi görürsün

Ne maziden paylaşımlar yarına taşınacak

Ne de yitik aşkların peşinden koşulacak

Sen kendi ruhuna el ben kendi dehlizimde

Aramızdaki tek bağ ayrılık bağlacıdır...

(İstanbul,20,12,1998)', 'Ne gezersin ey serseri salya sümük, ensemde Bulanıksın, yapış yapış göze gelmez bir demde Neye niyet neye kısmet neye hikmet bilmezsin Zemhe...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/muamma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Aşklar Ülkesi', 'yitik-asklar-ulkesi-gulcihan-atalay-xad0a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alışmış yüreğin avare aylak

Havada ağır esrik bir leylâk

Umursamaz adımlarla sarsak

Geçersin sokağımdan

Ömrümü talan edip geçtiğin gibi

**

Sen geçecek misin bu sokaktan

Şimâl yıldızını indirip saçlarına

Yaşanmamış aşkların

Buğusu dağılmış ömrüne

Sönmüş bir meşâle tutarak avuçlarında

Pencerelerden kızıl bir gün 

Batarken yüreğime sarsıntılarla… 

Sen geçecek misin bu sokaktan

Başında hasır şapka

Boynunda kırmızı atkınla

Dudağında keskin bir ıslık

Ellerin ceplerinde muhakkak

Toy bir delikanlı yüreği

Göğsünde acayip çarpıntılarla… 

Sen geçecek misin bu sokaktan

Penceremde hiç açmayan begonyalar

Arsız bir türkü tutturarak

Gelişine coşacaklar

Teninde binbir çığlık

Gözlerinde fiyakalı bakışlar

Omuzlarında acayip pırıltılarla… 

Sen geçecek misin bu sokaktan

Bir ekspres Ankara Garı’na yaklaşırken

Yanlış indiğin istasyonlarda 

Gecenin ellerine batışı gibi

Hüzünlü  bir filmin sonunda

Sinema çıkışı gibi 

Kalabalık fakat usul mırıltılarla…

Sen geçecek misin bu sokaktan

Ayaklarında yorgun yılların tozu

Bir karanfil takıp yakana

Kirpiklerinde bütün denizlerin tuzu

Çıkıp bütün cam kapılardan

Girip bütün cam kapılara

Bir aşktan öbürüne savrula savrula… 

Sen geçecek misin bu sokaktan

Puslu aynalarda taranmış anıların

Gözlerin vedaların ilk perdesi

Bir kolunda üsküdar

Bir kolunda kız kulesi

Yüreğim yitik aşklar ülkesi

Ardından baka kalacağım yıkıla yıkıla…', 'Alışmış yüreğin avare aylak Havada ağır esrik bir leylâk Umursamaz adımlarla sarsak Geçersin sokağımdan Ömrümü talan edip geçtiğin gibi ** S...', ARRAY['Türk Edebiyatı','Şiir','Gülcihan Atalay']::text[], 8.5, '{"poet":"Gülcihan Atalay","poet_slug":"gulcihan-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yitik-asklar-ulkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-gokhan-oktem-bps8h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdalı yarınlar bekliyor beni

Şu kırkı çıkmamış acılarımdan sonra

Zaman; her şey zaman

Yaşanacak ne çok şey varmış hayatta

Yaşanmamış onca şeye rağmen....

Tam da seni düşünüyorum şu an

Yalnızca seni...! 

Kopuk hatıralar çarparken belleğime 

Aşındırıyor yüreğimin çeperlerini

O kan tadında acılarım...

Damıtırken sensizliğimi

	Sessizliğimin süzgecinde

Loş bir ışık gibi dolduruyor odamı

Üstü kapanmamış acılarımdan arta kalan sancılar

“ Susmakmış bir şeylere saygılı kılan “

Beki de kabullenmek....

Ondandır....! 

Bir bahar geliyor paldır küldür

Kan fışkırıyor damarlarımdan

Martın hikmetinden midir, 

Nedendir bilmem...? 

	Bilemem...! 

Fakat kedi olmadığımdan da eminim ya

Aşk çağırıyor beni köşe bucak

Her ses eşsiz bir melodi olup çınlıyor kulaklarımda

Her güzel alıp götürüyor beni

Karşı konulmaz arzularım benliğini arıyor.

Bir taze bahar geliyor aşk tadında

Sevda buza, toprağa, havaya karışırken

Aşk sağanağı yağıyor üstümüze

Ve biz sırılsıklam...! 

Bahar; Sevda tadında bir sübyan

Bahar;  Milyon kere milyon yıldan arta kalan bakire

Fakat aklım ermez

Nasılda kalmasını bilir 

Geçer de üzerinden üç mevsim bir kerede...! 

Bahar; 

Dört mevsim biri bahar, 

Bahar akıyor damarlarımda 

Sevda çağırıyor beni köşe bucak

Bir gizem ki çözemedim

Martın hikmetindendir zaar

Kedi olmadığımı biliyorum bilmesine de 

Kediler gibiyim nedense

Dedim ya

Martın hikmetindendir zaar...! 

(İstanbul,29,03,1998)', 'Sevdalı yarınlar bekliyor beni Şu kırkı çıkmamış acılarımdan sonra Zaman; her şey zaman Yaşanacak ne çok şey varmış hayatta Yaşanmamış onca ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bahar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar', 'bayramlar-gokhan-oktem-35e2a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedendir bilmem

Bayramlar hep acı veriyor bana

Sahipsiz duygularım mıdır ruhuma bayrak açan? 

Seviye erken umuda geç dalışlarım mı yoksa

Tepeden tırnağa soysuzluklara batan? 

Nedendir bilmem

Bayramlar hep sızı veriyor bana

Zamansız gelişleri

Sebepsiz oluşları

Uzayan varışlarındaki serzenişlerimdi belki

İçime sızıp ruhumu sıkan

Nedendir bilmem

Bayramlar hep ekşi ayran tadı veriyor bana

Sanki, içten içe

Reçelleşmeye yüz tutmuş

Yapış yapış duygular kervanında		

Bir asi çığlık benimki

Ne bileyim 

Dam üstünde şakıyan saksağan gibi geliyor bana

Nedendir bilmem

Ama isterdim ki  bayramlar

“Ay” olup dört mevsim gün saydıracağına

“Bir tutam ay ışığı” olsa gizlice ruhuma dolan.....

(İstanbul,16,10,1999)', 'Nedendir bilmem Bayramlar hep acı veriyor bana Sahipsiz duygularım mıdır ruhuma bayrak açan?  Seviye erken umuda geç dalışlarım mı yoksa Tep...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bayramlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yanık Ezgi', 'bir-yanik-ezgi-gokhan-oktem-d4ycq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yanık ezgisin sen ruhumda titreyen

İki boncuk tanesi olup gözlerimden dökülen

Kalbimin her tek atışında derinden hissettiğim

Yokluğun acısıyla kanayan yaramsın sen....

(İskenderun,11,08,1997)', 'Bir yanık ezgisin sen ruhumda titreyen İki boncuk tanesi olup gözlerimden dökülen Kalbimin her tek atışında derinden hissettiğim Yokluğun ac...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-yanik-ezgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-gokhan-oktem-e3mk8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cehaletin cilvesiydi bizi bizden alı koyan

Bir cehalet hilesiydi içimize korku salan...

Mor gülleri yanağından deremeden geçti yıllar

Yürek bölük, yollar ayrı bize bizden arta kalan

Şimdi artık ne ben benim,  ne de sen sen, unutma ki

Bir seni hep yaşarım ben, bir ben de hep sende baki

Biz ikimiz iki bir’iz  fakat, bir’e bir değiliz

Bir bütünün parçasıyız, tek tek bir bütün değiliz

Yüreğime karşı geldim, öz sevgimi küçümsedim

Seneler sonra öğrendim, sevmek yaşamak demekmiş...

(İstanbul,08,02,1999)', 'Cehaletin cilvesiydi bizi bizden alı koyan Bir cehalet hilesiydi içimize korku salan... Mor gülleri yanağından deremeden geçti yıllar Yürek ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bilmece-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Damla Gözyaşı', 'i-ki-damla-gozyasi-gokhan-oktem-oijxd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İki damla göz yaşı

   İki gönül pınarı

      Çağladı, çağladı

         Aktı menzili bilinmez 

            Dibi görünmez 

               Bir yürek kuyusuna

     İki damla göz yaşı

        İki gönül pınarı

           Hasret yüklü

              Acı yüklü

                  İsyan yüklü....

                      Ah..........Ah...........

                         

           Ve kanadı gönül yarası

               Kan  pınarı oldu gönül pınarı

                   Karıştı göz yaşına

                       Çağladı, çağladı....

	            Aktı menzili bilinmez 

		Dibi görünmez 

                                   Bir yürek kuyusuna

                                   

           İki damla kanlı göz yaşı

                İki kanayan gönül pınarı

                   Çağladı, çağladı

                     Ve bu yürek

                        Acı, acı ağladı......

(Amasya,10,08,1997)', 'İki damla göz yaşı    İki gönül pınarı       Çağladı, çağladı          Aktı menzili bilinmez              Dibi görünmez                 Bir ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/iki-damla-gozyasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyor mu Ne', 'korkuyor-mu-ne-gokhan-oktem-6pun3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakmıyor bile

Korkuyor mu ne

Kaçırıyor gözlerini

	O mavisini denizden

	Pırıltısını güneşten ödünç aldığı...

			Mı desem...

	O mavisinden denize

	Pırıltısından güneşe bir parça verdiği

	Denize ve güneşe sebep

	Ve bir o kadar da güneş ve deniz olan

	O sonsuz güzellikleri barındıran

	O en cesur kaşifi bile 

	Can atarken keşfetmeye alıkoyan

	O gizemleri ebedi olmaya mahkum olan

	Ve fakat

	Cazibesi insanı çıldırtan

			Yakan 	

				Kudurtan

					Eriten 

					        Ve solduran

	O geçmiş ve gelecekte

	Her zaman ve her yerde

	Ve sadece bir müddet benim olan	

	O tadına doyum olmayan

	O aşkın tutkusuyla kavrulan

		Ve nefretin kuyusunda kaybolan

	O şimşek olup çakan 

	Ve sadece beni yakan ve yıkan.....

Kaçırıyor

O boncuk gözlerini

Benim fersiz gözlerimden

Korkuyor mu ne? 

Acımın dipsiz kuyusuna düşmekten...

Gözlerim gözlerini arıyor 

Gözlerin nerede....? 

(İstanbul,29,11,1997)', 'Bakmıyor bile Korkuyor mu ne Kaçırıyor gözlerini 	O mavisini denizden 	Pırıltısını güneşten ödünç aldığı... 			Mı desem... 	O mavisinden den...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/korkuyor-mu-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-golge-gezgini-0ou9e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gittiğini bildim unutamam

Hiçbirşeyle avunamam 

Karanlıklarda olmayan ışıklar gibi

Unutamam 

Vurgun gibi sakin gidişin unutamam 

Havada nem yoktu buhu yoktu

Yanaklarım ıslak

Gözlerim yaşlı avunamam

Yapayalnız geceydi unutamam

Heryer karanlık güneş yoktu sen yoktun 

Ayla yıldızlarla avunamam 

İçimde sızın var sen yoksun unutamam

Kalbimde sevgi yoktu aşk yoktu

Leylayla şirinle avunamam

Bir sen vardın sensizlikle avunamam

Unutamam..', 'Gittiğini bildim unutamam Hiçbirşeyle avunamam  Karanlıklarda olmayan ışıklar gibi Unutamam  Vurgun gibi sakin gidişin unutamam  Havada nem ...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutamam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zemheri Yeşillere Küstüm Ben', 'zemheri-yesillere-kustum-ben-golge-gezgini-8f74t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zemheri yeşillere küstüm ben 

Gözlerinin karasından sonra

Ne de yakın geldi gözünün karasından kalbine yol

Oysa nemruta yalın ayak çıkmak daha kolaymış

Sana bukadar uzaktan yazmakta varmış

Zemheri karalarada küstüm ben

İçime gömdüğüm depremlerden sonra

İnadına vurgun yüreğimi uslandırdım 

Alt tarafı bir sevda dedim 

Ben en çok zemheri sevdama küstüm 

Eski bir aynada kendimi gördüğüm 

Eski bir yüzüm vardı

Bitmeyen bir çizgi aynamdan yüzüme hatıra

Kocaman bir ihtiyar gördüm yaşı 25

Suskun suskun çığlık attım

Bir hıçkırık bin çığlık attım

Oysa 

Zemheri yeşillere küsmüştüm ben 

Gözlerinin karasından sonra

Mevsimlerden güz geldi

Küsmüşüm ya yeşillere

Hayatımı zemheri zehir etti bu mevsimler

Belki de kış gözlerinin karasına yanarım

Çaldım aklımı firara sanki

Lakin senden firar olmazki

Kurtuluşum dağlarda sanki binlerce kurtla

Belki bir kovandaki bal nasibim 

Belkide duvaklar içindeki sen 

Belkide hüzünlü bir şarkının ilk mısrası

Belkide neşeli bir tangonun son valsi

Yıllar var sanki içimde

Her an kanıyor

Hala kurşun gibi sözlerin içimde

Kendim bir çiftenin ucundayım sanki

Oysa 

Zemheri yeşillere küstüm ben 

Gözlerinin karasından sonra

Bir esmerin hapsine girdim cezam inmedi

Müebbte tabi bedenim ve kalbim 

Şu deli ekimin içinde gel

Aç zindanımın mahpus kemerini

Bir arşın ilerle zindanımdan içeri

Zemheri bir gül ve dikenleri ayıklaya ayıklaya

Bir gülücük bir isyan ver

Bırak, bırak ondan sonra

Güneşlerede küseyim 

Zemheri sarılara

Göklere küseyim

Zemheri mavilere

Zor değil

Zemheri yeşillere küstüm ben 

Gözlerinin karasından sonra

Zindan grilre aşığım ben 

Kara gözlerine 

Kahve tenine.

Bilmediğim türkülere aşığım ben 

Zemheri sevdalar küstüm ben 

Senin sevdandan sonra.

Sana küstüm ben 

Senin aşkından sonra....', 'Zemheri yeşillere küstüm ben  Gözlerinin karasından sonra Ne de yakın geldi gözünün karasından kalbine yol Oysa nemruta yalın ayak çıkmak da...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/zemheri-yesillere-kustum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-i-smail-saritas-ot06f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sana  fısıldayan rüzgarlarla serenad yaptım

Dilimin söylediği fani sözlerle değil

Ben seni yürekten sevdim

Başı boş üç beş kelimeden ibaret değil

Ben seni güneşin doğuşuyla sevdim

Bülbüllerin şakıyışı, suyun sesiyle sevdim

Ben seni tan yerinin ağardığında

Güneşin insanlara aksiyle sevdim

Ben seni şiirlerde sevdim

Adına yazdım  onlarca şiiri rüzgarların diliyle

Onun kanadında ulaştırdım sana sevgimi

Sana olan sevgimi sana olan keyfiyetimi

Ben seni katran gecelerin karanlığında sevdim

Toprağı döşek, yıldızları yorgan yaparak

Ben seni seninle sevdim

Seni sevdim, seni istedim

Dedim ya güzelim..! 

Ben seni yürekten sevdim

Dilimin söylediği başıboş üç beş kelimeden ibaret değil

                                                                           İ.SARITAŞ', 'Ben sana  fısıldayan rüzgarlarla serenad yaptım Dilimin söylediği fani sözlerle değil Ben seni yürekten sevdim Başı boş üç beş kelimeden iba...', ARRAY['Türk Edebiyatı','Şiir','İsmail Sarıtaş']::text[], 8.5, '{"poet":"İsmail Sarıtaş","poet_slug":"i-smail-saritas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerdeki sevdigim', 'duslerdeki-sevdigim-omer-avsar-t0d6m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimi böylesine çarptıran

Beni sanki yeniden yaratan

İçimde tarifsiz heyecan başlatan

Söndü sandıgım  volkanı  yakan

Bir yar var uzaklarda...

Sesini duydugumda umutlandıran

Er yada geç benim olacak olan

Yüregimde çiçekler açtıran

Sevgisi kaderime yazılan

Bir yar  var uzaklarda...', 'Kalbimi böylesine çarptıran Beni sanki yeniden yaratan İçimde tarifsiz heyecan başlatan Söndü sandıgım  volkanı  yakan Bir yar var uzaklarda...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/duslerdeki-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralar ortak', 'yaralar-ortak-sair-met-e7z76', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaralar ortak

Bilmezler

Bilenler

Gülenler gibi.

Sevmeler ortak

Sevmezler

Sevenler

Susanlar gibi.

Sancılar ortak

Sarmazlar

Saranlar

Soranlar gibi.

Kılıflar ortak

Dikmezler

Dikenler

Giyenler gibi.

Suçlar ortak

İşlemezler

İşleyenler

Mağdurlar gibi.

Ağlamaklık ortak

Kızmazlar

Kızanlar 

Krallar gibi.', 'Yaralar ortak Bilmezler Bilenler Gülenler gibi. Sevmeler ortak Sevmezler Sevenler Susanlar gibi. Sancılar ortak Sarmazlar Saranlar Soranlar ...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yaralar-ortak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak Arası', 'yaprak-arasi-sair-met-8uba0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaprak arası 

Benim öyküm gibi; 

Üçyüz elliyedi ile

Üçyüz ellisekizin arasındaki

Yıldızlı paragraf.

Dikkate gerek yok 

Sadece kendi tarihimi aydınlatıyorum.', 'Yaprak arası  Benim öyküm gibi;  Üçyüz elliyedi ile Üçyüz ellisekizin arasındaki Yıldızlı paragraf. Dikkate gerek yok  Sadece kendi tarihimi...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yaprak-arasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-sair-met-ry6bo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz, 

Kimsesiz bir hece

''Sen'' diyor gizlice

''Gel'' diyor

Parçalayan olma acıları, 

Acılar birdir içimde.

Ve ölüm boş; 

Bitmez, 

Ben bitsemde sevmeler

Ancak seni, 

Gözlerine bakılan her kadında, 

Yazar bilmeden şairler', 'Sensiz,  Kimsesiz bir hece ''Sen'' diyor gizlice ''Gel'' diyor Parçalayan olma acıları,  Acılar birdir içimde. Ve ölüm boş;  Bitmez,  Ben bitsem...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapatalım Hesabı', 'kapatalim-hesabi-yasar-yabutlu-3zl8g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yolumu bırakıp yoluna saptım, 

Sayende dert üstüne bin dert kaptım

Bilmemki sana ne kötülük yaptım

Seni el üstünde tutmaktan başka.

Her kim olsa bozulurdu asabı

Görmezmisin çektiğim ızdırabı

Ne verdiki, artık kes bu hesabı

Dikenler üstünde yatmaktan başka.

Sensizliğe canım alışamadım

Özlemimdin ama kavuşamadım

Ne yaptımsa sana ulaşamadım

Koşu bandı vari, koşmaktan başka.

       

          [email protected]', 'Yolumu bırakıp yoluna saptım,  Sayende dert üstüne bin dert kaptım Bilmemki sana ne kötülük yaptım Seni el üstünde tutmaktan başka. Her kim ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yabutlu']::text[], 8.5, '{"poet":"Yaşar Yabutlu","poet_slug":"yasar-yabutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kapatalim-hesabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis', 'sis-ozan-kaymak-x2v7r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tam ayrılık havası, 

Hava güneşliydi, 

Sevgililer kol kola, 

Sırası mıydı şimdi...

Tak sepeti koluna, 

Herkes kendi yoluna demenin.

Bardağımdaki kola, 

Çoktan asiti kaçmış, 

Keyfi yok içmenin.

Boğazım düğüm düğüm, 

Konuşmakta zorlanıyorum, 

Sorun ne, 

Yanlış nerede...

Ben nerdeyim...

Ben kimim...

Neydim, 

Şimdi neyim...

Nerde aşkın gücü...

Nerde süslü sözlerim...

Yalan mıydı...

Şimdi nemli gözlerim...

Nerde lan senin mertliğin! ..

Ve erkekliğin...

Doğrusu bu muydu...

İleride üzülmeyecek miyim...

Çocuklarım için mi, 

Ya ben düzelecek miyim...

Yoksa gece ve gündüz...

Sis içinde dümdüz...

Doğru ve yanlış içinde, 

Herşey kendi içimde...

Kararı ben mi vereceğim, 

Sorumluluk alacağım kararlarımdan, 

Sonuçlarına katlanacağım, 

Ya siz neredesiniz...

Belki ben kanatlacağım...

Siz neredesiniz...

Hani mutluluklar paylaşıldıkça...', 'Tam ayrılık havası,  Hava güneşliydi,  Sevgililer kol kola,  Sırası mıydı şimdi... Tak sepeti koluna,  Herkes kendi yoluna demenin. Bardağım...', ARRAY['Türk Edebiyatı','Şiir','Ozan Kaymak']::text[], 8.5, '{"poet":"Ozan Kaymak","poet_slug":"ozan-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sis-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-kivilcim-dosemeci-tjgk4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni gördüm gece rüyamda 

Gel dedin yağan yağmurla

Geldim sana o gece vakti 

Yıldızlar şahidimdi

Uyuyordun melekler gibi

Öptüm, kokladım seni

Tekrar bindim bir yağmur damlasına 

Beni getirdi o karanlığa

Aydınlık istedim yağmurdan 

Işte orda, yanıbaşında dedi bana.', 'Seni gördüm gece rüyamda  Gel dedin yağan yağmurla Geldim sana o gece vakti  Yıldızlar şahidimdi Uyuyordun melekler gibi Öptüm, kokladım sen...', ARRAY['Türk Edebiyatı','Şiir','Kıvılcım Döşemeci']::text[], 8.5, '{"poet":"Kıvılcım Döşemeci","poet_slug":"kivilcim-dosemeci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ruya-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülün Anatomisi', 'bir-gulun-anatomisi-barbaros-mustafa-guner-ozb9u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül tohumdur, gül toprak

Ve sen hayata atılırsın senin olmayan isteklerle, 

üzerine gülücükler yapıştırılır, sen anlayamazsın bir başka beyaz gözlerle.

       Gül yeşildir, gül tomurcuktur, toprak sıcak ışıklarla nemlenince

Ve sen tadını kaybedersin hala anlamsız, hala acımasız pembe köşende.

        Gül utangaçtır, gül kızarır

Ve sen anlamsızlıklarına ilk yorumlarını katarsın.

Pembe rengine siyah yakıştırmalara başlarsın, 

ebruli sanışında...

        Gül anlayamaz, gül sessiz kalır

Ve sen simsiyah umutlar yetiştirirsin

pembe tohumlardan geçmiş zamanlı sarı gül suskunluğuna.

Sarının siyaha yakıştığını bilirsin.

Gül sararmıştır, sense siyahsındır.

                                                        Gül topraktır, gül tohumdur...

                                               

                                             12-01-2001   -   İstanbul', 'Gül tohumdur, gül toprak Ve sen hayata atılırsın senin olmayan isteklerle,  üzerine gülücükler yapıştırılır, sen anlayamazsın bir başka beya...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Mustafa Güner']::text[], 8.5, '{"poet":"Barbaros Mustafa Güner","poet_slug":"barbaros-mustafa-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gulun-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lal Misali', 'lal-misali-cetin-akgun-eacwn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beynimde var olan sözcükleri

Dile getirememek ne acı

Oysa beynimdekileri boşaltmak istiyorum

Patlamamış kurşun misali

Tetiğe dokunamamak ne acı

Benliğime hakim olamasam da

Sözcükleri dile getiremesemde

Her gecen gün yok olmak ne acı

Uçmaya hazır kuş misali

Sürekli uçuyorum sonsuzluğa dogru

Gecenin sessiz karanlıgı çöküyor

Gökyüzü yıldızlarla doluyor

Bir yıldız kayıyor

Bir dilek diliyorum

Konuşamayan bir lal misali

Dilimi konuşturamıyor

Beynimde var olan sözcükleri

Sana söylüyemiyorum', 'Beynimde var olan sözcükleri Dile getirememek ne acı Oysa beynimdekileri boşaltmak istiyorum Patlamamış kurşun misali Tetiğe dokunamamak ne ...', ARRAY['Türk Edebiyatı','Şiir','Çetin Akgün']::text[], 8.5, '{"poet":"Çetin Akgün","poet_slug":"cetin-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/lal-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin İtirafı', 'sevginin-i-tirafi-cetin-akgun-4rqn1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni her defasında görmek

   Hayatımın akışını degiştiriyor

Okadar tatlısınki

Bunu sana belirtmek istedim

Sana dokuna bilmek, seni hissetmek istedim

Oysaki buna cesaretim dahi yok

Hayaller kurup yaşamaktansa

Seninle yaşamayı yeğlerim

Sana olan ilgimi gizlemekten sıkıldım

Artık haykırmak istiyorum

    Seni sevdigimi

Evet; SENİ SEVİYORUM

Aramızda nekadar uçurum olsada

Ben uçurumları aşıp 

Yinede sana koşacağım

Gönül ferman dinlemiyor ki

Şuan isterdim yanımda olmanı

Bana sarılmanı, beni öpmeni

Öyle bencil ve yalnızım ki

Şimdiden sana ihtiyacım var 

Henüz yolun başında olsam dahi

Yinede sana ihtiyacım var', 'Seni her defasında görmek    Hayatımın akışını degiştiriyor Okadar tatlısınki Bunu sana belirtmek istedim Sana dokuna bilmek, seni hissetmek...', ARRAY['Türk Edebiyatı','Şiir','Çetin Akgün']::text[], 8.5, '{"poet":"Çetin Akgün","poet_slug":"cetin-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevginin-itirafi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'labirent', 'labirent-tugba-ucar-dvabu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kartondan evlerin 

Kan kırmızı duvarlarında 

Ara sokaklar çizdim.. 

Halkaları severdim, 

sonra bir gün halkalar büyüdü içimde 

Labirentlere bölündüm.. 

Kan kırmızı duvarların 

ara sokaklarında 

halkalara sevdalı 

düzgün dört yüzlü bir labirenttim... 

Aynalarım vardı 

Taze kırık kokusuyla ayrıştırılan, 

Karanlıkta yansımıştın 

kucak dolusu ay mevsimlerinle. 

çıkmazlarım senin siluetine gebe 

çığlıklarınla yoğrulurken, 

nefesimi boğazımda tutup 

taze kırık kokusuyla 

kırmızı odalarımın ara çizgilerinde 

halkaları bi başına bırakıp 

labirentine daldım... 

soğuk iklimlerinin tadındaydım.. 

difteri olmuş solgun kederimle 

bir köşe sonunda vedalaştım 

sen ve senin parçalanmış aydınlık yüzünün 

kan kırmızısı duvarlarında dolaştım.. 

önce halkalarına sevdalandım 

sonra labirentlerine... 

bedenime çizilmiş yarı dinç şiirlerinle, 

tesadüflerinin esaslı kafiyesi, 

labirentlerdeyim şimdi... 

labirentlerindeyim...', 'Kartondan evlerin  Kan kırmızı duvarlarında  Ara sokaklar çizdim..  Halkaları severdim,  sonra bir gün halkalar büyüdü içimde  Labirentlere ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/labirent-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mır Bir Sabahı Beklerken', 'mir-bir-sabahi-beklerken-tugba-ucar-dctfu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'acıyı bastıran tek eşli bir sessizlik bu bizimkisi

gözlerimizde menus bir saldırganlık

üzgün şehrimizde mor bir sabahı bekliyoruz. herkes birbirini suçluyor

sabırsızlanıyoruz beklerken..

sabırsızlık derecelenirken dilimizde, acının sözünü kesip, talihli bir 

güvercinin ayağındaki mektupla cellatların eline düşüyor, hayatımızı 

dilimliyoruz sözcük aralarında. her bir sözcük kapının deliğindeki ışık 

demeti.ışık dağıtıyor bizi.. revan içinde kana bulanıyoruz.

sonra bir ses düşüyor yüreğimize. ''''hayata'''' döndüren bur ses.

suflörün tekrarıyla, düşümüzden uyanıp, sabırsız alacakaranlığımıza 

dönüyoruz. sararan gri bir sabahın, mor ışıklarını diliyoruz 

yıldızlardan..üzgün şehrimde yağmurlar dolduruyor çukur sevgilerimizi. bu 

tek eşli sessizlikle terk ediyoruz sizsizliği... sırtımda çocukluğum, 

ceplerimde biriktirdiğim gözyaşları ve nevrozum terk ediyorum üzgün 

şehrimdeki kırmızı sabahları..

Merhaba dipsizlik.....

Tuğba...', 'acıyı bastıran tek eşli bir sessizlik bu bizimkisi gözlerimizde menus bir saldırganlık üzgün şehrimizde mor bir sabahı bekliyoruz. herkes bi...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mir-bir-sabahi-beklerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçyüzün', 'i-cyuzun-turabi-turan-o6ddd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçinin çirkinliğine şuçlu arama

onu sen seçmedin

yüzünün çirkinliğine şuçlu arıyorsan

aynaya bak', 'İçinin çirkinliğine şuçlu arama onu sen seçmedin yüzünün çirkinliğine şuçlu arıyorsan aynaya bak...', ARRAY['Türk Edebiyatı','Şiir','Turabi Turan']::text[], 8.5, '{"poet":"Turabi Turan","poet_slug":"turabi-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/icyuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-turabi-turan-pqpwv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani var ya

yağmur sonrası renkler dizilir gökyüzüne 

bakarsın bakarsın da gözlerin kamaşır

yüzün öyle

Hani var ya

yağmur sonrası bir koku yayılır doğaya

tadarsın tadarsın da başkalaşır için

tenin öyle

Hani var ya

yağmur sonrası cıvıltılar kaplar dünyanı

ışıldar ışıldarsın da  yaşama sevincin artar

sevgin öyle', 'Hani var ya yağmur sonrası renkler dizilir gökyüzüne  bakarsın bakarsın da gözlerin kamaşır yüzün öyle Hani var ya yağmur sonrası bir koku y...', ARRAY['Türk Edebiyatı','Şiir','Turabi Turan']::text[], 8.5, '{"poet":"Turabi Turan","poet_slug":"turabi-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hani-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hareket Memuru', 'hareket-memuru-yavuz-agra-d1uzn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '09: 30

çaresiz, 

yorgun, 

her günün farklı bir hikayesiyiz, 

n yazan belli, 

n okuyan, 

birden, geriye saymaya kalkıyoruz, 

film bitse de, 

biz yine hep aynı mutsuz 

ve uzak sonu yaşıyoruz...

10: 45

dertleri dava eden kalbime, 

ömür boyu hükümsüzlük veren sarı sayfalar, 

hangi gün oluca dönen devranı, 

satılığa çıkaracaklar acaba...

11: 20

beni kağıttan gemilerimle  peçetelere çizdiğim ufka yollayan, 

masalların çoğunun mutlu sonunda, 

geri getirmeye ant içilen ama unuttuğun, 

mektupları yağmurlarından koruduğum sevgili, 

dipsiz denizlerde varmış meğer, 

hala boğulmakta birileri, 

hala yazılmakta masallar, 

sevilmekte unutulmuşum, 

bir sonraki treni yine kaçırdım, 

sen ben de hareket saatini beklemeye devam et

garların sevdalısı, 

durdukça yağmurlara, 

ıslandıkça güneşe, paslan...

12: 45

her istasyonda bir başka aşk hayalleri, 

her istasyonda bir başka gönül kırıklıklarına dönüşürken, 

nasıl sızlardı vagonların yürekleri bir bilseniz...

bir demet papatya geldi o gün gara, daha önceki yüzlercesi gibi, 

başına ne geleceğini hissetmişti sanki, 

büküktü boynu, 

parlak jelatininde ışıldayan, 

sanırım göz yaşlarıydı, 

vagonlara gülümsercesine silkindi, 

başı artık dikti, 

kendine gelmişti, 

koltuklarından camlarına kadar irkildi vagonlar, 

kadere isyan etmenin korkusu yayılmıştı sanki...

yarım saat kadar bekledi...

sonra havalara uçtu, 

yükseldi, ...yükseldi, ...

her bir parçası başka anıları temsilen, 

farklı yüzlerce kalpsiz ayak altında ezildi, 

aşkların yükünü jelatinin ardına gizlemişti...

vagonlar bir başkasının hüzünlü şarkısına yöneldiklerinde, 

dikenine katlanılanı taşıyan bir çift ayak geçip gitti üstünden, 

işte şimdi bitmişti hikayesi 12: 45 hüzünlerinin................................................................

13: 30

cennetinde yer aç bana, 

kovduğun dünyalar yetmedi mi, 

ilk ve son kez gömdüğün yerdeyim yine, 

her gece unuttuğun anıyı yaşıyorum anlamsız çehreler aleminde, 

omzumda kırık bir lokomotif busesi, 

susuyor yalnızlığında, 

her tarafım yorgun, 

her deniz dalgalı bu aralar, 

her sevdam kırgın, 

ve her delikanlılığım bir yosun, 

her hangi bir köşesinde garların...

...bir umut yolla bana, 

belki bir gün bulacağım cennnetinden...

‘paramparça gidiyor yine bir mektup kahrolanlar şehrine’.......

13: 45

bulutların nemli öpücüğünü kondurup ensene, 

hangi rüzgara binip gidersin şehrimden, 

hangi aşktı bizimkisi, 

kaç numaralı peronda bekliyordu, 

ve nerde unuttun, 

ve neden kaldı umutlarım, ALLAH VERGİSİ iademden geriye, 

dünü bitince katledilen şarkıların dirilişi, 

düşlerinde bile göremediğin sevdandan mı yardım isteyeceksin, 

nerede kaçıp giden zamanın, 

örtüsü kalkmış ıssızlığının rüyası yalnızlığı ya da, 

ben bi vagon düşlüyodum, 

makinist aldı götürdü............ 

14: 20

benden bana ne! 

komşularımın biten aşklarını biriktiriyorum arka bahçemde, 

çöpçülerle dost...

yıldızlarımın gün kokan yaşlarını saklıyorum, 

avucumdaki nice aşk yüzüklerinde...

ey umutsuzluğumun tanrısı, 

adayacak ruhlar ellerimde, 

sana geliyorum, 

dualarda unuttuğum

gece gibisin sevgilim, 

                  sevgilin, gün gibiydi, 

                  sevgili, öğlen vakti arayışları, 

beklemekle yalnızım şimdi, 

bir sonraki trenin sana adanmış gün batımında, 

uykusuz ve uygunsuz hala...

15: 30

bana bakmanın da ötesinde göremediğin daha neler vardı, 

konservelerde doyan karnım, 

beni bırakmanın kıyısında kim bilir daha ne heceler ardı gizli, 

berrak kokan dağ rüzgarları vardı, 

telli duvaklı turna masalları anlatırdın ya bana, 

gelin tellerinde intiharlara sebep yazdılar onu, 

hareket defterlerine....

başım camlara yaslı, yollardaki direkler yastığım, 

bir sonraki trende havalandı bak raylardan, 

boynumdaki yüzlerce nesillik bir yazgı, astığım, 

bir garip şarkı ufukta birleşen raylar, 

hep ayrılar aslında kitaplara konu olacak kadar...

kaderin hüznünü dinlemek elde olsaydı, 

onu dinlemekten yazgımıza isyan etmeye fırsat bile bulamazdık

gerçi hiç aramazdık da...

 eh yağmur bunca insan varken beni ıslatmaman nedendir.........

16: 30

ellerim mürekkebinden ıslandı, 

akan her damla kim bilir kaç ölümün kederli şiiriydi, 

ben her gecenin geçmeyen bir vaktiyim, 

akreple yelkovanın uzak bir rüyası belki de...

bebeğimi benden çalan insafsız zaman, 

hiç olmadığı kadar dik dursa da, 

evet yaşlanan gözlerim, 

kırışan sevgilerim, 

perişan aşklarım, 

16: 30 kahroluşlarım çocuğuma gebe hayatın

silinmiş kayıtları belki de...

17: 15

son yıldıza kadar kapsama alanı dışındasın, 

yazık ki ben, ulaşılamıyorum...

17: 30

köşelerinde sürüp giden hayatın, 

bitişlerinde başlanmış mektuplar, 

hayallerinde kurutulmuş, 

ağıtlar, aşklar, masallar, şarkılar, 

hep aynı örgü, 

bi yerlerde, 

son buluşlar..., 

17: 45

mordan pahalı pembeler, 

tan kızıllığı edasıyla vagonları yıkıyor taklidi yaparlarken, 

lokomotifin solgun bakışlarında bin bir farklı yüreği eritmeye uğraşan kırlangıcın lal tazeliğinde notaları 

bir başka sevdalı ve bir başka yaralı kulun

acılarını dağlıyordu...

ellerinde sayfalar dolusu boşlukları, 

güneyini tutmuş dağlar, 

kuzeyinde denizleri, 

pusulasında kar taneleriyle, 

bir sevgilinin ardından bakmama cesaretsizliğini aşılarken, 

mimli bakışlar, 

lal tazeliğini kabuslarıyla tanıştırıyorlardı, 

paramparça kanlar ve acılar, 

bir tek sağır lokomotif duydu sesini, 

o da ağır aksak jilet fabrikasına ilerliyordu....

18: 30

gara...

kara geceler...

gelme büyüklüğündeler...

sadece dönüş bileti almıştı, 

arka cebinde yankesici çocuklara gülümsüyordu, 

meçhulden anlık havlamalar yükselse de 

inceden bi sevgili yanı sıcaklığı, arıyordu gözleri, 

dizlerinde tattığı aşktı, 

mayhoştu, 

ekşiydi, 

metalimsi, gri bir tadı vardı belki de, 

 şarkılar hep aynı kaseti söylerken, 

birileri ‘play’ e basmamış olsa gerek diye düşündü, 

bilet ne kadar ağırdı, 

indirimli olması için yalvarmıştı oysa...

elleri, ellerinde tutuğu sevgilisinden dakikalar önce ayrılmıştı...

taşıyamadı gecenin yükünü, 

biletini kesicilere bıraktı, 

lokomotife bedenini...

polislere ise dünün gazetelerini aramak kaldı...

ardındaki vagonlar-soru sorulmasa da--

onu hep iyi bildiler...

19: 20

yırtık montundan içeri süzülen yağmur n kadar mutluydu, 

sıcak bir yer ararda bulamazsan, 

ellerindeki kemana, 

dudaklarındaki notaya, 

cebindeki üç beş bozukluğa, 

önünden geçip gidenlerin sessiz çırpınışlarına, 

ve yağmura, 

hayatında yapmadığını yap...

boyun ey...

yeter ki

git ona, 

senede

bir

gün.........

20: 15

çöp tenekeleri, 

içlerinde ölü ağaç artıkları, 

baş sayfaya çıkmış irili ufaklı doluşmuş bir kaç resim, 

neyin üzerinde olduklarını bilmeden 20: 15 kaderlerini bekliyorlar, 

paramparça ipler içinde buruşmuş eller, 

kapıp götürüyor onları, 

çürüttüğümüz yürekleri ısıtmaya, 

ağaç memnun, 

biz mağlup, 

ama asıl

uzatmalarda yeniliyoruz, 

kaybetmenin çooook uzağında...

20: 50

öyle iki yüzlü insanlar gördüm ki, 

ne kadar da çoktular, 

valesi, kızı, papazı, 

king yaparlarken hayata

hepsi teker teker uyandılar rüyalarından, 

ilk elden batanlar, 

bitmeyen eller, 

bir düşeş uğruna, kararan aşklar

ve tekel’e emanet umutlar, 

kağıtlar hileli, 

zarlar kırıktı oysa... 

21: 15

mermer kaplı yerlerinde yüzlerce sevgilinin ayaklarını sürüyerek yazdıkları, 

ayrılık hikayeleri, 

bağırlarında, uğurlanan ölüler, 

baharlarında, karşılanan hayatlar... 

22: 05

o, gözlerinin ayrılığında, 

kırdığı camın hesabını verirken tanıdı seni, 

babasına, 

gözleri sürmeli acıydı yatağında seviştiği, 

9 yaş hayali yok muydu, 

bundan sonra kırılan her camın hesabını o verecekti, 

hayatı hiç tek yakalayamadı, 

ta ki sen kurtalan’da yitinceye kadar, 

13 yaş hayali var mıydı, 

böylece bütün ayrılıkların sorumlusu da bulunuyordu, 

döndüğünde çoktan seçmeli bir yanıttı, 

20.yaş gününde 20 koca yılı dolduracak kadar ağladı, 

çünkü yaş günüydü, 

sana beş kala yetişti gara, 

aradı, 

şahitliğini ben yaptım, 

sorduğu sorulara yaşlı kurtalan bile ağladı, 

cevabını raylara kazımaya gittiğinde, 

üzerinden, 

önce kurtalan.......

sonra sen, 

onu beş geçmiştin bile.......

22: 30

kağıtlara çizilen miller, 

gözlere çekilenden acı olunca, 

yazdığım sigaranın, 

kanser’e tutulmasına, 

ağlamak kalıyor

bize de...

23: 00

ellere teslim

rüyalarımda; 

bir başkaydı senin çekip gitmen, 

ne yardan geçebildiğim, 

ne aşağı düşebildiğim, ...

çise tadında bir tokattı attığın, 

benim olmasına o kadar da sevindiğim...

23: 15

senden bir saat önceyim, 

gidişinden o kadar sonra...

23: 30

koynumdaki yılana aşıktım ben, 

bunca yıl ekmeğini yediğim...

23: 45

ne yani şimdi sen, 

sevgili miydin, 

pardon, ben o tartışmanın yabancısıyım, 

tanrı misafiri diye andığın, 

inancının en yitik köşesi, 

yol arkadaşlığında unutma mevsimindeyken, 

üzerini örtmüştüm, 

dudaklarıma komşu olmuştu yanağın, 

uzun bi süre ellerindeydim, 

arkamdan aşklarımı destan

tenimde kalan tuzunu kara sevda lekesi bellediler, 

ayrılığında boynun kollarıma dolanırken, 

içimde mahkum edilmiş göz yaşlarımın cezası da 

müebbede çevriliyordu...

senin gibi ana yoktu, 

bağdat’ıda bulan olmadı zaten...

00: 10

çevirmenin notu ardı ilerledim sayfalar boyu, 

gün sana çoktan tesellilerini iletmişti, 

ben sona geldiğimde, 

bulutlar yağmur olmakta direnirken, 

sayfaları seller, 

ankara istanbul seferindeki kaza haberini, 

hava tahminleri almıştı, 

harflerden boğulan, 

üç ölüden kurtulan olmamıştı...

00: 30

taş bebeklerim ağardı ellerimde, 

kimliksizcesine sevdanda dolanırken, 

bir bencillik türküsü ağlar izlediğim şarkılar, 

gözlerim bir daha dolmamaya yemin ettiklerinde, 

bi demli çay üstü kuru simit olsalar da nemli mendiller, 

14 yazdır neler çektiğimi iyi bilirler, 

arkamdan orospu diye seslenen, 

yüzüme nice dağlar deviren, 

siz ölüler, 

aşklarım vagonlara hayran gece körlerinde, 

umut; 

hakkım belki helal olur size...

01: 15

rüyalarına şarkılar söyledim sen bi yerlerde unut diye, 

olmayan çocuklarım gözlerinde sükut diye, 

bitmeyen cümleler kapı kollarına takıldı, 

gözü yaşlı bu mevsim sana nereden satıldı, 

bak yine aynı yağmur yağıyor, 

tenimde hüzün eriyor...

işte gidiyor o nazlı kara tren, 

arkasında ölenleri bilmeden bilemeden............

02: 00

aşık olmadan şiir yazılmazdı, 

ölmeden yaşamakta kimden mirastır, 

bilinmez, 

senin için bitmem gerekliydi, 

ona da hiç başlayamadım...

02: 45

uzunca ayrılıklar yazıyorum şimdilerde, 

sevince pişmanlıklar, 

sen ayrılmadın, 

ben ayırmadım, 

hala karşılıklı bakışmalardayız, 

sen beni güldürüyorsun, 

tanrıda seni, 

hangimizin işi daha zor, 

kısaca zamansızlıklarda kalma, 

bitince mezarlıklarda...dün, boyumu aşıyorsun...

03: 15

bitez’deki yalısını göremeyenlerin, 

komşusunun adaklarında kaybolan adını unutanların, 

sevgilisi dağlara yaslananların, 

adı koyulmamış yıldızların, 

gelen kolcuların, 

sağlığına, 

sarhoşluğumun en acı türküsünde, 

nakarat olmam, 

bilmem kaçıncı bedduamın aşklara şayan yazgısı...', '09: 30 çaresiz,  yorgun,  her günün farklı bir hikayesiyiz,  n yazan belli,  n okuyan,  birden, geriye saymaya kalkıyoruz,  film bitse de,  ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağra']::text[], 8.5, '{"poet":"Yavuz Ağra","poet_slug":"yavuz-agra","theme":"Türk Şiiri","is_hero":false,"total_lines":340,"source_url":"https://www.antoloji.com/hareket-memuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz Fırtınalar Dibindeyiz', 'karadeniz-firtinalar-dibindeyiz-yavuz-agra-b475i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'daha dün demlenmemişti aksayan ayağımda, 

yoksulluk hükmünü kollarımda sürerken, 

deniz henüz ayrılmıştı nehirden, 

üzgündü hissediyordum dalgalarında ki yalansı maviliği, 

nazikçe okşadı ayağımı, 

çekip giderken ardından uykuyla bulanıklık arası seni gördüm rıhtımda...

saçların da üç yaz önce fırlattığım bakıştan nemli gibi geldi önce 

seni hiç tanımadığım da ardınca...

sahi nerdendin sen topal ayağımla birlikte mi yazılmıştın bana 

doğamama çilesi miydin yoksa güneşin 

hatırlar mıydın ölmeleri üç sayfa sonrasında romanlarda...

sorular bendeydi cevabı başka yazarlarda kitaplara konu...

rakı soframdaki arkadaşlarla tanıştırmalıydım seni öncesinde benliğimin....

şu sağ tarafımda gördüğün bir çift göz beş yıl önce geldiler buraya, 

hiç unutmadığım gecelerin mahzeninde gezer gibi hatırlıyorum...

açıkta batmıştı tekneleri evleneli üç koca gün olmasına rağmen...

kayadan mı yazgıdan mıydı -bana da söylememişlerdi-soğuk sulara gömülü vermişti tekne...yanlarından geçen ortanca bi kayık kurtarmış adamı, 

karısının da şişmiş kollarından çıkmayan bileziklerini...

canlı canlı iki kol bilezik...

üç günlük dünya...

bir çift göz sabaha karşı kıyıya vurmuş taşıdıkları son görüntü içine baktıkları üç günlük koskoca bir sevda karadeniz sonbaharında...

sol tarafımdakinin adı gördüğün kadardır...

bunlardan bi sene sonra buldum onu da 

iki aylık mıydı neydi dede diyesi gelmiş bana 

anasından boynunda ki leke babasından 

anasının kolsuz vesikası miras kalmış...

kendi anlattı...

 dedesi topalın biriymiş seneler evvel sahilde gezerkene vurulmuş tanımadığı bir sevdalıya 

rakı masasına davet etmiş onu arkadaşlarıyla tanıştırmaya...

iç artık sen de, bakma kim tarafından yazıldığına 

karadeniz böyle işte 

bir evvel iki sonra......', 'daha dün demlenmemişti aksayan ayağımda,  yoksulluk hükmünü kollarımda sürerken,  deniz henüz ayrılmıştı nehirden,  üzgündü hissediyordum da...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağra']::text[], 8.5, '{"poet":"Yavuz Ağra","poet_slug":"yavuz-agra","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/karadeniz-firtinalar-dibindeyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agoraya', 'agoraya-yavuz-agra-ti4aa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'neylesinler ki senden büyük aşkı, 

azla yetinir onlar, 

sen öldükten sonra sevmenin ne anlamı var, 

yine de yaşar onlar, 

taşında mezarınım üstümde kalıntı şiirler, 

duymadan biter bu şehirde geceler, 

yoldan geçip gidendirler, 

bi şey anlamasalar da yinede okur onlar...', 'neylesinler ki senden büyük aşkı,  azla yetinir onlar,  sen öldükten sonra sevmenin ne anlamı var,  yine de yaşar onlar,  taşında mezarınım ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağra']::text[], 8.5, '{"poet":"Yavuz Ağra","poet_slug":"yavuz-agra","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/agoraya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agoradan', 'agoradan-yavuz-agra-yae7u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uzakta kalan bir kışın ardından, 

susuz bebekler ölüme gidiyorlar, 

babaları arkalarından-ne kadar uzak olsa da- içiyor sağlıklarına, 

sözlerinde farklı geçmişlerin bedeli bozuk para kırıntıları, 

mezesi; saflığın beyazında peynir, -ilk çocuktan kalma-

karanlığın içinde su-daha nice çocuklara-

ağlamak istiyor plaklar engel oluyor, 

tarih bi kere daha ağlatmıyor erkek adamı, 

yazıları üç bahar önceki terklerinden bu yana uğramıyorlar, 

baharı takan yok zaten, 

sarhoşluk sevdayla sevişiyor, 

burası agora meyhanesi, 

yaşanmıyor artık, 

kalkıp gitmek istiyor ellerim, 

uzaklarda bir beste iç diyor gözlerindeki sevgilere....', 'uzakta kalan bir kışın ardından,  susuz bebekler ölüme gidiyorlar,  babaları arkalarından-ne kadar uzak olsa da- içiyor sağlıklarına,  sözle...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağra']::text[], 8.5, '{"poet":"Yavuz Ağra","poet_slug":"yavuz-agra","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/agoradan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Kim Öldürdü', 'beni-kim-oldurdu-yavuz-agra-i8uth', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'oysa ben seni bir kaç gün evvel öldürmüştüm, 

küvette boylu boyunca yatıyordun, 

saçlarında korkudan delicesine ağlayan, 

üç yıl önceki dudak izlerim, 

gözlerinde aynı hain umutsuzluk, 

buz kesmişti tenin, 

zalimin duası kabul olmuştu, 

atalar söyleyecek söz ararken, 

ben pişmanlıktan dönüş biletimi iptal ettiriyordum, 

gözlerim polise haber vermişti, 

seni ikinci kez öldürdüğümde, 

gökten nur yağıyordu bir katilin omuzlarına, 

korkudan zamanlar terliyordum, 

sen uğrunda ölünecek kadını oynuyordun...

kendine geldiğinde, 

öbür taraftan hala haber yoktu, 

dizlerini büküp bana git dedin, 

yol çok uzundu üzgünüm, 

dönemedim...', 'oysa ben seni bir kaç gün evvel öldürmüştüm,  küvette boylu boyunca yatıyordun,  saçlarında korkudan delicesine ağlayan,  üç yıl önceki duda...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağra']::text[], 8.5, '{"poet":"Yavuz Ağra","poet_slug":"yavuz-agra","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/beni-kim-oldurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden', 'i-cimden-yavuz-agra-9nmrd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'adam başı beş ayrılıktan, 

üç müebbet ediyorsun ben de, 

hep hatırladığım gibi kal bu gece yanımda, 

sabaha kadar yine bende büyü, 

geçmiş aralansın yüzümdeki dikiş izlerinde, 

yıktığın her gelecek için bir ömür borçlusun bana, 

her ömür için bir gece, 

satılan her beden senden bir parça taşıyor artık, 

sen ne kadar büyüksen gün o kadar uzun, 

alnımın ak lekesi, 

meyhaneler taşımıyor ki beni, 

sana kuruttuğun güllerden şiirler yazayım...', 'adam başı beş ayrılıktan,  üç müebbet ediyorsun ben de,  hep hatırladığım gibi kal bu gece yanımda,  sabaha kadar yine bende büyü,  geçmiş a...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağra']::text[], 8.5, '{"poet":"Yavuz Ağra","poet_slug":"yavuz-agra","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icimden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marsın Işıkları', 'marsin-isiklari-yavuz-agra-aer9p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'açmadığın mektuplarda biriktim, 

telefon icat olalı beri, 

sence azrail bir melek miydi, 

hatırlamıyorum, 

üzgünüm, 

zaten benim olanı almaya gönderdiğim için onu...', 'açmadığın mektuplarda biriktim,  telefon icat olalı beri,  sence azrail bir melek miydi,  hatırlamıyorum,  üzgünüm,  zaten benim olanı almay...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağra']::text[], 8.5, '{"poet":"Yavuz Ağra","poet_slug":"yavuz-agra","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/marsin-isiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur aşığından', 'yagmur-asigindan-yavuz-agra-zsomo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'açmadığın mektuplarda biriktim, 

telefon icat olalı beri, 

sence azrail bir melek miydi, 

hatırlamıyorum, 

üzgünüm, 

zaten benim olanı almaya gönderdiğim için onu...', 'açmadığın mektuplarda biriktim,  telefon icat olalı beri,  sence azrail bir melek miydi,  hatırlamıyorum,  üzgünüm,  zaten benim olanı almay...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağra']::text[], 8.5, '{"poet":"Yavuz Ağra","poet_slug":"yavuz-agra","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yagmur-asigindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevsende Olmaz', 'sevsende-olmaz-gurcan-soner-4shng', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek zordur

Sevsende olmaz sevmesende

Ama bu sana acı verir

Çeksende olmaz ölsende

Sence değermi bu kadar acıya

Aylarca çektiğin ızdıraba

Sonunda ne geçti eline

Yine yalnız bir odada bakıyorsun etrafa

Sana hep acı verdi 

Güldürmedi yüzünü acıya değermi

Sevsende olmaz sevmesende', 'Sevmek zordur Sevsende olmaz sevmesende Ama bu sana acı verir Çeksende olmaz ölsende Sence değermi bu kadar acıya Aylarca çektiğin ızdıraba ...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Soner']::text[], 8.5, '{"poet":"Gürcan Soner","poet_slug":"gurcan-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevsende-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-emel-cengiz-alkmv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umut tarlalarında nadasa bıraktığım

Her gün özlemiyle yatıp kalktığım

Uğrunda her çılgınlığı yaptığım

Sensin anlasana kavuşamadığım

Gün saydığım, gecelerce aradığım

Sen; gönlümden asla atamadığım

Gurur dediler adına, anlatamadığım

Sensin anlasana hiç ulaşamadığım

Gün gelecek yeşerecek umut tarlalarım

Tutsak olduğum yokluğuna alışacağım

Madden olmayacaksın ya; ruhuna sarılacağım

Gör bak, sensizliğin zincirlerini nasıl kıracağım.

Sorulmayan duygularımı anlatacağım

Varolmanın yollarını bıkmadan arayacağım

Hayatımın anlamlı bölümüydün, yaşadığım

Anılarımda kal; seni asla unutmayacağım.', 'Umut tarlalarında nadasa bıraktığım Her gün özlemiyle yatıp kalktığım Uğrunda her çılgınlığı yaptığım Sensin anlasana kavuşamadığım Gün sayd...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlasana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsaydım', 'olsaydim-emel-cengiz-cug57', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kuş olsaydım

Senin olduğun yerlerde özgürce uçsaydım.

Çaren olsaydım, beklediğin çarelerde

Umudun olsaydım, aradığın yollarda

Hedefin olsaydım, varacağın noktalarda

Kıskançlığın olsaydım, arzuladığın

Özlem dağların olsaydım, ağladığın

Emel''in olsaydım, varamadığın

Bedeninde olsaydım, ruhunda; 

Kanında, canında, nefes alışında olsaydım

Gülüm, seninle varolsaydım.

Acın olsaydım, kahrın ve sitemin

Tutkun olsaydım, yangının olsaydım

Ömür boyunca yanında olsaydım

Yaşamanın anlamını seninle yakalasaydım

Uç olsaydım, yasak olsaydım

Ne olursam olayım, tek seninle olsaydım.', 'Bir kuş olsaydım Senin olduğun yerlerde özgürce uçsaydım. Çaren olsaydım, beklediğin çarelerde Umudun olsaydım, aradığın yollarda Hedefin ol...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olsaydim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız', 'adsiz-gokhan-oktem-18smh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ateş düşünce toprağa, bir damla buhar yükseldi gökyüzüne

Kavrulurken torak şerriyle ateşin

Sardı dünyayı buhar bir  Sceheherazade esintisiyle

Korssakoff’dan bu güne

Ateş düşünce yüreğime, yükseldi atışı  nabzım saniyenin binde birine

Genişledi damarlarım ve yayıldı ateşli kanım 

Bedenimim en kuytu köylerine...

           

(İstanbul,17,10,1998)', 'Ateş düşünce toprağa, bir damla buhar yükseldi gökyüzüne Kavrulurken torak şerriyle ateşin Sardı dünyayı buhar bir  Sceheherazade esintisiyl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/adsiz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlıklardayım', 'cigliklardayim-gokhan-oktem-kck8r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çığlıklardayım, 

  Sessizliğin ortasında 

    Feryat figan dardayım

      Susmakta bir eylemdir bilirsin: eylemsizlik eylemi

                                                     Ki ben ne zamandır mutlak susuşlardayım 

Ayrılık ateşin közlerken yüreğimi

  Bil ki sana

    Bir susuş mesafesi

       Uzaktayım...

Çığlıklardayım

  Çiğ yüreğim 

    Çığlaşırken suskunluğuma inat

       Şiir çağlayanımda

         Şiirimsi dokunuşlardan bile yoksun

            Hece hece,  mısra mısra dardayım...

Çığlıklardayım

  Kaybolurken çığlıklarım 

    Susuş çağlayanımda

      Var la yok arasında çığlaşan bir dardayım...

(İstanbul,11,12,1998)', 'Çığlıklardayım,    Sessizliğin ortasında      Feryat figan dardayım       Susmakta bir eylemdir bilirsin: eylemsizlik eylemi                ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cigliklardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda Öykünüş', 'umuda-oykunus-gokhan-oktem-ehxnx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1- Umutsuzum dedi genç ihtiyar.  U-mutsuzum

Daha hayatının baharında olmasına bakmadan 

Gün ola harman ola sözüne aldırmadan

Damarlarında bir bahar tazeliğinde akan ve geçen zamana inat sonsuz bir devinimle çağlayan 

Umut ırmağına ‘bir kayadan zümrüt bir denize dalarcasına’ dalmadan, haykırdı genç adam: umut-suzum...

Yararınlar diye bir kavram yok ne zamandır bu hastalıklı ruhun derinliklerinde... 

Umut bırakırken yerini umutsuzluğa siliyor  yaşama ait belirtileri de sanki  tek kalemde 

Diye ekledi sonradan

Oysa ki, istediği tek şeydi yaşamak: 

‘Bir ağaç gibi tek ve hür 

Ve bir orman gibi kardeşçesine’

Fakat  ne orman olabilmişti geçmişinde ne bir ağaç, ne de  ağaç dalından bir sap olabilmişti bir baltaya... 

Ve şimdi sapı ağacında, baltayı yerinde bırakmış haykırıyordu...

U-mut-suz-um...

...................0000.....................

2- Dikti gözlerini  ufka ihtiyar genç

Vakit tamamdı. Dayadı sırtını kayalıklara

‘kuruldu guruba karşı son demlerini keyfince’

Çekti alabildiğince vücudunu bir aziz sevgili gibi okşayan rüzgarı ciğerlerine

‘Yaşamak bu’ dedi

Süzdü ışık demetlerini göz siperlerinde, el verdi ruhunu guruba bir dem

‘Yaşamak bu’ dedi

Hissetti mavinin her tonunu gittikçe yaklaşan, yaklaştıkça uzaklaşan dalgaların deviniminde 

Ve titredi bir an karşısına dikildiği doğanın haşmetiyle

‘Yaşamak bu’ dedi

Kapadı gözlerini bir an ve  topladı güllerini anı bahçelerinin derin ve mesut bir gülümsemeyle

‘Yaşamak bu’ dedi 

Ve son kez yaslandı kayalıklara, hissettikleri karşısında kas katı kesilmiş vücuduyla bir kaya gibi...

‘Yaşamak bu’ dedi

Ve dikti gözlerini umuda, umudun sonsuzluğuna

‘Bedeni ağırlığını yitirmiş, beyni düşünme yetisinden uzaklaşmıştı’

Var la yok arasında bir tanımsız boyutta, bir an bile sürmeyen sonsuz bir zaman aralığında 

Tüm benliğini duyumsayarak

‘İşte yaşamak bu’ dedi

Ve ihtiyar genç kurtularak bedenini sımsıkı  kavrayan kayalıklardan bıraktı kendini hiç bilmediği  uzak ama mutlak umutlara

Ve süzülürken umut sonsuzluğunda haykırdı ilk ve son kez... 

‘Umut her daim umuttur güneşin doğduğu yerde

Mesele, içimizdeki bir kıvılcımı güneşe dönüştürebilmekte

Yani yürekte...’! 

‘Var olan tek şey bu’ dedi...

(İstanbul, Kasım 1998)', '1- Umutsuzum dedi genç ihtiyar.  U-mutsuzum Daha hayatının baharında olmasına bakmadan  Gün ola harman ola sözüne aldırmadan Damarlarında bi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/umuda-oykunus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama Dair', 'yasama-dair-gokhan-oktem-esv1f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat bu arkadaş

Yaşamak her şeye rağmen güzel! 

Gel sözümü dinle; 

Sil ruhundan ümitsizliği, 

                    Kini

		Nefreti...

Işıl ışıl bak yarınlara

  Sevgiyle yaklaş insanlara

     Sev onları

        Güven onlara...

Paylaş neyin varsa

İçinden kopup gelen her şeyi

Dene almadan vermeyi

Unutma ki vermek almaktan zordur.

Unutma ki gönülden vermenin 

    Verebilmenin özünde bin bir erdem gizlidir.

İnsanları koşulsuz ve beklentisiz, 

    Yani sebepsiz sev; 

		Sev, insan oldukları için, 

		Sev, sende bir insan oluğun için, 

		Sev, varlığını sevdiğin için, 

Çalış, didin 

Soluksuz üretmeyi dene

Göreceksin ki o zaman 

Sevgi fışkıracaktır yüreğinden hiç bitmeyen...

Korkma incinmekten

Sevilmeyeceğini de hiç düşünme

Sadece yaşa

İçinden geldiğince...

Sevgi sonsuz bir ummansa açıl açık denize

Düşünmeden fırtınayı, tufanı

Varsın kopsun kasırga, 

Varsın dolsun gemin amansız dalgaların savurduğu suyla

Ümit et yeter, 

Yaşama inancını yitirme asla

Elbet varacaksın bir gün 

Mutluluğun simgesi dingin bir limana 

Hiç beklemediğin bir anda.

Bilirsin ki demir atıyorsundur

Yeniden açılmak için azgın sulara.

Bilmeden yaşayacaksın arkadaş! 

Fakat bileceksin bilmeden yaşadığını; dolu, dolu

İşte bu bilgisizliğin belirsizliği

İtecek seni ileri, 

	Hep ileri...

Sonsuz bir arayıştır bu sürecek hep 

Varlığın ve yokluğun bilinmezliği

Ve bilinmezliğin gizemlerine yol alan

Bu menzilsiz yaşam yolculuğu

(İstanbul,08,01,1998)', 'Hayat bu arkadaş Yaşamak her şeye rağmen güzel!  Gel sözümü dinle;  Sil ruhundan ümitsizliği,                      Kini 		Nefreti... Işıl ış...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/yasama-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-gokhan-oktem-nz691', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ılık rüzgar eser

Ruhumda bir eski ezgi titrer

Gözlerim dalıp gider uzaklara

Ve bir uzun yolculuk başlar

		Geçmişten geleceğe.....

(İskenderun,31,07,1997)', 'Bir ılık rüzgar eser Ruhumda bir eski ezgi titrer Gözlerim dalıp gider uzaklara Ve bir uzun yolculuk başlar 		Geçmişten geleceğe..... (İsken...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yolculuk-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-gokhan-oktem-ulocd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Varlığın ateş pahası

Gücüm yetmiyor sahip olmaya

Her şeye alışıyor insan 

Yokluğuna bile.... Zamanla...! 

(İstanbul,20,12,1997)', 'Varlığın ateş pahası Gücüm yetmiyor sahip olmaya Her şeye alışıyor insan  Yokluğuna bile.... Zamanla...!  (İstanbul,20,12,1997)...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zaman-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-gokhan-oktem-nm1pl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşam apayrı bir şey

Koca bir bilinmeyen

İnsan bu bilinmeyen içinde bir denklem

Bir denklem ki çözümlenemeyen

Yaşam sonsuz zamanda bir nokta

	Başı sonu bir anlamda belirsiz 

Bizleri hayata bağlayan bir şey varsa o da

	Yarınlara dönük ümitlerimiz

Arayışımızsa bir mutlak belirsizlik içinde 

	Kendi bilinmeyenimiz....

(İstanbul,21,01,1998)', 'Yaşam apayrı bir şey Koca bir bilinmeyen İnsan bu bilinmeyen içinde bir denklem Bir denklem ki çözümlenemeyen Yaşam sonsuz zamanda bir nokta...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasam-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yansıma', 'yansima-gokhan-oktem-n320f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su akar ben bakarım

Suda kendimi ararım

Ben akar su olurum 

Ağlar, ağlar durulurum

Ben akarım su bakar

Göz yaşımda boğulurum

Su akar ben olurum

Suda kendimi bulurum..........

(İstanbul,31,08,1998)', 'Su akar ben bakarım Suda kendimi ararım Ben akar su olurum  Ağlar, ağlar durulurum Ben akarım su bakar Göz yaşımda boğulurum Su akar ben olu...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yansima-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefesin nefesime karışınca', 'nefesin-nefesime-karisinca-gokhan-oktem-tn4et', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nefesin nefesime karışınca nefesim

	Sevda kokuyor...

Nefesimde nefesin bir azgın anafor ki

	Tek nefeste ciğerlerim söküyor

Nefesin sevişirken nefesimle nefsim

	Nefsi müdafaada nefes nefese kalıyor...

Ve nefes nefeseyken nefsim

	Bir paradoks yaratıp

	Nefes bolluğundan; nefessiz, yüreğime vuruyor...

Velhasıl, nefesin nefesime karışınca, nefsim

	Bir nefeste nefes nefese sonum oluyor...

(İstanbul,29,04,1998)', 'Nefesin nefesime karışınca nefesim 	Sevda kokuyor... Nefesimde nefesin bir azgın anafor ki 	Tek nefeste ciğerlerim söküyor Nefesin sevişirke...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nefesin-nefesime-karisinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp değildi yaşadıklarım', 'kayip-degildi-yasadiklarim-gokhan-oktem-whpfp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kayıp değildi yaşadıklarım

Her yaşanan bir zamanın hırsızı

Suyu gider kumu kalır misali

Yaşananlar zamanın kirli demi

Kayıp değildi yaşadıklarım

Ben fidandım, zaman balta, budandım

Kah acıya kah sevince bulandım 

Acı sevinç öğretti bana beni 

Kayıp değildi yaşadıklarım

Derler, ‘öğrenmenin türlü yolu var’, 

‘Bir nusubet bin nasihatten yeğmiş’

Ki öğrendiklerim hep nusubetlermiş

Anladım ki sade bilmek yetmiyor

Bilgi aklı yaşamak gönlü sular

Her bilmenin birde yaşanası var

Yaşamadan bilmek para etmiyor

Kayıp değildi yaşadıklarım

An’ da an’ ı gün’ de gün’ ü yaşadım

Bilirdim ki yaşamaktır savaşım

Aklım duru, gönlüm dolu, dik başım

Kayıp değildi yaşadıklarım

Kayıplarımdan doğdu hep kazanımlarım

Geçmişim hoş anılar yarınım umut dolu

Ne dünü ne yarını ben an’ ı  an yaşarım

(İstanbul,10,12,1998)', 'Kayıp değildi yaşadıklarım Her yaşanan bir zamanın hırsızı Suyu gider kumu kalır misali Yaşananlar zamanın kirli demi Kayıp değildi yaşadıkl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kayip-degildi-yasadiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın ölüm olsun', 'adin-olum-olsun-gokhan-oktem-9cov8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ötesi var mı ey nazlı dilber

Ötesi var mı? 

Ruhum dibe vurmuş

Ölüm kol gezmiş ruhumun en mahrem yerlerinde

Vicdanım ölümü kovalamış

Ve bilmem kaç ay, kaç gün,  kaç saat

Ve dahası kaç dakika, saniye ve salise...

Ölümle hayat arasındaki o ip ince çizgide

Kimi zaman ölümle kol kola hayata küsmüş

Kimi zaman ölüme inat hayata dört elle sarılmış

Ama dengesiz

Ama bütün bir belirsizlik, 

		Ümitsizlik, 

		Amaçsızlık ve 

		Anlamsızlık içinde gidip gelmişim

Ötesi var mı ey nazlı dilber ötesi var mı? 

Acılar volkanına kendimi acımadan atmışım

Hayatın baharında ölümü tatmışım

El sallamışım bayramlık elbiselerim içinde

Nazlı bir dilber gibi ölüme 

El sallamışım öpücükler göndererek...

Ötesi var mı ey nazlı dilber ötesi var mı? 

Yaşamışım 

Doyasıya yaşamışım

Bilmem kaç ay sorgularda kalmışım

Sorgularım ölümün kıyısında yapmışım

Ölümle randevuma çekinmeden giderken

Son anda duraksayıp bir müddet

Bir azgın dalga gibi şahlanıp köpürerek

Ölümden ötesi yok sezmişim...

Al başını git uğurlar olsun

Var mutlu ol bensiz canın sağ olsun

Acıda sevinç de ölüme kadar

Sevgi de nefret de ölüme kadar 

Senle de sensiz de ölüme kadar

Ne ben sana mahkum ne de sen bana

Var git hayat yolun engelsiz olsun

Var git hayat bağın güllerle dolsun

Ayrılmak zor geldi beklemek acı

Aşkın gerçek olsa böyle olmazdı

Var git nazlı dilber benden uzak ol

Bu son sözüm sana bu son haykırış

Ölüm mutlak sondur mutlak ayrılış

Adın ölüm olsun benden uzak ol

Var git ölüm var git benden uzak ol

Her ne olursan ol benden uzak ol....

(İstanbul,01,12,1997)', 'Ötesi var mı ey nazlı dilber Ötesi var mı?  Ruhum dibe vurmuş Ölüm kol gezmiş ruhumun en mahrem yerlerinde Vicdanım ölümü kovalamış Ve bilme...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/adim-olum-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-gokhan-oktem-a24gp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Belirsizliğe gebe apansız inen geceye inat 

Doğan her yeni günün ilk ışık kervanıyla

Huzuru, mutluluğu ve bir taze bahar kokan

Umutları da beraber getirmesi dileğiyle...

(İstanbul,31,01,1998)', 'Belirsizliğe gebe apansız inen geceye inat  Doğan her yeni günün ilk ışık kervanıyla Huzuru, mutluluğu ve bir taze bahar kokan Umutları da b...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dilek-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Gözlüm', 'deniz-gozlum-gokhan-oktem-h1h6u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tek tesellim 

Bende kalan bir seki resim

O resimde beni benden alan

Gözlerin

	Ah o gözlerin

Maviş gözlerin

			Derin gözlerin

				Deniz gözlerin

Deniz gözlüm

	Bilir misin? 

Gözlerinde dalıp gidiyorum uzaklara

Gözlerinde süzüyorum mavilikleri

Ve gözlerinde buluyorum kendimi...

En acılı anımda en şefkatli kucak

En yalnız anımda en candan dost eli

Gözlerin

	Ah o gözlerin

		Maviş gözlerin

			Derin gözlerin

				Deniz gözlerin

Deniz gözlüm

	Bilir misin? 

Gözlerin, yüreğinin bana açılan penceresi

Gözlerin ruhunun en güzel ifadesi

Deniz gözlüm

Söz ver  bana

Kapama gözlerini

(Amasya,30,04,1997)', 'Tek tesellim  Bende kalan bir seki resim O resimde beni benden alan Gözlerin 	Ah o gözlerin Maviş gözlerin 			Derin gözlerin 				Deniz gözle...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/deniz-gozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryad', 'feryad-gokhan-oktem-cydo7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acılarım bir okyanus misali

Feryadım dalga, dalga.

Yalıyor kıyılarını

	Yalıyor yüreğinin

O yürek ki

	Mağrur ve gaddar ve zalim

O kıyılar ki

	Dik ve keskin ve yekpare kayadan

Kırıyor,  yok ediyor  feryat dalgalarımı

	Feryadıma aldırmadan...! 

	Yüreğin taş mı senin...? 

(Amasya,13,05,1997)', 'Acılarım bir okyanus misali Feryadım dalga, dalga. Yalıyor kıyılarını 	Yalıyor yüreğinin O yürek ki 	Mağrur ve gaddar ve zalim O kıyılar ki ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/feryad-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firardayım', 'firardayim-gokhan-oktem-c4xnr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimi tutsak ettin

Ey deniz gözlü yarim

Sevgime haksızlık ettin

Bil ki gönlü firardayım.

Elim varmaz arayamam

Halin hatrını soramam

Hiç düşünmeden duramam

Bil ki aklı firardayım

Sevgin giriyor kanıma

Kastın bilesin canıma

Elim açtım yaradan’ a

Bil ki canı firardayım...

(İskenderun,03,05,1997)', 'Yüreğimi tutsak ettin Ey deniz gözlü yarim Sevgime haksızlık ettin Bil ki gönlü firardayım. Elim varmaz arayamam Halin hatrını soramam Hiç d...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/firardayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geride kalan', 'geride-kalan-gokhan-oktem-1lt5i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce güven kaybedilir

Sonra saygı

İçten içe bir şeyler kemirir yüreğini

Her şey yavaş, yavaş ölür

Ve bir gün gelir

Taparcasına sevdiğin

Yüreğindeki tüm sevgiyi verdiğin

Ruh-u meleğin

Bir yabancı olup çıkıverir karşına

Tanıyamazsın

Hiçbir şey anlayamazsın

Sorarsın kendine

Ne kaldı diye geride

Sevgiye dair

Seviye dair

O zaman, işte o zaman anlarsın

Yaşananlardır kalan 

Koca bir aşka dair

İşte o yaşananlar 

Her şeye rağmen 

Saygıyı hak eder..........

(İstanbul,10,08,1997)', 'Önce güven kaybedilir Sonra saygı İçten içe bir şeyler kemirir yüreğini Her şey yavaş, yavaş ölür Ve bir gün gelir Taparcasına sevdiğin Yüre...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/geride-kalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurur', 'gurur-gokhan-oktem-fuw04', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senle başlar ve yine senle biterdi ümitlerim

Hayal gücümün sınırlarını çizerdi aşkım

Bilmem ki  neyleyim...

Bilsen sana kendimi ne denli hazırladım

Ama sen öyle kırdın ki ümitlerimi 

Yazık...

Ne ben sevebilirim başka birini 

Seni sevdiğim kadar

Bilirim

Ne de sen...

Yazık....

Açıklaması zor bir nefret, bir kin besliyorsun içinde

Gururun nefretinin önünde bir perde sadece

Kurbanı ben oldum

Olsun...

Bırak kalkanın olayım

Seni mutlu edecekse

	Rahatlatacaksa seni

Bırak nefretinin ateşinde yanayım

Bırak günah keçin olayım

Bu kadar mı zor anlaşılmak...

Bak anlatıyorum her şeyi

	Anlatabiliyorum artık

Demek ki imkansızı başarmışım

Aşılmazı aşmışım

Gemim açık denizde kasırgaya yakalanmış

Su almış çelik gövdem

Neredeyse batmışım

Ama ben direnmişim yılmadan

Ölüme savaş açmışım

Onca şey yaşamışım lakin

Mühim olan ben artık limana varmışım

Bırak da hedefimi vurayım

Kabul et sevgimi

Anla sebeplerimi

Ve affet artık bu seven kalbi

Ya da sil

Gerçeklerim rahatsız ettiyse seni

Sil beni

Yeter ki bileyim her şeyi

Kendimi bildiğim gibi....

Gel yazık etme

Beni kaybetme

Ve beni de senden mahrum etme

Gel etme

Sevdanı ilkel benliğine

	Gururuna kurban etme....

				

(İstanbul,21,02,1998)', 'Senle başlar ve yine senle biterdi ümitlerim Hayal gücümün sınırlarını çizerdi aşkım Bilmem ki  neyleyim... Bilsen sana kendimi ne denli haz...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gurur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişim', 'degisim-gokhan-oktem-vucw6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen beni gerçekten sevdin mi? 

Varlığımı yürekten özledin mi? 

Yokluğum acı verdimi sana? 

Keşke yanımda olsaydın dedin mi? 

Yoksa unutmak bu kadar kolay mıydı? 

Seviyorum derken hislerin yalan mıydı? 

Her şey toz pembe gelirken bana

Yoksa aşkım sana zindan mıydı? 

Sakladığın meğer ne çok şey varmış benden! 

Oysa, sevmek koşulsuz teslim olmaktır derken

Zaman neleri aldı götürdü bizden

Ne sen o eski sensin şimdi  ne de ben o eski ben...

(İstanbul,12,11,1998)', 'Sen beni gerçekten sevdin mi?  Varlığımı yürekten özledin mi?  Yokluğum acı verdimi sana?  Keşke yanımda olsaydın dedin mi?  Yoksa unutmak b...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/degisim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-gokhan-oktem-dfgqn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat böyledir dostum

Gelir geçer anlamsızlık içinde

Hayat böyledir dostum

Ararız mutluluğu anlamsızlık içinde

Anlardır yaşanacak

Ne geçmiş ne gelecek

Mutluluğa giden yoldur

Şu anı yakalamak

Hayıflanmak boşuna 

Keşkeler ne anlamsız

Anlamlı kılan şey dünü

Ders almaktır geçmişten

Tekrardan kaçınmak için

Bu günü yaşarken

Geçmişi geçmişte bırakmaktır bu günü yaşamak

Mutluluğa giden yoldur bu günü yaşamak

Hayat anlardan ibaret

Şu an bir an sonra dün

Gömülmek ‘keşke’ lere 

Olmaktır hayata küskün

Kendinle barışık ol

Değerlerini yaşa

Gerçeklerini kabul et 

Gerçeklerini yaşa

Seni sevenler zaten olduğun gibi sever

Sevmeyenleri boş ver sen bütünlüğünü yaşa...

Koşma mutluluğun peşinden bırak o gelsin sana

Sen, sen olduğun sürece sevilirsin herkesçe

Sakın başkasına özenme

Yaşa kendi kendince

Yüreğine kulak ver ve aklına eşitle

Aynı ses çıkıyorsa yürekten ve akıldan

Bil ki doğru yoldasın sen, sen oldun o zaman

Dürüst olmaktır kendine bu günü  yaşamak

Özü sözü bir olmaktır bu günü yaşamak

Sevmektir sevilmektir paylaşmaktır sevgiyi

Bu günü yaşamaktır zaten sevgiyi paylaşmak

Dünü dünde bırakıp bu günü yaşamak

Yaşamaktır gönlümüzce dolu dizgin yaşamak

Doğuştan hakkımız zaten insan gibi yaşamak....

(İstanbul,21,01,1998)', 'Hayat böyledir dostum Gelir geçer anlamsızlık içinde Hayat böyledir dostum Ararız mutluluğu anlamsızlık içinde Anlardır yaşanacak Ne geçmiş ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/hayat-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkiben', 'i-kiben-gokhan-oktem-sdd7n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sus, konuşma artık, tek kelime etme

Bırak sessizlik tütsülensin ruhlarımızda

Yol ver ıssızlığa, 

Başıboş bırak sonsuzluğu, 

Varlığınla zincirlere vurma yokluğunu.

Hak tanı eylemsizliğe bir kez, 

Dokunuşlarını dondur, 

Gözlerini kullanamadan suskunluğunla ağla.

Sal ümitlerini uçsuz bozkırlarıma, 

Algılarından uzak sezgilerinle yaşa.

Unut bildiklerini hiç bilmediğini farz et, 

Bilmedik bir ben içinde bilinmezliği yaşa...! 

İndir kapaklarını gözlerinin, küçülsün göz bebeklerin, 

Otur hareketsizce kenetlensin ellerin.

Ey başını önüne, duymasın kulakların, 

Kapa algılarını tümüyle dış dünyaya.

Ve başla o an’ a dek başlamaya korktuğun yolculuğa.

Ulaş ruhunun derinliklerinde ki ulaşılmaza.

Orada ne dağlar var ne denizler

Ne de adını bile bilmediğin canavarlar

Orada bir sen varsın ve seni sen yapan mazin

Savaşırsın kendinle; sen sana karşı durur.

Bilirim kolay değil benliğinle yüzleşmek

Bugünün ışığında geçmişten hesap sormak.

Bir büyük savaştır bu iki ben arasında

Ben, ben’ e karşı benliğini savunur 

Oysa ki savunduğu benliğinden ötedir.

Saklı gerçekler varsa iki ben arasında 

Gerçek ben’ e ulaşmak hiç de kolay değildir.

Öyle bir savaştır ki bu sonucu çelişkidir; 

Yenen ben yengisiyle yenilenden mağluptur.

Fakat bilinç gelişir. Kazanan tek zamandır.

Yenginin akıbeti zamana terk edilir.

(İstanbul,18,05,1998)', 'Sus, konuşma artık, tek kelime etme Bırak sessizlik tütsülensin ruhlarımızda Yol ver ıssızlığa,  Başıboş bırak sonsuzluğu,  Varlığınla zinci...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ikiben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi', 'neydi-gokhan-oktem-wgwnw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilemezdim senle ben

Bu kadar az zamanda 

Öylesine ateşli sevişip ayrılacağız

Bilemezdim seni ben

Bu denli derinden

	Ve yürekten

		İçtenlikle seveceğimi

			Hatta sevmekten öte

				Bir bütünlük içinde

					Ayrılmaz bir parçan olup

						Bağlanacağımı...

Şimdi sorguluyorum geçen güzel günleri

Arıyorum bir cevap ilişkimize dair

Neydi bizi bu denli derinden bağlayan

	Ve ayrılık acısıyla yüreğimi dağlayan? 

		Gözlerimin buğusunda iki boncuk tanesi

			Bendini yıkan bir azgın sel olup çağlayan...

Neydi aramızdaki bağlara sebep olan? 

Neydi hiç beklemediğim bir anda

Hiç kopmaz zannettiğim bu bağları koparan? 

Neydi bizi zamanla iki yabancı kılan

Ve şimdi böyle bir uçtan bir uca savuran? 

Neydi canım? 

Neydi bizi böyle derbeder eden? 

Neydi söyle? 

Neydi? 

Ne? 

(İstanbul,10,10,1998)', 'Bilemezdim senle ben Bu kadar az zamanda  Öylesine ateşli sevişip ayrılacağız Bilemezdim seni ben Bu denli derinden 	Ve yürekten 		İçtenlikl...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/neydi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odamdaki Islak Işık', 'odamdaki-islak-isik-gokhan-oktem-modyg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Odamdaki ıslak ışık

Yanık, yanık dol gönlüme

Islat içim kuraklığın

Baş kaldırayım ölüme

Ben sevdamı terk eyledim

Sevdam benden geçer oldu

Bir beni ben, ben eyledim

Bir benin yarısı soldu

Odamdaki ıslak ışık

Islaklığın sür tenime 

Salsın umut fidanları

Köklerini bedenime

(İstanbul,05,07,1999)', 'Odamdaki ıslak ışık Yanık, yanık dol gönlüme Islat içim kuraklığın Baş kaldırayım ölüme Ben sevdamı terk eyledim Sevdam benden geçer oldu Bi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/odamdaki-islak-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölçü', 'olcu-gokhan-oktem-owugq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölçülü olmayı öğrettin bana sen

Çelişsen de kendinle yine direttin bana

Ölçülü sevda

Ölçülü sevgi diye

Hani ya, sevgide ölçü olmazdı? 

Hani ya, ölçülü sevgi, sevgi sayılmazdı? 

Ölçüsüz acılar yaşattın bana

Ölçüsüz sevgi deryalarında

Hani alışmıştım ya ölçüsüzce dalmaya

Ölçüsüz derinliklerine aşk deryasının

Hesap bile etmeden tüpümdeki havayı

Zaman ve mekan atlatırcasına

Ölçülü olmayı unutturmuştu bana ölçüsüz sevgim

Ve onca sevgiyi barındıran yüreğimeydi

Beslediğim o ölçüsüz güvenim

Ve ölçüsüz derinliklerinde vurgun yediğim güne kadardı ölçüsüzlüklerim.

Olsun, varsın.

Vurgun dediğin vurur geçer

Lakin, ölçüsüzlüğe ölçü vurmak

Yüreği dizginlemekten geçer

Yar... Yar...

Kolay mı yüreğe söz geçirebilmek? 

Deryayı kurutmak

Sevdayı sulandırmak gerek

Hesap kitap meselesi bu

Kaç dirhem sevgi kaç dirhem acı eder

Tartmak gerek

Yüreği santimetrekarelere bölüp

Kat karşılığı kiraya vermek gerek

Ölçülü sevgi çıkar barındırır içinde

Çıkarların çatıştığı yerde durmak gerek

Oysa yürek ölçüsüzce savrulan bir azgın küheylan

Dizginleyebilmek zor olsa gerek...

Ya koparırsa dizginleri. O zaman...

Gözünü bile kırpmadan

	Ve asla dönüp arkana bakmadan

		Şakağına bir kuşun sıkabilmek gerek

			Yar... Yar...

Onun için bile

Mangal gibi  bir yürek gerek...

							

(İstanbul,21,02,1998)', 'Ölçülü olmayı öğrettin bana sen Çelişsen de kendinle yine direttin bana Ölçülü sevda Ölçülü sevgi diye Hani ya, sevgide ölçü olmazdı?  Hani ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/olcu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın', 'sakin-gokhan-oktem-5tdsp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim gözlerini öpünce 

Sakın kaçırma

Ya da bakma benden taraf

Nefes bile alma

Süzül yılan gibi sessizce yanımdan ama 

Sakın kaşlarını çatma

Ya da bir taze bahar gibi aç gözlerimde 

Şelaleler gibi çağla

Unutma yaşananları

Ya da koşulsuz kabullen 

	Hiçbir şey hatırlama...

Ya sev 

Ya nefret et ama

Sakın tereddütte kalma

Ya göm ya çıkart ama

Sakın ateşe atma

Ya tut ya bırak ama 

Sakın peşimden koşma

Ya son kez konuş ya sus ebediyen ama 

Sakın acıma

Ya öl ya öldür ama 

Sakın acı çektirme

	Acı çektirme, 

	Acı çektirme sakın.....

(İstanbul,29,11,1997)', 'Gözlerim gözlerini öpünce  Sakın kaçırma Ya da bakma benden taraf Nefes bile alma Süzül yılan gibi sessizce yanımdan ama  Sakın kaşlarını ça...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sakin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son nokta', 'son-nokta-gokhan-oktem-sn1i6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde verilmemiş bir kararın sancısı kabarıyor

Karnı burnunda ümitlerim doğmadan ölür

Sorgularım ayları, yılları kovalıyor

Son noktayı koymaya cesaretim yok

Gırtlağıma ulaşmadan tükenir çığlıklarım

Susmayı kabullenmek sandığım günden beri

Haykırmalıyken kendime sakladığım gerçeği

Geciken tespitlerim çaresizlik kokuyor

Kabullenmekten  kaçıştan başka bir şey değildir

Varolan gerçekleri tespitte gecikmeler

Oysa karar daha başlangıçtan bellidir

Beklemek, inkar etmek sonucu ne etkiler...! 

Doğum ölümün kaynağıdır doğada

Yaşam ve ölüm tek vücut ve gerçektir

Her bitiş bir başlangıç barındırır içinde 

Noktayı koyabilmek için bunu bilmek gerekir.

(İstanbul,21,02,1998)', 'İçimde verilmemiş bir kararın sancısı kabarıyor Karnı burnunda ümitlerim doğmadan ölür Sorgularım ayları, yılları kovalıyor Son noktayı koym...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-nokta-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütünlük', 'butunluk-gokhan-oktem-pr49n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kolay mı kabullenmek

	Kabullenebilmek...? 

Kolay mı aşkım bu kadar büyükken 

	Seni sevmiyorum demek...? 

Kolay mı onca sevgiyi kalbime gömü

	Arkamı dönüp gitmek...? 

Kolay mı yaşadıklarımızı hatıralarımdan silmek...? 

Kolay mı seni başka kollarda görmek...? 

Kolay mı tutkularıma direnmek, alışkanlıklarımı yenmek...? 

Kolay mı senle dolu yılları sildim diyerek silmek...? 

Kolay değil canım inan hiç kolay değil...! 

Her şeyinle iz bırakmış, çentik atmışsın ruhuma

Tutkulu aşkımla işlemişsin bilinç altıma.

Ben sen olmuşum sen de ben kadar ben, 

Nerede sen bitersin, nerede başlarım ben, 

Bir grift bilmece ki çözmek hiç mümkün değil.

Ayrılışın her şeyi bitirmedi ruhumda, 

Dil başka söylüyor şimdi yürek bir başka

Yokluğun bir beni aldı götürdü benden 

Bir ben kaldı geride ki  kalan ben, ben değilim

Yokluğunla arayışım derinleşti ruhumda

Kalmadı çalınmadık kapı bilinç altımda.

Hiç bilmediklerim çıktı bildiklerimden fazla, 

Bir ben tanıdım ki bildik ben’ e yabancı.

Birleştirmeye çalıştım bildik bilmedik ben’ i, 

Bir bütün edemedim bir parçası eksikti.

O eksik ki eksiltir beni ben yapan beni, 

Ve eksisiz tamamlar seni sen yapan sen’ i

Anladım ki bütünlük kurulmaz hiç ruhumda, 

Seni ben yapan benden ruhum ayrı kaldıkça.

Biz ki etle tırnakken iki yabancı olduk, 

Ayrı yollara sapıp ayrı dünyalar kurduk.

Şimdi benim dünyamda bir seni ben yapan sen

Ve senin dünyanda da bir beni sen yapan ben kadar

Bir boşluk hep var olacak

Ve sürdükçe bu ayrılık, 

Ne bu boşluk dolacak, 

Ne de ruhlarımızda bir bütünlük olacak...! 

(İstanbul,17,05,1998)', 'Kolay mı kabullenmek 	Kabullenebilmek...?  Kolay mı aşkım bu kadar büyükken  	Seni sevmiyorum demek...?  Kolay mı onca sevgiyi kalbime gömü ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/butunluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlişki', 'i-liski-gokhan-oktem-v6nnq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acemi öpüşler girdabında savrulan

İki ruh iki bedenin

Uzak sevişlerinin 

Kıvranışıydı ilişkimiz

Hem çok yakın hem uzak oluşumuz

Severken terk edişimiz

Sorgusuz sualsiz

Ve zamanla seviyesiz

Boynu bükük kalışımız.....

İşte bizim hikayemiz...........

(Amasya,  05,08,1997)', 'Acemi öpüşler girdabında savrulan İki ruh iki bedenin Uzak sevişlerinin  Kıvranışıydı ilişkimiz Hem çok yakın hem uzak oluşumuz Severken ter...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iliski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-gokhan-oktem-ajlwb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey karanlık ufkumda parlayan yıldız

Kıblem senden yana sen yerinde kal

Varsın batsın güneş bir daha hiç doğmasın

Varsın zifiri karanlıklar hükmünü sürsün bugün

Varsın ışık demetin ulaşmasın gözüme

Kaparım gözlerimi yine bulurum seni 

Ey karanlık ufkumda parlayan yıldız

Ruhum senden yana sen yerinde kal

Yeter ki hissedeyim, varlığını bileyim

Isıtır bu his beni, aydınlatır her zaman

Varlığın varlığımın var oluş kaynağıdır

Sen var ol ben bileyim

Bu bile yeter bana

                                                          

(İstanbul,11,12,1998)', 'Ey karanlık ufkumda parlayan yıldız Kıblem senden yana sen yerinde kal Varsın batsın güneş bir daha hiç doğmasın Varsın zifiri karanlıklar h...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seslenis-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni bir gül görmesem', 'seni-bir-gul-gormesem-gokhan-oktem-b6mia', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni bir gül görmesem, kıyardım sevmelere, 

Seni bir gün görmesem, gün görmem, dayanamam..

Günüm yok gül dudaklım, dikenlerin yüreğimi deşmesin

Gecem yok bahar yüzlüm, uykularım hayallerime yenik…

Bir gül desem, sen bir gülsen

Güllerinden bana versen..

Ben geceysem, karanlıksam

Işığımı sende bulsam

Ben aşıksam, sırılsıklam

Sen cihansan gül koynunda

Neyleyim….? 

(İstanbul,2001)', 'Seni bir gül görmesem, kıyardım sevmelere,  Seni bir gün görmesem, gün görmem, dayanamam.. Günüm yok gül dudaklım, dikenlerin yüreğimi deşme...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-bir-gul-gormesem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamıyorum', 'anlatamiyorum-gokhan-oktem-ay4oy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlatsam beni anlayabilir misin...? 

Çektiğim acılardan bihabersin

Tatmadığın duyguları hiç hissedebilir misin? 

Ben ki huzuru kovalayan seyyah

Mutluluğum olup çıkınca karşıma

Verebilir miydim sanıyorsun sana kendimi? 

Ruhum huzura açken 

Mutluluğa nasıl sunabilirdim

Bir altın sunak içinde, kendimi...? 

(İskenderun,10,07,1997)', 'Anlatsam beni anlayabilir misin...?  Çektiğim acılardan bihabersin Tatmadığın duyguları hiç hissedebilir misin?  Ben ki huzuru kovalayan sey...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anlatamiyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına ve öncesi sessizlik', 'firtina-ve-oncesi-sessizlik-gokhan-oktem-b19u5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yanardağdı yüreğim

Sanki yüzyıllardır için, için kanayan

Yüzyıllardır o muhteşem 

Ve o ürkütücü patlama anını bekleyen...

Ruhum bir çiğ et misali ham

Ve ülserli bir mide gibi hazımsız 

Ruhum yaşanmamışa duyulan açlık

Ve haksızlıklara duyulan isyan yüklü

Ruhum belirsizlikler denizi

Ruhum sevgiye aç

Sevgiden bihaber

Sevmekten korkar...

Ruhum engin ve fakat

Bir türlü dinmek bilmeyen 

Dalgalı bir umman

Bir umman ki

Kasırgadır kükremesi

Tufandır öksürmesi

Ve med – cezirdir iki uç arasında gidip gelmesi...

Ruhum diken üstünde huzursuz

Ruhum yaşamla ölüm arasında ki o ince çizgide karasız

Ürkek

Acımaklı 

Ve ağlamaklı gezinmekte

Ruhum dengededir terazinin en hassas yerinde

Ve terazi dengesizliğe gebe

Hastalık halinin ve belirsizliğin umutsuzluğu

Ve umutsuzluğun pis bir virüs gibi bulaşıcılığı

Ve kahreden dengesizlik...

Yarınlar diye bir kavram yok ne zamandır

Bu hastalıklı ruhun derinliklerinde

Umut bırakırken yerini umutsuzluğa

Siliyor yaşama ait belirtileri de

Sanki tek kalemde...

Yarınlar yolunu kaybediyor

O ölüm kokan belirsizlik vadisinde...

Yüzleşmek veya kaçmak

Ve bu iki uç arasında gidip gelmeler

Hayatın anlamı ve anlamsızlığının yüklendiği

Gizemlerin daha koyu bir hal aldığı

Veya bir gizem olmaktan çıktığı

Siyah ve beyaz

İyi ve kötü arasındaki zıtlık kadar uç iki kavram...

Kaçmak; her geçen zaman hayat labirentine 

Yeni ve daha karmaşık belirsizlik blokları ekleyerek

Kılar hayatı daha bir çekilmez ve acıları daha bir katlanılmaz....

Yüzleşmek bir kılavuzdur

Seni en kestirme yoldan çıkaran

Gizemli labirentin çıkış kapısına

Cerahat içerdedir 

Yanardağ için, için kaynamakta

Ve işte

İşte yüzleşmek

O ürkütücü

O korkunç acı veren

O muhteşem finaliyle

Patlama anıdır büyük bir gürültüyle

Sanki yüzyıllardır için, için kaynayan

O yanardağın, 

O fokurdayan volkanın

Ya gerisi...

Gerisi fırtınadan önceki

Derin ve ürkütücü sessizlik...

Ölüm sessizliği...

(İskenderun,18,09,1997)', 'Bir yanardağdı yüreğim Sanki yüzyıllardır için, için kanayan Yüzyıllardır o muhteşem  Ve o ürkütücü patlama anını bekleyen... Ruhum bir çiğ ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/firtina-ve-oncesi-sessizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-gokhan-oktem-aad2t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül gözüm görmez oldu

Şiir sözlüm neredesin

Ruhum aşkınla beslenir

Ruh-u özüm neredesin

Gönül gözüm, ruh-u özüm, iki gözüm neredesin

Bunca zamandır sensizim

Sensizliğimle bensizim

İki cihanda yersizim

Gönül gözüm neredesin

Gönül gözüm, ruh-u özüm, iki gözüm neredesin

Bendeki yürek yarası

Hükmün ömrümün dar’ası

Bekleme vadem dolası 

İki gözüm neredesin

Gönül gözüm, ruh-u özüm, iki gözüm neredesin

(İskenderun,16,08,1997)', 'Gönül gözüm görmez oldu Şiir sözlüm neredesin Ruhum aşkınla beslenir Ruh-u özüm neredesin Gönül gözüm, ruh-u özüm, iki gözüm neredesin Bunca...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nerdesin-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harcın değil', 'harcin-degil-gokhan-oktem-5skyb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hesapsızca sevmesini bilen bu yürek

Silmesini de bilir elbet tek kalemde

Sen bilmezsin bu yüreğin derinliğini

Sen bilmezsin toprağımın bereketini

Sevgi tohumlarının nasıl fidan verdiğini

Sen bilmezsin bu yüreğin enginliğini...

Sen ki alışmışsın sığ sularda kulaç atmaya

Dalamazsın yüreğimin derinliklerine

				Korkarsın...

Yetmez nefesin bu derinliklerde 

				Bilirsin...

İlk durakta vurgun yer senin o sığ yüreğin

				Dayanamaz bitersin...! 

Bilmezsin

Merak bile etmezsin

	Bu yüreğin derinliklerinde gizlenen

	O baştan sona mahrem olan

	O tatması şimdiye  dek hiç kimseye 

			Nasip olmayan

O sonsuz güzellikleri barındıran

O gizemler denizini bilmezsin

Çünkü sezemezsin

Yüreğin yetmez

		Bitersin...

Sen ki  sığ sularda yelken açan gemisin

Kıyıları kendine mesken bilirsin

Fırtınamın kokusundan ürker

Rüzgarımın hışmını bilmezsin

Dalga kıranlar, kuytu koylar, sığ kıyılardır senin yuvan

Dalgalarımın haşmetini bilmezsin...

Ah... bir bilsen

	İliklerine kadar titrersin

	Dayanamaz zayıf gövden

	Perçimlerine varana dek çözülür		

	Tek kalemde silinir

	Bu dünyadan gidersin

			Bitersin...

Bırak, 

Kuytu koylarda kal, 

Dalga kıranların arkası sana yeter

Tek tarafı deniz;  ufkunu çizer

Senin harcın değil engin denizler...

(İskenderun,18,12,1997)', 'Hesapsızca sevmesini bilen bu yürek Silmesini de bilir elbet tek kalemde Sen bilmezsin bu yüreğin derinliğini Sen bilmezsin toprağımın berek...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/harcin-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazılan satırlar', 'yazilan-satirlar-erol-sen-gtt0j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel duyguları hissedemezsin istemezsen

Neler geçiyor aklından diye sorarlar

Bırak onlar küçük dünyalarında yaşasınlar

Fırtınalar çıksada belli dönemlerde....

Kabul etmek yaşanmışlıkları hemde biteviye

Bunları yazılan satırlara dökmek, içini dökmek

Kime? bunu kimse bilemez biliyorum dese de

Hayat! ! ! enteresan arkaya bakanlar için

Neden bakayım yaşadığım duygular yalan değil ki

Hissettiklerim? cevabını kim bilebilir tabi ki ben

Bırak oda bana kalsın verilen sözlerle birlikte

Yazılan satırlar kime? cevabını kim bilebilir? 

Tabi ki '' BEN ''

15.01.2001', 'Güzel duyguları hissedemezsin istemezsen Neler geçiyor aklından diye sorarlar Bırak onlar küçük dünyalarında yaşasınlar Fırtınalar çıksada b...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yazilan-satirlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimin Hayal Dünyası', 'sevgimin-hayal-dunyasi-hanimsah-tekeli-hupsw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessizliği nasıl bölerse çığlığı rüzgarın

Yırttım attım yüreğimi bedenimden

İnceden sızılar ya yarası gecenin

Yıldızları sildim birer birer

Ayı doldurdum gökyüzüne

Bir dünya yarattım tekrar içimde

Orada kıvılcımlanan ateşte söndü birer birer yalanlar

Aldım sonra gözlerimi kanayan yaşlarla

Serptim tane tane çorak topraklara

Açıldı serpildi saçlarım

Sardım güzelce bencilliğin üzerine

Kapandı tüm yaralar

Bir koku yayıldı üzerine riyakarlığın

Gece böldü tüm yüzsüzlüğümü

Böylece karardı sonsuzluğunda bir hayatın

İçimize yayılan sevdanın ateşi

İnci dişler misali yıldızlar

Açtım gökyüzünü al dudaklar arasından

Göründü ardından yıldızlarla dolu karanlık

Tekrar tekrar sildim yalanları yıldızların üzerinden

Bir çığlık umarsız arayışlar içinde

Yankılandı tüm kalplerde

Beyinlere işlenen düşünceleri sildim

Karanlığı siler gibi güneş

Bir yaprağın üzerine yazdım sevdanın adını

Yeşerdi allığında doğan güneşin

Sessizce ötüştü böcekler bebeğin ağlayışı misali

Temiz bir kağıttı elimde

Yazdım, yazdım...', 'Sessizliği nasıl bölerse çığlığı rüzgarın Yırttım attım yüreğimi bedenimden İnceden sızılar ya yarası gecenin Yıldızları sildim birer birer ...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevgimin-hayal-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürsün', 'olursun-hanimsah-tekeli-64hxc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki de ölürsün

Uzanır gider ruhun

Geriye kalan bir tortu

Ruhun zehrini akıttığı

Özlerim seni belki

Belki de ağlarım

Sessizce yas tutmasam da 

Gülmem bir daha

Kahkahalarımı hıçkırıklarıma gömerim

Her yağmur damlasına adını yazarım

Toprak altında buluşursunuz

Ruhunu da beslerim

Bir dua ederim ya da kur''an okurum

Sonra belki de resmini yaparım

Renkli olmaz ama

Karakalem

Bilirsin suluboyayı da iyi yaparım

Bir ağacın dalına en sevdiğin meyveyi boyarım

Akşam güneşini seversin, batışını da

İki de martı yaparım

Sonsuz, sınırsız, umarsız

Sen ve ben

Dalgalanırız masum kızıllığında güneşin

Bir heykel de yapabilirim, ama

Bilirsin cesaret edemem

Alışkın değilim yabancı nesnelere

Ama olsun adını işlerim bir parça beze

Asarım duvara

Bir iki de gözyaşı dökerim

Hüzünlü ayrılık melodilerinin çığlığında

Ayrılığı hissederim acı acı

Kanar yüreğim sensizliğin buğusuna

Ama sen unutmazsın beni, bilirim

Bilirsin unutamam ben de seni

Belki tüm bunları yapmadan, yapamadan

Bir yağmur damlasına ben de kaptırırım ruhumu

Sessizce uzanır siluetim gecenin karanlığına

Kara bir gölge gibi

Ben de ölürüm belki

Taşıyamam sensizliği...', 'Belki de ölürsün Uzanır gider ruhun Geriye kalan bir tortu Ruhun zehrini akıttığı Özlerim seni belki Belki de ağlarım Sessizce yas tutmasam ...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/olursun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıdım', 'tanidim-cetin-akgun-aaa12', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani beni bırakıp gidişin varya

Hani en zor en kötü halimde, kaçışın varya

Hani sana ihtiyaç duyduğum an varya

Hani seni okadar çok seviyordum ya

Hani sensiz olmayacağını söylüyordum ya

Meger okadar yanılmışım ki

Meger nekadar aptalmışım

Ama şu bir gerçek ki

En kötü anında

Yanında bulunan kişilere çok iyi bakmalısın

Kimin ne olduğunu işte o an anlarsın

Artık çok mutluyum 

Çünkü seni daha iyi tanıdım

VE

Sensiz de hayatın sürdüğünü anladım

Bana gerçek kişiliğini gösteren SANA

TEŞEKÜR EDİYORUM.', 'Hani beni bırakıp gidişin varya Hani en zor en kötü halimde, kaçışın varya Hani sana ihtiyaç duyduğum an varya Hani seni okadar çok seviyord...', ARRAY['Türk Edebiyatı','Şiir','Çetin Akgün']::text[], 8.5, '{"poet":"Çetin Akgün","poet_slug":"cetin-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tanidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Işık Sevda', 'bir-isik-sevda-hanimsah-tekeli-vf9b5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen, ben

Boş bir sayfanın en başında

Ya da karalara boyanmış bir alın yazısında

Öyle sessiz, öyle derin

Öyle çaresiz

Sen bende yaşarsın

Bense bir dehlizde

Seslensem o karanlığın içinden 

''Gel'' desem

Bir tutam sevginin ışığında

Sessiz kalır mısın? 

Yoksa hani belki 

Belki gerçektir der de

Bana, o sessiz ve karanlık çığlıklarda

O umarsız sevdaların serkeşliğinde

Bir ışık sevda, bir ışık sevgi

Verir misin?', 'Sen, ben Boş bir sayfanın en başında Ya da karalara boyanmış bir alın yazısında Öyle sessiz, öyle derin Öyle çaresiz Sen bende yaşarsın Bens...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-isik-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonrası', 'senden-sonrasi-cemal-safi-n28bm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkın hudûdunu aştı muradım, 

Maksûda varıştır senden sonrası; 

Erenler katına belki bir adım, 

Belki bir karıştır senden sonrası.

Farkına varınca olup bitenin,

Kırdım zincirini nefsin, bedenin! 

Beni aşkın ile ıslah edenin,

Lutfuna eriştir senden sonrası...

Bana bu gayreti sağlayan kudret, 

Eyyûb''ün sabrından aldığım ibret.

Ne riya, ne kibir, ne kin, ne nefret; 

Ebedî barıştır senden sonrası.

Bir gonca Bakî''nin gül destesinden, 

Bir yudum sakînin sır testisinden, 

Yüce Mevlâna''nın gel bestesinden, 

Feyz alış veriştir senden sonrası.

Kevser sarhoşuyum meyhane değil,

Hiçbir zevk böylesi şahane değil,

Kays gibi Leyla''yı nefsane değil,

Efsane görüştür senden sonrası...

Yumup gözlerimi yalan dolana; 

Açtım can evimi gerçek olana.

Elifi bırakıp Karac''oğlana, 

Yunûs''la yarıştır senden sonrası', 'Aşkın hudûdunu aştı muradım,  Maksûda varıştır senden sonrası;  Erenler katına belki bir adım,  Belki bir karıştır senden sonrası. Farkına v...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/senden-sonrasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer', 'meger-hanimsah-tekeli-lqwhk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Meğer geceleri değil, 

Seni sevmişim.

Meğer yalnızlığı değil, 

Seni sevmişim.

Gecelerim senle dolu 

Yalnızlığım ikimizin yalnızlığıymış.

Şimdi gecelerin soğuğunu

Yalnızlığın çığlığını duyuyorum.

Meğer ben seni sevmişim

Hem de nasıl sevmişim...', 'Meğer geceleri değil,  Seni sevmişim. Meğer yalnızlığı değil,  Seni sevmişim. Gecelerim senle dolu  Yalnızlığım ikimizin yalnızlığıymış. Şim...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/meger-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-nurullah-aymali-t4xnn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yagmurlar kesildi hazan oldu bahar

nereden geldi neyin nesi bu karar

karalar mavileri sımsıkı sarar

hissedişler aciz gözler fecre dalar

hazan olmuş tutsak gönlüm biçare

solmuş güller üç beş lale ne çare

bir haber var ey vefa götür o yare

senden gelmiş sana dönmüş bir kere

hicran yıldızı mavi göklerle musavi

ruhumda kelebek örümceklerle harbi

doğar gün olur uzayan geceye mani

anlarım uyanınca uykudan bu acib hali.', 'yagmurlar kesildi hazan oldu bahar nereden geldi neyin nesi bu karar karalar mavileri sımsıkı sarar hissedişler aciz gözler fecre dalar haza...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aymalı']::text[], 8.5, '{"poet":"Nurullah Aymalı","poet_slug":"nurullah-aymali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzin Yok Oluyor', 'i-zin-yok-oluyor-cetin-akgun-wmvla', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani o mazlum bakışın varya

En derin okyanusların, içine sürüklüyor beni

Okyanusları aşıyor sana koşuyorum

Güneşin batışı gibi yok oluşun

Bir kabus olsa gerek

Sana olan tutkum korkutuyor beni

Yüreğimde volkanlar patlıyor

Kalbim yerinden fırlıyor

Çaresizlik içinde yok oluyorum

Hayallerin yok olduğu anda

Gerçekleri görüyorum karşımda

Gerçek olan şu ki

Sana ulaşmak imkansız

Yoruldum koşmaktan

Tükendim aramaktan

Ümitsizliğin verdiği acıyla

Benliğimdeki izin yok oluyor

Taki okyanusların derinliklerine kadar.', 'Hani o mazlum bakışın varya En derin okyanusların, içine sürüklüyor beni Okyanusları aşıyor sana koşuyorum Güneşin batışı gibi yok oluşun Bi...', ARRAY['Türk Edebiyatı','Şiir','Çetin Akgün']::text[], 8.5, '{"poet":"Çetin Akgün","poet_slug":"cetin-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/izin-yok-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşacaksın', 'kosacaksin-hanimsah-tekeli-tn306', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koşacaksın! 

Uzun bir yolda

Sonsuzluğa varacaksın.

Koşacaksın! 

Bırakacaksın arkanda tüm geçmişi.

Kalbini alacaksın avuçlarına, 

Bir parçasını bırakacaksın her adımda.

Yavaş yavaş atacaksın kafandan

Tüm bildiklerini.

Yepyeni bir hayata, 

Bilinmezlikler dolu bir yarına.

Koşacaksın! 

Sessiz yolda soluğun duyulacak

Ayakların konuşacak her adımda

Anlatacak tüm dertleri toprağa.

Her basışında 

Biraz daha hafifleyeceksin.

Koşacakın! 

Koştukça hafifleyeceksin

Yorulsan da bırakmayacaksın

Yarınlara ancak

Koştukça ulaşacaksın...', 'Koşacaksın!  Uzun bir yolda Sonsuzluğa varacaksın. Koşacaksın!  Bırakacaksın arkanda tüm geçmişi. Kalbini alacaksın avuçlarına,  Bir parçası...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kosacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Artık', 'anla-artik-faruk-elma-w85ol', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni seyrederdim uzak odamda

hayall ederken görürdüm yüzünü

senin anlaşılmanı tuhaf gösteren 

o çıplak o sahipsiz sevgin 

sana bakıp ölümcül bir tutkuya kapılırdım

ben gözümü senden hiç ayırmadım 

anla artık  seni değil ben kendimi yanlız   bırakıyorum 

içimde günlerdeir tek başıma bırakılmış 

tek taraflı aşk acısı var

bu gidişin bence bir ölüm gibi 

dokunmak istedikçe uzaklaşmak

sahip olacağım yerde seni kaybetmek

neden bu kadar zor oluyor seni anlamak 

hep birşeyler gizlemek

kadehte acı 

sigaramda sevdam yanıyor

yıprattın beni 

anla beni artık 

eskidim ben artık', 'seni seyrederdim uzak odamda hayall ederken görürdüm yüzünü senin anlaşılmanı tuhaf gösteren  o çıplak o sahipsiz sevgin  sana bakıp ölümcül...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anla-artik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Kimse', 'hic-kimse-hanimsah-tekeli-u2az0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni sevdiğini kimseye söyleme

Sokaktaki kediye bile

Göm içine beni

Gösterme kimseye

Acıklı ve derinden bir şarkı mırıldan

Yalnızca ben duyayım

Duymasın kimse

Havadaki kuş bile.

Öp beni gizlice yanağımdan

Sıcak ve hevesli bir halde

Görmesin kimse

Ağaçtaki böcek bile.

Öyle derinden sev ki beni

Kalbin benle dolsun.

Hissetmesin kimse

Ben bile.', 'Beni sevdiğini kimseye söyleme Sokaktaki kediye bile Göm içine beni Gösterme kimseye Acıklı ve derinden bir şarkı mırıldan Yalnızca ben duya...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hic-kimse-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-hanimsah-tekeli-s88e1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Süzülen damla damla yaşlar 

Dudaklarında birleşen mutluluk

Ardından acı bir tebessüm

Seni bana anlatan', 'Süzülen damla damla yaşlar  Dudaklarında birleşen mutluluk Ardından acı bir tebessüm Seni bana anlatan...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar', 'yillar-hanimsah-tekeli-d7qtu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçen yıl değil, bu yıl

Geçen; yıllar değil, ömrüm.

Gelecek ve geçmiş yıllar...

On yıl önce neydiysem, 

Şimdi de oyum.

Geçen; yıllar değil, ömrüm.

Geçen yıllar, geçecek yıllar, 

Hepsi sizin olsun

Yalnız bana beni verin, 

Alın hepsi

Benden size yadigar olsun...', 'Geçen yıl değil, bu yıl Geçen; yıllar değil, ömrüm. Gelecek ve geçmiş yıllar... On yıl önce neydiysem,  Şimdi de oyum. Geçen; yıllar değil, ...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yillar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazan', 'kazan-hanimsah-tekeli-0e7o3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boş bir kazan gibiyim

En hafif rüzgarda tıngırdıyorum.

İçime kuru bir yaprak düşse 

Onunla avunuyorum.

Boş bir kazan gibiyim

Altıma odun atsalar için için yanıyorum, 

Üzerime su dökseler 

Dolup dolup taşıyorum.

Boş bir kazan gibiyim

İçimde ne nimetten eser var, 

Ne üzerimde kokusundan

Yalnızım bu bahçede içimde bir hüzün var.

Boş bir kazan gibiyim

Kepçem bile avere, yok görünürde

Bana gölge veren kuru ağaç 

Salınır durur üzerimde.

Anlayamam halimi, gücüm yok

Sevemem yarimi, beni seven yok

Boş bir kazan gibiyim dedim ya

Ağlayamam, yaş dökecek gözüm yok.', 'Boş bir kazan gibiyim En hafif rüzgarda tıngırdıyorum. İçime kuru bir yaprak düşse  Onunla avunuyorum. Boş bir kazan gibiyim Altıma odun ats...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kazan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Karası', 'gozlerin-karasi-hanimsah-tekeli-3142r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaptırma sakın kendini 

Nereden estiği belli olmayan rüzgara.

Bilmediğin nehrin sularında yıkanma.

Bakma gözlerin en karasına 

Daima karanlıkta bırakır seni...', 'Kaptırma sakın kendini  Nereden estiği belli olmayan rüzgara. Bilmediğin nehrin sularında yıkanma. Bakma gözlerin en karasına  Daima karanlı...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozlerin-karasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-hanimsah-tekeli-wbmd3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımın bahçesine gömdüm umutlarımı

Sevgimi kopardım

Sonra durdurdum tüm aşkları, doğmadılar

Karanlığında düşüncelerimin bir ışık vardı sadece.

Besledim kinimi bir bebek sever gibi

Saldım üstüne çaresizliğimin bir köpek gibi

Parçalasın istedim tüm yaşananları.

Oysa serpilmezmiş yalanlar kar tanesi gibi, 

Bir çığ düşermiş insanın üzerine

Tertemiz sevda ateşine.

Doğmazmış gün gibi mutsuzluğu bir yüreğin, 

Yıldız yıldız olurmuş gecenin içinde.

Büyürmüş bir çiçek gibi

Zemheride açan.

Bir yalanmış bu sevda

Bilememişim, bir sonsuzlukmuş bende

Kainatın belirsizliğinde

Bir kalem gibi ince ince yazmışım içime.

Silinmezliğinde tüm yaşananların 

Bir uğultuymuş meğer

Tiz bir çığlık sandığım...', 'Yalnızlığımın bahçesine gömdüm umutlarımı Sevgimi kopardım Sonra durdurdum tüm aşkları, doğmadılar Karanlığında düşüncelerimin bir ışık vard...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı Teknesi', 'balikci-teknesi-hanimsah-tekeli-l967c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkımı bir balıkçı teknesi getirdi, 

Sessiz ve sakin yaklaştı bana

Dudaklarından dökemediği sözcükler

Gözlerinde anlam buldu

Kapkara gözlerinde çeşit çeşit renkler sundu.

Aşkımı bir balıkçı teknesi getirdi, 

Teninde tuzun tadı

Ellerinde minicik yüreği

Sundu bana aşkını derinden

Aldım verdiklerini sevgimden.

Aşkımı bir balıkçı teknesi getirdi, 

Kıvırcık saçlarında deniz kokusu

Yanında birçok midye

Bir kolye yaptı boynuma onlardan

Yüreğime bir zincir ördü aşkından.

Aşkımı bir balıkçı teknesi getirdi, 

Bir şey söylemek istedi, susturdum

Verdim ona neyim varsa

Aralandı bir an dudakları

Sessizce sokuldu bana

Kulağıma fısıldadı iki sözcük, 

SENİ SEVİYORUM.

Aşkımı bir balıkçı teknesi getirdi...', 'Aşkımı bir balıkçı teknesi getirdi,  Sessiz ve sakin yaklaştı bana Dudaklarından dökemediği sözcükler Gözlerinde anlam buldu Kapkara gözleri...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/balikci-teknesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru Yağmuru', 'soru-yagmuru-hanimsah-tekeli-vr4hn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum desem, inanır mısın? 

Yanağına öpücük kondursam, yüreğin pır pır eder mi? 

Elini tutsam, midene kramplar girer mi? 

Gözlerine baksam taa derinden

Kaybolur musun gözlerimde? 

Alsam seni içime, çıkmak ister misin? 

Koklasam tenini, 

Okşasam tel tel saçlarını

Heyecandan tir tir titrer misin? 

Kalbini açıp baksam

Kendimi oraya koysam, 

Bana ''hayır'' der misin? 

Bir gün çekip gitsem, aniden

Üzülüp ağlar, arar mısın beni? 

Bulduğunda da kaybetmemek için

Sıkı sıkı basar mısın bağrına? 

Sonra da tüm bu soruların üzerine 

Bana ''seni seviyorum'' der misin? 

Der misin bir tanem?', 'Seni seviyorum desem, inanır mısın?  Yanağına öpücük kondursam, yüreğin pır pır eder mi?  Elini tutsam, midene kramplar girer mi?  Gözlerine...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/soru-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıvılcım', 'kivilcim-cetin-akgun-g56ex', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Varmıydı be

Yarı yolda bırakmak

Hatırlıyormusun? 

Yeni yeni oluşan kıvılcımı

Bu kıvılcım için 

Yıllarca güddüğü davadan

Vaz gecişini

Sırf o kıvılcım için 

Burda kaldığını hatırlıyormusun? 

Bunda aranacak suçlu yok

Buda kaderin bir oyunu olsa gerek

Fakat kader oyununu 

Senden yana oynadı

Lakin sen bunun farkına varamadın

Varmıydı kıvılcımı yarı yolda bırakmak? 

Ama bıraktın 

Kıvılcım aylarca acı çekti

İNANAMADI

Ama bıraktın

Hemde en kötü anında

Oysa senin için 

Tüm hayattan vazgeçmişti

Kıvılcımın yaraları iyileşti

Yerini ise, yaraların izi aldı

İzleri gören 

Kıvılcım, kendini af edemiyor

VE

ETMEYECEĞİM DİYOR.', 'Varmıydı be Yarı yolda bırakmak Hatırlıyormusun?  Yeni yeni oluşan kıvılcımı Bu kıvılcım için  Yıllarca güddüğü davadan Vaz gecişini Sırf o ...', ARRAY['Türk Edebiyatı','Şiir','Çetin Akgün']::text[], 8.5, '{"poet":"Çetin Akgün","poet_slug":"cetin-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kivilcim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Sahilde', 'ayni-sahilde-hanimsah-tekeli-3lhxl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılık vurdu bu akşam sahile

Bir gemidir geldi yanaştı.

Sessizce içten içe aldı beni

Ayrılan eller boş kaldı

Gözlerde yaşlar

Gönüller buruk

Bir gemidir yanaştı bu akşam

Güneş batmasın 

Bugün bitmesin istendi.

Kıyıya vuran her dalga

Bir buse getirdi.

Yüzlere vuran rüzgar 

Dindirmek istedi gözyaşları, 

Deniz vermek istedi 

Beslediği balık kadar mutluluk.

Parıldayan güneş kurutmak istedi gözyaşları.

Bir gemidir geldi yanaştı

Sahile bu akşam ayrılık vurdu.

Gönlümde sen, gözümde yaş

Sensiz bir sene geçecek böyle.

Üzülme sevdiceğim döneceğim yine

Geleceğim bu sahile, tutacağım elini

Üzülme sevdiceğim kavuşacağız seninle

Başka bir yazda, ynı sahilde...', 'Ayrılık vurdu bu akşam sahile Bir gemidir geldi yanaştı. Sessizce içten içe aldı beni Ayrılan eller boş kaldı Gözlerde yaşlar Gönüller buruk...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayni-sahilde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yari görmeden', 'yari-gormeden-asik-sefai-fp9va', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaz gelende başaklar boyun bükse 

Kavrulsada biçmem yari görmeden 

On sekizbin renge senin deseler 

Ak karadan seçmem yari görmeden 

Divani iken imdadıma yetseler 

Saraya konuktur deyip ditseler 

Abu hayat deyu ikram etseler 

İç deseler içmem yari görmeden 

Naçarıda deli gönül naçarı 

Gönül istemiyor yüksek uçanı 

Cennet kapısını açıp içeri 

Geç deseler geçmem yari görmeden 

Aşık sefaiyem açmadan solsam 

Sevda pınarından aşk ile dolsam 

Topragın bagrında tomurcuk olsam 

Bahar gelse açmam yari görmeden', 'Yaz gelende başaklar boyun bükse  Kavrulsada biçmem yari görmeden  On sekizbin renge senin deseler  Ak karadan seçmem yari görmeden  Divani ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yari-gormeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Cennet Çiçegi', 'gozlerin-cennet-cicegi-asik-sefai-hplr0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin cennet çiçegi 

Gönlüm cehennem ateşi 

Eger sevdigine köle olursa gönül 

Nuh tufanına kucak açarmış 

Lakin arfatın gerisi cinnet 

Kalk güzeller güzeli yüregim sana tutsak 

Derdine pusatlandım çilen gün oldu bana 

Sen ki sevdaların şahı garip gönlümün ahı 

Dilegim sen kebelam sen muradım sen 

Dönsede dünya kendi başına ben dönmezem yolumdan 

Dolunaya güneş denktir ülgere kutup yıldızı 

Agla ey şafak yürküsü kaderim boynuma yafta 

Hükmü darimiş merger 

Boynumda yay kirişi 

Şer mi yagıyor yerin yüzüne 

Karanlık bastı başımı 

Sevdam yankılansın vadilerinde ey anadolum 

İgde çiçeginde gizli özüm 

Sarı papatyaki el eder sen gibi 

Alıpta sineme sarasım gelir 

Her koklayış bir acı her dokunuş bin ölüm 

Zaman dokuz başlı ejdarha 

Sen bana düşman bense bana 

Yüregim kaf dagına sürgün 

Ruhum tur dagında ersir 

Deli eyledi zaman 

Bir acıki dizlerim duymasada bedenim 

Parmaklşarımda öldürdüm isyanımı 

Şimdi sokak aralarında gezerken 

Duysamda topal seslerini 

Uyuşmuş bacagım duymayan parmaklarıma ragmen 

Bu dönek günyadan dimdik geçmek zorundayım 

Koy yal verdigim ekmek verdigim köpeklerde 

arkam sıra ürüp dursun 

Şimdi gecelere çivi çakar oldum 

Aglama ey şafak yürkülerim aglama 

Gece mavisi sevdalarımı çıglık çıglıga çadırırken gökleren 

Huzur benim deseydim vallahi düşünmezdim ey ölüm.', 'Gözlerin cennet çiçegi  Gönlüm cehennem ateşi  Eger sevdigine köle olursa gönül  Nuh tufanına kucak açarmış  Lakin arfatın gerisi cinnet  Ka...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gozlerin-cennet-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Ocakta', 'bizim-ocakta-asik-sefai-p5641', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçin için yanarız biz durmadan 

Bin bir şekil bin bir çizim ocakta 

Ortalıkta dönüyor iz durmadan 

Nice muammaya çözüm ocakta 

Seçmeli zamanla karadan akı 

İyi kollamalı gül veren bagı 

İlim irfan medeniyet kaynagı 

İkrarım var derki sözüm ocakta 

Filizi olmayan kökü sökeyim 

Sevdası olmayan yere dikeyim 

Yunuslar misali odun çekeyim 

Küllenmeden yansın közüm ocakta 

Köz ateş vurdukça kaynasın kazan 

Yanıpta kül olsun huzuru bozan 

Yapraklar sararıp gelmeden hazan 

Ham kalmasın pişsin özüm ocakta 

Özü pişirdikten sonra varayım 

Yaralı kuş kanadını sarayım 

Varıp dostun divanına durayım 

Ak olsu isterim yüzüm ocakta 

Leksizdir elbet yüzümüz bizim 

Sefai namustur sözümüz bizim 

Durmadan dövülür özümüz bizim 

Nice hamlar pişer bizim ocakta', 'İçin için yanarız biz durmadan  Bin bir şekil bin bir çizim ocakta  Ortalıkta dönüyor iz durmadan  Nice muammaya çözüm ocakta  Seçmeli zaman...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bizim-ocakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Dünyam', 'kucuk-dunyam-hanimsah-tekeli-p1kcc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık yaşamıyorum

Duymuyorum ne diyor insanlar

Bilmiyorum, etrafımdaki olaylardan habersizim

Hissetmiyorum hiç bir şeyi, konuşamıyorum.

Küçük bir dünya kurmuşum kendime 

Orada büyüyorum.

Hasretimi vuslata

Hüznümü sevince

Orada dönüştürüyorum, umutsuzluğu umuda

Seni orada yaşıyorum

Düşüncelerim, duygularım bedenime sığmadığından beri

Birlikte yaşıyoruz küçük dünyamda.

Yemyeşil ovalar, bal köpüklü nehirler yok

Zümrüt, yakut, elmaslar yok

Ama sen varsın, bir de umutlarım.

Sonsuz bekleyişlerimden yorulduğumda

Nefes alacak bir bahçe

Sensizliğimle savaşımdan kaçarken

Bir sığınak

Uzun yolculuklara başlamak için

Bir durak.

Benim küçük dünyam

Yüreğime sığmayan o yüce sevginle

Şimdi büyüyen küçük dünyam...', 'Artık yaşamıyorum Duymuyorum ne diyor insanlar Bilmiyorum, etrafımdaki olaylardan habersizim Hissetmiyorum hiç bir şeyi, konuşamıyorum. Küçü...', ARRAY['Türk Edebiyatı','Şiir','Hanımşah Tekeli']::text[], 8.5, '{"poet":"Hanımşah Tekeli","poet_slug":"hanimsah-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kucuk-dunyam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlerim Var', 'huzunlerim-var-faruk-elma-lgdci', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir yudum mutluluk vardır 

çoğu zaman yaşayamazsınız

ve acılarımız vardır  çoğunlukla onu yaşarsınız

hüzünleriniz size çoğu kez geçmişi hatırlatır 

hiç yaşamadıklarınızla  geçmişe yolculuk yapıp 

sıkıntılarınızı tartabilirmisiniz

tartabilirmisiniz sevinçlerinizi 

ve  anlatabilirmisiniz hüzünlerinizi

son on yılın hüzün ağacı bürümüştür içinizi

hani kafanız takılır ya zaman zaman 

hani vurursunuz ya kendinizi rakı kadehlarinin dibine

başınıza belki ağrı girer

kalbinizin sıkıştığını sanırsınız

hüzünler boğmuştur sizi 

karanlıklara gömülmüşsünüzdür

bir küçüçük yalan bitiriverir zamanı size 

veya bir küçüçük gülüş alır götürür sizi mutluluklara

yine diyorum ki sevmenin zamanı yoktur

ve çözülmeyecek şeyleri sevgiyle çözersiniz

o sevgi yumağını içinize bir gün alabilirsiniz

ne sizin hüzünleriniz kalır neden karşındakinin', 'bir yudum mutluluk vardır  çoğu zaman yaşayamazsınız ve acılarımız vardır  çoğunlukla onu yaşarsınız hüzünleriniz size çoğu kez geçmişi hatı...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/huzunlerim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykular Geldi''de Kovdumu Gözüm', 'uykular-geldi-de-kovdumu-gozum-asik-sefai-b43ep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne isyan edersin zülfü sırmalım 

Uykular geldi''de kovdumu gözüm 

Ahfalına taşın yakar sinemi 

Uykular geldi''de kovdumu gözüm 

Sular inişine durmaz akarken 

Kara bulutlarda şimşek çakarken 

Gece karanlıga çıra yakarken 

Uykular deldi''de kovdumu gözüm 

Besmeleyi çeksem aşın dibinde 

Sevdam gizli kaldı kaşın dibinde 

Hayalin uyutmaz taşın dibinde 

Uykular geldi''de kovdumu gözün 

Sevdam yatar sıra sıra toprakta 

Gizlidir görünmez yara toprakta 

Kuş tüyü yastıkta kara toprakta 

Uykular geldi''de kovdumu gözüm', 'Ne isyan edersin zülfü sırmalım  Uykular geldi''de kovdumu gözüm  Ahfalına taşın yakar sinemi  Uykular geldi''de kovdumu gözüm  Sular inişine ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uykular-geldi-de-kovdumu-gozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelam Bilmeyene Söz Bilmeyene', 'kelam-bilmeyene-soz-bilmeyene-asik-sefai-uz9ef', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kelam bilmeyene söz bilmeyene 

Desindiye dil verdiydim birzaman 

Ocak beyhudesi öz bilmeyene 

Muhabbete hal verdiydim bir zaman 

Kimisi bir etmez kimisi buçuk 

Kimi adan degil kimisi kaçık 

Kimi yalın ayak kimi sırt açık 

Çıplaklara çul verdiydim bir zaman 

Ayak saldım dağlardaki çagrına 

Aknergisi nişan koydum bögrüne 

Yaylaları dolandıydım ugruna 

Yesin diye bal verdiydim bir zaman 

Bunlar adam degil yaban kırı 

Hedefe ulaşmaz daban kırı 

Demirci artıdı çoban kırı 

Yol bilmeze yol verdiydim bir zaman 

Yigit olur dagın başı kar ise 

Sefai''yem söyleyemem sır ise 

Hakkım helal olsun hakkım ver ise 

Bir kaç ite yal verdiydim bir zaman', 'Kelam bilmeyene söz bilmeyene  Desindiye dil verdiydim birzaman  Ocak beyhudesi öz bilmeyene  Muhabbete hal verdiydim bir zaman  Kimisi bir ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kelam-bilmeyene-soz-bilmeyene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekip Git', 'cekip-git-oner-ozer-gdwng', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılık yaman kelime

Hangi yüreğe düşerse

Onu yakarmış

Şimdi ben yanıyorum

İçin için

Senden çok uzaklarda

Kahroluyorum

Uzanamıyorum

Tutamıyorum

Öpemiyorum

Sarılamıyorum

Sevemiyorum

Bazen lanet ediyorum

Bu hayata

Çekip gitmek var diyorum

Ama nereye?', 'Ayrılık yaman kelime Hangi yüreğe düşerse Onu yakarmış Şimdi ben yanıyorum İçin için Senden çok uzaklarda Kahroluyorum Uzanamıyorum Tutamıyo...', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cekip-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğim', 'gelecegim-oner-ozer-ljbpr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geleceğim bir gün oralara

Kırıp içimdeki zincirleri

Sevgimle dolu dolu geleceğim

Çalacağım kapını

Ben geldim diyeceğim

Açarmısın kapını

Aralarmısın gönül pencereni

Bana gel dermisin

İçten bir tebessümle

O sıcacık sesinle

Buyur edermisin

Bir kez daha 

CANIM dermisin', 'Geleceğim bir gün oralara Kırıp içimdeki zincirleri Sevgimle dolu dolu geleceğim Çalacağım kapını Ben geldim diyeceğim Açarmısın kapını Aral...', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gelecegim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİTTİN', 'gi-tti-n-oner-ozer-xdexj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gittin

Arkana bile bakmadan

Bir el sallamadan

Gittin sevdiğim

Öylece bakakaldım

Sonra

Döndüm arkama

Hızlı hızlı kaçtım

Uzaklaştım

Biliyordumki

Sen dönsen

Ben dönsem

Gidemezdik', 'Gittin Arkana bile bakmadan Bir el sallamadan Gittin sevdiğim Öylece bakakaldım Sonra Döndüm arkama Hızlı hızlı kaçtım Uzaklaştım Biliyordum...', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gittin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KONUŞ', 'konus-oner-ozer-8r5ux', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geliyorum güzelim

Beyaz bir ata bindim

Dolu dizgin koşuyorum

Taşlı-topraklı yollardan

Sana geliyorum

Aşıyorum engelleri bir bir

Kavuşmaya geliyorum

İlk günün heyecanıyla

Koşuyorum

Elimde söz mendilin

Onu sana getiriyorum.

Sunmak için

Kalbimi getiriyorum.

Varmısın güzelim

Varmısın

Sonsuza dek

Benimle yaşamaya

Bana sevdiğim demeye

İstermisin beni

Ben olarak

İstermisin şu yaşlı kalbimi

Tutarmısın ellerimi

Sımsıkı sarılırmısın

Evet dermisin

Söyle be güzelim

Konuş

Neden susuyorsun

Susmak sana yakışmıyor

Susman beni kahrediyor', 'Geliyorum güzelim Beyaz bir ata bindim Dolu dizgin koşuyorum Taşlı-topraklı yollardan Sana geliyorum Aşıyorum engelleri bir bir Kavuşmaya ge...', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/konus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEVDİM', 'sevdi-m-oner-ozer-4o0bz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adetlerin ışığında 

Acemilerin gecesini

Yaşadınmı sen güzelim

Ben yaşayamadım

Tadamadım

O duyguyu

Oldu bittiye geldi

Anlayamadım

İçimde bir burukluk kaldı

Aslında nasılda sevgi doluydum

Nasıl bir heyecan içindeydim

Hayallerim bile vardı

O büyük mutluluk hayalleri

Her geçen gün

Bir bir yok oldular

Silindiler önce gözlerimden

Sonra düşüncelerimden

Kaldım bir ben

Tek ben

Yapayalnız

Kaldım çaresiz.

Yıllar sonra

Gülen yüzünle

Sen çıktın karşıma 

O tatlı sesinle

Uyandırdın beni 

Kurtardın yalnızlıktan

Konuştum seninle

Güldüm

Dertleştim

Bazen ağladım

Ama sevdim

Çok çok sevdim

Yokluğuna dayanamıyacak kadar

Varlığına dünyaları satacak kadar

Sevdim güzelim

Mutluluğun için 

Mutluluğumu feda edecek kadar

Gülmen için 

Canımı verecek kadar

Sevdim canım

Ölesiye sevdim

Delicesine sevdim

Gitme kal diyecek kadar

Yalvaracak kadar

Önünde eğilecek kadar

Bir yaşam boyu seni

Sırtımda taşıyacak kadar

Sevdim aşkım', 'Adetlerin ışığında  Acemilerin gecesini Yaşadınmı sen güzelim Ben yaşayamadım Tadamadım O duyguyu Oldu bittiye geldi Anlayamadım İçimde bir ...', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sevdim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİNDEYİM', 'gozleri-ndeyi-m-oner-ozer-dnsus', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğim sende rehin kalsın

Geri verme almayacağım

Bir gün mutlaka 

Gözlerinden kalbine akacağım

Bağıracağım

Haykıracağım

Duvarlara adını yazacağım

Sen istemesen bile

Bir gün mutlaka 

Gözlerinden kalbine akacağım', 'Yüreğim sende rehin kalsın Geri verme almayacağım Bir gün mutlaka  Gözlerinden kalbine akacağım Bağıracağım Haykıracağım Duvarlara adını yaz...', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sevmek', 'sevmek-gurcan-soner-y0xj2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zor kardeşim sevmek zor 

hele sevipte anlatmamak

yaşam seni zorlar ama

yaşamak zor anlatmakta

gözlerin dolar  yaşlarla 

gel anlat sende kolaysa 

ama zor dedim ya işte ondan 

yaşanmak zorunda bunlar  acıyla

sen sen ol asla unutma 

aç gönlünü sınırsızca', 'zor kardeşim sevmek zor  hele sevipte anlatmamak yaşam seni zorlar ama yaşamak zor anlatmakta gözlerin dolar  yaşlarla  gel anlat sende kola...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Soner']::text[], 8.5, '{"poet":"Gürcan Soner","poet_slug":"gurcan-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevmek-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SahTE', 'sahte-kemal-taskin-cjj6r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir sahteliktir almış

başını gidiyor.

dün ''nisa''  yaşadığın

bu gün  ''mihrabın'' 

                     olmuş.

-anlamıyorsun-

     

     kara dem 

         tüm 

                vücutlara

                                mı-

                                     işlemiş? 

-bilmiyorsun-

sen böyle değildin 

                  diyorsun 

          kendi kendine

-şaşırıyorsun-

sahtelik yılanı

              seni de boğmaya 

                               çalışıyor, 

-direniyorsun-

            

             düşündük(çe) 

-üzülüyorsun-', 'bir sahteliktir almış başını gidiyor. dün ''nisa''  yaşadığın bu gün  ''mihrabın''                       olmuş. -anlamıyorsun-            kara d...', ARRAY['Türk Edebiyatı','Şiir','Kemal Taşkın']::text[], 8.5, '{"poet":"Kemal Taşkın","poet_slug":"kemal-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sahte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözün Kanadında', 'sozun-kanadinda-umit-sariaslan-gjtob', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karıma, servet''e

İki şakı iki göz gölün

İki şakı iki göl gözlerin

İki keskin kılıç

İki ölüm kuşu gözlerin', 'Karıma, servet''e İki şakı iki göz gölün İki şakı iki göl gözlerin İki keskin kılıç İki ölüm kuşu gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Ümit Sarıaslan']::text[], 8.5, '{"poet":"Ümit Sarıaslan","poet_slug":"umit-sariaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sozun-kanadinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Çiçeğim', 'sana-cicegim-behcet-hacibeyoglu-y3wup', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Otobüs camlarına yazdım bugün adını

Aynı gözlerini yazdığım gibi yüreğime

Bir kar tanesine verdim adını

Salına salına üzerime kon diye

Bir çiçeğe verdim adını

Sadece benim ol diye

Adını verdim herşeye

Benim için herşey sensin diye

Yarına verdim bir de adını

Yarınlar belki gelir seninle...', 'Otobüs camlarına yazdım bugün adını Aynı gözlerini yazdığım gibi yüreğime Bir kar tanesine verdim adını Salına salına üzerime kon diye Bir ç...', ARRAY['Türk Edebiyatı','Şiir','Behçet Hacıbeyoğlu']::text[], 8.5, '{"poet":"Behçet Hacıbeyoğlu","poet_slug":"behcet-hacibeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sana-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bebek Vardı', 'bir-bebek-vardi-behcet-hacibeyoglu-pfh6q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bebek vardı ağlıyarak açtı gözlerini dünyaya, 

Sonbahar yağmurlarına karıştı gözyaşları.

Yağmularda ıslanmış toprak gibi kokuyordu saçları.

Gözleride ıslaktı, henüz korkuyordu besbelli.

Bir çocuk vardı ışıl ışıl parlayan gözleriyle, 

Merak ederdi yarınları, ufka bakar dalardı, 

Unuturdu çocukluğunu büyürdü birdenbire.

Bir çocuk vardı hala bebekti bembeyaz elleriyle, 

Bir kız vardı hala annesinin kucağında ağlardı.

Bir kız yüreğinde tertemiz umutlar besleyen.

Bir kız vardı ekim rüzgarlarının serinliğinde doğmuştu.

Bir kız vardı hala bebekti el değmemiş yüreğiyle', 'Bir bebek vardı ağlıyarak açtı gözlerini dünyaya,  Sonbahar yağmurlarına karıştı gözyaşları. Yağmularda ıslanmış toprak gibi kokuyordu saçla...', ARRAY['Türk Edebiyatı','Şiir','Behçet Hacıbeyoğlu']::text[], 8.5, '{"poet":"Behçet Hacıbeyoğlu","poet_slug":"behcet-hacibeyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-bebek-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'mademki yokluğumla daha mutlusun...', 'mademki-yoklugumla-daha-mutlusun-cezmi-ersoz-cl34i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat soğuk, yağmurlu ve vurdumduymaz bir İstanbul gecesiydi... Ve gece yağan yağmur hep ürkütürdü beni. Yağmur değil yalnızlığımdı pencereleri damla damla yalayan, yıllarımı dolduran sensizlikti... Hep bir yanı yarımlık, hep senden uzaktalık, hayattaki tek ''kimse''mden yoksunluk, yani kimsesizlikti. Bir kavuşma mucizesine inanma yolunda harcanmış bir hayatın ansızın sonuna gelme, ve o mucizeyi yaşayamadan bir başına ölme korkusuydu yağmur…

Yine yağmur yağıyor, yine gece... Yine İstanbul... Ve sen kollarımın arasından sıyrılıp kalkıyorsun yataktan. Nereye gidiyorsun sevgilim? 

Sadece sana sarılarak uyuduğumda nefes alabiliyordum. Beni kollarına aldığında, yüzümü masumiyetinin yurduna, o kimsesiz boynuna dayadığımda, kokunu kalbimle soluduğumda... Uykun benim cennetimdi. Çünkü cennet sadece ikimizin olabildiği yerdi benim için. Ne sana aşık kadınlar, ne sevdiklerin, ne geçmişin, ne yarının...Uykunda sadece ikimiz vardık. Aşkıma dar gelen sevgi sözcüklerine ihtiyacım yoktu orada. Sana sevgimi anlatmaya, ispat etmeye ihtiyacım yoktu artık. Aşkımızın kokusuydu sana beni anlatan, sana seni anlatan.... Beni gerçekliğin o soğuk, o köpüklü dalgalarıyla yutan ve alıp alıp senden ötelere savuran hayatın dışındaki tek kaçış tünelimdi uykun. 

Önce kolunu çekerdin başımın altından, sonra sırtını dönerdin. Usulca sarılırdım sana arkandan, seninle ya da sensiz geçen yılların hasretiyle... Ardından yavaş yavaş kollarımın arasından sıyrılırdın...Yıllardır taşımaktan yorulmadığım hasretin, tenimden tenime akan o ateş, ağır gelirdi bedenine... Uyuyamıyorum, nefes alamıyorum, lütfen sarılma, derdin... Yatağın bir ucuna sığınmış bedeninden kovulmak, hayatından kovulmak gibiydi benim için. Sığındığım, soluk aldığım tek cennetten kovulmak gibiydi. Beni uykunda terk etmen, gerçek hayatta terk edişinden bile ağır gelirdi. Yanıbaşındaki sensizlik, o rutubetli evimdeki, o baştan ayağa sen olan evimdeki unutulmuşluğumdan çok daha ağır gelirdi. 

Seni kaybetme korkusu öyle işlemişti ki hücrelerime...Yataktan doğrulduğun anda bu korkuyla açılırdı gözlerim. Bilinçaltım konuşurdu benim yerime... Su içmek ya da tuvalete gitmek için kalktığın asla aklıma gelmezdi. Gittiğini düşünürdüm yalnızca... O saatte kendi evini terk edip, nereye gidebileceğini sorgulamadan, sadece beni o sonsuz hiçlikte, o en masum rüyada, cennetimizde, uykumuzda bir başına bırakıp, kaybolacağından korkardım. Bana hep aynı soruyu sorduran bu yüzyıllık korkuydu işte: Nereye gidiyorsun sevgilim? 

Beni yeniden hayatın içinde, gerçeklerin ortasında bir başına mı bırakıyorsun? Beni yeniden unutuluş sürgünlerine mi gönderiyorsun? Nereye gidiyorsun sevgilim? 

Oysa seni uyutmayan içindeki o yangınlı hesaplaşmaydı. Gece iner, aşıklar, yüzler, bedenler, anılar kaybolurdu; sadece ikimiz kalırdık. Ve sen uykunda sevgimle hesaplaşmaya dalardın. Cennette cehennemi hatırlardın.

Dönüp geriye bakıyorum da, sanki yıllar değil yüzyıllar geçmiş aramızdan... Aramızdan ayrılıklar, ihanetler, kayboluşlar, vazgeçişler, yeniden bulmalar, korkular, yalnızlıklar, savrulmalar geçmiş. Ve bu ilişki ne çok biçim değiştirmiş... 

Seni yollarca, şehirlerce uzağından sevdim. Seni kelimelerce, şiirlerce yakınından sevdim. Seni dünya üzerinde sanki ilk kez benim için kalemi eline alıp da yazdığın mektuplarca sevdim. Seni umutsuzca, beklentisizce, hayallerce sevdim uzağından. Hayatımı öyle olduğu gibi bıraktım. Şehrine geldim, ama kalbine giremeden sevdim. Neydik biz o yıllarda hiç düşündün mü? Neydik birbirimiz için sevgili? 

Geldim. Bana destek olacak, sırtımı vereceğim bir aşkın yoktu arkamda. Kendime yeni bir hayat kuracağım yalanını, kendim dahil, sen dahil herkese söyledim. Oysa tek istediğim seninle birlikte bir hayattı. Öyle cesaretsizdim ki karşında ve öyle açık sözlüydün ki bana karşı, ancak iddiasız bir sığınmacı olabildim hayatında. Hayatına iltica etmek isteyen bir yürek sürgünü... Bir aşk meczubu sadece...

Dürüstlük kimi zaman yalanlardan çok daha acımasızmış, sevgili... Gerçeğin buzdan ülkesinde yapayalnız kalan yürek, hayatta kalabilmek için yalanları bile özleyebilirmiş kimi zaman... Bana aksini ispat etmek için elinden geleni yaptığın o yıllarda, buzlar ülkesinde biraz olsun ısınabilmek için, aslında beni sevdiğin yalanına inandırmıştım ben de kendimi... 

Aşkıma kapalı bir kapının önüne bırakılmış yaralı bir kuş gibiydim. İnanacak, bir ibadet gibi yaşayacak tek şeyimdi senin aşkın. Karşılıksız, güvensiz, sessizce yaşanan bir aşk... Nasıl da hoyrattın bana karşı... Kalbinde değil miydim gerçekten? Neydik biz söylesene? O yıllarda senin neyindim ben sevgili? Can yoldaşın mı? Yol arkadaşın mı? Dostun mu? Sevgilin mi? .. 

Sonra bir gün geldi ve unutuldum. Ve bu sorular birer birer bıçak gibi saplandı yüreğime ve yüreğimde yanıtlarını buldu. Unutuluş hepsinin acımasız cevabı oldu. Sonrası dipsiz bir karanlık... Sonrası çaresiz bir çıldırış... 

Hayata karışmamak için tek kalkanım, tek sığınağımdı aşkın. Tek silahımı yitirdim ve hayata teslim oldum. Aldı beni savurdu başka bedenlere, parçası olamadığım o kırık dökük öykülere... 

Kırgınlık kimlik değiştirdi ve vazgeçiş oldu benim için. Unutmanın en ağırı unutamadan unutmaktır. Seni sonsuza kadar kaybetmek kimlik değiştirdi ve unutmak oldu benim için. Seni unuttuğum yalanıyla hayatı kandırmaya çalışınca hayat hiç olmadığı kadar acımasız tokatlar indirdi yüzüme... Sonrası dipsiz karanlık... Sonrası hatırlamaya bile dayanamadığım düş yıkımları... Sonrası kesif, karanlık ve rutubetli bir kuyu... Koskoca bir boşluk... Sonrası ''yalnızlık'' kelimesine sığmayacak kadar derin bir yalnızlık...

Kaç zaman sonra bilmiyorum, bir gün geldi ve beni yeniden hatırladın. Yokluğumda kendine kurduğun hayat, beni yasak bir ilişki haline getirdi bu kez de... Ve bu ilişki bir kez daha kimlik değiştirdi. Seni, bir başkasıyla birleştirdiğin hayatına uzaktan bakarak, kalbimi kıskançlığın lanetli hırsına teslim ederek, kısıtlı zamanlarda, gizli saklı buluşmalarda, o doyumsuz kaçamaklarda sevmeyi de öğrendim... Hasretinin o tarifsiz kokusu burnumu sızlatırken yapayalnız uyumayı da öğrendim. Yağmurlu İstanbul gecelerinde o baştan ayağa sen olan evimde kaderimle kıyasıya yaşamayı da öğrendim, sevgili... 

O zamansız unutuluşun ardından yeniden hatırlanmanın sevinci, seni paylaşmaya boyun eğmenin ve hep gizliliğin gölgesinde kalacak olmanın acısına büründü. Uykunda soluğunun bir başka soluğa karıştığını bilerek geçirdiğim sayısız gecelerde, gururumu parça parça bölüp aşkıma kurban verdim. O tarifsiz ağrıyı uyuşturmak için ruhumdan, kimliğimden, kadınlık onurumdan vazgeçtim. Her şeye rağmen direnebilmek için kendimden vazgeçtim. Geriye dönüş kapılarını sonsuza kadar kapatmış oldum böylece. Ruhumdan kendimi kovup, tüm hücrelerime sadece aşkını yerleştirdim. İşte o andan itibaren, sensizlik artık bensizlik oldu sevgili...

Nasıl da telaşlı, nasıl da soluk soluğa yaşardık o kaçamak anları... Aşkımızın en karanlık, en gerçek, ama en yoğun anlarıymış onlar... Sensiz geçen gecelerde yüreğimde biriken kıskançlığın, öfkenin, kırgınlığın ve hasretin hummalı karanlığı, sana kavuştuğum anlarda sevinçten çıldırmanın eşiğinde tarifsiz bir hazza dönüşürdü... Nasıl da ateşliydi sevişmelerimiz... Sana yeniden dokunmak, sanki bulutlara öpücükler kondurmak gibiydi... Huzurla huzursuzluk, hasret ve kavuşma, aşk ve öfke, merhamet ve acımasızlık, kırgınlık ve bağışlama her şey ama her şey sevgimizin taşkın sularında birbirine karışırdı. İki kalbin bir ömre sığdırabileceği tüm duyguları biz o kısacık anlarda soluk soluğa yaşardık...

Sonra hayatını değiştirdin. Yeniden özgürlüğüne kavuştun. Ve bu ilişki bir kez daha biçim değiştirdi. Yıllardır bir savruluş halinde aramızdan akıp giden aşkımız, nihayet dingin, doygun ve emin bir sığınak bulmuştu kendine. O savruk yıllar bile koparamamıştı ya bizi birbirimizden, artık hiçbir şey bu aşkı yıkamazdı. İhanetlerin, unutuluşun, hayatın sınavından geçmişti aşkımız. Tam da birbirimizi hayattan çok uzakta, dokunulmaz bir boyutta sevdiğimize inanmaya başlamışken, dudaklarından dökülen o lanetli cümle korkularımı yeniden uyandırdı, geçmişi zamandan koparıp aramıza soktu yeniden: ''Varlığın artık bana acı vermiyor...''

Ah sevgilim, ayrılık trenini çoktan kaçırmadık mı biz? Bulup bulup kaybetme oyunlarını çoktan tüketmedik mi? O dünyevi aşk oyunlarından, kıskandırmalardan, kaçamaklardan çoktan vazgeçmedik mi? Birbirimizi en ağır ihanetlerde sınamadık mı? Anlamadın mı artık, varlığım sana acı vermek için değil... Sadece seni sevmek için yaşadım ben! 

Senin için bir ilişkide girilebilecek bütün kimliklere bürünmedim mi? Önce aşkla değil kalbinin boşluğuyla tutunduğun bir can yoldaşıydım... Yüreğin bir başkasına kapılarını açtığında hayatından dışlanıp unuttuğun oldum sonra... Başka hayatlarda, başka ilişkilerde seni unutmaya çalışırken, belki de aslında sadece seni ararken kıskançlıktan deliye döndüğün oldum... Kalbime geri dönmek istediğinde gururumun gemilerini yakıp, metresin oldum... Vicdanın oldum senin... Merhametin oldum... Pişmanlığın oldum... Hazzın en sıradışı boyutlarını seninle paylaşan fahişen oldum... Arkadaşın oldum... Kardeşin oldum... Sevgilin oldum... Söylesene kaç kez biçim değiştirdi bu ilişki? Kaç kez kimlik değiştirdim seni sevebilmek için... 

Anlamadın mı artık, varlığım sana acı vermek için değil. Sadece seni sevebilmek için yaşadım ben... Hala seninle geçireceğim anların telaşıyla tüketir gibi yaşıyorum sensiz geçen günlerimi. Yıllar geçti, hala seni görecek olmanın kalp çarpıntılarıyla, yalnız senin için giyiniyorum en güzel giysilerimi. Sen güzel bulasın diye geçiyorum aynaların karşısına. 

Seninle geçen zaman bir daha tekrarı olmayan, doğaçlama bir melodi gibi benim için... Sanki birlikte yazılmış kaderimizin sayılı dakikalarından an çalıyorum. Öylece karşında oturup seni seyretmeyi, sana yemek hazırlamayı, seninle sohbet etmeyi, dostlarını ağırlamayı, seninle birlikte uyumayı, yani paylaştığımız ne varsa hepsini bir daha asla okuyamayacağım bir şiiri kelime kelime içime sindirir gibi, soluk soluğa hissederek yaşıyorum... Öyle birikmişsin ki içimde... Seni yaşamakla tüketmem, seni sıradanlaştırmam mümkün değil. İçime çektikçe çoğalıyorsun...

Şimdi varlığım her geçen dakika daha da daralan gizli bir çember örüyor etrafına. Her geçen gün biraz daha uzaklaşıyor, biraz daha kanıksıyorsun beni... O peşini bırakmayan yaralı geçmişin aramıza korku duvarları örüyor. Hayatını tüm kalbimle kucakladığımı hissettiğim anda ansızın yüzünde beliren o eski kaygıların alıp seni benden çok uzaklara, derinlere, yalnızlık kuyularına sürüklüyor. Yeni isimler, yeni aşk öyküleri, başka yüzler, başka bedenlerle kaçış planları yapıyorsun kendine... Gece ansızın seni uyandıran, kolunu başımın altından çeken, seni yatağın ucuna kadar götüren, uykunu bölüp ayağa kaldıran ve bana hep o aynı soruyu sorduran bu korkular değil mi...: ''Sevgilim nereye gidiyorsun? ''

Sevgilim nereye gidiyorsun? Orada ne var? Benliğini kıstırdığın duvarların arkasında soğuk, uçsuz bucaksız bir yalnızlıktan başka ne var? Neden kaçıyorsun? Neden bu aşkı sonsuzluğa, özgürlüğe, daha önce hiç yaşamadığın sınırsızlığa bir kapı olarak görmüyorsun? Ben senden gitme ihtimalini hiçbir zaman çalmaya yeltenmedim ki... Sevgim seni tüketmek değil, çoğaltmak içindi... Sevgim dünyanın yaşanılası bir yer olduğuna inanman, inanmamız içindi... Yüreğimizin çok derinlerinde yaşayan o iki masum çocuğun soluk alabilmesi için bir gökyüzüydü sevgim... Ben senin kanatlarını hiçbir zaman çalmadım ki... 

Öyle çok reddedildim ki, öyle çok unutuldum ki senin tarafından, sensiz kalmak yüreğimi ezen tek korku artık. Öyle ki hayatım yalnız bir korku halinde ayakta duruyor şimdi... Korkumu gerçeğe büründürdüğün anda yıkılıp gideceğim. Her şeyi tükettim. Hayata tutunmak adına ne varsa her şeyi yaktım seni sevebilmek için... Tüm sabrımı, kendime ve insanlara güvenimi, sevginin hayatın tek harcı olduğuna olan inancımı... Artık senden başkasına verecek enerjim, sevgim ve hayatla hesaplaşacak bir benliğim kalmadı. Geriye dönüp sığınacak bir kendim kalmadı...

Şimdi bana varlığımın sana acı vermediğini söylüyorsun. Gitmemi istiyorsun, sonra yeniden gelmemi... Ve sonra yeniden gitmemi... Beni sensizliğin o dipsiz çukuruna önce sarkıtıp, sonra yeniden gün ışığına çıkarıyorsun. Sevgimi, yokluğumu hissettiğin yerde bulmak istiyorsun. Aşkımın benliğini ve hayatını ele geçirmesinden duyduğun o sebepsiz korkuyu yenmek için, bana seninleyken tekrarı olmayan bir şiiri hatırlatan zamanın, sana benimleyken gösterdiği monoton ve tüketici yüzünü yok etmek için oynadığın bir oyun bu belki de... Beni deliliğin sürgünlerine yollayıp, sonra yeniden kalbine çağırıyorsun. 

Korkuyu beklemenin telaşı korkunun kendisinden çok daha ürkütücü biliyor musun? İşte bu yüzden sensizliğin karanlık kuyusuna kendi ellerimle bırakıyorum kaderimi. Korkuyu beklemekten vazgeçiyorum, ama asla seni sevmekten değil, sevgili... Sana veda etmeden kayboluşa karışmam da aslında sadece bunun için... 

Madem varlığım acı vermiyor sana, madem ki ancak yokluğumda sevgimi hissedebiliyorsun, öyleyse yokluğumla kal sevgili... Madem ki yokluğumla daha mutlusun, o halde yokluk benim bu aşk için büründüğüm son kimlik olsun...



 cezmi ersöz', 'Hayat soğuk, yağmurlu ve vurdumduymaz bir İstanbul gecesiydi... Ve gece yağan yağmur hep ürkütürdü beni. Yağmur değil yalnızlığımdı pencerel...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mademki-yoklugumla-daha-mutlusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Burada Değilsin', 'simdi-burada-degilsin-cezmi-ersoz-mr6i2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şimdi burda değilsin....

ama beni duyuyosunn...biliyorum...

kapat gözlerini benim için ve dinle n''olur...

bak yoksun...

bunun anlamını biliyomusunn....

yokluğun

yüreğimmdeki bu yıldızsız, 

bu dipsiz, karanlık gece...

yokluğun, odamın duvarlarına astığım suretlerine bakarken, 

unuttuğum dalgın gözlerim....

yokluğun yastığımda bıraktığın bu kimsesiz saç telleri...

sırf kalemini değdirdiğin için atmaya kıyamadığım bu kağıtlar...

her an gözümün önünde sakladığım  mektupların, 

peçetelere yazdığın  şiirlerin, 

hediyelerini sardığın paket kağıtların...

sen gidince, 

hala sen kokuyodur, diye üzerime giydiğim 

ve derinn derinn

soluduğumm giysilerin....

bu yarı deli...

bu hayattan kopuk ruhum...

kapat gözlerini ve bana baak....

ben ne diye varsa gördüğün, işte o senin yokluğun....

söyle.! 

sana neyi anlatayımm...

sabaha karşı çalan  telefonumun ucunda, 

n''luuur bana hayattan kötü davranma diyen...sayıklayan..

o kırgın, o kendine çarpan sesini mi..! !', 'şimdi burda değilsin.... ama beni duyuyosunn...biliyorum... kapat gözlerini benim için ve dinle n''olur... bak yoksun... bunun anlamını biliy...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/simdi-burada-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ Çileği', 'dag-cilegi-reha-basogul-tjwgr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sibirya kaplanının her zaman sahip olduğu

ama pencereden hızla eriyen karlar

o beyaz saflığın önünde yorulduğu

yerine sadece ve daha soğuk rüzgarın soluduğu anlar

hiç bilmediği, tanımadığı bir dağ çileği o

sadece uzaktan dağa baktığı 

sonsuz beyazlığın içinde 

kırmızısından tanıdığı...

o kırmızının içindeki beyazda

bir kürenin şeffaflığı

bir cennetin aralığı

bir yaprağın acısı

hiç görmedği, tanımadığı bir dağ çileği o

oraya tırmandığı

onsuz kalamadığı

ve koparmaya kıyamadığı

zorlu tırmanışın ardından

o çileğin araladığı

bir bahçenin ufacık

ama kocaman kapısı

bir bahçe ki o, minicik adımlarla keşfeden

bir çocuk olarak dolaştığı

koklamaya korktuğu

toprak kokusunda yürümekten sakındığı

çaresizce akan zamanın

çölün susuz kumunun

yağmurun ıslattığı tenin

dışında hiçbirşey, çocuğun hafızasında bıraktığı

sözlüklerin yazamadığı

anaların anlatamadığı

şairlerin soramadığı

bir dağ çileği o

o kürenin bilinmediği

aranmadığı 

güneşinin ısıtmadığı bir yerde

çocuğun sadece kalakaldığı bir dünya beklediği 

çatınca o küreden çıkma zamanı

çamurun pisliği

camların kırıntısı

akan karın kırmızısı

oysaki o dağ çileğinin tasarladığı

en güzel takısıydı yaprağı

kimi zaman yeşilinin huzuru

kimi zaman kırmızısının sıcaklığı

ayrılma zamanı gelince 

kaf dağına çıktı bilgenin rüyası

o dağ çileğini koparmayan

başka bir çocuğa yazdı zamanı

öptüğü, kokladığı

ama koparamadığı

sadece bakakaldığı

yazıldı dağ çileğinin şarkısı

bir minik kardelen aradı

burnuna kondurulmak üzere tavşanı

bir koku sardı etrafı

bahçeden gelen çalıntı

o unutulacak çocuğu sordular bilgeye

ne oldu ona diye

bilge akıttı gözyaşını

ağlattı soranları

her bir limon damlasıyla yazıldı onun ağıtı

ne bitti denebilir ne de başladı

önüne geçemediği, yazık ettiği ölümü

bırakmayacak yakasını

hakkında rivayetler çıktı sonraları

tez hazırlamışlar dar ağacını

üzerine aldığı tek gömlekte

bir beyaz varmış bir kırmızı

sakın sormayın zamanını

anılarını, acılarını

o dağ çileğinin yarattığı

doyamadığı büyük bahçede arayın cevabı', 'Bir sibirya kaplanının her zaman sahip olduğu ama pencereden hızla eriyen karlar o beyaz saflığın önünde yorulduğu yerine sadece ve daha soğ...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/dag-cilegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arayış', 'seni-arayis-reha-basogul-lc86b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'arayışın bu yüzünde; 

hüzünlü şarkıların tanburuyum 

taksimlerde dolaşan

kimi rüyaların şairi

kimi deryaların kayıp kaptanıyım ben.

ehram görmüş tazeciklerin

şarap görmüş hancıların dergahında

sultanların kadehi

çobanların hissedilmeyen asasıyım ben.

irkilen karanfillerden af dileyen

kırılan burçakların hoşgörüsünde

leylakları toplayan

nergislere boş bakan kucağım ben.

dağların yıkamadıklarına hırslanan

önyargıların ezemediği alçaklığın gençliğinde

kanı karla temizleyen çağın

hiçbir zaman olmayacak varisinin özlemiyim ben.

yalnızlar diyarında dost kapısından açılan

karanlık mahzeninde eskitilen fıçıdan kaçırılan 

herşeyi çözecek, bulunamamış inci tanesini

gözlerinden akıtan deniz kızının bakışlarıyım ben.

doğmamış çocukların beklenen kaderine

ölmemiş dedelerin son soluğuna

yazılmamış kitabın harflerine 

hatla yazılmış laleyim ben.

sürülmemiş toprağın meyvesini veren

çalınmamış güzelliklerin anahtarını diken

işlenmemiş madenlerin parıltısını seçen

kırılmamış kalplerin gülümsemesiyim ben.

girilen kapıların ilk ışığıyım

sönen yıldızların son sözü

kasvetli şimşeklerin gürültüsünde

masumluğun ilk yağmuruyum ben.

anılan oğulların ağıtıyım 

kazılan kuyuların ipi

sızılan inlerin ekmeği adına

saçılan yardımların eliyim ben.

bilinmezim

aranmazım

görülmezim

hissedilenim

ben ışığım

ben acıyım

ben tohum 

ben ölüm...

bende hangi nota, sendeki nokta

hangi sayı resmin...

söyle sen kimsin?', 'arayışın bu yüzünde;  hüzünlü şarkıların tanburuyum  taksimlerde dolaşan kimi rüyaların şairi kimi deryaların kayıp kaptanıyım ben. ehram gö...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/seni-arayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Sokaklarda Bir Gülücüğün Anatomisi', 'bos-sokaklarda-bir-gulucugun-anatomisi-reha-basogul-97cx5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seher, vakitsiz idi bugün

ansızın kulağıma fısıldadı.

zorla götürmek istedi kendine

bir loş ışık, bir kapı...

dumanların tam ortasında

çöplerin biriktiği

kedilerin koklaştığı an.

vakit yersiz, an kaçıyor.

yüzüme tane tane yağıyor sözler

özgürlüğün çoşkulu ilk dansları 

uykusuzlar diyarında bir karnaval

üstünü örtmeyenler ve gecenin örttükleri soluyor havayı.

doğa sessiz, doğa sakin

uzaklıkların sana yakın olduğu anlar bunlar...

düşünürsün oluverir hemen

eril, erkil herşey burada

yabancıların dostluğu çevremde

çirkin yüzlerin melek görüldüğü bir kanepe

bir bez, çırada bir ekmek, 

ıslak gözlerin biriktirdiği bir teneke

açlar sofrasında bir kurt, 

korkulu çocukların oyuncağıyım ben

saçlarımı okşayan

yüzümü tanıyan dostlar.

senden bahsettim biraz onlara

gülümsemeni, bir çiğ tanesinde olabildiğini

gördüğün barksız yavru kediyi anlattım.

çok şaşırmadılar.

her gün görüp ağladıklarıymış

kendi çarelerine biçareyken

sularını paylaştıkları anısıymış.

şaşırmadılar ama yine ağladılar.

ter kokan vücuduma

görülmeyen yaraların kokusu bastırıyor.

arkadan bakanlar dönüp gelmiyor yuvama

sıcak aşın kokusu, gecenin törpüsü oluyor

gidebilecek kadar gücü hissettiğimde

kalktım ortalarından.

bir yarını olan ben

yarınsızları taşıdım evime.

gecelik hayalleri ışıkla yok oluyor birer birer

güzel yüzlerin şeytan görüldüğü bir ayna beliriyor tenlerinde

bir karıncanın kaldıramadığını

isyancılar ordusu kaldırıyor

her gün gülünenlere bileniyor zaman

kalıpsız kalıpları çıkarıyor yüzüstüne

korkusuz korkakların savaşı

an be an yokediyor kahramanları

boş sokakların İstanbul''u burası

asırları deviren şehir

nice aşkı küçülten

nice yetimi büyüten...', 'seher, vakitsiz idi bugün ansızın kulağıma fısıldadı. zorla götürmek istedi kendine bir loş ışık, bir kapı... dumanların tam ortasında çöple...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/bos-sokaklarda-bir-gulucugun-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağın Kırmızısı', 'topragin-kirmizisi-reha-basogul-soazz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani toprağa ayağın değer ya 

ve ruhun yağan damlalarla birleşir o an. 

hani bir sanatçı biçimlendirir ya yüreğinin ham genişliğini 

kıvılcımın ta kendisiydi bunlar. 

işte senle böyle başladı yol arkadaşlığımız 

evreni kucaklayan bir pınarın üzerinde 

bir çiğ tanesi kadar olan bizler 

akıntısına karşı durmak yerine 

bıraktık ya kendimizi derinliklerine 

elleyemediğimiz ışıklardı bunlar. 

engin bir bilinç ne demek anladık o zaman 

isyanların boşluğunu 

fırsatçıların narını bulduğumuz 

alevlerin ortasındakilerdi bunlar. 

kelamımızla muhabbet edişimiz 

bir tek yüreğimizle kalışımız 

kıyam eden yaseminlere tanıklığımız 

karacaları anımsamamızdı bunlar 

soygunlar olsa da 

elimizden alamadığı bir ruhumuzun 

bir gülümsememiz var olduğu 

bir yolcuğun ilk durağıydı bunlar 

nedir gerçekler sence 

hırsımızın kurbanlıkları mı 

kardeşimizin kanları mı 

hipnozun büyüsünü bozduğumuz tarihti bunlar. 

bin çıplak ete 

bir güzel yüreği değişmediğimiz 

kahkahalara kulak asmadığımız 

bir ormandaki filizdi bunlar. 

ortada dev bir karyan 

bir kaç yılan 

biraz da zaman 

boğuşacağımız canavarın sunduklarıydı bunlar 

dağların zulmü 

toprağın hükmü 

bilirsinki ferahın arkasındaki 

aştığımız zahmetti bunlar. 

yastık altında sildiğimiz 

ellerimizle büyüttüğümüz 

sudan daha berrak 

akıttığımız gözyaşlarıydı bunlar. 

uykunun haram olduğu 

masumluğun suç olduğu 

paranın ilah olduğu 

yıkmaya and içtiğimiz şehirlerdi bunlar. 

kucaklara sığdıramadığımız 

paylaşmaktan doymadığımız 

en büyük silahımızı kullandığımız 

zaferin mimarı sevgimizdi bunlar. 

İşte o sevginin sonunda 

nebulaların ortasında 

bir çileğin bıraktığı 

sıcaklığın kırmızısıydı bunlar...', 'Hani toprağa ayağın değer ya  ve ruhun yağan damlalarla birleşir o an.  hani bir sanatçı biçimlendirir ya yüreğinin ham genişliğini  kıvılcı...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/topragin-kirmizisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DİKİLİTAŞ', 'di-ki-li-tas-hasan-basri-unlu-9s5sb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

doğduğumyer

esaplanıpka

ldımhayatım

boyuncayerd

engöğegeçmi

ştengeleceğ

eölümdenyaş

amauzananbi

rtehditoldu

fallusbeden

imbinyaşınd

ayımamahiçk

imseylekarı

ştırmadımy

aşlıkanımıb

benbubedenet

ekbiranlamk

azıyıpbaşım

diktaşıdımk

imsebakmıyo

rartıkbanab

enaslındahi

çuzanmadımb

uncazamanam

asessizlikt

enyorgundüş

tüilgiyemuh

taçbedenimi

yidinleyinb

enisizlerle

ilkvesonkez

konuşacağım

mzamanınmek

ânatehdidin

iartıkkendi

mekıyacağım

YIKILACAĞIM', 'I doğduğumyer esaplanıpka ldımhayatım boyuncayerd engöğegeçmi ştengeleceğ eölümdenyaş amauzananbi rtehditoldu fallusbeden imbinyaşınd ayımam...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Ünlü']::text[], 8.5, '{"poet":"Hasan Basri Ünlü","poet_slug":"hasan-basri-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dikilitas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OYUN', 'oyun-hasan-basri-unlu-nm2gl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oyun oynardık ölümle

Şal desenli rüzgârla bağlasan da gözlerimi

Ölmeden yapılan bir yağmadır bu bilesin

... oyun körebe

Gidişlerinden eksik olmaz geç kalmışlık

Soysuz sürgün neyin olur senin ayrılık

... ölüm körebe

Sanma ki hep misafirdir gözlerindeki karanlık

Ölüm seni de öper bir gün dudaklarından ayrılık

Biz kaçardır hiç durmadan hep kör kütük...', 'Oyun oynardık ölümle Şal desenli rüzgârla bağlasan da gözlerimi Ölmeden yapılan bir yağmadır bu bilesin ... oyun körebe Gidişlerinden eksik ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Ünlü']::text[], 8.5, '{"poet":"Hasan Basri Ünlü","poet_slug":"hasan-basri-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/oyun-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir yani ölüm?', 'nedir-yani-olum-in-use-g8myh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir yani ölüm 

Gömülüp gitmek midir buz gibi toprağın altına

Yoksa, 

Nefes alırken birden bitmesi mi soluğun

Belki de, 

Ruhla bedenin acı veren ayrılığı; barışmanın hayal olduğu

Ya da 

Bir martı kadar özgür ve beyaz, bir o kadar da yakın mı olmak okyanusa

Bir ihtimal

Cezasını bekleyen sanıkların, asık suratlı hakimlerin olduğu duruşmalar...

Nedir yani ölüm, ne olabilir ki, 

Kim bilebilir ki...', 'Nedir yani ölüm  Gömülüp gitmek midir buz gibi toprağın altına Yoksa,  Nefes alırken birden bitmesi mi soluğun Belki de,  Ruhla bedenin acı ...', ARRAY['Türk Edebiyatı','Şiir','In Use']::text[], 8.5, '{"poet":"In Use","poet_slug":"in-use","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nedir-yani-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dörtlük', 'aska-dortluk-in-use-09ymx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk denilen şaraptan daha tatmadım. 

Ama kokusunu derin bir nefesle çektim ciğerlerime, 

Öyle mayhoş ve buruktu ki, 

Rengine kansam da cesaret edemedim içmeye...', 'Aşk denilen şaraptan daha tatmadım.  Ama kokusunu derin bir nefesle çektim ciğerlerime,  Öyle mayhoş ve buruktu ki,  Rengine kansam da cesar...', ARRAY['Türk Edebiyatı','Şiir','In Use']::text[], 8.5, '{"poet":"In Use","poet_slug":"in-use","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aska-dortluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut Ellerimden', 'tut-ellerimden-abdurrahim-karakoc-ret2k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sırat’tan incedir sevda köprüsü 

Beraber geçelim tut ellerimden. 

Niyet ak güvercin, vuslat gökyüzü 

Beraber uçalım tut ellerimden. 

Gönüldeki birlik kalkandır dışa 

Aldırma ayaza, yele, yağışa 

Giden ilkbahara, gelecek kışa 

Beraber göçelim tut ellerimden. 

Birleşmek üzredir şafakla gurûp 

Korku beklenilmez kapıda durup 

İster zehir olsun, isterse şurup

Beraber içelim tut ellerimden.

Çağır hayallerin en ötesini 

Yakından duyarsın aşkın sesini 

Sonsuz mutluluğun penceresini 

Beraber açalım tut ellerimden. 

Hatırla kaybolan hatıraları 

Elmastan ışıklı, altundan sarı 

Zaman tortusundan işte onları 

Beraber seçelim tut ellerimden. 

Şüphe “başlangıç”tır, karar “nihayet”

Zamanı zamana etme şikayet 

Kaçmak kurtuluştur diyorsan şayet 

Beraber kaçalım tut ellerimden. 

(Akıl Karaya Vurdu)  

.

.', 'Sırat’tan incedir sevda köprüsü  Beraber geçelim tut ellerimden.  Niyet ak güvercin, vuslat gökyüzü  Beraber uçalım tut ellerimden.  Gönülde...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tut-ellerimden-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoğun', 'yogun-ozdemir-asaf-48nox', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YOĞUN

Evler, ampûller, bardaklar olacağım.

Ben yaşayacağım neysem öyle kalarak.

Sen boyuna yanımda ağlayıp güleceksin..

Demek ben bakacağım.

Biliyorum, ben bu şişeleri bırakacağım..

Kırılmasın, tozlanmasın dediğim.

Biliyorum, hepsini kıracaklar, hepsini, hepinizi.

Bu raflar, bu kitaplar, bu kutular, sildiğim.

Sizler, şu siz, şu sen, şu o, şu kim..

Uyurken, uyanmışken, şu giden, şu gelen.

Unuttuğum, benzettiğim, bildiğim..

İnsanlar; o siz, bu sen, şu ben.

Kıranları da kıracaklar, ezecekler, bugün, yarın.

Tozlarını silmeyecek bir el, bir bez.

Olanca kapısını açık tutanların

Dışına bile hırsız girmez.

Bir fazla almak bir fazla olmak değil.

Kimler var, vermekle tam kalmışlar.

Üsdenlik dışından parlamak değil..

Yerlerden çok kaçmak toplamışlar.

Ne iyi kırık bir şişe olmak,

Yıkık bir ev, çatlak bir bardak.

Gene de bir şişe, bir ev, bir bardak.

Giderken de biraz daha kendi kalarak.

Evler, ampûller, bardaklar olacağım,

Oluşmak için neysem öyle kalarak.

Sen boyuna yanımda değişeceksin,

Boyuna öleceksin, ben bakacağım.', 'YOĞUN Evler, ampûller, bardaklar olacağım. Ben yaşayacağım neysem öyle kalarak. Sen boyuna yanımda ağlayıp güleceksin.. Demek ben bakacağım....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yogun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alarga Gönül', 'alarga-gonul-nazim-hikmet-ran-8wyqj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alarga gönül: 

             Demir al...

Kırmızı bir amiral

                         gibi kaptan köprüsüne çık...

Karşında deniz: 

                    kaşı çatık 

                             sana bakan

                     kocaman

                              mavi bir göz...

Alarga gönül, 

                  palamarı çöz...

                     
..........
..........', 'Alarga gönül:               Demir al... Kırmızı bir amiral                          gibi kaptan köprüsüne çık... Karşında deniz:            ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/alarga-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süpriz', 'supriz-omer-avsar-ieoos', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayalmisin yoksa gerçekmi bilemedim

Bir anda dünyama giriverdin

Tam kapatmışken kalbimin  kepenklerini

Bana aşkı sevmeyi emrettin

Bak şimdi yapılırmı güzelim bu bana

Ne güzel alışmıştık ruh gibi yaşamaya

Başı belli sonu belli cansız masala

Yeni bir resim çizdin emsalsiz inancınla

Şimdi acıdım kendime

Beynimi yolladım yüregimin diplerine

Tekrar geldi özlem, aşk sahneye

Acımam bana degil sensiz geçen günlere..', 'Hayalmisin yoksa gerçekmi bilemedim Bir anda dünyama giriverdin Tam kapatmışken kalbimin  kepenklerini Bana aşkı sevmeyi emrettin Bak şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/supriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu da Bir Yalnızlıktır...', 'bu-da-bir-yalnizliktir-i-lker-bayulken-ztv1h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok güzeldi.Çok güzel olduğu kadar uzaklardaydı da.Bu diyardan olamazdı asla...Gözlerinin ışıltısı; bu rutinler kentinin, bu esaretler zincirinin, bu karanlıklar nehrinin yalanlarını duymadığını söylüyordu...

     Acıların; içimi boşaltan kuru soğuk rüzgarlarının dinişindeki huzursuz bir sukunette gördüm onu.Ne kederden ölüyordum, ne de mutluluktan göklere uçuyordum onu gördüğümde.Çok sessizdim; sadece sessiz...

     Gülüyordu...Benim gibi bir tutam mutluluğu göklerde aramadığı için gülmeye zorlamıyordu kendini ve bu yüzden sahtekar olmakla suçlamıyordu insanlar onu.Yarınların kendisine ne getireceğini merak eden heyecanlı bakışların içindeki tebessüm yanardağlarının kıvılcımlarıyla bağlıydı hayata...

      Kirlenmemişti, neşe doluydu...Ayrı dünyaların insanı olma kavramının acı gerçekliğini onda tattım acımasız tokatın beni bana getiren sersemlik nöbetlerinde.''Evet, bambaşka dünyaların insanlarıydık biz! ''Saatin 12''yi çeyrek geçmesinden ve bugün havanın ne kadar soğuk olmasından başka paylaşacak bir şeyimiz yoktu.Babasının okul notlarının kötü olmasına verdiği tepkiler ve en sevdiği TV programının ertesi güne ertelenmesi gibi içinden çıkılmaz acıları vardı...

     Geçte olsa anlamıştım bu gerçeği.İlk ve son kez derin derin gözlerine bakıp, başımı önüme eğerek tüm kirlenmişiğimle hızlıca uzaklaştım oradan.Ne o hak ediyordu böylesini ne de ben o denli bencil olamazdım...

     Çok güzeldi.Çok güzel olduğu kadar uzaklardaydı da.Bu diyardan olamazdı asla...

      (Eskişehir,15 Ocak 2001)', 'Çok güzeldi.Çok güzel olduğu kadar uzaklardaydı da.Bu diyardan olamazdı asla...Gözlerinin ışıltısı; bu rutinler kentinin, bu esaretler zinci...', ARRAY['Türk Edebiyatı','Şiir','İlker Bayülken']::text[], 8.5, '{"poet":"İlker Bayülken","poet_slug":"i-lker-bayulken","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-da-bir-yalnizliktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahverengi', 'kahverengi-oropa-seni-0zln4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen; 

Sen tum renklerisin

gokkusagimin

kirmizi yesil mavi

ve bir de 

gozlerinin

o vurgun rengi

Ama bir tek gri olma 

tek istegim tanridan

bilirsin gri

''''elvedadir 

soguk bir kis gununde 

tren penceresinden bakan

adsizlastirir sevdasini

attigi mektupla 

son istasyondan''''

Sen; 

Sen tum renklerisin 

ilkbaharimin

kirmizi yesil mavi

ve gozlerinin

o vurgun rengi...

Simdi oldun gri

gittin ellere

sag yanim

ille de soyluyor yine

''''allah sahibine bagislasin

bize de nasip etsin''''  diye', 'Sen;  Sen tum renklerisin gokkusagimin kirmizi yesil mavi ve bir de  gozlerinin o vurgun rengi Ama bir tek gri olma  tek istegim tanridan bi...', ARRAY['Türk Edebiyatı','Şiir','Oropa Seni']::text[], 8.5, '{"poet":"Oropa Seni","poet_slug":"oropa-seni","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kahverengi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce ve sık dokunurdu', 'i-nce-ve-sik-dokunurdu-mustafa-yavuzyilmaz-3hndu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnce ve sık dokunurdu ellerin

Dudaklarıma örerdin ağını; konuşamazdım

Gözlerin gözlerime meydan okurdu; susardım

Bır duvar soğukluğunda iç içe kalmıştık

Aynı tende farklı damarlara sapmış, içten içe ayrılmıştık

İnce ve sık dokunurdu ellerin; korkardım

Zehrini dağıtan suretinden...

Kanatlarıma jilet atardım

Birimizden biri aksın tül perdeden kefene

Çıkmasın ne ağından ne de ruhundan

İnce ve sık dokunurdu ellerin, aradım yine

Ben o gün kendimi astım işte!', 'İnce ve sık dokunurdu ellerin Dudaklarıma örerdin ağını; konuşamazdım Gözlerin gözlerime meydan okurdu; susardım Bır duvar soğukluğunda iç i...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yavuzyılmaz']::text[], 8.5, '{"poet":"Mustafa Yavuzyılmaz","poet_slug":"mustafa-yavuzyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ince-ve-sik-dokunurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehirde', 'bu-sehirde-serkan-cekirge-ue0fw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Istanbul''da kar var, 

Beyaz martılar karaya vurmuş.

Bende simsiyah zifiri bir karanlık, 

Üşüyorum...

Karanlık üşütmez ki yalnızlık kadar.

Her yerde kar var.

Sen ben güneş karlar altında. 

Güle güle sarışın toprak gözlü kız

Güle güle pempe pileli etekli sarışın kız

güle güle yaz

Güle güle...', 'Istanbul''da kar var,  Beyaz martılar karaya vurmuş. Bende simsiyah zifiri bir karanlık,  Üşüyorum... Karanlık üşütmez ki yalnızlık kadar. He...', ARRAY['Türk Edebiyatı','Şiir','Serkan Çekirge']::text[], 8.5, '{"poet":"Serkan Çekirge","poet_slug":"serkan-cekirge","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bu-sehirde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-gokhan-oktem-a1h5o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Prematüre bir sevinin sentezi: 

İlkel bir doyumsuzluk, 

                 Yoğun bir acı, 

                      Ve ürkek bir yürek...

Ki o yürek hapsederek acıyı kendi dehlizinde

Kaybolur gider kendi yitik evreninde...', 'Prematüre bir sevinin sentezi:  İlkel bir doyumsuzluk,                   Yoğun bir acı,                        Ve ürkek bir yürek... Ki o yü...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yitik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elde kalan', 'elde-kalan-gokhan-oktem-7amif', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir soğuk duş etkisiydi benimki 

Zamansızdım evvel zaman içinde

Ben zamandım zaman, zaman içinde

Yanılmışım an’ dım zaman içinde

Başa baştım söndüm zaman içinde

Başladığım yere döndüm zaman içinde

Ben zamana zaman bana çelmeydi

Yitik adımlardı  sevişmelerim

Zamansızdı, mekansızdı, arsızdı

Kaybedilen aşk değildi zamandı

Aşka teğet geçmedim hiç bir zaman

Kantar çekmez umutlardı tartılan

Su götürmez gerçekleri salya sümük yaladım 

Geçmişimde yitik yok var olan elde kalan

(İstanbul,1997)', 'Bir soğuk duş etkisiydi benimki  Zamansızdım evvel zaman içinde Ben zamandım zaman, zaman içinde Yanılmışım an’ dım zaman içinde Başa baştım...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/elde-kalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Med-cezir', 'med-cezir-gokhan-oktem-h4r8j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözleri ufka kilit, gönlü aklına esir

Soru okyanusunda bir meddim bir cezirdim, 

En bildik hislerinde bir yitiği arayan

Kendi evreninde yitik bir serseri meteordum ben...

(İstanbul,1997)', 'Gözleri ufka kilit, gönlü aklına esir Soru okyanusunda bir meddim bir cezirdim,  En bildik hislerinde bir yitiği arayan Kendi evreninde yiti...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/med-cezir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüy', 'tuy-gokhan-oktem-sgo1h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kırık kuş kanadında bir  tüydüm

Zemheride kanada tüy örtüydüm

Zaman geldi  ne kuş kaldı ne kanat

Zımlamadan zaman beni ben tüydüm

(İstanbul,1997)', 'Bir kırık kuş kanadında bir  tüydüm Zemheride kanada tüy örtüydüm Zaman geldi  ne kuş kaldı ne kanat Zımlamadan zaman beni ben tüydüm (İstan...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tuy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-gokhan-oktem-lp4o8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşka dair kalmadı hiçbir sözüm

Son sözümü ilk nefeste söyledim; 

Bilmez idim çeke, çeke bilendim

Aşk aşığa aşık aşkaymış aşık...

(İstanbul,1997)', 'Aşka dair kalmadı hiçbir sözüm Son sözümü ilk nefeste söyledim;  Bilmez idim çeke, çeke bilendim Aşk aşığa aşık aşkaymış aşık... (İstanbul,1...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/soz-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden Seni Otobüs Alıp Götürürdü', 'eskiden-seni-otobus-alip-gotururdu-erhan-sipahioglu-lkcmd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eskiden Seni Otobüs Alıp Götürürdü

ama biz bu mesafeleri aşardık

şimdi burnumun dibinde olsan bile

mesafeler otobüsün götürdüğünden

daha uzak

ben şimdi dönüşü olmayan 

bir otobüste

sen ise reddeden  kinli yaşlı gözlerinle

beni kıskandırmak için

hiç sevmediğin birisiyle', 'Eskiden Seni Otobüs Alıp Götürürdü ama biz bu mesafeleri aşardık şimdi burnumun dibinde olsan bile mesafeler otobüsün götürdüğünden daha uza...', ARRAY['Türk Edebiyatı','Şiir','Erhan Sipahioğlu']::text[], 8.5, '{"poet":"Erhan Sipahioğlu","poet_slug":"erhan-sipahioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eskiden-seni-otobus-alip-gotururdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy Diye', 'duy-diye-mahmut-dogan-5y7dx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir olsun diye yazmıyorum inan...

Bir sana duyurmak dileğim

Benim: 

Yürek çarpıntılarımı

Çektiğim acılarım burukluğunu

Hayal dünyamın kırık-döküklüğünü

Umutlarımın yitikliğini, 

Bir sana duyurmak dileğim

Bir sana duyurmak dileğim

Senin: 

Taş yürekliliğini

Ölçüye gelmeyen zalimliğini

Usandıran kahreden umursamazlığını

Granit kayalarca katılığını

Ve de benzersiz güzelliğini

Bir sana duyurmak dileğim

Şiir olsun diye yazmıyorum inan...', 'Şiir olsun diye yazmıyorum inan... Bir sana duyurmak dileğim Benim:  Yürek çarpıntılarımı Çektiğim acılarım burukluğunu Hayal dünyamın kırık...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Doğan']::text[], 8.5, '{"poet":"Mahmut Doğan","poet_slug":"mahmut-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/duy-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECENİN AYDINLIK YÜZÜ', 'geceni-n-aydinlik-yuzu-sema-gulser-keser-gl9xe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine gece, 

Ve gökyüzü 

              korkuları besleyen o korkunç fonunda

Yanan mum, 

Islak tenim, 

Esrik düşler bir de sen...

Dinlediğim ezgi  ve adın çalıyor beni.

Sesler sessizliği kovalarken, 

Açılıyor ömrümün yaprakları.

Şimdi, 

İçimdeki yangın beni vurmakta.

Zamanın sarkaçlarında yıllar can çekişiyor

Renkli kitaplarım dilsiz kalemlerim

 ağıt yakıyor ezik sesime.

Sigaramın dumanı yakalarken umutlarımı, 

Gözlerimin buğusu örtüyor usumu.

Yüreğimi düşlerin es noktasında bırakıyorum.

Anımsamaya çalışıyorum! 

Geceyi mi yeniyor yalnızlığım? 

Yoksa gecenin gölgesi mi şavkıyor bilincime? 

Gel gitler arasında seni aradığımı anlıyorum

 Sevdanın yalımı okşuyor  yüzümü

İçselliğimde harmanlanıyor gece ve yüzün

Işığın tanrısı! 

Hani ertelemesen gelişini

Karanlığı süpürsen

Türkü gibi dolansan boynuma

Sihirli öpüşünle kutsasan...

Yiğitçe hesaplaşırım korkuyla 

Işığını yakalasam.

Gözümde kalmasan, bir de sevdamı anlasan...

                                                     07-01-2002    ÇORUM', 'Yine gece,  Ve gökyüzü                korkuları besleyen o korkunç fonunda Yanan mum,  Islak tenim,  Esrik düşler bir de sen... Dinlediğim e...', ARRAY['Türk Edebiyatı','Şiir','Sema Gülser Keser']::text[], 8.5, '{"poet":"Sema Gülser Keser","poet_slug":"sema-gulser-keser","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gecenin-aydinlik-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim Bir Dunyadir', 'sevgilim-bir-dunyadir-gokhan-can-0fgsv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mezardan ben yeni geldim, Sevgilimi gördum cok agladim, 

Acimas oldum bu sevdada, Ayrilmas oldum bu kötu dunyada, 

Agliyorum Agliyorum guner göz yasda bitmiyor, 

Aciyor Aciyor Kalbim sevda icin Seviyor, 

Ben seni hic Unutmaycam canim Sevgilim, Elveda rahat yat

sevgilim..', 'Mezardan ben yeni geldim, Sevgilimi gördum cok agladim,  Acimas oldum bu sevdada, Ayrilmas oldum bu kötu dunyada,  Agliyorum Agliyorum guner...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Can']::text[], 8.5, '{"poet":"Gökhan Can","poet_slug":"gokhan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevgilim-bir-dunyadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'çoğalıyor istanbul..', 'cogaliyor-istanbul-rabia-can-ulas-sthwa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nereye uğrasam sana uğruyor tüm kederlerim

çoğalıyor şu istanbul şehri, 

seni aramaya çıktığım her akşam.

bir sokağa orhan veliden bir şiiri rehin bırakıyorum

bir kıyıya zeki mürenden bir şarkı..

ama her adımımda büyütüyor bu kent kendini

ben senin hüzünlerine ve gözyaşlarına, 

rehinim zaten ve tüm dizelerim sende

o yüzden ödünç dizeler ve seslerle geçiyorum geceleri

ama bu kentlerin yoldan çıkmış sokaklarının, 

en çok bir tanrıya ihtiyacı var..

şiirden sevgiden önce onları anlama yeteneği kazandıracak.

bir tanrı lazım..

minarelerden düşen seslere tıkanmış bu kulaklar..

üçüncü gözlerine ışık salacak.

bir aydınlığa ihtiyaçları var..

ve sen kendini böylesine sarmışken hüzünlere kimden ilham alacak

bu sokaklar..', 'nereye uğrasam sana uğruyor tüm kederlerim çoğalıyor şu istanbul şehri,  seni aramaya çıktığım her akşam. bir sokağa orhan veliden bir şiiri...', ARRAY['Türk Edebiyatı','Şiir','Rabia Can Ulaş']::text[], 8.5, '{"poet":"Rabia Can Ulaş","poet_slug":"rabia-can-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cogaliyor-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi ırmak', 'asi-irmak-emine-sumra-z9ixq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz ikimiz asi ırmak gibiyiz.

Birleştikçe ayrı kollardan, 

Çarpar kıyılara acı dolu köpüklerimiz.

Halbuki sevinç olmalıydı mavi sularımız.

Simsiyah taşları sararken kıvrımlarımız.', 'Biz ikimiz asi ırmak gibiyiz. Birleştikçe ayrı kollardan,  Çarpar kıyılara acı dolu köpüklerimiz. Halbuki sevinç olmalıydı mavi sularımız. S...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asi-irmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleğim', 'melegim-emine-sumra-jdpn0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Melekmi şeytanmısın bebeğim? 

Bazen eline su bile dökemez bilirim.

Nasılda zalim oluyorsun böyle? 

Eseflenir seni gördükçe şeytan

Ben bunu niye düşünmedim diye.

Tam karar veriyorum şeytan olduğuna.

Sanki beni yalancı çıkartmak ister gibi.

O kadar iyi oluyorsunki.

Melekler kıskanır seni.

Yaptıklarını görünce.

Melekte olsan, şeytanda iyiki varsın.

Canım eşim', 'Melekmi şeytanmısın bebeğim?  Bazen eline su bile dökemez bilirim. Nasılda zalim oluyorsun böyle?  Eseflenir seni gördükçe şeytan Ben bunu n...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/melegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sevmek', 'seni-sevmek-emine-sumra-htnuy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevmek zulüm gönlüme.

Sensizliğe adım attım bile bile

Ne zaman göreceğim meçhul.

Saçlarını okşayamayacağım belkide.

Bilinmezlik en kötü şey aşk için.

Yada beklemek sonsuza kadar.

Aşk ne yücesin, 

Cennetine maal oldun adem ile havvanın.

Cennet meleklerin olsun.

Ben sensiz kalmaktan korkarım.', 'Seni sevmek zulüm gönlüme. Sensizliğe adım attım bile bile Ne zaman göreceğim meçhul. Saçlarını okşayamayacağım belkide. Bilinmezlik en kötü...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-sevmek-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımı illaki birşeylere benzetseydim...', 'askimi-illaki-birseylere-benzetseydim-sukru-tahmaz-9pb95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana olan sevgimi birşeylere benzetseydim

Önce yağan yağmur altında ıslanan aşıklara

Yağmur dindikten sonra parıldayan güneşe

Çukulata yerken üstünü kirlenmiş çocuğun sevincine

Yıkandıktan sonra çocuğun o tertemiz gülüşüne

Karlar üstünde kartopu oynayan gençlere

Karlar kaltığında birbirine kavuşanlara

Sevincinden ağlarken yaşaran gözlere 

O yaşları silerken okşayan ipek mendile

Gece hayallerine sarılan yanlızlara

Yanlızlığı bitiren o bütün olaylara

Akan ırmakların kıyısında güllere

Irmağa baraj kurulunca suya kavuşanlara

Gece gündüz çalışıp ter akıtanlara 

Emeğinin sonunda tam hakkını alana

Küçük bir bülbülün mest eden ötüşüne

Ona eşlik ederken komik çıkan ıslığa

Küçücük bir çocuğun cüzi hediyesine

Koca adam olunca pahasız zümrütüne

Kendi açken lokmasını pay edene

Kendi tokken açları her vakit düşünüşüne

Küçücük bir evin panjurunun rengine

Koca bir bina için atılan sağlam temellere

Bugünlerin hakkıyla mutlu yaşanışına

Yarınlar için aydın günlere yatırıma

Havanın soğunun dinçleştiren yanına

Isınınca birazcık mest eden ılığına

Anne diye ağlayan saf ve küçük bebeğe

Annesine kavuşup mutluluktan gülüşüne

Senden önce değerini anlatan hatalarıma

Sana kavuştuğumda geçmiş için pişmanlığa

Tez zamanda kavuşulan sürekli mutluluğa

Adına tez yazılır bitmez tükenmez aşkıma

Espiriye gülmeyip somurtan şu ülkede o tatlı gülüşüne

Ülkeye refah getirip dertleri çözeceklere

O küçücük elinde parıldayan ışığa 

Kalten kalbe bir köprü kurmuş sevdamıza

Ben değil biz diye konuşmayı öğretene

Bizden öte sen diye düşündüren aşkına

Ve sana olan sevgimi ilaki bir şeye benzetmem gerekseydi

Tek başına sadece kendine benzetirdim

Her şeyin ötesinde üç dilek hakkım kalsa

Üçünüde sana dilerdim mutlu sağlıklı ve sonsuz yaşa derdim.', 'Sana olan sevgimi birşeylere benzetseydim Önce yağan yağmur altında ıslanan aşıklara Yağmur dindikten sonra parıldayan güneşe Çukulata yerke...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tahmaz']::text[], 8.5, '{"poet":"Şükrü Tahmaz","poet_slug":"sukru-tahmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/askimi-illaki-birseylere-benzetseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Son Vapur', 'bu-son-vapur-sukru-tahmaz-tkgwj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu son vapur kalkar birazdan

Gece bulamazsında başka vapur

Beni düşünme kıvrılır yatarım bir banka

Hem sen değilmiydin gitmek isteyen

Ayyaş dediğin evsizler arkadaş olur

Hem sadece bir gecelik bu

Gündüzünde yine evde olacağım ama

Ama sen olmayacaksın ben yanlız

Kimsesizlik değil korkum 

Sen alışkanlığımdın desem

Sabah peynirim, çayım gevreğim

Yo bu alışkanlık değil güzelim

Sen benim ilk ve son sevdiğim

Sen istemesende ömür boyu seveceğim...', 'Bu son vapur kalkar birazdan Gece bulamazsında başka vapur Beni düşünme kıvrılır yatarım bir banka Hem sen değilmiydin gitmek isteyen Ayyaş ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tahmaz']::text[], 8.5, '{"poet":"Şükrü Tahmaz","poet_slug":"sukru-tahmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-son-vapur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma itafen', 'askima-itafen-sukru-tahmaz-y9scq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sana yazdığım ilk söz olsun, İlk siir ilk beste

Belkide ünlü olur söylenir dilden dile

Bu şarkı dillerde bu şarkı heryerde

Yarınlarda görürmüyüm seni, aşkım gibi suretini

O kumral saçlarını okşar mıyım, bir gün gelir evimizde

O kahve gözlerine kavuşur muyum, kırk yıl hatrı olan

O kahve gözlerine, O kahve gözlerine

İlk tanıştığımız günü hatırlasam, Ah o en şanslı günümü ben

İkinci doğum günüm belki de, o gün doğdum

Yardım et bana aşkım söyle o günü sen

Söyle o günü sen, Söyle o günü sen', 'Bu sana yazdığım ilk söz olsun, İlk siir ilk beste Belkide ünlü olur söylenir dilden dile Bu şarkı dillerde bu şarkı heryerde Yarınlarda gör...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tahmaz']::text[], 8.5, '{"poet":"Şükrü Tahmaz","poet_slug":"sukru-tahmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askima-itafen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Güz Geldi Ömür Hanım', 've-guz-geldi-omur-hanim-sukru-erbas-rulcp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve güz geldi Ömür Hanım. Dünya aydınlık sabahlarını yitiriyor usul usul. İnsanın içini karartan bulutların seferi var göğün maviliğinde.

Yağmur ha yağdı ha yağacak. İncecik bir çisenti yokluyor boşluğunu insan yüreğinin. Hüznün bütün koşulları hazır. Nedenini bilmediğim bir keder akıyor damarlarımdan. Kalbimin üstünde binlerce bıçak ağzı, yüzüm ömrümün atlası, düzlükleri bunaltı, yükseklikleri korku, uçurumları yıkıntılarımla dolu bir engebeler atlası. Yaşamak bir can sıkıntısı mıdır Ömür Hanım? 

Her şeyi iyi yanından görmeyi kim öğretti bize? Acıyı görmeyen insan, umutsuzluğu yaşamayan, iliklerine dek kederin işleyip yaralamadığı bir insan, mutluluktan, umuttan, sevinçten ne anlar? 

Göğü görmeden, denizi görmeden maviyi anlamaya benzemez mi bu? Bir güz düşünün ki Ömür Hanım, ilkyazı olmamış, yazı yaşanmamış. Böyle bir güzün hüznü hüzün müdür? Başlamanın bir anlamı varsa bitişi göze almak, bitişin bir anlamı varsa başlangıcı olmak değil midir? 

Yaşamı düz bir çizgide tutmak tükenmektir. Yaşamak zorunda olduğumuz şunca yılı aykırı uçlar arasında gezdirip geçirmedikçe, alışkanlıkların sınırlarını aşmadıkça zaman zaman, yaşamak nasıl yenilik olur tükenmek değil de? 

Yağmur yağıyor ömür hanım... Gökten değil, yüreğimin boşluğundan ömrümün ıssız toprağına... Ve ben sonsuz bir düzlükte bir küçücük bir silik nokta gibi eriyip gidiyorum. Seslensem kim duyar sesimi yalnızlıklar katından? 

Dönelim... Dönmek yenilmektir biraz da, yarım kalmasıdır çıkışlarımızın, korkaklıktır, alışkanlıkların güvenli küflü kabuklarına sığınmaktır... Olsun dönelim biz yine de. Bilincinde olmadan üstlendiğimiz sorumluluklarımız var. Evlere dönelim, sırtımızın kamburu evlere, cılızlığımızın görkemli korunaklarına, yalnızlığımızın kalelerine dönelim. Ölçüsüz yaşamak bize göre değil Ömür Hanım. Büyürken geniş ufuklarımız olmadı bizim. Küçücük avuçlarımızla sınırlarımızı genişletmek istedikçe yaşamın binlerce engeli yığıldı önümüze. Hangi birini yenebilirdik bunca olanaksızlık içinde. Umutsuzluğu tanıdık, yenilgiyi öğrendik böylece.

Yaşama sevinci adına bir tutamağım kalmadı Ömür Hanım. Bir garip boşlukta çiviliyim günlerdir gözbebeklerimden. Sahi nedir yaşamın anlamı? Geriye dönüyorum sık sık yanıt aramak adına, yüreğimin silik izler bırakıp, ağır yükler aldığı zamanın derin denizlerine. Bakıyorum 
..........
..........', 'Ve güz geldi Ömür Hanım. Dünya aydınlık sabahlarını yitiriyor usul usul. İnsanın içini karartan bulutların seferi var göğün maviliğinde. Yağ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ve-guz-geldi-omur-hanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğulmadan Evveldi', 'bogulmadan-evveldi-sukru-tahmaz-du5j8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinin okyonusunda boğulmadan evveldi

Evvel saatler evet gecelerdi seninle

Solukluğuna bandığım ekmeğimi 

Üzüm gözlerinden pekmekle karmamıştım henüz

Henüz sensizliği tatmamıştım hayatta

Yanlızlıktan better sensizliği soğukta

Ayaz gecelerinde balkan soğukları gibi

İçime işleyen garipliğim derinden yaraladı

Anasız, babasız kalmaya alıştığım günlerde

Birde sen gittin apansız

Hani zamanını söyleseydin ayrılığın

Ayrılığı hiç beklememiştim nedense

Senle bir ömür umuşlarımda ayağım kaydı

Saplandım ayrılığın beyazlığında don tuttum

Hani sen nereden bileceksin dedim sonra

Ah keşke bilerek yaşansaydı kırarmıydım seni

Kahrolası kanser seni alıncaya 

Seni üzermiydim bulut ağırlığında meselerle

Ve haykırmazmıydım gözlerimde

Seni ne çok sevdiğimi kör olasıya...', 'Gözlerinin okyonusunda boğulmadan evveldi Evvel saatler evet gecelerdi seninle Solukluğuna bandığım ekmeğimi  Üzüm gözlerinden pekmekle karm...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tahmaz']::text[], 8.5, '{"poet":"Şükrü Tahmaz","poet_slug":"sukru-tahmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bogulmadan-evveldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel elini koy yüregime', 'gel-elini-koy-yuregime-sukru-tahmaz-0rr9p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Palmiye süslü sokaklarında bir kentin

Seni düşündüm derinliklerinde mavinin

Aklımdan hiç çıkaramadığım sende 

Vurgun yedim ılık bakışlarında rengarenk

Seni düşünmeden varlığım yokluğa

Kütlem boşluğa dönüşüyordu ve seni düşündüm

Çözümsüz onbeş problem mi kalmış? 

Bana sorsunlar yaşamım karşılığında

Ben ki problemde bir sembol olmuş bir sayı bir nokta

İçinde yaşıyorum problemin belli belirsiz

Ya sinus ya integral yada toplam sembolü olmalıyım

Yo bir sıfır yada virgülün sağında küçük bir rakam olamam

Fakat en zor problemi yaşasamda hayatta

Tüm formüller cebimde sen yanımda oldukça

Ve senle yaşarım sadece o bembeyaz keğıdın üzerinde

Ne mi söyleyecektim sana 

Seni seviyorum diyecektim kabul görürse

Yalın bir seviyorum yerine çok mu zırvaladım sence

Neyse Aşkım kelimeler anlatamaz gel elini koy yüreğime...', 'Palmiye süslü sokaklarında bir kentin Seni düşündüm derinliklerinde mavinin Aklımdan hiç çıkaramadığım sende  Vurgun yedim ılık bakışlarında...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tahmaz']::text[], 8.5, '{"poet":"Şükrü Tahmaz","poet_slug":"sukru-tahmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gel-elini-koy-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-i-smail-ozabaci-k6kam', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sürgün şehirde 

Dev bir yalnızlıkla yaşamak

Nedir bilir misin? 

Seni düşlemek gece yarılarında

Sesini, gülüşünü, nefesini hissetmek

Soğuk bir yurt odasında

Çiçek kokularıyla büyüttüm hüznümü

Sevinçlerimi ona verdim

Ve hep seni sevdim

Biliyorsun seni sevmek yaşamak demek

Ve yaşamak senle güzel

Seni seviyorum

Öyleyse yaşıyorum', 'Bir sürgün şehirde  Dev bir yalnızlıkla yaşamak Nedir bilir misin?  Seni düşlemek gece yarılarında Sesini, gülüşünü, nefesini hissetmek Soğu...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-sevmek-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sesli düşünceler', 'sesli-dusunceler-faruk-elma-id7uq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevmek ve 

terketmek 

karşı konulmaz iki güç

 düşününce kahroluyor insan

ama bir türlü vazgeçilmiyor

seni sevmek 

ve 

yaptıkların için senden nefret etmek 

ama  hala arzu duyuyorum sana

ve 

ama hatırlatıyorum bana yaptıkların için 

söz vermek kolaydır 

önemli olan onu sonuna kadar savunmaktır 

harcamak hayatı ne pahasına 

yaşamak desteklemk sevgiyi

takvimden yaprak kopar 

kalbimden kanlar akar

düşünmek seni günlerce

ve kapatmak gözlerimi gözlerine

sabah ışığı gibiydin eskiden 

şim di ya şimdi

gecelerimin korkulu rüyası', 'sevmek ve  terketmek  karşı konulmaz iki güç  düşününce kahroluyor insan ama bir türlü vazgeçilmiyor seni sevmek  ve  yaptıkların için sende...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sesli-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-cetin-akgun-js7kr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuzluğa doğru yol almış gidiyorum

Yolunu kayıp etmiş bir rehber misali

Nerden gideceğimi

Nerde duracağımı

Bilmiyor sürekli ilerliyorum

Bu ilerleyiş nereye kadar, bilmiyorum

Tek endişem; YALNIZLIK

Hayaller kurup yaşamaktansa

Bu hayatı benimle paylaşacak

Sevgili arıyorum

Aramak yetmiyor olsada

Yapa bilecek bir şeyler arıyor

Nereden başlıyacağımı düşünüyor

Evrene haykırmak istiyorum

Yalnız yaşamak istemiyorum

Bir deniz dalgası gibi

Dalgalanıyor oluşum

Yalnızlığım için olsa gerek

Sonsuzluğa doğru gidiyor olsam dahi

Hayat devam ediyor

Ve EDECEK

Taki yalnızlık tan kurtuluncaya kadar.', 'Sonsuzluğa doğru yol almış gidiyorum Yolunu kayıp etmiş bir rehber misali Nerden gideceğimi Nerde duracağımı Bilmiyor sürekli ilerliyorum Bu...', ARRAY['Türk Edebiyatı','Şiir','Çetin Akgün']::text[], 8.5, '{"poet":"Çetin Akgün","poet_slug":"cetin-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizlik-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'aynalar', 'aynalar-faruk-elma-62p4i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aynalar yalan söylemiyordu

bir tek şey farkediliyordu

esir düşen gözler

param parça içimi acıtan

anladım ve kendime döndüm 

dokunuşlarda gizlidir

o dokununca anladım 

karanlıkta sadece ikimiz', 'aynalar yalan söylemiyordu bir tek şey farkediliyordu esir düşen gözler param parça içimi acıtan anladım ve kendime döndüm  dokunuşlarda giz...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aynalar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'aşk dedim', 'ask-dedim-faruk-elma-sqgus', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşk dedim 

acı çekmek 

dokunmak ağlamak 

karanlıkta gözlerini görmek

dünü yaşamak 

bugünü yaşamak

yarını ümit etmek

ve düşlemek ömür boyu', 'aşk dedim  acı çekmek  dokunmak ağlamak  karanlıkta gözlerini görmek dünü yaşamak  bugünü yaşamak yarını ümit etmek ve düşlemek ömür boyu...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-dedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'üçüncü PERDE', 'ucuncu-perde-kemal-taskin-ta7n7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'üçüncü perde...

sonu 

  belli olmayan

üç perdelik 

  bir oyunun

tedirgin

  ve de

çaresiz 

oyuncularıyız  sadece...

birinci perdeyi 

   sen oynadın 

 her zaman (ki)

                   gibi! 

ikinci perdeyi 

   beraber oynadık

gülüşleri ve ağlayışları

   kardeş 

              bilerek...

üçüncü perde 

                 hala

     devam ediyor...

        ve biliyormusun? 

herşey  senin elinde!', 'üçüncü perde... sonu    belli olmayan üç perdelik    bir oyunun tedirgin   ve de çaresiz  oyuncularıyız  sadece... birinci perdeyi     sen o...', ARRAY['Türk Edebiyatı','Şiir','Kemal Taşkın']::text[], 8.5, '{"poet":"Kemal Taşkın","poet_slug":"kemal-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ucuncu-perde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan ve Allah', 'i-nsan-ve-allah-necip-fazil-kisakurek-6g0uz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan...İplikte büklüm, suda bir anlık suret...

ALLAH...Olmanın O''na mahsus olduğu kudret...

(1974)', 'İnsan...İplikte büklüm, suda bir anlık suret... ALLAH...Olmanın O''na mahsus olduğu kudret... (1974)...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/insan-ve-allah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '8.10 Vapuru', '8-10-vapuru-cemal-sureya-hmv33', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sesinde ne var biliyor musun

Bir bahçenin ortası var

    Mavi ipek kış çiçeği

    Sigara içmek için 

    Üst kata çıkıyorsun

Sesinde ne var biliyor musun

Uykusuz Türkçe var

    İşinden memnun değilsin

    Bu ke
..........
..........', 'Sesinde ne var biliyor musun Bir bahçenin ortası var     Mavi ipek kış çiçeği     Sigara içmek için      Üst kata çıkıyorsun Sesinde ne var ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/8-10-vapuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal Sağlıcakla', 'kal-saglicakla-cemal-safi-pse0m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kader defterimin dram bölümü; 

Sana tutsak ettim sefîl gönlümü, 

Esaret yerine bil ki ölümü, 

Seçerim sevgilim kal sağlıcakla.

Benimle bir dünya dar geldi sana, 

Seviyorum demek ar geldi sana, 

Kara toprak daha yâr geldi bana, 

Göçerim sevgilim kal sağlıcakla.

Göçüp gidenlerin son nefesini, 

O sessiz ülkenin efsânesini, 

Hayatla ecelin mesafesini, 

Ölçerim sevgilim kal sağlıcakla.

Çektiğim çileler gelmiyor dile, 

Söylesem nafile, yazsam nafile, 

Senden vazgeçersem, Sırat''tan bile

Geçerim sevgilim kal sağlıcakla.', 'Kader defterimin dram bölümü;  Sana tutsak ettim sefîl gönlümü,  Esaret yerine bil ki ölümü,  Seçerim sevgilim kal sağlıcakla. Benimle bir d...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kal-saglicakla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk', 'ey-ask-cetin-akgun-outi2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey Aşk sen ne yaptığının farkındamısın

Seni birtürlü çözemiyorum

Oysa sen

Nicelerini sevince boguyor

Nicelerini ise hüzünlendiriyorsun

Sana kızmayı, haykırmayı düşlüyorken

O anda senin hiçbir suçunun, olmadığını anımsıyorum

Suçlu olan varsa, galiba oda benim

Aslında seni doyasıya tatmak

Seni yaşamak, seni tanımak istiyorum

Dünya öyle tuhaf ki

Seni yaşamama, seni tanımama, izin vermiyor

Bense seni yaşatacak, tanıyacak bir kişi arıyorum

Tam buldum derken 

Birde bakıyorsun kibu kişi seni sana lanet ettiriyor

Tabiki bunda senin suçun yok

Aramızda suçlu olan varsa, o suçlu yine benim

Sen ne olursa olsun, bana sakın kızma

Ben seni yaşayacak

Seni bana yaşatacak bir kişi, mutlaka bulacağım

Bu anıda herikimizde, sabırla bekliyeceğiz.', 'Ey Aşk sen ne yaptığının farkındamısın Seni birtürlü çözemiyorum Oysa sen Nicelerini sevince boguyor Nicelerini ise hüzünlendiriyorsun Sana ...', ARRAY['Türk Edebiyatı','Şiir','Çetin Akgün']::text[], 8.5, '{"poet":"Çetin Akgün","poet_slug":"cetin-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ey-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ben', 'sen-ve-ben-yavuz-sevinc-6jkrd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen

Ben olmadan, 

Sığdıramazsın yıldızları gözlerine..

Buğulu sesinin anlamını

Sadece ben bilirim.

Ben bilirim teninin üşüdüğünü, 

Ellerin yanarken..

İçinde yanan ateşin sıcaklığını...

Ben.', 'Sen Ben olmadan,  Sığdıramazsın yıldızları gözlerine.. Buğulu sesinin anlamını Sadece ben bilirim. Ben bilirim teninin üşüdüğünü,  Ellerin y...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sevinç']::text[], 8.5, '{"poet":"Yavuz Sevinç","poet_slug":"yavuz-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-ve-ben-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Oldu', 'ne-oldu-cetin-akgun-fm6i5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne Oldu Güzelim

Niye Bakıyorsun? 

Birşeymi Gördün? 

Birşeymi Oldu? 

Ben Sana Demedim mi

Bakma Diye

Karşıma Çıkan Sensin

Bakan Yine Sensin

Hani Fenada Değilsin

Hatta Güzelsinde

Göz Desen

Fizik Desen

Hepsi Sende

E Ozaman Niye Bakıyorsun GÜZELİM...

SANA BAKMAKTANSA

KARŞI KOMŞUNUN

MİNİK KEDİSİNE BAKARIM.....', 'Ne Oldu Güzelim Niye Bakıyorsun?  Birşeymi Gördün?  Birşeymi Oldu?  Ben Sana Demedim mi Bakma Diye Karşıma Çıkan Sensin Bakan Yine Sensin Ha...', ARRAY['Türk Edebiyatı','Şiir','Çetin Akgün']::text[], 8.5, '{"poet":"Çetin Akgün","poet_slug":"cetin-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-oldu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aldatiyordum', 'seni-aldatiyordum-huseyin-cayikli-3etkl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir aksam vaktiydi...

ellerim elini ariyordu.hic ummadan

oyle duruyordum...bilmiyordum

seni severken bir baskasini asik oluyordum.

magosa sokaklarinda asik oluyordum...

bu benimde agrima gidiyordu...

ama aldatilan sen olmuyordun ki

bende aldatiliyordum...

kendimi aldatiyordum.

Ruhumu sevfaya mahsus kelimelere satiyordum

seni aldatiyordum magosa sokaklarinda

seni aldatiyordum.

Elime kimse deymiyordu aslinda 

ruhum icime sigmiyordu

o kadinda senin gibi degildi...

cok konustuki

etkilemisti, 

nerden bileyim yoktun yanimda 

sana aldatilan tek sen olmadigini soylesem

bana inanirmiydin? 

magosa sokaklarinda 

sana asik olmustum

...', 'bir aksam vaktiydi... ellerim elini ariyordu.hic ummadan oyle duruyordum...bilmiyordum seni severken bir baskasini asik oluyordum. magosa so...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-aldatiyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇİYORUM', 'i-ci-yorum-lost-dolphin-yg5mv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalnızım  yine yapayalnız

kendimle iciyorum.

Ayılıp dünü hatırladıkca

kendimden geciyorum...

durma meyhaneci doldur! 

yeter artık unutmak istiyorum.

icmek bence tek cıkar yoldur

kendimle yarısmak istiyorum...

ne yapayım be meyhaneci aksın gözyaşım? 

biraz sen doldur birazda ben

tek dostum sen kaldın yine, sadık sırdaşım

neolur durmaksızın dönsün başım...

sevinsin artık karanlık 

birkac kuruşa sarhoşum

merak etme bukadar 

senin icin degil böyle sarhoş oluşum...

bir kadeh  şarapta bütün uzaklık 

anladım büyüklüğünü mesefanin

seni unutmak,  unutmak artık

 ve saçların gibi bir perdeyi 

çekmek üstüne gözlerimin

birkere olabilir herşey 

bir kere sevebilirim...

Ve bir kere unutabilirim seni....

Sonra; 

bir kere ölebilir ancak  senin aşkından 

RAMAZAN! ! !', 'yalnızım  yine yapayalnız kendimle iciyorum. Ayılıp dünü hatırladıkca kendimden geciyorum... durma meyhaneci doldur!  yeter artık unutmak is...', ARRAY['Türk Edebiyatı','Şiir','Lost Dolphin']::text[], 8.5, '{"poet":"Lost Dolphin","poet_slug":"lost-dolphin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/iciyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreği Felsefe Çalan Varoşlu Kız', 'yuregi-felsefe-calan-varoslu-kiz-onder-karadag-b9gsm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mübarek günlerden bir gün

Buğday ben’li varo(lu) şlu kız

Sakladı usulca varoluşu

Vişne çürüğü rengine eteğinin 

Kızardı yüzü kitabın. 

Sezdi anında tutucu...

Buğday ben’li varo(lu) şlu kız

Ahlaktan ikmale kaldı

Varoluşta felsefeden

Müzikten sol fa sol la...

Küstü serçe parmağına.

Açtı orucunu sorgucu

Durdu niyaza usluca

Aklında vişne çürüğü etek 

Aklında vişne çürüğü...

Buğday yüzlü varo(lu) şlu kız

Bu şiirde  ben bir hiçim

Beni bağışla!', 'Mübarek günlerden bir gün Buğday ben’li varo(lu) şlu kız Sakladı usulca varoluşu Vişne çürüğü rengine eteğinin  Kızardı yüzü kitabın.  Sezdi...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuregi-felsefe-calan-varoslu-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-ramazan-hakan-ayhan-skqnf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çoktan seçmeli değildi sinir sistemimi alt üst eden başıboş gerekçelerin gerçekliği ama ben çoktan seçiyor görünüyordum her şeyi bir manyak gibi. Adaptasyonum her gün erteleniyordu dünyaya. Kaçamaklığında tesadüf oluyordu bakışların ben ise cerrahi bir maksat arıyordum gözlerinde. Kardelen kadar asi, kardelen kadar deli. Zehirden kibrit olmuştuk ve her çaktığımızda zehirleniyorduk ve öylesine zamanlarda çıkıyordun karşıma. Korku çocukluğuma ikincil bir hüzün katarken yirmili yaşlarımda, kurşun kalemimin yumuşaklığı oranında kahramanlar uyduruyordum hikayelerime kahramanca. Çoğulcul bir menfilik okunuyordu sabır taşlarında. Karanlıklar kaçak yapıtordu yalnızlığıma mesnet dakikaları ve limanlara yanaşmadığını anlıyordum bütün gemilerin demir atan sessiz zamanlarında. Ve öylesine zamanlarda çıkıyordun karşıma. Kapı aralığına dolan gıcırtıya, kalabalıklardaki yalnızlığıma ve antep fıstığının kabuğuna çıkıyordum zıvanadan. Ölçeksiz haritalarda ve çayıma iki ölçek şeker kattığım zamanlarda hesaplıyordum  aramızdaki mesafenin gidilebilirliğini; mesafeyi sen şekeri ben artırıyordum. Tasarrufa gidiyordum ciğerlerime doldurduğum oksijenden ve kurduğum cümlelerden. Öznenin, tümlecin ve yüklemin minnettinde eziliyordu dudaklarım. Ve öylesi zamanlarda çıkıyordun karşıma öylesine. Uzun düşlerimde ağlatıyordu ve boğazımı kurutuyordu iklimin karasal özelliği. Ter tacak zamanlarında zar atan çocukların varlığındandım oldum olası. Cümlelerin devrikliği ilgilendirmiyordu kimseyi kafiyelerin güzelliğiydionlarn derdi. Vasıfsıs tanrıçaların dedikodularını duyuyordum hakkında; kardelen kadar asi kardelen kadar deli. Bense ne kadar gülümsesem yine mahzun çıkıyordum fotoğraflara. Rakamlar ilerledikçe takvimlerde mutlu oluyorduk bir ölüm ilanına rastlamadığımız müddetçe.

Yelkovanı kıskanırsa bir gün akrep kendini yakacak öylesine. Kardelen kadar asi

Kardelen kadar deli', 'Çoktan seçmeli değildi sinir sistemimi alt üst eden başıboş gerekçelerin gerçekliği ama ben çoktan seçiyor görünüyordum her şeyi bir manyak ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Hakan Ayhan']::text[], 8.5, '{"poet":"Ramazan Hakan Ayhan","poet_slug":"ramazan-hakan-ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kardelen-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onsekizinde', 'onsekizinde-emre-konyali-scgxi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'On sekizinde bir firar

Yatıyor Kaldırımda

Öylesine mahzun, öylesine garip

Ağlıyor doyasıya

Gözlerinden umutlar akıyor

Sakalından, bir zamanlar unuttuğu mutluluk

Atıyor kendini bir vakit yollara

Arkasında ne ses, ne koku

Yürüyor bilinmezliğe

Kavgalardan sıkılmış ömrü

Ben ‘’Barışım’’, ‘’Özgürlüğüm’’ diyor dağlara

Sevdasına bırakmış umutlarını

Şimdi kim çeker onu kolundan

Geri dönmenin hasretliği koynunda

On sekizinde bir firar

Yatıyor kaldırımda

Yağmurlar türkü söyler

Karanlık sokaklarda

Aldatan gecenin sessizliği düşmüş gönlüne

Tütünden derin bir nefes çekiyor

Ciğerine kadar indiriyor hasreti

Gece olunca dalıp gidiyor denize doğru

Ne kız kulesi anlıyor yalnızlığını

Ne de Galata Köprüsü

On sekizinde bir firar

Kaldırım kenarında

Dalıp dalıp gider gözleri

Çaresiz sevdalara

İsyanlara küsmüş gönlü

Nasırlı elleri

Bakımsız sakalı, yorgun gözleri

Bir şeyler anlatmaya çalışır hep.

Kavgaların arasından

Sevdalar ekmek ister toprağa

Yılmayan sevinci kırılmış gidiyor sonsuzluğa

On sekizinde bir firar

İsyanlar arasında

Ellerinde sevda, gözlerinde umut

Koşuyor yalnızlığa

Oysa ne hayaller süslemişti ömrünü

Ne sevdalara koşmuştu

Yalanın en acısını gördü sonunda

Hak etmediği tokatları..

Kim bilir şimdi neredesin.? 

Hangi sevdanın peşinde.? 

Kimler aldatıyor seni, 

Kimler kırıyor umutlarını

Ya yalnızlığına ne demeli.! 

Hele dağları eriten sabrına

Mutluluk seninki gibi olsun çocuk.! 

Yaşamın en anlamsız yerinde sen gel yanımıza

Bir şarkı mırıldan kulağımıza

Umutları koştur peşimizden, 

Sevdayı öğret bize…

Seni ben, 

Seni sevdam anla ancak

Alış acılara gönlüm

Baştan yaz umutları

On sekizinde bir çocuk ölüyor.! 

Bırakıyor kendini uçurumlara

Gerisinde bir yalan

Gerisinde bir hüzün

Gerisinde yeni bir Emre bırakarak.! 

On sekizinde bir firar

Uçurum kenarında

Kaçıyor Dünyadan, koşuyor sevdalara.', 'On sekizinde bir firar Yatıyor Kaldırımda Öylesine mahzun, öylesine garip Ağlıyor doyasıya Gözlerinden umutlar akıyor Sakalından, bir zamanl...', ARRAY['Türk Edebiyatı','Şiir','Emre Konyalı']::text[], 8.5, '{"poet":"Emre Konyalı","poet_slug":"emre-konyali","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/onsekizinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Mavi Dev Geceler', 'mavi-dev-geceler-nurten-altinok-dnrrp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.........Nazım Hikmet''in anısına..

“ebruliiii

hanım eli

açan”

bir bahçeleri olmadı

bir evleri oldu oysa

derme çatma birkaç eşya

oradan buradan toplama

yola bakıyordu camları

Nazım Hikmet ’i  okuyordu

“o mavi gözlü bir devdi

minnacık bir kadın sevdi”

kaderleri miydi “mavi dev”

binlerce şiir arasından seçilen

yarınları mıydı

hey gidi koca Nazım Hikmet hey

gel de gör şimdi 

nasıl ağlıyor bak bir kadın

zengin bir cücenin koynunda yitirilen

arkasından o adamın

unutulur mu zamanla devleşen geceler

her gün biraz daha büyürken yalnızlık

her köşe başında duran sanki O dev adam

dönüp bakacak diye umutlanıyor

gecelerine bir ıslık

ıslak bir mendil gibi yanan alnına

dudak olacak sanıyor...

mavi gözlü dev bir gecede yitirilen dev

şimdi anlıyor ki

sevdalara mezar oldu

bahçesinde ebruli

hanımeli

açmayan ev...', '.........Nazım Hikmet''in anısına.. “ebruliiii hanım eli açan” bir bahçeleri olmadı bir evleri oldu oysa derme çatma birkaç eşya oradan burad...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mavi-dev-geceler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Dünyacı', 'kor-dunyaci-ramazan-hakan-ayhan-s3ci7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Altını üstüne getidim beynimin 

Bir türlü hatırlayamadım koyduğum ayracı

Çığırsız, uğrsuz, sabırsız 

Kaybolup var olan zor denilen zor bir tür sancı

Kül kül savruluyor selamsız bir avuntu

Ardınsıra yamuk bir hayat ağacı

Ters

Hepsi ters bir açı

Dünya

maden dünyaydı bütün amacı

neden Enelhakk dedi ve öldü Hallacı

ol ayrımında kısır bir rol icabı 

Desem

Gözlerin bir darağacı

Bu devran oluverir birden basit bir simyacı

Bazen anlamsızım 

Bazen çalkantılı

Ve komik görünüyor aslında

olmak yüreğinde fakir bir kiracı 

Bazen sır ediyor işte

titrek zamanlar ve unutulamayanlar

hep alttan aln redoks bir mizacı

Yaz diyor sanki

Bitir diyor sanki dünyayı

Yitir diyor kör dünyayı', 'Altını üstüne getidim beynimin  Bir türlü hatırlayamadım koyduğum ayracı Çığırsız, uğrsuz, sabırsız  Kaybolup var olan zor denilen zor bir t...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Hakan Ayhan']::text[], 8.5, '{"poet":"Ramazan Hakan Ayhan","poet_slug":"ramazan-hakan-ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kor-dunyaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teyzeme Yeniden', 'teyzeme-yeniden-ertan-sezgin-la4sx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok zaman olmadı daha

''Gitme ne olur'' diyeli sana.

Dayanamadın gittin yine

Her zamanki tezcanlılığınla.

Kırkbeş gün yalnız bıraktın kocanı, 

Uzandın sonra toprağa, onun yanına.

Ah canım teyzem.

Annem yarısı.

Kabullenemiyorum birtürlü öldüğünü.

Sanki yan odadaymışsın gibi, 

Açıp da kapıyı birden gireceksin içeri, 

Bizler eskisi gibi çocuk ve haşarı, 

Birtürlü gizleyemediğimiz yaramazlıklarımızla, 

Sanki yakalanacağız yine sana

Son gödüğümde de hala gülüyordun.

O hasta ve yorgun bedenin, 

Dökülmüş saclar, 

Ve inadına hala gülen gözler.

Ölümün seni yendiğine inanmıyorum asla.

Sen her zaman güleçtin, 

Eminim cansızken de güleçsin.

Sana dokunamayacaksam bile, 

Öpemeyeceksem de ellerinden bir daha, 

Sen hala benim; 

Tonton ve güleç

Teyzemsin.

İZMİR 17 Ocak 2002', 'Çok zaman olmadı daha ''Gitme ne olur'' diyeli sana. Dayanamadın gittin yine Her zamanki tezcanlılığınla. Kırkbeş gün yalnız bıraktın kocanı, ...', ARRAY['Türk Edebiyatı','Şiir','Ertan Sezgin']::text[], 8.5, '{"poet":"Ertan Sezgin","poet_slug":"ertan-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/teyzeme-yeniden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-nurhan-ozkan-y2cdb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gölgesi bile güzeldi hayatın

Ama benim hayatta bir gölgem bile olmadı.

Yalnızca bir ışığa bile razıydı dudaklarım, 

Gülümsemek için.

Ama gözlerim o ışığa hiç bakamadı.

Hani bir gün vardı, günün birinde...

Sen söylemiştin ya bana

Hatırladın değil mi? 

Hani o gün hayattaki bütün güzellikler, 

Karanlıktan aydınlığa çıkacaktı.

Hani o gün sevginin tutsak olduğu bütün hücreler

Açacaktı kapılarını, 

Hani o gün sen çıkacaktın karşıma da

Ben gözlerime bile inanmayacaktım

Hani usulca eğilecek, 

Ellerimi tutacak

Ve hayatta ışığa hiç bakmayan gözlerim

Senin gözlerine bakacak

Ve kulaklarım tek bir sevgi sözcüğüyle çınlayacaktı.

O gün hala gelmedi, 

Biliyorum! 

Ama ben hala seni bekliyorum! 

Gözlerim bütün gözler arasından senin gözlerini, 

Kulaklarım bütün ayak sesleri arasından

Seninkileri ayırt edebilmek için sabırsız.

Bense çaresiz...

Azalan umutlarımla

Üç şey için dua ediyorum Tanrı''ya

Sen, sen, sen.

Ah bir gelsen!', 'Gölgesi bile güzeldi hayatın Ama benim hayatta bir gölgem bile olmadı. Yalnızca bir ışığa bile razıydı dudaklarım,  Gülümsemek için. Ama göz...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Özkan']::text[], 8.5, '{"poet":"Nurhan Özkan","poet_slug":"nurhan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyebilseydim', 'diyebilseydim-umit-yasar-oguzcan-r1cz4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anladım diyemem ki! Suçluyum

Belki ben anlatamadım sana kendimi

Tutuştum, yandım da yokluğunda her gece

Yine gözyaşlarımla söndürdüm kalbimi

Her gün her dakika seni özlerdim

Bitmezdi kederim senin yanında bile

Susardım, gözlerime baktığın zaman

Mermer bir heykelin çaresizliğiyle

Oysa neler düşünürdüm sen yokken

Sana kavuşunca neler söylemek isterdim

Dakikalar bir ışık hızıyla geçerdi

Ayrılık başlayınca ben biterdim

En kötüsü beni koyup gitmendi

O öyle bir yalnızlıktı anlatılmaz

Hep yarım kalmış heyecanlar hazlar içinde

Biterdi bir kış, geçerdi bir yaz

Ve nice yıllar kovalardı birbirini

Gözlerimde gitgide büyürdü mesafeler

Bütün teselliler uzaklarda kalırdı

Bütün çiçekleriyle solardı bahçeler

Ne olurdu saadetlerin en büyüğü

İşte ellerimde al, diyebilseydim

Anlardın, ve hiç gitmezdin, değil mi

Bir gün duyduğum gibi kal diyebilseydim.', 'Anladım diyemem ki! Suçluyum Belki ben anlatamadım sana kendimi Tutuştum, yandım da yokluğunda her gece Yine gözyaşlarımla söndürdüm kalbimi...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/diyebilseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNANMAZDIN YAR', 'i-nanmazdin-yar-serhat-cenkciler-sb6ey', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin gözlerin var ya güzelim

uğruna ben herşeyimi vermişim

Seninle bir dakika geçirmek için

Sana ben koca bir ömür vermişim

Rüyamda görseydim inanmazdım yar

Yanıma gelipte ağlamazdın yar

Hani sen büyüktün yıkılmazdın yar

Hayatta neler var inanmazdın yar', 'Senin gözlerin var ya güzelim uğruna ben herşeyimi vermişim Seninle bir dakika geçirmek için Sana ben koca bir ömür vermişim Rüyamda görseyd...', ARRAY['Türk Edebiyatı','Şiir','Serhat Cenkçiler']::text[], 8.5, '{"poet":"Serhat Cenkçiler","poet_slug":"serhat-cenkciler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/inanmazdin-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhların Buluşması', 'ruhlarin-bulusmasi-emel-kocer-gur-mlxjh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üsküdar Vapur iskelesinde 

Rastladım onlara

Biri erkek, diğeri kadın

Bir an gözleri değdi birbirine

Hiç konuşmadılar; 

Çok şey anlattılar

Ruhlarını gördüm: 

Tekti!', 'Üsküdar Vapur iskelesinde  Rastladım onlara Biri erkek, diğeri kadın Bir an gözleri değdi birbirine Hiç konuşmadılar;  Çok şey anlattılar Ru...', ARRAY['Türk Edebiyatı','Şiir','Emel Koçer Gür']::text[], 8.5, '{"poet":"Emel Koçer Gür","poet_slug":"emel-kocer-gur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruhlarin-bulusmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Ev', 'yesil-ev-emel-kocer-gur-9gpyo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sis perdesi aralanıyor

Geçmişin hüzünle sarmalanmış

O tanıdık, loş sokaklarında

Eski bir ev beliriyor yanıbaşımda

Öylesine sessiz, öylesine gizemli

Öylesine yeşil

Huzur veren, sevecen bakışlarla

Ağustosun buğulu sıcağı

Yediveren güllerinin kırmızısında

Damaktaki taze ceviz tadını alıyor

Gizliden

Aşkın yakıcılığında eriyor

Tüm kırgınlıklar, ayrılıklar

Hızla uzaklaşıyor geride kalan

Tüm unutulmuşluklar, yaşanmamışlıklar

Gözyaşı bardaktaki suya karışıyor

Usul usul

İçli bir şarkı sesleniyor

Çok uzaklardan

Çerçevedeki resim gülümsüyor

Belli belirsiz

Alabildiğince yeşil bu evde

Yalnızca mutluluğa açılıyor pencereler

İncir ağaçlarının koyu gölgesinde 

Derin bir uykuya dalıyor

Bütün saatler, bütün zamanlar

Ve sis perdesi yavaş yavaş inerken

Anılar sokağına

Seçilebilen son karede; 

Ağustos böceklerinin orkestrası 

Yönetiyor yürekleri 

İnce ince sızlatarak! ! !', 'Bir sis perdesi aralanıyor Geçmişin hüzünle sarmalanmış O tanıdık, loş sokaklarında Eski bir ev beliriyor yanıbaşımda Öylesine sessiz, öyles...', ARRAY['Türk Edebiyatı','Şiir','Emel Koçer Gür']::text[], 8.5, '{"poet":"Emel Koçer Gür","poet_slug":"emel-kocer-gur","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yesil-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşe', 'nese-ender-cetinkaya-0x8bi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bulutların arasından

Gülümseyiverdi güneş, 

O an

Sen düştün aklıma

İçim ısındı bu sabah...', 'Bulutların arasından Gülümseyiverdi güneş,  O an Sen düştün aklıma İçim ısındı bu sabah......', ARRAY['Türk Edebiyatı','Şiir','Ender Çetinkaya']::text[], 8.5, '{"poet":"Ender Çetinkaya","poet_slug":"ender-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nese-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git....me!', 'git-me-yavuz-sevinc-vkss2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alışmayalım diyorsun..

Birlikte olmayalım.

Gezmeyelim kolkola, 

Kimse görmesin bizi..

O anda üşüyorum, 

Henüz elimde iken dudaklarının izi..

Birden araya mesafeler giriyor

Bir sis çöküyor geceye..

Öylece gidiyorsun.

Herşey gidiyor seninle, 

Bakıyorum ardından.

Şimdi sadece hayalin var az önceki yerinde, 

Dışarda zaman gidiyor..', 'Alışmayalım diyorsun.. Birlikte olmayalım. Gezmeyelim kolkola,  Kimse görmesin bizi.. O anda üşüyorum,  Henüz elimde iken dudaklarının izi.....', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sevinç']::text[], 8.5, '{"poet":"Yavuz Sevinç","poet_slug":"yavuz-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/git-me-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün', 'gun-selcuk-yilmaz-vf498', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmez mi bu gönül 

Gem vurmuş duyguların haykırışını

Damlayan gözyaşlarındaki 

buselerin  sesini

Teninin o sessiz garip ürperişini, 

Yalvarıp yakarmalar boşuna hep, 

Boşuna bu geçen zamanın yiten kısmını 

Gün be gün her bir fırsatında 

aramak boşuna, 

Gün sevgi günü, 

gün aşka susayanların günü, 

Taparcasına daldığı uhrevi bir esintisinde

Buselerin hülyasında 

dalgalarına kapılma günü, 

Gün geleceğe  bakışında 

yeniden hep gördü bugünü....

18.1.2002   S.Y.', 'Bilmez mi bu gönül  Gem vurmuş duyguların haykırışını Damlayan gözyaşlarındaki  buselerin  sesini Teninin o sessiz garip ürperişini,  Yalvar...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yılmaz']::text[], 8.5, '{"poet":"Selçuk Yılmaz","poet_slug":"selcuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Andım olsun', 'andim-olsun-omer-avsar-88kgw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başka bir şeysin sana anlatamam

Sensiz geçen her saat bana haram

Aglamaklı oluyorum görmedigim zaman

Yaktın kalbimi buna inan

Yıkılsa barkım sönse ocagım

ömür boyu açık sana kucagım

Gönlümde sevgili başımda tacım

Bir sen varsın yalnız tapacagım...', 'Başka bir şeysin sana anlatamam Sensiz geçen her saat bana haram Aglamaklı oluyorum görmedigim zaman Yaktın kalbimi buna inan Yıkılsa barkım...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/andim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim aşktan yana şikayetim var', 'benim-asktan-yana-sikayetim-var-gokhan-oktem-ny4gn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim aşktan yana şikayetim var

En umarsız yanım yaşamışlığım

Uzak umutlarım uzak düşlerim

Bir nice mürtede varışlarım var

Beni senden yana yoklayan hüzün

Hüznümün dilinden anlayan sözüm

Bir yok oluş güzelliğinde belki

Benim aşktan yana tükenmişliğim

Benim aşktan yana şikayetim var

Sevda girdabında savrulmuşluğum 

Ararken kendimi bir yar elinde

En derin aşklarda kalmış bir yarım

Benim aşktan yana şikayetim var

Bakir bir istanbul kalakalmışım

Bir ben bir de garip martılar 

Gök kubbe altında uzayışlarım

Benim aşktan yana şikayetim var

Her seher seviye mendil açmışım

Devriye gezmişim gecelerimde

Bilmezler seni ben ne çok sevmişim

Benim aşktan yana şikayetim var 

Kendi hayalimde yaratmışlığım

Belkim bir bilinmezde ararken seni

Savrulup düşmüşüm kendi özüme

Benim aşktan yana şikayetim var

Her yanımla bir sevdaya vurgunum

Benim hüzne gebe dalışlarımda

Serzenişlerimin suskunluğu var

Sessizlik çoğalır susuşlarımda 

Bıçak keser gibi seslenişlerim

Bilmezler nasıl isterdim şöyle haykırmak

Lakin, 

Benim aşktan yana susuşlarım var.

(İstanbul,14,01,2002)', 'Benim aşktan yana şikayetim var En umarsız yanım yaşamışlığım Uzak umutlarım uzak düşlerim Bir nice mürtede varışlarım var Beni senden yana ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/benim-asktan-yana-sikayetim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydarpaşa Garı', 'haydarpasa-gari-yalcin-ergun-2hk90', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıradan akşamlardan biriydi Haydarpaşa Garı için...

Herkesin, ''en büyük askerin'' kendilerinin ki olduğu iddiasına bile aldırmıyordu hatta

Umursamaz taştan edasıyla trenler ağırlıyor, trenler uğurluyordu ihtiyar gar

Ta ki; bir kaç damla yaş düşünceye kadar mermer zeminine

Silkindi o anda daldığı asırlık uykudan... ürperdi, titredi sanki

Dolu dolu oldu insafsız bakan masmavi gözleri

Sus ağlama diyecekti, yüreğim kanıyor diyecekti belki... öylesi bir baktı ki! 

Kafasını çevirip denize doğru yalan yanlış bir lanet savurdu birden~içinden

Sıradan akşamlardan biriydi Haydarpaşa Garı için...

Tonlarca lokomotif ve katarlar bile ağırına gitmemişti bir kaç damla gözyaşı kadar

Öylesi yılgındı oysa, öylesi bitkin. Öylesine dolu doluydu yüreği

Taştan yapılmış yüreğinde bir nebze sıcaklık mı kalmıştı... kim bilir? 

Ardından bakakaldı giden trenin...

Yüzündeki mağrur, yıkılmaz ifadeyi bir an olsun bozmadı lakin, 

Yüreğindeki sancıyı saklayamadı bir türlü uçuşan martılardan

Umutların ağır aksak gürültülü gidişini seyretti son vagonun raylarda çıkardığı kıvılcımlarda... 

Sıradan akşamlardan biriydi Haydarpaşa Garı için...

Tıpkı bence de sıradan bir gece olduğu gibi

Ama aynı anlarda hissettik yoğunluğunu duyguların

Aynı anlarda anladık... neden ki ağlamazmış erkekler

Eğilip bir şeyler fısıldayacak oldu denizi seyreden genç kıza

Teselli edecekti belki... belki ağlamanın ayıbından faziletin erdeminden bahsedecekti

Belki oturup yanına o da ağlayacaktı fakat bilemedi ne yapacağını

Dokunamadı düşüncelerine, hıçkıramadı kaderine... sustu hep olduğundan da fazla

Sıradan akşamlardan biriydi Haydarpaşa Garı için...

Ama o, sıradan bir gar değildi... yalnızca trenlere ve kuşlara yuva kabul etmedi hiç kendini

Buğulu gözlerinin ardında yeşeren umutların filizlerini hissetmek

Ve yılların yalnız acılarını paylaşmak istedi birileriyle

Yumuşamaya yüz tutan kalbini umursamadan yine takındı katı üslubunu

Yine sarımtırak, yine loş ve karanlıktı. Çoktan gitmişti tren ve yolcuları

Çoktan bitmişti o akşam, sabahı martı çığlıklarıyla karşıladı her günkü gibi

Bitmeyen ya da gitmeyen tek şey vardı... bir kaç damla gözyaşı

Sıradan akşamlardan biriydi Haydarpaşa Garı için...

Bence de öyleydi... gecesi uykusuz bile olsa

Belki en büyük asker bizimkisi değildi ama; 

Anlamıştık ikimiz de... en şanslı asker bizim askerimizdi...

*ASLI''ma...

23.11.1999', 'Sıradan akşamlardan biriydi Haydarpaşa Garı için... Herkesin, ''en büyük askerin'' kendilerinin ki olduğu iddiasına bile aldırmıyordu hatta Um...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ergün']::text[], 8.5, '{"poet":"Yalçın Ergün","poet_slug":"yalcin-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/haydarpasa-gari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-levent-keskin-7nktj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şaşkınlığım kısa sürmüştü ilkgördüğüm anda 

gözlerime inanmakla hatamı ettim diye 

hep düşündüm hayatım boyunca.

Artık anladım gerçek olan sen değil, 

yaşanmışlık adına geçen beyaz bir sayfa.

Gidiyorum, benim için bir yer var orda.

Yorgunum, son bir huzur için çıktığım yolda.

Saklanmakla geçen onca yılın acısına, 

Bir gün olsun nefes almalı bu güzel hayatta.', 'Şaşkınlığım kısa sürmüştü ilkgördüğüm anda  gözlerime inanmakla hatamı ettim diye  hep düşündüm hayatım boyunca. Artık anladım gerçek olan s...', ARRAY['Türk Edebiyatı','Şiir','Levent Keskin']::text[], 8.5, '{"poet":"Levent Keskin","poet_slug":"levent-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/veda-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'düşünüyorum', 'dusunuyorum-faruk-elma-a92ld', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'eğer bir cümle anlatabiliyorsa seni

tüm cisimler ve kelimeler tanımlayabilir

ve seni anlayabilir

karmaşık ve basit

düzgün veya virane görebilirim 

hiç düşünmeden seni anında düşünebilirim 

sana aşık veya nefretlik duyabilirim 

bildiğim tek şey seni sevmek 

aklım ve duyum olmadan 

herşeyini  mi yoksa 

sadece sınırlı bir duygunu mu biliyorum 

seni tarih ve aşk açısından seviyorum

zaman insanoğluna kötü 

durmak ayrı dert 

sevmek ayrı 

acaba doğru olan şeyi biliyormuyuz

ben kimim  sen kimsin   AŞK nedir? 

sezgilerim yanılmaz 

ama doğru olduğuna inanmıyorum

bir şeyin var olduğunumu sanıyorsun yağmurun 

aşık olmanın bedava olduğunu mu sanıyorsun 

herşeyin bir bedelinin olduğunu kim bilebilir

aşk bir yıkıntıdır 

kuşkulu  kalabilecek ne kaldı acaba

kimin kesin bir kuşkusu var

gerçek var olma savaşı verir dünyada

zihne gelen basit 

ayırt edilen karmaşık 

kalbten doğan aşk

birlikte varoluş  veya

zorunlu bağlantı 

ihtiyaç duyulmayan nesne 

kendi kendine kanıt olması

yanlışlıklar duygulardadır 

yanlış sevgi, yanlış insan, yanlış AŞK 

zihni ve iradesi aşka yenilir insanların', 'eğer bir cümle anlatabiliyorsa seni tüm cisimler ve kelimeler tanımlayabilir ve seni anlayabilir karmaşık ve basit düzgün veya virane görebi...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dusunuyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmuşum', 'unutmusum-levent-umit-temiz-d7ll8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sabah uzaklara yürüdüm

Uzun uzun yürüdüm

Nereden

Nereye bilmeden

Güneşin doğuşuna yürüdüm

Eskiyi tanıdım

Yeniyi ezberledim

Yorgunluğu hatırladım

Ama aksamadan yürümeyi

Unutmuşum

Telaşsız ve özgürce

Belki de saatlerce yürüdüm

Maviyle yeşilin arasından

Tek başıma yürüdüm

Sandalları tanıdım

Balıkları ezberledim

Açlığı hatırladım

Ama diz çöküp denizi tutmayı

Unutmuşum

Dizime nispet yürüdüm

İnadına inadına 

Dik yokuşlara tepelere yürüdüm

Hatta 

Yol kenarında

Patlak bir topa vurdum

Nereden

Nereye bilmeden

Güneşin batışına yürüdüm

Kedileri tanıdım

Köpekleri ezberledim

Bir çocuğu hatırladım

Ama öylesine koşmayı

Unutmuşum

                   

                     (Merhaba)', 'Bu sabah uzaklara yürüdüm Uzun uzun yürüdüm Nereden Nereye bilmeden Güneşin doğuşuna yürüdüm Eskiyi tanıdım Yeniyi ezberledim Yorgunluğu hat...', ARRAY['Türk Edebiyatı','Şiir','Levent Ümit Temiz']::text[], 8.5, '{"poet":"Levent Ümit Temiz","poet_slug":"levent-umit-temiz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/unutmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-ender-baht-0up6o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yabancı! Bir gün beni sevebilir misin? 

Sana ellerimi uzattıgımda

Avuçlarına alıp sımsıcak nefesinle

Küçücük bir öpücük

Kondurur musun ellerime, 

Yüreğinde bana yer verir misin? 

Başımı omzuna koyduğumda, 

Okşar mısın saçlarımı ılık nefesinle, 

Fısıldar mısın kulağıma sevgini, 

Küçücük bir öpücük

Kondurur musun dudaklarıma, 

Gözlerime bakar mısın sevgiyle, 

Benimle ağlar benimle güler misin? 

Beni sev yabancı! 

Dalgaların kayaları sevmesi gibi...

Hoyrat rüzgârın agaçları, 

Kızgın güneşin toprağı, 

Yağmurun bitkileri sevmesi gibi.

Sen de beni, delicesine sev yabancı!', 'Yabancı! Bir gün beni sevebilir misin?  Sana ellerimi uzattıgımda Avuçlarına alıp sımsıcak nefesinle Küçücük bir öpücük Kondurur musun eller...', ARRAY['Türk Edebiyatı','Şiir','Ender Baht']::text[], 8.5, '{"poet":"Ender Baht","poet_slug":"ender-baht","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yabanci-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seherde Karşılaşma', 'seherde-karsilasma-mehmet-sait-bozyel-93qla', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimsin sen alacakaranlıktan çıkan 

Gümüşi bir sonat mı yüzünden akan 

Sehere bir ok gibi saplanan mavi 

Vakitsiz ülkenin kabuk bağlamayan 

Yerinden uzakta mısın 

Ah bu yalnızlık kavşağında 

Ne arasın 

Güneşsiz yüzün sahibi 

in misin cin misin', 'Kimsin sen alacakaranlıktan çıkan  Gümüşi bir sonat mı yüzünden akan  Sehere bir ok gibi saplanan mavi  Vakitsiz ülkenin kabuk bağlamayan  Y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Bozyel']::text[], 8.5, '{"poet":"Mehmet Sait Bozyel","poet_slug":"mehmet-sait-bozyel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seherde-karsilasma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğa', 'doga-mehmet-sait-bozyel-1jslm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baktım iki tepenin arasından 

Suyla sevişkendi eğik ova 

Kokular bayıltıyordu yorgun ruhları 

Parçalanıyordu bedenler 

Dağılıyordu damlıyordu düşlere 

Bildiğiniz gibi değil 

Dansa uçuşuyordu zaman', 'Baktım iki tepenin arasından  Suyla sevişkendi eğik ova  Kokular bayıltıyordu yorgun ruhları  Parçalanıyordu bedenler  Dağılıyordu damlıyord...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Bozyel']::text[], 8.5, '{"poet":"Mehmet Sait Bozyel","poet_slug":"mehmet-sait-bozyel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/doga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk: Rüya Gören Yıldız', 'cocuk-ruya-goren-yildiz-mehmet-sait-bozyel-6omr0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi yalazdan pirinç tanesine geçen neydi 

Donmuştu, usulca bekler, bakar giderdi 

Çocuktu seherde en güzel 

Rüya gören bir yıldızdı 

Kavak dallarından atları olurdu 

Tırmanamazdı henüz aklın yalvaçlı kayalıklarına 

Gözlerden akarsu alırdı 

O bir okyanus/yaydı 

Zaman utancından belirsizdi 

Evler, ağaçlar, kokular kocamandı 

Onun için ilençsiz yarındı hayat 

Bir oyundan diğer oyuna geçilen', 'Mavi yalazdan pirinç tanesine geçen neydi  Donmuştu, usulca bekler, bakar giderdi  Çocuktu seherde en güzel  Rüya gören bir yıldızdı  Kavak ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Bozyel']::text[], 8.5, '{"poet":"Mehmet Sait Bozyel","poet_slug":"mehmet-sait-bozyel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuk-ruya-goren-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviyi Sokan Akrrep', 'maviyi-sokan-akrrep-mehmet-sait-bozyel-u28zq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mavinin üşüyen tonuna dokunduğunda kızıl akrep 

Dağıttı tutulmuş öfkesini 

Mavinin benzi attı barklıyan semada 

Akrep uçuyordu boşalmaktan 

Kurtulmuştu bilinçaltından', 'Mavinin üşüyen tonuna dokunduğunda kızıl akrep  Dağıttı tutulmuş öfkesini  Mavinin benzi attı barklıyan semada  Akrep uçuyordu boşalmaktan  ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Bozyel']::text[], 8.5, '{"poet":"Mehmet Sait Bozyel","poet_slug":"mehmet-sait-bozyel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/maviyi-sokan-akrrep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerin Şiiri', 'duslerin-siiri-i-smail-ozabaci-cjwya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece

Bir avuç hüzün düştü penceremden

Bir basamak diye düşündüm yaşamak

Yenilgi mahkumu bir savaşçıydım

Başımda yalnızlığın mezar taşı

Bu gece

Ölmek daha kolay geldi  bana

Üşümek ve yalnızlıksa tezat

Hasret koydum senin adını

Uzak bir şehirdeydin

Bu gece

Toprak rengi bir hayalle düşündüm seni

Kovdum karanlıkları kapımdan

Sır vermedim ser verdim

Bu gece hüznü çıkardım aklımdan

Dört yüzüm var artık

Ve kükürtlü sabun kokusu burnumda

Ben bir hayal sarhoşuyum aslında

Arkamda yalnızlığın ayak sesini duydum

Beni beklediğini biliyordum

Bir yağmur damlasını beklediği gibi toprağın

Biliyor musun? 

Seraplar görmüyorum artık

Her sabah bir kara yazıyla uyanmıyorum

Yine aynıymış meğer yüzüm

Bir üniversite kantininde usulca

Önüme düştü sözüm

Gölgede kalınca güneş üşürmüş meğer

Bir şehir bir cinayet demekmiş

Ve en masum isyanlarım

Bu şehirde kenetlenmiş

Bir çığlık olmak

Bir bitmez bekleyiş

Ve umut olmak rüyalarına

Sonra susmak ve

Kahverengi gözlerine dalmak saatlerce

Gül kokar nefesin

Ve sevgi militanıdır sana yazılan her şiir

Bir delinin aşkıdır

Bir  kölenin özgürlüğü

Biz aşkı hayal tacirlerinin üç boyutlu çantasından çalmadık

Sonsuzluğa sevgiyle

Beyaz bir gökyüzüyle uzandık

Biz senle nice gölgeler yarıladık

Ağlamaklı nice gün

Sevmeli  nice saat

Ve nice ufuk yolcusu uğurladık

Güneş nerede diye sordun

Gözlerini gösterdim

Tereddütte kalmıştın oysa

Biz hayatı senle üç günde yaşadık

Bak artık yağmursuz duygulara gidiyorum

Bir çağın sancısı boynumda

Çiçeklere fısıldadığım şeyler var

Seni seviyorum.', 'Bu gece Bir avuç hüzün düştü penceremden Bir basamak diye düşündüm yaşamak Yenilgi mahkumu bir savaşçıydım Başımda yalnızlığın mezar taşı Bu...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/duslerin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Santim', 'santim-ertan-ciloglu-aarm4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzlerce kilometre uzak da yanımdayken, 

Santim ötede çok uzak kalabildin ya çocuk sen.

Bak bunu unutmayacam,

Ama   ben gene uzaklara  yanına kaçacam....yazık...', 'Yüzlerce kilometre uzak da yanımdayken,  Santim ötede çok uzak kalabildin ya çocuk sen. Bak bunu unutmayacam, Ama   ben gene uzaklara  yanın...', ARRAY['Türk Edebiyatı','Şiir','Ertan Çiloğlu']::text[], 8.5, '{"poet":"Ertan Çiloğlu","poet_slug":"ertan-ciloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/santim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüp Dolaşan Hikaye', 'donup-dolasan-hikaye-ahmet-ozturk-l46ia', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I.

kara tahta, sıralar ve okulun merdivenleri aşınmakta

kitaplı eller beynimi kucaklamaktaydı

bir yığın ders, iki yığın yıl, gurbet

aralarında sen

sana gelene kadar 

arayışımın dayanaklarında 

arzuladığım geçmişim

sıfırdan bire ise sevemiyordum şiiri bile

birer birer yağmurlar birikmekteydi  yerküreye

tutsak öyküme ilerledim geceler boyu

sessiz ve iz sürerek avcı gibi

sen bağlanmış bir düğüme kördüğüm

kalabalıklarda bir sabitlik gibi durmaktaydın

sağın dolu 

solun cümbüş...

seyr-ü sefer eyliyor, baharı bekliyordum

birbirimizi göremeyeceğimiz bir karambolde

susuyor ve yürüyorduk birgün koşacakmışcasına haykırarak

çocukluğumdan yansıttıkların öz aynama

dirsekli anımsamalar ve dolan boşluklarım

oysa ne gözlerin değdi 

ne sözlerin gazel

ben sana vurulmam derken 

sen beni vurmuştun

atlas geceleri yaşıyordum öte yıllarda

ötedeki yollarda

sense başka kollarda

''sen'' diyordun seni ve senin hiç bitmeyecek kışını anlatırken

sesini ahizeye hapsedip sabahları bekliyordum

kulağım telefonda, yüreğim bilmem kaçıncı boyutta

iki ses yoğuruluyordu

hayattı, aşktı, mizahtı

bir de masallar kahramanıymışız gibi

güzelliğinin ötesinde aradığım 

ve görüp de oturamadığım tahtı

ah bir bilseler kan çıkar aşk bağında

sözleştik ilk başladığımız yerde buluşmaya

ardına gördüğümde seni

dönüyorduk istanbula

yolları çiğnedik

omuzunda uyudum bir dünya döndü

benim olacaktın umudum vardı

başka bir sıcağa sıcaklığımdan alıp bıraktım seni

oy dilsizim (*)   umudum ağlayan çocuktu

ve koptuk salkım salkım sesten, haberden

işte o zaman kazıdım seni

kan oturarak yüreğimden

o kanı ve o revanı ne ben bilirim

ne de sen...

bir garip yürek bilir



II.

yeni bir hayatı ve eksilmiş bir yüreği yeğlerken

kaçış rüzgarına kapılmışken dolu dizgin

set çektin rüzgarıma

rüzgarlı bir bank akşamında

sabahı bulduğumuzda 

bir kadın bir erkek uyanmıştık

bir kadın mahcup

bir erkek sarhoş

sana ve milyarlarca renge vurdum kendimi

toparlanman, tanımlaman lazım geliyor

bir erkeğe vız gelip tırıs gidiyordu

sen toparlandıkça ben dağılıyordum

hep tedirgin hep yanımda hep yaralayandın

beni ve bir garip yüreği



gittin birgün ve peşine yirmi gün

ve koptuk salkım salkım sesten, haberden

kainatı serdim yüreğime seni bastırsın diye

kazıdım seni kan oturarak yüreğimden

biliyorsun işte ne ben ne de sen...

olanları bir garip yürek bilir

III.

yokluğun süresince yok oluyordum

yavaş yavaş

başka dudaklara, başka nefeslere

başka yüreklere sattım kendimi

döndüğün gündü sessiz, habersiz

bıraktığın şeylere baktığında

onlar çoktan seni ve hatıralarını bırakıp gitmişti

oysa yüreğim çatal çatal olmuş

bir sağa bir sola uzuyordu

ben kararımı vermiştim sevmiyordu sevilen

aylar geçti 

ne adın ne sanın geçti

susmuş ve herşeyi o akışa bırakmıştık yine

köşeye bucağa saklandığım birgün

teker teker döküldüler sözcükler dudaklarından 

konuşmak istiyordun

yok diyesi gelmez alnında insan yazanın

bu kaçışı yazanın yok diyesi gelmez

kabul ettim kaçarak geçmişimizden

ve geleceğimizden

ne kaçabildim ne kovalayabildin

''önemli değilse konuşmayalım'' dı 

öneminden korkarak söylediğim

oturdun karşıma saplanarak gecenin ortasına

içimde çağlayan gizli ve haleli şeylerin 

bir kanat çırpmasını bekliyordum

kaçıp çıkabilmesi, damarlarımın boşalması için

önemliymiş anlatacakları ve soracakları beyaz yarin

açtı gözlerini yumdu ağzını

anlatıyordum ondan üryan kaçışımı

''neden? '' diyordu sabah gelmesin der gibi

''neden beklemedin beni? '' diyordu 

bu gece sana zindan der gibi

dört mevsimi, uzak yolları

kokusunun karıştığı rüzgarları anlattım ona

beynimin kalbime maruzatnamesi olarak

''peki... bunları diyorsun, hoş

 ben de sana seven beklemez miydi derim o zaman'' diyordu

düşülen kuyu nasılmış gör der gibi

sevmiyordu sevilen narin vahşi

sanki seviyordu ve soruyordu

o bana sordukça sormayı öğrendim

''neden aramadın iki kıta istanbuldan? '' diyordum

sabah gelmesin der gibi

boğazın mavisini, yarımadanın tarihini

mayısı, inzivadaki evini 

beni içindeki sorgulayışını anlatıyordu

biraz lamı biraz da cimi katarak

düşündün de ne oldu ki...

 kaçtın gittin işte

 ve  kalakaldım derinlerinde su alan gemimle

 ben de bir limana kaçtım işte'' diyordum

düşülen kuyu nasılmış gör der gibi

''geldiğimde kararımı vermiş 

 ve sana gelecektim umutla'' dedi

geldi sabah

geldi geçmiş

dört duvar ancak bu kadar sıkabilirdi suyumu

ancak ölüm geçirirdi gözlerimden yaşadıklarımı

film şeridi gibi

ne olurdu yarılaydı yer

ben içine düşeydim

içime kor düşmeden balam



çok sonradan sen söyledin

etrafıma duvar ördüğümü o saatlerde

uzanmış yerdeki yatağına

uzanmış yerdeki sevdama

yanıma gelmeni nasıl duvarlıyordum

duvarı kırman saatler almış

çok sonradan söyledim üflesen yıkılırdı

bir baktım kollarımdasın 

yürek bak dedim sevdanın yollarındasın

yıllarca aradığınız birşeyi bulduğunuzda 

doya doya onu yaşarsınız 

biz de öyle yaşadık o geceyi

herşeyin orada bitmesi gerekirken 

artarak sürdü doymamışlık

yarım kalan bir aşkı soruyorsanız

açgözlülüğün son noktası diyebilirim

sabahı bulduğumuzda 

bir kadın bir erkek uyumamıştık

aynı gün yine kaderin şakası

ve gene zorunlu ayrılık

memleket çilehanelerine seferler

döndüğümüzde kaçamadım bu örümcek süreçten

IV.

geceydi gene her zaman olduğu gibi kuyusunda zamanın

oturuyordum içim sereserpe yerlerde

sokaktaydın umarsız ve sarhoş edasıyla

ki umarsızdın  sarhoş değil

gene yıldız kaydı yeterdi artık

yukarıda kayan yıldıza aldandım

bankımıza gittik yine havuzun yanına yer ayırtmıştık

şarkılar... sözlerinin içimizi burkması ve anlatması

yasaktık ve öylesine güzeldik

öylesine özeldik haftalarca

korktuk sorgulamaktan birbirimize duyduklarımızı

hissettiklerimiz kulaktan dolmaydı sanki

iki geceni emanet ettin sürüklenerek

rüyayı reel yaşamak buydu ey şiir

sonrası...

sonrasıysa arayıp sormak 

hissedilen bir ton lak lak

tuttun üzerken üzüldüğün tek insan olduğumu 

yapıştırdın uzak denizlerde canlanan onca şeye

dalgalar, bir sandal, bir okyanus

yani bir batışı hissettim ilk defa

ne kaçabiliyorum ne kovalayabiliyorsun

günler tutsak ben gardiyan yuvarlanıp gidiyorduk

''hayatımın en güzel iki günü'' diyordun

bu süreç devam edecek 

ve her yaklaştığımızda bizi ayıracak birşeyler hep olacaktı

biliyordum

öyle de oldu yeni bir baharı beklerken 

sen gene kayboldun

ve koptuk salkım salkım sesten, haberden

bu sefer şaşırmayan bir akıl, kanayan bir yürek vardı

oysa yasaklardan kurtulmaya çeyrek vardı

saatini durdurdun

şimdi hangi zamanın, 

hangi geçmişin, 

hangi sevdanın bizi ateşleyeceğini biliyor muyuz? 

her ağzını açışın, salınışın 

hep şaşırtmayan süreci aklıma damgalıyor 

bu damgalayış hırçın dalgalara 

yıkılmaz dağlara, şaşmaz hayata vız gelecek 

sevebiliyorum diyemem seni

sevmek kolay sevebilmek zor

yaşanan ve elde edilmeyen çok şey

olmazı sahneleyecek ve perdeler inene dek böyle olacak

bunu bir yetim gibi kabullenmeliyiz

ne ağlamalı ne gülmeli

dimdik olmalı 

içimiz yangın çıkarmalı

dışımız ayaza çalmalı

ve herşey bir sonu bulmalıdan öte bulacak

hatta  sesler vuracak kulaklarımıza 

hatırımıza vurmayacak hiçbir ses zerresi ve anılar

öylece yaşandığın yerde kalacaksın ve de kaldın

bir yanlışı omuzladık yere çöktük 

bu günah beynimizi döndürecekti

bak o da oldu

bu şiiri içimde sen bittiğinde 

ya da ölüm çizgi çektiği zaman bitirecektim

işte şimdi bitiriyorum

yaşandığın yerde kaldın içimde

bilinmezlikteki sen etkisiz elemansın artık', 'I. kara tahta, sıralar ve okulun merdivenleri aşınmakta kitaplı eller beynimi kucaklamaktaydı bir yığın ders, iki yığın yıl, gurbet araların...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":220,"source_url":"https://www.antoloji.com/donup-dolasan-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burası Kainatın Tam Ortası', 'burasi-kainatin-tam-ortasi-ahmet-ozturk-z1ghx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İbretli soysuzluğuma baksınlar

Topraklayım

çocukluğumu ellerime alamadan

dert dediğin güneşte sararmış çayır çimen

dert dediğin kendine bakıp da

diyemediğin

yorgunum akıp giden ter gibi

buhar olup tuzum kalacak

tutulacak ellerim 

ben kimseye vermeden

ellerim ben mi olacak şimdi? 

Burası kainatın tam ortası 

Göğüs kafesimin kenarı 

Allı kanlı yüreğim

(08 Aralık 2001 Cumartesi)', 'İbretli soysuzluğuma baksınlar Topraklayım çocukluğumu ellerime alamadan dert dediğin güneşte sararmış çayır çimen dert dediğin kendine bakı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/burasi-kainatin-tam-ortasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnan', 'i-nan-ertan-ciloglu-4fac4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnız bırakılmayacak kadar ıssız, 

Doymayacak kadar aç, 

Üşümeyecek kadar soğuk, 

Korkmayacak kadar ürkek, 

Ölmeyecek kadar yaralı bıraktım 

belki de seni.

Ama sevemeyeceğin kadarda sevdim.....', 'Yalnız bırakılmayacak kadar ıssız,  Doymayacak kadar aç,  Üşümeyecek kadar soğuk,  Korkmayacak kadar ürkek,  Ölmeyecek kadar yaralı bıraktım...', ARRAY['Türk Edebiyatı','Şiir','Ertan Çiloğlu']::text[], 8.5, '{"poet":"Ertan Çiloğlu","poet_slug":"ertan-ciloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/inan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağınık Gazel', 'daginik-gazel-yilmaz-odabasi-92u4o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Eski güzel şeylerden değil,

yeni kötü şeylerden başlamak gerekir.”

                   -Water Benjamin-

Göç

geçer...

Geçer ayrılıklar baladı.

Siyah bir orman olur gençliğimiz.

Bize böyle pay kalır.

Bize böyle pay kalır...

Ağla sömürgem... Belki dönemem! 

Oralarda usul usul talazlanan nehirlerde yaz kalır; 

kış yanar, düş üşür yüreğimde.

Ağlarım, gözyaşım beyaz kalır...

Sonra askerler yeniden kuşatırlar aşınmış kaleleri.

Bin “hawaar “parçalar gecenin döşeğini.

Ocaklar iniler, yas büyür, orta yerde kan kalır; 

Dıngılava’da peştamallı çocuklar havuzlara işerler; 

gözlerinde bir mahmur özlem kalır...

Derken bir Ankara, bir poyraz beni döve döve içeri alır.

Yollar da giderek uzaklaşır... Giderek uzaklaşır.

Fahişeler terli kasıklarıyla sabaha uğurlanır,

kuşlar inkâr edilir, gökyüzü yağmalanır; 

ben büyürüm bu kederle kalbim uslanır...

Ağla sömürgem! 

Ağla ve kucakla kumral delikanlını.

Buralarda çatılmış bir tüfeğim böğrümde taflan kalır.

Şimdi Kızılay’da oturmuşum hasretin kancasında; 

geçer zaman, geçer yıllar, günlere bir yeni hazan kalır...

Ağla sömürgem... Sen hep mağlup bir ağlayışta,

ben uzak susarım bu mağlubiyet için hep anlayışta.

Bak, çöpçüler bu geceyi de piç edip süpürdüler.

Ben ise haber değeri bile olmayan bir haykırışta,

özleminle hâlâ bir yakarışta...

Ağla, ben de ağlarım gözyaşlarım özlemine az kalır.

Buralarda nem var; nem varsa sende kalır! 

Daha çağırırken beni,

anı bile kalmaya tenezzül etmeyen dağ dorukları,

sömürgem yaslar durur sesime kırgın ayrılıkları…

Ben gittim

ve yittim! 

Oralarda usul usul talazlanan nehirlerde yaz kalır,

yaslarım günleri yüzüme gözyaşım beyaz kalır.

Burada yıllar küfürle uğurlanır.

Ben büyürüm içindeki haylaz çocuk uslanır…

Ve günler geçer, herkes gider, pistler boşalır; 

sahnede bir kurtlar, bir ben bir klasik dans kalır.

Ağla sömürgem... Buralarda döne döne-

mem! Artık bir yeşile dolmasak da anılardan haz kalır.

Sen de bir zaman duyarsın

bir gün bir taze mezar kazılır:

A r d ı n d a  b i r  d a ğ ı n ı k  g a z e l  i l e, k ü l  i l e

A n k a r a ’d a   b i r   ö l ü  y ı l m a z  k a l ı r...', '“Eski güzel şeylerden değil, yeni kötü şeylerden başlamak gerekir.”                    -Water Benjamin- Göç geçer... Geçer ayrılıklar baladı...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Odabaşı']::text[], 8.5, '{"poet":"Yılmaz Odabaşı","poet_slug":"yilmaz-odabasi","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/daginik-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar', 'sarkilar-seda-sezgin-gglwv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün şarkılar seni hatırlatıyor bana

Her şarkıda senden bir parça

Bir şarkı gözlerini anlatıyor bana

Başka bir şarkı teninin kokusunu

Hiç duymasam da biliyorum kokunu

Hiç ''Seni seviyorum'' demesen de

''Seni seviyorum'' diyen sesin hep kulaklarımda

İşte şarkılar bunu da anlatıyor

Sensizliği anlatıyor...

(Hiç seninle olmasam da biliyorum seninle olmayı)

Çünkü şarkılar bunu anlattı bana

Hiç gelmesen de biliyorum gelişini

Çiçeklerle gelirsin sen gelirsen

Öpmesen de biliyorum öpüşünü

Şarkılar hep anlattı bana

Şarkılar hep öğretti

Şarkıların öğretmediği bir şey var sadece

Sensizliğe nasıl katlanırım 

İşte onu bilmiyorum.', 'Bütün şarkılar seni hatırlatıyor bana Her şarkıda senden bir parça Bir şarkı gözlerini anlatıyor bana Başka bir şarkı teninin kokusunu Hiç d...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sarkilar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokun', 'kokun-seda-sezgin-n3ji0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyorum geceleri

Gece gizliyor sanki hüzünleri

Mutsuzluğum gözükmüyor karanlıkta

Ve sen

Seni düşünüyorum artık her gece

Yastığıma sarılıyorum sana sarılıyormuşçasına

Ama yastık sen kokmuyor

Hüzün kokuyor yastığım

Bağırmak istiyorum 

Ben senin kokunu istiyorum

Ben seni istiyorum

Sadece seni', 'Seviyorum geceleri Gece gizliyor sanki hüzünleri Mutsuzluğum gözükmüyor karanlıkta Ve sen Seni düşünüyorum artık her gece Yastığıma sarılıyo...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kokun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-seda-sezgin-c2u0p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerimi uzatsam

Dokunabilir miyim

Orda mısın 

Eskisi gibi...

Bilmiyorum

Belki de sen hiç orda olmadın

Ben sana hiç dokunmadım

Bu da yalandı

Herşey gibi', 'Ellerimi uzatsam Dokunabilir miyim Orda mısın  Eskisi gibi... Bilmiyorum Belki de sen hiç orda olmadın Ben sana hiç dokunmadım Bu da yalandı...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalan-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Sevda', 'yalanci-sevda-seda-sezgin-2ervt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gittin...

Arkana bile bakmadan 

Önemsizdim senin için

Yalanlarda başlamıştın

Bu yalanlara sessizce son verdin

Ben arkanda

Gözlerim dolu

Bekledim

Dönersin belki diye

Senden sonra ben de yalanlar söyledim

Unuttum dedim

Ama unutmadım hiç

İlk bakışı

İlk dokunuşu

Belki unutmak da istemedim 

Hayatımdaki ilk yalancı sevdayı', 'Gittin... Arkana bile bakmadan  Önemsizdim senin için Yalanlarda başlamıştın Bu yalanlara sessizce son verdin Ben arkanda Gözlerim dolu Bekl...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalanci-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acele Aşk', 'acele-ask-seda-sezgin-f5gjr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acele bir aşktı bizimki

Herşey hemen yaşanmalıydı

Çünkü daha en başında ayrılık vardı

Seni seviyorum bile diyemeden gitmek vardı

Ağlamak vardı', 'Acele bir aşktı bizimki Herşey hemen yaşanmalıydı Çünkü daha en başında ayrılık vardı Seni seviyorum bile diyemeden gitmek vardı Ağlamak var...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/acele-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '514', '514-seda-sezgin-z59xz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giderken beni bile bırakmadın bana

Benden parça parça götürdün yanında

İnsan gülemezmiş ya eksikken

Ağlayamazmış da

Sen giderken ben de geldim seninle

İçim bomboş şimdi

Bende bana ait hiç bir şey yok artık

Senle dolu içim

Artık bende sen yaşıyorsun

             Benim yerime', 'Giderken beni bile bırakmadın bana Benden parça parça götürdün yanında İnsan gülemezmiş ya eksikken Ağlayamazmış da Sen giderken ben de geld...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/514-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ne-dersen-de', 'ne-dersen-de-seda-sezgin-8dvul', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani gözlerini kapatınca hep aynı kişiyi görürsün

Hani her gece rüyanda aynı kişiyi görmek için dua edersin

Hani sabahları uyanınca hep aynı kişinin gelmesini istersin

Hani hep aynı kişinin resmine bakarsın

Ve aynı kişiyi seversin hep

O seni sevse de sevmese de

İşte sen benim en büyük hayalim, isteğimsin

Ya da sen ne dersen de....', 'Hani gözlerini kapatınca hep aynı kişiyi görürsün Hani her gece rüyanda aynı kişiyi görmek için dua edersin Hani sabahları uyanınca hep aynı...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-dersen-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-seda-sezgin-9syim', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden gönül bu kadar inatçı

Bu kadar umursamaz

Ve acı çekmeyi bu kadar seviyor

Seni seven var

Sen de sevsene

Neden sevmeyenin peşindesin hep

İstese gelirdi

İstese evet derdi

O seni istemedi

Sen ni ye hala onu istiyorsun

Niye seni asıl isteyene bağlanmıyorsun

Neden sanki gelecekmiş gibi 

Her gün ona uyanıyorsun', 'Neden gönül bu kadar inatçı Bu kadar umursamaz Ve acı çekmeyi bu kadar seviyor Seni seven var Sen de sevsene Neden sevmeyenin peşindesin hep...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonul-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soruyorum', 'soruyorum-seda-sezgin-ey64v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanlar nasıl buluyor sevgiyi

Nasıl yakalıyor mutluluğu

Anlamıyorum

Bakıyorum çevreme sevgililer görüyorum

Sen geliyorsun aklıma

Neden diyorum

Neden biz de böyle olamadık

Neden elele yürüyemedik yollarda

Neden öpüşemedik boş sokaklarda

Ya da neden ıslanamadık iki kişiye asla yetmeyecek bir şemsiyeyle

Bu şiir böyle uzar gider asıl sen bana gelecek misin onu söyle', 'İnsanlar nasıl buluyor sevgiyi Nasıl yakalıyor mutluluğu Anlamıyorum Bakıyorum çevreme sevgililer görüyorum Sen geliyorsun aklıma Neden diyo...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuz', 'mutsuz-seda-sezgin-hgned', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutlu muyum 

Hep bu soruyu soruyorum kendime

Cevap açık HAYIR

Ne istiyorum peki

Neyi bekliyorum hala

Mutlu olmak için neyim eksik

Seviyorum, seviliyorum

Bu yetmez mi sanki

Yetmiyor

Sevdiğimle

Beni seven aynı insan değil ki', 'Mutlu muyum  Hep bu soruyu soruyorum kendime Cevap açık HAYIR Ne istiyorum peki Neyi bekliyorum hala Mutlu olmak için neyim eksik Seviyorum,...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mutsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-seda-sezgin-bamc0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılık nasıl mı olur dostum? 

Bütün hüzünlü şarkılar seni anlatır sanki

Onun yüzünü görürsün boş duvarlarda

Onun için ağlarsın her gece

Ve onu görmek için uyanırsın her sabah

Radyoda hep o şarkıyı beklersin

Hani ayrılığı anlatan

Hani seni anlatan

Ne onunla dersin ne de onsuz

Tekrar dersin

Tekrar başlasak

Hani mutlu günler yaşasak tekrar

Ama bilirsin tekrar başlamak

Tekrar ayrılmaya eşittir

Ve dayanabilir misin sanıyorsun tekrar bu acıya....', 'Ayrılık nasıl mı olur dostum?  Bütün hüzünlü şarkılar seni anlatır sanki Onun yüzünü görürsün boş duvarlarda Onun için ağlarsın her gece Ve ...', ARRAY['Türk Edebiyatı','Şiir','Seda Sezgin']::text[], 8.5, '{"poet":"Seda Sezgin","poet_slug":"seda-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayrilik-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-yusuf-sen-qisvd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seviyorum desende bir baskasını yalan 

Unutamayacaksın beni; unuttum desende inan

Benim yerime kim olursa seni soran 

Benim diye ona sarılacaksın inan

Öyle günler gelecekki haykıracaksın 

Beni uzak uzak yasayacaksın 

Bir yabancıyı dahi ben sanacaksın

Sevdigin sandıgın her kiside beni bulacaksın

Unuttum desende yalan 

Bendim seni senden ilk alan 

Sevgimizden geriye tek kalan 

Unuttum seni dedigin o koca yalan...

Seni Seviyorum', 'Seviyorum desende bir baskasını yalan  Unutamayacaksın beni; unuttum desende inan Benim yerime kim olursa seni soran  Benim diye ona sarılac...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Şen']::text[], 8.5, '{"poet":"Yusuf Şen","poet_slug":"yusuf-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalan-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senmisin', 'senmisin-yusuf-sen-njbf7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senmisin aradığım sevgili 

Yoksa bir kalp yanıltmasımı

Herzaman yanımda kalacakmısın

Yoksa bir baskasındamı

Sevdalandığım aşkım senmisin

Yoksa yine bir hüzün çemberimi

Tekrar seviyorum dediğim senmisin

Belkide karşılaştığım beterin beterimi

İlkgörüşte vurulduğum senmisin

Beni benden alabilecek, 

Sevinçten göklere uçurabilecek, 

Seni seviyorum dedirtecek, 

Senmisin birtanem senmisin...', 'Senmisin aradığım sevgili  Yoksa bir kalp yanıltmasımı Herzaman yanımda kalacakmısın Yoksa bir baskasındamı Sevdalandığım aşkım senmisin Yok...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Şen']::text[], 8.5, '{"poet":"Yusuf Şen","poet_slug":"yusuf-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senmisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Gözlüm', 'kor-gozlum-baris-akm-caf4r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeter be kör gözlü azrailim 

Bir kere de şaşırma beni 

Kurşunların ıskalamak yerine 

Sıyırıp geçmek yerine etimi 

Tam ortasından vur başımı 

Sevmiyorum işte hayatı 

Zorla sevilmezki 

De ki ben istedim 

De ki ben seçtim 

Hayat çizgimin rengini 

Tırnaklarımla kazıdım kendimi 

Şimdi de, azrail seni istiyorum 

Sonsuza kadar oynayacağım 

Tahta atımı istiyorum 

Üstünde, yahut içinde olacağım 

Hani çocukken hiç olmayan 

İstemiyorum yaşamadığım zamanları 

Mal mülk istemiyorum ne sevdası 

İstediğim son bir çivi 

Yırtıp yırtıp tenimi 

İnlettiğin ruhum özlüyor seni 

barış', 'Yeter be kör gözlü azrailim  Bir kere de şaşırma beni  Kurşunların ıskalamak yerine  Sıyırıp geçmek yerine etimi  Tam ortasından vur başımı ...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kor-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Bu Ne-ki', 'daha-bu-ne-ki-baris-akm-pivrl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha bu bir şey değil 

Sanmaki bu kadara sığar 

Bu kadar sözün sırrı 

Akşam olsun bir hele 

Güneş şu memleket gibi 

Şu derya kentini bir yaksın 

Kuşlar yuvalarına dönsün hele 

Sen o zaman gör beni 

Yeni bir şişe daha açınca 

Bir Kutup Yıldızı''ndan 

Bir gecenin demlerinden mezem 

Daha bu bir şey değil 

Henüz öğleyi gösteriyor akrepler 

Yelkovanla onikide sarılsın bir 

Işıklar sönmeye dursun perdelerde 

Kaldırımlarda, bir gölgeler kalsın hele 

Sen o zaman dinle sarı gazelleri 

Yeşil bildiğin, hani güneşte nemli 

Seherde inci sandığın çiğ tanelerini 

O yeşilin hakiye kavuşmuş rengini 

Sen bir de o zaman gör beni 

Daha bu bir şey değil 

Hiç değil', 'Daha bu bir şey değil  Sanmaki bu kadara sığar  Bu kadar sözün sırrı  Akşam olsun bir hele  Güneş şu memleket gibi  Şu derya kentini bir yak...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/daha-bu-ne-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir adam', 'bir-adam-baris-akm-k25no', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir adam 

Yaşamdan yana özürlü bir adam 

Artık kendini bile tanımayan 

Geceymiş günmüş farketmeyen 

Sevmek sevilmek bile acı verirken 

Kendinden kaçarken bile düşen 

Bir adam 

Artık 

Kendi canı ağır gelemeye başlamışken 

Bir nefes bile meğer ne zormuş derken 

Bir uyku nasıl özlenir bilirmisin? 

En kınalısından kızılından 

Zaman ne çok şey alıp gitmiş 

Sapıyla vermeden malı götürürken 

Ne savaşların toprağı olmuş beden 

Can bedenemi yük 

Bedenmi cana fazla yoksa 

Yoksa 

Varsa yoksa bir adam 

Bir masal şehri akşamları 

Yıldızları bir başka solgun 

En son mehtap ne zamandı 

Unutulmuş 

Unutulmuş çoktan 

Nefes alıyor olmak 

Gözlerinin incili incisiz açık olması 

Yaşıyorum demekse eğer 

İşte böylesine iyiyim ben 

Çok şükür bir sabah daha varmış 

Görmem gereken 

Biraz daha yol yürümem 

Bir adam ben 

Yaşıyorum bak işte 

Kendimden bir haber 

Yaşamdan 

Yarından umutsuz dallarım 

Bugün bile zor gelirken 

Sisli bir nefes bile canımı acıtırken 

Çiçekli rüzgarlar ölüm gibi eser düşlerimden 

Meğer ne zormuş insanın kendine ağır 

Kendine yük olan yapraklarının dökülmemesi 

Yaşam bu olmasın meğerki 

Var oluşun karanlığı bir kere sevmesin 

Bir kere günlerin, güneşin gri olmasın 

Alışır gider bu ağırlığa ayakların 

Acılı denizlerin lacivert gözlarine martıların 

Bir adam 

Bir küçük ömür törpüsü yeter ömrüne 

Sevmek yasak onun defterine 

Beyaz sayfaları sürgün ayaz bozkırlarına 

Sibirya mı? 

Epeydir gülmüyordum 

Şimdi gülerim ben buna 

Ben hep böyle gülerim işte gülünce 

Keskin ve soğuk soluğu 

Bıçak gibi namussuz akşamlarda 

Seheri kınasız sabahların kucağına uyanınca 

O ilk göz açışın serin olması gerek nefesinde 

Bir sarhoşluk doğar bazen 

Işır güvercin misali vitrinimde 

Bir külhanbeylik eser başımda 

Kara bir kasırga saçlarımda 

Son nokta konmaz bir türlü yüreğime 

Bir varmış bir yokmuş 

Hiç olmamış 

Gelip geçmemiş dünyadan 

Bir adam', 'Bir adam  Yaşamdan yana özürlü bir adam  Artık kendini bile tanımayan  Geceymiş günmüş farketmeyen  Sevmek sevilmek bile acı verirken  Kendi...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/bir-adam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüyorum', 'guluyorum-baris-akm-i69fp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüyorum işte bak yeni güne 

Dün dündü demek var amma 

Dil dönmüyor günün umuduna 

İstanbul resmi kapağımda 

Kızkulesi yanar geceleri sularımda 

Galata''sı bir tepede 

Bayezit Kulesi ötekinde 

Çamlıca durur Üsküdar''ın ardında 

Düşlerimi salarım oradan İstanbul''a 

Nasıl da güzel görünür gece oradan göze 

Bilirimki kaç yürek soyunuyor içinde 

Vurmak için kıyının birine 

Sönmeye hazırlanan kaç ışık tetikte 

Son vapur yanaşıyor Kavak''a 

Eminönü''ne varınca bitecek günü 

Sabah çıtırdarken dallarda 

Gahi bulut doğar sabahlara 

Gahi en nadide güneş gözlerime 

İşte böyleyim ben yine 

Bir yanımda seher, bir yanımda gece 

Bir başından İstanbul''un, bir başına 

Avare dallardan bir çiçek elimde 

Gahi beyaz kardeş otağına 

Gahi pembe dost dağına 

Bir kırmızı ki gülde 

Soldu solacak avuçlarımda 

Belki uçacak bir ela göze 

Belki yeşile, belki zeytin karasına 

Geç kalsa da trene garda 

Bir umut yakalarım sondan bir önce 

Gitmeye çeyrek kala', 'Gülüyorum işte bak yeni güne  Dün dündü demek var amma  Dil dönmüyor günün umuduna  İstanbul resmi kapağımda  Kızkulesi yanar geceleri sular...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/guluyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Gazel', 'olume-gazel-omer-yavuz-can-7b3w1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sonbaharda eller utangaç olur

belki bulamadıkları için seni

ve 

devam eden günler

ve

arada aralarda gidip gelmeler

ölümü tamamlayan yüzler

nihayetinde 

anlaşılmadı

her şey ama her şey bekleniyordu

birisi ya da birileri

günlere daha çok vardı

saat saat düşünce ikliminin kışındaydım

ve

kış gene huysuz çoçuğu oynuyordu 

bekliyorum

kapı zili çalındı

kapı zilim yoktu ki', 'sonbaharda eller utangaç olur belki bulamadıkları için seni ve  devam eden günler ve arada aralarda gidip gelmeler ölümü tamamlayan yüzler n...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yavuz Can']::text[], 8.5, '{"poet":"Ömer Yavuz Can","poet_slug":"omer-yavuz-can","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olume-gazel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimseye Soramıyorum Seni', 'kimseye-soramiyorum-seni-ceyhun-yilmaz-otuy6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kimseye soramıyorum seni! 

kirlenme diye hiç öpmedim ya...

belki başkasını seversin diye, 

hiç söylemedim sana sevdiğimi.

bilmiyorsun, 

boğazımda düğümsün! 

yutkunsam gideceksin, 

yutkunmasam...

ölürüm...!', 'kimseye soramıyorum seni!  kirlenme diye hiç öpmedim ya... belki başkasını seversin diye,  hiç söylemedim sana sevdiğimi. bilmiyorsun,  boğa...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kimseye-soramiyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buna Ayrılık Derler', 'buna-ayrilik-derler-ceyhun-yilmaz-394xj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ıslak bir sabah dağıttım kendimi.

gözlerimde yaş, 

dudaklarım yok! 

adım atmak istersin, 

yürüyemezsin ki! 

ellerin donar, yüreğin titrer.

gözyaşı...

üşüdüğünü zannedersin, 

ölmektesindir.

sıkı dur bebeğim, 

buna ayrılık derler!', 'ıslak bir sabah dağıttım kendimi. gözlerimde yaş,  dudaklarım yok!  adım atmak istersin,  yürüyemezsin ki!  ellerin donar, yüreğin titrer. g...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/buna-ayrilik-derler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kahpelikler Gördüm Ben -1-', 'ne-kahpelikler-gordum-ben-1-golge-gezgini-hzz1q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanırım artık yok yüzün aynada

Yok artık benliğin 

Bozamazdı hani acılar bizi

Hani her belada bir olurduk olmazları bulurduk

Günlerce ağlamaktansa 

Kahırlarımızı birleştirir

Kahrederdik

Sinsilikle değil

Bağıra çağıra yürürdük hani belaya

Hani köpekler ve kuşlardan feyz alırdık

Ezdirmezdik birbirimizi kimseye

Dualarımızla yaşardık hani

Beddua etmeden yaşamaktı amacımız hani

Hani Kaybetmek yoktu kitabımızda

Hani bu yaz beraber olacaktık

Günleri arpalara bölüp atacaktık hani torbaya

Her arpada biraz daha sevinip ağlayacaktık hani

Hani ölüm ayıracaktı bizi birbirimizden 

Ben ne kahpelikler gördüm be gülüm bu birşeymi

Evimi başıma yıkıp gitmek gibiydi bu

Bu gölgeme ışık tutmaktı 

Peşinden koştuğum gölgeme güneşler hediye etmekti

Bu ölümden beter sanırım

Ama dayanırım be gülüm 

Hani demiştim ya

Hatırlasana

Ben bahtsızımdır diye

Ama olsun yıkılmadım 

Üzülme ben ne kahpelikler gördüm be gülüm', 'Sanırım artık yok yüzün aynada Yok artık benliğin  Bozamazdı hani acılar bizi Hani her belada bir olurduk olmazları bulurduk Günlerce ağlama...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ne-kahpelikler-gordum-ben-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kahpelikler Gördüm Ben -2-', 'ne-kahpelikler-gordum-ben-2-golge-gezgini-dxusd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani demiştim ya zor olur isteklerim

Yok ağlama be gülüm

Yıkılmam korkma

Ben ne kahpelikler gördüm

Hani demiştim ya

Benim her işim zordur diye

Dur be güzelim içlenme hemen 

Yıkılmam korkma

Ben ne kahpelikler gördüm

Sussana be gülüm 

Dur hele bi 

Bu ilk değil benim için 

Ne çabuk unutttun

Benim ne kahpelikler gördüğümü

Ben her yolu gece geçerim bilmezmisin

Temizdir her yol

Her karanlık

Üzülme be gülüm

Sil gözlerini

Unutma 

''Yıkılmam ben korkma'' dediğimi

Ben ne kahpelikler gördüm be gülüm

Sil gözlerini yaşa.

Yaşa ve mutlu ol gülüm.

Unutma 

Yıkılmam ben korkma.', 'Hani demiştim ya zor olur isteklerim Yok ağlama be gülüm Yıkılmam korkma Ben ne kahpelikler gördüm Hani demiştim ya Benim her işim zordur di...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ne-kahpelikler-gordum-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönme Sakın', 'donme-sakin-golge-gezgini-ewflt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Demek gidiyorsun

Git, kapıdan ardına bakma

Bu akşam git.

Mahşerde görüşelim

Dönme sakın

Ve tanıma dediğini unutup

Tanıyacağımı sanma

Yağmurlara git

Git sırıl sıklam hayata

Sırıl sıklam gözlerim gibi

Unutma sakın 

Unut dediğini

Hatırlayacağımı sanma

Seni bana

Getirecek şöförlerle takılma

Seni benden götüren 

Deliliklere takıldığını unutup

Git dediğini unutup 

Döneceğimi sanma

Küsmeyeceğimi sanma hain geceye

Seni benden alan geceye

Özleyeceğim; 

Ama özleyeceğimi de sanma

Özleme dediğini unutup

Özleyipte dönme sakın.

Unutma mahşerde görüşelim dediğimi.

Dönme sakın..', 'Demek gidiyorsun Git, kapıdan ardına bakma Bu akşam git. Mahşerde görüşelim Dönme sakın Ve tanıma dediğini unutup Tanıyacağımı sanma Yağmurl...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/donme-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Lazımsın', 'sen-lazimsin-golge-gezgini-n17u8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günlere kafa tutmak

Topraktaki verime isyan

Doğduğum yazgıma küsmek

Kitapları yakmak

İşte benim hayatım

Gecelere verdiğim 

Kuraklığa verdiğim

Canımı vereceğim

Romanlara verdiğim

İşte benim kara sevdam

Güneşlerden büyük

Dağlardan yüce

Kalbimden taşan

Beynimden çıkmayan

İşte benim Aşkım

Kum tanesinden ufak

Pireden küçük

Diş kovuğunu doldurmaz

Akılda bir harften az

İşte bu da sen

Firari kalbime

Bakmadığım yüzüme

Dumanlanmış ciğerime

Taşıyamayan bedenime

Bunca Şeye Rağmen

Sen Lazımsın...', 'Günlere kafa tutmak Topraktaki verime isyan Doğduğum yazgıma küsmek Kitapları yakmak İşte benim hayatım Gecelere verdiğim  Kuraklığa verdiği...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-lazimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız Duygular', 'adsiz-duygular-mehmet-kepez-efcbo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinin buğusu durduruyor zamanı

Geçmişle gelecek yok oluyor o an

Kaçırdığında gözlerimde gözlerini

İşlemeye başlıyor yeniden zaman

O korkunç kararlığıyla

Yüreğimin en kurak ikliminde

Gürül gürül bir bahar olup

Ekleniyorsun kimliğime

Düşler kuruyorum senli

Belli belirsiz

Adı tanımlanmamış duygular konuk oluyor yüreğime

Sen gecenin bilmem kaçıncı uykusundasın

Bense

Yasaklanmış sözlerden dizeler örüyorum 

Sana.', 'Gözlerinin buğusu durduruyor zamanı Geçmişle gelecek yok oluyor o an Kaçırdığında gözlerimde gözlerini İşlemeye başlıyor yeniden zaman O kor...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kepez']::text[], 8.5, '{"poet":"Mehmet Kepez","poet_slug":"mehmet-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/adsiz-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Yıl', 'gecen-yil-orhan-kotan-aat0x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'geçen yıl

haberler geliyor ardarda 

haberler kanlı 

karanlık 

gri göklerde bin yıllık keder 

ve ecnebi sokaklarda yalnızlık 

yas var 

ölüm ve işkence siyahına büzülmüş hayat 

dijle kan akıyor diyorlar 

parça parça cesetlerle kararmış fırat 

basma perdeler güne kapalı 

gramafonlar kısık 

gencecik gelinlerin rahminde kasatura 

bir afet 

bir salgın olarak büyüyor kısırlık 

haberler geliyor ardarda 

haberler kanlı 

karanlık 

umudu yaşadık geçen yıl 

öfkeyle 

kin tutarak 

eylül''den bu yana 

hesap-kitap 

istatistik 

on idam 

sekseni işkenceyle binikiyüz cinayet 

yaralılar 

sakatlar da ayrı 

kızıltepe dokuz can verdi 

kamışlı onbeş 

- üçü kadın 

üçü çocuk 

biri de gebeydi ilk bebesine - 

vahşet sınırları tuttu iyice 

hücrelere koğuşlara yayıldı 

ekim 

adalı''yı aldı götürdü 

aralık 

erdal'' ı 

sonra 

''kürt halkı da bütün halklar gibi 

insanca yaşama hakkına sahip olmalıdır'' dediği için 

''türk devleti 

kürt ulusuna 

köle olmayı öneremez'' dediği için 

vurdular kollarına kelepçeyi 

beşikçi''nin 

gülseren 

- ruşen''in karısı- 

kocasını göremedi aylarca 

ceyhun, kardeşim benim 

- yaşamadan çocukluğunu 

ilk gençliğini - 

umutsuz bir ihtiyar oluverdi bir yıl içinde 

yılmaz askerliğini bitirdi 

konuşmaya başladı jir - yeğenim - 

mümtaz'' ın kızı 

- zelal - 

okuma yazma öğrendi 

mektup yazdı bana 

resim gönderdi 

çiçekleri 

ağaçları 

bulutları ile 

koca bir dünya 

resmin üstünde bir kelepçe var 

zincirinde kan 

sonra öğrendim ki bütün bir yıl 

hasret büyüten çocuk 

bir dakika görebilmiş babasını 

kollarında zincir yaraları 

bileklerinde kan 

zelal - mümtaz''ın kızı - 

bir daha ne zaman yazar bilemem 

ama biliyorum ki 

okullar tatile girince 

ve parası da varsa anasının 

gene gidecek diyarıbekr''e 

hasret dolu gözleri 

ve beyaz 

toparlak yanaklarıyla 

biliyorum ki 

gene konuşamayacak doyasıya 

ve göremeyecek geçen yılki amcalardan pek çoğunu 

ali'' yi 

ferhan''ı 

önder'' i 

ve kimliksiz vurulup 

törensiz gömülenleri göremeyecek 

dijle''nin çığlıklarından 

fırat''ın homurtularından yükselen seslerle 

demek ki yazın 

demek ki diyarıbekr''in cehennem yangınında zelal 

zincir seslerini 

copları 

ve köpek hırlamalarını duyabilecek ancak 

bir de kanlı duvarlara yapışmış 

çıplak gözlerle 

ölülerimizin direnme türkülerini 

umudu yaşadık geçen yıl 

öfkeyle 

kin tutarak 

saksılar soldu, büzüldü 

ama 

dağlarda 

solgun bir güz geçirileceği düşünülmedi hiç 

bütün bir yıl solgun bir güz 

çiçeksiz 

rüzgarsız 

miting alanlarının coşkusu kelepçede 

grev şenliklerinde panzer karası 

ve asla bahara çıkılamayacakmış gibi 

zemheri ayazı yürüdü düşüncelerimizden 

ölüler taşıdık bir odadan bir odaya 

ölüler 

ölüler 

ölüler 

kirli uzun tırnakları 

kireç beyazı ayaklarıyla 

parçalanmış başlar 

ezik kollar, bacaklar 

bir odadan bir odaya sürünüp durdu hüzün bulutları 

kederli türküler 

ve donmuş 

simsiyah gözlerle 

silahları pas tutmuş 

yalnız ve aç gerillalar böldü uykuları 

çığlıklar çarpıp çarpıp döküldü duvar diplerine 

sonra duyuldu ki 

düşük kabusları içinde de olsa 

derinden derine duymaktadır cem 

üçüncü bebeğinin kalp seslerini 

usul usul büyümektedir meral''de yeni bir can 

ve kristina 

bir oğlan daha doğurmuş 

adı serdar 

demek ki 

stockholm'' e bahar 

büyüyen bebeklerle gelecek 

demek ki 

her ne kadar 

bahara ulaşılamayacak diye düşündüysek de 

bahar 

çatlayan tomurcukları 

yağmur yüklü bulutlarıyla 

kıpırdamaktadır buzların arasından 

varsın kanlı irinleriyle nefrit 

oyup dursun böbreklerimi 

ne çıkar 

doğan 

ve doğacak olan bebeklerin çığlıklarında 

stockholm''de de olsa 

ses edip 

boyvermektedir bahar', 'geçen yıl haberler geliyor ardarda  haberler kanlı  karanlık  gri göklerde bin yıllık keder  ve ecnebi sokaklarda yalnızlık  yas var  ölüm v...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kotan']::text[], 8.5, '{"poet":"Orhan Kotan","poet_slug":"orhan-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":154,"source_url":"https://www.antoloji.com/gecen-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yerine', 'son-yerine-orhan-kotan-frn9t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kirsiz-passız, arı duru özümüz 

namussuza kanlı hançer sözümüz 

çok uzaktır dostlar bizim yolumuz 

düşene dövüşene bin selam olsun', 'kirsiz-passız, arı duru özümüz  namussuza kanlı hançer sözümüz  çok uzaktır dostlar bizim yolumuz  düşene dövüşene bin selam olsun...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kotan']::text[], 8.5, '{"poet":"Orhan Kotan","poet_slug":"orhan-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-yerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-mustafa-egilmez-h5bje', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerin batıp çıkardı maviye

her batış bir mevsim

her batış bir sevgili

kardaydı

batışları çıkışlarından', 'gözlerin batıp çıkardı maviye her batış bir mevsim her batış bir sevgili kardaydı batışları çıkışlarından...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Eğilmez']::text[], 8.5, '{"poet":"Mustafa Eğilmez","poet_slug":"mustafa-egilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mavi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enayi', 'enayi-mustafa-turk-2-lbhyz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyük bir hikayeydi Fuzûli

Tek kalemde eyledi Mecnûn''u deli

Aşkları sürermiydi ebedi

İstinsah etmeseydi Mecnûn''u Fuzûli

Hüseyin varken Fuzûli 

Yazmamalıydı Mecnûn''u fuzuli

Çağ yirminci asır mecnun oldu enayi

Oldu ya ne yazar fuzuli', 'Büyük bir hikayeydi Fuzûli Tek kalemde eyledi Mecnûn''u deli Aşkları sürermiydi ebedi İstinsah etmeseydi Mecnûn''u Fuzûli Hüseyin varken Fuzûl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Türk 2']::text[], 8.5, '{"poet":"Mustafa Türk 2","poet_slug":"mustafa-turk-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/enayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nilüfer', 'nilufer-mustafa-turk-2-46qax', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.....Ve gökteki ay suya düştü, 

Gönlüm gölün sathına döndü.

Su üzerinde bir garip Nilüfer, 

Söndü seher vakti ay ile beraber.', '.....Ve gökteki ay suya düştü,  Gönlüm gölün sathına döndü. Su üzerinde bir garip Nilüfer,  Söndü seher vakti ay ile beraber....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Türk 2']::text[], 8.5, '{"poet":"Mustafa Türk 2","poet_slug":"mustafa-turk-2","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nilufer-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkıp Gel', 'cikip-gel-yavuz-turhan-fkp7d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''''Özlediğimde aynalara bakıyorum: 

gözlerimde sen varsın.''''

          Sırların içinden

çıkıp gel...

           Tutuştur bedenimi...

Ateşi dudakların olsun.

            Özlemini tazele.....', '''''Özlediğimde aynalara bakıyorum:  gözlerimde sen varsın.''''           Sırların içinden çıkıp gel...            Tutuştur bedenimi... Ateşi du...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cikip-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğim', 'gelecegim-levent-akcay-05m53', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu son seferim aşka... 

Daha önce ne gittiğim yerlerde bulabildim nede sığındım limanlar bana aşkı anlattı. 

Bir kördüğümdü, bir anlamsızlık, bir  umursamazlık, bir sahiplenme duygusuydu ki, bitirdi aşk sandıklarımı bir bir.... 

Tam bitmişken, tam yitmişken geldin hani, kumsaldan, deniz masalları anlatan...

Sen anlattın ben dinledim, 

ben anlattım sen dinledin...

Sonra martılar BİLE Sustu, 

hatta bir kanat sesi bile yoktu

HANİ ACILARINI 

DİNDİRECEK BİR ÇARE OLMAYINCA SUSAR YA İNSAN, SEN SUSTUN, BEN SUSTUM, MARTILAR SUSTU...

Konuşan sadece yürekler oldu.... 

Sadece gözler, duygular konuştu... 

Sonra yürüdük el ele kumsalda, sahiller bizimdi, kirlenmiş 

denizler kiminse kimin... 

Martılar hani hep yanımızda idi, kimi suskun, kimi çığlık çığlığa, sevgimiz bizim, aşkımız bizim....

İşte aşk bu dedin, bana sevilmeyi ögrettin... 

Ben sevmeyi bilirim sevilmeyi asla demistin, bende hep sevdim, hiç sevilmedim...

Sen bendin?

Ben sen miydim? 

Bunca sene aynı duygularla farklı bedenlerde mi yaşamıştık...? 

Şimdi aşkı arıyorduk birbirimizde, 

Kumsallar, deniz yıldızları, yakamozlar bizim, kirlenmiş denizler kiminse kimin....

Kentlere geçemedik, 

zaten almadılar bizi içlerine, 

biz sahil insanlarıydık, 

aşkı arayan, 

sevmeyi bilen, 

sevilmeyi asla, 

kentlerde öğrenemeyen...

Sevilmeyi ögretmeye calışıyoruz simdi birbirimize aşkla kumsallarda... 

Bu son seferim aşka, kılavuzum martılar, yelkenim sen, bir aşk selidir içimde esen..... 

Bu son seferim sana düzenlenen....

 Yıllarca sürsün istediğim, 

martılar hep sevinç çığlıkları atsın diye dilediğim, kumsalımızda mutlu bir yasam özlediğim, 

bir sefer düzenliyorum sana, 

AŞKLA.... 

Aç kollarını bekle, bahar da yada yaz da... 

Geleceğim..... 

O zaman işte hiç güz olmayacak, 

denizler hep temiz, kumsallar hep aşk kokacak... 

Hep yaz olacak..

Hep sevda, şiirler olacak hayatımızda, 

Masallar gerçek olacak, 

sevilmek ve sevmenin tadı damaklarımızda kalacak.. 

  Masallarını biriktir, 

o güzel şiirlerini topla bir bir.. 

Geleceğim...  

Deniz kumsalı öperken, 

güneş ufukla dans ederken, 

DENİZLERDEN GELECEGİM, 

ellerim ellerinde olacak, 

masallar gerçek olacak...

BU SON SEFERİM OLACAK AŞKA...

Sen benim, ben senin... Kirlenmiş denizler kiminse kimin', 'Bu son seferim aşka...  Daha önce ne gittiğim yerlerde bulabildim nede sığındım limanlar bana aşkı anlattı.  Bir kördüğümdü, bir anlamsızlık...', ARRAY['Türk Edebiyatı','Şiir','Levent Akçay']::text[], 8.5, '{"poet":"Levent Akçay","poet_slug":"levent-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/gelecegim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapacaklarım', 'yapacaklarim-levent-akcay-psqbi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğimi anlatabilmek için bitanem, 

Yıldızları gökyüzünden koparıp

Dolunayın üzerine takacağım

Yağmurları bulutlarından ayırıp

Ovaların çukurlarında toplayacağım

Güneşi parçalara bölüp

Başına taç yapacağım

Yüreğimin en derinine uzattığın sevgini

Senin güzelliğinle yoğurup

Tatlı ve uzun bir öpücük olarak

Dudaklarına konduracağım.

Ellerin ellerimde olacak

Bedenin bedenimde

Herkes bizi konuşup

Bizi kıskanacak

Zaman akıp gitse de

Seni tüm sevgimle

Ömrüm boyunca içimde tutacağım.

Bunu bilmeni istedim

Bebeğim, bitanem

Tek sevgilim

Artık senin oldum

Hep senin kalacağım', 'Seni sevdiğimi anlatabilmek için bitanem,  Yıldızları gökyüzünden koparıp Dolunayın üzerine takacağım Yağmurları bulutlarından ayırıp Ovalar...', ARRAY['Türk Edebiyatı','Şiir','Levent Akçay']::text[], 8.5, '{"poet":"Levent Akçay","poet_slug":"levent-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yapacaklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmasaydın', 'sen-olmasaydin-levent-akcay-nt8vh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben olmasaydım

Duyar mı idin fısıltılarımı

Görür mi idin gözlerimi

Sana saklı düşüncelerimi

Sever mi idin ki beni

Haykırarak

Son nefesine kadar

Dokunur mu idin ellerime

Sen beni bilmeden

Ben ise seni sevmeden önce? 

Sana ait olan

Benden sana kalan

Hislerimin özü; 

Sen görmesen bile

Gökyüzünde dolaşacaklar sessizce

Kimseler görmese de sen bil yeter

Çünkü senin sevgin her şeye değer

Ya görmezden gelse idin? 

Ya anlamasaydın? 

Ya hissedemeseydin? 

Varlığımın sana aktığını

Ya gözlerin kör olsa idi? 

Dudakların kupkuru? 

İki damla gözyaşında

Kalbine aksaydı

Kör kıyılarda ışıksızdım şimdi

Ya senin sevgin olmasaydı...?', 'Ben olmasaydım Duyar mı idin fısıltılarımı Görür mi idin gözlerimi Sana saklı düşüncelerimi Sever mi idin ki beni Haykırarak Son nefesine ka...', ARRAY['Türk Edebiyatı','Şiir','Levent Akçay']::text[], 8.5, '{"poet":"Levent Akçay","poet_slug":"levent-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-olmasaydin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı Şehir', 'yabanci-sehir-hermann-hesse-irln9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasılda üzüyor insanı

Yürüyüş, yabancı bir şehirde

Çatıları ayın parlattığı

Öylece uyuklayan sessiz gecede

Kule ve tepelerin üzerinden

Bulutların imrenilen gidişi

Vatansız, ama vatanını arayan

Güçlü ve sessiz bir ruh gibi

Fakat sen iradesizce, aniden

Teslim oluyorsun bu acılı sihre

Ve bırakıp mendilini elinden

Acı acı ağlıyorsun uzun süre', 'Nasılda üzüyor insanı Yürüyüş, yabancı bir şehirde Çatıları ayın parlattığı Öylece uyuklayan sessiz gecede Kule ve tepelerin üzerinden Bulut...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann-hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yabanci-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-hermann-hesse-rdjek', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluğu aradığın sürece, 

Mutlu olacak kadar olgun değilsindir, 

Ve ulaşacak kadar her istediğine.

Kayıplara yakındığın sürece

Ve hedeflerin varsa durmadan yöneldiğin, 

Bilemezsin huzur nedir diye.

Vazgeçersen şayet her arzudan, 

Ne hedef, nede istek tanıyıp

Mutluluğu artık adıyla anmıyorsan, 

O zaman olup bitenlerin akışına

Dayanamaz yüreğin ve ruhun erişir huzura..', 'Mutluluğu aradığın sürece,  Mutlu olacak kadar olgun değilsindir,  Ve ulaşacak kadar her istediğine. Kayıplara yakındığın sürece Ve hedefler...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann-hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mutluluk-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Ülkesi', 'masal-ulkesi-mutlu-gonen-rd8q9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir masal ülkesinin kapısındasın; 

Aydınlık günler düşle, yıldızlı geceler

Hayallerin bir martının kanadına takılı

Yüreğin ay kadar büyük ve parlak.

Ben küçük bir su damlasıyım

Sense deniz.

Düşen bir yaprağın ağladığını kim bilebilir.

Ben küçük bir yaprağın kalbindeyim nicedir

Sense rüzgarın gözlerinde.

Yağan yağmurun aslında gülümsediğini,

Ve yıldızların geceleri üşüdüğünü kim bilebilir.

Bir masal ülkesinin kapısındasın işte. 

Billur kadehlerde gizle gözyaşını, 

Ve ağlamaktan korkma sakın.

Olacaksan aşkın rengi ol, 

Acemi bir aşığın gözleri gibi; 

Çekingen, tutuk, kaygılı ve rengarenk.

Çiçeklerin rüzgarla fısıldaştığını, 

Ve bir yamaçtan özlemle denize baktığını kim bilebilir.

Bir çocuğun düşlerini kaçan balonunda gizlediğini, 

Ve ağaçların aslında yalnızlıktan korktuğunu kim bilebilir.

Bir masal ülkesinin kapısındasın işte; 

Aydınlık günler düşle, yıldızlı geceler

Hayallerin bir kırlangıcın kanadına takılı

Yüreğin ay kadar büyük ve parlak.

Düşen bir yaprağın  ağladığını kim bilebilir.

Ben küçük bir yaprağın kalbindeyim nicedir,

Sense rüzgarın gözlerinde ve bir masal ülkesinin kapısında....', 'Bir masal ülkesinin kapısındasın;  Aydınlık günler düşle, yıldızlı geceler Hayallerin bir martının kanadına takılı Yüreğin ay kadar büyük ve...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Gönen']::text[], 8.5, '{"poet":"Mutlu Gönen","poet_slug":"mutlu-gonen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/masal-ulkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amacım', 'amacim-sair-sefil-pgelo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni ürküten hayatın boşluğu değildi

İçimdeki soğuk boşluğun kadar

Hayatın koymuşluğuna yenilmedim

Beynindeki gururuna yenildiğim kadar

Eğer sorarsan yine seni sevdiğimi

Bu dünyadan başka bir dil bilmeyişimin

Çaresizliği ve acizliğiyle haykırıyorum ki

Seni cok seviyorum...

Sen de bilseydin gözlerimdeki yıldızların kayışını

Belki döner gelirdin bana

Ama azraille yapılmışsa bir sözleşme

Yıldızların düştüğü yerde bekleyeceğim..', 'Beni ürküten hayatın boşluğu değildi İçimdeki soğuk boşluğun kadar Hayatın koymuşluğuna yenilmedim Beynindeki gururuna yenildiğim kadar Eğer...', ARRAY['Türk Edebiyatı','Şiir','Şair Sefil']::text[], 8.5, '{"poet":"Şair Sefil","poet_slug":"sair-sefil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/amacim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlik Bağı', 'birlik-bagi-mehmet-akif-ersoy-2orwj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Müslümanlık nerde bizden geçmiş insanlık bile

Alem aldatmaksa maksat aldanan yok nafile

Kaç hakiki müslüman gördümse hep makberdedir

Müslümanlık bilmem ama galiba göklerdedir

Varsa şayet söyleyin bir parçık insafınız

Böyle kansızmıydı haşa kahraman eslafınız

Böyle düşmüşmüydü herkes ayrılık sevdasına

Benzeyip şirasesiz bir mushafın eczasına

Hiç görülmüşmüydü olsun kayd ı vahdet tarumar

Böyle olmuşmuydu millet can evinden rahnedar

Böyle açlıktan bogazlarmıydı kardeş kardeşi

Böyle adetmiydi bi perva yemek insan leşi

Irzımızdır çiğnenen evladımızdır doğranan

Hey sıkılmaz ağlamassan bari gülmekten utan

Kurt uzaklardan bakar dalgın görürmüş merkebi

Saldırırmış ansızın yaydan boşanmış ok gibi

Lakin aşk olsunki aldırmazda otllarmış eşşek

Sanki tavşanmış gelen yahud kılıksız köstebek

Kar sayarmış bir tutam fazla olsun yutmayı

Hasmı derken çullanırmış yutmadsan son lokmayı

Bir hakikattır bu bildiğin usluba sok

Halimiz merkeple kurdun aynı asla farkı yok

Burnumuzdan tuttu düşman biz boğaz kaynındayız

Bir bakın halamı hala ihriras ardındayız

Saygısızlık elverir bir parça olsun arlanın

Vakti çoktan geldi hem geçmektedir arlanmanın

Davranın haykırmadan nakus-u izmihlaliniz

Öyle bir buhrana sapmıştırki zira haliniz

Zevke dalmak şöyle dursun vaktiniz yok mateme

Davranın zira gülünç olduk aleme

Bekleşirken gökte yüzbinlerce ervah intikam

Yerde kalmış naşa benzer kavm için durmak haram

Kahraman ecdadınızdan sizde bir kan yokmudur

Yoksa istikbalinizden korkulur pek korkulur', 'Müslümanlık nerde bizden geçmiş insanlık bile Alem aldatmaksa maksat aldanan yok nafile Kaç hakiki müslüman gördümse hep makberdedir Müslüma...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/birlik-bagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçindeki Kelebek', 'i-cindeki-kelebek-levent-kizildag-kaolw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karar veremez günler, beyaz ve siyah arasında

Tanımı yapılmaz rengi seçilmez ama, 

En dikeyine yaşanır betimsiz duygular.

Anlamsız parıltılar geri kalan bir saat gibidir 

Bir türlü gelmez yarın, ulasamazsın

Yorgun ve tozlanmış gülüşleri indirsin raflardan.

Yine de nazlanmaktadır lakin, 

İçinde pırpır eden kelebek.

Direnmektedir  sana kendi geçmişine ve kanatlarına.

Ufukta bir çizgi halini gösteremiştir aşk, 

Ama içindeki kelebek razı değildir henüz, olacaklara.

İç geçirir, hayıflanır 

Uzun bir yolun başında ancak farkındadır

Mutluluk bir gülücüğün ardındadır.

04.01.2002', 'Karar veremez günler, beyaz ve siyah arasında Tanımı yapılmaz rengi seçilmez ama,  En dikeyine yaşanır betimsiz duygular. Anlamsız parıltıla...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/icindeki-kelebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUHAF', 'tuhaf-levent-kizildag-avtr3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine gozyaslarinla islak

Dizelerin

Icinin rengi vurmus siirlerine

Kara kapkara.

Bir garip olmussun yine bu aksam

O gozlerle bu siirler

Tuhaf cok tuhaf.

15.06.1979', 'Yine gozyaslarinla islak Dizelerin Icinin rengi vurmus siirlerine Kara kapkara. Bir garip olmussun yine bu aksam O gozlerle bu siirler Tuhaf...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tuhaf-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-levent-kizildag-d1s3e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aaa! 

Bu gün güneş tutulacakmış.

Eyy Tanrım

Bari bunu bırak.

Tutulmadık.

Bir güneşimiz kalmıştı.

06.02.1981', 'Aaa!  Bu gün güneş tutulacakmış. Eyy Tanrım Bari bunu bırak. Tutulmadık. Bir güneşimiz kalmıştı. 06.02.1981...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gunes-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-taskin-asan-czm16', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreklerimiz nasıl

Nasıl yakın ederse ırakları

Gözlerimiz de elbet

Kucaklayacak aydınlıkları

Güneş

Sevenleri basar bağrına

Unutma güzelim

Değil sıcaklığından kaçanları...

                  (14.11.2001/Güngören)', 'Yüreklerimiz nasıl Nasıl yakın ederse ırakları Gözlerimiz de elbet Kucaklayacak aydınlıkları Güneş Sevenleri basar bağrına Unutma güzelim De...', ARRAY['Türk Edebiyatı','Şiir','Taşkın Aşan']::text[], 8.5, '{"poet":"Taşkın Aşan","poet_slug":"taskin-asan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/unutma-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Biline', 'i-yi-biline-taskin-asan-jn61l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülüm

Biz düşüneceğiz

Onlar bizi yakacaklar

Bugün

Biz direneceğiz

Onlar bizi coplayacaklar

Yarın

Biz konuşacağız

Onlar bizi alkışlayacaklar

Birgün

Darağacı kurup meydanlara

Çocuklarımızı asamayacaklar! ..

       (31.10.1999/Güngören)', 'Gülüm Biz düşüneceğiz Onlar bizi yakacaklar Bugün Biz direneceğiz Onlar bizi coplayacaklar Yarın Biz konuşacağız Onlar bizi alkışlayacaklar ...', ARRAY['Türk Edebiyatı','Şiir','Taşkın Aşan']::text[], 8.5, '{"poet":"Taşkın Aşan","poet_slug":"taskin-asan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iyi-biline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin Ölüm', 'hos-geldin-olum-nevzat-celik-nxqed', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hoş geldin ölüm 

Buyur otur

Saklımız kalmadı

Dök eteklerinden taşları

Ben bir rüzgarım 

Özgürlük rüzgarı

Bir yürekten bir yüreğe

Taşırım umutları

Ben bir dağ seliyim

Yıkarım duvarları

Yükselir kentten

Çorba kokuları

Ben bir denizim

Hırçın dalgalı

Ölüm nedir bilmeden

Döverim kıyıları

Bütün dostlar uyanık

Şafağı karşılıyor

Yan hücre kapıyı çalıyor

Kalk gidelim sıradakini bekletmeyelim

                                 (şubat 1983)', 'Hoş geldin ölüm  Buyur otur Saklımız kalmadı Dök eteklerinden taşları Ben bir rüzgarım  Özgürlük rüzgarı Bir yürekten bir yüreğe Taşırım umu...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çelik']::text[], 8.5, '{"poet":"Nevzat Çelik","poet_slug":"nevzat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hos-geldin-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HOŞÇAKAL', 'hoscakal-cem-batu-nit98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey! Gecelerime 

bir şaytan gibi girip

Günün doğuşunu 

zamansızlığa teslim eden, 

Tutkularımın izdüşümü

Saygısız kadın...

Ey! Mehtabın şerefine kurulan 

rakı sofralarında, 

Masama meze, 

dudaklarıma şarkı olan, 

Acılarımın çığlığı

Melankolik kadın...

Ey! Arzularımın gölgesinden çıkıp, 

gözlerimde rahibe, 

Yatağımda yosma kesilen, 

Adı bende saklı

Esrarengiz kadın...

Ey! Böylesine 

sarhoş akşamlarda bile

Mutluluğa hasret

Alkolsüz düşlerime 

kahraman olan

Zalim kadın....

Ben şimdi gidiyorum; 

En az senin gittiğin kadar...

Sana, ağlamaklı kalemlerden 

Sırılsıklam dizeler bırakıyorum...

Sana çocuksu sevdalardan

Yetişkin acılar bırakıyorum...

Geçmişime ait ne varsa, 

Söküp yerlerinden, 

Üzeri toz tutmuş

anılar masasının

Üzerine bırakıyorum...

Sana ait ne varsa

Çekinmeden gel ve al...

Ben şimdi gidiyorum; 

En az senin gittiğin kadar...

Hoşçakal! ...', 'Ey! Gecelerime  bir şaytan gibi girip Günün doğuşunu  zamansızlığa teslim eden,  Tutkularımın izdüşümü Saygısız kadın... Ey! Mehtabın şerefi...', ARRAY['Türk Edebiyatı','Şiir','Cem Batu']::text[], 8.5, '{"poet":"Cem Batu","poet_slug":"cem-batu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hoscakal-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırpınır', 'cirpinir-necip-fazil-kisakurek-r6swi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinle, kulağını ver de mezara! 

Ölüler evlattan yana çırpınır.

Nesiller arası korkunç manzara; 

Domuz yavrulayan ana çırpınır.

Kalbten kazıdılar iman sırrını; 

Hergünün bugünden beter yarını.

Acı rüzgarlara vermiş bağrını

Türk bayrağı yana yana çırpınır.', 'Dinle, kulağını ver de mezara!  Ölüler evlattan yana çırpınır. Nesiller arası korkunç manzara;  Domuz yavrulayan ana çırpınır. Kalbten kazıd...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cirpinir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Ah', 'ah-nurten-altinok-lf631', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hoşgeldiniz 

                      





 



Kedi - ciğer  meselesi

Mundar değil

Gözlerim, 

Dudaklarında 

Asılı kaldı

Merdiven getireceğim...', 'Hoşgeldiniz                           Kedi - ciğer  meselesi Mundar değil Gözlerim,  Dudaklarında  Asılı kaldı Merdiven getireceğim......', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Gün Gelir', 'gun-gelir-nurten-altinok-0woqu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün gelir şairler de ölür

Öksüz kalır kâğıt kaleme

Duygular dizelere

Gün gelir şairler de ölür

Mezarı bir şiirdir anılar içinde', 'Gün gelir şairler de ölür Öksüz kalır kâğıt kaleme Duygular dizelere Gün gelir şairler de ölür Mezarı bir şiirdir anılar içinde...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gun-gelir-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Çözülebilsem', 'cozulebilsem-nurten-altinok-kvsgb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizi rahat koymazlar 

Her taraf kara diken

Gel kaçalım desen

Dünya ayaklarıma dolanmış 

Kördüğüm

Elense

Bir çözülebilsem...', 'Bizi rahat koymazlar  Her taraf kara diken Gel kaçalım desen Dünya ayaklarıma dolanmış  Kördüğüm Elense Bir çözülebilsem......', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cozulebilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarım Belli Değil', 'mezarim-belli-degil-nurten-altinok-j7t7v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ölürsem 

Saatlerin 00.00 da ölmeliyim

Ne dün olmalı

Ne bugün 

Ben ölürsem

Enginlerde ölmeliyim

Kimseler beni bulmamalı

Ne ağıt istiyorum

Ne gözyaşı

Bir kağıtta saklayın benli anıları

Kâğıtta şiir olmalı', 'Ben ölürsem  Saatlerin 00.00 da ölmeliyim Ne dün olmalı Ne bugün  Ben ölürsem Enginlerde ölmeliyim Kimseler beni bulmamalı Ne ağıt istiyorum...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mezarim-belli-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Öyle Öp', 'beni-oyle-op-nurten-altinok-ql9xs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bekle

Ay buluta girsin 

Ellerim avuçlarında 

Göğsünde başım

Nefesindeyim

Bekle

Ay buluta girsin

Beni öyle öp

Kimseler görmesin

Bulutların gözü kör...', 'Bekle Ay buluta girsin  Ellerim avuçlarında  Göğsünde başım Nefesindeyim Bekle Ay buluta girsin Beni öyle öp Kimseler görmesin Bulutların gö...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beni-oyle-op-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit', 'kibrit-nurten-altinok-lnl3v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir kibrit olacağım dünlerime

geçmişim çıradan gemi

avuçlarımı ısıtacağım inadına

gözlerimde papatyalar 

falların aç çığlıkları

ve yenibaştan 

ve sıfırdan

tuvale ilk pembe renk düşeceğim

ebem kuşağı gözlerim

aynaları ters yüz ettim...', 'bir kibrit olacağım dünlerime geçmişim çıradan gemi avuçlarımı ısıtacağım inadına gözlerimde papatyalar  falların aç çığlıkları ve yenibaşta...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kibrit-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '****Bir Yapabilsem', 'bir-yapabilsem-nurten-altinok-glkhq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir yapabilsem 

beynimi indiriversem yüreğime

önce seni unutacağım

tırnaklarımla kazıyacağım gölgeni 

tüm kokun sinmişleri

aynalar paramparça 

geceler

ışık seli akacak gözlerime

bir yapabilsem

ezberleyeceğim tüm küfürlerle

zehir zıkkım

seni yoğuracağım

mayasız hamur 

kabaramayacaksın

bir yapabilsem', 'bir yapabilsem  beynimi indiriversem yüreğime önce seni unutacağım tırnaklarımla kazıyacağım gölgeni  tüm kokun sinmişleri aynalar paramparç...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-yapabilsem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Sabah Olmuyor', 'sabah-olmuyor-nurten-altinok-p7y3u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sessiz gecelerin

Karanlık yalnızlığında

Özlem ebe olursa

Korkular

Köşe kapmaca 

İstediği kadar ötsün vakitsiz horozlar

Sabah olmuyor 

       Olmuyor işte

                 Olmuyor 

Nafile...', 'Sessiz gecelerin Karanlık yalnızlığında Özlem ebe olursa Korkular Köşe kapmaca  İstediği kadar ötsün vakitsiz horozlar Sabah olmuyor        ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sabah-olmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Yaşam Bu Olmalı', 'yasam-bu-olmali-nurten-altinok-ch4jf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep yarınların özlemiydi

Umutlar yarınlara odaklı

Tükettikte bir ömrü

Tüketemedik umutları

Hala yarım sevdaların burukluğu 

Gecelere isyan sil baştan

Beklenenlere susmadı çağrı

Susturamadık çığlıkları

Gönül yaşı baş yaşı değilmiş

Nice sonbaharlar geçirdi de saçlarımız

Yüreğimiz hala bir taze bahar dalı 

Boy attı budadıkça umutları

Yaşam bu olmalı…', 'Hep yarınların özlemiydi Umutlar yarınlara odaklı Tükettikte bir ömrü Tüketemedik umutları Hala yarım sevdaların burukluğu  Gecelere isyan s...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasam-bu-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Hadi Gidiyoruz', 'hadi-gidiyoruz-nurten-altinok-w1a7z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu suskunluk 

seni aldatmasın

sinsi bir deprem gibiyim 

n’olur beni kınama

bir gün

ansızın dayanacağım kapına

kaçmaya vaktin olmayacak

ne de 

yıkılan yanlarını toplamaya

seni çalmaya geldim

çaldıklarını almaya geldim

hadi gidiyoruz 

hadi kalk

hadi...', 'bu suskunluk  seni aldatmasın sinsi bir deprem gibiyim  n’olur beni kınama bir gün ansızın dayanacağım kapına kaçmaya vaktin olmayacak ne de...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hadi-gidiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik', 'platonik-sair-anakha-j6wvr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'o kadar güzel gizliyorsun ki

beni sevdiğini...

nerdeyse

beni 

bile 

kandıracaksın!', 'o kadar güzel gizliyorsun ki beni sevdiğini... nerdeyse beni  bile  kandıracaksın!...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/platonik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Deli Gönül', 'deli-gonul-nurten-altinok-jwby9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah be deli gönül 

Al beynimi de

Sürükle götür

Götür de 

Rahat edeyim', 'Ah be deli gönül  Al beynimi de Sürükle götür Götür de  Rahat edeyim...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deli-gonul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Bir Anlatabilsem', 'bir-anlatabilsem-nurten-altinok-yq0bk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adressiz yollara düştüm

Sesler sır kapılarının ardında 

Beynimde cevapsız sorular

İçimde bitmemiş acılar

Bir anlatabilsem 

Kurdu kuşu ağlatırdım 

Sen

Seni kurşuna dizerdin

Bir anlatabilsem...', 'Adressiz yollara düştüm Sesler sır kapılarının ardında  Beynimde cevapsız sorular İçimde bitmemiş acılar Bir anlatabilsem  Kurdu kuşu ağlatı...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-anlatabilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-sair-anakha-bmwzd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bana bir tek sen yardım edebilirsin...

gel gör ki

bir tek senden yardım isteyemem ben...', 'bana bir tek sen yardım edebilirsin... gel gör ki bir tek senden yardım isteyemem ben......', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ask-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeç', 'vazgec-nurten-altinok-sffs2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aygen Toruner’e

bir sessiz çığlık var

duyamazsın

bir yürek

bilemezsin

n’alet olsun böyle kadere

çekip gidemezsin

çok geç

kalabalık sessizliklere

vize verilmiyor

vazgeç

   yalnız değilsin', 'Aygen Toruner’e bir sessiz çığlık var duyamazsın bir yürek bilemezsin n’alet olsun böyle kadere çekip gidemezsin çok geç kalabalık sessizlik...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vazgec-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değdi', 'degdi-sair-anakha-f4ab6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne gözlerim değdi gözlerine, bir kez olsun, sekmeden geri...

ne ellerim değdi ellerine, sen çekmeden geri

soruyorum kendime ''değdi mi? '' diye ilk günden beri...

''DEĞDi! '' diyor her seferinde, içimdeki o diğer serseri...', 'ne gözlerim değdi gözlerine, bir kez olsun, sekmeden geri... ne ellerim değdi ellerine, sen çekmeden geri soruyorum kendime ''değdi mi? '' diy...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/degdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Gel Demedim mi', 'gel-demedim-mi-nurten-altinok-dps9j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gel  demedim mi

hüzünlere ben,

tek başıma da bilirim göğüs germesini

gözyaşlarım bilir akacak  menzili

geceler, 

nasıl kundakladığımı sessizliği

sor istersen kağıtlara

nasıl bilir kalemlerim

şiirlerin intihar ettiğini

                       

gel demedim mi

ayrılıklara ben,

tek başıma da bilirim kalkan olmayı

sensiz sokak sokak dolaşmayı İstanbul’u...

elbette bilirim,

bir simidi tek başıma yemeyi

kaldırımları tekmelemeyi,

kaderimdir niyetine...

gel demedim mi 

sevinçleri ben 

tek başıma da bilirim karşılamayı

türkülerim bilir,

        yanan mumlara

                 şerefe 

                        adak sunmayı

gel demedim mi

sensiz 

      nasıl

              yaşanır 

                       öğret

                            demedim mi

nasıl 

    nefes 

            alınır

                nasıl ölünür 

gel demedim mi

     gel de

        öğret

             demedim mi...', 'gel  demedim mi hüzünlere ben, tek başıma da bilirim göğüs germesini gözyaşlarım bilir akacak  menzili geceler,  nasıl kundakladığımı sessiz...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gel-demedim-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslanmadım', 'uslanmadim-sair-anakha-osju7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'teninin kıvrımlarında kaybettim yolumu her gece

ve gözlerinin boşluğunda unuttum kim olduğumu

sesinin yumuşaklığında uyudum...

nefesinin soğuğuyla uyandım sonra, bu ölüm uykusundan

gözlerinin karasıyla bozdum ölüm orucumu

gülüşüne bandım ekmeğimi...

dudaklarının ateşinde yandım sonra, kül oldum...

saçlarının rüzgarıyla savruldum dört bir yana, 

uslanmadım...', 'teninin kıvrımlarında kaybettim yolumu her gece ve gözlerinin boşluğunda unuttum kim olduğumu sesinin yumuşaklığında uyudum... nefesinin soğ...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uslanmadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-nurten-altinok-ej2g4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'alıp başımı kaçmalıyım bu şehirden

güneş nefesini tanımıyor

denizler gözlerini

bulutlar sesini

alıp başımı kaçmalıyım bu şehirden

rüzgarlar kokunu tanımıyor

toprak terini

zaman  hasretini

alıp başımı kaçmalıyım bu şehirden

nerdesin?', 'alıp başımı kaçmalıyım bu şehirden güneş nefesini tanımıyor denizler gözlerini bulutlar sesini alıp başımı kaçmalıyım bu şehirden rüzgarlar ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nerdesin-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vekil', 'vekil-nurten-altinok-9ix96', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ellerim günahkar

kırılası ellerim

ellerim isyankar

ellerim

ellerine vekil

nefesim günahkar

kesilesi nefesim

nefesim ateş kokar

nefesim

nefesine vekil

gözlerim günahkar

kör olası gözlerim

gözlerim aşk bakar

gözlerim

gözlerine vekil

bedenim günahkar

ateş topu bedenim

bedenim sen kokar

bedenim

bedenine vekil

yalnızlığı can evinden 

karanlığı şimşeğinden

mutluluğu hüzünden

silip süpürdü yüreğin

yüreğim

yüreğine vekil...', 'ellerim günahkar kırılası ellerim ellerim isyankar ellerim ellerine vekil nefesim günahkar kesilesi nefesim nefesim ateş kokar nefesim nefes...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/vekil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca', 'karinca-sair-anakha-a176n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen gittiğin gün, 

farkında olmadan

üzerlerine basıp

canlarını aldığım 

tüm karıncalar için 

ağladım...

bir de kendim için, 

senin yerine...

umarım bir gün 

ne demek istediğimi

anlarsın 

umarım bir gün 

sen de

ağlarsın....', 'sen gittiğin gün,  farkında olmadan üzerlerine basıp canlarını aldığım  tüm karıncalar için  ağladım... bir de kendim için,  senin yerine......', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/karinca-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sen İstanbul’u Bilmezsin', 'sen-i-stanbul-u-bilmezsin-nurten-altinok-xpg3p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen İstanbul’u bilmezsin a çocuk

Hiç yaşamadın ki burada dört mevsimi

Resimlerden tanırsın asma köprüleri

Camileri çeşmeleri

Şarkılardan

Çamlıca ’yı Kanlıca’ yı Boğaziçi’ni

İstanbul’da yağmur nasıl yağar sicim sicim

Nasıl sele dönüşür caddelerde

Nasıl çiğnenir ayaklar altında kar

Umut umut

Bilemezsin

Bilemezsin denizin sarı-yeşil, mavi-mor rengini

Hele bir de vurdu mu lodos

Azdı mı köpük köpük dalgalar

Tanıyamazsın martıların sesini

Sen Beyoğlu’nu bilmezsin a çocuk

Hiç yaşamadın ki burada dört mevsimi

Tarihi, vitrinlerinde sergiler gibidir O

Bir renk cümbüşüdür 

Bir insan seli, akar gider

Arka sokaklarda yaşananları gizlercesine

Sır perdesi

Örtünce cibinlik gibi karabasan gece yürekleri

Bir yerde birilerinin sızlar gözbebekleri

Yitirilmiş gençlik midir

Gelinlik midir 

O da bilmez ki

Kimse sordu mu acaba

İlk aşkı kimdi 

Ya da 

Yaşayabildi mi

Sen İstanbul’u bilmezsin a çocuk

Hiç yaşamadın ki burada dört mevsimi

Ayağında delik deşik ayakkabısı bir çocuk çorapsız

Sırtı donmuş tek gömlek kazaksız hırkasız

Kim bilir hangi han kapısında sabahladı kaç gece

Ya da hangi köprünün altında, rüzgarla koyun koyuna

Bilemez sorsan

Son yemeği hangi öğündü neydi kiminle 

Ve de en son sarılışı anasına ne zamandı şefkatle

Kimse sordu mu acaba ilk oyuncağı neydi

Tinerden önce

Ya da neydi aradığı 

Sen İstanbul’u bilmezsin a çocuk

Hiç yaşamadın ki burada dört mevsimi

Umutların nasıl bir gecede kondu ya döndüğünü

Ve bir sabahın seherinde nasıl yıkıldığını gözyaşlarıyla

Bilemezsin gökdelenlerde kimler yaşar ne yapar

Caddelerde bu koşturmaca niye nereye

Açılan pankartlarda ne yazar üniversiteli

Ne ister memuru işçisi emeklisi işsizi

Sen İstanbul’u bilmezsin çocuk

Hiç yaşamadın ki burada dört mevsimi

Bir büyük düştür İstanbul 

Bir büyük tiyatro sahnesi 

Taşı toprağı altın oldu mu bilemem ama

Umutlar çoğu kez ayaklar altında ezildi

Sen İstanbul’u bilmezsin a çocuk

Hiç yaşamadın ki burada dört mevsimi...

.', 'Sen İstanbul’u bilmezsin a çocuk Hiç yaşamadın ki burada dört mevsimi Resimlerden tanırsın asma köprüleri Camileri çeşmeleri Şarkılardan Çam...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/sen-istanbul-u-bilmezsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Almayayım', 'ben-almayayim-nurten-altinok-4x7p5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soğuk bir nefes midir ensemizde hissettiğimiz

Diken diken ürpermesi midir tenimizin

Geçse de yıllar benimseyemediğimiz

İçimizden atamadığımız bir korku mudur ölüm

Kopup gitmek midir bilinmeze

Karanlıkta yalnızlığın sonsuzluğumudur

Suskunluğumudur dillerin lal ötesi

Gözlerin kararması mıdır ışıkların donduğu

Hiç birine yılgın değil içimdeki korku

Toprak üstü severim çiçeği koklamayı

Gideceksem severim güllü dikenli yolları

Göreceksem yeşil ormanı

Nöbet beklemeyi değil selvi altı

Ağlayamaz ölüler 

Sevemez 

Sevilemez

Gülemez

Günah işleyemez boyunu aşan

Acıkınca bir duru suya ekmek bile çalamaz

Bir çalar saatleri yoktur 

Babah koşturmaya uyandıracak

Cebinde bir hapı ağrısını unutacak

Hesap kitap istemez 

Ay sonunu getirecek

Gecekonduları yıkılamaz 

Karakışın ayaz gecelerinde

Lodosları olamaz 

Bir kömür sobasının geri tepen isinde

Halay çekemezler 

Davul zurna eşliğinde

Oturup ağlayamazlar 

Yağmayan yağmura bereket niyetine

Ninniler söyleyemezler 

Sallanmayan beşiğe

Ve ağaçları ve böcekleri ve çiçekleri

Bulutları ayı güneşi kayan yıldızları

Seyredemezler 

Ufuk çizgisinde

Bırakın beni ağlayayım

Bırakın seveyim

Bırakın konuşayım

Yazayım, haykırayım

Ölüm bir huzur ise sunulan

Bize altın sinide

Bırakın beni ne olur

Bırakın

Ben almayayım...', 'Soğuk bir nefes midir ensemizde hissettiğimiz Diken diken ürpermesi midir tenimizin Geçse de yıllar benimseyemediğimiz İçimizden atamadığımı...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ben-almayayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utangaç', 'utangac-sair-anakha-xqc39', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne zaman baksam gözlerine, dünyayı görürüm

ve ne zaman baksam dünyaya, kimsesizliğimi

işte bu yüzden bakamam gözlerine sevgilim

yanlış anlama sakın, utangaç falan değilim

ne zaman dokunsam ellerine, martılar gelir aklıma

ve ne zaman bir martı görsem, uçup gitmesinden korkarım ellerinin

işte bu yüzden tutamam ellerini sevgilim

yanlış anlama sakın, utangaç falan değilim

ne zaman dokunsam saçlarına, ağlayasım gelir

ve ne zaman ağlasam, saçlarının kokusu, ezilmişliğim

işte bu yüzden dokunamam saçlarına sevgilim

yanlış anlama sakın, utangaç falan değilim

ne zaman ''kal'' desen bana, gidesim gelir

ve ne zaman gidesim gelse, sövesim gelir Yılmaz Güney''e

işte bu yüzden kalamam artık buralarda sevgilim

yanlış anlama sakın, utangaç falan değilim...', 'ne zaman baksam gözlerine, dünyayı görürüm ve ne zaman baksam dünyaya, kimsesizliğimi işte bu yüzden bakamam gözlerine sevgilim yanlış anlam...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/utangac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Arzu ve Ölüm', 'son-arzu-ve-olum-sair-anakha-28wi7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'son arzun nedir diye sorsaydın eğer

sakın tereddüt etme, derdim...

ya gel şimdi seviş benimle

ya bas tetiğe hiç düşünme...

teselli etme sakın beni

izin verme can çekişmeme 

ya hemen şimdi öldür beni

ya soyun, seviş benimle....

ölüm...

attığın kurşun öldüremezdi beni 

farketmeseydim ellerinin titrediğini

yatarken cansız bedenim yerde

düşüneceğim sonsuza kadar, 

mahkumum düşünmeye, 

bir yerde yanlış yaptım

ama nerde?', 'son arzun nedir diye sorsaydın eğer sakın tereddüt etme, derdim... ya gel şimdi seviş benimle ya bas tetiğe hiç düşünme... teselli etme sakı...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-arzu-ve-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendeyim', 'sendeyim-sair-anakha-ehk6a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'olurda 

dönerse dünya tersine, ve sen

unuturda tüm sevdiklerini

hatırlarsan beni...

''hani o kalbi kırık çocuk

cebinde 

yeni sahibini bekleyen

kimsesiz bebekler gibi

ürkek ve kararsız

hüzünlü ama bir o kadar da heyecanlı 

bir mektup

içinde

bir şiir

devrik hayatlardan kurulu''

hani olurda

düşerse yolun

mezarıma....

hala bıraktığın yerdeyim

sendeyim...', 'olurda  dönerse dünya tersine, ve sen unuturda tüm sevdiklerini hatırlarsan beni... ''hani o kalbi kırık çocuk cebinde  yeni sahibini bekleye...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sendeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tabiri Caizse', 'tabiri-caizse-sair-anakha-nsvhv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hep bahstmek istedim senden 

mahalledeki çocuklara 

bahsedemedim...

hep anlatmak istedim seni

en yakın dostlarıma

anlatamadım...

hep örnek vermek istedim seni

edebiyat derslerinde

veremedim...

belki de ben seni

sırf bu yüzden sevdim

çünkü

hiçbir zaman 

caiz olamadı tabirin...', 'hep bahstmek istedim senden  mahalledeki çocuklara  bahsedemedim... hep anlatmak istedim seni en yakın dostlarıma anlatamadım... hep örnek v...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tabiri-caizse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateist', 'ateist-sair-anakha-mmbfl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ona değil bana inan bebeğim

ne kadar umrunda isen onun, söz ben sana

iki katını veririm...

ona değil bana güven bebeğim

korkuyorsam şerefsizim

nelere katlanabiliyorsa o senin için, söz ben sana

iki katını veririm

milyonlarca seveni var onun 

benimse bir kırık kalbim

kıskanıyorsam şerefsizim

umrumda bile değil hiçbirisi yeter ki sen, 

ona değil bana inan bebeğim...

ondan değil benden yardım iste bebeğim

ne kadar vazgeçebiliyorsa o kendinden, söz ben sana

iki katını veririm

onunla değil biraz da benimle ilgilen bebeğim

ne kadar ağlıyorsa geceleri o senin için, söz ben sana 

iki katını veririm

hani oyunlar oynardın ya bebeğim

mahalledeki çocuklarla

önce kazanacakmış gibi yapıp da

kaybederdin ya hani bilerek

dönerlerdi evlerine sevinçli, gülerek

n''olur bi kez de benim için kaybet bebeğim

çünkü tüm kaybedenler gibi 

ben seni hep karşılıksız sevdim

ne zaman gönderdiysem şu kırık kalbimi sana

geri getirdiler evde yokmuşsun

işte bu sana son mektubum bebeğim

artık verdiğim sözleri ödemeliyim

korkuyorsam şerefsizim

ne kadar öldüyse o senin uğrunda, bak ben sana

iki katını veriyorum....', 'ona değil bana inan bebeğim ne kadar umrunda isen onun, söz ben sana iki katını veririm... ona değil bana güven bebeğim korkuyorsam şerefsiz...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ateist-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Oyna', 'buyuk-oyna-sair-anakha-su18o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'acele et! 

kaçırma, 

mutluluk vadisine kalkan

son treni...

hiçbir şey alma sakın

yanına giderken

umutlarından başka

ağırlık yapar anılar

bırak geçmişini ardında 

bırak acı veren tüm yaraları...

şimdi kaldır kafanı ve koşmaya başla! 

asla bir hedef seçme kendine

ve asla bakma bastığın yerlere...

güneşten rahatsız olursan dik gözlerini onun üstüne

göster patronun kim olduğunu! 

soğuk bir rüzgarsa sana meydan okuyan

çıkar tüm elbiselerini ve ciğerlerine çek rüzgarı

eğer seni ıslatırsa

dilini çıkarıp nanik yap yağmura

eğer seni korkutursa

berbat şarkılar söyle bağırarak, o en berbat sesinle

gökgürültüsüne...

ve nihayet anladığın zaman

dünyanın sana blöf yaptığını

büyük oyna 

eğer mutluluksa istediğin

hayat denen bu garip oyunda', 'acele et!  kaçırma,  mutluluk vadisine kalkan son treni... hiçbir şey alma sakın yanına giderken umutlarından başka ağırlık yapar anılar bır...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/buyuk-oyna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişmek Ayıp Değil', 'sevismek-ayip-degil-umit-yasar-oguzcan-h33vc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-1-

Ne katı yüreklisiniz, aşkolsun

İnim inim inletiyorsunuz beni

Kendinizi dirhem dirhem satıyorsunuz

Oysa verdiğiniz kederler yetmez mi? 

Şunu şurasında kaç paralık ömrümüz var

Ne kadar zavallıyız bir düşünün

Belli mi sabaha sağ çıkacağımız

Kim bilir ne getireceğini doğan günün

Gecelerce sevişmek var gecelerde

Uzun etmeyin işte, gelin, gitmeyin

Birlikte çıkalım aydınlıklara

Gecenin ortasında beni bekletmeyin

-2-

Sizinle yatalım isterseniz çimenlere

Gelin, başınızı şöyle göğsüme dayayın

Bakın yüreğim nasıl çarpıyor

Sizi ne kadar sevdiğimi anlayın

Sizinle yatalım isterseniz yataklara

Şöyle bir güzel sevişelim o biçim

Güzel olalım, mutlu olalım, ne dersiniz

Biraz konuşalım, biraz öpüşelim

Sizinle yatalım isterseniz topraklara

Ölelim, dünyayı unutalım

Gelin, sarılalım birbirimize

Aşkı her şeyden üstün tutalım

-3-

Sevişmek var, başka şey düşünmeyin

Boş verin kavgalara, tartışmalara

Şöyle bir nefes alın adamakıllı

Vurun kendinizi çılgın yaşamalara

Gelin, tenhalara gidelim, tenhalara

Saçlarımdan öpün, dudaklarımdan öpün

Öylesine yaşayalım ki utansın

Ölüm kapımıza geldiği gün

Sevişmeden güzel, sevmeden yüce

Ne bulduk ki bu dünyada, söyleyin

Açın yüreğinizi dostluklara, sevgilere

Sevişelim durmadan, aptallık etmeyin

-4-

Buraya yatsanız daha iyi bence

Yanıma şöyle yanıbaşıma

Aşka bırakıverin kendinizi

Ağlamayın, üzülmeyin ama

Şunlar dudaklarınız dolgun, biçimli

Şunlar elleriniz işte alımlı, ince

Bir bir öpmeliyim her yerinizi

Her yerinizi vakti gelince

Çıkarıp atın üstünüzde ne varsa

Çıplaklığınızı güzelliğinizle sarın

Şu küpeleri de, şu yüzüğü de

Onu da çıkarın, onu da çıkarın

-5-

Tutumunuza bayılıyorum bana karşı

Sevginizi pek güzel saklıyorsunuz

Bir bakıyorum anlayışlısınız, incesiniz

Sonra sırtımdan bıçaklıyorsunuz

Kızmıyorum, üstelik hoşuma gidiyor

Değişikliği severim, bilirsiniz

İstiyorum kendinizi verirken

Hep böyle canımı acıtsın elleriniz

Sigaranızı avucumda söndürün dilerseniz

Bırakın tenim yanabildiği kadar yansın

Yeter ki doyalım artık birbirimize

Dudağımda diş izleriniz kalsın', '-1- Ne katı yüreklisiniz, aşkolsun İnim inim inletiyorsunuz beni Kendinizi dirhem dirhem satıyorsunuz Oysa verdiğiniz kederler yetmez mi?  Ş...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/sevismek-ayip-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Bitti', 'yalan-bitti-umit-yasar-oguzcan-vldu7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün gelir yaşanmaya değecek zaman biter

İnsanda güç tükenir, şeref biter, şan biter

Sesler duyulmaz olur, solar renkler ansızın

Yıllardır yüreğine hayat veren kan biter

Yıkılır inançları, umutları tükenir

Sevdiği, sevildiği kişiler bir an biter

Hala bir boş bedeni taşır da ayakları

Ömür boyu üstüne titrediği can biter

Yuvarlanmaya başlar dünyası bir boşlukta

Yalnız Allah''ı değil, insanda insan biter

Bütün bunları yaşar, sonunda anlar kişi

Ölüm o ki: İnsanın içinde yalan biter', 'Gün gelir yaşanmaya değecek zaman biter İnsanda güç tükenir, şeref biter, şan biter Sesler duyulmaz olur, solar renkler ansızın Yıllardır yü...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalan-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-sair-anakha-3sxrg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kalmanı istesem yanımda 

bu son gecemde istanbulda

koyupta başımı usulca omzuna 

uyumak istesem son bir defa 

ve bir daha uyanmamak....

kalmamı istesen

bu son gecemde istanbulda

korkuyorum desen

üşüyorum desen

tutsan kolumdan bırakmasan

allahımı şaşırtsan

sonra bi fırt çeksen dudaklarımdan

sonra bi fırt daha 

sonra bi fırt daha 

bi masalda burda bitmese...', 'kalmanı istesem yanımda  bu son gecemde istanbulda koyupta başımı usulca omzuna  uyumak istesem son bir defa  ve bir daha uyanmamak.... kalm...', ARRAY['Türk Edebiyatı','Şiir','Şair Anakha']::text[], 8.5, '{"poet":"Şair Anakha","poet_slug":"sair-anakha","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/masal-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bir dakikada kaç rüya görebilirsin', 'bir-dakikada-kac-ruya-gorebilirsin-cevahir-evren-aqua0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yıkıl dünya o sarınıp da bedenime vazgeçemediğin yere yıkıl

uyan gün sabahı özledi gözlerim

derinlerde kayboluyorum toz bulutu alıp götürüyor

içinden çıkılması ansızlık

bir

  iki

     üç...

sonsuza kadar sayıyorum yine baştan başlıyorum

bir dakikada kac rüya görebilirsin', 'yıkıl dünya o sarınıp da bedenime vazgeçemediğin yere yıkıl uyan gün sabahı özledi gözlerim derinlerde kayboluyorum toz bulutu alıp götürüyo...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-dakikada-kac-ruya-gorebilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'aşk', 'ask-cevahir-evren-6zdv4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bana mı sordunuz hakim bey

bilmiyorum...

geceleri var sanıyorum da 

ondandır

yalan da söylemiyorum

dogrusunu isterseniz

ne söylediğimi hatırlamıyorum

tanıklarım mı 

tanık gerekli öyle mi

bunu hiç düşünmemiştim

belki de siz haklısınız

bakın efendim o sizin bahsettiğiniz şeyin ne olduğunu bilmiyorum 

evet ona benzer duygular oluyor ama

sizin dediğiniz duygular mı değil mi

onu bilmiyorum

aşk diyorsunuz ama

belki de haklısınız aşk

hayır 

   hayır

bunun bir aşk olduğunu sanmıyorum

ya da neyin aşk olduğunu bilmediğimdendir

daha doğrusu 

yalvarırım hakim bey 

bana bu cezayı vermeyin

ölmemi isteyemezsiniz herhalde

hayat mı

sevgi mi

anne mi baba mı

anlamıyorum hakim bey 

daha fazla dayanamayacağım 

şimdi yalnızca uyumak istiyorum

yalnızca uyumak', 'bana mı sordunuz hakim bey bilmiyorum... geceleri var sanıyorum da  ondandır yalan da söylemiyorum dogrusunu isterseniz ne söylediğimi hatır...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ask-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece nemi', 'gece-nemi-sair-eylul-ak39f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gecemide bir tek sana ayırdım yine

Tek tek düşündüm senden arta kalanları

Silinmek bilmeyen bir halin vardı

Düşlerimde kalan...

Hani o kapkara gözlerin vardı, 

İçinde ırmaklar taşıran.

Birde simsiyah saçların, 

Geceleri kıskandıran.

Unutamadığım birde yüreğin vardı.

Sözlere sığmayacak kadar büyük, 

Sahip olamayacagım kadar uzak.

Ne benim diyebildim, 

Ne de bir başkasının diyebilecek kadar cesur olabildim.

Bana kalp atışım kadar yakınken, 

Bir yıldız kadar uzaktın.

Kalbimin umut yeşermeyen bahçelerinde, 

Büyüttüm hep seni...

Birgün yeşerttiğim çiçegi, 

Ellerimle sökeceğimi bile bile...

Biliyorum ki ellerimi gökyüzüne açıp seni dilesem, 

Payıma düşen koskoca bir yalnızlık olur.

Bu gece de ben yokluğunda solan, 

Çiçekleri topluyorum bir bir..

Kimi zaman bir gözyaşı, 

Kimi zaman masum bir bakış, 

Düşen avuçlarıma...', 'Bu gecemide bir tek sana ayırdım yine Tek tek düşündüm senden arta kalanları Silinmek bilmeyen bir halin vardı Düşlerimde kalan... Hani o ka...', ARRAY['Türk Edebiyatı','Şiir','Şair Eylül']::text[], 8.5, '{"poet":"Şair Eylül","poet_slug":"sair-eylul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gece-nemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AĞLAYACAKSIN', 'aglayacaksin-sukru-soyarslan-4yjnn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'AĞLAYACAKSIN

Dönüpte bakınca, bir an maziye

Kırdığın kalbime, gönder taziye! 

Bilemedim kıymetin, eyvah diye

Döküp gözyaşların..Ağlayacaksın

Aşkın kalpte saklı, görünmez derin

Yüreğim yanıyor, ellerim serin

Bu perişan adam benim eserim

Deyip hıçkırarak, Ağlayacaksın

Izdıraptan gayri, ne verdin bana? 

Sen’i seven Ben’ken..gittin yabana

İçip hicran zehrini, kana kana

Geçmişe vah! edip..Ağlayacaksın

Benim gibi seven, nerde bulunur? 

Sevgimin günahı, Sen’den sorulur

Bir gün minarede, SELAA duyulur

Aşkım ölmüş deyip..Ağlayacaksın

Değer vermedin, bakmadın yaşıma

Bir demet gül, koyacaksın başıma..

Affet! ..deyip, sarılarak taşıma

Fatiha okuyup..AĞLAYACAKSIN!', 'AĞLAYACAKSIN Dönüpte bakınca, bir an maziye Kırdığın kalbime, gönder taziye!  Bilemedim kıymetin, eyvah diye Döküp gözyaşların..Ağlayacaksın...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aglayacaksin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VATANIM', 'vatanim-sukru-soyarslan-v3okt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'VATANIM

Her yeri şehit yatanım

Kanıyla oldu vatanım

Sana; kalbimdir atanım

Sen; ne güzelsin VATANIM

Kurban olam toprağına

Sarı- yeşil yaprağına

Ay-yıldızlı bayrağına 

Sen; ne güzelsin VATANIM

Dağda açan çiçeğiyle

Karıncası, böceğiyle

Geçmişi, geleceğiyle

Sen; ne güzelsin VATANIM

Dört mevsim gönlümde bahar

Güneşim var, denizim var

Ömrümce kalsın payidar

Sen; ne güzelsin VATANIM

Kimler gelmiş, kimler geçmiş? 

Buz gibi suyundan içmiş

Yurt olarak Seni seçmiş

Sen; ne güzelsin VATANIM

Semadan inerek hilal

Eş olmuştur; yıldızla-al

Bayrağım sen, hep böyle kal

Sen; ne güzelsin VATANIM

Her adımda bir evliya

Doludur her yer Enbiya..

Seni, değişmem dünyaya

Sen; ne güzelsin VATANIM

Kubbende okunur ezan

Her köşesinde bir ozan

Seni bana, Hakk’tır yazan

Sen; ne güzelsin VATANIM

Gel! ..der, çağırır Mevlana

Hizmet edelim Kur’an’a

Rabbim! Eriştir imana

Sen; ne güzelsin VATANIM

Yunus-Emre, Hacı-Bektaş

Alevi-Sünni..hep kardaş

Türk’ü-Kürd’ü olsun sırdaş

Sen; ne güzelsin VATANIM

Sana, kafir gözün dikmiş

Hazırız; yediden-yetmiş

Öğrensinler..Türk’ler kimmiş? 

Sen; ne güzelsin VATANIM

Çoluk-çocuk; Ana-hanım

Helal diyor.. O’na kanım

Sana; fedadır bu canım

Sen; ne güzelsin VATANIM

Kansın; damarda atanım

Cansın; bedende yatanım

Ellere peşkeş çektirmem

NAMUSUMSUN SEN, VATANIM', 'VATANIM Her yeri şehit yatanım Kanıyla oldu vatanım Sana; kalbimdir atanım Sen; ne güzelsin VATANIM Kurban olam toprağına Sarı- yeşil yaprağ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/vatanim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTTUM O''NU! !', 'unuttum-o-nu-sukru-soyarslan-n6zh6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'UNUTTUM ONU

Koskoca bir mâzi dururken arkanda

Nasıl dersin ben artık unuttum onu

Her gününde gözyaşı varken sevdânda

Nasıl dersin ben artık unuttum onu

Her dâim canlı yaşıyorken hayâlin

Sevmedim dersen boynunadır vebâlim

Hesabı sorulacak aşkımın, zâlim

Nasıl dersin ben artık unuttum onu

Her an ayrılmam diye yemin ederken

Bir tek sevdiceğim var, yalnız SEN derken

Dudağım dudağını öpüp inlerken

Nasıl dersin ben artık unuttum onu', 'UNUTTUM ONU Koskoca bir mâzi dururken arkanda Nasıl dersin ben artık unuttum onu Her gününde gözyaşı varken sevdânda Nasıl dersin ben artık ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unuttum-o-nu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Yağmuru', 'nisan-yagmuru-murat-solmaz-jd1d9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakmaya kıyamadığım kara gözlerin

Nisan yağmuru olup

Yağarsa yanaklarına ellerinden sımsıkıtutan 

Ben olurum elbet', 'Bakmaya kıyamadığım kara gözlerin Nisan yağmuru olup Yağarsa yanaklarına ellerinden sımsıkıtutan  Ben olurum elbet...', ARRAY['Türk Edebiyatı','Şiir','Murat Solmaz']::text[], 8.5, '{"poet":"Murat Solmaz","poet_slug":"murat-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nisan-yagmuru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız', 'adsiz-ozan-emre-baykara-k2kbp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlık duvarlarda canlandırdım, 

Puslu bakışlarını! 

Sessizliği gözlerinde seslendirdim! 

Geceleyin gökyüzüne ormanlar çizdim! 

Çizdiğim ormanlarda kayboldum! 

Hasret topraklarında büyüttüm umutlatrı! 

Yüreğimin bir köşesine, 

Özlemlerin resmini çizdim! ..

Sana isimler aradım ıssız sokaklarda! 

ADSIZ Kaldım! .....

(Zulam''a)', 'Karanlık duvarlarda canlandırdım,  Puslu bakışlarını!  Sessizliği gözlerinde seslendirdim!  Geceleyin gökyüzüne ormanlar çizdim!  Çizdiğim o...', ARRAY['Türk Edebiyatı','Şiir','Ozan Emre Baykara']::text[], 8.5, '{"poet":"Ozan Emre Baykara","poet_slug":"ozan-emre-baykara","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adsiz-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Gemisi', 'hasret-gemisi-ozan-emre-baykara-9pz47', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gece hasret yüklü gemiler kalkar, 

Yüreğimin limanından! 

Kaptanı; Yalnızlıktır! 

Tayfası; Hüzün! 

Rotası belli olmayan

Karanlık şehirlere doğru, 

Ağır ağır yol alır!', 'Her gece hasret yüklü gemiler kalkar,  Yüreğimin limanından!  Kaptanı; Yalnızlıktır!  Tayfası; Hüzün!  Rotası belli olmayan Karanlık şehirle...', ARRAY['Türk Edebiyatı','Şiir','Ozan Emre Baykara']::text[], 8.5, '{"poet":"Ozan Emre Baykara","poet_slug":"ozan-emre-baykara","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hasret-gemisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayacaksın?', 'anlayacaksin-ozan-emre-baykara-stjdl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdayı anlamak, 

Bir yaşam harcamaktır! 

Harcayacaksın! ..

Bir gün anlatmaya bakacaksın, 

Gözlerimi kapayacağım, 

ANLAYACAKSIN! ...', 'Sevdayı anlamak,  Bir yaşam harcamaktır!  Harcayacaksın! .. Bir gün anlatmaya bakacaksın,  Gözlerimi kapayacağım,  ANLAYACAKSIN! ......', ARRAY['Türk Edebiyatı','Şiir','Ozan Emre Baykara']::text[], 8.5, '{"poet":"Ozan Emre Baykara","poet_slug":"ozan-emre-baykara","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlayacaksin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim', 'seni-sevdim-ozan-emre-baykara-9aeus', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın bütün izlerini, 

Gecenin karanlığına gömdüm! 

Gözlerinde körelttim olumsuzlukları! 

Sessizliği çığlıklarla susturdum! 

Beyazında aklandım sevdanın! 

Mavi Mavi Sevdim Seni, 

İçim Kan Ağlayarak! ...', 'Yalnızlığın bütün izlerini,  Gecenin karanlığına gömdüm!  Gözlerinde körelttim olumsuzlukları!  Sessizliği çığlıklarla susturdum!  Beyazında...', ARRAY['Türk Edebiyatı','Şiir','Ozan Emre Baykara']::text[], 8.5, '{"poet":"Ozan Emre Baykara","poet_slug":"ozan-emre-baykara","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seni-sevdim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurulmuşum!', 'vurulmusum-ozan-emre-baykara-bxs6z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vurulmuşum! 

Ellerim kelepçeli, 

Ve içimde sensizlik korkusu! 

Bir yanımda mavzer, 

Ötekinde umut pınarı! 

Yürek cehennem narı, 

Çağlayan kan pınarı gözlerim, 

Dudaklarımda tutsak sözler! ..

Otuz üç kurşun izi yüzümde, 

Otuz üç ihanet tablosu! 

Yerlerdeyim, serilmişim! 

Titrek bakışlar altında, 

Seni, yalnız seni beklemişim! ....

Vurulmuşum! 

Kan kokulu sokaklarda, 

Zemheri ayazında, 

14 Şubat akşamında! ..

Karşımda hayalin var, 

Ve de ismin dudaklarımda! 

Biliyorum bu son veda! 

Türkülerde adım olacak, 

Sayfalarda yerim! 

Son nefeste, son arzumsun benim! ....

Yerlerdeyim, serilmişim! 

Titrek bakışlar altında, 

Seni, yalnız seni beklemişim! ...

(Zulam''a)', 'Vurulmuşum!  Ellerim kelepçeli,  Ve içimde sensizlik korkusu!  Bir yanımda mavzer,  Ötekinde umut pınarı!  Yürek cehennem narı,  Çağlayan ka...', ARRAY['Türk Edebiyatı','Şiir','Ozan Emre Baykara']::text[], 8.5, '{"poet":"Ozan Emre Baykara","poet_slug":"ozan-emre-baykara","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/vurulmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAT BU', 'hayat-bu-atanur-yildiz-50au6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat bu; 

ne çok karmaşıktır

bizim sandığımız gibi

ne de çok basit.

küçük bir ayrıntıda saklıdır o

anlayabilene...

Hayat bu; 

ne sevinçlerle doludur büsbütün

ne de mutsuzluklarla.

hayatta her şeye yer vardır ya

hayatı hayat yapan da budur işte...

Hayat bu; 

gelip geçiyor işte

zaman su gibi akıyor.

her şey aslına dönüyor.

gidenler geri gelmiyor.

hani evrenin biricik sırrıdır belki de bu; 

sadece, sadece ölümün çaresi yok şimdilik...

Dr.Atanur Yıldız

(29 Ağustos 2001, Derince-İzmit, Saat: 11.30)', 'Hayat bu;  ne çok karmaşıktır bizim sandığımız gibi ne de çok basit. küçük bir ayrıntıda saklıdır o anlayabilene... Hayat bu;  ne sevinçlerl...', ARRAY['Türk Edebiyatı','Şiir','Atanur Yıldız']::text[], 8.5, '{"poet":"Atanur Yıldız","poet_slug":"atanur-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayat-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmak', 'seni-unutmak-abduldeyyan-duru-2i2uc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiğim! Sevgi nedir bilirmisin? 

Ne olur biliyorum deme bana

Bakma öyle, gözlerin anlamsız olmasın.

Biliyorum, sen sevemezsin benim kadar

Anladım artık seni sevmemeliyim

Ve şimdi ayrılık vakti geldi

Kalbimde ince bir sızı var

Derinlerde çok derinlerde

Bilemezsin ne kadar acı verdiğini

Geceleri uyuyamadığımı bilemezsin

Bilseydin ne değişirdi sanki

Sevebilir miydin beni seni sevdiğim kadar? 

Çiçeklerde koklayabilir miydin beni? 

Rüzgarlarda sesimi duyabilir miydin? 

Yanan ateşe bakıp, 

Kalbime benzediğini görebilir miydin? 

Oysa ben kokluyorum, duyuyorum, görüyorum.

İşte sevdiğim ben

Seversem böyle severim

Fuzuli değilim ki 

Aşkının acısından zevk alayım

Ferhat değilim ki 

Aşılmazları aşıp sana geleyim

Yusuf değilim ki

Seni kendime meftun edeyim

Kabul etsen de etmesen de

Ben böyleyim

Ve seni böyle sevdim

Biliyorum unutmak zor olacak

Ama sevmek daha zor

Ve daha da zoru

Senden bir başkasını sevmek

İnan bana bunlar doğru

Söylediğim tek yalan

İstediğim tek gerçek

Seni Unutmak

(14.01.1994-İstanbul)', 'Sevdiğim! Sevgi nedir bilirmisin?  Ne olur biliyorum deme bana Bakma öyle, gözlerin anlamsız olmasın. Biliyorum, sen sevemezsin benim kadar ...', ARRAY['Türk Edebiyatı','Şiir','Abduldeyyan Duru']::text[], 8.5, '{"poet":"Abduldeyyan Duru","poet_slug":"abduldeyyan-duru","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/seni-unutmak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nefes Karanlık', 'bir-nefes-karanlik-orhun-basat-it0yk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece bitmek üzere, 

rüzgarın kırık kapılara bıraktığı notaları topladım, 

bunlarla günün birinde bir şarkı yazabilirim sana..

Bu gece, bütün resimler silindi gözlerimden, 

kurt ulumalarında, geceyi seninle adımladım..

İsmini yazdım camlara,  tırnaklarımla, 

sigaranın külüne gömdüm doğan güneşi, 

bir nefes çektim çekebildiğim kadar, 

İçimin karanlığına kahroldu güneş, 

yıldızlar, yıldız olduklarından utandılar...', 'Gece bitmek üzere,  rüzgarın kırık kapılara bıraktığı notaları topladım,  bunlarla günün birinde bir şarkı yazabilirim sana.. Bu gece, bütün...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-nefes-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANA DEĞER VERMESEYDİM', 'sana-deger-vermeseydi-m-ramazan-okyay-1u2xw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana değer vermeseydim eğer

Yıldızlara seni anlatırmıydım

Hiç çıkmayasın diye kalbimden

Kalın zincirlerle  bağlarmıydım

Sana değer vermeseydim eğer

Adına şiirler yazarmıydım

Heran içimde hissedermiydim

Geceleri seni düşünerek uyurmuydum

Şu şiiri bile yazarken seninleyim

Daha nekadar zaman geçtiki aradan

Seni delice ölesiye özlemişim

Değer vermeseydim yaşarmıydım bunları

En basiti sana GÜLÜM dermiydim

Güllerin en güzeli diye seni seçermiydim

Severmiydim seni böylesine; severmiydim

Sana değer vermeseydim', 'Sana değer vermeseydim eğer Yıldızlara seni anlatırmıydım Hiç çıkmayasın diye kalbimden Kalın zincirlerle  bağlarmıydım Sana değer vermeseyd...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Okyay']::text[], 8.5, '{"poet":"Ramazan Okyay","poet_slug":"ramazan-okyay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-deger-vermeseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünmek Özlemek Sevmek', 'dusunmek-ozlemek-sevmek-ramazan-okyay-re94o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Negüzeldir bilirmisin seni düşünmek

Günün ilk ışıklarıyla açıp gözlerimi

Herşeyden önce ilk seni düşünmek

İlk seni aklıma düşürmek

Seni gözlerimde canlandırmak

Sevinç heyecan ve; 

Sonsuz mutlulukla dolu yüreğimle

Seni ilk görüşümü

Sana sıkıca sarılıp öpüşümü düşünmek

Negüzeldir bilirmsin seni özlemek

Yüzüne bakmayı sana dokunmayı

Seni, sıcaklıgını hissetmeyi

Güzel kokunu teninde koklamayı

Dudaklarının tadını tatmayı

Sarmaşdolaş gezip tozmayı

Biryerlerde oturup elini tutmayı

Seninle konuşup sohbet etmeyi özlemek

Negüzeldir bilirmisin seni sevmek

Ruhumun derinliklerinde seni barındırmak

Yüreğimde sevgimle sevgini kucaklaştırmak

Seninde beni sevdiğini bilerek sevmek

Herşeye ama herşeye rağmen seni sevmek

17.01.2002  bu sana okumak istediğim son yazdığım 

şiirimdi.bunu sana okumak, seni ne kadar çok sevdiğimi

söylemek yerine ayrılığımızı konuştuk.

seni çok sevdim herzamanda sevicem.

hoşçakal gülüm', 'Negüzeldir bilirmisin seni düşünmek Günün ilk ışıklarıyla açıp gözlerimi Herşeyden önce ilk seni düşünmek İlk seni aklıma düşürmek Seni gözl...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Okyay']::text[], 8.5, '{"poet":"Ramazan Okyay","poet_slug":"ramazan-okyay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dusunmek-ozlemek-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zenginlik', 'zenginlik-sabit-i-nce-kzsr8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akıl en büyük zenginlik, 

                                   Kıymetini bilirsen sen.

                                   Ne kötüdür bilgisizlik, 

                                   Bilmediğin bilir isen.

  

                                  dep büyük mirasındır, 

                                  Bırakıp gidebilirsen.

                                  Sevgi senin parçandır, 

                                  Koparıp verebilirsen.

                                  İlim maldan hayırlıdır, 

                                  Arayıp bulabilirsen.

                                  İlim sana muhafızdır, 

                                  Bilgiyi sevebilirsen.

                                  Mal vermekle azalır, 

                                  Kıyıp da verebilirsen.

                                  İlim durmadan çoğalır, 

                                  Karını bilebilirsen.

                                  Mal yenilir, insan biter, 

                                  Farkında olabilirsen.

                                  İNCE dediklerin yeter, 

                                  Faydalı olabilirsen.

                                17.8.1996-Kayseri', 'Akıl en büyük zenginlik,                                     Kıymetini bilirsen sen.                                    Ne kötüdür bilgisizl...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zenginlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUNUS KARACA', 'yunus-karaca-sabit-i-nce-8gdg7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Değerli saz üstadı Yunus Karaca''ya-

Sanki Yunus''un bir misli, 

Nevşehirli, Türkmen asli.

Hoş bakişli gül nefesli, 

Sarıyor Yunus Karaca.

Beş Ocak da Ankara da, 

Gözü yok ikbal, parada.

Acısı var her yarada, 

Kanıyor Yunus Karaca.

Saz çalıp, türkü söylüyor

Gönlünü dostla eğliyor, 

Kalbini hakka bağlıyor, 

Yanıyor Yunus Karaca.

Dost meclisinde pervane, 

Hak kapısında divane.

Erce geliyor meydane, 

Yarıyor Yunus Karaca.

Dağlar O''na engin gelir, 

Dost kadrin kıymetin bilir, 

Sarraf olur altun alır, 

Biliyor Yunus Karaca.

İnce dünya boş bilirsen, 

Canın verir dost olursan, 

Kapısı açık varırsan, 

Tanıyor Yunus Karaca.

SABİT İNCE  Ankara yolunda', '-Değerli saz üstadı Yunus Karaca''ya- Sanki Yunus''un bir misli,  Nevşehirli, Türkmen asli. Hoş bakişli gül nefesli,  Sarıyor Yunus Karaca. Be...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yunus-karaca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUH OLSUN..', 'yuh-olsun-sabit-i-nce-9puf5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gördüğün insan sanma, 

                                    Tatlı sözlere aldanma.

                                     Alış verişine kanma, 

                                  Kanarsan, yuh olsun sana.

                                    Canım cicim dese bile, 

                                   Kalbinde vardır bir hile.

                                      Hileyi getirir şere, 

                                 Görmezsen yuh olsun sana.

                                 Masumane boyun büker, 

                                     Ocağına incir diker.

                                     Açarsan dişini söker, 

                                  Bilmezsen yuh olsun sana.

                                     Kime yaran olur isen, 

                                    Onunla yola gidersen.

                                   Eğer bir lokma yer isen, 

                                  Yutarsan yuh olsun sana.

                                 Dinleyin garipler sözü, 

                                   Cahillerin kördür gözü.

                                    Lağım çukurudur yüzü, 

                                 Gülersin yuh olsun sana.

                                   Dinle İnce''nin sözünü, 

                                   Seyreyle sahte yüzünü.

                                    Vallah çıkarır gözünü, 

                                   Verirsen yuh olsun sana.

                         1994 TMO Bölge Müdürlüğünde yazılmıştır.', 'Her gördüğün insan sanma,                                      Tatlı sözlere aldanma.                                      Alış verişine kan...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yuh-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YETER ARTIK', 'yeter-artik-sabit-i-nce-walrc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeter artık bu kadarla bitirek, 

Eksiğimiz varsa çabuk yetirek.

Ne istersen bedelini getirek, 

Yorma şu garibi yollara dogru.', 'Yeter artık bu kadarla bitirek,  Eksiğimiz varsa çabuk yetirek. Ne istersen bedelini getirek,  Yorma şu garibi yollara dogru....', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yeter-artik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YESEVİ''DE', 'yesevi-de-sabit-i-nce-ld33m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yesevi de yesevi de, 

                                   Sevgi çağlar Yesevi de..

                                    Pirim Hacı Bektaş Veli, 

                                     Pişti geldi yesevi de..

               

                                    Ahmed yesevi nurunu, 

                                     Saçtı gitti yesevi de.

                                     Yüzyılların gururunu, 

                                   Taşidim ben yesevi de..

                                    Türk alemi kültürünü, 

                                    Arar bulur yesevi de...

                                    Yüce İslam gururunu, 

                                    Arar durur yesevi de..

                                     Yesevi''de, Yesevi''de, 

                                    Benliğim var yesevi''de.

                                    İNCE seller akar durur, 

                                    Bizim eller yesevi''de..

                                          15.11.1995', 'Yesevi de yesevi de,                                     Sevgi çağlar Yesevi de..                                     Pirim Hacı Bektaş Veli...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yesevi-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARAB', 'yarab-sabit-i-nce-t8vgd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarab namertlere muhtaç eyleme, 

İster cehennemde yandır da beni.

En zehirli oku vur da sineme, 

Muhanete muhtaç eyleme beni.

Yarab namertlere imkanlar verdin, 

Onların eline koydun seveni.

Bütün nimetlerin onlara serdin, 

Bir sevgi peşine gönderdin beni.

Yarab sevenlerin mahzun eyleme, 

Aşkindan divane döndürme beni.

Şakisam konsam da gonca gülüme, 

Yar gülünden başka kondurma beni.

Yarab bu İNCE''nin dileği senden, 

Muhanet atına bindirme beni.

Dünya nimetini istemem senden, 

Yeter ki aşkina kandir sen beni.

13.1.1995', 'Yarab namertlere muhtaç eyleme,  İster cehennemde yandır da beni. En zehirli oku vur da sineme,  Muhanete muhtaç eyleme beni. Yarab namertle...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarab-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞIYOR O', 'yasiyor-o-sabit-i-nce-38eie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Veysel dünyada gülmedi, 

                                    Benzeri aşik gelmedi.

                                    Bilin ki Veysel ölmedi, 

                                   Canda, tende yaşiyor o.

   

                                  Aşkin deryasinda gezdi, 

                                   Maddeyi, manada sezdi.

                                  Kalp gözünden bade ezdi, 

                                   Bardaklardan taşiyor o.

                                   Veysel çekilip oturmuş, 

                                    Ötelerden sır getirmiş.

                                  Dertlere derman yetirmiş, 

                                 Telde şifa taşiyor o.

                                  Her çiçekten balı almış, 

                                 Dünyaya bir Veysel gelmiş.

                                    İnce''de gönülü vermiş, 

                                    Çağdan çağa aşıyor o.', 'Veysel dünyada gülmedi,                                      Benzeri aşik gelmedi.                                     Bilin ki Veysel ölmed...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasiyor-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARİM DEYİ', 'yari-m-deyi-sabit-i-nce-2xcjy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gene bülbül oldu ötüyor dilim, 

Çağırır güllere gel yarim deyi.

Gözüm nurun arar, niyazda elim, 

Yalvarır Allah''a bil yarim deyi.

Ömür geldi gider soluyor gülüm, 

Sonbahar geliyor, sol yarim deyi.

Bir gün dilim durur gelir ecelim, 

Beni de yanına al yarim deyi.

Ne mal mülk kalır ne de iyalim, 

Sevgilim bağırır, kal yarim deyi.

İNCE emir almış nasıl duralım, 

Vakit tamam oldu, bil yarim deyi

26.10.1994', 'Gene bülbül oldu ötüyor dilim,  Çağırır güllere gel yarim deyi. Gözüm nurun arar, niyazda elim,  Yalvarır Allah''a bil yarim deyi. Ömür geldi...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yarim-deyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARADANA', 'yaradana-sabit-i-nce-xglj6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaradana, yaradana, 

Seni, beni yaradana, 

Esen yeller ''hu'' diyorlar, 

Tüm varları yaradana...

Yaradana, yaradana 

Noksanlık yok yaradana.

Seher vakti kuşlar bile, 

Niyaz eyler yaradana.

Yaradana, yaradana, 

''Yar'' dedim ben yaradana.

İNCE! de ıkrarın verip, 

''Var'' dedik biz yaradana.

15.4.1996', 'Yaradana, yaradana,  Seni, beni yaradana,  Esen yeller ''hu'' diyorlar,  Tüm varları yaradana... Yaradana, yaradana  Noksanlık yok yaradana. S...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaradana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YA RESULALLAH', 'ya-resulallah-sabit-i-nce-x0z56', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alemlere rahmetsin, 

Nursun ya Resulallah.

Şefaatkani sensin, 

Birsin ya Resulallah.

Evliyanın rehberi, 

Pirsin ya Resulallah.

Kainatın önderi, 

Sensin ya Resulallah.

Her dertlerin dermanı, 

Emsin ya Resulallah.

Yaradanın fermanı, 

Mim''sin ya Resulallah.

Gönüllerin sultanı, 

Sensin ya Resulallah.

Mü''minlerin hayranı, 

Gülsün ya Resulallah.

Şu INCE''nin mahbudu, 

Olsun ya Resulallah.

İnsanlığın umudu, 

Yolsun ya Resulallah.

8.1.1996-Kayseri

NOT: Bestelenmiştir.', 'Alemlere rahmetsin,  Nursun ya Resulallah. Şefaatkani sensin,  Birsin ya Resulallah. Evliyanın rehberi,  Pirsin ya Resulallah. Kainatın önde...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ya-resulallah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANARIM', 'yanarim-sabit-i-nce-op6kh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden selam gelmiş edna kuluna, 

Kurban olam o Ahmed''in yoluna.

Sakın üzülmeyin dostlar halime, 

Yitirdim Leyla''yı ona yanarım.

Ben bir zaif kulum O da yaradan, 

''Kün'' emri gelince yüce hüdadan.

Ademi horlayan o lain şeytan, 

Kandırdı beni de ona yanarım.

Bilin geçen devran geri gelmiyor, 

Yanıp kül olmadan insan olmuyor.

Korkak olan her deryaya dalmıyor, 

Dalamam deryaya ona yanarım.', 'Senden selam gelmiş edna kuluna,  Kurban olam o Ahmed''in yoluna. Sakın üzülmeyin dostlar halime,  Yitirdim Leyla''yı ona yanarım. Ben bir zai...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YA ALİ', 'ya-ali-sabit-i-nce-0sk4l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılık od''una yandım tutuştum, 

                                Yanarım aşkına söndür ya Ali.

                              Gül cemalin için ummana düştüm, 

                                Yönünü bize de döndür ya Ali.

      

                         Elestü bezminde ahdimiz vardı, 

                                Yalansak pirime sordur ya Ali.

                             Medet ya Muhammed diye ağlardı, 

                                Gözlerimden yaşi durur ya Ali.

                                Yedi iklim dört köşeyi aradim, 

                              Gördüğüm Ademe sordum ya Ali.

                                On sekiz bin alemleri taradım, 

                              Haydar''ım diye de sordum ya Ali.

                               İNCE''de yanmada aşkın narına, 

                               Ateşin cismimde kordur ya Ali.

                                 Aşiklarin, sadiklarin nuruna, 

                               Muhammed aşkina vardir ya Ali.

                                           8.8.1995', 'Ayrılık od''una yandım tutuştum,                                  Yanarım aşkına söndür ya Ali.                               Gül cemalin içi...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ya-ali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VARIR MI OLA...', 'varir-mi-ola-sabit-i-nce-lwogz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel cemalini her yerde bulsam, 

Konya diyarında Mevlana olsam.

Bin tevbe ederek bir haber salsam, 

Hak çağırmış diye gelir mi ola...

Şeriat, tarikat, hakikat bulsam, 

Geceler ağlayıp saçlarım yolsam.

Huzura varıp da abidler olsam, 

Bir rekat namazım varır mı ola...

Kalbimdeki kiri silip parlatsam, 

''Ben de kulunum'' deyip zorlatsam.

Sana gideriken yollarda kalsam, 

Karınca misali, ''gel'' der mi ola...', 'Güzel cemalini her yerde bulsam,  Konya diyarında Mevlana olsam. Bin tevbe ederek bir haber salsam,  Hak çağırmış diye gelir mi ola... Şeria...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/varir-mi-ola-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VAR MI YARADAN..', 'var-mi-yaradan-sabit-i-nce-hk6il', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçları ipek mi sırma mı sırma, 

Aşkin zehirli ok kalbime vurma.

Gördüm ki katarla gidiyor turna, 

Ne güzel yaratmış turnam yaradan, 

Yeşil sunam şimdi geçti buradan.

Gözlerin şavkidi alemi tuttu, 

Seni gören gözler dilini yuttu.

Olmaz amma bir hayaldi, umuttu, 

Bu güzeli bana yazsa yaradan, 

Gövel ördek yüzüp geçti buradan.

Gönlüm bir hoş oldu ateşe düştüm, 

Cemalin görünce aklımı şaştım, 

Gözlere bakınca kendimden geçtim, 

Alemde bu güzel var mı yaradan, 

İNCE ismin soramadım sunadan.

NOT: Bestelendi.', 'Saçları ipek mi sırma mı sırma,  Aşkin zehirli ok kalbime vurma. Gördüm ki katarla gidiyor turna,  Ne güzel yaratmış turnam yaradan,  Yeşil ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/var-mi-yaradan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VAR', 'var-sabit-i-nce-uusvc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neye gamlanıyon behey gafilim, 

Bitmez tükenmez bir hazinedar var.

Bülbül de ağlıyor diyor ''ey gülüm, ''

Şahlarin şahi da bir padişah var.

Şu yalan dünyada deme sefilim, 

Senden daha dertli kulları da var.

Garib diyor ise ''Allah vekilim, ''

Görünmez yerlerden sebepleri var.', 'Neye gamlanıyon behey gafilim,  Bitmez tükenmez bir hazinedar var. Bülbül de ağlıyor diyor ''ey gülüm, '' Şahlarin şahi da bir padişah var. Şu...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/var-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebeğim', 'kelebegim-gul-i-cel-zz1cn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kelebegim, eger  sevgiyle bakan, 

Bu gözlerim, 

Uçamaz hale getiriyorsa seni, 

Sonsuza kadar  Kapatıyorum.

Sevgiyle oksamak isteyen

Bu ellerim, 

Zarar veriyorsa, kanatlarına

Kelepçeliyorum sessizce...

Haydi git, bakma sakin arkana.

Görme gözyaşlarımın

Dönüştügüne  kara.

g.g.   13.ocak.2002', 'Kelebegim, eger  sevgiyle bakan,  Bu gözlerim,  Uçamaz hale getiriyorsa seni,  Sonsuza kadar  Kapatıyorum. Sevgiyle oksamak isteyen Bu eller...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kelebegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'USTAM', 'ustam-sabit-i-nce-agmkm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşik zavalli sazla söylüyor, 

Söyleyip de ciğerimi dağlıyor.

TV başinda herkes agliyor, 

Bu kadar dertli de söyleme ustam.

Sazıyın telleri akord tutmuyor, 

Dinleyelim diye herkes yatmıyor.

Allah diyor başka kelam etmiyor, 

Yarden başka yari isteme ustam.', 'Aşik zavalli sazla söylüyor,  Söyleyip de ciğerimi dağlıyor. TV başinda herkes agliyor,  Bu kadar dertli de söyleme ustam. Sazıyın telleri a...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ustam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'USANMAN MI', 'usanman-mi-sabit-i-nce-hsc0c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Felekleri gezme gönül, 

Alta alıp ezme gönül.

Başka güzel süzme gönül, 

Hiç arlanman, usanman mı? 

Dosttan gamı çekme gönül, 

Keder, hüzün ekme gönül.

Hiç el ense çekme gönül, 

Güreşip de yikilman mi? 

Ahu zarın nice gönül, 

Kederliyim diye gönül? 

Seni kurtlar yiye gönül, 

Bir can içre duraman mı? 

Destur deyip dur ha gönül, 

Nefse bir gem vur ha gönül, 

İNCE''m dosta var ha gönül, 

O kapıda kalaman mı?', 'Felekleri gezme gönül,  Alta alıp ezme gönül. Başka güzel süzme gönül,  Hiç arlanman, usanman mı?  Dosttan gamı çekme gönül,  Keder, hüzün e...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/usanman-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Ölüm', 'bekle-olum-gul-i-cel-4sz72', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bekle ölüm geliyorum, ama agır ağır.

Yaşadıkdan sonra özlemlerimi, 

Tatdıkdan sonra mutluluğu.

Bekle ölüm geliyorum, 

Büyüttüm artık yavruları, 

Tatdırdım analı yuvayı.

Bekle ölüm geliyorum, 

Kaybetmişken ruhumu, gönlümü

Öttürememişken gülün bülbülünü.

Bekle ölüm geliyorum, 

Duyamadıkdan sonra sevgilim sözünü, 

Okşayamadıkdan sonra sevgili yüzünü.

Bekle ölüm geliyorum

Ucup giden hayallerim olmayınca, 

Gülün yaprakları kuruyunca, 

Bekle ölüm geliyorum, 

Yaşama arzum, ölüm korkum

KALMAYINCA....

G.G.       31.07.2000  İST', 'Bekle ölüm geliyorum, ama agır ağır. Yaşadıkdan sonra özlemlerimi,  Tatdıkdan sonra mutluluğu. Bekle ölüm geliyorum,  Büyüttüm artık yavrula...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bekle-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-gul-i-cel-a7xzu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lanet okuyorum sana, 

Hayatı kahrettin bana.

Dilerim tanrıdan ki, 

Çevrendekilerin varları, 

Sen istediğinde yok olsun.

Onların kadehlerindeki şarap, 

Sana zehirle dolsun.

Evlatlarınsız yediğin her lokma, 

Sana zehir zıkkım olsun.

Kendine harçadığın her para, 

Hayatını yapsın kapkara.

Hasret kalasın sevilmeğe, 

Yalvar: yavrularım, 

Ben babanızım diye.

Kork, ürper görünce görünce gözlerini, 

Kulağında çınlasın sesleri.

Şimdimi anladın baba.

Sonra  desinler ki sana

Şimdi Dua et anama, 

O öğretti bize, 

Senin gözünle değil

Sevgi gözüyle bakmağa.

G.G    8 EYLÜL 2001', 'Lanet okuyorum sana,  Hayatı kahrettin bana. Dilerim tanrıdan ki,  Çevrendekilerin varları,  Sen istediğinde yok olsun. Onların kadehlerinde...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sana-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçluyum Hakim Bey', 'sucluyum-hakim-bey-gul-i-cel-s1xy7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinle hakim bey anlatayım; 

Ayın birinde doğarak memur babamı, 

Altıncı hamileliğinden annemi, 

Rahatça kurtarmayı  BAŞARDIM.

Sessiz ama inatçı  bir kız olarak, 

Liseyi babam için, 

Yüksek okulu kendim için, 

Bitirmeyi BAŞARDIM.

Benim olsun, evim olsun diye 

Evlenmeyi, 

Evliliğin güzelliği için oğlumu, 

Kendim için kızımı doğurmayı BAŞARDIM.

Sırtımda iflas aşığı kocamı, 

Kucağımda sevgimle yavrularımı, 

Mum gibi eriyen evliliğimi, 

Dimdik  tutmayı BAŞARDIM.

Çalıştıkça kazanmayı, 

Kazandıkça paylaşmayı, 

Paylaştıkça güçlenmeyi BAŞARDIM.

Azrail’le flört edip, kandırmayı, 

Analı yavru büyütmeyi BAŞARDIM.

Yok hakim bey az sabret.

Suçluyum. Hem de çok, 

Bir baktım ki arkaya, 

En önemliyi BAŞARAMAMIŞIM.

Kendimi unutmuşum.

Ortam uygun, Loş bir mekan, 

Son duanı yap dedim.

Duadan önce boy abdesti.

En temizler giyildi üste.

Sofra hazır, mumlar masada, 

Kadehler şıkır şıkır, 

En güzel kokular sürüldü.

Düğüne gider gibi.

Kimse anlamasın, veda yemeği bu.

Gülmek gerek, 

Bir kaç kadeh beyaz şarap, 

Her şey güzel, mükemmel, 

Yatma vakti gelir, 

İşte tam hesaplanan zaman, 

İyi geceler öpücüğü konulur

O gül yanaklara yavruların.

Bir sigara yakılır, 

Sessizce dökülür masaya haplar, 

Üç, beş, yetmez belki otuz, 

İki yudumla içilir.

Sonra kadehin tamamı.

Veda başlamıştır artık.

Doğru yatağa......

Gözler kapanır iyice, 

Hafif bir baş dönmesi, 

Huzurla sarınılır yastığa......

Aman..Oda ne? 

Gün ışımıştır, açılır gözler.

İçerden kurulan kahvaltı sesi.

SUÇLUYUM HAKİM BEY, 

Yaşamayı BAŞARAMADIĞIM gibi

Ölmeyide BAŞARAMADIM...

G.G (Kendimi tanıdığım bir gece-İstanbul.)   1998', 'Dinle hakim bey anlatayım;  Ayın birinde doğarak memur babamı,  Altıncı hamileliğinden annemi,  Rahatça kurtarmayı  BAŞARDIM. Sessiz ama ina...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/sucluyum-hakim-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz', 'kimsesiz-gul-i-cel-9x8tc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne  acıdır ah bir anlatabilsem, 

Varken yok olan hayatımı.

Bakamam  gökyüzüne hiç geceleri.

Korkarım sönen her bir yıldızı gördükçe

Canlanır  hafızamda  aniden, 

Pırıl pırıl ışıkların sönüşü.

Bilirmisiniz bakamıyorum vitrinlere, 

İçime  bir bıçak gibi saplanıyor.

Sanki ben değildim onları  seven, 

Pırıl pırıl ışıklar içinde seyreden.

Ürküyorum dostlarımdan, bilirmisiniz? 

Yokum artık aralarında, hepsi ilgisiz, 

Anladım ki ben artık, 

Parasız, pulsuz  ve  KİMSESİZ.

G.G.  17 TEMMUZ 1999  İST', 'Ne  acıdır ah bir anlatabilsem,  Varken yok olan hayatımı. Bakamam  gökyüzüne hiç geceleri. Korkarım sönen her bir yıldızı gördükçe Canlanır...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kimsesiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrailin elçisi Saf Kanser', 'azrailin-elcisi-saf-kanser-gul-i-cel-2bgfi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazarlar  ilanlarda, 

Acı bir ölüm, 

Sanki tatlısı varmış gibi, 

Dilleri varmaz adını demeye...

Halbuki  kolay, sadece

Kanser, 

Neymiş efendim çaresiz bir hastalık, 

Yalan, vallahi yalan, 

Azrailin bir oyunu, 

Maksat iyi bilmek  huyunu...

Panzehiri gülmek.

Tehtidi...dökerim bak  saçını

Dök...gülüşümü  dökemezsin ki...

Seni istiyorum der.

Ben seni istemiyorum ki dersin.

Üzülür, 

Tamam kıyamam sevebilirim dersin.

Sevinir.

Ama  bana zaman  ver.

Saftır... İnanır...

Gider, gözleri arkada içi buruk.

Beklesin..  gideceğim.

Ben sözümün eriyim.

Ama

Daha gülünecek  çok işim var..

G.G.   Ocak 1993 

(son kemoterapi krizi bittikden sonra yani  ikincihayat ın başı)', 'Yazarlar  ilanlarda,  Acı bir ölüm,  Sanki tatlısı varmış gibi,  Dilleri varmaz adını demeye... Halbuki  kolay, sadece Kanser,  Neymiş efend...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/azrailin-elcisi-saf-kanser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki Sen', 'bendeki-sen-gul-i-cel-py376', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göz pınarımdaki yaş gibi, 

Damarımdaki kan gibi içimdesin...

Üzüntümle üzülen, 

Sevincimle gülensin.

Beynimdesin, gönlümdesin.

Sanki bensin, bense sen.

Artık iki kişilik gülüp, 

İki kişilik ağlıyorum.

Senin için gülerken, 

Ağlıyorum kendim için.

İnsan kendini sever mi? 

Gülme birtanem gülme.

Kendimde, seni seviyorum.

Özlüyorum bir tanem, 

Kendimdeki seni özlüyorum.

Tenimde hissedemediğim tenini, 

Saçımda hissedemediğim elini, 

Yüzümde hissedemediğim

Nefesini özlüyorum.

Seni senle yaşamağı özledim.

Yoruldum birtanem, çok yoruldum.

Seni, bende yaşamaktan değil, 

Seni sensiz yaşamaktan yoruldum.

g.g.29.09.2001 istanbul', 'Göz pınarımdaki yaş gibi,  Damarımdaki kan gibi içimdesin... Üzüntümle üzülen,  Sevincimle gülensin. Beynimdesin, gönlümdesin. Sanki bensin,...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bendeki-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmesin', 'bitmesin-gul-i-cel-7wqcp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gene bir tuhaf içim, 

Sanki Bir matkap oyuyor kalbimi.

Halbuki alışmaya çalışmıştım.

Seni sensiz yaşamaya.

Hasretlik uzadukça bitermiş sevgi.

Kim demiş? 

Hasretlik uzadıkça, 

Sevgi tutku oluyor bende.

Korkuyorum...hemde çok..

Hani rüyalarda, tutarsın ya.

Tutarsında yok olur ya birden.

Kaçıp uçuverir elinden.

Yarım asırlık hayatımin sonunda 

Hatiralarimdaki sevgi.

Yüreğimi Çarptıran heyecan, 

Sevgiliye duyulan özlem.

Yoksa tanrım bu bir rüyamı? 

Duyduğum Korku bu mu? 

Ne olur tanrım bu bir rüyaysa, 

Rüyam bitmesin...

Yok yaşamsa

Aşkımız bitmesin.

g.g 25.eylül.2001', 'Gene bir tuhaf içim,  Sanki Bir matkap oyuyor kalbimi. Halbuki alışmaya çalışmıştım. Seni sensiz yaşamaya. Hasretlik uzadukça bitermiş sevgi...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bitmesin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle bir gecede', 'boyle-bir-gecede-gul-i-cel-ennl9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Böyle bir gecede bulsunlar beni, 

Varlık içinde yok olduğumda, 

Görsünler alnımdaki çizgileri

Sanmasılar ki yılların izleri 

Böyle bir gecede baksınlar yüzüme, 

Okusunlar her çizgiyi

Hepsi ayrı bir hikaye, 

Yaşanmış her bir acıdır çizgi. 

Böyle bir gecede duysunlar sesimi, 

Bir dilsizin attığı çığlık gibi, 

Hissetsinler yaşar gibi ölmüşlüğümü.

Sevgisizlik denizindeki sevgililiğimi.

Böyle bir gecede baksınlar yüzüme.

Görsünler, görmezleri gördüğü gibi.

Bir şırca saray içindeki, 

Yaşanmamış yaşamışlığımı.

 G.G.      22.2.1997  İst', 'Böyle bir gecede bulsunlar beni,  Varlık içinde yok olduğumda,  Görsünler alnımdaki çizgileri Sanmasılar ki yılların izleri  Böyle bir geced...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/boyle-bir-gecede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanırım Birtanem', 'dayanirim-birtanem-gul-i-cel-xsx0i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sarmaşık gibi sardı ruhumu sensizlik, 

Geceler bitmiyor inan sensiz.

Uyku nedir unuttu gözlerim.

Bilmem hissediyor musun bebeğim.

İsmin dudaklarıma dua oldu.

Hayalin tuvalimde resim.

Düşünceler bulut oldu, 

Özlemlerse şimşek.

Ulaşılmazlıksa kabusum.

Varsın olsun bir tanem.

Dayanırım.

Yeter ki, ben solan bir gül, 

Sense giden bir kelebek olma.

g.g.14.ekim 2001', 'Bir sarmaşık gibi sardı ruhumu sensizlik,  Geceler bitmiyor inan sensiz. Uyku nedir unuttu gözlerim. Bilmem hissediyor musun bebeğim. İsmin ...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dayanirim-birtanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızım', 'kizim-gul-i-cel-ov3fm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülünce içimde güller açtıran.

Neşeliyken bülbül gibi şakıyan, 

Yaşama küstüğümde

İç güdülerinle, beni

Hayata bağlıyan tatlı kızım.

Benim canım Anka kuşum..

Sanki melekler el vermiş sana..

Gözlerden ruhu okuyan, 

Bakışlardan nem kapan, 

Gözlerinden sağanaklar yağdıran, 

Gül dudaklarını titreten, 

Minik kuşum.

Hayatın bir gül bahçesi, 

Sense orda şakıyan bülbülü

Bile kıskandıran Anka kuşu ol bebeğim.

Yıllar geçip saçların da

Aklarını taradığında, 

Yavrularının kulağına fısılda

Gülerek.

Annem kuzgun değilmiş...

Gül güneş 3 eylül 1999', 'Gülünce içimde güller açtıran. Neşeliyken bülbül gibi şakıyan,  Yaşama küstüğümde İç güdülerinle, beni Hayata bağlıyan tatlı kızım. Benim ca...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kizim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum', 'oglum-gul-i-cel-jjbl0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaferimsin sen benim, 

Sırdaşım, arkadaşım, oğlumsun.

Bedenimde canlanan ilk filiz, 

Hayat tarlamdaki fidanımsın.

Korka sakın, 

Fırtınadan, kasırgadan.

Sana sevgim o kadar köklüki, 

Sökemez fırtınalar, 

Donduramaz  karlar.

Isıtsin içini sevgimin şerbeti.

Ver doyasıya, ver sevgini.

Unutmaki, mutluluğu besleyen sevgi, 

Başarıyı besleyen mutlulukdur.

Ananın sana eksilmeğen duası, 

Sev, sevil, mutlu ol

gül günes  26.haz.1993', 'Zaferimsin sen benim,  Sırdaşım, arkadaşım, oğlumsun. Bedenimde canlanan ilk filiz,  Hayat tarlamdaki fidanımsın. Korka sakın,  Fırtınadan, ...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oglum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül koymuşlar adımı', 'gul-koymuslar-adimi-gul-i-cel-ipqrz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Babam gül koymuş adımı, 

Hep güleyim diye.

Öyle tuttum ki sözünü, 

Güldükçe, hani derler ya.

Gözlerimin içi güldü.

Bir kahkaha attıkça, 

Bin kahkaha olurdu.

Sorardı hep dostlar, 

Sen hep gülermisin.

Yok mu enin hiç üzüldüğün.? 

Derdim ki, ''babam gül koymuş adımı.

Günler ayları, 

Aylar yılları takip etti.

Yaşanan her üzüntüden, 

Süzerek buldum gülme sebebini.

Öyle değil mi ya.

Kötüler olmasa kim anlardı iyileri, 

Yoklar olmasa anlarmıydık varları.

Gene gülüyorum, düşünerek geçmisi, 

Nelere güldüğümü sebep aramadan.

Hep gülmelisin diyorum kendime.

Ta ki..sebepler bitene kadar.

g.g.   5.ocak.2002', 'Babam gül koymuş adımı,  Hep güleyim diye. Öyle tuttum ki sözünü,  Güldükçe, hani derler ya. Gözlerimin içi güldü. Bir kahkaha attıkça,  Bin...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gul-koymuslar-adimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar, Ben ve Sevgim.', 'sarkilar-ben-ve-sevgim-gul-i-cel-5w1bd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutsan da gözlerimin rengini, 

Bekliyorum.

Gül sen gülün olayım demeni.

Sevmek korkulu bir rüya olsada, 

Korkmuyorum sevmekden.

Unutulmak çok acı, 

Diyorlar ama.

Unutamam ben seni.

Unutulsamda ben.

Biliyorsun.

Sen benim gönlümde, 

Açan son güldün.

Düşünürken sessizce, 

Ne yaptım sana ben, 

Neden uzaklaştın, derken....

Cevabı gene kendi veriyor şarkılar.

Ben gamlı hazan, sense bahar, 

Dinlede vaz geç....

gul gunes  (kendimi yalnız hissetiğim bir an)', 'Unutsan da gözlerimin rengini,  Bekliyorum. Gül sen gülün olayım demeni. Sevmek korkulu bir rüya olsada,  Korkmuyorum sevmekden. Unutulmak ç...', ARRAY['Türk Edebiyatı','Şiir','Gül İçel']::text[], 8.5, '{"poet":"Gül İçel","poet_slug":"gul-i-cel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sarkilar-ben-ve-sevgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama hepsinde yine sen varsın', 'ama-hepsinde-yine-sen-varsin-sukru-tahmaz-xhm1x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gümüşten gökyüzünün parıldayan hüzmeleri

Sensiz geçen günlerin bitmeyen hüzünleri

Sen gelince son bulacaktı

Yanlız oyun oynayan bir çocuğun sesizliği

Kullanmayı çözemediğim gitarımın sesizliği 

Sen gelince son bulacaktı

Yalanlardan örülmüş şu dünyada 

Sensiz kaldım ben yarınlarda

Yağan o yağmurlarda yere düşen damlalarla

Sevdiğim tüm kelimeler yine geldi bak aklıma

Ama hepsinde yine sen varsın

Annemin canım deyişi bir çocuğun saf sevgisi

Gökkuşağının tüm renkleri, Mutlu bir günün gelişi

Ama hepsinde yine sen varsın', 'Gümüşten gökyüzünün parıldayan hüzmeleri Sensiz geçen günlerin bitmeyen hüzünleri Sen gelince son bulacaktı Yanlız oyun oynayan bir çocuğun ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tahmaz']::text[], 8.5, '{"poet":"Şükrü Tahmaz","poet_slug":"sukru-tahmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ama-hepsinde-yine-sen-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşça Kal Canım Sevdiceğim', 'hosca-kal-canim-sevdicegim-tolga-baydar-x5f1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hatıralar içimde hep sızlayacak

Aklıma ilk öpüştüğümüz an geldiğinde

Masumane ve de çocuksu

Hala öyleyim merak etme

Tek bir farkım varsa şayet

O da sana etmiş olduğum ihanet.

Varlığını bilip sensiz yaşadım seni

Hep hayal ettim yanımdaymışçasına

Başım omuzundaydı hep ağlamaklı

Bil ki; Sana hiç yalan söylemedim

Bu kadar yakınken sana hep uzaktım

Sırf ki, sen zarar görmeyesin dedim.

Sen de biliyorsun nasıl yaşadığımı seni

Sor bakalım var mı başka böyle bir deli

Sevdiğine bu kadar uzak duran ben

Aşkını kalbine gömüp ağlayan ben

O yatağa girerken bin defa ölen ben

Sabah olduğunda uyandığına kahreden ben.

Teşekkür ediyorum, küfretmediğin için

Teşekkür ediyorum, sövmediğin için

Teşekkür ediyorum, beni böyle kabul ettiğin için

Teşekkür ediyorum, verdiğin mutluluk için

Teşekkür ediyorum, her şey için

Hoşça kal canım sevdiceğim.', 'Hatıralar içimde hep sızlayacak Aklıma ilk öpüştüğümüz an geldiğinde Masumane ve de çocuksu Hala öyleyim merak etme Tek bir farkım varsa şay...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hosca-kal-canim-sevdicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağbozumu', 'bagbozumu-gokhan-oktem-8d4m0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şiirin bir hikayesi olmalı tıpkı

Her hikayenin bir şiiri olması gerektiği gibi...

Yaşam bir hikayeler bütünü değil mi aslında...? 

Şöyle karıştırıp birleştirince de bir roman...

Bir hikayeler manzumesi... ya da hikayemsi bir roman...

Bir adanmışlıkların, gizli tutkuların, dipsiz acıların, eşsiz mutlulukların, sevinçlerin, kazanışların ve kaybedişlerin hikayesi

Ya da tarifsiz korkuların  ve derin ihtirasların romanı...

Aşklarımızı terk ediş ve edilişlerimizden soyutlayabilir miyiz hiç...? 

Ya da alışkanlıklarımızı geçmişimizden... ? 

Zaman geçer, her şey zamanla birlikte akıp geçer..

Olaylar duygularla kol kola

Anılarda yerlerini alıverir vakit kaybetmeden

Zamanın uzayan kirli koridorlarında...

Anılar hikayelere dönüşür bir çırpıda, kesik kesik hikayeler..

Her hikaye başlangıçtır aslında sonu gelmez bir romana

Ya da bildik sonlar yüklenir her romanın hikayemsi dokusuna...

Yaşamlar yaşanmışlıklardır aslında, tercihler kıskacında...

Ve yaşanacaklardır umutlar bulamacında..

Her tercih biraz umuttur aslında biraz da bildik tanıdık bir alışkanlık, 

Ama salt bir umut değildir ne de salt alışkanlık...

Bu yüzden, salt bu yüzden çoğu zaman bir bilinç gerektirmez 

Ama her tercih huzursuzluk yaratır biraz bilinç altından.

Bilinç ile bilinç altı sularında gidip gelen 

karakterimizin aynasıdır aslında tercihlerimiz

Ve bağbozumu gibidir hayat geçmişimizin hikayemsi romanından arta kalan

Mevsimler gibi akışkan ve sözcükler kadar saydam...

Bağbozumu gibidir hayat her ölümden bir yaşam çıkaran...

Her şiirin bir hikayesi vardır

Her hikayenin bir şiiri  olduğu kadar...

Yaşam bir hikayeler bütünüdür aslında... 

Şöyle karıştırıp birleştirince de bir roman

Bir hikayeler manzumesi... ve de hikayemsi bir roman...

Bir bağbozumu deviniminde akışkan ve sözcükler kadar saydam..

Bir bağbozumu güzelliğindedir hayat her ölümden bir yaşam çıkaran...

(İstanbul,20,01,2002)', 'Her şiirin bir hikayesi olmalı tıpkı Her hikayenin bir şiiri olması gerektiği gibi... Yaşam bir hikayeler bütünü değil mi aslında...?  Şöyle...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bagbozumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah...', 'bir-sabah-bahar-kilinc-uu0wy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah

Ben ''ben'' olarak uyanacağım

O günden sonra

Artık...

Ne uyuyacağım, ne de uyutulacağım! ! !', 'Bir sabah Ben ''ben'' olarak uyanacağım O günden sonra Artık... Ne uyuyacağım, ne de uyutulacağım! ! !...', ARRAY['Türk Edebiyatı','Şiir','Bahar Kılınç']::text[], 8.5, '{"poet":"Bahar Kılınç","poet_slug":"bahar-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-sabah-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım DENİZ', 'askim-deni-z-levent-keskin-auppn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kahverengi gözleri var sevda çiçeğimin, 

Kısacık saçları ellerimde erir titrer yüreği, 

Uzun kirpikleri kaygılı, ısıtır içimi, 

Her dokunuşu tenimde bir alev bir alev sanki.

Kayboluyor dudaklarında tüm benliğim, 

Bakışlarında eriyor ruhum, bedenim.

Dilimden hiç eksilmiyor onun adı, 

Söylendikçe artıyor tadı.

Sevgimize karşılık aramakla geçti aylar, 

Şimdi buldum onu ruhumda sadece onun tadı var, 

Kaderle yaptığım anlaşma sonsuza kadar.', 'Kahverengi gözleri var sevda çiçeğimin,  Kısacık saçları ellerimde erir titrer yüreği,  Uzun kirpikleri kaygılı, ısıtır içimi,  Her dokunuşu...', ARRAY['Türk Edebiyatı','Şiir','Levent Keskin']::text[], 8.5, '{"poet":"Levent Keskin","poet_slug":"levent-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askim-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Tanesi', 'kar-tanesi-bahar-kilinc-qwe1c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kar tanesi olup sana gelmek isterim

Temiz ve beyaz, güzel ve saf

Rüzgarın esişine bırakırım kendimi endişesiz, dertsiz

Sen daha uykudayken sessizce beklerim camında

Sonra o mahmurluğunda seyrederim gülüşünü, bakışını, odanı

O şenşakrak kahkahalarını işitirim

Beklerim bir ümitle farkedeceksin diye

Geçen saatler koparır seni benden sen gülerken zaman eritir beni yavaşça

Üzgünüm ömrüm çok kısa bekleyemiyorum artık seni

Geçte olsa farkedersin belki ama

Bir su birikintisi kalır kartanesinden

Geriye sana! ! ! !', 'Bir kar tanesi olup sana gelmek isterim Temiz ve beyaz, güzel ve saf Rüzgarın esişine bırakırım kendimi endişesiz, dertsiz Sen daha uykudayk...', ARRAY['Türk Edebiyatı','Şiir','Bahar Kılınç']::text[], 8.5, '{"poet":"Bahar Kılınç","poet_slug":"bahar-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kar-tanesi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Soğuk Günlerinde Yokum', 'en-soguk-gunlerinde-yokum-erdal-gisi-y5pdp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son Otuz Yılın En Kurak Yazı Gibi 

En Soğuk Kışı Da Geçmek Üzere 

Pencereler Eşsiz Manzaraları Sergiliyor Buzdan 

On Gündür Beyaz Sessizlik 

Dallar Eğilmiş Kardan 

Çocukluğumda Gürgen Ağacından Kızaklarım Vardı 

Sol Kaşımdaki Çizik Bir Kızak Kazasından 

Şimdi Kartopu Oynayamasam 

Çoraplarım Islanmamışsada Üşüyorum 

Üşüsem De... Rüya Gibi Geliyor 

Bir Şeritmiş Gibi Eski Hatıralardan 

Aslında Herşey Gerçek 

Doğalgaz Olmasa Odun Telaşı, Kömür Kokusu 

Okullar Tatil Olmasa Çocuklar Üşüyecek 

Sevgili... En Büyük Sorun Anısızca Yaşamak 

Üşüyen Kulaklarımdan Başka Anı Bırakamıyorum 

Düşündükçe... Ürperecek 

Son Yılların En Çetin Kışıda Bitmek Üzere 

Doğrusu Çok Üzgünüm 

Halbuki Soğuktan Nar Kesilmiş Ellerini 

Avuçlarımda Isıtabilirdim 

Dudakların Morarmıştır 

Bir Sabah Otobüs Durağında 

Başını Göğsüme Alabilirdim 

Duman Dumandır Şimdi Nefesin 

Vakit Geç Olsa Da 

Sahlep İçsek... Az Daha Kalsan 

Eldivenlerinde Islanmış Belli 

Benimkileri Al Diyebilirdim 

Sevgili... 

En Soğuk Günlerinde Yokum 

Özür Diliyorum 

En Soğuk Günlerimde Yoksun 

... Kader Diyorum', 'Son Otuz Yılın En Kurak Yazı Gibi  En Soğuk Kışı Da Geçmek Üzere  Pencereler Eşsiz Manzaraları Sergiliyor Buzdan  On Gündür Beyaz Sessizlik ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/en-soguk-gunlerinde-yokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veronica', 'veronica-huseyin-aktas-pff9p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son çanlar çalıyor, 

Duymaz mısın veronica? 

Yanımdasın, hadi sende ağla 

Eğme başını, kulaklarını kapatma

O esen rüzgarı dinle, 

İşte o benim, benim veronica! 

Bırak saçlarını bana, 

Oynayayım ağaçlar gibi.

Hiddetli estiğimden korkma, 

Haykırışımdır sana, 

Duymaz mısın Veronica? 

Hüküm gelmiş mikailden

Çıkarım artık dağlara.

Anlatırım seni nasıl sardığımı, 

Ağaçlara ve kuşlara; 

Ama bırakmam seni veronica.

Bulut olurum ağlarım senin adına, 

Ağlarım ne kadar ömrüm varsa. 

Unutmaki hükmü geçmez mikailin bana! 

................................................................

...Durma veronica, 

Hadi koş, mavi boşluğa

Ağla, ben yokum artık orada.

Kar oldum eridim, eritildim, 

Dolu oldum, kendimden korktum, 

Etrafıma baktım sen yoktun.

Durma veronica, ağla 

Mikailin hükmü geçti bana 

Ruhumu savurdu kuru bir dağ yamacına; 

Ses yok, sen yok, ben yok orada.

Kupkuru toprak ve çok uzaklarda bir yaprak, 

Dünden kalan ve koca bir ağaç olan; 

Ama 

Kupkuru bir yaprak.

Nice rüzgarlarla oynaşmış, 

Yalnız kalmış, ağlamış, kırılmamış

Bir yaprak

Sen veronica tutsaksın; 

Ama

O, o olmayan yaprakken 

Haykırdı özgürlüğü.

Ta  ki

Senin hikayeni benden dinleyip 

Seni sevip sen olana kadar.

Yaşamayı yarınlara bırakan sen, 

Kendini yaşayamadın.

Dinle veronica, 

Kendini o kuru yapraktan dinle! 

Neler anlatacak sana 

Seni sen yapan yaşanan rüya, 

Onun sözlerinde gerçekliğe aksedecek...', 'Son çanlar çalıyor,  Duymaz mısın veronica?  Yanımdasın, hadi sende ağla  Eğme başını, kulaklarını kapatma O esen rüzgarı dinle,  İşte o ben...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Aktaş']::text[], 8.5, '{"poet":"Hüseyin Aktaş","poet_slug":"huseyin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/veronica-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz ayazı', 'guz-ayazi-gokhan-oktem-5kkpn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur çiseliyor

Yağmur çiseliyor

Güz ayazı dökmüş çiğlerini yerde yatıyor

Hüznüm göz bebeklerimin çukurunda sabahlamış

Hüznüm sabahın çiğlerine akıyor

Çiğ yüreğim dökme demir

Gözlerim demli derya....

Gözlerim bir sabah mahmurluğu tadıyor

Kırılmış umutların mı taşınması zor...? 

Sırra kadem aşkların mı yaşatılması...? 

Hüznüm çiseliyor

Hüznüm çiseliyor

Yüreğim güz ayazı

Dökme demir kanıyor

Dışarıda kızılca kıyamet

Yağmur yağıyor...

(İstanbul,18,07,2001)', 'Yağmur çiseliyor Yağmur çiseliyor Güz ayazı dökmüş çiğlerini yerde yatıyor Hüznüm göz bebeklerimin çukurunda sabahlamış Hüznüm sabahın çiğle...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/guz-ayazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Diyebilseydim', 'keske-diyebilseydim-abaryan-engin-dl1jm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni sevmiyorum artık diyebiliyorum

seni düşünmüyorum diyebiliyorum

arkadaşlarn senden bahsettiklerinde

beni ilgilendirmiyor diyebiliyorum

mutlu veya mutsuz olman beni ilgilendirmiyor

demek isterdim inan olmuyor meryem''im

yine her ismini duyuşumda

kalbimin çarpış sayısı iki katına çıkıyor

bana yaptığın onca ihaneti hiçe sayıyorum

evet bu banada mantıksız geliyor

inan gönül mantıklı davranmıyor

mantıklı davranmam gerekseydi

seni çoktan öldürmem gerekirdi

günden güne kendi ölümümü görmektense

senin bir dakikakalık ölümünü görmeyi yeğlerdim

geçenlerde berbat bir gün geçirdim

halbuki o günün benim en mutlu günüm olması gerekirdi

aylar olmuş yüzünü görememiştim

hatta artık sesini bile duyamıyordum

berbat bir halde kendimi attım sokağa

sensiz olmak berbat bir durumda olmam için yeter artar bile

niyetim seni konyanın o biçare sokaklarında bulabilmek

yoksa biçarelerin sokaklarımı deseydim

seni görmek hiç birşey demeden dudaklarına yapışmak

nefes almanı sağlamadan ateşli ateşli öpmek

ve nefessizlikten kollarımın arasına düşüp son nefesini vermen

birden bir ses ilişiveriyor kulağıma

evet eminim bu senin sesin diyorum kendi kendime

fakat kendi kendime cevabım gecikmiyor

hadi be sende zaten bi halüsülasyon kalmıştı görmediğin

biraz yavaşlıyorum belki arkamda olursun diye

dayanamayıp arkama bakıyorum daha doğrusu bakakalıyorum

sen başkasıyla elele tutuşmuş kahkahalar atıyorsun

beni görünce kafanı öne eğiyorsun bilmem belkide utanıyorsun

ama biraz geç kalmadın mı be canım

beni bile bile ölümlere atarken utanmadında şimdi mi utanıyorsun

sonra bir yabancıymışım gibi yanımda geçiyorsun

geçmekle kalmayıp ölüm fermanımı imzalıyorsun tabir-i caizse

ve benim elimden hiç bir şey gelmiyor

gelip seni onun elinden alamıyorum

alıp oracıkta boğazını sıkıp bu hikayeyi bitiremiyorum

sonra düşünüyorumda sen mutlusun

ve zaten bende seni mutlu etmek istiyorum

birden üzüntüler mutluluğa, gözyaşlarım hkahalara dönüşmek istiyor

ama ben izin vermiyorum buna

benimle olmayacaksa bu hikayenin mutlu bitmesine 

izin vermek istemiyorum

ucunda ikimiz için ölüm bile olsa', 'seni sevmiyorum artık diyebiliyorum seni düşünmüyorum diyebiliyorum arkadaşlarn senden bahsettiklerinde beni ilgilendirmiyor diyebiliyorum m...', ARRAY['Türk Edebiyatı','Şiir','Abaryan Engin']::text[], 8.5, '{"poet":"Abaryan Engin","poet_slug":"abaryan-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/keske-diyebilseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tercih', 'tercih-faruk-elma-puxty', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben hayatta seni tercih ettim 

kahkahayla güldüm sana 

sen sadece tebessüm ettim 

beni etkilemiştin derinden 

gözyaşlarıma yanıldım

damladı kanadı ta içimde

her kim seviyorsa seni

her ne zaman ordaysan 

ağlamak gerekmezdi senin için 

karmakarışık duygular 

tekrardan yaşamak bitmiş hayatı

ve bir demet gül sana

üzerine almak istediğin benim hatyatım

sana ait olan ne varsa benim 

bırakmak ellerimi

titremek tenine dokunarak 

çıldırmak güzelliğine

ve seni sevmek ömürboyu', 'ben hayatta seni tercih ettim  kahkahayla güldüm sana  sen sadece tebessüm ettim  beni etkilemiştin derinden  gözyaşlarıma yanıldım damladı ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tercih-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl', 'akil-mustafa-turk-2-dy2v8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'akıllı insanlar hep aklın peşinden koştu, 

sonunda hepsi de telef oldu....

çünki; akıl da orospu çıktı.', 'akıllı insanlar hep aklın peşinden koştu,  sonunda hepsi de telef oldu.... çünki; akıl da orospu çıktı....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Türk 2']::text[], 8.5, '{"poet":"Mustafa Türk 2","poet_slug":"mustafa-turk-2","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/akil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SENSİZLİK', 'sensi-zli-k-sair-yasef-fx9ua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SENSİZ GEÇEN HER ANIM İSYANLA DOLU

SENSİZ ALDIĞIM HER NEFES ZEHİR MİSALİ

SENLE DOĞACAK GÜNE ÖZLEMLE HASRETİM

SENSİZ BATAN HER GÜN ÖLÜMLE YÜZYÜZEYİM', 'SENSİZ GEÇEN HER ANIM İSYANLA DOLU SENSİZ ALDIĞIM HER NEFES ZEHİR MİSALİ SENLE DOĞACAK GÜNE ÖZLEMLE HASRETİM SENSİZ BATAN HER GÜN ÖLÜMLE YÜZ...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensizlik-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırımlar', 'kaldirimlar-levent-keskin-hsn2x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaldırımlar, adım adım eziliyor, yavaşça geçiliyor, 

ama hiç kimse bilmiyor, 

buradan geçenler sadece adımlarını değil

umutlarını bırakıyor.

Biliyorum yine boşalacak ve yine yalnız! 

İçimdeki ateşi söndürmek pahasına geçeceğim

o kaldırımlardan.

Biliyorum her geçişimde, 

içimde yeniden yeşerecek geçmişin o acı izleri

ve diyorum ki; 

bu sefer son, son bulacak! ....', 'Kaldırımlar, adım adım eziliyor, yavaşça geçiliyor,  ama hiç kimse bilmiyor,  buradan geçenler sadece adımlarını değil umutlarını bırakıyor....', ARRAY['Türk Edebiyatı','Şiir','Levent Keskin']::text[], 8.5, '{"poet":"Levent Keskin","poet_slug":"levent-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kaldirimlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLSEM...!', 'olsem-sair-yasef-rgcau', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dayanamıyorum bu karanlıklara sensiz! 

Kolay olur ölsem, 

Zaman durur, 

Sensizlik de son bulur o zaman! 

Ve ben mezarımda, 

Ruhumda ise hala sen sevdiğim!', 'Dayanamıyorum bu karanlıklara sensiz!  Kolay olur ölsem,  Zaman durur,  Sensizlik de son bulur o zaman!  Ve ben mezarımda,  Ruhumda ise hala...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olsem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yitik cesaret', 'yitik-cesaret-faruk-elma-mupm7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'cesaretim kalmadı  gözlerine bakmaya

gözlerimde manzara kayboldu

tatlı gülüş bir edayla dokunuş

sana bakabilmek yürek isterdi

sana görünmek daha da zordu

hediye getirmek duygusal olmaktı

yağmurlu ve kurak bakışların vardı

sana ihtiyaç duyulan ama 

yinede mahsun bakışların vardı', 'cesaretim kalmadı  gözlerine bakmaya gözlerimde manzara kayboldu tatlı gülüş bir edayla dokunuş sana bakabilmek yürek isterdi sana görünmek ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yitik-cesaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyva Sepeti', 'meyva-sepeti-levent-keskin-c7c8u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ortada karışık bir meyva sepeti, 

Sepetteki meyvalarmı beni düşündüren

Yoksa baktıkça bakası gelen o dayanılmaz güzelliğimi? 

Güzelliğimidir beni benden götüren, 

Lezettimidir o unutulmazı veren, 

Bilirsin kalır tadı damağımızda

ama hiç aklından gitmez lezzeti.

Neden güzelliği aklımızda kalmaz tadı gibi

Neden her güzelliği bitiririz bir daha yaşanmıyacakmış gibi.', 'Ortada karışık bir meyva sepeti,  Sepetteki meyvalarmı beni düşündüren Yoksa baktıkça bakası gelen o dayanılmaz güzelliğimi?  Güzelliğimidir...', ARRAY['Türk Edebiyatı','Şiir','Levent Keskin']::text[], 8.5, '{"poet":"Levent Keskin","poet_slug":"levent-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/meyva-sepeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seni seviyorum', 'seni-seviyorum-faruk-elma-p65n0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni seyrederdim uzak odamda

hayal ederken görürdüm yüzünü

seni anlaşılmaz ve tuhaf gösteren

o çıplak ve sahipsiz sevgin 

sana bakıp ölümcül bir üzüntüye kapılırdım 

ben gözümü senden hiç ayırmadım

anla artık seni seviyorum 

kendimi yalnız bırakamıyorum

 içimde günledir tek başına bırakılmış

tek taraflı aşk acısı var

bu gidişin bence bir ölüm gibi

dokunmak istedikçe uzaklaşmak

sahip olacağım yerde kaybetmek

neden bu kadar seni anlamak

hep bir şeyler gizlemek

sen seviyordum 

ta ki......', 'seni seyrederdim uzak odamda hayal ederken görürdüm yüzünü seni anlaşılmaz ve tuhaf gösteren o çıplak ve sahipsiz sevgin  sana bakıp ölümcül...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-seviyorum-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözlü Bunalım İMTİHANI', 'sozlu-bunalim-i-mti-hani-fulya-ertur-visqd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün yine mutsuzum, 

Sinirimi yüzümden çıkarıyorum

Gözlerim kan çanağı

Boğuyor göz yaşları

Bir ben anlamıyorum, bir de ben

Zaten kimse bilmiyor

Ancak gözlerim anlıyor

Ağlıyor.

Düşünmek yeter mi çözmek için dertleri? 

Ya elinde kalem, kağıt anlamsız bir şiir yazmak mı? 

Yağmur tanelerini izlemek mi sabaha karşı? 

Tarayıp durmak mı bezgin saçlarını? 

Yardım istemek birilerinden

Kirli veya temiz bir el uzanmasını beklemek, 

Kimsenin yardımı olmayacağını bilerek

Haricinde, kendinden.

Yapraklarını kirletmek defteriin, 

Pis havadan bir soluk almak içten, derin

Gözlerini kapamak hayata, 

Faydası ancak bir dakika

Ölsem akşama doğru, 

Yok en iyisi gece yarısı, 

Kıvranmamı, son soluğumu

Kimse duymamalı

Sızlarken kalbim

Vururken beynime acısı, 

Her yerimi sarar, üşürüm, titrerim

Ne fark eder ki

Kimsenin umrunda değilim.', 'Bugün yine mutsuzum,  Sinirimi yüzümden çıkarıyorum Gözlerim kan çanağı Boğuyor göz yaşları Bir ben anlamıyorum, bir de ben Zaten kimse bilm...', ARRAY['Türk Edebiyatı','Şiir','Fulya Ertür']::text[], 8.5, '{"poet":"Fulya Ertür","poet_slug":"fulya-ertur","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sozlu-bunalim-imtihani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasandra Yokuşu', 'kasandra-yokusu-levent-keskin-nxzd6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolları aşındırmak bitirmiyor geçmişi, 

Hırçın rüzgarlar dindirmiyor gerçeği, 

Kavakların fısıltısı vuruyor üzerine, 

Ürperiyor nedendir birden, 

Geçmişin izleri belirdi yine

Kasandra yokuşunu getirdi önüne.

Ezdiği gülümüydü veremediği biricik aşkına, 

Geçtiği yollardan beklemek o güzel yüzünü, 

Ümidi beslemeliydi bu yüce gücü, 

Aşkı çağırdı onu bu yola, 

Kasandra Yokuşuna!', 'Yolları aşındırmak bitirmiyor geçmişi,  Hırçın rüzgarlar dindirmiyor gerçeği,  Kavakların fısıltısı vuruyor üzerine,  Ürperiyor nedendir bir...', ARRAY['Türk Edebiyatı','Şiir','Levent Keskin']::text[], 8.5, '{"poet":"Levent Keskin","poet_slug":"levent-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kasandra-yokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'her sabah', 'her-sabah-faruk-elma-rwwnt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her sabah aynı şey 

seni bulamamak yatakta

her sabah aynı şarkı

çınlıyor kulaklarımda

her sabah aynı yalnızlık

yatağa yorgana sarılıyorum

her sabah  aynı alışkanlık

ve küçüçük bir yalan akıllarda 

zaten yoktun', 'her sabah aynı şey  seni bulamamak yatakta her sabah aynı şarkı çınlıyor kulaklarımda her sabah aynı yalnızlık yatağa yorgana sarılıyorum he...', ARRAY['Türk Edebiyatı','Şiir','Faruk Elma']::text[], 8.5, '{"poet":"Faruk Elma","poet_slug":"faruk-elma","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/her-sabah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birkaç Anının Hakimiyetine Sunuyorum', 'birkac-aninin-hakimiyetine-sunuyorum-barbaros-mustafa-guner-fnwyh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yemin törenleri düzenliyor ilkokul talebeleri.

İlk teslimiyet noktasında kıyıya vuruyor keşif tadında

mutlu sesler.

Ve ben mavi sen pembe ile varoluşunu taşıyorsun

cüzdanında ve günahların daha ağır oluyor

                                                         renklerin aşkına...

Ama ilk defa masa örtünü yıkamadan getiriyorsun

ve suçunu sıraya kazıyorsun bir gölge anında, 

iki arka sıranda oturan Selvinihal adlı

                                                          sarı saçın aşkına...

Hiç te öyle basite almayın he, 

bi ebelemeç molasına devam ediyor uğrunda kavgalar, 

önlükler yırtılıyor.

Ama Atatürk büstü işini iyi biliyor.

Arkasında komalık aşkları seruma mahkum bakışlarıyla beraber saklıyor....

Ama şimdi söyleyin bana, 

kim koyuyor bu 2x2 nin ilk dörtlüğünü

şu Selvinihal adlı kızın sarı saçlarına 

kurduğum hayalin tam ortasına...', 'Yemin törenleri düzenliyor ilkokul talebeleri. İlk teslimiyet noktasında kıyıya vuruyor keşif tadında mutlu sesler. Ve ben mavi sen pembe il...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Mustafa Güner']::text[], 8.5, '{"poet":"Barbaros Mustafa Güner","poet_slug":"barbaros-mustafa-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/birkac-aninin-hakimiyetine-sunuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilim', 'kilim-fatih-kisaparmak-hzahq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdiğine sözü olan bir kilim dokur

Kilimin dilinden ancak anlayan okur

Sırlarımı verdim sana sevgimi verdim

Şu gönlümü kilim yaptım yoluna serdim

Ayıptır günahtır diye

Kilit vurdular dilime

Aşkı dokudum kilime 

Anlıyor musun

Yetinmedim türkü yaktım 

Gayrı bu canımdan bıktım 

Hani senin olacaktım

Dinliyormusun

Kilim kalpin aynasıdır gönlün sesidir

Her nakışı bir duygunun ifadesidir

Kilim sevgiliye cağrı aşka davettir

Kimi renkler şikayettir kimi hasrettir

Ben şu gönül dergahında aşkı okudum

Kilim yare mektupumdur arzıhalimdir

Her nakışı bir kelime kalem elimdir

Elin değmedi elime

İsmin dolandı dilime

Aşkı dokudum kilime

Anlı yormusun

Yetinmedim türkü yaktım

Gayrı bu canımdan bıktım

Hani senin olacaktım

Dinliyor musun...', 'Sevdiğine sözü olan bir kilim dokur Kilimin dilinden ancak anlayan okur Sırlarımı verdim sana sevgimi verdim Şu gönlümü kilim yaptım yoluna ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kısaparmak']::text[], 8.5, '{"poet":"Fatih Kısaparmak","poet_slug":"fatih-kisaparmak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kilim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin... (Tuğba''ya)', 'senin-i-cin-tugba-ya-zeynel-gurdal-7rjkn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tuğba''ya...

Bir gece, 

Gecede bir uyku..

Uykunun icinde ben..

Uyuyorum, 

Uykudayim, 

Yanimda sen.

Uykunun icinde bir ruya, 

Ruyamda bir gece, 

Gecede ben..

Bir yere gidiyorum, 

Delice..

aklimda sen.

Ben seni seviyorum, 

Gizlice..

El-pence duruyorum, 

Yuzune bakiyorum, 

Soylemeden, 

Tek hece.

Seni yitiriyorum

Cok karanlik bir anda..

Birden uyaniyorum, 

Bakiyorum aydinlik; 

Uyuyorsun yanimda..

Guzelce.

(μ - 10.10.1993) 

                            (μ - 10.10.1993)', 'Tuğba''ya... Bir gece,  Gecede bir uyku.. Uykunun icinde ben.. Uyuyorum,  Uykudayim,  Yanimda sen. Uykunun icinde bir ruya,  Ruyamda bir gece...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Gürdal']::text[], 8.5, '{"poet":"Zeynel Gürdal","poet_slug":"zeynel-gurdal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/senin-icin-tugba-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı Bebe', 'nazli-bebe-fatih-kisaparmak-2vgxi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toros yaylaları buzlu ayazlı

Üşür Nazlı bebe solgun benizli

Yüzüne baktıkça Nazlı bebenin

Ağlar Elif kadın hep gizli gizli

Kalktı göç eyledi Türkmen obası 

Elifin`in sırtında Nazlı bebesi

Fransız harbinde Yörük elinde

Sırtından vuruldu yiğit babası

Dağların kuytuluk tenha yerinde

Gavurdağları`nın mor segerinde

Göz pınarlarında iki damla yaş

Yağlı kurşun durur ciğerlerinde

Sus ağlama Nazlı bebe

Zaten ağlatacaklar

Baban nasıl şehit oldu 

Bir gün anlatacaklar

Dayan Elif kadın dayan 

Kara gündür gececek

Sabrın çiçekleri er geç 

Filizlenip açacak

Nazlı kız Elif`in aşk tomurcuğu

Şehir Mustafa`nın en son cocuğu

Elinde katıksız bir kuru ekmek 

Başı boydan boya nazar bonçuğu

Yavru ceylan gibi ürkek bakışlı

Yay gibi kaşları hilal nakışlı

Babası görseydi öper koklardı

Kınalı saçları çiğdem kokuşlu

Sus ağlama Nazlı bebe

Zaten ağlatacaklar

Baban nasıl şehit oldu 

Bir gün anlatacaklar

Dayan Elir kadın dayan 

Kara gündür gececek

Sabrın çiçekleri er geç 

Filizlenip açacak', 'Toros yaylaları buzlu ayazlı Üşür Nazlı bebe solgun benizli Yüzüne baktıkça Nazlı bebenin Ağlar Elif kadın hep gizli gizli Kalktı göç eyledi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kısaparmak']::text[], 8.5, '{"poet":"Fatih Kısaparmak","poet_slug":"fatih-kisaparmak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/nazli-bebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ya)', 'ya-zeynel-gurdal-qsy9m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gece, 

Gecede bir uyku..

Uykunun icinde ben..

Uyuyorum, 

Bir gece, 

Gecede bir uyku..

Uykunun icinde ben..

Uyuyorum, 

Bir gece, 

Gecede bir uyku..

Uykunun icinde ben..

Uyuyorum, 

Bir gece, 

Gecede bir uyku..

Uykunun icinde ben..

Uyuyorum, 

μ - 10.10.1993

&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; μ - 10.10.1993', 'Bir gece,  Gecede bir uyku.. Uykunun icinde ben.. Uyuyorum,  Bir gece,  Gecede bir uyku.. Uykunun icinde ben.. Uyuyorum,  Bir gece,  Gecede ...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Gürdal']::text[], 8.5, '{"poet":"Zeynel Gürdal","poet_slug":"zeynel-gurdal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ya-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarına Kaç Var', 'yarina-kac-var-fatih-kisaparmak-1ss98', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelmiş gecmiş türkülerin ilk sözü sensin

Vazgecemiyorum senden tütün gibisin

Ekmeği ikiye beraber böldük

Birlikte ağladık birlikte güldük

Yıllar girdi aramıza

          Birlikte öldük

Geceden sonra sabah

Her kıştan sonra ilkbahar

Yarına kaç var çocuklar

Ne olur söyle benim mi bu titreyen el

Yalvarırım şimdi gitte yıllarca önce gel

Ellerim elini nerden tanıyor

Yaklaştıkca sabah gece utanıyor

Bir pembe yağmur altında

            Aşk ıslanıyor', 'Gelmiş gecmiş türkülerin ilk sözü sensin Vazgecemiyorum senden tütün gibisin Ekmeği ikiye beraber böldük Birlikte ağladık birlikte güldük Yı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kısaparmak']::text[], 8.5, '{"poet":"Fatih Kısaparmak","poet_slug":"fatih-kisaparmak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yarina-kac-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Biz Uyandırdık', 'gunesi-biz-uyandirdik-fatih-kisaparmak-kja51', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güller kelepçeli çiğdemler tutsak

Aysız gecelerde kanar öfkemiz

Düşlerde sevişsek el ele tutsak

Dilsiz duvarlara siner öfkemiz

Şafak sancıları var kulaklarımda 

Yarınların ninnisi bozlaklarımda 

Bir türkü çıldırır dudaklarımda 

Çiçekli dallara döner öfkemiz

     Güneşi biz uyandırdık 

     Yıldızların yerine

     Sesimizi yorgan yaptık

     Umut türkülerine

Alnımızda çizgiler belirmiş derler

Gelirse üst üste gelirmiş derler

Çıksak şu dağlara delirmiş derler

Haykırsak belki de diner öfkemiz

Varmışız hayatın buruk tadına

Ne aşka muhtacız ne de kadına

Yangınla seviştik ışık adına

Alevler içinde söner öfkemiz', 'Güller kelepçeli çiğdemler tutsak Aysız gecelerde kanar öfkemiz Düşlerde sevişsek el ele tutsak Dilsiz duvarlara siner öfkemiz Şafak sancıla...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kısaparmak']::text[], 8.5, '{"poet":"Fatih Kısaparmak","poet_slug":"fatih-kisaparmak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunesi-biz-uyandirdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günün Birinde', 'gunun-birinde-fatih-cinar-k3xo0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'büyük bir fırça getirin bana

bütün gökyüzünü boyayacağım

yağmurlu bulutların girip kanına

beyaz yıldızlarla dost olacağım

gönlümdeki kederi sileceğim dağlardaki karla

karatoprağın beyaz bereketiyle donatacağım soframı

hasretin tahtasından yapılmış beyaz bir salla

yaracağım engin denizleri okyanusları

tüm acı günleri saklayacağım yamalı ceplerimde

ağlatacağım gurbetin gülümseyen uğursuzluğunu

elimde kirbitle değil alev alev çehremle

yakacağım vuslatın kandilini mumunu

dostlarla birlikte içeceğim neşenin şerbetini

diz vuracağım toprağa heybetli zeybeklerle

sileceğim defterden düşmanıma kinimi

kolkola gireceğiz şarkılarla türkülerle

gülümseyeceğim yine gurbetin tozundan silkinerek

yüzeceğim sılanın deli çağlayan nehrinde

dağlardan zalim azraile seslenerek

can vereceğim annemin mübarek ellerinde', 'büyük bir fırça getirin bana bütün gökyüzünü boyayacağım yağmurlu bulutların girip kanına beyaz yıldızlarla dost olacağım gönlümdeki kederi ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunun-birinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Umudum Sensin', 'tek-umudum-sensin-fatih-cinar-go4oi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şimdi yıldızlara bakıyorum

o günleri anıyorum ağlıyorum

biliyorum o günler geri gelmeyecek

küçük yaralı bir kuşun çırpınışları gibi

çırpınıyorum haykırmak istiyorum

yapamıyorum

kollarına al beni

teselli et

tek umudum sensin

ve sensin beni dinleyecek', 'şimdi yıldızlara bakıyorum o günleri anıyorum ağlıyorum biliyorum o günler geri gelmeyecek küçük yaralı bir kuşun çırpınışları gibi çırpınıy...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tek-umudum-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaçlar Ayakta Ölür', 'agaclar-ayakta-olur-fatih-kisaparmak-pph8u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün gelir bunları da unutursun

Gün gelir gözyaşını kurutursun

Gün gelir bunları da unutursun

Gün gelir yüreğini avutursun

Zamanla öyle değişirki insan 

Gün gelir ateşini soğutursun

Ağlama yaşamak kumar olsada

Ağlama seni vuran yar yar olsada 

Ağlama mevsim sonbahar olsada

    Ağaclar ayakta ölür

Ağlama seni vuran yar olsada 

Ağlama saclarında kar olsada 

Ağlama yaşamak kumar olsada

     Ağaclar ayakta ölür

Şimdiki aklınla yeniden başlaya bilseydin herşeye 

Pişmanlıkların olmazdı bugüngü kadar

Doya doya gülmeleri zaten unuttun

       Ve sevmeleri

       Ve sevilmeleri

Seneler nasıl da su gibi aktı 

Hatırası bile öyle uzak ki

Başını koyupta bir omuza

Güzel şeyleri duymayalı cok oldu

        Lanet olsun

Varsın kimseler bilmesin hayatta mısın

Ah``Bu şarkıların gözü kör olsun``

Gün gelir hayata yine doğarsın

Gün gelir kahrolduğuna yanarsın

Gün gelir hayata yine doğarsın

Gün gelir üzüldüğüne yanarsın

Yüzünde acı bir gülümseyişle

Anarsın geçmiş günleri anarsın

Ağlama seni vuran yar olsa da

Ağlama saçlarında kar olsa da

Ağlama yaşamak kumar olsa da

     Ağaclar ayakta ölür

Ağlama seni vuran yar olsa da 

Ağlama buraya kadar olsa da

Ağlama sonu intihar olsa da

     AĞAÇLAR AYAKTA ÖLÜR', 'Gün gelir bunları da unutursun Gün gelir gözyaşını kurutursun Gün gelir bunları da unutursun Gün gelir yüreğini avutursun Zamanla öyle değiş...', ARRAY['Türk Edebiyatı','Şiir','Fatih Kısaparmak']::text[], 8.5, '{"poet":"Fatih Kısaparmak","poet_slug":"fatih-kisaparmak","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/agaclar-ayakta-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar Yolumu Kesti', 'aynalar-yolumu-kesti-fatih-cinar-yt4fk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'siyahlar benden uçup gitti

saçlarım kar beyaz oldu

kırılırdı aynalar güzelliğimden

şimdi yüzüm sararıp soldu

hüzzamlar bana kaldı

yalnızlık bana kaldı

iyi günümde çalan kapılar

şimdi yüzüme kapandı

şimdi çıkamam yollara

aynalar zindan

şimdi bakamam aynalara

aynada vicdan

beni beklemeyin o bir hevesti

gelemem aynalar yolmu kesti

aynalar bakmayın yüzüme dik dik

işte yakalandık kelepçelendik

çıktınız umulmaz anda karşıma

başımın tokmağı indi başıma

suratımda her suç bir ayrı imza

benmişim kendime en büyük ceza

şiir: necip fazıl kısakürek

söz.müzik: fatih çınar', 'siyahlar benden uçup gitti saçlarım kar beyaz oldu kırılırdı aynalar güzelliğimden şimdi yüzüm sararıp soldu hüzzamlar bana kaldı yalnızlık ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aynalar-yolumu-kesti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL SONU NOTU', 'yol-sonu-notu-huseyin-aktas-rsb93', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'koza yırtılıyor

sesin acı melodisiyle

yavaş yavaş hüzünle

esrarengiz dağlar 

şimdi ufka bakan gözlerde

mustarip makber düşü yok 

lakin henüz 

fakat girmişpatikanın menziline

kayan ay ve güneş bilinmez neden

şimdi ufukta bilinmezin serabı 

birde merakın serin sabahı

yanan abad ateş sorunsuz

mutlu güleç keza yaşam dolu umutlu

ab-ı hayat kaynıyor 

ancak hayalin ilk fasıl son nefesine dek

bir gün yeni bir dönemeç

sorular çok ama pek çok 

bir ağaca bir taşa patikaya 

sorular şimdi geçmiş ufka

esasen

o ufka bakan gözlerin 

şimdiki doğan yaşlarına

neden sorusunun yanıtı yok ortalıkta

öyle bir anki anın komedisi

mustarip makber şakacı

komik görünüşlü şimdi

neden sorusu yok unutulmuş

artık gözler sukun içinde

son faslın son nefesini dayanmış..', 'koza yırtılıyor sesin acı melodisiyle yavaş yavaş hüzünle esrarengiz dağlar  şimdi ufka bakan gözlerde mustarip makber düşü yok  lakin henüz...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Aktaş']::text[], 8.5, '{"poet":"Hüseyin Aktaş","poet_slug":"huseyin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yol-sonu-notu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hostes Aşkım', 'hostes-askim-fatih-cinar-0qjo8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sana bir görüşte kalbim aktı

ellerim ayaklarım dolaştı

ruhumu bir alev sardı

otobüsteki hostes aşkım

iyiki binmişim bu otobüse

bu otobüs bizi aşka götürse

ya seni sevdiğimi herkes bilirse

otobüsteki hostes aşkım

otobüs şehirler geçiyor

molalarda benzin içiyor

bilsen içimden neler geçiyor

otobüsteki hostes aşkım

şimdi bir su getir bana

içeyim elinden kana kana

sevdiğini söyle bana

otobüsteki hostes aşkım

terminale geldik ne çare

ayrılacağız biz biçare

keşke otobüs hiç durmadan gitse

otobüsteki hostes aşkım', 'sana bir görüşte kalbim aktı ellerim ayaklarım dolaştı ruhumu bir alev sardı otobüsteki hostes aşkım iyiki binmişim bu otobüse bu otobüs biz...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hostes-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SICAK', 'sicak-yavuz-turhan-udx1t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretime sarılmak isteyeceksin, 

gecenin bir vaktinde....soğukta....

        Tutunamayacaksın yüreğime.

         Yüreğini ısıtacak, 

sıcak bir nefesim olmayacak, 

pencerenden yüzüne vuran rüzgarda...

        Bir yıldız misali uzaktan seveceksin.

        Yüreğinde olacağım, 

dokunamayacaksın...', 'Hasretime sarılmak isteyeceksin,  gecenin bir vaktinde....soğukta....         Tutunamayacaksın yüreğime.          Yüreğini ısıtacak,  sıcak ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sicak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Çıkıyor', 'sana-cikiyor-fatih-cinar-xpmz8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her köşe başında hayalin gölgen

gitmedi gitmiyor gözlerimden

sokaklar ıssız caddeler sessiz

şehirde bir ben bir ben kimsesiz

sana çıkıyor bu şehin bütün yolları

beni vuruyor hasretin yağlı kurşunları

sana çıkıyor bu şehrin bütün yolları

beni sarıyor gurbetin zalim kolları

gelde bana sor ayrılığın tadını

hiç unutulmaz sensizliğin adını

sokaklar ıslak saçlarımda ak

şehirde bir ben bir ben yalınayak

müzik: fatih çınar', 'her köşe başında hayalin gölgen gitmedi gitmiyor gözlerimden sokaklar ıssız caddeler sessiz şehirde bir ben bir ben kimsesiz sana çıkıyor bu...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-cikiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerindeki Çocuk', 'gozlerindeki-cocuk-mustafa-sarpkaya-gts3q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son sigaramdı belkide 

Son çekişim seni içime 

Son tutiyamdı belikide 

Son sürüşüm seni saçıma 

Bu son gidişin bir manası vardı elbet 

Bakıyordu gözlerin 

Dalıyordu gözlerime 

Ve yakıyordu gözlerin 

Kalıyordu sözlerime 

Hüzünlü çekip içini 

Bakma öyle der gibi 

Bakıyordu gözlerin 

Bakıyordu gözlerime 

Sessiz bir çocuk oturuyordu gözlerinde 

Ses saymazsak hıçkırığı 

Sen değildin ağlayan 

Ağlıyordu çocuk gözlerinde 

Ellerime düştü ıslak 

Sen sandım başında 

Ne sendin düşen ne yağmur 

Oturan çocuktı gözlerinde 

Belki sendin belkide ben 

Ya sendeki ben ya da bendeki sen 

Ama aslolan çocuktu 

Ve düşüyordu gözlerinden 

Yalvarıyordu gözlerini 

Açma diye kirpiğini 

Korkuyordu düşmekten 

Korkuyordu gözlerinden 

Göz kalmadı gözlerinde 

Giz kalmadı yüreğimde 

Döküldü iki damla yaş 

Ve süzüldü güzlerinden 

Islanmıştı küçük çocuk 

Düşen damlayla yanakta 

Bir umut arıyordu belkide 

Fer kalmayan gözlerinde 

Belki bendim belkide sen 

Ne bendeki ben ne de sendeki sen 

Aslolan çocuktu zaten 

Ki düşmüştü gözlerinden', 'Son sigaramdı belkide  Son çekişim seni içime  Son tutiyamdı belikide  Son sürüşüm seni saçıma  Bu son gidişin bir manası vardı elbet  Bakıy...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gozlerindeki-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlahi Azrayil', 'i-lahi-azrayil-mustafa-sarpkaya-wfdth', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlahi azrayil sen adamı öldürürsün

Bazen ağlatır bazen de güldürürsün

Diyemiyorum

Çünkü hep öldürürsün

Kimi kandırayım güldürmezsin ki

Yalan mı? 

Bir cansız beden arta

Kalan mı? 

Geçici dünya bir dert salan mı? 

Salman mı? 

Gül olsan susuz toprakta solan mı? 

Solman mı? 

Yalan değil tabi cansız beden arta 

Kalan

Geçici dünya bir değil bin dert zevkleri 

Yalan

Susuz toprakta bir değil bin gül

Solan

İlahi azrail biliyorum sensin canımı 

Alan!', 'İlahi azrayil sen adamı öldürürsün Bazen ağlatır bazen de güldürürsün Diyemiyorum Çünkü hep öldürürsün Kimi kandırayım güldürmezsin ki Yalan...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ilahi-azrayil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olursun Gitme', 'ne-olursun-gitme-emel-cengiz-jlckg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne olursun gitme

Sensiz olmaya hiç hazır değilim

Deli olurum yokluğunda

Felç olur sensizlikte bedenim

Serseri mayın gibi dökülürüm yollara

Çaresizlikler çoğalır arka arkaya

Kahrolurum, yok olurum uzağında

Aşksız, sevgisiz akşamların tuzağında

Umutlarımı besleyip, cesaretlendirdim günlerce

Öpücüklere boğarım geldiğinde binlerce

Ne olursun gitme

Uzun yollar girmesin aramıza

Gönlünde yaşamak istiyorum korkusuzca

Bütün çiçekler sen kokuyor

Baharlara yokluğunda itirazım var

İsyanım var sensiz akşamlara

Yokluğunda ruhum gece gibi kapkara

Atamıyorum kafamdan senli düşleri

Kaçıncı kez söylüyorum bilmiyorum

Sevgi dolu, sen dolu heceleri

Kokunu özlüyorum, seni özlüyorum

Olmadığın yollara terketme beni

Bugün ayrılıktan sakın bahsetme

Ne olursun gitme.', 'Ne olursun gitme Sensiz olmaya hiç hazır değilim Deli olurum yokluğunda Felç olur sensizlikte bedenim Serseri mayın gibi dökülürüm yollara Ç...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-olursun-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Şiirler Yazdım', 'sana-siirler-yazdim-mustafa-sarpkaya-uo5v4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana şiirler yazdım bir geceyarısı 

Yazdım! sana şiirler yazdığımda bir geceyarısı 

Kış geldi soğudu kalbimin bir yarısı 

Ben yine yazdım! Sana şiirleri bir geceyarısı 

Sonbahara yeltenirken gönlümün güzayazı 

Yapraklar savrulur kalbimin tenhalarında 

Soğukcasına esti rüzgar engelimdi benim 

Yazdım! Sana şiirler bir geceyarısı 

Sen yağmuruydun kurak kışımın 

Damlası göl olan her gözyaşımın 

Seni rüzgarı sanarken her kıpırdanışında saçımın 

Yazdım! Sana şiirler bir geceyarısı 

İlkbaharıydı en güzel mevsimi gönlümün 

Çiçekler açtı, kuşlar uçtu yine yazdım 

Esince sıcak rüzgar sandılar değişti mevsim 

Ama ben yazdım! Sana şiirler bir geceyarısı', 'Sana şiirler yazdım bir geceyarısı  Yazdım! sana şiirler yazdığımda bir geceyarısı  Kış geldi soğudu kalbimin bir yarısı  Ben yine yazdım! S...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-siirler-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerpe''nin Köpre Duyguları', 'kerpe-nin-kopre-duygulari-emel-cengiz-1fawv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duyguların doruğunda seyrettim denizi

Seni özledim guruba dalarken

Kilometrelerce mavi çarşaflar içinde

Sevdim seni, seviştim hayalinle

Aşk şarkılarının ne olduğunu düşünmedim

Tümünü söylüyordu hışırtılarıyla deniz

Tutkunun ne olduğunu bana bedelle ödettiniz

Seninle seyretmeliydim güneşin doğuşunu

Kollarında dinlemeliydim dalgaların sesini

Mehtap pırıl pırıldı masum sevdam gibi

Yokluğunun ayazları bedenime indi

Zevk vermedi bunca güzellik

Tenimi okşaman kadar

Yanımda olmadın, olamadın

Çılgın olmama bir sürü sebep var

Kerpe''de açıldı ruhum enginlere

Direndi güneş batmamak için

Sevgililer sarhoşlamış, manzara seyrederken

Özlemim büyüdü yokluğuna kahırlarla

Olsaydın yanımda dev kayalar gibi

Seyretseydin denizin kayalara sevgisini

Her vuruşu benzettim bir bir konan buseye

Erimiş de tükenmemiş, mutluydu kayalar yine de

Koynunda olmayı arzuladım, herşeyden arınmış

Denize sevdam, sana sevdam gibi köz olmamış

Daldım ufkun ötesinde kalmış varlığına

Çıldırmak üzereydim Kerpe''de yokluğunla

Seni düşledim, denizi seyrettim

Hasret şarkılarını söylerken kayalarda

Doyumsuz zevkini yaşayamadım doğanın

Gün ağardı, zaman kısaldı, gündönümü başladı

Güneş heryeri ısıttı, gönlümün dışında

Özdeşleştirdim kendi özümde ikinizi

Bir seni böyle sevdim bir de denizi.', 'Duyguların doruğunda seyrettim denizi Seni özledim guruba dalarken Kilometrelerce mavi çarşaflar içinde Sevdim seni, seviştim hayalinle Aşk ...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kerpe-nin-kopre-duygulari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşımdın', 'arkadasimdin-muhtesem-oksel-h2s8k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adaleti yoktu aşkın.

Biçilmiş kaftandın.

Aslında, 

Ruhumun yarısıydın.

Gittin, o Lavuğa kapıldın.

Aman Yarabbi, 

Böylesine anlaşmak, 

İyi arkadaş olmak, 

Herşeyi paylaşmak, 

Canımız sıkıldığında, 

Hep birbirimizi bulmak, 

Dertlerimize çare olmak, 

Neticeten iyi arkadaş olmak.

Lanet olsun! 

Buydu sadece yaşanan, 

İyi arkadaş olmak.

Halâ da öyleyiz.

Adaleti yoktu aşkın.

Biçilmiş kaftandın.

Aslında, 

Ruhumun yarısıydın.

Gittin, o Lavuğa kapıldın.', 'Adaleti yoktu aşkın. Biçilmiş kaftandın. Aslında,  Ruhumun yarısıydın. Gittin, o Lavuğa kapıldın. Aman Yarabbi,  Böylesine anlaşmak,  İyi ar...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/arkadasimdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Oğlu', 'turk-oglu-fatih-cinar-hccb8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ekmek yediği ele ihanet eden

altında yaşadığı bayrağa küfreden

yüzüne güldüğü arkadaşa kin güden

namertler tanıdım türke yakışmaz

namertler tanıdım eşi bulunmaz

dikenler bir gün gül olacak elbet

ateşler sönüp kül olacak elbet

dağlar düze dönüp yol olacak elbet

sen türkün oğlu kendini bilirsen

şanlı bayrağını gökten indirmezsen

al kanlı toprağı namerde çiğnetmezsen

türk oğlu

paydos diyerek düne

türk oğlu

sünger çekerek kine

türk oğlu

özlenen o mutlu güne

varıyor namertler bekleyin hele

matem değil türke gülmek yaraşır

bilki yaşlı gözleri silmek yaraşır

zalimin kirini görmek

emeğin terini silmek

yoksulun zincirini kırmak yaraşır

dağlar doğudan batıdan

sedayla müjde verir

taşar türkün oğlu kabından

seller olur

çevirir kışı yaza

dağ olsada yolu

vatan çiçekleri

namluda açar barutta açar

namerdin cümlesi türkün önünde

bir köpek misali koşar

müzik: fatih çınar', 'ekmek yediği ele ihanet eden altında yaşadığı bayrağa küfreden yüzüne güldüğü arkadaşa kin güden namertler tanıdım türke yakışmaz namertler ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/turk-oglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Bugün', 'gitme-bugun-emel-cengiz-cja54', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni bırakıp gitme bugün

Sevgi sözcüklerini söyle arka arkaya

Hasret bırakma yüzüne, gözlerine

Ağlatma beni geçmişe geleceğe

Senin değilim diye mi bu kahır? 

Aşk mıdır ki bu denli ağlatır? 

Buseler kondurmak isterim yüzünün her yerine

Tenim teninde eriyip bitse de

Ben sevda şarkılarının kadınıyım

Aşkı yaşayanların hep yanındayım

Dağ çiçeği kardelenim kimi gün

Türküyüm, sevdalara söylenen

Çareyim; 

Köhne masalarda içilen içkiyim

Bir adım aşk, diğeri özlem

Sevgiyi ifadeyi pek beceremem

Söyleyemem gönlümden geçenleri

Keşfedilmeyi beklerim hep

Kapris yapmak isterim, nazlanırım

Küçücük mimiklerden de alınırım

İlgi beklerim, sıcaklık beklerim

Olmazları zamansız denerim

Akıl sır ermez, yüreğimin yürekliliğine

Heyecanları unutanlar beni bilmez

İsyan bayrakları açılır gönül teknemde yelken yerine

Sev beni, gör ruhumdaki fırtınaları

Sen başlattın bitmek bilmez kasırgaları

Sevgim gerçeklerin sesi oldu her gün

Ne olur beni bırakıp gitme bugün.', 'Beni bırakıp gitme bugün Sevgi sözcüklerini söyle arka arkaya Hasret bırakma yüzüne, gözlerine Ağlatma beni geçmişe geleceğe Senin değilim d...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gitme-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Doğarsa Bir Gün', 'gun-dogarsa-bir-gun-mustafa-sarpkaya-5edhq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şubat''tan günü ben çaldım bakma öyle 

Dil ucunda hece bırakma söyle 

Sevmedim de 

Sevmeseydim de 

Olmazdın şimdi yüreğimde 

Olur olmadık yerde dökülen 

Yaşımsın gözlerimde 

Ben doğmuşum güneş batmış 

Ay kaşlarını çatmış 

Dünyaya merhaba diyen yürek 

Nice gönüllere hüzün katmış 

Satmış anasını dünyanın 

Sonra gitmiş buzullara yatmış 

Bulut sandığı dumanları yüreğine katmış 

İşte o an gözlerimden dökülen yaşın 

Olur olmadık zamanıymış', 'Şubat''tan günü ben çaldım bakma öyle  Dil ucunda hece bırakma söyle  Sevmedim de  Sevmeseydim de  Olmazdın şimdi yüreğimde  Olur olmadık yer...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-dogarsa-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik Sevgili', 'platonik-sevgili-mustafa-sarpkaya-d4i08', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül yüzünde güller açar 

Dudağın gevher saçar 

Güller açan gül yüzün 

Ne ettim ki benden kaçar 

Saki sun ki zer tas ile 

Aşk şarabını şu gönlüme 

Tez sunasın ey saki 

Yoksa onu eller içer 

Sabah sultanı es yüzüme 

Değme ağlayan gözüme 

Ağlamaktan bir hal aldı 

Diyorsun ki gelir geçer 

Ey sevgili fanisin sen 

Ne olurdu bir yüz versen 

Yaprağından koklatmazsan 

Dikene bağrım konar göçer', 'Gül yüzünde güller açar  Dudağın gevher saçar  Güller açan gül yüzün  Ne ettim ki benden kaçar  Saki sun ki zer tas ile  Aşk şarabını şu gön...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/platonik-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü Yalnız Kalmasın Diye', 'gokyuzu-yalniz-kalmasin-diye-mustafa-sarpkaya-fzlbg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağarmakta gün dedikleri şey 

Gökyüzü loş mavi 

Mayhoş pembesi denizin ufkuyla buluşuyor 

Zirvesinde tek yıldız tek olmanın gururunu yaşıyor 

Eminim güneşe bile caka satıyor 

-Gördün mü ben de senin gibi tekim işte? diyor 

Sen de gördüysen eğer var demekki bir ortak yanımız 

Bak bulduk bile gördün mü? 

Şafak söküyor biz farkına bile varmazken 

Horozlar ötüyor kuşlar cıvıldaşmaya başlıyor 

Nedense hep dünyanın en muhteşem anı oluyor 

Karanlığın ağarması ve yıldızların güneşi çağırması 

Gökyüzü kutluyor bu muhteşem olayı 

Insanlar uykuda insanlar gafletteyken 

Tüm doğa bayram yerine dönüyor 

Doğal olduğumdan mıdır nedır? ben de katılıyorum onlara 

Bende kutluyorum güneşin esrarengiz doğuşunu 

Yıldızların hüzünlü yokoluşunu 

Altta mavi deniz üstte pembe şafak 

Sırayla sergiiyor gökyüzü yedi rengini 

Bir cümbüş mü bu nedir? 

Gözler kamai kamaş aklıllar yavaş yavaş farkına varıyor doğanın 

Her gecenin gündüzü oluyor bu sayfada 

Her gece doluyor bu sayfada 

Ve bu sayfa dolarken her gece insanlar hep uyuyor 

Bir ben uyumuyorum 

Gökyüzü yalnız kalmasın diye...', 'Ağarmakta gün dedikleri şey  Gökyüzü loş mavi  Mayhoş pembesi denizin ufkuyla buluşuyor  Zirvesinde tek yıldız tek olmanın gururunu yaşıyor ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gokyuzu-yalniz-kalmasin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanan Ben Olayım', 'kiskanan-ben-olayim-mustafa-sarpkaya-trs6n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koydum yıldızların terkesine 

Yazdığım bu ince satırları 

Serpssinler sen uyurken o sırma saçının tellerine 

Ve dokunsunlar yastığına benim yerime 

Uyuyordun! 

Sen mışıldın 

İkinci mışılsa ben 

Eğer gelseydi elimden 

Girerddim rüyana 

Kovardım düşlerini 

Bir ben görürdüm gülüşlerini 

Tutaardım ellerinden 

Uçardık gökyüzüne 

Sonra inerdik yeryüzüne 

Ben senin yüzüne 

Sen benim yüzüme hasret 

Vedalaşıp bir düzine 

Çıkardım rüya kapısından 

Girerdim yatağıma 

Ve sonra sorardım yıldızlara 

Gördünüz mü yarimi diye? 

Serptiniz mi ince satırlarımı sırma saçının tellerine? 

Dokundunuzmu yastığına benim yerime? 

Hoş beş içinde yıldızlaarla bugün de ağardı gün 

Güneş doğdu yine ve günaydın dedi sana 

O da gördü seni, o da konuştu seninle 

Bende bir sensizlik 

Ya sende sevdiğim 

Yıldız, ay, güneş gibi dostlar 

Üstelik her sabah günaydınlar 

Geceleri ay ve yıldızlar 

Sana yalnız kalmak mı? 

Yok be sevdiğim…. 

İsterdim ki yüreğine o güneş gibi ben doğayım 

İsterdim ki gecelerine yıldızlar gibi ben dolayım 

Yok yok böyle iyi 

Ben onları kıskanayım 

Kıskanan hep ben olayım…', 'Koydum yıldızların terkesine  Yazdığım bu ince satırları  Serpssinler sen uyurken o sırma saçının tellerine  Ve dokunsunlar yastığına benim ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kiskanan-ben-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-mustafa-sarpkaya-srwkp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hadi ben sevdim ağlamayı 

Bari sen gülümse 

Başaramadım sensiz olmayı 

Gülümsen gülümse 

Yaş aramadım gözlerinde hiç 

Benimsen gülümse 

Yaşaramayan gözlerimdeki 

Kanımsan gülümse 

Yapamadı ellerim sensiz 

Elimsen gülümse 

Kelebekmişim çiçeğimdeki 

Balımsan gülümse 

Serçeymişim konacağım 

Dalımsan gülümse 

Sensiz bir adaya düşmüşüm 

Salımsan gülümse', 'Hadi ben sevdim ağlamayı  Bari sen gülümse  Başaramadım sensiz olmayı  Gülümsen gülümse  Yaş aramadım gözlerinde hiç  Benimsen gülümse  Yaşa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulumse-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Mezar Olmadan Önce', 'sen-bana-mezar-olmadan-once-timur-dadaloglu-exzg2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir umudun türküleştirilmiş haline saklamıştım seni.

Her çagrışımda aşıklar olacagın belliydi.

Böyle umuyordum, böylebiliyordum.

Sen ona yar olmadan önce...

Bir gülün yapraklarına sarmıştım seni.

Umuyordumki her koklayışımda ordan çıkacak ve bana sarılacaktın.

Böyle bekliyordum böyle seviyordum seni.

Sen bülbüle diyar olmadan  önce.

Henüz bir çiçek açmış bir agaçtan farksız sevmiştim seni.

Senden bekledigim bir damla sevgiydi.

 Böyle istiyordum böyle biliyordum, 

Sen sevgime mezar olmadan önce.

Bir güvercin kadar hür hissadiyordum kendimi, 

Şimdi ise bir güvercin kadar yalnız! ! ! 

Hayallerimden başka birşey yok yanımda, 

Ve bıraktıgnı anılardan.

Herşey öyle yankılanırken beynimde, 

Sen gittin Anlıyormusun; 

^^Git-tin^^

Bir zamanlar ışık olan umutlarımıyıkıp gittin.

Bir zamanlar sadecessenin için sakladıgım sevgime; 

Son veripte gittin. 

Bir zamanlar sadece senin yer aldıgın düşüncelerimi; 

Katledip gittin.

Ne yapayım gittin işte gittin, 

Şimdi umutsuzum, şimdi ümitsizim! ! ! 

Artık ümit türkümü çagıramıyorum, 

Artık o gülü koklayamıyorum.

Artık seni sevemiyorum; 

Sen bana mezar olmadan önce...', 'Bir umudun türküleştirilmiş haline saklamıştım seni. Her çagrışımda aşıklar olacagın belliydi. Böyle umuyordum, böylebiliyordum. Sen ona yar...', ARRAY['Türk Edebiyatı','Şiir','Timur Dadaloğlu']::text[], 8.5, '{"poet":"Timur Dadaloğlu","poet_slug":"timur-dadaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-bana-mezar-olmadan-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarını Kim Melteme Benzetti', 'saclarini-kim-melteme-benzetti-ahmet-ozturk-9v45n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalabalıklara bodoslama dalman seni kör sevdalara itebilir

İtilmek ne kadar hor gelse de kör sevdalar zor gelir

Ve sen şuursuzca ağlasan da her acı da

Bir nokta belirir  yürek dediğin en bilinmez sığınağında

Elinden tutup ta seni kendi bilinmezinde hangi aşık dolaştırdı? 

Saçlarını kim melteme benzetti, gözlerini açan papatyalara

Sen yalnızlığını dost edinmişken bu yüreğe dost aramak niye? 

Yaralar kapanmadan yaralanmak niye

03: 57

14 Mayıs 2000 Pazar', 'Kalabalıklara bodoslama dalman seni kör sevdalara itebilir İtilmek ne kadar hor gelse de kör sevdalar zor gelir Ve sen şuursuzca ağlasan da ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/saclarini-kim-melteme-benzetti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yalnız Sana', 'ben-yalniz-sana-emel-cengiz-jtvof', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllanmış şarap gibi özlemim

Okyanuslar kadar derinleşmiş sevgim

Sen yaşamım, kendimce kurduğum evrenim

Yoksun ve ben yalnız sana hasretim

Sesini duyduğumda ruhum koynunda

Sarhoşlamış benliğim dudağında

Gönlümün en coşkulu sevgi çağında

Yoksun ve ben yalnız sana hasretim.

Gözlerim gözlerini arıyor hergün

Bitmek bilmiyor çaresizliğimdeki sürgün

Gel, mutlu et beni ne olur, bir gün

Yoksun ve ben yalnız sana hasretim

Çabalıyorum yokluğuna alışıp, yaşamaya

Hazır değilim başka yalancı baharlara

Aşkımın şahidiydi şarkılar, dökülürken yollara

Yoksun ve ben yalnız sana hasretim

Mutluluğu özümde yaşamayı istiyorum

Tükendim, sorgusuz, yargısız bekliyorum

Bırak artık gururu, seni çılgınca seviyorum

Yoksun ve ben yalnız sana hasretim.', 'Yıllanmış şarap gibi özlemim Okyanuslar kadar derinleşmiş sevgim Sen yaşamım, kendimce kurduğum evrenim Yoksun ve ben yalnız sana hasretim S...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-yalniz-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırmanın Bir Fecre Değeri', 'haykirmanin-bir-fecre-degeri-ahmet-ozturk-shi27', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sırtladım anı denen bu yüklü dolambaçları

Uzaklar gözlerimi kapatıp ellerimi havaya tırmandırıyor

Ben buraları buralar beni hiç sevmedi gibi

Gencim dedim ne sevdan acıdı ne buralar

Derim pul pul olmuş kanlı sevdan pıhtılaştıkça

Ve ısınamamak aşk ateşiyle törpülüyor kalbimi

Yaşadığım yerler de sen yoksun bilirim

Belki herkes yabancı, herkes yalancı

Ama o kükürtlü  gecelerde 

Yüreğimde zehir, ciğerlerimde kükürt vardı

Her yazdığım şiir seni bulmamalı 

Ve ilmiklememeli beynimi çıkmazdayken

Ömrünü boş yollara, boş sevdalara harcarken 

Korkularını herkeslerden saklarken 

Haykırmanın bir fecre değerini anlatmaya çalışıyordum

Anladım ki sen anlamıyorsun yar

Anladım ki bu yollar ayrı

Senden başkasını severim gayrı

16: 51

14 Mayıs 2000 Pazar', 'Sırtladım anı denen bu yüklü dolambaçları Uzaklar gözlerimi kapatıp ellerimi havaya tırmandırıyor Ben buraları buralar beni hiç sevmedi gibi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haykirmanin-bir-fecre-degeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanlı Sensizlik', 'i-syanli-sensizlik-emel-cengiz-e3c4t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir arzu içimde seninle olmak

Hasret rüzgarlarına inat

Seninle yatıp, seninle uyanmak

Bulutlar üzerinde sarhoş dolaşıp

Teninin kokusunu hep soluklamak

Eririm, yokolurum bakışlarında

Utanırım, söyleyemem aklımdakileri

Kahretsin! 

Yokluğunda deli oldum deli..

Duygular doruktayken

Fırtınalar kopuyor yüreğimde

Anlatamıyorum

İsyanımı yapayalnızlığımda yaşıyorum.

Seni bedenimde değil, ruhumda saklıyorum

Gelmen acılarımın sonu olurdu

İlacı olurdun, çaresiz dertlerimin

Yüreğimin sesi, son nefesim

Geleceğim misin bilemem, belki de ecelim

Sakin limanım, suskunluğum

Vazgeçilmez tutkum

Sevdalara sarhoş gecelerdeki vurgunum

Dağınık kafamda hayallerini kurduğum

Damarımdaki kanım

Hasretine yandığım

Anılarımda sakladığım

Sürgününü yaşadığım

Neredesin? 

Gel! 

Yokluğunda çıldıracağım.', 'Bir arzu içimde seninle olmak Hasret rüzgarlarına inat Seninle yatıp, seninle uyanmak Bulutlar üzerinde sarhoş dolaşıp Teninin kokusunu hep ...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/isyanli-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜMÜMDEN SONRA...', 'olumumden-sonra-sair-yasef-kpdnl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün başımı alıp gideceğim buralardan

Kalbimde sevdan, gözlerimde gözlerin.

Son defa gözyaşı dökecek gözlerim

Son defa tutacak ellerim kalemi şiir için

Son defa bakacağım anlamadığın bakışlarla

Ve çekip gideceğim buralardan...

Aynı günün gecesinde duyacaksın gidişimi

Ve anlam vermeye çalışacaksın yaptıklarıma...

Herşey şerit gibi gelecek gözlerinin önüne.

Neden diyeceksin kendine, 

Neden gitti diyeceksin...

Ve ilk kez, evet ilk kez 

Sitem edeceksin bana! 

Vedasız ayrılışım üzecek seni.

Canım sevdiğim! ! ! 

Bu ayrılık vaktinde; 

Sen her son verdiğim güzelliklere bin anlam vereceksin...

Bense uzaklarda da olsam, 

Ruhum erecek göklere...

Çünkü sevdiğim

Sen, sen değilsin artık! ...

Kalbinde sevgimin tohumları oluşacak, 

Ve gidişim anlam kazanacak! ! ! 

‘Sevmişti’ diyeceksin, 

‘Çok sevmişti’.....', 'Bir gün başımı alıp gideceğim buralardan Kalbimde sevdan, gözlerimde gözlerin. Son defa gözyaşı dökecek gözlerim Son defa tutacak ellerim ka...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olumumden-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BENİMLE SON BULMALISIN', 'beni-mle-son-bulmalisin-sair-yasef-01gn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana kalbimi veriyorum.

Sana emanet gözlerim.

Yaşamamı istiyorsan, sen nefes almalısın.

Susadıysam aşka, sevgini sermelisin.

Üşüyorsam, sarmalısın bedenimi.

Karanlık gecemde güneşim, 

Gündüzümde hayalim olmalısın.

Ellerimin uzandığı yerde olmalısın.

Uçurumun ucundaysam

Sımsıkı sarılmalısın bana.

Son nefesimi veriyorsam

BENİMLE SON BULMALISIN! ! ! ...', 'Sana kalbimi veriyorum. Sana emanet gözlerim. Yaşamamı istiyorsan, sen nefes almalısın. Susadıysam aşka, sevgini sermelisin. Üşüyorsam, sarm...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benimle-son-bulmalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HERŞEYİN HERŞEYİM', 'herseyi-n-herseyi-m-sair-yasef-y51re', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her gülüşün bir hüznüm 

Her bakışın bir yanışım 

Her seslenişin bir parçam

Her elvedan bir ölümüm', 'Her gülüşün bir hüznüm  Her bakışın bir yanışım  Her seslenişin bir parçam Her elvedan bir ölümüm...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/herseyin-herseyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİNE SENSİZİM', 'yi-ne-sensi-zi-m-sair-yasef-jyvr3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sabah yine sensiz uyandım

Gözlerim yine sensizliğe ağlamıştı geceden 

Ve sen yine yoktun

Yine anlamamıştın yaşlarımın sebebini

Ve sen yine sevmiyordun beni

Ve ben hala senle doluydum...', 'Bu sabah yine sensiz uyandım Gözlerim yine sensizliğe ağlamıştı geceden  Ve sen yine yoktun Yine anlamamıştın yaşlarımın sebebini Ve sen yin...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yine-sensizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN', 'sen-sair-yasef-kazva', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen her son verdiğim güzelliğin müsebbibi

Her uykusuz gecemde tek var olan yalnızlığımda

Her doğan günde bana nefes kadar yakın olansın', 'Sen her son verdiğim güzelliğin müsebbibi Her uykusuz gecemde tek var olan yalnızlığımda Her doğan günde bana nefes kadar yakın olansın...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sen-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ANLAYABİLİR MİSİN', 'anlayabi-li-r-mi-si-n-sair-yasef-hkha6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana itiraf etsem gözlerimle; 

Anlayabilir misin sevgimi? ! 

Nefesimdeki yorgunluğu hissedip; 

Anlayabilir misin acımı? ! 

Yüzümdeki hüznümü görüp; 

Anlayabilir misin sensizliğimi? !', 'Sana itiraf etsem gözlerimle;  Anlayabilir misin sevgimi? !  Nefesimdeki yorgunluğu hissedip;  Anlayabilir misin acımı? !  Yüzümdeki hüznümü...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlayabilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HİSSETMELİSİN', 'hi-ssetmeli-si-n-sair-yasef-8o6rh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkım sarmalı seni varlığımda...

Yokluğumda acı çekmelisin...

Kalsam da, gitsem de

Her an hissetmelisin beni yüreğinde! ! !', 'Aşkım sarmalı seni varlığımda... Yokluğumda acı çekmelisin... Kalsam da, gitsem de Her an hissetmelisin beni yüreğinde! ! !...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hissetmelisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HER YERDE SEN HERŞEYDE SEN', 'her-yerde-sen-herseyde-sen-sair-yasef-1dzyc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşe bakıyorum; 

Gözlerin diye, senin kadar parlak ve her sabah umut dolu...

Rüzgarı çekiyorum içime; 

Kokunu getirmiştir diye...

Yıldızları sayıyorum her gece; 

Aşkım da o kadar çok olsun diye...

Gökyüzüne uzanıyorum her korktuğumda; 

Ellerin beni yalnızlıktan kurtarsın diye...', 'Güneşe bakıyorum;  Gözlerin diye, senin kadar parlak ve her sabah umut dolu... Rüzgarı çekiyorum içime;  Kokunu getirmiştir diye... Yıldızla...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/her-yerde-sen-herseyde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN GİBİ', 'sen-gi-bi-sair-yasef-nquvw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni bekledim tüm gece –güneş gibi

Yalnızlığıma sarıldım –sen yoksun diye

Yıldızlara baktım doya doya –gözlerin misali

Geceyi dinledim –sen gibi', 'Seni bekledim tüm gece –güneş gibi Yalnızlığıma sarıldım –sen yoksun diye Yıldızlara baktım doya doya –gözlerin misali Geceyi dinledim –sen ...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimdeki Sevdama (Aşkıma)', 'yuregimdeki-sevdama-askima-emel-cengiz-wo6ip', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimden gelen sesle yakaladım seni

Özün iliklerime dek işledi

Ellerimi uzattım yakalamak adına mutluluğu

Sen oldun tutkulu sevdalarımın unutulmaz soluğu

Bir bir beynime kazıdım yüreğimdeki seni

İncitmiyordu gerçekte söylemek istediklerin beni

Aşmıştım kendime koyduğum yasakları

Düşüncelerinde bulmuştum senli yarınları

Seni senden arındırmak kaygısı taşımadan

Tek sen olmalıydın taptığım adam

Aşkım dediğinde coşku seline kapıldıysam

Olmazları sende bulup, sende demir attıysam

Bebeğim, senin yarınlarında endişeler taşıyorsam

Yokluğunu taşıyamayacağımı anladığımdan

Terin koktu bedenimde sevda çiçeği gibi

Rüzgarlarda soluk soluğa kalmışken

Bırakmak istedim kendimi sana korkusuz

Özgürlüğün sınırlarını zorlayıncaya dek

Sen türküleri severek dinle, ben seni

Uzakların rüzgarları üşütmesin artık bedenimi

Al kollarına sorgusuzca, yokolayım

Sar bedenimi, tutkularla çıldırayım

Şiir şiir bul ruhumdan, canımdan kelimeleri

Tempo tutsun çılgın arzular an gibi geçen zamana

Hesabı tutulmasın gündönümlerinin

Çünkü her gündönümünde tek parçayız

Bir yarım ben, diğer yarım sen

Öylesine işlemişsin ki iliklerime

Seni yaşıyorum, istemek ne kelime

Seni resmediyorum, beynimden bedenime

Geldiğinde bir tek SEN bulacaksın bende.', 'Yüreğimden gelen sesle yakaladım seni Özün iliklerime dek işledi Ellerimi uzattım yakalamak adına mutluluğu Sen oldun tutkulu sevdalarımın u...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yuregimdeki-sevdama-askima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem', 'birtanem-emel-cengiz-ywu3h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birtanem

Bilseydim sonsuzluklarda seninle yaşayacağımı

Mutluluktan havalara uçacağımı

Özgürce enginlere kanat açacağımı

Sarılıp bedenine çıldıracağımı

Hasretine yanmazdım.

Birtanem

Bilseydim hazanlara seninle varacağımı

Tutkuya dönüşen duyguların taşacağını

Duyulmamış aşk masallarını bana anlatacağını

Sustuğunda gözlerinin konuşacağını

Hasretine yanmazdım.

Birtanem

Bilseydim aydınlık yarınlara seninle koşacağımı

Közlenmiş ruhumun yeniden kor olacağını

Kocaman yüreğimin sevdana sarhoş yaşayacağını

Ve; buselerinde hep eriyip yokolacağımı

Hasretine yanmazdım.', 'Birtanem Bilseydim sonsuzluklarda seninle yaşayacağımı Mutluluktan havalara uçacağımı Özgürce enginlere kanat açacağımı Sarılıp bedenine çıl...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/birtanem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-rukiye-cerezci-cvpsh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzayıp giden karanlıkta

gecelere salt, 

düşünceler bölünür

ben de bölünürüm.

Uzaklarda bir köpek uluması, 

hava soğuk, üşür belki; 

ben de üşürüm.

Sonra aklıma yaşamın değil, 

ölümün sonsuzluğu gelir.

Boşlukta kaybolan nesneler gibi, 

yada bir damla var olma çabasına girerse belki; 

ben de var olurum.

Uzayıp giden karanlıkta

gecelere salt, 

düşünceler bölünür, 

ben de ölürüm...

                    (02.07.1999-Konya)', 'Uzayıp giden karanlıkta gecelere salt,  düşünceler bölünür ben de bölünürüm. Uzaklarda bir köpek uluması,  hava soğuk, üşür belki;  ben de ü...', ARRAY['Türk Edebiyatı','Şiir','Rukiye Çerezci']::text[], 8.5, '{"poet":"Rukiye Çerezci","poet_slug":"rukiye-cerezci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/belki-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekten Dudaklara', 'yurekten-dudaklara-emel-cengiz-btrpy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğer bir gün olduğun yollara düşersem

Yüreğim çılgıncasına tempo tutarsa sevilere

Bir ateş yanarsa devasa gecenin karanlığında

Suya hasret kalırsa çatlamış dudaklar

Seni yaşıyorum.

Eğer bir gün sevgini söylersen bana

Nutkum tutulur, dilim lâl olursa

Anılar, kahırlarla karışırsa anlamsızca

Acılara direnirse inatla, bu beden

Seni seviyorum.

Eğer bir gün kelimeler dökülürse dudaklarından

Beklediğim, düşlediğim ve istediğim

Sitemler başka baharların peşinde koşarsa

Ve sen yanımda olursan sonsuza dek, koşulsuz

Seni istiyorum.

Eğer bir gün suskunluğundan arınırsan

Olmaz dağlarını sorgusuz arkana alırsan

Çareler üretirsen çaresizlik ormanlarında

Karadan beyaza bir gündönümü çizersen

Seni bekliyorum...', 'Eğer bir gün olduğun yollara düşersem Yüreğim çılgıncasına tempo tutarsa sevilere Bir ateş yanarsa devasa gecenin karanlığında Suya hasret k...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yurekten-dudaklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HEDEF', 'hedef-emel-cengiz-8f1ym', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bir türlü anlatamadığım

Ulaşamadığım

Şimdi mutlu musun yokluğumda? 

Paylaşmamanın acısı çöktü yüreğime

Ayrılık şarkılarını artık sen dinle

Uzun uzun düşün

Hassas terazilerde tart beynindekileri

Döndüremeyecek bilmelisin

Gönlümdeki sevgin beni geri

Sen, hasret rüzgarım

Sen sığınağım

Yokluğuna alıştım, alışacağım

Bir sigara yakacağım vakitsiz

Düşlerimde sen, belli belirsiz

Kahır yazmayacağım

Sensizlikte ayakta dimdik duracağım

Zaman su gibi akıp gidecek

Gün gelecek nehir olup taşacağım..

Unutma! 

Kafamdaki hedeflere..

Birgün mutlaka ulaşacağım..', 'Sen bir türlü anlatamadığım Ulaşamadığım Şimdi mutlu musun yokluğumda?  Paylaşmamanın acısı çöktü yüreğime Ayrılık şarkılarını artık sen din...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hedef-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlığın Gerçeği', 'i-nsanligin-gercegi-emel-cengiz-twfq0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Paylaşabilmek çıkarsız duyguları benlikte

Herkesle, hep birlikte

Uç olmak değil, doğalı yakalamak

Sevgiyle, hoşgörüyle sarmaş dolaş olmak

Anlatmak, anlaşılmak

Konuşmayı duygulara bırakmak

Gözlerde tüm hayatı yaşamak

Özgür olmak, koşulsuz mutlulukla

Yarınlarda, bugünlerde ve dünlerde

Yolun uzunu kısası ölçü olmamalı

Dolu dolu sona ulaşmalı

Tanımalı insan kendini, sorgulamalı

Coşkularla, tutkularla hesaplaşmalı

Hoşgörü tohumları ekilmeli evrenin tarlalarına

Yaşanılası bir dünya bırakılmalı yarınlarımıza

Ben erimeli ''BİZ''in güçlü nefesinde

Bu insanlığın gerçeğidir, iyi dinle! 

Siyah - beyaz karıştırılmalı renk armonisinde

Çatlamalı huzur tohumları sade ve sessizce

Güzellik ruhlarda olmalı, bedende değil

Pozitifse insan, karşısında saygıyla eğil

Gönül aşkların her türlüsüne doysun sonuçta

Tanıyorsan böyle insanı...

Bil ki o dorukta...', 'Paylaşabilmek çıkarsız duyguları benlikte Herkesle, hep birlikte Uç olmak değil, doğalı yakalamak Sevgiyle, hoşgörüyle sarmaş dolaş olmak An...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/insanligin-gercegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Sensizlik Yok', 'ama-sensizlik-yok-mustafa-sarpkaya-ofxhg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Emellerimi 

Sarıp 

Rüzgara 

Astın 

Bıraktın beni bir başıma bu hoyrat ellerde 

Tuz bastın yüreğime 

Dağladın yüreğimi her zamanki gibi 

Savurdun denize küllerimi 

Attı beni kıyıya 

Lanet olası kıyı ayırdı benden seni 

Ayırdı ikimizi 

Lanet olaası rüzgar ayrı koydu sevenleri 

Sensizlik olsaydı yapmazdım biliyorum 

Ama sensizlik yok sen de biliyorsun 

Yani olmasaydın 

Atmazdı rüzgar 

Ayırmazdı kıyı 

Sarılmazdı emellerim rüzgara 

Ama sensizlik yok 

Ve sen yine… 

Emellerimi 

Sarıp 

Rüzgara 

Astın', 'Emellerimi  Sarıp  Rüzgara  Astın  Bıraktın beni bir başıma bu hoyrat ellerde  Tuz bastın yüreğime  Dağladın yüreğimi her zamanki gibi  Savu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ama-sensizlik-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Seviyorum', 'beni-seviyorum-mustafa-sarpkaya-sb4cm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülen gözlerimi uçurup ta uzaklara 

Yaşayan ölünün yaşaran gözlerine 

Bakıyorum ve dalıyorum derin denizlere 

Ve oturunca tahta taşın üstüne 

Kahkahalarla ağladığım o yıllar geliyor aklıma 

Bakıpta görmeyen nar eşkisi gözlerinden 

Usulca süzülürken damla yanaklarına 

Kısa ve yorucu bir yolun daha ortasındayım ben 

Henüz ağlamak için çok geç 

Hayatımın treni batarken soğuk denizlerde 

Gülmeyi arzulayan yüzümü azdırıyorum öylesine 

Yeşeren evrenin saf sevgisinden 

Sensizliği çıkarıyorum payıma 

Kalakalıyorum öylece başım ellerimin arasında 

Gülmeyi ve ağlamayı aynı anda başaran 

Bu gözlere çok şey borçluyum biliyorum 

Ve artık beni seviyorum...', 'Gülen gözlerimi uçurup ta uzaklara  Yaşayan ölünün yaşaran gözlerine  Bakıyorum ve dalıyorum derin denizlere  Ve oturunca tahta taşın üstüne...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beni-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü Seni...', 'cunku-seni-mustafa-sarpkaya-gdghu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dinecek elbet bu acı bir gün biliyorum 

Sevecek gönlüm işte onu görüyorum 

Senden önce geçen günlere şu kalbim 

Sitem edecek çünkü seni seviyorum 

Ruhun bana aşık bense gölgene 

Sevmesende beni gözlerime gül yine 

Bahçemde gül gibi açan sevgine 

Sığınıyorum artık çünkü seni seviyorum 

Gel desem gelirmisin bilmem buaralara 

Adını yazarım sevsen dört kıtaya 

Gönül dağındaki o Sarpkaya”ya 

Vuruyorum kendimi çünkü seni seviyorum 

Güllerim soldu gelmedin diye 

Bilmem ki bana bu nazın niye 

Anla artık seni seviyorum ölesiye 

Ölüyorum sana çünkü seni seviyorum', 'Dinecek elbet bu acı bir gün biliyorum  Sevecek gönlüm işte onu görüyorum  Senden önce geçen günlere şu kalbim  Sitem edecek çünkü seni sevi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cunku-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülistan', 'gulistan-mustafa-sarpkaya-nf7nk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül güldü gülistanda 

Bulamadı dengini 

Bülbül bildi bulduğunu 

Güle verdi rengini 

Bülbül geldi gülistana 

Yenemedi hislerini 

Hançerledi göğsünü 

Güle verdi yüreğini 

Gül güldü bülbüle 

Veremedi sevgisini 

Yere düşen bülbülün

Bilemedi kıymetini 

Gül mezardı gülistanda 

Bülbüle kazılmış adeta 

Toprağı kanla sulanmış 

Harmanlanmış bin defa 

Kokusu düşmüş gülün 

Gülistandaki mezara 

Yakışmadı bu mezar 

Gül kokulu gül-zar''a 

Nihayetidir bülbülün 

Kaplanışı toprağa 

Ve gülistandaki o gülün 

Saplanışı toprağa', 'Gül güldü gülistanda  Bulamadı dengini  Bülbül bildi bulduğunu  Güle verdi rengini  Bülbül geldi gülistana  Yenemedi hislerini  Hançerledi g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gulistan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim...', 'kalbim-mustafa-sarpkaya-dd49z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Martılar uçuyor gökyüzünde buranın 

Yollar sanki bir başka kıvrılıyor 

Hasretle sallanıyor bir el 

Elden üstünse durma gel 

Aldın mı lafımın iyisini? 

Rastladınmı sahilde cam şişeye? 

Tüm acılar ve hasret ondaydı 

Yoksa almadın mı? 

Veda ettin gittin ölmedim 

İlelebet değildi ya hasretim 

Laleler açacak diyorum bak sen gelince 

Limoni mi olduk yoksa ayrı kalınca? 

Gelsene hadi ne duruyorsun be? 

O güzel gözlerini süzsene 

O garip duygularımı sezsene 

Narin parmakucunla kristal kalbimde gezsene', 'Martılar uçuyor gökyüzünde buranın  Yollar sanki bir başka kıvrılıyor  Hasretle sallanıyor bir el  Elden üstünse durma gel  Aldın mı lafımın...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayende', 'sayende-mustafa-sarpkaya-eqwbj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen benim biricik aşkım 

Ben senin Esra''rkeşin 

Yalan yok sevdim seni 

Son damlasına kadar 

Tükenen düşüncelerimi 

Ve hatta… 

Ellerini gözlerini saçlarını 

Birde en çok dudaklarını 

Sevdim yalan yok 

Düşlerimi süsleyen o eşsiz güzelliğinle 

Ağır sevdanı nakşettin yüreğime 

Ve şimdi anlıyorum hayatın manasını 

Niçin yaşadığımı 

Sayende sevenim 

Sayende insanım 

Benim her yanım 

Sayende…', 'Sen benim biricik aşkım  Ben senin Esra''rkeşin  Yalan yok sevdim seni  Son damlasına kadar  Tükenen düşüncelerimi  Ve hatta…  Ellerini gözle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sarpkaya']::text[], 8.5, '{"poet":"Mustafa Sarpkaya","poet_slug":"mustafa-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sayende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırlangıç Yağmurum', 'kirlangic-yagmurum-hasan-huseyin-memis-q0p6w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nice yıllar var ki

Sevgi sürgünlerim

Koparılmıştı birer birer...

Öksüz ve yetim kalmıştı yüreğim; 

Kimsesizdi ama

İçindeki sevgiler

Yıllanmış

Ağdalanmış

Bakir kalmıştı...

Benden de geriye

Elden ele gezen 

Bir eskiz

Bir de

Sahte mutluluk bırakmıştı...

Açmamıştım derdimi

Ne merde

Ne namerde, 

Derman olup da

Diyet istemesin diye...

İçimdeki kasırgalar

Bağ bozumları

Talanlar, 

Hep sessiz, 

Sedasız

Ve 

Yalnız yaşanmıştı...

Aynalar bile

Hep beni 

Mutlu sanmış

Kıskanmıştı...

Eski şarap kadehim, 

Rakı bardağım, 

Gece mavisi

Bir zamanlar da sigaram

Olmuştu yarenim; 

Mezemdi

Sevdiğim

Kurutulmuş

Korkutulmuş

Boğulmuş 

Yüreğim...

Bir onlar 

Bir de bilirdi derdimi, 

Sırdaşım

Kurşun kalemim...

Serhoş dostlar da yoktu

Yoktu artık çelebiler, 

Onlar da benin gibi

Birer yıldız olup

Nice dileklere

Nice sevdalara

Kendilerini feda ettiler...

Kaldırımlar bile öksüzdü

Öksüzdü titrek kandiller

Yetimdi kuytu köşeler

Delikanlı, mert fahişeler bile

Gecelerden

Birer birer silindiler...

Sabah ezanlarını

‘Saba’ makamında okumuyor

Okuyamıyor müezzinler

Onlar da 

Sevgiyi

Uykularına, 

Mahur makamına

Kurban ettiler...

Bir gün

Sen geldin bana

Kırlangıç yağmurlarınla

Göçmen kuşların

Göç hazırlığına başladığında

Seni bana

Onlar emanet ettiler...

Bana sen, 

Bir seni, 

Bir zindanlardaki eskizimi

Bir de 

Tertemiz

Bakire yüreğini getirdin...

Geldin, 

Girdin dünyama, 

Bana beni, 

Bana sevgiyi, 

Bana sadakati, 

Bana yaşamı sevdirdin...

Doğurdun

Sevginle beni, 

Beni 

Gizli göz yaşlarınla emzirdin, 

Saramadığın kollarınla

Mutsuzluklarınla besledin...

Kıyamam sana! 

Üzemem seni! 

Duygularınla oynayamam! 

Çünkü sen benim

Meleğim, 

Yaşamımda mutlu pişmanlık sebebim, 

Geç fark ettiğim hayat iksirimsin...

Seni üzersem eğer

Sürerler beni melekler

Zulmet diyarına; 

Yılanlar emzirir cesedimi, 

Zebaniler söyler ninnimi, 

Gardiyanım olur kırk haramiler...

Ama onlar bile

Seni üzdüm diye

Bana işkence ederler...

Sana gönül borcum var! 

Sana can borcum var! 

Mutlu etmeye seni

Ahdım var! 

Sevmeye seni

Yeminim var! 

Senin olmaya

Senin kalmaya

Seninle birlikte yok olmaya

Tanrı huzurunda 

Sözüm var! 

Sen istemesen bile

Sensizliğe, 

İsyanım

İtirazım var! 

Kararlıyım! 

Yeminliyim! 

Seni hep, 

Kimsenin sevmediği

Kimsenin düşlemediği

Kimsenin sevemeyeceği kadar seveceğim! 

Sen güneşim oldun

Ben ise gündöndü, 

Yüzümü

Yalnızca sana döneceğim...

Çekip gitsen de geceleri

Boynumu bükeceğim

Hayata küseceğim

Bıraktığın yerde

Gelmeni bekleyeceğim...

Sabahları sana

İlk ben

‘Günaydın güneşim! ’

‘Sana muhtacım! ’ diyeceğim, 

O güzel yüzünü

İlk ve sadece

Ben öpeceğim bebeğim...

Kahramanlar diyarında

Kahramanımla

Seninle

Yürek yüreğe gezineceğim...

Ben senin teninle değil

Çilelerinle

Yüreğinle

Beyninle sevişeceğim...

Dudaklarını değil

Kahramanım! 

Önünde diz çöküp

Elini öpeceğim, 

‘Şovalyem’ demen için

Hep buralarda bekleyeceğim...', 'Nice yıllar var ki Sevgi sürgünlerim Koparılmıştı birer birer... Öksüz ve yetim kalmıştı yüreğim;  Kimsesizdi ama İçindeki sevgiler Yıllanmı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":158,"source_url":"https://www.antoloji.com/kirlangic-yagmurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüyorum Kendime', 'guluyorum-kendime-hasan-huseyin-memis-415y5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülüyorum

Kendi halime.

Yüreğimin lekesizliğine

Beynimin dürüstlüğüne

Dilimin yalansızlığına

Gülüyorum.

Onlar da çağdışı kalmışlar, 

Kalmışlar

“Şovalyelik” günlerimde...

Bunu anlamak zor

Çözümü belki

Mona Lisa’nın

Tebessüm gizinde...

Gülünecek halimden nedendir

Gurur duyuyorum.

Çoğu zaman

Hatalı mıyım? diye düşünüyorum.

Belki aptalca ama...

Kendimi “hatalı” bulmuyorum.

Ama suçluyum! 

Suçum; 

Riyakar ve sinsi olmamak.

Cezam; 

Yalnız ve uzakta kalmak.

Kayıplarım

Hep bu nedenle oldu 

Ama 

Er geç kazanacağım

Hem de 

Hiç kimsenin

Bugüne kadar

Kazanamadığı kadar...

Hep söylerlerdi bana

‘Sabun gibisin.

Elde avuçta durmuyorsun.

Zapt edilemiyorsun

Sel gibisin.

Kurtlar kadar özgür, 

Kartallar kadar

Başına buyruksun.

Tavus kadar rengarenk, 

Siyah kadar katkısız, 

Su kadar şeffaf ve durusun.

Neslinin son türü, 

Fosilleşmemiş dinozorsun...’

Haklılar sanırım; 

Mükemmel değilim.

Ama, 

Sıradan da değilim...

Çünkü ben sadece

Bana benzerim.

Müslüman’ım ama

“Çarmıh”a gerilmiş İsa’ya ağlarım.

Aslında O’na değil

Ağlarım Kendi halime...

İsa’ya birkaç çivi çakmışlar

Bırakmışlar Mevlası ile 

Kendi haline...

Bana her an çiviler çakıyorlar, 

Hem de 

Ya hep yüreğimin

Ya dilimin

Ya da beynimin üzerine

Yaradan’ımla da beni

Baş başa bile bırakmıyorlar...

Ama biliyor musun? 

Her çakılan yeni bir çivi ile

Dünyamda

Yeni bir Hüseyin büyütüyorlar...

Nedendir? 

Pek çok insanın

Yıllarca anlatacağı olayları

Ben her gün yaşıyorum

Çok önemli olmayabilir ama

Ben

“Anamla” değil

“Anılarımla” anılıyorum.

Anılarımı anlatmak bir kenara

Genelde hatırlayamıyorum

Ben gerçekten farklı yerdeyim

Bunu çok iyi biliyorum.

Ulaşılmaz değilim asla! 

İhtiyacım

Ama görülmüyorum

Hava gibi

Sevgi gibi

Aşk gibi

İnanmak

Hissetmek

Özlemek gibi...

İsa’dan da şanssızım ben

Havarilerim yok çünkü benim.

Ama belki de şanslıyım

Çünkü

Melekler benim havarilerim...

Çocuklar hep bana sarılıp uyurlar

Bana sarılıp bebekler sükun buluyorlar

Hepsi nedense benim kucağımda gülüyorlar

Annelerinin memesi yerine parmağımı emiyorlar

Sanırım

Onlar da müritlerim benim...

Masum değilim kesinlikle

Ama masum olmadığımı söyleyecek  kadar

Gerçekler yorgunuyum...

Ben, 

Beyazı severim

Her şeydir...

Siyahı severim

Sadece kendisidir...

Sarıyı severim

Güneşimdir....

Yeşili severim

Gözlerimdir...

Maviyi severim

Derinliğimdir...

Pembeyi severim

Yüreğimdir...

Kahverengini severim

Beynimdir...

Lilayı severim

Hayallerimdir...

Moru severim

Hem de 

Çok severim

Esrarım

Farklılığım

Gökyüzüne kazınmışlığımdır...

Renksiz rengimi

Berraklığımı severim

En çok.

Kendimdir çünkü

O

Kendimdir benim...

Korkuturum insanları

İçim dışım göründüğü için

Hep ben ağlarım nedense

Meleklerimi

Bebeklerimi

Sevgilerimi

Sevgililerimi

Ağlatmamak için...

Kaybolduğum anlaşılmaz

Çünkü ben berrağım

Zamanım

Mekanım

Eşim

Benzerim de yoktur benim.

Çünkü, 

Ben yürekten özlendiğim

Anılarımla anıldığım

Hiç kirletilmemiş yerde

Yüreğimin dibindeyim...

Günaha girmedim mi? 

Girdim! 

Ama kimsenin değil! 

Kendi günahıma...

Hep aaah! dedim

Hiç aaah! dedirtmedim.

Ben

Bana izin vermeyen

Rüyamdaki

Gölgeleri bile sevemedim...

Gelen emanet oldu bana

Hiç emanete ihanet etmedim...

Çok yandım

Ama hiç yakmadım

En azından hiç yürek yıkmadım....

Su oldum

Su dağıttım.

Ama hep ben

Susuz kaldım...

Çözemiyorum be arkadaş! 

Ben sence

Şeytan mı? 

Yoksa şeytan ve şeytanilerin

Zebanisi miyim?', 'Gülüyorum Kendi halime. Yüreğimin lekesizliğine Beynimin dürüstlüğüne Dilimin yalansızlığına Gülüyorum. Onlar da çağdışı kalmışlar,  Kalmışl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":176,"source_url":"https://www.antoloji.com/guluyorum-kendime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Sen?', 'neden-sen-hasan-huseyin-memis-reokq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzünden bakardım yeryüzüne, 

Sonsuz özgürlüğümü yaşardım...

İnsanlar birer zavallı, 

Kadınlar maskeli baloda, 

Erkekler ise zebaniydiler

Çünkü insanlar

İnsanlıklarını yitirmiştiler...

Bir su damlasıydım, 

Güneşin ışıklarında kayarak derinlere sızan, 

Renklerle sevişip

Karanlıklarda yıldızlara yoldaş olan, 

Koyu ve duru laciverttim ben...

Yıldızlarla konuşur, 

Mehtapla sevişir, 

Bulutlarda uçardım...

Mutluydum belki Hande ile ısınırken, 

Mutluydum belki Neslihan ile yatarken, 

Onlar da mutluydu, 

Birer birer, 

Benim rüzgarımla yatakta savrulurken, 

Kuşlar gibi kanat çırpar, 

Gökkuşağını takarlardı bellerine, 

Sonra da beni çekerlerdi içlerine, 

Derinlerine...

Tekdüzeydi her şey, 

Her şey mekanikti, 

Zevk anları zevk değil

Genelde ızdırab verirdi

Her şey biter 

Ardından pişmanlığım

Yüreğimin kapısına dikilirdi...

Alırlardı 

Hande ve Neslihan benden erliğimi, 

Oynarlardı onunla bütün geceleri, 

Cesedimle yatarlardı

Cesedime sarılır

Cesedimle boşalırlardı...

Ruhum gökyüzünde

Gözleri yaşlı

Yıldızlara aşk şiirleri yazardı...

Ağır bir sigara kokusuyla gelirdim kendime, 

Öperlerdi dudaklarımdan

Bencil olmadım diye, 

Bilmezlerdi ki oralarda gezinmediğimi, 

Oralarda eğlenmediğimi, 

Onların olanın cesedim olduğunu, 

Ruhumla sevişmediklerini, 

Derlerdi birde..

Erkek mi? 

İşte bu! Diye...

Hissetmezlerdi, başka diyarlarda gezdiğimi bile...

Takılırdım yine bembeyaz pamuk bulutların peşine, 

İmrenerek röntgenlerdim, 

Sevgililer öpüşürken sevgiyle, 

Onlara imrenirdim..

En çok da altmışlı yaşlarda bile

Birbirlerine aşık çiftlerin

Çilelerini dilerdim...

Herkes koşarken bir şeylerin ardından, 

Ben kendimi arar bulurdum

Derin mor kuytulardan...

Bazan bir kuşun kanadına dadanırdım, 

Bazan bir aslanın yelesine yapışır, 

Bazan bir yunusun yüzgecine asılır, 

Arar dururdum

Hem kendimi, 

Hem de diğer kendimi, 

Yani arardım diğer yarımı, 

Arar da bulamazdım yarimi...

O sıralar, 

Bir fahişenin gözyaşlarıyla yıkanır, 

Bir travestinin telaşında saklanır, 

Rutubet kokulu nezaretlerde dolaşırdım görünmeden

Sonra da hastahanelerin çileli koridorlarında

Bulurdum kendimi, 

Fakirlerin sefalet koğuşlarında, 

İdrar kokulu koridorlarda

Ayın sonunu getirme hesabı yapan

Nurdan hemşirenin odasında; 

Nezarethanelerde elektriklenmiş

Denizlerin, Hüseyinlerin yareni

İlkelilerin sökülmüş ızdırap tırnaklarında...

Oralarda bile örülen

Demir parmaklıkların loşluğunda...

En çok da

Bebesini ilk kez kucağına alıp öpen

Anneleri seyretmeyi severdim, 

Annesinin göğüs uçlarını içgüdüyle arayan

Bebelerin kokusunu çekerdim içime...

Onların umutlarını yakalamak

Sevmek

Ben de umut etmek isterdim...

Umutlar mezarlığı beynimi, 

Yeniden düzenlemeyi dilerdim...

Sonra da morga iner

Ölümün ayırdığı yürekli sevgililere

Yarenlik ederdim, 

Bedenlerinden değil

Yüreklerinden sızan kanı

Özlemle seyrederdim...

Sonra da cenazelerine katılır, 

Onlarla gömülür

Sorgu meleklerinin sorularına cevap

Onlara kopya verirdim

Bilirlerdi melekler

Ses de çıkarmazlardı

Sevgililer ayrıldı diye, 

Azraille birlikte

Onlar da benimle ağlardı...

Görmezlikten gelirlerdi kopyalarını, 

''Geçti! '' derlerdi...

‘Kalmak’ ne demek se...

! Burak’ın hadi, 

Bırakın onları yüreğiniz

Adaletiniz varsa! 

Bırakın! 

İlah

Kulunla dalaştıysa

Bırakın! Sizlerden şefaat dilenen mi var? 

Bırakın! 

Oradan, 

Siyasi şubenin sorgu odasına dalardım

Bir genç kızın 

İlk erkeğinin

Polis copu olduğu

Tacizin sıradan

Tecavüzün hak

İşkencenin gurur

Yargısız infazın kahramanlık olduğu

Hücreleri gezerdim...

Çıplıklarla kahrolur

İnançlarla donanır

''İşte kahramanlar! '' derdim...

Sonra da polis copundan

Kendinden bile tiksindiğini dinlerdim, 

Bir gün gelip te o copların

Canlanmasını

Ve

İntikam almasını dilerdim Tanrı''dan...

Zebanileri bile utandıran

Polis hikayeleri dinlerdim, 

Gasp edilmiş demli çay bardaklarından...

''Gardaş'' deyip te kuyusunu kazdığı

''Bacı'' deyip te geleceğini çaldığı

''Ülkü'' adına soysuzluk yaptığı

''Töre'' adına insanlığı karaladığı

''Geçim'' adına vatanını sattığı

''Zevk'' uğruna hayasızca saldırdığı

''Sorgu'' adı altında yaşam kararttığı

Şeffaf (!)  karakollardan ayrılırdım...

Ayrılırken, 

İnsanlığımdan bile utanırdım...

Ayrılırken, 

Kahramanların gözyaşlarına saklanırdım...

Yaşamı sorardım yaban kazlarına

''Özgürlük! '' derlerdi

Dilediğince uçabilmek

Evreni gezmek

İstediğin gölden su içmek

Katil avcı çiftelerine meydan okumak, 

Kurulan sinsi tuzaklara yakalanmamak, 

Ölüme meydan okumak'' derlerdi...

Hatta bazısı, 

''Rüzgara baş kaldırmak ta dahil beyim''

Diye ilave ederlerdi...

Kazlar, 

Kazlıklarınla

Özgürlük uğruna

Canlarını

Sevgililerini verir

Ama

Asla

Özgürlüklerinden vazgeçmezlerdi...

Sevgiyi sorardım

Gelin duvaklarına

''istemek, 

Almak, 

Yaşatmak, 

Yaşamak, 

Dönmemektir geriye, 

Gerekirse can vermektir, 

Sevgilin tek damla gözyaşını silmeye'' derlerdi...

Eklerdi bazı duvaklar, 

''Sevmek adam olmaktır, 

Sevmek kadın olmaktır, 

Sevmek duvağın altında, 

Hep cenneti yaşamaktır, 

Her fırsatta O''nunla

Gerdeğin heyecanını

İlk öpüşmenin telaşını

İlk dokunuşun ürpertisini

İlk ''biz'' oluşu

Her an 

Yeniden 

Yepyeni yaşamaktır'' diye...

Bazıları da bıçkınca, 

Alaylı konuşur

''Sevmek mi? 

Sevdiğinin mutluluğu için

Gerekirse 

Yeryüzünden silinmektir'' derlerdi...

Yağmura sorardım

''Sevişmek nedir? '' derdim, 

''Kolay

Sevişmek sızmaktır usul usul

Doyurmaktır sinsice

Beslemektir orayı

Eritmektir kayayı

Parçalamaktır yaprağı

Çatlatmaktır toprağı

''Su! ''

''Su! ''

''Su! '' diye inletmek, 

Sonra da coşarak akıp

Nehirleri baştan çıkarmak

Her yer yıkılırken

Denize kavuşmak

Sonra tekrar dolup

Bulutlara firar edip

Daha güçlü geri dönmektir'' derdi...

Yağmur için bile sevişmek, 

Dellenmek, 

Dellenmek, 

Sadece dellenmekti...

Yani dellenirken bile vermekti...

Bizler gibi

Sadece almak değil

Tüketmemekti...

Güneşi özlerdim, 

Yıldızlara merhaba demek, 

Ayda iki tek atmak, 

Samanyolu''nda fasıla katılmak, 

Gökkuşağında saklambaç

Kar taneleriyle poker oynamak

''Rest'' çekmek isterdim

Zulümlere

İşkencelere

Feryatlara

Namus adına kıyılan hayatlara

İnsanlık talanlarına karşılık 

Tanrı''ya...

O da hile yapar

Kağıt araklar

''Reste rest'' derdi

Kaybeden hem ben

Hem de benim gibiler; 

Kazananlar

Zebanilerin şahı eşkıyalar

Eşkıyalar da başımıza sonra 

Olurdu hükümdar...

Bir sabah karar verdim

Güneşin kucağında

Talan edecektim cenneti

Haramilik edecektim

Sevgiyi, sevgiliyi bulmak adına...

Melekleri atlatıp

Cennetin tek Gülünü

Elde edecek

Sırtlayıp O''nu

Cennetten birlikte tüyecektim...

Fark ettiklerinde en güzel meleğin

Araklandığını

Tanrı''nın feryadına

Nanik yapıp gülecektim...

Her şeyi göze aldım

Cinsiyetsizdi o melek

Ama güzeldi...

Hem melekti

Hem de huri gibi

Ebedi bakireydi...

Sevgi doluydu...

Aşk doluydu...

Sevda doluydu...

İyilik doluydu...

Ama hep O

Kendini sevecek

Bir erkeği bekler

Dururdu çaresiz

Kıyameti bekler

Beklerdi kopamazdı

Bir türlü hain

Büyük mahkemeyi bekler

Sanıkları bir türlü çağırmazdı İsrafil...

Suçluları alıp mahkumiyete

Götürmezdi Azrail...

Getirmezdi bir türlü erkeğini

Sağdıç Cebrail...

Şeytan uğrardı yanına

Sık sık

Göz koyar

Gözleriyle soyar

Aklını çeler

Rüyasına girer

Düşlerini iğfal eder

Sonra da ardına dönüp yatar

''Seni seviyorum'' bile demeden

Hoyratça giderdi kendi işine

Bunların polisi de

Oydu ya! 

Aynasızdı lakabı

Şeytan dı esas adı, 

Yengeç gibi yürür

Çalımından 

Yanına varılamazdı...

Aslında o

Bir hiç

Kağıttan kaplandı...

Meleklerin meleği

Kalırdı tek başına cennetinde...

''Ne üzülüyorsun, 

Bak cennettesin! '' derlerdi

Diğer huriler...

Huri olup

Melek olup

Gül meleği anlayamazlardı...

Sızdım cennete bir gün, 

Gülü buldum

Attım sırtıma

Başladım kaçmaya...

Yakaladı melekler

Ellerimi kelepçelediler

Gülün sevgisiyle...

Ayaklarıma pranga vurdular

Gülün özlemiyle...

Suçlu gömleği giydirdiler

Gülün feryatlarıyla...

Ağzına kilit vurdular

Gülün ızdırabıyla...

Çıkardılar Yüce Divan''a

Karar verdi Tanrı...

''Cennetten meleğim Gülü çalmaktan

Hurilerin hurisi Gülü sevmekten

Gözbebeğime, 

Güle aşık olmaktan

Güzeller güzeli Güle vurulmaktan

Seni suçlu bulum! 

Suçun aşık olmak, 

Suçun sevmek

Suçun benim yerime

Gülü koymak

Suçun benden çok 

Gülü istemek

Suçun benim yerime

Güle yalvarmak

Suçun; 

Cennetten meleğimi 

Aşkımı

Gülümü araklamak...

Cezan büyük

Ama cezanı erteliyorum...

Eğer O''nu üzersen

O''nu kırarsan

O''nu aldatır

Duygularınla oynarsan

O izin vermeden

O''nu gözlerinle bile öpersen

O''nu ilk fırsatta

''Karın''

''Nikahlın''

''Eşin'' yaparsan

O ister de 

Sen de O''na uyup

O''nu 

O cehenneminde bırakırsan

Sevgini

Aşkını

Vurgunluğunu, 

İçtenliğini, 

Dürüstlüğünü yitirirsen O''na karşı...

O''na 

Benim O''na sarıldığım gibi sarılmazsan

Gelme karşıma! 

Gelme! 

Affetmem! ! ! 

İbret için

Seni yakarım! 

Yakar da yakarım! 

Seni Cehenneme

Çıra yaparım! 

Sonra da seni

Kül eder

O''nun yatağına yayarım

Tenine yapıştırırım...

Seni ben değil

Atarım önlerine

Timsahlara parçalatırım! 

Eğer O''nu mutlu edersen

Eğer beni de O''nun yarısı kadar seversen

Seni cennetime

Hükümdar yaparım! 

‘Al götür şimdi meleğini, 

Al götür, 

Sözünü unutma

Seni O''na

O''nu sana yazdım

''Biz'' dedim size

Engellerinizi kaldırdım

Sahip olun

Sahip çıkın

Sevgili olun birbirinize

Sizi birbirinize nikahladım

Haydi gidin evinize! 

Gelirken de yanıma

Ayrı ayrı değil

Size yakışan gibi

Birlikte gelin

Ölüme bile birlikte gidin

Sevin birbirinizi

Sakın beni üzmeyin! 

Eğer hata yaparsanız

Cenneti de cehennem yapar

Sizi orada yargılar

Orada yakarım...

Diye bitirdi Tanrı...

Bir kulu 

Sevgilisi meleğini almıştı ondan

Ağlıyordu...

Meleklerinin meleği

Artık sadece Hüseyin''in di

Cennet ıssız dı artık

Melekler ve huriler bile

Gülmüyordu

Hepsi

O''nunla Hüseyin''in mutluluğu için

Dua ediyordu...

Cennet artık 

Gülsüz cennet değil

Tanrı''nın çilehanesiydi...', 'Gökyüzünden bakardım yeryüzüne,  Sonsuz özgürlüğümü yaşardım... İnsanlar birer zavallı,  Kadınlar maskeli baloda,  Erkekler ise zebaniydiler...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":428,"source_url":"https://www.antoloji.com/neden-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Üzsem Seni', 'ne-zaman-uzsem-seni-hasan-huseyin-memis-qv5as', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman üzsem seni, 

Yıkılıyor, yanıyor bu şehir, 

Yüzüm dağlanıyor, 

Düğümleniyor boğazımda yaşam, 

Gözlerime kan, baskın veriyor...

Ne zaman üzsem seni, 

Selamı kesiyor kuşlar, 

Güneş, görmemek için yüzümü

Bulutların ardına çekiliyor...

Yapraklar, 

Seni üzdüm diye

Lanet edercesine, 

İntihar ediyor...

Sağnak yağmur bile

Damlasını benden esirgiyor...

Yandıkça yanıyor ciğerim, 

Yıkılan şehir, 

Beni altına alıyor...

Enkazlar bile

Beni örtmekten iğreniyor...

Bebeğim

Yalnızım, 

Avuçlarıma kar yağıyor

Yüreğimi yanar dağlar parçalıyor...

Seni üzmemek için

Ne yapmalıyım sevgilim? 

Hüseyin senden ‘af’ diliyor...

Sessizliğini dinliyorum kaldırımların, 

Suskunluğunu soruyorum karanlıkların, 

Bir yerlerde

Bir şeyler kırılıyor.

Farkındayım, 

Ama çaresiz

Söndüremiyorum yangınını

Ateşler içinde dudaklarım...

Güldüremiyorum onları bir türlü, 

Damlaları kovalıyor yüzüme

Göz pınarlarım...

Ne zaman üzsem seni

Yüreğimde faili meçhul cinayetler yaşanıyor, 

Talana uğrayan benliğim

İçim, 

Dışım, 

Her şeyim, 

Üzüntülerinle çürüyor...

Donuyor! 

Dökülecek ellerim, 

Ellerinin sıcaklığını dileniyor; 

Sustuğun, 

Ağladığın, 

Üzüntülerle oynaştığın yerde, 

Bu suçlu sevgilin

Affetmeni bekliyor...

Affet! Ne olur beni, 

Affetmezsen eğer, 

Yıkılan bu şehrin çöplükleri bile

Beni kabul etmiyor...', 'Ne zaman üzsem seni,  Yıkılıyor, yanıyor bu şehir,  Yüzüm dağlanıyor,  Düğümleniyor boğazımda yaşam,  Gözlerime kan, baskın veriyor... Ne za...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/ne-zaman-uzsem-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-hasan-huseyin-memis-09mts', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biri var, 

             Düşünüyor, 

Bir eli şakağında.

      Nur arıyor, 

                       Hatta, 

                                Muma razı; 

                                                   Riyakarlık karanlığında, 

                                                                                         İhtiraslar girdabında.

Çırpınıyor yüreği, 

                 Çirkeflik, 

                                Kalleşlik tuzağında.

Hatası; 

           Düşünmek, 

                             Yazmak, 

                                           Beyin özürlüler rıhtımında.', 'Biri var,               Düşünüyor,  Bir eli şakağında.       Nur arıyor,                         Hatta,                                  Mum...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizlik-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçak', 'kacak-hasan-huseyin-memis-0h5t8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Konuşsanıza ***’ım” dediniz, 

Konuşmama izin vermediniz, ürküp kaçtınız.

“Gülsenize ***’ım” dediniz, 

Gülmeme engel oldunuz, yanlış anladınız.

“İlgilensenize ***’ım” dediniz, 

İlgilenmemi küstahlık, düşürülmek sandınız.

“Gelsenize ***’ım” dediniz, 

Geleceğim kapıları kapattınız, beni hırsız yaptınız.

Son sözlerinizle, beni değil, 

Kendinizi tükettiniz, kendinizi yaktınız.

Konuşmak isteğimin sebebi, zerafetinizdi, 

Gülümseyişimin nedeni, asaletinizdi, 

İlgimin hikmeti, sesinizdi, 

Ayağınıza gelmemin muradı, gözlerinizdi, 

Size sevgimin temeli, içtenliğinizdi.

Hepsini yanlış anladınız, kaçtınız, 

Sevgi sarmaşığını ucundan budadınız, 

Beni, ben değil, kendi içinizdeki canavar sandınız, 

Sevgileri ötelere, uzaklara, hatta, mahşere bıraktınız.

Kaç! Sen ***’ya layık değilsin, 

Kaç! Kendinden kaçan, ne ilk, ne de son kelebeksin, 

Kaç! Mizan’ına dek kaçtığın yerde gizlenemeyeceksin, 

Kaç! Kaçmazsan, önce kendini, sonra beni seveceksin.

Kaçmak, 

Kendinden korkmak, kaçamağı yaşayamamaktır, 

Yalnız kalmak, kendi içinde boğulmaktır.

Kaçmak, 

Lanetlere boyun eğmek, kadere oyuncak olmaktır, 

Bataklığa sığınmak, çırpındıkça daha fazla batmaktır.

Kaçmak, 

Sevgiyi şehvete, geleceği geçmişe boğdurtmaktır, 

Sevmekten korkmak, sevginin celladı olmaktır.

Kaçmak, 

Ateşken kül olmak, havaya savrulmaktır, 

Su iken buhar olmak, serseri bulutlarla dolaşmaktır.

Kaçmak, 

Güneşi beklemek, sonuçta mum’a razı olmaktır, 

Tökezlemek, bir daha doğrulamamaktır.

Kaç! Ey Kaçak, kaç, 

Sen, bir gün mutlaka geri gelecek, 

Kaçtığın ***’ını, vurduğun yerde bekleyeceksin, 

İşte O Gün, her kaçak gibi, 

Kaçtığına nadim olacak, bir garip gibi öleceksin, 

Koluna vurduğun damgayı, kendin bile silemeyeceksin, 

Kaçaklığının bedelini, canınla ödeyeceksin, 

Cemaatin olmayacak, 

Makbere, omuzlarda değil, hamallarla gideceksin.

Mahşere dek, mahşerini, 

***’ını bekleyeceksin.

Sen ne cennete, ne cehenneme girecek, 

Şeytanla dans edeceksin.

Oralarda bile, kolu damgalı bir kaçak olarak bilineceksin.', '“Konuşsanıza ***’ım” dediniz,  Konuşmama izin vermediniz, ürküp kaçtınız. “Gülsenize ***’ım” dediniz,  Gülmeme engel oldunuz, yanlış anladın...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/kacak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harami', 'harami-hasan-huseyin-memis-au5vr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilemezdim, 

Bir bakışınla vurgun yiyeceğimi, 

Düşünemezdim, 

Rastlantıların beni serhoş edeceğini.

Amacım, 

Seni tüketmek değil, 

Zerafet bardağından, asaletini içmek, 

Zarif ve asil bir can’ı, Canan etmekti.

Sana zarif dedim, 

Zerafetin

Giysilere sığınmakmış.

Sana asil dedim, 

Asaletin, 

İnsanla oynayıp, 

Bıkınca kenara atmakmış.

Senin zerafetin ve asaletin, 

Vurgun yememek, vurgun vurmakmış.

Senin amacın, 

Canan olmak değil, 

Harami olmak, harami kalmakmış.

Kal tahtında ey gönül haramisi, 

Çok yakında olacaksın kendinin zebanisi, 

Cehennemi yaşayacak, gönlünü yakacaksın, 

Söndürmek için yüreğindeki yangını, 

Vurgun vurduklarına koşacak, 

Ancak onları da bulamayacaksın, 

Sen sadece bu dünyada değil, 

MAHŞERDE DE YANACAKSIN.', 'Bilemezdim,  Bir bakışınla vurgun yiyeceğimi,  Düşünemezdim,  Rastlantıların beni serhoş edeceğini. Amacım,  Seni tüketmek değil,  Zerafet b...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/harami-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-hasan-huseyin-memis-8tg5i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanyeri morardı, gökler karıştı, 

Deryalar karardı, bulutlar kaçıştı, 

Gazabı geliyor Manolya’mın, 

İşte bende, fırtına başladı.

Nefretinle; 

Mağrur başım eğiliyor, 

Duygularım el etek öpüyor.

Hiddetinle; 

Gönlüm kaçıyor, 

Yüreğim, nefretime sığınıyor.

Beynim, ruhum telaşlanıyor, 

Küçük Mahşerim, telefonla yaşanıyor.

Dalkavuklar seni alkışlıyor, 

Sana gülüyor, 

Çünkü: 

Onlar, senin tükenmeni istiyor.

Koparttığın, yapraklarım uçuşuyor, 

Ve onlar, Canan’a kavuşuyor.

Yeni bir sevda için parçalanıyor, 

Çürüyüp toprağa karışıyor.

Sesin; 

Asaletinin, 

Zerafetinin güftesi.

Fırtınan; 

Kötülük habercisi, 

Fırtınan; 

Tükenişin bestesi.

Bana hiddetlenip, kendini tükettin fırtınam, 

Şüpheler uğruna, kendini de yaktın fırtınam, 

İşte, sesin kesildi, 

Sen kendini, kendin bitirdin fırtınam.

Yaşantıma sükun geldi, 

Artık sen öldün fırtınam.', 'Tanyeri morardı, gökler karıştı,  Deryalar karardı, bulutlar kaçıştı,  Gazabı geliyor Manolya’mın,  İşte bende, fırtına başladı. Nefretinle;...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/firtina-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Anlarsın...', 'sen-anlarsin-hasan-huseyin-memis-ix42e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben, kumral kadınları severim; 

Bir de, beyaz dişli, ağzı gül kokanları, 

Hem de, tırnakları uzun, beli ince olanları.

Ben, menekşe gözlü kadınları severim; 

Bir de, uzun saçlıları, küçük dudaklıları, 

Hem de, beyaz tenlileri, gonca göğüslüleri.

Ben, mahçup kadınları severim; 

Bir de, çenesinde gamze, saçları düz olanları, 

Hem de, beni süzerken, yanakları allaşanları.

        Ben, hoş kadınları severim

Bir de, dudağının sol üzerinde minik ben, kulak memeleri küçük olanları, 

Hem de, sol eline yalancı alyans takanları.

Ben, akıllı kadınları severim; 

Bir de, gözlük takanları, makyajsız olanları, 

Hem de, ceylan kadar ürkek, sincap kadar şirin olanları.

Ben, gizemli kadınları severim; 

Bir de, eteği yırtmaçlı, ince çoraplıları, 

Hem de, siyah çamaşırlı, ten parfümü kokanları.

Ben, gösterişli kadınları severim; 

Bir de, boyu kısa olmayanları, koyu renk ruj kullananları, 

Hem de, ojeleri temiz olup, manikür yaptıranları.

Ben, nazlı kadınları severim; 

Bir de, zor ulaşılanları, çokça nazlanmıyanları, 

Hem de, bakımlı olup, elleri zarif olanları.

Ben, zarif kadınları severim; 

Bir de, çok bilenleri, az konuşanları, 

Hem de, bakışlarıyla bana aşkını anlatanları.

Ben, zeki kadınları severim; 

Bir de, gözlerime bakanları, gölgemden kaçanları, 

Hem de, beni görmek için, bahane bulanları.

Ben, küstah kadınları severim; 

Bir de, güzelliğinin farkında olanları, 

Hem de, kendine çok iyi bakanları.

Ben, inatçı kadınları severim; 

Bir de, maymun iştahlı olmayanları, 

Hem de, ölüme dek erkeğini bırakmayanları.

Ben, ihtiraslı kadınları severim; 

Bir de, benimle dolup, benimle boşalanları, 

Hem de, ser verip sır saklayanları.

Ben, kadın olan kadınları severim; 

Bir de, okşayınca coşan, sınır tanımayanları, 

Hem de, cüretkar olup, gözlerime bakanları.

Ben, sadık kadınları severim; 

Bir de, iğfal etmeyip, iğfal ettirmeyenleri, 

Hem de, benimle sevişirken başkasını düşlemeyenleri.

Ben, bakire kadınları severim; 

Bir de, beyni bakire olanları, 

Hem de, benimle olup benimle beni paylaşanları.

Ben, işte böyle kadınları severim; 

Bir de, dokunduğumda titreyip beni de titretenleri, 

Hem de, öpüşürken düşleyen, sarılınca mestedenleri.

Ben, dişi olan kadınları severim, 

Hem nasıl severim, öyle severim işte, 

Beni tutuşturmalı, sonsuzluk ateşini o yakmalı, 

Öldükten sonra bile, ruhumla dost hayatı yaşamalı, 

Tüm vücudu benim ateşim ve hasretimle kavrulmalı, 

Öbür dünyada bile, benim hurim O olmalı, O kalmalı, 

Ben de seni seviyorum XXXXXX, bilmem sana daha nasıl 

                                                                               anlatmalı?', 'Ben, kumral kadınları severim;  Bir de, beyaz dişli, ağzı gül kokanları,  Hem de, tırnakları uzun, beli ince olanları. Ben, menekşe gözlü ka...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/sen-anlarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-hasan-huseyin-memis-j7p2w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgileri, sevgilileri boğdurduk kaprislere, 

Sevgisiz, sevgilisiz kaldık, 

Boğdurduğumuz sevgilere, sevgililere ulaşmak için göklere eller açtık, 

Gemileri yaktık, yüreklerimizi parçaladık, uykusuz kaldık, 

Bilmeden boğdurduğumuz sevgilere, sevgililere bir daha kavuşamadık.', 'Sevgileri, sevgilileri boğdurduk kaprislere,  Sevgisiz, sevgilisiz kaldık,  Boğdurduğumuz sevgilere, sevgililere ulaşmak için göklere eller ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmalısın', 'i-nanmalisin-hasan-huseyin-memis-6ad8w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimseler inanmayacak, 

İnanamayacaklar bu besteye, 

Hatta, 

Belki, 

Sen bile.

Günlerce düşünecek, 

Sabahlara dek dinleyecek, 

Çözmek isteyecek, 

İnanasın gelecek, 

Belki, 

İsyan edecek, 

Ve sonunda, 

Gülüp geçeceksin

Belki, 

Benim için serseri, 

Belki de, 

Zavallı diyeceksin.

Sonra bir gün, 

Merak edecek, 

Mısralarıma başını gömeceksin.

Eminim ki o gün, 

Pişman olacak, 

Üzülecek, 

Belki, 

Kendine kahredecek, 

Beni tanımadığın günlere 

Lanet edeceksin.

Hissedemediğin çarpıntılarımı, 

Çözemediğin bakışlarımı, 

Beni mahveden sevdamı, 

Silinen yarınlarımı düşünecek, 

Gözlerin nemlenecek, 

Neden beni anlayamadığını çözecek, 

Belki ilk kez, 

Benim için kendini sevecek, 

Demek “aşk buymuş! ” diyeceksin.

Belki de, 

Şiirlerimde, 

Kendini yeniden keşfedecek, 

Düşen her kar tanesiyle, 

Beni özleyecek, 

Artık beni sadece, 

Rüyalarına bekleyecek, 

Ve sonsuza dek, 

Yitirilen bir hayali sevecek, 

Sol kulağını, 

Bir çifte firuze küpe ile süsleyeceksin.', 'Kimseler inanmayacak,  İnanamayacaklar bu besteye,  Hatta,  Belki,  Sen bile. Günlerce düşünecek,  Sabahlara dek dinleyecek,  Çözmek isteyec...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/inanmalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Olmadan...', 'pisman-olmadan-hasan-huseyin-memis-p0ssj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Takılır eteklerine bir gün, 

Hoyratça bir düğün, 

Parmağını kelepçeler, 

Altın rengi bir düğüm.

Kaçmak ister, kaçamazsın, 

Atmak ister, atamazsın, 

Namus derler, ayrılamazsın, 

Yanarsın ellerde, kurtulamazsın.

Gözyaşların çağlayan olur, 

Ahından, Kainat savrulur, 

Bağrın yanar, kavrulur, 

Anlatamazsın derdini, dilin tutulur.

Teselliyi meyde ararsın, 

Belki, 

Gizlice bana yazarsın, 

Gel kurtar der, 

Yalvarırsın, 

Unuttun mu? 

Beni sen öldürmüştün, 

Mahşerde bile bana kavuşamazsın.

Seni, kendimden bile kıskanırdım, 

Peşinde dolaşır, yalvarırdım, 

İstesen can verip, can alırdım, 

Toprak olup, ayaklarının altına yayılırdım.

Gözlerim yok artık, gözlerinde kaldı, 

Dilim yok, çiğnendi çöpe atıldı, 

Kollarım yok, ilgisizliğinle koparıldı, 

Ellerim yok, ellerinde kaldı, 

Yüreğim yok, yatak odana fener yapıldı, 

Hatırlar mısın? 

Bu can, senin mutluluğuna adandı.

Yok edilmeseydim, Ukbadan koşar gelirdim, 

Kanımı döküp, gelinliğinin belini süslerdim, 

Yine sana, canım der, alnından öperdim, 

İstesen gözlerimi oyup, duvağına serpilirdim, 

Gözyaşlarımla, karalanan kaderini silerdim, 

Gülmeyen yüzünü  güldürür, kulağına “Seni Seviyorum” derdim.

Mutlu olmak istiyorum dedim, itildim, 

Evlendin, defterinden, sen bilmeden silindim, 

Sevgilim, herşeyim, xxxxxx’ım, 

Ben senin için, kendi isteğimle katledildim.

Gözlerinde kalan gözlerimi, geri ver, 

Dilimi bul, getir, yerine dikiver, 

Kollarımı, üstünkörü tutturuver, 

Ellerimi, yüreğimi eski yerine takıver, 

Öp dudaklarımdan, beni uyandırıver, 

Sarıl bana, kalbimi canlandırıver, 

Ne olur yardım et! 

Sana muhtacım, 

Kaderime kendini bir kez olsun, yazıver.', 'Takılır eteklerine bir gün,  Hoyratça bir düğün,  Parmağını kelepçeler,  Altın rengi bir düğüm. Kaçmak ister, kaçamazsın,  Atmak ister, atam...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/pisman-olmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükeniş', 'tukenis-hasan-huseyin-memis-ppdjo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırıldı sazım, kırıldı yüreğim, 

Son bestemi, bitiremedim.

Hep sevdim, hiç sevilmedim, 

Son şarkımı, seslendiremedim.

Çenendeki gamzende hayat bulurdum, 

Savrulan saçlarından düşen tek tele kul olurdum, 

Bakıştığımızda, gözlerinde kaybolurdum, 

Her gülümsemende, aklımı uçururdum.

Beş parasızdım, açtım, seninle doyardım, 

Sokak ışıklarının altında şiir yazardım, 

Geceleri camlarda görüneceğin anı beklerdim, 

Gün doğmadan, senin için ortalıktan silinirdim.

Sesin. Nefesin, 

Ellerin, hasretin, 

Kolların, emelin, 

Gözlerin, kaderin, 

Dudakların, tesellin, 

Kirpiklerin, beni yaralayan hançerindi, 

Yoksun artık, yaşam gücüm tükendi, 

Sen yoksun diye, 

Vadem doldu, şah damarım kesildi, 

Seni, 

Karşılıksız sevmek bile, gururum, erdemim di.', 'Kırıldı sazım, kırıldı yüreğim,  Son bestemi, bitiremedim. Hep sevdim, hiç sevilmedim,  Son şarkımı, seslendiremedim. Çenendeki gamzende hay...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tukenis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem Ki...', 'bilmem-ki-hasan-huseyin-memis-nuyqi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın? Bilmem, 

Seni, ilk gördüğümü, 

Gizli gizli süzdüğümü, 

Oyunlar yapıp güldürdüğümü.

Unutur musun? Bilmem, 

Seninle, ilk konuştuğumu, 

Gölgen gibi, peşinde koşuştuğumu, 

Saklanbaç oynayıp, yokolduğumu.

Anlatır mısın? Bilmem, 

Seninle, ilk öpüştüğümü, 

Dokunmalarınla, deliye dönüştüğümü, 

Ellerimi bırakınca, üşüdüğümü.

Yazar mısın? Bilmem, 

Sensizliğin, beni öldürdüğünü, 

Yokluğunun sonucu, gömüldüğümü, 

Yağmur olup, göğüslerine süzüldüğümü.', 'Hatırlar mısın? Bilmem,  Seni, ilk gördüğümü,  Gizli gizli süzdüğümü,  Oyunlar yapıp güldürdüğümü. Unutur musun? Bilmem,  Seninle, ilk konuş...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmem-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Değilsin!', 'yalniz-degilsin-hasan-huseyin-memis-zr6uw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnız değilsin, 

Hiç yalnız kalmayacaksın, 

Aşkımı duvak, sevdamı, gelinlik yapacaksın, 

Şiirlerimde mısram, 

Resimlerimde rengim, olacaksın, 

Gözyaşlarımda kendini yıkayacak, 

Tertemiz kalacaksın.

Gönül yaramı, 

Gelin çiçeği gibi, takacaksın, 

Üşürse ellerin, 

Beni yakıp, ısınacaksın.

Mahşere dek seni seveceğim, 

Hiç, aşıksız kalmayacaksın, 

Bu dünyada olmasa bile, 

Cennette hurim olacaksın, 

Bundan kaçamazsın.', 'Yalnız değilsin,  Hiç yalnız kalmayacaksın,  Aşkımı duvak, sevdamı, gelinlik yapacaksın,  Şiirlerimde mısram,  Resimlerimde rengim, olacaksı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalniz-degilsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bestem', 'bestem-hasan-huseyin-memis-petez', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şiirsin sen, 

Yıllarca anlatılacak, 

Bir Şarkısın sen, 

Gönüllerde çalacak, 

Bir duasın sen, 

Ömür boyu okunacak, 

Sen, 

Gönlümün sultanı, 

Mahşerimsin, 

Sen, 

Ruhumun son güftesi, 

Final bestesisin, 

Sen, 

Benim herşeyim, 

Meleğimsin, 

Sen, 

Tanrıçam, 

Sen, 

Efendimsin, 

Buselikle başlayıp, 

Nihaventle biten aşkım, 

Kainatı yok edecek hasretimin, , 

Son notası, 

Son nefesisin.', 'Bir şiirsin sen,  Yıllarca anlatılacak,  Bir Şarkısın sen,  Gönüllerde çalacak,  Bir duasın sen,  Ömür boyu okunacak,  Sen,  Gönlümün sultan...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bestem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapma Güzel', 'yapma-guzel-hasan-huseyin-memis-ael3q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaktığın kalpler huzur bulmuyor, 

Gezdiğin gönüllerde hiç sabah olmuyor, 

Kemanlar, neyler artık çalmıyor, 

Güneş korkmuş, artık şafak sökmüyor.

Gün batıdan doğduğunda mı, geleceksin? 

Sur üfürüldüğünde mi, beni seveceksin? 

Yapma güzel! 

Yoksa, sen, hiç gülmeyeceksin, 

Bir kez baksan gözüme önce kendini, 

Sonra beni seveceksin, 

Mutlulukları benimle yaşayacak, 

Yıldız olup göklere serileceksin, 

Bekliyorum yolunu, 

Söyle! 

Ne zaman geleceksin?', 'Yaktığın kalpler huzur bulmuyor,  Gezdiğin gönüllerde hiç sabah olmuyor,  Kemanlar, neyler artık çalmıyor,  Güneş korkmuş, artık şafak sökmü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yapma-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanlı Yıldızlar', 'kanli-yildizlar-hasan-huseyin-memis-zqjck', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün, 

Çekip gittiler, 

Tarihi rollerini bitirdiler, 

Sırça saraylarına gömüldüler.

Onları, 

Melek sanmıştık, 

Çatımıza, 

Baykuş olup tünediler.

Kristal beyinleri, 

Lekesiz yürekleri, 

Geleceğimizi kirlettiler.

İlkeler, , ilkeliler yok, 

Yok artık karanfiller.

Meydanlar boş, 

Bomboş artık beyinler.

Yüreklerde, 

Sevgi tüketildi, 

Tüketildi, 

Gerçek sevgililer.

Gaflet, 

Dalalet, hayretlerde, 

Hıyaneti bile, maskara ettiler.', 'Bir gün,  Çekip gittiler,  Tarihi rollerini bitirdiler,  Sırça saraylarına gömüldüler. Onları,  Melek sanmıştık,  Çatımıza,  Baykuş olup tün...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kanli-yildizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamet', 'kiyamet-hasan-huseyin-memis-cndzn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kabus sandım, 

Yanıldım.

Adalet’i aradım; 

Barlarda çalışıyormuş.

Vicdan’ı sordum; 

Yol kenarında bekliyormuş.

Vefa’yı merak ettim; 

Artık, 

Anılarını yazıyormuş.

Dostluk düştü aklıma; 

Kilosu beş paraymış, 

Alıcı bulamıyormuş.

Dürüstlük, hapse düşmüş; 

Riyakarlık, 

Gardiyanlık ediyormuş.', 'Bir kabus sandım,  Yanıldım. Adalet’i aradım;  Barlarda çalışıyormuş. Vicdan’ı sordum;  Yol kenarında bekliyormuş. Vefa’yı merak ettim;  Art...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kiyamet-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoyrat', 'hoyrat-hasan-huseyin-memis-gkh0n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Amacın, 

Benimle oynamak sa, oyna! 

Benden bıktığında, 

Beni, 

Sandığına sakla; 

Bir gün olup, 

Oyuncaksız kaldığında, 

Çeyiz sandığındaki oyuncağını, 

Beni hatırla.', 'Amacın,  Benimle oynamak sa, oyna!  Benden bıktığında,  Beni,  Sandığına sakla;  Bir gün olup,  Oyuncaksız kaldığında,  Çeyiz sandığındaki o...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hoyrat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradışı', 'siradisi-hasan-huseyin-memis-x59t7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben erkeğim, 

Erkek ağlamaz deme, ağlarım.

Her damla göz yaşımla, 

Ya, 

Yürekler yakarım, 

Ya da, 

Yürekler yıkarım.', 'Ben erkeğim,  Erkek ağlamaz deme, ağlarım. Her damla göz yaşımla,  Ya,  Yürekler yakarım,  Ya da,  Yürekler yıkarım....', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siradisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şizofren Aşklar ve Uşaklar', 'sizofren-asklar-ve-usaklar-hamdullah-arvas-wi37n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koşar saat gece telaşı

Bir bakır şehrayiniydi ruhum

Nesneler lehimlendi bedenime

Yığın yığın oyuncaklar buldum

Sofralarla şizofren

Evciklerle paskalya 

Tuz kadar eski

Ve tanrı kadar gerçek

Sevgi kadar belki

Tapacak, tapacaktı yürek

Parçalandıkça köleleştim

Köleleştikçe efendileştim 

Gökler nasıl bir kuyuya açılırdı

Damlalar nasıl bir deryaya

Suya nasıl dokundu ateş

Sebebe nasıl sözleri 

Ellerim elleridir  şimdi

Gözlerim gözleri 

Yağmurlar yağıyor sahipsiz

Uçurumlar sarkıyor dipsiz 

Nerede? .. 

Cevaplarımın soruları

Gerçeklerimin düşleri

Hislerimin dokunuşları

Anlaşılan yaşamamalıyım

Yaşarsam ölmeliyim

Ölürsem yaşamamalıyım

Ben ölmeliyim 

Ben yaşamamalıyım yaşarsam

Tuz kadar eski

Tanrı kadar gerçek', 'Koşar saat gece telaşı Bir bakır şehrayiniydi ruhum Nesneler lehimlendi bedenime Yığın yığın oyuncaklar buldum Sofralarla şizofren Evciklerl...', ARRAY['Türk Edebiyatı','Şiir','Hamdullah Arvas']::text[], 8.5, '{"poet":"Hamdullah Arvas","poet_slug":"hamdullah-arvas","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sizofren-asklar-ve-usaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'RÜZGARIN YALANI', 'ruzgarin-yalani-poet-of-the-darkness-12iga', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Esen rüzgar anlatır sana hayatı

Dağıtır saçlarını ufka doğru

Ama gözlerin unutturmaz yalanları

Acılar söküp atar ruhunu

Taşın üstünde belirir sevginin izleri

Anılar doldurmaya çalışır içindeki boşluğu

Masmavi denizler kıskanır gözlerini

En sonunda hatırlatırım sana mutluluğu

Rüzgarın yalanını boşaltırım gözlerinden', 'Esen rüzgar anlatır sana hayatı Dağıtır saçlarını ufka doğru Ama gözlerin unutturmaz yalanları Acılar söküp atar ruhunu Taşın üstünde beliri...', ARRAY['Türk Edebiyatı','Şiir','Poet Of The Darkness']::text[], 8.5, '{"poet":"Poet Of The Darkness","poet_slug":"poet-of-the-darkness","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruzgarin-yalani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Z: Horozlu Ayna ve Ölüm', 'z-horozlu-ayna-ve-olum-cevdet-karal-s1nvh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sözlerimin buğusuyla söndürülsün

tabutumu taşıyan atların

nallarında başlayan yangın

ağzıma tutulan aynalarda

öten horozun boynu vurulsun', 'sözlerimin buğusuyla söndürülsün tabutumu taşıyan atların nallarında başlayan yangın ağzıma tutulan aynalarda öten horozun boynu vurulsun...', ARRAY['Türk Edebiyatı','Şiir','Cevdet Karal']::text[], 8.5, '{"poet":"Cevdet Karal","poet_slug":"cevdet-karal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/z-horozlu-ayna-ve-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Kar Kasidesi', 'siyah-kar-kasidesi-cevdet-karal-95xf6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hiçliğin o kekre tadı

vardığın her kıyıda

serin tapınaklara girdin durulmadın

serap öldü, rüzgar saldı

kumdan atlarını, bu son kum

sal/dı ya

ne sandın

şehvetli bir dua

gibi boşaldın

kasıklarından hayatın

denizlerde hep aynı fırtına

bilmem kaç kez yalvardım

allahım

bir cehennemden ötekine

savrulsun hayatım', 'hiçliğin o kekre tadı vardığın her kıyıda serin tapınaklara girdin durulmadın serap öldü, rüzgar saldı kumdan atlarını, bu son kum sal/dı ya...', ARRAY['Türk Edebiyatı','Şiir','Cevdet Karal']::text[], 8.5, '{"poet":"Cevdet Karal","poet_slug":"cevdet-karal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siyah-kar-kasidesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yeşil yankılanışlar', 'yesil-yankilanislar-rabia-can-ulas-vs3h1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'senin gözlerinden daha berrak

nerde yansıdımki ben

ben diyebildim kendi aksime

bir tek sende yaklaşabildim kendi gerçeğime.

unutulmuş içime öksüz kalmış geçmişime

sende yeşil yansılar oluştuktan sonra uğrayabildim..

ben en çok bakışlarında varolan bir gerçekliktim..

flu belirsiz ürkek yansılarında..

bazen ürküten, üşüten bazı zamanlar

ama düşündükçe ısıtan bir belirsizliktim, 

sen bende ben sende..

ama terki zor..

alışkanlık değil ama..

alışmamaya çalışma çabasıydık.

incinmemek için dokunmamayı öğrendiğimiz..

kaybetmemek için sahip olmamayı denediğimiz..

sisli bakıışlardı..

ömrümüz..

ama sesimiz ve düşlerimiz..

yetiyordu..

çoğaltmaya kendimizi..

ben sende öğrendim..

sevdaya çekimli vefakar bir çok fiili

ve cefakar bir ömre misafir olabilmeyi..

sende öğrendim kendimi bulabilmeyi..', 'senin gözlerinden daha berrak nerde yansıdımki ben ben diyebildim kendi aksime bir tek sende yaklaşabildim kendi gerçeğime. unutulmuş içime ...', ARRAY['Türk Edebiyatı','Şiir','Rabia Can Ulaş']::text[], 8.5, '{"poet":"Rabia Can Ulaş","poet_slug":"rabia-can-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yesil-yankilanislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-reha-basogul-kvtl0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Değiştirilemeyen acı diyarında...

Tarihi kandıramayan bir yavuz

saat seherin dördü, azbuçuk geçmiş dokuz

çarpışmalar, top sesleri, 

düşen soluksuz

kantar ise yine topuzsuz

korkunç sesin toprağı kaldırdığı devran

zeytin saçlı bebek yerde, ağlamayan

kanı kurumamış, mektuplu yerde yatan

yer: galibin olmadığı, olamayacağı vatan

umut...

yerde yatan ve ağlamayan

baksaydı birbirine o an

sorar mıydı günahsızı, sebebine

niye yaraşır, kalır bu insanlığın günlüğüne

cevap verir miydi geçmişi, geleceğine

yeter miydi soluğu söylemeye

hata idi, sevmelisin sadece

hüzün...

ah, ah arzuhal

bir soluğa muhtacım lal

akmayacaktın nehire böyle

olmayacaktı küllerden bir sal...

değiştirecekti böğürtlenler rengini

bırakmayacaktı güller peşini

aşk kalacaktı sadece

ve sadece bülbüllerin sesi

keder...

vurmayın artık yüreğine güm güm

eylediniz beni kudüm

nasıl dinecek bu hüznüm

hep ama hep yaşlı gözüm

sazlıklarımı  rüzgarsız bıraktınız

güzümü bile yapraksız

yeter artık isyan ediyorum desem

baharım geçecek şarkısız

aşk...

aklımı tutamıyor ellerim

dudaklarını yakalıyor dilim

anlamsızca çıkıyor kelimelerim

oysa daha okunaklı gözlerim

tangoların keskin dönüşleri

kemanların narin sesi

duvakların en incesi

bebeklerin minik ellisi

kin...

analar doğursa da yağızları

kaçırsada şehirlerden

çağırır kaderi

tez yayılırmış savaşın zehiri

ey beden avcılarının aradığı kurban

karşındaki, efendilerin koynundaki yılan

kanacaksın, sararacaksın, kızacaksın

alacak seni kayınlardan

ölüm...

doyamadan emzirilene

kanamadan sevdiğine

gençliğine geleceğine

mektubun verecek mukabele

ekin...

değiştirilemeyen acı diyarında

bıraktığım umutlarımda

karaladım hüzünlerimi

aşkıma sığındım

kinime yenik düştüm

ah ah arzuhal 

bir soluğa muhtacım lal

sevgi varken

ölüme kandı hayal...', 'Değiştirilemeyen acı diyarında... Tarihi kandıramayan bir yavuz saat seherin dördü, azbuçuk geçmiş dokuz çarpışmalar, top sesleri,  düşen so...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/mektup-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkiden Bir Çıkınca Yalnızlık Kalır', 'i-kiden-bir-cikinca-yalnizlik-kalir-omer-faruk-cakir-lqgrj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hava soğuktu, elleri de üşüyordu

Aslında

Avuçlarıysa terliyordu

Bir kağıt mendil çıkardı paketinden

İtina ile kapatarak

Avuçlarını sildi, yavaşça açarak

Gömlek cebini

Paketi koydu

Sevdiğinin gözlerinin içine

Bakarak

Henüz farkında değildi sevilen

Böylesi sevildiğinden

Uzunca bir zamandır vardı bu

Kişi

Yeni farkediyordu

Avuçlarının sıklıkla terlediğini

Bir rahatsızlıktan mı? diye düşündü

Hayır! bu olamazdı

O kadar rahattı ki kişi

Sevdiğinin gözlerinin içine bakarken

Ve çevredeki insanlırın

Rahatsız edici bakışları rahatsız etmiyordu o’nu

Güneşin

Gözlerini rahatsız ettiği kadar

Küçük bir poşet olmalıydı aslında

Farkındaydı

Aradığı o poşette değildi

Ama yine de şöyle bir kurcaladı

Kişi

Kısık bir ses tonuyla

Biliyordum dedi biliyordum

Belki dedim

Belki

Meraklı bir bakış oluştu sevilenin gözlerinde

Ve dudaklarında

Anlamadığını belirten bir ifade

Gözlerini kapadı kişi ve avuçlarını

Gözlerinin üzerine götürdü

“Kanlanmıştı” kişinin gözleri, yorgun

Bir ses; 

Pek bir alınganlaştılar dedi

Herkes gibi! 

Sevilenin dudakları

Anlamadığını belirten ifadeyi

Taşımaktan

Yorgun düşmüştü belli

Peki dedi kişi; 

“Gözdamlam benle aynı şehirde değil”

Zaten birşeyleri unutmadan

Bir başka şehre gitmişliğim vaki mi? 

Sahi dönmek vakti yakındır

Zaman huysuz bir çocuk gibi

Durmaz

Dakikalar süzülür zamanın süzgecinden

Gitmeye ve kalmaya dair

Söylendi herşey

Sıcak bir hatıra olacaktır birazdan

Herşey

Yer uzak diyarların yakın durağı

Işıklı... parlak... çirkin

Gitmekse gidiyordu kişi, 

Kalmaksa, kalıyordu

Gözleri sevdiğinin gözlerinde

Ve hasretlik koyuyordu şimdiden

“Bütün gitmeler şahit olsun diyordu 

Kişi; 

Nasıl ki gidiyorsam şimdi

Nasıl ki gidişimin tanığıysa gece

Bir gece

Şahitlik yapacaktır döndüğüm güne”

Ne çok gün geçti ne çok gece

Dönüp gelmeler oldu, çekip gitmeler 

Sonra 

Çıkmaz oldu bütün sokaklar

Küçük ayrılıklar oldu

Gün oldu, ay oldu yıl oldu hatta

Umut oldu sevilen her geldiğinde

İstenen hiçbir zaman olmadı

Gereklilik kondu adı

Ve sanki herşey yaşanmış gibi

Bir ayrılğın önünde durdular

Birazdan ayrılığa binip gidecekti sevilen

El ele tutuştular

“Bırak hasret binsin o ayrılığa

Sen kal, özlemler binsin, şiirler binsin

Her sabah

Sensizliğe uyanmalar binsin

Bırak ağustos binsin, 

Sensizlik binsin ayrılığa

Sen gitme, sen kal

Diyebilmek için yalvardı

Kendine

Kişi

Çare bilse söylediklerini

Söyliyecekti en sevdiğine, gecelerce özlediğine

Kişi sustu, dünya durdu

Elleri kopunca sevgiliden, ayrılığa adım attı sevilen

Mutluluk iki kişiyledir

Aşk iki kişiyle

İkiden bir çıkınca yalnızlık kalır!', 'Hava soğuktu, elleri de üşüyordu Aslında Avuçlarıysa terliyordu Bir kağıt mendil çıkardı paketinden İtina ile kapatarak Avuçlarını sildi, ya...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/ikiden-bir-cikinca-yalnizlik-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sitemdir', 'sitemdir-omer-faruk-cakir-ygmg1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geceyi bağlasalar ucundan bir diğerine

ortasında sönen umudumdur, günümdür

		aydınlık bir geceden bir geceye

yarin soluğu değer ılık rüzgarla sineye

ayrılığı bitirmez, biten sözümdür

		tükenir bir heceden bir heceye

rüyayı gerçek eylesem seslensem sevgiliye

mutluluk yazmaz ki kader, yazılan hep acıdır

		yürekler ezilir, bir sitemden bir siteme

yare haber salsam, ağıt yaksam gel diye

ne hasret biter ne sevda, biten ömürdür

		tenim solar, bir nefesten bir nefese', 'geceyi bağlasalar ucundan bir diğerine ortasında sönen umudumdur, günümdür 		aydınlık bir geceden bir geceye yarin soluğu değer ılık rüzgarl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sitemdir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir', 'sehir-omer-faruk-cakir-sud3q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geceleri bu şehrin tek sahibiyim ben

ses kesilince dolaşır ayak sesim caddelerde

ve o saatlerde bir tek benim ceplerim ıslanır

terlemiş ellerimle

birkaç şiir dökülür dudaklarımdan

hüzün renginde

daha, ne çöpçüler ne ekmek arabaları

serseri yalnızlığımdır bir tek beliren 

sokak önlerinde

sanmasın ki kaldırımlar

sebepli sebepsiz hep onlar ezilir

sokak sokak gezdirdiğim yüreğim

hepsine ibreti alemdir', 'geceleri bu şehrin tek sahibiyim ben ses kesilince dolaşır ayak sesim caddelerde ve o saatlerde bir tek benim ceplerim ıslanır terlemiş elle...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sehir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gökyüzü', 'gokyuzu-omer-faruk-cakir-zfgvj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gökyüzü

haykırırken gece karanlığı

bir yıldıza takıldı gözüm

parlıyordu! 

bu yüzdendir en tükendiği anlarda

gözlerimi gökyüzünde asılı bırakmam', 'gökyüzü haykırırken gece karanlığı bir yıldıza takıldı gözüm parlıyordu!  bu yüzdendir en tükendiği anlarda gözlerimi gökyüzünde asılı bırak...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gokyuzu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'beş satırla', 'bes-satirla-omer-faruk-cakir-em8ih', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugünlerde ölebilirim

yaşıyorda sayılmam aslında

yanımda olduğun birkaç gün dışında

yokluğun binbir gece

bugünlerde ölebilirim öyleyse!', 'bugünlerde ölebilirim yaşıyorda sayılmam aslında yanımda olduğun birkaç gün dışında yokluğun binbir gece bugünlerde ölebilirim öyleyse!...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bes-satirla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tabir', 'tabir-omer-faruk-cakir-esjm8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hiçbirşey değişmemiş

eskisi gibi herşey

bıraktığım gibi hala

ne hasret yaşanmış sanki

ne sevda

seneler eskitmemiş genç bedenleri

o yaşlı bina

hiç yaşlanmamış, mesela

dökülmemiş kenarların sıvası

kapısı halen yeşil ve 

“bekledim gelmedin”

eski zamanlardan bir yazı

hitabı; eski zamanlara

tahta masasında gülümsüyorsun

karşımda, eski bir radyo, suskun ama

konuşmaya meyilli dudakların

sözlerinse kör düğüm

sözlerinse hayatım

sözlerinse çıkmazda', 'hiçbirşey değişmemiş eskisi gibi herşey bıraktığım gibi hala ne hasret yaşanmış sanki ne sevda seneler eskitmemiş genç bedenleri o yaşlı bin...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tabir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesim üşüyor... Titriyor seslenişlerim', 'sesim-usuyor-titriyor-seslenislerim-gokhan-oktem-9nq7x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sesim üşüyor....üşüyor sesim...

Ondandır bakışlarımın donukluğu.. 

Ondandır titrek seslenişlerim... 

Sevdaya dair mırıldanmalarım da ondandır.. 

Kendimi koy vermişliklerim de kavgaya dair... 

Ondandır...

Nicedir şöyle adamakıllı bir şiir yazamayışlarımın bir sebebi olmalı... 

Tırpanlanan duygularımla seviye yelken açamayışlarımın bir açıklaması...

Her başlangıçta kanayan bitişlerime dair bir neden 

Ya da susuşlarımda gizlenen nedenler girdabında  bir çözüm...

Bir sebep...

Bir açıklama...

Bir neden... 

Bir çözüm...

Yaşanmışlıklarımı mı şöyle bir gözden geçirmeliyim öncelikle 

Yoksa ufka kilit gözlerle geleceğe mi yaslamalıyım benliğimi... 

Önceliklerimi mi yaşamalıyım bir tercih olarak olayları değiştirme inancıyla...

Yoksa her şey olacağına varırlara mı vurmalıyım kendimi başıboş...

Bir soru....

Sesim üşüyor...üşüyor seslenişlerim... 

20 asrın son çeyreğinde göz açtığım bu dünya yabancılaşıyor bana..

Bu ülke, bu dil, bu coğrafya...

Ellerimin arasından akıp gidiyor tüm bildik tanıdık yüzler, duygular ve mekanlar...

Buldukça kaçıyor, yakaladıkça uzaklaşıyorum ve tanımaya çalıştıkça yabanlaşıyorum sanki.. Anlamsızlaşıyor bir benler diyarındaki gezintilerim... 

Anlamsızlaşıyor masumiyetimle birlikte kaybettiğim yutkunuşlarım...

Üşüyen sesim cılız çabalar bırakıyor peşi sıra 

Ve yalnızlıklarımda boğulan yüklenişlerim sonuç vermiyor seviye dair.. 

Bezginliktendir belkim, belkim kör talih, kader....

Hissiyatım bir başkalaşım içinde sanki... 

Boş vermişliklerim buluyor kendini her şey olacağına varır düşüncesinde...

Ve bu düşünce kaplıyor bensizliğimin devr-i alemini...

Boğuluyorum...

Sesim üşüyor, titriyor seslenişlerim

Sabah ayazını yemiş evsizler kadar sefil

Ve dokunsan iki gözü iki çeşme ağlayacak içli bir çocuk kadar dolu

Ve yayından fırlayacak bir ok kadar gergin..

Ve sefil, 

Ve dolu, 

Ve gergin...

Sesim üşüyor, titriyor seslenişlerim

Titreyen sesim üşüyen ses tellerimin yankıması belki

düzensiz, ritimsiz, ve titrek...

Yankıyan  iç seslerimin ağıdı belki de 

İçli, buğulu, ve burgulu...

Bir haykırış dizesinden sebepsiz dökülen 

Bir çığlık inceliğinde hazin 

Ve asi ve çırpısız  bir  başkaldırış güzelliğinde...

Köklü, ıslak, ve diri, 

Bir başkaldırış güzeliğinde... 

Bir sevda, bir şiir, bir kavga gibi

Bir eylem, bir yüklem, bir emek...

Ve tarih, 

Ve zaman, 

Ve kainat, 

Ve ölüm, 

Ve hayat....

Ve tek ülkü, 

Ve tek bilek, 

Ve tek yürek....

Bir başkaldırış güzelliğindeydi

İçimi dolduran 

Ve köklerini geçmişten alan bu aidiyet

(İstanbul,20,01,2002)', 'Sesim üşüyor....üşüyor sesim... Ondandır bakışlarımın donukluğu..  Ondandır titrek seslenişlerim...  Sevdaya dair mırıldanmalarım da ondandı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/sesim-usuyor-titriyor-seslenislerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece mi olur koyu kendi karamdan gayrı?', 'gece-mi-olur-koyu-kendi-karamdan-gayri-muammer-erkul-8gb0o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Gece  mi olur koyu kendi karamdan gayrı? ..''

Karanlıktı...

Hayır “ben” karanlıktaydım! 

Bir ışık gördüm; hem ırak hem yakın...

Bir ışık gördüm; zayıf gibi kuvvetli, ince gibi kalın! ..

Veya; bazen görünüp bazen kaybolan; bazen büyüyüp bazen küçülen; bazen elle tutulurcasına şurda gibi ve bazen de yok kadar uzak! ...

...

gece olur mu daha karanlık; insanın kendi karanlığından? ..

işte, bendim karanlıkta olan, gördüğümde gökteki ay’ı

***

Ben, kendi içimdeki karanlığımda, kendi kendimle toslaşınca, iki “ben” peydah  oldum  kendimden; her biri diğerinden ayrı düşünen...

Dedim ki bir benle; 

“bu ay, bu nurdan madde muhhteşem! ..bu ay; akıl almaz bir ışık kaynağı; ki bütüün ayağı toprakta sürünenlerin ilhamı, vazgeçilmezi...bu ay, bundan böyle kılavuzumdur benim! ..”

YANILDIM.

Ardından hemen atılıp, diğer benle dedim ki, 

“bu ay, beş para etmez...bu ay, ayağımla ezdiğim şu topaçtan bile değersiz taş ve toprak yığını...bu ay, en karanlık gecelerde bile bakmaya değmez! ..”

...

GENE YANILDIM...

***

Şimdi ben  “SANA”  bakarken karanlığın içinden...

Ve bilirken, benim duramadığım açılarda bulunup; parıl parıl bana ışık yansıttığını...nasıl bakabilirim senin kirine, tozuna, saçının tıraşına? ..

Veya ben, ışığı benden bilip, yüzünü bana dönenleri görünce; nasıl unuturum çiğnenen toprak kadar bile, değerim bereketim ve hükmüm olmadığını? ..

***

Seni bilmem ama ben; “kendimdim” karanlıkta! ..

Ve işte tam burda durduğum için...

Yani yansıyan ışığı değil; “ışığı KİMİN yansıttığını” düşündüğüm için yanılan bendim...

...

ve de, unutan bendim; 

insanın, kendi karanlığından daha koyu gece olmayacağını! ..', '''Gece  mi olur koyu kendi karamdan gayrı? ..'' Karanlıktı... Hayır “ben” karanlıktaydım!  Bir ışık gördüm; hem ırak hem yakın... Bir ışık gör...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erkul']::text[], 8.5, '{"poet":"Muammer Erkul","poet_slug":"muammer-erkul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gece-mi-olur-koyu-kendi-karamdan-gayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-ozcan-unlu-ll1hz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SıR

En son kuşlarla konuşuyorum, geceye dönerken

Çatılarda tüneyen seslere bakıp...

Ellerinde uyanacak dudaklarını düşlüyorum

Üflüyorum gecenin gaz lambasına

Parmaklarını öpüyorum...

Gidiyorsun...

Susuyor ve gidiyorsun...

İmece topluyorum, ipini çekmek için gecenin

Güneş ne çok uzakta, 

Ne çok yakında gece....

Savaşa giden askerler anlar beni, 

Yattığım sensizlik siperinde.

Ve kör kuyularda büyürken karanlıklar, 

Zehirli sarmaşıklar dolanır dilime...

Bir sürgünü yaşıyorum, 

Sıkıyorum yumruklarımı, 

Taze aşklar geliyor her sabah güneşle yâr...

Hepsi günahtan uzak, 

Ve yakın sesin kadar yüreğime....

Sen dinç zamanlarımın korkusuz rengi, 

Günü gülistana çeviren sırsın

Tılsımın satılmaz hiçbir pazarda, 

Öpersin güneşi uyandırırsın, 

Her sabah isyanımı dindiren sırsın....

Özcan ÜNLÜ', 'SıR En son kuşlarla konuşuyorum, geceye dönerken Çatılarda tüneyen seslere bakıp... Ellerinde uyanacak dudaklarını düşlüyorum Üflüyorum gece...', ARRAY['Türk Edebiyatı','Şiir','Özcan Ünlü']::text[], 8.5, '{"poet":"Özcan Ünlü","poet_slug":"ozcan-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sir-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden bu kadar çoksun', 'neden-bu-kadar-coksun-baris-akm-geqcg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden bu kadar çoksun? 

Her sessiz adımda rüzgarın

Her gözde sen varsın

Bakışlar neden illede sen

Telefonlarda sen

Arkasından gelen suskunluk 

Her ismin ardından gelen

Hep sen

Hangi şiirin perdesini aralasam

Ne zaman bir öyküyü kaldırsam

Sen dökülürsün arasından

Acaba, acaba sen hangisisin? 

Neden bu kadar çoksun

Ya ben, neden az değilim

Neden sen çoğaldıkça çoğalıyorum

Nerede birini görsem

Dudaklarında zehir zenberek 

Zil-zurna sarhoş dizeler

Sen doluyorsun gözlerime

Yokluğun öpüyor karanlığımı

Ben aynı ben, çoğaldıkça sen

Sen gibi çoğalıyorum dinmeden 

Ne zaman bir şarap şişesi

Sen misali dudağıma değse

Gene sen! bulutların prensesi

Çoğalırsın deli deli, içime doğru

Ateş sarar dağınık zerrelerimi

Sen çoğaldıkça ben parçalanırım

Çoğalırız seninle ben

Ne zaman postamda bir mektup görsem

Hafiften de nemliyse bir köşesi

Yüreğimden taşar okyanus dalgaları

İşte bak yine çoğalıyorsun

Adın çıkmazsa hep olduğu gibi

Ben bölünür doldururum ırmakları

Sen çoğaldıkça sanmaki ben azalırım

Ne zaman kayıp bir hikaye duysam

Yar diye diye umutlu tanelerce

Sevdiğinin dalından kopmuş meyvesi

Bir de gözleri ağlamaklı ise

Sensiz başım düşer omzumdan yere

Sen yine çoğalırsın gözlerimde

Ben azalır mıyım sanırsın

Yüreğimde adın mıhlı kaldıkça

Gittiğin yerde kal hadi

Unut yaşanmış yaşanmamışlığı

Bir kırmızı gül var elimde şimdi

Buğusunda adın gizli

Bekleyeceğim gül kurusu olmasını

Sonra unuturum belki seni

Sensizlikte bir gün

O muhteşem huzur sarar

Sen yerine beni

barış', 'Neden bu kadar çoksun?  Her sessiz adımda rüzgarın Her gözde sen varsın Bakışlar neden illede sen Telefonlarda sen Arkasından gelen suskunlu...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/neden-bu-kadar-coksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla unutulmayacaksın', 'asla-unutulmayacaksin-i-lkay-yuvka-5v85i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İ çimde hep anılar, hep geçmiş dolanıyor.

L anet okuyorum biten umutlarımın ardından.

K elimeler anlamıyor sana olan sevgimi.

A rkanda öyle bir kalp bıraktın ki, 

Y okluğunla beslenip acınla büyüyen.', 'İ çimde hep anılar, hep geçmiş dolanıyor. L anet okuyorum biten umutlarımın ardından. K elimeler anlamıyor sana olan sevgimi. A rkanda öyle ...', ARRAY['Türk Edebiyatı','Şiir','İlkay Yuvka']::text[], 8.5, '{"poet":"İlkay Yuvka","poet_slug":"i-lkay-yuvka","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asla-unutulmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrıçanın İç Sesi', 'tanricanin-i-c-sesi-ay-kalabaligi-eprnm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşka küflü bir nefesle bulaşan 

geceyi ininden sıyırıp güneşe çıkaran

tarihsiz bir yalnızlığın iklim değiştirdiği bahçelerde

sana adanmış kuşlarımın kafataslarını topluyorum

şimdi onlarca böcek var içinde.

Su hemen akmıyor çıldırdığında nehirler, 

ateş kendini bile ısıtmıyor.

Umudun heyacansız bekleyişinde yüzüyor periler

Kanlı oraklarla yaşamı biçiyor

ağzında kirli umut kokusuyla zebaniler.

Kulakları yırtan bir sesle mermerin üstüne yayılan yüzüm

gerçeğin dümdüz ettiği beynime vuruyor.

Vurdukça ölü kuşların kanatlarına yapışıyor özüm

sana yapışkan bir nefesle adıyorum kendimi

böcekler tabutuma sarılınca ağlıyor ölüm.

Duvarlar içe doğru nem tutar

bir deniz kazasında martılar vurur açığa

beynime yığılan kumun ardında kertenkeleler

kuyruklarını bırakıp kaçar boşluğun ağzına

ardımdan gölgeler alınır, gölgem bana yas tutar.

Göğsündeki ıslaklığımla ısıtıyorum saçlarımı

bir ip saklıyorum koynumda geçmişin uzantısı

aslında bir darağacına asılı cinayet tanığım onlar

çeksem bir dizi ceset toplanır kırgınlığıma 

saklansam yok olur önümde kısır bir tay gibi yaşam.

Bir yol bulur kendine parmak uçlarım

akrepleri zehirleyen dizeler bırakır siyah aynalara

şafak kızarırken utancından, coşkuyla akar kanım 

delirir şeytanlarım ruhumda açan zambak kokusuna

delirir ruhum, ışıktan kan gelir.

Ölüler evinde mezarlar açılır yaşama

Başkaldırır korku yokluğa

ve kırılır tomurcuk erken gelen soğuğa

damarlarında topraktan emdiği tuz kalır

geçince unutulur içinde aşk kopan fırtına.

Sana şehvetin sunağında yanan çiçekler veremedim

olmadı ten kokusu bulaşmış gece yarılarımız

korkmadan sarılsam da çıldırtan bir hevesle

sırtımdaki soğuk yardı eskinin çıbanını

yüzüm yoktu kasıklarım ağrıdığında sana sokulmaya.

Senin için yara değil, korku, acı değil

senin için kızaran bir gök biriktiriyorum

bozulmamış düşlerimi, atılmamış tarihleri

biriktiriyorum aklımın saçtığı güneşli tohumları

açacaklar deniz yiterken günün yamaçlarında.

Sana sonsuzun kısrağıyla koşuyorum

demir bir yürek taşıyorum ayağa kalkınca ışıyan

donmuş resimlerden siliyorum adını 

sana dudaklarıma dokununca içime açan 

soluğumla yanan bir gül sunuyorum.

Kanamıyor sesimde açılan kurşun yaralar

pişmanlıklar vuruyor kendini uzağımda

seninle dağılıyor korkunun zehirli saçları

ateş seninle ısınıyor gece sana açıyor yalnız kanatlarını

şimdi yaşamın bir anlamı var diyor yaralı martı.

Tanrıya sarılır gibi sarılırken sana 

aşktan ve mutluluktan çıldırırken

iç sesimle konuşmayı öğrendim.

(Temmuz 2001)', 'Aşka küflü bir nefesle bulaşan  geceyi ininden sıyırıp güneşe çıkaran tarihsiz bir yalnızlığın iklim değiştirdiği bahçelerde sana adanmış ku...', ARRAY['Türk Edebiyatı','Şiir','Ay Kalabalığı']::text[], 8.5, '{"poet":"Ay Kalabalığı","poet_slug":"ay-kalabaligi","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/tanricanin-ic-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SENSİZ BİR GECE', 'sensi-z-bi-r-gece-esra-yilmaz-jda5l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine sensiz bir gece

Ve ben

Seni düşünüyorum...

Dudaklarımda

Hiç bir zaman söyleyemediğim

Bir kaç hece

SENİ SEVİYORUM...

Ve sanki sensizlik bir bilmece

Çözemiyorum...

Rüyalarıma giriyorsun gizlice

Uyanıveriyorum...', 'Yine sensiz bir gece Ve ben Seni düşünüyorum... Dudaklarımda Hiç bir zaman söyleyemediğim Bir kaç hece SENİ SEVİYORUM... Ve sanki sensizlik ...', ARRAY['Türk Edebiyatı','Şiir','Esra Yılmaz']::text[], 8.5, '{"poet":"Esra Yılmaz","poet_slug":"esra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensiz-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİRDAPTA BİR GÜL MÜ?', 'gi-rdapta-bi-r-gul-mu-esra-i-clal-q92d3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'girdapta bir gül mü?

Asiler gibi yanacak mı bu yalan? 

Sus! 

Bir kelime 

Söyleyemesin dilin...

Kimsin? 

Seni parmaklarıma

el değmemiş gecelerime

taşıyan kim? 

Rüzgarın mı bu koku

Yoksa sen mi ayarttın rüzgarı 

Kokunu taşıması için..? 

Gülerken; 

Göremediğim gözlerin, 

Sesinle dans ediyordu. 

ve sesin; 

kaldırmaya hazır 

yere serilmiş hayalleri

kimsin? 

Ensemde tevbesi geç kalmamış

Günahların soluğu...

Yüreğimde, 

Şaha kalkan beklentilerin

Savaş naraları...

Darağacında sallanan 

dilim. 

Celladı ise benim! 

Suskunluğum bu yüzden 

Anla 

ve 

konuş şimdi 

Kimsin? !', 'girdapta bir gül mü? Asiler gibi yanacak mı bu yalan?  Sus!  Bir kelime  Söyleyemesin dilin... Kimsin?  Seni parmaklarıma el değmemiş gecele...', ARRAY['Türk Edebiyatı','Şiir','Esra İclal']::text[], 8.5, '{"poet":"Esra İclal","poet_slug":"esra-i-clal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/girdapta-bir-gul-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anacığım', 'anacigim-esra-i-clal-7ix8m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ana; 

Sensiz akşamlar duman tütmez bacalardan

Yürekler çılgın türküler söyler, diller sukut eder

Gözler feryat eder, dudaklar gözyaşı döker

Yitik bir mananın figüranıdır eller...

Bilmezdim böylesine acılığını ayrılığın

Ve duyamazdım kokusunu yokluğun

Ana! 

Git ve mutlu ol bilinmezlik ülkesinde

Ama beni terk etme...!', 'Ana;  Sensiz akşamlar duman tütmez bacalardan Yürekler çılgın türküler söyler, diller sukut eder Gözler feryat eder, dudaklar gözyaşı döker ...', ARRAY['Türk Edebiyatı','Şiir','Esra İclal']::text[], 8.5, '{"poet":"Esra İclal","poet_slug":"esra-i-clal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anacigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Adı Yaşanan', 'askin-adi-yasanan-esra-i-clal-ppjfx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 've gidiyorum

ikiyi kırk geçe

Yalnızlığın olmadığı aynalar arıyorum

Vakit gece...

      Rüzgar örüyor saçlarımı

      Aydınlığı yaktığım kandilden

      Rafa kaldırdım uykularımı

      Gözlerim; 

      görsün diye, yalnızlığın olmadığı anı.

ve gidiyorum

vakit gece...

Feryatta yüreğim

Ramak kalmış fecre

Karanlıkta bir gaip, soruyor

“hiç yalan söyler mi parmakların? ”

Susuyorum...

Vakit gece

Gaip soruyor

“bildin mi

öncesi hüzün olan

yalnızlığın ardından gelen aşkı? ”

Düşünüyorum...

Vakit gece...

      Aşkın adıydı

      Gecelerde eskiyen

      Raflarda, tozlanan

      Uykuları bölen.

      Aşkın adıydı yaşanan! 

Ama aşktı; 

Yüzleri güzelleştiren, aynalarda

Merhaba derken fecre

Aklımdan geçirmedim

Teslim olmayı 

Yine de! ! ! 

                                             22.08.01', 've gidiyorum ikiyi kırk geçe Yalnızlığın olmadığı aynalar arıyorum Vakit gece...       Rüzgar örüyor saçlarımı       Aydınlığı yaktığım kand...', ARRAY['Türk Edebiyatı','Şiir','Esra İclal']::text[], 8.5, '{"poet":"Esra İclal","poet_slug":"esra-i-clal","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/askin-adi-yasanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgu', 'sorgu-esra-i-clal-gnr12', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana 

Gözyaşının seyrini; 

Aşk şiirleini

Ulaşılması kolay

Gizli hazineleri

Celal ve İkram sahibi ile

Konuşmayı öğreten

Üstadlarım, 

Sana gelen yolu

Göstermediler..! 

Bir ömür boyu

Anlamsız kıldılar 

varlığını, 

Ve ben 

anlayamadım

gönlümün amansız haykırışlarını...', 'Bana  Gözyaşının seyrini;  Aşk şiirleini Ulaşılması kolay Gizli hazineleri Celal ve İkram sahibi ile Konuşmayı öğreten Üstadlarım,  Sana gel...', ARRAY['Türk Edebiyatı','Şiir','Esra İclal']::text[], 8.5, '{"poet":"Esra İclal","poet_slug":"esra-i-clal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sorgu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun', 'sen-yoksun-esra-i-clal-m27bs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir at cesareti ile geldin kapıma

bir deniz coşkusu bakışlarında

bir gül masumiyeti tebessümünde

bir elif miktarı ile söyledin ismimi

bir hanımeli ferahlığıydı kokun

bir incir mübarekliği vardı ellerinde

bir dağın asaleti attığın her adımda

bir merhaba sancısı idi gidişin

bir martı çığlığı ile veda ettin

Gittin, 

Bittim... 

                                                        19.06.01', 'bir at cesareti ile geldin kapıma bir deniz coşkusu bakışlarında bir gül masumiyeti tebessümünde bir elif miktarı ile söyledin ismimi bir ha...', ARRAY['Türk Edebiyatı','Şiir','Esra İclal']::text[], 8.5, '{"poet":"Esra İclal","poet_slug":"esra-i-clal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-yoksun-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Sanrısı', 'eylul-sanrisi-esra-i-clal-5mx0r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hislerin gizlendiği

Dostlukların tükendiği

Gözyaşının zamansızlaştığı

Uykuların ağırlaştığı

Anaların hırçınlaştığı

Canların hoyratlaştığı

Mananın arandığı

Bir Eylül geride kalan...

Sonrası

Merhaba

01.10.01', 'Hislerin gizlendiği Dostlukların tükendiği Gözyaşının zamansızlaştığı Uykuların ağırlaştığı Anaların hırçınlaştığı Canların hoyratlaştığı Ma...', ARRAY['Türk Edebiyatı','Şiir','Esra İclal']::text[], 8.5, '{"poet":"Esra İclal","poet_slug":"esra-i-clal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/eylul-sanrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BEN OLSAYDIM...', 'ben-olsaydim-fatih-gunaydin-c66nh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu ilk düşüşüm yerlere, 

  ve bu ilk ihtiyacım, 

                                ilk çaresizlik...

Boşlukta kalan yaralı eli ilk tutan SEN olsaydın.

Bir çölün en kızgın halinde, 

çatlamaya gebe dudaklarıma, 

akan bir damla su SEN olsaydın.

En umutsuzca gözlerimi kapadığım gece, 

Rüyama giren ilk güzel, 

gözlerimi açtığımda bir seher vakti, üstümedoğan, ilk güneş SEN olsaydın.

Yokluğunda, 

                  kaybettiğim en büyük değer SEN, 

VE sensizliğe ağlayan tek yürek BEN olsaydım...........', 'Bu ilk düşüşüm yerlere,    ve bu ilk ihtiyacım,                                  ilk çaresizlik... Boşlukta kalan yaralı eli ilk tutan SEN o...', ARRAY['Türk Edebiyatı','Şiir','Fatih Günaydın']::text[], 8.5, '{"poet":"Fatih Günaydın","poet_slug":"fatih-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-olsaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DİLEK', 'di-lek-fatih-gunaydin-218ix', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir saniyede olsa 

öylece bakmaktı gözlerine, 

   hasretle kucaklamak...............

Ve sen her aklıma düştüğünde, 

hıçkıra hıçkıra ağlamaktı birgece

en güzel gecenin son düşünde, 

sen gözlerimde kaybolmadan uyanmak..................', 'Bir saniyede olsa  öylece bakmaktı gözlerine,     hasretle kucaklamak............... Ve sen her aklıma düştüğünde,  hıçkıra hıçkıra ağlamakt...', ARRAY['Türk Edebiyatı','Şiir','Fatih Günaydın']::text[], 8.5, '{"poet":"Fatih Günaydın","poet_slug":"fatih-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dilek-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi Ağlatan Kadın', 'geceyi-aglatan-kadin-duahan-hanci-vi9b4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kehribar renkli saçları omuzuna dökülmüş 

Gözlerini günlerce kanlı yaşlar bürümüş 

Dünya ona değil o dünyaya tam küsmüş 

Bir narin çiçekti o hep kırılıp dökülmüş...

Sanki dünyanın tüm derdi çöktü sırtına 

Umudu hiç kalmadı mutlu yaşamdan yana 

Kederler geldi hep, ayrılık peşinsıra 

Sevgiler, mutluluk, yaşamında kapkara...

Işıklar tükendi kadının aydınlık dünyasında 

Gündüzler gece oldu karanlık her yanında 

Uzansa bir ışık yok kahretti dostlarına 

Anladı ki tüm dostluklar zeval yollarında...

Gece onun tek dostu tek sırdaşı olmuştu 

Sabahlara dek başbaşa mutsuzlukla dolmuştu 

Karanlıklar gözyaşlarına kara bir kucak olmuştu 

Dertleşti gecelerce artık gün açmaz olmuştu...

Göklerde yıldızlar vardı hepsi bir bir söndü 

Mehtabın kızıl rengi hep siyaha büründü 

Ümit yok beyazlara sanki birbirine küstü 

Kehribar saçlı kadının saçları aklara döndü...

Bir gece sabaha dek kanlı bir yağmur yağdı 

Hıçkırıkla boğulan güçlü şimşekler çaktı 

Her tarafı kara sis kara duman kapladı 

Anladı ki o kadın, sonunda gece de ağladı...', 'Kehribar renkli saçları omuzuna dökülmüş  Gözlerini günlerce kanlı yaşlar bürümüş  Dünya ona değil o dünyaya tam küsmüş  Bir narin çiçekti o...', ARRAY['Türk Edebiyatı','Şiir','Duahan Hancı']::text[], 8.5, '{"poet":"Duahan Hancı","poet_slug":"duahan-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/geceyi-aglatan-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her An', 'her-an-duahan-hanci-v1o0k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hain çınlayışıyla her an 

gönlümün saatine ayrılıklar vururdu. 

sarsılırcasına uyandırılırdım, uykular dururdu, 

uykuların bittiği, zamanın çınladığı gözlerimde. 

umutlarım bitmişti bir yerlerde, 

o yerden sen çıktın karşıma, 

belki istemeden, 

mutluluk şişesinin deli eden içkisinden, 

sarhoş olana dek içtim. 

bilemedim! 

sen de umutlandın mı için kan ağlarken, her an... 

çok sevdalar geçmişti gönlümden. 

belki binlerce bakış geçti gözlerimden. 

bilmem kaç kez yandı yüreğim? 

gidişlerden, hasretlerden, kederlerden... 

şimdi anlarım ki; 

bir sen varsın içimde her an. 

sadece senin gözlerin. 

ve sadece: 

senin gidişlerin vurdu beni hissettirmeden... 

anlarım ki; 

bir sen bakmışsın gözlerime, 

kaçamak ve derinden... 

istemekle olmuyor her şey 

olsaydı gitmezdin hiç 

bakışlarını verirdin bana 

titreyen ellerimi tutardın bir an 

sıcak bir buse olurdun alnımda 

öperdin beni, her an, her an, her an... 

elini göğsüne attığında dokunuyorsun ya bana, 

öylesine içindeyim bilirim. 

hafif sarhoş olup gülümsüyorsun ya bana, 

inan öylesine sıcak içimdesin her an. 

o çocuk kokan göğsüne dayasaydım başımı, 

ılık ılık okşasaydın saçlarımı her an. 

''yaşamak işte bu'' derdim... 

''işte ben o''nunum'' derdim... 

bil ki; bana senden başkası haram. 

her yerde tenin kokar. 

yel estikçe kokun gelir buram buram. 

esen her yel hatırlatır seni her an. 

belki seninle başladım hayata yeniden. 

sanki nefesimmişsin gibi, 

sindiririm içime seni her an. 

sanki yanımdaymışsın gibi, 

kucaklarım hayalini her an. 

sanki ezelmişsin gibi, 

yaşarım seni her an. 

''sevgin biter mi'' diyorsun bana, 

söyle sende biter mi bir an? 

içimde öyle bir sen var ki, 

öyle büyük sevgin var ki, 

çıkarabilir miyim seni içimden bir an. 

yaşanır mı havasız, susuz? 

yaşayabilir miyim bir ömür sensiz? 

benim değilsin bilirim. 

sanırım ki! 

dünyada bir benim böyle çaresiz. 

çaresizlik öyle bir çöreklendi ki yüreğime, 

savaşıyorum amaçsızca her an, her an. 

avuntum sözlerinde, gözlerinde. 

çekme gözlerini gözlerimden bir an. 

hiç olmazsa düşün beni bebeğim. 

uzaklara gitsem de birgün istemeden, 

bil ki muhtacımdır buna. 

sev beni, özle beni. 

her an, her an, her an', 'hain çınlayışıyla her an  gönlümün saatine ayrılıklar vururdu.  sarsılırcasına uyandırılırdım, uykular dururdu,  uykuların bittiği, zamanın ...', ARRAY['Türk Edebiyatı','Şiir','Duahan Hancı']::text[], 8.5, '{"poet":"Duahan Hancı","poet_slug":"duahan-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/her-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşım', 'paylasim-duahan-hanci-g0m7p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'paylaşım görecelerle doludur. 

kimilerine göre, bir yudum sudur paylaşım 

kimilerine göre ise, beraberliğin bir diğer adıdır. 

eğer, ben seni sevmişsem dolu dolu, 

yüreğini paylaşmışımdır. 

o yürek hem senin, hem de benim için atıyor demektir. 

eğer dalıp gitmişsem kara gözlerinin derinliğine, 

bakışlarını ve gözlerini paylaşmışımdır. 

tuttuğum zaman sıcak ellerini, 

sıcaklığını paylaşmışımdır. 

ya da sarılsam sana, 

şevkatli kollarını paylaşmışımdır. 

tatlı bir sohbet geçiyorsa aramızda, 

cümlelerimizi paylaşıyoruz demektir. 

bu benim için ne demektir bilir misin? 

eğer bir kutlama yapıyorsak seninle mutluluğa dair, 

işte o anı paylaşıyoruz demektir. 

sevinçliysen o gün ve sebebini bana anlatıyorsan, 

sevincini paylaşıyoruz demektir. 

paylaşım ne demek değil ki? 

geceleri, hayalini kare kare çizerek uyumaya çalışıyorsam, 

gecelerimi paylaşıyorumdur seninle. 

gecenin kör karanlığında, 

bir ışık gibi alıyorsam seni rüyama, 

rüyalarımı paylaşıyorumdur seninle. 

aynı biçimde sen de öyle gece gözlü yar. 

eğer ortak düşünceler sarmışsa bizi çepeçevre, 

işte biz fikirlerimizi paylaşıyoruz. 

yeter ki sen iste gülüm. 

mutlulukları paylaşırız, acıları paylaşırız. 

şair diyor ya: 

''''yalnızlık paylaşılmaz paylaşılsa yalnızlık olmaz'''' diye 

bir paylaşıma girmişsek ikimiz, yalnızlık zaten olmaz. 

sonuçta beraberizdir. 

işte bebeğim. 

sevincimizi paylaşırız, 

hüzünlerimizi paylaşırız. 

ekmeğimizi, suyumuzu paylaşırız. 

cüzdanımızda kalan son lirayı paylaşırız, 

ve sonuçta beraber oluruz. 

pakette kalan son sigarayı paylaşırız, 

bir nefes sen bir nefes ben. 

benim paylaşım anlayışım seninle dolu. 

yeter ki sen iste ve ''gel'' de, 

bir ömrü seninle paylaşırız...', 'paylaşım görecelerle doludur.  kimilerine göre, bir yudum sudur paylaşım  kimilerine göre ise, beraberliğin bir diğer adıdır.  eğer, ben sen...', ARRAY['Türk Edebiyatı','Şiir','Duahan Hancı']::text[], 8.5, '{"poet":"Duahan Hancı","poet_slug":"duahan-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/paylasim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLK SON', 'i-lk-son-fatih-gunaydin-dpa7t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu son bakış gölerime, 

          son tutuşun ellerimi, 

 ve bu akan, ilk göz yaşım.

                     ilk korkum, 

                     ilk defa kalışım bir başıma, 

ve bu son yalvarışım kaldiye.

                      ilk bakışın; bir gülüş, 

                                        bir sevinç, 

                                        bir umut.

Ve bu ilk terk ediliş, 

            ilk hüzün, 

            ilk hasret.

omuzlarında son uykum 

                      ilk uyanmayışım.

         son bakış, 

         son tutuş, 

ve ilk gözyaşım.................', 'Bu son bakış gölerime,            son tutuşun ellerimi,   ve bu akan, ilk göz yaşım.                      ilk korkum,                       ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Günaydın']::text[], 8.5, '{"poet":"Fatih Günaydın","poet_slug":"fatih-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ilk-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşağılık Aşk', 'asagilik-ask-gurcan-gunay-ojash', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Köşebaşında rasgeldi yine bu sabah

Eski masum bakışlarından eser yoktu

Bir yabancı gibi geçti gitti yanımdan

Dilinde bir ''Merhaba'' ya bile yer yoktu

Hiç mi hiç değişmemiş görmeyeli

Karmaşık bakışlarında hala bin sır, 

Saçlarında bir mağrur bahar yeli

Yürüyüşü yine öyle kibirli ve ağır

Kahpe ne de güzel, ne de alımlı

Geçiyor yanımdan yine çalımlı

İstiyor ki olunsun peşinde pervane

Ben de aşk tükenmiş ne çare

Bilmez ki yitmiş gözümde değeri

İster takınsın böyle işveler nazlar

Beklemesin sakın benden niyazlar

Nazarımda beş para etmez ciğeri

Yeter karşısında hep aşağılanmak

Yeter un ufak parçalanmak

Çekil git gönül kapımdan artık

Ömrümü tüketen beş paralık aşk', 'Köşebaşında rasgeldi yine bu sabah Eski masum bakışlarından eser yoktu Bir yabancı gibi geçti gitti yanımdan Dilinde bir ''Merhaba'' ya bile y...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asagilik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglarsın Çektigim Dertleri Bilsen;', 'aglarsin-cektigim-dertleri-bilsen-timur-dadaloglu-5qabw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırdıgın kadehten, kalna ömrümden, 

Aglarsın içtigim yılları bilsen. 

Hüzünle sararıp solan gönlümden, 

Aglarsın geçtigim yolları bisen. 

Sefiller gücünü bende sınadı, 

Kimi kaçık dedi kimi bunadı! ! ! 

Sarhoş eleştirdi, bürdüş kınadı, 

Aglarsın düştügüm dilleri bilsen. 

Felsefe böyledir divanelerde, 

Teselli ararım meyhanelerde, 

Bir kadeh ney için viranelerde, 

Aglarsın düştügümİhalleri bisen. 

Ateşe su dedim, göz göre göre; 

Aklım zavallıydı, duyguma göre, 

Haline şükretti, mecnun binlere, 

Aglarsın çektigim dertleri bilsen...', 'Kırdıgın kadehten, kalna ömrümden,  Aglarsın içtigim yılları bilsen.  Hüzünle sararıp solan gönlümden,  Aglarsın geçtigim yolları bisen.  Se...', ARRAY['Türk Edebiyatı','Şiir','Timur Dadaloğlu']::text[], 8.5, '{"poet":"Timur Dadaloğlu","poet_slug":"timur-dadaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglarsin-cektigim-dertleri-bilsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçem;', 'sercem-timur-dadaloglu-jjfh1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün seninle bir candık, 

Bugün bir yabancıyız! ! ! 

Dag gibi sevgimizi, 

Sen harcadın vijdansız.

Vurulmuş serçelerin, 

Bende garipligi var.

Benim yeni adresim, 

Bu kimsesiz sokaklar.

Aşk yetimi ayptın sen, 

Beni gözgöre gözgere! ! ! 

Deli gibi severken, 

Muhtaç ettin ellere...', 'Dün seninle bir candık,  Bugün bir yabancıyız! ! !  Dag gibi sevgimizi,  Sen harcadın vijdansız. Vurulmuş serçelerin,  Bende garipligi var. ...', ARRAY['Türk Edebiyatı','Şiir','Timur Dadaloğlu']::text[], 8.5, '{"poet":"Timur Dadaloğlu","poet_slug":"timur-dadaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sercem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra', 'yillar-sonra-sezen-aksu-igl99', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç bir şey kalmasın

Hepsi silinsin hepsi

Hiç bir şey kalmasın

Hepsi silinsin hepsi

Elimde olsa yırtardım gölgeni

Resmine vurmuş bir pazar günü

Elimde olsa yırtardım gölgeni

Resmine vurmuş bir pazar günü

Yıllar sonra, yıllar sonra

Yıllar sonra, yıllar sonra

Hiç bir şey kalmasın

Hepsi silinsin hepsi

Hiç bir şey kalmasın

Hepsi silinsin hepsi', 'Hiç bir şey kalmasın Hepsi silinsin hepsi Hiç bir şey kalmasın Hepsi silinsin hepsi Elimde olsa yırtardım gölgeni Resmine vurmuş bir pazar g...', ARRAY['Türk Edebiyatı','Şiir','Sezen Aksu']::text[], 8.5, '{"poet":"Sezen Aksu","poet_slug":"sezen-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yillar-sonra-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayışığı', 'ayisigi-sezen-aksu-r8lvj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buralarda artık

Parlamıyor ayışığı

Güneşimize kar yağdı

Gidenlerden haber yok

Yasaksız aşklar yabancı

Aşina tuzak savaşlar

Üzerimize örtülünce

Lacivert akşamlar

Sen seç artık

Sen seç artık ooy oy ooy oy

Ne şarkı ne ayışığı ooy oy ooy oy

Ne ölüm kalım

Ne gençlik çağım

Darmadağın, darmadağın

Darmadağın, darmadağın

Bir atımlık umudum kaldı

Sen seç artık

Sen seç artık ooy oy ooy oy

Ne şarkı ne ayışığı ooy oy ooy oy

Ne ölüm kalım

Ne gençlik çağım

Darmadağın, darmadağın

Darmadağın, darmadağın

Bir atımlık umudum kaldı', 'Buralarda artık Parlamıyor ayışığı Güneşimize kar yağdı Gidenlerden haber yok Yasaksız aşklar yabancı Aşina tuzak savaşlar Üzerimize örtülün...', ARRAY['Türk Edebiyatı','Şiir','Sezen Aksu']::text[], 8.5, '{"poet":"Sezen Aksu","poet_slug":"sezen-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayisigi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni istemiyorum aşk;', 'seni-istemiyorum-ask-timur-dadaloglu-kcht2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çig^Düşmediyürgime

Kıran gelmedi hislerime

Seni istemiyorum hepsi bu.

Lütfen huzuruma gölge düşürme.

Herkesin bir aşkı varmış, 

Olsun varsın.

Sen asla benimle olamayaksın

Beynime nüfus edip

Geceleri uykumu kaçıramıyacaksın.

Bırak gecem siyah

Gündüzüm beyaz kalsın

Her agladıgımda ıslatacak

Bir omuz bulamassın.

Sırf ben istiyorum diye, 

Kimseyi masallrdan çıkramassın.

Dokunma ıslak yanaklarıma, 

Aglamayı ögrendim ben

Kimseseiz tek başıma

Hadi git artık

Gece bitmeden, 

Gün vurmadan gözyaşlarıma...', 'Çig^Düşmediyürgime Kıran gelmedi hislerime Seni istemiyorum hepsi bu. Lütfen huzuruma gölge düşürme. Herkesin bir aşkı varmış,  Olsun varsın...', ARRAY['Türk Edebiyatı','Şiir','Timur Dadaloğlu']::text[], 8.5, '{"poet":"Timur Dadaloğlu","poet_slug":"timur-dadaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-istemiyorum-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yolculuk', 'yolculuk-huseyin-cayikli-au8du', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yolcu yolunda gerek 

bu aksam ciktim belkide bilinmedik yerlere

yolcu yolunda gerek

ve gidiyor 

ay isiginda tren

raylar karlarla kapli

bir ulkenin icindeki yollari kapanmis bir koye

gidiyor tren

bende gidiyorum...', 'yolcu yolunda gerek  bu aksam ciktim belkide bilinmedik yerlere yolcu yolunda gerek ve gidiyor  ay isiginda tren raylar karlarla kapli bir u...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yolculuk-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak', 'toprak-asik-veysel-satiroglu-8zoii', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dost dost diye nicesine sarıldım 

Benim sâdık yârim kara topraktır 

Beyhude dolandım boşa yoruldum 

Benim sâdık yârim kara topraktır.

Nice güzellere bağlandım kaldım 

Ne bir vefa gördüm ne fayda buldum 

Her türlü isteğim topraktan aldım 

Benim sadık yarim kara topraktır.. 

Koyun verdi kuzu verdi süt verdi 

Yemek verdi ekmek verdi et verdi 

Kazma ile döğmeyince kıt verdi 

Benim sadık yarim kara topraktır.. 

Adem''den bu deme neslim getirdi 

Bana türlü türlü meyva yetirdi 

Her gün beni tepesinde götürdü 

Benim sadık yarim kara topraktır.. 

Karnın yardım kazmayınan belinen 

Yüzün yırttım tırnağınan elinen 

Yine beni karşıladı gülünen 

Benim sadık yarim kara topraktır.. 

İşkence yaptıkca bana gülerdi 

Bunda yalan yoktur herkes de gördü 

Bir çekirdek verdim dört bostan verdi 

Benim sadık yarim kara topraktır.. 

Havaya bakarsam hava alırım 

Toprağa bakarsam dua alırım 

Topraktan ayrılsam nerde kalırım 

Benim sadık yarim kara topraktır.. 

Dileğin var ise iste Allah''tan 

Almak için uzak gitme topraktan 

Cömertlik toprağa verilmiş Hak''tan 

Benim sadık yarim kara topraktır.. 

Hakikat ararsan açık bir nokta 

Allah kula yakın kul da Allaha 

Hak''kın hazinesi gizli toprakta 

Benim sadık yarim kara topraktır.. 

Bütün kusurlarım toprak gizliyor 

Merhem çalıp yaralarım düzlüyor 

Kolun açmış yollarımı gözlüyor 

Benim sadık yarim kara topraktır.. 

Her kim olursa bu sırra mazhar 

Dünyaya bırakır ölmez bir eser 

Gün gelir Veysel''i bağrına basar 

Benim sadık yarim kara topraktır.', 'Dost dost diye nicesine sarıldım  Benim sâdık yârim kara topraktır  Beyhude dolandım boşa yoruldum  Benim sâdık yârim kara topraktır. Nice g...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/toprak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceylan', 'ceylan-asik-veysel-satiroglu-7azu2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bir ceylan olsan ben de bir avcı 

Avlasam çöllerde saz ile seni..

Bulunmaz dermanı yoktur ilacı 

Vursam yaralasam söz ile seni..

Kurulma sevdiğim güzelim deyin 

Bağlanma karayı alları geyin 

Ben bir çoban olsam sen de bir koyun 

Beslesem elimde tuz ile seni.. 

Koyun olsan otlatırdım yaylada 

Tellerini yoldurmazdım hoyrada 

Balık olsan da takla dönsen deryada 

Düşürsem toruma bez ile seni..

Veysel der ismini koymam dilimden 

Ayrı düştüm vatanımdan ilimden 

Kuş olsan da kurtulmazdın elimden 

Eğer görse idim göz ile seni.

Aşık Veysel Şatıroğlu', 'Sen bir ceylan olsan ben de bir avcı  Avlasam çöllerde saz ile seni.. Bulunmaz dermanı yoktur ilacı  Vursam yaralasam söz ile seni.. Kurulma...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ceylan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Selam', 'benden-selam-asik-veysel-satiroglu-f802i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benden selam söylen vefasız yare 

Gurbet benim olsun sıla kendine..

Çekilmedik derdimizi bölüşek 

Yadı ben alayım sıla kendine..

Dökek derdimizi ölçek bölüşek 

Ne el bize ne biz ele karışak 

Felek bize gül demezki gülüşek 

Cefa benim olsun çile kendine..

Çektigim cefalar yar senden geldi 

Bana bu sitemler kar senden geldi 

Başımdaki duman kar senden geldi 

Ben kara bağlayım ala kendine..

Evvelden hastadır yaralı gönlüm 

Sevdayı mahbuba ereli gönlüm 

Aşkın gömleğine gireli gönlüm 

Hicranı Veysel''den n''ola kendine', 'Benden selam söylen vefasız yare  Gurbet benim olsun sıla kendine.. Çekilmedik derdimizi bölüşek  Yadı ben alayım sıla kendine.. Dökek derdi...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benden-selam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Beni', 'askin-beni-asik-veysel-satiroglu-a0kh2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın beni elden ele gezdirdi 

Cok dolandım bulamadım eşini 

Beni candan usandırdı bezdirdi 

Tuzlu imiş yiyemedim aşını..

Benim ile gezdin beni arattın 

Beraber oturup beraber yattın 

Türlü türlü güllerinden koklattın 

Aşık ettin güle bülbül kuşunu..

Altmış iki yıldır seni ararım 

Tükendi sabrım yoktur kararım 

Dağa taşa kurda kuşa sorarım 

Kimse bilmez hikmetini işini..

Her millete birer yüzden göründün 

Kendini sakladın sardın sarındın 

Bu dünyayı sen yarattın girindin 

Her nesnede gösterirsin nakşını..

Görenlere açık körlere gizli 

Kimine göründün oruç namazlı 

Veysel''e göründün cilveli nazlı 

Tutan bırakırmı senin peşini.

Aşık Veysel Şatıroğlu', 'Aşkın beni elden ele gezdirdi  Cok dolandım bulamadım eşini  Beni candan usandırdı bezdirdi  Tuzlu imiş yiyemedim aşını.. Benim ile gezdin b...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanma', 'aldanma-asik-veysel-satiroglu-pn28l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aldanma cahilin kuru lafına 

Kültürsüz insanın külü yalandır..

Hükmetse dunyanın her tarafına 

Arzusu hedefi yolu yalandır..

Kar suyundan süzen çeşme göl olmaz 

Gül dikende biter diken gül olmaz 

Vız vız eden her sineğin bal''olmaz 

Peteksiz arının balı yalandır..

İnsan bir deryadır ilimle mahir 

İlimsiz insanın şöhreti zahir 

Cahilden iyilik beklenmez ahir 

İşlediği amel hali yalandır.. 

Cahil okur amma alim olamaz 

Kamillik ilmini herkes bilemez 

Veysel bu sözlerin halka yaramaz 

Sonra sana derler deli yalandır.

Aşık Veysel Şatıroğlu', 'Aldanma cahilin kuru lafına  Kültürsüz insanın külü yalandır.. Hükmetse dunyanın her tarafına  Arzusu hedefi yolu yalandır.. Kar suyundan sü...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aldanma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı Dilber', 'nazli-dilber-asik-veysel-satiroglu-uxp3y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ala gözlü benli dilber 

Bir gün gelsen bize dogru..

Seni sevdim can u dilden 

Çekme kendini naza doğru..

Ne pervam var ne de perdem 

Sanma beni hali bir dem 

Söyler seni teller her dem 

Kulak versen saza doğru..

Aşığa zülfükar isen 

Gülşende güle zar isen 

Hakikatli bir yar isen 

Ben geleyim size doğru..

Gönülleri bir edelim 

Gayrileri biz nidelim 

İkimiz de bir gidelim 

Yürüyelim ize doğru..

Bir gün için feryadı zar 

Bülbül eder her dem seher 

Aç sinemi gel gör ne var 

Arttı derdim yüze doğru..

Kafi derdim bir derd katma 

Veysel''i yabana atma 

Kerem eyle çok uzatma 

Kavuşalım yaza doğru.

22.01.2002', 'Ala gözlü benli dilber  Bir gün gelsen bize dogru.. Seni sevdim can u dilden  Çekme kendini naza doğru.. Ne pervam var ne de perdem  Sanma b...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nazli-dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Çektikce Erir Gider', 'ah-cektikce-erir-gider-asik-veysel-satiroglu-asopd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah çektikce erir gider 

Yüreğimin yağı benim..

Seni görsem durur gider 

Dillerimin bağı benim..

Gam leskesi saf saf oldu 

Hep sözlerim boş laf oldu 

Senin yolunda mahv oldu 

Gençliğimin çağı benim..

Ah belimi büken oldu 

Gurbet bana diken oldu 

Altı aydır mekan oldu 

Dibi kırkkız dağı benim..

Sensin derdine dustugum 

Hayal oldu konuştuğum 

Her gün yediğim içtiğim 

İçerimde ağu benim..

Ağlar VEYSEL çıkmaz sesi 

Gine coştu gam deryası 

Garip gönlümün yaylası 

Güzel hüsnün bağı benim.

Aşık Veysel Şatıroğlu', 'Ah çektikce erir gider  Yüreğimin yağı benim.. Seni görsem durur gider  Dillerimin bağı benim.. Gam leskesi saf saf oldu  Hep sözlerim boş l...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ah-cektikce-erir-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İğneli Dost', 'i-gneli-dost-gulten-akin-mux0b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İster ki herkes ölsün 

Neler besleyip büyütmüş

Gömmüştür neleri gizli gizli

Belleği sıra

İster ki herkes ölsün

Şarap olacakken sirkeye dönmüş

Üzüm suyu şaşkınlığında

Gidişi kelebek, gelişi beygir

Kişnemesi çöplük sanrılarıyla

Yollarda ipekler halılar, çağırır evine

Eli dili soylu kırmanç güzelliğinde

Tarih düşersiniz artık İsa doğmuştur

Dostluktan önce, dostluktan sonra

Arınmıştır kirlerinden insan ve dünya

Belli belirsiz bir siziyla

Dönüşte eliniz varırsa sırtınıza

Kocaman paslı bir iğne 

Onların

Çimen bitmez bastıkları yerde

Sevgi buruşur', 'İster ki herkes ölsün  Neler besleyip büyütmüş Gömmüştür neleri gizli gizli Belleği sıra İster ki herkes ölsün Şarap olacakken sirkeye dönmü...', ARRAY['Türk Edebiyatı','Şiir','Gülten Akın']::text[], 8.5, '{"poet":"Gülten Akın","poet_slug":"gulten-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/igneli-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkindi Serinliği', 'i-kindi-serinligi-cihattin-postnisin-0gs84', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakışın kadar farklıydı

Çayını tek şekerli içmen

Gereksizdi başka bir tat

Lütufken, seni katıksız yudumlamak

Sustuğunda kururdu içim

Susuzluğumu sesinle giderdim

Senin cümlelerinle başlardı

Hep aynı biten hikayelerim

Dünya ile yanarken nefsim

İkindi serinliğiydi nefesin

Yoktu ayazda kalma ihtimalim

Gözünün içiyken sıcak evim

Düşünmedim, aşk mı, sana hissim

Ben seni isim vermeden sevdim.', 'Bakışın kadar farklıydı Çayını tek şekerli içmen Gereksizdi başka bir tat Lütufken, seni katıksız yudumlamak Sustuğunda kururdu içim Susuzlu...', ARRAY['Türk Edebiyatı','Şiir','Cihattin Postnişin']::text[], 8.5, '{"poet":"Cihattin Postnişin","poet_slug":"cihattin-postnisin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ikindi-serinligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazeretin Bensem', 'mazeretin-bensem-ahmet-temel-uera4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben iki damla gözyaşıyım; 

       Burnunun kıvrımlarını aşıp, 

       İki yanağından süzülen, 

       Sonrada dudaklarını sıyırıp 

       Kara toprağa karışan 

                                İki  damla gözyaşı! 

             BENİ BENİM İÇİN TÜKETME! 

                          

                                 Ben iki uzun saç teliyim; 

        Esintisiyle meltemin

        Gözyaşına karışan 

        Sonra da iki parmağınla

        Kulağına sıkıştırdığın

                                 İki uzun saç teli! 

             BENİ BENİM İÇİN AĞARTMA! 

          

                                 Ben yalnızca iki kelimeyim

         Hasret kalıp da

         Duyamadığı kulağımın

         Söylemeyi isteyip de 

         Yapamadığı dudağının

                                Yalnızca iki kelime! 

              BENİ BENİM İÇİN BEKLETME!', 'Ben iki damla gözyaşıyım;         Burnunun kıvrımlarını aşıp,         İki yanağından süzülen,         Sonrada dudaklarını sıyırıp         Ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Temel']::text[], 8.5, '{"poet":"Ahmet Temel","poet_slug":"ahmet-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mazeretin-bensem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salıver Gitsin', 'saliver-gitsin-emine-sumra-ib842', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Burnumda tütüyorsun burcu, burcu

Ocaklar misali yanan şu gönlüme, 

Bir tas su döküver gitsin.

Kirpiklerini düşür gözlerime, 

Bırak gölgeleri sevişsin senelerce.

Kendi hallerine bırakıver gitsin.

Kelep, kelep aşkın yüreğimde, 

Senin kelepleride koy üstüne, 

Bir ucu sende, bir ucu bende sarıver gitsin.

Yumak yaptık mı kelepleri el ele, 

Kurduğun gönül tezgahında, 

Renk, renk çözüver gitsin.

Bir senden koy bir benden, 

Hasret, ayrılık renklerini koyma sakın, 

Aşk kilimini gönlüme yayıver gitsin.', 'Burnumda tütüyorsun burcu, burcu Ocaklar misali yanan şu gönlüme,  Bir tas su döküver gitsin. Kirpiklerini düşür gözlerime,  Bırak gölgeleri...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/saliver-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-orhan-veli-kanik-ryr1b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her zaman, fakat, bilhassa

Beni sevmediğini

Anladığım zamanlarda

Görmek isterim seni de

Annemin kucağından

Seyrettiğim insanlar gibi, 

Küçüklüğümde...', 'Her zaman, fakat, bilhassa Beni sevmediğini Anladığım zamanlarda Görmek isterim seni de Annemin kucağından Seyrettiğim insanlar gibi,  Küçük...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/insanlar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir Haricinde', 'sehir-haricinde-orhan-veli-kanik-x08pm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çatlamak üzre olan tomurcuklar

Güzel günler vadetmededir.

Ve bir kadın, şehir haricinde; 

Otların üstünde, 

Güneşin altında, 

Yüzükoyun uzanmış; 

Göğsünde ve karnında

Baharı hissetmededir.', 'Çatlamak üzre olan tomurcuklar Güzel günler vadetmededir. Ve bir kadın, şehir haricinde;  Otların üstünde,  Güneşin altında,  Yüzükoyun uzan...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sehir-haricinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümden Sonra Neşelenmek İçin Lied', 'olumden-sonra-neselenmek-i-cin-lied-orhan-veli-kanik-a1i6i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sonsuz bir deniz düşünürüm.

Bulutlar başımın üzerinden

Bir Olymp ilahı sükuniyle geçip giderken

Ve kır melekleri şarkılarını söyleyip

Raksederken ekin tarlalarında, göze görünmeden.

Fakat neden mavi gökyüzlerine

Genişlerken ağustos böceklerinin sesi, 

Kuşlar yine onun türküsünü söyler?', 'Ben sonsuz bir deniz düşünürüm. Bulutlar başımın üzerinden Bir Olymp ilahı sükuniyle geçip giderken Ve kır melekleri şarkılarını söyleyip Ra...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olumden-sonra-neselenmek-icin-lied-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul için', 'i-stanbul-icin-orhan-veli-kanik-9byau', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'NİSAN

İmkansız şey

Şiir yazmak, 

Aşıksan eğer; 

Ve yazmamak, 

Aylardan Nisansa.

   ARZULAR VE HATIRALAR

Arzular başka şey, 

Hatıralar başka.

Güneşi görmeyen şehirde, 

Söyle, nasıl yaşanır? 

   BÖCEKLER

Düşünme, 

Arzu et sade! 

Bak, böcekler de öyle yapıyor.

   DAVET

Bekliyorum

Öyle bir havada gel ki, 

Vazgeçmek mümkün olmasın.', 'NİSAN İmkansız şey Şiir yazmak,  Aşıksan eğer;  Ve yazmamak,  Aylardan Nisansa.    ARZULAR VE HATIRALAR Arzular başka şey,  Hatıralar başka....', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/istanbul-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Quantitatif', 'quantitatif-orhan-veli-kanik-fi0dj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel kadınları severim, 

İşçi kadınları da severim, 

Güzel işçi kadınları

Daha çok severim.', 'Güzel kadınları severim,  İşçi kadınları da severim,  Güzel işçi kadınları Daha çok severim....', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/quantitatif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyahat Üstüne Şiirler', 'seyahat-ustune-siirler-orhan-veli-kanik-xdv25', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I

Seyahat edildiği zamanlarda

Yıldızlar konuşur

Söyledikleri şeyler

Ekseriya hüzünlüdür.

   II

Sarhoş olunduğu akşamlar

Islıkla çalınan şarkı

Neşelidir.

Halbuki aynı şarkı

Bir treninin penceresinde

Neşeli değil.', 'I Seyahat edildiği zamanlarda Yıldızlar konuşur Söyledikleri şeyler Ekseriya hüzünlüdür.    II Sarhoş olunduğu akşamlar Islıkla çalınan şark...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seyahat-ustune-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali Rıza ile Ahmed''in Hikayesi', 'ali-riza-ile-ahmed-in-hikayesi-orhan-veli-kanik-r0c95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne tuhaftır Ali Rıza ile

Ahmedin hikayesi! ..

Birisi köyde oturur, 

Birisi şehirde

Ve her sabah

Şehirdeki köye gider, 

Köydeki şehre.', 'Ne tuhaftır Ali Rıza ile Ahmedin hikayesi! .. Birisi köyde oturur,  Birisi şehirde Ve her sabah Şehirdeki köye gider,  Köydeki şehre....', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ali-riza-ile-ahmed-in-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asfalt Üzerine Şiirler', 'asfalt-uzerine-siirler-orhan-veli-kanik-1mwg4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I

Ne kadar güzel şey; 

Yolun üstündeki bina

Yıkıldığı zaman

Bilinmeyen bir ufuk görmek.

   II

Kaldırımın kenarına dizilip

Bacası olan silindirin

Yürüyüşünü seyreden

Çocuklara imreniyorum.

   III

Onun sesi

Bir arkadaşıma

Denizden geçen

Motorları hatırlatıyor.

   IV

Kırık taşlara bakıp

Işıklı bir asfalt düşünmek

Acaba yalnız

Şairlere mi mahsus?', 'I Ne kadar güzel şey;  Yolun üstündeki bina Yıkıldığı zaman Bilinmeyen bir ufuk görmek.    II Kaldırımın kenarına dizilip Bacası olan silind...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asfalt-uzerine-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut', 'bulut-orhan-veli-kanik-rhzna', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuşçu amca! 

Bizim kuşumuz da var, 

Ağacımız da.

Sen bize bulut ver sade

Yüz paralık.', 'Kuşçu amca!  Bizim kuşumuz da var,  Ağacımız da. Sen bize bulut ver sade Yüz paralık....', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bulut-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyhane', 'meyhane-orhan-veli-kanik-ed7tk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Madem ki sevmiyorum artık, 

O halde, her akşam

Onu düşünerek içtiğim

Meyhanenin önünden

Ne diye geçeyim? ..', 'Madem ki sevmiyorum artık,  O halde, her akşam Onu düşünerek içtiğim Meyhanenin önünden Ne diye geçeyim? .....', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/meyhane-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah', 'sabah-orhan-veli-kanik-s6oyw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimi çok dallı bir ağaç gibi

Tutarım gölün yüzüne

Ve seyrederim bulutları

Bir deve gürültüler içinde koşar, koşar, koşarken

Güneş doğmadan evvel varmak için

Ufka...', 'Elimi çok dallı bir ağaç gibi Tutarım gölün yüzüne Ve seyrederim bulutları Bir deve gürültüler içinde koşar, koşar, koşarken Güneş doğmadan ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sabah-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetler Armağan Olsun (Annenin Rüyası)', 'cennetler-armagan-olsun-annenin-ruyasi-yakup-erol-winx1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben küçücük bir bebeğim

Daha doğmadım bile

Yaşım bile yok 

Adım ne bilmem

Her şey gece 3: 02 de başladı.

İniltilerle uyandı annem

Anacığım

Bir anda üç kat aşağıya

İniltilerle indik

Ben küçücük bir bebeğim 

Daha doğmadım bile 

Oysa ne rüyalarım vardı

Her gece o meçhul

Trenin sesiyle uyur

Kuşların horozların

Sesiyle uyanırdım.

Önce bir kahvaltı yapardık

Meleğimle, bitanemle

Sonraysa..

Her şey gece 3: 02 de başladı

Yavaş yavaş doğruldu annem

Bir lokma ekmek

Bir dirhem su için

Yavrusu için 

Bitanesi için

Meleği için…

Ne çare ki tuğlalar boy boy

Ranzalar inmiş

Saatler ters

Kıyamet mi Allahım

Bu gizli cihan

Yer, makam, yaş dinlememiş

Serivermişsin her şeyi…

Ben küçücük bir bebeğim

Daha doğmadım bile, adım bile yok

Benim için alınanlar

Küçük bir patik

Elde örme bir kazak

Kışın o soğukta 

Üşümeyim diye annem annem diye

Sarılaydım sana bir kere

Yaş olup  ta şakısaydım

Gözlerine

Ellerine dayansaydım

Yürümeye çalışsaydım

Her seferinde düşseydim

Yaramazlık yapsaydım

En değerli vazoyu kırsaydım

En değerli fotoğrafı yırtsaydım

Yaramaz bir çocuk 

Bir bebek olsaydım

Ama olmadı 

Ne çare ki olamadı anne

Her şey gece 3: 02 de başladı.

İlk defa gözlerimi açtım

Burada beni melekler karşıladı anne

Ruhuma can veren; 

Meleklere yıkattı beni anne

Melekler kıldı cenaze mi

Saf saf bölük bölük melekler

Ne güzel varlık bunlar anne

Aynı senin gibi

Bir tanem gibi sardılar beni..

Ağlama annem ağlama bitanem

Dalından düşürüp veremediğin 

Elmalardan binbir türlüsü var anne

Belki

Belki sen yoksun

Ama üzülme annem, üzülme anacığım

Yaradanın huzurundan 

Geliyorum rüyana

Gir dediler bana

Nereye? Dedim titrek titrek

Cennetime gir dedi

Girmem dedim

Neden diye sordu yüce Mevla

Allahım dedim

Yetimlerin öksüzlerin hakkı yok mu? 

Ya kimsesizlerin hakkı

Ve doğmamış çocukların 

Hakkı için

Annemi isterim annemi dedim

Sustum

Allahım git dedi

Nereye dedim ya zülcelal

Annenin rüyasına git dedi

Müjdele

Sevgiline, yarine, annene

Rüyasına giriver ve müjdele dedi

Ağlamasın çocuklar

Ağlamasın anneler

Giriversin cennetime  ya kulum dedi

Üzülme anacığım

Çünkü sen cennetlik bir anne

Çünkü sen cennetlik anamsın.

Ben küçücük bir bebeğim

Daha doğmadım bile 

Annelerin en güzeline 

Cennetler armağan olsun

Sevgilime 

Yarime

Bitaneme

Anneme müjdeler olsun.

                           (    29/09/1999    21: 10)', 'Ben küçücük bir bebeğim Daha doğmadım bile Yaşım bile yok  Adım ne bilmem Her şey gece 3: 02 de başladı. İniltilerle uyandı annem Anacığım B...', ARRAY['Türk Edebiyatı','Şiir','Yakup Erol']::text[], 8.5, '{"poet":"Yakup Erol","poet_slug":"yakup-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/cennetler-armagan-olsun-annenin-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldırış', 'aldiris-yakup-erol-uzbdv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir taş atsam gökyüzüne

Aldırır mı bu kalp

Yaşar mı bilmem sessiz geceyi

Her şey kolay diyorsun

Ama aldırmıyorsun

Yaşayan sende

Aldırmayan benmiyim.', 'Bir taş atsam gökyüzüne Aldırır mı bu kalp Yaşar mı bilmem sessiz geceyi Her şey kolay diyorsun Ama aldırmıyorsun Yaşayan sende Aldırmayan b...', ARRAY['Türk Edebiyatı','Şiir','Yakup Erol']::text[], 8.5, '{"poet":"Yakup Erol","poet_slug":"yakup-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aldiris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek', 'gelecek-yakup-erol-1q09v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelecekte  bir gün gelecek 

Ve o geleceği kimler görecek

Ölüm seni sevmiyorum desemde 

Sen olmasan bile 

O gelecek yine gelecek 

Ama zamansız mutlu bir gelecek 

Seninle gelecek

       Geleceğe, sevgiliye..

                    09/04/2001', 'Gelecekte  bir gün gelecek  Ve o geleceği kimler görecek Ölüm seni sevmiyorum desemde  Sen olmasan bile  O gelecek yine gelecek  Ama zamansı...', ARRAY['Türk Edebiyatı','Şiir','Yakup Erol']::text[], 8.5, '{"poet":"Yakup Erol","poet_slug":"yakup-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gelecek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmek-Düşünmek-Lezzet Almak', 'gormek-dusunmek-lezzet-almak-yakup-erol-mzml9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan hislenir mi bu kadar 

Bilmem

Nasıl bir sevgi ki 

Gündüzleri düşünsün, 

Geceleri düşlesin

Ana sevgisi baba saygısında mı gizli? 

Tertemiz pırıl pırıl sevsin

Yaşatsın kalbinde onu hiç öldürmesin.

Allahım ne güzel kardeşlik 

Ne manidar bir sevgi; 

Bir çiçeği sever gibi

Dalından düşüremediğin gibi

Yar gibi.

Hani güller yalan söylemez

Sor derdini güllere derler

Derdin devası mıdır yada tevekkül

Asra yemin olsun ki diye başlar

Ve yazılır ciltler dolusu kitaplar

Anlatırlar kurtuluşu, dirilişi

Yada  o en hummalı sevgiyi

Kuş tüyünden yada 

Kuş sütünden öte sevgiyi

Karamsarlık neye yarar ki

Malda mı  saklıdır veya mülkte mi sevgi

Madem ki öleceğiz

Hislerden ders alıp hayata güleceğiz

Mutlulukta sabrı

Sabırda huzuru bulacağız

Ve bir olacağız, 

Seveceğiz

Hem de sevileceğiz

Mutluluk uçsuzdur, bucaksızdır

Kainatın sonudur sevgi.

Mutluluk olgunluktur, yaşamdır

Katıksızdır bu sevgi

Mutluluk güzel görmektir

Gördüğünü güzel düşünmektir sevgi

Mutluluk hayattan lezzet almaktır 

Yaşamaktır

Yani ölümüne sevmektir.

             03/03/1999   4: 12', 'İnsan hislenir mi bu kadar  Bilmem Nasıl bir sevgi ki  Gündüzleri düşünsün,  Geceleri düşlesin Ana sevgisi baba saygısında mı gizli?  Tertem...', ARRAY['Türk Edebiyatı','Şiir','Yakup Erol']::text[], 8.5, '{"poet":"Yakup Erol","poet_slug":"yakup-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gormek-dusunmek-lezzet-almak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-yakup-erol-mk6x7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğer gidersen yazık olur

Sonra adın hasret olur

Gönlümde kor, gözlerimde yaş

Dudağımda bir tek ismin olur

Sonra adın hasret olur

Sonra ismin hasret kalır.

                      08/04/2001', 'Eğer gidersen yazık olur Sonra adın hasret olur Gönlümde kor, gözlerimde yaş Dudağımda bir tek ismin olur Sonra adın hasret olur Sonra ismin...', ARRAY['Türk Edebiyatı','Şiir','Yakup Erol']::text[], 8.5, '{"poet":"Yakup Erol","poet_slug":"yakup-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hasret-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız İnsan', 'yalniz-i-nsan-yakup-erol-3v9xe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç yalnız kaldın mı

Yalnızlığı ciğerlerine çektin mi? 

Hiç kuşlara mısralar

Şarkılar ve 

Yarım kalan aşkları anlattın mı? 

Gökyüzüne bakıp, 

Yedi rengide gördün mü

Yalan 

Yalan

Yalan

Bir hiçmiydi hepsi

Gülesi yarim hepsi bir hiçmiydi

Bir ömür geçiyor

Durağı olmayan

Durağı bilinmeyen bir ömür

Ve bu durağın çilesi sen

Yalnızlığı ben.', 'Hiç yalnız kaldın mı Yalnızlığı ciğerlerine çektin mi?  Hiç kuşlara mısralar Şarkılar ve  Yarım kalan aşkları anlattın mı?  Gökyüzüne bakıp,...', ARRAY['Türk Edebiyatı','Şiir','Yakup Erol']::text[], 8.5, '{"poet":"Yakup Erol","poet_slug":"yakup-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalniz-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-yakup-erol-q457f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoruldum

Yordular

Ama mutluyum bitiyor

Zaten başlayan ne oldu ki? 

Ve ben neye yoruldum

Ve beni kimler yordu

Umarsızca 

Aldırmadan...

             09/04/2001', 'Yoruldum Yordular Ama mutluyum bitiyor Zaten başlayan ne oldu ki?  Ve ben neye yoruldum Ve beni kimler yordu Umarsızca  Aldırmadan...       ...', ARRAY['Türk Edebiyatı','Şiir','Yakup Erol']::text[], 8.5, '{"poet":"Yakup Erol","poet_slug":"yakup-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yoruldum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta', 'karanlikta-levent-keskin-8mtz9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlıktaki yüzümü bıraktım seninle

Ansızın çıkagelen travmalarım

tekrar etme sakın.! 

Söyleme içinde kalsın; çürüsün.

Bırakma hep seninle üzülsün

Ben özgürmüyüm ki o sevinsin

Bilinmezlik bu, nerden bilsin

Karanlık yüzüm yine göründü seninle

Terk etmek olsaydı kitabımda

Ben burda olurmuydum acaba? 

Delirmekte bir çare aslında

Amaçlardan kaçmak umarsızca

Boşver be bırak gider nasıl olsa

Gİtmesede kalırsın yine onunla, karanlıkta!', 'Karanlıktaki yüzümü bıraktım seninle Ansızın çıkagelen travmalarım tekrar etme sakın.!  Söyleme içinde kalsın; çürüsün. Bırakma hep seninle ...', ARRAY['Türk Edebiyatı','Şiir','Levent Keskin']::text[], 8.5, '{"poet":"Levent Keskin","poet_slug":"levent-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/karanlikta-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınca', 'kadinca-levent-keskin-u5od1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sahibi çağırdığında gitmek

zor gelmez kadınlığına.

Arzular yavandır, farkedilmez! 

Sevdası yaradır içinde, bilinmez! 

Izdırabı akar içinde gece yatınca, 

Gönül fermanı yazılmaz olur, sabaha.

Bitmeyen feryadın son perdesini

Kuralsız bir oyunun çekilmez sahneleri

Kare kare giden bitmeyen drenişi

Sonu bilinen bir oyun gibi.', 'Sahibi çağırdığında gitmek zor gelmez kadınlığına. Arzular yavandır, farkedilmez!  Sevdası yaradır içinde, bilinmez!  Izdırabı akar içinde g...', ARRAY['Türk Edebiyatı','Şiir','Levent Keskin']::text[], 8.5, '{"poet":"Levent Keskin","poet_slug":"levent-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kadinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamasanda', 'anlamasanda-levent-keskin-qkct7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kelimeler kifayetsiz kaldı, 

Karşılıksız bir aşkı anlatmama.

Sözcüklerim öksüz kaldı, 

Beni aldattığın anda.

Cevapsız kalan her mısranın sonuna

eklediğim saflığın kaldı aklımda.

Süzgeçten geçmeden, tüm yalınlığınla

yazdığım hayatındı, anlamasanda.', 'Kelimeler kifayetsiz kaldı,  Karşılıksız bir aşkı anlatmama. Sözcüklerim öksüz kaldı,  Beni aldattığın anda. Cevapsız kalan her mısranın son...', ARRAY['Türk Edebiyatı','Şiir','Levent Keskin']::text[], 8.5, '{"poet":"Levent Keskin","poet_slug":"levent-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlamasanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Kalan Mektuplar 1', 'bende-kalan-mektuplar-1-riza-polat-akkoyunlu-l74yh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün bir dosttan 

Uzun bir mektup aldım. 

Beni anlatmış sana, 

Ve sen ona, 

> demişsin. 

Hem bu sözü gülerek

Medar-ı iftiharla söylemişsin

Unutamazsın! 

Nokta noktam 

Unutamazsın! 

Çünkü inan, 

Unutmak için, 

Önce unutulmak gerek, 

Oysaki sen, 

Hala bende esen, 

Eski kavak yelisin. 

Unutamazsın.. 

Kan değil, tüküremezsin, 

Ruj değil, 

Silemezsin, 

Dişi dudaklarına, dişlerimle yazdığım, 

Dört heceli  adı.. 

Unutamazsın.. 

Seninle biz, 

Hala bir kabukta, 

İki badem içi gibiyiz. 

Baharsın, 

Kokacaksın.. 

Güneşsin yakacaksın, 

Sabah yatağım kadar rüya dolu. 

Sabah yatağım kadar sıcaksın.. 

Unutamam, 

Unutamazsın 

Şimdilik bu kadar.. 

Öbür mektuba, 

Daha diyeceklerim var. 

Gücenme sakın, 

Darılma bana, 

Ankara günlerinin bem beyaz ufkundan, 

Binlerce selam 

Sana...', 'Dün bir dosttan  Uzun bir mektup aldım.  Beni anlatmış sana,  Ve sen ona,  > demişsin.  Hem bu sözü gülerek Medar-ı iftiharla söylemişsin Un...', ARRAY['Türk Edebiyatı','Şiir','Rıza Polat Akkoyunlu']::text[], 8.5, '{"poet":"Rıza Polat Akkoyunlu","poet_slug":"riza-polat-akkoyunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bende-kalan-mektuplar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Kalan Mektuplar 2', 'bende-kalan-mektuplar-2-riza-polat-akkoyunlu-hiku0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bende Kalan Mektuplar 2 		

Bahar başladı, nokta noktam, 

Ankara''da bahar... 

Veriminde toprak ana, 

Aylar var ki sana, 

Tek satır yazamadım. 

Oysaki, şimdi mevsim bahar, 

Ötüşlerde adın, 

Kokuşlarda tadın 

Var. 

Artık yazmalıyım... 

Takvime baktım bu sabah, 

Ayrılalı, beş ay olmuş, 

Düşün ki nokta noktam. 

Beş ay denilen nesne tam, 

Yüz elli gün eder.. 

Bunca uzun bir ayrılıksa, 

İnsanı her şeye küskün eder... 

İnan bana nokta noktam, 

İnan bana... 

Dargınlığım herkese, 

Ve tek hasretim sana. 

Düşünüyorum, 

Hava keskin kokularla dolu, 

Düşünüyorum, 

> na çıkan yolu 

Düşünüyorum, 

Bu yolun sağında yükselen, 

Her geçişte penceresinden, 

Tebessümler gelen, 

Bahçesinde iri 

Kayısı gülleri 

Açan evi... 

Düşünüyorum, 

Bir türlü gelmiyor, 

Düşüncelerin ardı: 

Ablan yanımda çorapsız gezer, 

Baş örtüsüz annen, 

Benden, 

Kaçardı! .. 

Düşünüyorum: 

Bu mevsimde baban, 

Bir yerine iki şişe içerdi. 

Miyoplaşınca gözleri, 

> derdi. 

Bahar başladı nokta noktam, 

Ankara''da bahar, 

Gönül ufkumda yağmur bulutları; 

Cennet olsa da artık, 

Sevmiyorum, sevemiyorum, 

Sensiz baharı...', 'Bende Kalan Mektuplar 2 		 Bahar başladı, nokta noktam,  Ankara''da bahar...  Veriminde toprak ana,  Aylar var ki sana,  Tek satır yazamadım....', ARRAY['Türk Edebiyatı','Şiir','Rıza Polat Akkoyunlu']::text[], 8.5, '{"poet":"Rıza Polat Akkoyunlu","poet_slug":"riza-polat-akkoyunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/bende-kalan-mektuplar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Kalan Mektuplar 4', 'bende-kalan-mektuplar-4-riza-polat-akkoyunlu-2qhvd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece yılbaşı, 

Başkente kar yağıyor, nokta noktam, 

Başkente kar. 

Ve tütüyor gözlerimde, 

Küllenmiş bir mangal gibi eski hatıralar.. 

Başkente kar yağıyor, 

Başkente kar... 

Bu gece yılbaşı, 

Bilirsin ki nokta noktam, 

Yılbaşlarında hesaplanır 

Çoğu zaman, 

İnsanların yaşı! . 

Bu gece yılbaşı. 

Tokmaklarında yirmi dört hece, 

Eğilip üstüme sessizce, 

Şehrin kule saati 

Bilirimsin nokta noktam, 

Bilirmisin ne dedi: 

> 

Ve bir el, saçlarından tutarak kalbimi, 

Sana kadar sürükledi... 

Bu gece yılbaşı, 

Başkent ayakta, 

Çalınan Tuna Dalgalar dır komşu plakta. 

Nede kıvrak bu vals havası... 

Başladı gönlümün yine, 

On yıl evvelki kanaması. 

Ne günlerdi o günler, cancağızım, 

Ne günler.. 

Sen on yedisinde, 

Sevgilerin sisinde 

Başı duman duman bir kız. 

Ben, 

Yirmi dört üstünde, 

Gönlü her güzelle nişanlı, 

Öylesine bir şair, 

Öylesine bir delikanlı. 

Ne de çabuk geçti zaman, 

Hey gidi dünya hey... 

Bu gece yılbaşı, 

Dışarıda kar yağıyor, 

Dışarıda kar. 

Ve tütüyor gözlerimde, 

Küllenmiş bir mangal gibi eski hatıralar: 

Köşede bir kırlent, 

Kırlentte bir resim, 

Resimde bir mevsim 

Bartın''da bahar.. 

Elimle yapmışım: 

Asma köprüsünde kocanaz deresi. 

Sağda lise, 

Solda, 

> in elma bahçesi 

Derede bir kayık, 

Kürekde sen, 

Dümende ben, 

Hava berrak, 

Hava temiz, 

Ve sularda sarmaşan gölgemiz.. 

Bu gece yılbaşı, 

Başkent ayakta. 

Çalınan (Tuna Dalgaları)   değildir artık 

Komşu pikapta. 

Gönlüm bu diyardan çok çok uzakta... 

Dışarıda kar yağıyor, 

Dışarıda kar 

Ve tütüyor gözlerimde, 

Küllenmiş bir mangal gibi eski hatıralar', 'Bu gece yılbaşı,  Başkente kar yağıyor, nokta noktam,  Başkente kar.  Ve tütüyor gözlerimde,  Küllenmiş bir mangal gibi eski hatıralar..  Ba...', ARRAY['Türk Edebiyatı','Şiir','Rıza Polat Akkoyunlu']::text[], 8.5, '{"poet":"Rıza Polat Akkoyunlu","poet_slug":"riza-polat-akkoyunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/bende-kalan-mektuplar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkekler ağlamaz', 'erkekler-aglamaz-erol-sen-aia7r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yetiştirildik acılara boyun eğmek için

Yoğrulduk geleneklere uymak için

Dünyaya erkek olarak gelmişiz

Yer etmiş beynimizde erkekler ağlamaz

Yaşananlarda hep gülünecek şeyler varmış gibi

Erkeklerin günleri hep neşe içinde geçermiş gibi

Bütün acılar kadınlara yazılmış gibi

Yoğrulduk tüm üzüntülere boyun eğmek için

Yetiştirildik tüm benliğimizle

Nedense ağlama hakkı hep bayanlarda

Söylerler ya makus talihine karşı gelemedi

Yapacağı hiç bir şey yoktu boğun eğmekten başka

Bak bu da güzel buna da gül haydi

Hadi gül neden gülmüyorsun

Hiç olmazsa talihin ve geleneklerin bir kısmı

Hiç olmazsa beynindeki tabuların bir kısmı

Yıkılsa, savrulsa yada yok olsa

Yada kurallarına isyan etsek insanların

Neden olmasın yıllardır yapıyorum zaten

Ağlarım ben hem de sessizce, 

Doya doya içimdeki yanan ateşlerin üstüne

O ateşler sönmesede............

23.01.2002', 'Yetiştirildik acılara boyun eğmek için Yoğrulduk geleneklere uymak için Dünyaya erkek olarak gelmişiz Yer etmiş beynimizde erkekler ağlamaz ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/erkekler-aglamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'uzanabilmek', 'uzanabilmek-suna-gunes-ldfxo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzanabilmek, el değmemiş güzelliklere, 

Ağrı dağındaki bir çiçeğe, 

Cudi dağındaki çocuğa, 

ve de; 

el değmemiş, gün görmemiş, 

 güzelliklere uzanabilmek..

Seninle; 

uzanabilmek umuda, uçsuz bucaksız, 

gökyüzüne, sevgilere uzanabilmek en çok..

kavgaları yararak, okyanusları aşarak, 

bir güvercin gibi uçarak gözlerimde, 

tüm renklerle, koşarak uzanabilmek, 

güzelliklere, sevinçlere...

seninle.', 'Uzanabilmek, el değmemiş güzelliklere,  Ağrı dağındaki bir çiçeğe,  Cudi dağındaki çocuğa,  ve de;  el değmemiş, gün görmemiş,   güzellikler...', ARRAY['Türk Edebiyatı','Şiir','Suna Güneş']::text[], 8.5, '{"poet":"Suna Güneş","poet_slug":"suna-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uzanabilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ Rüzgarı', 'dag-ruzgari-mehmet-kepez-u3vic', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzak dağların sessizliği

Fırtınası, coşkusu

Anlatır yüreğimin o

Gün batımı yanlızlığını

Bir sen

Sen anlamadın beni

İçimdeki sokakların

Kar yürekli karakızı..', 'Uzak dağların sessizliği Fırtınası, coşkusu Anlatır yüreğimin o Gün batımı yanlızlığını Bir sen Sen anlamadın beni İçimdeki sokakların Kar y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kepez']::text[], 8.5, '{"poet":"Mehmet Kepez","poet_slug":"mehmet-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dag-ruzgari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarım', 'gozyaslarim-tolga-baydar-957rm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarım sağanak oldu, aktı yine, 

Mutluluğum ve hüznüm, bir şarkı nakaratı, 

Çoğu zaman sinemde yanar, kime ne, 

Bir ben bilirim, sevgilimin hatıratı.

Coşarım kimi zaman, bebekler gibi ağlarım, 

Karşımda görünce sevgilimin fotoğrafını, 

Kor olurum kömür gibi, ciğerimi dağlarım, 

İsler, dumanlar kaplayınca yarimin etrafını.

İçimde bir ses, her an tetikte gamlı haber için, 

Kime sevdalandımsa uçup gitti elimden, 

Gözyaşım akmadı bu sefer, ağladım için için, 

Sevdalanmalar, ayrılıklara davetiye dilimden.

Ağla gözlerim ağla, ırmak, nehir olsun, 

O nehirler ki okyanuslara varacak, 

Ağla ki sevdanın değeri sorulsun, 

Okyanus içinde bulunmaz bir inci olacak.

Herkesle beraber, gönülden yürüyorken el ele, 

Şimdi bir başıma kaldım, dostsuz ve yarsız, 

Aşıklar ağlarmış, yürek kesilmiş lime lime, 

Ah durmuyor gözyaşlarım, ne kadar da arsız.', 'Gözyaşlarım sağanak oldu, aktı yine,  Mutluluğum ve hüznüm, bir şarkı nakaratı,  Çoğu zaman sinemde yanar, kime ne,  Bir ben bilirim, sevgil...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozyaslarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapmayın', 'yapmayin-baris-akm-qt6hv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yapmayın şair ruhlar

Ne olur artık durun

Bu dizeler olacak sonum

Pek erken değil amma

Biraz daha var olmalı yolum

Alınacak demli nefeslerim

Yakılmayı yaşıyacak anılarım

Biraz daha var sanıyorum

Yapmayın şair ruhlar

Ne olur artık durun

Kaleminiz olacak sonum

Ben bilmem ne günah işledim

Bilmem hangi duvar dibinde günahım

Bilen varsa beri gelsin

Şurada biraz daha bekleyeceğim

Sonra sırtlanlar diyarı yolum

Yapmayın şair ruhlar

Ne olur artık durun

Daha dinmeden kızıl pınarlarım

Üstüme üstüme yazmayın

Geçitsiz dağlarımı zorlamayın

Bir kibritliktir ömrü dinamitin

Son defa söylüyorum bakın

Neredeyse titremesi kesilecek ellerimin

Sonra, sonuncusunu tutacağım acıların

barış', 'Yapmayın şair ruhlar Ne olur artık durun Bu dizeler olacak sonum Pek erken değil amma Biraz daha var olmalı yolum Alınacak demli nefeslerim ...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yapmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezsin', 'bilemezsin-baris-akm-85k9m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi yagmur var bu şehirde

Sigaram ıslak titrek dudagımda

Dumanın bir savruluşu var ki

Bilemezsin bitanem bilemezsin

Gözüme batan dumanım oldun

Çiçegi solgun yalın damlalarımda

Yeşil şişenin dökülen acısını

Bilemezsin bitanem bilemezsin

Gözümün yollarda kalışını

Kahreden kamburumun batışını

Bir sana bakıp bir yazmanın acısını

Bilemezsin bitanem bilemezsin

Bilirmisin acep sensizligi

Sana uzanan öykünün pembeligini

Sevda bulutlarımı, saldıgım gökkuşagımı

Bilemezsin bitanem bilemezsin

Kulagımdaki şarkıyı da duyamazsın

İçimde tüten samanlıgın içten yanışınıda

El sallayıp elveda derken, beni

Bilemezsin bitanem bilemezsin

Bunu sana yazdıgımıda bilemezsin...

....................................................................1989', 'Şimdi yagmur var bu şehirde Sigaram ıslak titrek dudagımda Dumanın bir savruluşu var ki Bilemezsin bitanem bilemezsin Gözüme batan dumanım o...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bilemezsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Arkadaşım', 'sevgili-arkadasim-baris-akm-mulef', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgili Arkadaşım

1. 

Gözlerinin rengi gibi

Yüreğinin rengi gibi

Saçların da kendi renginde

Ama ben, ellerini gördüm önce 

Toplayan, düzelten, onaran ellerini

Dokunduğuna soluk aldıran

Telaşlı, usta, sevecen ellerini

Geç anladım ve inandım

Her gün daha cok inanıyorum

Ellerin, güzel işlerin karıncası

Ellerin, ellerden bıkmış ellerime sığınak

2. 

Yüzünün rengi gibi

Dudaklarının rengi gibi

Saçların da kendi renginde

Ama ben, özverini gördüm önceİ

İçinden cavlan gibi dökülen ozverini

Hep koşan, yürümeyi bilmeyen

Hesapsız, gücendirmeyen, saydam ozverini

Neye uzansa dirilten

Susan, hüzünlenen, sıcak ozverini

Geç anladım ve inandım

Gün gün daha cok inanıyorum

Özverin, güzel işlerin arısı

Özverin, sözcüklerden yılmış kafama barınak

3. 

Derinin rengi gibi

Sesinin rengi gibi

Saçların da kendi renginde

Ama ben seni gördüm önce

Gülen, yaşayan, bilen seni

Körpe bir söğut dalı gibi çırpınan

Durduğu yere can veren

Gönüllü, duyan, seven seni

Geç anladım ve inandım

Şimdi daha cok inanıyorum

Sen, hayatın ablası

Saf olan herşeyin mayası

Sen, eşyalardan usanmış kalbime dayanak

4. 

Sevgili arkadaşım benim

Sana ''sevgili arkadaşım'' diyorum

Budur, bizim anladığımız sevdanın tanımı

İşte sana bir aşk şiiri

İçinde ''sevgilim'' sözcüğü geçmiyorsa

Suçun yarısı senin

Çünkü, ben de bize yaraşanların sözcüğünü değil

Kendisini seviyorum senin gibi

Süreyya Berfe', 'Sevgili Arkadaşım 1.  Gözlerinin rengi gibi Yüreğinin rengi gibi Saçların da kendi renginde Ama ben, ellerini gördüm önce  Toplayan, düzelte...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sevgili-arkadasim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'mevsimler', 'mevsimler-burhan-kamali-tyu2f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimler 

Nice mevsimler yaşanıldı

Onca zaman içinde

İlkbaharı yazı, sonbaharı ve kışı

Herbiri ayrı şeyi anlatırdı

İnsanın yaşamındaki

Duyularına fısıldanırdı sanki

Gerçeğe ermenin vakti

Mevsimler gelip geçen değil

Yaşamanın ilahi bir işareti', 'Mevsimler  Nice mevsimler yaşanıldı Onca zaman içinde İlkbaharı yazı, sonbaharı ve kışı Herbiri ayrı şeyi anlatırdı İnsanın yaşamındaki Duyu...', ARRAY['Türk Edebiyatı','Şiir','Burhan Kamalı']::text[], 8.5, '{"poet":"Burhan Kamalı","poet_slug":"burhan-kamali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mevsimler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güne Özlem', 'gune-ozlem-gece-karasi-actu0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güne Özlem

Ben artık, 

Geceye ağıt yakmayacağım.

Ben, 

Karanlıklarda yaşamayacağım.

Ben her gece, 

Sabahı beklemeyeceğim.

Ben, 

Ufukta doğan güneşe, 

Artık umutla bakacağım.

Ben her gece, 

İcimde bir hüzün, 

Geceye ağıt yakmayacağım.

Ben artık, 

Karanlıklarda yaşamayacağım! 

Gece Karası  2002     İstanbul', 'Güne Özlem Ben artık,  Geceye ağıt yakmayacağım. Ben,  Karanlıklarda yaşamayacağım. Ben her gece,  Sabahı beklemeyeceğim. Ben,  Ufukta doğan...', ARRAY['Türk Edebiyatı','Şiir','Gece Karası']::text[], 8.5, '{"poet":"Gece Karası","poet_slug":"gece-karasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gune-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hicran', 'hicran-tarik-ziyad-9bnc0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tevhid ile coşar azablı gönlüm

Bir sevdaya gitti şu bahsız ömrüm

Cemalimde varsa hicran ve kahır

Yazacak bir söz var nede bir satır

Ab-ı hayatı yok bu derdi gamın

Zari kıldım bunca yıl geçti ömrü baharın

Sorsalarda anlatsam gönüldeki hüsranı

Kurulsada elim varmaz bedahı haceganı

Tesellim yoktur artık dalmışım bir mateme

Geçer gider gayrı ömür belli aşikare

Şu kainat şu varlık hepsi bir fani

Ne gelen var ve giden olur hepsi malayani', 'Tevhid ile coşar azablı gönlüm Bir sevdaya gitti şu bahsız ömrüm Cemalimde varsa hicran ve kahır Yazacak bir söz var nede bir satır Ab-ı hay...', ARRAY['Türk Edebiyatı','Şiir','Tarık Ziyad']::text[], 8.5, '{"poet":"Tarık Ziyad","poet_slug":"tarik-ziyad","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hicran-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'renkli yağmurlar', 'renkli-yagmurlar-burhan-kamali-r3y9c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Renkli yağmurlar

Yağmurlar yitirirdim

Bazısı yeşil, bazısı kırmızı

En son mavi olanını yitirdim

Mevsim yine yazdı 

Hatırama kazınmıştı

Masmaviydi, deniz gibi

Denizler kaybolmazdı

O kayboldu işte

Diğerleri gibi

Galiba inek içti

Bitti ve tükendi

Şimdi kış kar yağıyor

Renkli yağmurlar

En yakın ilkbaharın yağar

Yine şemsiyemi açmayacağım

Bu kez belkide başıma 

Pembe olanı yağar

Sırılsıklamda ıslatır

Bir daha kaybolmasın....', 'Renkli yağmurlar Yağmurlar yitirirdim Bazısı yeşil, bazısı kırmızı En son mavi olanını yitirdim Mevsim yine yazdı  Hatırama kazınmıştı Masma...', ARRAY['Türk Edebiyatı','Şiir','Burhan Kamalı']::text[], 8.5, '{"poet":"Burhan Kamalı","poet_slug":"burhan-kamali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/renkli-yagmurlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MENDİL', 'mendi-l-burhan-kamali-m6hcd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'MENDİL

Bir mendilim var

Kara geceden

Yıldızlar desen desen

Ağlamak istiyorum

İnceden inceden', 'MENDİL Bir mendilim var Kara geceden Yıldızlar desen desen Ağlamak istiyorum İnceden inceden...', ARRAY['Türk Edebiyatı','Şiir','Burhan Kamalı']::text[], 8.5, '{"poet":"Burhan Kamalı","poet_slug":"burhan-kamali","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mendil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Varım!', 'ben-varim-hasan-huseyin-memis-dtizw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlemle andığın sevdalarını, 

Kaybettiğini sandığın umutlarını, 

Tuttuğunda kuruyan dallarını, 

Kahrettiğin yaşamını, 

Çektiğin kahırlarda aradığını, 

Unut! 

Unut her şeyi artık, 

BEN VARIM...

	Rüzgarların önünde 

	Artık sürüklenmeyeceksin, 

	Çakıl taşları gibi 

	Yuvarlanmayacaksın, 

	Denizlere kavuşacak, 

	İçindeki azgın sular durulacak, 

	Nehirlerin taşıp 

	Seni boğmayacak, 

	Korkma.

	Korkma çünkü artık, 

	BEN VARIM...

	Kaldırımlar sensiz 

	Öksüz ve yetim kalacak, 

	Köşe başlarında gözlerin 

	Kimseyi aramayacak, 

	Gözlerin ışıkları sönen evleri görmeyecek, 

	İçindeki sen; 

	Seni özlemeyecek, 

	Senin için üzülmeyecek, 

	Seninle kucaklaşacak, 

	Seninle barışacak, 

	Hatta sana yeniden aşık olacak; 

	Gecelerin ayazında soğuklar sana sarılmayacak, 

	Üşüme.

	Üşüme çünkü artık, 

	BEN VARIM...

Her gecede bin umudun, 

Her umudunda bin cennetin olacak, 

Ümitlerin ölmeyecek yeniden doğacak, 

Sevgililer bile gözlerine saklanacak, 

Göçmen kuşlar artık sana sığınacak, 

Sen yaşama değil, 

Yaşadıklarına veda edecek, 

Tek başına içtiğin zehirlerden vazgeçeceksin

Çünkü, 

Artık o zehiri seninle paylaşacak 

BEN VARIM...

Bedenindeki tüm damarlarından sök at onları, 

Değmez! 

Haykırma geceleri artık onlar için, 

Şarkılarındaki notalar onlarsız kalsın, 

Kirpiklerin artık onlarsız ve mutluluktan ıslansın, 

Mutluluk gözyaşların benim kaderimi de aklasın, 

Yok et! 

Boğ! 

Sök at yüreğinden O haramileri! 

Hatta yak onlarla ilgili her şeyi, 

UNUT BİRTANEM

	UNUT ARTIK HERŞEYİ

	YALNIZ DEĞİLSİN ARTIK! 

		Kapında, 

		Senin için gelen, 

		Kovsan da gitmeyecek, 

		BEN VARIM...

		SENİN İÇİN...

		BİZİM İÇİN...

		BENİM İÇİN...', 'Özlemle andığın sevdalarını,  Kaybettiğini sandığın umutlarını,  Tuttuğunda kuruyan dallarını,  Kahrettiğin yaşamını,  Çektiğin kahırlarda a...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/ben-varim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-hasan-huseyin-memis-8ov52', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keşke seninle, senin olsaydım

Keşke saçının teli kadar yer

Seninle benim sığınağım olsaydı.

Keşke gölgen kadar seninle olsaydım, 

Sadece gölgede dolaştığına üzülseydim, 

Ay ışığıyla daha da sana yakınken...

Keşke her gün bastığın merdivenlerin basamağı olsaydım, 

Böyle uzaklarda olacağıma

Bastığın taşlar ben olsaydım...

Seni tanımamış olsam 

İnan ölümle gıdıklanmış olurdu canım.

Düştüğüm kadar kolay çıkamam girdabından

Kendi halime gülmez

Uçardım mutluluğumdan.

Gören oldu mu düşüşümü diye bakmazdım camlara

Sana doğru akmaktan hiç utanmaz, 

Sana koşarken tökezleyip yeniden düşmekten korkmazdım.

Keşke o hasta yatağın ben olsaydım

En zor anında kucaklasaydım seni, 

Dilediğin kadar ısıtsaydım narin bedenini...

Olsaydım eğer, gözyaşlarının sızdığı yastık olurdum, 

Belki de o zaman ‘gelsin! ’ diye ‘gelir mi? ’ diye

Özlemezdin kimseleri...

Sende bu yürek, 

Sende bu güzellik, 

Sende bu içtenlik varken, 

Cehennemlerimi cennet yapar içine sığınırdım...

Senin yerine ben ağlar, 

Senin yerine benim canım yanar, 

Senin için belki de bir işe yarar, 

En yalnız olduğun anda, 

En az yalnızlığı sana yaşatırdım...

Keşke seninle, senin olsaydım

Senden uzaklaşanları, 

Senden kaçanları özlemezdin o zaman

Yüreğine sarılırdım

Sızlamazdı bağrın o zaman.

Asla unutmadım

Unutmadım, unutamadım bak seni, 

Zaten unutmaya da çalışmadım ki...

Aslında unutmadım kendimi yakmayı

Unutmadım yangınımla seni de ısıtmayı, 

Küllerimi alıp gecelerde, yalnız kaldırımlara savurmayı.

Hepsi senin içindi

Bilmem rüyalarında bunları da görebildin mi? 

Sığdıramam, 

Sığmaz ki anlatacaklarımın hepsi kainata

İşte sen orada, 

Ben burada.

Sen öyle sansan bile

Ayrı değiliz işte, 

Sessiz, ıssız ve garip değilsin

Bilmem acaba sessizliklerde ve karanlıklarda 

Bir gün beni de fark eder misin? 

Yaşayan, yaşanan, yaşanamayan saatler geçiyor

Akıp, yitiyor zaman...

Yine telaş içinde dilim, yüreğim

Biliyorsun, 

Son durağa senden yakın yerdeyim; 

Sana ondan koşuyor ve hatta anlayamasan da yalvarıyorum

Tarifsiz bir telaş içinde

Öldüresiye panikteyim...

Yanındayım işte

Beynimle, yüreğimle

Sen ızdıraplar içinde

İşte seni özlüyorum

İşte senin için ben yanıyorum.

İşte seni anıyorum

Kulakların çınlar, 

Acaba hıçkırık tutar mı diye, 

Olmuyor, 

Üzülmekten ve çaresizlikten yoruluyorum...

Aklım sendeyken bile

Aklının benimle olmadığını anlıyorum

Kahroluyorum...

Bir bilsen ne kadar güzel oluyor

Yan yanayken bile seni özlemek...

Acaba neden? 

Acaba niye? 

Görmediğim acılarınla, 

Çekmediğim ızdırabınla yaşıyorum

Ama sen (               ) 

Bana duyurmasan da çınlıyor kulakların

Seyriyor göz kapakların...

Seni ananı benden başka bir kimlikte aramak niye? 

Kaldır öne eğdiğin dertli başını

Öpeyim alnından ve gömüleyim istersen oraya

‘Bembeyaz kaderim’ diye...

Seni görmesem de 

Biliyorum birini özlediğini

Sen söylemesen de

Biliyorum birini beklediğini

Sen demesen de

Biliyorum yaşadıklarına lanet ettiğini.

Kulaklarım çınlıyor

Boğuluyorum yalnızlıkla

Gözüm seğriyor

Hissediyorum beni hep ve yalnızca 

Hayallerde ve uzaklarda bırakmak istediğini

Tanrı’nın varlığına inandığım gibi...

Sessiz olma olur mu? 

Daha önceleri olduğun gibi..

Aç kulaklarını ne olur

Yapma! Tıkama! 

Duymamak için düşünmediklerini

Kendini sağırlaştırdığın gibi...

Günlerinde ve aydınlıklarında da dokunayım

Şafaklarında tül olayım

Sen de gecelerimde güneşim ol hadi! 

Isıt, 

Yaşat, 

Besle, 

Sev, 

Sar 

Öp ve koru beni

Şimdiye kadar kimseye yapmadığın gibi...

Sevgimi anlamak için gül değil toprak ol

Sar, 

Ve içimden

Yeni ve sana ait bir ben çıkıncaya kadar

Asla bırakma beni...

Rüzgar esmese de duyuyorum kokunu, 

Hissediyorum tenini

Sen paylaşmak istemesen de 

Birlikte yaşıyorum kederlerini, 

Ben biliyorum

Ama sen bilmiyorsun

Belki de bilmek istemiyorsun

Deli olmadan da

Aklı başında

Delice özlüyorum, 

Delice bekliyorum seni

Hiç kimseyi

Bugüne dek beklemediğim, özlemediğim

Hiç kimsenin bugüne dek seni 

Beklemediği ve özlemediği gibi...', 'Keşke seninle, senin olsaydım Keşke saçının teli kadar yer Seninle benim sığınağım olsaydı. Keşke gölgen kadar seninle olsaydım,  Sadece göl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Memiş']::text[], 8.5, '{"poet":"Hasan Hüseyin Memiş","poet_slug":"hasan-huseyin-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":136,"source_url":"https://www.antoloji.com/keske-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN VE BEN', 'sen-ve-ben-sair-yasef-5ifxk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sensizliğin isyanlarında, 

Sen kimbilir hangi düşüncelerde.

Ellerim ellerine muhtaçken, 

İçimi ısıtan gözlerin nerde.

Her gece ağlarken yalnızlığa, 

Hayallerimden çıkıp gerçekleşmelisin.

Karanlığıma bir güneş gibi doğmalı, 

Yalnızlığımı sevginle sarmalısın.

Üşüyen ellerime, kanayan yarama, 

Sonsuzluğa dek umut olmalısın.

Gördüğüm her gözde, duyduğum her seste, 

Aramamalıyım seni.

Yokken var olmalısın benimle.

Özlemeliyim seni doya doya, en umutsuz özlemimde, 

Ansızın çıkmalısın karşıma.

Bin hasretime, tek bir bakışın yetmeli.

Ben sensizliğe ağlarken, 

Sen her düşen gözyaşıma değmelisin.....!', 'Ben sensizliğin isyanlarında,  Sen kimbilir hangi düşüncelerde. Ellerim ellerine muhtaçken,  İçimi ısıtan gözlerin nerde. Her gece ağlarken ...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-ve-ben-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İHANET', 'i-hanet-sair-yasef-8mar0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece hangi limanda durdu yüreğin! 

Hangi havayı soludu yüreğin! 

Hangi yıldıza baktı gözlerin! 

Hangi nefesi sardı ruhun! 

Daha kaç gece

Aşkıma ağlamalı gözlerim! ....', 'Bu gece hangi limanda durdu yüreğin!  Hangi havayı soludu yüreğin!  Hangi yıldıza baktı gözlerin!  Hangi nefesi sardı ruhun!  Daha kaç gece ...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ihanet-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİNSİZ', 'gozleri-nsi-z-sair-yasef-a5o26', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben senin dünyanda; 

Senin duygularının eseri.

Sen benim bahçemde; 

Hiç solmayan çiçek.

Ben senin gecende ışıldayan yıldız; 

Sen benim gecemde sonsuz güneş.

Hiç bitmesin istiyorum bu rüya.

Hep yaşasın hayallerim seninle.

Sevgime hiç doymamalı yüreğin, 

Hep istemeli beni gözlerin.

Sonsuza dek hissetmeliyim ateşini.

Sevginle nefes almalı, 

Gözlerinsiz son bulmalı hayatım...', 'Ben senin dünyanda;  Senin duygularının eseri. Sen benim bahçemde;  Hiç solmayan çiçek. Ben senin gecende ışıldayan yıldız;  Sen benim gecem...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerinsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEVGİN GERÇEK', 'sevgi-n-gercek-sair-yasef-khbjq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece sensizliği düşündüm...

Sensiz, sevginsiz var olmayı...

Mümkünmüydü yaşamak! 

Hep sordum

Tekrar tekrar sordum.

Her cevap aradığımda, 

Biraz daha düştüm ölümün tuzağına...

Nefesim duraksadı, yüreğim suskunlaştı.

Ölümü an be an içtim sordukça...

Sonra bir an gözlerin geldi aklıma.

Sevgin sardı beni, titrerken bedenim.

Gözlerin umut oldu, ışık verdi bana.

Yüreğim anlam kazandı, can buldu.

Ellerini yüreğimde hissettim o an...

Ayrılmak mı? ! Gitmek mi uzaklara? ! ASLA! ! ! 

Sen ve ben aşkım

Var oldukça yaşam bulacak sevgimiz.

Sensizlik bu dünya kadar yalan, 

Sevgin gözlerin kadar gerçek! 

Seni seviyorum....', 'Bu gece sensizliği düşündüm... Sensiz, sevginsiz var olmayı... Mümkünmüydü yaşamak!  Hep sordum Tekrar tekrar sordum. Her cevap aradığımda, ...', ARRAY['Türk Edebiyatı','Şiir','Şair Yasef']::text[], 8.5, '{"poet":"Şair Yasef","poet_slug":"sair-yasef","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgin-gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayali', 'hayali-barbaros-mustafa-guner-nbrcs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hadi güzelim sessizliğimizi harflerle paylaşalım diyorum sana

Ben ünsüzleri almışım pek sesim çıkmıyor, 

sana ünlüler kalmış çığlık çığlığa susuyorsun.

İçimde birşeyler var söylemek istiyorum sana tabiri caizse

ve caiz olmak bir tabir ise seni seviyorum diyorum.

Ama sen hayallerimin fahişesi olmuş camlara yazılıyorsun.

Bi de sabaha karşı düşlerimde gerçeğe.

Oysa ayrılığımızın kurduğumuz bi cümle arasında 

küçük bi virgüle sulandığını bilmiyorsun.

Bi sen, bi ben virgülü bol cümleler kullanıyoruz zaten

noktalara göz kırpıyoruz...

                                                  16-01-2001', 'Hadi güzelim sessizliğimizi harflerle paylaşalım diyorum sana Ben ünsüzleri almışım pek sesim çıkmıyor,  sana ünlüler kalmış çığlık çığlığa ...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Mustafa Güner']::text[], 8.5, '{"poet":"Barbaros Mustafa Güner","poet_slug":"barbaros-mustafa-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orta Halli', 'orta-halli-ahmet-ulukaya-uxlaj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne altımda sihirli seccade var

Ne elimde kırbaç

Ne ebemkuşağını belime dolayabilirim

Ne yıldız toplayabilirim gökyüzünden

Orta halli bir insanım ben

Ne geceye hükmüm geçer ne güne

Yağmur yağacaksa yağar

Dur diyemem

Rüzgar esecekse eser sus diyemem

Havadan hoşnut değilsem

Kendi kendime söylenir dururum

Ben orta halli bir insanım

Ne ayı kucaklayıp yanına getirebilirim

Ne seni gökyüzüne götürebilirim

Orta halli bir insanım ben

Sana en güzel hediyem sevgimdir

Sade, samimi, sıcak

Kapına geldim ister içeri al

İster kapıda bırak

Orta halli bir insanım ben, beklerim...', 'Ne altımda sihirli seccade var Ne elimde kırbaç Ne ebemkuşağını belime dolayabilirim Ne yıldız toplayabilirim gökyüzünden Orta halli bir ins...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ulukaya']::text[], 8.5, '{"poet":"Ahmet Ulukaya","poet_slug":"ahmet-ulukaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/orta-halli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüksek Gönül', 'yuksek-gonul-ahmet-ulukaya-d5vli', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duyduğuma göre

Alçakgönüllüyü seviyormuşsun

Gönül senin

Seversin

Ben 

Yüksekgönüllüyü severim...', 'Duyduğuma göre Alçakgönüllüyü seviyormuşsun Gönül senin Seversin Ben  Yüksekgönüllüyü severim......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ulukaya']::text[], 8.5, '{"poet":"Ahmet Ulukaya","poet_slug":"ahmet-ulukaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yuksek-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ufkun Çocuğuyum', 'ben-ufkun-cocuguyum-osman-yuksel-serdengecti-ny2c5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ufuk uçsuz bucaksız gerilmiş bir kanattır.

Nazar dokunuverir onun güzelliğine, 

Bilmem hiç rastlanır mı yeryüzünde dengine? 

Bakarsın belki bugün kararıverir ufuk, 

Bakarsın belki yarın ağarıverir ufuk

Ufuk derin bir aşkla yanıp tutuşur bazan, 

Bazan bir bıçak olur yürekleri zedeler, 

Bazan bir hasret olur neler bekletir neler! ...

.......................................................................

Demin çatkın bir kaştı, şimdi gülen bir yüzdür.

Bakarsın bir yetimdir, bakarsın bir öksüzdür.

Birgün beni öp diye yalvaran bir dudaktır, 

Birgün zehir kaynağı kurulmuş bir tuzaktır.

Bahtımla kara bahtı ayıran çizgidir o! 

Dertleri günahları silen bir silgidir o! 

Kalemlere, dillere gelmeyen bir eserdir, 

Bakarsın bir batıştır, bakarsın bir zaferdir.

Ufuk benim her şeyim can yoldaşımdır ufuk, 

Sevgimdir, sevgilimdir, öz kardeşimdir ufuk.

................................................................

Ben de zaman elinde hem batı hem doğuyum, 

Beni ufuk doğurdu ben ufkun çocuğuyum.

İstanbul, Çamlıca,5-Eylül-1937', 'Ufuk uçsuz bucaksız gerilmiş bir kanattır. Nazar dokunuverir onun güzelliğine,  Bilmem hiç rastlanır mı yeryüzünde dengine?  Bakarsın belki ...', ARRAY['Türk Edebiyatı','Şiir','Osman Yüksel Serdengeçti']::text[], 8.5, '{"poet":"Osman Yüksel Serdengeçti","poet_slug":"osman-yuksel-serdengecti","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ben-ufkun-cocuguyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lale Sevdası', 'lale-sevdasi-hamdullah-arvas-r3wgq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Laleli bir düştür benimki

Laledan bir gülüş seninki

Lalezar bir serzeniştir benim ki

Laleden bir cevap seninki

Lale diyorsam siyahındandır

Lale sevdasıdır bizim ki

22 Aralık 2000

HİZAN', 'Laleli bir düştür benimki Laledan bir gülüş seninki Lalezar bir serzeniştir benim ki Laleden bir cevap seninki Lale diyorsam siyahındandır L...', ARRAY['Türk Edebiyatı','Şiir','Hamdullah Arvas']::text[], 8.5, '{"poet":"Hamdullah Arvas","poet_slug":"hamdullah-arvas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lale-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ihlamurlar Çiçek Açtığı Zaman I', 'ihlamurlar-cicek-actigi-zaman-i-bahaettin-karakoc-l10vd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dilimde sabah keyfiyle yeni bir umut türküsü

Kar yağmış dağlara, bozulmamış ütüsü

Rahvan atlar gibi ırgalanan gökyüzü

Gözlerimi kamaştırsa da geleceğim sana

Şimdilik bağlayıcı bir takvim sorma bana

-Ihlamurlar çiçek açtığı zaman.

Ay, şafağa yakın bir mum gibi erimeden

Dağlar çivilendikleri yerde çürümeden

Bebekler hayta hayta yürümeden

Geleceğim diyorum, geleceğim sana

Ne olur kesin bir takvim sorma bana 

-Ihlamurlar çiçek açtığı zaman.

Beklesen de olur, beklemesen de 

Ben bir gök kuruşum sırmalı kesende 

Gecesi uzun süren karlar-buzlar ülkesinde 

Hangi ses yürekten çağırır beni sana 

Geleceğim diyorum, takvim sorma bana

-Ihlamur çiçek açtığı zaman.

Bu şiir böyle doğarken dost elin elimdeydi

Sen bir zümrüd-ü ankaydın, elim tüylerine deydi

Sevda duvarını aştım, sendeki bu tılsım neydi? 

Başka bir gezegende de olsan dönüşüm hep sana 

Kesin bir gün belirtemem,  n`olur takvim sorma bana 

-Ihlamurlar çiçek açtığı zaman.

Eski dikişler sökülür de kanama başlarsa yeniden

Yaralarıma en acı tütünleri basacağım ben

Yeter ki bir çağır beni çiçeklendiğin yerden 

Gemileri yaksalar da geleceğim sana 

On iki ayın birisinde, kesin takvim sorma bana 

-Ihlamur çiçek açtığı zaman.

Bak işte, notalar karıştı, ezgiler muhalif 

Hava kurşun gibi ağır, yağmursa arsız 

Ey benim alfabemdeki kadîm Elif

Ne güzellik, ne de tat var baharsız

Güzellikleri yaşamak için geleceğim sana

Geleceğim diyorum, biraz mühlet tanı bana

-Ihlamurlar çiçek açtığı zaman.

Ihlamurlar çiçek açtığı zaman

Ben güneş gibi gireceğim her dar kapıdan 

Kimseye uğramam ben sana uğramadan

Kavlime sâdıkım, sâdıkım sana 

Takvim sorup hudut çizdirme bana 

Ben sana çiçeklerle geleceğim

-Ihlamurlar çiçek açtığı zaman. 

(Uzaklara Türkü)', 'Dilimde sabah keyfiyle yeni bir umut türküsü Kar yağmış dağlara, bozulmamış ütüsü Rahvan atlar gibi ırgalanan gökyüzü Gözlerimi kamaştırsa d...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ihlamurlar-cicek-actigi-zaman-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuğbam', 'tugbam-mahir-cagri-sfdet', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanlar; gün 25 saat olsa der

daha çok çalışmak

daha çok uyumak

daha çok kazanmak

daha çok eğlenmek

ve daha çok dahalar için

Ben ne için isterdim biliyor musun? 

Seni günde 1 saat daha çok

sevebilmek için.', 'İnsanlar; gün 25 saat olsa der daha çok çalışmak daha çok uyumak daha çok kazanmak daha çok eğlenmek ve daha çok dahalar için Ben ne için is...', ARRAY['Türk Edebiyatı','Şiir','Mahir Çağrı']::text[], 8.5, '{"poet":"Mahir Çağrı","poet_slug":"mahir-cagri","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tugbam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Ve Denizkızı (1)', 'i-stanbul-ve-denizkizi-1-yakup-erol-tlkn3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı yoldayım, yorgunum

Seni düşünüyor, seni düşlüyorum.

Kışın soyunan, yazın giyinen ihtiyar çınarı

Renk renk şekerli külahları

Sakız satan çocukları

Bostan sulayan köylü kadınları

Bir bahçevan edasıyla bahçe çapalayan ninemi

Düşünüyor, düşlüyor ve ağlıyorum.

Hıçkırığım hıçkırığına karıştı

Sende ağlıyorsun denizkızı biliyorum

Fikir kuşu oldun, yaralı bir kuş

Uçamıyor ağlıyorsun

Bir kız gibi süslenmiyor

Beyaz ve hisli cildine değen

Nameleri duymuyorsun.

Hiç olmazsa sen konuş ihtiyar çınar

Anlat derdini, derdimizi

Rahleitedrisinden geçenleri

Hisleri, duyguları, ihtirasları

Sokakları ve kızları

Bir gelin gibi süzülen

Yaprakları anlat bana.

Şirvanlı kahvehaneleri 

Maşandıralı odaları

Nara vuran leventleri

Cirit oynayan delikanlıyı

Sabır taşından akan ninnileri anlat

Ebrularla bin destanı anlatan Nedimi anlat

İstanbulu anlat İstanbulu…

Salık verdim duygularımı

Sadabat parkının hemen arkasında kaldı.

Güzel yüzlü avuntuları duymadım

Ben yaşadıysam hiç yaşamadım

Süleymaniyede bir bayram namazı kılmadım

Beyazıtta bir nargile

Çamlıcada bir ahududu içmedim.

Sesimi sesine verdim

Kulaklarımı kulaklarına

Ve kalbimi kalbine

Bir çift cariyeye değişmedim gülüşünü

Ben divitleri, maktaları

Ben zarif nakışlarını

Ve boynuz saplı kalemtraşını sevdim.

Ben şefkat kuyusundaki sebilinden

Bir cansuyu içmedim

Bir cansuyu dağıtmadım.

Ben gözleri kanlandıran yazılarını okumadım

Nisandaki yağmurunu tatmadım

Hep ağladım, hep ağlayacam.

İçindeki bakir duyguları açmadın bana 

Yoksa nazar mı değdi? 

Ne oldu söyle sana ne oldu? 

Dilin tutulmuş, kalemin kırılmış

Mürekkebinde mi tükendi yoksa

İsyanım ve yalnızlığım hep sana 

Ben mor salkımlı akşamların hüznüyüm

Hakikatle mağlup olmak ne kötü

Yada ne üstün bir zevk.

Yanına sokulmak acemiliği içindeyim

Kırlara yayılan taze otlar gibi serildim

Buram buram Anadolu kokan türküleri dinledim

Mıcırla yanan bir mangalı 

Ve üst üste kesik öksürükleri

Hep seni düşledim hep seni

Bir elinde kuş lokumunu

Diğerinde simidi, kırmız şurubunu

Turşucuların günlük melodisini dinledim.

Ben acem halılarını, yastıklarını

Fıskiyeli havuzunu, oyma tavanı

Nargilenin ölü yılan gibi

Sallanan marpuçlarını görmedim.

Ben sevdim ama sevilmedim

Ben yaşadıysam hiç yaşamadım

İstanbullu olamadım, İstanbullu

Ben gözü dönmüş şehir uşaklarını gördüm

Pilavcı Muammer ağayı

Vefada Baki çavuşun kahvesini gördüm.

Bugün gülüp söyleyip 

Yarın unutup geçmedim

Bir çocuk gibi harçlığımı verdim

Muheyya bir gülüşüne

Sesine ve nefesine

Bahsettiğin aklalem

Kırmızı begonyam nerde

Yardım et bana denizkızı

Oluklardan kopan buzlar gibi dağıldım

Üsküdarın serin sularıyla uyandım

Taşları göle atan bir çocuk edasıyla seslendim

Yoksa beni duymadın mı

Güneşin pembeleşmiş gözkapağında seni buldum

İçimde yaşattım eritmedim

Muhteşem vucudunla benliğimi hatırladım

İstanbul Ah…

Altın parmaklarını uzatıver gökyüzüne 

Bulutların saçları dağılsın

Ateşten elbiseni çıkart

Akşamın mor ve yumuşak kaftanını giy

Deniz böcekleriyle yapılmış gerdanını tak

Takıver ne olursun bir kere

Bir kez göster vucudunu 

Mazi çukuruna dalmış bir gözle

Gümüş bir bilezikle

Mercan bir yüzükle

Dalgaların sahile hamlesini göreyim bir kere

Gülistan olsun gönlüm şu kandil gecesinde

Ve sürmesinde, kınasında ve tesbihinde 

Hulasa tövbekardır insanlar bu günde 

Hissiyatsız hissime his ver ne olursun

Açıver duvağını bir gelin edasıyla bu günde…

                                    

                                                  29/04/1999', 'Gecenin bir yarısı yoldayım, yorgunum Seni düşünüyor, seni düşlüyorum. Kışın soyunan, yazın giyinen ihtiyar çınarı Renk renk şekerli külahla...', ARRAY['Türk Edebiyatı','Şiir','Yakup Erol']::text[], 8.5, '{"poet":"Yakup Erol","poet_slug":"yakup-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":110,"source_url":"https://www.antoloji.com/istanbul-ve-denizkizi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİİRİMİN ADI', 'si-i-ri-mi-n-adi-nurhan-ozkan-4xtir', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ŞİİRİMİN ADI

Bir şiir yazsam, 

İçinde aşk, tutku ve sen! 

Bir şiir yazsam yine

Ve içinde yalnız ben! 

Çünkü yalnızım şimdi ben

Öyle, şiirlere konu olan yalnızlıklardan değil bu

Gerçek gibi, sensiz gibi, tek gibi

Beceremem ya hiç, olsun.

Bir şiir yazsam, 

İçimde iki dost eli...

Dokunsam o ellere

Ve sonsuz bir güvenle bağalansam hayata.

Mutlu olsam

Hiç olmadığım kadar belki.

Bir şiir yazsam, 

Bu defa içinde yalnızca gerçekler

Umutsuz çaresiz hayatların gerçeği.

Onlar, 

Her sabah bir koşuşturma 

Dökülürler sokaklara.

Dudaklarında gözlerinde anlatılmak istenen

Onca şey varken

Ne ağızlarını bıçak açar

Ne de anlamlı bakar gözleri; 

Öfkeleri de sevinçleri de yüreklerinde gizlidir, 

Anlatamazlar ne demek istediklerini

Anlatmaya kalkarlar, 

Bu defa da nereden başlayacaklarını bilmezler.

Birbirlerine karıştırırlar her şeyi.

Belki onlardan biriyim ben de

Anlatamıyorum ne demek istediğimi.

Bunun içindir ki

Düşündümde, 

Bir şiir yazsam

Adı olmasa...

Adı dünde saklı

Yarında bilinmez olsa

Ama bugünde yaşasa! 

Bir şiir yazsam

Birlikte bugünü yaşasak...', 'ŞİİRİMİN ADI Bir şiir yazsam,  İçinde aşk, tutku ve sen!  Bir şiir yazsam yine Ve içinde yalnız ben!  Çünkü yalnızım şimdi ben Öyle, şiirler...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Özkan']::text[], 8.5, '{"poet":"Nurhan Özkan","poet_slug":"nurhan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/siirimin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canlar', 'canlar-tekin-gonenc-4hl8d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'siz bakmayın

ne el çekilir buralardan

ne ayak

arada serseri bir kurşun

ya da ucuz atlatılmış bir kımıltı

deler sessizliğini

en dilsiz yerinden gecenin

kim aklar karaları

kim karalar akları

hiç sormayın bana

bilemem

uçuk mavi bir yalnızlığın ortasında

çıkıp kendimden günde üç posta

koşar aynalara seslenirim

bu nasıl ben

ölümün en çok yakıştığı bu nasıl ben

siz kendi gelgitlerinizde

uyurken gecelerinizi

yüzümüzün kıvrımlarından

seğirterek geçer

o gizemli masal

ben tuncelili hamza

sen istanbullu hakan

uçuk mavi bir yalnızlığın ortasında

birer kahraman', 'siz bakmayın ne el çekilir buralardan ne ayak arada serseri bir kurşun ya da ucuz atlatılmış bir kımıltı deler sessizliğini en dilsiz yerind...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/canlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hayata..eskimeyen yüzüne..ömrün..', 'hayata-eskimeyen-yuzune-omrun-rabia-can-ulas-6fj3u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'o bembeyaz gelinlikli saçlarını zamana inat savuran

güzel kıza hayata...kaldırıyorum..gözlerimi..

sancısı.eksilmez ayçok sevdiğimizden midir nedir ayrılık ve bitişin 

sırtımı yasladığım her yerde bir tedirginlik..

gelecek bir haberin sancısı.

aşamayı..

seninki gülümseten bir mesajdı..

karlar arasında dersimde..

ben titreşirken soğuktan cebimde çırpınan bir ağrıydı..

gözlerim değdiğinde bakışlarımı yakan..

a.c de b.de simetrik y.k layan kitle i.yazmıştın..

kendi anladığınca..

gülümsedim ve hatadır dedim..

ve sen işe girmek için rutin bir muayenede yakalanmıştın..

azraile.

sonra dedim bunu..

dedimya o zaman hata dır demiştim..

nasıl yirmiüç yaşında ölüme hazırlanır bir insan..

-gözlerimi bağladığım yıllarda olurdu böyle şeyler..-

açmaya hazırlana bir çicek nasıl solardı..

her nefes doldururken kendini, 

karanfil kokularıyla..

şimdi genzim yanıyor..

ve yaslayamıyorum kendimi hiç bir yere

boğazımda düğümleniyor zaman..

teller duvaklar sarıyor soluklarımı..

ve terler içinde uyanıyorum..

her mesaj geldiğinde..

ki karlar içinde ne çok ısınırdı içim yazdıklarınla..

dağlara sererdim, kokunu 

gözlerin munzurca çoğalırdı..

sarardım sesini üşüyen bedenime..

dalar giderdim..kendi ülkem kıl bir battaniye altında..

şimdi üşüten bir yalnızlık, her mesaj tonu..

çekip gittin bir kez titretmeden içimi..

duyduğumdaysa depremler oldu yüreğimde, 

yaslayamıyorum şimdi kendimi hiç bir yere, 

ve sığamıyorum koca ömrümle o minik ömrüne..

benden almadın inan..

yirmi üç yıl ekleyipte gittin şu sisli yüreğime..

genzimi yaksada çicek kokuları.

sen koklanmamış bir çicektin..

dünya sana yetmedi..

-ki hep sorduğum soruydu kendime-

çok ta eyvallah etmedin azraile..

sallamadın pek kemoterapi, radyoterapi

radyodan sevdiğin şarkılar kadar.önemsemedin.

ve kışı sonbahara çevirdin gittin..

önemseme benim mızmız romantizmimi..

sen keyfine bak..

tek mutlandığım şey varki..

sen olduğun her yeri cennete çevirirsin..

orda ol..

her çocuğun ağlayışında.

her çiceğin açışında..

ve her mesaj tonunda..

bendesin..

mevsimler boyu..

ağrısada yüreğim..

unutmayı öğreninceye kadar..

umutları hiç önemsemedin..

şimdi mutlu uyu..

ve geç dalganı bulutlarla..', 'o bembeyaz gelinlikli saçlarını zamana inat savuran güzel kıza hayata...kaldırıyorum..gözlerimi.. sancısı.eksilmez ayçok sevdiğimizden midir...', ARRAY['Türk Edebiyatı','Şiir','Rabia Can Ulaş']::text[], 8.5, '{"poet":"Rabia Can Ulaş","poet_slug":"rabia-can-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/hayata-eskimeyen-yuzune-omrun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNDÜZ GECEDEN BAŞLAR', 'gunduz-geceden-baslar-zubeyde-basaran-5rnnc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÜNDÜZ GECEDEN BAŞLAR      

Timsahların oynaştığı yerlerde

Tavus kuşları da yaşar...

Gelincikler serpilir 

Yollara...

Güneş düşlerimizde

Doğar...

Durmaz

Yıldızların

Şiirsel yansımaları...

Yığınlaşan sevinçler

İçimize sığar…

Seviyesinde ilişkilerin

Sıcaklığı yayılır…

Kırgınlıklar

Ve iç kapanıklıklar

Yer bulmaz

Yaşantımızda…

Ülkeleri aşar

Elmas gibi işlenen

Dostluklar...

Soluk alır güzellikler

Değer kazanır çağ...

Anlaşılmazlığı konuşulmaz

Varsayımların...

Düğümlenmez

Hukuk içinde hukuk

Aşılır ayrıntısı farklılıkların...

Koşarız

Düşüncelerimizle

Kuşkuları aşarak...

Biliriz...

Zevklidir

Böylesine yaşamak...', 'GÜNDÜZ GECEDEN BAŞLAR       Timsahların oynaştığı yerlerde Tavus kuşları da yaşar... Gelincikler serpilir  Yollara... Güneş düşlerimizde Doğ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Başaran']::text[], 8.5, '{"poet":"Zübeyde Başaran","poet_slug":"zubeyde-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gunduz-geceden-baslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Beni Sen de', 'sev-beni-sen-de-serif-gurakar-ji633', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sırmısın her çiçeğin renginde? 

Kokarmısın gül gibi gizeminde? 

Haberin var, biliyorsun bunu sen de! 

Kamp kurdun, yaşlı-yorgun yüreğimde! 

Sevgiye susamış gönlümde bir yangınsın.

Her gün ve gece, düşüncem ve kaygımsın.

Aşka gösterebileceğim; sevgim ve saygımsın.

Sev beni sen de, ben gibi; herkes bunu anlasın! 

Hüzünü anımsatır, sonbaharlar hep bana.

Yüceliğini aşkımın, nasıl anlatsam ki sana? 

Diz çöksem önüne, şarkı yazsam yoluna! 

İnanır da; sevgilim der, girermisin koluma? 

Gel artık kollarıma benim nazlı çiçeğim! 

İnan seni ömrümce, çılgınca seveceğim! 

Kalbimi yalnız sana, tek sana vereceğim! 

Ulaşamazsam sana, aşkınla öleceğim! ! ! 

               (Turgutlu     01.10.2001)', 'Sırmısın her çiçeğin renginde?  Kokarmısın gül gibi gizeminde?  Haberin var, biliyorsun bunu sen de!  Kamp kurdun, yaşlı-yorgun yüreğimde!  ...', ARRAY['Türk Edebiyatı','Şiir','Şerif Gürakar']::text[], 8.5, '{"poet":"Şerif Gürakar","poet_slug":"serif-gurakar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sev-beni-sen-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzler', 'i-zler-baris-akm-3n865', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç yabancı değil bana

uzanmak uçurum diplerine

ki heyhat ben zaten oralıyım

siyah laleler kokar bağım bahçem

sönük ışıklarım, yıldızım ve ay-ım

yeni değil sinsi sızılarım

Kaybolmak gecenin bir yerinde

ben zaten kayıplardayım

aldırmadan kimseye deyince

kanayan yarama tuz bastın

nereden, nasıl bileceksin

bir yürek var ki prangalarda

en pahalısı bileklerinde zincirin

gözlerinde hayat pahası yılların

Yanlış mı duydum hüzün mü dedin? 

bilmiyorum daha ne yaşın ne başın

bir adın bir kaç da yazdığın

daha ne acılar var oysa öğrenmeyesin

diliyorum öğrenmeyesin, aman ha sakın

barış', 'Hiç yabancı değil bana uzanmak uçurum diplerine ki heyhat ben zaten oralıyım siyah laleler kokar bağım bahçem sönük ışıklarım, yıldızım ve a...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/izler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayattan Beklentiler', 'hayattan-beklentiler-baris-akm-nt1wt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok şey bekledim yaşamdan yana çok

Sabah uyandığımda bir kahve göz gözümde

Penceremi araladığımda daha sıcacık güneş yüzümde

Peşine takılı baharlardan tatlı bir esinti saçlarıma

Kapıdan çıkarken güle güle diyen bir ses dudağıma

Her zengin yahut fakir kahvaltı sonrasında 

Çok şey istedim yaşamdan yana çok

Günün bir yerinde merhaba tatlım fısıltısını kulağımda

Öğle kahvesinde sesini duymak seni çok seviyorum diye

Sonra ne istersin akşama demeliydi yorgun güneşin kızıllığında

Güler yüz bekledim kaç yıl kapının her açılışında yok yere

Bir çay bekledim sevgiyle demlenmiş akşam sefalarında

Çok şey istedim yaşamdan yana çok

Ve buldum sonunda bulmasına da

Etrafım sarılı olunca kaktüs dikenleriyle

Zaman atı alıp çoktan gittikten sonra

Sonbaharda sarıca saçlarım seyrelip kırlaştıktan 

Ve gözlerim çöktükten sonra karanlık gökyüzüne

O da olmadı, yarınlar dizilince yüreğimin meydanına

Çok şey istedim yaşamdan yana çok

Denenirmiydi yaşam defalarca sevmek için aşkla

Belki denenirdi de olmuyor işte yiten zaman olunca

Yüreğine izlerini hançerlerle kazımış bir kere

Tenini çoktan sermiş toprağın yakın dalına

Şimdi yok yere yaşamış olmak koyuyor olsa da

İyisimi kapayıp kapıları yakıp gitmeli köprüleri

Çok şey istedim yaşamdan yana çok

Bunca zaman gülmeyen istesede gülemez bundan sonrada

Çünkü ben çok güvenmiştim hayat bir gün gülecek diye

İnanmıştım safça, tâki düşler bu kadar kırılıp dökülünceye

Yokuşlar artık çıkılamaz olmaya varınca birde

Kuyruğumu kırıp oturmak düşer artık yaşamın ben-ine 

barış', 'Çok şey bekledim yaşamdan yana çok Sabah uyandığımda bir kahve göz gözümde Penceremi araladığımda daha sıcacık güneş yüzümde Peşine takılı b...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hayattan-beklentiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Şehir', 'kayip-sehir-baris-akm-c19sw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni arıyorum boğazı incili şehir

Bulursam kendimide bulurum

Ya bir kıyının mendireğinde 

Yahut demir alan bir geminin su yolunda

Kimbilir belki hala duruyorumdur 

Hani o hep koştuğum zamanın tozlu rafında 

Biliyorum

Aslında boş yere arıyorum seni

Sen hep yaramaz çocuk kaldın

Büyürken yolların hanların

Gövdene işlenirken köprülerin

Ben nokta misali neferin

Kimbilir hangi kaldırımının taşı

Hangi kıyının kum tanesiyim

Bilmemki seni nasıl bulurum

Ben kaybetmedimde seni

Sen beni adeta bir esmer lodosun

Bir deli zamanının kudurgan dalgalarında 

Işığımı karartıp lacivert tonlara boğdun

Bulursam seni bir umut kendimide bulurum

Hoş, aptalca bir arayış bu ya, olsun

Yoksa? 

Kaybettimmi gerçekten ben seni? 

Kayboldum sanışımın korkusu ondanmıdır? 

Düşlerimin bile siyah örtülen patiskası, 

Sabah perdelerin açılmayışı ondanmı? 

Onun içinmi kayboldum sanıyorum içinde

Demek gerçekten kayboldun gerdanı incili şehir

Beni içinde unutup gittin demek 

Bir zamanların güzel gelini İstanbul

İyi halt ettin benide yuttun

barış', 'Seni arıyorum boğazı incili şehir Bulursam kendimide bulurum Ya bir kıyının mendireğinde  Yahut demir alan bir geminin su yolunda Kimbilir b...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kayip-sehir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yüksek Bulut', 'ne-yuksek-bulut-muammer-erkul-omqe8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne yüksek bulut! .. 

Bir varmııış, bir yokmuş boyutundan: Ben zaman zaman, zemine kadar yaklaşabilip, kökü toprağa bağlı olanların kulağına; 

“Göreceksin, diyorum. 

Güneş doğacak ve pırıl pırıl yükselecek... 

Biraz sabret, diyorum. 

İnan bana; hava gayet güzel olacak... 

Sen, sadece, birazcık sabret! ..” 

§ 

Mesajlarımı fısıldadıktan sonra, sanki derin bir nefes almış gibi havalanıp yerden uzaklaşıyor, ve yine kendi irtifama dönüyorum. Belirli bir hizada geziniyor; bazen gölge, bazen yağmur gönderiyorum insanlara... 

..... 

Ama çoğu kez de bana bakıp gönül eğlendiriyor sevdalılar... 

Çocuklar, girdiğim değişik şekillerle neşelenip, bildikleri nesnelere benzetmeye çalışıyorlar beni... Ve sanata yakın kişiler, benden bir parçayı kesip saklamak istercesine, tuvallerinde veya fotoğraf kağıtlarında görüntümü zaptetmeye uğraşıyorlar... 

§ 

Halbuki ben, en çok, dupduru göllere benzeyen bebek gözleriyle; bebek gözlerine benzeyen, ve ürkek ceylanların su içtiği serin ilkbahar göllerine aksetmeyi seviyorum... 

Fakat, biliyorum ki; durmak ve dinlenmek yok... 

..... 

Biliyorum; aşağıya inmem gerek ve kulaklara fısıldamam gerek: 

“Ümitsizliğe kapılmadan sabredin... 

Bu karanlığın ardında sabah var... 

Güneş doğacak ve pırıl pırıl yükselecek... 

Şikayetlerle zaman yitirmeden, biraz daha sabredin! ..” 

§ 

Bir ses duyuyorum, heyecanlı bir ses... Fısıldar gibi bağıran, veya teeey uzaklardan çağırır gibi fısıldayan bir ses: 

“-Eyy benim ulaşılmazım; 

Sana hayranım! ..” 

“-Bana mı? 

Hayranlığın bana mı? ..” 

“-Gözüm gördü göreli hep önümde olanım... 

Benim özgürlük duygum, benim mutluluk hissim; 

Elbet sana hayranım! ..” 

“-Peki, nedenini de söyle... 

Şuna cevap ver asıl; niye hayransın bana? ..” 

“-Çünkü sen çok yükseksin. 

Aaah, yanına gelirdim, olsaydı bana iznin! ..” 

§ 

Diyorum ki bu lafının ardından; 

“-Peki, gel öyleyse... 

Haydi gel de, sana bir hakikati göstereyim...” 

..... 

Bu laf tutuşturuyor onu, ve yanıma uçuyor! 

“-Geldiğin yere bak! ” diyorum. Bakıyor. Ama baktığı an; 

“-Başım döndü, diyor. 

Çok yüksek, aşağıya baktıkça başım dönüyor... 

Ben bu kadar yükseğe senin sayende geldim, inanılır şey değil; ne kadar yüksekteyim! ..” 

..... 

“Şimdi bir de yukarı bak! ..” 

§ 

Bakıyor... 

Bariz şekilde nefesi tıkanıyor... rengi sararıyor... terliyor... 

Bir derin nefes alıyor; hayata tutunur gibi! .. 

Gözbebekleri büyüyor... 

Kocaman olmuş gözlerini ilk kırpıştırdığında, gözyaşları, fışkırıyor adeta... 

Sonra gülümsüyor... 

Sonra hıçkırır gibi oluyor! 

Gülüyor mu, ağlıyor mu belli olmuyor; konuşuyor mu, sayıklıyor mu belli olmuyor; ne düşündüğünü anlamaya uğraşırken kucağıma düşüyor! .. 

..... 

“İyisin, değil mi? ..” 

Garip ve yabancı bir ifadeyle bana bakıp, sadece başını sallıyor... 

§ 

Teselli eder gibi okşuyorum onu... 

“Sakin ol, diyorum. Ürkme... 

Gerçeklerden korkmak bir şey değiştirmez ki; tedbir almadığın sürece! .. 

Üstelik biz, gözü bağlılardanız... 

Üstelik sen hiçbir şey de görmedin! .. 

Ne görülebilir ki aklın ölçüleriyle? .. 

..... 

Başını sallıyor yine, takatsiz şekilde. 

“Şimdi, diyorum... 

Rahatlamak için bak, yeniden aşağıya. Geldiğini sandığın yerleri yeniden gör! ..” 

§ 

Bakıyor... Ama şaşırıyor yine; 

“Yer, diyor... Yer nerde? 

Yer; burdan başka yerde değil ki! .. 

Biz... Biz, henüz YERLE AYNI YERDEYİZ! ..” 

§ 

“Biliyorum, diyorum. 

Biliyorum! .. 

Ben de, işte bunu söylüyorum ya her zaman...” 

Muammer ERKUL', 'Ne yüksek bulut! ..  Bir varmııış, bir yokmuş boyutundan: Ben zaman zaman, zemine kadar yaklaşabilip, kökü toprağa bağlı olanların kulağına;...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erkul']::text[], 8.5, '{"poet":"Muammer Erkul","poet_slug":"muammer-erkul","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/ne-yuksek-bulut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Gözlerinle Başladı', 'her-sey-gozlerinle-basladi-guven-sert-razrw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne zaman bir şey dileyecek olsam

bir yıldız kayardı, 

mırıldandığım her melodi

mutlak sevda kokardı.

aldığım her nefeste içime sevgin dolar, 

yağmurlu günlerde yüreğime gözlerin çakardı.

gözlerin ki

takılsın diye gözlerime, 

ne değerler adamıştım

tek dostum gecelere.

gözlerin anlamlarıma bakışlar yüklerdi, 

o anlamlar

en yüce değerlerden daha ötelere

gözlerinle giderdi, 

her şey gözlerinle başlar, 

gözlerinli hiçbirşey bitmezdi.

ne oldu gözlerine...

hangi lanet günden beridir

gözlerin anlamlarımı terk etti.

bakışlarında gözlerin yok, 

-anlamlarımda hiç-

hayatı ve sevdayı değerli kılan ne varsa

gözlerinsizliğimin yasındadır...

-ve tek bir anına adanan değerler

kurtarabilmek için kellelerini

kutsallıkların anlamsızlığından güç alan

inançların kör bıçağından, 

gökten inecek bir meleğin

getireceği koça bel bağlamışlardır şimdi-

oysa ki benim sevdabilirliğimden başka

hiç bir dayanağı olmayan kutsallığım

asla peygamberliğimin onanmasına yetmeyecek, 

işte bu yüzdendir ki

o taşaklı koç hiç inmeyecek, 

o değerler ayaklar altında çıkıp

bir daha yükselmeyecek, 

gözlerin, 

gözlerin anlamlarıma bakışlar yüklemeyecek.

kutsallığı sevdalardan onaylı

güzel insanların

bu ve buna benzer öyküleri

hep mutlu sonsuz kalacak.

bunun tek sebebi

anlamlarımı bakışsız bırakan gözlerin olacak.

ve nice yeni sevdalıların düşlerinde

çok bilmiş bir ak sakallı dede

bu öyküyü takiben

en ukala sesiyle 

-bir büyük sevda hikayesi daha

gözlerle başladı, 

gözlerin bittiği yerde bitti-

diyecek; 

ne oldu gözlerine...', 'ne zaman bir şey dileyecek olsam bir yıldız kayardı,  mırıldandığım her melodi mutlak sevda kokardı. aldığım her nefeste içime sevgin dolar,...', ARRAY['Türk Edebiyatı','Şiir','Güven Sert']::text[], 8.5, '{"poet":"Güven Sert","poet_slug":"guven-sert","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/her-sey-gozlerinle-basladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Incidende parlaksin', 'incidende-parlaksin-emrullah-erdinc-soh2i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni ilk resminde gördugumde

ne kadar guzel 

mukemmel bir ask 

ilahi diye dusundum

gözlerin icimi oksadi.

Bir an  ruhumun derinliklerinde 

hissettim bakislarini 

sen incidende 

seni sana nasil anlatsam 

resmine her baktigimda 

gözlerim kamasiyor 

icim eriyor sanki 

gerdanin sanki cekiyor beni 

al beni kollarina saril sevgilim 

haykir ta ki sen artik 

sevgimi farkedipte kendini 

kollarima birakana dek 

haykirmak haykirmak istiyorum 

son nefesime kadar seni 

sevdigimi bende haykirmak istiyorum 

sen incidende parlaksin

gul cicekleri gibi kalbimde acmalisin

kollarimdq askin en buyugunu tatmalisin

sen incidende parlaksin. 

sana resminden dolayi

olan yuce askimi anlamalisin.', 'seni ilk resminde gördugumde ne kadar guzel  mukemmel bir ask  ilahi diye dusundum gözlerin icimi oksadi. Bir an  ruhumun derinliklerinde  h...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/incidende-parlaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-fatih-cinar-u1a03', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'biliyorum suçluyum

yarınımdan umutsuzum

senden şüphe ettim

ama kendim namussuzum

ihanetimin bedelini

ödüyorum ağır ağır

ihanetin bedeli

inanki çok ağır

sensizliğin adı yok 

inanki birtanem

sensiz geçen zamanlar 

kör ve sağır

seni aldattım 

biliyorum sinsice

zamanı akıttım

biliyorum gizlice

ama inan çok pişmanım

şimdi ben

biliyorum ihanete yer yok

gerçek sevgide

müzik: fatih çınar', 'biliyorum suçluyum yarınımdan umutsuzum senden şüphe ettim ama kendim namussuzum ihanetimin bedelini ödüyorum ağır ağır ihanetin bedeli inan...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ihanet-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Demiş', 'kim-demis-hasan-huseyin-ersoy-3hosb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim demiş, ışık mutlak hızdır

Atomda hızlısı var.

Kim demiş Ferhat son aşıktır

Bende fazlası var', 'Kim demiş, ışık mutlak hızdır Atomda hızlısı var. Kim demiş Ferhat son aşıktır Bende fazlası var...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Ersoy']::text[], 8.5, '{"poet":"Hasan Hüseyin Ersoy","poet_slug":"hasan-huseyin-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kim-demis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç!', 'kac-fatih-cinar-ezzx2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biz yürekliyiz ama güçsüzüz

onlar yüreksiz ama güçlüler

üzerimize bir şarjör mermi boşaltacaklar

bizi bizden koparıp

koparıp alacaklar

kaç kaç! 

durma kardeş kaç

kaçmazsan eğer gözümüzde yaş olacak

kaçmazsan eğer buralarda kan olacak

gönül ferman dinlemez bilirim

bilekler zora dayanır bilirim

kaçmak erkekliğe sığmaz bilirim

kaçmazsak eğer bilekler kırılacak

kaçmazsak eğer namertlere gün doğacak

müzik: fatih çınar', 'biz yürekliyiz ama güçsüzüz onlar yüreksiz ama güçlüler üzerimize bir şarjör mermi boşaltacaklar bizi bizden koparıp koparıp alacaklar kaç k...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kac-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlık Pusuda', 'yanlizlik-pusuda-fatih-cinar-tctap', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kelepçe senin çekip gitmen

inanki bir hücre sensiz geçen günler

solacak gelmezsen inan bütün güller

ne zaman bitecek söyle bu ceza

ölüm her an her an kapımda

yalnızlık kucağımda

acılar yollarımda pusuda

ayrılık kor bir ateş yanar yüreğimde

son geceki halin silinmedi gözlerimde

bıraktığın o son hatıra düşmedi ellerimde

müzik:fatih çınar', 'bir kelepçe senin çekip gitmen inanki bir hücre sensiz geçen günler solacak gelmezsen inan bütün güller ne zaman bitecek söyle bu ceza ölüm ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yanlizlik-pusuda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancılar', 'sancilar-erol-sen-a1kkb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derinden ve ince, 

Öyle şairin dediği gibi değil

Birdenbire tepeden ve hızlı

Bitmez umutsuz günlerin sancısı

Depremler olur yüreğimde

Onlar ki bitimsiz ve ölesiye

Hayata bağlayan özlemler de olmasa

Verilen karşılıksız sevgilerle birlikte

Bazen sakladığın minik bir sararmış kağıtta

Karalanmış çocuk isimlerinde

Bazen okuduğun ayrılık şiirinde

Bazende gözünün önünden geçen hatıralarda

bitimsiz SANCILAR.....

24.01.2002', 'Derinden ve ince,  Öyle şairin dediği gibi değil Birdenbire tepeden ve hızlı Bitmez umutsuz günlerin sancısı Depremler olur yüreğimde Onlar ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sancilar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-mumtaz-begen-zyo0j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstersen boydan ölç, dilersen enden, 

Değişmez çıkmadan bu can bu tenden, 

Ne yapıp etseler yine de senden, 

Ne usanır ne de bıkarım gülüm.

Falanlar filanlar bir biri ile, 

Bir araya gelip yapsalar hile, 

Vallahi billahi kuyudan bile, 

Bir yolunu bulur çıkarım gülüm.

Basmasa ayağım tutmasa elim, 

Yaşlansam iyice bükülse belim, 

Biliyorsun senden doğmuş bir selim, 

Yine sana doğru akarım gülüm.

Kalsam bir köşede topal kötürüm, 

Gözüm de görmese, sevmek de hürüm, 

Bende seni, sende beni görürüm, 

Gönül gözüm ile bakarım gülüm.

Hatırla hele bir hiç coşmadım mı? 

Sen çağırdın beni, ben koşmadım mı? 

Gün oldu kuş olup dağ aşmadım mı? 

Engel mi tanırım? .. Yıkarım gülüm.

Yatağa atmazsa bu iltihaplar, 

Ya da öldürmezse beni bu haplar, 

Dağlardan Kardelen çiçeği toplar, 

Taç yapar başına takarım gülüm.

Seni duyar senden emir dinlerim, 

Gel dersen gelir, git dersen giderim, 

Uğruna canımı fedâ ederim

Dünyayı top yekûn yakarım gülüm.

Velhasılı sensin tutunduğum dal, 

Aynen böyle işte bu cephede hâl, 

Kalmazsa bir çarem en son ihtimâl, 

Kafama bir kurşun sıkarım gülüm.', 'İstersen boydan ölç, dilersen enden,  Değişmez çıkmadan bu can bu tenden,  Ne yapıp etseler yine de senden,  Ne usanır ne de bıkarım gülüm. ...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gulum-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Yalancı', 'yalanci-fatih-cinar-xg7fa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'eski sayfaları yaksanda

külü kalır izi kalır hayatında geçmiş günlerin

yüzüme bakıpta söylediğin yalanlar

yankılanır kulağında hüzzam bir melodi gibi

seni seviyorum dediğin günlerden

takvim yaprakları kalır sadece

terkedişin tarihini hesapladığın

yalancı sen bir yalancısın! 

yalancı! 

yorgunsun ve durmaksızın

kaçıyorsun gözlerimden

sinsice ve ansızın girmiştin hayatıma neden? 

artık bana güzel gelmiyor yüzün saçların

ve sıcak bir kan akmıyor damarlarımda

yalancı sen bir yalancısın! 

yalancı şimdi git

belkide gezdiğimiz yerlerden

bir kuru toprak parçası kalır

gözyaşlarımla sulanan

üzerine evler yapılır belkide

çiçeklerini kokladığımız kırların

seni hasretle karşladığım tren garında

hasret biter raylar kalır

acılarım gibi uzayan

yalancı sen bir yalancısın! 

yalancı şimdi git...', 'eski sayfaları yaksanda külü kalır izi kalır hayatında geçmiş günlerin yüzüme bakıpta söylediğin yalanlar yankılanır kulağında hüzzam bir me...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalanci-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanırdım', 'sanirdim-mumtaz-begen-hos6h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Haylaz değil ama biraz yaramaz, 

İki sene aynı yerde duramaz, 

Şehri bırak, yere yurda sığamaz, 

Cihanı kendime, dardır sanırdım! ..

Çok görmeyin bunu, böyleydim aynen, 

Nice günler geldi geçti hey heyinen, 

Kimi zaman kuyu kazdım iğneyinen, 

Yalanı, dolanı, ardır sanırdım! ..

Köyden bilirdim ya gerçi halayı, 

Askerde öğrendim çayda çırayı, 

Görmeden misketi ve fidaydayı, 

Oyunun hasını, bardır sanırdım! ..

Portakalın, muzun nice elmanın, 

Tadına bakmadan daha ayvanın, 

Kirazın, hurmanın onca meyvanın, 

En tatlı olanı, nardır sanırdım! ..

Güzel bir gönüle kalbe girmeden, 

Bilmek mümkün değil zaten ermeden, 

Sevda ocağında nârı görmeden, 

Soba sıcağını, hardır sanırdım! ..

Şubat ayazında ter yürümeden, 

Yürüyüp tenimi kor bürümeden, 

Ağustos ayında kar kürümeden, 

Kışlarda yağanı, kardır sanırdım! ..

Kimlerden sormadım ki ince ince, 

Sevilirsin dendi sende sevince, 

Böylesi bir derde düşmeden önce, 

Dertlerin dermânı, vardır sanırdım! ..

Kim diyebilir ki; “o bir serkeşti”

Ne zaman ki gönül yaram depreşti, 

Depreşen yaramı yine yâr deşti, 

Yaranın saranı, yârdır sanırdım! ..', 'Haylaz değil ama biraz yaramaz,  İki sene aynı yerde duramaz,  Şehri bırak, yere yurda sığamaz,  Cihanı kendime, dardır sanırdım! .. Çok gör...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sanirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzinsiz Sevdam', 'i-zinsiz-sevdam-fatih-cinar-zhw4m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni düşünmeye izin yok

hain gecelerden

yakamı bırakmaz yıldızlar

sanki çığlık çığlığa yakamozlar

düşünme onu der gibi

hırçın dalgalar

seni düşünmeye izin yok gönlümden

siliyor beynim hayalini gözlerimden

bir elim resmine gidiyor

çekiyor diğer elim resmini 

resmine giden elimden

seni düşünmeye izin yok mevsimlerden

bir kar yağıyor bir gün yağmur

göstermiyor güneşini tepelerden

bülbüllerinide çekti güllerimden

seni düşünmeye izin yok hiçbir şeyden', 'seni düşünmeye izin yok hain gecelerden yakamı bırakmaz yıldızlar sanki çığlık çığlığa yakamozlar düşünme onu der gibi hırçın dalgalar seni ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/izinsiz-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-fatih-cinar-a5vfd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen şiirlerime cümlesin

sen bestelerime notasın

sen dilimde acıklı bir şarkısın

söyler söyler ağlarım

sen sabahımın güneşisin

sen gecelerimin yıldızı

sen bir yağmursun penceremde

bakar bakar ağlarım

sen bir kemansın elimde

sen gitarımın telisin belkide

seni çalarım hüzzam bir melodiyle

dinler dinler ağlarım

sen bir kadehsin elimde

seni içerim her gece

seni ararım hep meyhanelerde

içer içer ağlarım

sen bahçemde açan bir çiçeksin

sen gülsün lalesin menekşesin

seninle başlarım her güne

koklar koklar ağlarım', 'sen şiirlerime cümlesin sen bestelerime notasın sen dilimde acıklı bir şarkısın söyler söyler ağlarım sen sabahımın güneşisin sen gecelerimi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Kötürüm', 'kor-koturum-fatih-cinar-lkuj6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'benimde yollarım vardı koştuğum

umutlara açılan

benimde ağaçlarım vardı tırmandığım

meyveleri saçılan

benimde nehirlerim vardı yüzdüğüm

suları deli deli çağlayan

ama artık ben

koşamam koşamam koşamam

uzun uzun yolları

açamam açamam açamam

çalan kapıları

gezemem gezemem gezemem

ormanları dağları

çünkü ben adımlarımı kaybettim

ne yazık ben adımlarımı kaybettim

benimde kitaplarım vardı okuduğum

asi sevdalı

benimde aşklarım vardı taptığım

güzel yüzlü gül dudaklı

benimde şiirlerim vardı yazdığım

içinde binbir keder saklı

ama artık ben

göremem göremem göremem

yemyeşil baharları

saramam saramam saramam

aydınlık ufukları

yazamam yazamam yazamam

sana sevgiliye aşk mektupları

çünkü ben bakışlarımı  kaybettim

ne yazık ben bakışlarımı kaybettim

müzik: fatih çınar

(TRAFİKTE ORTAĞIZ RAKİP DEĞİL! LÜTFEN TRAFİKTE CANAVARLAŞMAYALIM! ! !)', 'benimde yollarım vardı koştuğum umutlara açılan benimde ağaçlarım vardı tırmandığım meyveleri saçılan benimde nehirlerim vardı yüzdüğüm sula...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kor-koturum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Dair Dört Nasihat!', 'sevgiye-dair-dort-nasihat-fatih-cinar-l2zrh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bırakın ellerinizden zeytin dallarını

avuçlarınıza kalplerinizi alın sıkıysa

salıverin beyaz güvercinleri ilgilenmeyin

bırakında çırpsınlar küçük kanatlarını

zengin bir hazla aşayın sevgiyi

siz tüccar değilsiniz karşılık beklemeden

sormadan sorgulamadan sevin dünyayı

dillerinizde hapsetmeyin gözlerinizdeki sevgiyi

aşkı tadın bir zeytinyağı şifasında

koklayın onu bir kırmızı gül misali

filtresiz bir cigara gibi çekin ciğerlerinize

yaşatın onu ebediyen bir fincan kahvenin hatırasında

bileklerinizi değil yüreklerinizi güçlendirin

kılıçlarınızı değil şiirlerinizi çıkarın kınından

gülün geçin arkanızdan vuran kahpe insanlara

sevdaya akan gözyaşlarınızla aşk bahçesinde çiçekler filizlendirin', 'bırakın ellerinizden zeytin dallarını avuçlarınıza kalplerinizi alın sıkıysa salıverin beyaz güvercinleri ilgilenmeyin bırakında çırpsınlar ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgiye-dair-dort-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin Zamanı Yok', 'sevmenin-zamani-yok-orhan-gencebay-bchoz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne sen gördün ne ben gördüm

Habersizce gelivermiş

Ne sen duydun ne ben duydum

Gönlümüze girivermiş

Herkesin dilinde aşk denilen meçhul

Bizi kollarına alıvermiş

Kadere bak  çok çektirdi ikimize

Şimdi özür diler gibi sevin dedi gönlümüze 

Ne sen çağırdın ne ben

Ne sen anladın ne ben 

Usul usul sessiz sessiz aşktır bizi mutlu eden

Şu kısacık ömrümüzün nesi var ki aşk olmasa

Ne olurdu şu dünyayı ayrılıklar soldurmasa

Gönül istiyor ki sevip sevilirken bir mucize olsa zaman dursa

Zamanı yok aşk bir meçhul zamanı yok

Büyük söz söylemiş dilim sevmenin hiç zamanı yok.', 'Ne sen gördün ne ben gördüm Habersizce gelivermiş Ne sen duydun ne ben duydum Gönlümüze girivermiş Herkesin dilinde aşk denilen meçhul Bizi ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmenin-zamani-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Seni', 'seviyorum-seni-burhan-karatas-wosbz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne uzun ayrılıktır bu

Ne bitmez bir özlem...

Çok uzun sürdü çok...

Ararım 

Özlersem demiştin

Ey Sevgili! hiç mi özlemedin beni

Hiç mi beklemedin aramamı 

Her ayrı geçen gün  umutsuzluğa

Biraz daha itse de beni

Biraz daha uzaklaştığını hissetsem de

Çarem yok

Seviyorum Seni Bir defacık duyabilsem gel deyişini

Yalçın dağlar eğilecek önümde

Bir defacık sarsam seni

Bahar gelecek gönlüme 

Karlar yağsa da

Gönül köşküme 

Çarem yok 

SEVİYORUM SENİ', 'Ne uzun ayrılıktır bu Ne bitmez bir özlem... Çok uzun sürdü çok... Ararım  Özlersem demiştin Ey Sevgili! hiç mi özlemedin beni Hiç mi beklem...', ARRAY['Türk Edebiyatı','Şiir','Burhan Karataş']::text[], 8.5, '{"poet":"Burhan Karataş","poet_slug":"burhan-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seviyorum-seni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanasin Gonul', 'yanasin-gonul-muhammed-garip-v56hc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Odun gibi gonul, yanasin ateste

Yanmak gunahin kadar haktir sana! 

Askmis sevdaymis! Yok buna hakkin! 

Sevabin bile daha cok haktir sana! 

Lime lime olasin kizgin sularda

Parcalanasin zerrelere, yok olasin! 

Ne kadar hak ettiyse rahmeti seytan

Sevilmek de senin o kadar hakkin!', 'Odun gibi gonul, yanasin ateste Yanmak gunahin kadar haktir sana!  Askmis sevdaymis! Yok buna hakkin!  Sevabin bile daha cok haktir sana!  L...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Garip']::text[], 8.5, '{"poet":"Muhammed Garip","poet_slug":"muhammed-garip","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanasin-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniliş Açılmamış', 'yenilis-acilmamis-edip-cansever-gqm03', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Açılmamış bir şarap şişesiydim

Ki öyle kaldım

Acımı köpürtmedim

İçime sağdım

Gözyaşlarımı göstermedim

Ki sildim

Özgürlüğüm beni tutsak düşürdü 

Başaramadım

İçimde kara kara bulutlar sallandı 

Ki sallandılar

Dışarı yağamadım

Ve yenildim ve sustum', 'Açılmamış bir şarap şişesiydim Ki öyle kaldım Acımı köpürtmedim İçime sağdım Gözyaşlarımı göstermedim Ki sildim Özgürlüğüm beni tutsak düşür...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yenilis-acilmamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
