INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vera''nın Uykudan Uyanışı', 'vera-nin-uykudan-uyanisi-nazim-hikmet-ran-hl11q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İskemleler ayakta uyuyor

masa da öyle

serilmiş yatıyor sırtüstü kilim

yummuş nakışlarını

ayna uyuyor

pencerelerin sımsıkı kapalı gözleri

uyuyor sarkıtmış boşluğa bacaklarını balkon

karşı damda bacalar uyuyor

kaldırımda akasyalar da öyl
..........
..........', 'İskemleler ayakta uyuyor masa da öyle serilmiş yatıyor sırtüstü kilim yummuş nakışlarını ayna uyuyor pencerelerin sımsıkı kapalı gözleri uyu...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vera-nin-uykudan-uyanisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Kuşları Ve Karanlığın Dansı', 'gece-kuslari-ve-karanligin-dansi-deger-ulas-turan-tubha', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soğuksun ellerim 

Bir ölü kadar... 

Dizlerimin çöktüğü yerdesin, 

Sevi sözlerinin döküldüğü yer... 

Bir gençlik hikâyesindesin, 

Nerdesin? 

Çaresiz meleklerin mezarlığı 

Ve tanrının yasındasın... 

Sesler var duyuluyor; 

Fakat yok ki kulağım, 

Duyayım dünyayı... 

Cerensin aya çarpan... 

Bedenim ellerin şimdi, 

Tutsak bir özgür düşü bedenim... 

Yittiğin bir varlık, 

Bastığın yüreğim... 

Ellerim senin şimdi, 

Ellerim yüreğin... 

Çürümüş bir kar çiçeği, 

Çaldığın kemanım... 

Nice düşerden sana kalan, 

Nice ayrılıklar şarkı oldu, 

Sesimiz ses değil, 

Biliriz söylemesini... 

Gözlerin yüreğim, 

Görebildiğin hissettiğim... 

Duyumsa susmuş mu kuşlar 

Meleklerin gece dansında... 

Köpükleri denizlerden getirdim, 

Bir fırtınadan kaçmışlar... 

Karları çığdan çaldım, 

Nice kentler yıkmışlar... 

Ellerim gecenin, 

Gözlerim senin... 

Ve en güzel anında yüreğim kuşların... 

Dansları var meleklerin tutmalısın yüreğinle... 

Son bir kez olsun duymalısın, 

Olmasa da kulakların, 

Ellerinle, geceyi sarmalısın, 

Yüreğinle beni... 

Bir veda hazırlamalısın, 

Geceyi kuşlara boyarken, 

Karanlığı danslara boğmalısın, 

Ayın gölgesinde bir çift gül 

Ve tatlı bir şarap melodisi dilimde... 

Bir geçmişin kurgusu, 

Karanlığın buruk tangosu... 

Bir adam, 

Bir kadın Ve acı bir sevgi hikâyesi...', 'Soğuksun ellerim  Bir ölü kadar...  Dizlerimin çöktüğü yerdesin,  Sevi sözlerinin döküldüğü yer...  Bir gençlik hikâyesindesin,  Nerdesin?  ...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/gece-kuslari-ve-karanligin-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişin Adı', 'gecmisin-adi-deger-ulas-turan-2xj7l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte böyle arzulardan arta kalır, 

Yâre dokunduğum sitemsiz ayrılık. 

Gümüş tepsilerinde bir yazgıysa, 

Aslını inkârdadır benliğim. 

Sebepsiz savruluşlarım bilir kendini 

Bilmeli zamanın uyuklayan tümceleri 

Nedenli ayrıysa bile özünden. 

Bulur elbet akan su yatağını. 

İşte budur sevdanın hasat zamanı. 

Arta kalan dişleri kenetli bir kaçış yolu. 

Özlediğim savunmasız bir kız çocuğu suretidir... 

Kendini sınar insan masum bir yüzün hikâyesinde. 

Kaybolan hayatlar mazi çıkarır, 

Hazine sanıp kokladığım geçmişten... 

Bütün sema yıldızla dolar, 

Üşüyen kuşlar da ölmüştür zaten... 

İşte kanla yazılı geçmişim, 

İşte umut diye lekeleri sökme eylemi, 

Muhafız kimliğinde gözlerim, 

İşte ışık diye sarıldığım... 

Yazanı asarlardı geçmişe

Geçmişse bütün duvarları boş bir evin, 

Çatlamış sıvasında bir rutubet kokusu. 

Ve geleceğin anlamsız kısır döngüsü...', 'İşte böyle arzulardan arta kalır,  Yâre dokunduğum sitemsiz ayrılık.  Gümüş tepsilerinde bir yazgıysa,  Aslını inkârdadır benliğim.  Sebepsi...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gecmisin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kestin Zülfünü', 'kestin-zulfunu-deger-ulas-turan-agthb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağıtsan saçlarını, 

Rüzgâr olursun, 

Yüreğimden bir ırmak boşalır, 

Akan yaşlardan kanar yüreğim 

Ve sen sevda sararsın yüreğime... 

Ayrılıklar boğar geceyi, 

Özlemler aşkı gömer toprağa. 

Beni ellerine hasret bırakan, 

Dumanlı bir ayrılığa suç taşırım... 

Öyle bir baharı dünden yarım bırakmak, 

Ancak yakışırdı saçlarına, 

Rüzgârını saramadan, 

Saçların olurdu son kez görebildiğim... 

Sana yıktığım duvarları getirsem, 

Ellerime ateş tutuşturan çocukları, 

Birde çiçekleriyle baharı... 

Ne geceler, 

Ne gün suretini taşıyan, 

O boğuk karanlık anlatırdı... 

Anlatmaksa bu suskun ayrılık; 

Neden anlatmak, ağlamak olmasın... 

Bindiğim otobüsün camları, 

Arkanı dönüp gittiğin siluetin kalmasın... 

Bir kısa saçın ne sureti olur bilmem, 

Ama şarkılar var yarına, 

Sözleri saçından kısa… 

Yarın sevda olur, 

Saçlarına dolarsın bir bir hasretini… 

Konuşmak neyi değiştirir ki? 

Ay susmuşsa, 

Birde saçların kısalmışsa. 

Ve hep unutmuşsan karanlığa küsmeyi. 

Umut diye lekeli gömleklere sarılmışsan, 

Neyi sararsın saçların yoksa 

Rüzgâr neye çarpıp şaşırır artık, 

Ben artık... 

Sen kestin zülfünü, 

Ay karardı... 

Kaçışanlardan oldun, 

Yine umut sana küstü, 

Yine öfke bana dost... 

Bir sen sustun, 

Bir zülfün burkuldu teninde... 

Kısaldı saçların, 

Geçmiş kısaldı... 

Saçlarına bir düş kurdum, 

Düşler kısaldı...', 'Dağıtsan saçlarını,  Rüzgâr olursun,  Yüreğimden bir ırmak boşalır,  Akan yaşlardan kanar yüreğim  Ve sen sevda sararsın yüreğime...  Ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kestin-zulfunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevda', 'kara-sevda-behcet-necatigil-r2wed', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Delicesine daha dün

Kitaplara düşkündü, 

Almış yürümüş serserilikte.

Ak
..........
..........', 'Delicesine daha dün Kitaplara düşkündü,  Almış yürümüş serserilikte. Ak .......... .............', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kara-sevda-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelkensiz Gemi', 'yelkensiz-gemi-fatos-yildiz-582tn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Kal'' deseydin, kalırdım. Demedin oysa... 

Kuru bir ''Bitmesin''den başka hiçbir şey demedin. 

Öyle kuru, öyle soğuk, öyle uzaktı ki, ondaki anlam! 

Bu kadar kolay mıydı her şey, bu kadar yakın mıydık uçuruma? 

Savunmayacak mıydın sevgimizi? 

''Kal'' diye haykırmayacak mıydın ardımdan? 

Düşündüğüm bu değildi... 

Hayal ettiklerim, beklediklerim başkaydı senden, 

Mücadele beklemiştim oysa...

Yelkensiz olan gemimizi kıyıya ulaştırırız sanmıştım...

Kıyıya ulaştırırsın sanmıştım... 

Oysa, onu denizin ortasında savunmasız bırakmama göz yumdun...

Bu kadar yıpratıcı olamazsın... 

Oysa, bir anlam olmalıydı yaşadıklarımızda! 

Paylaşılan duyguların bir anlamı olmalıydı. 

Yüreğimdeki martıların bir anlamı olmalıydı. 

Beynimizdeki melodilerin, aramızdaki çekimin, 

Geçen akşamki sohbetin bir anlamı olmalıydı. 

Duygularımızın bir anlamı olmalıydı.

Yüreğimdeki tüm martıları uçurdun şimdi... 

Hangi yöne gittiler bilmiyorum, 

Geri dönerler mi bilmiyorum. 

Dünya boşaldı mı ne! 

Neden bu kadar sessizleşti birden yaşam, 

Neden artık parlamıyor yakamozlar gözlerimde? 

Neden artık rüzgar esmiyor, 

Her şey seninle mi kaldı yoksa? 

Mantığım... Mantığımı bana bırak lütfen, ona ihtiyacım var. 

Bazı şeyleri anlamak için ona ihtiyacım var! 

Evet! Ben istedim ayrılığı, çıkmaz yollara yönelen bendim, 

Kucağında bir yığın noktayla karşına çıkan bendim... 

Kahretsin! Bunu neden yaptığımı bilmiyorum. 

Ve senin buna nasıl göz yumduğunu... 

Tıpkı balkondaki akasyaları sularken, 

Fazla sudan dolayı sararacaklarını bilmediğim gibi...

Su, onun için hayat olmalıydı oysa...

Ve... Sen de benim tutunacak dalım! 

Bazı şeyler vardı aramızda biliyorsun, 

Olmaması gereken ama daima varolan. 

Farklı uçlardaydık seninle, 

Farklı mevsimleri seviyorduk, farklı zamanlarda....

Sen büyük fırtınalara vardın, bense lodostan bile ürküyordum..

Oysa başardığımız şeyler vardı her şeye rağmen, 

Daha doğrusu öyle sanıyordum... 

Binlerce yıldız arasında, 

Ayın güzelliğini gösterebilmekti tek amacım...

Yıldızları söndürmekti... Sorunları yok etmekti... 

''Bitti'' deyişim öylesine bir şeydi, öylesine, sıradan, şakacıktan... 

''Hayır'' demeliydin! 

Hatta kıyametler koparmalıydın yüreğimde, 

Hendekler açmalıydın yoluma gidemeyeyim diye. 

Sahip çıkmalıydın gözlerimdeki ay''a sevgimiz diye... 

Beni yolumdan alıkoymalıydın... 

''kal'' demeliydin... Defalarca ''kal'' demeliydin... 

Oysa, demedin... 

Belki de senin çiçeklerin çoktan solmuştu ve ben 

Akasyaları kışın yaşatmaya çalışmakla hata etmiştim...

Belki böylesi daha iyi oldu... 

''Kal'' deseydin kalırdım... Hem de seve seve kalırdım. 

Martılarla kalırdım. Yakamozlarla kalırdım. 

Demedin oysa! 

Bilir misin? 

Kaç çığlık olup yıkıldı yüreğim giderken... 

Bilir misin? 

Nasıl bir cana hasretti yüreğim, yolumdan döndürecek... 

Bilir misin? 

Nasıl zor oldu ardıma bakmadan çekip gitmek... 

''KAL'' desen kalacaktım... 

DEMEDİN OYSA! !', '''Kal'' deseydin, kalırdım. Demedin oysa...  Kuru bir ''Bitmesin''den başka hiçbir şey demedin.  Öyle kuru, öyle soğuk, öyle uzaktı ki, ondaki a...', ARRAY['Türk Edebiyatı','Şiir','Fatoş Yıldız']::text[], 8.5, '{"poet":"Fatoş Yıldız","poet_slug":"fatos-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/yelkensiz-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Kuşak', 'bizim-kusak-rustu-arseven-1cjnc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani  pek bilmem  50''nin  başlarını

gelmişim  57'' de, 

hiç  unutmam  daha  üç  yaşındaydım, 

yıl  60,  millet  şaşmış

birkaç  arkadaş  yapıverdik  ihtilali, 

asıverdik  birkaçını, 

ohhh..ortalık  sütliman..

...

Sonra  okul  yıllarım  başladı, 

alfabe  filan  takıldık, 

ilkokulu  bitirmişim, 

ortaokulun da  sonları  hani, 

Müjgan''a  pul  kolleksiyonumu  gösterdiğim  günler, 

yıl  71 , hava da  bulutlar  dolaşıyor, 

hükümete  bir muhtıra, 

birkaçını  yine  darağacına, 

ne  ulan  burası , dingonun  ahırımı, 

vaaaaamı   işi  azıttırmak! 

...

Derken  74''de  üniversiteye  gittim, 

sınıfta  her  türü  var, 

al, mor, sarı, şeffaf, yeşil 

aynı  meclis  gibi, 

Hükümetlerin  biri  gidiyor , biri geliyor

Adamlar  gazoz  alır  gibi, milletvekili satın alıyor,

Baktım  yine  kaşınıyorlar, 

80 ''de  dayanamayıp, bastım  tekmeyi, 

bizim  ip  sağlam  nasıl  olsa, 

sallandırdık  üçü beşi, 

Astık  tavan  arasına  hukuk  guguk falan,  ohhh...

....

Bir tombul  arkadaşım  vardı, gel  dedim. 

Herşey  sana  emanet, 

evelallah  iyi  çocuktur, sizden  iyi  olmasın.

hemen  bir  sistem  kurdu, iyi de  götürdü  kerata, 

neyi mi? 

.....

90'' da  60'' lıları  affettik, artık  onların  cezası  bitti.

10 yıl  sonra  70''lileri ,20 yıl  sonra  80'' lileri  affedersek, 

bu  millette  rahat  eder , herhalde..

Bana  bakın  yaramazlık  yok,  çarparım  haaa....', 'Hani  pek bilmem  50''nin  başlarını gelmişim  57'' de,  hiç  unutmam  daha  üç  yaşındaydım,  yıl  60,  millet  şaşmış birkaç  arkadaş  yapıv...', ARRAY['Türk Edebiyatı','Şiir','Rüştü Arseven']::text[], 8.5, '{"poet":"Rüştü Arseven","poet_slug":"rustu-arseven","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bizim-kusak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabalı Kız', 'arabali-kiz-rustu-arseven-vt5pv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güneş  yapışık  gökyüzüne.

deniz  oynak, 

dallar  suskun, 

yapraklar  kıpırtısız, 

deniz  oynak, 

orospu  karı  gibi...

.....

güneş  kızılca  sarı, 

saat  06.00  suları, 

bir  moloz  beygir, 

dört  tekere  beş  tahta, 

al  sana  bir  araba..., 

ister  kağıt  parçası, 

ister  bir  naylon  torba, 

yallah  arabaya , uçarcasına.., 

.....

çıplak  ayaklar, 

esmer  yanık  bir  surat, 

başında  bir  çaput  örtü, 

saçlar  küskün  hayata, 

eller  kirli, 

gözlerin  sönmüş  feri.

.....

her  kağıt ta  bin  umut, 

umut  üç  beş  kuruş, 

.....

güneş  yapışık  gökyüzüne.

deniz  oynak, 

dallar  suskun, 

yapraklar  kıpırtısız, 

deniz  oynak, 

orospu  karı  gibi...

koca  şehir  kalkma da  yeni  güne, 

sokaklar , fabrikalar  dolacak  birazdan, 

ve  birazdan  tahta  araba, 

o  esmer  minik  kız, 

kaybolacak, 

günün  aydınlığında, 

kalabalığa  yem  olacak, 

sessiz  sedasız, 

......

bir  ertesi  sabaha  kadar...,', 'güneş  yapışık  gökyüzüne. deniz  oynak,  dallar  suskun,  yapraklar  kıpırtısız,  deniz  oynak,  orospu  karı  gibi... ..... güneş  kızılca...', ARRAY['Türk Edebiyatı','Şiir','Rüştü Arseven']::text[], 8.5, '{"poet":"Rüştü Arseven","poet_slug":"rustu-arseven","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/arabali-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatırım', 'kanatirim-esref-erdem-rwxdd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kanatırım yalnızlığı gergefe tutulur ince sızılarla

Sıyrılır son parçası

Kanatırım yalnızlığı, hüzün kaplı sularda

Ellerimi  uzatırım tutan olmaz 

Donar ellerim....

Kanatırım yalnızlığı, çabalar, tüterim

İncinmenin girdabında hayal tüketirim

Layık değil di ki hiç kimse sevilmeye

Öylesine tüketilecekti sevmelerim....

Hangi kova salınmıştı hüzün kuyulara

Bıraksak nasıl başlardı bitmeye

Ki hüzün asrıdır yirmibirinci asır

Gök yalnızlıkla, kavga taşır

Taşır yalnızlık aşkta yitmeye

Bıraksak nasıl başlardı bitmeye.....

Kanatarak kadın kadınlığımı, erkek benliğimi

Öylesine tüketilecekti sevmelerim....

Bıraktım! ..nasıl başlar bitmelerim.....', 'Kanatırım yalnızlığı gergefe tutulur ince sızılarla Sıyrılır son parçası Kanatırım yalnızlığı, hüzün kaplı sularda Ellerimi  uzatırım tutan ...', ARRAY['Türk Edebiyatı','Şiir','Eşref Erdem']::text[], 8.5, '{"poet":"Eşref Erdem","poet_slug":"esref-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kanatirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarım', 'mezarim-alone-poet-w4qjl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mezarıma gelip ağlamayın

Ben orada değilim

Ben uyumuyorum

Ben binlerce esen rüzgarım

Ben karın üzerindeki gümüşi parıltıyım

Ben olgun buğday tanesindeki gün ışığıyım

Sabahın sessizliğiyle uyandığınızda

Daireler çizerek dolaşan kuşların

Hızlı kanat çırpışlarıyım

Gecelerin karanlığında parıldayan yıldızlarım

Mezarıma gelip ağlamayın

Ben orada değilim

Ben uykuda değilim', 'Mezarıma gelip ağlamayın Ben orada değilim Ben uyumuyorum Ben binlerce esen rüzgarım Ben karın üzerindeki gümüşi parıltıyım Ben olgun buğday...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mezarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yanlızlık', 'yine-yanlizlik-alone-poet-ffkor', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yanlızların çığlıklarını duyabilirmisiniz

Yada onları tanıyabilirmisiniz

Gecelerin karanlığında

Anımsayabildiniz mi? 

Hani kan çanağına dönmüş gözlerle bakan biri vardı

Hemen yanı başında

Farkına varabildin mi? O gözlerin

Tadabildin mi? Acısını

Hepsini boşver aslında

Ortak olabildin mi? Yanlızlığına

Yada sevebilodin mi? Onu doyasıya

Yoksa elveda mı dedin sonsuza kadar ona.', 'Yanlızların çığlıklarını duyabilirmisiniz Yada onları tanıyabilirmisiniz Gecelerin karanlığında Anımsayabildiniz mi?  Hani kan çanağına dönm...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-yanlizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KIrçiçeğim', 'kircicegim-alone-poet-6zkrv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani özel günler vardır ya

İnsanlar için

Ve bu günlere ait özel cünleler kurulur

Sarfedilmek üzre

İşte onlardan biri

Bu güne ve sana uyanı

''İyiki doğdun KIRÇİÇEĞİM''', 'Hani özel günler vardır ya İnsanlar için Ve bu günlere ait özel cünleler kurulur Sarfedilmek üzre İşte onlardan biri Bu güne ve sana uyanı ''...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kircicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzyılın Yalancısı', 'yuzyilin-yalancisi-deger-ulas-turan-sbwmq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ak zamanlı hayalleri, 

Bir bir tutuğu geçmişi, 

Yarım bıraktığı gerçeği, 

Koparcasına düğümlerinden 

Şimdilik ısrar edemiyordu kendine. 

Aklı başından epey yol almış tümceler 

Ak gelir anılar aksedilirse diye, 

Kontrolsüz dalışlar içinde şimdi. 

Dingin bir okyanus gibi duruyorsa da, 

İnanılmaz bir gerçeğin, 

Zaman içinde sonsuz denen her şey, 

Bir bir geçmiş yalanlarından... 

O ki sözlerinde bir dahi, 

Akıllara inat septik bir bakış, 

Sanki kendi birinden kalmış kendine, 

öz suyu, dinamiğinde gizli... 

Yabanıl yaşamların 

Susmak bilmeyen iktidarından koparıp 

Aklı zahir zayıf utanmasında, 

Saklıydı tüm gerçeği 

Çok gelişmiş bir tümce niyetinde, 

Kehanet değildi elbet yaşadığı. 

Şimdi denklemler o ki, 

Sonsuzlukta sallanır tüm sedasıyla 

Denilir ki hayat 

Onu böyle yarım yaşamıştı, 

Böyle sanılırdı okunan her hikâyede, 

Oysa kendi de unutulan gerçeklerde 

Bir bir ağlamak zamanını hiç unutmamıştı 

Bu sondu 

Ve sonlar mutlak bir başlangıç korkusu taşırdı. 

Bir sonbahar gelmese de, 

Kış dondurmasa da ellerini, 

Bahar bile sözcüklerinden yarım bıraksa 

Gönül çiçeklerini 

Geçmişine savrulan tüm yapraklar 

Geçmişte kalırdı, 

Kurumadığını sanıp kandırırdı, 

Öyle ya hayatında bir an olsun bulamadığı, 

İçine uyuyabildiği, 

Rüyaları bile yoktu kendine ait. 

Tüm yalanlarıyla, 

Bir okyanus kıyısı buldu kendine, 

Kıyılarda, 

Uçsuz bir eksen çizdiğinde, 

Korkutan tüm mahşer, 

Onu alırdı arkasına... 

Ve saraylarda yıllanan bir yalan gibi gizliydi, 

Kralına ihanet gibi, 

Tanrısına yüz çevirmiş 

Ve aldattığı tüm şeylere aldanan, 

Kendi değildi, 

Çünkü o bitmeyen dalgalarında 

Okyanusun anaforları kadar, 

Sahile vuran yalanları adına yaşadı tüm gerçeğini. 

O yok zamanların 

Bütün kesişmeleri üzerine, 

Giydiği sonsuz eteğinden sıyrılamayacaktı. 

Zafer ne adına anılırdı, 

Yuttuğu tüm gerçekleri 

Bir bir kussa da 

Hayatın tadından kopamayacaktı. 

İçtiği her yalan giydiği her okyanus, 

Üşüdüğü her yağmur, 

Saklandığı her gerçek 

Ölümse sonunda, 

O ölümüne üstlendi yalanlarını... 

Her yoldan geçilirdi, 

Her şarkı söylenirdi korkmadan...

Ama 

Bir yol vardı 

Korkutan onu 

İçinden hayat geçerdi, 

Bu yolda kaybolmuştu ya, 

Ona aldanıp kandırırdı gerçeğini, 

Şimdi yılları da katladı yüzyıllara 

Yolları arkasında unutmadı 

Yalanları bir nehir gibi keserken hayatını, 

Yıkanacağı tek nehir yoktu, 

Temizleneceği tek gerçeği gibi. 

O yüzyılların yorgunluğunda, 

Aldatılan tüm insanlık adına 

Hep yaşadı, 

Yaşarken binlerce ölüm tanıktı, 

Yaralarında binlerce ihanet, 

Binlerce tutku gözyaşlarında... 

Ve bir sona yaklaşırken 

Düşlerinde gizlediği çocukluğuna 

Sorular soruyordu, 

Nedenli, nedensiz. 

Tüm yalanlardan kaçan bir kurbandı o, 

Yaralarında yıllanmış bir ağacın 

Yaprakları sarılıydı. 

Şimdi geçmişini soran olursa, 

O, yüzyılın içinden akan bir ırmak kadar temiz, 

Geleceğine soluyan 

Bir çocuk kadar masumdu... 

Hatırası ise 

Bıraktığı yüzyıllık yalanlarıydı, 

O, geçmişinde büyük bir yalancıydı 

Tüm insanlık kadar 

Dürüsttü aslında kendine...', 'Ak zamanlı hayalleri,  Bir bir tutuğu geçmişi,  Yarım bıraktığı gerçeği,  Koparcasına düğümlerinden  Şimdilik ısrar edemiyordu kendine.  Akl...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/yuzyilin-yalancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık', 'isik-ahmet-harun-vht7y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölümün kokusu 

takip ediyor beni... 

karanlığın içinde 

delicesine koşturuyorum 

hissediyorum 

arkamdan uzatıyor kollarını 

koca bir girdap... 

ayağım takılıyor 

lanet olası bir insana 

düşüyorum... 

yaklaşıyor, 

göremiyorum... 

kokusu burnumda 

tek adımlık mesafe 

son anlarım artık 

destek arıyorum 

yok...! 

sonra, sonra 

bir ışık... 

karanlığın, ölümün 

içinden çekip alıyor 

yükseliyorum, 

gözüm kamaştı... 

nefes alamıyorum, 

ışık her yanı sarmış... 

ölüm arkada kaldı 

diye düşünüyorum. 

derken bırakıyor ellerimi 

düşüyorum... 

karanlığın içine doğru, 

o koku... 

o ölüm... 

salıverdim kendimi 

umursamadan... 

yalnız o ışığı hatırlıyorum 

ışık... 

yandı ve söndü 

bir an için... 

belki de rüyaydı... 

bıraktım ve gidiyorum.', 'ölümün kokusu  takip ediyor beni...  karanlığın içinde  delicesine koşturuyorum  hissediyorum  arkamdan uzatıyor kollarını  koca bir girdap....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Harun']::text[], 8.5, '{"poet":"Ahmet Harun","poet_slug":"ahmet-harun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/isik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-deger-ulas-turan-lzval', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman, 

Bu dünya için saymaktır... 

Bir rüya içinde, 

Irmak olup akmak... 

Suyu tanımak, 

Aktığı yatağına kadar... 

Ve kaybolmaktır, 

Varlığına aldırmadan... 

Akışkan suretime, 

Bir iz bırakmaktır... 

Gerçeği yakalamaksa; 

Bırak onu da yalanlar zapt etsin... 

Sevgiyi zamana saymak gerek, 

İçinde coşan bir kıvılcımın 

Yangınını taşırken. 

Harcadığımız onca hayali, 

Sevgiyle yormak... 

Zaman, 

Seni tanımaktır. 

Ellerine baharı sunmak, 

Çocukları bir şarkı gibi sevmektir. 

Yeniden, yeniden söylemek...', 'Zaman,  Bu dünya için saymaktır...  Bir rüya içinde,  Irmak olup akmak...  Suyu tanımak,  Aktığı yatağına kadar...  Ve kaybolmaktır,  Varlığ...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zaman-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-erol-sen-a7488', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Habersiz gidersin düşünmezsin

Seni bekleyenler meraktadır ardından

Ayna kenarına minik bir not bile bırakmadan

Gittin yeni doğacak  aya edilen yemin gibi

Umuda yelken açan yeni gün gibi

Goncaya dönen gülün doğumu gibi

Dalında açan umut çiçekleri gibi

Sevgi bahçesine akan aşıklar gibi

Birde aynalar var barışmadığım

Bakan ama görmeyen ben

Yaşayan ama göstermeyen aynalar

Kaybolmuş gitmiş bedenden yürek çarpıntıları

Bedendeki ruhun gidişi gibi

Aynalar yansıtmıyor aksini

Işık tutmak bile yetmiyor batan güne

Gün bitiyor gece geliyor amansız...

Kısır döngü anlamsız çaresiz

Gece biter gün doğar yaşama akar

Gecede yaşananlar gündüze yiter

Gündüz örter geceyi aynalar göstermez...

19.03.2002', 'Habersiz gidersin düşünmezsin Seni bekleyenler meraktadır ardından Ayna kenarına minik bir not bile bırakmadan Gittin yeni doğacak  aya edil...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aynalar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamzeler', 'gamzeler-garip-fahri-qssuy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İplik iplik dökülen yağmura inat

Ben ağlamadım

Yüreğimi acıtan sevdaya inat

Ben yakınmadım

Ama ben bir tek

Bir tek senin gamzelerine dayanamadım.', 'İplik iplik dökülen yağmura inat Ben ağlamadım Yüreğimi acıtan sevdaya inat Ben yakınmadım Ama ben bir tek Bir tek senin gamzelerine dayanam...', ARRAY['Türk Edebiyatı','Şiir','Garip Fahri']::text[], 8.5, '{"poet":"Garip Fahri","poet_slug":"garip-fahri","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gamzeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusura Bakma', 'kusura-bakma-ceyhun-yilmaz-p6txl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk defa ayağıma kadar geldin

Daha önce ağlarken görmemiştim seni

Başucumda durdun, 

Özlediğini söyledin, cevap veremedim

Bıraktığın gülleri koklayamadım

Ve sen giderken ayağa kalkıp 

Yolcu edemedim...

Kusura bakma! ...

Dün gece ölmüştüm.', 'İlk defa ayağıma kadar geldin Daha önce ağlarken görmemiştim seni Başucumda durdun,  Özlediğini söyledin, cevap veremedim Bıraktığın gülleri...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kusura-bakma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Aşkım', 'tek-askim-ender-guncelik-9dixm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün gece yine seni düşünürken

Bir an sıkıntı doldu içime

Sokağa çıkıp dolaşmak 

Dolaşırken de seni beş-on dakikalığına unutmak istedim.

Hiçbir şey almadım üzerime

Hemen o sıkıcı dört duvardan ayrıldım

Kapıya gelince düşündüm ki 

Kapı bir engel senle benim aramdaki gibi

Merdivenleri yavaş yavaş inmek istedim

Ama ne fayda 

Sanki sen vardın aşağıda ve beni bekliyordun orada

Daracık sokakta ben ve yalnızlığım vardı artık

İçimden of çekmek geldi.

Kafamı havaya kaldırdım

Ve orada da sen vardın

Yıldızlar vardı ve sokağı aydınlatan sokak lambaları

Onlar da sen gibi ışıldıyorlardı etrafına.

Az yürüdüm, yalnızlığım bozuldu

Geleni gördüm ve sanki sana benziyordu

Bir haykırış geldi içimden

Kime olduğunu bilmediğim 

Sadece “sen ne yaptın da bunları hak ettin” diyordu o ses

Ve niye böyle bir vefasıza takıldın 

Onu aklından bir türlü atamadın diyordu

On beş dakika sonra geri döndüm geldiğim yere

Sensizliğe ve umutsuzluğa

Yine de son bir umut baktım yola

İki göz vardı yolda 

Belki de sen vardın yolcusuz o araba da

Ama içinden hüzün ve keder indi

Mutluluk, yani sen yoktun

Dört duvara dönmüştüm geri

Yorganı çektim başıma kadar

Orda da rahat bırakmadın beni

Rüyalarımın baş aktörüydün 

Sabaha kadar da beni oynadın

Senle yaşayamadıklarımı yaşattın bana

Ama aklımdan bir an bile çıkmadın  

Seni düşüncelerimde yaşadım, tek aşkım.', 'Dün gece yine seni düşünürken Bir an sıkıntı doldu içime Sokağa çıkıp dolaşmak  Dolaşırken de seni beş-on dakikalığına unutmak istedim. Hiçb...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/tek-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıktım', 'biktim-ender-guncelik-qeni9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bıktım artık, 

Her gün yüzüme bakıp 

Seni seviyorum demenden.

Bıktım artık 

Sokak ortalarında

El ele yürümekten.

Bıktım artık 

Sebepsiz yere

Karşılıksız gülüşmelerimizden.

Bıktım artık

Boş yere 

Gereksiz konuşmalardan.

Bıktım artık 

Her gece gördüğüm 

Bu rüyalardan.

Bıktım artık 

Uykudan kalktığım da 

Seni bulamamaktan.

Bıktım artık

Bunları yaşamak için

Başka rüyaları beklemekten

Bıktım ben...', 'Bıktım artık,  Her gün yüzüme bakıp  Seni seviyorum demenden. Bıktım artık  Sokak ortalarında El ele yürümekten. Bıktım artık  Sebepsiz yere...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/biktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Dakika Ara', 'bes-dakika-ara-erdinc-ozdemir-bkt5l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neydi binaltıyüzkırk yılı

Ya da üçbindörtyüzaltmışiki

İşte birdenbire oluşan ansızlık 

Kaçalım 

Vardığımızda kaçacağımız yere', 'Neydi binaltıyüzkırk yılı Ya da üçbindörtyüzaltmışiki İşte birdenbire oluşan ansızlık  Kaçalım  Vardığımızda kaçacağımız yere...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Özdemir']::text[], 8.5, '{"poet":"Erdinç Özdemir","poet_slug":"erdinc-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bes-dakika-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solgun Güzel', 'solgun-guzel-aydin-karatay-j604h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba güzel

neden bukadar yorgunsun

mutsuz ve huzursuzsun 

bak ağlama ne olur 

yaşamak gibi bir kaygın mı var yoksa 

ne olursun yapma 

Merhaba güzel 

bakıyorumda gülmüyorsun 

muttlulugunu kaldırmışsın rafa

yine hüznün vuruyor camlara 

dur sakın ağlama 

yaşamak gibi bir kaygınmı var yoksa 

ne olursun yapma 

Merhaba güzel 

ne o huzursuzsun 

güzelligini soldurmuşsun 

gülümsemeni vurmuşsun bu akşam 

deniz üstüne düşmüş umutların 

yaşamak gibi bir kaygınmı var yoksa 

ne olur dur yapma 

Merhaba solgun güzel

saçlarını toplamışsın 

gözlerini silme yine ağlamışsın 

dur bakayım 

sitemlerinde silinmiş 

yitik gözlerinden 

bitkin düşmüş bedenin 

yaşamak gibi bir kaygınmı var yoksa 

ne olur dur yapma 

Merhaba solgun güzel

bu akşamda geldim 

ama bakıyorumda yoksun 

yazmayıda unutmuşsun bu sefer 

giderken birde tokanı düşürmüşsün 

peki ya dönüşün ne zaman....

Merhaba solgun güzel 

düşümde gördüm seni dün gece 

düşündümde 

galiba ağlıyordun yine 

sana bir sevgi buketi hazırlamıştım oysa 

neden terkettin 

neden bırakıpta gittin 

Bak hüzünün ıslıkları var yine kulaklarımda 

hatıralar saçılmış etrafa 

toparlanması mümkün olmayan 

yüzleri yitik resimler düşmüş yollara 

artık doğmayacak bir güneş batmakta 

yinede beklemek gibi bir his var içimde 

Merhaba 

yine gelmedi degilmi buralara 

haklısınız gelmez artık 

dönmez geri

umutlarınıda savurduysa haliç üstüne 

gelmez haklısınız 

Merhaba 

dün yine düşlerimdeydi 

ama ufak bir tebessüm vardı dudaklarının arasında 

sanırım yıldız topluyordu gecenin koynundan

beni görmedi

halbuki arkasını dönseydi

sarılacaktım boynuna 

haykıracaktım 

seni seni seviyorum diye 

Merhaba solgun güzel 

bu akşam gidiyorum 

seni bulamak için 

martıların kanadına biniyorum 

seni bulmak için bende geliyorum.........', 'Merhaba güzel neden bukadar yorgunsun mutsuz ve huzursuzsun  bak ağlama ne olur  yaşamak gibi bir kaygın mı var yoksa  ne olursun yapma  Mer...', ARRAY['Türk Edebiyatı','Şiir','Aydın Karatay']::text[], 8.5, '{"poet":"Aydın Karatay","poet_slug":"aydin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/solgun-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Ülkem', 'benim-ulkem-suat-atar-jdhxf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben Semah cekilen topraklardan gelmisim

Pirsultanin yattigi ülkeden

Kerbelanin kilic salladigi

Köroglanin kan akittigi daglardan

Analarin gözyaslari döktügü ve

Sazlarin konustugu ülkeden gelmisim.

Dokunmayin, esmeyin kanayan yarami

Yetmisyedi milletin karistigi bir yerden

Tabancalarin konustugu, bombalarin patladigi

bir ülkeden gelmisim.

Dokunmayin, esmeyin yarami

her Sigarami yaktigimda sanki ben yaniyorum.

Özledim köyümü, 

Ben cok özledim

Toprak kokan havasini

Aglayan cocuklarin sesini

Harputun havada ucusunu

Özledim dostum özledim ben köyümü.

Ben Semah cekilen topraklardan

Pirsultanin yattigi

Kerbelanin kilic salladigi

Köroglanin kan akittigi

ve Analarin gözyaslari döktügü

bir ülkeden gelmisim.

Terk ettik iste o silayi

biraktik geride herseyi

geldik namusu olmayan 

Seref bilmeyen

Günahkar bir ülkeye.

Monoton bir hayat yasamaya

Etinde, tuzunda tadi olmayan

bir yere geldik.

Hani benim köyüm nerde? 

Esen rüzgari, dogan günesi, akan suyu nerde? 

Okunan Ezan seslerini

Bayramda vurulan davul seslerini

Genc kizlarimizin halay cekisini

Dedelerimizin dügünlerde Arak icisini özledim.

Iste ben böyle bir yerden gelmisim

Semah cekilen topraklardan

Pirsultanin yattigi

Kerbelanin kilic salladigi

Köroglanin kan akittigi

Analarin gözyaslari döktügü ve

Sazlarin konustugu bir ülkeden gelmisim 

özledim ben gardas o ülkemi özledim.

04.03.2002

Suat Atar', 'Ben Semah cekilen topraklardan gelmisim Pirsultanin yattigi ülkeden Kerbelanin kilic salladigi Köroglanin kan akittigi daglardan Analarin gö...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/benim-ulkem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-caner-avci-ydc01', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Toprak adımlarıma hasretse 

Çiçekler ellerime hasretse

Ve kelebekler gurbette beklerse

Bu sabah güneş doğmuşsa neyleyim.

Benim  şehirim beton giymişse

Dağlarıı görmeme apartmanlar engelse

Yeşiller plangalı, kuşların kanatsızsa

Bu sabah güneş doğmuşsa neyleyim.', 'Toprak adımlarıma hasretse  Çiçekler ellerime hasretse Ve kelebekler gurbette beklerse Bu sabah güneş doğmuşsa neyleyim. Benim  şehirim beto...', ARRAY['Türk Edebiyatı','Şiir','Caner Avcı']::text[], 8.5, '{"poet":"Caner Avcı","poet_slug":"caner-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/istanbul-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatılmaz Şeyler Vardır..', 'anlatilmaz-seyler-vardir-mine-aktas-ozkamali-91rg8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlatılmaz şeyler vardır hani... 

Yaşanır da ifade edecek kelime bulunmaz. 

Sanki kelimelere döksek basitleşecek gibi....

öyle yüklüdürler ki 

birkaç harfin yan yana dizilimiyle 

ortaya çıkacak hiçbir kelime

anlatamaz. onları

Öyle zordur ki onları ifade edebilmek. 

Bir annenin çocuğunu ilk kucağına aldığında 

neler hissettiği gibidir... 

Bir gencin 

ilk aşkı tatması gibidir... 

martı çığlıklarının verdiği zevk gibidir... 

Uzaklara çok uzaklara gidenin ardından 

bakakaldığında yaşanılanlar gibidir...

biten bir aşk, doğan güneş gibidir... 

Öyle çoktur ki anlatılamaz şeyler... 

Belki o nedenle 

anlamakta güçlük çekeriz

karşımızdakini 

O da bulamaz çünkü

anlatılmaz şeyleri anlatacak kelimeleri...

Mutlu olunması gereken zamanlarda üzüntülü olabiliriz... 

Kim bilir kaç kişi bizim yerimizde olmak ister de

biz yerimizden memnun değiliz.

Kim bilir biz kimlerin yerinde olmak isteriz de 

onlar da memnun değillerdir? ... 

Çelişkiler... 

İnsanın kelime haznesini azaltan büyük neden. 

Yüreğin dümeni bozulur da 

ne tarafa doğru gideceğini bilmez.... 

yürek yorgun düşer de gene mücadele eder... 

pusulası olsa bile 

dümeni bozulmuştur ya yüreğin

yapılacak çok şey de yoktur aslında. 

Bütün dertlerin sizi beklediğini düşünürsünüz

dünya nefes bile alamayacağınız kadar küçülmüştür de 

siz şehirler arası otobüslerin rahatsız koltuklarında 

anlık rahatlamaları özlersiniz... 

Hani küçük bir pozisyon değişikliği, 

o bir saniyelik rahatlama

 çift kişilik karyolanızda tek başına yatmanızdan daha rahat gelir ya 

onları özlersiniz.... 

ama anlatamazsınız... 

Anlatılmaz şeyler vardı hani... 

geçmişten sizi ziyarete gelen müzik gibidir... 

Gözleriniz bir yere dalar 

ve saatlerce öyle kalırsınız da fark etmezsiniz... 

Yıllar öncesindeki müzik sizi esir almıştır çünkü... 

esirliğin içindeki özgürlük gibi 

anlatılmaz şeyler vardır... 

Anılar müzik tarafından sizi esir alır ama 

siz bundan üzüntü değil de 

mutluluk duyarsınız. 

Ta ki müzik sonlanana 

siz şimdiye dönene kadar, 

İşte o anda yaşananlar anlatılamaz kelimelerle. 

Anlatılmaya çalışılsa ihanet olur geçmişe.... 

Anlatılmaz şeyler vardır hani... 

Yaşanır da ifade edecek kelime bulunmaz. 

Sanki kelimelere döksek basitleşecek gibi....

öyle yüklüdürler ki 

birkaç harfin yan yana dizilimiyle 

ortaya çıkacak hiçbir kelime

anlatamaz. onları', 'Anlatılmaz şeyler vardır hani...  Yaşanır da ifade edecek kelime bulunmaz.  Sanki kelimelere döksek basitleşecek gibi.... öyle yüklüdürler k...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/anlatilmaz-seyler-vardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Olabilmek', 'kus-olabilmek-mine-aktas-ozkamali-4mjjk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herkesin hayalleri içindedir belki de

Kuş olabilmek.

Kuşlar kadar özgür, 

Kuşlar kadar hafif

Kuşlar kadar kıskanılası

Kanatlarının götürebileceği yerdir yuvası

Kanatları tek sermayesi

Çoğu sevmez kısıtlanmayı

Çirkin kavgalarla da ilgileri yoktur...

Karamsarlık dağlarından, 

Olabildiğince uzakta kanat çırparlar

Doğanın küçük oyunlarına yenik düşerler belki

Doğanın acımasızlığını yaşarlar

Ama, 

Asla birbirlerine zarar vermezler

Zorluklar karşısında iki kanat, 

Olur bin kanat

Onların geniş zamanları da yoktur

Biz insanlar gibi

Doya doya, çığlık çığlığa geçirirler ona nedenle

Onlara armağan edilmiş hayıtı...

Herkesin hayalleri içinde kuş olabilmek vardır

Kuşlar kadar kıskanılası.....', 'Herkesin hayalleri içindedir belki de Kuş olabilmek. Kuşlar kadar özgür,  Kuşlar kadar hafif Kuşlar kadar kıskanılası Kanatlarının götürebil...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kus-olabilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk', 'cocukluk-mine-aktas-ozkamali-9fwdo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çocukluğumdan arta kaldı

bu içimdeki coşkular

çocukluğumda yaşadı

şimdi hatırlamakta bile 

güçlük çektiğim o güzel duygular

yokluk ne güzel şeydi...

tadı ne güzeldi

anneme anneler gününde günlerce para biriktirerek aldığım

bir mücevher değerini taşıyan 

sıradan şampuanı hediye etmek....

ve annemin o şampuanı

aylarca kullanmayışı, 

yatak odasını bir biblo gibi süsleyişi

hele bayramlar....

günler öncesinde

beş metre kare halının üzerinde

“yaşasın bayram geliyor” diye

dört dönmelerim

dilimdeki mutluluk şarkıları....

yüreğimdeki büyüme umutları

Ne güzeldi sabah kahvelerindeki sohbetler

Sebahat hanım teyzenin en taze dedikoduları

Fatma hanım teyzenin oğlunun yaramazlıkları

Öyle merak ederdim ki

“sus kız çocuk var” diye neden dediklerini

kikir kikir neden güldüklerini

Ne kadar çok imrenirdim

Onların oldukları yaşlara

Gene de 

Hiçbir zaman yalnız kalmadım

Gökyüzündeki güneş gibi

Onların yanında

Ne çok sevinirdim

Annemin cam kenarındaki menekşeleri açtığında

çocukluğumdan arta kaldı

bu içimdeki coşkular

çocukluğumda yaşadı

şimdi hatırlamakta bile 

güçlük çektiğim o güzel duygular

çok zor sanırım artık

bu duyguları yaşayıp

geçmişe dönmek....

hala açıyor annemim cam kenarındaki menekşeleri

ama eskisi değil içimdeki sevinçleri

artık “sus kız çocuk var” demiyorlar

ben özlerken çocukluğumu

artık imrenmiyorum onların oldukları yaşlara

ben özlem duyarken çocukluğuma

onlar imreniyor bulunduğum yaşa...', 'çocukluğumdan arta kaldı bu içimdeki coşkular çocukluğumda yaşadı şimdi hatırlamakta bile  güçlük çektiğim o güzel duygular yokluk ne güzel ...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/cocukluk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-mine-aktas-ozkamali-0guga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'pencereden giren rüzgar ürpertir hani

hani eski bir şarkı seni alır da

götürür ya çok uzaklara

hiç gitmediğin, hiç görmediğin yerlere gidersin ya hani

ve bir ağacın gölgesinde dinlenmenin huzurunu

bu huzuru yürekten paylaşmayı

paylaşırken de çoğalmayı 

özlersin ya hani

ben de özlüyorum

çocukluğumun vurdumduymazlığını......

22.06.01', 'pencereden giren rüzgar ürpertir hani hani eski bir şarkı seni alır da götürür ya çok uzaklara hiç gitmediğin, hiç görmediğin yerlere giders...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozluyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-ender-guncelik-zc1xj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde sen vardın bu gece 

İsmini bilmediğim yıldızlar

Yüzünü çizmişti gökyüzüne 

En parlakları gözlerini oluşturuyordu

O sırada yıldız kaydı 

Gülüşündeki güzelliği hatırlattı

Sana gelmek istiyordum, 

Sana uzanabilmek istiyordum artık

Gökyüzüne doğru uçtum o gece 

Sana yetişecekken

Aşağıda iki yanardağ patladı

Baktığın yeri yakan gözlerinde ki gibi

Işıltı saçtı yer yüzüne

O ince burun 

Bir dağı oluşturuyordu

Ve göz yaşların denizleri doldurmuştu.

En güzel ormanlıklar 

Senin ince kaşlarında saklıydı

O zaman anladım ki, 

Dünyanın anlamı sendin 

Benim için sevdiğim.', 'Gökyüzünde sen vardın bu gece  İsmini bilmediğim yıldızlar Yüzünü çizmişti gökyüzüne  En parlakları gözlerini oluşturuyordu O sırada yıldız ...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sensin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-ender-guncelik-zm1y7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En son ne zaman konuştum bile hatırlamıyorum

Geçen ay mı? Yok yok iki ay önce olmalı, 

Ama sen hala konuşmamakta ısrarlısın benimle

Ne olur bir merhaba desen 

Ve güzel bir gülücük eklesen kelimelerine 

Tıpkı eskisi gibi

Hani hiçbir şeyi açıklamadığım eski günlerdeki gibi

Masumca hiçbir şey bilmeden 

Olan biteni anlatsan bana 

Her olaya eskisi gibi gülsek

Göz göze gelince dakikalarca donup kalsak olduğumuz yerde 

Ve arkadaşların dedikodularını yapsak 

Benim içimde kalmayan ümit taneleri filizlenmeye başlasa 

Yine sana sevdiğimi söyleyebilsem

Ne olur konuş benimle

Hiç olmazsa bir merhaba, bir merhaba de...', 'En son ne zaman konuştum bile hatırlamıyorum Geçen ay mı? Yok yok iki ay önce olmalı,  Ama sen hala konuşmamakta ısrarlısın benimle Ne olur ...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/merhaba-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-mine-aktas-ozkamali-f12jd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlamak zor anlaşılmak kadar

Tarihin gizli kalmış sayfaları gibi

Ebediyete gömmek

Anlamayı, anlaşılmayı

Cesaret edip de çıkaramamak oradan

Silememek akan gözyaşlarını

Dindirememek sancı çeken yüreğin acısını

Dargın, dalgın bakışlarla 

Kılı kırk yaran düşüncelerle

Yüzleşememek

Mücadele edememek...

Anlaşılmak zor, 

Anlamak, anlaşılmak kadar', 'Anlamak zor anlaşılmak kadar Tarihin gizli kalmış sayfaları gibi Ebediyete gömmek Anlamayı, anlaşılmayı Cesaret edip de çıkaramamak oradan S...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zor-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Zaman Oldu', 'uzun-zaman-oldu-mine-aktas-ozkamali-i8a2p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzun zaman oldu

Biriktirmeye başlayalı

Avucumdaki ışığı

Yüreğimdeki acıyı

Kum saati misali

Tane tane birikti

Ellerimdeki ışık

Yüreğimdeki acı

Hiç kimse anlamadı

Bakarken onlar bana

Çıplak gözleriyle

Oysa benim yüreğim kanardı

Her damlada

Yüreğimdeki acıyı sulardı...

Uzun zaman oldu

Biriktirmeye başlayalı

Avucumdaki ışığı

Yüreğimdeki acıyı', 'Uzun zaman oldu Biriktirmeye başlayalı Avucumdaki ışığı Yüreğimdeki acıyı Kum saati misali Tane tane birikti Ellerimdeki ışık Yüreğimdeki ac...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uzun-zaman-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyrum', 'seni-seviyrum-sedat-cakir-6xqd0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum

Sus pus içten içe

Çiğ yağmurlarıyla ıslanıyor

                    sessizliğim sabaha karşı

Uykusuz bir akşam daha bitiyor seni düşünmekle

Bir bulut gibi sızıyorsun gözlerime

Dünyaya kırgınlığım seninle

                    ıslak bir hayale varıyor

Seni seviyorum

Dünün iyi niyetli sevmelerine

                    yargısız infazlar yaparak

Ve unutarak eski bir sevgiliye verdiğim sözleri

Seni seviyorum

Bugüne güzel bir anlam

                    yarına benim olmayan bir avuntu gibi

Her akşam yüreğimin namlusuna sürüp imkansızlığını

Çaresiz sevmelerime intiharlar planlasam da

Faydasız...

Seni seviyorum

Hiç olmayacağının bilincine vararak...

Seni yağmur gibi, seni bulut gibi

Seni sırılsıklam bir nisan gibi seviyorum

ve ben hep susuyorum seni sevdiğimi 

     ve ben yine sana susuyorum...

Sapasavruk bir aşk düşüyor gözlerime 

                    esmer bakışlarından

Mitolojik bir tanrıçanın gizemli güzelliği var sende

ve çölde yağmur imkansızlığı...

Yüzünde ki çocukluğa

                    biraz kadınlık bulaşmış dudaklarından

Üzerimde ki kara örtüleri bir bir kaldırıyorsun

                    nasıl yapıyorsan

Beni bir damla su gibi buharlaştırıp

                    bir bulut gibi kendine çekiyorsun...

Seni seviyorum

İnceden inceye bir sen imkansızlığı sızlıyor şimdi içimde

               

                                                                     İstanbul  2002', 'Seni seviyorum Sus pus içten içe Çiğ yağmurlarıyla ıslanıyor                     sessizliğim sabaha karşı Uykusuz bir akşam daha bitiyor sen...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/seni-seviyrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın Değişiverir', 'ansizin-degisiverir-mine-aktas-ozkamali-moioq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ansızın değişiverir insanın hayatı

Garip gelir ilk başta, uyum sağlayamazsın

Oyun sanırsın ama, rolünü de bulamazsın

Rasgele dalıverirsin

Tam ortasındasındır

Sahne denen yalan dünyanın

Aykırılıklar görürsün

Elbette şaşırırsın, alışık değilsindir

Aldanırsın...

Kime sığınsan, kimden medet umsan 

Lanetliymiş gibi aşağılanırsın...

Merhamet yoktur

Ne yaparsan yap

Daima ve özellikle hiç ummadığın anlarda

Yalanla, ikiyüzlülükle

Sarsılırsın

Ansızın değişiverir hayatın

Tam ortasında bulursun kendini sahte dünyanın

Ezilirsin, daha ezmek-ezilmek nedir bilmeden

Dimdik durmaya çalışırsın da her şeye rağmen

Gücün tükenir, 

Kurtlar sofrasında olduğunu çok geç anlarsın...

Canın yanar

İncinirsin, incindikçe

Göremediklerini görmeye başlarsın

Mesafe azalmaya başlar, değişen hayatınla senin aranda

Ne yapacağını bilir artık şaşırmazsın

Bırakırsın insanlığa dair ne varsa

Tam ortasındasındır işte sahte dünyanın

Geriye dönüp hatırlamaya bile çalışmazsın

Madem dersin kurtlar sofrasının kuralı bu

Madem dersin bir oyunun küçük parçalarıyız biz

Ezmeliyiz

Yenmeliyiz

İnsanlığa dair ne varsa gömmeliyiz...

İşte ansızını değişiverir insanın hayatı

Garip gelir ilk başta uyum sağlayamazsın

Ama öyle bir oyun oynar ki hayat sana

Değişiveren hayatını hiç hatırlamazsın....', 'Ansızın değişiverir insanın hayatı Garip gelir ilk başta, uyum sağlayamazsın Oyun sanırsın ama, rolünü de bulamazsın Rasgele dalıverirsin Ta...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ansizin-degisiverir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaplama', 'kaplama-mine-aktas-ozkamali-gcagp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dışı kaplanmış

içi açmak yerine 

güzel bir hediye paketinin içinden çıkan

kötü bir sürpriz gibi

içi olduğu gibi açmak yerine

dışı kaplanmış sevgilerin

üstü kabuk bağlamış hayallerin

olduğu gibi değil olmak istediğini

gösterirken sevilene....

yaşanır hayal kırıklığı

en acı biçimde

sonradan anlaşılır ki

dışı kaplanmış

içi açmak yerine.....', 'dışı kaplanmış içi açmak yerine  güzel bir hediye paketinin içinden çıkan kötü bir sürpriz gibi içi olduğu gibi açmak yerine dışı kaplanmış ...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaplama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Aşık oldum', 'bugun-asik-oldum-huseyin-cayikli-9ykp1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kolay degildi sevmek

yeniden aşık olmak kolay değildi...

bugun anladım da ben bir kadını seviyorum...

bir aşk bitmişti ve yeni bir aşk için

sipariş çoktan verilmişti...

Akdenizli bir kız

karsımda

saçları desen o saçları

işte

sevebilmek 

yeniden sevebilmek...

bu olmalıydı

seviyordum 

yüzü solgun yaralı

içinde yılların biriktirdiği acı

akdenizin kızı seni sevebildim...', 'kolay degildi sevmek yeniden aşık olmak kolay değildi... bugun anladım da ben bir kadını seviyorum... bir aşk bitmişti ve yeni bir aşk için ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bugun-asik-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçaklanmış Özlemler', 'sacaklanmis-ozlemler-mine-aktas-ozkamali-7baiv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçaklanmış zamanlardayım şimdi

Suskunluğumdur saçakları eriten

Özlemlerimdir sessizce oradan akıp giden...

Dilimde yok uzun zamandır

Fırtınalı türküler

Yüreğim kapatmış kapılarını

Kilit de vurmuş üstüne

Beklediğim sakince gülümsemeler

Benim yerim artık saçaklanmış zamanlardadır

Saçaklanmış zamanlardaki o özleyişler....', 'Saçaklanmış zamanlardayım şimdi Suskunluğumdur saçakları eriten Özlemlerimdir sessizce oradan akıp giden... Dilimde yok uzun zamandır Fırtın...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sacaklanmis-ozlemler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-mine-aktas-ozkamali-gqzk7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eski bir aldanıştır mutluluk

Üzüntünün peşinden hep beklenen

Can benzdiğinde

Tanrı’dan dilenen 

Tükenmeye yüz tutmuş

Bir çiçek gibi 

Onu bulduğumuzu sandığımızda 

Ve

Avucumuzu sımsıkı kapadığımızda

Darmadadığın olan

Eski bir aldanıştır mutluluk

Ama hiç vazgeçilmez bu aldanıştan

Ölüm gelene kadar

Koşulur, yorulunmadan peşinden

Hayat, işte bu eski aldanışın 

Durmaksızın aranışı değil midir?', 'Eski bir aldanıştır mutluluk Üzüntünün peşinden hep beklenen Can benzdiğinde Tanrı’dan dilenen  Tükenmeye yüz tutmuş Bir çiçek gibi  Onu bul...', ARRAY['Türk Edebiyatı','Şiir','Mine Aktaş Özkamalı']::text[], 8.5, '{"poet":"Mine Aktaş Özkamalı","poet_slug":"mine-aktas-ozkamali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutluluk-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Düşün', 'beni-dusun-sedat-cakir-ary9z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni toprak gibi düşün

yağmur gibi sev

Beni deniz gibi düşün

rüzgar gibi sev

Beni mıtluluk gibi düşün

hüzün gibi sev

Beni yaz gibi düşün

kış gibi sev

Beni sen gibi düşün 

ben gibi sev

                     Tekirdağ 2001', 'Beni toprak gibi düşün yağmur gibi sev Beni deniz gibi düşün rüzgar gibi sev Beni mıtluluk gibi düşün hüzün gibi sev Beni yaz gibi düşün kış...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beni-dusun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-sedat-cakir-mxa9v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevmek

Bir mavzer patlaması gibi gürültülü

ve dağılan öfkemden sonraki 

sessizlik kadar hüzünlü...

Bir bulutun beni

tepeden tırnağa sırılsıklam yapması gibi

Yada bütün şimşeklerini

üzerime boşaltması gibi bir şey.....

Fakat asla aynı değil.....

                           Tekirdağ 2001', 'Seni sevmek Bir mavzer patlaması gibi gürültülü ve dağılan öfkemden sonraki  sessizlik kadar hüzünlü... Bir bulutun beni tepeden tırnağa sır...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-sevmek-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Yarısı', 'askin-yarisi-sedat-cakir-566jp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her akşam bir meyhane

Tutturmuşuz bir eğlence

İçiyoruz öylesine

Yakışır bize...

Yollarda adım adım

Kadehleri sıraladım

Dertleri ayıkladım

Yakışır bize...

Dün akşam şişe şişe

Yar aşkını sayıkladım

Gel artık çok bekletme

Kaldım burda virane

Her akşam bir meyhane

Tutturmuşuz bir eğlence

Geziyoruz öylesine

Yakışır bize...

Kadehler, altın başak

Yar saçlarının karası

Özledim gel nolursun

Oldun yürek yarası

Tadı yok bu gezmelerin

Adı yok bu sevmelerin

Nerdesin ay''ım güneş''im

Bulup bulup yitirdiğim

Tutturmuşuz bir sıkıntı

Her akşam aynı yıkıntı

Gözyaşlarım kan kızılı

Ağlamak yakışmaz bana ama

Budur aşkın yarısı..

                    istanbul 2002', 'Her akşam bir meyhane Tutturmuşuz bir eğlence İçiyoruz öylesine Yakışır bize... Yollarda adım adım Kadehleri sıraladım Dertleri ayıkladım Ya...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/askin-yarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimde Bir New York Cafesinde Seninle', 'hayalimde-bir-new-york-cafesinde-seninle-selin-samanoglu-48vxs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hele birde yagmurlu bir gunse... 

Eski bir yer olmasi sart

Kucuk kare kare camli, boydan boya koyu renk tahtadan kapilari ve  camlari olmasi lazim, 

Albinoninin Adagio muzigi calsin 

Ruhuma hitab eden muzik, beni derinliklere indiren, 

Uzaklara goturen muzik..., 

Herhangi bir klasik muzik olsada olur, 

Eski bir tahta ahsap bina kokusu, eski taslar kokusu...

Icerde bir kedi miskin miskin uyumus, 

Degisik degisik, eski, antika, koyu koltuklar, masalar, 

Up uzun cok yuksek duvarlar, 

Karanlik, koyu boyanmis duvarlar, 

Antika saydam camli los isikli avizeleri olsun, 

Her masada saydam camin icinde bordo mumlar olsun, Beyazda olsa olur, 

Saydam camin icinde  mumun alevi yavas yavas dans etsin, Kalbimi isitsin... 

Iyce cilasi cikmis iri iri parkeleri olsun, yururken ciyaklasin, 

Eski antika, lekeli, guzel cerceveli aynalari olsun, kocaman, ufak, degisik sekilli...

Eski eski cerceveler icinde eski eski yagli boya resimleri olsun... 

New York''ta, yanimda olsan, saatlerce boyle bir cafe''de otursak, 

Disarisi yagmurlu, karanlik, 

Saat 4 filan, 

Yagmurdan hizli hizli yuruyenler, is adamlari, is kadinlari, 

Giri yollar, giri gokyuzu, 

Sen ve ben bu cafede yudum yudum demli, bergamotlu bir cay icsek, 

Zamani durdursak...

Ben kahvede cok severim... Cappuccino, veya  regular American coffee... 

Los isiklar, los duvarlar, los ruhlar, 

Biraz bir kitap okusak, 

Biraz arada bir bakissak, 

Biraz konussak, 

Biraz dizlerimiz birbirine carpsa, 

Sonra yavas yavas bir bacagimi bir bacaginin ustune atsam, 

Sonra uzun uzun konussak, 

Sana dusuncelerimi soylesem, 

Kendimi tanitsam, 

Benim icimi dinleyebilsen... 

New York, Mart 19,2002', 'Hele birde yagmurlu bir gunse...  Eski bir yer olmasi sart Kucuk kare kare camli, boydan boya koyu renk tahtadan kapilari ve  camlari olmasi...', ARRAY['Türk Edebiyatı','Şiir','Selin Samanoğlu']::text[], 8.5, '{"poet":"Selin Samanoğlu","poet_slug":"selin-samanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/hayalimde-bir-new-york-cafesinde-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-sedat-cakir-r94qq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Leyla sen miydin

Dün gece bu sokaklardan

bağıra çağıra geçen kadın? 

Sen miydin Leyla

O yaralı şarkıyı söyleyen, 

Yılların özlemini yeniden ateşleyen? 

Söyle Leyla, sen miydin? 

Sarı sonbaharlara

mavi mutluluklar yükleyen

Sen miydin Leyla? 

Gece yarıları uykularımda

rüyalarıma

içli bir türkü gibi yerleşen

O ışık perisi sen miydin Leyla

Penceremin önünde

rüzgarla dans eden? 

Leyla sen miydin

Sevdiğim kadınlardan

bir küçük iz getiren? 

Sen mi yolladın

kapımı çalıp kaçan çocuğu? 

Leyla sen miydin

Dün gece bu sokaklardan 

bağıra çağıra geçen kadın? 

Gözlerimde yangın çıkaran, 

O yaralı şarkıyla ağlatan

Söyle Leyla sen miydin? 

Bana o bildik efkarı hatırlatan...

                          Denizli 2001', 'Leyla sen miydin Dün gece bu sokaklardan bağıra çağıra geçen kadın?  Sen miydin Leyla O yaralı şarkıyı söyleyen,  Yılların özlemini yeniden ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/leyla-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksilen Yanım', 'eksilen-yanim-sedat-cakir-9ined', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlar yıkılır, güneş doğar belki

Sevdiğin bir gün geri döner

Güller yeniden açar belki

Hayal değil düşlediğin bir umuttur

Dün değil beklediğin yarındır

Uzat ellerini doğan güne karşı

Ve dağılsın bulutlar üzerinden

Yıkılsın dağlar ayaklarının dibine

Güneş yine parlatsın saçlarını

buğday başağı

Hayal değil düşlediğin bir umuttur

Dün değil beklediğin yarındır

Ağlama artık yeter, sil gözyaşını

Soluduğun bir kara sevdadır

Ölümün koynunda bir nefes değil

Dağılır giderim şafaktan şafağa

Damarlarımdan kan eksilir

Gözyaşın sicim gibi yanaklarımda

Ağlama artık, yeter ağlama...

Bağır bağır bağırdım bütün bir zemheri

Kimse duymaz oldu sesimi

Karlar altında kaldı umutlarım

Sen ağladın ve eksildi hep bir yanım

Ağlama artık sil gözyaşını

Soluduğun bir kara sevdadır

Ölümün koynunda bir nefes değil

Hayal değil düşlediğin bir umuttur

Dün değil beklediğin yarındır

                           Gökçeada 2000', 'Dağlar yıkılır, güneş doğar belki Sevdiğin bir gün geri döner Güller yeniden açar belki Hayal değil düşlediğin bir umuttur Dün değil bekledi...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eksilen-yanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Gidiyorum', 'i-ste-gidiyorum-sedat-cakir-wekow', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte gidiyorum

yalnızlığımı atıp ömrümün çöp tenekesine

Bütün yıldızları doldurdum ceplerime

Size yıldızsız geceler bırakıyorum

Adımı unutup gidiyorum

yepyeni denizler keşfetmeye

İçimde yeşil umutlar yeşertip

güzel yarınlar ezberliyorum

Çocuklara devrediyorum

karşılıksız sevmelerimi

Ve ahlaksızlığını ömrümün 

yol üstü fahişelerine

Aşkımı o imkansız esmere bırakıp 

gidiyorum

Birazdan kalkacak son otobüs

birazdan yeni başlangıçlara doğru

Zaman hızla tükeniyor

ve koyunlaşıyor insanların çoğu

İşte gidiyorum

Başlıyor yaşlı adamın çocukluğu

ve her zaman olduğu gibi

hiç elvedasız gidiyorum...

                           Tekirdağ 2001', 'İşte gidiyorum yalnızlığımı atıp ömrümün çöp tenekesine Bütün yıldızları doldurdum ceplerime Size yıldızsız geceler bırakıyorum Adımı unutup...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iste-gidiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstediğin Oldu mu', 'i-stedigin-oldu-mu-ugur-oguz-sahin-bwehl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bırak anıları çoğaltmayı  kapat bu yarayı

Taşıma bu sevdayı vazgeç

Yoruldum damarlarımda taşımaktan seni

İki yoldan birini seç

Ne bana yaşat kederi ne sen çek elemi

Düş yakamdan bırak bana beni

Yalan gözlerle ağlama bana

Sen silah gözyaşlarınla  bulursun yakacak birini

Bana mı yansam  sana mı üzülsem

Yoksa kaderime mi kızsam

Kasvetli gecelerin sabahında

Yorgun düşüp seni unutsam

Unutsam seni ebediyen

Bir daha rüyalarıma bile sokmasam

Sana gökyüzünden  güneşi indirsem

Yıldızları ayaklarına sersem  yaranamam

Puslu gecelerin boşalttığı çığ gibi

Dilinden düşürmedin yalanı nefreti

Masum şehla bakışların bitti

Geride hatıralar kaldı  dizi dizi

Sevmeye çalıştım seni adam gibi

Seninki yalan  yalanmış  söylerken sevdiğini

Sevgimle vurdun beni  hedef tam on iki

İstediğin...istediğin oldu mu şimdi', 'Bırak anıları çoğaltmayı  kapat bu yarayı Taşıma bu sevdayı vazgeç Yoruldum damarlarımda taşımaktan seni İki yoldan birini seç Ne bana yaşat...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istedigin-oldu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farketmez', 'farketmez-sadettin-altintas-1e8u6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Farketmez sevdiğim sensiz olunca

Gün doğmuş gün batmış inan farketmez

Kalbime diktiğin GÜLüm solarsa

GÜL bahçem de olsa  inan karetmez

Ufkumda güneşler tutsak da kalsa

Hazanda bahçemde GÜller de açsa

Dünyanın serveti benim de olsa

Yanımda sen yoksan inan karetmez

Güldürmez yüzümü senden başkası

Nasıl sevsin kalbim bir başkasını

Göklere yazsalar  benim adımı

Yanımda sen yoksan inan karetmez

Bu can senin zaten istersen güldür

İster kölem deyip Fizana sürdür 

İster  suçsuz yere idama götür

KALBİMDE SEN VARKEN inan farketmez', 'Farketmez sevdiğim sensiz olunca Gün doğmuş gün batmış inan farketmez Kalbime diktiğin GÜLüm solarsa GÜL bahçem de olsa  inan karetmez Ufkum...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/farketmez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mümkün mü', 'mumkun-mu-sadettin-altintas-nkbpt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yemyeşil gözlerin o sarı saçın

görüp de yanmamak mümkün mü seni

bağlamaya yeter bir tek bakışın

sevip de ölmemek mümkün mü seni

aşkımı reddedip kovsan da beni

kolayca unutmak mümkün mü seni

beni yok sayıp sevsen elleri

kalbimden çıkarmak mümkün mü seni

kalbimi eline vermem hata mı

her yüzde görmemem mümkün mü seni

ecel bile olsan alsan canımı

yine de sevmemek mümkün mü seni', 'yemyeşil gözlerin o sarı saçın görüp de yanmamak mümkün mü seni bağlamaya yeter bir tek bakışın sevip de ölmemek mümkün mü seni aşkımı redde...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mumkun-mu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma', 'sanma-sadettin-altintas-5725c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sanma unutarak senli günleri

yeni sevdalara yelken açmışım

içinde sen yokken tek bir nefesi

şu sefil bedene sanma almışım 

umrun olmasa da artık varlığım

gitgide büyüyor yürekte aşkın

ardından kapanan gönül kapımı

senden başkasına sanma açmışım', 'sanma unutarak senli günleri yeni sevdalara yelken açmışım içinde sen yokken tek bir nefesi şu sefil bedene sanma almışım  umrun olmasa da a...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sanma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebi Sensin', 'sebebi-sensin-sadettin-altintas-ugqie', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kar düşmüşse gülüm gönül bahçeme

sebebi bir tek sen tek sensin inan

güneş doğmuyorsa artık geceme

sebebi bir tek sen tek sensin inan

suçlu sen olsan da biten sevdada

cezayı çekmeyi bıraktın bana 

sitem ediyorsam şimdi ben sana 

sebebi bir tek sen tek sensin inan', 'kar düşmüşse gülüm gönül bahçeme sebebi bir tek sen tek sensin inan güneş doğmuyorsa artık geceme sebebi bir tek sen tek sensin inan suçlu s...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sebebi-sensin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce', 'once-sadettin-altintas-iynnr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaktığın bu ateş söner mi bilmem

bedenim toğrağa girmeden önce

şu kara talihim döner mi bilmem

saçıma beyazlar dolmadan önce

senden başka ismi anar mı dilim

sensiz doğan günü görür mü gözüm

senden başkasını sever mi kalbim

ecelim kapıma gelmeden önce

bir defa gerçekten güler mi yüzüm

huzura erer mi varlığım özüm

uykuyu tanır mı kirpiğim gözüm

sen beni ben gibi sevmeden önce', 'yaktığın bu ateş söner mi bilmem bedenim toğrağa girmeden önce şu kara talihim döner mi bilmem saçıma beyazlar dolmadan önce senden başka is...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/once-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eş Gibi', 'es-gibi-sadettin-altintas-ujve0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'doğ gönül ufkuma bir güneş gibi

kalbimde varolan yara kapansın

yakın ol kalbime sanki eş gibi

sen yokken bedenim nefes almasın

hasretim sevdiğim bedende cansın

her zaman dilimde sözümde varsın

baktığım her yerde gözümde varsın

sen yokken geceme güneş doğmasın', 'doğ gönül ufkuma bir güneş gibi kalbimde varolan yara kapansın yakın ol kalbime sanki eş gibi sen yokken bedenim nefes almasın hasretim sevd...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/es-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük', 'dortluk-sadettin-altintas-oa0hc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman gözgöze gelsek seninle 

Bakışların öfke hep kan kusuyor

Ne zaman bir nergis bir gül koklasam

İnan ki sevdiğim tek sen kokuyor', 'Ne zaman gözgöze gelsek seninle  Bakışların öfke hep kan kusuyor Ne zaman bir nergis bir gül koklasam İnan ki sevdiğim tek sen kokuyor...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur ve Veda', 'yagmur-ve-veda-sadettin-altintas-zjewn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyordu çekip giderken

Ardına bakmadan sen bu şehirden

Senle dolu olan kırık yüreğim

Seninle yol aldı garip göğsümden

sanki artık ruhum bedende yoktu

ne bir yaşam isteği ne bir tek arzu

beni tek anlayan ecelim oldu

ölürken düşmedin yine dilimden', 'Yağmur yağıyordu çekip giderken Ardına bakmadan sen bu şehirden Senle dolu olan kırık yüreğim Seninle yol aldı garip göğsümden sanki artık r...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-ve-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-sadettin-altintas-h6eqk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'An be an yüreğe kurşunlar sıkar

Tetiği olmayan silah gözlerin

Görünce inan ki beni mahveyler

Görmesem canımı alır gözlerin

gülünce gönlüme baharlar gelir

bir damla yaş bile ölüm demektir

gün gelir gönlüme bir ümit verir

sonra umudumu kırar gözlerin

gece gökyüzünde bir yıldız olur

sabah olduğunda güneşim olur

görmediğim zaman ölsem de olur

bedende canözüm artık gözlerin

nakşettim gönlüme gitsen ne fayda

görmese yüreğim unutur sanma

aşkın yüreğimde olduktan sonra

görmese ne çıkar beni gözlerin', 'An be an yüreğe kurşunlar sıkar Tetiği olmayan silah gözlerin Görünce inan ki beni mahveyler Görmesem canımı alır gözlerin gülünce gönlüme b...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceza', 'ceza-sadettin-altintas-2seh2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Perişan halime bakıp da anla

Karşılıksız sevda ölüm demektir

Sana verilecek yegane ceza 

Gülüm seni daha fazla sevmektir', 'Perişan halime bakıp da anla Karşılıksız sevda ölüm demektir Sana verilecek yegane ceza  Gülüm seni daha fazla sevmektir...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ceza-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostij', 'akrostij-sadettin-altintas-wdv1a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her günüm başlasa hoş gülüşünle

Ayrılmasa gözüm hiç gözlerinden

Baharı getirsen SEVDİM sözünle

Silemese beni kimse kalbinden

Üzmesem hiç seni ve üzülmesem 

Benle dolu olsa her bir kelimen 

Ben olsam sadece çileni çeken

Yanımdan bir ömür hiç ayrılmasan

 Lal eder dilimi bu büyük sevda

Aşkımı söylemek yasaktır bana

Her şiir her şarkım bil ki tek sana

Sözümden aşkımı sezip anlasan

Yazık ki sevenin bir sevdiğin var

Derdimi paylaşır her gece duvar

Hep sana dairdir anlatılanlar

Duvarın ardından sesimi duysan

Aşkım değil ama umudum bitti

Her sözün inan ki beni tüketti

Bana yar olmasan uzak da olsan

Dünyada en mutlu yine SEN olsan', 'Her günüm başlasa hoş gülüşünle Ayrılmasa gözüm hiç gözlerinden Baharı getirsen SEVDİM sözünle Silemese beni kimse kalbinden Üzmesem hiç sen...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akrostij-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sadettin-altintas-4b1st', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbimle gördüğüm tek sevdiğimsin

Ruhumda duyduğum beklediğimsin

Her gece rüyamda gördüğüm halde

Herşeyden daha çok özlediğimsin

attığım her adım sana doğrudur

her anım her günüm senle doludur

her zaman dilimde adın duyulur

yüreğimde açan ilk çiçek sensin', 'Kalbimle gördüğüm tek sevdiğimsin Ruhumda duyduğum beklediğimsin Her gece rüyamda gördüğüm halde Herşeyden daha çok özlediğimsin attığım her...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'söz', 'soz-sadettin-altintas-tv0lf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yüzyıllar geçse de hiç solmayacak

kalbime diktiğin sevda çiçeği

ne gündüz ne gece hiç batmayacak

kalbimde yükselen sevda güneşi

sensiz güneş bana uğramayacak

gitsen bile kalbim unutmayacak 

dünya varoldukça hiç sönmeyecek

kalbimde yaktığın sevda ateşi', 'yüzyıllar geçse de hiç solmayacak kalbime diktiğin sevda çiçeği ne gündüz ne gece hiç batmayacak kalbimde yükselen sevda güneşi sensiz güneş...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/soz-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'And', 'and-sadettin-altintas-swq72', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'adından başka ad anarsa dilim

o anda lal olsun hiç konuşmasın

bir başka güzele meyletse kalbim

taş olsun bir daha hiç atamasın

yerine koyarsam başka birini

yar diye tutarsam bir başka eli

mutluluk unutsun o zaman beni

yar olsun tüm dertler hiç bırakmasın', 'adından başka ad anarsa dilim o anda lal olsun hiç konuşmasın bir başka güzele meyletse kalbim taş olsun bir daha hiç atamasın yerine koyars...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/and-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değil miydin', 'sen-degil-miydin-sadettin-altintas-u0k1u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'büyük bir boşluğa bıraktın beni

asla gitmem diyen sen değil miydin

şimdi başka kollar sarmakta seni

hep seninim diyen sen değil miydin

güneşi çaldın sen ufuklarımdan

harabe bıraktın umutlarımdan

kan damlar oldu satırlarımdan

her şeyimsin diyen sen değil miydin

bensiz dünya sana hani zindandı

yanında ben yokken her şey yarımdı

bensiz gülmek bile büyük günahtı

can özümsün diyen sen değil miydin', 'büyük bir boşluğa bıraktın beni asla gitmem diyen sen değil miydin şimdi başka kollar sarmakta seni hep seninim diyen sen değil miydin güneş...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-degil-miydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanmadın', 'i-nanmadin-sadettin-altintas-mb458', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kim bilir kaç defa haykırdım sana

seviyorum diye sen inanmadın

yazılmış yazısın dedim alnıma

kaderimsin diye sen inanmadın

günü tutsak ettim senin ufkuna

mutluluklar ektim yarınlarına

selam durdum senin her fermanına

sultanımsın diye sen inanmadın

sevilen sevmezse seven tükenir

onun tek yoldaşı artık elemdir

sensiz alacağım son bir nefestir 

can özümsün dedim sen inanmadın', 'Kim bilir kaç defa haykırdım sana seviyorum diye sen inanmadın yazılmış yazısın dedim alnıma kaderimsin diye sen inanmadın günü tutsak ettim...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/inanmadin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm(Akrostij)', 'gulum-akrostij-sadettin-altintas-yqb1k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gizlerim bir ömür herkesten seni

sen benim en büyük sırrımsın gülüm

sensiz avutamaz kimse kalbimi

mutluluğa giden yolumsun gülüm

Üzsen de kırsan da senden kopamam

kalbimden sevgini söküp atamam

sensiz tek an bile nefes alamam

damarımda dolaşan kanımsın gülüm

Lutfeyle bir ömür senin kalayım

yüzünü görmesem sanki yarımım

yanımdaysan eğer o an tamamım

sanki benim diğer yarımsın gülüm

Çare yok gül yüzün solacak inan

ben olurum o gün sana tek kalan

ayrılmam yanından inan tek bir an

gönül sarayımda sultansın gülüm

İnan ki kalbimde teksin eşşizsin

aldığım nefessin çektiğim dertsin

kalpteki yaraya tek sen çaresin

dahası bedende canımsın gülüm

Ne olur kalbinden silme yerimi

düşman say yeter ki önemse beni

bir ömür severim beklerim seni

sen bana benden de yakınsın gülüm', 'Gizlerim bir ömür herkesten seni sen benim en büyük sırrımsın gülüm sensiz avutamaz kimse kalbimi mutluluğa giden yolumsun gülüm Üzsen de kı...', ARRAY['Türk Edebiyatı','Şiir','Sadettin Altıntaş']::text[], 8.5, '{"poet":"Sadettin Altıntaş","poet_slug":"sadettin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gulum-akrostij-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Beklemedi', 'ask-beklemedi-sedat-cakir-u4zrw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk beklemedi

Vurup gitti can evimden

Aşk o''ydu, o aşk değil

Vurup gitti katlanmayı bilmeden

Aşk beklemedi

Bir dev gibi severken ben

O ancak bir dev''in hayali olabilirdi

Bir dev gibi içimde büyümüşken

Aşk beklemedi

Korktu hep medcezirlerimden

Mavi bir aldanışa kapılmıştı belki

Şimdi gri bir akşam damlıyor gözlerimden

Aşk beklemedi

Bu dev''in yüreği ona küçük geldi

Günü geldimi taşacaktı bütün denizleri

Çünkü aşk büyüktü

            yürek küçük

                     o gidecekti

Aşk beklemedi

Vuslatı ibadetti

Aşk o''ydu

o aşk değil

Gitti

o bitti

ben bittim

Aşk beklemedi 

Çünkü o benimdi

o aşk değil

              Tekirdağ 2002', 'Aşk beklemedi Vurup gitti can evimden Aşk o''ydu, o aşk değil Vurup gitti katlanmayı bilmeden Aşk beklemedi Bir dev gibi severken ben O ancak...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ask-beklemedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeyecekmiş Gibi', 'gitmeyecekmis-gibi-sedat-cakir-salsw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bahar gibi sevdim

güz oldun soldurdun beni

Seni rüzgar gibi sevdim

fırtına oldun savurdun beni

Seni deniz gibi sevdim

vurgun oldun boğdun beni

Seni özgürlük gibi sevdim

esaret oldun zicire vurdun beni

Seni mutluluk gibi sevdim

hüzün oldun çürüttün beni

Seni yağmur gibi sevdim

sel oldun süpürdün beni

Seni yaşamak gibi sevdim

ecel oldun öldürdün beni

Ben seni hiç gitmeyecekmişsin gibi sevdim

Gittin...bitirdin beni...

Seni sevmek oysa hep yağmur

hep ılık bir rüzgar

hep durgun bir deni

Seni sevmek oysa hep bahar

hep güzel yaşamak

sınırsız özgürlük

Seni sevmek oysa hep mutluluk

Hep bile bile mavi bir aldanış seni sevmek

Ve sen hep

hiç gitmemiş gibi benim yanımdasın...

                     Tekirdağ Mart 2002', 'Seni bahar gibi sevdim güz oldun soldurdun beni Seni rüzgar gibi sevdim fırtına oldun savurdun beni Seni deniz gibi sevdim vurgun oldun boğd...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gitmeyecekmis-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmak', 'seni-unutmak-sedat-cakir-ueo5g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir masala başlar gibi

Gülerken ağlar gibi

Seni unutmak canım

Yağmur toprağa küser gibi

Bir hayale vardım dün akşam

Hayal değil gerçek gibi

Bir okyanus ezberledim

Mavisi biraz eksik gibi

Yollar yolculuklar var şimdi

Sensiz bir şehir kollarımda

İsimsiz kayıklar, limansız vapurlar

ve aydınlıklar umutlarımda

Son durakta iner gibi

''Hancı rakı ver''der gibi

Seni unutmak canım

Sonum olur sanırım

Güneş sabaha dargın

Yıldızlar geceye

Seni unutmak canım

Vurgun vurgun üstüne

Küserse küssün yağmur toprağa

Her gün doğuşu düşerim ben yollara

Ha bu gün ha yarın

Seni unutacağım canım

Son olursa olsun vurgunların bana', 'Bir masala başlar gibi Gülerken ağlar gibi Seni unutmak canım Yağmur toprağa küser gibi Bir hayale vardım dün akşam Hayal değil gerçek gibi ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Çakır']::text[], 8.5, '{"poet":"Sedat Çakır","poet_slug":"sedat-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-unutmak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bir Müddet', 'seni-bir-muddet-hakan-sengun-8h9vn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuşların peşinden gittim bir müddet

Sonra yağmur yağdı, ıslandım.

Gökyüzü kararmıştı, kaybolmuştu kuşlarım.

Sandımki dönerler geri, 

Ve kuşları bekledim bir müddet.

Dağlara vurdum sonrasında

Karlara vardım, üşüdüm.

Şiirler yazdığım çiçeği düşündüm.

Kuşlara bakakaldım gökyüzünde

Ve güneşi bekledim bir müddet.

Güneşin ardından eridi karlar

Ben sulara karıştım.

Öyle bir hız, öyle bir hırs; 

Denizlere ulaştım köpük köpük.

Ve kumsalda bekledim bir müddet.

Yıldızlara söyledim ağlayan şarkımızı

Kumlara yazıp durdum bir kalpte adımızı

Dalgaların sırtında yakamozlar oynaşırken

Aklımdan geçirirken talihsiz aşkımızı; 

Ve düşlerde bekledim seni bir müddet.', 'Kuşların peşinden gittim bir müddet Sonra yağmur yağdı, ıslandım. Gökyüzü kararmıştı, kaybolmuştu kuşlarım. Sandımki dönerler geri,  Ve kuşl...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-bir-muddet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanal Kahve', 'sanal-kahve-ersin-bulun-h72nf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SANAL KAHVE

Kurukahveci Mehmet efendiden, 

Bir kaşık taze kahve, 

Tepeleme; 

Bir kaşıkta toz şeker, 

Silme; 

Üzerine bir fincan su, 

Taze; 

Hepsi birlikte bakır cezveye...

Nazikçe karıştırdım, 

Gücenmesin diye, 

Çarpmadan kaşığı cezveye.

Kısık ateşte, 

Yavaş, yavaş...

Kahve suya, 

Şeker kahveye kavuştu...

Pişirirken sürekli, 

Gülümsedim yüzüne, 

Kabarsın köpükleri diye.

Artık o; 

Ne su, ne şeker, 

Nede kuru kahve; 

Gönlüm gibi kabarmış, 

Az şekerli bir sanal kahve...

Yanında su tepside, 

Light Marlboro da ikram bizde...

Damağında kahve tadı, 

Hissedemediysen bile; 

Bil ki: Sende değil, 

Hata bende; 

Tarif iyi yerden, 

Kalk birde sen dene...', 'SANAL KAHVE Kurukahveci Mehmet efendiden,  Bir kaşık taze kahve,  Tepeleme;  Bir kaşıkta toz şeker,  Silme;  Üzerine bir fincan su,  Taze;  ...', ARRAY['Türk Edebiyatı','Şiir','Ersin Bulun']::text[], 8.5, '{"poet":"Ersin Bulun","poet_slug":"ersin-bulun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sanal-kahve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Sende Başladı Sende Bitti', 'hersey-sende-basladi-sende-bitti-aysun-elagoz-3cuvq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyorum açacağım gözlerimi ve bitecek bu rüya

Oysa ben uyumak isterdim sonsuza kadar..

Bazen umutlu şarkılar mırıldandı yüreğim 

Yüreğini yaşarken, 

Bazen umutsuz denizlerin

En dibine daldım gözlerinde.

Hiç şikayetim olmadı seni sevmekten.

Bir gün açıverdim gözlerimi

Bir gün bitti bu rüya

Sende başladı herşey

Ve sende bitti.', 'Biliyorum açacağım gözlerimi ve bitecek bu rüya Oysa ben uyumak isterdim sonsuza kadar.. Bazen umutlu şarkılar mırıldandı yüreğim  Yüreğini ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hersey-sende-basladi-sende-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Yalancı', 'en-buyuk-yalanci-aysun-elagoz-ipoxj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En büyük yalancı benim

Hiçbir zaman olmayacakların masalı ile avuttum yüreğimi, 

Geleceğe dair ninnilerle uyuttum, 

Hiç bitmeyeceğine inandırdım kendimi sevgilerin...

Yüreğim, 

Bir gün herşeyi farkedecek 

Ve beni asla affetmeyecek.', 'En büyük yalancı benim Hiçbir zaman olmayacakların masalı ile avuttum yüreğimi,  Geleceğe dair ninnilerle uyuttum,  Hiç bitmeyeceğine inandı...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/en-buyuk-yalanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '0 Çay İçilmeyecek', '0-cay-i-cilmeyecek-cumhur-turan-etekh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'o çay 

içilmeyecek içilmesine

oysa içilebilirdi

tam da

dudaklarına sıcaklığı değmişken

burnuna kokusu

koltuğunda öylesi dingin oturmuşken 

üstelik

nedeni deprem mi

evetlemesine evet

hayırlamasına hayır

demek gerek

evet

yırtılan bir faydı

saat 18.58''de

sadece çay değildi dökülen

yıkılan kolon altında bedeninden

akan kandı ölümüne

zift karası karanlıkta

uçuşurken kelebekçe tozlar

son kez algıladın

yalnızdın evrende

ölümün

çaresizliğe bir küfür gibi

aktı

aktı

derken boşalan bir zembereğin

son titreyişinde durdu bedenin

oysa 

son

bu son 

olmazdı

olamazdı

eğer

meclis üyesi

kara İsa''nın oğlu Kel Hasan

çamur deryası çukuru doldurup

arsa eyleterek Meclise

üstüne yedi katlı bina

cebine de tonla para

koymasaydı hani

hani

bu binayı yapan Tilki Osman

temeli atarken

sağlam zemin derdine düşseydi

Kontrol  Mühendisi Sarı Avni

Her beton atılışı öncesi bitseydi inşaatta

projeye uygunluğa baksaydı

imzalarının ağırlığını duyumsayarak

yüreğinde

sen hala 

çayını içiyor olabilirdin de

bu kez

depremin şokunu atmak için üstünden', 'o çay  içilmeyecek içilmesine oysa içilebilirdi tam da dudaklarına sıcaklığı değmişken burnuna kokusu koltuğunda öylesi dingin oturmuşken  ü...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/0-cay-icilmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesini Kaybeden Şehir', 'sesini-kaybeden-sehir-nazim-hikmet-ran-c5azr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adedi devir

       sıfır.

Şehir

   sustu

Kenetlendi nokta nokta şehrinin

                 asfalt-beton çenesi: 

bin dokuz yüz nokta nokta senesi

                    nokta nokta

                           ayında...

Cadde boş.

bir uçtan bir uca koş.

Cadde boş

       bomboş

           cebim gibi...

Kesildi akmıyor su...

Ne bir motor uğultusu

              ne dönen bir tekerlek var.

Rüzgar: 

   sürüklüyor asfaltta Mister Ford''un adını: 

   duvardan kopan renkli bir ilan kaadını

          
..........
..........', 'Adedi devir        sıfır. Şehir    sustu Kenetlendi nokta nokta şehrinin                  asfalt-beton çenesi:  bin dokuz yüz nokta nokta se...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sesini-kaybeden-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı Lokantası', 'balikci-lokantasi-murat-gulen-67n64', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Salaş bir balıkçı  lokantası  düşlerim, Egede.

İki  adım denize …

Gözlerim yakalar dansını  minik dalgaların.

Hayaller kurarım sayesinde, esen ılık  rüzgarın.

Tahta masalar, eski  tabakların, 

denize değen çamların  arasında, 

ben  özgürlüğümü  kutlarım;  yalnızlığımda.

Oysa içimde ne kahkahalar, ne şarkılar var , 

laf aramızda …

Bir kadeh şarap ve balık ve denizin sesi; 

Hoşgeldin der  yanımıza, 

gitme buralardan, bırakma bizi …

Tabaktaki balık bile ağlar.

Bak feda ettim kendimi sana, ne olur bizi bırakma…

İçimdeki şarkılar da  katılır  bu  israra.

Kadehimdeki şarap bile  ümitli.

Hepsi bir koro gibi; 

En güzel şarkılarını  sunarlar  bu gizemli hayatın, 

Öyle ki; 

bugüne kadar yaşamadığım.

Cevabım çok zor çıkar ağzımdan.

Ne yana baksam çağrıyor beni.

Oysa ben bir yaşamın peşine takılmışım, 

bir deli gibi..

Başımı önüme eğdim. ve, …..

bir türlü  diyemedim ki ,  bırakmıyorum  sizi …', 'Salaş bir balıkçı  lokantası  düşlerim, Egede. İki  adım denize … Gözlerim yakalar dansını  minik dalgaların. Hayaller kurarım sayesinde, es...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülen']::text[], 8.5, '{"poet":"Murat Gülen","poet_slug":"murat-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/balikci-lokantasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlangıç', 'baslangic-murat-gulen-i2ohi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolculuğun  başındayız, sonunda değil.

Son dediğin  nedir? 

O da belli değil.

Hayat dediğin, başlangıçla  son arası, 

iyi yap hazırlığı, 

başlayacağın yer belli  değil.', 'Yolculuğun  başındayız, sonunda değil. Son dediğin  nedir?  O da belli değil. Hayat dediğin, başlangıçla  son arası,  iyi yap hazırlığı,  ba...', ARRAY['Türk Edebiyatı','Şiir','Murat Gülen']::text[], 8.5, '{"poet":"Murat Gülen","poet_slug":"murat-gulen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/baslangic-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Daha Bulamadığım Hazine', 'sen-daha-bulamadigim-hazine-sair-duman-jzdmy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen, daha bulamadığım hazine 	                                      ne zaman esinle oturup seni yazmaya kalksam kalemim yutkunuyor, sayfalar kayıyor masadan, hafızamın sana dairliğini yitiriyorum.                                                           Sözcükler yangından kaçarcasına kaçıyor belleğimden			unutuyorum, utanıyorum...                   anladım artık seni yazacak kadar olgunlaşmadı(m.)  kalemim! Sen daha bulamadığım hazine haznem hüzün küpü sanki.. sanki sen yoksun, gelmedin daha;   kaç bahar  bekleyeceğim                                                                          kaç nisanı sensiz ıslatacağım...                  		    ama ya(rı) nımda olman gerek! ! !                                            Sen daha bulamadığım hazine 	                                    bir gelip pir gidensin ömrümün garına, duygularım taşıyor seni duraktan durağa, sen onlarla geziyorsun gözlerim vefakar yaşlarıyla bende kalıyor	                                         sen varken şenleniyor gar durmadan yolcular taşıtılıyor iklimden iklime...	                                                                                                '' hep   güzellikler soluyoruz’’	                                  kim bilir nerdesin şimdi                                                    Dışarıda çıldırmış bir hava, 	                                                    bir kedi ürke  ürke miyavlıyor! 	                                        -sen kendi fırtınandasın-	     ben iklimini kavalayan göçmen...', 'Sen, daha bulamadığım hazine 	                                      ne zaman esinle oturup seni yazmaya kalksam kalemim yutkunuyor, sayfalar...', ARRAY['Türk Edebiyatı','Şiir','Şair Duman']::text[], 8.5, '{"poet":"Şair Duman","poet_slug":"sair-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sen-daha-bulamadigim-hazine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazım', 'nazim-sair-duman-fwnk5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir parça nazım''ız aslında,  yüreğimize bir liman, bir dalga yetmez. durmadan yeni bir fırtıne ara dururuz, uslanmak bilmez yüreğimiz                                                                                         bir parça nazım''ız aslında...', 'bir parça nazım''ız aslında,  yüreğimize bir liman, bir dalga yetmez. durmadan yeni bir fırtıne ara dururuz, uslanmak bilmez yüreğimiz       ...', ARRAY['Türk Edebiyatı','Şiir','Şair Duman']::text[], 8.5, '{"poet":"Şair Duman","poet_slug":"sair-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/nazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih', 'tarih-sair-duman-wr0d0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bugün bir tarih yazıldı biz seyrettik, bugün koca bir yük gibi  (b) indi belleğimizin  işgal altındaki coğrafyasına...bugün bir tarih yazıldı dün gibi, yarın yine takvimlerden yaprak hafifliğiyle düşüp tarih olacak...yarın yine takvimlerden  çığ gibi düşecek  belleğimize -tarih olacak-', 'bugün bir tarih yazıldı biz seyrettik, bugün koca bir yük gibi  (b) indi belleğimizin  işgal altındaki coğrafyasına...bugün bir tarih yazıld...', ARRAY['Türk Edebiyatı','Şiir','Şair Duman']::text[], 8.5, '{"poet":"Şair Duman","poet_slug":"sair-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/tarih-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Gibi', 'benim-gibi-ceyhun-yilmaz-r38al', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızca yağmur yağdığında seviyorum bu şehrin insanlarını..

Herkesin yüzü gözü ıslak, 

Başları eğik omuzlarının arasında..

Yağmur yağdığında... Herkes.. 

Benim hep olduğum gibi...', 'Yalnızca yağmur yağdığında seviyorum bu şehrin insanlarını.. Herkesin yüzü gözü ıslak,  Başları eğik omuzlarının arasında.. Yağmur yağdığınd...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/benim-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Adım Yanlızlık', 'benim-adim-yanlizlik-belgin-kistavul-syavc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim Adım Yanlızlık............

Benim bir adım hüzün, diğer adım yanlızlıktır; 

Yanlızlığı yaşamakta bir erdemdir bunu herkes başaramaz....

Sevmem öyle kendimi anlatmayı, kısa cümleler kurarım hep

Karanlık odamda ışık yakmam, mum yakarım, 

Güzel bir müzik açar dalar giderim uzak limanlara....

Pek öyle fazla düşünmem hayata dair ne varsa diye; 

Sadece beynimdeki kırık, dökük düşünceleri toparlarım

Hayatın bana verdiklerini değil, benden aldıklarını irdelerim.........

Bende ondan bir şeyler alabilmek için

Hüznün dibine atarım bir yürek dolusu sevgiyi

Kimse bulup çıkartamasın diye.......

Öyle hayallerimde yoktur benim

Real düşünür, real yaşarım; 

Hayaller kağıt ev gibidir benim için bir gün yıkılabilir..........

Yapabileceğim şeyleri düşünür

Yapamayacaklarımı yarınlara bırakırım.....', 'Benim Adım Yanlızlık............ Benim bir adım hüzün, diğer adım yanlızlıktır;  Yanlızlığı yaşamakta bir erdemdir bunu herkes başaramaz.......', ARRAY['Türk Edebiyatı','Şiir','Belgin Kistavul']::text[], 8.5, '{"poet":"Belgin Kistavul","poet_slug":"belgin-kistavul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benim-adim-yanlizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana', 'bana-belgin-kistavul-05o3h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana sevgiden bahsetme yabancı; 

Dedim ya; ben sevmeyi bilmem

Bir zamanlar sevdiğimi sandım

Hayat mı insanlara çok şey öğretiyor, 

Yoksa insanlar mı hayata.? 

Benim yüreğim buz gibi yabancı

Yanlızlığımı seviyorum ve şiirlerimi

Yok! hayır bana sevmeyi bilmiyorsun deme sakın! 

Benim kadar bilen var mı, ama yorgunum

Yüreğimde yorgun benim kadar

Bilmem belki de haklısın korkuyorum, 

Sevmenin acı ve ihanet olduğunu öğrendim

Sade dostlukları seviyorum, kısa sohbetler

İçimi ısıtan gülmeler......', 'Bana sevgiden bahsetme yabancı;  Dedim ya; ben sevmeyi bilmem Bir zamanlar sevdiğimi sandım Hayat mı insanlara çok şey öğretiyor,  Yoksa ins...', ARRAY['Türk Edebiyatı','Şiir','Belgin Kistavul']::text[], 8.5, '{"poet":"Belgin Kistavul","poet_slug":"belgin-kistavul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilirsin', 'sen-bilirsin-ceyhun-yilmaz-x3w7g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Görmediğimden değil...

Yanımda olsan yine özlerdim..

Ve bil ki bu kadar sevmem senden değil

Gitsen benden..

Ben gidişini bile severim..

Aramızda hep aynı fark..

Sen gitmeyi bilirsin

Ben sevmeyi..', 'Görmediğimden değil... Yanımda olsan yine özlerdim.. Ve bil ki bu kadar sevmem senden değil Gitsen benden.. Ben gidişini bile severim.. Aram...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-bilirsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Birşeyi', 'hic-birseyi-belgin-kistavul-6ymii', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç Birşeyi

Hiçbir şeyi paylaşmayı bilemedik değil mi..? 

Ne konuşmayı, nede sevgiyi

Sadece birbirimizi yıprattık

Üzdük hırpaladık, 

Ve içimizde evcilleşmiş acılar yarattık 

Oysa her şey güzel olabilirdi..

Şimdi ne söylesek boş, geriye dönemeyiz ki

Senin paylaşmayı sevmediğin duyguların

Benimse kocaman bir gururum var

İnsanlar hep birbirlerini basit şeylerden kaybediyor

Ben sevmeyi bilemedim, belki de belki de sevilmeyi

Artık çok geç zaten; 

Yalan sevgilerle oyalanmak için

Ama üzülmüyorum biliyor musun

Sevgilerimi şiirlerimde yansıtıyorum

Kağıt ve kalemim senden daha çok sadık bana

Yanlızlığım ise  hep yanımda

Senden daha fazla omuz bana

Farkındayım telefonuma sessiz çağrılar sen bırakıyorsun

Benim seni aramamı bekliyorsun 

Konuşmaya cesaretin yok  çünkü

Her şeyi hep benden beklediğin gibi 

Ama biliyor musun..? 

Sen artık benim beynimin en ufak hücresinde bile yoksun

Senden kalan hatıraları da sildim

Senin ve sana ait her şeyi çöpe attım

Hem de hiç tereddüt etmeden

Kalbim buz gibi

Ruhum yorgun artık

Ne sevebilirim nede sevmek için vaktim var...

Benimde artık bahanelerim var

Ve hayaller kurmuyorum sadece kendimi seviyorum

Sağol bunu bana sen öğrettin...B.K.', 'Hiç Birşeyi Hiçbir şeyi paylaşmayı bilemedik değil mi..?  Ne konuşmayı, nede sevgiyi Sadece birbirimizi yıprattık Üzdük hırpaladık,  Ve içim...', ARRAY['Türk Edebiyatı','Şiir','Belgin Kistavul']::text[], 8.5, '{"poet":"Belgin Kistavul","poet_slug":"belgin-kistavul","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hic-birseyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-ceyhun-yilmaz-y2jq4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrıl ayrıl bıktım sevdalardan...

Ne farkeder sen bıraksan, ben bıraksam

Bırakmayan hüzün yakamı...

Bıraktım ölmesi muhtemel sevmeleri..

Yaktım birr birr

Yalandan güldüğün resimleri...', 'Ayrıl ayrıl bıktım sevdalardan... Ne farkeder sen bıraksan, ben bıraksam Bırakmayan hüzün yakamı... Bıraktım ölmesi muhtemel sevmeleri.. Yak...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalan-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci', 'dilenci-ceyhun-yilmaz-nf5fq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En yakın deniz kenarına atıyorum kendimi

Her dalga halime üzgün..

Her dudakta bana tebessüm..

ne vardı diyorum ''ah'' ne vardı

Şu kaldırımda resmin olsaydı...

Eğilip öperken ben 

Görenler, varsın dileniyorum sansaydı...', 'En yakın deniz kenarına atıyorum kendimi Her dalga halime üzgün.. Her dudakta bana tebessüm.. ne vardı diyorum ''ah'' ne vardı Şu kaldırımda r...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dilenci-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben.. Sen...', 'ben-sen-ceyhun-yilmaz-tvk39', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben seni seviyorum 

sen gezmeyi, 

senin hep gittiğin yere ben hiç gidemiyorum.

Öylece durmayı seviyorum ben.. 

Durup ardından bakmayı.. 

Sen yürümeyi seviyorsun ama arkana bakmadan.. 

yaprak seviyorum ben yaprak.. 

Kuru, yaş ayırmadan.. 

Sen ezmeyi seviyorsun, neye bastığına bakmadan..', 'ben seni seviyorum  sen gezmeyi,  senin hep gittiğin yere ben hiç gidemiyorum. Öylece durmayı seviyorum ben..  Durup ardından bakmayı..  Sen...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Karım', 'eski-karim-ceyhun-yilmaz-i53hn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hala sen varmışsın gibi

İki yastıkla yatıyorum..

Kimseye söyleme gidişini, ben söylemedim.

Elimde senin siparişin olmayan torbalarla geliyorum eve..

Ağlaya ağlaya öpüyorum yattığın yastığı yorganı

Sanki beni az önce yolcu etmişsin gibi çıkıyorum sokaklara..

Üst komşuya hava atarak, bi fiyaka bi görsen..

Ne garip bu insanlar! 

Bütün mahalle, hatta alttaki bakkal bile seni geçen kasım öldü sanıyor...

Ne garip bu insanlar! 

Hala her sabah bana selam veriliyor..

Sanki yaşıyormuşum gibi..', 'Hala sen varmışsın gibi İki yastıkla yatıyorum.. Kimseye söyleme gidişini, ben söylemedim. Elimde senin siparişin olmayan torbalarla geliyor...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eski-karim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taksici', 'taksici-ceyhun-yilmaz-ejea3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben ne kadar sevdiysem.. 

O kadar gittin...

Gitmediğin zamanlarda bile, hep gidecekmiş gibi durdun yanımda...

Her bakışında başka bir el sallama

Tam sevmek isterken seni..

Taksi çağırdın..

Gitme deyişimi ne sen duydun, ne taksici..', 'Ben ne kadar sevdiysem..  O kadar gittin... Gitmediğin zamanlarda bile, hep gidecekmiş gibi durdun yanımda... Her bakışında başka bir el sal...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/taksici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharda Sessizlik', 'baharda-sessizlik-duahan-hanci-9uzpt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Odamda bir saatin sesi, 

Bir de benim soluk alışım var.

İçimde binlerce ezik his

Gönlümde açılmadık çiçekler var

Açılması istenmemiş, Gözyaşları yetmemiş.

Tomurcuğu hüzünle dolu

Kokusu hiç yayılmamış

Ne o çiçeğin kokusu çıkar, 

Ne de bahtım gün yüzüne.

O siyahlara bürünen akşam

Sessizce geldi yine

Odamda bir saatin sesi

Bir de benim soluk alışım var

İçimde ne kuş sesleri

Ne de bahar sevinci var

Ben miydim o bahar çiçekleriyle coşan, 

Yoksa hayallerine tutunmuş bir delikanlı mıydı 

Mutlulukla koşuşan? 

Bir şenlikti mevsimler

Hepsinde ayrı neş''e, ayrı bir sevinç vardı

Şimdi nerede mevsimler

Bana bir tek kış kaldı

Ne dünyamda dindi yağmur

Ne de gözlerimde tükendi.

Odamda bir saatin sesi

Bir de benim soluk alışım var.

Geçen her dakika ömrümden

Geçen her saniye beynimden

Geçen her an yürekten vuruyor beni.

Kulaklarımda binlerce uğultu

İçimde sayısız depremler

Dünyamdaysa sonsuz bir gürültü var.

Oysa

Odamda bir saatin sesi

Bir de benim soluk alışım var? ...', 'Odamda bir saatin sesi,  Bir de benim soluk alışım var. İçimde binlerce ezik his Gönlümde açılmadık çiçekler var Açılması istenmemiş, Gözyaş...', ARRAY['Türk Edebiyatı','Şiir','Duahan Hancı']::text[], 8.5, '{"poet":"Duahan Hancı","poet_slug":"duahan-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/baharda-sessizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Geceden Kalan', 'o-geceden-kalan-duahan-hanci-4jl2b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin kör sesinde bir korku kaldı bende

Gözlerim bulut bulut, ellerim kor bir ateşte

Dudaklarım sitemkar bir gülüşün hevesinde

Gidişinle buz gibi bir kış kaldı bende

Yorulmak ne güzeldi heyecanı hissedip

Mutlulukla döndüm geriye üzüntüyü devirip

Dudakların sıcacıktı, şefkati de ekleyip

Alnıma koyduğun buse kaldı bende

Bir görünüp kayboldun, yüzünü çevirdin

Sanki hiç dönmeyecek gibi ansızın gittin

Getirdiğin baharı kışa döndürdün

Senli dünyamda sensizliğim kaldı bende

yorgun gecede yorgun iki iz vardı

Solgun yüzünde yinede mutluluk vardı

Heyecanın derindi canımda canın vardı

Seninle olmak başkaydı tenimde terin kaldı

Geceyi yırtan kısık sesinle

Tenimi kavuran sıcak elinle

Gözlerime bıraktığın bakış iziyle

Aldığım nefesteydin, Soluğun kaldı bende

Bitti sandığım yerden yeniden başladım

Kederleri fırlatıp Sevinçleri aldım

Dünyama bahar getirdin sana alıştım

O geceden bir çok şey

Gözlerin, elleri, nefesin

hatta sıcacık bir sevgi

Belki de sadece yüreğin kaldı bende! ...', 'Gecenin kör sesinde bir korku kaldı bende Gözlerim bulut bulut, ellerim kor bir ateşte Dudaklarım sitemkar bir gülüşün hevesinde Gidişinle b...', ARRAY['Türk Edebiyatı','Şiir','Duahan Hancı']::text[], 8.5, '{"poet":"Duahan Hancı","poet_slug":"duahan-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/o-geceden-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın', 'ayriligin-mesut-erbas-9shph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gideceksin; 

Bu aşkın külleri avuçlarında.

Göreceksin; 

Yanmış bedenim az uzakta.

Kanlı yüreğim avuçlarımda...

...', 'Gideceksin;  Bu aşkın külleri avuçlarında. Göreceksin;  Yanmış bedenim az uzakta. Kanlı yüreğim avuçlarımda... ......', ARRAY['Türk Edebiyatı','Şiir','Mesut Erbaş']::text[], 8.5, '{"poet":"Mesut Erbaş","poet_slug":"mesut-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayriligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-mehmet-kepez-33l1l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birgün bir yerde karşılaşırız belkide

Alırda o hasreti

Onca ayrılığın acısını çıkarırcasına

Yerden yere vururuz seninle.', 'Birgün bir yerde karşılaşırız belkide Alırda o hasreti Onca ayrılığın acısını çıkarırcasına Yerden yere vururuz seninle....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kepez']::text[], 8.5, '{"poet":"Mehmet Kepez","poet_slug":"mehmet-kepez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-gun-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seven-ne-yapmaz', 'seven-ne-yapmaz-hakan-sengun-9zsfx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeterki düşme aklıma ayrılık olup

Deli gönlüm nehir olur, bir yere akmaz.

Dilsiz olur çağlamaz, 

Dolanmaz yollarına

Acı çeker ama kollarına dolanmaz.

Gururum çelik olur, vursalarda kırılmaz

Sana böyle hasretken seven ne yapmaz.

Ne olur ayrılık diye yazma kader yazımı

Sevgileri gönlümde zindanlara kapatma.

Ben razıyım çileme, gönül buna aldırmaz, 

Güneş olur sönerim ateşim seni yakmaz.

Söylerim şarkıları

Sonrasında dinlerim.

Gerekirse kaparım gözlerim sana bakmaz

Sana böyle hasretken seven ne yapmaz.', 'Yeterki düşme aklıma ayrılık olup Deli gönlüm nehir olur, bir yere akmaz. Dilsiz olur çağlamaz,  Dolanmaz yollarına Acı çeker ama kollarına ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seven-ne-yapmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Sonbahar', 'sensizlik-sonbahar-hakan-sengun-xc29w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sevda kokan çiçek

Yeşildim, yeşerecektim sen olmadan

Yeşil kalacaktım senin olmadan önce.

Kurudum, sarardım

Kolay değil, sensiz ilk sonbaharı yaşadım.

Gittiğin gün baharın hüznü vardı içimde

Öyle bir güneşle uyandımki

Gözlerim kamaştı, gözlerim ağlamaklı

Yüreğimde bir kuşun kanatları

Ardımdan kovalayan  sert bir rüzgarı

Hissettim sonbaharı.

Yüreğim büklüm büklüm

Yüreğim buruş buruş

Ve yüreğim darma dağın

Merak sarar ya insanı

Ardında ne vardır dağların; 

Yüreğim dağların ardında şimdi.

Dağlar ayaz, dağlarda kar

Dağların ardına kuş olup uçamaz yar.

Yüreğim çaresiz, yüreğim sefil

Yüreğim ateşlerde, yüreğim yangın.

O yangının alevinde kül olup yandım, 

Kolay değil, sensiz ilk sonbaharı yaşadım.', 'Ben sevda kokan çiçek Yeşildim, yeşerecektim sen olmadan Yeşil kalacaktım senin olmadan önce. Kurudum, sarardım Kolay değil, sensiz ilk sonb...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sensizlik-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaygaracı', 'yaygaraci-i-rfan-topcu-wmhbf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne söylemediğin kadar sır

nede, 

anlattığın kadar yaygarasın

sen benim tanıdığım kadarsın.', 'Ne söylemediğin kadar sır nede,  anlattığın kadar yaygarasın sen benim tanıdığım kadarsın....', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yaygaraci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende yalan', 'sende-yalan-i-rfan-topcu-dm1ye', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elerken bütün aşklarımı,elekle,

