INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-ceyhun-yilmaz-w4hbs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolculuklarda tuhaf oluyorum

Bu şehirden her gidişimde

Sanki şehri ben uğurluyorum

Sen benden gideli çok oldu ama..

Ben her gidişimde hala sana el sallıyorum', 'Yolculuklarda tuhaf oluyorum Bu şehirden her gidişimde Sanki şehri ben uğurluyorum Sen benden gideli çok oldu ama.. Ben her gidişimde hala s...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/veda-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-ceyhun-yilmaz-a6cht', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık yolların hep ışıksız

olduğunu söylemediler bana

ben küçükken söyleselerdi

büyümezdim zaten! ..', 'Karanlık yolların hep ışıksız olduğunu söylemediler bana ben küçükken söyleselerdi büyümezdim zaten! .....', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kucugum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakma Beni', 'birakma-beni-zafer-alaftargil-pb82d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılığın en zor anında, 

içine akıttığın göz yaşlarıyla acı verir hayat. 

Haykırırsın tüm gücünle, 

''Ne olur bırakma beni! '' 

Titreyen ellerini açarak, 

Yalvarırsın tanrıya tüm benliğinle. 

Son bir defa uyuyup, 

O eski rüyaları görmek için 

''Ne olur bırakma beni! '' 

Ümitsizliğin artar 

Yanaklarından süzülen göz yaşlarıyla birlikte. 

Ve son bir defa izlersin ''o''nu. 

Ayrılığın en zor anında. 

Sarılırsın sımsıkı 

Sonsuza dek bırakmak istemezcesine. 

O gül yüzü hala o kadar güzeldir ki, 

Okşarsın tenini tüm sevginle. 

Sonra korkar, 

İrkilirsin o eski sıcaklığı hissedemeyince. 

Artık tüm şiddetiyle 

Özlem akmaya başlar damarlarından. 

Ve ayrılığın en zor anında 

Haykırırsın tüm gücünle; 

''N e olur bırakma beni! '' 

''Bırakma! ! ! ''', 'Ayrılığın en zor anında,  içine akıttığın göz yaşlarıyla acı verir hayat.  Haykırırsın tüm gücünle,  ''Ne olur bırakma beni! ''  Titreyen elle...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/birakma-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum', 'erzurum-zafer-alaftargil-btzh0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fırtınaların bitkin sesi

Siyah kefeni sevdaların

Sen de döndün

Bende sözümüzden

Yalancıyız ikimizde

Ne kadar benziyoruz

Sana ve bana 

Seni depremler

Beni çileler

Yıldırmadı

Belki titredik

Beraberce geceleri

Ama yüreğimizde sevda

Kavrulduk çöl misali

Sana güneş gülmedi

Bana ise yar

Oysa ne kadar yakındık

İkisine de

Erzurum

Beklentilerimiz oldu

Sen denizi düşledin

Göz yaşlarım da

Bense mutluluğu

Ayazlarında

Hep birbirimizi unuttuk

İki bebek

Sen ve ben Erzurum

Fırtınaların bitkin sesi

Bekle

Hayat güldürecek ikimizi', 'Fırtınaların bitkin sesi Siyah kefeni sevdaların Sen de döndün Bende sözümüzden Yalancıyız ikimizde Ne kadar benziyoruz Sana ve bana  Seni d...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/erzurum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Acı', 'i-lk-aci-zafer-alaftargil-lyi87', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özür yetmez bilirsin

Kan kusturan çilelere

Güneş uğrar mı dersin

Sensiz geçen gecelere

Zehrine müptelayım aşkının

Özlemini kaldırmaz duygular

Çaresizlik türevi sancının

Harfini haykırtmaz korkular

Lanet fışkırır gönüllerden

Ayrılık heceleyen zamana

Aşk sıyrılır kalplerden

Gözlerinde dönüşür hüsrana

Erkeği ağlatmayan gurur

Dökülür damla damla toprağa

Geceler sensizlikten dem vurur

Gönlüm sitem eder yalnızlığa

Mevsimler ölüme götürür

Bin bir renge alışamadan

Aşkın ateşini toprak söndürür

Mutlulukla tanışamadan

Nilüferler kadar ıslağım

Ilık nisan yağmurlarında

Deve dikenlerinden yastığım

Uykusuzum, her gecenin sabahında

Ecelden korkum olmaz

Sonunda vuslat varsa

İstesen yüreğim solmaz

Üstüne karlar da yağsa

Baharlara hasretim

Kara kışında ikliminin

Bir umuda endeksliyim

Anlamsız bakışında sevgilinin

İnat düğümlenir boğazıma

Ağlamaklı hıçkırıklara inat

Yıldızlar tüner enkazıma

Saçlarında yoğunlaşınca kainat

Okur yazar değil gönlüm

Ben acemi ozan, kalem tercüman

Yazmaya yetmez gücüm

Ama ismin dilimde her zaman

Gonca değil artık sevdam

Çok zaman oldu açalı

Şimdi istesem de kurutamam

Beklemek zorundasın hazanı

Leşimden çıkmaz bir damla kan

Hepsini gözlerimden akıttım

Ruh değil bedenimden çıkan

Onu da aşkınla erittin

Utancım dağlar kadar

Seni Seviyorum diyemez

Yalnız bir sorun var

Söylemeden ölemem...

18/02/02-03: 30

zafer', 'Özür yetmez bilirsin Kan kusturan çilelere Güneş uğrar mı dersin Sensiz geçen gecelere Zehrine müptelayım aşkının Özlemini kaldırmaz duygula...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ilk-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötenazi', 'otenazi-zafer-alaftargil-sj7oi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kurşuna hasret şimdi yüreğim

Çektiğim acı ölümden beter

Bitir bu ızdırabı gözbebeğim

Yalnız sevmediğini söyle yeter

Bir kez olsun yardım et bana

Sen ümitleri öldür ben kendimi

Son noktayı koyalım aşkıma

Huzura gömelim yorgun bedenimi', 'Kurşuna hasret şimdi yüreğim Çektiğim acı ölümden beter Bitir bu ızdırabı gözbebeğim Yalnız sevmediğini söyle yeter Bir kez olsun yardım et ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otenazi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilme', 'sen-bilme-zafer-alaftargil-w53la', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayağını sürüyerek yürü sokakta

Geçtiğin yolları izinden bilmeliyim

Ve bekleme hiçbir durakta

Bir ömür boyu peşinden gelmeliyim

Arkana bakma köşe başlarında

Farketme gölgendeki varlığımı

Ufka diktiğin ürkek bakışlarında

Ölesiye hissetmeliyim yalnızlığı

Aldırış etme yağan yağmura

Bırak ıslatsın seni efkarım

Sakın öfkelenip şemsiyeyi açma

Saçında gözyaşım kurumadan ölmeliyim', 'Ayağını sürüyerek yürü sokakta Geçtiğin yolları izinden bilmeliyim Ve bekleme hiçbir durakta Bir ömür boyu peşinden gelmeliyim Arkana bakma ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-bilme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sipariş Hüzün', 'siparis-huzun-zafer-alaftargil-j0io4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sipariş bir hüzün sızıyor penceremden

Gözlerinin karasına gömüyorum umutları

Yalnızlık cehennemleri süzüyor sinemden

Sesinin rengine boyuyorum bulutları

Vefasız bir sevda suluyorum göz yaşlarımla

Hayaline bir demet efkar sunuyorum

Bir çift darağacı kuruluyor başıma

Yarınları gülüşüne kurban veriyorum', 'Sipariş bir hüzün sızıyor penceremden Gözlerinin karasına gömüyorum umutları Yalnızlık cehennemleri süzüyor sinemden Sesinin rengine boyuyor...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siparis-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım', 'unutamadim-zafer-alaftargil-cvuov', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir nefeslik kısacık ömrümü

Uğrunda of çekerek harcadım

Yalnızlığa katık ettim de hüznümü

Yinede gönlümü avutamadım

Zehrin her türlüsünü içtim elinden

Ruhumu sevda dan arıtamadım

Bir volkan fışkırsa da yüreğimden

Elimde değil seni unutamadım', 'Bir nefeslik kısacık ömrümü Uğrunda of çekerek harcadım Yalnızlığa katık ettim de hüznümü Yinede gönlümü avutamadım Zehrin her türlüsünü içt...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unutamadim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyet', 'vasiyet-zafer-alaftargil-0y5n3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mezarıma bir çiçek yeter

Hayatta birden fazla gül

koklamadım zaten

Bırakın

Öldükten sonra da öyle kalsın

Gelip başımda kimse ağlamasın

Türküler söyleyin, parti düzenleyin

Mezarımın üstünde

Dünya da gülmedim

Izdırabı, hep ağlamakla dindirdim

Bırakın, 

Azabım neşeli olsun.', 'Mezarıma bir çiçek yeter Hayatta birden fazla gül koklamadım zaten Bırakın Öldükten sonra da öyle kalsın Gelip başımda kimse ağlamasın Türkü...', ARRAY['Türk Edebiyatı','Şiir','Zafer Alaftargil']::text[], 8.5, '{"poet":"Zafer Alaftargil","poet_slug":"zafer-alaftargil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vasiyet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün ki', 'dusun-ki-guney-ahiskali-p6uh5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kulaklarim adini hiç duymamis 

Ve hiç tekrar etmemis, isminin ilk hecesini, 

Yalçin kayalarda akislenen seda gibi 

Düsün ki, 

Düsüncelerimde hiç olmamissin sen 

Ugultusu avuçlarimda kalan rüzgar gibi geçmissin. 

Ay isigina hasret yakamozlarinin vuslatiymis, 

Tam yerine ve tan yerine vuran o umutlarinin gölgesi... 

Düsün ki, 

Bir sigara içimlik vakitmissin, 

Cigerime ecza diye dolan 

Ya da ugrak bir, giderlemeyen efkâr kahvehanesi... 

Düsün ki, 

Bardakta eriyen; ebediyen beklemekmis, seker sanilan 

Kirik bir sandalyeymis umutlarimi yasladigim... 

Düsün ki, 

Bir uçurum dibiymis, bakislarindaki o mana 

Oyuncaksiz kalmasiymis bir çoçugun 

Ya da bir annenin yavrusuna hasreti... 

Düsün ki, 

Yanik bir Anadolu türküsüymüssün, 

Çesme basindaki güzel kizlara inat 

Ve inat, gurbetin tüm güzelliklerine... 

Düsün ki, 

Gam yüklü duvarda asi, kirik bir aynaymissin 

Hep yarim, hep eksik, hep mahçup.. 

Ayna karsisinda kirik bir bakis, 

Kaybolan diger yarisindaki tilsim.. 

Bir yagmur olmussun 

Ve tanelerin düsermis pembe düslerimin düstügü yere.. 

Düsün ki, bir orada bir burada 

Bir gurbette bir silada 

Isminin yalin, yanlizligimin çogul halinde.. 

Ve arkasina saklanmis binlerce yürek 

O binlerce yürekten düsen..Tek bir düs 

Ve ilik bir nefesinde üsümüs... 

Düsün ki, 

Uzak hatiralarim kalmis sende 

Tek kisilik bir oyun 

Gurbete bir tren bileti 

Ya da yarasi, 

Yarisindan büyük olan yirtik bir resim... 

	

Düsün ki, 

Hiç olmamis

Hiç çalinmamis bir beste 

Hiç tadilmamis bir zehir, 

Düsün ki, 

Hiç yazilmamis bir siir...', 'Kulaklarim adini hiç duymamis  Ve hiç tekrar etmemis, isminin ilk hecesini,  Yalçin kayalarda akislenen seda gibi  Düsün ki,  Düsüncelerimde...', ARRAY['Türk Edebiyatı','Şiir','Güney Ahıskalı']::text[], 8.5, '{"poet":"Güney Ahıskalı","poet_slug":"guney-ahiskali","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/dusun-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde', 'i-cimde-yasar-toprak-m1thd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'içimde bir adam yürüyerek uzun ve tozlu yolu

sarmaya çalışıyor herkese dağıttığı

kendini terk etmiş mikroplu aklını

içimde bir adam tüm sevgi gösterilerine

gülüyor içtenlikle

biliyor gülünen herşeyin gizli sırrını', 'içimde bir adam yürüyerek uzun ve tozlu yolu sarmaya çalışıyor herkese dağıttığı kendini terk etmiş mikroplu aklını içimde bir adam tüm sevg...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Toprak']::text[], 8.5, '{"poet":"Yaşar Toprak","poet_slug":"yasar-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/icimde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Hiç Sizi Aldattuğı Oldu mu?', 'siirin-hic-sizi-aldattugi-oldu-mu-ertan-tanoba-yur6h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiçbir şiir sizi düpedüz anlattı mı? 

Siz anlatamadığınız için şiirin biri

Sizi mutlaka anlatmıştır.

Muhtemelen yalnızdınız.

Hiçbir şey sevmiyordunuz.

Korkuyordunuz.

İt gibi korkuyordunuz hem de

Yalnızdınız.

Bir şiirin, 

Sevdiğiniz değil, adını bile bilmediğiniz bir şiirin sizi anlattığı sıra siz

Sikilmiş bir sıpa gibi sahillerde pinekliyordunuz.

Boğazınız hıçkırıkla tıka basa dolduğunda bile

Ağlayamıyordunuz.

Birileri sizden önce davranmıştı ve “hıçkırmıştı”

Şimdi hıçkırarak ağlamak size “tuhaf” geliyordu.

Boğazınızdaki düğümü çözmeden bir yenisi düğüm atıyordu.

Boğuluyordunuz.

Anlamıyordunuz.

Hiç birinin nedenini anlamıyordunuz.

Bağırmak isterdiniz, 

Bağırmayı çocukluktan beri isterdiniz.

Çok seyrek gülerdiniz

O zaman etrafı neşeye boğardınız.

Herkes bu kadar açken

Neden daha fazla gülmezdiniz ki? 

Severdiniz bazen

Nadiren severdiniz evet.

Meftunu olur sevdiğinizin, bırakmak bilmezdiniz

Kimse anlamazdı bunu.

Ne yaşarken ne bitmişken 

Kimse anlamazdı.

Siz bir de yaşarken ne çok ölürdünüz

Lakin ölüm size ne çok yakışırdı

Dirildiğinizde içinde bulduğunuz yaşamları selamlayıp

Mağrur ve vakur güler geçerdiniz

Kimse gülmezdi ama. 

Yazık tutunamadınız.

Ya hiç tutunacak bir dal olmadı, 

Ya da oldu siz tutunmayı bilmediniz.

Sizi kimse sevmezdi

Diliniz sivriydi az biraz

Kıvrak olduğu kadar az biraz da oynak, uylak olsaydı

Ne olurdu sanki.

Olmadı mı? 

Söyleyin bunların hiçbiri olmadı mı? 

Peki, diyelim hiçbiri olmadı.

Hiçbir şiir sizi anlatmadı.

Siz bile hiç anlatmak istemediniz mi? 

O zaman, 

Yanlış zaman, 

Yanlış insan.

Ya siz tam bir şiirin sizi anlatması gerektiği yerde değildiniz, 

Ya hiçbir kafa size dönük değildi, 

Ya tam karşı masada bir şiir tam sizi anlatıyorken

Çekip gittiniz birden, 

Ya çoktan anlatmıştı

Ama siz habersizdiniz.

Peki, diyelim hiçbiri olmadı.

Ne siz düşündünüz, 

Ne birileri düşündü

Ne birileri yazdı.

Diyelim bunların hiçbiri olmadı.

Ee... Madem buradayız

Ve madem ben (ya da sen)

Bu soruyu sorduK! 

O zaman çoktan 

		Şiirin biri

		Bir yerlerde

		Bir zaman

Sizi çoktan anlatmıştır! 

Gidin onu bulun.

Bulamazsanız gocunmayın sakın.

Açın yüreğinizi ardına kadar

Aşık olun! 

				Ertan Tanoba

19 Aralık,2001-Haymatlos/Taksim', 'Hiçbir şiir sizi düpedüz anlattı mı?  Siz anlatamadığınız için şiirin biri Sizi mutlaka anlatmıştır. Muhtemelen yalnızdınız. Hiçbir şey sevm...', ARRAY['Türk Edebiyatı','Şiir','Ertan Tanoba']::text[], 8.5, '{"poet":"Ertan Tanoba","poet_slug":"ertan-tanoba","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/siirin-hic-sizi-aldattugi-oldu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıpırtı', 'kipirti-ertan-tanoba-hkmxd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Önce aşkın kıpırtısı, gelir yerleşir içine, 

Ner''den geldiği bilinmez güvercinler

Göğsünün kafesinin içinde kanat çırpıyor gibidir, 

Yüreğin ''çıpır çıpır'' çarpar! 

Sonra birgün bir korku sarar içini

(ner''den geldiğini bilmezden gelirsin)

Güvercinler sığmaz ne göğsüne ne onun kafesine

Kavga ederler.

İçin kaygıyla acır.

Hiç dinmeyecek gibidir, 

Yüreğin ''sapır sapır'' kanar! 

Nice sonra bir gün, 

(sen yine nedensiz sanırsın)

Yüreğinin acısı diner.

Güvercinleri kanatlarından tuttuğun gibi

Özgür bırakırsın.

Onları gökyüzünde seyrederken, 

Yüreğin yeniden ''kıpır kıpır'' atar! 

Kasım,2000, Moda-İstanbul', 'Önce aşkın kıpırtısı, gelir yerleşir içine,  Ner''den geldiği bilinmez güvercinler Göğsünün kafesinin içinde kanat çırpıyor gibidir,  Yüreğin...', ARRAY['Türk Edebiyatı','Şiir','Ertan Tanoba']::text[], 8.5, '{"poet":"Ertan Tanoba","poet_slug":"ertan-tanoba","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kipirti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Seni Düşünsem', 'ne-zaman-seni-dusunsem-aysun-elagoz-ewvxr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman seni düşünsem, 

Çiçekler açıyor yüreğimde, 

Işıl ışıl bakıyorum hayata, 

Gülümsemekten kendimi alamıyorum...

Ne zaman seni düşünsem, 

Umutlarla bezeniyor gökyüzüm, 

Sevgiyle doluyorum, 

Nefes alırken seni soluyorum...

Ne zaman seni düşünsem, 

Gözyaşlarımı elimin tersiyle siliyor, 

Yaşamak için

Yeniden güç biriktiriyorum...', 'Ne zaman seni düşünsem,  Çiçekler açıyor yüreğimde,  Işıl ışıl bakıyorum hayata,  Gülümsemekten kendimi alamıyorum... Ne zaman seni düşünsem...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-zaman-seni-dusunsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinde Gelişen', 'i-cinde-gelisen-mehmet-caner-sumengen-v4wb0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ektiğin tohumdur toprakta yeşeren 

Güneşe uzanıp ışığa erişen 

Derler ki; Kalplere rehberdir bir eren

Umuttur işte o, içinde gelişen...', 'Ektiğin tohumdur toprakta yeşeren  Güneşe uzanıp ışığa erişen  Derler ki; Kalplere rehberdir bir eren Umuttur işte o, içinde gelişen......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/icinde-gelisen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonraki Hayat', 'senden-sonraki-hayat-mehmet-caner-sumengen-vtr51', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yol göster, unutabilmem için seni 

Ya da; Bir ışık tut, göreyim o güzel yüzünü... 

Gittiğin günden beri gecelerdeyim, karanlığım 

Gecelerce adını sayıkladım duymadın 

Bir ışık tut, aydınlığa adım atayım... 

Şiirler yazıyorum acıları heceleyerek... 

Mutsuzluğun resimlerini çiziyor 

Yalnızlık türküleri söylüyorum. 

Ve içimde kalan son umut tanecikleriyle 

Dualar ediyorum dönmen için 

Ve de vefasızlığına inat 

Sen terketsen de odamızı, ben bir an olsun bırakıp gitmiyorum... 

Zindanlardan farksız yokluğunda odamız 

Odamız keder dolu, odamız suskun, odamız öyle sarhoş 

Odamız sanki cehennemin dünya şubesi... 

Böyle olsun istemezdin, bilirim...

Bilirim ki hesapsız, düşüncesiz, tutarsız gittin.

Yoksa ne ölümlere yollayacak bir yürek var sende

Ne de karşılıksız, sınırsız sevecek bir yürek! 

Bilirim...Gerçekten sevemezsin sen hiç! 

Oysa ben, ben hep delice sevdim! 

Yanımda, kanımda, canımda ol yeterliydi. 

Yeterliydi, bir gülüşünün gözündeki parıltısı 

Yeterliydi, gönül çeşmenden akan sevgi damlacıkları 

Yeterliydi doyasıya yaşanmışlığın, aynı yastığı paylaşımın. 

Sana dünyaları veremezdim ama 

Dünyaları da bana verseler, sana değişmezdim... 

Şimdi ah edip vah etsem de çok geç

Almış başını yürümüş ömrümüzün hırsızı zaman.

Tüm adımlarımı atsam da geriye doğru, inançla 

Kavuşmaz, varamaz, uzak kalmış bize vuslat. 

Yitirdiğim yarisin bitmeyecek sevdamın 

Gençliğimi harcadığım bu yolun çıkmazısın...

Aç, susuz, tek başına, garip yaşamak 

Ağlamak, yalvarmak, kanamak 

İşte bu, benim için, senden sonraki hayat... 

Bir yol göster, unutabilmem için seni 

Ya da; Ya da! Bir ışık tut, tutayım ellerini...', 'Bir yol göster, unutabilmem için seni  Ya da; Bir ışık tut, göreyim o güzel yüzünü...  Gittiğin günden beri gecelerdeyim, karanlığım  Gecele...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/senden-sonraki-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Beni', 'anla-beni-ahmet-kurt-mxl1a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ahvalimi sen bilirsin sevdigim, 

Anla beni, dinle beni, duy beni. 

Hasretle yorgunum, vuslatla bitap, 

Anla beni, dinle beni, duy beni. 

Söz isteme benden, gözlerime bak, 

O bakisla eri, yüregime ak, 

Simsek gibi çakip, ruhuma birak, 

Anla beni, dinle beni, duy beni. 

Sorma neden, gülme sakin halime, 

Tarifsiz duygular gelir dilime, 

Yine anlatamam, seni gönlüme, 

Anla beni, dinle beni, duy beni. 

Kurdoglu bir acayip cisimdir, 

Hafizada naksolacak isimdir, 

Insan türlü türlü, kisim kisimdir, 

Anla beni, dinle beni, duy beni.', 'Ahvalimi sen bilirsin sevdigim,  Anla beni, dinle beni, duy beni.  Hasretle yorgunum, vuslatla bitap,  Anla beni, dinle beni, duy beni.  Söz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anla-beni-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-ergun-yildirim-jjvc0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanlık yaşamaksa eğer, 

Ölmek yaşamaktan da beter', 'İnsanlık yaşamaksa eğer,  Ölmek yaşamaktan da beter...', ARRAY['Türk Edebiyatı','Şiir','Ergün Yıldırım']::text[], 8.5, '{"poet":"Ergün Yıldırım","poet_slug":"ergun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/insan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilme Yeter', 'sen-bilme-yeter-cemal-mercan-2ump9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gördüm seni ben, gün batımında

O gülen gül yüzün, hep hatırımda

Tatlı dilin sözlerin, hep satırımda

Bu sır bende kalsın, sen bilme yeter

Gittiğin an bile, seni özledim 

Belki döner diye, yolun gözledim 

Seni sevdiğimi ben, hep gizledim

Bu sır bende kalsın, sen bilme yeter

Gittin yağmurlar, hiç yağmaz oldu

Güneşin üstüme hiç, doğmaz  oldu

Sevgin yüreğime hiç, sığmaz oldu

Bu sır bende kalsın, sen bilme yeter

Dostlarımdan kestim, artık selamı 

Hiç kimseye demem, birtek kelamı

Şu garip gönlümün bütün meramı

Bu sır bende kalsın, sen bilme yeter

İsterim  bedenden, bu canı atmak 

İsterim aşk için, dünyaya çatmak

Ömrümü bitirip, ömrüne katmak

Bu sır bende kalsın, sen bilme yeter

Nefes daralıyor, ömür bitmiyor

Bu sevgi içimden, bir an gitmiyor

Sana doyulmuyor, zaman yetmiyor

Bu sır bende kalsın, sen bilme yeter

Senin için gece, gündüz oturdum

Senden ayrılınca, sokakta durdum

Yanında olmak için, bahane buldum

Bu sır bende kalsın, sen bilme yeter

	             Cemal MERCAN', 'Gördüm seni ben, gün batımında O gülen gül yüzün, hep hatırımda Tatlı dilin sözlerin, hep satırımda Bu sır bende kalsın, sen bilme yeter Git...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sen-bilme-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmışım', 'sanmisim-cemal-mercan-emqv5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derdim bir taneyle, kalır  sanmışım

Hayat birgün güler, diye kanmışım

Felek çemberin de, hergün yanmışım

Derdim bir taneydi, bine bölündü

Bütün dertler geldi, bize bu yazla 

Bütün sıkıntılar, sıktı bu hazla 

Taşıyamıyorum, bu yük çok fazla

Derdim bir taneydi bine bölündü

Beklenen umutlar, hiç gelmeyecek

Bu kader bu  hayat, hiç gülmeyecek 

Çekilen çileler, hiç bitmeyecek

Derdim bir taneydi, bine bölündü

Ömür de, hayat ta, hepsi ayıpta 

Günahı sevabı, birbir sayıpta 

Cennetle cehennem, onlar kayıpta

Derdim bir taneydi, bine bölündü

                                                        Cemal MERCAN', 'Derdim bir taneyle, kalır  sanmışım Hayat birgün güler, diye kanmışım Felek çemberin de, hergün yanmışım Derdim bir taneydi, bine bölündü Bü...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sanmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ergun-yildirim-5a0lt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılık yolunu şaşırdı sanki

Geceler sabah olmak blimiyor 

gözler çökmüş, 

Ellerin sevmek bilmiyor sanki

Sonbahar akşamı yaprak dökülür

Hüzünlenir yüregim, kalbim sökülür

Anımsarsın sevdiğin yağmur dökülür

Rüzğar sanki sevmek bilmiyor', 'Ayrılık yolunu şaşırdı sanki Geceler sabah olmak blimiyor  gözler çökmüş,  Ellerin sevmek bilmiyor sanki Sonbahar akşamı yaprak dökülür Hüzü...', ARRAY['Türk Edebiyatı','Şiir','Ergün Yıldırım']::text[], 8.5, '{"poet":"Ergün Yıldırım","poet_slug":"ergun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşerde Sorarım', 'mahserde-sorarim-cemal-mercan-yj8ru', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsanım ben, ne dertlerle, yoğruldum

Yaşamımda, çilelerle kavruldum

Günüm doldu, bu dünyadan savruldum

Ahım kalır, ben mahşerde sorarım

Akşam olur, kös kös, eve dönerim 

Dertlerimle, zindanlara, inerim

Kavgalardan, kötülerden, sinerim

Ahım kalır, ben mahşerde sorarım

Sevdalanır, yalımlanır, kaçarım

Etrafıma, gülücükler, saçarım

Bir gül olur, gönüllerde, açarım

Ahım kalır, ben mahşerde sorarım

Sevdam yakar, ince ince, bedeni

Aşkım barbar, birazcıkta, medeni

Sevdim işte, bilmem nedir, nedeni

Ahım kalır, ben mahşerde, sorarım

                                                  Cemal MERCAN

AHIMLA BUR DA BEN, MAHŞERDE SORARIM.', 'İnsanım ben, ne dertlerle, yoğruldum Yaşamımda, çilelerle kavruldum Günüm doldu, bu dünyadan savruldum Ahım kalır, ben mahşerde sorarım Akşa...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mahserde-sorarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpte Gör Beni', 'kalpte-gor-beni-cemal-mercan-u6eee', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göğün en üstünde yıldızlarında

Güneşte sıcakta çölde gör beni

Denizin dibinde suyun bağrında

Aldığın nefeste camda gör beni

Giydiğin papucun ökçelerinde

İçtiğin nesnenin şişelerinde

Aldığın kasetin nağmelerinde

Kasette teypte seste gör beni

Oturduğun koltuğun döşemesinde

Önündeki sehpanın işlemesinde

Baktığın aynanın çerçevesinde

Kanında canında sende gör beni

Yattığın yatağın nevresiminde

Yaptığın makyajın ham maddesinde

Taktığın takının her tanesinde

Atomda zihinde kalpte gör beni

                      Cemal MERCAN', 'Göğün en üstünde yıldızlarında Güneşte sıcakta çölde gör beni Denizin dibinde suyun bağrında Aldığın nefeste camda gör beni Giydiğin papucun...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalpte-gor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrımla Giderim', 'kahrimla-giderim-cemal-mercan-k554h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimdeki dalgalar, karanlığı döverken

Yürekteki fırtına, şehir şehir gezerken

Kalbimdeki ateşler, denizlerde yüzerken

Çivilendiğim bu yerden, kahrımla giderim

Güneş de alev alev, üşüyorsa, çağrımda

Dünya da, damla damla, eriyorsa bağrımda

Sevdalarım, fersah fersah yaşarken, kahrımda

Çivilendiğim bu yerden, kahrımla giderim

Korkular, birer birer çıkıyorsa, ininden

Duygular, hain olup, atılmışsa dininden

Yüreğim, kor kor olup, yanıyorsa kininden

Çivilendiğim bu yerden, kahrımla giderim	

Mutluluklar sevinçler, cehenneme girmişse

Şeytan da, melek olup, karşıma dikilmişse

Güzellik, iyilikler, hesaba  çekilmişse

Çivilendiğim bu yerden, kahrımla giderim

                                                               Cemal MERCAN', 'İçimdeki dalgalar, karanlığı döverken Yürekteki fırtına, şehir şehir gezerken Kalbimdeki ateşler, denizlerde yüzerken Çivilendiğim bu yerden...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kahrimla-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-cemal-mercan-uxi7c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluk ejderha olmuş ağzını açar bize

Varlık huri olmuş durmadan kaçar size

Mecalimde kalmadı yorgunluk çöktü dize

Nasıl yaşarsan yaşa gel bu yalan dünyada

Çocuk bakar beşikten mama da veremezsen

Hanım bakar kapıdan ekmek götüremezsen

Şu üç günlük dünyada yemek yediremezsen

Nasıl yaşarsan yaşa gel bu yalan dünyada

İsyan ettim yaşama, hayata, cana, sine 

Hırsım haksızlıklara içimde kötü kine

Sinirlerim gerilgin şu açlık denen cine

Nasıl yaşarsan yaşa gel bu yalan dünyada

Karladı yazım benim şu deli genç yaşımda 

Yokluklar kara duman geldi çöktü başımda

Sevgiler mutluluklar hepsi  mezar taşımda 

Nasıl yaşarsan yaşa gel bu yalan dünyada

                                          Cemal mercan', 'Yokluk ejderha olmuş ağzını açar bize Varlık huri olmuş durmadan kaçar size Mecalimde kalmadı yorgunluk çöktü dize Nasıl yaşarsan yaşa gel b...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isyan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-cemal-mercan-9n6v4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat, yaşam buldum dudaklarında

Benimle gül açtı yanaklarında 

Seviyorum sözüm de  kulaklarında

Ömrüm geldi geçti sen dönmez oldun

Hayatıma ruhum  düşman olmadan 

Dünyanın  üstünde ecel bulmadan 

Yaşamın zamanı burda dolmadan 

Ömrüm geldi geçti sen dönmez oldun

Hayat baharında güller solmadan 

Dünya döner iken zaman durmadan

Dertler kederlerde  beni  vurmadan

Ömrüm geldi geçti sen dönmez oldun

Yokluğunda ağarttım saçlar kırlaştı 

Sensiz yaşamak burda zorlaştı

Ölüm arzusu bende  korlaştı

Ömrüm geldi geçti sen dönmez oldun

				     Cemal MERCAN', 'Hayat, yaşam buldum dudaklarında Benimle gül açtı yanaklarında  Seviyorum sözüm de  kulaklarında Ömrüm geldi geçti sen dönmez oldun Hayatıma...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayat-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıram', 'hatiram-cemal-mercan-wlwet', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar geçti artık unuttum seni

Gönlümde kalbinde kuruttum seni

Hayatımdan söküp çürüttüm seni

Sönmüşmü ateşin kormudur  bilmem 

Yıllar oldu düşünmedim anmadım

Sensizliğe alışmayıp yanmadım

Hayatı sevgiyi sende bulmadım 

Sönmüşmü ateşin kormudur  bilmem

Hatırlatma bana kinim çıkmasın

Bu yürek isyanla sana çatmasın

Bu gözler bir daha sana bakmasın

Sönmüşmü ateşin kormudur  bilmem

Dönme artık şehre görüşmeyelim

At artık kalbinden düşünmeyelim

Menzile seninle erişmeyelim

Sönmüşmü ateşin kormudur  bilmem

                                  Cemal MERCAN', 'Yıllar geçti artık unuttum seni Gönlümde kalbinde kuruttum seni Hayatımdan söküp çürüttüm seni Sönmüşmü ateşin kormudur  bilmem  Yıllar oldu...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hatiram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Nesin', 'sen-nesin-cemal-mercan-pe5bu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözümde özümde senin hayalin 

Üzerime bindi onca vebalin 

Hiç çıkmaz akıldan senin misalin

Melekmisin resimmisin sen nesin

Sensiz bu dünya hep karadır dardır 

Yokluğunda soğuk heryerde  kardır 

Yaşanılanlar da hayırda vardır

Melekmisin resimmisin sen nesin

Gözümü kapattım sen rüyamdasın

Yatağımdan baktım duvarımdasın

Üstümü giyerken etrafımdasın

Melekmisin resimmisin sen nesin

Tek başıma kalsam dostum sırdaşım

Sıkıntılı olsam tek arkadaşım

Herzaman yanımda sensin kardaşım			

Melekmisin resimmisin sen nesin

Gökyüzüne baksam sen yıldızımsın

Yeryüzünde nurum hep ışığımsın

Göçüp gitsem burdan tek aşığımsın

Melekmisin resimmisin sen nesin

		Cemal MERCAN', 'Gözümde özümde senin hayalin  Üzerime bindi onca vebalin  Hiç çıkmaz akıldan senin misalin Melekmisin resimmisin sen nesin Sensiz bu dünya h...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-nesin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılırken', 'ayrilirken-onur-uysal-zo5k0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmezdim

Ayrılıkların bu kadar yürek delici

Sevdaların bu kadar kırılgan

Tükenişin bu kadar hızlı olduğunu...

İnandım, inandım tüm samimiyetimle

Kaçışların bir kucaklaşması

Sessizliğin bir haykırışı

Tükenmişliğin bir üreyişi olduğuna..

Bilmezdim, bilemezdim inan

Bir sabah gözlerimi sensizliğe açacağımı

Vedalaşan buğulu gözlerini

Sadece resimlerde bulacağımı...

Peki ya sen, sen bilir misin

Kaçıracağını bildiğin geminin arkasından

                    seyreder misin? 

Sabahlara dek bekleyişlerin tik taklarını sayarken

Heyecanların kapı önü bırakılışına

                    gülümser misin? 

Bilmezsin gülüm, bilemedin hayret

Bu acılı yürek ilk günden şefkate hasret

Şu kovup gidemediğim düşünlerde

İkimiz bile yok, sen varsın bir tek...

Biliyorum canım, 

Hazırsın şimdi yeni sevdalara

Yeni denizlere yelken açmaya

Hazırsın biliyorum

Cesaretini yüzünden

Heyecanını gözlerinden

     anlıyorum...

Yine de bilesin

Seni, 

Bir su kadar duru yüreğini

     ve bir okyanus kadar derin gözlerini

İnan çok özlüyorum...', 'Bilmezdim Ayrılıkların bu kadar yürek delici Sevdaların bu kadar kırılgan Tükenişin bu kadar hızlı olduğunu... İnandım, inandım tüm samimiye...', ARRAY['Türk Edebiyatı','Şiir','Onur Uysal']::text[], 8.5, '{"poet":"Onur Uysal","poet_slug":"onur-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ayrilirken-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Rengi', 'gece-rengi-cemal-mercan-rxbz1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gök yüzünde, ummanlara dalmışım

Gece rengi, gözlerine al beni

Yalım yalım, olup sende kalmışım

Gece rengi, gözlerine al beni

Etrafımda, yıldız gibi parladın

Ağaç gibi, yüreğime kök saldın

Kışım oldun, lapa lapa karladın

Gece rengi, gözlerine al beni

Batacaktın madem, hiç  doğmasaydın

Şimal yıldızımdın, sen solmasaydın

Güneşsiz kalırdım, sen olmasaydın

Gece rengi, gözlerine al beni

Sen gelmeden, pembe düşler dikerdim

Gökyüzüne, mutluluklar ekerdim

Gözüm kördü, evde cefa çekerdim

Gece rengi, gözlerine al beni

Dünyayı seninle, tanıdı canım

Heryere ulaştı, şöhretim şanım

Seninle duruldu, damarda kanım                                         

Gece rengi, gözlerine al beni

                             Cemal MERCAN', 'Gök yüzünde, ummanlara dalmışım Gece rengi, gözlerine al beni Yalım yalım, olup sende kalmışım Gece rengi, gözlerine al beni Etrafımda, yıld...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gece-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çılgınsın Deli Gönlüm', 'cilginsin-deli-gonlum-cemal-mercan-xmzvb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çılgınsın deli gönlüm, denizlere dalmışsın

Zincirleyip hisleri, çilelere salmışsın

Bir kenara itilip ateşlerde kalmışsın

Kötülüğü bilmezsin iyisin  deli gönül

Gün olur çılgın gibi top misali atarsın

Bazen de durgunlaşır derdine dert katarsın

Ölüm seni yıldırmaz düşmanına çatırsın

Kötülüğü bilmezsin iyisin  deli gönül

Dinim kadar derinsin gökyüzü kadar uzak

Bin asker kadar güçlü bir aslan gibi kazak 

Birgül kadar narinsin düşmanlara bir tuzak

Kötülüğü bilmezsin iyisin  deli gönül

                                  Cemal MERCAN', 'Çılgınsın deli gönlüm, denizlere dalmışsın Zincirleyip hisleri, çilelere salmışsın Bir kenara itilip ateşlerde kalmışsın Kötülüğü bilmezsin ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cilginsin-deli-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetle Cehennem', 'cennetle-cehennem-cemal-mercan-esx1f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beter ettin beni, şirin den beter

Senin için insan, ağrıyı deler

Sevgi yok mu abi, dostluğu biler

Cennetle cehennem, dünyada abi

Hayat yolu uzun, belki çok kısa

Dünyada yaşarsan, heryerin yasa

Sevginin uğruna, çekmezsen tasa

Cennetle cehennem, dünyada abi

Cehennem ateşi, içimde yaşar

Volkanlar misali, başımdan taşar

Ben geri kaçsamda, ayaklar koşar

Cennetle cehennem, dünyada abi

Dilim ayrı söyler, gözlerim ayrı

Zihnim ayrı işler, sözlerim ayrı

Kader ayrı gider, dizlerim ayrı

Cennetle cehennem, dünyada abi

                         

                        Cemal MERCAN', 'Beter ettin beni, şirin den beter Senin için insan, ağrıyı deler Sevgi yok mu abi, dostluğu biler Cennetle cehennem, dünyada abi Hayat yolu ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cennetle-cehennem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara Beni', 'ara-beni-cemal-mercan-4v3lh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşin doğmasın, sabah olmasın

Aklına girenler, sağda kalmasın

Kararsın hayatın, aydınlanmasın

Beni ara elinde, mum dünyada

Düşmanların hepsi, yanına gelsin

Dost olanlar ise, bir bir tükensin

Elinde avcunda ne, varsa gitsin

Beni ara elinde, mum dünyada

Bir kez olsun, yetinmedin malınla

Bir gün olsun, mutlanmadın canınla

Her gün soğuk, hiç gülmeyen kanınla

Beni ara elinde, mum  dünyada

Viraneler evin, olsun bilmezsen

Kurtuluşun ölüm, olsun sevmezsen

Papuç dilin hep, sürünsün kesmezsen

Beni ara elinde, mum  dünyada

Sokak köpekleri, sırdaşın olsun

Bütün yıkık yerler, kardaşın olsun

Kol kanat kırıklar, yoldaşın olsun

Beni ara elinde, mum  dünyada

Güvendiğin dağlar, üstüne uçsun 

Bel bağladıkların, sırtından vursun

Düzgün yolların, hep patika olsun

Beni ara elinde, mum  dünyada

   		   				Cemal MERCAN', 'Güneşin doğmasın, sabah olmasın Aklına girenler, sağda kalmasın Kararsın hayatın, aydınlanmasın Beni ara elinde, mum dünyada Düşmanların hep...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ara-beni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyorum', 'yuruyorum-cemal-mercan-cxrun', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıldızlar  yolunda bende yürürüm

Her gece rüyamda seni görürüm

Kurban misali yolunda ölürüm 

Eritip yok etme tut güzel gözlüm

Bütün vasıtalar sana getirir 

Körelmiş umutlar beni bitirir

Canı benden alır sende yitirir 

Eritip yok etme tut güzel gözlüm

Seni sazlar sözler gibi özledim

Geleceksin diye her gün gözledim

Sevdim meleklerden bile gizledim

Eritip yok etme tut güzel gözlüm

Oturup kalkarım hatırımdasın

Şiirler yazarım satırımdasın

Canımın içinde kahırımdasın

Eritip yok etme tut güzel gözlüm

Seninle vermiştik umut arası

Aramıza girdi gece karası 

Beni öldürecek bu aşk yarası

Eritip yok etme tut güzel gözlüm		   

                        Cemal MERCAN', 'Yıldızlar  yolunda bende yürürüm Her gece rüyamda seni görürüm Kurban misali yolunda ölürüm  Eritip yok etme tut güzel gözlüm Bütün vasıtala...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yuruyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşar mı Sandın', 'yasar-mi-sandin-cemal-mercan-pxcg1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alışılmaz yüreğimdeki  hüzün

Hiç çıkmıyor aklımdan senin yüzün

Bakar durur heryerden bana güzün

Yoksun ankarada, yaşar mı sandın

Kafamdan çıkmıyor hiç kaygılarım

Yüreğimi  yakıyor duygularım

Her gece de bölünür uykularım

Yoksun ankarada, yaşar mı sandın

Seninle herşeyin yaşandığını

Birlikte hislerin boşandığını

Silahı tüfeği kuşandığını

Bilsem ne yazar yaşanır mı sandın

Aklımdasın  gözyaşımın sisinde

Fikrimdesin rüzgarların sesinde

Üstüme sin dumanların isinde

Yoksan ne yazar yaşar mı sandın

Güneşimdin sende benim günahsız

Gecem karanlıktır benim sabahsız

Ansızın çekip gittin sen  vefasız

 kalsan ne yazar yaşar mı sandın

                         Cemal MERCAN', 'Alışılmaz yüreğimdeki  hüzün Hiç çıkmıyor aklımdan senin yüzün Bakar durur heryerden bana güzün Yoksun ankarada, yaşar mı sandın Kafamdan çı...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasar-mi-sandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabul Et', 'kabul-et-cemal-mercan-xuxw6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zamanı saati, sana kurmuşum

Takılıp aylarca, sende durmuşum

yıldızlara aya, seni sormuşum

Kabul et ne olur, yada vur  gülüm 

Yeryüzüde esen, kara yeldim  ben

Nehirlerde akan, coşkun seldim ben

Sakinim duruldum, sana geldim ben

Kabul et ne olur, yada vur  gülüm 

Kabul dersen eğer, yerden uçayım

Etrafa dünyaya, umut saçayım 

Gül misali gelip, sende açayım

Kabul et ne olur, yada vur  gülüm 

Senin sevgin hergün, kalbe yerleşir

Bedenimle, canla, kanla birleşir

Sevginle yeşerir, büyür gürleşir

Kabul et ne olur, yada vur  gülüm 

                          Cemal MERCAN', 'zamanı saati, sana kurmuşum Takılıp aylarca, sende durmuşum yıldızlara aya, seni sormuşum Kabul et ne olur, yada vur  gülüm  Yeryüzüde esen,...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kabul-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterim', 'i-sterim-cemal-mercan-21wzp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyalara vermem, senin gülmeni

Ne kadar isterim, bilsen gelmeni

Göz yaşlarımı, senin Silmeni

Tarihe ismini, yazmak isterim

Güneşin dağlardan, inse bağrıma

Bir kez kulak versen, benim çağrıma

Bir gün ortak olsan, benim kahrıma

Bu kötü kaderi, bozmak isterim

Dünyayı dolaşsan,  burda yerleşsen

Herkesi unutup, benle birleşsen

Burada kök salıp, benle gürleşsen

Göklere ismini, kazmak  isterim

Ağaçlar çiçekler, yaprak dökünce

Ömrümün üstüne, kara çökünce 

Bu sevda uğruna, bende ölünce

Kabrime ismini, yazmak isterim

                        Cemal MERCAN', 'Dünyalara vermem, senin gülmeni Ne kadar isterim, bilsen gelmeni Göz yaşlarımı, senin Silmeni Tarihe ismini, yazmak isterim Güneşin dağlarda...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isterim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Murat''ım', 'murat-im-cemal-mercan-nmhig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'MURAT’ım

	

Şiir yazıp burda ağlatırmısın

Beni derde koyan İnce MURAT’ım

Derdimi alıpta dağlatırmısın

Beni benden alan  İnce MURAT’ım

Bulutsam içimde yagmur  yanımda

Çölde çiçek olsan susun başımda

Üzülsem gülsemde ben her yaşımda

Yanımda her zaman  İnce MURAT’ım

Karanlık gecede yıldızım olur

Yolumu kaybetsem heryerde bulur

Sıkıntı duyarsam yanımda olur

Dostumdur her zaman  İnce MURAT’ım

Sıkıntıma ortak derdime dayak

Şiirimde dize satırda ayak

Paten düşünsem ayağımda kayak

Destektir her zaman İnce MURAT’ım

                                            Cemal MERCAN', 'MURAT’ım 	 Şiir yazıp burda ağlatırmısın Beni derde koyan İnce MURAT’ım Derdimi alıpta dağlatırmısın Beni benden alan  İnce MURAT’ım Bulutsa...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/murat-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-cemal-mercan-h9mwf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saçları kar ile bolca sulanmış

O kara bıyıklar kara bulanmış

Sakalı sormayın  bol uğralanmış

İşte bu resim halis bozkurtmuş

İçini açmış da yalınlar sokmuş

Kalbinde bir damla kinide yokmuş

Güzelce özenmiş bu beden olmuş

İşte bu beden halis bozkurtmuş

Allahım bu yüze bolca özenmiş 

Koca yüreği sevgiyle bezenmiş

Melekler seyredip hepsi beğenmiş 

İşte bu insan halis bozkurtmuş

                         Cemal MERCAN', 'Saçları kar ile bolca sulanmış O kara bıyıklar kara bulanmış Sakalı sormayın  bol uğralanmış İşte bu resim halis bozkurtmuş İçini açmış da y...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/resim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanım', 'sultanim-cemal-mercan-cigur', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen dağlarda gezen allı maralım

Sen kalplerde gezen cansın karalım

kimse vurmaz seni içi yaralım

vurdun can evimden öldürdün gülüm

seninle geçen saatleri sayamam

karşıma alsamda baksam doyamam 

lime lime olsam gene duyamam

vurdun can evimden öldürdün gülüm

seninle dolaşıp senle yaşarken

gündüzde gecede senle coşarken

seninle yükselip sensiz düşerken

vurdun can evimden öldürdün gülüm

Acılarımı unutup sana yaslandım

Senin aşkın ile çölde ıslandım

Koştum  yoruldum da şimdi  uslandım

Vurdun bu garibi öldürdün gülüm

                                                

                                                  Cemal MERCAN', 'Sen dağlarda gezen allı maralım Sen kalplerde gezen cansın karalım kimse vurmaz seni içi yaralım vurdun can evimden öldürdün gülüm seninle g...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sultanim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sümbülüm', 'sumbulum-cemal-mercan-t7lzc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgimi ben göklere tüm denizlere

Seni ben kalbime yazdım sümbülüm

Kinimi cihana tüm yelizlere

Seni ben kalbime yazdım sümbülüm

Sen buhulu cama resmimi yaptın

O resmin yanında yerini kaptın

Yağmur damlasıydım ben sana baktım

Seni ben kalbime yazdım sümbülüm

Peri kızı gibi beni vurmadan

Uzunca bir süre haber almadan

Damlalarla geldim buhar olmadan

Seni ben zihnime yazdım sümbülüm

Camdaki o resim  kaçıp gitsede

Kapıları gönlüne açıp gitsede

Ardından gülleri saçıp gitsede

Seni ben zihnime yazdım sümbülüm

                                Cemal mercan', 'Sevgimi ben göklere tüm denizlere Seni ben kalbime yazdım sümbülüm Kinimi cihana tüm yelizlere Seni ben kalbime yazdım sümbülüm Sen buhulu c...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sumbulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yaban-gulu', 'yaban-gulu-cemal-mercan-uoe2d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaban gülü osanda can sende kalmaz

Umut ya bozkurtta yada bozkurtta

Zaman böyle kalmaz yüz  böyle olmaz

Umut ya bozkurtta yada bozkurtta

Belki bu söze sen kanmayacaksın

Yıllar geçince sen anlayacaksın

Etrafa dost diye haykıracaksın

Çare ya bozkurtta yada bozkurtta

Seni yabangülü yapmış gönlüne

Ömründen alıpta katmış ömrüne

Bülbül gül misali düşmüş üstüne

Umut ya bozkurtta yada bozkurtta

                           Cemal MERCAN', 'Yaban gülü osanda can sende kalmaz Umut ya bozkurtta yada bozkurtta Zaman böyle kalmaz yüz  böyle olmaz Umut ya bozkurtta yada bozkurtta Bel...', ARRAY['Türk Edebiyatı','Şiir','Cemal Mercan']::text[], 8.5, '{"poet":"Cemal Mercan","poet_slug":"cemal-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaban-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdeniz Masalları I', 'akdeniz-masallari-i-onur-uysal-jgzks', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rivera küçük bir sahil kentidir.

Kentin masmavi bir denizi, 

     cıvıl cıvıl insanları, 

          ve şirin mi şirin bir limanı vardır.

Güneşin doğuşuyla her sabah, 

Küçük liman büyük insanlarla dolar.

Bu insanlar kaptanlardır, 

     yüreğini ortaya koyup

     açılan engin denizlere o yiğit insanlar…

“Kaptan olmak emek ister” der o yiğit insanlar

“tekneni iyi tanıyacaksın, 

     bileceksin, 

     nereye kadar gidilir, nelere dayanır, 

     motor sesinden derdini, 

     süzülüşünden keyfini

     anlayacaksın.”

Kentte eski bir inanış da vardır.

Gülüp geçer ya gençler, 

Hiçbir zaman şüphe etmemiştir eskiler.

“tekneler de kaptanlarını seçermiş” inanışa göre

Tutukluk yaparmış da kaptanı istemediğinde

Kıpır kıpır olurmuş geleni beğendiğinde…

Limanda kaptanların gözdesi bir tekne yeralır

Alımlı mı alımlı, 

     kıvrak mı kıvrak

          coşkun mu coşkun.

“O’nla açılmak denizlere bir zevk” der bütün kaptanlar.

“Coşkuyla açılır denizlere, 

     direnir dev dalgalara, 

          tutkuyla sarılır yeni yolculuklara…”

Dedik ya, kaptanlar tanır teknelerini, 

Adeta okur içinden geçenleri, 

Tutkusunu bilirler ya o teknenin, 

Kimse bilmez özlemini, 

Sakin denizlere demir atacak kaptanını beklediğini…

Limanda bir de kaptan yaşar

İşidir ya sakin denizlerde balık avlamak

Gözünde de tütmez değil

     engin denizlere açılmak

          ufuk çizgisinin ötesine varmak.

Düşünmek bile heyecan verir

dev dalgalarla boğuşmak

ve her tehlikeyi atlattıktan sonra

     huzurla teknesine uzanıp

          bir sigara yakmak.

Her sabah vardığında kıyıya, 

Gözleri arar alımlı tekneyi

Hissettirmez ya heyecanını

Özlemle bekler teknenin kıpırdanmasını

Yine de uzaklaşır arkasına bakmadan

     hayat kavgasına atılmak üzere ucundan

          yetinir gelecek balıklarla

               sakin denizlere attığı ağından…

Yıllar geçti liman kentinde, 

Kaptan biraz daha ustalaştı

     sakin denizlerde balık avlamakta

Tekne ise buldu kendini engin denizlerde

     buldu heyecanı başka başka kaptanlarda.

Fırtınalarla geçti son bir ay, 

Ve bir aydır çıkamadı kaptan

     sakin sulara

          balık avlamaya.

Seyretti bir ay boyunca her gün

     bembeyaz köpüklerini dalgaların

Düşledi heyecanını

     ufuğun ötesine varmanın.

Derken dindi fırtına, açıldı gökyüzü

Ilık bir rüzgar

Doldurdu kaptanın odasını

     engin denizlerdeki özgürlük rüyasını.

En güzel giysilerini giydi kaptan, 

Hayat kavgası yeniden başlıyor, 

Sakin denizler kendisini bekliyor.

Limanın girişinde, 

Bütün ihtişamıyla duruyordu o tekne

Salınıyordu usul usul ya

Dalga da hic yoktu denizde

Yavaşça yaklaştı kaptan kıyıya, 

Sadece bir adım kalmıştı

     tutkuyla düşlediği yolculuğa çıkmasına

Sadece bir adım kalmıştı

     ufukların ötesine varmasına.

“Artık çok geç kaptan, 

     çok geç artık açılmak için engin denizlere

          ufukların taaa ötesine”

Öfkeyle döndü kaptan, 

Eski bir dosttu bağıran

Sevindi ya bir eski dostu gördüğüne, 

     özlemle baktı hayallarinin yıkıntısına, 

          tutkuyla baktı ufukların ötesindeki

sevdasına…', 'Rivera küçük bir sahil kentidir. Kentin masmavi bir denizi,       cıvıl cıvıl insanları,            ve şirin mi şirin bir limanı vardır. Gün...', ARRAY['Türk Edebiyatı','Şiir','Onur Uysal']::text[], 8.5, '{"poet":"Onur Uysal","poet_slug":"onur-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/akdeniz-masallari-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz Hiç Kimse Yok', 'kimsesiz-hic-kimse-yok-avni-fatih-sultan-mehmed-upcr1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç kimse yok kimsesiz

Herkesin var bir kimsesi

Ben bugün kimsesiz kaldım

Ey kimsesizler kimsesi

*******

Kimse aradığım yollarda

Kimsesizlik kimsem oldu

Dinsin artık hicranın cana 

Kimse aradığım yollar

Kimsesiz kimselerle doldu

 Avni (Fatih Sultan Mehmed)', 'Hiç kimse yok kimsesiz Herkesin var bir kimsesi Ben bugün kimsesiz kaldım Ey kimsesizler kimsesi ******* Kimse aradığım yollarda Kimsesizlik...', ARRAY['Türk Edebiyatı','Şiir','Avni (Fatih Sultan Mehmed)']::text[], 8.5, '{"poet":"Avni (Fatih Sultan Mehmed)","poet_slug":"avni-fatih-sultan-mehmed","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kimsesiz-hic-kimse-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpmek', 'opmek-necip-fazil-kisakurek-zn1y7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerime uzanan dudaktan tepeyim; 

