INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reyhan Kokusu', 'reyhan-kokusu-mahmut-bingul-s65tt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir reyhan kokusu doluyor genzime

Ferahlıyorum! ...

Gözlerim seni arıyor

Seni kokluyorum sensizce.

Bir kanser çiçeği oldun kalbimde 

kopardıkça arasızlaşıyorsun

bitiveriyorsun tekrar yüreğimde

seni düşünüyorum seni 

bir de

sensiz olan bensizliğimi.', 'Bir reyhan kokusu doluyor genzime Ferahlıyorum! ... Gözlerim seni arıyor Seni kokluyorum sensizce. Bir kanser çiçeği oldun kalbimde  kopardı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/reyhan-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Mevsimi', 'hazan-mevsimi-adnan-toc-khpx2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hazan yaprakları dökülüyor

Sararmış solmuş, 

Bülbül artık şakımaz oldu

Yuvası tarumar olmuş.

Yağmur insafsız, 

Rüzgar insafsız, 

Kar insafsız.

Orda gönlü kırık biri var

Aşkı bitmiş, sevdası tükenmiş

Duyguları ile yapayanlız

Sevgili insafsız

Yıllar insafsız

Kader insafsız', 'Hazan yaprakları dökülüyor Sararmış solmuş,  Bülbül artık şakımaz oldu Yuvası tarumar olmuş. Yağmur insafsız,  Rüzgar insafsız,  Kar insafsı...', ARRAY['Türk Edebiyatı','Şiir','Adnan Toc']::text[], 8.5, '{"poet":"Adnan Toc","poet_slug":"adnan-toc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hazan-mevsimi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evler Var', 'evler-var-baris-akm-cypee', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evler var sıcacık

Perdelerinde bile güller açar

Odun istemez kömür istemez

Isınmaya yürekler yeter

Her köşesinde sevgi eser

Evler var ayaz mı ayaz

Perdeleri gül bilmez

Dünya yansa içinde ısınmaz

Ne odunu ne kömürü

Her köşesinde kasırga süngüsü

Evler var sis basmış odalarını

Belirsizliğe koşar çocukları

Bir yanda anası bir yanda babası

Sadece kütükte yazar hane numarası

Çoktan çökmüştür aslında çatısı', 'Evler var sıcacık Perdelerinde bile güller açar Odun istemez kömür istemez Isınmaya yürekler yeter Her köşesinde sevgi eser Evler var ayaz m...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/evler-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaca Ayazlar', 'alaca-ayazlar-baris-akm-jcv0v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün anlaşılan kelimelerin günü

Esmer olanların sanki düğünü

Bir nefese eklenir, bir cana karası

Her köşede ayrı ses, aynı sızının buğusu

Nedendir dersin soluk bu günün yüzü

Oysa bahar erkenden almış azıya gemi

Kırlar çiçek çiçek açarken kollarını

Kilitte tutulmak başka yakar kalbi

Zor gelir yaşamak bazen günleri

Şeytan der bir kurşuna yaz adresi

Ne bahar görsün seni ne sen baharı

Bir şehirsin unutulmuş sokakları

Daha dündü yıldızların umudu

Yaşadığın kaçıncı kıştı

Biliyorum canlansada baharın toprağı

Nisan yine dökmeyecek çiçeklerini

Boşuna değil kara bügün nefesimin sesi

Eski çağlara dayanır hikayemin kökeni

Yaşanacak günler güneşler o zamanda kaldı

Şimdi çiğnendiğim alaca ayazların ayakları

[email protected]', 'Bu gün anlaşılan kelimelerin günü Esmer olanların sanki düğünü Bir nefese eklenir, bir cana karası Her köşede ayrı ses, aynı sızının buğusu ...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/alaca-ayazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MESELA', 'mesela-baris-akm-hkjzc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O geçmiş zamanda geleydin ya

Harman zamanı ömrüme keşke

Hiç yaşamadan hüzünleri

Tanımadan acıların varlığını

Vuslatta kalmanın tadında

Yunus olmak ister miydim sanırsın

Uçsuz bucaksız denizlere 

Uçarcasına geçermiydi sarı zaman

Bu kurşuni akşamlar kadehlerden

Sızar mıydı gelseydik geç kalmadan

Bu şarkı bu denli hüzünlü olur muydu

Bu gözler böyle sis pus içinde

Kulak ses umar mıydı sanırsın

Geleydin zamanında, yıllar öncesinde

Mesela ayın ondördü, saat onikide

[email protected]', 'O geçmiş zamanda geleydin ya Harman zamanı ömrüme keşke Hiç yaşamadan hüzünleri Tanımadan acıların varlığını Vuslatta kalmanın tadında Yunus...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mesela-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Bulmuşsun', 'aski-bulmussun-furkan-birol-38x2v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'düşündüm günlerce bir başıma 

nasıl anlatmalıydım 

aşkı sana? 

şarkıyla mı anlatmalıydım şiilerimi

yoksa konuşarak mı bitirmeliydim bu işkenceyi

seni gördüğüm her gün 

bir güzelini daha buluyordum 

ve birdahaki sefere diyordum 

gunler geçti birdahalar geçti

duydum ki aşkı bulmuşsun 

birdahalar demeyen biriyle

bir yol daha olmalıydı

son bir yol daha

sana sevgimi anlatmanın bir yolu

mektubumu yazdım 

içine bir karanfil bıraktım 

kalbimi satırlara 

başımı darağacına astım...', 'düşündüm günlerce bir başıma  nasıl anlatmalıydım  aşkı sana?  şarkıyla mı anlatmalıydım şiilerimi yoksa konuşarak mı bitirmeliydim bu işken...', ARRAY['Türk Edebiyatı','Şiir','Furkan Birol']::text[], 8.5, '{"poet":"Furkan Birol","poet_slug":"furkan-birol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aski-bulmussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Çek Elini Sînemden!', 'cek-elini-s-nemden-mustafa-engin-karatay-pllrw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çek elini sînemden, yeter artık vicdânsız! 

Tükenmeyen zamânın, arlanmaz payandası! 

Kezzâb döktün umûda, çürüdü şimşir direk 

Taştan da olsa tartmaz, bu yükü Binbir yürek 

Kusmaya doymadın mı; zehrini be Engerek! 

Yılanlara şâh olsan, akrepler tutar yası 

Yakınlığın zamânsız, sokuşların ap-ânsız... 

Çöreklendin yoluma, senden kurtuluş yok mu? 

Hep sana takılıyor, fîrâr teşebbüslerim 

Sinmişlik duygusunu mağlûb edip yensem de, 

Hıncımla tekrar tekrar toparlanıp dönsem de, 

Kene gibi kandasın! Gölge gibi ensemde... 

İşkence kıskacında nâra atar hislerim 

Nerdesin ey Kıyâmet, o kutlu kopuş yok mu? 

Bırak beni kendime, çık mâsum düşlerimden! 

Sana âit ne varsa, götür berâberinde! 

Ölümsüz vakitlerde, candan can çekişlerin 

Sakız etti bağrımı, ısırdıkça dişlerin 

Kan rengini bastırır, o kıpkızıl şişlerin 

Kurtulursam pençenden eğer günün birinde; 

Uçarım sevincimden, ağlarım hünerimden... 

27.03.2002 Münih 04:25', 'Çek elini sînemden, yeter artık vicdânsız!  Tükenmeyen zamânın, arlanmaz payandası!  Kezzâb döktün umûda, çürüdü şimşir direk  Taştan da ols...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cek-elini-sinemden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gidimi', 'gun-gidimi-baris-akm-fkg96', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir güneş daha eksildi gün takviminden

Bu gece ay doğar mı dersin yeniden

Unuttum en son ne zamandı öptüğüm mehtabından

Epey geçti hançer gibi hilal oluşunun üstünden

O ne saplanıştı o öyle gözlerinin sadağından

Hala can sızar gövdemin kasnağından

Bir gün sonu gelecek biliyorum bekleyişimin

Evet, bir güneş daha geçti mavili şehirden

Yeni bir akşam üstü sunuyor yokluğun

Ve ben yine meyhanesindeyim hasretinin

Bir köşesinde ben, karşımda hayalin masamın

Ne gözlerin var, ne de benden haberin

Yine  elimde o kara-kaşlı kalem, içinde sen, 

Bu kaçıncıdır unuttum, kağıtlara yazık ediyorsun

Dört başı mamur olur meyhaneleri bu saatlerin

Güneş sancağını indirince sularına bir kadehin

Bir anda en büyük şairi olursun memleketin

Doğup büyüdüğün İstanbul''da gurbet yaşarsın

Vatan türküleri gibi yanık olur toprağın

Askerlik olsa şafakla der sayarsın

Saniyeleri bile asırlar sürer yokluğunun

Takvime uymazki bir bir çentik atasın

Yıldızlar gülecek mi dersin sabah olmadan

Bu deniz, bu boğaz çatlayacak mı bir gün

Sen gelecek misin dağlarından o gün

Bu Marmara''nın suları çekilir mi dersin

Yetmez mi sanırsın yakmaya gökleri bir selamın

Daha bunlar ne-ki hele bir gel sen

Ayağının pembe tozu bu bu limana bir dökülsün

Düşmanları dökecek deniz bulamazsın inan

Sen o zaman gör bir de beni, en hasını şiirin

[email protected]', 'Bir güneş daha eksildi gün takviminden Bu gece ay doğar mı dersin yeniden Unuttum en son ne zamandı öptüğüm mehtabından Epey geçti hançer gi...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gun-gidimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-ahmet-ataman-jjq4i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin büyülü bir fener, 

Sevgi yolumun tek kılavuzusun sen, 

Tüm yollarım sana çıkıyor artık, 

Dünyadaki tek ışığım yalnızca sen...

Gönlüme liman aramıyorum artık, 

Güneş doğsa da olur doğmasa da, 

Ne olur ki sana ulaşamazsam eğer, 

Işığınla gönlüme kattığın sevgin, 

Bana bin ömür boyu yeter...', 'Gözlerin büyülü bir fener,  Sevgi yolumun tek kılavuzusun sen,  Tüm yollarım sana çıkıyor artık,  Dünyadaki tek ışığım yalnızca sen... Gönlü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataman']::text[], 8.5, '{"poet":"Ahmet Ataman","poet_slug":"ahmet-ataman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozlerin-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ahmet-ataman-538gl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece ay ışığım, 

Gündüz ise güneşim, 

Papatya kokan saçların, 

Bakmaya doyamadığım gözlerin, 

Anladımki dünyaya, 

Nefes almak için değil, 

Seni sevmek için gelmişim...

Meğer hep seni özlemişim, 

Geceleri rüyamda görmüş, 

Adını çiçeklere vermişim, 

Anladımki dünyaya, 

Nefes almak için değil, 

Seni sevmek için gelmişim...', 'Gece ay ışığım,  Gündüz ise güneşim,  Papatya kokan saçların,  Bakmaya doyamadığım gözlerin,  Anladımki dünyaya,  Nefes almak için değil,  S...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataman']::text[], 8.5, '{"poet":"Ahmet Ataman","poet_slug":"ahmet-ataman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-137-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayboluş', 'kaybolus-ahmet-ataman-wkl8v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürek acısıyla tanıştım, 

Ne olduğunu bilmiyormuşum, 

Güzel gözlerine bakarken, 

Yüreğimi sende unutmuşum...

Farkına varamamışım meğer, 

Ellerinde kaybolup, 

Saçlarında uyumuşum, 

Kalbini çalmak isterken, 

Ben sende kaybolmuşum...', 'Yürek acısıyla tanıştım,  Ne olduğunu bilmiyormuşum,  Güzel gözlerine bakarken,  Yüreğimi sende unutmuşum... Farkına varamamışım meğer,  Ell...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataman']::text[], 8.5, '{"poet":"Ahmet Ataman","poet_slug":"ahmet-ataman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kaybolus-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-ahmet-ataman-v442b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle, rüyalarımda buluştum, 

Bulutları serdim ayaklarına, 

Tüm çiçekleri saçlarına kondurdum, 

Ilık rüzgarlar gibi nefesinle, 

İçime sığmayan sevgime yeniden kavuştum...', 'Seninle, rüyalarımda buluştum,  Bulutları serdim ayaklarına,  Tüm çiçekleri saçlarına kondurdum,  Ilık rüzgarlar gibi nefesinle,  İçime sığm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataman']::text[], 8.5, '{"poet":"Ahmet Ataman","poet_slug":"ahmet-ataman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seninle-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-yusuf-pangal-04xkg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tozpembe bir hayal içre dalmışım; 

Eserken ölümün soğuk yelleri.

Bomboş sokaklarda yalnız kalmışım; 

Ellerim... Üstünde yarin elleri.

Tozpembe bir hayal içre dalmışım, 

Akşam bir yaz kadar sıcak esmekte; 

Halimi derinden alıp, salmışım.

Azrail önümü çabuk kesmekte.

Tozpembe bir hayal içre dalmışım; 

Tutmuşum yolumu yolun sonuna, 

Herkesin derdinden bir dert almışım.

Ne zaman varırım, acep limana? 

Aldımsa kederden bir parça hüzün, 

Dert bahçelerimden bir dert çalmışım.

Ölümü sevdiğim anda ben bugün; 

Tozpembe bir hayal içre dalmışım.', 'Tozpembe bir hayal içre dalmışım;  Eserken ölümün soğuk yelleri. Bomboş sokaklarda yalnız kalmışım;  Ellerim... Üstünde yarin elleri. Tozpem...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Pangal']::text[], 8.5, '{"poet":"Yusuf Pangal","poet_slug":"yusuf-pangal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sarki-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı Yar', 'nazli-yar-pir-sultan-abdal-a9ryt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nazlı yare selam saldım almamış

Almazsa gam değil almayıversin

nazlı yarde bana selam salmamış

Salmazsa gam değil salmayıversin

İstemem kaşların kara ise de

Ciğerden yüreğim pare ise de

Melhemi derdime çare ise de

Çalmazsa gam değil çalmayı versin

Yıktı viran etti gönül tahtımız

Ta e, zelden kara imiş bahtımız

Böylemiydi ikrarımız ahdımız

Gönül hayaline gelmeyiversin

Doksana vardı da yüz geçti ise

Aradan ahd aman söz etti ise

Pir Sultan Abdal''dan vazgeçti ise

Bergüzar saldığım elmayı versin', 'Nazlı yare selam saldım almamış Almazsa gam değil almayıversin nazlı yarde bana selam salmamış Salmazsa gam değil salmayıversin İstemem kaşl...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nazli-yar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''ya Giden Gemi', 'ankara-ya-giden-gemi-mehmet-sercan-tezcanoglu-611pc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kış geçip gitmek üzereyken 

Genç kız yürüdü denizin üstünde 

Deniz yürüdü 

Sarayburnu, Boğaziçi 

Boğaziçi yürüdü İstanbul''un içine 

Küçücük bir gemi ansızın 

Denizin içinde 

Genç kız gemide 

Ankara''ya yürüdü. 

Yürüdü durmadan gemi, 

gecenin içine.', 'Kış geçip gitmek üzereyken  Genç kız yürüdü denizin üstünde  Deniz yürüdü  Sarayburnu, Boğaziçi  Boğaziçi yürüdü İstanbul''un içine  Küçücük ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ankara-ya-giden-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binbir Gece', 'binbir-gece-mehmet-sercan-tezcanoglu-x275g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırışır fikrimin ince gülleri 

Yaprakları buruşur 

Çıkarır dikenini gönlümden 

Yetişir 

İmdadıma engereğin sivri dişleri 

İfrit görünür göze 

Tutulur dilleri 

İçimi kurtlar kemirir 

İçirir 

Büyülü aşk iksiri 

Tutuşur, çamurdan Afrodit heykeli 

Tutuşur iki kalp 

Güvercinler uçar içimden 

Öpüşür 

Kaybolur martı leşleri 

Açılır kapısı, güzellik yurdunun 

Serer on üç dilberi 

Çırpınır balıkları susuz gölümün 

Kamaşır 

Bin bir gecenin uykusuz gözleri', 'Kırışır fikrimin ince gülleri  Yaprakları buruşur  Çıkarır dikenini gönlümden  Yetişir  İmdadıma engereğin sivri dişleri  İfrit görünür göze...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/binbir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biryerlerde biri', 'biryerlerde-biri-mete-parlar-4ptqt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Simdi bir seyahat

denize dogru, 

uzun uzun

icine cekmek

o havayi, 

hayallere dalmak

yildizlara bakip

sevdigine sarilip

usul usul

yasadigina sevinmek

bahtiyarligini

tatmak

sevmenin

ve

sevebilmenin

biryerlerde

birinin

oldugunu bilmenin...', 'Simdi bir seyahat denize dogru,  uzun uzun icine cekmek o havayi,  hayallere dalmak yildizlara bakip sevdigine sarilip usul usul yasadigina ...', ARRAY['Türk Edebiyatı','Şiir','Mete Parlar']::text[], 8.5, '{"poet":"Mete Parlar","poet_slug":"mete-parlar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/biryerlerde-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-sureyya-turkmenli-zn2vc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle zorki ardından 

akşamlara sormak seni

aramak çaresiz yorgun

son gölgelerde hayalini

öyle zorki dört mevsim 

yokluğuna dayanmak

gelecekten umutsuz

anılarla yaşamak

öl ölebilirsen hadi

bitsin yaşam denen saltanat

güneş sensiz batıyor 

sabah sensiz doğacak', 'Öyle zorki ardından  akşamlara sormak seni aramak çaresiz yorgun son gölgelerde hayalini öyle zorki dört mevsim  yokluğuna dayanmak gelecekt...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Türkmenli']::text[], 8.5, '{"poet":"Süreyya Türkmenli","poet_slug":"sureyya-turkmenli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ardindan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sekiz', 'sekiz-can-yucel-9mya2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün Ondokuz Mayıs, 

Mayısın ondokuzu! 

Sen ey Türk ülkemizin geleceği, 

Ulusumuzun gözbebeği, 

Sen ey demirparmaklıklarda barfiks yapan, 

Ranzalarda parende atan

Sportmen ve kahraman Türk gençliği, 

Önünde senin bütün Kilit-bahirler açık, 

Ama her zaman Samsun''a çıkılmaz ya, 

Bu sabah da avluda volta atmaya çık!', 'Bugün Ondokuz Mayıs,  Mayısın ondokuzu!  Sen ey Türk ülkemizin geleceği,  Ulusumuzun gözbebeği,  Sen ey demirparmaklıklarda barfiks yapan,  ...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sekiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer Gülüp Geçmişim', 'meger-gulup-gecmisim-yildirim-turker-s1y7k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Meğer Gülüp Geçmişim

İncitmeden hüzünle

Okşuyorum anıları

Nasıl da gençtim

Kaygısız ve şehvetli

Gece kaçamakları

Gizli buluşmalardan

Vaktim yoktu sanki

Saymaya aşkları

Yıllar sonra şimdi

Anlıyorum o çocuğu

Bir yaz akşamı

Kucağımda ağlayan

Okşayıp altın saçlarını

Gülüvermiştim

Meğer gülüp geçmişim

Aşkın yanından

Sonradan vurur dehşeti

Yiten şeylerin

Bedeli işlediğin her cinayetin

Bakarsın kalmamış sana

Ağlayacak kucak

Meğer gülüp geçmişin

Aşkın yanından

Şimdi o kederli akşam

Çökerken üstüme

Hayatım akıp

Gidiyor ellerimden

Bir yaz akşamı

O çocuğun saçları gibi

Yıldırım Türker', 'Meğer Gülüp Geçmişim İncitmeden hüzünle Okşuyorum anıları Nasıl da gençtim Kaygısız ve şehvetli Gece kaçamakları Gizli buluşmalardan Vaktim ...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Türker']::text[], 8.5, '{"poet":"Yıldırım Türker","poet_slug":"yildirim-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/meger-gulup-gecmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost''a Sitem', 'dost-a-sitem-haci-osman-ayyildiz-qwwdi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve...

İşte geldi zamanı

Kalkıyor ayrılık treni

Nice aşkları yanında götürürken 

öyle kibirli öyle acımasız

Nasılda gülüyor dertsiz ve gamsız...

Sen binmiş trene gidiyorsun! 

Geride kalan için gözyaşı bile dökmüyorsun

Bu nasıl sevgi anlayışı Allah''ım? 

Birde üstüne üstlük gülüp eğleniyorsun

Oysa neler demiştin bana: 

''Sensiz hayat bir yana

Ayrılık bile gelmesin aklına

Dayanamam bu acıya

Kıyarım acımadan canıma''

Demek sevgin gibi sözlerinde sahteymiş

Aşk senin için büyük bir eğlenceymiş

O o gözyaşların bile uymuş senin yalanlarına

Akmış bunca zaman boşu boşuna

Dedin ya bana ''unuttum seni''

İşte o an 

Canlı canlı mezara koydun beni

Anladım ki hak etmedim ben 

Senin sevgini

Ya da seni sevmeyi...

Sanki bir hançer sapladın kalbime

Vurdun acımasızca beni

Eğer vursaydın kalbimdeki seni

İşte o zaman gerçekten öldürmüş olurdun beni.

Sen unuttun demek bütün geçmişi

Kolay olmuş anlaşılan 

Kolay mı unutmak gerçekleri

Söyle bende bileyim yöntemini

Belki o zaman unuturum seni

Ama şunu bilki 

Ben seni Dün sevmedim

Ben seni bugün de sevmedim

Ben seni yarın sevdim.

Çünkü yarınlar hiç bitmezmiş

Benim sevgimde ömrümün sonunda bitecek.

Sen yoksun artık yanımda 

Bana kalan 

Yırtık bir resimle bomboş bir oda.

Yıkık dökük duvarlar bide.

Evet duruyor eskisi gibi

Senin kokun sinmiş vaziyette

Sana yazdığım şiirlerle birlikte...

Alışmaya çalışıyorum yalnızlığıma

Uykusuz geceler sırdaşım olmuş

Karanlık günler ise kabusum.

Bilmem sen şu anda orda mutlu musun

Allah daima yanında bulunsun

Bu sana son sözüm 

Sen 

Sevgi nedir bilir misin? 

						Geçmişini silen sahte dostlara...', 'Ve... İşte geldi zamanı Kalkıyor ayrılık treni Nice aşkları yanında götürürken  öyle kibirli öyle acımasız Nasılda gülüyor dertsiz ve gamsız...', ARRAY['Türk Edebiyatı','Şiir','Hacı Osman Ayyıldız']::text[], 8.5, '{"poet":"Hacı Osman Ayyıldız","poet_slug":"haci-osman-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/dost-a-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-haci-osman-ayyildiz-ao80v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçükken masallar anlatırdın bana

İçinde hep sevgi, hep hasret bulunan

Sonunda ise o bildiğimiz mutlu son.

Ben şimdi gurbetteyim; 

Tek başıma, yalnız, darmadağın.

Ellerim ellerini arıyor; 

Gözlerim gözlerini...

Küçük yüreğim sevgini...

Ben şimdi gurbetteyim; 

Sen nerdesin anne! 

Mutlu değilim eskisi kadar

Her anım hüzün ve zarar

Sevgiye saygıya muhtaç

Köhne yüreğim seni arar

Ben gurbetteyim

Sen neredesin anne! 

Hatırlar mısın eski günleri

O çocukluk günlerimi

Konuşmaya başladığım günü

Yürüyüp sana koştuğum anı

Hatırlar mısın şimdi.

O günleri özlüyorum anne

Sana koşmayı

Annem deyip sarılıp ağlamayı

Sevgimi seninle paylaşmayı özlüyorum.

Seneler geçip de okula başlamıştım

Sen beni okuldan hep kıskanırdın

Okuma aşkı bana seni unutturur diye

Senin sevgin neye değişilir anne! 

Kim verebilir bana o sevgiyi

O iyi niyeti ve insanları sevmeyi...

Şimdi gurbetteyim

Hasret girdi aramıza anne

Ayırdı bizi birbirimizden

Hem de benim için çok erkenken

Evet anne gençliğim seni özlemekle

Her an ve her yerde ağlamakla

Sana kavuşamamanın ezikliği içinde

Elini tutamamanın burukluğuyla geçiyor

Ne zamana kadar dayanır yüreğim bilmem

Her gece rüyamda seni görür oldum anne

Yine eskisi gibi güzel

Eskisi gibi neşeli 

Eskisi gibi sevecensin.

Sesleniyorum sana 

Duyuramıyorum sesimi anne

Ağlamam yakarmam gelmiyor sana

Elimi uzatıyorum 

Yeniden dokunabilmek

Yeniden o sıcacık elini tutabilmek

Çok uzak geliyor bana anne! 

“Okul nasıl gidiyor yavrum”

diye soruyorsun annem

hissediyorum bunu

çok iyi anne merak etme

ben hala başı dik, alnımın akıyla

şerefimle ve namusumla, 

vatana hayırlı bir insan olmak için

çaba sarf ediyorum anne! 

“halin nasıl” diye hiç sorma anne

saçlarım ağardı, yüreğim yoruldu

gözlerime yaş yerine kanlar doldu

hasret acısı beni sırtımdan vurdu

kısacası

gençliğim elden gitti

çünkü ben gurbetteyim 

sen 

sen nerdesin anne! 

Bizim buralar karışık anne

Her gün bir olay

Her gün  bir vukuat var 

Polis jandarma sürekli tepemizde anne

Evimize gitmek bize bir işkence

Bazen karakolda geçiyor gece

Cop yiyoruz günlerce

Biliyor musun anne

Beni bunların acısı değil de

Aramızda olan o kahrolası

Bilmem kaç kilometre

Hasret, ve sevgisizlik yakıyor anne! 



Kışlar soğuk oluyor burada

Sürekli yağmur ve kar

Yoları açmaya imkan mı var? 

Telefonlar bile kilitlendi

Ulaşım çok zor

Umutlarım bahara kaldı anne

Oysa ne hayaller kurmuştum

Gün batmadan yanında olmuştum

O güzel sesini duymuştum

Huzur ve rahata kavuşmuştum

Ne yazık ki bunlar sadece

Hayallerimde kaldı anne! 

Düşünüyorum anne

Düşündükçe kahroluyorum

Seni göremeden yaşamak

Kadere sitem ettiriyor anne

Seni sensiz yaşamak

Yüz defa Bin defa milyon defa 

Beni öldürüyor anne! 

Hayatım yanıp tükeniyor 

Umutlarım birer birer yok oluyor

Gençliğim gençliğim elden gidiyor

Ben şimdi gurbetteyim 

Sen nerdesin anne! 

Sesimi duymuyor musun anne! 

Beni özlemiyor musun anne! 

Seni seviyorum 

Seni seviyorum anne!', 'Küçükken masallar anlatırdın bana İçinde hep sevgi, hep hasret bulunan Sonunda ise o bildiğimiz mutlu son. Ben şimdi gurbetteyim;  Tek başım...', ARRAY['Türk Edebiyatı','Şiir','Hacı Osman Ayyıldız']::text[], 8.5, '{"poet":"Hacı Osman Ayyıldız","poet_slug":"haci-osman-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":108,"source_url":"https://www.antoloji.com/anneme-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle', 'bekle-konstantin-simonov-xhwgx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekle beni, döneceğim ben.

Çok çok, bıkmadan bekle! 

Sarı yağmurların

Hüznü basınca, 

Kar kasıp kavururken, 

Kızgın sıcaklarda.. bekle.

Başkaları dünden unutulmuşken, 

Beklenmedikleri zaman bekle.

Uzak yerlerden mektuplar kesilince

Bekle beni.

Birlikte bekleyenlerin beklemekten

Usandığına bakma, bekle.

Bekle beni, döneceğim.

Unutmak zamanı geldiğini

Ezbere bilenleri

Hayırla anma! 

Varsın oğlum, annem

Hayatta olmadığıma inansın, 

Dostlarım beklemekten usansın, 

Ocak başında toplanıp

Acı şarapla 

Yadetsinler beni

Sen bekle, onlarla birlikte 

İçmekte acele etme.

Bekle beni; döneceğim, 

Bütün ölümleri çatlatmak için döneceğim! 

''Şansın varmış..'' desinler.

Beklemedikleri için, 

Beni bekleyerek

Düşman ateşinden

Nasıl koruduğunu anlayamazlar.

Sağ kalışımın sırrını yalnız 

Senle ben bileceğiz..

Bütün sır.. senin 

Başkalarının bilmediği gibi beklemeyi bilmende.

(Çev.: N.Yalaza Taluy)', 'Bekle beni, döneceğim ben. Çok çok, bıkmadan bekle!  Sarı yağmurların Hüznü basınca,  Kar kasıp kavururken,  Kızgın sıcaklarda.. bekle. Başk...', ARRAY['Türk Edebiyatı','Şiir','Konstantin Simonov']::text[], 8.5, '{"poet":"Konstantin Simonov","poet_slug":"konstantin-simonov","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bekle-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-haci-osman-ayyildiz-3aii6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tarifi imkansız hisler içinde

Seviniyor... coşuyorum şu anda

HARPUT görünüyor... HARPUT sisler içinde

Yollarına...yollarına düşüyorum şu anda

	Niyet ettim daha yola çıkmadan

	Geçilir mi Malatya’yı görmeden

	KÖMÜRHAN’da bir çay içip durmadan

	BASKİL’deyim şaşıyorum şu anda

BASKİL’de hasretimi çözer gibiyim

Sanki, sanki Bakır MADEN’de gezer gibiyim

KEBAN’ı okşayan MURAT gibiyim

Kabarıyor şişiyorum şu anda

	Can MADEN’de kabaran yürek

	Durmaz artık yolcu yolunda gerek

	Ver elini güzel AĞIN diyerek

	Dağlarını, yollarını aşıyorum şu anda

Güzel AĞIN’dan çıkıp KEBAN yoluna

Hankendi... Yolçatı’dan GAKKOŞ eline

Yeşil FIRAT olup HAZAR  gölüne

Dolup... dolup taşıyorum şu anda

	Ben taşarken PALU ile SİVRİCE’lim susuyor

	ALACAKAYA ya da ARICAK’a varmazsam onlar küsüyor

	MASTAR dağlarından Meltem esiyor

	Tatlı... Tatlı üşüyorum şu anda

Üşüsem de gidiyorum köyüme

Tekevlerden sonra yıkık MADEN’e

Mazideki gibi binip kara trene

Sılam... Sılam deyip yanıyorum şu anda

	Çünkü sıla bir mübarek kucaktır

	Ana kucağından daha... daha sıcaktır

	Ahmet Hoca’ya yana bana ait ocaktır

	O, ocakta...yanıyorum, pişiyorum şu anda

Mübarek HARPUT’umun erleri de pişmişler

Onlar Horasan’dan, Harput’uma düşmüşler

Hepside birer ışık, bir güneşmişler

Nurlarında... nurlarında ışıyorum şu anda

	Nurlarında ışıyorken işte tam

	Gam bürüyor yüreğimi yine gam

	ÇEMİZGEZEK, PERTEK VE KARAKOÇAN

	Yaranızı... yaranızı, sarıyorum şu anda

Yaralı, yaralı gönül yürüyor

Geri dönüp ta... MADEN’e varıyor

Rahmet-i Rahman’a erenler gel, gel ediyor

Mezarımı, kendi mezarımı kazıyorum şu anda

	Mezar eşmek korkutmuyor beni pek

	Çok... mezarlar eştim bugünlere dek

	MADEN’i...PALU’yu HARPUT’u tek tek

	Göz yaşımla... göz yaşımla suluyorum şu anda

Göz yaşım gıdasıdır güzel sılamın

Ahmet Hoca, doruğunda murat almanın

ELAZIĞ’lı olmanın GAKKOŞ olmanın

Gururunu, gururunu yaşıyorum şu anda

Gururunu yaşıyorum şu anda...', 'Tarifi imkansız hisler içinde Seviniyor... coşuyorum şu anda HARPUT görünüyor... HARPUT sisler içinde Yollarına...yollarına düşüyorum şu and...', ARRAY['Türk Edebiyatı','Şiir','Hacı Osman Ayyıldız']::text[], 8.5, '{"poet":"Hacı Osman Ayyıldız","poet_slug":"haci-osman-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/hasret-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narçiçeğime', 'narcicegime-ahmet-ozturk-su6tl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kan boyamış sanki sana adadığım güllerimi 

bu bahçeler saçtığın sevda tohumlarıyla doldu bir bahar boyu

sen ağlamadan duracağın bir durak bulamadın

ben dar sokakları aşamadım bu bahçelere gelip de

sevda tohumlarının filizlerini görmeye

(02: 16) 

(20 temmuz 2001-cuma) 

(BOSTANCI)', 'kan boyamış sanki sana adadığım güllerimi  bu bahçeler saçtığın sevda tohumlarıyla doldu bir bahar boyu sen ağlamadan duracağın bir durak bu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/narcicegime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayattan Bi Kare', 'hayattan-bi-kare-yusuf-sabri-bagriacik-kvrkj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ışıklar, üzerime doğruda gelse

gözlerim kamaşmadan, ilerliyebiliyorum hayatta.

bakıyorum da arkama

tüm ışıklar geldikleri gibi gidiyorlar.

dayanmanın, mücadele vermenin

önemini anımsıyorum uzun bi aradan sonra.

ben uzun bi aradan sonra ilk kez

senin için mücadele veriyorum.

görüyorsun ki, ismini saklıyorum bu şiirde

ama o yeşil gözlerini, 

ama o ıslak saçlarını saklamak mümkün olmuyor.

öylesine yorgunum ki şimdi

sana seslendiğim yeri görsen

şaşırır kalırsın

sanki yeşiller içinde bi kır bahçesinden sesleniyorum sana

ama alakası yok.

çevremde yeşil insanlar var

sadece gözlerini gösteriyorlar bana

sema hemşire de

o da sadece gözlerini gösteriyor bana

aslına bakarsan ıslak saçlım, 

gözleri her şeye de yetiyor ama...

bi tuhaflık var üzerim de 

tepki veremiyorum ona...

ne yaptın bana diyorum

az sonra diyor

az sonra, bi film biticek diyor

sen hep sonunu hatırlamaya çalışacaksın diyor

ben bi daha sema hemşireyi hiç görmüyorum.

ama seni hala yazmaya devam ediyorum kadınım

dedim ya

bi tuhaflık çöktü üzerime

ilk değil, ikinci kezdir oluyor

şimdi öylesine yorgunum ki, 

daha fazla yazamayacağım sanırım.

beni affedersin dimi

inanamıyorum yaşadıklarıma... 

tam, seni en iyi anlatmaya başladığım şiiri yazarken

narkoz veriyorlar bana

gözlerim sönmek üzere olan, bi mumu canlandırıyor

adını gizlediğim sevgilim, 

gözlerim kapanıyor, gözlerim.

üstüne üstlük bu sema hemşirenin oyun bozanlığı

beğenilmeye alışkın olmasa gerek

sakın yalnış anlama

ben, beğendiğimi sözlü olarak belirtmedim ki

gözlerimden anlamış olacak 

ki, heyecandan ne yapacağını şaşırdı

ve dayadı damarlarıma narkozu

gülünç bi durumdayım şimdi

sema hemşire de yok ortalıkta

sen zaten yoksun

içimdeki şiir de yok

olmaz tabii

verirlerse bi şaire, şiir yazarken narkoz

olacağı budur

bizim ülkemiz de artık bu da oluyor sevgilim.

şaire de saygı yok artık bu ülkede

ben sana gösteririm sema hemşire

eger ben de sana 

günün birinde

aynı narkozu vermezsem, şiirlerim de

adımı değiştiririm.

aslına bakarsan sema hemşire

o hatırladığım gözler sen de olmasa 

sana çok daha kızgın olucam ama 

sen o gözlerine dua et.

o kadar güzeldiler ki 

ha bu arada

sen yanlış anlama sevgilim

hayatım onun ellerindeydi ya

o sebepten, 

teşekkür maksatlı iltifatlarda bulunuyorum

yaptıklarım bundan ibaret

gözlerinin güzel olması kimin umrunda 

sen de daha güzelleri var.

allah biliyo ya, 

bi tek beni çok iyi tanıyanlar anlar 

bu şiirdeki duygularımı

	Nisan 2002'' Bahçeşehir', 'ışıklar, üzerime doğruda gelse gözlerim kamaşmadan, ilerliyebiliyorum hayatta. bakıyorum da arkama tüm ışıklar geldikleri gibi gidiyorlar. d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/hayattan-bi-kare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım', 'unutamadim-omer-tirendez-ktzc1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatımın, tatlı  hatıralarıydı, 

 Yaşanması,  bir  daha güç  olanlardı.

 O  seneler  ne  güzeldi...

 Unutmadım , unutamadım...

 Seviyor, seviliyordum! 

 Hem  ölesiye, hemde  taparcasına.

 Aşkımız, bir  mutluluk  şarkısı.

 Unutamadım, unutamadım...

 Bakıyor, görüyordum! 

 Hem  külkedisi,  hemde  prensesi.

 Farketmez, onu  seviyordum...

 Unutmadım, unutamadım...

 Sevgi, mutluluk dolu

 Bir  ömür  paylaşmışsın

 Unutlurmu, kolay  mı  sandın? 

 Unutmadım , unutamadım...

 Sen , unuttun  gitinde, 

 Ben, kül  olup  bittimde, 

 Bir  daha  dönersin  diye, 

 Unutmadım, unutamadım...

 Nafile  gözyaşlarım, çektiğim  kahırlar.

 Gittin, belli  dönmeyeceksin, 

 Yaşamıyor, toprak  olmuşsun.

 Unutmadım, unutamadım...', 'Hayatımın, tatlı  hatıralarıydı,   Yaşanması,  bir  daha güç  olanlardı.  O  seneler  ne  güzeldi...  Unutmadım , unutamadım...  Seviyor, se...', ARRAY['Türk Edebiyatı','Şiir','Ömer Tirendez']::text[], 8.5, '{"poet":"Ömer Tirendez","poet_slug":"omer-tirendez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unutamadim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla', 'asla-kadir-celik-4q1bd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şarkı söylerdi cengiz hatırlıyormusun..

Yinemi sen, yinemi sen ne istiyordun benden

Her şeyimi aldın benden SEVEMEM SENİ YENİDEN

Evet her şeyimi aldın benden

Ufak bir çocuğun oyuncağını elinden alırsın ya

İşte sen kalbimi yüreğimi bedenimi hatta canımı...

Belki bedenim karşında 

Ama o beden yasamıyor

Derin sulardaki uzatma ağının gözlerindeki mezgitin                                                           İçini boşaltan yengeç gibi..', 'Bir şarkı söylerdi cengiz hatırlıyormusun.. Yinemi sen, yinemi sen ne istiyordun benden Her şeyimi aldın benden SEVEMEM SENİ YENİDEN Evet he...', ARRAY['Türk Edebiyatı','Şiir','Kadir Çelik']::text[], 8.5, '{"poet":"Kadir Çelik","poet_slug":"kadir-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/asla-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Umudu!', 'umudun-umudu-omer-tirendez-67igu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevginin , mertliğin  hasreti.

Huzurun  kaçtığı, aşkın  arandığı, 

Duygular  yok  olan  duygular...

Bu, bendeki   beni  aarayışımdı.

Akıl   sır  erdiremiyordum! 

Madem  faniydim, niçin  yaşıyordum? 

Bir sebebi  yok  muydu? 

Olmalıydı, umutlarım  vardı  zaten...

İnsanoğlu , yükselmek  amacında, 

Bir  yerlere , gelebilmenin  savaşında, 

Kimi  önde, kimileri  geride, 

Umutlarının  yolculuğunda...

Hayatım , bir  sınav  tadında, 

Bir  sınav , bir  yarış   içersinde, 

Arzularıma, kavuşmak için  didiniyorum, 

Bunlar  için yaşıyor  ve  ölecektim.

Ölmek  dedim de! 

Madem   öleceğim  be! 

Niçin  üzülürüm, boş  yere? 

Kafa  patlatırım, her  kedere...

Olanlaar, olmuş.Ben  ise; 

Dökülen  süte   ağlıyorum

Sanki, geri   gelecekmiş  gibi.

Nafile, giden  geri  gelmiyor...', 'Sevginin , mertliğin  hasreti. Huzurun  kaçtığı, aşkın  arandığı,  Duygular  yok  olan  duygular... Bu, bendeki   beni  aarayışımdı. Akıl   ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Tirendez']::text[], 8.5, '{"poet":"Ömer Tirendez","poet_slug":"omer-tirendez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/umudun-umudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gelin Gidelim! ..', 'hadi-gelin-gidelim-omer-tirendez-apubg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman, beni  götürürdü, 

İleri  gidiyordum, seviyeliydi.

Anılar , geriye  döndürdü, 

İrtifa  kaybettim, saniyesiydi...

Meğer, anıların  kötüsü,  iyisinde.

Kalmalıymış , geçmiş  zaman  eklerinde, 

Olanları,  bırakmalı insan geride, 

Dop dolu  yaşamalı, her  anı  ileride...

Bugünü, anında  yaşamalı, 

Dünü ,  geçmişte  bırakmalı, 

İçindeki, nasihatlar  alınmalı , 

İyisi , kötüsü  unutulmalı...

Bugünü yaşamalı, mutlu olmalı! 

Herkezi ,  çok  sevmeli, 

Kimseleri   üzmemeli, 

Yürüdüğümüz  ,  adımları  saymalıyız...

Bay  Ukala  ''nın  derdi  var! 

Büyüklerinden ,  biraz  izin  ister.

İzin  gelmişse,  dinleyin  dostlar; 

Hayat  bir  sınav, bir  yarış, 

Herkez toprak  ister , karış  karış, 

Hem  bu  dünya , hemde  öteki  dünya , 

Cennet  olsun  ister ,  kapış  kapış...

Biraz  olsun  sevelim,  sevilelim, 

İnsanlara  iylik   edelim.

Bu  dünya  kimseye  kalmaz, gidelim.

Doğruya , güzele, sevgiye   gidelim.

Gidelim  be  gidelim , ne  kaybederiz? 

Dostluğa , barışa, iyiye  gidelim.

Gidelim , hadi  gelin  gidelim...', 'Zaman, beni  götürürdü,  İleri  gidiyordum, seviyeliydi. Anılar , geriye  döndürdü,  İrtifa  kaybettim, saniyesiydi... Meğer, anıların  kötü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Tirendez']::text[], 8.5, '{"poet":"Ömer Tirendez","poet_slug":"omer-tirendez","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hadi-gelin-gidelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla', 'damla-enis-batur-x9br2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman, dolmakalemin kustuğu 

mürekkep damlasında biçim alır: 

Islak, aldığı ışıkla canlı, 
..........
..........', 'Zaman, dolmakalemin kustuğu  mürekkep damlasında biçim alır:  Islak, aldığı ışıkla canlı,  .......... .............', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/damla-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımızdan', 'canimizdan-paul-eluard-gpauw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsteğim yok seni sevmekten başka

Bir fırtına dolduruyor koyağı

Irmağı bir zehir

Seni yalnızlığımın boyunda yarattım

Saklanmaya yarattım bütün dünyayı

Kendimi kavramaya günleri geceleri

Görmek için yalnızca

Senin için

Tıpkı sana benzer bir dünya için düşündüğümü

Gözkapaklarınla düzen verilmiş günler geceler için.

(Çev.: Sait Maden)', 'İsteğim yok seni sevmekten başka Bir fırtına dolduruyor koyağı Irmağı bir zehir Seni yalnızlığımın boyunda yarattım Saklanmaya yarattım bütü...', ARRAY['Türk Edebiyatı','Şiir','Paul Eluard']::text[], 8.5, '{"poet":"Paul Eluard","poet_slug":"paul-eluard","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/canimizdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız', 'i-mkansiz-aysun-aksu-kif8d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İmkansızmıydı aşkımız

Olamazmıydı? 

Yetmezmiydi bana 

Bir gecelik mutluluk

Dudakta bir hatıra

Yürekte bir sızı

Yetmezmiydi bana

Kırılırmıydı kalbim

Üzülürmüydüm sonunda

Benim olmayan

Hiç olmayacağını bildiğim

Ama yine sevdiğim

Gururum kırılırmıydı

İncinirmiydim

Şu an yaşadığın

Mutsuzluk adına

Kullanırmıydın beni

Evet imkansızdı 

Bizim aşkımız aşkım

Yanlış bendeydi belkide..', 'İmkansızmıydı aşkımız Olamazmıydı?  Yetmezmiydi bana  Bir gecelik mutluluk Dudakta bir hatıra Yürekte bir sızı Yetmezmiydi bana Kırılırmıydı...', ARRAY['Türk Edebiyatı','Şiir','Aysun Aksu']::text[], 8.5, '{"poet":"Aysun Aksu","poet_slug":"aysun-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/imkansiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-i-lhan-yolcu-h5go3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittin... 

Kalbimde yer eden kocaman sevgi ile 

Günlerimin yaşamdaki anlık anlamları 

ve sevgimi kazanmış muzaffer bir 

Amazon edası ile uzaklaştın... 

Bence çaba gibi görünen 

ufak bir ağa takılmış

koca balina gibi 

çırpınışlarımı

görmedin giderken 

sana tanıdık gelmişti hepsi 

Tekrarlardan sıkılmış 

Artık kendin olmak istediğin için 

Beni sevdiğin 

ya da bunu ifade ettiğin halde 

Seni sen yapan geçmişine 

beni de katmak için gittin... 

Güçlü ve ayakta kalan gibi 

görünmeye çalıştın 

İçin için acılar yaşadığını hissediyordum 

Sana ulaşma gayretimdeki 

her hareket beni daha çok aşk acısına boğuyor 

Sen 

Daha da uzaklaşıyordun benden 

Çırpınarak bir bataklıkta 

çaresiz bir gergedan gibi hissettim. 

Durdurdum acıları

Kendimi 

Çırpınışlarımı tuttum. 

Bu ne kadar gerçekti. 

Biz ne kadr gerçektik? 

Aşkımızın damarlarında kangren olmuştuk 

Kesip atmayı seçtin 

Sen mi seçtin? 

İstedin mi sanki bu eksilmeyi? 

Hayatına beni katarak gidişine 

Saygı ile bakmayı öğrendim bunca zamanda 

Seni sevgili olarak sevmenin 

Senden aynı aşkı almış olmanın hazzıyla 

Gidişini izledim 

''Sessiz gemi'' gibi 

Ne bir kol vardı gidişinde 

Ne de bir mendil 

İstemediğim bu gidişe sadece 

Islanmamış 

ağlayan gözlerle baktım... 

ŞUBAT 2002', 'Gittin...  Kalbimde yer eden kocaman sevgi ile  Günlerimin yaşamdaki anlık anlamları  ve sevgimi kazanmış muzaffer bir  Amazon edası ile uza...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yolcu']::text[], 8.5, '{"poet":"İlhan Yolcu","poet_slug":"i-lhan-yolcu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gittin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsancıklar', 'i-nsanciklar-gece-karasi-y6jcb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İNSANCIKLAR

Dost sandığım nicelerini, 

Anlamaya calıştım olmadı.

Bildiğim tek şey şimdi, 

Dostluk o denli yalanmış.

Dost sandığım  insancıklarmış.

Bağrıma bastığım icin, 

Yüreğimi actığım icin, 

Her yüze güleni, 

Dost sandığım icin, 

Bildiğim tek şey var şimdi, 

Dostluk o denli, yalanmış.

Dost sandığım insancıklarmış, 

Kendimi  suclamışım boş yere, 

Sizlere acırım insancıklar, 

Bir hicmiş dostluğunuz

Üzülmeye değmezmiş yokluğunuz, 

Bildiğim tek şey şimdi, 

Dostluk o denli yalanmış! 

Dost sandığım insancıklarmış.: ((

gece karası     2002      İstanbul', 'İNSANCIKLAR Dost sandığım nicelerini,  Anlamaya calıştım olmadı. Bildiğim tek şey şimdi,  Dostluk o denli yalanmış. Dost sandığım  insancıkl...', ARRAY['Türk Edebiyatı','Şiir','Gece Karası']::text[], 8.5, '{"poet":"Gece Karası","poet_slug":"gece-karasi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/insanciklar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-kamil-aydemir-81u9t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'anneler gününde sana gül alabildim ancak

ve her yaprağına sevgimi gömdüm sımsıcak

gül sana yakışır anne

                                 gülmekte

senin o sevgi küpü kalbini kırmamak

hediyelerin en büyüğüdür

bize yakışır bunu bilmekte', 'anneler gününde sana gül alabildim ancak ve her yaprağına sevgimi gömdüm sımsıcak gül sana yakışır anne                                  gül...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anne-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Okuluna Benziyorsun', 'koy-okuluna-benziyorsun-kamil-aydemir-a41ku', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'duvarları ellerin gibi çatlak

çatısında kiremitleri eksik

camları kırık

ama içerisi aydınlık

değeri bilinmemiş

köy okuluna benziyorsun

olsun

sen bana aşkı öğretiyorsun

yalçın dağlara uzanan

tozlu yolar gibi zorsun

olsun

sen mutluluğuma çıkan yolsun', 'duvarları ellerin gibi çatlak çatısında kiremitleri eksik camları kırık ama içerisi aydınlık değeri bilinmemiş köy okuluna benziyorsun olsun...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/koy-okuluna-benziyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyle', 'sevgiyle-suna-gunes-1oll9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bulutlarla  ninni söyler gökyüzü

yıldızlardan çarşaf serer gecelere

sevgi öpücüğü kondurur çiğ taneleri

bir prens uyutsam göğsümde 

güneş doğmaya kıyamazdı

sabah ertelerdi kendisini sevgiyle

sevda bülbülleri öterdi sadece seherde

bir prens  uyutsam göğsümde', 'bulutlarla  ninni söyler gökyüzü yıldızlardan çarşaf serer gecelere sevgi öpücüğü kondurur çiğ taneleri bir prens uyutsam göğsümde  güneş do...', ARRAY['Türk Edebiyatı','Şiir','Suna Güneş']::text[], 8.5, '{"poet":"Suna Güneş","poet_slug":"suna-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgiyle-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odanda Tek Başına', 'odanda-tek-basina-cezmi-ersoz-xp8bx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz seninle hep bayağılıktan kaçtık... Sıradan, basit, gündelik olandan. 

Küçük mutlulukları, hayatın içindeki o kanaatkar doyumları değil, hep 

trajediyi aradık. Mükemmeli... Biz seninle hep kusursuzluğu aradık.

Bizi birbirimize yakınlaştıran ne varsa hep kutsaldı, özeldi, 

ayrıcalıklıydı. İlişkimizden aslında ikimize de ait olmayan, kutsal ve 

kusursuz bir imge yarattık. Hayatımızda eksik kalmış ne varsa, o yarım 

kalmış tutkularımızı o yaralı arzularımızı, eksik çocukluğumuza ait ve 

içtenlikle koruyamadığımız bütün duygularımızı bu imgeye ödünç verdik. Artık 

yaşayan gerçek kişiliklerimiz değil, sanki bu kutsal, bu kusursuz imgeydi.

Bu imge lekelenmesin, bu düş bozulmasın diye öyle çok şey gizlerdim ki 

senden. İçim ürperirdi böyle anlarda, kendimden çok uzak bir yere çekilirdim 

sanki, bilinmezliğe... Aramızda öyle çok tanımlanmamış anlar, öyle kopuk, 

öyle başıboş duygular, bana o denli ait olduğu halde nasıl anlatacağımı 

bilemediğim öylesine derin savruluşlarım vardı ki...

Yarattığımız ve aşk adını verdiğimiz bu kutsal imgeye sadık kalabilmek için 

kendime karşı sadakatsiz davranıyordum.

Seninle yanyana uzanırdık, dünyanın dışındaki yaz bahçelerinde, o gerçekdışı 

mevsimlerin kıyılarında... Üzüntülerimiz, içimizdeki yaralar yanyana dururdu 

öyle. Bizden çok bu yaralar özlerdi birbirini, o kimsesiz üzüntülerimiz...

İçimdeki yaram senin yaranı özledikçe ruhumun gurbetlerinde daha çok 

hissederdim kendimi... Asıl çektiğim acı buydu aslında, yanındayken kendimi 

yine de senden çok uzaklarda hissetmemdi.

Farkederdin sürükleniş suskunluklarımı. Böyle anlarda zamanı durdurmak 

isterdin. Zamanı dondurdukça içimizdeki boşlukların kapanacağını, o gizli 

ürpertilerin dineceğini, tanımlanmamış anların ve o kopuk, o başıboş 

duyguların tanımlanacağını, savrulmaların biteceğini düşünürdün. Zamanı 

dondurunca hep iyi ve mükemmel insanlar olarak kalacağımızı sanırdın. Hayata 

bu donmuş zamandan, bu mağrur ve korunaklı kristalin ardından bakınca hiç 

kirlenmeden ve ebedi bir saflık halinde yaşayacağımızı hayal ederdin.

Oysa ne zamandan kopabiliyor, ne de hayattan gizlenebiliyorduk. Biz zamandan 

kopmak istedikçe zaman bizi daha çok acıtıyor; hayattan gizlendikçe o 

kendisini daha çok hatırlatıyordu. Hayattan ve kendimizden korktukça 

kendimizi aşkın kutsal acısına kapatıyorduk. Hayat acı verdikçe biz o 

kutsal, o ayrıcalıklı kıldığımız acımıza daha bir sarılıyorduk. Bu kutsal 

ıstırap bizi hayattan korurken başkalarından üstün kılıyordu.

Oysa kutsallık hiç saf değildir sevgili; gücünü zayıfların kanından alır. 

Mükemmellik, kaybedeni çok, anlamsız ve haksız bir yarıştır. Saflığın içinde 

birçok günah gizlidir. Ben bu kutsal aşkın kan kaybeden zayıfıydım işte. Bu 

kötü yarışta hep kaybedendim. Saflıktı benden istediğin, ama saklayamazdım 

kendimden, içimde birçok günah gizliydi. Ben kaybettikçe yarattığımız o 

kutsal imge sana ait oldu. Ben günahı kabullendikçe kusursuz ve mükemmel 

olan sen oldun. Oysa kendisini diğer insanlardan biraz olsun farklı ve özel 

sayan her insana zor gelir hayatın o basit, o sıradan dertleri, doğal 

acıları, lekelenmiş tutkuları. Böyle insanlar ya kutsal olmaya soyunurlar, 

ya da kutsal birine adarlar kendilerini. Hayatın içinde çırılçıplak varolmak 

gururunu incitir böyle insanların. Gerçek bayağı gelir. Mükemmelin kölesi 

olmak, hayatın sıradanlığını yaşamaktan daha gözalıcıdır çoğu kez. Kendi 

sıradanlığından tiksinince hayallerinde yarattıkları gerçekdışı bir 

trajediye sığınırlar.

Başta bende böyleydim. O dokunulmaz güzelliğini, o ulaşılmaz kutsallığını 

gördükçe sıradanlığımdan tiksiniyordum ve yaşadığım gerçek giderek daha çok 

bayağı geliyordu bana. Sıradan biri olmaktansa, mükemmelin kölesi olmak 

istiyordum. Bildiğim ve bilmediğim bütün zaaflarımı gizleyip, bu trajedinin 

cesur ve ölümsüz kahramanı olmak istiyordum.

Oysa gerçek hiç böyle değildi. Sadece seni yitirmekten korkuyordum. Çünkü 

sen özlediğim herşeydin. Mükemmeldin, kusursuzdun, sıradanlığı aşmıştın, en 

önemlisi kutsaldın. Sana ulaşmam, seni etkilemem için yaşadığım herşeyi 

inkar etmem gerekti bu yüzden. Hiç olmadığım kadar iyi, hiç olmadığım kadar 

ince, hiç olmadığım kadar derin gözükmem gerekiyordu. Hissetmediğim şeyleri 

hissediyormuş gibi gözükmem gerekiyordu.

O kutsal güzelliğin benden herşeyimi istiyordu. Oysa ben o herşeyim neydi 

bilmiyordum ki... Tamamlanmamış, eksik bir varlıktım. Tıpkı hayat gibiydim. 

İstediğin şeyleri verebilmem için hissetmediğim şeyleri hissediyor gibi 

söylemem gerekiyordu.

O kutsal aşk için sana yalan da söyledim. Seni yitirmemek içinde hepsi. En 

zor, en gizli, en iflah olmaz yaralarımı gizleyerek anlattım sana kendimi. 

Seni kazanırsam bu yaralarımdan kurtulurum sanıyordum. Oysa sen o dokunulmaz 

güzelliğine, o ulaşılmaz kutsallığına sığındıkça hayattan gizlenirken, ben 

sana ulaşmaya çalıştıkça kendi hayatımdan, kendi gerçekliğimden daha geriye, 

daha aşağıya düşüyordum. İkimiz de kendi gurbetimizde yaşıyorduk oysa. Ne 

yapsak, ne etsek kendimizi özlüyorduk. Yaşadığımız acı hayatlarımız gibi 

gerçekdışıydı. Ama acıydı sonuçta...

Sen hayatın bayağılığından kaçıyordun, bense kendimden. Ama buluştuğumuz yer 

aynı acıydı. Bizi hayattan kopartan, bizi hiç ummadığımız kadar bencil kılan 

bir acıydı bu. Ve hayatla sınanmayan bu içe dönük acı bizi hep yüzeyde 

tutuyordu. Çünkü en derinde yatan gerçeğimize insek ne olacağımızı 

bilmiyorduk. Oysa belki çıldıracak, belki de gerçekten değişecektik. 

Tabiatımız değişecekti. Oysa biz kendimizi kutsala adadıkça, mükemmelin, 

kusursuzluğun peşinden koştukça, hayat bize dokunmadan, içimize hiç sızmadan 

geçip gidiyordu uzaklara. Tıpkı bize dokunmadan geçip giden hayat gibi. 

Aslında biz de birbirimize dokunmadan geçip gidiyorduk.

Sana taptığımı söylüyordum, ama seni gerçekten tanımıyordum. Sen beni 

hayatın bayağılığından, sıradanlığından yanına çağırıyordun, ama aslında 

beni pek tanımıyordun. Bu yüzden inanmıyordum yaşadığımız hiçbir şeye. Bizi 

başkalarından üstün kıldığını sandığımız bu acının hayatta bir karşılığı 

yoktu, inan...

Seni unutmam mümkün değil, ama ben geldiğim yere geri dönüyorum. Bu 

kusursuzluk senin olsun. Birgün kendimi inkar etmeye karar verirsem bunu 

sadece kendim için yapmalıyım: Mükemmellik senin olsun. Sana herşeyimi 

vermemi istiyorsun. Oysa ne seni, ne de kendimi tanıyorum: Kutsallık senin 

olsun. Bu aşk beni tutuk, ezik, korkak biri yaptı. Seni biraz olsun 

etkileyebilmek için yaptığım bütün fedakarlıkların, hayatımın en büyük 

bencillikleri olduğunu anladığım an kendimden kaçıp kurtulmak istedim.

O an anladım ki, fırından aldığım ekmeğin sıcaklığı bu aşktan daha kutsaldı. 

Yüzümü ısıtan mütevazi güneş, evlerine ekmek götürdüğüm çocukların sevinci, 

çay bardaklarındaki kaşık sesi daha kutsaldı. O küçük mutluluklar, o eksik, 

o kanaatkar doyumlar daha kutsaldı...

Evet, hayat karanlık, bayağı, acımasız, kirli, sıradan, incitici; ama gerçek 

sevgili... Ona dokunabiliyorsun. Ama ben senin kutsal ve mükemmel saydığın 

hiçbir şeye ulaşamadım. Sana ulaşamadığım için duyduğum kaygı ve 

pişmanlıklar da bana ait değildi. Çektiğim acıysa yıllardır sakladığım 

yaraları biraz daha gizlemeye yarıyordu. Oysa hayat çok basit sevgili... 

Bunu bir anlayabilsek herşey çok farklı olacak. Ve hayatın o basitliği 

içinde saklı derinliği, vazgeçilmezliği...

Artık kutsal olan hiçbir şeye inanmadığım için daha berrak ve açık görüyorum 

çarşıdan eli boş dönenleri... Şehirleri hızla saran açlar ordusunu... 

Dünyayla aramdaki o sahte acıları ortadan kaldırdığım için tanık oluyorum 

herşeye: İşte dün gece TEM karayolunda bir travestiyi daha ezip geçti; 

sürücüsü karanlık ve sarhoş bir araba... İzmir''de bir kafeteryada garsonluk 

yapan Dersim''li Gökhan bugün, tıpkı dün ve önceki günlerde olduğu gibi tam 

onbeş saat ayakta servis yapacak müşterilere ve onca yorgunluktan sonra 

evine döndüğünde, Jack London gibi sabah dek ezilen insanların öyküsünü 

yazacak. Eskiden olsa çok romantik gelirdi bu gencin hali bana. Ama değil, 

çok sert, çok acımasız bir hayatı var; ama yine de gözlerinden o sımsıcak 

gülümsemesi hiç eksik olmuyor.

Yıllardır görmediğim üniversiteden bir arkadaşımın matbaasına uğradım 

geçenlerde. Devrimci bir belediye başkanının afişiyle aynı makinede bastığı 

porno dergileri kurusunlar diye birlikte ipe asıyordu. Bunu yaparken de 

bütün içtenliğiyle, bu düzeni değiştirmeliyiz arkadaş, diyordu.

Cezaevindeki çocukları için direniş yaptıklarından karakola götürülüp 

gözaltına aldıkları yaşlı anneleri polis gecenin bir yarısı sokağa 

bırakıyor. Ceplerinde neredeyse hiç para olmadığından şehrin çok uzağında 

olan evlerine gitmek için yürümekten başka çareleri yok bu çilekeş 

kadınların. Neredeyse sabaha dek yürüyecek olan bu yaşlı kadınların 

çektiklerini mutlaka içimizde hissetmezsek yaşadığımız hayatın hiçbir anlamı 

olmaz. Çünkü çoğu kez biz farketmesek de bu hayatta acı tek... Istırap 

tek... Aşk ve iyilik tek bir yerden akıyor kalplerimize...

Aynı saatlerde başka bir yerde, yaşlı ve eşcinsel bir tiyatrocu iki kimsesiz 

sokak çocuğunu zorla evine götürmek istiyor; onunla birlikte olurlarsa çok 

para vereceğini iddia ediyor. Evet, hayat hiç romantik değil; ama 

yargılamadan önce onu anlamalıyız sonuna dek... Belki de tam bu sırada 

lekesiz bir aşkı özleyen ve yalnızlığın o korkunç kaderiyle boğuşan Serpil 

öğretmeni çalıştığı kasabada, çocuklarını okuttuğu adamlar telefonla arayıp, 

yanına gelelim mi, boş musun, diye taciz ediyorlardır.

Asıl trajedi hayatın ta kendisi sevgili...

Hayat karanlık, acımasız, bayağı ve kirli; ama bizim erdem sayıp 

abarttığımız duygusallıklardan, kendimizi başkalarından üstün kılmak için 

sığındığımız kutsallıklardan daha gerçek, daha sahici.

Yıllardır ruhumun gurbetinde yaşamaktan tükendim. Kendi yaramı görüp, ona 

sarılamadığım için, ondan akan kanla yıllardır zehirleniyorum. Yıllardır 

senin yanında, ama senden çok uzakta kalmaktan sevgim acıyor. Birlikte 

yarattığımız bu hayattan kopuk imgeyi bırakıp, kendime doğru yürüyorum.

Hayatı ve seni buradan seyrediyorum. Odandasın ve tek başına dans ediyorsun....

İyilik ve sevgiyle gülümsüyorum; seni sevip hissetmem için seni sahiplenmem 

gerekmiyor. Oradasın ve varsın işte. Nereye gitsem içimde hissediyorum seni...

Hayatın bütün renkleri yüzünde...Odanda tek başına dans ediyorsun...

İlk kez acı çekmeden özlüyorum seni...', 'Biz seninle hep bayağılıktan kaçtık... Sıradan, basit, gündelik olandan.  Küçük mutlulukları, hayatın içindeki o kanaatkar doyumları değil, ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":147,"source_url":"https://www.antoloji.com/odanda-tek-basina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-cezmi-ersoz-pus2m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat soğuk, yağmurlu ve vurdumduymaz bir İstanbul gecesiydi... Ve gece 

yağan yağmur hep ürkütürdü beni. Yağmur değil yalnızlığımdı pencereleri 

damla damla yalayan, yıllarımı dolduran sensizlikti... Hep bir yanı 

yarımlık, hep senden uzaktalık, hayattaki tek ''kimse''mden yoksunluk, yani 

kimsesizlikti. Bir kavuşma mucizesine inanma yolunda harcanmış bir hayatın 

ansızın sonuna gelme, ve o mucizeyi yaşayamadan bir başına ölme korkusuydu 

yağmur…Yine yağmur yağıyor, yine gece... Yine İstanbul... Ve sen kollarımın 

arasından sıyrılıp kalkıyorsun yataktan. Nereye gidiyorsun sevgilim? 

Sadece sana sarılarak uyuduğumda nefes alabiliyordum. Beni kollarına 

aldığında, yüzümü masumiyetinin yurduna, o kimsesiz boynuna dayadığımda, 

kokunu kalbimle soluduğumda... Uykun benim cennetimdi. Çünkü cennet sadece 

ikimizin olabildiği yerdi benim için. Ne sana aşık kadınlar, ne sevdiklerin, 

ne geçmişin, ne yarının...Uykunda sadece ikimiz vardık. Aşkıma dar gelen 

sevgi sözcüklerine ihtiyacım yoktu orada. Sana sevgimi anlatmaya, ispat 

etmeye ihtiyacım yoktu artık. Aşkımızın kokusuydu sana beni anlatan, sana 

seni anlatan.... Beni gerçekliğin o soğuk, o köpüklü dalgalarıyla yutan ve 

alıp alıp senden ötelere savuran hayatın dışındaki tek kaçış tünelimdi uykun.

Önce kolunu çekerdin başımın altından, sonra sırtını dönerdin. Usulca 

sarılırdım sana arkandan, seninle ya da sensiz geçen yılların hasretiyle... 

Ardından yavaş yavaş kollarımın arasından sıyrılırdın...Yıllardır taşımaktan 

yorulmadığım hasretin, tenimden tenime akan o ateş, ağır gelirdi bedenine... 

Uyuyamıyorum, nefes alamıyorum, lütfen sarılma, derdin... Yatağın bir ucuna 

sığınmış bedeninden kovulmak, hayatından kovulmak gibiydi benim için. 

Sığındığım, soluk aldığım tek cennetten kovulmak gibiydi. Beni uykunda terk 

etmen, gerçek hayatta terk edişinden bile ağır gelirdi. Yanıbaşındaki 

sensizlik, o rutubetli evimdeki, o baştan ayağa sen olan evimdeki 

unutulmuşluğumdan çok daha ağır gelirdi.

Seni kaybetme korkusu öyle işlemişti ki hücrelerime...Yataktan doğrulduğun 

anda bu korkuyla açılırdı gözlerim. Bilinçaltım konuşurdu benim yerime... Su 

içmek ya da tuvalete gitmek için kalktığın asla aklıma gelmezdi. Gittiğini 

düşünürdüm yalnızca... O saatte kendi evini terk edip, nereye gidebileceğini 

sorgulamadan, sadece beni o sonsuz hiçlikte, o en masum rüyada, 

cennetimizde, uykumuzda bir başına bırakıp, kaybolacağından korkardım. Bana 

hep aynı soruyu sorduran bu yüzyıllık korkuydu işte: Nereye gidiyorsun sevgilim? 

Beni yeniden hayatın içinde, gerçeklerin ortasında bir başına mı 

bırakıyorsun? Beni yeniden unutuluş sürgünlerine mi gönderiyorsun? Nereye 

gidiyorsun sevgilim? 

Oysa seni uyutmayan içindeki o yangınlı hesaplaşmaydı. Gece iner, aşıklar, 

yüzler, bedenler, anılar kaybolurdu; sadece ikimiz kalırdık. Ve sen uykunda 

sevgimle hesaplaşmaya dalardın. Cennette cehennemi hatırlardın.

Dönüp geriye bakıyorum da, sanki yıllar değil yüzyıllar geçmiş aramızdan... 

Aramızdan ayrılıklar, ihanetler, kayboluşlar, vazgeçişler, yeniden bulmalar, 

korkular, yalnızlıklar, savrulmalar geçmiş. Ve bu ilişki ne çok biçim 

değiştirmiş...

Seni yollarca, şehirlerce uzağından sevdim. Seni kelimelerce, şiirlerce 

yakınından sevdim. Seni dünya üzerinde sanki ilk kez benim için kalemi eline 

alıp da yazdığın mektuplarca sevdim. Seni umutsuzca, beklentisizce, 

hayallerce sevdim uzağından. Hayatımı öyle olduğu gibi bıraktım. Şehrine 

geldim, ama kalbine giremeden sevdim. Neydik biz o yıllarda hiç düşündün mü? 

Neydik birbirimiz için sevgili? 

Geldim. Bana destek olacak, sırtımı vereceğim bir aşkın yoktu arkamda. 

Kendime yeni bir hayat kuracağım yalanını, kendim dahil, sen dahil herkese 

söyledim. Oysa tek istediğim seninle birlikte bir hayattı. Öyle 

cesaretsizdim ki karşında ve öyle açık sözlüydün ki bana karşı, ancak 

iddiasız bir sığınmacı olabildim hayatında. Hayatına iltica etmek isteyen 

bir yürek sürgünü... Bir aşk meczubu sadece...

Dürüstlük kimi zaman yalanlardan çok daha acımasızmış, sevgili... Gerçeğin 

buzdan ülkesinde yapayalnız kalan yürek, hayatta kalabilmek için yalanları 

bile özleyebilirmiş kimi zaman... Bana aksini ispat etmek için elinden 

geleni yaptığın o yıllarda, buzlar ülkesinde biraz olsun ısınabilmek için, 

aslında beni sevdiğin yalanına inandırmıştım ben de kendimi...

Aşkıma kapalı bir kapının önüne bırakılmış yaralı bir kuş gibiydim. 

İnanacak, bir ibadet gibi yaşayacak tek şeyimdi senin aşkın. Karşılıksız, 

güvensiz, sessizce yaşanan bir aşk... Nasıl da hoyrattın bana karşı... 

Kalbinde değil miydim gerçekten? Neydik biz söylesene? O yıllarda senin 

neyindim ben sevgili? Can yoldaşın mı? Yol arkadaşın mı? Dostun mu? Sevgilin 

mi? ..Sonra bir gün geldi ve unutuldum. Ve bu sorular birer birer bıçak gibi 

saplandı yüreğime ve yüreğimde yanıtlarını buldu. Unutuluş hepsinin acımasız 

cevabı oldu. Sonrası dipsiz bir karanlık... Sonrası çaresiz bir çıldırış...

Hayata karışmamak için tek kalkanım, tek sığınağımdı aşkın. Tek silahımı 

yitirdim ve hayata teslim oldum. Aldı beni savurdu başka bedenlere, parçası 

olamadığım o kırık dökük öykülere...

Kırgınlık kimlik değiştirdi ve vazgeçiş oldu benim için. Unutmanın en ağırı 

unutamadan unutmaktır. Seni sonsuza kadar kaybetmek kimlik değiştirdi ve 

unutmak oldu benim için. Seni unuttuğum yalanıyla hayatı kandırmaya 

çalışınca hayat hiç olmadığı kadar acımasız tokatlar indirdi yüzüme... 

Sonrası dipsiz karanlık... Sonrası hatırlamaya bile dayanamadığım düş 

yıkımları... Sonrası kesif, karanlık ve rutubetli bir kuyu... Koskoca bir 

boşluk... Sonrası ''yalnızlık'' kelimesine sığmayacak kadar derin bir yalnızlık...

Kaç zaman sonra bilmiyorum, bir gün geldi ve beni yeniden hatırladın. 

Yokluğumda kendine kurduğun hayat, beni yasak bir ilişki haline getirdi bu 

kez de... Ve bu ilişki bir kez daha kimlik değiştirdi. Seni, bir başkasıyla 

birleştirdiğin hayatına uzaktan bakarak, kalbimi kıskançlığın lanetli 

hırsına teslim ederek, kısıtlı zamanlarda, gizli saklı buluşmalarda, o 

doyumsuz kaçamaklarda sevmeyi de öğrendim... Hasretinin o tarifsiz kokusu 

burnumu sızlatırken yapayalnız uyumayı da öğrendim. Yağmurlu İstanbul 

gecelerinde o baştan ayağa sen olan evimde kaderimle kıyasıya yaşamayı da 

öğrendim, sevgili...

O zamansız unutuluşun ardından yeniden hatırlanmanın sevinci, seni 

paylaşmaya boyun eğmenin ve hep gizliliğin gölgesinde kalacak olmanın 

acısına büründü. Uykunda soluğunun bir başka soluğa karıştığını bilerek 

geçirdiğim sayısız gecelerde, gururumu parça parça bölüp aşkıma kurban 

verdim. O tarifsiz ağrıyı uyuşturmak için ruhumdan, kimliğimden, kadınlık 

onurumdan vazgeçtim. Her şeye rağmen direnebilmek için kendimden vazgeçtim. 

Geriye dönüş kapılarını sonsuza kadar kapatmış oldum böylece. Ruhumdan 

kendimi kovup, tüm hücrelerime sadece aşkını yerleştirdim. İşte o andan 

itibaren, sensizlik artık bensizlik oldu sevgili...

Nasıl da telaşlı, nasıl da soluk soluğa yaşardık o kaçamak anları... 

Aşkımızın en karanlık, en gerçek, ama en yoğun anlarıymış onlar... Sensiz 

geçen gecelerde yüreğimde biriken kıskançlığın, öfkenin, kırgınlığın ve 

hasretin hummalı karanlığı, sana kavuştuğum anlarda sevinçten çıldırmanın 

eşiğinde tarifsiz bir hazza dönüşürdü... Nasıl da ateşliydi 

sevişmelerimiz... Sana yeniden dokunmak, sanki bulutlara öpücükler kondurmak 

gibiydi... Huzurla huzursuzluk, hasret ve kavuşma, aşk ve öfke, merhamet ve 

acımasızlık, kırgınlık ve bağışlama her şey ama her şey sevgimizin taşkın 

sularında birbirine karışırdı. İki kalbin bir ömre sığdırabileceği tüm 

duyguları biz o kısacık anlarda soluk soluğa yaşardık...

Sonra hayatını değiştirdin. Yeniden özgürlüğüne kavuştun. Ve bu ilişki bir 

kez daha biçim değiştirdi. Yıllardır bir savruluş halinde aramızdan akıp 

giden aşkımız, nihayet dingin, doygun ve emin bir sığınak bulmuştu kendine. 

O savruk yıllar bile koparamamıştı ya bizi birbirimizden, artık hiçbir şey 

bu aşkı yıkamazdı. İhanetlerin, unutuluşun, hayatın sınavından geçmişti 

aşkımız. Tam da birbirimizi hayattan çok uzakta, dokunulmaz bir boyutta 

sevdiğimize inanmaya başlamışken, dudaklarından dökülen o lanetli cümle 

korkularımı yeniden uyandırdı, geçmişi zamandan koparıp aramıza soktu 

yeniden: ''Varlığın artık bana acı vermiyor...''

Ah sevgilim, ayrılık trenini çoktan kaçırmadık mı biz? Bulup bulup kaybetme 

oyunlarını çoktan tüketmedik mi? O dünyevi aşk oyunlarından, 

kıskandırmalardan, kaçamaklardan çoktan vazgeçmedik mi? Birbirimizi en ağır 

ihanetlerde sınamadık mı? Anlamadın mı artık, varlığım sana acı vermek için 

değil... Sadece seni sevmek için yaşadım ben! 

Senin için bir ilişkide girilebilecek bütün kimliklere bürünmedim mi? Önce 

aşkla değil kalbinin boşluğuyla tutunduğun bir can yoldaşıydım... Yüreğin 

bir başkasına kapılarını açtığında hayatından dışlanıp unuttuğun oldum 

sonra... Başka hayatlarda, başka ilişkilerde seni unutmaya çalışırken, belki 

de aslında sadece seni ararken kıskançlıktan deliye döndüğün oldum... 

Kalbime geri dönmek istediğinde gururumun gemilerini yakıp, metresin 

oldum... Vicdanın oldum senin... Merhametin oldum... Pişmanlığın oldum... 

Hazzın en sıradışı boyutlarını seninle paylaşan fahişen oldum... Arkadaşın 

oldum... Kardeşin oldum... Sevgilin oldum... Söylesene kaç kez biçim 

değiştirdi bu ilişki? Kaç kez kimlik değiştirdim seni sevebilmek için...

Anlamadın mı artık, varlığım sana acı vermek için değil. Sadece seni 

sevebilmek için yaşadım ben... Hala seninle geçireceğim anların telaşıyla 

tüketir gibi yaşıyorum sensiz geçen günlerimi. Yıllar geçti, hala seni 

görecek olmanın kalp çarpıntılarıyla, yalnız senin için giyiniyorum en güzel 

giysilerimi. Sen güzel bulasın diye geçiyorum aynaların karşısına.

Seninle geçen zaman bir daha tekrarı olmayan, doğaçlama bir melodi gibi 

benim için... Sanki birlikte yazılmış kaderimizin sayılı dakikalarından an 

çalıyorum. Öylece karşında oturup seni seyretmeyi, sana yemek hazırlamayı, 

seninle sohbet etmeyi, dostlarını ağırlamayı, seninle birlikte uyumayı, yani 

paylaştığımız ne varsa hepsini bir daha asla okuyamayacağım bir şiiri kelime 

kelime içime sindirir gibi, soluk soluğa hissederek yaşıyorum... Öyle 

birikmişsin ki içimde... Seni yaşamakla tüketmem, seni sıradanlaştırmam 

mümkün değil. İçime çektikçe çoğalıyorsun...

Şimdi varlığım her geçen dakika daha da daralan gizli bir çember örüyor 

etrafına. Her geçen gün biraz daha uzaklaşıyor, biraz daha kanıksıyorsun 

beni... O peşini bırakmayan yaralı geçmişin aramıza korku duvarları örüyor. 

Hayatını tüm kalbimle kucakladığımı hissettiğim anda ansızın yüzünde beliren 

o eski kaygıların alıp seni benden çok uzaklara, derinlere, yalnızlık 

kuyularına sürüklüyor. Yeni isimler, yeni aşk öyküleri, başka yüzler, başka 

bedenlerle kaçış planları yapıyorsun kendine... Gece ansızın seni uyandıran, 

kolunu başımın altından çeken, seni yatağın ucuna kadar götüren, uykunu 

bölüp ayağa kaldıran ve bana hep o aynı soruyu sorduran bu korkular değil 

mi...: ''Sevgilim nereye gidiyorsun? ''

Sevgilim nereye gidiyorsun? Orada ne var? Benliğini kıstırdığın duvarların 

arkasında soğuk, uçsuz bucaksız bir yalnızlıktan başka ne var? Neden 

kaçıyorsun? Neden bu aşkı sonsuzluğa, özgürlüğe, daha önce hiç yaşamadığın 

sınırsızlığa bir kapı olarak görmüyorsun? Ben senden gitme ihtimalini hiçbir 

zaman çalmaya yeltenmedim ki... Sevgim seni tüketmek değil, çoğaltmak 

içindi... Sevgim dünyanın yaşanılası bir yer olduğuna inanman, inanmamız 

içindi... Yüreğimizin çok derinlerinde yaşayan o iki masum çocuğun soluk 

alabilmesi için bir gökyüzüydü sevgim... Ben senin kanatlarını hiçbir zaman 

çalmadım ki...

Öyle çok reddedildim ki, öyle çok unutuldum ki senin tarafından, sensiz 

kalmak yüreğimi ezen tek korku artık. Öyle ki hayatım yalnız bir korku 

halinde ayakta duruyor şimdi... Korkumu gerçeğe büründürdüğün anda yıkılıp 

gideceğim. Her şeyi tükettim. Hayata tutunmak adına ne varsa her şeyi yaktım 

seni sevebilmek için... Tüm sabrımı, kendime ve insanlara güvenimi, sevginin 

hayatın tek harcı olduğuna olan inancımı... Artık senden başkasına verecek 

enerjim, sevgim ve hayatla hesaplaşacak bir benliğim kalmadı. Geriye dönüp 

sığınacak bir kendim kalmadı...

Şimdi bana varlığımın sana acı vermediğini söylüyorsun. Gitmemi istiyorsun, 

sonra yeniden gelmemi... Ve sonra yeniden gitmemi... Beni sensizliğin o 

dipsiz çukuruna önce sarkıtıp, sonra yeniden gün ışığına çıkarıyorsun. 

Sevgimi, yokluğumu hissettiğin yerde bulmak istiyorsun. Aşkımın benliğini ve 

hayatını ele geçirmesinden duyduğun o sebepsiz korkuyu yenmek için, bana 

seninleyken tekrarı olmayan bir şiiri hatırlatan zamanın, sana benimleyken 

gösterdiği monoton ve tüketici yüzünü yok etmek için oynadığın bir oyun bu 

belki de... Beni deliliğin sürgünlerine yollayıp, sonra yeniden kalbine 

çağırıyorsun.

Korkuyu beklemenin telaşı korkunun kendisinden çok daha ürkütücü biliyor 

musun? İşte bu yüzden sensizliğin karanlık kuyusuna kendi ellerimle 

bırakıyorum kaderimi. Korkuyu beklemekten vazgeçiyorum, ama asla seni 

sevmekten değil, sevgili... Sana veda etmeden kayboluşa karışmam da aslında 

sadece bunun için...

Madem varlığım acı vermiyor sana, madem ki ancak yokluğumda sevgimi 

hissedebiliyorsun, öyleyse yokluğumla kal sevgili... Madem ki yokluğumla 

daha mutlusun, o halde yokluk benim bu aşk için büründüğüm son kimlik olsun...', 'Hayat soğuk, yağmurlu ve vurdumduymaz bir İstanbul gecesiydi... Ve gece  yağan yağmur hep ürkütürdü beni. Yağmur değil yalnızlığımdı pencere...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":188,"source_url":"https://www.antoloji.com/ozledim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-murat-basaran-s4n6v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kal diyen yanım; katilim olursun...

Şimdi gitmek zamanı buralardan, 

Bir bardak serin sudan yarenlik dileyip, 

Ve serinleyip..

Varsın açmasın bahçemde çiçek, 

Bir fesleğene anlatırım rüyamı, 

Şimdi gitmek zamanı...

Farzet ki gönlüm; burda doğmadın...

Bu güneş, bu gökyüzü yabancı...

Bir kara sevdayla vedalaşırcasına...

Gitmek zamanı...

Vakıa, bu bahçenin bülbülüydüm ben, 

Çiçeklerden önce açardım her sabah, 

Bir bakıştı önce...

Sonra tebessüm... 

Bunca yıl avunduğum...

Şimdi gitmek zamanı buralardan...

Yavaştan toplarım hüznümü, heyecanımı.

Bana ait ne varsa.. Benden başka...

Ve incitmeden...

Ve incinmeden olsun isterdim...

Şimdi gitmek zamanı...', 'Kal diyen yanım; katilim olursun... Şimdi gitmek zamanı buralardan,  Bir bardak serin sudan yarenlik dileyip,  Ve serinleyip.. Varsın açması...', ARRAY['Türk Edebiyatı','Şiir','Murat Başaran']::text[], 8.5, '{"poet":"Murat Başaran","poet_slug":"murat-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/veda-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimin Kurdelası Ateşten', 'sevgimin-kurdelasi-atesten-murat-basaran-8820c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yıl daha geride kalırken, geleceği düşündüm...

Ölümü... Yeni bir yıl... Yeni umutlar...

Palavra...

Yeni bir yıl, sona biraz daha yaklaşmak...

Nasıl bir son? 

Bu sorudan korkmadan, hediyelik eşya satan dükkanlara saldırmak arsızca...

Ve plastik sevgileri... kurgulanmış sevgileri, eciş bücüş ama rengârenk para tuzaklarına gömüp, paketlemek sonra...

“Al... Seni hatırladım... Ve senin için zahmete girdim... Bu anlamsız ambalaj, sana sevgimi gösterebileceğim yegâne vasıtadır... Çünkü sevgim o kadar derindir ki (!)  ancak bu ucube ifade edebilir....”

“Bu sene yılbaşı hediyeliklerinde ne moda? ”

Bir yıl daha geride kalırken, durduğum yer, kendime ve sevgilerime ve sonra ölüme baktığım yerdir...

Yılbaşı, takvimin kulağımızdan çekip “Zaman geçiyor” haykırmasından ibarettir aslında...

Ama...

Ama önümüze konan, sonsuza yeni bir başlangıç yaptığımız paranoyasıdır...

“Yeni yıl... Yeni heyecanlar... Yeni umutlar...”

Karamsar mıyım? 

Evet... Doğru... 

Böyle bir iyimserlik faciası karşısında, sorgulanması gereken karamsarlığım, daha da artıyor...

Daracık bir yerden baktığımı söyleyecekler belki ama, ısrarlıyım...

Kutlu, mutlu, belirli günler, hediyelik eşya sektörünün dayatması altında çoğalıyor ve anlamsızlaşıyor giderek...

Ve işin acı tarafı...

Sevgi ve hediye gibi mukaddes bir duygu ve eylem, işporta malı oluyor...

“Bu sene yılbaşı hediyeliklerinde ne moda? ”

“Ucuz bir hediye bulmam lâzım... Ucuz ama gösterişli...”

Kimi kandırıyorsunuz? 

Veya kandırılmaya razı insanların içinde ne işiniz var? 

Ben... Seviyorsam eğer...

Gözlerim söyler bunu...

Duruşum... Bakışım...

Ateş olur, yakarım...

Yangınım hayat verir... 

Paketlenemez...', 'Bir yıl daha geride kalırken, geleceği düşündüm... Ölümü... Yeni bir yıl... Yeni umutlar... Palavra... Yeni bir yıl, sona biraz daha yaklaşm...', ARRAY['Türk Edebiyatı','Şiir','Murat Başaran']::text[], 8.5, '{"poet":"Murat Başaran","poet_slug":"murat-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevgimin-kurdelasi-atesten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Toplumcu Yüzün', 'senin-toplumcu-yuzun-siyami-ozel-s7v2y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En güzelliğin bir yerlerimde şimdi

En güzelliğin

Durup durup ansıtır

Canevinden vurulmuş

Bir çetecinin bakışlarını

Bilmediğim güneşler geçer

Akşam oldu mu pencerelerden

Bulutlar

Saçlarına saçlarına yürür

Ve senin toplumcu yüzün

Ağlar kimseye gözükmeden geceleri

Senin toplumcu yüzün

Şimdi bir ay gibi doğmaktadır

İnsanların solgun yüzlerine

Yüreklerine

Ah, o ılmlı tarla

Gün gelip bire yüz verecek

Bire yüz verecek anlıyor musun

Senin toplumcu yüzünde

İnan ki çok yakın

Sevgiler boy atacak

Umulmadık sevgiler

Doyulmadık sevgiler', 'En güzelliğin bir yerlerimde şimdi En güzelliğin Durup durup ansıtır Canevinden vurulmuş Bir çetecinin bakışlarını Bilmediğim güneşler geçer...', ARRAY['Türk Edebiyatı','Şiir','Siyami Özel']::text[], 8.5, '{"poet":"Siyami Özel","poet_slug":"siyami-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/senin-toplumcu-yuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağımızın Bulantısı', 'cagimizin-bulantisi-siyami-ozel-evs5a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tutarsız bir karanlık içindesin

Nerede gökyüzü, nerede güneş

İstediğin kadar yumrukla, bağır

Duvarlar sağır, duvarlar kalleş

Ayağında bir yaşam boyu prangalar

Ve bir gölge gibi peşinde

Çağımızın bunaltısı kardeş...', 'Tutarsız bir karanlık içindesin Nerede gökyüzü, nerede güneş İstediğin kadar yumrukla, bağır Duvarlar sağır, duvarlar kalleş Ayağında bir ya...', ARRAY['Türk Edebiyatı','Şiir','Siyami Özel']::text[], 8.5, '{"poet":"Siyami Özel","poet_slug":"siyami-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cagimizin-bulantisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan 1', 'i-nsan-1-ergun-yildirim-pjukz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanlık yaşamaksa eğer, 

Yaşamak ölmekten de beter', 'İnsanlık yaşamaksa eğer,  Yaşamak ölmekten de beter...', ARRAY['Türk Edebiyatı','Şiir','Ergün Yıldırım']::text[], 8.5, '{"poet":"Ergün Yıldırım","poet_slug":"ergun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/insan-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim Kadar', 'sevgim-kadar-cihan-ayrancioglu-d53yg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yaz mevsimiydi sanki içime çöken. 

ılık rüzgarlar esiyordu sensizliğin gölgesinde. 

oysa ki sıcaktan çatlamış dudağımda bir meltemdin, bir esinti. 

biliyorum. 

sen yokken bile su vardı dağlardan akan... 

Ayaz kış geceleri koynumda sakladığım resmin ve hatıralar. 

yazdığım satırlar 

ve fosforlu olduğunu fark ettiğim kalemim. 

gözlerin gibi parlıyordu gökkuşağı renginde... 

bu anlamsız ve bu kargaşa içinde nice kavgalar verdim 

nice sevmeler-sevişmeler 

kabuslar yaşadım gözlerinin renginde... 

‘Bir İlkbahar sabahı 

Güneşle uyandın mı hiç? ’ 

dercesine şarkılar 

koşup ta uzandın mı hiç sevgilinin boynuna? 

Yokluğunu yaşadığım en güzel geceler de 

ki en büyük hüzünler yaşadığım o gecelerde 

akan göz yaşların 

kim bilir kimin için? 

ve kim bilir? 

kirpiklerinden akan damlalar bir okyanus gibi 

tek yürek, 

tek bir damla gözyaşı anlatıyordu her şeyi... 

Yüreğimde herkesten büyük bir çocuk var 

şiir tadında yazmak bu sözleri 

en masum en çocukça şeyler yazmak 

her göz yaşımı akıtmak istediğimde o çocuğa sığınırım senin gibi 

okyanuslar kadar olmasa da 

buzullar kadar soğuk 

cehennem gibi sıcak 

ve taptaze elma dalında seni hissetmek... 

Göz yaşların! 

en masum, en çocukça 

nasıl da inandım hayatın bir cümle kadar basit 

ve bir nefes almak kadar kolaylığına 

sigara dumanını çekmek zor olsa gerek tiryaki olmayanlara... 

Hayatı ve her şeyi öylesine yaşamak yarını düşünmeden 

sergüzeşt, 

berbatça, 

gününü gün etmek doyasıya 

her şeye rağmen 

adam gibi bir şeyler yapmaya uğraşmak 

bir şeyler yaşamaya... 

Gözlerin 

ve kirpiklerinin arasından akan göz yaşların ne kadar az da olsa 

onları bir okyanus gibi yaptım 

umudun adını koydum fosforlu kalemimle 

okyanuslar kadar olmasa bile o yağmurlar 

çocuksu yüreğim kadar yücelttim 

Sevgim kadar okyanuslar yaptım...', 'Bir yaz mevsimiydi sanki içime çöken.  ılık rüzgarlar esiyordu sensizliğin gölgesinde.  oysa ki sıcaktan çatlamış dudağımda bir meltemdin, b...', ARRAY['Türk Edebiyatı','Şiir','Cihan Ayrancıoğlu']::text[], 8.5, '{"poet":"Cihan Ayrancıoğlu","poet_slug":"cihan-ayrancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sevgim-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülme Ey Nazlı Çiçek', 'gulme-ey-nazli-cicek-cihan-ayrancioglu-iqd10', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '‘Gülme ey nazlı çiçek! ’ 

Seni de neşeli diye, 

Güzel diye koparırlar toprağından, 

Ayırırlar, 

Hasrete sürerler, 

Su vermezler artık, 

Kırlardaki kardelen olmak istersin, 

Vitrindeki gül yerine. 

‘Gülme ey nazlı çiçek! ’ 

Solgun bak gökyüzüne, 

Kederli bak, susuzmuşçasına, 

Dikenlerini çıkar, 

Yaprakların yerine, 

Gülme ey nazlı çiçek! 

Gülme! 

Seni mutlu sanırlar.', '‘Gülme ey nazlı çiçek! ’  Seni de neşeli diye,  Güzel diye koparırlar toprağından,  Ayırırlar,  Hasrete sürerler,  Su vermezler artık,  Kırl...', ARRAY['Türk Edebiyatı','Şiir','Cihan Ayrancıoğlu']::text[], 8.5, '{"poet":"Cihan Ayrancıoğlu","poet_slug":"cihan-ayrancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulme-ey-nazli-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Var Sende', 'her-sey-var-sende-cihan-ayrancioglu-zuszu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öylesine bak ki! 

o derin, 

dürüstçesine, 

namusluca parlayan gözlerinle, 

mutluluk taşıyan kelebekler, 

pencereye konan kırlangıçlar gibi bak; 

belli etmeden korkaklığını... 

Yüreğinle... 

hani ağlamıştın ya geçen yaz 

bir sır gibi 

gece yarıları saksılarda kaldılar, 

en güzel, 

en renkli çiçekler yetişti. 

onlara bakar gibi bak; 

belli etmeden hüznünü... 

Sende her şey var, 

her şeyinle bak. 

çamurlar vardır yağmursuz, 

yağmurlar vardır bulutsuz olmaz ya! 

nikotin gibisin, 

bir nefes çeker gibi bak. 

belli etmeden ihanetini... 

Dedim ya! 

sende her şey var. 

meleklerin saflığı, 

bir bebeğin öpülmesi doyasıya, 

ve mutluluk dolu gülümsemesi onun, 

sevgili beklercesine bak; 

belli etmeden orospuluğunu...', 'Öylesine bak ki!  o derin,  dürüstçesine,  namusluca parlayan gözlerinle,  mutluluk taşıyan kelebekler,  pencereye konan kırlangıçlar gibi b...', ARRAY['Türk Edebiyatı','Şiir','Cihan Ayrancıoğlu']::text[], 8.5, '{"poet":"Cihan Ayrancıoğlu","poet_slug":"cihan-ayrancioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/her-sey-var-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabus', 'kabus-ergun-yildirim-2mzdb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceleri düşlerimdesin, 

Ne hayellerim nede düşüncelerimsin

Gerçekmisin bilmem ki  nesin', 'Geceleri düşlerimdesin,  Ne hayellerim nede düşüncelerimsin Gerçekmisin bilmem ki  nesin...', ARRAY['Türk Edebiyatı','Şiir','Ergün Yıldırım']::text[], 8.5, '{"poet":"Ergün Yıldırım","poet_slug":"ergun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kabus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdeniz Masalları– II', 'akdeniz-masallari-ii-onur-uysal-hu8jw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte yine yükseliyor güneş Torosların üzerinden

İşte yine başlıyor bir gün Rivera’da

Telaşlı insanlar dolduruyor sokakları

Balıkçılar topluyor serdikleri ağları

Balıkçılar merakla dinler her sabah rüzgarın sesini

Kimi zaman dile gelir deniz tanrıçası, anlatır bereketini

Ve kıpır kıpır olur deniz, gösterir en güzel danslarını

Zamanıdır der balıkçılar, yarışırlar göstermek için ustalıklarını

Kimi zaman Torosların ötesinden gelir haber

Delice bir rüzgara eşlik eder

Uyarır balıkçıları, o gün mola verirler

Siner deniz o zaman, saklar bereketini

Rüzgarı sadece balıkçılar dinlemez

Rüzgar sadece bereket haberi getirmez

Bir de dinler rüzgarı Rivera’nın gençleri

Beklerler denizden, tutkulu aşkların haberini

Kentte bir zamanlar bir genç yaşamış

Her sabah rüzgarın getirdiğine bakarmış

Usta olmasına ustaymış denizde

Balıkların en irisini, en güzelini

     hep o tutarmış

Ancak almamış haberini, görmemiş aslını

     hiç yaşamamış tutkulu bir sevdayı

O sabah da çıkmış ya genç

     rüzgarın sesini dinlemeye

Toroslardan esermiş rüzgar

     kimse boşuna beklemeye

Derken dile gelmiş rüzgar, irkilmiş genç

Tatlı bir aşk melodisiymiş kulağına gelen

Belli ki mahsun bir aşıktan yükselen

Günlerce sürmüş aşkın melodisi

Hiç kesilmemiş cevapsız kalan sesi

Çaresizce aramış tutkuyu, sevdayı, sevgiyi

İstemiş mi bilinmez ama

     hiç ses çıkmamış Rivera’daki gençten

Bir zaman sonra da kesilmiş rüzgar

     vazgeçmiş Torosların ötesine haber götürmekten

O gün bu gündür

     beklermiş denizden gelecek haberi

          usta balıkçılar

beklermiş Toroslar’dan bir esinti

          sevdalılar

Deniz ana göndermiş ya balık haberini

     tutkulu bir aşk arayanlar boşuna beklemiş

          dağlardan gelecek ılık bir rüzgarın esişini', 'İşte yine yükseliyor güneş Torosların üzerinden İşte yine başlıyor bir gün Rivera’da Telaşlı insanlar dolduruyor sokakları Balıkçılar topluy...', ARRAY['Türk Edebiyatı','Şiir','Onur Uysal']::text[], 8.5, '{"poet":"Onur Uysal","poet_slug":"onur-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/akdeniz-masallari-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdeniz Masalları – III', 'akdeniz-masallari-iii-onur-uysal-rtif2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün vakit bulup da düşerseniz yollara

Mutlaka uğramalısınız sahildeki küçük liman kasabasına

Rivera denir kasabanın adına

Gittiniz mi o güzel kasabaya

İnin bir de limanına

En güzel aşkların, 

     en çoşkulu maceraların

Bir de hikayesini yaşlı kadının

Dinlemeyi unutmayın

Efendim, hikaye başlar bu kasabadaki bir tarlada, 

Yaşlı bir kadın vardır, çiçek dikip satar sokakta

Denemiştir ya tüm çiçekleri

Karar kılmıştır en son zambakta

Kolay yetişirmiş zambak, 

Bol ürün verir, hızlı büyür, çok dayanırmış

Lakin kente bir de karanfil satıcısı dadanmış

İnsanın içindeki en ince duyguları

     karanfil yansıtırmış

Kızmış yaşlı kadın

Bakmış pazar elden gidiyor

Aklın yolu bir, herkes karanfili seçiyor

Başlamış sağda solda konuşmaya

Karanfilin komşu kentin simgesi olduğunu yaymaya

Doğrudur, simgedir ya diğer kentte karanfil

Çiçek dediğin nedir, tüm sevenlerce sevilir

Masal bu ya, inanmış tüm kent yaşlı kadına

Karanfili sevmenin kötü birşey olduğuna

Yıllar sonra bir genç gelmiş kente

Sahilde bir bira içmeye

Anlatmışlar en güzel aşkları

     en coşkulu maceraları

          bir de karanfille ilgili hatıraları.

Şaşırmış genç

Demiş en sevdiğim çiçektir karanfil

Çiçeğidir tutkulu aşkların, sınır tanımaz sevginin

Yok mudur yüreğinizde yer, bir başka çiçek için

Mümkün müdür varolması kasabada bu nefretin

Çıkarmış, vermek istemiş ya genç karanfil tohumlarını

İstememiş kasabanın halkı

     sevginin tomurcuklarını

Çok geç demişler, 

Sen git öbür kente ver

Bize zambağımız fazla fazla yeter

O gün bu gündür Rivera’da karanfil ekilmez

Zambaktan başka çiçek sevilmez

Siz yine de ihmal etmeyin sahil kasabasını

Hissettirmeden atın karanfil tohumlarını

Limana da uğramayı unutmayın

Ve bir de kadeh kaldırmayı

     yaşanan ve yaşanacak en tutkulu aşklar, 

          sınırsız sevgiler için.', 'Bir gün vakit bulup da düşerseniz yollara Mutlaka uğramalısınız sahildeki küçük liman kasabasına Rivera denir kasabanın adına Gittiniz mi o ...', ARRAY['Türk Edebiyatı','Şiir','Onur Uysal']::text[], 8.5, '{"poet":"Onur Uysal","poet_slug":"onur-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/akdeniz-masallari-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-bahadir-atay-s9k7a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşle uyanmışım ağlayarak, 

Elime bir çıngırak vermişler susmuşum.

Öğlen olmuş tutulmuşum bir yağmura, 

Upuzun, kısacık okul yollarında.

Güneşin batışını izlemişim bir dağda, 

Dağın tepesinde bir ben, bir kadın, bir de çocuk.

Ve saatler geceyarısını vurduğunda, 

Nasıl bilirdiniz diye sormuşlar insanlara.', 'Güneşle uyanmışım ağlayarak,  Elime bir çıngırak vermişler susmuşum. Öğlen olmuş tutulmuşum bir yağmura,  Upuzun, kısacık okul yollarında. G...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-gun-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-bahadir-atay-tiib2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatta gözü açık olmayayım bana ne, 

Ama hep gözüm açık ölmek istedim.

Arkamdan uyanık desinler diye değil, 

Hayata gözlerini yumdu diyemesinler, 

Hep derin bir nefes çekmek istedim ölürken

Sigara dumanı değil hani halis çam havası.

Yaşarken çok şey vermek istedim hayata, 

Ama bırakın bari bir nefes kalsın bende

Ve son nefesini verdi diyemesinler.', 'Hayatta gözü açık olmayayım bana ne,  Ama hep gözüm açık ölmek istedim. Arkamdan uyanık desinler diye değil,  Hayata gözlerini yumdu diyemes...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasam-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş', 'savas-bahadir-atay-n2nyc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimi öğretmendi, kimi çocuk, 

Kimiyse terzilik yapardı arka mahallede.

Hepsinin ortak bir yanı vardı o zamanlar, 

İnsandılar, ölmeden ve öldürülmeden önce.', 'Kimi öğretmendi, kimi çocuk,  Kimiyse terzilik yapardı arka mahallede. Hepsinin ortak bir yanı vardı o zamanlar,  İnsandılar, ölmeden ve öld...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/savas-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsizce', 'sebepsizce-bahadir-atay-hu1kw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünü olmayan sadece bir bugünüm oldu, 

Ve o gün bile ağlıyordum.

Niye olduğunu ise hala bilemiyorum.

En ufak bir suçum yoktu daha, 

Pişman olacağım hiç bir şey yapmamıştım

Kimsenin kalbini kırmamıştım durduk yere, 

Yada kimseye vurmamıştım hiç sebepsizce.

Bir kere bile yalan söylememiş, 

Bir kere bile aşık olmamıştım karşılıksız.

Aşkı, korkuyu, acıyı ve pişmanlığı hiç tatmamıştım, 

Bir hediye olarak hayat sunulmuştu önüme, 

Ve ben hala ağlıyordum hiç sebepsizce.

Yaşadım ve sanırım biraz daha yaşayacağım, 

Biliyorum ki yarınsız bi günüm de olacak.

O günün gelmesi uzak veya yakın, o zamana kadar; 

Elimden geldiğince güzel, doğru, 

Elimden geldiğince iyi, mutlu, 

Hiç keşke dememek ve hiç pişman olmamak için yaşayacağım.

Ve o gün geldiğinde, tıpkı bir bebek gibi, 

Sebepsiz yere ağlayacağım.', 'Dünü olmayan sadece bir bugünüm oldu,  Ve o gün bile ağlıyordum. Niye olduğunu ise hala bilemiyorum. En ufak bir suçum yoktu daha,  Pişman o...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sebepsizce-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizlerin', 'dizlerin-ahmet-ataman-lkwdg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık içinde karanlıktır yokluğun, 

Aydınlık içinde aydınlık, gözlerin...

Ellerinde tüm sevgim, özlemlerim, 

Çilemin bittiği yer, yalnızca gül bahçesi dizlerin...', 'Karanlık içinde karanlıktır yokluğun,  Aydınlık içinde aydınlık, gözlerin... Ellerinde tüm sevgim, özlemlerim,  Çilemin bittiği yer, yalnızc...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataman']::text[], 8.5, '{"poet":"Ahmet Ataman","poet_slug":"ahmet-ataman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dizlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlara', 'bulutlara-deger-ulas-turan-2qgsb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bulutların şarkısı ancak böyle söylenir 

Islak name taşır kendine... 

Bulutsuz bir baharı ancak böyle kandıra bilirsin 

Güneşin ardına saklanıp... 

Yolları aşmadan 

Rüzgâr olup esmeden 

Yağmur olup ıslatmadan 

Kandırırsın yarınları... 

Umudu sen böyle paralarsın 

Hiç yokken varlığın... 

Böylesine masum saklanırsın 

Suçları bir bir işlerken ömrüne... 

Yolları aşmadan, 

Rüzgâr olup esmeden 

Yağmur olup ıslatmadan 

Kandırırsın yarınları... 

Bir vakit sessizce koynuma aldığım çiçekleri 

Koklayamadan çürütürsün... 

Vadesi uzun senet gibi taşırım ömrümü 

Yarına borçlu, suçlu yaşarsın... 

Yolları aşmadan 

Rüzgâr olup esmeden 

Yağmur olup ıslatmadan 

Kandırırsın yarınları...', 'Bulutların şarkısı ancak böyle söylenir  Islak name taşır kendine...  Bulutsuz bir baharı ancak böyle kandıra bilirsin  Güneşin ardına sakla...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bulutlara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buydu...', 'buydu-dandik-yazar-3pusz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yanın deniz, 

bir yanın orman olsa da; 

önün mezarlık.

Yürüyüşün sonunda 

ölüler kalkıp ayağa, 

o çirkin suratlarıyla 

karşıcı çıkacaklar sana; 

ellerini uzatıp

''gel! ''

Diyecekler

Gideceksin 

ve 

anlayacaksın ki, 

melek diye bildiğin onlardır

Toprağı bağrında, 

çiçekleri kökünden, 

toprak örttükce üstünü 

temizliği koklayacaksın.

Sevineceksin 

ve

anlayacaksın ki, 

cennet diye bildiğin orasıdır.

İnsanın son halini göreceksin.

Ve 

anlayacaksın ki, 

umut diye bildiğin oradadır.

''Bu muydu? '' 

Diye soracaksın.

Ve 

anlayacaksın ki, 

hepsi buydu.', 'Bir yanın deniz,  bir yanın orman olsa da;  önün mezarlık. Yürüyüşün sonunda  ölüler kalkıp ayağa,  o çirkin suratlarıyla  karşıcı çıkacakla...', ARRAY['Türk Edebiyatı','Şiir','Dandik Yazar']::text[], 8.5, '{"poet":"Dandik Yazar","poet_slug":"dandik-yazar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/buydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Anatomisi', 'gecenin-anatomisi-arif-baltaci-up81i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Asi bir haykırıştı gönlümde sevdan

Ansızın susuverdi fırtınanın içinde 

Ardından dökülüverdi iki damla mutluluk 

O yeşil o sonsuz pınarların içinden

Kadehler ardı sıra kalkarken şerefine

Yitirdim o büyüyü kadehlerin içinde 

Umut dolu yarınlarım var benim 

Her an sevmeye hazır bir de yüreğim 

Gamla dolu geçirilmez ki  bir hayat

Zaten yaşayacağımız kaç sene var ki

Garsonların bıkkın bakışlarından sonra 

Daldım o boğazın yalan manzarasına 

Düşündüm dostlarımı neredeler kimbilir

Kimbilir yollarımız tekrar nerde kesişir.

Bulur muyum eski sıcaklığı 

Yoksa unutulur muyum 

Düşündükçe dostları hasretten kurtulur muyum 

Yusuf benden çok uzak Samsun denen şehirde 

Rıza’yı bulur muyum Antalya’nın içinde 

Yakup ne yapar Hatay’da yine öyle deli midir.

Ya Ramazan yanında öyle serserimidir.

Düşünürken bunları unuttum sevdiğimi

Zaten beni sevmemişti böylesi daha iyi 

Doğukan’la beraber bindik sarı dolmuşa 

Sen olmadan Doğukan sıkıysa burda yaşa 

Boğazdan geçerken anladım dedim

Aşkın zamanı yoktu

Beliriverirdi ansızın ellerinde 

Zorlamaya gelmezdi sevgi

Yitirirdin o zaman bakışların birinde 

Geriye dönemem artık 

Bütün yollar kapanmış

Sana mutluluklar güzelim 

Kısmetimiz bu kadarmış.

	Yeşildirek/İSTANBUL

	27.03.2002', 'Asi bir haykırıştı gönlümde sevdan Ansızın susuverdi fırtınanın içinde  Ardından dökülüverdi iki damla mutluluk  O yeşil o sonsuz pınarların...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gecenin-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi', 'simdi-arif-baltaci-wf8p0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İmkansız aşklara kucak açıp ta 

Sevmekten zevk aldım sevilmekten değil

Ne olurdu bir kere gözlerime bakıpta 

Olamaz deseydin unuturdum kimbilir

O karanlık gecede düşündüm iyice

Artık kovalamaca bitti bunu bil 

Sebepsiz fırtına dindi gönlümde 

Sende yeni aşklara açıl da sevil

Hicaz makamında kaldı son hatıran 

Şimdi gülüşünde umrumda değil

Yoruldu deli gönlüm basit aşklardan

Ben artık mecnunum bunu böyle bil 

İster uzaklaş ellerimden meçhule doğru 

İster gir kalbime hissetmem artık 

Üzülmek eski bir hatıra şimdi

Giden sevgiliye boşa ağladık 

Zamanın bilinmezinde kaybettim seni

Beni bulsan bile zaman çok geçti

Şimdi aşkımı buldum ona yaklaşıyorum 

Ona yaklaştıkça senden uzaklaşıyorum 

Azrailin peşinden ölüme koşuyorum

Yeşildirek/İSTANBUL

25.03.2002', 'İmkansız aşklara kucak açıp ta  Sevmekten zevk aldım sevilmekten değil Ne olurdu bir kere gözlerime bakıpta  Olamaz deseydin unuturdum kimbi...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/simdi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz bakışmaların ardından', 'sessiz-bakismalarin-ardindan-arif-baltaci-f8n2t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessiz bakışmalarda sevmiştim seni

Sen ki bir ipekböceği kadar narin 

Bir kardelen çiçeği gibi eşsizdin

Titreyen sesinle iyiyim derken 

Eşsiz gülüşünle beni mest ettin

Resimlere inat uzaktın benden 

Yazık ayrıldı ellerimiz birbirine değmeden 

Gözlerini kaçırırken san her bakışımda 

Sevgimi de götürdün o bakışlar ardında 

Hataydı seni sevmem söylemiştim herkese 

En azından anladım vakit çok geç olmadan

Bu gönül yeniden birini de sevse 

Hep buruk kalacaktır senin yerin dolmadan

Belki bir gitarın tellerinde bulacağım seni

Belki bir aşkın ellerinde bulacağım seni 

Ama üzülmeyeceğim buna eminim

Bulduğum yerde kaybedeceğim seni

Seni kaybettikçe delireceğim

Belki bir gün dönersin diye 

Seni mahşerde bile bekleyeceğim.

							Zeynepkamil/İSTANBUL

								26.03.2002', 'Sessiz bakışmalarda sevmiştim seni Sen ki bir ipekböceği kadar narin  Bir kardelen çiçeği gibi eşsizdin Titreyen sesinle iyiyim derken  Eşsi...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sessiz-bakismalarin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram yalanları', 'bayram-yalanlari-arif-baltaci-oqzil', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bayram günü 

Çengelköy’e kar yağıyordu 

İnceden ince 

Şeker topluyordu çocuklar 

Yüreğinde karşılıksız sevgilerle 

Ne eski bayramlar kalmıştı 

Ne de eski sevdalar 

Hepsini kopan takvim yapraklarıyla 

Yitirmiştik birer birer

Sahipsiz kalmış bir çocuk yüreğiydim

İstanbul’un yalan kalabalığında 

Tarih bile tekerrür etmiyordu artık

Oysa düşler kurardık mutluluk üstüne 

Yalanın yeri yoktu sanırdık düşlerimizde 

Meğer en büyük yalanları

Düşünmüşüz düşlerimizde 

Ne yaşamak mutlulukmuş

Ne de dünya bir cennet 

Yıllarca bu yalanlarla uyutulmuşuz 

Umut sözleriyle avutulmuşuz.

					18.12.2001

					Çengelköy/İSTANBUL', 'Bir bayram günü  Çengelköy’e kar yağıyordu  İnceden ince  Şeker topluyordu çocuklar  Yüreğinde karşılıksız sevgilerle  Ne eski bayramlar kal...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bayram-yalanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'zamanın zamansızlığı', 'zamanin-zamansizligi-arif-baltaci-3764b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '^Yalnızlık bir muştu yüreğimde^

Gün be gün  daha derine işler

Sus pus olmuş tüm şehir 

Sessizlik sensizliğe küser 

Kapımı çalan yok aylardır 

Gönül bir dosta hasret 

Gönül perişan 

Gönül buruk 

Gönül gurbete gider

Zamanın zamansızlığında 

Yitirdik bir dost selamını 

Beklediğim biri yok bu şehirde

Bekleyenim bir ölüm var 

Oda her an peşimde.

					Çengelköy/İSTANBUL

					18.12.2001', '^Yalnızlık bir muştu yüreğimde^ Gün be gün  daha derine işler Sus pus olmuş tüm şehir  Sessizlik sensizliğe küser  Kapımı çalan yok aylardır...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zamanin-zamansizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlar gibi', 'aglar-gibi-arif-baltaci-dqset', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün ışığına hasret bir gül gibi 

Öyle mahzun öyle solgundu yüzü 

Büküktü boynu güneşsiz bahar gibi 

Gözlerinde bir telaş bir korku vardı

Sanki yaşamaktan korkar gibi

Sonra bir siren sesiyle 

Değdi gözlerimiz birbirine 

Gözünü kapattı bir şeyler saklar gibi 

Vapur yanaşınca iskeleye 

Hızla indi vapurdan bir şeyden kaçar gibi 

Soru işaretleriyle birlikte 

Düştüm o bilinmezin peşine 

Birden döndü baktı bana 

İçimdeki o ateşi yakar gibi

Bende bir telaş başladı 

Sandım birden dünyam karardı

Geldi durdu yanımda bir şey hatırlar gibi 

Dedi ''Tanışıyor muyuz biryerlerden 

Bana öyle geldi de'' dedi başını eğerken 

Sustu anlamsızca bir anda 

İçinde bir yerler yanar gibi 

Dedi ''Neyse karıştırdım herhalde 

Elbet benzer insan insana değil mi? 

Ve sen'' dedi gözlerime bakıp sustu 

Sanki benden birşeyler umar gibi

Lal oldu dilim konuşamadım 

Baktım anlamsızca gözlerine o yabancının

İçerimden bir yerle kopar gibi

Gitti bir meçhule bakarak arkasına 

Sildi gözyaşlarını hırkasının ucuna 

Unutamadım o günü ömrümce hatırlarım 

Hatırladıkça dönerim arkama 

Sanki o sesi duyar gibi 

Gönlümde o kız sessizce ağlar gibi...

							Çengelköy/İSTANBUL										21.12.2001', 'Gün ışığına hasret bir gül gibi  Öyle mahzun öyle solgundu yüzü  Büküktü boynu güneşsiz bahar gibi  Gözlerinde bir telaş bir korku vardı San...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/aglar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk', 'dostluk-arif-baltaci-waa62', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüzün kokan gecelerde 

Hissetmek isterdik 

Bir dost elini yüreğimizde 

Koca yıllar vardı paylaşılan 

Dostluğun sıcak evinde

Hiçbirimize gülmemişti kader

Biz miyadsız sevdalar beklerdik 

Beklenmeyesi anlarda 

Her limana uğrayan aşk gemisi

Transit geçerdi beklediğimiz limandan 

Bakakalırdık arkasında 

Saatlerce kıpırdamadan 

Yüreğin bam teline dokununca bir şair 

Yaşlar dökülürdü gözlerden gönüllere

Yemin ederdik son olsun derdik

Son olmayacağını bile bile 

Bir meçhule giderdik

Şimdi saat tik taklarıyla harcanan ömrün 

Belki de son dönemecindeyiz

Doğduğumuz gün gibi yalnızız

Ama doğduğumuz gün gibi temiz değiliz

Artık zamanım doldu 

Biliyorum bu sahneyi

Kapattım gözlerimi 

Beklerim son perdeyi....

						Çengelköy/İSTANBUL

							05.01.2001', 'Hüzün kokan gecelerde  Hissetmek isterdik  Bir dost elini yüreğimizde  Koca yıllar vardı paylaşılan  Dostluğun sıcak evinde Hiçbirimize gülm...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dostluk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınav Arefesiydi', 'sinav-arefesiydi-arif-baltaci-2wnxp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne bakardım geceleri 

Sahte sevgilerle dolu dünyadan 

Bir lahza uzaklaşmak için 

Bilhassa sana yaklaşmak için

Sevda labirentinin çıkmaz bir yerinde

Umudu bulmak için 

Gökyüzüne bakardım

Oysa ben seni sınav arefesinde sevmiştim 

Hani o bitmez dediğin ceza dersinde 

Ve sen benim yanımda bana yabancıydın 

Bahar kokan saçlarınla beni yaraladın

İstanbul ayazıyla üşüyen ellerim

Senin hayalinle ısınırdı her gece 

Ve her gece sabahlardım ben 

O karanlık o yalnız bekar evinde

Zamansız geldi aşkın dağınıktı bu yürek 

Kırıntılar kalmıştı o eski sevdalardan

Henüz hazır değildim yeni bir aşka 

Gönlüme bir his verdin ki bambaşka 

İşte ben seni bu duygu çatışmalarında sevdim

Gel desen sev desen bilir misin 

Mahşerde olsam yine gelirdim 

Resmine bakarken yine dün gece 

Bir garip hale düştüm ilk defa 

İlk defa ağladım hıçkırıklarla 

Umut senin olsun zalim sevgilim 

Azrailim geldi artık gitmeliyim...

						Çengelköy/İSTANBUL

							01.02.2001', 'Gökyüzüne bakardım geceleri  Sahte sevgilerle dolu dünyadan  Bir lahza uzaklaşmak için  Bilhassa sana yaklaşmak için Sevda labirentinin çıkm...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sinav-arefesiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana yakışır', 'sana-yakisir-arif-baltaci-cz2i9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığa soyunduğu bir yerde 

Seslerimiz değmişti birbirine bir kere 

Klasik laflarla başladık söze

Sonra hayatın akışına bıraktık kendimizi

Ve sen yeşil gözlerinle mest ettin beni

Gülmek sana yakışır...

Zamanın patavatsız bir anında 

Tartışmaya başladık sebepsiz yere

Sende sebepsiz kıskançlıklar 

Bendeydi bütün hatalar

Ama yinede söylemiştim hata bende olsa bile

Kalmak sana yakışır...

Gittin sonra, zamanın sonsuzluğuna 

Ve ben senden sonra yaşayamadım 

Uyanamadım yeni güne sen yoksun diye 

Kalbim acırdı kırılırdı kalbim

Şu kalbimi lime lime 

Dilmek sana yakışır...

Bilirdin seni ne çok sevdiğimi 

Senin için nelerden vazgeçtiğimi

Sensiz günlerin ne zor geçtiğini 

Bilirdin duygusallığını bu yüreğin 

Şimdi ağlıyorsam eğer gözyaşımı 

Silmek sana yakışır...

Yalnız sende vardır derdime derman 

Ne olursun dön artık geçmeden

Olmuyor işte sen olmadan 

Derdime çare bulunmaz sevdiğim

Birgün seninle dolduğum anda ansızın 

Gelmek sana yakışır...

Yaşıyorsam eğer senin içindir 

Umutlar senin güller senindir

Hala bıraktığın gibi beklerim seni

Her kapı çalışında sen geldim derim

Şimdi ne haldesin diye sorma

Bilmek sana yakışır...

Büsbütün gidiyorum bu yerlerden

Ne hatıralar kalacak ne iz kalacak 

Hayatım bir meçhulde son bulacak 

Adresimi vermeyeceğim kimseye

Döneceksin yerimi bilmeyecek kimse ama 

Bulmak sana yakışır...

Birgün ölüm haberimi duyarsın 

Gözlerinle inciden yaşlarla 

Sonra kendine kızar tasalanırsın 

Nasıl yaptım diye bunu ona 

Haydi bekletme artık sevdiğim 

Ölmek sana yakışır...

					Çengelköy/İSTANBUL

                          04.02.2002', 'Gecenin karanlığa soyunduğu bir yerde  Seslerimiz değmişti birbirine bir kere  Klasik laflarla başladık söze Sonra hayatın akışına bıraktık ...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/sana-yakisir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-sinan-gungor-mps0j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmedim ben bu dünyayı. Bu gidişle hiç sevmeyeceğim.Anlamak ne güzel bu duyguyu.Sevmekse; Biliyorum yanlış düşünüyorum ama boş verin. Katılanlarda olabilir gülmektenmi bilinmez ama boş verin.Zaten yalan demezlermiydi bu dünyayı yalanmı söylüyorlar yoksa bilinmez ama boş verin.Her şeyin bir sonu vardır bu şiirde olduğu gidi şiir bitti desem her şey gibi.', 'Sevmedim ben bu dünyayı. Bu gidişle hiç sevmeyeceğim.Anlamak ne güzel bu duyguyu.Sevmekse; Biliyorum yanlış düşünüyorum ama boş verin. Katıl...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güngör']::text[], 8.5, '{"poet":"Sinan Güngör","poet_slug":"sinan-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/dunya-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canan', 'canan-kamuran-turkmenli-c8w5s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir bayram sabahıydı vakit erken

mutluluk neden bize uzak derken

derilmemiş gülleri dererken

sen canan oldun bende can', 'bir bayram sabahıydı vakit erken mutluluk neden bize uzak derken derilmemiş gülleri dererken sen canan oldun bende can...', ARRAY['Türk Edebiyatı','Şiir','Kamuran Türkmenli']::text[], 8.5, '{"poet":"Kamuran Türkmenli","poet_slug":"kamuran-turkmenli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/canan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duydun mu?', 'duydun-mu-abdurrahim-karakoc-30xm0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karagözlüm, kavuşmayı beklerken

Ayrılığın vakti geldi, duydun mu? 

Beraberce diktiğimiz çiçekler

Açılmadan önce soldu, duydun mu? 

İçimde acıdan ırmaklar çağlar 

Gözlerim yaş dolu, gönlüm kan ağlar

Tatlı hatıralar, sıcak sevdalar

Hakikatsiz rüya oldu, duydun mu? 

Kara talih ile olunmaz yarış

Eğer küskün isen gitmeden barış

Belki son ayrılık, belki son görüş

Kavlimiz yarıda kaldı, duydun mu? 

Çok olur dağların karı-kıcısı 

Böyle imiş alnımızın yazısı

Bu mevsimsiz ayrılığın acısı...

Ok vurdu sinemi deldi, duydun mu? 

KARAKOÇ’um, kalbim yara, dilim lâl...

Ömrümün ufkunu sardı bir melâl

Beslediğim umut, kurduğum hayal

İçime ateşler saldı, duydun mu?', 'Karagözlüm, kavuşmayı beklerken Ayrılığın vakti geldi, duydun mu?  Beraberce diktiğimiz çiçekler Açılmadan önce soldu, duydun mu?  İçimde ac...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duydun-mu-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-hilmi-tanrikulu-g87v7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerim titriyor, 

Aylardan, yıllardan bu yana, 

Neden mi? 

Bilmiyorum! 

Beynim ağlıyor, 

Her düşündüğümde.

Neyi mi? 

Bilmiyorum! 

Yalnızlık en yakın dost, 

Bunların arasında.

Kimlerin mi? 

Bilmiyorum! 

Hiç kimseye inanamıyorum, 

Birkaç eski dost hariç.

Neden mi? 

Bilmiyorum! 

Küçük, ufacık ama beni ağlatan hatalar için, 

İçimdeki çocukları öldürüyorum.

Seni mi? 

Seviyorum!', 'Ellerim titriyor,  Aylardan, yıllardan bu yana,  Neden mi?  Bilmiyorum!  Beynim ağlıyor,  Her düşündüğümde. Neyi mi?  Bilmiyorum!  Yalnızlık...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilmiyorum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkenden', 'erkenden-hilmi-tanrikulu-laj9u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlamsızlığın ötesinde, 

Erken kalktım bu sabah yine.

Kaldırdılar istemesem de.

Kargalar yok.

Hiçbirisi bir halt yiyememiş.

Yalnızlığımı aradım, 

Oda kalkmamış.

Herşeye gebe yeni gün, 

Daha o bile uyanmamış!', 'Anlamsızlığın ötesinde,  Erken kalktım bu sabah yine. Kaldırdılar istemesem de. Kargalar yok. Hiçbirisi bir halt yiyememiş. Yalnızlığımı ara...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/erkenden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlice', 'gizlice-hilmi-tanrikulu-ab7nq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Merdivenlerden indim, yalnızlığım kaldı, 

Yürüdüm aldırmadan sokaklara.

Birikirken yarınlara, 

Fırtınalar başlayacaktı, 

Sonra...

Önce gözler vardı karanlıkta, 

Sonra aşk sebeplendi, heyecanla

Dursam, 

Duramam.

Ben çoğalsam içimde, 

Ruhum boyanır bulutlara.

Çoğalsam yağmurun cesaretine, 

Sahil kucaklar beni gride.

Oyunlar ayrı kaldı, 

Sen filizlendin boşvermişliğimde, 

Bile bile...

Yağmur güneşi ıslatsa, 

Ben yine ölmem.

Kızarım hayata cinnetle, 

Korkarım, 

Başlamadan bitenlere.

Ben yaşlansam içinde, 

Öderim bedelini, 

Gizlice...', 'Merdivenlerden indim, yalnızlığım kaldı,  Yürüdüm aldırmadan sokaklara. Birikirken yarınlara,  Fırtınalar başlayacaktı,  Sonra... Önce gözle...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gizlice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Şiir', 'hangi-siir-hilmi-tanrikulu-7ovao', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşlemeyi düşlerken, 

Yanında masum sessizliğin, 

Yazamadığın kelimeler terkettiler.

Hangi kentte özlüyorum seni? 

Uğramıyor arık ölümler, 

Sağır oldum; Azrail kekeler.

Ağlasam, 

Konuşsam, 

Heceler seni özler.

Kendimi kaça böldüm, 

Her parçamı sana gömdüm.

Yağmurların ıslattılar, 

Ağaçlarımı hep bahçende büyüttüm.

Seni yazmayı isterken, 

Kağıtlarda siyah beyaz gözlerin, 

Söyleyemediğim sözler terkettiler.

Hangi şiirde okuyorum seni?', 'Seni düşlemeyi düşlerken,  Yanında masum sessizliğin,  Yazamadığın kelimeler terkettiler. Hangi kentte özlüyorum seni?  Uğramıyor arık ölüml...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hangi-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutkum', 'tutkum-hilmi-tanrikulu-aalkr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir anlık değildi benim tutkum. Her zaman tutkuluydum. Sabah yatağımla günaydınlaşırken sanki sana uyanıyordum. Çok uzaklarda yada başka bir tutkuda olsan bile sana uyanıyordum.

	Yeni gün neler getirecekti acaba sana? Üzecek mi acımasız, tutarsız, cesaretli. Konuşabilecek miydik rasgele. Yeni gün fahişe akşamını bize ayıracakmıydı. Yoksa bunların hepsi, sana uyanmadan önce gördüğüm rüyamıydı. 

	Hep sana gelmek istedim. Ama her başlayışımda sonu bir türlü getiremedim. Korkuyordum. Seninle  beraberken heyecandan konuşamamaktan, ben olamamaktan, sana çirkin görünmekten korkuyordum. Bu yüzden sana gelmek yerine, hep sen yokken, yapayalnızken konuştum seninle. Titredim o zaman sana titredim. Ağladığımda oldu. Korkuyla titreyerek. Çaresizlikten. İçimdeki sen ile, asıl seni tanıştıramamazlığın verdiği korkuyla titreyerek. Bunlardan dolayı sana gelmek, sana kavuşmak, birkaç kelime konuşmak için senden kaçıyordum.

	Ama bitmeyen ve sorunlu bir tutkuydu benimkisi. Her sabah sana uyanıyordum. Korkuyla. Titreyerek...', 'Bir anlık değildi benim tutkum. Her zaman tutkuluydum. Sabah yatağımla günaydınlaşırken sanki sana uyanıyordum. Çok uzaklarda yada başka bir...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tutkum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önceleri', 'onceleri-hilmi-tanrikulu-i5d0m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Önceleri  yetmedik birbirimize, az geldik düşlerimize... sonra sevdik, sonra ağladık. Sonra uyuduk birbirimizi görmek için rüyalarda. Tütsüler yakıp, şarkılar dinledik. Hep ateş oldu, kolayca öldük. kaldırıp attık cesetlerimizi, birbirimizi gömdük, ama hiçbir şey değişmedi ve bitmedi. Hep sevdik. Hep düşledik birbirimizi.

	Konuşurduk sadece, birbirimizi sevdiğimizi birbirimizden saklayarak. Birbirimize sevgi yerine acı vermekten korktuk. Ama çaresizliğimiz bize en dayanılmaz ve az öldüren acıyı öptürdü. Kitaplar  okuyup birbirimize hediye ettik. Kitaplarımız, hediyeler hep aşkı anlatırdı ve birbirimizi  uzaktan uzaktan severdik. Unutamazdık yinede sevemezdik. Kolay değildi çünkü. Son sözü, dağınık kalplerimiz söylemişti. Ve bunu içimizde saklamıştık.   Bazen şarkılar bazen ölümler bazen de çocuklar bize söylememizi anlatmıştı ama biz anlamazlıktan geldik. Yalnız kalınca oyunlar oynayıp, şarkılar söylerken söylermiş gibi  yaptık. Hatta ben bir kere ağzımdan kaçırdım, sonra sana yalvarıp af diledim. Çünkü bizim sessizliğimiz aşkımızdan daha anlamlıydı. Ne koptuk, ne birbirimizin olduk.

	Hep hayal kurar kurduğumuz hayalleri birbirimize aktarırdık. Ama  hiç birisinde ne sen nede ben vardık. Aslında tüm hayallerimiz birbirimizin üzerineydi. Ama korkardık. Yaşamdan,  garipliklerden, anılardan, geleceğimizden korkardık. birbirimize yalan söyleyip hayallerden bedenlerimizi soyutlardık.  Yalan söyleyip, söylediğimiz yalanı anlamamız için gözlerimizle birbirimize yalvarırdık. Aslında gerek yoktu. Çünkü anlatmadan önce bile bunu bilirdik. Sonra kendimizden kaçıp iki dost gibi hikayeler anlatırdık.  vitrinlere  bakıp beğendiklerimizi anlatıp sonra birbirimizden habersiz alırdık. Sadece sevdiğimizi anlatmamak için. 

	Kış olurdu. Geceler soğuk ve sessiz. Dünden yarınımız belliydi. Zaman bize hep zor gelmişti zaten. Ama kışları daha çok severdik. Kış karanlığında aşkımız birbirimize daha çabuk dağılırdı. İçimize kalan alışkanlıklar  beraberken  kendilerini  unuttururlardı. Gözlerimiz yapamazdı sadece bunu çünkü onlar hep gerçeğin peşindeydi. 

	Bazen kızardım sana. Zamanla beni unutacağını düşünüp seni bu kadar sevmeme neden izin verdiğini düşünüp kızardım. Çünkü duygularımın eskiyip, küflenmeyeceği bakiydi. Ben ölsem de hep içinde olacağımı biliyordun. Ve sen de aynı durumdaydın. 

	Ben ölümü sadece senin için istiyordum. Çünkü yanlış zamanda yanlış yerde yaşamıştık. Bu dünya yağmurlarıyla bile bizi hiçi sevmedi. Belki başka bir dünyada başka bir biçimde yetebilirdik. O zaman ne birbirimizi ne kendimizi kandırırdık. Ağlayıp seni düşünmek zaten ölümdü ve ölüm senin için olursa daha tatlıydı.   Anlamıştım ki; 

       Ölüm başkaları için ayrılık, bizim içinse kavuşmak demekti.', 'Önceleri  yetmedik birbirimize, az geldik düşlerimize... sonra sevdik, sonra ağladık. Sonra uyuduk birbirimizi görmek için rüyalarda. Tütsül...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/onceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkedildi', 'terkedildi-hilmi-tanrikulu-1hbgh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Terkedildi.

Uzun, yorgun uykusu terketti.

Gecenin izlerin aradığı, 

Biraz sıcak, biraz soğuk yatağında.

Öğlen vakti.

Gün ışığını örten perdelerdi, 

Yataktı, evdi, düşlerdi, sessizlikti, 

Azıcık günaydın dilendiği.

Güneş doğduğu yerden  batacaktı sanki, 

Unutturuyordu birden, 

Günaydın beklentisini, 

Cinneti.

Biraz bekledi, 

Ortamdaki yalnızlığın, onu kabullenmesini, 

Sessizliğin içini temizlemesini, 

Doğrunun yalandan geçmesini, 

Dışarıdaki seni, beni, 

Bekledi, 

Terkedildi, 

Zamansız sessiz bağırışlar terketti.

Ayakları yalnızlığı ile yoldaş oldu, 

İçindeki boşluk onu kapının önüne 

Uçurdu.

Yürüdü, 

Ağır gözleriyle hayatı süzerek.

Yalnızlığı coştu oyunlar oynayarak.

Düştü; 

	Yanındaki yalnızlığı, 

Sıkıntıydı; 

	Yalnızlığının oyunları.

Gün ışığını örten binalardı.

Kaldırımdı, sokaktı, yalnızlığıydı, insanlardı, sessizlikti, 

Azıcık tebessüm  dilendiği.

Yoktu, olamadı sevdiği, 

Yollar O’ naydı aslında gittiği, 

Eller O ’naydı gerçekte titrediği

Ama yoktu olamadı sevdiği.

Akşamı yaptı, günü kovdu.

Yalnızlığı, yağmur ve yorgunluğu.

Gidişi ve dönüşü bir oldu, 

Bulamadı sonsuzluğu.

Gün ışığını örten geceydi.

Yıldızlardı, aydı, karanlıktı, yataktı, düşleriydi, 

Azıcık iyi geceler dilendiği.

Uykusuna kaçtı.

Sabah onu terk eden.

Geceye kaçtı, 

O ‘ nu kabullenen.

Terkedildi, 

Yaşayamadığı gün terketti.

Sabahtı beklediği...

...Terkedildi.

Uzun, yorgun uykusu terketti.

Gecenin izlerin aradığı, 

Biraz sıcak, biraz soğuk yatağında.

Öğlen vakti...', 'Terkedildi. Uzun, yorgun uykusu terketti. Gecenin izlerin aradığı,  Biraz sıcak, biraz soğuk yatağında. Öğlen vakti. Gün ışığını örten perde...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/terkedildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Bir Yıl', 'yine-bir-yil-mahmut-yildiz-qx4b8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine bir yıl daha mazilerde 

Geri dönülmez bu yolculukta

Kısacık bir kıspıştı gözlerde 

Acı, tatlı anılar izler bıraktı yüreklerde...

Aralık 2001 - İstanbul', 'Yine bir yıl daha mazilerde  Geri dönülmez bu yolculukta Kısacık bir kıspıştı gözlerde  Acı, tatlı anılar izler bıraktı yüreklerde... Aralık...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Yıldız']::text[], 8.5, '{"poet":"Mahmut Yıldız","poet_slug":"mahmut-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yine-bir-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlı Adam', 'yasli-adam-mahmut-yildiz-h5fav', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşlı adam artık güneş görmez olmuştu

Ya da doğa ona pinti davranıyordu

Kara bulutlar mavi göğü buladığında 

Bir damla düşmüyordu civarına 

Mehtaplı ıssız bir gece vaktinde 

Hayaller, beklentiler çöp tenekesinde 

Gözleri dikili kalmıştı kara deliklerde 

Çaresizlikle sonunu beklerdi bu hayat penceresinde 

Ne zaman, nereye açılacağı belli mi olurdu 

İçindeki sızı yalnız kalma korkusuydu...

Aralık 2001 - İstanbul', 'Yaşlı adam artık güneş görmez olmuştu Ya da doğa ona pinti davranıyordu Kara bulutlar mavi göğü buladığında  Bir damla düşmüyordu civarına  ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Yıldız']::text[], 8.5, '{"poet":"Mahmut Yıldız","poet_slug":"mahmut-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasli-adam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günler', 'gunler-mahmut-yildiz-dceh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne hatırlıyorsan geçen günlerden 

Bu gün de öyle kalacak anılarda 

Geçilenleri kar sayma yanına 

Bir zaman o günlerden biri senin olacak 

Hayır diyemeyeceksin ona 

Artık o senin bir felaketin

Ve o senin mezar taşındaki resmin 

Aralık 2001 - İstanbul', 'Ne hatırlıyorsan geçen günlerden  Bu gün de öyle kalacak anılarda  Geçilenleri kar sayma yanına  Bir zaman o günlerden biri senin olacak  Ha...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Yıldız']::text[], 8.5, '{"poet":"Mahmut Yıldız","poet_slug":"mahmut-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tören Başlıyor', 'toren-basliyor-mustafa-nuri-celebi-2584w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ölüm bide aydınlık 

onuda yendim sonunda...

aç ama alnı açık bir çocuk 

fabrika kapısında 

karanlığa doğru bir çığlık 

şimdi duyulacak...

ne kadar da ufalmış bedenin 

göz yaşıma sığdın sonunda 

yoksa güneş 

sendemi batıyor geceleri

ben ölürsem anam

''ölüme'' toplatmayın çiçekleri

çiçeklerimiz bitmezki...

rüzgar dokunsa 

yırtılır canım 

keskin sivrili

lacivert kayalarım.....

hasretim kıldan ince 

gözlerim yüreğinin ardına düşmüş

şu ayaz gecenin başı boş rüzgarı 

tırmandı yine beynime 

yavaş yavaş kapandı perde 

son birkez gülüyordu hayata 

halbiki bilemiyordu nereye gidiyorlardı

güneşe gidiyorlardı...

gidenin ardından analar ağıt yakar 

ben ne yapayım bilmiyorum

gelenede ateşler yakılır karanlıklarda

ölüm bide aydınlık 

onuda yendim sonunda....

yalnızım martıların kanadında 

bir tüğ tanesi...

bazen savaşların ortasında 

bir teneke parçası...

bir körün gözleri ile bakıyorum hayata 

anamın dizinde ağlıyorum

yarim salmış efkarına 

mapusa..

kendisi gelmez yollar kışmıdır

hasret başını eğermiş adamın 

mapustan kalkan uzun bir halayım 

hatır alın baş düşe yana 

kağıt kaleme sarılın...

ahhh bi haykırsam adını 

kuşluktaki dağdan 

ahhh bi haykırsam 

ağzımdaki adında toplanır dünya 

ölüm bide aydınlık 

onuda yendim sonunda', 'ölüm bide aydınlık  onuda yendim sonunda... aç ama alnı açık bir çocuk  fabrika kapısında  karanlığa doğru bir çığlık  şimdi duyulacak... ne...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Nuri Çelebi']::text[], 8.5, '{"poet":"Mustafa Nuri Çelebi","poet_slug":"mustafa-nuri-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/toren-basliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Bilmeli', 'herkes-bilmeli-ozan-arif-cn80f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben ülkücü doğdum bu yoldan asla

Sapmadım sapmam da mümkün değildir.

Makasla kestiler beni makasla

Kopmadım kopmam da mümkün değildir.

Başımı koyduğum mübarek yola

''Ters düştü'' diyormuş bir kaç budala

Yaydıkları gibi paraya pula

Tapmadım tapmam da mümkün değildir.

İhtirasım olsa mal mülk nevale, 

Ben de alkış tutup şimdi şu hale

Ya makam kapardım ya da ihale

Kapmadım kapmadım da mümkün değildir.

Küresellik, globallik, tombulluk

Her şeye he demem yok öyle bolluk

Allah varken Allah, kuluna kulluk

Yapmadım yapmam da mümkün değildir.

Bu Arif''i herkes iyi bilmeli, 

Ne şimdi ne sonra ne de evveli

Ben Türkeş''ten başka bir lider eli

Öpmedim öpmem de mümkün değildir.', 'Ben ülkücü doğdum bu yoldan asla Sapmadım sapmam da mümkün değildir. Makasla kestiler beni makasla Kopmadım kopmam da mümkün değildir. Başım...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/herkes-bilmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkalık Vardı', 'baskalik-vardi-ozan-arif-pv5o9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yemin ediyorum Başbuğum yemin, 

Gülüşünde bile başkalık vardı.

Kürsüye gelirdin kendinden emin

Gelişinde bile başkalık vardı.

Gelip ''Bozkurtlarım'' deyince hele

Zelzele olurdu sanki zelzele

Davudi sesinle mevzuyu ele

Alışında bile başkalık vardı.

Her derdini düşünürdün ülkenin

Ferasetin müthiş, müthişti fenin

Herkesin bildiği konuyu senin 

Bilişinde bile başkalık vardı.', 'Yemin ediyorum Başbuğum yemin,  Gülüşünde bile başkalık vardı. Kürsüye gelirdin kendinden emin Gelişinde bile başkalık vardı. Gelip ''Bozkurt...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/baskalik-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Küçücük Kırılgan', 'ask-kucucuk-kirilgan-nazmi-agil-gox63', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'işte öyle güzeldin, orda suya yazılan

en güzel kasideydin, değsen cemre bir suya

can suyu bir yaşamak - ki gittikçe azalan

iyiyi çoğaltarak - gül mevsimidir diye

yürürdü pıtraklara, usulca, yudum yudum, 

meğer su küçüğünmüş, söze kandım büyüdüm', 'işte öyle güzeldin, orda suya yazılan en güzel kasideydin, değsen cemre bir suya can suyu bir yaşamak - ki gittikçe azalan iyiyi çoğaltarak ...', ARRAY['Türk Edebiyatı','Şiir','Nazmi Ağıl']::text[], 8.5, '{"poet":"Nazmi Ağıl","poet_slug":"nazmi-agil","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-kucucuk-kirilgan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günü Suya Yazmak', 'gunu-suya-yazmak-deger-ulas-turan-54g0z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suyu dinledik seninle, 

Gizli hecelerin 

Dökülen beyazları içinde 

Dinledik aşkın denize dökülüşünü... 

Sahil boyunda adımların 

Hep ardıma ardıma vurur, 

Su kıyıya, aşkın günceme. 

Adımladın ardım sıra yüreğimi... 

Konuşup ta üzmedik say geçmişi, 

Suya yazdım, 

Adımlarını. 

Ardım senden kalanla kanıyor.

Suyu dinledik, 

Şarkı bitti... 

Gün suya, karıştı 

Ben sana yazamadım sevdamı... 

Suyu dinledik, 

Çağlayık kanadı gözlerinden... 

Kulağında duruldu cesareti, 

Çizgisinde kayboldu gün... 

İçimde içsiz bir kadını yaşatırken, 

Boşluğuna her şeyi koyabilen. 

İçimde gizli bir yarayı yaşıyorum, 

Her dokunuşta tazelenen. 

Beklettiğim umuda ihanet ederken, 

Sarıldığım mazide kirli bir aşka 

Yazamıyorum suyun berraklığını. 

Birde utanmadan suyu dinliyoruz seninle. 

İnsan ne kadarda kirli yaşıyor, 

Bilebile geçmişini, 

Dinlediğinde arınıyor. 

Ben seninle sudan uzak yaşıyorum. 

Biz seninle suyu dinlerdik, 

Bir zaman umuda tutunarak. 

Şimdi sonsuzluğu veremezken gün suya 

Sana yazamazdım sonsuzluğu... 

Bu yüzden günü suya yazmak boştur 

Ve aşkı yaşamak kirli geçmişiyle...', 'Suyu dinledik seninle,  Gizli hecelerin  Dökülen beyazları içinde  Dinledik aşkın denize dökülüşünü...  Sahil boyunda adımların  Hep ardıma ...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/gunu-suya-yazmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendim Gibi', 'kendim-gibi-deger-ulas-turan-5f7ou', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkı tecritte yaşayan, 

Her yüreğe verin ellerimi. 

Aşkı acıtan sesleriyle, 

Yankılarında kanayan ellerimi... 

Biliyoruz geç kaldık her şeye 

Ve her şeyin bir sonu olması da bundan... 

Her şeyimiz varken geç kalmışlığımızla, 

Yoktuk içinde, yoksulduk... 

Geçen zamanı ayıklar tarih ustaları, 

Taş diye biz çıkarız sentezinden... 

Ayıklanan bir gerçeğiz 

Ve tarihe yazılmaz varlığımız... 

Biz asır içinde, bir ufak zamanı 

Ömür diye taşırız aşkımızla... 

İçinde ömür olan her yeni yoksulluk, 

Bin kere geçer içinden sonsuzluğun... 

Sahici gibiydi renklerimiz, 

Veriyorken kendini gerçeğe. 

Tutuşturulmuş geceye bile 

Alevin kırmızısını yanıl satıyoruz. 

Sen, 

Ben ve diğerleri sayıyoruz 

Yaşadığımız bu mutasyonu 

Sıfatı hazır,

Sen ben ve... 

Oysaki her şey böyle miydi? 

Tarih böyle mi yazacaktı bizsizliği. 

Kendim gibiler varken hiç yok sayıldı gerçek, 

Her sayımda adam başı bir ömür ederdik hâlbuki. 

Şimdi biz dudaklarımızı 

Acıya nemli bir haykırışla kanatıyoruz... 

Geçmişe hayır diyemedik ama 

Gerçeğe, geleceğe biz de varız diyebilmekle yaşıyoruz...', 'Aşkı tecritte yaşayan,  Her yüreğe verin ellerimi.  Aşkı acıtan sesleriyle,  Yankılarında kanayan ellerimi...  Biliyoruz geç kaldık her şeye...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kendim-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam', 'adam-deger-ulas-turan-lp73m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adam

Fotoğraf gibi yaşadık, 

Renkleri gün geçtikçe soldu ömrümüzün.. 

İlk anında bir heyecansa, 

Sonunda bir yırtılıştı bütün bunlar.. 

Biz yorgun atlar gibiydik, 

Büyük ovalarında hayatın... 

Şahlanır gibi, tepe taklak yuvarlanışlar.. 

Biz büyük ovaların ölü atlarıyız artık.. 

Bir adanın iki yabancısıyız, 

Sadece sen ve yalnızlığım yaşar... 

Buluşmalar yoktur sahilinde, 

Sen bir dağ ve ben okyanus serinliği.. 

İlkin ellerimi yalnız bıraktı hayat, 

Sonra gözlerim sonsuzluğu buldu... 

Bir adım daha geride umut, 

Yol aldıktan çok sonra farkındayım her şeyin... 

Buradan bakınca her şey gariptir, 

Önemli olanı bakmasında, 

Baktıkça düşer cümleler, 

Çıkar ortaya kayıp kafiyeler. 

Devamını sağladığım rüyaları 

Ve sonra çocukları, 

Ellerinde küçük sevinçleriyle, 

Tek tek yazdım geçmişe... 

Hırpalandığım düşlerimde, 

Ben ayyaş bir sokak şövalyesi; 

Savaşımın içinde, 

Sen bir sokak kadını... 

Ve bulamam tenini, 

Ellerimi saklamıştım oysa... 

Şimdi öyle bir adam düşün, 

Çocuksu suretinde bir ihtiyarı 

Ve cümlelerin anlamsız çığlıklarını... 

Düşün, 

Özlediği bir kadını yakarken 

Adam, kendini yaktı kadınında...', 'Adam Fotoğraf gibi yaşadık,  Renkleri gün geçtikçe soldu ömrümüzün..  İlk anında bir heyecansa,  Sonunda bir yırtılıştı bütün bunlar..  Biz ...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/adam-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Ayrı Olsakta', 'artik-ayri-olsakta-aydin-karatay-izwtx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başka 

özlem var burada bu sefer 

hasretin kokusu sinmiş duvarlara 

bir karayazı olumsuz özneler gibi

gidişin gibi ama sessiz 

kırılmış ve üzerine basılmış hatıralar sacılı 

                                                            etrafa 

Başka 

sadece seni düşünmek var bu sefer 

sadece eskilerle yetinmek 

ve yokluğuna alışmak var 

ne kadar alışamamış olsamda 

gezdiğimiz sokaklarda ne kadar özlem koksada 

                                                           sedir ağaçları 

sadece yokluguna alışmak var 

yağmurlar bile anlamış megersem 

eskisi gibi ıslatmıyorlar artık otobüs beklerken 

hele o yolculukların su gibi aktıgı zamansız yollar 

onlarda anlamış artık bir sonu var 

                                                             inanmasanda 

Başka

olmasına başkada galiba 

bir ben aynıyım galiba 

her zamanki gibi saf inançlı 

ve her zamanki gibi saçma sapan düşlerde kayıp

çayımı da hala aynı şekilde içiyorum

biraz açık az şekerli

hayatıda zehir tadında yaşıyorum galiba

                                                          artık ayrı olsakta

Başka 

zevk vermiyor artık yaşamak 

ölüm korkutmuyor gözümü eskisi kadar

ve tirenler gürültü çıkarmıyor artık rayların üzerinde 

insanlar bir garip yürümüyorlar galiba 

boşa adım atıyorlar gibi

yada boşa yaşıyorlar 

aslında yaşamak adına yaşayamasakta 

yaşıyoruz degilmi

                                                          artık ayrı olsakta

                                                          05 - 04 - 00

                                                     bursa/karacabey', 'Başka  özlem var burada bu sefer  hasretin kokusu sinmiş duvarlara  bir karayazı olumsuz özneler gibi gidişin gibi ama sessiz  kırılmış ve ü...', ARRAY['Türk Edebiyatı','Şiir','Aydın Karatay']::text[], 8.5, '{"poet":"Aydın Karatay","poet_slug":"aydin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/artik-ayri-olsakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli Belirsiz', 'belli-belirsiz-aydin-karatay-8wxqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bellibelirsiz düşünceler 

yollar dar soguk ve karanlık 

yollar ki düzlüklere sığamamış yaşamlar 

hep yokuş hep rampa

belli belirsiz düşünceler

kıyıya vurmuş hayallerim ufak bir ada 

sıcak bir kumsal yinede bir yol var 

dönüp dönüp beni başladıgım yere geri getiren 

belli belirsiz düşünceler

içimin odalarında kilitli kalmış bir keder 

yapılması gerekenler arasında kaybolmuş 

saklama tarihi geçmiş heceler ve buzlanmış bazı kelimeler

bir kibrit çöpü kadar değersiz bazen 

bazende bir okadarda degerli yeri geldiğinde 

huzursuzlugumun raflarına kaldırılmış dostluklar 

tozlanmış ve kirli hatıralar zaman caddesinde 

hüznüne yenik düşmüş bir rüzgar 

yavaş yavaş dönüyor geri 

oysa...........................................

belli bellirsiz düşünceler

sonsuzluga sıkışmış zaman durmuş gibi

yaşanmayan umutlar yaşanmayı beklerken yaşlanmış

yinede muttluluk sahile vuruyor dalgalar gibi

eskisi kadar şiddetli esmesede lodos 

kayıplara karışmış bir şeyler untulmuş olsada 

saklayamadıgımız yüzlerimiz gibi olmasada 

gözlerimiz gibi içimiz.............................

belli belirsiz düşünceler....

belli belirsiz düşünceler......

06  -  04  -  02        00.36        izmir.........................', 'bellibelirsiz düşünceler  yollar dar soguk ve karanlık  yollar ki düzlüklere sığamamış yaşamlar  hep yokuş hep rampa belli belirsiz düşüncel...', ARRAY['Türk Edebiyatı','Şiir','Aydın Karatay']::text[], 8.5, '{"poet":"Aydın Karatay","poet_slug":"aydin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/belli-belirsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz', 'olumsuz-deger-ulas-turan-wi96v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne söylenir ki? 

Hangi sözcük kendini aklar yüreğinde? 

Sen renkler içinde tutunamayan, 

Beyaz bir umuttun yüreğinle… 

Ve acılardan geçtin 

Bir savaşçı gibi savaşarak.. 

Öldürüldün binlerce kere 

Ve dirilttin binlerce duyguyu. 

Her şeye rağmen… 

Ne söylenebilirdi ki? 

Şimdilerde ölüm sözcüğüyle 

Bu kadar samimiyken, 

Dudakların kurumuşken acılardan 

Ve renklerini dökmüşken umutların 

Ne söylenebilir? 

Ey insan kalan... 

Hadi! 

Okyanuslar diyorsun, 

Açıklara uzanıyor duyguların 

Ama kıyısında boğuluyorsun 

Enginlere varamadan... 

Bense çoktan kaçmıyorum 

Bu karanlıktan 

Bir korkak gibi... 

Ne denebilir ki? 

Gücün yetmezdi elbet... 

İşte senin zaferin! 

Evet, zafer diyorum. 

Çünkü bu savaşlarda insanlar, 

Leşlerinden güç alıp, 

Kanla yürüttüler bu düzeni... 

Ve kalleştirler çoğu kez, 

Sevdaları kanatıp, 

Umutları çürütüp gittiler... 

Ve sen artık sorgulama kendini, 

Kimliğinden utanma, 

Ellerinde yarım bırakma sevinçleri 

Neden, nasıl deme... 

Biliyorum 

Ve nefret ediyorum bilmekten... 

Sen gerçeğini kazandın işte 

Gülmeni isterim daima, 

Bir kahraman gibi. 

Sen de yozlaşıp gidebilirsin belki de 

Bu uçurum serinliğinde... 

Cesaret bahçelerinde açabilirsin 

Bir yaban gülü adını taşır... 

-Ki zaman olur da, 

Atıverir kendini, senin serildiğin yamaçlara

Acılarıyla yozlaşan bir serüvenci 

Seni koparıp götürebilir beraberinde belki de... 

Ama artık şunu bilmeni isterim 

Gerçekte senin varlığınla yaşamak, 

Var olmanın en güzeli... 

Artık hiç niyetim yok uçurumlarda dolaşmaya 

Seni sadece var olduğun yerleri seyretmek, 

Güzelliğini ve mükemmelliğini 

Bu derinlerden görmek 

Bekleyişlerin en umutlusu... 

Ve inanışım o ki 

Mutluluk hep senin olacak. 

Anlaman gerek. 

Anla, 

Ve hissettiklerin çoğalsın; 

Nefretten ve kinden başka 

Başkalaşsın 

Ve özüne dönsün duyguların… 

Ne denebilir ki? 

Bir affedişi yok! 

Biliyorum... 

Renkleriyle cebelleşiyorum acıların... 

Tanımlarını çıkaramıyorum; 

Tanımlatamıyorum bilincime. 

Zaten nasıl anlatılır, 

Bir acı bin acıya boy verirken... 

Yani tanımını yapabilir mi 

En bilge olan... 

Ölümsüzlüğüme inat, 

Vicdanımın beni her gün 

Aynı şatoda bin türlü işkencesiyle 

Öldürmesi yetmez mi... 

Evet ''ÖLÜMSÜZLÜK'' diyorsun… 

Bil ki ölümsüzlük sevgimden 

Ve senden geliyor... 

Aslolan ölümsüz,‘AŞKIM’ dır.', 'Ne söylenir ki?  Hangi sözcük kendini aklar yüreğinde?  Sen renkler içinde tutunamayan,  Beyaz bir umuttun yüreğinle…  Ve acılardan geçtin  ...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/olumsuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinek De Olsa', 'sinek-de-olsa-sukru-tarla-818ey', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oduna gitmem, bakmadan boyuma, 

Uyarsa alırım, huyu huyuma.

Bakmam anasının meçhul soyuna, 

Tosun doğuruyor inek de olsa...

İyi düşünmeden sözü söylemem.

Duyduğumu hemen tasdik eylemem.

Görünüşe bakıp karar veremem, 

Biraz iman vardır, dönek de olsa...

Elifi bilmeyen takıyor kavuk, 

Kartal suretine girmede tavuk.

Belli olmaz hürmetkarla dalkavuk, 

Korkarım onlardan, sinek de olsa...

Şükrü’yüm, aklıma eseni derim, 

Dünya neme gerek! Yoktur kederim.

Akıllanmaz zannediyor pederim, 

Uslanır dayakla, eşek de olsa...

(Kayseri,16.12.1971)', 'Oduna gitmem, bakmadan boyuma,  Uyarsa alırım, huyu huyuma. Bakmam anasının meçhul soyuna,  Tosun doğuruyor inek de olsa... İyi düşünmeden s...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tarla']::text[], 8.5, '{"poet":"Şükrü Tarla","poet_slug":"sukru-tarla","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sinek-de-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ol Günden Beri', 'ol-gunden-beri-sukru-tarla-zz78g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir zaman candan severdim kalbi altın bir kızı

Gök ve yer şahitti aşka gizli seyretmiş bizi

Geçti günler kaldı ondan yadigar ismi bana

Ruhuma bir hüzn-ü sevda verdi ol günden beri

Mecnunum artık ne ondan var ne zevkten bir haber

Yaptığım herşey belirsiz bense benden bihaber

İşte söndü kalbimin nuru ne hal oldu bana

Hep karanlık dertli ferda verdi ol günden beri

“Kız, ” dedim, “gel, insaf et, gücendirme beni.

Karşılıksız koyma aşkım, böyle öldürme beni.”

Bir gün aldım bir haber ki, pek melal oldu bana

Şükrü’ye bir dil-i şeyda verdi ol günden beri.

(Kayseri,27.03.1974)', 'Bir zaman candan severdim kalbi altın bir kızı Gök ve yer şahitti aşka gizli seyretmiş bizi Geçti günler kaldı ondan yadigar ismi bana Ruhum...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tarla']::text[], 8.5, '{"poet":"Şükrü Tarla","poet_slug":"sukru-tarla","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ol-gunden-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıladan Uzak', 'siladan-uzak-sukru-tarla-3w578', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neresinden tutam kahpe dünyanın, 

Her neye el atsam, yanık kokusu.

Kalbimden çıkmıyor aşkı sılanın, 

Burnumda vatanın sönük kokusu.

Yadelde yalınız gezemiyorum, 

Sonu neye varır, sezemiyorum.

Ben eski halime benzemiyorum, 

Daha iş başında, panik kokusu.

Kafese koymuşlar burda çeşmeyi, 

Unuttum pınardan saf su içmeyi.

Yapamadım bir arkadaş seçmeyi, 

Hangi yüze baksam, sanık kokusu.

(Ankara,08.11.1974)', 'Neresinden tutam kahpe dünyanın,  Her neye el atsam, yanık kokusu. Kalbimden çıkmıyor aşkı sılanın,  Burnumda vatanın sönük kokusu. Yadelde ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tarla']::text[], 8.5, '{"poet":"Şükrü Tarla","poet_slug":"sukru-tarla","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siladan-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurdaki Sevgilim', 'yagmurdaki-sevgilim-sukru-tarla-7kc08', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çılgıncasına yağmur...

“Sen yağmurdan, ben aşkından

Sırılsıklam...”

Dışarıda yağmur sesleri, 

İçerde aşk ıstırabı.

Kim anlatabilir bu hisleri? 

Soram...

Habire alev, birkaç gözyaşı.

Titreyen dudaklar...

Sevdaymış bunun adı! 

Senin yoluna adadım bu başı! 

Aşkına kurban olam! ..

Delicesine yağmur...

Sevgi yağmuru.

Ne kadar sevenin var dünyada! 

Kışın, yazın, baharın, 

Yağmurun, dolun, karın

Ben olam.

Yağmurdan kaçışan adamlar...

Buğulu camlar...

Tüm güllere şemsiye gerek! ..

Hasta olacaklar giderek...

Gel yanıma sevdiğim, gel yanıma.

Her zaman sığın kanadıma.

Üşüme, ıslanma kurban olduğum! 

Şemsiyen olam! 

(Ankara,18.05.1975)', 'Çılgıncasına yağmur... “Sen yağmurdan, ben aşkından Sırılsıklam...” Dışarıda yağmur sesleri,  İçerde aşk ıstırabı. Kim anlatabilir bu hisler...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tarla']::text[], 8.5, '{"poet":"Şükrü Tarla","poet_slug":"sukru-tarla","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yagmurdaki-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Entrikalar Çiftliği', 'entrikalar-ciftligi-sukru-tarla-n6mri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Atamalar-

Çiftliğin halini duydunuz zahir, 

Bilmeyen var ise anlatam bir-bir.

Sonradan istemem tek sitem-kahir.

Çiftlik bizim için en son vatandı, 

Kümese bir tilki, horoz atandı.

Köpekler sürüyü daladı hepten, 

Uludu: ”-Süremez böyle, bu düzen! 

Sürmeli Çoban’ı bu memleketten”.

Kokarca fırlattı -koku atandı-: 

“-Atlara birkaç kurt, seyis atandı”.

Kedi miyavladı: ”-Bu ne iştir yav! 

Biz de istiyoruz, tavuklu pilav.

Fareler özgür bırakılsın, miyav”.

Onlar hep soba dibinde yatandı, 

Uygun görüldü, müşavir atandı.

İnek dedi: ”-Moo moo, süt vermiyecem”, 

Öküz de katıldı: ”-Çift sürmiyecem”.

Zağar ürdü: ”-Kapıda durmıyacam”.

Bir lokma tezeğe göbek atandı: 

Hınzır da mutfağa aşçı atandı.

Horoz öttü: ”-Olmasam çiftlik onmaz, 

Hayvan haklarını kimse savunmaz”.

Beygir müstafidir, dolap da dönmez.

Kazlar ürkünce sazlığa saklandı, 

Katır da revire baytar atandı.

Eşek anırdı: “-Şifayım kulağa, 

Beni kahya yapın çiftlikle bağa”.

On bir çoban iti etti istifa.

Gerçekten bu durum enteresandı, 

Kirpi dış destekle kahya atandı.

(Ankara,12.01.1978)', '-Atamalar- Çiftliğin halini duydunuz zahir,  Bilmeyen var ise anlatam bir-bir. Sonradan istemem tek sitem-kahir. Çiftlik bizim için en son v...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tarla']::text[], 8.5, '{"poet":"Şükrü Tarla","poet_slug":"sukru-tarla","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/entrikalar-ciftligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgün Tekniker', 'uzgun-tekniker-sukru-tarla-k8g4m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Benim gibiler adına-

Teknik öğretmenim, vatana hizmet

Edip, endüstriye şan veriyorum.

Bilgi ile teknik, bende azamet

Kazanır, zulmete son veriyorum.

Ama, dertler gölge gibi izimde.

Küçük bir memurum, devlet gözünde.

Hayatım, gündüzün hain “gez”inde, 

Gece, düşlerimde can veriyorum.

Maaşı kaptırdım vergiye-borca, 

Çilem hiç bitmiyor: Harca da harca! 

Örgütler pek vahşi, ezer hunharca, 

Dost düşünse, akla son geliyorum.

Neler düşlemiştim, işe başlarken! 

Sevmiştim görevi ilk derste, hemen.

Şimdi artık bizi –güya- yöneten

İlgili Bey’lere gün veriyorum: 

Bu gidişle insanlıktan çıkarız, 

Odun için evimizi yakarız.

Gün gelir, hor görülmekten bıkarız.

Yurdu terketmeyi hayalliyorum: 

Gidiyorum bir gün gurbet yoluna, 

Diyorum “orada belki buluna

Bizi tutan bir yer, orda kalına.”

Orda yiyip-içip, yan geliyorum.

Lacivertlerimi düğmeliyorum, 

İstese bir ülke, ben geliyorum.

Siyasilerimiz tutmaz sözünü, 

“Ben çekemem Kürt kızının nazını.”

Sevin, alıyorsun, malın özünü.

Mektubun geldi, her an geliyorum.

Borç ile karımı dengeliyorum, 

Bekle Alamanya, ben geliyorum.

Sana satılacak elde malım yok, 

Devalüasyondan, param-pulum yok.

Zamların zoruyla sattım, çulum yok, 

İnan, bir gömlek, bir don, geliyorum.

Sebep olanları iğneliyorum, 

Bekle Alamanya, ben geliyorum.

Sermaye yapınca, hemen kaçmalı, 

Memlekette bir atölye açmalı.

Gönül istemez mi, her kuş uçmalı, 

Galiba, Bey’lere bön geliyorum.

Gideceğim, ama hem senin için

Bir şey kazanayım, hem kendim için.

Milletim! Dua et bu gencin için, 

Kısmetse, dönüşte şen geliyorum.

Yetiştirmek için kaç hoca tuttun? 

Tekniğin hakkını ne tez unuttun! 

Gavura hizmet için mi okuttun! 

İnşallah cebimde fen, geliyorum.

(Alaplı,28.03.1980)', '-Benim gibiler adına- Teknik öğretmenim, vatana hizmet Edip, endüstriye şan veriyorum. Bilgi ile teknik, bende azamet Kazanır, zulmete son v...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tarla']::text[], 8.5, '{"poet":"Şükrü Tarla","poet_slug":"sukru-tarla","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/uzgun-tekniker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırdın Orta Direği', 'kirdin-orta-diregi-sukru-tarla-z7yhk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Orta direk dedin, kırdın belini, 

Soldurdun milletin gonca gülünü.

Şöyle bir dolaş da seyret halini: 

Çarşıda Efendi, Bey bırakmadın.

Başta çok tutmuştuk milletçe, sizi, 

Üst-üste vermiştik hep reyimizi.

Radyasyon, zam ile korkuttun bizi, 

Keyifle içecek çay bırakmadın.

Getirdiğin her şey uydu zengine, 

Fakirin tasası arttı gün-güne.

Rol yapmada kimse çıkmaz dengine, 

Sözde, cüce kalmış boy bırakmadın.

Vergi şampiyonu, memurlar oldu.

KDV, satanın cebinde kaldı.

Fiyat kontrolleri sayende öldü! 

Zengine vermedik pay bırakmadın.

Pembeyle boyadın üstünü morun, 

Her defa dansettin, hep öttü borun. 

“İcraat içinde” kalmadı “sorun”, 

Refaha ermemiş ay bırakmadın (!) 

Ahlaka en büyük darbeyi vurdun, 

Rüşveti hoş gören kanun uydurdun.

Azeri kardeşler yanarken, durdun, 

Küstürdün, tutkun bir soy bırakmadın.

İşçi yarım maaşa sevinemiyor, 

İkinci kanalla avunamıyor.

Vicdanı olanlar savunamıyor, 

Artık güven denen şey bırakmadın.

Bir AET için çok takla attın, 

Onlar ile kalktın, onlarla yattın.

Millet malı olan ne varsa sattın, 

Kısrağın altında tay bırakmadın.

Gavur işgalini sen ettin yasal, 

İsrail gerçeği olmadı misal.

Türk’e has ne varsa eyledin masal, 

Bir milli an’ane, toy bırakmadın.

Milletçe çok şendik, buydu özümüz, 

İnsanı sevmekti temel tezimiz.

Son zamanlar gülmez oldu yüzümüz, 

Kimsede şen-şakrak huy bırakmadın.

Getirdin, haini bayrağa sardın.

Yetmedi, askerin sırtına vurdun! 

Yüzüğü biz taktık, sen ele vardın, 

Bizlerden alacak oy bırakmadın.

Söyler misin bugün kaç “Çağ” atladın? 

Fabrika sayısını kaç katladın? 

Yoksulun başında fena patladın, 

Yetimin başında tüy bırakmadın.

(Kayseri,20.11.1987)', 'Orta direk dedin, kırdın belini,  Soldurdun milletin gonca gülünü. Şöyle bir dolaş da seyret halini:  Çarşıda Efendi, Bey bırakmadın. Başta ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tarla']::text[], 8.5, '{"poet":"Şükrü Tarla","poet_slug":"sukru-tarla","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kirdin-orta-diregi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Elini Bayrağımdan', 'cek-elini-bayragimdan-sukru-tarla-yc0l7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ulan PKK’lı veled-i zina! 

Çek elini bayrağımdan, şerefsiz! 

Seni kimler böyle eyledi bina? 

Çek elini bayrağımdan, şerefsiz! 

Sana köpek demem, köpeğe yazık.

O bile cinsine çok daha nazik.

Belli, senin soyun, kanın da bozuk! 

Çek elini bayrağımdan, şerefsiz! 

Düşmansan da saygılı ol marşıma, 

Gizli-gizli bomba koyma çarşıma.

Erkek isen, erkekçe çık karşıma, 

Çek elini bayrağımdan, şerefsiz! 

Türkiye’de halklar yoktur. Millet var! 

Asırlardır birlik oldu insanlar.

Belli... Sizin beyninizde illet var! 

Çek elini bayrağımdan, şerefsiz! 

Habire sinsice planlar kurma.

Öne çık, kalleşçe arkadan vurma.

Sevmiyorsan bu ülkeyi, çık. Durma! 

Çek elini bayrağımdan, şerefsiz! 

Ya yola gel, tarafımızdan af ol, 

Ya çek sürünü, karşımda saf-saf ol.

Ya sev bayrağımı, ya da git, defol! 

Çek elini bayrağımdan, şerefsiz! 

Şükrü’yüm, işte son sözü  söylerim, 

Bütün sapıklara ilan eylerim: 

Ayağa kalkarsam pişman eylerim! 

Çek elini bayrağımdan, şerefsiz! 

(Kayseri,29.06.1996)', 'Ulan PKK’lı veled-i zina!  Çek elini bayrağımdan, şerefsiz!  Seni kimler böyle eyledi bina?  Çek elini bayrağımdan, şerefsiz!  Sana köpek de...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Tarla']::text[], 8.5, '{"poet":"Şükrü Tarla","poet_slug":"sukru-tarla","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cek-elini-bayragimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-gece-karasi-s1kmv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman  senden  bir şikayetim var

Kime anlatayım derdimi? 

Ahlarla vahlarla doldurdun ömrümü...

Saclarıma karlar yağdırdın

Kollarında kaybettim ben beni...

Zaman seni kime şikayet edeyim? 

Durmayı bilemedin bir yerlerde...

Yüreğime düşmeden acılar kor gibi, 

Yüzüme derin cizgiler cekmeden, 

Gecip gittin  be zaman insaf etmeden

gece karası   2002 İstanbul', 'Zaman  senden  bir şikayetim var Kime anlatayım derdimi?  Ahlarla vahlarla doldurdun ömrümü... Saclarıma karlar yağdırdın Kollarında kaybett...', ARRAY['Türk Edebiyatı','Şiir','Gece Karası']::text[], 8.5, '{"poet":"Gece Karası","poet_slug":"gece-karasi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zaman-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum Dün', 'dostum-dun-burcu-ergun-n7yyh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''''Dostumdun'''' diyerek başlayan 

Bir kaç kelimeyle dökülmek istedim anılara 

Aslına bakarsan bu söyleyiş 

O kadar çok tekrardı ki; benim için 

Yine, yine, yeniden kelimelerinin 

Boğazıma dizilişi 

Oysa seni hissetmeyi 

Seni geriye getirebilmeyi 

Ve dostumsun diyebilmeyi; 

O kadar çok isterdim ki; 

Ayrılmaya o kadar duyarlıydı ki dünyam 

Topraklar bile sana varamayan 

Adımlarına küskündü. 

Özüm özüm özlemim ta derinden gelen 

Hastanın nefesiydi sensizliği solumak. 

Artık hiç aldanmamışların 

O engin iç rahatlığına hasretim. 

Güvenmek İyidir Ama 

Güvenmemek Daha İyidir...', '''''Dostumdun'''' diyerek başlayan  Bir kaç kelimeyle dökülmek istedim anılara  Aslına bakarsan bu söyleyiş  O kadar çok tekrardı ki; benim için...', ARRAY['Türk Edebiyatı','Şiir','Burcu Ergün']::text[], 8.5, '{"poet":"Burcu Ergün","poet_slug":"burcu-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dostum-dun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Qartal yuxusu', 'qartal-yuxusu-ahmet-hani-8ar0d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece idi.

Dörd duvar dörümde

Dörd mile qarşimda 

Sanki her biri.

Yuxu görürdüm

Qartal yuxusu görürdüm.

-

10  august  1993', 'Gece idi. Dörd duvar dörümde Dörd mile qarşimda  Sanki her biri. Yuxu görürdüm Qartal yuxusu görürdüm. - 10  august  1993...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/qartal-yuxusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgem düşmüyor Artık Evinin Duvarlarına', 'golgem-dusmuyor-artik-evinin-duvarlarina-cezmi-ersoz-p6qmu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hadi gir içeri. Ama gözlerindeki o kanayan suçluluk bırak kapıda kalsın. Ona ihtiyacımız yok artık. O hayatın içine birtürlü sığamayan ve telaşından durmadan sigaraya sarılan yorgun ellerini, nereye baksan hep karşında duran o kırgın çocukluğunu, uzak denizlerin sisli buğusuyla her daim ıslak dudaklarını, ruhumun tek sığınağı o tarifsiz kokunu kapıda bırak. Tutkunu olduğum neyin varsa hepsini bırak kapıda. Yoksa ne kadar istesem de konuşamam seninle. Konuşamam, yalnızca ağlarım. 

Ne olur gir içeri. Ama girerken tut elinden sevdanın. Yıllar sonra seni yeniden uzağıma düşüren, seni o geri dönüşü olmayan yollara düşüren, yüreğinden aşkımı, dudaklarından adımı, evinden gölgemi silip götüren, o adını kimselere söylemeden ölmek istediğin, o, hiç kimseyi bu kadar sevmedim ki, dediğin sevdanı al yanına ve gir içeri. İlk aşkının yüzünü yanına al. Utanma benden n''olur. Kalbindeki o sızının halinden en çok aşkınla kavrulmuş yüreğim anlar benim... 

Kapat kapıyı. Kapat, içeri hayat girmesin. İçeri yalanlar girmesin. İhanetler, ihtiraslar, oyunlar, maskeler girmesin içeri. Çünkü burada yalnızca sevdan oturuyor. Hayatın içinde soluk alamayan, kendine kalbinde bir yer bulamayan sevdan oturuyor bu evde. Bak, bu ev benim yüreğim. Ne zaman kalbinden kovulsam, ne zaman hayatın ortasında öyle hazırlıksız, öyle savunmasız, öyle yapayalnız kalakalsam gelip sığındığım bu dört duvar benim yüreğim. Burası aşkımın mabedi. Burası sensizliğimin kalesi. Burası deliliğim... Burası baştan ayağa sensin, sevgilim.

Sana sevgilim diyorum hala, bağışla beni. Sen artık bir başkasının sevgilisisin. Yalnızca bu cümleyi kurmamak için bile ölmek isterdim. Seni sonsuza dek kaybettiğim bu günleri hiç yaşamadan ölmek isterdim. Adım dudaklarında yok olmadan, tenim teninde henüz solmadan, daha böylesi yabancın olmadan... Gözlerine baktığımda kendimin değil, bir başka aşkın aksini görmeden önce ölmek isterdim. Ama yapamadım. Nice kaybedişlerden, nice savruluşlardan sonra, artık bu aşkı hayatın pençesinden kurtardık, o dünyevi ihtiraslardan, oyunlardan sıyrıldık ve şimdi artık Tanrı''ya yaklaştık dediğim anda, hayatı, dünyayı ve kaderi yendik dediğim anda, kalbin kalbimin yanında atarken, çocukluğum çocukluğunun ellerinden tutarken, içinde o annemin rahmi kadar huzurlu kokunu soluyarak nefes aldığım yüreğini bırakıp gidemedim. Çünkü zaten hayattan kopmuştum ve cennetteydim. Aşkınla öylesine sarhoştum ki birgün cennetimden kovulacağıma hiç inanmak istemedim.

Evimin, şu talan olmuş yüreğimin dağınıklığını bağışla. Sensizliğe benimle beraber ağladı bu duvarlar. Rutubetleri ondan, aldırma. Otur şöyle, bir sigara yak. Konuşalım. Sözcüklerle değil, sevdamızla konuşalım. Anlatalım herşeyi. Sonra söz bitsin. Ölüme kadar yalnızca susalım. Anlatalım ki bu sevda kanatlarından kırgınlıklarla bağlı kalmasın bu çirkef hayata. Kurtulsun yüklerinden, bağışlasın hayatı ve sonsuzluğa uçabilsin huzurla. 

Biliyorum. Seni böylesi sonsuz bir aşkla severek çok büyük bir günah işledim ben. Hayatın girdaplarında savrulup duran ruhuna o yarım ruhumun ağırlığını yükleyerek çok büyük günah işledim. Ne yaptıysan sevdim seni, ne yaşadıysan sevdim. Aşkın o bulup bulup kaybetme oyunlarından yaptığın zırhın içine sakladığın kalbini ne yaparsan yap yıkılmayarak, vazgeçmeyerek ve hep affederek savunmasız bıraktım. Hiç solmayan bir sevda çiçeği olup bozdum ezberini. Direncini kırdım, kalbine girdim. Seni bir kalbi fethetmenin, ona her an kaybedebilme ihtimaliyle bağlanmanın, bir aşk için çırpınmanın o karanlık hazzından mahrum bıraktım. Affet beni, seni aşkın o dünyevi oyunlarından mahrum bıraktım. Belki de bunun için gözyaşlarıyla kazandığın ve yitirmekten çok korktuğun bir sevgiliyi sever gibi değil, sesini birtürlü susturamadığın vicdanını ya da o kusursuz ve daimi sevgisinden bunaldığın ve bu yüzden incitmekten asla çekinmediğin anneni sever gibi sevdin beni. Ama hiç aşık olmadın. Bu yüzden suçlama kendini. Asıl suçlu, bu hayatta kendine yer bulamayan, nereye gitse ya eksik ya fazla kalan, hayatı bir oyun gibi görmeyi ve kurallarına göre oynamayı hep reddeden benim o isyankar, o yaralı ve yabancı ruhum... Sen değilsin sevgilim.

Hayatında önce bir sığıntı gibi yaşamaya, sonra seni kaybetmeye, ardından seni paylaşmaya, sonunda tam da sana kavuştum sanırken aşkın değil vicdanın olmaya, senin için aklına ne gelirse ona dönüşmeye razı oldum hep, katlandım. Hiç pişman olmadım seni sevmekten. Sana hiç kırılmadım. Hep anladım seni. Hayatın içinde soluk alan ve hayat kadar acımasızlaşan o karanlık yanını, buralara ait olmayan, annenin kırgın ömrünün kıyılarında unutulmuş, o yaralı, o sevgiye hasret çocukluğunun, hayatla uzlaşamamış aşk kırgını, yitik ilk gençliğinin ve herşeyin farkında olmanın çaresizliğiyle derinleşen yüzündeki çizgilerin aşkına bağışladım. 

Sevdim seni sevgili, sevdim... Seni o birtürlü kucaklayamadığım, ama başımı kaldırıp bakmasam bile hep orada, yukarda olduğunu bildiğim gökyüzüne duyduğum hasret gibi... Seni o suyundan hiç içmediğim, toprağına hiç basmadığım, insanlarını hiç tanımadığım, ama herşeyden kaçıp sığınmak istediğim o uzak ülkelerin hayali gibi... Seni aşkın için gözümü hiç kırpmadan arkamda bıraktığım, gözyaşlarını ve o yaralı ömrünü vicdanım gibi hep içimde sakladığım annemin karşılığı bu hayatta mümkün olmayan duaları gibi... Seni o rahmimden kanaya kanaya söküp atmak zorunda kaldığım, ama kalbimde aşkınla besleyerek büyüttüğüm sevdamızın o masum çekirdeğini tarifsiz bir hasretle özler gibi... Seni öylece, seni çırılçıplak, seni kadere isyan eder gibi, seni Tanrı''ya eş koşar gibi... Sevdim seni sevgili, sevdim... 

Beni bir kez öldürüp sensizliğe gömdüğün o yıllarda, o yabancısı olduğum hayatın ıssızlığında soluk almadan ömrümü yalnızca Tanrı''dan gözyaşlarıyla dilediğim o mucize için bekletirken... Sonra Tanrı sesimi duyup o mucizeyi, yani seni, yani o hayatın içine birtürlü sığamayan ve telaşından durmadan sigaraya sarılan yorgun ellerini, nereye baksan hep karşında duran o kırgın çocukluğunu, uzak denizlerin sisli buğusuyla her daim ıslak dudaklarını ve ruhumun tek sığınağı o tarifsiz kokunu yeniden bana verdiğinde... Kalbim kalbinde atarken, çocukluğum çocukluğunun ellerinden tutarken... Mutluluğa dokunarak, mutluluğumun farkında olarak, mutluluktan ağlayarak... Ama bir yanım seni her an yeniden kaybedecek gibi hep tetikte... Sensizliğin o dipsiz uçurumunun kıyılarında korkusuzca dans ederek, seni benden çalan hayatın o acımasız pençesini her an arkamda hissederek... Her gece yüzümü masumiyetinin o benzersiz yurdu olan boynuna gömüp uykuya dalmadan önce bu huzuru bana bağışlayan Tanrı''ya minnetle gülümseyerek... Ve işte tam da o anda ölmeye, sonsuzluğa karışmaya hazır olduğumu ona sessizce fısıldayarak... Sevdim seni sevgili, hep sevdim... 

Otur karşıma hadi, bir sigara yak. Konuşalım. Anlat bana sevdanı... İlk aşkının yüzünü anlat... O, hiçkimseyi bu kadar sevmedim ki, dediğin, o adını kimselere söylemeden ölmek istediğin sevdanı anlat bana. Kalbindeki o sızının dilinden en çok aşkınla kavrulmuş bu yüreğim, sevdanın uğruna solup giden şu çocuk ömrüm anlar. Anlat hadi ne olur. Ama sakın bana hayattan söz etme. Sakın bana, hayat böyle bir yer, herşey bitip tükeniyor, her aşk hayata yenik düşüyor, deme... Hayatın içinde soluk alan ve hayat kadar acımasızlaşan o karanlık yanınla değil, buralara ait olmayan, annenin kırgın ömrünün kıyılarında unutulmuş, o yaralı, o sevgiye hasret çocukluğunla, hayatla birtürlü uzlaşamayan o aşk kırgını, yitik ilkgençliğinle ve herşeyin farkında olmanın çaresizliğiyle gün geçtikçe daha da derinleşen yüzündeki çizgilerle konuş benimle. Hayat dışarda kaldı, bak. Burada yalnızca sevdan oturuyor. Sevdanın dilinden konuş benimle. Ben hayatın dilinden anlayamam. Biz bu sevdayı hayatın içinde yaşamadık. Biz bu sevdayı hayatın diliyle yaşamadık. Biliyorum bu şizofren aşkım hep korkuttu seni. Bu uyumsuz varlığım, gerçekliğin içinde yaşayan ve en az hayat kadar acımasız olan o yanını çok korkuttu. Benimle hayata yabancılaşmaktan korktun. Bu yüzden yalnızca öykülerinde ağladın o uyumsuz varlığıma. Yalnızca öykülerinde eğildin bu sevdanın önünde. Sen beni yalnızca öykülerinde sevdin... 

Şimdi ilk aşkımın yüzü diye sarıldığın ve uğruna adımı dudaklarından, kalbimi kalbinden, gölgemi evinin duvarlarından söküp attığın o sevdanın, yaralı yüreğine rağmen hayatın ortasında dimdik ayakta duruyor olması bir tesadüf mü sence? Hayatla yaralanmış iki kırgın yürekten, onun içinde varolmayı reddederek yalnızca aşkı kendine vatan bileni ve bu yüzden çırılçıplak, savunmasız ve güçsüz kalarak yıkılmış olanı değil, hayatın tam da ortasında ona meydan okuyarak yaşayanı, sevgiye duyduğu güvensizliği yaralı yüreğine kalkan yaparak ayakta kalmayı başarmış olanı seçmen bir tesadüf mü? Hayattan kopmuş bir roman kahramanından sıkılıp, hayatın içinde mücadele eden bir gerçeklik kahramanını tercih etmen bir tesadüf mü? 

Anlat bana ne olur... Kaybedecek birşeyimiz yok artık. Birazdan şu kapıdan çıkıp gideceksin. Aramıza hayat girecek... Aramıza başka bir sevdayla anlamlanan sayısız anlar, sayısız mekanlar, geri dönüşü olmayan anılar, sözler ve koca bir yaşam girecek. Gittiğin o sonsuzluk yolculuğundan seni bir daha geri çağırmayacağım. Duvarları gözyaşlarımla rutubetlenen bu dört duvar yüreğimde geçireceğim karanlık gecelerde bana o mucizeyi yeniden göndermesi için Tanrı''ya yeniden yalvarmayacağım. O hayatın içine birtürlü sığamayan ve telaşından durmadan sigaraya sarılan yorgun ellerinin, nereye baksan hep karşında duran o kırgın çocukluğunun, uzak denizlerin sisli buğusuyla her daim ıslak dudaklarının ve ruhumun tek sığınağı o tarifsiz kokunun özlemiyle çıldırsam bile, merhametin için yalvarıp sana bir kez daha aynı acımasızlığı yapmayacağım. Kimi geceler başka bir sevdaya sarılıp uyuduğun yatağından ansızın uyanıp doğrulduğunda, o koyu sevdasıyla boşlukta kanayan gözlerimin hayali ''nereye gidiyorsun sevgilim'' demeyecek sana... Korkma benden artık. Aşkına rakip değilim. Ömrüne rakip değilim. Seni kadere emanet ettim. Seni ilk aşkının yüzüne emanet ettim. Kırgın değilim ne sana, ne de seni elimden alan bu acımasız hayata... Beni onca kaybedişten ve gözyaşından sonra bu dünyadaki cennetine çağıran, sonra annemin rahmi gibi huzur kokan uykularımızı sonsuza kadar yeniden elimden alan Tanrı''ya bile kırgın değilim ben... 

Şimdi git artık sevgilim. Sana sevgilim diyorum hala, bağışla beni. Sen artık bir başkasının sevgilisisin. Yalnızca bu cümleyi kurmamak için bile ölmek isterdim. Seni sonsuza dek kaybettiğim bu günleri hiç yaşamadan ölmek isterdim. Adım dudaklarında yok olmadan, tenim teninde henüz solmadan, daha böylesi yabancın olmadan... Gözlerindeki o çocuksu suçluluğu giderken denize at. Ona ihtiyacın yok artık. Affet kendini... Beni affet... Affet bu yaralı sevdamı... O hayatın içine birtürlü sığamayan ve telaşından durmadan sigaraya sarılan yorgun ellerini, nereye baksan hep karşında duran o kırgın çocukluğunu, uzak denizlerin sisli buğusuyla her daim ıslak dudaklarını, ruhumun tek sığınağı o tarifsiz kokunu yanına al giderken... Tutkunu olduğum neyin varsa hepsini alıp git... Şizofren aşkının son mektubu bu sana... Şimdi söz bitti artık. 

Konuşamam artık seninle... Konuşamam, yalnızca ağlarım...

Uçurumun dibinde nasıl göründüğümü

Merak ederdim hep.

Yüzümün aynadaki boşluğuna hep bakmak isterdim.

İnançlarımın kırılıp döküldüğü yeri anlamak için

kalabalıklar içindeki yalnızlığıma dokunmak isterdim...

Aşktı adın uçurumda, yanı başımda

aynadaki suretimdi yüzüm, 

aykırı kanardı bana.

İnançlarımın çoğu yalanmış

alay ederdi benimle.

Çok geç anladım, kalabalıklar arasındaki

senmişsin dokunamadığım...

Yalnızlığım diye küçümsediğim senin sevginmiş, 

Geceleri ansızın uyanıp

İncitip durduğum senin yokluğunmuş...

Onca sevişmeden sonra değişmemişsem, 

sihirli bir aydınlıkta, 

içimde bir yer sana sonsuz hasret kaldığı içinmiş...

İşte onca yalan geçen hayatımda

buymuş tek gerçekliğim...', 'Hadi gir içeri. Ama gözlerindeki o kanayan suçluluk bırak kapıda kalsın. Ona ihtiyacımız yok artık. O hayatın içine birtürlü sığamayan ve te...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/golgem-dusmuyor-artik-evinin-duvarlarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-tolga-acar-wqimj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara gözlüm, gül dudaklım, 

Her an sendedir aklım, 

O ne güzel bakış öyle, 

Bende kalmaz, gider aklım.

Saçlarını tutabilsem, 

Okşayıp da sarabilsem, 

Nasip eylese Allah’ım, 

Hep seninle kalabilsem.

Kaşlarını çatma bana, 

Al benden bir şiir sana, 

Sakın atma bunu canım, 

Hayatın boyunca sakla.', 'Kara gözlüm, gül dudaklım,  Her an sendedir aklım,  O ne güzel bakış öyle,  Bende kalmaz, gider aklım. Saçlarını tutabilsem,  Okşayıp da sar...', ARRAY['Türk Edebiyatı','Şiir','Tolga Acar']::text[], 8.5, '{"poet":"Tolga Acar","poet_slug":"tolga-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-tolga-acar-s73rb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bunalıyorum, yine tıkanıyorum, 

Başımı dertten alamıyorum, 

Ah bir affetsen beni sevgilim, 

İnan ki seni çok seviyorum...

Ben bir çıkış yolu bulamıyorum, 

Sanki sensiz nefes alamıyorum, 

Artık üzme beni birtanem, 

İnan ki seni çok seviyorum...

Bilmesen de budur durumum, 

Birgün bana varmandır tek arzum, 

Kır artık inadını kara gözlüm, 

İnan ki seni çok seviyorum...', 'Bunalıyorum, yine tıkanıyorum,  Başımı dertten alamıyorum,  Ah bir affetsen beni sevgilim,  İnan ki seni çok seviyorum... Ben bir çıkış yolu...', ARRAY['Türk Edebiyatı','Şiir','Tolga Acar']::text[], 8.5, '{"poet":"Tolga Acar","poet_slug":"tolga-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-seviyorum-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-tolga-acar-wpnc5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şart mıydı sanki benden ayrılman, 

En güzel günlerde bırakıp gitmen, 

Faydasız biliyorsun ne kadar yazsan, 

İçim parçalanıyor, dön gel hemen! 

Karşıma çıkmadı senin gibisi, 

Anlatamıyorum sana halimi, 

Ölürüm eğer birgün unutursan, 

Rüya gibi geçen şu günlerimizi.

Mutlu ol başka birşey istemem senden, 

Üzme kendini başkasına gönül vermem, 

Şifa veriyorsun sen bana birtanem!', 'Şart mıydı sanki benden ayrılman,  En güzel günlerde bırakıp gitmen,  Faydasız biliyorsun ne kadar yazsan,  İçim parçalanıyor, dön gel hemen...', ARRAY['Türk Edebiyatı','Şiir','Tolga Acar']::text[], 8.5, '{"poet":"Tolga Acar","poet_slug":"tolga-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayrilik-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimdeki sevgilim', 'resimdeki-sevgilim-gunes-kara-3khfw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine bekledim cafe''mizde onu bu gece

Her geceki gibi saatlerce

Açtım resmini, bakıp durdum orda

Sevgilim duruyor karşımda

Bana sadece bakan sevgilim

Ne elini uzatıyor, ellerimi tutmaya

Ne de dudaklarını değdiriyor, dudaklarıma

Ne hissedebiliyorum sıcaklığını

Ne de duyabiliyorum sesini

Tabiiki karşımdaki, sevgilimin resmiydi

Biliyormu acaba resimdeki sevgilim

Sevgimin büyüklüğünü duygularımın sıcaklığını

Gecenin karanlıklarında uyanıp birden

Aklımdaki resmine özlemle baktığımı

Yağmurun bitmeyen şırıltısının

Kulaklarımda adını sayıkladığını

Ellerimin boşlukta geceboyu onu aradığını

Gözlerim yavaşça alıştıkça karanlığa

Onsuzluğun tüm bedenimi sardığını

Heyhat yine onu göremediğimi

Saatlerce dönüp durdukça yatağımda

Gözlerimden akan selleri

Bilir mi acaba onsuz geçmeyen geceleri

Günboyu aklımdan çıkmayan ismini sayıkladığımı

Günler ve gecelerce

Özlem ve hasretiyle yandığımı

Gelmesini sabırla beklediğimi

Bilir mi acaba? Onu böylesine sevdiğimi......', 'Yine bekledim cafe''mizde onu bu gece Her geceki gibi saatlerce Açtım resmini, bakıp durdum orda Sevgilim duruyor karşımda Bana sadece bakan ...', ARRAY['Türk Edebiyatı','Şiir','Güneş Kara']::text[], 8.5, '{"poet":"Güneş Kara","poet_slug":"gunes-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/resimdeki-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle', 'bekle-tolga-acar-q78f0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekle beni geleceğim, 

Birgün geri döneceğim, 

Kim ne derse desin, 

Yine seni seveceğim! 

Korkma seni terketmedim, 

Olmasan da seninle kalbim, 

Biraz daha sabret gülüm, 

Yalnız seni sevdi gönlüm!', 'Bekle beni geleceğim,  Birgün geri döneceğim,  Kim ne derse desin,  Yine seni seveceğim!  Korkma seni terketmedim,  Olmasan da seninle kalbi...', ARRAY['Türk Edebiyatı','Şiir','Tolga Acar']::text[], 8.5, '{"poet":"Tolga Acar","poet_slug":"tolga-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bekle-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-tolga-acar-ll9ie', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoksun artık, gittin, 

Hiç olmadın ya zaten! 

Yine kaçıyor son tren, 

Sen gittin, bense bittim...

Hani saçların, gül kokun, 

Bir kez koklasaydım ya! 

Kalbimde derin yara, 

Bağrımda ayrılık okun...', 'Yoksun artık, gittin,  Hiç olmadın ya zaten!  Yine kaçıyor son tren,  Sen gittin, bense bittim... Hani saçların, gül kokun,  Bir kez koklasa...', ARRAY['Türk Edebiyatı','Şiir','Tolga Acar']::text[], 8.5, '{"poet":"Tolga Acar","poet_slug":"tolga-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoksun-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-sinan-gungor-2qwhe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açım diye bağırıyor biri.Neden diye sorulmaz. Nedenini kendiside bilmez.Bağırıyor insalar televizyondan nedenini bilmeden vatan haini ilan ediyoruz onu.Oysa yaşamaya çalısıyor zalimler arasında. vatan haini diyoruz ona oysa o insanların parasına göre itibar gördüğü bir yerden geliyor.Salakmıdır bilinmez bu insanlar.Nedenini sormayın bana ve düşünün ben hizmet etmek içinmi yaratıldım yada bir düşüncenin peşinden körü körüne gitmek içinmi hayır ben bu dünyaya yaşamak için ama yalnızca yaşamak için geldim ey insanlar.', 'Açım diye bağırıyor biri.Neden diye sorulmaz. Nedenini kendiside bilmez.Bağırıyor insalar televizyondan nedenini bilmeden vatan haini ilan e...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güngör']::text[], 8.5, '{"poet":"Sinan Güngör","poet_slug":"sinan-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/insanlar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-tolga-acar-s1872', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara gözler yakar geçer, 

Kalbim durur aklım gider, 

Bu ruhum hep seni özler, 

Nerde kaldın ey sevgili! 

Gözlerim yollara daldı, 

Bir tek resmin bende kaldı, 

Sen de sevsen ne yazardı, 

Yeter artık gel sevgili! 

Telefonum çalmaz oldu, 

Güllerin elimde soldu, 

Sanki hafızam kayboldu, 

Bana elini ver sevgili!', 'Kara gözler yakar geçer,  Kalbim durur aklım gider,  Bu ruhum hep seni özler,  Nerde kaldın ey sevgili!  Gözlerim yollara daldı,  Bir tek re...', ARRAY['Türk Edebiyatı','Şiir','Tolga Acar']::text[], 8.5, '{"poet":"Tolga Acar","poet_slug":"tolga-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgili-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '+Karınca Ve Yılan', 'karinca-ve-yilan-zeki-ergin-t79rh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'paldırlar arasından

bir yılan uzatmış kafasını

ihtiraskar

gözleri feldir feldir

biz de varız  diyor karıncalar

ve tüm bir yaz uğraştalar

toprak testisini dikmiş kafasına

nazilli dokuması gömleği ıpıslak

ömerin yanmışlığı 

bir başka bu yaz

bir yılan uzatmış kafasını

başaklar arasından

görmüyorsa da ömer

sezinliyor

yakında

ırakta

bu sıra bir türkü tutturuyor

deme gitsin

''gökte güneş

yerde ateş yanıyor

yüreklerimiz yalım yalım

toprak altında

solucanlar uyanmaklı

ilk yaza karşı

dereler çağlar

çiçerler açarmış

neme gerek''

_mustafakemalpaşa şubat1969

_köz yt:1973', 'paldırlar arasından bir yılan uzatmış kafasını ihtiraskar gözleri feldir feldir biz de varız  diyor karıncalar ve tüm bir yaz uğraştalar top...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/karinca-ve-yilan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlüyorum', 'seni-ozluyorum-yildiz-bilgin-dycad', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hatırlarım o yemyeşil orman evindeki dünyamızı

Sen odunları  dizerdin  şöminenin yanına

Çam kokan havanın   içeriye dolduğunu hissederdim 

Şömineyi yakışını izlerdim  her  akşam  bıkmadan

Elele yan yana koyun  koyuna beraber  olurduk

Ben  o bal rengi gözlerinde  arardım   mutluluğu

Ellerinden  yayılan  sıcaklığı hissetmek isterdim

Sokulurdum sana beni  hiç bırakma  diye

Bir düş  aleminde yaşar gibi geçiyordu günler

Her  gecenin sabahında yeşeren bir ağaç gibi

Yeni güne taze  şen ve mutlu başlardık ta ki! 

Sonsuzluğa  giden yolda  beni yalnız  bırakana kadar.', 'Hatırlarım o yemyeşil orman evindeki dünyamızı Sen odunları  dizerdin  şöminenin yanına Çam kokan havanın   içeriye dolduğunu hissederdim  Ş...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Bilgin']::text[], 8.5, '{"poet":"Yıldız Bilgin","poet_slug":"yildiz-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-ozluyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlıyorum', 'hatirliyorum-yildiz-bilgin-7unko', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hatırlarım el ele dolaştığımız deniz kıyısını

Başımı omuzuna yasladığımı

Kız kulesinin o  muhteşem   güzelliğini

Geceleri ışık saçan huzur dağıtışını

Yeditepe  ormanındaki  bana  ilk, 

''Seni seviyorum'' deyişini

Hatırlıyorum  martıların sesleri  arasında

Bana evlenme  teklif edişini

O harikulade ki  düğünümüzü

Gözlerini gözlerimden ayırmayışını

Mutlulukların en  güzelini, en inanılmazını, 

Yaşadığımız günleri hatırlıyorum.

Sonra  bir gün içimde  bir çıban

Büyüdükçe büyüyen ve beni  saran

Mutluluğumuzu söndüren o sonsuz, 

Ayrılığımızı  da hatırlıyorum  birtanem.', 'Hatırlarım el ele dolaştığımız deniz kıyısını Başımı omuzuna yasladığımı Kız kulesinin o  muhteşem   güzelliğini Geceleri ışık saçan huzur d...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Bilgin']::text[], 8.5, '{"poet":"Yıldız Bilgin","poet_slug":"yildiz-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatirliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığamıyorum', 'sigamiyorum-tarkan-kalkan-4guad', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sığamıyorum

Dokunamadığım rüzgara

O koskoca okyanusa

Yalnızlığım sandığım iç üşümelerim

Üç kuruşluk sancılarmış

İstanbul kadar ucuz

Yalnızlığım yok muy muş ki

Sığamadığım odalar yağmuru gark

derdi anneannem

Kukumav kuşu uçururken

Şimdi ölüm kafdağında 

Yaşam İstanbul çöplüğünde

Kötünün kötüsüne takkın

Oysa iyini iyisiydi yalnızlığım

Ah 

bir sığabilsaydim

sığınabilseydim İstanbul a

Dokunabilseydim kurşuni gecelere

Of deseydim

karakuru rüyalara 

su gibi akıp giderdim 

yağmura gark odalara

Ver elini çekeleş derken marmara

neden 

Ben sana küseleş demiş ki

Elbet bende sana küseleş

küseleş be canım

saçım sakalım terli yüzüm

Gözyaşlarım

uç kukumav kuşu 

kon kafdağına 

Bul beni yalnızlığım

Üç beş kurşuna 

ıslat yağmur 

dokun gözlerime kapat

sıyrıl gece sabaha

Sığamıyorum 

ne kendime nede ölüme', 'Sığamıyorum Dokunamadığım rüzgara O koskoca okyanusa Yalnızlığım sandığım iç üşümelerim Üç kuruşluk sancılarmış İstanbul kadar ucuz Yalnızlı...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Kalkan']::text[], 8.5, '{"poet":"Tarkan Kalkan","poet_slug":"tarkan-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sigamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil yarası', 'dil-yarasi-gokhan-oktem-u3856', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklenmedik anlarda bir vurur geçmez dil yarası 

Kim söylerse yalan söyler, içerde kalır karası 

İp kopar da düğümlersin, döner ele gelir düğüm 

Boğaz dokuz boğum derler, sekizinde dil yarası 

Yıllar yılı emek versen sarsan sarmalasan kanmaz 

Gönül umduğuna küser, akan göz yaşı kurumaz 

Ne çare, söz ağızdan çıkar...heyhat, çıktığıyla kalmaz 

Yüz yüze baka kalır kapanmaz dil yarası 

Özür kafi gelmez elbet dil yaraladıyasa eğer 

Pişmanlık, pişmiş aşa su katmaya eş değer 

Gün o gündür ki dostlar zorluk bizi kenetler 

Affetmek büyüklüktür olsa da dil yarası.... 

İstanbul,03,04,2002', 'Beklenmedik anlarda bir vurur geçmez dil yarası  Kim söylerse yalan söyler, içerde kalır karası  İp kopar da düğümlersin, döner ele gelir dü...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dil-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercinlerde Bulurum', 'guvercinlerde-bulurum-yildirim-yildirim-2kfa2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güvercinler hatırlatır seni bana 

kanat çırpışlarındaki hürriyete duyduğum özlem kadar, 

hasretim sana

bir ışık demetinde görürüm güvercinleri

ışığa doğru duydukları özlem kadar 

bende! bende! hasretim sana.', 'Güvercinler hatırlatır seni bana  kanat çırpışlarındaki hürriyete duyduğum özlem kadar,  hasretim sana bir ışık demetinde görürüm güvercinle...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Yıldırım']::text[], 8.5, '{"poet":"Yıldırım Yıldırım","poet_slug":"yildirim-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guvercinlerde-bulurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ararsın', 'ararsin-yildirim-yildirim-wwikh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'senide bir gün unuturlar yaban gülü gibi

sende başı boş kalırsın çöldeki mecnun gibi

ararsın aslının keremini aradığı gibi

ve sende benim gibi romanlar yazarsın fuzuli gibi.', 'senide bir gün unuturlar yaban gülü gibi sende başı boş kalırsın çöldeki mecnun gibi ararsın aslının keremini aradığı gibi ve sende benim gi...', ARRAY['Türk Edebiyatı','Şiir','Yıldırım Yıldırım']::text[], 8.5, '{"poet":"Yıldırım Yıldırım","poet_slug":"yildirim-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ararsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Gel', 'artik-gel-caner-avci-8frtz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakışları kara üzüm gibi

Kapkara saçları da uzunca

Kavaklıdan bir rüzgar estimi 

Olurum başka, başka yerlerde

Denizin dalgaları rıhtımı dövüyor

Ruhlar geceye çengel atmış

Karaya vurmuş balık gibi çırpınıp

Seni her yerden bekliyorum

Gel...! 

Artık gel...

Alaca itler boğuşuyor beynimde

Gelmezliğin ah gelmezliğin

İçimde boylu boyunca yaşanıyor

Bir bilsen kara üzüm gözlüm

Ne haldeyim

Artık gel...!', 'Bakışları kara üzüm gibi Kapkara saçları da uzunca Kavaklıdan bir rüzgar estimi  Olurum başka, başka yerlerde Denizin dalgaları rıhtımı dövü...', ARRAY['Türk Edebiyatı','Şiir','Caner Avcı']::text[], 8.5, '{"poet":"Caner Avcı","poet_slug":"caner-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/artik-gel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Men Yansamam', 'men-yansamam-rustem-behrudi-yl32l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Azerbaycan, ruhum canım.

Varlığımsan, nece danım, 

Kür-Araz’ı ahan ganım, -

Men sanmasam öleceyem.

Nisgilimdi gelib dile, 

İstemirem yadlar bile.

Azadlığı ganım  ile, 

Gazanmasam, öleceyem.

Veten, dilin şirin, ince, 

Sevincini isteyince, 

Gemlerini bes  deyince

Yazammasam, öleceyem.

Yuhuda bir körpe bala, 

İsteyirdi körpü sala, 

O yuhumu men vüsala

Yazammasam, öleceyem.

Öz –özümü tapmag üçün, 

İçim yandı için için, 

Doğulmuşam  yanmag üçün, 

Men yanmasam, öleceyem.

                                      1970', 'Azerbaycan, ruhum canım. Varlığımsan, nece danım,  Kür-Araz’ı ahan ganım, - Men sanmasam öleceyem. Nisgilimdi gelib dile,  İstemirem yadlar ...', ARRAY['Türk Edebiyatı','Şiir','Rüstem Behrudi']::text[], 8.5, '{"poet":"Rüstem Behrudi","poet_slug":"rustem-behrudi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/men-yansamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Umut*', 'umut-caner-avci-uicfh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiirleri kucakladım

Sarmaladım.

Ömrümü ömrüne merdiven yaptım, 

Şiirlerin gökleri sardığında

Gümüş rengi kuşlar 

Uçun semada en özgür.

Salına, salına kanat çırpın gözlerime  gözlerime

Arada bir 

Beni de yanınıza alın 

Hep burada kalırsam

İnce narin  atan kalbime dayanamam', 'Şiirleri kucakladım Sarmaladım. Ömrümü ömrüne merdiven yaptım,  Şiirlerin gökleri sardığında Gümüş rengi kuşlar  Uçun semada en özgür. Salın...', ARRAY['Türk Edebiyatı','Şiir','Caner Avcı']::text[], 8.5, '{"poet":"Caner Avcı","poet_slug":"caner-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umut-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışlar', 'karislar-caner-avci-vk5q4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dede tornuna, 

Aklı bir karış havada derdi

Derdi, derdi kim dinlerdi

Dede öldü

Torun büyüdü

Oğlu kızı derken

Sonunda o da dede oldu

Başladı torununa söylenmeye

Aklı üç karış havada

Dinleyen olmadı

Değişen sadece karışlardı.', 'Dede tornuna,  Aklı bir karış havada derdi Derdi, derdi kim dinlerdi Dede öldü Torun büyüdü Oğlu kızı derken Sonunda o da dede oldu Başladı ...', ARRAY['Türk Edebiyatı','Şiir','Caner Avcı']::text[], 8.5, '{"poet":"Caner Avcı","poet_slug":"caner-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/karislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-burakcan-avci-ohaii', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öğretmeni çok seviyrum.

Doğruyu o öyretiyor

Büyük adam olmayı

Vatana hizmet etmeyi

Yılmada usanmadan

O öğretiyor.

Onun  için onu 

Çok çok seviyorum', 'Öğretmeni çok seviyrum. Doğruyu o öyretiyor Büyük adam olmayı Vatana hizmet etmeyi Yılmada usanmadan O öğretiyor. Onun  için onu  Çok çok se...', ARRAY['Türk Edebiyatı','Şiir','Burakcan Avcı']::text[], 8.5, '{"poet":"Burakcan Avcı","poet_slug":"burakcan-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ogretmenim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-hamdullah-arvas-7312h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerin ne güzel

ne derin güzel gözlerin 

göğe açılan bir çift pencere 

güzel gözlerin ne derin

gözlerin 

bir yaz ikindisi gibi

kumla deniz arasında 

küçük bir çakıl taşı

gözlerin ne ıslak

gözlerin 

bakınca gülce incinirim

bakınca uyanır düşlerim

kalbim buz gibi erir içime 

gözlerin ne sıcak

gözlerin

bir umuda açılır her bakışı

her bakışında şarkılar şiirler

notaları düşer akşamlardan 

gözlerin ne berrak

gözlerin

sarsın istiyorum, sarsın işte

tutsun ve bırakmasın işte

sonsuza dek esir alsın işte

gözlerin ne güçlü

gözlerin

öylece beklerim her gece

her gece gözlerine bir şiir 

düşerim sırılsıklam yüreğine

gözlerin ne engin

gözlerin

gözlerin ne özgür 

gözlerin çarpan yürek kadar

gözlerin durmadan atar 

gözlerin ne özgür

gözlerin

gözlerin kelimesiz bırakır

gözlerin toprak şefkatiyle dolu

gözlerin nefessiz bırakır

gözlerin ne ağır

gözlerin

gözlerin sabaha gülen düş

bir çift güvercin gibi hayalden

yağmur yağmur gözlerin

gözlerin ne rüya

gözlerin 

gözlerin gözlerin gözlerin

gözlerin gözlerin gözlerin

gözlerin gözlerin gözlerin

gözlerin ne sonsuz 

gözlerin ne bitmez 

gözlerin', 'gözlerin ne güzel ne derin güzel gözlerin  göğe açılan bir çift pencere  güzel gözlerin ne derin gözlerin  bir yaz ikindisi gibi kumla deniz...', ARRAY['Türk Edebiyatı','Şiir','Hamdullah Arvas']::text[], 8.5, '{"poet":"Hamdullah Arvas","poet_slug":"hamdullah-arvas","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/gozlerin-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Yaşatıyorum', 'kendimi-yasatiyorum-mehmet-caner-sumengen-ufr7r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzümden atamadığım bu hüzün...

Yoldan geçen eskiciye veremediğim; 

Kırık dökük aşk anılarım kadar, 

Küflenmeye yüz tutmuş sevda artığı acılarım kadar, 

Yaşantımda fazlasıyla yer kaplıyor.

Ben mi sahip olduğum gülücükleri fazlasıyla dağıttım, 

Hırsızlar mı çaldılar ben de ki umut dolu benliği? ...

Boşa harcanmış yılların ağırlığı çöktükçe içime; 

Geceleri uykumu böler, 

Oyuncağı elinden alınmış çocuk yanımın çığlıkları...

Bilirim...Hiçbir anı geri gelmez zamanın.

Bilirim...Fotoğrafı çekilse de gençlik çağımın, 

Yaşlandığımda hep yaşlı gözlerle bakarım...

Kalbimin derinliklerinde bir pişmanlıklar müzesi var...

Ve serin havalarda biriktirilmiş bir terkedenler kolleksiyonu...

Oysa ne çok isterdim tüm paylaşımlarımdan geriye, 

Payıma düşenin sadece mutluluk olmasını...

Şimdi...Şiirler yazıyorum eksikliğini hissettiklerime, 

Resimler çiziyorum göremediğim o güzel günlere, 

Kaybettiğim herşey için türküler söylüyorum, 

Yüzümden atamadığım bu hüzün ile ise; 

Kendi kendime kendimi yaşatıyorum...

Dedim ya işte; 

Kendi kendime kendimi yaşatıyorum...', 'Yüzümden atamadığım bu hüzün... Yoldan geçen eskiciye veremediğim;  Kırık dökük aşk anılarım kadar,  Küflenmeye yüz tutmuş sevda artığı acıl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kendimi-yasatiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Zamanlar', 'o-zamanlar-yavuz-nufel-zfmv1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O ZAMANLAR 1 

 o zamanlar; 

sevda şiirleri yazmazdık. 

slogan kokardı nalburda boya 

düşük voltajlı elektriğin 

nokta nöbetçisi direkler, 

fakülte kapısında kurşunlanmışların 

resimleriyle doluydu 

boydan boya... 

briket duvarları bahçelerin 

politika sayfalarıydı sanki, 

günlük gazetelerin... 

bıyıklara yansıyan fikirlerin 

bize ters düşen bildirilerini 

almak zorunda kalmadan almazdık 

ve ilk fırsatta 

öznesi yüklü yüreğimizin 

duvarların tanıklığında 

buruşturup atardık... 

kimin öldürülüp 

''ÖLÜMSÜZ'' olduğunu (?)

polisle saklambaç oynayarak 

dağıtılan gazetelerden anlardık 

moda değildi O ZAMANLAR 

ölüleri alkışlamazdık... 

 Yavuz Nufel', 'O ZAMANLAR 1   o zamanlar;  sevda şiirleri yazmazdık.  slogan kokardı nalburda boya  düşük voltajlı elektriğin  nokta nöbetçisi direkler,  f...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Nufel']::text[], 8.5, '{"poet":"Yavuz Nufel","poet_slug":"yavuz-nufel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/o-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam Bacım Avradım', 'anam-bacim-avradim-yavuz-nufel-oeehw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'toprak için 

toprağa düşen 

kara yağız 

aslanların doğuranı, 

tepeden tırnağa sevi, 

ağıtların soylu ozanı... 

ateş üstünde tandır, 

altta yanan odun, 

üstte pişen ekmek; 

benim ülkemde 

kadın demek... 

kanlı olursa

gerdek, 

mutlanır; 

doğurursa erkek 

kutlanır. 

bir tatlı söz, 

bir güler yüz''e 

ömür boyu

umutlanır...', 'toprak için  toprağa düşen  kara yağız  aslanların doğuranı,  tepeden tırnağa sevi,  ağıtların soylu ozanı...  ateş üstünde tandır,  altta y...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Nufel']::text[], 8.5, '{"poet":"Yavuz Nufel","poet_slug":"yavuz-nufel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anam-bacim-avradim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek -İntizar-', 'beklemek-i-ntizar-hamdullah-arvas-h3jwt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gece erir 

gözlerin doğar

gözlerin kadar hür 

gözlerin kadar 

bir gül açar içimde

kırmızı bir gül

gözlerin kadar hür

beklemek seni

seni

seni

seni

seni beklemek

üşüyen şarkıda

yanan şiirde

dilde 

gönülde

umudun ta kalbinde

kan gibi

beklemek seni

seni

seni 

seni

seni beklemek

güvercin beyazında her sabah

kanat tozlarında ısırgan kelebeğinin    

kır yılanının pullarında

toprağın kış sıcağıyla

beklemek

tohum gibi

gökte yıldız 

kalpte ateş gibi

acı gibi

ıstırap gibi

seni beklemek

seni

seni

seni

seni beklemek

her akşam

al güllerle

lal şiirlerle

beklemek seni 

melek düşünde

bebek gülüşünde 

seni beklemek

bir ömür

seni beklemek

seni her akşam

seni 

seni

seni

seni beklemek

güneşle sımsıcak

yağmurla ıpıslak 

kurşunla delik deşik

seni beklemek

ilk seni

düşen yaprakta

kayan yıldızda

parlayan kıvılcımda

seni beklemek 

seni 

seni

seni

seni beklemek

beklemek seni

mavi türküde

mor uçurtmada

varmışçasına sen

yaşamışçasına seni

seni beklemek

tutkusuyla aşkın

nefretiyle ayrılığın

hiç gelmesen de 

inadına senin

seni beklemek

seni

seni

seni

s

e

n

i

.

.

.', 'gece erir  gözlerin doğar gözlerin kadar hür  gözlerin kadar  bir gül açar içimde kırmızı bir gül gözlerin kadar hür beklemek seni seni seni...', ARRAY['Türk Edebiyatı','Şiir','Hamdullah Arvas']::text[], 8.5, '{"poet":"Hamdullah Arvas","poet_slug":"hamdullah-arvas","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/beklemek-intizar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçak', 'kacak-zeki-ergin-5ms6l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bulutların yüksekliğindeyse

bir merdiven gerek

sicim sicim yağan yağmur 

engellemede olsun varsın

varsın bir bora kessin yolumuzu isterse

bir bağ evinde içilen rakıda değil

uçarı bir genç kızın 

kor gözlerinde hiç değil

o dağ başında eşkiyanın düşlerinde

katıksız sofralarda

tütün dumanlarınca

yükselmiş

gizlenmiş

bir sır olmuş

eller ermez ona 

ses ses büyümek

bitmeyen türkünün savrukluğunda

bir keçi inatlığı içinde

yüreklere yazılmaklı o

nerededir 

nasıl buluruz

hakkımız mı

değil mi

o dağbaşında

bir sabah yıldızı

o karanlıklara

köprü kuracak ışık yolu

yutturamazlar

çocukça

masallarca erişilmezlik içinde

kafdağında yitik değil

o gönlümüzde yatan aslan

o gözlerimizde bir parıltı

_mustafakemalpaşa eyl67

_köz yt:73

_dağlara ver sırtını yt:haz09', 'bulutların yüksekliğindeyse bir merdiven gerek sicim sicim yağan yağmur  engellemede olsun varsın varsın bir bora kessin yolumuzu isterse bi...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kacak-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-murat-gunes-h5ykb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen bir çift elin birleşmesidir umut

Bazen bir gelinlik 

Bazen mutlu bir yuva 

bazen bir çocuğun gözyaşlarıdır umut

Bazende umut gönlümüze yağan her yağmurun 

Ardından iki damla nedadır geriye kalan sadece....... 

bazende sessiz sessiz giderken ölüme seni sevenlerdir umut', 'Bazen bir çift elin birleşmesidir umut Bazen bir gelinlik  Bazen mutlu bir yuva  bazen bir çocuğun gözyaşlarıdır umut Bazende umut gönlümüze...', ARRAY['Türk Edebiyatı','Şiir','Murat Güneş']::text[], 8.5, '{"poet":"Murat Güneş","poet_slug":"murat-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/umut-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sandalın aşkı', 'sandalin-aski-murat-gunes-856lu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sonra sen geldin kopardın halatımı sürükledin beni engin deryaya senden kurtulmalıydım 

ne kadar çırpınsamda senden kurtulabilmek için hep boşunaydı çabalarım duyulmuyorduki feryatlarım

senden kurtulmamın yalnızca iki yolu vardı

ya sen dinecektin güneşi sunacaktın gönül deryama yada ben alabora olacaktım feryad''ı  figan içinde', 'sonra sen geldin kopardın halatımı sürükledin beni engin deryaya senden kurtulmalıydım  ne kadar çırpınsamda senden kurtulabilmek için hep b...', ARRAY['Türk Edebiyatı','Şiir','Murat Güneş']::text[], 8.5, '{"poet":"Murat Güneş","poet_slug":"murat-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sandalin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuş', 'konus-cemil-bilgi-vdtsf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'konuşuyormuş gibi seninle yazsam bu şiiri

bu şekilde seninle konuşabilir miyiz ki

duyabilir misin sesimi

cevap verebilir misin sorularıma

böyle de sevebilir misin beni

bilemem ne zaman tanıştık seninle

hangi gündü o ilk gün

aklımdan çok şeyi sildim şimdi

küçük bir kızdın ilk gördüğümde seni

büyüdün değiştin zamanla herkes gibi

beni gerçekten sevdin mi

sorduğunu duyar gibi oluyorum

ben seni sevdim mi

ya da tahmin ettiğini bilir gibi oluyorum

seni deli gibi sevdiğimi

ama ben de bilmiyorum

seni sevip sevmediğimi

bir gün geçmişte bir gün

bir adım atsaydım diyorum

bir adım

belki şimdi

çok şey yaşanmış ve bitmişti

mutlu olur

bir o kadar da acı çekerdik belki

ama en azından bunların sonu bir pişmanlık değildi

konuşabilir miyiz seninle eskisi gibi

harcamamalı mıyım bir şiirde

sana söyliyeceğim kelimeleri

tekrar karşılaşmamız mümkün mü

yoksa tek şansımız bir rastlantı mı ayaküstü

ya da diyorum bir adım atabilsem şimdi bile

çok şey değişir belki

aslında her şey geçmiş şimdi

beni düşündüğün bile yalan bir teselli

yine de ben çok isterdim senin aklındayken ölmeyi...', 'konuşuyormuş gibi seninle yazsam bu şiiri bu şekilde seninle konuşabilir miyiz ki duyabilir misin sesimi cevap verebilir misin sorularıma bö...', ARRAY['Türk Edebiyatı','Şiir','Cemil Bilgi']::text[], 8.5, '{"poet":"Cemil Bilgi","poet_slug":"cemil-bilgi","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/konus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran Ortası', 'haziran-ortasi-cemil-bilgi-rsxri', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerimi kapasam hayalin karşımda, 

açsam sen yoksun ki yanımda.

ama yine de sensiz yaşamak, 

daha iyidir hayalinle olmaktan.

hayalin beş para etmez bir servet gibi; 

büyük ikramiye çıkmış bilet bende sanki, 

ama yok ikramiye alma ihtimali; 

biletin sol tarafı yırtık çünki.

niye sol tarafı dersin şimdi sen, 

kalbim solda ya, o yüzden.

verdiğin hasarın yeri belli ezelden.', 'gözlerimi kapasam hayalin karşımda,  açsam sen yoksun ki yanımda. ama yine de sensiz yaşamak,  daha iyidir hayalinle olmaktan. hayalin beş p...', ARRAY['Türk Edebiyatı','Şiir','Cemil Bilgi']::text[], 8.5, '{"poet":"Cemil Bilgi","poet_slug":"cemil-bilgi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/haziran-ortasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın', 'sakin-cemil-bilgi-ecc9u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sakın okuma bu şiiri! 

güzellerin en güzeli...

çok mu belli ediyorum seni sevdiğimi? 

sakın okuma, 

sakın okuma bu şiiri; 

anlarsın diye, korkuyorum, hislerimi.

sana yazıldığı besbelli.

biraz da çekiniyorum söylemekten, seni sevdiğimi.

yazmak daha kolay herşeyi.

ama sen sakın ola okuma bu şiiri! 

çünkü istemiyorum öğrenmeni.

ya sen sevmezsen beni? 

aman, ne olur, sakın okuma bu şiiri! 

ben seni dost bileyim, sen de beni.

sakın okuma bu şiiri! 

sana yazıldığı her hecesinden belli...', 'sakın okuma bu şiiri!  güzellerin en güzeli... çok mu belli ediyorum seni sevdiğimi?  sakın okuma,  sakın okuma bu şiiri;  anlarsın diye, ko...', ARRAY['Türk Edebiyatı','Şiir','Cemil Bilgi']::text[], 8.5, '{"poet":"Cemil Bilgi","poet_slug":"cemil-bilgi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sakin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Sevdam mı; Deli Sevdalın mı?', 'deli-sevdam-mi-deli-sevdalin-mi-cemil-bilgi-769f0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I

deli sevdam mı? 

deli sevdalın mı? 

seni hala seviyorum belki ama, 

sensiz yapamayacağımı düşünmem; 

biliyosun, yanlış aslında.

bunca zaman geçtiyse, 

ve ben, 

hala senin ayaklarına kapanmadıysam, 

hangi yerde kiminleysen, 

oraya gelip hala önünde diz çöküp sana yalvarmadıysam, 

gururumu ayaklar altına alıp da

senden başka her şeyi unutup

senin bana değer verip vermediğini boşverip

beni sevmen için senin karşına geçip ağlamıyorsam; 

hala gücüm var benim.

eğer ki seni gerçekten sandığım kadar çok seviyorsam...

yok, seni sevmiyorsam, 

o zaman deliyim ben.

her dakika aklıma gelmen, 

ağzımı açsam sen, gözümü yumsam sen, 

adım atsam bir yerlerde yine sen.

kafayı seninle  bozmuşum o zaman ben.

tabi eğer bu sevda değilse.

belki de sadece meraktan

sürekli seni düşünmem.

içtiğim suda birazcık sen olsan, 

gördüğüm rüyada senden haber alsam, 

(bak bi de bu çok önemli) 

sevdiğin kimse olmadığını bir bilsem; 

senin aklını okuyabilsem, 

yaptığın her şeyi avucumun içindeymişsin gibi takip edebilsem; 

belki de biterdi o zaman her şey, 

derdim kalmazdı.

bunlar açıklıyor işte benim deli sevdamın bitişini

ya da

senin sevdalının delirişini.

ne dersin; cevap sence bunlardan hangisi? 

II

ayrıldık; ama buluşabiliriz...

ne bilirsin? 

bir gün çıkarım belki seni bulmaya yollara.

bir gün gelirim belki ayaklarına kapanmaya.

kim bilir? 

elim, ayağım tutmayabilir; 

gözlerim görmeyebilir.

ama bir sen varsındır aklımda.

gözlerin ışık saçar, yol gösterir bana.

saçların tek tek, tel tel batar kalbime ama, 

acı vermez artık.

yaşlı bi adam olmuşumdur.

o kadar acı görmüşümdür ki, 

senin verdiğin acı ödüldür bu adama.

sonra o güzel ellerin tutar o yaşlı adamın buruşmuş ellerinden.

ve belki hayat verir yeniden

ayaklarıma bile belki; 

belki koşmaya başlarım seni ilk gördüğüm anda.

sesin açar paslanmış kulaklarımı.

gerçi bu yaşlı adam beş para etmez bir enkazdır artık ama, 

yine de küçük düşmek istemem karşında

belki ölmeden önce gösterebilirim son bir çaba.

o gün daha da çok sevebilirim seni.

işte o gün, 

son bir kez sarılır mısın o yaşlı adama? 

III

buluştuğumuz gün en önemlisi! 

o gün seni sevdiğimi söyleyemeyebilirim.

lütfen bağışla sevgilim! 

belki seni gördüğümde tutulur dilim.

ya da çok zaman geçmiştir aradan, 

derman kalmamıştır dilimde sana seni sevdiğimi söyleyecek.

affet beni sevgilim! 

o gün seni sevdiğimi söyleyemeyebilirim; 

ama seni ölene kadar seveceğim! 

.........', 'I deli sevdam mı?  deli sevdalın mı?  seni hala seviyorum belki ama,  sensiz yapamayacağımı düşünmem;  biliyosun, yanlış aslında. bunca zama...', ARRAY['Türk Edebiyatı','Şiir','Cemil Bilgi']::text[], 8.5, '{"poet":"Cemil Bilgi","poet_slug":"cemil-bilgi","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/deli-sevdam-mi-deli-sevdalin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz Daha', 'biraz-daha-cemil-bilgi-2b7uw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni göremediğim her gün

biraz daha görüyorum seni

baktığım her insanın yüzünde

biraz daha zorluyor gözlerin beni

geçirmem konusunda sensiz günleri

yolum çıkmaza dönüyor biliyorum

ne ağlamaların ıslattığı gizli bir kelime

ıslanıyor yine o gülüşümün altında

ve birden sen geliyorsun aklıma

çıkmaz yol daralmaya başlıyor yavaş yavaş

ve gizli kelime göğsümün sol yanında ortaya çıkıyor yine

ıslatmıyor kalbimi artık, acı veriyor derinden

tarif edilemeyen manası ile

ve geriye kalan kelimeler

yetmiyor bana anlatmak için sana senin zorunluluğunu.

tam adını koyamıyorum

ne sana olan sevgimin

ne de ulaşmak istediklerimin 

kafam karışıyor ve kurtulamıyorum

seni göremediğim her gün

biraz daha görüyorum seni

baktığım her insanın yüzünde

biraz daha zorluyor gözlerin beni

sonuca ulaşamıyorum

başını bulamıyorum

kendi içimde kayboluyorum

yavaş yavaş...', 'seni göremediğim her gün biraz daha görüyorum seni baktığım her insanın yüzünde biraz daha zorluyor gözlerin beni geçirmem konusunda sensiz ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Bilgi']::text[], 8.5, '{"poet":"Cemil Bilgi","poet_slug":"cemil-bilgi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/biraz-daha-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli', 'gizli-cemil-bilgi-wr7sn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bizde gizli aşklar var; 

kimsenin bilmediği, 

bizim bildiğimiz, 

ama bir köşemizde gizlediğimiz aşklar...

insan hep yalnız bu dünyada.

gizli ve yalnız...

bir yaşam, 

tek bir pencereden yaşanır; 

çift bölmeli.

gerisi hikaye; 

hem de uzun hikaye.

her şey gizli.

her pencerenin ardında herkes yalnız.

bizde gizli aşklar var, 

bir de yalnız insanlar.

pencerenin dışında ne kadar çoğul isek, 

pencerenin içinde de o kadar yalnız.

sahip olduğumuz iki öznemiz: 

biri gizli özne, 

diğeri sözde.

pencerenin dışında hepimiz sözdeyiz.

pencerenin içinde herşey gizli...', 'bizde gizli aşklar var;  kimsenin bilmediği,  bizim bildiğimiz,  ama bir köşemizde gizlediğimiz aşklar... insan hep yalnız bu dünyada. gizli...', ARRAY['Türk Edebiyatı','Şiir','Cemil Bilgi']::text[], 8.5, '{"poet":"Cemil Bilgi","poet_slug":"cemil-bilgi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gizli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gelir', 'gun-gelir-cemil-bilgi-f1wif', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gün gelir

vazgeçerim her şeyden

bir senden vazgeçemem; bir senden

gün gelir

unuturum her şeyi

gençlik günlerimi

iyi kötü güzel çirkin

doğru yanlış her şeyi

bir seni

bir seni unutamam; bir seni

gün gelir

sevmem, sevemem hiç bir şeyi

kim bilir belki de sevmedim hiç kimseyi

ama bir seni sevdim; bir seni

bir gün herkes gider

bir ben kalırım buralarda

yalnız ve uzakta

kimseyi özlemem ama

bir seni özlerim oralarda bilemem kaç başına

gün geldi

sensiz kaldım bir başıma

hep yabancılar oldu etrafımda

çok sustum ama

sana açtım içimi, bir sana

benden o kadar uzak olsan da

tek kelimemi bile duymasan da.

biter dedim

bitmedi

her şey bitti

bir sen bitmedin

bir sensizlik bitmedi', 'gün gelir vazgeçerim her şeyden bir senden vazgeçemem; bir senden gün gelir unuturum her şeyi gençlik günlerimi iyi kötü güzel çirkin doğru ...', ARRAY['Türk Edebiyatı','Şiir','Cemil Bilgi']::text[], 8.5, '{"poet":"Cemil Bilgi","poet_slug":"cemil-bilgi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gun-gelir-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün', 'gulusun-pablo-neruda-mn312', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Al ekmeği benden

istersen havayı da; 

ama gülüşünden mahrum etme beni.

Koyma gülsüz

ve çiçeksiz beni,

sevinciyle coşarak

parıldayan sudan

ve senden yayılan

gümüşün kıvılcımlarından.

Bu çetin ve uzun kavgamdan

yorgun gözlerle dönerim

ve görürüm ayaklar altında

bu değişmeyen toprağı; 

ama o sevecen gülüşün

yükselir gökyüzüne peşimden

ve ardına dek açar

yaşamın tüm kapılarını benim için.

Sevdalım, zifiri karanlıkta bile

gülümse bana

ve ansızın saçılıyorsa

kanım sokak taşlarına,

gülüver

çünkü gülüşün eştir

yalın bir kılıca.

Sonbaharda denizle birlikte

gülüşün coşturmalı

köpüren çağlayanını.

Ve sevdalım baharın

beklediğim çiçek gibi

gülüşünü ararım

mavi çiçeği, gülü

yurdumdan seslenen.

Gül gecenin şavkında

gündüzün aydınlığında

gül yamru-yumru

sokaklarında adanın,

gül sana sevdalanmış

şu ipe-sapa gelmez adamın bakışında,

ama ben gözlerimi açtığımda

ve de kapadığımda onları,

ve ayaklarım götürüp

geri getirdiğinde beni

al benden ekmeği, havayı,

ışığı, baharı,

ama mahrum etme 

gülüşünden beni

işte o zaman ölürüm gayri.

Çeviri: Fahri Özdemir', 'Al ekmeği benden istersen havayı da;  ama gülüşünden mahrum etme beni. Koyma gülsüz ve çiçeksiz beni, sevinciyle coşarak parıldayan sudan ve...', ARRAY['Türk Edebiyatı','Şiir','Pablo Neruda']::text[], 8.5, '{"poet":"Pablo Neruda","poet_slug":"pablo-neruda","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/gulusun-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-erdal-bozdogan-6k6hl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün o da ölümü bekliyor artık.

Yaşarken beklemek, beklerken yaşamak gerek.

İnsans önce doğmasını bekler, 

Sonra yavaş, yavaş emekler.

Zamanla yaşlanır bu alemde, 

Bu gün o da ölümü bekliyor artık.

Dostluklar kurulur beklerken, 

Sadece bekleke yetmez, özlemek de var.

Ömür beklekle geçsede bu dem.

Yaşarken beklemek, beklerken yaşamak gerek.

(27.02.2002)', 'Bu gün o da ölümü bekliyor artık. Yaşarken beklemek, beklerken yaşamak gerek. İnsans önce doğmasını bekler,  Sonra yavaş, yavaş emekler. Zam...', ARRAY['Türk Edebiyatı','Şiir','Erdal Bozdoğan']::text[], 8.5, '{"poet":"Erdal Bozdoğan","poet_slug":"erdal-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beklemek-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüseyin''in Ağıtı', 'huseyin-in-agiti-ozan-arif-bu9vg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Mamak Zindanlarında Sabah namazını eda ederken kafasına dipçikle vurularak şehit edilen Hüseyin Kurumahmutoğlu''nun aziz hatırasına-

İzimiz olacak hep onun izi, 

Ne desem nafile bu imiş yazı

Bu dünyada yarım kalan namazı

Cennet-i Ala ''da kıldı Hüseyin

Muradı Firdevs''te aldı Hüseyin.

Hak yolda yürüdü Hak yolda gitti

Hak yolda bir ömür böylece bitti.

Çiçeği burnunda babayiğitti

Ülkü bahçesinde güldü Hüseyin

Soldu Ülküdaşım soldu Hüseyin.

Hüseyin''de ne can ne nefes kaldı

Geriye bir ülkü bir heves kaldı.

Bir kanlı seccade bir de fes kaldı

Arif''i acıya saldı Hüseyin.

Öldü Ülküdaşım öldü Hüseyin.', '-Mamak Zindanlarında Sabah namazını eda ederken kafasına dipçikle vurularak şehit edilen Hüseyin Kurumahmutoğlu''nun aziz hatırasına- İzimiz ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huseyin-in-agiti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüseyinler Ölmez', 'huseyinler-olmez-ozan-arif-979kg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Mamak Zindanlarında namaz kılarken şehit edilen Hüseyin Kurumahmutoğlu''nun ardından-

Nasıl öldü dedim nasıl ben ona

Hüseyinler ölmez, Şehitler ölmez.

Öldü denilmezmiş şehit olana

Hüseyinler ölmez, Şehitler ölmez.

Onlar yaşar amma zordur görmesi, 

O kanlı seccade, o kanlı fesi, 

İşte işareti işte belgesi

Hüseyinler ölmez, Şehitler ölmez.

Esas ölü onun kanına giren, 

Kıldığı namazı ona çok gören, 

Esas ölü onlar onlar geberen

Hüseyinler ölmez, Şehitler ölmez.

Ve siz.Ey vicdanı katı olanalar, 

Vatanın kan emen biti olanlar

Her devrin köpeği iti olanlar

Hüseyinler ölmez, Şehitler ölmez.', '-Mamak Zindanlarında namaz kılarken şehit edilen Hüseyin Kurumahmutoğlu''nun ardından- Nasıl öldü dedim nasıl ben ona Hüseyinler ölmez, Şehit...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huseyinler-olmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanımı Özledim.', 'vatanimi-ozledim-ozan-arif-jya6u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sorma gardaş derdimi, 

Vatanımı özledim.

Adım adım yurdumu

Vatanımı özledim.

Çekmeyen bilmez hey hey, 

Yurt hasreti kötü şey, 

Şehir şehir kaza köy

Vatanımı özledim.

Muşlu hasrettir Muş''a

Maraşlılar Maraş''a

Ben ise baştan başa 

Vatanımı özledim.

Bahçesini bağını, 

Dalını yaprağını

Taşını toprağını

Vatanımı özledim.

Elvan elvan gülleri, 

Ilgıt ılgıt yelleri, 

Türkü diyen dilleri

Vatanımı özledim.

Bıırak be kader bırak, 

Biliyorum çok ırak, 

Yoları çamur çorak

Vatanımı özledim.

Sıkıntı derdi ile, 

Köpeği kurdu ile, 

Kalleş merdi ile

Vatanımı özledim.

Gelenekler töreler, 

Ezanlar minareler

Ah..Daha neler neler

Vatanımı özledim.

Şu gurbet kasa kasa, 

Al sana para dese

Dünyayı bağışlasa

Vatanımı özledim.

Her bayram acı acı, 

Sızlar burnumun ucu

Batsın gurbetin tacı

Vatanımı özledim.

Arif der: Çürür müyüm? 

Kalır mı durur muyum? 

Acaba görür müyüm? 

Vatanımı özledim.', 'Sorma gardaş derdimi,  Vatanımı özledim. Adım adım yurdumu Vatanımı özledim. Çekmeyen bilmez hey hey,  Yurt hasreti kötü şey,  Şehir şehir k...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/vatanimi-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Bahtsız', 'bahtsiz-mustafa-engin-karatay-obu0i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün yüzü görmeyişim; sayılmaz pek de tuhaf

Ebede dek tâlihim, yâver gitmekten muaf

*Zâten doğarken bahtımdan yemişim tekmeyi, 

Kahrın rütbelisini, üstlenmişim çekmeyi*

Hâkim müebbed yazmış tek celsede cezâmı; 

Temyîz, fesih imkânsız; değiştirmez kazâmı

Kazırlarken Künyem''i levhâlara, çelikten

Yolumu geçirmişler, iplik geçmez delikten

İrâdem tâ özünden yüzüztü yere mıhlı

Firâsetim zincirli, basîretim çarmıhlı

Sonuç: 

-Mahrûmluklar içinde, tek kulvarlı bir yarış

-Sonu programlanmış, başından belli varış...

06.04.2002     Münih    04: 40', 'Gün yüzü görmeyişim; sayılmaz pek de tuhaf Ebede dek tâlihim, yâver gitmekten muaf *Zâten doğarken bahtımdan yemişim tekmeyi,  Kahrın rütbel...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bahtsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azizem', 'azizem-muhammet-sunar-3snge', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bakışlarım uzanıp

suretin deldi geçti

suret değil aslında

hayaldi geldi geçti

besmeleden bir sonra 

adın evveldi geçti

aşka destur çekildi

araf şehirde geçti

şehir nedir bir sürgün

demi tehirde geçti

susuzluğun ardından

faslı zehirde geçti

yağmur sonsuz kez yağdı

tufan değil nuh geçti

usul usul bedenim

bedenimden ruh geçti

lisan olup muamma

bakışlar vuzuh geçti

lakin artık azizem

bu akşam hepsi geçti

(Erzurum        Ağustos 95)', 'bakışlarım uzanıp suretin deldi geçti suret değil aslında hayaldi geldi geçti besmeleden bir sonra  adın evveldi geçti aşka destur çekildi a...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/azizem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiy, Yağmur ve Gecenin Alacakaranlığı', 'ciy-yagmur-ve-gecenin-alacakaranligi-nevzat-gurmen-67al4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gecenin ayazında çıkacaksın yola, 

her sabah alacakaranlığa.

ön cama çiy olup düşeceğim.

temizlerken silecekler, 

gece olup saracağım seni; 

korkma sakın yalnızlıktan.

yağmur olup çiseleyeceğim gündoğumunda.

alışacak mısın gizli dostuna; ya da

yağmuru sever misin, hiç sormadım.

gecenin karanlığı hep olacak, 

yağmur da çiseleyecek arada bir.

ve ben bir gün sessizce, 

çekilmiş olacağım aradan.

artık çiy, yağmur ve gecenin alacakaranlığı

seninle yalnız.', 'gecenin ayazında çıkacaksın yola,  her sabah alacakaranlığa. ön cama çiy olup düşeceğim. temizlerken silecekler,  gece olup saracağım seni; ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ciy-yagmur-ve-gecenin-alacakaranligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşmeden Direnmek', 'dusmeden-direnmek-nevzat-gurmen-k8zii', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen bir gül goncası

bir dikenli dal

ben bir çınar yaprağı

bir koca gövde

sana da karşı zaman, bana da

düşmeden direnmek değil mi yaşam', 'sen bir gül goncası bir dikenli dal ben bir çınar yaprağı bir koca gövde sana da karşı zaman, bana da düşmeden direnmek değil mi yaşam...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dusmeden-direnmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Artık', 'yeter-artik-ozan-arif-fiov0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeter be! Üstüme çok gitmesinler, 

Ülkücülük haddi aşmak değildir.

Bana ülkücülük öğretmesinler, 

Ülkücülük yoldan şaşmak değildir.

Ülkücü kavrulur her nefesinde 

Ocak ateşinde ocak isinde

Sistemin düdüklü tenceresinde

''Kelle paça'' gibi pişmek değildir.

Merkezmiz herkesmiş bilmem ne derken

Erken unuttular Türkeş''i erken

Ülkücülük ''ülkü'' elden giderken

Hoplayıp zıplayıp çoşmak değildir.

Seneden seneye mezar ıslayıp, 

''Türkeşçilik'' yapmak ayıptır ayıp

Sırf bununla Ülkücülük taslayıp

Ülkücünün derdini deşmek değildir.

Köylü bile öküz alsa işine, 

Dişine bakıyor önce dişine

Ülkücülük her hıyarın peşine

Bir avuç tuz alıp koşmak değildir.

Düşünen ve konuşanı ezerek, 

Soru soran ülkücüyü bozarak

Cevaptan ziyade ona kızarak

Köpürmek değildir taşmak değildir.

Ülkücülük makamları koz yapıp, 

Gönülleri ufalayıp toz yapıp

Elaleme gık yok bize poz yapıp

Kabarmak değildir pişmek değildir.

Bu sevda gönlüne aldıklarına

Vefayı öğretir bulduklarına

Kötü günde muhtaç olduklarına

İyi günde mezar eşmek değildir.

Ülkücülük böyle utanmazlaşıp, 

Sevdayı unutup hatta yozlaşıp

Geçmişine sövenlerle uzlaşıp

Arif''in paşine düşmek değildir.', 'Yeter be! Üstüme çok gitmesinler,  Ülkücülük haddi aşmak değildir. Bana ülkücülük öğretmesinler,  Ülkücülük yoldan şaşmak değildir. Ülkücü k...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yeter-artik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çift Yürek', 'bir-cift-yurek-tacettin-cetin-qsh32', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazen bir dalga bile vurmuyor sahillerime 

Yıldızlar umutsuzluk işareti 

Keşmekeşler içindeki hayat 

Adı olmayan bir nüfus sureti 

Sonsuzluğun tanımını yaparken 

Sonsuzluğun içindeymişiz meğer 

Alfabetik sıraya koyarsak 

Z benim için en büyük değer

Bazen bir otobüs bile durmuyor duraklarda 

Geçenler ise kendi havasında 

Umutsuz bir bekleyiş 

Yalnızlığın tam ortasında 

İçiçe geçmiş suretlerde 

Bir yerlere sıkıştırılmış ikinci bir benlik 

Doyumsuzluklar içinde 

Bence en büyük ilkellik', 'Bazen bir dalga bile vurmuyor sahillerime  Yıldızlar umutsuzluk işareti  Keşmekeşler içindeki hayat  Adı olmayan bir nüfus sureti  Sonsuzluğ...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Çetin']::text[], 8.5, '{"poet":"Tacettin Çetin","poet_slug":"tacettin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-cift-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-erdal-bozdogan-qyie3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle doludur bu dünyam.

Kadehlerde, 

Şişelerde, 

Gözyaşlarımda, 

Hep sen varsın sarhoşluğumda.

Gecenin karanlığında ışığımdın, 

Şarkılarımda, 

Ruhumda, 

Aklımda, 

Bedenimde, 

Hep sen varsın gecelerimde.

Ayın doğuşunda, 

Yıldızlarda, 

Dağlarda, 

Yemyeşil ovalarda, 

Denizin köpüğünde, 

Kumsalın tanelerinde, 

Sen varsın gördüğüm her şeyde.

Yüreğimin sıcaklığında

Demli çayımda, 

Güneşin doğuşunda, 

Batışında, 

Sonbaharda düşen yaprakta, 

Sen varsın hep yanlızlığımda.

Aldığım her nefeste, 

Yağmur tanelerinde, 

Lapa, lapa yağan karda, 

Kalbimin ılgıt, ılgıt  ağladığında, 

Sen, sen, sen, 

Sen varsın gecelerimin yanlızlığında. 

18.02.2000', 'Seninle doludur bu dünyam. Kadehlerde,  Şişelerde,  Gözyaşlarımda,  Hep sen varsın sarhoşluğumda. Gecenin karanlığında ışığımdın,  Şarkıları...', ARRAY['Türk Edebiyatı','Şiir','Erdal Bozdoğan']::text[], 8.5, '{"poet":"Erdal Bozdoğan","poet_slug":"erdal-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sen-varsin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gİbi', 'dun-gi-bi-tacettin-cetin-9y7vh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gibi aklımda beni yüzüstü bırakıp gittiğin o gün 

Çöldeki bir bedevi gibi susadım gözlerine 

Ve içimde ellerini tutmanın arzusu 

Ardına bile bakmadan nasılda gidebildin 

Bir başkasını seviyorum masalıyla 

Arkadaşlarından haber aldım bugün pişman olduğunu 

Biliyorum korkuyorsun yüzün yok dönmeye 

Bulabilirmiyim diyorsun o eski sevgiyi 

Sakın aklından bile geçirme artık geri dönmeyi 

Geçen yıllar çok iyi öğretti bana silmeyi 

Ve içimde nefret biriktirmeyi 

Adını bile unuttum inan 

Benim için bir hiç bile değilsin 

Dönersen mi 

Dönersen şerefsizsin', 'Dün gibi aklımda beni yüzüstü bırakıp gittiğin o gün  Çöldeki bir bedevi gibi susadım gözlerine  Ve içimde ellerini tutmanın arzusu  Ardına ...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Çetin']::text[], 8.5, '{"poet":"Tacettin Çetin","poet_slug":"tacettin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dun-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar', 'duvar-onur-uysal-w5ki2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir duvar ördük aramıza

Bir duvar ki

Sevgimiz kadar sağlam

sevdamız kadar uzun

ve yüksekti beklentilerimiz kadar...

Bir duvar ördük aramıza, büyüdü usulcadan.

Her kaçan bakışımızda	

Ve can dostlara her sığınmamızda

	eklendi bir tuğla, bir tuğla daha

elbet istemeden...

Bir duvardı bu örülen yavaş yavaş

Ördük sırtımızda taşıdığımız tuğlalarla, 

	boşalttık ama hafifleyemedik.

Bir cam gibiydi başta, saydamdı ya, 

aradı gözlerimiz birbirimizi, bir şey göremedik

Ve inceydi ince olmasına dokunsak kırılacak, 

	yine de sessiz çığlıklarımızı ulaştıramadık.

Duvar böyle gün be gün büyürken

Her gelen de bir omuz verdi bu karanlık sevdamıza, 

belli ki fark etmeden.

Körleşti gözlerimiz, 

	sağır oldu kulaklarımız, 

İnkar etmek en kolayıydı

kolay oldu duvarı görmezden gelmek...

Bugün, 

Arkasında yalnız başınayken şu koca duvarın

Artık duyuluyor çığlığın, çınlıyor haykırışların

Diyorsun, ağlama artık, zamanıdır ileriye bakmanın

Bilmez miyim gülüm, biliyorum, 

Arkamı dönüp tüm geçmişe, 

	açılmayı engin sevdalara

inan ben de istiyorum.

Ama bırakmıyorlar gülüm, bırakmıyorlar

Bırakmıyor duvardaki resmin, 

Kulaklarımdan gitmiyor sesin

Silinmiyor aklımdan o sevdalı gözlerin...', 'Bir duvar ördük aramıza Bir duvar ki Sevgimiz kadar sağlam sevdamız kadar uzun ve yüksekti beklentilerimiz kadar... Bir duvar ördük aramıza,...', ARRAY['Türk Edebiyatı','Şiir','Onur Uysal']::text[], 8.5, '{"poet":"Onur Uysal","poet_slug":"onur-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/duvar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimki Aşk', 'benimki-ask-tacettin-cetin-0df35', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'önce kaçamak bir bakış 

hayaller alemine amansız bir dalış 

her şey toz pembe derken 

başlar aşk dedikleri gölgenden kaçış

uyumak ölümden daha zor gelir 

geceler içinde gündüzler erir 

gözlerinin anlattığı sevda masalı 

kutsal bir kitap gibi ezberimdedir

bir resim vermiştin bakamam ki 

yazdığın mektupları açamam şimdi 

bir yıldız kayıyor bak gök yüzünden 

geri dönmeni dileyemem ki

ellerim boş kaldı bak sensiz 

gökyüzü ağlar bana sessiz sessiz 

hala masamda durur 

birkaç gün önceki mutlu resmimiz 

masum bir kuş gibi uçtun yuvadan 

sebebini bile kimse anlamadan 

bilinmezlere olan bu yolculuğunda 

mutluluklar dilerim sana allahtan', 'önce kaçamak bir bakış  hayaller alemine amansız bir dalış  her şey toz pembe derken  başlar aşk dedikleri gölgenden kaçış uyumak ölümden da...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Çetin']::text[], 8.5, '{"poet":"Tacettin Çetin","poet_slug":"tacettin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benimki-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimin Daldığı Yerdesin', 'gozlerimin-daldigi-yerdesin-erdal-bozdogan-p2sah', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim bilirdi ki o küllerin altında, 

Hala ateş dağı yanmakta.

Yine aşk, yine yalnızlık, yine acı, 

Ve benim yüreğimde aynı sancı, 

Sen yine kabuğunun içinde, 

Ve ben dertlerimle baş başa, 

Uçurumun kenarında boşluğa bakıyorum.

Ve sen yine gözlerimin daldığı yerdesin.

12 Ocak 2002', 'Kim bilirdi ki o küllerin altında,  Hala ateş dağı yanmakta. Yine aşk, yine yalnızlık, yine acı,  Ve benim yüreğimde aynı sancı,  Sen yine k...', ARRAY['Türk Edebiyatı','Şiir','Erdal Bozdoğan']::text[], 8.5, '{"poet":"Erdal Bozdoğan","poet_slug":"erdal-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozlerimin-daldigi-yerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Şimdi Gittin', 'sen-simdi-gittin-tacettin-cetin-c4d10', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece küsmüş kendine 

güneş niye doğduğundan habersiz 

inkar ediyor deniz mavi olduğunu 

bütün gülleri sözü var açmamaya 

sen şimdi gittin 

kuşlar şaşkın bana soruyorlar seni 

havlun bile korkuyor kurumaya 

aynalar şaşırdı kendini 

ben bakıyorum seni gösteriyorlar bana 

kapı hala aralık 

sen şimdi gittin 

hiç yıldız kaymadı senden sonra 

her halde bir anlaşmanız vardı 

her gün geçen kağıt helvacı geçmedi bugün 

radyoda sevdiğin şarkı çalmadı 

astığın çamaşırları rüzgar aldı 

sen şimdi gittin', 'gece küsmüş kendine  güneş niye doğduğundan habersiz  inkar ediyor deniz mavi olduğunu  bütün gülleri sözü var açmamaya  sen şimdi gittin  k...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Çetin']::text[], 8.5, '{"poet":"Tacettin Çetin","poet_slug":"tacettin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-simdi-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-erdal-bozdogan-cs6h7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok tuhaf şey vaktim olmazdı, 

Hatırlamaya yalnızlığımı.

Yalnızlık gerçi hiç aklımdan çıkmazdı.

Ama düşünmezdim yalnız kaldığımı.

Suda genişleyen halkalar gibi, 

Birer, birer uzaklaştı dostlarım.

Dağılıp gitti herkes, sırdaşım, arkadaşım...

Uzaklaştılar benden sudaki halkalar gibi.

Kapımı çalsanız her biriniz birer, birer, 

Çıkıp karşıma merhaba deseniz.

Çekip çıkarsanız beni yalnızlığımdan, 

O zaman ne mutlu olurum bilemezsiniz.

Bir romandan, bir şiirden çıkıp, 

Her seferinde bir güneş gibi doğan, 

İnsanı vazgeçilmez hayata bağlayan, 

Neredesiniz eski dostlar? Hepinizi özledim.

20.02.2000', 'Çok tuhaf şey vaktim olmazdı,  Hatırlamaya yalnızlığımı. Yalnızlık gerçi hiç aklımdan çıkmazdı. Ama düşünmezdim yalnız kaldığımı. Suda geniş...', ARRAY['Türk Edebiyatı','Şiir','Erdal Bozdoğan']::text[], 8.5, '{"poet":"Erdal Bozdoğan","poet_slug":"erdal-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizligim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-tacettin-cetin-nfupm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tüm düşlerin son bulduğu bir anda 

düşmekten korkan bir yağmur tanesinin 

ona muhtaç olan bir avuç toprağa düşmesi gibi 

bir aralık sızıverdin dünyama 

yeni aşkım MERHABA', 'tüm düşlerin son bulduğu bir anda  düşmekten korkan bir yağmur tanesinin  ona muhtaç olan bir avuç toprağa düşmesi gibi  bir aralık sızıverd...', ARRAY['Türk Edebiyatı','Şiir','Tacettin Çetin']::text[], 8.5, '{"poet":"Tacettin Çetin","poet_slug":"tacettin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/merhaba-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paranoya', 'paranoya-muhammet-sunar-qwsjy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eller geziniyor sırtımda

bu resimden aldığım ilhamla

fenerde kavuşmanın tadıyla

gecenin karşısına çıkacak

bir yüz arıyorum

birazda nem kokusu

                                                  /yanında biri

kovalıyor 

gizli kaypak

düşünki birazdan kırmızı dökülecek

üstüne gecenin 

devrik cümlelerle

-yeterli nedeni yok-

kimseyi doyurmaz

                                                 /gece

yani herkes

aynı saate doğmaz

                                                /kırmızı dağılıyor iyice

madem yanıyorum

göğsümü gömleğimi yırtarak

kanıtlayamam size içindekilerle

zira hayata dair bir leke 

büyümekte üzerimde

ve gece olmadan

gözlerimde sefere hazır gemiler

sonra bir kıvılcım

                                                 /kırmızın rolü biter böylece

belki ürkünç

gözlerin her parlayışı

saçını yolan bir cinnet fırtınasından

bağıran notalardır

evet evet

gizlenenler çıkmalı

benim diyen her şey

hissettiklerini boğmalı

elleriyle 

ve kan kırmızı gözleriyle

(istanbul mart 92)', 'eller geziniyor sırtımda bu resimden aldığım ilhamla fenerde kavuşmanın tadıyla gecenin karşısına çıkacak bir yüz arıyorum birazda nem kokus...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/paranoya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-muhammet-sunar-x74qc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sonbahar

sarı yapraklar gibi

çoğalıyor ölüm

yüreğimin gözlerine çevrilen

uzaklara dikilen yerinde gözlerinin

yalnızlıksa rüzgarca hırpalıyor

dolgun ve en gerçek yerinden

okyanusun bir köşesinde

bir başına bir gemide

solgun akşam üstleri

sesinin titrek anında 

anlamlanıyor ölüm

yaşamışlığın ıssızlığında

benim ıssızlığım kimsesiz

gözlerim açık ölüm kadar

(erzurum ocak 92)', 'sonbahar sarı yapraklar gibi çoğalıyor ölüm yüreğimin gözlerine çevrilen uzaklara dikilen yerinde gözlerinin yalnızlıksa rüzgarca hırpalıyor...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonbahar-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Kaçkını', 'yagmur-kackini-muhammet-sunar-n7z4y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'haz vermiyorsa yağmur artık

al gülüm ver gülüm uzanışlar ortasına

bir bezginlik oturdu biliyorum

biliyorum

saklananlar açığa vurana dek

her sabah bir gerçek fısıldanacak

hiçbir şeye bağlanamayan yalnızlığa

çünkü sen anladıkça düşecek

aklar saçına

sen gizlendikçe yüreğinde

dibe çökecek hayat

yüzünü çınlatan kapılar

yorgun gıcırdar anla

yaslan duvara konuşmahafif mırıldan

zamanıdır

(istanbul kasım 91)', 'haz vermiyorsa yağmur artık al gülüm ver gülüm uzanışlar ortasına bir bezginlik oturdu biliyorum biliyorum saklananlar açığa vurana dek her ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-kackini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Dön Be', 'don-don-be-aydin-karatay-thceb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yaşayamadık seninle biz

en güzel duyguların tazeligini

barındıramadk benligimizde aşkı

yada yaşatamadık sevgiyi ölümsüzce 

erken başladı ve erken bitti nedense

yaşayamadık biz seninile 

düzensizce haykıramadık 

karşı gelemedik ayrılıkların sarhoşluguna

oysa 

benim için yaşanmış en güzel günlerdi

benim için en güzel bahardı

benim için en güzel geceydi 

seninle yaşadıgım 

ve şunu bilki sen gidince 

neyse............................

bilirsin beni hala aynıyım sanırım 

sanırım çünkü bir parçam yok gibi bu günlerde 

sen yoksun yoksun be 

odamdayım yine sahil seniniçin bestelemiş şarkısını

bu gece senin için çalıyor sanki

saatim durmuş

gidişinden hemen bir saniye ötede 

dön be dön çok geç olmamış bak 

neredeysen geri dön 

bu gece sarhoşum biraz 

bilirim şimdi olsaydın 

tutardın ellerimi yatagıma yatırırdın usulca 

üzerimi örterdin penceremi aralardın birazda 

sabaha çayım hazır olurdu kalktıgımda 

ve sen uyumazdın o gece bilirim 

seni seviyorum derdin 

dön dön be bak çok geç olmamış zaten 

neredeysen dön be 

saatim durmuş gişinin bir saniye ötesinde 

bu gün dışarı çıkmadım hiç

odanda dolaştım biraz kokun sinmiş duvarlara 

sancılanmış bedenim duvarların arasında 

güneş sımsıcak bedenim donuyor 

konuşmuyor gülmüyor aglamıyor gözlerim 

boşluga bırakılmış bir uçurtma gibiyim 

sensizlik gibiyim yani 

gidişin gibiyim kapıyı çarpışın gibiyim

sana dur diyi yalvardıgım gibiyim hala 

dön dön be neredeysen dön 

bak çok geç olmamış zaten 

saatim durmuş gidişinin bir saniye ötesinde 

      06   - nisan  -   02       16: 54        izmir', 'yaşayamadık seninle biz en güzel duyguların tazeligini barındıramadk benligimizde aşkı yada yaşatamadık sevgiyi ölümsüzce  erken başladı ve ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Karatay']::text[], 8.5, '{"poet":"Aydın Karatay","poet_slug":"aydin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/don-don-be-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İma Kuşu', 'i-ma-kusu-muhammet-sunar-a9ceb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir gül üşümesini uyandıran

bu ney sesi 

bahtına vurulmuş veremdir

bu gülün gözleri gridir

bilinmez

hatta mecazi bile değildir

ondanki narin

ondanki melankolidir

bu beyazlık toprağından

gri gözleri ben aşık olayım diye

ey rüyasına boğulduğum

ey rüyasında boğulduğum

bilirim

bu kuşlar senden bir imadır

lakin bu duruluk bu gece vakti 

bir yolculukmudur

bir gül üşümesini uyandıran bu ney sesi

bir bölük ima kuşudur

(erzurum ağustos 91)', 'bir gül üşümesini uyandıran bu ney sesi  bahtına vurulmuş veremdir bu gülün gözleri gridir bilinmez hatta mecazi bile değildir ondanki narin...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ima-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamayacak Yarın İnsanlar', 'aglamayacak-yarin-i-nsanlar-zeki-ergin-5k7zm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çağ durmaz 

yürüyor

arayanlara doğru

tüm verileriyle

ölüme meydan okuyan yiğitleriyle

ölüm bir gonca gül bizler için

ölümün başladığı yerde

artakalanların 

mutluluğudur bizler için

onlar yüzyıl sonra

bizim düşlerimizi yaşıyor

yüzyıl sonra da olsa

sofralarda anılmak

ruhlarda sonsuzlaşmak

sağlıklı yüzler

evrenimizi

ve de herşeyiyle kendine sahip

kişiler süslüyor

_ mustafakemalpaşa ağus68

_köz yt:1973

_sevgiliye isyan yt:haz04', 'çağ durmaz  yürüyor arayanlara doğru tüm verileriyle ölüme meydan okuyan yiğitleriyle ölüm bir gonca gül bizler için ölümün başladığı yerde ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aglamayacak-yarin-insanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasırlı Eller', 'nasirli-eller-zeki-ergin-ujc0o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bugün

bir adamoğlu gördüm sokakta

yüzü

kırış kırış

gözleri

halka halka morarmış 

kafakağıdını bilmem ya

zavallı çökmüş ömrünün baharında

herkes

bir başka bakıyordu yükseklerden

yoktu güzel giysileri

ama

gene de sevdim

ayağında

kıl çorabı

kara lastiği

ve de 

nasırlı elleriyle

_çavuşlu ağus65

_köz yt:1973

_dağlara ver sırtını yt:haz09', 'bugün bir adamoğlu gördüm sokakta yüzü kırış kırış gözleri halka halka morarmış  kafakağıdını bilmem ya zavallı çökmüş ömrünün baharında her...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nasirli-eller-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Zulüm', 'ayrilik-zulum-umut-gul-o1elu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yol nedir ki, gülüm yürürsün biter, 

Dağ nedir ki gülüm, aşarsın biter, 

Ateş nedir ki gülüm, su ile söner, 

Soğuk nedir ki gülüm, ateşle gider.

Ayrılık zordur gülüm, sensizlik zulüm, 

Hasret zordur gülüm, arkası ölüm, 

Ölüm nedir ki gülüm, her kulun sonu ölüm, 

Yeter ki hasret olmasın sevene, 

Ayrılık zulüm..! 

Gün nedir ki gülüm, bir çırpıda geçer, 

Mevlam ayrılık vermesin yeter, 

Yıl nedir ki gülüm, saymakla biter, 

Yeter ki sev beni gelirde geçer.

Ayrılık zordur gülüm, sensizlik zulüm, 

Hasretin acıdır gülüm, sonrası ölüm, 

Ölüm nedir ki gülüm, uğrunda ölüm, 

Yeter ki hasret olmasın bana, 

Ayrılık zulüm..!', 'Yol nedir ki, gülüm yürürsün biter,  Dağ nedir ki gülüm, aşarsın biter,  Ateş nedir ki gülüm, su ile söner,  Soğuk nedir ki gülüm, ateşle gi...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayrilik-zulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Kuşları', 'sevda-kuslari-muhammet-sunar-r9zty', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'beklentilerim ağırlıklarıyla

yol oldu olalı

üzerinde sevda kuşlarının

otomobil çiğnentisi cesetleri 

ve hafif pıhtılaşmış kanlı 

tüyleri duruyor

dünyadan dünya beğenmek 

kolay değil

hatta kavgalık canlık

oğulsuzluk

boş günlük düşünülerimi

karlı ve yüksek dağlarla

özdeşleştirmemi hırpalayan 

işte bu beğeni', 'beklentilerim ağırlıklarıyla yol oldu olalı üzerinde sevda kuşlarının otomobil çiğnentisi cesetleri  ve hafif pıhtılaşmış kanlı  tüyleri dur...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevda-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlarını Özgür Kıl İçinden', 'kuslarini-ozgur-kil-i-cinden-muhammet-sunar-0unia', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kuşlarını özgür kıl içinden

üçgen bir betimlemeyle

tahta açılımlarına bırak

zamanın

yeşili mavi tonlarla düşle

tut bütün çinilerini

ustaların buz damlalarına 

kat kanat çırpınışlarının

yeşili mavi tonlarla düşle

zira acımaktadır ruhun

ilginç sıralamalar 

öğrendikçe hayatta

içinden çoğaltıdır

fırlayışı çığlayanın

(erzurum aralık 92)', 'kuşlarını özgür kıl içinden üçgen bir betimlemeyle tahta açılımlarına bırak zamanın yeşili mavi tonlarla düşle tut bütün çinilerini ustaları...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kuslarini-ozgur-kil-icinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos', 'agustos-muhammet-sunar-dszbz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aşka iman ettim

akşamla gece arasından 

kurtarıp kalbimi

araladım sayfalarını ağustosun

koluna koydum başımı

sesimi hediye ettim

ve

bekledim

beden nedirki 

ruh aşkın sayfasıdır

aşka iman ettim

çünkü geceydi

ağustostu

ağzım yoktu

dilim yoktu

ölüm yoktu

yalnız uykumuz vardı

ve gözlerimiz içsindi sıcağı

çünkü ağustostu

(erzurum ağustos 95)', 'aşka iman ettim akşamla gece arasından  kurtarıp kalbimi araladım sayfalarını ağustosun koluna koydum başımı sesimi hediye ettim ve bekledim...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/agustos-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar Vezni', 'i-ntihar-vezni-muhammet-sunar-zb51s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sana ulaşamıyorum

ellerimi

bulduğum her dala uzatıp

gözlerim dola dola

anlamalısın 

çaresizlik boğuyor

ve çöp gibi kalıyorum

acıların nehrinde

sensizliğin derininde

intihar vezninde

boğula boğula

sona ulaşamıyorum

(istanbul mayıs 93)', 'sana ulaşamıyorum ellerimi bulduğum her dala uzatıp gözlerim dola dola anlamalısın  çaresizlik boğuyor ve çöp gibi kalıyorum acıların nehrin...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/intihar-vezni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SARIYOR SARI YORDUKÇA', 'sariyor-sari-yordukca-muhammet-sunar-hu4gl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yeniden sarıya vurdu yapraklar

radyoda sonsuzluk soloları başladı

ölüm bir daha uzandı 

şehrin ölgün çehresinde

kedi renkleri ufak adımlarla

pencere önlerinde yeniden

iskemle sigara öksürük

en mutena yerinden tutuyor

hayatın insanlarını

tututkça sarı yor

çün ölüm

bir yaprağın içinde uzanmaktadır şimdi 

(istanbul mayıs 93)', 'yeniden sarıya vurdu yapraklar radyoda sonsuzluk soloları başladı ölüm bir daha uzandı  şehrin ölgün çehresinde kedi renkleri ufak adımlarla...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sariyor-sari-yordukca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Yürek', 'deli-yurek-can-yucel-be7j1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni yıldızlara benzetiyorum onlar kadar etkileyici, çekici ve güzelsin ama aranızda tek fark var onlar milyonlarca sen birtanesin.........', 'seni yıldızlara benzetiyorum onlar kadar etkileyici, çekici ve güzelsin ama aranızda tek fark var onlar milyonlarca sen birtanesin............', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/deli-yurek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyi Kaybettim', 'herseyi-kaybettim-i-lyas-altuner-220p8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-- Filistin''e --

Herşeyi kaybettim

Seni, kendimi, bir de sapanımı

Düştü kucağımdan taşlar

Onun için akıyor yerlerde kanım

Canım yitiyor onun için

Düşüyorsun

Durmuyorsun avuçlarımda

Gündüzler ateş

Geceler soğuk

Ayakta dursa da yüreğim

Kanadımı kaybettim

Uçamıyor kollarım ölüme şimdi

Azrail''i kaybettim', '-- Filistin''e -- Herşeyi kaybettim Seni, kendimi, bir de sapanımı Düştü kucağımdan taşlar Onun için akıyor yerlerde kanım Canım yitiyor onun...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/herseyi-kaybettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-sair-kacubet-wdop2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir kardeşim hayat dediğimiz? 

Kalbin atması mı, nefes almak mı? 

Sevmek midir hayat, yoksa hayat mıdır sevdiğimiz? 

Gözyaşıyla mı yaşarız biz kanla mı? 

Hissizleştikçe mi yaşlanır insan zamanla mı? 

Aslında yok galiba hayatın anlamı, 

Bir rüya görüyoruz biz iki ezan arasında...

Öyle olmasa fark olmaz mıydı gülmekle ağlamak arasında?', 'Nedir kardeşim hayat dediğimiz?  Kalbin atması mı, nefes almak mı?  Sevmek midir hayat, yoksa hayat mıdır sevdiğimiz?  Gözyaşıyla mı yaşarız...', ARRAY['Türk Edebiyatı','Şiir','Şair Kaçubet']::text[], 8.5, '{"poet":"Şair Kaçubet","poet_slug":"sair-kacubet","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Köprüde', 'bir-koprude-haldun-i-plikcioglu-gkfp5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susa susa nasıl da anlaşmıştık

bir köprüde konuşarak

gözlerinden gözlerime

Avuç avuç sakladığım korkularla

loş puslu, bir iki mumluk

ışık karanlığındaki o bekleyiş

Geldiğinde kardelenlerin

kokusu sarmıştı her yanı

ve yüzünde

solgun mu solgun bir gülümseyiş

Yüreğinden yüreğime asılı bir köprüde

susa susa nasıl da konuşmuştuk

öyle saatlerce, günlerce

Bir tarafta çıplak omuzlarını gizleyen 

sarı başak, mavi menekşeler

bir tarafta küllenmiş pişmanlık

Hüzünlere dar gelen geceler

ve bir iki mumluk ışık

Yukarda  sessizliğin doruğunda ikimiz

altımızda bir deli fişek

akıp giden hislerimiz

Rengarenk geceyarısı ışıklarının

puslu dumanından çıkma

uzaklara çağıran bu ağrı

Yıllardır korkularımı sakladığım

kucağımda yavaş yavaş gevşeyen

benliğimdeki bu soluksuz sargı

Bir hatırladığım, sızıların aktığı

kum saatiydi çevirip bıraktığın

Bir de, gecenin sabaha kavuştuğu

duygulara bağlanan ayazıydı

o son geçtiğimiz sokakların

Gözlerinden gözlerime gerili bir köprüde

susa susa nasıl da anlaşmıştık

susa susa nasıl da konuşmuştuk 

öyle saatlerce, günlerce, senelerce', 'Susa susa nasıl da anlaşmıştık bir köprüde konuşarak gözlerinden gözlerime Avuç avuç sakladığım korkularla loş puslu, bir iki mumluk ışık ka...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-koprude-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengarenk gri', 'rengarenk-gri-haldun-i-plikcioglu-rwtyu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk döndürür başımızı, 

bitmez  sanırız gözlerimize dolan sevinç

Rengarenk mis kokulu günlere

çivilenmek ister hep geçmişimiz

Oysa çiçekler kurur önce

yapraklar terkeder sonra ağaçları

sapsarı olur etraf sessizce

ve solar sevginin heceleri artık içimizde

Birden sarsılır yüreğindeki duvarlar

birden erir içindeki özlem

Sevgin yavaşca sönmeye başlar

yaşayıp da yitip giden günler gibi

Hiç hissettirmeden solar gönlün

Ve önce sen beni unutursun

sonrada ben seni', 'Mutluluk döndürür başımızı,  bitmez  sanırız gözlerimize dolan sevinç Rengarenk mis kokulu günlere çivilenmek ister hep geçmişimiz Oysa çiçe...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/rengarenk-gri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Saydın mı', 'hic-saydin-mi-haldun-i-plikcioglu-pjetc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimin çöplüğünden çıkarttığım anılardır

geçmiş rüzgarların kumlarla karıştığı gecelerde

öfkeyle kalkıp

	üstünden atladığım ateşler

Sırtüstü yatıp dinlediğim fısıltılardır

gitgide küçülen gökyüzünde

ağır aksak yağıp

	gözlerimi yalayan yıldızlar

Ardımda kalan dağlara tırmanıp

yakalamaya çalıştığımda dolunayı

köpürüp kaynayan sulardır

kaygısız yayılan yalnızlık

Ay doğar

	ay batar

aslında korkaktır gece kuşları

Ben çamurdan duvarlar örerken

sen hiç saydın mı yıldızları

toprak güne karışıp

	tan ağırırken

Yüreğimin çöplüğünden çıkarttığım düşlerdir

ilkbahar yaza

	yaz sonbahara karışırken

bembeyaz bulutlardan dökülen sözcükler

Issız sabahlara yayılan küllerdir

bahçedeki güller gülerken

parmaklarımın ucunda değişen günlükler

Sabahın soğuk saatlerinde

düşler avlarım

	bir düşten, bir düşe

Ne olmak isterim gerçekten

Bulutlardan dökülen sözcükler

yağmur olur ağaçlara

	dallar bükülür

Kimseler yokken evimin kapısında

şarkı olur yağmurlar

	düşlerden süzülür

Ben ilk saatlerinde ayazın 

	insan olduğumu hatırlarken

sen hiç saydın mı bulutları

toprak güne sarılıp

	sabah yeryüzüne yayılırken

Yüreğimin çöplüğünden çıkarttığım sıkıntılardır

toprak havaya

	ateş suya değerken

sürekli kavgalara teslim olan dünyam

Öğle sıcağında yüreğimi sızlatanlardır

herkes evlerini boşaltırken

gün ışığından keskin, donuk yalan

Camdan gerçekler yontarım

ne gören olur

	ne duyan

Sokaklarda kendi öykümü ararken

aydınlığa itirazlarımı bırakırım

Ben sokakları ucu ucuna eklerken

sen hiç saydın mı boş evleri

toprak güne karışıp

	öğle yeryüzünü sıvarken

Yüreğimin çöplüğünden çıkarttığım

yine iki parça yürektir

ortasından bölünmüş iki parça

Akşamüstlerinin dar geçitlerine bıraktığım

bir iki parça sıkıntıdır

bir iki parça hüzün

bir iki parça sevgi

Dilim yaşlanır kendime söylenmekten

göz alabildiğince uzanır akşamüstü

ve insanlar oynar yanımda sürekli

Ben böyle parçalanırken

sen hiç saydın mı beni

kaç parçaya bölündüğümü

akşam günü vururken

	açılırken yüreğimin örtüsü', 'Yüreğimin çöplüğünden çıkarttığım anılardır geçmiş rüzgarların kumlarla karıştığı gecelerde öfkeyle kalkıp 	üstünden atladığım ateşler Sırtü...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/hic-saydin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerımdekı Gurbetlım', 'gozlerimdeki-gurbetlim-sair-haydar-dfmvk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gozlerimdeki gurbetlim yureyimdeki sevdam hayalimdeki kiz gecelerimin kadini ruyamdaki meleyimsin seni seviyorum', 'gozlerimdeki gurbetlim yureyimdeki sevdam hayalimdeki kiz gecelerimin kadini ruyamdaki meleyimsin seni seviyorum...', ARRAY['Türk Edebiyatı','Şiir','Şair Haydar']::text[], 8.5, '{"poet":"Şair Haydar","poet_slug":"sair-haydar","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/gozlerimdeki-gurbetlim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik', 'gelincik-haldun-i-plikcioglu-5kob3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sımsıcak bahar sabahı açılır yüreğin

kapanıp kalır üstüne

bir yol kenarında yalnızlığa inat

kıpkırmızı açan gelinciğin

Bir rüzgar kopar uzaklardan

sımsıcak bir bahar sabahı

konar en derin  kuytularına

Bahar heyecanından ellerin terler

dağılır gelincik yaprakları

Karışır diğer çiçeklerle

dağılan gelincik yaprakları

Uçup da yapışır tenine

gözlerine dolar yeşil sarı

Gözbebeklerinde karşılaşır ilk kez

eflatun mor ve kırmızı

Sımsıcak bahar sabahı

gözlerinde büyür çiçekler

yaprak yaprak yeşil sarı

Gözyaşlarınla akar ilk kez

uçup dağılan gelincik yaprakları', 'Sımsıcak bahar sabahı açılır yüreğin kapanıp kalır üstüne bir yol kenarında yalnızlığa inat kıpkırmızı açan gelinciğin Bir rüzgar kopar uzak...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelincik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serinlik', 'serinlik-haldun-i-plikcioglu-0a6cr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendi gözlerim kendimi seçmiyor

Ellerim benden yana değil

Ayaklarımı ileri sürümek istiyorum hep

Oralı oldukları bile yok

Hepsi yanımda, kimse bende değil.

Bir serinlik istiyor sıcak gece, 

Hortumlu bir fırtına denizden

Uğultulu bir rüzgar tepeden

Ne serinlik yarıyor geceye

Ne de gece serinliğe', 'Kendi gözlerim kendimi seçmiyor Ellerim benden yana değil Ayaklarımı ileri sürümek istiyorum hep Oralı oldukları bile yok Hepsi yanımda, kim...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/serinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bina', 'bina-haldun-i-plikcioglu-aupr7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde bir yerlerde

duvarları neden bilmem

bir bina yapıyorum durmadan

Önce her şeyi her yere yerleştiriyorum

sonra bir şey arıyorum her yerde

Ben farkında olmadan sakın

içimde bir yerlerde mi hep yaşıyorum', 'İçimde bir yerlerde duvarları neden bilmem bir bina yapıyorum durmadan Önce her şeyi her yere yerleştiriyorum sonra bir şey arıyorum her yer...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğım', 'bebegim-sair-haydar-06ngz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni  gördugum  an  sor kalbıme                   

hukmeder  gözlerıme

bu  gözler   ağlamak  ister       

bu  gönlum  senı  sevıyorum  demek  ister      

ağlamak  karım  oldu   gözlerım  yaş  doldu          

senı  çok  çok  sevıyorum  bebeyım

sana  haykırarak  senı  sevıyorum  demek  tek  dıleyım sarılarak  saçlarını  okşamak  tek  hayalım          

sevda  gulum  senı  öyle  sevıyorum ki   

inanmiyorsan  sor  kalbıme                                 

seni  çok  çok  sevıyorum  bebeyim', 'seni  gördugum  an  sor kalbıme                    hukmeder  gözlerıme bu  gözler   ağlamak  ister        bu  gönlum  senı  sevıyorum  demek...', ARRAY['Türk Edebiyatı','Şiir','Şair Haydar']::text[], 8.5, '{"poet":"Şair Haydar","poet_slug":"sair-haydar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bebegim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiş Geliş', 'gidis-gelis-haldun-i-plikcioglu-8log5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanın içini kemiriyor bu merak

Yüreğimin son sığınağı da doldu

Sorun

gitmelerinde değil

Gelmelerin nasıl olacak', 'İnsanın içini kemiriyor bu merak Yüreğimin son sığınağı da doldu Sorun gitmelerinde değil Gelmelerin nasıl olacak...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gidis-gelis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kale', 'kale-haldun-i-plikcioglu-he69c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıkılacaktı elbette birgün surları biliyordum

Etrafımı kuşatan bu kale de düşecekti

Çırılçıplak kalakalacaktım karlar üzerinde

Yüreğimde bir büyük heyecan kalacaktı sadece

Ve bedenimde kanamalı diken yaraları

Yenilecektim elbette birgün biliyordum

Şimdi etrafımda yenilginin alevleri 

Hayat, artık sana teslim oluyorum

Yüzleşmekten korktuğum ne varsa eskiden

Gelip saplanacaktı umutlara biliyordum.

Sözsüz kalacaktı dilim çaresiz

Gözlerime yerleşecekti hecelerim

Kaçmak bir yenilgiydi de

Cesaretin yeni adı ne 

Hayat, artık sana teslim oluyorum', 'Yıkılacaktı elbette birgün surları biliyordum Etrafımı kuşatan bu kale de düşecekti Çırılçıplak kalakalacaktım karlar üzerinde Yüreğimde bir...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkese Seni Söylerim', 'herkese-seni-soylerim-haldun-i-plikcioglu-z11mg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedir  gökyüzünün küle çalan bu rengi

Nedir sabahtan beri yağmurlarla inip

ayaklarımı zorla yollara çeken bu ezgi

Bu serinlik

bu gittikçe sıkıştıran

üstüme üstüme gelen insan seli

Nedir, hiç durmadan gözümde

bir kırptığımda yok olan

bir kırptığımda ışıyan

Kalbimi zorladığımda

önümde beliren bir  mahsun karaltı

Kulaklarımı yırtarcasına açtığımda

duyduğum  o sararmış fısıltı

Duvarın ötesine meraklandığımda

arkasında, çürümüş yaprakların yatağında

hep üstümü örtmeye çalışan bir sancı

Ne geceye söylerim

ne güneşe

Ben seni bilir

sana seni söylerim

Yok olduğunda ya da ışıdığında

karaltı olduğunda ya da fısıltı

kalbimi yırtar

çürümüş yapraklara ben yine seni söylerim', 'Nedir  gökyüzünün küle çalan bu rengi Nedir sabahtan beri yağmurlarla inip ayaklarımı zorla yollara çeken bu ezgi Bu serinlik bu gittikçe sı...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/herkese-seni-soylerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatlaklar', 'catlaklar-haldun-i-plikcioglu-n9c0z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi ışık parlar

el değmemiş zamane fenerlerinden

Hangi aşk büyür, taşar

daha duymadığımız  öykülerden

Hangi söz sarar bizi, hangisi sizi 

bugünün anlamsız düşüncelerinden

Neden satarız benliklerimizi

sürekli neyi hatırlamaya çalışırız

Bulanık çeşmelerde yıkayıp da sevgimizi

neden bölük pörçük etrafa dağılırız.', 'Hangi ışık parlar el değmemiş zamane fenerlerinden Hangi aşk büyür, taşar daha duymadığımız  öykülerden Hangi söz sarar bizi, hangisi sizi  ...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/catlaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı', 'sizi-haldun-i-plikcioglu-zt41u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanımın 

bilmem kaç bin yıl öncesinden 

gelip bana sarılan 

bilmem kaç bin yıl ötesine

benden kopup giden

birikimin yazgısına kapıldım bir kez

Bir kez gözlerime yerleşti insanlar.

el değmemiş gecelerime girdiler

duyulmamış hikayelerime

hiç hatırlanmayan düşlerime

Neydi o

yıllardır bahçemde duran

yarı aydınlık, yarı karanlık ağacın

dallarından koparıp koparıp

didiklediğim

Neydi o

demincek avucumda duran

parmaklarıma dolanıp dolanıp

çözemediğim

Neydi o sözcükler

dilimin ucunda heceleyip heceleyip

bir türlü söyleyemediğim

Neydi o içimdeki  bent

sızım sızım ardına biriktiğim', 'Zamanımın  bilmem kaç bin yıl öncesinden  gelip bana sarılan  bilmem kaç bin yıl ötesine benden kopup giden birikimin yazgısına kapıldım bir...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sizi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın', 'yarin-haldun-i-plikcioglu-yflf3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“Kuşlar

Kanatlarını yarına doğru çırpar

Gülümseyen yüzüne doğru sıcak güneşin.”

Ben de, 

Ben de koparabilsem kendimi dünden, 

Bir dolu tutsaklıktan kurtarabilsem düşüncelerimi, 

Ayrılıklar daha gelmeden

Bir kanatta aşabilsem özlemleri.

Ne olurdu

Yarında kalabilsen yanımda, 

Bugün olduğu gibi…', '“Kuşlar Kanatlarını yarına doğru çırpar Gülümseyen yüzüne doğru sıcak güneşin.” Ben de,  Ben de koparabilsem kendimi dünden,  Bir dolu tutsa...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yarin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Damlası', 'yagmur-damlasi-haldun-i-plikcioglu-bhg9t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sular çekilmeden o kimsesiz göllerde

buharlaşıp bir bulut oldu gökyüzünde

Dolu dolu içine çekti mavilikleri

ve günlerce serin bir gece bekledi

bambaşkaydı çünkü ayışığında süzülmek

konmak yeryüzüne, soğuğu hissetmek

O küçücük bir yağmur damlasıydı

Farkını bilmezdi hiç mutlulukla, hüznün

Öyle gölden göğe, gökten yere koşardı

Neye yaradığını bilmedi hiç içindeki gücün

Benim onu tanıdığım gün 

Teşekkür etmek için bile durmadı

oysa çiçekler sermiştim altına

hiçbir yeri incinmeden konması için

Anlatmak istesek, ne yaşamlar vardı

kocaman gölgesinde devlerin

Onunkisi küçücük bir yaşam parçasıydı

gölden göğe

	gökten yere

bilemedin üç günlük bir telaş zamanıydı

O, küçücük bir yağmur damlasıydı

Öbür yağmur damlalarını  taksa peşine

hiçbir set onları durduramazdı

Hızla çarpsa hiç tanımadığı tenlere

kimse gözünü bile  kırpamazdı

Oysa o, küçücük bir yağmur damlasıydı

farkını  bilmezdi hiç mutlulukla, hüznün

ve ne olduğunu içindeki gücün

Yaşam olurdu yeryüzüne

Renkleri taşırdı sırtında

yeşili ormana verirdi, maviyi denize

O küçücük bir yağmur damlasıydı, 

üç günlük bir telaş zamanı

Düşünmedi  hiç neden yaşadığını

ve kocaman amacını hiç öğrenmedi', 'Sular çekilmeden o kimsesiz göllerde buharlaşıp bir bulut oldu gökyüzünde Dolu dolu içine çekti mavilikleri ve günlerce serin bir gece bekle...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yagmur-damlasi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-emine-sumra-s8txt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sokak lambasının ışığı yırtarken sisli geceyi

O ıslak, o soğuk gecede, 

Beyaz perde sarmış sensizliği paylaşıyorum.

Çıkıp gelsen sisin içinden

Yorgun, bitkin

Buz tutmuş parmakların.

Uzat bebeğim dudaklarıma ısıtsın nefesim

Gel! 

Gelki gecenin matemi kalksın üstünden

Gelki yırtmasın gözlerim puslu geceyi.', 'Sokak lambasının ışığı yırtarken sisli geceyi O ıslak, o soğuk gecede,  Beyaz perde sarmış sensizliği paylaşıyorum. Çıkıp gelsen sisin içind...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bekleyis-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerimde bıraktım', 'hayallerimde-biraktim-emine-sumra-inyj8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doyunca yaşamadım seni.

Elinin tadı kaldı elimde.

Saçlarım saracakken dudaklarını, 

Seni hayallerimde bıraktım

Kayboldum ya gözlerinde, 

Çırpına, çırpına nefesim kaldı dudaklarında

Taştı yüreğim acıdan.

Seni hayallerimde bıraktım.

Çiğ düşmüş yaprak gibi

Aha şuramda bir üşüme.

Nede yakışır yaprak ve çiğ bir birine

Ama ben seni hayallerimde bıraktım', 'Doyunca yaşamadım seni. Elinin tadı kaldı elimde. Saçlarım saracakken dudaklarını,  Seni hayallerimde bıraktım Kayboldum ya gözlerinde,  Çır...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayallerimde-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik Kız', 'minik-kiz-hulya-arisan-i4q6g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey 

rüyalar ülkesinin

 minik kızı, 

gerçek dünyada 

bulamadığın, 

tüm güzellikler için miydi,

  bu fedakarlık.

Kaçmak istiyorsun, 

gerçeklerden kaçmak.

Gizli bir sonsuzluğun

arkasından gitmek, 

gitmek

ve, 

geri dönmemek...

İstanbul, Nisan 1993', 'Ey  rüyalar ülkesinin  minik kızı,  gerçek dünyada  bulamadığın,  tüm güzellikler için miydi,   bu fedakarlık. Kaçmak istiyorsun,  gerçekler...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/minik-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız', 'zamansiz-tarkan-kalkan-o9k5n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamansız

Katıksız susuz

Sorgusuz

öylesine yürüyorum

aklım uçmuş rüzgarda

sana diyor martılar

söylemiştik

zamansız

ağlamıyorum yürüyorum

yer de bir yaprak uçuşuyor

elimde son kalan yaz

yürüyorum denize doğru

sırtımda rüzgar tutuyor beni

düşeceğim düşemiyorum

yürüyorum sorgusuz

oysa yağmur sözvermişti 

ıslatacaktı beni

ve yine gelmedi

uçuşan yapraklar denizde

dalgalara yem oldu

aklım rüzgara 

uykusuzum

uyusam dünya mı kurtulacak

dalgalar bana mı vuracak

boşver

yırtılır bir gün zaman

bin yıl sonra

kimler gelecek bana

dünya mı olacak

kemiklerim müzedemi

köpeğinmi olacak

sorgusuz

katıksı susuz

daralmışım

zamansız diyorlar

algısız', 'Zamansız Katıksız susuz Sorgusuz öylesine yürüyorum aklım uçmuş rüzgarda sana diyor martılar söylemiştik zamansız ağlamıyorum yürüyorum yer ...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Kalkan']::text[], 8.5, '{"poet":"Tarkan Kalkan","poet_slug":"tarkan-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/zamansiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkıların Can Yaktığı Günlerdeyim', 'sarkilarin-can-yaktigi-gunlerdeyim-haldun-i-plikcioglu-llo1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden ansızın güneş gelir aklıma

Sımsıcak bir güneş.

Düşlerimin sessiz ufuklarından

Süzülüp de sakin bahçelerime 

Üşümüş dünyamı ısıtan

Ve yüreğimi saran güneş

Neden ansızın dağlar gelir aklıma

Yüksek ve sarp dağlar.

Uçup da geceleri odamdan

Tırmanmak isterken sarp yamaçlarına

Sürekli düşüp durduğum

Ve zirvelerinden bağıramadığım dağlar

Neden ansızın su gelir aklıma

Bir yudum su.

Düşlerimde yarattığım dağlardan

Akıp da bu yorgun şehre doğru

Sızlayan ayaklarıma dolanan

Ve kirli ellerimi yıkadığım su.

Şarkıların can yaktığı günlerdeyim.

 Sokak lambalarında gece kuşları

Akşam balkonlarında böcekler

Ne umarlar belli değil

Hep aydınlığa doğru uçarlar.

Gece kuşları sokak lambalarının

Böcekler balkonların

Her ışığın bir bekçisi var.

Ben senin başında

Sürekli nöbetteyim

Şarkıların can yaktığı günlerdeyim.

		

Dudağımın kenarına yapıştı sözler

Bir türlü ses olamıyorum.

Koşuyorum dağlara

Cebimde sessiz sözcükler

Varmak mümkün değil zirveye.

Koyuveriyorum kendimi su gibi

Önümde geceler

Ulaşmak mümkün değil güneşe.

Lambalarda kuş oluyorum

Balkonlarda böcekler

Ben mi bekçisiyim herşeyin

Bir de senin nöbetindeyim

Şarkıların can yaktığı günlerdeyim.', 'Neden ansızın güneş gelir aklıma Sımsıcak bir güneş. Düşlerimin sessiz ufuklarından Süzülüp de sakin bahçelerime  Üşümüş dünyamı ısıtan Ve y...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sarkilarin-can-yaktigi-gunlerdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bahçeler', 'ah-bahceler-cihan-erdem-ertek-8hrh5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bahçelerde lahana.

Bu ne biçim? kerviz.

Ben annemi özledim.

Gelsin 19 Mayıs...', 'Bahçelerde lahana. Bu ne biçim? kerviz. Ben annemi özledim. Gelsin 19 Mayıs......', ARRAY['Türk Edebiyatı','Şiir','Cihan Erdem Ertek']::text[], 8.5, '{"poet":"Cihan Erdem Ertek","poet_slug":"cihan-erdem-ertek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ah-bahceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey', 'bir-sey-haldun-i-plikcioglu-c46wd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimsenin eli değmez

bir ben bilirim adresini

İçimde bir yerlerde

bir şey var

Günlerdir içimin yollarındayım

Yağmurlar yağıyor sürekli

yüzüm sırılsıklam

Saçlarımdan düşüyor ellerime

üşümüş yağmur taneleri

İçimde bir yerlerde

bir şey var

İçimin yollarında yürüyorum

Bir ışık süzülüyor dalların arasından

etrafımda ağaçlar uyuyor

Bahar yağmurlarla geliyor

uyanıyor içimdeki yapraklar 

Bir cebimde umutlar

diğerinde  korkular

Hayat izler bırakır her anında

bende seni bıraktı

bir de ıslak yolları

Uyuyordum hiç bilmezdim

soğuk bir günde

aniden keşfettim

İçimdeki yollara

koşar adım giriverdim

İçimde bir yerlerde

bir şey var

sadece benim bildiğim', 'Kimsenin eli değmez bir ben bilirim adresini İçimde bir yerlerde bir şey var Günlerdir içimin yollarındayım Yağmurlar yağıyor sürekli yüzüm ...', ARRAY['Türk Edebiyatı','Şiir','Haldun İplikçioğlu']::text[], 8.5, '{"poet":"Haldun İplikçioğlu","poet_slug":"haldun-i-plikcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-sey-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırlarsan Bİr Gün', 'beni-hatirlarsan-bi-r-gun-hulya-arisan-2hgig', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani

an gelirde aklına takılırsa

yıllarca yaşanan 

o anıları.

Mutlu yaşanan günlerin 

hazını, 

o zaman resmime bak 

ve 

beni HATIRLA...

İstanbul, 2002', 'Hani an gelirde aklına takılırsa yıllarca yaşanan  o anıları. Mutlu yaşanan günlerin  hazını,  o zaman resmime bak  ve  beni HATIRLA... İsta...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beni-hatirlarsan-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen + Ben', 'sen-ben-hulya-arisan-dqoqb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorsun değil mi? 

Yokluğun ızdırap, 

varlığın çoşku. 

Yokluğun ölüm, 

varlığın yaşam.

Yokluğun sensizlik, 

varlığın SEN + BEN

Istanbul,2002', 'Biliyorsun değil mi?  Yokluğun ızdırap,  varlığın çoşku.  Yokluğun ölüm,  varlığın yaşam. Yokluğun sensizlik,  varlığın SEN + BEN Istanbul,2...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-ben-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkınım', 'saskinim-hakan-ocak-9k06o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ucurumun onunde duruyorum

Gozlerim ufukla, saclarim ruzgarla dalgalaniyor

Bir adim ileri atsam

geriye donus olmayacak

Caresizim, saskinim

Bir adim geriye atsam

ileriye gidis olmayacak

Dertliyim, saskinim

Oldugum yerde kalsam

omrumde degisen bir sey olmayacak

Asigim, saskinim', 'Bir ucurumun onunde duruyorum Gozlerim ufukla, saclarim ruzgarla dalgalaniyor Bir adim ileri atsam geriye donus olmayacak Caresizim, saskini...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ocak']::text[], 8.5, '{"poet":"Hakan Ocak","poet_slug":"hakan-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/saskinim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş', 'ates-hakan-ocak-9lpht', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbim, carpma oyle deli gibi

Bekleme, bosuna......o seni aramayacak

Dizlerim, titremeyin agacta kalan son yaprak gibi

Umutlanmayin, kapiyi acinca karsina o cikmayacak

Basim, nolur donme pervane gibi

Dusunme, o seni asla sevmeyecek

Yuregim, yanma komur gibi

Sevinme, o senin atesini asla sondurmeyecek', 'Kalbim, carpma oyle deli gibi Bekleme, bosuna......o seni aramayacak Dizlerim, titremeyin agacta kalan son yaprak gibi Umutlanmayin, kapiyi ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ocak']::text[], 8.5, '{"poet":"Hakan Ocak","poet_slug":"hakan-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ates-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-abacan-askisev-senkal-28jqc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana herşeyimi vermek isterdim; 

Aşkımı, sevgimi, kalbimi...

Seni her zaman mutlu etmek, 

Ama olmadı yapamadım! 

Seni her gördüğümde; 

Koşup yanına gelmek, 

Sımsıkı sarılmak isterdim, 

Ama olmadı yapamadım! 

Seni daha çok sevmek isterdim; 

Her saniye yeniden yeniden...

Gece gündüz sevdiğimi söylemek, 

Ama olmadı yapamadım! 

Senin için öyle şeyler isterdim ki; 

Yıllarca hatırlanacak nice güzel günler

Ve sana daha çok layık olabilmek, 

Ama olmadı yapamadım! 

Senin için çok şey yapmak isterdim; 

Mutluluğunla, neşenle, sevincinle, 

Kederinle, hüznünle, üzüntünle, 

Herşeyini paylaşmak yıllar boyu...

İsmini eksiltmeden dudaklarımdan, 

Sesini duymak her yeni an, 

Kalbinde yaşamayı her zaman...

Ama olmadı yapamadım! 

Güzel hatıralarla, güzel insanlarla, 

Daha güzel günlere, daha güzel yarınlara, 

Dolu dolu, sevip sevilerek, 

Umutla ve gülümseyerek...

Seninle birlikte ulaşmak isterdim, 

Ama olmadı yapamadım!', 'Sana herşeyimi vermek isterdim;  Aşkımı, sevgimi, kalbimi... Seni her zaman mutlu etmek,  Ama olmadı yapamadım!  Seni her gördüğümde;  Koşup...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/senin-icin-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-abacan-askisev-senkal-4dqv1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara kışın soğuk akşamlarında, 

Karanlıklar çöker yamaçlarına.

Yüksek tepelerinden gülümser, 

Bulutların sade gözyaşlarına.

Kuru yazın serin sabahlarında, 

Gün doğar zirvesinin uçlarına.

Aheste aheste rüzgarlar eser, 

Ardındaki koyu yeşil yaylaya.

Şimdi bembeyaz o yüce dağlar, 

Dorukları bulutlara yaslanır.

Kimbilir nerelerden başlayıp, 

Engin engin diyarlara uzanır.

''''Ne de çabuk geçti koca yıllar, 

 Çocukluğumun şahidi yaylalar... ''''

Diyerek şu gönlüm kahırlanır! 

Ve o haşmetli dost yaşlı dağlar, 

Bana hep geçmişimi hatırlatır...', 'Kara kışın soğuk akşamlarında,  Karanlıklar çöker yamaçlarına. Yüksek tepelerinden gülümser,  Bulutların sade gözyaşlarına. Kuru yazın serin...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/daglar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Diyemedim', 'elveda-diyemedim-abacan-askisev-senkal-k1tx8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok uzun bir aradan sonra, 

Beraberdik seninle kısa da olsa.

Belki birkaç saat, belki biraz fazla...

Hiç değişmemiştin, hala eskisi gibi, 

Hala çok güzel, hala çok çekici...

Birlikte oturduk kaygısızca

Eskiyi andık, duygulandık! 

Sokaklarda elele dolaştık, 

Sadece yürüdük, konuşmadan.

Bozulmasın istedim o an, 

Hiç bitmesin istedim.

Yaşadığımız sihirli dakikaların, 

Büyüsü bozulmasın dedim...

Sonra seni sevdiğimi söyledim, 

Tıpkı eskisi gibi dipdiriydi aşkım.

Dudaklarımda buseni hissettim, 

Sıcaklığını ise taa içimde...

Elveda diyemedim bir türlü, 

Anlatamadım tüm hislerimi...

Ayrılırken son bir kere gülümsedin, 

Çok şeyler okudum gözlerinden! 

Sonra koşarak uzaklaştın benden.

Gözyaşlarını görünce yüzünde, 

Ardından gelmek istedim.

Yapamadım, gelemedim bir türlü, 

Herşeyi daha zorlaştırmak istemedim! 

Bugünü, seni ve o son anı, 

Hiç unutmayacağım asla...

Aşkımızı ve hatıralarımızı, 

Sonsuza dek içimde yaşatacağım! 

Koskoca yıllar geçse de aradan, 

Kalbimde bıraktığın izi hep taşıyacağım...', 'Çok uzun bir aradan sonra,  Beraberdik seninle kısa da olsa. Belki birkaç saat, belki biraz fazla... Hiç değişmemiştin, hala eskisi gibi,  H...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/elveda-diyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kasım Sabahı', 'bir-kasim-sabahi-abacan-askisev-senkal-shmdn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dışarda hava soğuk ve dumanlı, 

Bulutlar simsiyah gökyüzünde

Yağmur çok yakın olmalı...

Esen rüzgar uçururken yaprakları, 

Sallanır ağaçların çıplak dalları.

Dolaşırken çamurlu yolları, 

Hala tenha sokak araları.

Yapayalnızım, unuttum anıları, 

Beni benden çalan yılları...

Sızlayan bir yara var içimde, 

Birkaç damla yaş gözlerimde! 

Kaybolmuş parlak ışıkları, 

Kalmamış güneşin sıcaklığı...

Yırttım bütün eski mektupları, 

Koparıp attım tüm sevdaları, 

Kapatalı çok oldu o sayfaları! 

Bugün günlerden salı, 

Soğuk bir Kasım sabahı...', 'Dışarda hava soğuk ve dumanlı,  Bulutlar simsiyah gökyüzünde Yağmur çok yakın olmalı... Esen rüzgar uçururken yaprakları,  Sallanır ağaçları...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-kasim-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ovuc Torpaq', 'bir-ovuc-torpaq-ahmet-hani-65onx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'at oynadı

toz qalxdı

yox oldu atlı birden.

Tozda Ana

tozda göz 

tozda ürek 

tozda söz 

tozda qardaş 

tozda yar 

her ne desem 

tozda var. 

bir ovuc torpağa 

gümanım gelir.

29 september   2000

30 april   2001', 'at oynadı toz qalxdı yox oldu atlı birden. Tozda Ana tozda göz  tozda ürek  tozda söz  tozda qardaş  tozda yar  her ne desem  tozda var.  bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-ovuc-torpaq-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlatma(mektup derken şiir olu)', 'hatirlatma-mektup-derken-siir-olu-abdurrahim-karakoc-1vo6a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mektup derken şiir oldu bak gene

Darılırsan ben ölürüm, unutma...

Taze sarmaşığım, hoyrat bedene...

Sarılırsan ben ölürüm, unutma...

Bir gün güneş olur göle doğarsın

Bir gün yağmur olur yola yağarsın

Bir gün çiçeklerden koku sağarsın

Yorulursan ben ölürüm, unutma...

Kılıç ağzı yoldur, ok ucu meydan

Dikkat et; sen benim canımsın ey can! .

Koyakta kekliksin, kayada ceylan

Vurulursan ben ölürüm, unutma...

“Aşk” denince aklı bırak, deli ol! .

Işık ışık gökten inen dolu ol

Boz-bulanık akan yağmur seli ol

Durulursan ben ölürüm, unutma...

Dinlemek zor, anlamak zor yâr beni

Göreceksen dertte, gamda gör beni

Gönül toprağıma yaptım türbeni

Dirilirsen ben ölürüm, unutma...

(Dosta Doğru)', 'Mektup derken şiir oldu bak gene Darılırsan ben ölürüm, unutma... Taze sarmaşığım, hoyrat bedene... Sarılırsan ben ölürüm, unutma... Bir gün...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hatirlatma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşama Beş Var', 'aksama-bes-var-emin-yavuzyigit-ztip3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gün akşama beş var

Her şey tebessümle bakıyor bana

Ben bu gün çok neşeliyim neşeli

Dokunmayın bana sevdadan ölebilirim

Dokunmayın bana sevdadan ölebilirim...', 'Bu gün akşama beş var Her şey tebessümle bakıyor bana Ben bu gün çok neşeliyim neşeli Dokunmayın bana sevdadan ölebilirim Dokunmayın bana se...', ARRAY['Türk Edebiyatı','Şiir','Emin Yavuzyiğit']::text[], 8.5, '{"poet":"Emin Yavuzyiğit","poet_slug":"emin-yavuzyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aksama-bes-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aylaklığımın Birinci Günü', 'aylakligimin-birinci-gunu-ozgur-kayim-bjbl0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aylaklığımın birinci günü bugün

Boş vaatler dünyasının zamansız ışıklarıyla uyandım, 

Kaynak suların eşsiz temizliğiyle yıkandım, 

Çocuk büyütme enstitüsünden yarım litre süt, 

Şairin dediği gibi “basit yaşayacaksın basit”.

Radikalleştim gazete konusunda da, 

Arka sayfasında bir kayakçının ölümünü yazıyor, 

Daha otuzunda, yüzü çillice ama belli ki sağlıklı

Hem üzüldüm, hem sevindim, 

Üzüldüm, otuz çok, çok erken

Sevindim, kaç kişiye nasip olur ölüm

Hayat sahnesinin ortasında dans ederken.

İlk sayfayı açtım sonra, 

Memleketimden insan manzaraları.

Kırk üç gün sonra çıkarmışlar Macar anne kızın cesetlerini

Metro yüzünden çöken pansiyonun altından, 

Elli yaşlarında bir adam ağlıyor hüngür hüngür 

Etrafına bile bakmadan

Kırk üç gün… devlet eliyle ölülere bile işkence yapılıyor

Göz göre göre

Kırk üç gün… devletin metrosu alenen adam öldürüyor.

Manşetteki haberse daha ilgi çekici, 

Sarıkamış’ta “beşinci sınıf” bir öğrenci

Yapılan yardımların hep zenginlere dağıtıldığını söylediği, 

Hakkını aradağı için, bacakları morarıncaya kadar dayak yiyor

Bu devletin şeref”li” müdüründen, 

Büyük yürekli küçük öğrencinin cesaret dolu 

Gözlerini hayal ediyorum

Yerimden kalkıp, bu memlekette halâ iş var diyorum

Aylaklığımın birinci günü bugün, 

Aylaklığımı seviyorum…', 'Aylaklığımın birinci günü bugün Boş vaatler dünyasının zamansız ışıklarıyla uyandım,  Kaynak suların eşsiz temizliğiyle yıkandım,  Çocuk büy...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kayım']::text[], 8.5, '{"poet":"Özgür Kayım","poet_slug":"ozgur-kayim","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aylakligimin-birinci-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-sair-mahcubat-pk75a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'icli gonul nice sızılar barindirir icinde

bir dertli bakis duvarlari deler degince

bir hikaye sarar insani, uzun ve olabildigince

arda kalan bahtin renkleri, derin ve ince

usulca bir ciglik yukselir, dilekler yuce

manasi cok uzun bir anlatim, ama tek hece

caresiz adimlarla yutkunmalar alir birde

yalvaris gecesi olur her yer, hâl acizce

masaüstü düşünceler gözde gezince

şayia sesler girer beyne sinsice

bir intihar çağrısı kulağı delince

son için sebep aranmaz artık, bence....', 'icli gonul nice sızılar barindirir icinde bir dertli bakis duvarlari deler degince bir hikaye sarar insani, uzun ve olabildigince arda kalan...', ARRAY['Türk Edebiyatı','Şiir','Şair Mahcubat']::text[], 8.5, '{"poet":"Şair Mahcubat","poet_slug":"sair-mahcubat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-nazim-hikmet-ran-yc8tg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kulede bir başına bir adam oturur

önünde milyonlarca düğme var

düğmenin birine bastı mıydı

bizlerden biri ya kolunu kaldırır

                             ya adam öldürür

                             ya çişini eder

tereci tere satar 

biz vatan satarız

biz kurşuna dizeriz düşünceyi
..........
..........', 'kulede bir başına bir adam oturur önünde milyonlarca düğme var düğmenin birine bastı mıydı bizlerden biri ya kolunu kaldırır                ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biz-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tadı Yok', 'tadi-yok-ozan-arif-azcwb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim için artık yalan dünyada

Ekmeğin tadı yok aşın tadı yok.

Alparslan Türkeşsiz kalan dünyada

Baharın tadı yok kışın tadı tok.

Onun sağlığında gezerken yurdu

Yüreğim bambaşka şevkle vururdu

O şevki içime o doldururdu

O gitti toprağın taşın tadı yok.

Yok çünkü yerinden oynamış taşlar, 

Vefa yok haksızlık çok arkadaşlar

Kuru olmadan da yanıyor yaşlar

Kurunun tadı yok yaşın tadı yok.

O gitti gideli yollar bir tuhaf

Fikirler bir tuhaf diller bir tuhaf

Edirne’den Van’a iller bir tuhaf

Muğla’nın tadı yok Muş’un tadı yok.

Yok gardaş yok artık her yere git bak

Ayaklar baş olmuş başlar da ayak

Konuşursan ihraç, susarsan dayak

Ayağın tadı yok başın tadı yok.

Baskın yemiş gibi yiğitler baskın

Kimi ele kimi bahtına küskün.

Bıçaklar açmıyor ağızlar suskun

Ağızın tadı yok dişin tadı yok.

Yaraladı beni yaran dediğim

Unutuldu rehber Ku’ran dediğim

Hatta ‘Kızıl Elma’ ‘Turan’ dediğim

Hayalin tadı yok düşün tadı  yok.

O Türkmen Başbuğ’u olunca mezar

Pazar yeri oldu sevdamız pazar

Yek pare iktidar olsak ne yazar

Dünyayı tuş etsek tuşun tadı yok.

Hesaplar ortaya serilmedikçe

Ve işler ehline verilmedikçe

Bozkurtlar yeniden dirilmedikçe

Arif için artık işin tadı yok.', 'Benim için artık yalan dünyada Ekmeğin tadı yok aşın tadı yok. Alparslan Türkeşsiz kalan dünyada Baharın tadı yok kışın tadı tok. Onun sağlı...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tadi-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz', 'goz-metin-altiok-ve5u2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu bizim dışa dönük gözümüz, 

Bir daldan bir orman çıkaran

Usumuza her zaman.

Şu bizim bulup seçen gözümüz, 

bir kuşu yüzlerce yapan.

Bir kanatla göğünü durmadan kımıldatan, 

Bak çapak tutmuş sevgiyi çoğaltmaktan.

Şu bizim çok arayan gözümüz, 

Baktığında karıştıran kendini.

Aldatılan, yadsınan, başımıza vurulan.

Bir yas çıkarır ortaya yaşamasından; 

Suskun ve gizemli, 

Küflü bir kitap gibi yazısı okunamayan', 'Şu bizim dışa dönük gözümüz,  Bir daldan bir orman çıkaran Usumuza her zaman. Şu bizim bulup seçen gözümüz,  bir kuşu yüzlerce yapan. Bir ka...', ARRAY['Türk Edebiyatı','Şiir','Metin Altıok']::text[], 8.5, '{"poet":"Metin Altıok","poet_slug":"metin-altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/goz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sor', 'bana-sor-ozan-arif-vx9vt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başbuğum bak yine başına geldim.

Bakıyorum ama sen gel bana sor.

Dert dökmeye mezar taşına geldim.

Döküyorum ama sen gel bana sor.

Belki de derdimi dökmem boşuna, 

Duymazsın duysan da gitmez hoşuna

Öyle bir çile ki düşman başına

Çekiyorum ama sen gel bana sor.

Beni bu çileye salanlar saldı, 

Sen gittin her şeyin içi boşaldı

Kala kala senden bir rozet kaldı

Takıyorum ama sen gel bana sor.

Sevdamızın günahı ne suçu ne? 

Bu sevda layık mı gönül göçüne? 

Arada sırada halkın içine

Çıkıyorum ama sen gel bana sor.

Halk eskisi gibi önüme çıkıp

Hal hatır etmiyor elimi sıkıp

Sebebini halkın gözüne bakıp

Okuyorum ama sen gel bana sor.

Halkı bırak halkı öz kardeşimi

İknadan acizim evde eşimi

‘La Havle’ çekerek her gün dişimi

Sıkıyorum ama sen gel bana sor.

Çünkü iktidarda bütün varımı

Yitirdim siyasi itibarımı

Söylenen sözlere kulaklarımı

Tıkıyorum ama sen gel bana sor.

Sen yoksun başını tuttular suyun 

Oyun oynuyorlar başında oyun

Birlik için birlik bunlara boyun

Büküyorum ama sen gel bana sor.

Arif’im yıkılmış şehir gibiyim

Tadım yok tuzum yok zehir gibiyim.

Yatağına küskün nehir gibiyim

Akıyorum ama sen gel bana sor.', 'Başbuğum bak yine başına geldim. Bakıyorum ama sen gel bana sor. Dert dökmeye mezar taşına geldim. Döküyorum ama sen gel bana sor. Belki de ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bana-sor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki Sen', 'bendeki-sen-pervin-adalioglu-o59xy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'rüzgâr çıksa çalsa benden sen açlığını

dağıtsa tüm ruhunun melodisini dudaklarımdan alıp

çookk uzaklara, 

aşıklara...

ürperir misin görsen bedenimin süresiz uyanışlarını, 

kalabilir misin içimde kopan aşkının fırtınası arasında, 

bilmem çekebilir misin ruhumdaki özlem dolu ağlamaların sesini

benliğimin sevgi kokan iklimlerinde ''sen'' çırpınışlarını, 

kucaklayabilir misin benimseyebilir misin ben gibi, 

içimde durup durup büyüyen dram kokan bu aşkı izlemeye

dayanabilir misin süregelen

hava, toprak ve suyun buluştuğu mekanda

içimde en tenha en gizli yerde barınabilir misin

aşkımın sonsuzluğunda

sen içimde sen olarak kalabilir misin hep! ..', 'rüzgâr çıksa çalsa benden sen açlığını dağıtsa tüm ruhunun melodisini dudaklarımdan alıp çookk uzaklara,  aşıklara... ürperir misin görsen b...', ARRAY['Türk Edebiyatı','Şiir','Pervin Adalıoğlu']::text[], 8.5, '{"poet":"Pervin Adalıoğlu","poet_slug":"pervin-adalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bendeki-sen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokakların Serserisi', 'sokaklarin-serserisi-pervin-adalioglu-zcqcx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir cigaranın dumanı değildir 

gözlerimi yaşla dolduran

karanlık çökmüş bir yataklı odamda 

seni düşünerek içtiğim cigaraların haddi hesabı yok be güzelim

uzanır yatağıma karanlıkta ihanetini düşünür 

hani: 

yüreğime bir ok gibi fırlattığın ihanetin bakışlarını saplamıştın

bi cigara daha

bir elimde yalnızlığımın arkadaşı cigaram

püfür püfür

sehpanın üzerinde de boş bir şarap şişesi

sen beni ne sandın güzelim

benim kendime olur zarar 

kıyarmıydım ki ben sana benim olsan

ben serserisi olmuşum sokakların

sokaklar benim evim olmuş

sigaralar arkadaşım şaraplar yoldaşım olmuş

senin bir oğlun bir kızın olmuş 

bir dairen olmuş kalöriferli

bir araban olmuş ne çıkar bundan banane güzelim

ben sarhoşluğuma doymam 

yalnızlığıma gam yedirmem 

ben serserisi olmuşum sokakların

sokaklar benim evim olmuş

sigaralar arkadaşım şaraplar yoldaşım olmuş

benimle yaşayan bir sevda varmış

oda ölmüş', 'bir cigaranın dumanı değildir  gözlerimi yaşla dolduran karanlık çökmüş bir yataklı odamda  seni düşünerek içtiğim cigaraların haddi hesabı ...', ARRAY['Türk Edebiyatı','Şiir','Pervin Adalıoğlu']::text[], 8.5, '{"poet":"Pervin Adalıoğlu","poet_slug":"pervin-adalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sokaklarin-serserisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmese de Gözlerim Seni', 'gormese-de-gozlerim-seni-zeki-ergin-3ork4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir el uzandığını fark etsem

görmese de gözlerim seni

bir çorağın içinde olsam da

içimde bir umut ışığı yanabilir

bu yörede

olmadığını bilsem de

bastığın kaldırım taşları

bana yoldaşlık edebilir

bir el uzandığını farketsem

görmese de gözlerim seni

bu kentin mor akşamlarında

şarabıma katık olursun

her yanımı saran

kahır giysilerini

sarmalasam da bedenime

mutluyum diyebilirim gene de

bir el uzandığını fark etsem

görmese de gözlerim seni

_mustafakemalpaşa mayıs1968

_köz yt:1973

_dağlara ver sırtını yt:haz09', 'bir el uzandığını fark etsem görmese de gözlerim seni bir çorağın içinde olsam da içimde bir umut ışığı yanabilir bu yörede olmadığını bilse...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gormese-de-gozlerim-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadım', 'anlamadim-sinan-gungor-usbnp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlamak mümkün değil bu insanları.Kimi ortam yaratmak için yalakalık yapar kimi insanlara hoş görünmek için şarlatanlık yapar.Tanımak acı verir böylelerini acırsın bunlara bazende malzeme olmak yokmu bunlara o daha kötü.Sevemiyorum bunları sevmekte istemiyorum nedeninide bilmiyorum bilmekte istemiyorum.Ama bu kişiliğini kaybetmiş insanların peşinde dolaşan salaklar yokmu bunlar daha kötü.Bugünkü yazıyıda bunlara ayırdık değermiydi onlara ama boş ver.', 'Anlamak mümkün değil bu insanları.Kimi ortam yaratmak için yalakalık yapar kimi insanlara hoş görünmek için şarlatanlık yapar.Tanımak acı ve...', ARRAY['Türk Edebiyatı','Şiir','Sinan Güngör']::text[], 8.5, '{"poet":"Sinan Güngör","poet_slug":"sinan-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/anlamadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrik Şiirler 1', 'devrik-siirler-1-devrik-sair-b7z47', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Devrik Şiirler1 

sana yazıyorum 

en kısa ve en özlü yerindeyim günün

sana yazıyorum devrik bir şiirin ortasındayım

sana yazıyorum 

dört yanımda deniz mavisi', 'Devrik Şiirler1  sana yazıyorum  en kısa ve en özlü yerindeyim günün sana yazıyorum devrik bir şiirin ortasındayım sana yazıyorum  dört yanı...', ARRAY['Türk Edebiyatı','Şiir','Devrik Şair']::text[], 8.5, '{"poet":"Devrik Şair","poet_slug":"devrik-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/devrik-siirler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlmik', 'i-lmik-ozgur-kayim-hm9b3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Varlığın boynuma asılı 

                                     yağlı bir ilmik

Ya sandalyeye basıp tekmeyi

                                     yokluğunla kavrulacağım

Ya da sen vuracaksın sandalyeye

Varlığımı bana bırakıp 

                                     yokluğumla kavrulacaksın.

Özbencilliğe karşı özsencillik...', 'Varlığın boynuma asılı                                       yağlı bir ilmik Ya sandalyeye basıp tekmeyi                                    ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kayım']::text[], 8.5, '{"poet":"Özgür Kayım","poet_slug":"ozgur-kayim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ilmik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-fatih-cinar-oi62e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne bilinir kadrin ne geçer sözün

kocamış kurt olursun itlere doğar gün

yaz mevsimi kar yağar yaprak açar güzün

gözlerinde mazi yanar yaşayamazsın bugün

yürüdüğün ovalar güngelir olur tepe

tohum atarsın ekin vermez sana bağ bahçe

istemesende intizar dökülür ağzından hece hece

fareler terk eder bir sen kalırsın bu batan gemide

gelen gider meydan kalmaz sana

yiğit öldü şan kaldı namert olana

cihanda yoktur sorgu sual sana bana

ibret vardır dört kitapta arif olup anlayana

nehirler akıp gider kelep kelep

hem su verir hem boğar aranmaz hiç sebep

ağaç baki değil meyve dalda durmaz hep

hiç şüphe yok birgün kopacaktır kıyamet

zaman geçer viran olur bu şehir

lokman gelir nafile yaralar derinleşir

vitrine koyup kendini etsende teşir

gelen geçen bakarda yaraları depreşir

garip ankaralı söylerde bir ders alırmı

su üstüne mürekkeple hiç yazı yazılırmı

sultan süleymana kalmadı bu faniye kalırmı

bu sözlerim boşlanıp yabana atılırmı', 'ne bilinir kadrin ne geçer sözün kocamış kurt olursun itlere doğar gün yaz mevsimi kar yağar yaprak açar güzün gözlerinde mazi yanar yaşayam...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ogut-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Denizi', 'olum-denizi-hakan-akyurt-g79ka', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir deniz kıyısında yaşarız gerçekte, 

Ölüm ile yaşam arasındaki bir deniz..

Bazen isteye isteye atlarız bu denize, 

Bazen birileri iter, bazende; 

İstemesekte deniz alır götürür bizi..

Ölüm denizidir bu kıyısında yaşadığımız.

İşte böyle birgün gelirde sevdiğim, 

Ansızın deniz alacak olursa beni, 

Dönmeyecek olsamda bir daha, 

Üzülme ve sakın ağlama..

Bu dünya da ayrı kalacak olsakta, 

Sevgimizle buluşacağız; 

Ölüm denizindeki yuvamızda....', 'Bir deniz kıyısında yaşarız gerçekte,  Ölüm ile yaşam arasındaki bir deniz.. Bazen isteye isteye atlarız bu denize,  Bazen birileri iter, ba...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarımdasın', 'ruyalarimdasin-hakan-akyurt-fmrkc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen benim rüyalarımdasın..

Her gece karşıma çıkan, 

Güzel sesiyle kalbimi çalan, 

Uykulara hasret bırakan, 

Hayallerimdeki meleğimsin...

Sen benim rüyalarımdasın..

Sevgiyi kalbten yaşayan, 

Herşeyiyle bana yaşatan, 

Sabırla usanmadan anlatan, 

Güzel gözlü bebeğimsin...

Sen benim rüyalarımdasın..

Yaşayamayacak olsamda seninle, 

Hissedemeyecek olsamda kalbimde, 

Göremeyecek olsamda gözümle, 

Unutamayacağım sevdiğimsin...', 'Sen benim rüyalarımdasın.. Her gece karşıma çıkan,  Güzel sesiyle kalbimi çalan,  Uykulara hasret bırakan,  Hayallerimdeki meleğimsin... Sen...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruyalarimdasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitermi Böyle', 'bitermi-boyle-fatih-cinar-uvzdr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'duyduklarım gördüklerimden ibaret

düşüncelerim hayalden

sen benim hayalim sadece sen dedim

duy beni be zalim sadece duy dedim

sana adanmış bir ömür bu

ha demeye geçermi söyle

koskoca bir sevda bu

he demeye bitermi böyle

ben yine severim duygularımla

seni yad ederim duyduklarımla

gözlerim bir kapanır seni görürüm

hayalin yetmiyor der dururum

müzik:fatih çınar', 'duyduklarım gördüklerimden ibaret düşüncelerim hayalden sen benim hayalim sadece sen dedim duy beni be zalim sadece duy dedim sana adanmış b...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bitermi-boyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körfez Vapurları', 'korfez-vapurlari-ahmet-aslan-l75h5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirsiniz körfez vapurlarını

Uğradıkları limanlar hep aynı

Hep aynı bağlandıkları kıyılar

Dönüp dururlar yıllarca

Karşıyaka-Pasaport

Alsancak-Konak

Açık denizleri özledikleri belli

Hissederim hissederim de

Öyle bir hüzün kaplar içimi

Ne bileyim

Ne farkım var ki onlardan

Ben de aynı limanlara yanaşırım her gün

Hergün ben de bağlanırım halatlarla kıyılara

Gitmek istesem de gidemem ki 

çok uzaklara

Uğradığım limanlar hep aynı

Hep aynı bağlandığım kıyılar...', 'Bilirsiniz körfez vapurlarını Uğradıkları limanlar hep aynı Hep aynı bağlandıkları kıyılar Dönüp dururlar yıllarca Karşıyaka-Pasaport Alsanc...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aslan']::text[], 8.5, '{"poet":"Ahmet Aslan","poet_slug":"ahmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/korfez-vapurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Kal', 'gitme-kal-fatih-cinar-10kmp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yarın çok geç olacak

sevgilim biliyormusun

yarın gözlerde yaş olacak

sevgilim anlıyormusun

gitme kal de bana

razıyım sonbahara

gitme kal de bana

çevir sensizliğe

giden yolları sana

yarın ikimize

derin yaralar açacak

yıllar geçse bile 

inan kapanmayacak

yarın kötü günler

başlangıcı olacak

takvimler yalnızlık

hesabını tutacak

çıkacağım bir gün sana gelen yollara

geleceğim yanına ömür boyu kalmaya

isterse ölümüm olsun sana gelen yollar

şunu bilki aşkım

ölümüm bile senin yanında başlar

Müzik: Fatih Çınar', 'yarın çok geç olacak sevgilim biliyormusun yarın gözlerde yaş olacak sevgilim anlıyormusun gitme kal de bana razıyım sonbahara gitme kal de ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gitme-kal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Olur', 'gun-olur-fatih-cinar-lpueg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gün olur alır başımı giderim

hatırlamam hatıraları

unuturum senle geçen anları

dönüp bakmam arkama

silerim geçtiğim yolları

gün olur alır başımı giderim

silinir hayalimden senle geçen geceler

damla damla gözyaşına döner

birbir sevdalı seneler

dökülür ağzımdan inan hep ıstırap dolu heceler

gün olur alır başımı giderim

bir sigara yakarım tiren garında

gider bütün efkarım tirenin dumanıyla

gün olur alır başımı giderim

bir yıldız kayar hayatımdan

seninle geçen günler geceler

çıkar hatıralardan

birlikte olduğumuz zamanlar

bir mum ateşiydi zaten yanan

ve deli bir rüzgardı benim sevdam

gün olur alır başımı giderim

giderim sensizliğe

işlerim bir nakış gibi işlerim

sensizliği bütün benliğime

gün olur alır başımı giderim', 'gün olur alır başımı giderim hatırlamam hatıraları unuturum senle geçen anları dönüp bakmam arkama silerim geçtiğim yolları gün olur alır ba...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gun-olur-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanacaksın Leyla', 'yanacaksin-leyla-fatih-cinar-kmc4b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'az koşturmadın beni peşinden

kavruldum senin kor ateşinden

gözlerinden sözlerinden

güzelliğinden sıkıldım ben leyla

bir gün elbet ahım tutacak

yanacaksın sen leyla

yeşil gözlerin kör olacak

tutuşacaksın sen leyla

çaresiz dertlere attın sen beni

yıkık bir virane ettin kalbimi

gözlerini sözlerini

güzelliğini unuttum ben leyla

Müzik: Fatih Çınar', 'az koşturmadın beni peşinden kavruldum senin kor ateşinden gözlerinden sözlerinden güzelliğinden sıkıldım ben leyla bir gün elbet ahım tutac...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanacaksin-leyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-fatih-cinar-2e3y3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geçen yılın gülleri var vazomda

mutluluğu hapsetmiş resimler duvarda

kulağımda senin çalmadığın kapının zili

gönlümde açtığın yaranın kan seli

bir parçamı alıp götürdün giderken 

niyeydi bu ayrılık deli gibi severken

seni benden fazla sevenmi vardı

kimbilir kalbin hangi namerde kandı

nerede senle geçen güzel günler

şimdi ağlar herzaman gülen gözler

sana dair hatıralar saçılmış odaya

kederler göz dikmiş gönlümdeki umuda', 'geçen yılın gülleri var vazomda mutluluğu hapsetmiş resimler duvarda kulağımda senin çalmadığın kapının zili gönlümde açtığın yaranın kan se...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/giderken-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadığımsın', 'anlayamadigimsin-osman-turkmen-f0vqe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazları çok soğuk, kışları sıcak, 

Gündüzleri ay, geceleri güneş, 

Anlayamadığım bu nasıl bir aşk, 

Bir göklerde bir de toprak altında.

Mevsimler şaşırmış, yıllar uzamış, 

Saat ki zamanın farkında değil, 

Anlayamadım, bu bozuk dengeyi, 

Aylar ring yapıyor, peşimde sanki.

Beşinci mevsim bu, on üçüncü ay, 

Otuz ikinci gün, kırkıncı saat, 

Anlayamadım nasıl dönüyor zaman, 

Koskoca boşluktu geriye kalan.', 'Yazları çok soğuk, kışları sıcak,  Gündüzleri ay, geceleri güneş,  Anlayamadığım bu nasıl bir aşk,  Bir göklerde bir de toprak altında. Mevs...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlayamadigimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Uğruna? ..', 'ne-ugruna-gulay-kaygusuz-ntjzo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çabuk pes  ettik, 

Ağacın yere  düşen gölgesi gibi 

Güneşi  bekledin  görünmek için

Serininde  oturamadan  akşamı ettik.

Daha vakit erkendi, 

Çabuk pes ettik.

Papatyaları  yolamadık seviyor sevmiyor diye

Birbirimizin  gözlerindeki parlaklığı görmeden, 

Kapattık  gözlerimizi.

Tutamadan yumduk ellerimizi

Çabuk pes ettik.

Ne uğruna? 

Ben  adını koymadım, çözemedim sevgili, 

Sen de bir kere hadi.

(İstanbul  08/04/2002)', 'Çabuk pes  ettik,  Ağacın yere  düşen gölgesi gibi  Güneşi  bekledin  görünmek için Serininde  oturamadan  akşamı ettik. Daha vakit erkendi,...', ARRAY['Türk Edebiyatı','Şiir','Gülay Kaygusuz']::text[], 8.5, '{"poet":"Gülay Kaygusuz","poet_slug":"gulay-kaygusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim', 'benim-sair-mahcubat-3b5ry', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sükûtun adı olsa ben derdim

kelamın her halini ben yêrdim

dillerin yoluna kül serdim

çığlığım bile sükût oldu benim

nadan akıllarla muhatap gezdim

acı aşkımın demlerinden bezdim

yâr''e yakındım, sarhoştum, sezdim

sarhoşluğumda kısa oldu benim

üç anlatım vardı gönlümde, bildim

bir hâl, bir yâr, bir cân idim

al gözümden zehir yaşlar sildim

dertli ağlamam çok oldu benim

sevda duruşlarımla umut bekledim

feleğe sitem mektubum açık verdim

ver bana gönül dermanım derdim

karşılık almadığım çok oldu benim', 'sükûtun adı olsa ben derdim kelamın her halini ben yêrdim dillerin yoluna kül serdim çığlığım bile sükût oldu benim nadan akıllarla muhatap ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mahcubat']::text[], 8.5, '{"poet":"Şair Mahcubat","poet_slug":"sair-mahcubat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Sandığı', 'dost-sandigi-sair-mahcubat-3uluc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir dost sandığı geldi önüme

içinden selam ve zehir çıktı

selamda dosttandı zehirde

kelamla aldım onları sineme kattım

dinledim ızdırabını, bekledim 

cevap istedim dertlerinden

kıymak için muhabbetin nikahını 

ayrılık dedi uzak, hasret dedi zehir

bekle dedi, sabır dedi selam 

bir buse ile karşılık verdim

selamı aldım zehiri içtim

kalan sadece içli bir bakış oldu

we selam oldu

selam we selam', 'bir dost sandığı geldi önüme içinden selam ve zehir çıktı selamda dosttandı zehirde kelamla aldım onları sineme kattım dinledim ızdırabını, ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mahcubat']::text[], 8.5, '{"poet":"Şair Mahcubat","poet_slug":"sair-mahcubat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dost-sandigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın', 'yarin-sair-mahcubat-mn5y3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'günler geçmekte gül seraplarla heran

değişik nazarlar serpiyor içime sevdan

hangi şekliyle saklasam çelişkilerimi

hepsi farklı, hepsi bir güzel duran

bir sesle seslensem, dillerim ozan

sana bir içli bakış atsam, gözlerim suzan

senin için endişelerimi nerde saklasam

endişem gözümde yaş, düşmek üzere her an

geceler boyu düşüncelerimi saran

ne çok yaşadım sende seni bir an 

demlerin hepsi geride kalmadı belki

hayal içinde düşlerin hepsi yalan

sen bir isim sen bir sevda, bir heyecan

bir ayrılış vaktidir kopmak üzere olan

gelişin gerçek olacak diyorum yarın

ancak selam oldu geriye baki kalan

ama yarın we sewdam we..........', 'günler geçmekte gül seraplarla heran değişik nazarlar serpiyor içime sevdan hangi şekliyle saklasam çelişkilerimi hepsi farklı, hepsi bir gü...', ARRAY['Türk Edebiyatı','Şiir','Şair Mahcubat']::text[], 8.5, '{"poet":"Şair Mahcubat","poet_slug":"sair-mahcubat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kız Tanıdım', 'bir-kiz-tanidim-onur-uysal-ihjxp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kız tanıdım, yıllar öncesinde

Bir kız ki, mert dersen mert

Yürek desen büyük sevdalara hasret 

Yine de bir o kadar emin

tek başına olacağına ölene değin

Böyle dedi otururken bir parkta, 

Sadece iki sene geçti

	masaya oturmak için nikahta.

Bir kız tanıdım, tanıyorum sanırım

En büyük dönüşlerimi onunla yaşadım

Yaşamı sindirirken o ağır ağır

Çevresinde dolaşan bir tekne gibi şen yaşadım.

O ararken kendini dev okyanuslarda

küçük heyecanlar sadece benim sandım.

Şimdi o yudumlarken doyasıya aşkın pınarından

Ben ağlıyorum yiten bir sevdanın arkasından.

Bir kız tanıdım, yanılmış olamam

Gözlerine bakıp gerçeği soramam

Bir kız ki, ne olursa olsun kalacak

		sağduyum olarak

Sonsuza dek bir direk yaslanılacak

Ve çok değil birkaç saat sonra bunu düşündükten

Buz gibi bir veda geldi hiç gözyaşı dökmeden

O kız şimdi bana yabancı, yaşıyor uzaklarda

Bana kalan birkaç resim duvarımda

Biter diyor ya usta ölüm acısı bile yirminci yüzyılda

Silinmiyor gülüm, silinmiyor aklımdan

on yılın her dakikası hatırımda...', 'Bir kız tanıdım, yıllar öncesinde Bir kız ki, mert dersen mert Yürek desen büyük sevdalara hasret  Yine de bir o kadar emin tek başına olaca...', ARRAY['Türk Edebiyatı','Şiir','Onur Uysal']::text[], 8.5, '{"poet":"Onur Uysal","poet_slug":"onur-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-kiz-tanidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-halil-yanar-jw1pc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ıhlamur bardağını yana itince

başını kaldırınca ıslak saç kokusundan

olgun bir kayısının içidir

sende senin gözlerin

dün akşam yere serili gölgen

bu akşamki gölgenle üst üste

gene dönmüş dünden 

nasıl dönmüş se

mutluluğun sana verdiği

pırıltıyı yaşıyor

bir açılıp bir kapanıyor kirpiklerin

bilmem alınırmısın söylesem

geride sadece çirkin bir yüzden başka kalan güzelliğin', 'ıhlamur bardağını yana itince başını kaldırınca ıslak saç kokusundan olgun bir kayısının içidir sende senin gözlerin dün akşam yere serili g...', ARRAY['Türk Edebiyatı','Şiir','Halil Yanar']::text[], 8.5, '{"poet":"Halil Yanar","poet_slug":"halil-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kardelen-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye İşçi Sınıfına Selam Olsun', 'turkiye-i-sci-sinifina-selam-olsun-huseyin-cayikli-w5w6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uyanın yoldaslar

gece bizi bekliyor ve sonrası aydınlık

turk işçi sınıfına selam olsun

selam yerin dibindeki madenciye 

kömürü kardeşi gibi çıkarana 

selam olsun...

ey sen büyük petrolcü

fışkıran cevhere ve o enerjiye 

o mükemmel maddeye

yani herşeyinle sana

selam olsun

bu gece uykuyu biz öldüreceğiz

devrimimizle yüreklerimizle...

bu gece bizim ve aydınlıklarımız...

selam Turkiyemin rengarenk gökkkuşağı işçilerine...

emekçime

ey sen

demiri dizginleyen ona hayat veren 

sanatını işleyen ve onu döven 

sana çelikçilere selam olsun

sen ey sen

uygarlığın hamurunu yoğuran

bir ulusun özgürlüğünün simgesi

sen grevlerinle hakkıkını arayan 

kağıtçılara selam olsun

Türkiyemin aydınlığı geleceği öğrenciler

geleceğin işçileri

Türkiye İşçi Sınıfına Selam Olsun...', 'uyanın yoldaslar gece bizi bekliyor ve sonrası aydınlık turk işçi sınıfına selam olsun selam yerin dibindeki madenciye  kömürü kardeşi gibi ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/turkiye-isci-sinifina-selam-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar Uzak', 'yollar-uzak-ergun-yildirim-47629', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yollar uzak gelemedim

Muradıma eremedim

Tutunacak dalım sendin

Kıymetini bilemedim

Gözlerime bir baktın

Yaktın ah beni yaktın

Ben sana ne yaptımki

Beni yalnız bıraktın.

Bana el  gözüyle bakma

Gurbet ellerde bırakma

Ayrılık canıma yetti

Birde sen gönlümü yakma

Gözlerime bir baktın

yaktın ah beni yaktın

Ben sana ne yaptımki

beni öksüz, yalnız bıraktın.', 'Yollar uzak gelemedim Muradıma eremedim Tutunacak dalım sendin Kıymetini bilemedim Gözlerime bir baktın Yaktın ah beni yaktın Ben sana ne ya...', ARRAY['Türk Edebiyatı','Şiir','Ergün Yıldırım']::text[], 8.5, '{"poet":"Ergün Yıldırım","poet_slug":"ergun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yollar-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaçları Kesmeyin', 'agaclari-kesmeyin-can-yucel-8vzxw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düş bir yaş dalından düşerse

Nereye düşer hiç düşündünüz mü? 

Yerde bir iz kalmayacak mı izdüşüm? 

Düşen yaş dalından düşünce

Gözlerinizdedir pınarı

Bir yaş bir daldan düşünce

Kökündedir yaşı

Bir yaş düşer bir daldan

Hepimizin ölen arkadaşı

Ve çok eskilere dair bir düşünce', 'Düş bir yaş dalından düşerse Nereye düşer hiç düşündünüz mü?  Yerde bir iz kalmayacak mı izdüşüm?  Düşen yaş dalından düşünce Gözlerinizdedi...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/agaclari-kesmeyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-can-yucel-5a3e9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün gece seyrimde gördüm cerenim.

Kızlar ne kadar çok seviyorlarmış ki seni

Mosmor olmuş gülyazısı bedenin

Mosmor olmuş gülyazısı bedenin

Düşmüş sanki erguvanlar içinde

En genç burcu yıldızdan bir kalenin

En genç burcu yıldızdan bir kalenin

Uçmuş sanki uçsuz bir uçuruma

Gökyüzünün çakır gözlerinden

Gökyüzünün çakır gözlerinden 

Düşmüş bir damla, bir deniz feneri

Işınlarıyla şile bezlerinin

Güdüyor çobansız kalmış tekneleri', 'Dün gece seyrimde gördüm cerenim. Kızlar ne kadar çok seviyorlarmış ki seni Mosmor olmuş gülyazısı bedenin Mosmor olmuş gülyazısı bedenin Dü...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/agit-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslandan Al Haberi', 'aslandan-al-haberi-can-yucel-g3k5u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Romalılar aslanlara atarlarmış Hıristiyanları.

O Hıristiyanlar ki

Romalılardan daha dürüst, daha düzgün, daha uygar bir 

                                                                            düzene

inanmaktan başka suçları yoktu...

Romalılar oyalamak için işsiz yığınlarını

O zamanın gazetesi

Ve Hürriyet’i olan Coliseum stadyomunda

Aslanlara atarlarmış sen gibi ben gibi

Mehmet Turgut gibi insanları

O Mehmet Turgut ki

İşsiz olmaktan başka suçu yoktu

İşsiz parasız evsiz-barksız

Ve aslanın kafesine girdiğini farketmeyecek 

                                  kadar uykusuz...

O Mehmet Turgut ki

Libya’ya gitmek için sıra bekleyen bir

                                  Kunuri Aslanıydı

Adana’nın Girne yolunda bir lunaparkta

Buldular parçalanmış vücudunu...

Sade Adana’nın Girne yolunda değil

Roma’da da böyle

Oyalamak için işsiz yığınlarını

Ve belki de azalsın diye işsizlerin sayısı

O zamanın gazetesi

Ve Hürriyet’i olan Coliseum stadyomunda

Aslanlara atarlardı sen gibi ben gibi

Mehmet Turgut gibi insanları...

Ama Ali adındaki

O kendi de müebbete mahkum aslan

Aslanlar akıllanıyorlar mı nedir

Yemedi kardeşim yemedi

Kore Gazisi Mehmet Turgut’un göğsündeki

                                   Silver Star nişanını!', 'Romalılar aslanlara atarlarmış Hıristiyanları. O Hıristiyanlar ki Romalılardan daha dürüst, daha düzgün, daha uygar bir                     ...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/aslandan-al-haberi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Çocuğu', 'ask-cocugu-can-yucel-xbyqk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pencerelerin kenarından

Sarkmış tül perdeleri

Pembe Evin

Uçup uçup yüz sürüyorlar

Karşı tepedeki manastırın selvilerine

Rüzgârla eğilip doğruldukça

Sardunyalar, biberiyeler, 

Hiç korkma

Karada ölüm yok oğlum sana bugün

Leylekler daldı birden göğün acentasına

Gidip-gelme almak üzere Güneye hicret

Sen de gel diyorlar kanatlarıyla, 

El sallıyorum ben de yattığım yerden

Leyleklere Leylim-Leylim

Diye diye 

Güneşle karışık bir esinti geçiyor şakağımdan

Uzatıyorum elimi denizden yeni çıkmış senin serinliğine, 

Göğsümün, karnımın, kasıklarımın, bacaklarımın

Tüyleri kamaşıyor sevinçten

Uyanıyoruz sonra

Dizine yatırıp beni çingene benlerimi sıkıyorsun

Gümüşlü zurnası dikiliyor havaya çeribaşının

Işıklar bir bahriye çiftetellisi çalıyor yüzümde

Hay allah

Yine tutuldum galiba

Derken bir aşk çocuğu doğuyor

Çırpınan denizin karnından

Bu şiir

Ağlarken gülüyor

Ve ağlıyor gülerek

Tuzlu damlalarıyla güneşin, 

Sözcükler yanıp yanıp sönerken

Körpecik teninde

Uzaylardan aparttığım yıldız bitleriyle.', 'Pencerelerin kenarından Sarkmış tül perdeleri Pembe Evin Uçup uçup yüz sürüyorlar Karşı tepedeki manastırın selvilerine Rüzgârla eğilip doğr...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ask-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aygün Uğurlar İçin', 'aygun-ugurlar-i-cin-can-yucel-tukx7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne nimetleri var şu dünyanın

Ekmek peynir zeytin yemiş....

Bir nimeti daha var dünyanın: 

İnandıkları uğruna açlıktan ölmek.', 'Ne nimetleri var şu dünyanın Ekmek peynir zeytin yemiş.... Bir nimeti daha var dünyanın:  İnandıkları uğruna açlıktan ölmek....', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aygun-ugurlar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharla Ölüm Konuşmaları', 'baharla-olum-konusmalari-can-yucel-etd9w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I

Memelerim koparıyor

Yüzyıl süren bir yalnızlık

                           dile gelmişçesine

Nasıl nasıl bir sevinç yarabbi!

Ve ağrıya

        ağrıya tabi,

                ağraya

                    ağraya ağbi...

Nakkaş Tepe de ancak

                        bezmimize böyle gelmiştir

Gelincikleri ve Nazım Hikmet’leriyle

Yerbilimsel bir hapisten sonra

II

İçimdeki karanlığı patlatacağım

Zifiri bir su akacak

               kamışımdan toprağa

Bir kedi yavrulayacak

                       köpek dişli bir kedi

Ve böğürtlenler köpürecek ağzından

Yedikçe

          kendi

                 kendini

                        mayhoş

Ya da Posta Nazırı dedemden kalma

Mors’un en morundan bir karga 

Konacak karşıki direğin doruğuna

Düşmanlarım öyle doldurmuşlar ki onu

Ne kadar taşlasan boş

                    oynamıyor yerinden

Ben kargadan korkmam ama

                      bunun gözleri baykuş

Ve tüyleri güngörmedik deniz dipleri kadar ıslak

Ve ötüyor

        ötüyor

             ötecek

Beni ışığa bağlayan

               (Bağlayın beni ışığa!

                Gerin telleri gerin!) 

                beni  ışığa bağlayan

                             o gelin telleri

                             o gelin telleri

                                  kopuncaya dek...

Akpembe bahar yelkenleriyle

Güneşin rüzgarına gerilmiş

                           bir badem ağacı gibi...

İçimdeki karanlığı patlatacağım

Ve beynimin en ölümcül yaşlarıyla

                                        ağlaya

                                             ağlaya

Yepyeni bir insan

                pırıl pırıl bir can

                                 bitecek toprağa... 

III

İki çöpçü geliyordu karşıdan.

Biri

     (Aynen Selahattin-i Eyyubi Haçlılar

     Seferinden, sanırsın, pos bıyıklarıyla

     Tarihin, süpürmeye gelmiş Prens Adalarını) 

Öbürüne

     (Marmara’yı bizim Yaşar Küklopsunun o

     Anavavza gözüyle dünyanın en güzel

     atlarının neredeyse ineceği e biraz

     genişçe bir çakır su gibi görüyordu,

     eminim) 

Eyitti kim:

     Halk Partisi’nin solunda bir parti olsa

     Hiç dinlemez oyumu ona veririm

IV

Sevda Tepesinde  geçen gün

Karşıki masanın altında

İki tane tavuk gördüm

Toprakla yıkanıyorlardı

Eşeledikleri çukurda

İnsanlar için de belki ölüm

Toprakla bi tür

Yıkanmaktır diye düşündüm

V

Üşüyor mu deniz

                üstüne boşandıkça yağmur?

Ondan mı dersin

                tüyleri böyle ürperiyor?

Ben de gidersem bi gün bu biçim bi sağnakta

Alı al moru mor bir sandal gibi acaba

Yıllar sonra yılmayıp yine

Çarpar mı yüreğim yurdumun sahillerine?

VI

Buket diye bahçeli bir meyhane vardı Yenişehir’de

Yıkıldı çoktan GİMA var şimdi yerinde

Kenarı küpelerle çevrili o küçücük havuzun

Yamacında bir masa

Cahit Ağ’beyle otururduk yaz gecelerinde

Fıskiyenin serpintisiyle sırılsıklamdı muşamba

Zaten Cahit’in gözleri daim yaşlı

“Şunu siliver! ” derdi garsona

“Şu muşambayı siliver, mirim! ”

Ne Cahit kaldı, ne Buket, ne fıskiye

Yine de bu bahar öğlesinde

Fıskiyenin üstündeki o kırmızı top gibi

-İsterse kalpten olsun, isterse-

Hop hop ediyor ya yüreğim bi düziye

VII

Ruhum sıkıldıkça, ruhum,

Mızrapsız bir tambur gibi

Apayrı bir hava çalıyor vücudum

Ruhum sıkıldıkça ruhum,

Senden ayrı, kendimden ve kentten ayrı

Apayrı bir hava çalıyor vücudum

Kalk gidelim, kalk gidelim başka yere!

Başka yere, başka yere, başka yere!

Ruhum sıkıldıkça, ruhum,

Cemil Beysiz bir tambur gibi

Kendi kendini çalıyor vücudum

VIII

Yalıların surları boyunca giderken Kanlıca’da

Duvarda bir gedik ilişti gözüme

Uydurdum gözümü deliğe:

Bir bahçe

Bahçe değil bir havuz

Havuz değil bir bahçe

Üstü nilüfer kesmiş silme

O nefti yapraklarıyla gelmiş

O aksarı çiçeğiyle

Ne hevesle gelmiş kim bilir bu güzelliğe!

İnsanoğlu beni görsün diye mi?

Bahçede oysa

        Bahçedeki bir havuz

Bir havuz ki bir bahçe

Ne in var ne cin ne bey ne ağa

Surları da çekmişler dört bir yanına

Bizler de varmayalım diye bu uçmağa

Sade bir garibim yavru kurbağa

Serilmiş o ortası çukur

O sal gibi yaprağa

Yarı suyun içinde

Yarı yansımış ışığa

Pırıla pırıl yeşile yeşil

Rezil mi rezil

Başladı birden haykırmağa

Başladı inin cinin ağanın beyin

Ne kendi görüp ne kimseye gösterdiği

Çevresine bizler görmeyelim diye

Surlar çektiği

O kimsesiz güzele türkü yakmağa

Şairim ben

Benim işte o kurbağa

IX

Hep ölümü çalacak değil a Zangoç

Bu da

Sema’yla Asaf’ın kızına

Hoşgeldin demek için

Oysa 

Ne kadar

Ne kadar

Ne kadar yalnız

Sanıyordum kendimi demin

X

Atkestanelerini geçen süvari ışıklar

Er-erken kaldırmış hanımellerini

                             tühallah üşüyecekler!

Ve zeytinler eski Rum tenteneleriyle

Esen yel!

Esen yel!

Kim gördü böyle gül yiyen horoz

Tanyeri kokuyor sesi...

Yuvarlandıkça sanki bayırdan aşağı

                    hapiste dolmuş bir şarap şişesi

Öbür horozlar da ayaklanıyor

                     merdiven nakışlı ibikleriyle

Ve balkonlardan sarkarken

            düşleri bebelerin

                      bir albayrak yarışı gibi

Horozlar nev-icad ediyorlar denizi

Hırsızlar!

Hırsızlar!

Ve deniz

          levent gölgeleriyle Turgut Reis’in

Bütün bu dizelerden alınıyor

Bir ala

       bir mora  kesiyor yüzü

Esen yel!

Esen yel!

Bu sabah 

          bir firardır

                kan-davasından bir çocuk

Kuşluk vaktine kalmadan önce

Güneşin kurşunlarıyla vurulacak

Ve akşamladı mıydı çamlar

                             ve karardı mıydı

Tepelerde

Tepelerde

Öyle güzel ki esen yel

Esen yel!

Esen yel!

Bu sabah 

         ve bu bahar

              bir firardır

Baruta koşan bir fitil

İfil

İfil

Öyle güzel ki esen yel!

Esen yel!

Esen yel!

Öyle güzel 

Öyle güzel ki

Esmese de

Esmese de

Güzel

XI

İçimden bir his bırakmıyor  beni ölmeceye.

İçimden bir his.

Bir his ki

Çapraz oturmuş denizin kıyısına

Taş 

Taş

Taş

Derken bir GÜNEŞ!

Tıpkı Üsküdarda’ki

Şemsi Paşa Camisi gibi.

Sen iskeletlerle değil diyor bana

Sen iskelelerle kuracaksın cesedini

Ve öyle köpeksin ki sen

Öldükten sonra bile

Yılmaz’ın UMUDundaki 

Paytonların ardından

Koşacaksın hep

Geleceğe

Çın

Çın

Çın

Ve karnımın gevşemesine karşın

Taş..larımdaki tarçın

Bırakmıyor beni ölmeceye

Evet diyemiyorum

Diyemiyorum ki evet

O hayırlı

O hayırlı geceye

XII

Ben de

    Boğaziçi de bu bahar

Mavi sakalına erguvanlar takmış

Sarhoş bir İskele Babası kadar

Hem delikanlı

              hem deliler gibi ihtiyar', 'I Memelerim koparıyor Yüzyıl süren bir yalnızlık                            dile gelmişçesine Nasıl nasıl bir sevinç yarabbi! Ve ağrıya     ...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":244,"source_url":"https://www.antoloji.com/baharla-olum-konusmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış İçin', 'baris-i-cin-can-yucel-6zaa7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözleri görmeyen Eşber, 

Dünyayla barışık

Gözleri açıklar

Dünyaya kapalı, 

Yağmurdereli`yle birlikte

Savaş için, Rusça niyet

Yani hayır, 

Yağmurdereli`yle birlikte

Barış için döğüşelim, 

Dereler gibi akacak

Güzelim yağmur

Rahmet gelecek dünyaya

Kör gözlerimizden akan

Barış gelecek dünyaya

Barış için döğüşelim', 'Gözleri görmeyen Eşber,  Dünyayla barışık Gözleri açıklar Dünyaya kapalı,  Yağmurdereli`yle birlikte Savaş için, Rusça niyet Yani hayır,  Ya...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/baris-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlık', 'bayramlik-can-yucel-ejs0v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Koyunlar keçiler ve koçlar için

Ne kadar bayramsa Kurban Bayramı

Bu barış var ya, bu barış

Cephedekiler için o kadar barış', 'Koyunlar keçiler ve koçlar için Ne kadar bayramsa Kurban Bayramı Bu barış var ya, bu barış Cephedekiler için o kadar barış...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bayramlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden De Koyu Mai Bir Blues', 'benden-de-koyu-mai-bir-blues-can-yucel-vpryb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senlen raks rakına kalktıkta

Başım ayaklarınla

Ayaklarım başınla beraber, 

Ve oran orama değdikçe, 

Evler boşalıyor

Sokaklar boşalıyor

Bahçeler masalar boşalıyordu

Ben boşalıyordum, 

Bizden gayrı kalan

Bi tek rüzgar vardı

Yaprakları üfleyen rüzgar…

Senden ayrılınca anımsadım

Dünyanın bu kadar kalabalık olduğunu…', 'Senlen raks rakına kalktıkta Başım ayaklarınla Ayaklarım başınla beraber,  Ve oran orama değdikçe,  Evler boşalıyor Sokaklar boşalıyor Bahçe...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/benden-de-koyu-mai-bir-blues-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benzetmeyi Benzetme', 'benzetmeyi-benzetme-can-yucel-txf7r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Susurluk” ismi su sığırından geliyor

“Manda” demek yani

3 Kasım 1996`da

Susurluk yolunda

O iblis Mercedes`in

Masum kamyona çarpmasıyla

Gazi tarafından vaktiyle

Vaktinde sittir edilip de

Sonradan harimimize

Sinsi sinsi sokulan

Manda var ya

İşte o MANDA göle sıçtı', '“Susurluk” ismi su sığırından geliyor “Manda” demek yani 3 Kasım 1996`da Susurluk yolunda O iblis Mercedes`in Masum kamyona çarpmasıyla Gazi...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benzetmeyi-benzetme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bereket Versin', 'bereket-versin-can-yucel-1gc3j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşama bir gitardır

Tellerine vurdukça yediveren

Güneş nasıl doğarsa

Ve yeşil ne kadar solaksa

Saksofon ne kadar benziyorsa asma kabaklarına

Bir sebzevat kokusu sarıyor ortalığı 

Sanki sırık tomatları biz kızardık diyorlar

Santana çaldıkça

Kurbağalar ötüyor tosbağalar yürüyor

Beni bir bostana gömün

Gübre olmak istiyorum', 'Yaşama bir gitardır Tellerine vurdukça yediveren Güneş nasıl doğarsa Ve yeşil ne kadar solaksa Saksofon ne kadar benziyorsa asma kabaklarına...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bereket-versin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Koşu', 'bi-kosu-can-yucel-vd9eo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğdum doğalı yürüyordum

Adım adım ölüme doğru

Ama şimdi dışarda evvel-bahar

Çiçeğe durmuş badem ağaçları

İçerde masanın üstüne eğilmiş dalgın başım

Sırılsıklam yeleleriyle

Doludizgin gidiyorum gayrı', 'Doğdum doğalı yürüyordum Adım adım ölüme doğru Ama şimdi dışarda evvel-bahar Çiçeğe durmuş badem ağaçları İçerde masanın üstüne eğilmiş dalg...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bi-kosu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivas', 'sivas-ergun-yildirim-sv37v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sivas yolları uzun ve taşlı

Kızıldağ karlı ve yağışlı

Sevdiğim nazlı yarim, uzun siyah saçlı

Sevme gönül sevme sende yanarsın

Gönül kapılmış sele

Akıp gidiyor ırmak ve dere

Sevdiğim nazlı yarim gitmiş gurbet ele

Sevme gönül sevme sende yanarsın

Gönül ferman dinlemez

Bülbül ile gül birleşmez

Nazlı yarim bana gelmez

Sevme gönül sevme sende yanarsın', 'Sivas yolları uzun ve taşlı Kızıldağ karlı ve yağışlı Sevdiğim nazlı yarim, uzun siyah saçlı Sevme gönül sevme sende yanarsın Gönül kapılmış...', ARRAY['Türk Edebiyatı','Şiir','Ergün Yıldırım']::text[], 8.5, '{"poet":"Ergün Yıldırım","poet_slug":"ergun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sivas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gidince', 'sen-gidince-rifat-ilgaz-0m3cp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gidiyorsun ya işine yetişmek için, 

Saçlarını, gözlerini, ellerini

Neyin varsa toplayıp gidiyorsun ya, 

Her seferinde birşey unutuyorsun, sıcak, 

Termometrede yükselen çizgi çizgi.

Kimbilir nerelerde soğuyorsun...

Senin gözbebeklerin var ya, kadın kadın gülen

İnsan insan bakan gözbebeklerin, 

Beni tutsa tutsa gözlerin tutar ayakta, 

Beni yıksa yıksa gözbebeklerin yerle bir eder.

Ne gelirse onlardan gelir bana, 

Çalışma gücü, yaşama direnci...

Mutluluk gibi kazanılması zor, 

Mutluluk gibi yitirilmesi kolay.

Bir açarsın ki mutluyum, 

Bir kaparsın herşey elimden gitmiş.', 'Sen gidiyorsun ya işine yetişmek için,  Saçlarını, gözlerini, ellerini Neyin varsa toplayıp gidiyorsun ya,  Her seferinde birşey unutuyorsun...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-gidince-274-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Orucu', 'olum-orucu-zeki-ergin-bd38h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ölecek

biliyor herkes

doktor raporu var

türkülerle büyüttüğün oğlun

türkülerle ölecek

ağır ağır kuruyup

granit bir yontu gibi

görkemli duruşu yıkılacak

ve de yüreği duracak

varacak

kaynağı dinamitlenmiş ırmaklara

şafağın

nabzı atarken

gözlerinde yarınlara

_çağ sayı:10 haz76 

_sevgiliye isyan yt:haz04', 'ölecek biliyor herkes doktor raporu var türkülerle büyüttüğün oğlun türkülerle ölecek ağır ağır kuruyup granit bir yontu gibi görkemli duruş...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-orucu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-duahan-hanci-z35xq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hassas bir yürektim ben  ''Can''

Sana  can dedim, çünkü dediğim gibi sen benim canımdın. Bu canı kopardın yerinden sebepsiz yere, ben bile anlayamadım. Beni aylarca mutluluktan mutluluğa attın. Şimdi ise kederden kedere savuruyorsun. Benim canım beni üzmez. Çünkü biz bütünüz ve ikimizinde canı yanıyor. Beni canımdan ettin, hissetmedin mi sevdiğim? 

Verdiğin ödüller vardı bana  ''Dünya''

İkimize ait bir dünya vardı, sandığımız. oysa çevremizdeki etten duvar bize bakıyormuş, geç uyandık. Bana kendi ellerinle bir dünya kurdun, Küçük fakat öylesine büyük ve huzur dolu ki. O dünyada kaybolmak, gözlerinde kaybolmak, ellerinin sıcaklığına tutunmak öyle huzurluydu ki, o dünyayı yıktın biliyor musun? Sen kurdun, sen yıktın. Dünyamı değil beni yıktın, seyrettin sevdiğim...

Bir asi kuştum ben  ''Şahin''

Yüreğim tertemiz bir sevda köprüsünün bir ucunda bekliyordu. Heyecanla çırpındım yerimde, köprünün ucunda gördüm seni bir an. Hayalinle yaşamaya öylesine alışmışımki, o görüntünün hayal olduğunu anlayamadım. Sonra yine o aldatıcı mutluluk da sönüverdi gözlerimde, yüreğimde. geleceksin biliyorum, o sevda köprüsünü birgün birlikte adımlayacağız can yarim...

Bir sade çiçektim ben  ''Papatya''

Bir temmuz sabahı sevgi damlacıkları suladı beni. Büyüdüm bugüne kadar, kök saldım derin bir sevgiye. Sarı rengimi hüzünlerimden, beyazlarımı temiz sevgimden aldım. Oysa hiçbir sevgi kirli değil. Hatırlarmısın herzamanki yerde birgün bana ''Çok temizsin'' demiştin. Utancımdan kafamı eğdiğimde ''Kafanı kaldır'' dedin. temizlik yaşamda değildi, sadece duygulardaydı sevdiğim...

Coşkuyla akan bir suydum ben  ''Şelale''

Hala çağlıyorum, hala çağlıyorum. Gönlümde bir fırtına var dinmiyor. Yüreğim çağlıyor, düşüncelerim çağlıyor, duygularım ve hatta gözlerim çağlıyor. O günde dindiremedim bu coşkuyu, bugün de. Ben çağladım sen duruldun, sen çağladın ben duruldum. Ortak bir şelalemiz olmadı sevdiğim...

Duygularımı döktüğüm sayfalar var  ''Şiir''

Yazdığım her kelime, duygularımın damlalarıydı. Yürekten sevmeyen bir insan şiir yazamaz bilirsin sende. Oysa yazabildiğim her şiir, yazamadığım binlerce duygunun emaresiydi. Hala dolu dolu anlatamıyorum sevdamı. Sonu olmayan ve umutsuz sevdamı. Duygularımı anlatmaya bir ömür de bitse, bıkmadan yazacağım sana. Belki okumayacaksın ama seni erkekçe seven ve senin için hep şiir yazan biri olacak sevdiğim...

Sevgime verdiğin en güzel armağan  ''Ayrılık''

Temeli kıskançlık, yalan, yanlış anlaşılma, dedikodular gibi görünen, gerçek sebebi bir türlü anlaşılmayan bir ödül verdin bana, Ayrılık... 

Köprünün ucunda uçmayı bekleyen ''Asi'' bir kuş boynunu büktü artık. 

''Sade çiçek'' soldu gitti...

Çağlayan bir ''Şelale'' vardı ya, artık sadece gözleri çağlıyor, yapma artık sustur bitanem. Beni şefkatli kollarınla sardığım zamanlar artık uzadı, şimdi tek eksik var, o da kolların. Az bir eksiklik mi? Kolların yoksa yaşamda yok. Sevgiye değer veriyorsun biliyorum ama yine söylediğin gibi ''Sevgi herşey demek değil.'' Yine de seni sevmek sevgilerin en güzeli. 

Bu gönül Seni Çok Seviyor...', 'Hassas bir yürektim ben  ''Can'' Sana  can dedim, çünkü dediğim gibi sen benim canımdın. Bu canı kopardın yerinden sebepsiz yere, ben bile anl...', ARRAY['Türk Edebiyatı','Şiir','Duahan Hancı']::text[], 8.5, '{"poet":"Duahan Hancı","poet_slug":"duahan-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yoklugun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyküsel Yaşamalar', 'oykusel-yasamalar-zeki-ergin-pi6rk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'soluklaşmış anılar 

belleğimi işgal ederse

donuklaşmış

soyut fikirler saplanırsa kafama

aydınlık dünyam kapkara olup

soysuzlaşırsa yaşantım

ben neyleyim güzelliği

bir ağıt söyler

hafiften esen yel kulağıma

güneş güneşlikten çıkar

gün günlükten

huysuzlaşır

yıldızlar gökte

bulutlar devamda

bilinçsiz yaşamalara

sapık şarkılar söyler

dalgalar sahilde

vahşice

ırmakta akan su

duru yaşamalardan uzak

salt balıklar habersiz

fırtına yaşamadan

fırtına dünyadan

savruklaştı umutlarım

dalgın esen yel gafil avladı

gülmez oldu yüzüme ay

bulutların gazabına uğradı

köpükleşir dalgın su

hoyratlaşır

kişilerin yaşamına inat

coşar da coşar

gecenin sessizliğine inat

sarhoşça nağralar atar

sahilde dalgalar

tüm gücüyle saldırır kayalara

denizde balıklar

duru yaşamalara devamda

gelecekten habersiz

_mustafakemalpaşa ağu''67

_köz yt:1973

_şarkılar savrulur Ege''den yt:mar''14', 'soluklaşmış anılar  belleğimi işgal ederse donuklaşmış soyut fikirler saplanırsa kafama aydınlık dünyam kapkara olup soysuzlaşırsa yaşantım ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/oykusel-yasamalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-ahmet-ataman-x54jy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Korkuyorum gözlerinden, 

Gözlerime bakmamandan.

      Gözlerinde kendimi, 

Görememekten korkuyorum...

Düşlerimde yaşıyorum seninle, 

      Gözlerinde kaybolup, 

Ellerinde yeniden doğuyorum.

Gözlerimi kapatıp seni düşündüğümde, 

       Bir kere olsun dizlerinde,           

Uyuyamadan ölmekten korkuyorum.

    ...Ölüm de belki bir son değil ama, 

Seni tekrar tekrar sevmekten korkuyorum...', 'Korkuyorum gözlerinden,  Gözlerime bakmamandan.       Gözlerinde kendimi,  Görememekten korkuyorum... Düşlerimde yaşıyorum seninle,        G...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataman']::text[], 8.5, '{"poet":"Ahmet Ataman","poet_slug":"ahmet-ataman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korku-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '+Akgece-Karagün', 'akgece-karagun-zeki-ergin-uc06x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nedir o

gecenin duruluğundaki

sessizlik

gizlilik

gecelere tutsağım ben

günbatımı

öte yaşamıma köprü kurar akşamlar

akşam ah akşamlar

doyamam sizlere

bir gurup vakti

sessizliğe

yitikliğe köprü sizler

gerçek yaşamalara doğru

sıcak bir el okşarsa saçlarımı

bakarsa yüzüme

dost bir çift göz

mahsunca

yel yel yitirdim umutlarımı oysa

umut

ah umut

katı 

yoz

sevilerden uzak 

okşamak düşlerdeki yüzü

gecenin sessizliği

garipliği seslenir kulağıma

şiirsel öyküler anlatır

çobanyıldızı

ağlamaklı

sabahla birlik

güneş demirleşir keskinleşir

elmas kömürleşir yanar

güçsüzlüğüm doğar

güneşle

_mustafakemalpaşa eylül1967

_köz yt:1973', 'nedir o gecenin duruluğundaki sessizlik gizlilik gecelere tutsağım ben günbatımı öte yaşamıma köprü kurar akşamlar akşam ah akşamlar doyamam...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/akgece-karagun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Endülüs Kadar Maktul', 'endulus-kadar-maktul-i-lyas-altuner-p63w7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Delikanlı çağı edasıyla

Dönse de kalbini gökyüzüne

Dökülmek üzeredir şimdi saçları

Yüzüme yaslanan arzın 

Bir çayın kenarında

Mızraklar batar alnına

Uluorta sancılarla bezenir yüzü

Yeşilliğine kıyarken bahçe

En az Endülüs kadar maktüldür 

Gündönümü pervasızlığında

Uçurum gibidir fikri sokakların

Seccade tutar yüreğime bir ihtiyar

Kayıp mezarda 

Kafatasına ''Fatiha'' okur

Bilmeden kim olduğunu 

Yavaş

Usul

Kapanır dudakları sonra

Korkarım yalnızdır sokaklar

Korkuludur yüreği

Son aforozundan önce

Duvarlar ter boşalır

Yasını tutar bir mahallenin

Susayıverir yalnızlığa ve yıkılmışlığa

Kaybolan mihrakta

Seremoniler

Kuş seslerine yürür dehlizde 

Bilmeden yürür

Anlamadan öleceğini taşlanarak

Bir Filistin yamacında

Kar-siyah yüzünde yokuş vardır

Bir çocuk gibi ağlar annesine

En az benim kadar yaslıdır bu şiir

Kılıç kadar yürekli

Ve maktüldür Endülüs kadar

Gönlüm kadar', 'Delikanlı çağı edasıyla Dönse de kalbini gökyüzüne Dökülmek üzeredir şimdi saçları Yüzüme yaslanan arzın  Bir çayın kenarında Mızraklar bata...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/endulus-kadar-maktul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-alone-poet-d5cgq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fırtınaya kapılıp batmış sal gibi

Dikeninden zarar görmüş gül gibi

Sevgisiz kalmış biri gibi

Bir yaşam sahibiyim YALANLARLA DOLU

Sevgilisini göremeyen ama gibi

Sevdiğini söyleyemeyen dilsiz gibi

Sevildiğini duyamayan sağar gibi

Bir yaşam sahibiyim DERTLERLE DOLU

Patlamaya hazır volkan gibi

Dertlerle savrulan gemi gibi

Görülmeye değer şelale gibi

Bir yaşam sahibiyim RÜYALARLA DOLU

Diken üzerinde durur gibi

Hayatı kısıtlanmış biri gibi

Sevgiye doyamamış yar gibi

Bir yaşam sahibiyim GÖRÜLMEMİŞ AŞKLARLA DOLU', 'Fırtınaya kapılıp batmış sal gibi Dikeninden zarar görmüş gül gibi Sevgisiz kalmış biri gibi Bir yaşam sahibiyim YALANLARLA DOLU Sevgilisini...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasam-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'aşkın Günahını', 'askin-gunahini-alone-poet-kas1h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın günahı

Şiirin içinde

Karacaoğlanın dilinde

Irmağın ötesinde

Nedeni gönülde

Güneşin ardından

Ürpermiş dalından

Nefret dolu bir an

Ayrılık kalmış sonradan

Hazin olmuş sevdanın sonu

Israr etme işte bu', 'Aşkın günahı Şiirin içinde Karacaoğlanın dilinde Irmağın ötesinde Nedeni gönülde Güneşin ardından Ürpermiş dalından Nefret dolu bir an Ayrıl...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askin-gunahini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Tanımı', 'askin-tanimi-alone-poet-5ajba', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk okyanustur

Keşfedilecek bir sonsuzluktur

Aşk sudur

Gerektiğinde insanı ölümüne kurutur

Aşk ölümdür

İnadına insan üstüne üstüne sürünür

Aşk kratopraktır

Sonunda gidilecek tek yer orasıdır

Aşk zulümdür

İnsanı sonuna kadar çürütür

Aşk gürbettir

İnsana özlem çektirir

Aşk labirenttir

Kurtulabilmek kafa yedirttirir

Aşk dağdır

Zirveye ulaşabilmek zaman alır

Aşk insandır

Bunları çekmek doğa yasasıdır', 'Aşk okyanustur Keşfedilecek bir sonsuzluktur Aşk sudur Gerektiğinde insanı ölümüne kurutur Aşk ölümdür İnadına insan üstüne üstüne sürünür A...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/askin-tanimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzellik Önemli Değil', 'guzellik-onemli-degil-alone-poet-n0jh4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bir gül olsan

Bende bir deve tabanı

Gülün dikeninden zarar görmüş olsam

Bana cazip gelmezmi katır tırnağı

Sen bir yat olsan

Bende bir sal

Bazen yatın özelliği bir yere kadar biter

Ama herkes için benim sadeliğim yeter

Sen bir saray olsan

Bende derme çatma bir köşk

Senin sadece yapından etlilenilir

Benim ise o yıllara karşı direncimden', 'Sen bir gül olsan Bende bir deve tabanı Gülün dikeninden zarar görmüş olsam Bana cazip gelmezmi katır tırnağı Sen bir yat olsan Bende bir sa...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzellik-onemli-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş', 'savas-alone-poet-nh3di', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine gözlerime perde çekiyorum

Görmüyorum dünyadaki bu rezaleti

Yine kulaklarımı tıkıyorum

Duymuyorum savaşın o acı iniltilerini

Ama yüreğimi susturamıyorum

Birtek o durduracak bu sefaleti

Yine tuz bastım kanayan yarama

Silemiyorum savaşın o yok edilemez izlerini

Yine gösteremedim savaşa neden olanlara

Sakat insan yüzlerini

Ama bir gün gerecekler nelere sebep olduklarını

Anlayacaklar bir hiç uğruna nice insan katlettiklerini', 'Yine gözlerime perde çekiyorum Görmüyorum dünyadaki bu rezaleti Yine kulaklarımı tıkıyorum Duymuyorum savaşın o acı iniltilerini Ama yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/savas-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancıyız Bu Şehir İçre', 'yabanciyiz-bu-sehir-i-cre-i-lyas-altuner-snq7g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalk, gidelim

Yabancıyız bu şehir içre

Yolcu yolunda gerek

Gidelim, yollar bizi bekler

Gidelim, ayaklarımıza uzanır taş cadde

Bakma ardına sakın

Yoksa geri çağıracak bizi evler

Bakmadan gidelim bu şehirden

Bu şehir ki

Fırsat kolluyor ayağımızı kaydırmak için

Bağlamak için yüreğimizi

''Bu gidiş nereye'' diye sorma

Yürümene bak sen

Yolumuzun sonu meçhûle çıkacak

Gidelim, kalırsak eğer

Didikleyip durur akbabalar

İçimizde katran gibi duran yabancılığı

Olmasın bu şehirde dostumuz

Bedbaht olsak da kangren muhabbetiyle

Gidelim, savursun rüzgâr

Savursun ateşle bezenmiş küllerini üstümüze

Gidelim, son karakteri biziz kelimelerin

Ve cazgırların sesi adımlarımıza

Çarpsın şehir çıkışında

Çarpsın şehrin çöküşünde izlerimize

Şafak söküşünde

Tozlar silkelim üzerimizden

İhtiyar, su ver bize

Her ne kadar kirli olsa ellerimiz

Yüreğimiz temizdir, ihtiyar

Bir sen misin bu şehir içre

Yalnız sen misin izden biri

Yoksa, ölülere su taşıyan şehit misin

Söyle ihtiyar

Betin benzin neden kırmızı

Sen de bizden misin

Yolcuyuz, sonu yok yolumuzun

Arza mekân tutmak olmaz

Takılmaz aklımızın çengeline böyle şeyler

İklimler ölüme çağrı yapıyor

Gidelim kana dönüşmeden ellerimiz

Gidelim, gırtlağımız daralmakta

Dönme sakın ardına 

Çağıracak yoksa bizi yabancı sokak

Mavi atlas çökecek üstümüze

Ve çökecek üstümüze kibirli bulutlar

Ki, düşmanca kararıyorlar

Yürü şimdi 

Yabancıyız bu şehir üzre

Yolcu yolunda gerek', 'Kalk, gidelim Yabancıyız bu şehir içre Yolcu yolunda gerek Gidelim, yollar bizi bekler Gidelim, ayaklarımıza uzanır taş cadde Bakma ardına s...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/yabanciyiz-bu-sehir-icre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gözlerim...', 'sen-gozlerim-sema-senel-tum3x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben kördüm, sen gözlerim, 

Sen gidince söyle ben nasil görürüm, 

Askin bitti gidiyorsan, 

Ben seve seve körde gezerim.', 'Ben kördüm, sen gözlerim,  Sen gidince söyle ben nasil görürüm,  Askin bitti gidiyorsan,  Ben seve seve körde gezerim....', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asker', 'asker-alone-poet-b4o74', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deki o şimdi asker

Deki o şimdi vatani görevini yapıyor

Deki o bizleri koruyor

Askerim ana asker

Desinler ki

Gitmiş vatani görevini yapmaya

Düşmüş bir kışlaya

Çavuş demiş başladınız asker olmaya

Askerim ana asker

Derim ki

Gönderirim resimlerimi

Çekerim sıla hasreti

Açamam sevgilime derdimi

Askerim ana asker

Dediler ki

Çıktı bir göreve

Girdi bir cepheye

Yıktı bir kurşun mehmedim nerede

Askerim ana asker

Dedim ki

Ana sen gönlünü ferah tut

Sizleri kötülükten koruduk

Vatan sağ olsun şehit olmuşuk

Askerim ana asker', 'Deki o şimdi asker Deki o şimdi vatani görevini yapıyor Deki o bizleri koruyor Askerim ana asker Desinler ki Gitmiş vatani görevini yapmaya ...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asker-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aylem', 'aylem-alone-poet-0ej0k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir istanbul sahili

Gökyüzünün deli mavisi

Birgün bir sevgi elçisi

Düşünün ki maziyi

Düşersin peşine deliler gibi

Sorarsın derdini kederini

Arada kaynatısın belki sevip sevmediğini

Ama yapamadın hiç bir zaman istediğini

Gitti işte! Şimdi istemediğin kollarda

Sevgimiydi neden? Bütün bu olanlara

Sonunda ayrılsada

O şimdi çok çok uzaklarda', 'Bir istanbul sahili Gökyüzünün deli mavisi Birgün bir sevgi elçisi Düşünün ki maziyi Düşersin peşine deliler gibi Sorarsın derdini kederini ...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aylem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Körüm', 'ben-korum-sema-senel-zykaf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben körüm, 

Sen gözlerim, 

Sen gidince söyle ben nasil görürüm, 

Askin bitti gidiyorsan, 

Ben seve seve kör de gezerim.', 'Ben körüm,  Sen gözlerim,  Sen gidince söyle ben nasil görürüm,  Askin bitti gidiyorsan,  Ben seve seve kör de gezerim....', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-korum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Girdap', 'girdap-alone-poet-gz52f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilinmez bir girdabın içinde

Savrulan bir sal misali

Şu an içinden çıkılamayacak bir durumdayım

Ben istemezmiyim bundan kurtulayım

Ama siz  söylemiştiniz bu lafı bana

Ben istediğim içi bu durumdayım...', 'Bilinmez bir girdabın içinde Savrulan bir sal misali Şu an içinden çıkılamayacak bir durumdayım Ben istemezmiyim bundan kurtulayım Ama siz  ...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/girdap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın Yazısı', 'alin-yazisi-alone-poet-xsx53', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğarken yazmışlar yazımızı

Doktor tokatla acıtmış kıçımızı

Büyümüşüz yasaklamışlar nahımızı

Sonra sevmişiz Lacivertle Sarıyı

Okudular bize falımızı

Söylediler yemiş olduğum kazığı

Zırlada olsa kovalattılar tazıyı

Dünya bu belli olmazmış kime yazacak bu yazıyı', 'Doğarken yazmışlar yazımızı Doktor tokatla acıtmış kıçımızı Büyümüşüz yasaklamışlar nahımızı Sonra sevmişiz Lacivertle Sarıyı Okudular bize ...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/alin-yazisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Dünya', 'zalim-dunya-alone-poet-e0rst', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kederle sevgiyide

Acımasızların sillesinide

Görgüsüzlerin kibirlerinide

Sende gördüm zalim dünya

Bilinmez dertleri

Ölümsüz yarenleri

Maddiyata bağlı herşeyi

SEnde gördüm zalim dünya

Çektiğim çileleri yanyana koyarsan

Derdi kederi yanyana koyarsan

Araya sevgiyi koyarsan

Şayet bir de fikrimi sorarsan

Sana söyleyeceğim şudur; 

Sıkı dır dünya! Katilin karşında durur

Bunu senden öğrendim zalim dünya işte kin budur

Hadi şimdi beni sıkıysa durdur.', 'Kederle sevgiyide Acımasızların sillesinide Görgüsüzlerin kibirlerinide Sende gördüm zalim dünya Bilinmez dertleri Ölümsüz yarenleri Maddiya...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zalim-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bu', 'gonul-bu-alone-poet-agkc0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlüm sevsede

Bu fan, i bedenim yedi kat

Yerin dibine girsede

Seni seven bu ruhum

Göklere ersede

Deli gönül seni sevdiğini

Avaz avaz dilede getirse

Unutma senin peşine gelmeyeceğim

Ama seni yine ama yine seveceğim', 'Gönlüm sevsede Bu fan, i bedenim yedi kat Yerin dibine girsede Seni seven bu ruhum Göklere ersede Deli gönül seni sevdiğini Avaz avaz dilede...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gonul-bu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melankolik', 'melankolik-emel-cengiz-00g43', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O masum gözlerini arıyor gözlerim

Sevginle konuşturduğun

Sıcaklığını sunduğun

Hasret rüzgarlarına tutuldu bedenim

Kimsesiz, derbederim

Çılgınca özledim

Düşmedin sevda yollarıma şimdilerde

Nefesini soluklamak istiyorum

Tenini koklamak

Bedenine dokunmak

Seninle olmak istiyorum

Gün gün büyüyor sensizlik

Kahretsin! 

Sevmek değil bu; delilik

Yokluğundaki adım: 

MELANKOLİK', 'O masum gözlerini arıyor gözlerim Sevginle konuşturduğun Sıcaklığını sunduğun Hasret rüzgarlarına tutuldu bedenim Kimsesiz, derbederim Çılgı...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/melankolik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İZ', 'i-z-alone-poet-jue4l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pervasızca beni sensiz bıraktığın

O günden bu güne

Arkandan iz arar olmuşum

Gözüm yerde beynim sende

Senin ardından kalan küçük bir izinle

Seni bulacağım günü bekler olmuşum

İtiraf; 

Git dersen giderim

Gözüme perde çekerim

Yüreğimi örter giderim

Ama seni unutamam

Haykırış; 

Gönlümün bu boşluğunu

Kalbine ait olduğu için sana

Duygularına inanıp kandığı için gönlüme

Senin gibleri karşıma çıkardığı için

DÜNYAYA LANET OLSUN', 'Pervasızca beni sensiz bıraktığın O günden bu güne Arkandan iz arar olmuşum Gözüm yerde beynim sende Senin ardından kalan küçük bir izinle S...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/iz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-alone-poet-qglja', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir hiç uğruna ben den ayrıldın

Neydi seni bu ayrılığa iten sebep

Koskoca devri alem mi? 

Bu ayrılıktaki tek neden

Aşkımızı körelten

Seni benden, beni sevginden eden

Bir cevap bulamoıyorsun değil mi? 

Çünkü sen haksızsın

Beni dinlemeden

Kestin ilişkiyi

Tam eskileri silmiş sana alışmışken

Beni sevgimsiz

Beni yarimsiz

Beni eşsiz

Beni sensiz bıraktın

Ayrılıktı bunu adı

Bunu bilmezken

Bunuda öğretmiş oldun

Sevgiyide öğrettiğin gibi birtanem

Koskoca sevgimden geriye

Ufacık bir tebessüm

Koskoca bir hüzün

Az biraz düşünce

Bir çokta paylaşılamayacak anı bıraktın

Keşke zamanı durdurabilsen

Keşke kaderimi değiştirebilsem

Keşke yanında olabilsem

Keşkelere kaldık görüyormusun birtanem', 'Bir hiç uğruna ben den ayrıldın Neydi seni bu ayrılığa iten sebep Koskoca devri alem mi?  Bu ayrılıktaki tek neden Aşkımızı körelten Seni be...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ayrilik-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-emel-cengiz-ycrsd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen; adını bir türlü koyamadığım

Duygu karmaşam, çılgınlık yumağım

Acını hissediyorum yüreğimde

Sensizliğin yollarına düştüğümde

Öylesine özlüyorum ki anlatamam

Kahır yazsam da asla yapamam

Saklarım düşüncelerimi

Bilemem bu delilik mi

Bir kez görmek tutkusuyla

Olmazları koyarım araya

Sen isyanımın dev dalgaları

Düşlerimin ilkbaharı

Gönül sensiz kalmamalı

Sürekli düşüncelerle hesaplaşmalı

Bir bir anlatılmalı sevdalar

Çılgınca yaşanmalı

Terkedilmiş hissediyorum sanki kendimi

Bilmem hayatımda ki yanlış benlenti mi

Huzurlu değilim olduğum mekanlarda

Mutlu değilim bir başıma

Dedim ya adını koyamadığım

Galiba sensin; kaderim, YALNIZLIĞIM', 'Sen; adını bir türlü koyamadığım Duygu karmaşam, çılgınlık yumağım Acını hissediyorum yüreğimde Sensizliğin yollarına düştüğümde Öylesine öz...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizligim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızım Yıldız', 'yanlizim-yildiz-alone-poet-tho2l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökyüzünün o akılalmaz kızıllığına bakarken

Saatin nasıl ilerlediğini anlamazsın tabi

Akrep kaçıp yelkovan kovalarken

O güzellik göz gözü görmez bir karanlığa bıraktı yerini

Ve şimdi yine yanlızım

Her karanlık beni yeni bir yanlızlığın içine sürükler gibiydi

Ben o karanlıkta yürüyüp kendimi ararken

Gözüm semadaki bir parıltıya baka kaldı

O ekşimiş yüzümü çevirdiğimde

Şimdiye kadar görmediğim parlaklıkta

Bir yıldıza bakıyordum

O yıldız ki

Bana o kadar sıcak

Bana yolumu aydınlatacak kadar parlak

Ve o kadar yakındı

Ben bu göz aldatmacasına kanıp

Etkilendiğimi belli etmek için ellerimi uzattığımda

Sanki onu yakalayıp yanlızlığımı paylaşacakmış gibi

İşte o anda anladım benden çok uzakta olduğunu

Bir gerçeğin daha kırbaç gibi yüzüme vurulduğunu

O an kendimi olmadığım kadar yanlız hissettim

Yanlızlığıma bir yenisinin daha eklendiğini bilerek

Hayata devam etmeye çalıştım

Ne gecelerin gündüz olmasını istedim

Nede gündüzlerin gece

Ama her gece hüzünle birlikte indi yüreğime

Kendikendime sordum bu acı bir yıldız içinmiydi diye

yüreğim cevapladı bu saçma soruyu

Benim gölün yani ben

Hep uzakları kendine yakın bilmiş

Hep olgun insanları dinlemiş

Hepte imkansızları seçmiştir

Şimdi ise gördüğüm o yıldız

Olgun insan profilini çizen değil

O pozu veren ve o duyguyu yaşatan birisi

Benim için imkansızların en ötesi

O yıldız görmek istediğim halde

Göremediğim o yerde

İşte yine ben

Benim düşüncelerim, benim yanlızlığım

Benim duygularım bende saklanmış olarak gidiyorum

Hem çok uzaklara

Ama elini uzatıpta yakın hissedebileceğin yere

Hemde yanlızlığımı sorgulamaya her zamankinin aksine', 'Gökyüzünün o akılalmaz kızıllığına bakarken Saatin nasıl ilerlediğini anlamazsın tabi Akrep kaçıp yelkovan kovalarken O güzellik göz gözü gö...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yanlizim-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayabilmek', 'yasayabilmek-alone-poet-mq3fq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şayet yaşayabilseydim

Elimdeki kalemle bu boş defterde

Anlamlı kelimeler oluşacaktı

Kelimelerden cümleler kurulacaktı

Cümlelerden de halimi anlatan şiirler yazılacaktı

Hayat beni yaşatmadı

Şayet yaşayabilseydim

Kafamdaki düşüncelerle yanlız geçen günlerde

Dopdolu sevgiler oluşacaktı

Sevgilerden büyük aşklar doğacaktı

Aşklardanda yıkılması zor ilişkiler kurulacaktı

Hayat beni yaşatmadı', 'Şayet yaşayabilseydim Elimdeki kalemle bu boş defterde Anlamlı kelimeler oluşacaktı Kelimelerden cümleler kurulacaktı Cümlelerden de halimi ...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasayabilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-alone-poet-s3rdn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen hiç kendi kendine tokat attın mı? 

Ve hiç hissettin mi? ellerinin acısını

Terledin mi? sokakların dayağında

Ben yaptım

Sen hiç yalan söylemek zorunda kaldın mı? 

Hiç yalanla yüz yüze bırakıldın mı? 

Becebildin mi? kendini aramayı

Ben yaptım

Sen hiç ağlayabildin mi yanlızlığına? 

Hiç sevgisizlikten döküldü mü? bir göz yaşı damlası yanağına

Ve hiç sevilmenin, sevmek kadar bakabildin mi? tadına

İşte ben bunu yapamadım', 'Sen hiç kendi kendine tokat attın mı?  Ve hiç hissettin mi? ellerinin acısını Terledin mi? sokakların dayağında Ben yaptım Sen hiç yalan söy...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/itiraf-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakalca Bir Yalınzlık', 'sakalca-bir-yalinzlik-alone-poet-iz7dm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanlızlık bir sahil kenarında oturup

Onu seyretmektir

Ve doyacasına kendini keşfetmektir

Ne başlangıcını hatırlayıp

Nede sonunu getirebilmektir

Yanlızlık sonsuza kadarda olsa

Ondan ayrılmamaktır

Sevgisiz kalacağını bilsen bile

Kalbini doldurma çabasında olmamaktır

Ne aşkı bilmek

Nede aşkı tatma çabasında olmaktır', 'Yanlızlık bir sahil kenarında oturup Onu seyretmektir Ve doyacasına kendini keşfetmektir Ne başlangıcını hatırlayıp Nede sonunu getirebilmek...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sakalca-bir-yalinzlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-emel-cengiz-fuuxv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni ruhumun derinliklerinde sakladım

Kimse görmesin diye

Uykusuz geceler sıralanırken arka arkaya

Çareyi bulamadım

Üretemedim sevgisizliğinde sevgi sözcüklerini

Söyleyemedim gönlümdekilerini

Sen; sevdasız yollarda hasret kaldığım

Sen; bir türlü silip atamadığım

Ayrılık şarkılarına hazırlıyorum kendimi

Vedalara övgülerim şimdi

Gönül fırtınalarım zamansız dindi

Takılı kalmıştın bende

Aşamamıştım

Tutku olmuştun, arzu olmuştun

Bir baktım ki herşey olmuşsun

Acılar denizinde boğulmaktayım

İsyanların bini bir para yokluğuna

İster anla ister anlama

Dudaklarımdan dökülürken kelimeler

Gönlüm aksini söyler

Beklenenler, beklentiler

Senin için çekilen çileler 

Anlıyorum, hiçbir şey ifade etmediler

Anlatamadım gönlümün isteklerini

Söylemedim ama ölesiye sevdim seni', 'Seni ruhumun derinliklerinde sakladım Kimse görmesin diye Uykusuz geceler sıralanırken arka arkaya Çareyi bulamadım Üretemedim sevgisizliğin...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/isyan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elde Edilemeyen Deniz Kızı', 'elde-edilemeyen-deniz-kizi-alone-poet-rb1md', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Okyanusa benzer yanlız kalmak

İçi o kadar doludur ki

Bilinmezliklerle ve güzelliklerle

Buna karşılık beni yanlız bırakan

Kendimi dışa vurma çabasıdır

Bilmezmisin ki içindekileri kabul etmez bu çirkef dünya

Ve dışlar seni acımasızca

O kadar paylaşanım olsada

Paylaşılamayan düşüncelerdir paylaşmak istediğin sonsuzlukla

İnsanları içine alırsın be dünya

Onları düşünmeksizin bencilce

Ne dertlerini dinleyip çare bulursun nede yanlızlıklarına

Sonunda okyanusun çığlığı sahilde kayalarla buluşur

Tükenir çabaları dalgayla son bulan bir çığlıkta

O ki kendini anlatmaktır çabası

Haykırmaktır yanlızlığını

İnsanların duyarsızlığına kızması

Sevkeder onu tükenmeksiz bir duygusallığa mı? 

Sonucunu bilmese bile o anlatır

Yanlızlığını dile getirir

Hep aynı tecrübe ile o ne bilir

Şiir yazmakla anlatmaya çalışır yanlızlığını

O kendi çapında delidir', 'Okyanusa benzer yanlız kalmak İçi o kadar doludur ki Bilinmezliklerle ve güzelliklerle Buna karşılık beni yanlız bırakan Kendimi dışa vurma ...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/elde-edilemeyen-deniz-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar Arasında Çığlık', 'yildizlar-arasinda-ciglik-alone-poet-lrhmv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yanlızlık bir çığlıktır

Delicesine kayalara çarpan bir denizde

Sahile bakan bir yerde

Avazın çıktığı son nefeste

Onu sevdiğinşi haykırmaktır

O bilmesede yada o olmasa bile

Yanlızlık bir yıldızdır

Tatma çabasıdır ondan uzaklaşmak

Yakınında hissetmek ama imkansızca

Elini uzatabilmek ama delice bir çaba

Onsuz kalsanda bir zifiri karanlıkta

Rakımı yüksek dağın zirvesinde

Gökyüzüne bakma desem bile kendi kendime

İşte yıldızlar her yerde

Savrulan bir yanlızlığın içinde', 'Yanlızlık bir çığlıktır Delicesine kayalara çarpan bir denizde Sahile bakan bir yerde Avazın çıktığı son nefeste Onu sevdiğinşi haykırmaktır...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yildizlar-arasinda-ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaba', 'caba-alone-poet-j4aph', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendimi aradım gecelerin içinde

Labirent misali karma karışık

Düşüncelerle dolu beynimde

Küflenmiş sevgiler ve sevgililer

Hala eskilerdeyim

Ve hala eskileri keşkelere çevirme peşindeyim

Ama bilmezki ne yüreğim nede beynim

Eskiler geri gelmez deli saçması keşkelerim

Gökyüzünde gündüzlerim

İmkansızı görmek istedi gözlerim

Nerede diye sordu dilim

Gündüzleri sensiz geçen gecelere tercih ederim', 'Kendimi aradım gecelerin içinde Labirent misali karma karışık Düşüncelerle dolu beynimde Küflenmiş sevgiler ve sevgililer Hala eskilerdeyim ...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/caba-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yanlızım', 'yine-yanlizim-alone-poet-bcfdg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yanlızlığı tanırım

Birde yanlızlığımı

Yanlız geçen günlerimi

Sevgi için çırpınan yüreğimi

Gökyüzüyle yakınlaşam ruhumu

Sevgiyle bağdaşan yüreğimi

Sensiz geçen günlerimi

Rüyalarıma sorarım

Gökyüzüyle tanıdım seni

Ve yıldızlara bıraktım kalbimi

Sabahları göremedim belki

Ama en mutlu anlarım senin ile olan gecelerimdi', 'Bir yanlızlığı tanırım Birde yanlızlığımı Yanlız geçen günlerimi Sevgi için çırpınan yüreğimi Gökyüzüyle yakınlaşam ruhumu Sevgiyle bağdaşan...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-yanlizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim', 'seni-ozledim-osman-turkmen-yrpho', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hasretim vurur, önce gecelere, 

geceler dönüşür, işkencelere, 

yazdın beni sen, sensiz hecelere, 

sabahında senin, seni özledim.

gidişinle bitti, tüm sözlerim, 

biliyorum yoksun, ama hislerim, 

uzaktan da uzak, seni gözlerim, 

kışların yazında, seni özledim.

ister inan bana, ister inanma, 

ben tutuldum sana, sen yakalanma, 

yalan değil inan, dün gibi hala, 

yaşamaktan öte, seni özledim.

zamana bıraktım, dönersin diye, 

bir tek resmin kaldı, senden hediye, 

gittiğin gün gibi, dön be geriye, 

seviyorum işte, seni özledim.', 'hasretim vurur, önce gecelere,  geceler dönüşür, işkencelere,  yazdın beni sen, sensiz hecelere,  sabahında senin, seni özledim. gidişinle b...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-ozledim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-alone-poet-oflry', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık bir sokaktayım

Yılların getirdiği bir yorgunlukla

Yanlızlığın getirdiği savurganlıkla

Ne çıkabildim, Nede sonunu bulabildim

Çıkmazın içinden çıkanlardan değilim

Yürüyorum tabanlarım şişecesiye

Etrafım yüksek binalarla dolu

Ve karşımda o hep aynı menfaatçı yüzler

Ne kadar kaçsamda onlardan

Sanki üstüme yürüyorlar

Sanki peşimden geliyorlar

Beni kurtaracak farklı bir yüz

Düşünceli bir el

Sevgiyi tanıyabilen ve sevebilen

Sevgiyi karşılıksız paylaşabilen

Çıkar beklemeyen

Beni sevebilecek bir yürek

Çıksın istedim o koskoca gökyüzünden

Ve ben koşsamda

Belki de ona koşuyorum

Yada ondan uzaklaşıyorum

Seslenmesini bekliyorum

Uzaklaşıyorsam geri döneyim diye

doğru gidiyorsam çabuk olayım diye

Çünkü yoruldum ve tükendim

Hem koşmaktan

Hemde etrafımdaki mefaatçı yüzlerden

Onlardan uzaklaşmak için

Ya sen beni çekersin bu düşünceden

Yada ben çekerim kendimi bu alemden

Ben seçmedim bu yolu ve bu yorumu

Artık insanlar bana güvenmiyor bende onlara

Bu yüzden haykırıyorum

Bu yüzden sevgiyi arıyorum

Çünkü hakketmedim

Artık sevmek ve sevilmek istiyorum', 'Karanlık bir sokaktayım Yılların getirdiği bir yorgunlukla Yanlızlığın getirdiği savurganlıkla Ne çıkabildim, Nede sonunu bulabildim Çıkmazı...', ARRAY['Türk Edebiyatı','Şiir','Alone Poet']::text[], 8.5, '{"poet":"Alone Poet","poet_slug":"alone-poet","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yorgunum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Dostum', 'can-dostum-buruk-sevinc-bmt7s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen günlerin yorgunluğunda

Yine seni düşündüm candostum

Mutsuz geçen gecelerin durgunluğunda

Kalbime seni yazdım candostum

Yine yoksunum senden, hayallerinden

Buna çare yok mu çarelerinden

Kaderimle beni de al mısralarından

Yalnızım yanımda yoksan candostum

Sen yokken yalnızlık yoldaşım oldu

Ama seni unutmadım candostum

Mutsuzluktan yüreğim sararıp soldu

Yine seni unutmadım candostum

Bir kez olsun halimi soran olmadı

Çok çekmişim ama çilem dolmadı

Haykırdım sesimi duyan olmadı

Sen duydun mu feryadımı candostum

Sevmek yalnızlıktan daha zor geliyor

Geçen her gün bana acı veriyor

Akan gözyaşımı silen olmuyor

Gözyaşımı siler misin candostum', 'Sensiz geçen günlerin yorgunluğunda Yine seni düşündüm candostum Mutsuz geçen gecelerin durgunluğunda Kalbime seni yazdım candostum Yine yok...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/can-dostum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlar mısın?', 'hatirlar-misin-buruk-sevinc-osrgf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın? 

Küçükken, saklambaç oynardık, 

Taşlarla ismimizi yazardık yollara.

Geceleri, yıldızları izlerdik doymadan, 

Mehtabı seyrederdik, 

Ağustos akşamında...

Hatırlar mısın? 

Hatırlar mısın? 

Sadece aşk öykülerini okurduk, 

Leyla''yı, Mecnun''u, 

Aslı''yı, Kerem''i okurduk, 

İntizarı okurduk defalarca...

Hatırlar mısın? 

Hatırlar mısın? 

Giderken ardından ağladığımı, 

Gitme diye diz çöküp yalvardığımı, 

Seni seviyorum dediğimi...

Hatırlar mısın? 

Şimdi hatırlar mısın? 

Hatıralarla beni...

Hatırlar mısın?', 'Hatırlar mısın?  Küçükken, saklambaç oynardık,  Taşlarla ismimizi yazardık yollara. Geceleri, yıldızları izlerdik doymadan,  Mehtabı seyrede...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hatirlar-misin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin Ettim', 'yemin-ettim-buruk-sevinc-cvnmh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmezdim...

Zamanın bu kadar uzun olduğunu, 

Sen gittikten sonra...

Saniyeler günlerim, 

Dakikalar aylarım, 

Saatler yıllarım oldu.

Yorgun düştüm artık bu sevdadan...

Seni sevmek istemesemde, severken, 

Her seni sevmiyorum dediğimde

Seni sevdiğimi, 

Hem de delice sevdiğimi hatırladım.

Ağladım saatlerce...

Sana değil, seni sevdiğime ağladım durmadan.

Ağlarken uykuya dalmışım, 

Tam seni unuttum derken, 

Rüyalarıma girdin...

Yine seni unutamayacağımı hatırladım.

Hiçbir zaman kavuşamayacağımı bilsem bile, 

Hayatımı sevmeyip, seni seveceğimi, 

Yıldızlardan, mehtaptan, yalnızlıktan vazgeçip

Senden vazgeçemeyeceğimi anladım.

Ellerimi tutmasan bile, 

Ellerini bırakmamaya yemin ettim.

Hayalini unutmamaya, 

Seni unutmamaya yemin ettim.', 'Bilmezdim... Zamanın bu kadar uzun olduğunu,  Sen gittikten sonra... Saniyeler günlerim,  Dakikalar aylarım,  Saatler yıllarım oldu. Yorgun ...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yemin-ettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezdim', 'bilemezdim-buruk-sevinc-eh2h6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilemezdim...

Seni böyle seveceğimi bilemezdim.

Kavuşamayacağımı bilsem bile, 

Seni unutamayacağımı bilemezdim.

Bilemezdim...

Karanlık gecemi mehtaba çevireceğini, 

Yeşili, maviye döndüreceğini, 

Kalbimi tamamiyle alacağını, 

Beni böyle etkileyeceğini bilemezdim.

Bilemezdim...

Sana yazdığım mektupları, 

Yırtıp atacağını, 

Sana olan aşkımdan nefret edeceğini, 

Seni sevdiğim için üzüleceğini, 

Beni sevmeyeceğini bilemezdim.

Bilemezdim...

Herkesi güldürürken, 

Beni ağlatacağını, 

Neşenle herkese neşe katarken

Beni uzaktan da olsa üzeceğini, 

Dönüpte bir defa bana bakmayacağını bilemezdim.

Bilemezdim...

Seni ömrüm boyunca

Sevmeye yemin edeceğimi, 

Şu kalbimde senden başka

Kimseye yer vermeyeceğimi, 

Seni arkadaşlarından bile kıskanacağımı, 

Seni böyle seveceğimi bilemezdim.', 'Bilemezdim... Seni böyle seveceğimi bilemezdim. Kavuşamayacağımı bilsem bile,  Seni unutamayacağımı bilemezdim. Bilemezdim... Karanlık gecem...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bilemezdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kez', 'son-kez-buruk-sevinc-ojlvp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu, sana yazdığım son satırlarım olacak belki de, 

Belki de bundan sonra sana hiç şiir yazmayacağım, 

Belki de büyüdüğüm için, 

Hiç olmazsa büyüdüğümü hissettiğim için.

Zira, gerçekleri görmeye başlıyorum yavaş yavaş.

Ağlamaktan vazgeçiyorum, kalbim istemese de, 

Bitiriyorum melal yolculuğumu, ben istemesem de.

Anlıyorum yavaş yavaş...

Anlıyorum hayatı, hayatın gerçeklerini, 

Anlıyorum bu dünyada aşkın yerinin olmadığını, 

Sevgiden daha değerli şeylerin olduğunu, 

Anlıyorum...

Anlıyorum ve vazgeçiyorum senden, 

Vazgeçmek istemesem de.

Kalbime gömüyorum aşkımı, 

Unutmak istemesem de, 

Senden vazgeçmek istemesem de...

Dün geceye kadardı herşey.

Son kez yıldızları saydım, 

Son kez efkarlandım, 

Son kez düşündüm seni, 

Son kez ağladım senin için, 

Son kez dua ettim Rabbime, 

Seni bana kavuştursun diye

Ya da mutlu etsin diye...

Senden ayrılmak zor olsa bile, 

Son kez elveda deyip gitmeliyim bu yerden.', 'Bu, sana yazdığım son satırlarım olacak belki de,  Belki de bundan sonra sana hiç şiir yazmayacağım,  Belki de büyüdüğüm için,  Hiç olmazsa ...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/son-kez-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrik Şiir-2-', 'devrik-siir-2-devrik-sair-22f3c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana yazıyorum

ıssızlığıma uzanan bir el gibi

sana yazıyorum

su sızdıran yalnızlığımın içinden boğulurken

derinlemesine dalıyorum

bilmediğim acılara

sana yazıyorum 

burdan her şey bulanık

sana yazıyorum

bilmediğim dillerde ağlıyorum', 'sana yazıyorum ıssızlığıma uzanan bir el gibi sana yazıyorum su sızdıran yalnızlığımın içinden boğulurken derinlemesine dalıyorum bilmediğim...', ARRAY['Türk Edebiyatı','Şiir','Devrik Şair']::text[], 8.5, '{"poet":"Devrik Şair","poet_slug":"devrik-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/devrik-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor Bir Türlü', 'olmuyor-bir-turlu-buruk-sevinc-x0c0v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adını ben kattım alın yazıma, 

Şimdi kendim bile bozamıyorum.

Ne yapsam yanına kalacak gibi

Sana küsemiyorum, kızamıyorum.

Öğrenmek istedim seni seveli, 

Beni yeni baştan dokuyan eli, 

Geldim son düğüme gözüm perdeli, 

Ah onu bir türlü çözemiyorum.

Beni bırakmıyor kurduğun tuzak, 

Kıskancım, hastayım, tedirginim bak, 

Hoş geliyor kuyruğuyla oynamak, 

Yılanın başını ezemiyorum.

Boşa aranırdım, boşa dalardım, 

Açıldım engine, kıyına vardım, 

Canım pahasına inci çıkardım, 

Bir sağlam ipliğe dizemiyorum.

Bir senden alıyor gönlüm haberi, 

Sen oldun o körün bakan gözleri, 

İçime sinmiyor bir güzel yeri, 

Sen yanımda yokken gezemiyorum.', 'Adını ben kattım alın yazıma,  Şimdi kendim bile bozamıyorum. Ne yapsam yanına kalacak gibi Sana küsemiyorum, kızamıyorum. Öğrenmek istedim ...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmuyor-bir-turlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-buruk-sevinc-l5in7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen kimsesizlik nedir bilir misin arkadaş? 

Seni kimse hayatın kucağına atıp kaçtı mı? 

Sana her gün yalnızlığını hatırlatan oldu mu? 

Sen hiç yalnız kaldın mı arkadaş? 

Sen gözyaşı nedir bilir misin arkadaş? 

Hiç saatlerce ağladığın oldu mu? 

Hıçkırıkların odanda yankılandı mı? 

Seni ağlatacak bir sevgilin oldu mu arkadaş? 

Sen hiç mutsuz oldun mu arkadaş? 

Çaresizlik içinde başını duvarlara vurdun mu? 

Ve saatlerce oturup düşündüğün oldu mu? 

Seni böylesine düşündüren bir sevgilin oldu mu arkadaş? 

Ve sen hiç azap çektin mi arkadaş? 

Seni diri diri mezara gömdüler mi? 

Yaşarken öldürdüler mi seni? 

Seni hayatta en acı silahla vurdular mı arkadaş? 

Sen hiç sevdiğin oldu mu arkadaş? 

Her şeyin çözümünü aradın mı? 

Çaresiz kalınca ona koştun mu? 

Sen uğruna ölecek kadar sevdin mi arkadaş?', 'Sen kimsesizlik nedir bilir misin arkadaş?  Seni kimse hayatın kucağına atıp kaçtı mı?  Sana her gün yalnızlığını hatırlatan oldu mu?  Sen h...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arkadas-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değil', 'degil-buruk-sevinc-nmprh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmem ki, sana nasıl anlatsam; 

Nasıl, nasıl size derdimi? 

Bir dert ki yürekler acısı, 

Bir dert ki düşman başına...

Gönül yarası desem...

Değil! 

Ekmek parası desem...

Değil! , 

Bir dert ki...

Dayanılır şey değil.', 'Bilmem ki, sana nasıl anlatsam;  Nasıl, nasıl size derdimi?  Bir dert ki yürekler acısı,  Bir dert ki düşman başına... Gönül yarası desem......', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/degil-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzayan Bir Şafak Sonrası', 'uzayan-bir-safak-sonrasi-buruk-sevinc-r3vcu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ufuklar sisli, yıldızlar sürgün, ay buğulu, 

Ölgün bakıyor muhteşem kehkeşan öteden.

Gözlerim birkaç asırlık hicranla dopdolu, 

Kulaklarımda hasret nağmeleri her telden.

Her gece binbir duyguyla etrafı süzerken, 

Ümit, inkisar arası ve hep yapayalnız.

Ne çığlıklar duyarım böyle yalnız gezerken, 

Çevre alaca karanlık, dörtbir yan ıpıssız.

Düşer gönlümün enginliklerine hep hüzün, 

İçerim bazen gözyaşlarımı sessiz sessiz...

Peltekleşir hislerim, dili tutulur sözün, 

Sesler dinlerim ruhumda güftesiz, bestesiz.

Bir de kalbimin ritmi inkisarla vurunca, 

Salarım kendimi en uzun ağlamalara, 

Ve ne hafakanlar yaşarım gece boyunca, 

Dökerken içimi kapkaranlık kuytulara.

Söyleyin güneş ne zaman doğacak acaba? ! 

Gece sürüp gidemez şafak söktükten sonra...

Bir deyin yağmur ne zaman yağacak acaba? ! 

Kar, buz böyle kalamaz cemre düştükten sonra...', 'Ufuklar sisli, yıldızlar sürgün, ay buğulu,  Ölgün bakıyor muhteşem kehkeşan öteden. Gözlerim birkaç asırlık hicranla dopdolu,  Kulaklarımda...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzayan-bir-safak-sonrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayacağım', 'unutmayacagim-buruk-sevinc-ivrjm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah sevgilim! ..

Sen gittikten sonra, 

Güneş battı, akşam oldu ruhumda.

Yine karanlığa boğuldu dünyam.

Sensiz geççen her saniyenin ızdırabı var içimde.

Ama, biliyorum ki bir gün, 

Yine sabah olacak, 

Yine güneş doğacak ruhuma.

Sensiz geçecek senle bir hayat, 

Senle bitecek sensiz bir ömür.

Hayalin ruhumda, 

Gözlerin kalbimde...

Unut desen unutamam, 

Sevsen bile ben sevemem.

Öylesine vebali ağır bir yük yükledin ki bana, 

Kaldıramıyorum artık, 

Artık taşıyomıyorum.

Bedenim değil kalbim yoruldu.

Ama, biliyorum ki, 

Bir ikindi vakti, 

Yine seher yeli esecek, 

Yine ferahlayacağım.

Unutma ki seni asla UNUTMAYACAĞIM.', 'Ah sevgilim! .. Sen gittikten sonra,  Güneş battı, akşam oldu ruhumda. Yine karanlığa boğuldu dünyam. Sensiz geççen her saniyenin ızdırabı v...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unutmayacagim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekik Gözlüme', 'cekik-gozlume-buruk-sevinc-0pj1k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabah oldu yine uykusuzum.

Erken ama belki dönersin diye bekledim.

Ne yazık, bu sabahta gelmedin.

Vefasızlığını bir kez daha gösterdin bana

Ama olsun, belki yelkenin kırılmıştır, 

Rüzgar esmiyordur belki, 

Ya da deniz kurumuştur.

Aşkın denizi kurur muymuş? 

Sen ve ben boğulduk o denizde, 

Endamın ve ruşenin denizinde.

Neydin ki aklıma senden başka bir düşünce girmiyor, 

Ve neydin ki, Hala seni unutamayacak kadar sevdim.

Ellerini, gözlerini özlüyorum, 

Fevkalade olan sesini özlüyorum.

Ama neden? Neydin ki? ..

Sen bir vefasızdan başka neydin? 

Issız bir çölün ortasında

Zambaklar ve leylaklar açar mı? 

Yarim sen açtın kalbimde.

Ateş böceği gibi gecemi aydınlattın, 

Rümeysam oldun ıslık çalan gecelerde...

İnce ve zarif bir gül yaprağım, 

Matemim oldun, istemesem de...

Yüzüme bakmadın giderken, 

İçimdeki ateşi görmekten korktun.

Neden ayrıldık ki seninle? ..

Elele tutuşmak, gözgöze bakışmak, 

Sevgi dolu güzel günler yaşamak varken...

Endamın sarayında oturmak, 

Nihavend zehrini içmek varken...

İntizarı okumak, 

Umudu yaşamak varken...

Neden ayrıldık seninle? ..

Unutmak kolay mı seni? 

Toprağına gül ektim, bağrıma taş

Ama seni unutamadım.

Mücellamı unuttum, 

Adını unutamadım.

Direttim seni unutmaya, 

Islandım yağmurda aşkını silmek için.

Mazimsiz seni unutamadım.', 'Sabah oldu yine uykusuzum. Erken ama belki dönersin diye bekledim. Ne yazık, bu sabahta gelmedin. Vefasızlığını bir kez daha gösterdin bana ...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/cekik-gozlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Güzel', 'mechul-guzel-buruk-sevinc-v6t0m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki uzun zamandan beri

Yazdığım ilk şiir olacak.

Hem de hiç tanımadığım birine...

Gözlerine bile bakamadığım birine...

İçimde biraz sevinç, biraz burukluk...

Kalemimi elime alıyorum.

Ve yazmaya başlıyorum

Adını MEÇHUL koyduğum GÜZEL''e

Meçhul Güzel! ..

Sana merhaba dediğimde, 

Yüzümde oluşacak kızarıklığı anımsıyorum.

Yüzümde bir tebessüm nağmesi...

Gülümsüyorum...

Elini tuttuğumda, 

Yerinden çıkacakmışcasına

Çarpacak olan kalbimi anımsıyorum.

Ve kalbim

Yerinden çıkacakmışcasına çarpmaya başlıyor.

Yüzümde utangaç bir tebessüm...

Gülümsüyorum...

Seninle konuşurken bakamayacağım

Gözlerini hayal etmeye çalışıyorum, 

Bakışlarını düşünüyorum, 

Beni öldürecek olan bakışlarını...

İrkiliyorum...

Yine aynı hüzünle mi karşılaşacağım? 

Diyorum kendi kendime...

Korkacağımı biliyorum sana yaklaşırken.

Hep bir kaybetme korkusu olacak.

Ama vazgeçiyorum...

Benimleyken değerliyse, 

Gittiğinde daha değerli olacak diyorum.

Yüzümde hüzünlü bir  tebessüm...

Gülümsemeye çalışıyorum, olmuyor.

Gözlerim dolacak gibi oluyor, 

Seni hayal ederken...

Hüzünleniyorum...

Beni bu duygulara sürükleyen

İlksin Meçhul Güzel.

Seni düşünürken, böyle olsun biraz da...

Biliyorum...

Beni tanımıyorsun! 

Ben de seni tanımıyorum.

Ama kalbim seni tanıdı ve sevdi, 

Hem de vazgeçmeyecekçesine...

Bunu duyunca gülümsüyorsun.

Yüzünde, saklamaya çalıştığın ama saklayamadığın

Bir sevinç yumağı oluşuyor.

Utanıyorsun...

Yüzün kızarıyor...

Ve sevmek böyle oluyormuş diyorsun...', 'Belki uzun zamandan beri Yazdığım ilk şiir olacak. Hem de hiç tanımadığım birine... Gözlerine bile bakamadığım birine... İçimde biraz sevinç...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/mechul-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Vazgeçmek', 'sen-ve-vazgecmek-buruk-sevinc-6upw7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen, Çekik Gözlüm...

Sen ve Vazgeçmek.

Öylesine uzaksınız ki birbirinize.

Soruyorlar bana; 

Seni sevdiğimi söylüyorum.

Bu defa seni soruyorlar bana; 

Beni sevdiğini söylüyorum, 

Tereddüt etmeden...

''Sen ve Vazgeçmek'' diyorlar.

Bütün kalbimle ''Sen'' diyorum.

Söyle, senden vazgeçebilir miyim Çekik Gözlüm.', 'Sen, Çekik Gözlüm... Sen ve Vazgeçmek. Öylesine uzaksınız ki birbirinize. Soruyorlar bana;  Seni sevdiğimi söylüyorum. Bu defa seni soruyorl...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-ve-vazgecmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Öğrenciyim Anne', 'ben-ogrenciyim-anne-buruk-sevinc-6nfh4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Odamın bir köşesine oturdum, efkarlıyım

Bir seni bir de sevdiğimi düşünüyorum anne.

Ne kadar kırgın olsan da bana

Beni, ne çok sevdiğini biliyorum.

Sözünü dinlemediğim zamanlar

Kızıyorsun bana.

Ama bu kızgınlık az sürüyor, 

Saçlarımı okşuyorsun anne.

Biliyorum kalbini kırdım, 

Ne yapayım ben öğrenciyim anne.

Şimdi ayrı diyarlardayız anne.

Seni çok özlüyorum.

Bir seni bir sevdiğimi özlüyorum anne.

Çok dertliyim anne.

Biraz mutlu, biraz da hüzünlü...

Affet beni ben öğrenciyim anne.

Biliyor musun anne? 

Bir seni, bir de sevdiğimi düşünürken

Zaman su gibi akıp geçiyor.

Sanki yanımdasınız, şuramda bir yerde.

Şimdi yaptıklarım senin için, 

Bir de sevdiğim için anne.

Onun kim olduğunu bilmiyorsun

Ama bir gün öğreneceksin.

Belki yine kızacaksın, 

Belki de sevineceksin.

Biraz çapkınım, biraz deli dolu, 

Ama ben öğrenciyim anne.', 'Odamın bir köşesine oturdum, efkarlıyım Bir seni bir de sevdiğimi düşünüyorum anne. Ne kadar kırgın olsan da bana Beni, ne çok sevdiğini bil...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-ogrenciyim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme Mektup', 'anneme-mektup-buruk-sevinc-b0w97', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu umutsuzca bekleyiş yok mu? 

Artık şiir yazamıyorum, 

Ağlıyamıyorum, 

Aşk şarkıları söyliyemiyorum anne.

Biliyorum, bu sevda

Ya beni, ya da seni yakacak anne

Ne olur bana kızma anne, 

Yüreğimde ki bu ateş, 

Beni her an yakıyor.

Ama bir gün seni de, beni de, 

Sevdiğimi de yakacak anne.

Bir seni, bir sevdiğimi, 

Bir de memleketimi çok özledim anne.

Beni affet anne.

Bir daha sözünden çıkmayacağım, 

Bir daha sevmeyeceğim anne.

Dün gece sevdiğimi gördüm rüyamda anne.

Gizleme benden sen de biliyorsun, 

Artık beni sevmiyor, 

Şimdi bir başkasının dimi anne.

Biliyor musun anne? 

Ben sevdiğimi hep sevmiştim.

Biliyorum, yine kızacaksın bana

Ama hala seviyorum anne.

Sen de olmasan anne, 

İlk önce kalbimi, 

Sonra dünyayı yakardım.

Biliyor musun? 

Sevdiğime yazdığım şiirleri yaktım bile anne.

Biliyor musun anne? 

Geceleri korkuyorum artık.

Bir sensizim, bir de artık benim olmayan sevdiğimsiz.

Sana kavuşacağım

Ama o asla dönmeyecek anne.

En son O''na Çekik Gözlüm demiştim anne.

Bundan alınmış olsa gerek.

Ama bunu söylememi çok severdi.

Öyleyse niye gitti anne? 

Niye beni yapayalnız bıraktı anne? ..

Biliyor musun anne? 

Bugün ayın otuzu, 

Sevdiğimin doğum günü, 

Benimse ölüm günüm anne.

Yine kızma bana anne.

Biraz kırgınım, biraz da dargın, 

Biraz da efkarlıyım anne.

Hala inanamıyorum.

Sevdiğim beni terketmiş anne.

Duydun mu? 

Seni sevmiyorum dedi, 

Ve şimdi kalbimi sıkıyor anne.

Bu terkediliş var ya anne, 

Dönmek istemiyorum.

Ağlama be anne.

Üzüntüden böyle konuşuyorum.

Sana söz döneceğim.

Dedim ya anne, 

Bir seni, artık benim olmasa da sevdiğimi, 

Bir de memleketimi özledim anne.', 'Bu umutsuzca bekleyiş yok mu?  Artık şiir yazamıyorum,  Ağlıyamıyorum,  Aşk şarkıları söyliyemiyorum anne. Biliyorum, bu sevda Ya beni, ya d...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/anneme-mektup-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Güne Girerken', 'yeni-bir-gune-girerken-buruk-sevinc-sws4o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mum ışığındayım, 

Odam karanlık.

Saatim yeni bir güne saniyeler sayıyor, 

Korkmuyorum...

Çünkü seni düşünüyorum, 

Yeni bir güne girerken...

Ne annem, ne babam, 

Ne de kardeşlerim.

Hele hele ne de dostlarım

Geçmiyor aklımdan.

Sadece seninleyim, 

Yeni bir güne girerken...

Epey oldu ayrıldığımız.

İlk önceleri nefret ettim senden, 

Sonra affettim, vazgeçeceğim dedim, 

Vazgeçtim dedim ama vazgeçemedim.

Vazgeçmeyeceğim dedim, 

Yeni bir güne girerken...

Ben güne sıfırdan başlıyorum, 

Yeni hayatıma başladığım gibi.

Ne sensiz olabiliyorum, ne de senle.

Seni ve dostlarımı unutmak istiyorum, 

Her şeye yeniden başlamak istiyorum, 

Yeni bir güne girerken...

Senin ve yalnızlığın acını çekiyorum.

Çile dedikleri bu olmalı.

Sensiz olmak, yalnız kalmak var ya...

Ah bir anlayabilseydin beni...

Gözlerim doluyor ama ağlamıyorum, 

Yeni bir güne girerken...

Bir gün, bir gün Çekik Gözlüm

Ama bir gün mutlaka; 

Aşk yudum yudum, 

Hasret yumak yumak, 

Vuslatımız yakındır elbet.

Biliyor musun? 

Hala seni seviyorum, 

Yeni bir güne girerken...', 'Mum ışığındayım,  Odam karanlık. Saatim yeni bir güne saniyeler sayıyor,  Korkmuyorum... Çünkü seni düşünüyorum,  Yeni bir güne girerken... ...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yeni-bir-gune-girerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-buruk-sevinc-boqqz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum, 

Ne yalnızlığın acısını, 

Ne de sana olan hasretimi...

Ne seni, 

Ne de gözyaşlarımı, 

Bu kara isle boğamam.

Ama içiyorum işte...

Biliyorum, 

Ne sen geri döneceksin, 

Ne de yaktığım gençliğim.

Hepsini günlüğümle rafa kaldırdım, 

Eskisi gibi değil, 

Sık sık bakmıyorum artık.

Artık seni özlesem de, özlemiyorum.

Çaresizliğimi gören sigaram, 

Hemen yanıbaşımda.

Yine efkarlanıyorum...

''Ah ulan ahh! '' demek istesem de, 

İki damla gözyaşına sığdırıyorum.

Ve bir nefes daha çekiyorum, 

Bitmesini istemediğim bir nefes daha...

Biliyorum, 

Derdime derman olmayacak, 

Yarama merhem sürmeyecek, 

Kanayan kalbimi sarmayacak, 

Biliyorum...

Ne senden, ne de sigaramdan

Vazgeçemiyorum işte...', 'Biliyorum,  Ne yalnızlığın acısını,  Ne de sana olan hasretimi... Ne seni,  Ne de gözyaşlarımı,  Bu kara isle boğamam. Ama içiyorum işte... ...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/biliyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım Yine', 'aglarim-yine-buruk-sevinc-onyd6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünürken ağladım yine, 

Yarama bastın gülüm gidince, 

Ne olacaktı sen beni sevince? 

Kime dert yanayım Fatma ağlarım yine.

Hayal ettim seni uzaktan da olsa, 

Ne çıkardı kalbin benimle kalsa, 

Cankuşum olup canımı alsa, 

Kime dert yanayım Fatma ağlarım yine.

Karanlık üstüme dert gibi çöktün, 

Rüyamda Fatma kalbimden öptün, 

Sevda çiçeğimi kökünden söktün, 

Hep ağladım Fatma ağlarım yine.

Gün oldu beraber gezdik yollarda, 

Gün oldu beraber olduk kırlarda, 

Şimdi bıraktın beni karanlıklarda, 

Yalnızım yalnızlıkta Fatma ağlarım yine.

Öyle zaman geldi sevinçten uçtum, 

Öyle zaman geldi hayaller kurdum, 

Seni sevdim ya, aşkımdan korktum, 

Sevda neyime Fatma ağlarım yine.

Mutluluk artık benim için bitti, 

Kaderim, sevdiğim elimden gitti, 

Vurduğun son darbe ölmeme yetti, 

Sen de vur Çekik Gözlüm ağlarım yine.', 'Seni düşünürken ağladım yine,  Yarama bastın gülüm gidince,  Ne olacaktı sen beni sevince?  Kime dert yanayım Fatma ağlarım yine. Hayal etti...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aglarim-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geç Olacak', 'cok-gec-olacak-buruk-sevinc-mllax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittin onunla mutlu olmaya, 

Korktun benimle yalnız kalmaya, 

Oysa geleceksin gönül almaya, 

Fatma o zaman çok geç olacak.

Sensiz yaşamak haram oldu bana, 

Unutamam seni, son sözüm sana, 

Gerçeği anlayıp dönünce bana, 

Fatma o zaman çok geç olacak.

Ne yapsan haklısın birşey diyemem, 

Eğer geri dönersen inan sevemem, 

Bunu biliyorsun, git de diyemem, 

Geri döndüğünde Fatma çok geç olacak.', 'Gittin onunla mutlu olmaya,  Korktun benimle yalnız kalmaya,  Oysa geleceksin gönül almaya,  Fatma o zaman çok geç olacak. Sensiz yaşamak ha...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cok-gec-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Yolu', 'gurbet-yolu-buruk-sevinc-odl8x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gurbet yolu gariplerin yoludur, 

Gönül yere kalbim hicran ile doludur, 

Ayrı düştüm çekik gözlü yarimden, 

Kalbim yara, içim hasret doludur.

Gözlerimde kanlı yaşlar sel oldu, 

Verem oldum kalp, ciğerim söküldü, 

Yalnız kaldım yine boynum büküldü, 

Çekik gözlü yarimden uzak düştüm düşeli.', 'Gurbet yolu gariplerin yoludur,  Gönül yere kalbim hicran ile doludur,  Ayrı düştüm çekik gözlü yarimden,  Kalbim yara, içim hasret doludur....', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gurbet-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmek Yok', 'vazgecmek-yok-erdal-gisi-fmyek', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'güneşin bağrını hedef alan ok

gitse küle döner gitmese küle

...

vazgeçmek bu işin kaderinde yok...', 'güneşin bağrını hedef alan ok gitse küle döner gitmese küle ... vazgeçmek bu işin kaderinde yok......', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vazgecmek-yok-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Kızları', 'koy-kizlari-buruk-sevinc-9zjo2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaz gelince yaylalarda dolaşır, 

Hem çayırla hem çimenle uğraşır, 

Kış gelince soğuk suya karışır, 

Sevdalı köy kızları.

Giyinirler, allanırlar, 

Bin naz ile sallanırlar, 

Kapılara yaslanırlar, 

Güzelim köy kızları.

Çıkar yaylalarda gezerler, 

Soğuk soğuk su içerler, 

Orak alıp ot biçerler, 

Sevdalı köy kızları.

Dertli aşığım, gözümde, 

Yalanım yoktur sözümde, 

Aşkı buldum köy kızında, 

Sevdalım köy kızları.', 'Yaz gelince yaylalarda dolaşır,  Hem çayırla hem çimenle uğraşır,  Kış gelince soğuk suya karışır,  Sevdalı köy kızları. Giyinirler, allanır...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/koy-kizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-buruk-sevinc-92wyj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine başım dumanlı, 

Canım sıkılıyor anne.

Her geçen gün seni daha çok özlüyorum.

Yanımda olmanı daha çok istiyorum anne.

Bağrına basmanı, saçlarımı okşamanı istiyorum.

Şimdiye kadar hiç okşamadın

Ama yine de özlüyorum.

Ve pamuk ellerinden öpüyorum.

Gözyaşlarımı siliyorsun, 

Ellerini uzatıp ''ağlama yavrum'' diyorsun, 

İçin ağlamaklı...

Ve mutlu bir hüzünle uyanıyorum, 

Uyanmak istemediğim rüyamdan.

Seni çok seviyorum, 

Biliyorum sen de beni...

Ama benim kadar değil.

Seni çok özlüyorum anne, 

Biliyorum sen de beni...

Ama benim kadar değil.

Hiç yanımda olmadın, 

Ama hep yanımda kalmanı istiyorum anne.

Seni nasıl sevdiğimi bilmeden seviyorum, 

Sen beni hiç sevmesen de anne...', 'Yine başım dumanlı,  Canım sıkılıyor anne. Her geçen gün seni daha çok özlüyorum. Yanımda olmanı daha çok istiyorum anne. Bağrına basmanı, s...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anne-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Masalımız', 'bizim-masalimiz-buruk-sevinc-nxfbw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu, bizim sevdamızın masalı, sevgilim.

Bu, bitip tükenmeyen masal...

Yalnızlığın ve ayrılığın anlatıldığı, 

Gözyaşının hiç eksik olmadığı, 

Hasretin dolu dizgin yaşandığı, 

Aşkın en alıcı yanı...

Bazen, sonsuz mutluluğa dalıp giden, 

Bazen, bir salyangoz gibi kabuğuna çekilen, 

Ama her şeyden en önemlisi, 

Yalnızlığı anlatan, 

Seni anlatan, 

Anlatırken ağlatan bir masal.

İşte bu, bizim sevdamızın masalı...

Her sayfası hicranla dolan, 

Noktasına, virgülüne dikkat edilmeyen, 

İmla hatalarıyla dolu olan bir masal.

İşte bu, bizim sevdamızın masalı sevgilim.

Bizim aşkımızın masalı, 

Yanıp tutuşan iki kalbin masalı, 

İşte bu, bizim masalımız sevgilim.

Bu bizim aşkımızın masalı...', 'Bu, bizim sevdamızın masalı, sevgilim. Bu, bitip tükenmeyen masal... Yalnızlığın ve ayrılığın anlatıldığı,  Gözyaşının hiç eksik olmadığı,  ...', ARRAY['Türk Edebiyatı','Şiir','Buruk Sevinç']::text[], 8.5, '{"poet":"Buruk Sevinç","poet_slug":"buruk-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bizim-masalimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dostun Ardından', 'bir-dostun-ardindan-timur-i-lbegi-wlk6m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Durmadan dönüyor dünya, 

Martılar ölüyor kuytularda, 

Kardelenler üşüyor dağbaşlarında, 

Gülen yüzler resimlerde artık, 

Takvimlerde son yaprakların hışırtısı...

Bölünerek çoğalıyor çaresizlik, 

Ve bir bir sönüyor yıldızlar, 

Yarasalar uçuyor, köpekler dolanıyor, 

Yollar yalnızlığımı haykırıyor

hep bir ağızdan...

Katrankarası kabuslar arasındayım şimdi

Damarlarımdan yorgunluk akıyor

Boğazımda düğümleniyor dostluğa dair sözler

Ayrılık bir adım ötede, 

Mihrican gidiyor bu gece, 

Boğuluyorum....

20.12.2001', 'Durmadan dönüyor dünya,  Martılar ölüyor kuytularda,  Kardelenler üşüyor dağbaşlarında,  Gülen yüzler resimlerde artık,  Takvimlerde son yap...', ARRAY['Türk Edebiyatı','Şiir','Timur İlbeği']::text[], 8.5, '{"poet":"Timur İlbeği","poet_slug":"timur-i-lbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-dostun-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek Yildizi', 'dilek-yildizi-hakan-ocak-u4ku2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gece olusunda yildizlara bakip karanliga dogur konusurum.

Umarimki gordugum binlerce yildizlarin icinden bir tanesi beni dinler ve dilegimi yerine getrir.

Her gece yildizlara ayni soruyu sorarim. 

Bana cesaret vermelerini dilerim

Cesaret isterimki ona olan sevgimi anlatabileyim, 

bana cektirdigi aciyi dile getireyim.

Cesaret isterimki onun gozlerinin icine bakabileyim, 

askimi itiraf etmeden once o hasret kaldigim ellerini tutabileyim.

Bunca yildizlarin icinde vardir elbet bana cesaret, guc verebilecek bir yildiz.

Ve hala bu umutla her gece yildizlara bakip saatlerce konusurum.

Her gece yeni umutla cikarim disariya, bu gece bulacagim ve yarin askimi itiraf edecigim.', 'Her gece olusunda yildizlara bakip karanliga dogur konusurum. Umarimki gordugum binlerce yildizlarin icinden bir tanesi beni dinler ve dileg...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ocak']::text[], 8.5, '{"poet":"Hakan Ocak","poet_slug":"hakan-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dilek-yildizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımın içi', 'canimin-ici-yusufcan-koksal-r8s3t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yanımda yoksun ya, olsun 

ben var ederim seni istediğim zaman 

önce sesin gelir aklıma, seni düşünürüm 

zaten sensin benim gerçeğim gerisi yalan, 

düşünürüm seni haftanın her günü 

fark etmez ha Cuma ha Cuma ertesi 

hayal ederim o döndüğün günü 

sarılırım bırakamam gelince canımın içi, 

arasıra düşer aklıma 

buralardan kaçıp yalnız kalmak fikri, 

ama ne yalan söyleyeyim 

seninle yalnız kalmak, 

seninle nefes almak istiyorum, 

içim pamuklara sarılmış gibi, 

rüzgara bırakılmış gibi rahat 

cocuklar gibi guluyor gözlerimin içi 

sen yanımdayken canımın içi, 

sen yanımdayken canımın içi 

uçsuz bucaksızlara uzanıyorum 

anlatabilmem lazım sana bendeki seni 

ama kelimelere sığdıramıyorum 

gökyüzü yeterince uçsuz değil 

yıldız gözümü almıyor sen gibi 

bulutlar acıtıyor tenimi 

ellerini ver canımın içi, 

önce sesin gelir, seni düşünürüm 

bak yine güldüm çocuklar gibi 

ne yalan söyleyeyim canımın içi 

seni yaşamak gibi seviyorum..', 'yanımda yoksun ya, olsun  ben var ederim seni istediğim zaman  önce sesin gelir aklıma, seni düşünürüm  zaten sensin benim gerçeğim gerisi y...', ARRAY['Türk Edebiyatı','Şiir','Yusufcan Köksal']::text[], 8.5, '{"poet":"Yusufcan Köksal","poet_slug":"yusufcan-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/canimin-ici-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Adım', 'i-lk-adim-enver-gokce-dn9ze', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir mermi de benden aslanım, 

Bir mermi de benden.

Bir mermi de benden zafer topları

Mukaddes namlular! 

Daha gelmesin mi bahar, 

Daha gülmesin mi ağlayanlar? 

Yıllardır kan içinde, sargı içinde

Unuttunuz mu

Sevmesini şakalaşmasını? 

Çekik gözlüler, 

Kıvırcık saçlılar, ablak yüzlüler! 

Küller mi saz beniz etti sizi

Yabani güller, dost bakışlar, otlu çiçekler! 

Ve sizler: 

Adana, Aras pamuğu kadar

Sevdiğim yüzler! 

Yayla türkülerim kadar

Memleketlilerim kadar

Sevdiğim yüzler! 

Altıya mı değdi yaşlarınız

Otuz dokuz doğumlu çocuklar? 

Ömrünüz, gözleriniz, uykularınız

Sığınaklarda geçti harp boyunca.

Oylum oylum ateşleri gördünüz mü, 

Cepheden dönenleri sordunuz mu? 

Tanır mısınız

Ay nedir, gün nedir, elma nedir? 

Güneşi gözlere doldurmak güzelken

Hey küçük kardeşler hey

Görün ne hale koydular dünyamızı.

Şimdi zafer topları gürlüyor

Avrupa''da.

Ve deniz ötesi kıtalardan

Şarkılar...

Şimdi kazaska oynuyor Avrupa.

Şimdi silah yerine bayrak tutanlar...

Hiçbirini tanımadığımız, 

Oyunlarını bilmediğimiz

Mişiganlılar, Oksfortlular, Ukranyalılar

Şimdi, göz aydın etme zamanıdır.

Yeni bir dünya doğuyor.

Şorul şorul giden kan pahası.

Müjdeler, müjdeler olsun

Yeni bir dünya doğuyor

Zincir seslerinden

Verem basillerinden uzakta...

Büyük ölülerini bağrına basıp

Yaralı insanlarımız

Kahramanlarımız konuşuyor: 

''Benim olsun, senin olsun, bizim olsun, 

Hani kardeşlerimiz vardı ya

Bu dünyada.

-Kız kardeşlerimiz, annelerimiz, şairlerimiz-

Dumdum kurşunuyla vursalar da

Her zaman böyle döğüşeceğiz: 

Gırtlak gırtlağa, diş dişe, tank tanka

Demokrasi için, 

Eşitlik ve hürlük uğruna''

Bir mermi de benden aslanım

Bir mermi de benden

Bir mermi de benden

Zafer topları, mübarek namlular!', 'Bir mermi de benden aslanım,  Bir mermi de benden. Bir mermi de benden zafer topları Mukaddes namlular!  Daha gelmesin mi bahar,  Daha gülme...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"enver-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/ilk-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Güzel', 'seninle-guzel-bahadir-atay-zmm2p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşler seninle güzel, 

Her sabah unutsam bile.

Hayat seninle güzel, 

Sadece bir gün olsa bile.

Güneş seninle parlak, 

Vakit gece olsa bile.

Ve sevgilim

Aşk seninle güzel, 

Seninle değilken bile.', 'Düşler seninle güzel,  Her sabah unutsam bile. Hayat seninle güzel,  Sadece bir gün olsa bile. Güneş seninle parlak,  Vakit gece olsa bile. ...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seninle-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın Gizem', 'adin-gizem-huseyin-cayikli-dsg6h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şimdi anladım ki

seni sensiz yaşadıgı mı? 

anladım ki mutlu olamıyorum 

anladım ki

sabahları sensiz uyanmanın ne kötü oldugunu.

bir insanın seni unutturamadıgını 

anladım...

kor ayazda ki rüzgarda adının ne kadar sır 

yani Gizem oldugunu anladım...

seni üzdüğümü anladım

hataları mı sorguladım...

anladım herseyinle unutamadıgımı anladım

bir yolu olmalı

bir nedeni olmalı eski günlerin

bir nedeni işte 

bu olmalı

unutamadım 

biliyorum

adının hala Gizem oldugunu...', 'şimdi anladım ki seni sensiz yaşadıgı mı?  anladım ki mutlu olamıyorum  anladım ki sabahları sensiz uyanmanın ne kötü oldugunu. bir insanın ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/adin-gizem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Dansı', 'siirin-dansi-bahadir-atay-xr6vk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benimle dans edermisiniz, 

Sabahlara kadar gözgöze

İsterseniz mutluluk olurum, 

İsterseniz gözyaşı 

Uçurabilirim sizi

Uçsuz bucaksız gökyüzüne

Benimle dans edermisiniz

Soluk soluğa elele

İsterseniz aşkı tadarız

İsterseniz hüznü, acıyı

Tıpkı masallardaki gibi

Kafdağının ardına gideriz sizinle

Benimle dans edermisiniz

Yavaşca ve sessizce

Ve ben son sözümü söyleyince

Geri alırız zamanı, tekrar yaşamak için

Tekrar varabilmek için

Kelimelerin bittiği yere', 'Benimle dans edermisiniz,  Sabahlara kadar gözgöze İsterseniz mutluluk olurum,  İsterseniz gözyaşı  Uçurabilirim sizi Uçsuz bucaksız gökyüzü...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/siirin-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemre', 'cemre-tevfik-mengulluoglu-iesp1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cemre düşer toprağa

                     Isınır toprak, patlar tomurcuklar bir bir...

                     Gök gürler, yağmur oluk oluk boşalır, 

                     Cemreyle bütünleşip

                     Usul usul

                     Bir ceylanın kalbine damlar

                     Ceylan doğrulur...

                     Bir ağıt kopar gökyüzünden

                     Doğrulur  toprağın altındakiler 

                     Yakarlar güneşi

                     Toprakta filiz açar

                     Çocukların kalbinde, gençlerin yüreğinde, 

                     Dudaklarında, Türkülerinde

                     Dört köşesinde Vatanın

                     İlk baharın toprağa ılk düşen cemresiydi Yusuf

                     Sevdasının tohumlarını 

                     Kalplerinin derinliklerine

                     Düşürdü Vatanın

                     Yalnızlığı ona ulaşamayacak kadar 

                     Çaresizdi...', 'Cemre düşer toprağa                      Isınır toprak, patlar tomurcuklar bir bir...                      Gök gürler, yağmur oluk oluk boşa...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cemre-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyeceğim Gel', 'diyecegim-gel-hakan-sengun-5x6rw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dayanamadın gülüm

Direnemedin.

Kader yıkarken düşlerini

Ona dur diyemedin, 

Neden? 

Yoksa benmiydim seni böylesine kahreden.

Sana anlattığım

O umut ağacının yanındayım şimdi

Yaşamasamda hayattayım

Anlaki hala ayaktayım.

Umutlarıyla beraber 

Sararmış sevgilim benim.

Mevsim bahara çalmış

Yağmur hergün yağarmış buralara

Sen boşuna kurumuşsun.

Bilsemki beni duyuyorsun güzelim

Diyeceğim gel, beraber yeşerelim

Bahar yağmurlarında.

Yağmurlardan uzakta

Sararmış sevgilim benim.', 'Dayanamadın gülüm Direnemedin. Kader yıkarken düşlerini Ona dur diyemedin,  Neden?  Yoksa benmiydim seni böylesine kahreden. Sana anlattığım...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/diyecegim-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İstiyorsun Diye', 'sen-i-stiyorsun-diye-hakan-sengun-otgs8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen istemiyorsun diye; sevmeyeyimmi? 

Her ardını dönüp gidişinde 

Ben bakakalıyorum.

Her yoluma çıkışında

Ayağım sendeliyor, kapaklanıyorum yere.

Gözgöze gelmemek için

Vitrinlere dönüyorum yüzümü

Gözlerim gözlerine değmesin diye

Sen geçip gidiyorsun.

Sen istemiyorsun diye; sevmemeyimmi? 

Her gözümü kapayışımda 

Seni hayal ediyorum.

Senin gittiğin yer oluyorum

Her duruşumda.

Bir yudum suyun yanında

Senide hayal ediyorum

Bir yudumda içmemek için seni

Sabahı zor ediyorum.

Sen istemiyorsun diye; sevmeyeyimmi? 

Kör kurşunlara yürüyorum

Sonumu bile bile.

Yasak levhalarının arasında

Gözüm kapalı yürüyorum.

Canımı yakmıyor artık

Arkası vuran ayakkabılarım.

Dayanılmaz acılarım

Duruluyor her çıkışımda yoluna.', 'Sen istemiyorsun diye; sevmeyeyimmi?  Her ardını dönüp gidişinde  Ben bakakalıyorum. Her yoluma çıkışında Ayağım sendeliyor, kapaklanıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-istiyorsun-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz Büyüdüm Sadece', 'biraz-buyudum-sadece-hakan-sengun-9vevw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biraz daha büyüdüm sadece

Yokluğun koymadı bana.

Geceleri tek başıma; 

Korkmamayı öğrendim karanlıktan.

Kendi ellerimden tutmayı

Hayata sıkı sıkı sarılmayı

Rastlantı sevdaların, sahiplenilen kayıp aşkların

Serseri gidişlerin, yalan dönüşlerin

Kaçamak sevişmelerin

Ve bir gecelik düşlerin acısını öğrendim sadece.

Anlaki yokluğun koymadı bana.

Tek kişilik demlediğim çayımı

Tek şekerli içiyorum.

Tek kişilik yatağımdan yorgun kalkmıyorum artık.

Düşünmüyorum doğumgününü

Ne alayım, ne vereyim

Nasıl sarılayım, nasıl öpeyim

Anlaki yokluğun koymadı bana.

Sessiz günlerim benim

Şarkılarım hala aynı.

Yaşadığım mutluluklar; 

Şimdi sadece bir anı tozlu geçmişimden.

Birde tutmasa başımın ağrısı

Yoksa çoktan öğrendim

Sensiz ama seninle yaşamayı.

Anlaki yokluğun koymadı bana.', 'Biraz daha büyüdüm sadece Yokluğun koymadı bana. Geceleri tek başıma;  Korkmamayı öğrendim karanlıktan. Kendi ellerimden tutmayı Hayata sıkı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/biraz-buyudum-sadece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Bastı Gönlüme*', 'hasret-basti-gonlume-bayram-tunca-f3ldw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine hasret bastı şu hicranlı gönlüme

Hor görmeyin, ona gönlümü verişime

Hasretiyle sanki kırk parçaya ayrıldım

Bizleri ayıranlara çok mu çok darıldım

Onu görmek istiyor hicranlı ela gözlerim

Hasretinden ciğerimi akkorlarla közlerim

Çook yalvardım, makes bulmadı sözlerim

Bak kan çanağına döndü şu ela gözlerim 

Her daim, ufuklardadır hicranlı gözlerim

Gece gündüz yetim gibi yolunu gözlerim

Eğer, onu görmeden kapanırsa gözlerim

Bilin ki cennette dahi, hep onu gözlerim

O sevdalı, her an hülya ve rüyamızdadır

O bizim yüreğimizin değişmez sultanıdır

Başımızın tacı, dertlerimizin biricik ilâcıdır

Biliyorum, o da her an bizler için duacıdır

Ondan ayrı yaşamak ölümden daha acıdır

Bu sanki, doğum öncesindeki bir sancıdır

Dünya han, insanlar da geçici bir hancıdır

İnşallah bu hasretimiz, geçici bir sancıdır

Ah şu fırtınalı rahmetin oluşturduğu çaylar

Elbette ki bir gün geçecektir bu çileli aylar

Çaylar, deryasına ulaşmak için nasıl çağlar

Şair de deryasına kavuşmak için öyle ağlar

31.03.2002-12.45', 'Yine hasret bastı şu hicranlı gönlüme Hor görmeyin, ona gönlümü verişime Hasretiyle sanki kırk parçaya ayrıldım Bizleri ayıranlara çok mu ço...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hasret-basti-gonlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağrı ve Sadakat', 'agri-ve-sadakat-bayram-tunca-8m0dy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağrılar vardır, Ağrı Dağından da ağır

Yükler vardır, tüm dağlardan da ağır

Ağrılar vardır, bir ömür boyu bağırtır

Gece gündüz imdat çığlıkları çağırtır

Yüreklerde sancı, başlarda müthiş ağrı

Sevdalımızın volkan gibi yanıktır bağrı

Ömür boyu inlese de bitmez ki ağrıları

Hasreti bitse, belki biraz azalır ağrıları

Kaldırmaz ki bu baş, bu kadar ağırlığı

Çekemez ki bu kalb, bu kadar sancıyı

Zaten, her bir yangın artırıyor, bu sancıyı

Dilerse, ancak Mevlam dindirir bu sancıyı

Sancı vardır, doğum sancısından da ağır

İstersen, sen bir ömür boyu her an bağır

Eğer ki dostlarda olmuşlarsa, sanki sağır

Ağrı, kasırga gibi yıkıcı, lav gibi yakıcıdır

O zaman yanarsın gece gündüz cayır cayır

Zaten yanmıyor mu alemi İslâm cayır cayır

Zaten yanmıyor mu halkımız da cayır cayır

Onun için kendi dertlerini unutmuştur şair

Eğer bulamazsan başka dost, bu şairi çağır 

O saçları adedince, canını vermeye hazırdır

Kuşlar gibi kanat çırparak gelmeye hazırdır

Gece gündüz her an, emirlerinize amadedir

Nasıl güzellikler paylaşılırsa, mutluluk artar

Ağrılar ve girdaplı sancılar paylaşılırsa azalır

Gerçek dava adamı olanlar bundan haz alır

Ateşte yansalar dahi gönülleri gül gülistandır

Ben yanmışım zaten, bari başkaları yanmasın

Ben çoktan razı olmuşum, akkorlarda yanmayı

Vücudum yanarken gönlüm gül gülistan olsun

İlke edinmişiz, her insanın imanını kurtarmayı

www.baysab.com/04.04.2002-16.25', 'Ağrılar vardır, Ağrı Dağından da ağır Yükler vardır, tüm dağlardan da ağır Ağrılar vardır, bir ömür boyu bağırtır Gece gündüz imdat çığlıkla...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/agri-ve-sadakat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Rüyanın Öyküsü-1-', 'bir-ruyanin-oykusu-1-bayram-tunca-gu0z2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüyada bile görmeye hasret kalmıştım

Hasretinle çok tatlı hülyalara dalmıştım

Kaç gece susuz yatıp, susuz kalkmıştım

Bugece, hasretinle az uykuya dalmıştım

Senle cennet numun bir yerde buluştuk

Sanki de, sevinçten uçan bir çift kuştuk

Yılların hasretini gidermek için konuştuk

Nice güzelliği, has bir bahçede paylaştık

Gidilecek bir menzili, karadan gidecektik

Sarp ve dikenliydi, yürünecek olan yollar

Etrafımızı da sarmıştı amansız düşmanlar

Ne kadar çetin de olsa, bu yolu aşacaktık

Sen bana geriye dön ikazında bulundun

Ben ise, aradıklarımı, sende bulmuştum

Dön desen de, hiç geriye döner miydim

Sen önden ben arkadan ilerdik o yoldan 

Düşmanlar sarmıştı, dört bir yanımızdan

Karadan ilerleme imkanı hiç kalmayınca

O Cennet gibi gizemli, vadiden geçerken

O menzile ulaşmak için daldık bir ırmağa

Irmağın, sağ ve solunda düşmanlar dizilmiş

Oradan geçerken yakalama planı düzülmüş

Fakat, önlerinden geçerken sizi göremediler

Bana gördüklerinden, bana doğru yöneldiler

Onlardan kaçayım derken, bu sefer oldum sizden

Siz cennet ırmağından yüzerek deryaya ulaşırken

Bense, çalı/çırpıya takılıp, o deryaya ulaşamadım

Seninle bir daha buluşamadım o telaşla uyandım

B. Tunca/07.04.2002-17.55

Not: 06.04.2002 cumartesi günü gecesinde

      gördüğüm bir rüyanın öyküsünün şiiri', 'Rüyada bile görmeye hasret kalmıştım Hasretinle çok tatlı hülyalara dalmıştım Kaç gece susuz yatıp, susuz kalkmıştım Bugece, hasretinle az u...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-ruyanin-oykusu-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Darbeleri', 'hayatin-darbeleri-bayram-tunca-wp3sc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağ olsaydı dayanmazdı bu darbeleri 

Hiç hattı hesabı yoktu o günden beri 

Düşündüm hayli, acep neydi nedeni 

Hayat darbeleri delik deşik etti beni 

Tez büktü belimi; şu hayatın darbeleri

Belirdi saç sakalda ihtiyarlık alametleri

Çözüldü darbelerden dizlerimin bağları

Bilmez kimse ne çektiğimi ezelden beri

Aah şu darbeler darbeler darbeledi beni 

Darbeli makkap gibi delik deşik etti beni 

Şu hayatın darbeleri mevti çok arttı beni 

Ne hikmetse Mevlam çileli yaratmış beni

Daha kabuk bağlamadan kanadı yaralarım

Kırıldı ufacık yaşta her iki kolum kanadım

Yıkıldı dostlarım tarafından gönül sarayım

Düştüm dermansız derde kime yalvarayım

Gel gayri gel; ey benim vefalı dostum gel

Bak! dostlarım dahi oldular sanki birer el

Dayanmaz oldu hayatın darbelerine bu bel

Akan gözyaşlarım sanki de oldu bulanık sel

Gelip geçmiş en çileli şairlerden biri de benim 

Yıllarca gece gündüz hep sızladı durdu kalbim

Geç anladım kaderimmiş bütün bu çektiklerim

Sitem etsem de dostlarıma; halimi şükrederim

10.04.2002-08.35 

NOT:Uğradığım haksızlıklar neticesinde 

duygularımı türküye yatkın bir dille 

şiir şeklinde anlattığım bir öykümdür', 'Dağ olsaydı dayanmazdı bu darbeleri  Hiç hattı hesabı yoktu o günden beri  Düşündüm hayli, acep neydi nedeni  Hayat darbeleri delik deşik et...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hayatin-darbeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulduktan Sonra Arama', 'bulduktan-sonra-arama-abdurrahim-karakoc-r2wyx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Omuzumda sevda yükü 

Yollarda Seni aradım. 

Beste beste, türkü türkü 

Tellerde Seni aradım. 

Girdim yeşilden sarıya 

Sordum ölüye, diriye 

Çiçeği verdim arıya 

Ballarda Seni aradım. 

Aşk yalımı girdi cana 

Gönlüm döndü gülistana 

Gece-gündüz yana yana 

Küllerde Seni aradım. 

Yorulup demedim, yeter 

Hasretin gözümde tüter 

Kerem''den, Mecnun''dan beter 

Çöllerde Seni aradım. 

Bahçem çiçek, bağım gazel 

Birleşir ebetle, ezel 

Ayırmadım çirkin, güzel 

Kullarda Seni aradım. 

Ulaşmak için rahmete 

Katlandım bin bir zahmete 

Karışıp söze, sohbete 

Dillerde Seni aradım. 

(Suları Islatamadım)', 'Omuzumda sevda yükü  Yollarda Seni aradım.  Beste beste, türkü türkü  Tellerde Seni aradım.  Girdim yeşilden sarıya  Sordum ölüye, diriye  Ç...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bulduktan-sonra-arama-seni-aradim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rahmet', 'rahmet-necip-fazil-kisakurek-p7s2n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaradan, rahmetini kahrından üstün saydı; 

Ne olurdu halimiz, gözyaşı olmasaydı?', 'Yaradan, rahmetini kahrından üstün saydı;  Ne olurdu halimiz, gözyaşı olmasaydı?...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/rahmet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Olsun', 'haberin-olsun-sukru-soyarslan-x65cf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sana son mektup, son seslenişim 

Bir daha aramam, haberin olsun. 

Sana son yalvarış, son serzenişim 

Bir daha aramam, haberin olsun. 

Bunca zamandır hep ben yazdım, çizdim 

Aşkın için; deli, divane gezdim. 

Yeter artık! Ben, bu canımdan bezdim 

Bir daha aramam, haberin olsun. 

Her günüm seni düşünmek, düşlemek 

Bir gün gelir, arar diye beklemek. 

Acaba..boşuna mı, bunca emek? 

Bir daha aramam, haberin olsun.', 'Bu sana son mektup, son seslenişim  Bir daha aramam, haberin olsun.  Sana son yalvarış, son serzenişim  Bir daha aramam, haberin olsun.  Bun...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haberin-olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mim', 'mim-harun-gelgel-fcylb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavi hüzünler girdabında 

Karanlığa mekik dokur acılar, 

Sadece bir yol var 

Sadece bir yol ulaşmakta aydınlığa, 

Toz duman olur dağlar 

Kızıl alevinde sevdanın, 

Biçare gözler intizarda 

Denizde mehtap ve yakamoz 

Cim karnında arsız bir nokta 

Ve sonra bu gecenin hikayetine dahi 

Nihayet taze bir mim konmakta.', 'Mavi hüzünler girdabında  Karanlığa mekik dokur acılar,  Sadece bir yol var  Sadece bir yol ulaşmakta aydınlığa,  Toz duman olur dağlar  Kız...', ARRAY['Türk Edebiyatı','Şiir','Harun Gelgel']::text[], 8.5, '{"poet":"Harun Gelgel","poet_slug":"harun-gelgel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Hasret', 'kucuk-hasret-sinan-potur-pfn79', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kavuşacagız diye hasretim küçük 

Üzüntülerim şimdi daha az

Çünkü hasretim küçük 

Üşümem bile daha az

Kelimeler bile daha çok 

  Haydi bekleme 

  Ay ışıgını, dogan güneşi

  Sabırsızlan, sabırsızlanki 

  Rüyalarımda önce gelesin 

  Ellerini uzat bana, uzatki

  Tutamasamda hasretin küçük olsun', 'Kavuşacagız diye hasretim küçük  Üzüntülerim şimdi daha az Çünkü hasretim küçük  Üşümem bile daha az Kelimeler bile daha çok    Haydi beklem...', ARRAY['Türk Edebiyatı','Şiir','Sinan Potur']::text[], 8.5, '{"poet":"Sinan Potur","poet_slug":"sinan-potur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kucuk-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölme Zamanı', 'olme-zamani-hakki-hakan-kaya-31nhu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat gülünce güzel

Acı kahreder insanı

Ağlamayı bırak

Şimdi gülme zamanı

Sevgi çözer herşeyi

Nefret kurutur insanı

Kaçmak çare değil

Şimdi sevme zamanı

Ayrılık ölümden beter 

Gurur mahveder insanı

Zaman geri dönmez 

Şimdi gitme zamanı

Biter birgün umutlar

Çaresizlik tüketir insanı

Kapanır bütün kapılar

Şimdi ölme zamanı', 'Hayat gülünce güzel Acı kahreder insanı Ağlamayı bırak Şimdi gülme zamanı Sevgi çözer herşeyi Nefret kurutur insanı Kaçmak çare değil Şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olme-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Bilmediğim Filistinli Kıza', 'adini-bilmedigim-filistinli-kiza-deral-baran-olqpq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adını bilmediğim 

Filistinli kıza 

Masumiyetin 

Minik ellerinle

Yüreğimi tarumar ederken

Gözyaşların

Kudüs’ü

Yasa boğuyordu.

Yürekler taş kesilmişti

Tüm insanlık

Sağır ve kör...

Ve

Yağmalanıyordu pervazsızca

Kutsiyet.

Feryatlar arşa sığmıyordu.

Cesaretimi

Narin, kırılgan

Bedenine terk etmiştim.

Uykularım kasırgaya dönüştüğünde

Yüzüme çarpan

Ramallah’tı Filistin ‘di

İbrahim ‘i yüzler arıyordum

“Utanın” diyordu

günahsız yüreğin

bedeninle bütünleşerek.

Utan! ey insanlık

Ve.

Uyanın

Bu onulmaz acılara

Ortak olmak için cesaretimizi

Koca gövdelerimize ekleyelim

Öpeceğiniz her çocukta

Adını bilmediğim

Filistinli cesur kızın

Feryadıyla irkilin

Adlarını bilmediğimiz

Masum, günahsız

Yürekli çocukların

Annesi  olun

Babaları gibi ölün

Ve

İnsanlığın haysiyeti için

Utanın...

5 nisan 2002 ist', 'Adını bilmediğim  Filistinli kıza  Masumiyetin  Minik ellerinle Yüreğimi tarumar ederken Gözyaşların Kudüs’ü Yasa boğuyordu. Yürekler taş ke...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/adini-bilmedigim-filistinli-kiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-deral-baran-8xfvd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kabaran bir denizdi içtiğim su

Zaman bir bulutla yolculuktaydı

Bütün bir gece keder yükledim

Yedi renk bir gergefin üzerine 

Gitmekteydi bütün yolcular

Batmak için rotasını ölüme 

Çevirmiş geminin hüzünlü sürüklenişi

Bir yıldız kaydı yakamozlar üstüne

Buluşma noktasında ellerim seni ararken 

Devrildi dünya uyuduğum çınarın üstüne

Bir uğultu sarstı ruhumu 

Mutlulukla gülümsedim gördüğüm rüyaya

09 nisan 2002', 'Kabaran bir denizdi içtiğim su Zaman bir bulutla yolculuktaydı Bütün bir gece keder yükledim Yedi renk bir gergefin üzerine  Gitmekteydi büt...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ruya-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-seref-gunenc-qfkfk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seninle yildizlarda olmak isterdim

Gözden uzak

Göze gelmeyelim diye, 

Seninle  güneste olmak isterdim

Seni benden, beni senden

Sogutmasinlar diye.', 'Seninle yildizlarda olmak isterdim Gözden uzak Göze gelmeyelim diye,  Seninle  güneste olmak isterdim Seni benden, beni senden Sogutmasinlar...', ARRAY['Türk Edebiyatı','Şiir','Seref Günenç']::text[], 8.5, '{"poet":"Seref Günenç","poet_slug":"seref-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seninle-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Vefasız', 'gel-vefasiz-tarik-armagan-y3d9k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gerçekten inanıp sevseydin beni

Böyle sabahları beklermiydin hiç

Çoktan yanımda olurdun, çoktan

Gece üç beş nöbetlerine itmezdin beni

Sensiz kaldığım ilk günden beri

İçimde bir umut muslata dair

Akşamları İmzaladım göz yaşlarınla

Seni aramıyor, seni sormuyorsam

Bu senden vaz geçtim demek değil 

Bir daha böyle sevecek olsam 

Bir kalemde silerdim seni', 'Gerçekten inanıp sevseydin beni Böyle sabahları beklermiydin hiç Çoktan yanımda olurdun, çoktan Gece üç beş nöbetlerine itmezdin beni Sensiz...', ARRAY['Türk Edebiyatı','Şiir','Tarık Armağan']::text[], 8.5, '{"poet":"Tarık Armağan","poet_slug":"tarik-armagan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gel-vefasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yinemi Ben', 'yinemi-ben-mustafa-karamelek-nhflk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir inceden

Usuldan, usuldan

Paslı bir hançer yanaşıyor

Sol yanımdan

Can alacak tatlı canımdan

kan akıtacak al kanımdan

Köşkler yapacak vefasızlar

Viran olmuş hanımdan

Vay başıma küller başıma

Felek su katacak yine

Tatsız aşıma

Gözün kör olsun sevda

Yinemi ben', 'Bir inceden Usuldan, usuldan Paslı bir hançer yanaşıyor Sol yanımdan Can alacak tatlı canımdan kan akıtacak al kanımdan Köşkler yapacak vefa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yinemi-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş', 'gunes-hakki-hakan-kaya-yz44f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hayatı anlamaya çalışma sakın

bir dehlizde kaybolur gidersin

ruhuna uydur kendini

böyle daha rahat edersin

iş, güç, para, pul

hiç önemli değildir

evli bekar yada dul

 tek hazinesi yüreğidir', 'hayatı anlamaya çalışma sakın bir dehlizde kaybolur gidersin ruhuna uydur kendini böyle daha rahat edersin iş, güç, para, pul hiç önemli değ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunes-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasılda Yaratırdık', 'nasilda-yaratirdik-mustafa-karamelek-obeiz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasılda bulurduk hazanın ortasında

Yazdan kalma bir günü

Henüz gazel olup savrulmamış

Yaprakları kurumamış ağaçları

Oturup altına iki sevgili gibi

Nasılda dertleşirdik değil mi  canım

Niyetlerimiz

Yüreklerimiz bir olduktan sonra

Nasılda bulurduk gezilecek günleri

Ara sokakları patika yolları

Yaratırdık zamanı

Olmazlığın kollarında çırpınırken

Bahardan günler getirirdik

Olmayacak zeminde

Olmayacak yerde

Özlemlerin sevdaların umutların

Sürme çeker gibi gözlerinden

Yaşanacak anlar yaratırdık

Nasılda kıskandırırdık

Nasılda çatlatırdık feleği ortasından

Nasılda sevdalıydık o zamanlar

Değil mi gül yüzlüm

Yaşıyorduk o zamanlar 

Öyle değil mi..', 'Nasılda bulurduk hazanın ortasında Yazdan kalma bir günü Henüz gazel olup savrulmamış Yaprakları kurumamış ağaçları Oturup altına iki sevgil...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nasilda-yaratirdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Karaydıki Gözlerimiz', 'oyle-karaydiki-gozlerimiz-mustafa-karamelek-719kh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle karaydı ki gözlerimiz

El ele göz göze

Gezerdik gün ortası

İşimize gelirdi

Ortalığın yağmur kar olması

Yan yana olurduk

Aynı şemsiye altında

Ya da

Saçaklardaki serçeler gibi

Saçak diplerinde dertleşirdik

Öyle karaydı ki gözlerimiz

Yeşertip umutsuzluklarımızı

Alış-veriş yapardık

Sokak satıcılarından

Simitçilerden kestanecilerden

Elma şekeri alırdık

Çocuksu duygularla

Cebimizdeki son kuruşumuzla

Öyle kara ki gözlerimiz

Nazara göze gelmeyi

Getirmeden aklımıza

Yaratırız, gülecek, gelecek

Ve 

Yaşanacak zamanı

Adımlarımızdan kısa kalır günler

Beşiksiz büyüttüğümüz sevgi sayesinde', 'Öyle karaydı ki gözlerimiz El ele göz göze Gezerdik gün ortası İşimize gelirdi Ortalığın yağmur kar olması Yan yana olurduk Aynı şemsiye alt...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oyle-karaydiki-gozlerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-hakki-hakan-kaya-76nxu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan bir kum tanesidir, okyanusun kıyısında 

Kaybolup gitmiş, binlercesinin arasında. 

Bugün kadar yakın, yarın kadar uzakta 

İnsan bir kum tanesidir, okyanusun kıyısında

Hakan Kaya', 'İnsan bir kum tanesidir, okyanusun kıyısında  Kaybolup gitmiş, binlercesinin arasında.  Bugün kadar yakın, yarın kadar uzakta  İnsan bir kum...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/insan-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canan Aşkı', 'canan-aski-mustafa-karamelek-vi9s6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni; dağın, taşın, cümle tabiatın

Bahar tutkusu gibi, 

Garip bir çiftçinin, 

Toprak aşkıyla sevdim.

Seni, İrem bahçesindeki bahçıvanın

Gonca gül tutkusu gibi 

Yüce dağlar delen Ferhat’ın

Şirin aşkıyla sevdim.

Seni, bir akşamcının

Kadeh tutkusu gibi

Karaya vurmuş balığın

Su aşkıyla sevdim.

Seni, bir ozanın sazındaki

Mızrabın tel tutkusuyla, 

Ve bağrındaki onmaz yaranın

Derman aşkıyla sevdim.

Seni Hak meclisindeki erenlerin

Dem tutkusu gibi

Sevmekten usanmayan bu canın

Canan aşkıyla sevdim...', 'Seni; dağın, taşın, cümle tabiatın Bahar tutkusu gibi,  Garip bir çiftçinin,  Toprak aşkıyla sevdim. Seni, İrem bahçesindeki bahçıvanın Gonc...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canan-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Ve Yaşam', 'olum-ve-yasam-hakki-hakan-kaya-2oyag', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gezinirken bahçemde ölümün melekleri, 

Can bulur bir çiçek komşu evin içinde. 

Silinirken gözümde, ömrümün ilk günleri, 

Çınlar arka sokak, çocukların sesiyle. 

Çakılırken son çivi, tahtdan tabutuma, 

Bir uçurtma yaparlar, arta kalanlar ile. 

Hazırlanırken bahçem çetin geçecek kışa, 

Taze bir bahar gelir karşıki mahalleye.

Hakan Kaya', 'Gezinirken bahçemde ölümün melekleri,  Can bulur bir çiçek komşu evin içinde.  Silinirken gözümde, ömrümün ilk günleri,  Çınlar arka sokak, ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olum-ve-yasam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birini Bekliyorum', 'birini-bekliyorum-mustafa-karamelek-qfjec', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Farzet ki karşında değilim

Seni seyretmiyorum 

Say ki

Saçlarında kızıllığını akşamın

Gözlerinde; 

Yeşilden siyaha dönüşünü seyrediyorum zeytinin.

Farzet ki karşında değilim

Aldırma bana takma kafana

Yokmuşum gibi davran

Say ki

Şırıl şırıl akan bir derenin kenarında

Dalları suya uzanmış bir selviyi seyrediyorum

Ya da masmavi bir denizde

Sefere çıkmış gemilere el sallıyorum..

Farzet ki karşında değilim

Bakışım sana değil

Hayranlığım değil

Say ki

Uykudaki bir bebeği seyrediyorum

Ya da ufka dalmışım

Bir canan bekliyorum.', 'Farzet ki karşında değilim Seni seyretmiyorum  Say ki Saçlarında kızıllığını akşamın Gözlerinde;  Yeşilden siyaha dönüşünü seyrediyorum zeyt...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/birini-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak', 'son-durak-hakki-hakan-kaya-0189x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Döküldü sırları gönül aynamın, 

Yılların aksini yansıtmaz oldu. 

Açıldı kapısı sonsuz diyarın, 

Vakit tamam diye bir ses duyuldu. 

Hiç hükmü yoktur orda, yelkovanın, 

Akrebin ardından koşamaz oldu. 

Önündeyim artık yorgun zamanın, 

Ardımdan koşmaktan o da yoruldu. 

Tahtadan atımı rüzgara salın, 

Beyaz kaftanımı toprakla karın, 

Anacım ardımdan ağlama sakın, 

Vardığım bu diyar, son durak oldu.

Hakan Kaya', 'Döküldü sırları gönül aynamın,  Yılların aksini yansıtmaz oldu.  Açıldı kapısı sonsuz diyarın,  Vakit tamam diye bir ses duyuldu.  Hiç hükmü...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-durak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Değil', 'elimde-degil-asli-kasapoglu-mi26i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnan çok uğraştım kendimle

Çok uzun zaman kabullenmek istemedim, 

Ama olmuyor işte

Ne yaptıysam buna engel olamadım, 

Ne seni düşünmekten alı koyabildim kendimi 

Ne de sevmekten.

Kim bilir kaç kez denedim unutmayı seni, 

Kim bilir kaç kez sildim sandım kalbimden.

Ama yapamıyorum işte, 

Hala aklımdasın

Hala süslüyorsun hayallerimi.

Dalıp gittiğim zaman

Gözümün önüne gelen yine sensin, 

Duyduğum zaman kalbimi acıtan

Yine senin sesin, 

Ve baktığımda 

Kendimi alamadığım gözler yine seninkiler.

24.01.2002', 'İnan çok uğraştım kendimle Çok uzun zaman kabullenmek istemedim,  Ama olmuyor işte Ne yaptıysam buna engel olamadım,  Ne seni düşünmekten al...', ARRAY['Türk Edebiyatı','Şiir','Aslı Kasapoğlu']::text[], 8.5, '{"poet":"Aslı Kasapoğlu","poet_slug":"asli-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/elimde-degil-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-hakki-hakan-kaya-4hvv6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi narin bir çiçektir kaf dağının arkasında

Kaybolup gitmiş dikenlerin arasında

Arayıp bulamaz koparıp kıyamazsın

Sevgi narin bir çiçektir yaşamın kıyısında', 'Sevgi narin bir çiçektir kaf dağının arkasında Kaybolup gitmiş dikenlerin arasında Arayıp bulamaz koparıp kıyamazsın Sevgi narin bir çiçekti...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgi-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağara', 'magara-asaf-halet-celebi-io39u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'içimdeki mağarada

kurumuş ölüler yatar

zehirle gülen zümrüt

ve yakut yatak içinde

bir zaman

beni uğurlamaya gelen

                        haramîler

içimdeki mağarada

bir yığın kitap var

bakınca yakından

tasvirlerin gözleri oynar

ve konuşur

hepsinin yüzleri benim yüzüm gibi

                ve gözleri benim gözüm gibi', 'içimdeki mağarada kurumuş ölüler yatar zehirle gülen zümrüt ve yakut yatak içinde bir zaman beni uğurlamaya gelen                         ha...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/magara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadıncığım', 'kadincigim-asaf-halet-celebi-k1bcs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'oyluk kemiğimi çıkarıp

                kendime bir kadıncık yaptım

ve bir şamar vurup

                rafa oturttum

ben evden çıkınca

kadıncığım yemeklerimi pişirdi

söküklerimi dikti

ve akşam olunca

                korkusundan

çıkıp rafa oturdu

geceleri kadıncığımın dizlerine korum başımı

ve üç kıil koparınca

                uyurum', 'oyluk kemiğimi çıkarıp                 kendime bir kadıncık yaptım ve bir şamar vurup                 rafa oturttum ben evden çıkınca kadınc...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kadincigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Uyanmak', 'olume-uyanmak-gurkan-anbarli-at7yl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak? 

Eskidendi o, eskidendir benim yaşamışlığım, 

O hariç bir zamanlar yaşamak için gücümü aldigim hersey yaşamimla beraber

eskide kaldi.

Artık gece kafamı yastığa koyduğumda başlıyorum hayata, rüyamda görüyorum

sevdiğimi, 

ancak rüyamda ulaşıyorum O''na ve ulaştığım o an zamanın çarkları

alabildiğince hızlı dönmeye başlıyor, 

her rüyada dahada büyük bir istek ve arzuyla mücadele veriyorum, 

sarılmak, dokunmak, koklamak, gözündeki yaşı silmek, sesimi duyurmak, ''iyiki

varsın meleğim, özlemişim, hoşgeldin'' demek için.

Yazık ki ulaşmak yolunda yaptığım her hamlede dahada uzaklaştırılıyorum

sevdiğimden, 

zincirlenmiş, kayan bir yıldızın çaresizliğinde ve harap haldeyiz, tonları

farklı gibi gözüksede karanlıktayız ikimizde.

Bu gecede gözlerim ışıksız kaldı diyorum, ve düşünüyorum eğer şu an

ulaşamıyorsam sana, uzaktamıyım gerçektende gönlüne, peki yanındakiler, 

onlar çokmu yakın sanki sana? 

bu geceki hayatımında sonuna yaklaştığımı hissediyorum ve son bir defa

gözlerine bakıyorum, gözlerinden gözlerime, gözlerimden içime bir ışık gibi

süzülüyor hisleri.

Akıp geçen zamana, namert insanlara ve yaşam denen olguya lanet ediyorum, 

içine düştüğüm çaresizlik her geçen gün daha fazla kemiriyor beni, 

Ve sabah

sabah yine ölüme uyanıyorum, sevda yangınlarıyla yanıp tutuşan kalbimde, 

nikotin kokulu soğuk cesedimi taşımaya, rotasız ölümü yaşamaya başlıyorum.

Aşkımın ateşine bıçak gibi keskin çaresizlik rüzgarları tersten esmeye

başlıyor, üzerine burukluğum, kırılmışlığım, kinim, nefretim ve öfkem

ekleniyor.

Ve bir sonraki rüya için zamanla oynamaya başlıyorum. Benimle dalga

geçercesine ağır ilerleyen zamanla beraber

ben ölmeye devam ediyorum, kini solurken yüreğim, ciğerlerime çektiğim her

nefesde içimdeki yangın daha fazla körükleniyor, 

her solukda daha fazla yanıyorum, ölmenin gerçekte ne olduğunu her yanışımda

tekrar anlıyorum.

Çevremdeki insanlara bakıyorum, ve yalnız ben, sadece ben görüyorum, 

aslında kimlerin yaşayıp, kimlerinse zaten ölü olduğunu.', 'Yaşamak?  Eskidendi o, eskidendir benim yaşamışlığım,  O hariç bir zamanlar yaşamak için gücümü aldigim hersey yaşamimla beraber eskide kald...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Anbarlı']::text[], 8.5, '{"poet":"Gürkan Anbarlı","poet_slug":"gurkan-anbarli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/olume-uyanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-huseyin-cayikli-482u2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hoscakal

ve bir umudu bir namnu agzinda ki yillarim

hoscakal dunya

son bir veda bu adaya geri donmenin hazzi

ve icimde ki sikinti

kitaplar raf boyu siralanmis

gunlerimiz gibi

ve bir sayfadan 

bir sayfadan kapanmasi gibi

hic acilmadan

hoscakal 

demek icin erken ama 

hayat simdiden hoscakal.', 'hoscakal ve bir umudu bir namnu agzinda ki yillarim hoscakal dunya son bir veda bu adaya geri donmenin hazzi ve icimde ki sikinti kitaplar r...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hoscakal-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışkanlık', 'aliskanlik-erol-sen-ldwe5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdanın anlamsız alışkanlıkları 

Alışkanlık mı hırs mı çözümsüz

Bilinmez bir meçhule gidiyorsun yolcu

Sen sensin kimse sen olamaz

Yaptıkların sevdayı örseliyor anlamsız

Acıtıyor ama yine yapıyorsun

Bir aldatmacadır gidiyor hayatın

Mailler bitti görüşmeler başladı

Seni kaybetmek diyorsun yine yapıyorsun

Ne yaptığını gerçekten bilmiyorsun yolcu

Kalbim senindir diyorsun ama

Yine saçmalıyorsun yolcu

Bu nasıl sevdadır bu nasıl aşk

Aldatmak bunun adı başka adı yok

Bir kere yapıldımı alışkanlık yapar yolcu

Birde gizler içindesin söylemiyorsun

Nasıl yaparsın yolcu

Vicdanın sızlamazmı, haklı görürken kendini

Bu nasıl sevgi bu nasıl aşk yolcu

Düşünmek  ama nice düşünmek yolcu...

10.04.2002', 'Sevdanın anlamsız alışkanlıkları  Alışkanlık mı hırs mı çözümsüz Bilinmez bir meçhule gidiyorsun yolcu Sen sensin kimse sen olamaz Yaptıklar...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aliskanlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bardak Çay Sıcaklığı', 'bir-bardak-cay-sicakligi-cengiz-mise-1thft', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana çay demledim, hadi gel! 

Küçücük iki kişilik çaydanlığımla.

İçimiz ısınır hatırlarken, 

Eski yaşanmışlarımızı.

Avuçlarımızda sıcacık bardaklar, 

konuşuruz usulca, kendi kendimize.

Kimseler görmez, 

Üşüdüğümüzde birbirimize sokulduğumuzu.

Söz senin bardağına 

Üç şeker atacağım.

Söz, demlik bitene kadar, 

Yanındayım.

Bu sefer herşeyimin üstüne 

Yemin ediyorum ki; 

Çay kaşıklarının şıngırtısıyla

Uyuyup kalmayacağım.

28.01.1999 - 00: 38', 'Sana çay demledim, hadi gel!  Küçücük iki kişilik çaydanlığımla. İçimiz ısınır hatırlarken,  Eski yaşanmışlarımızı. Avuçlarımızda sıcacık ba...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Mişe']::text[], 8.5, '{"poet":"Cengiz Mişe","poet_slug":"cengiz-mise","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-bardak-cay-sicakligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızca', 'yalnizca-cengiz-mise-b1afp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gecede sensizliği tükettim, 

Yüreğimin başucunda.

Bomboş hayallerimle.

Ne sen vardın, 

Ne o kahrolasıca gözlerin.

Yalnızca yalnızlıklar, yalnızca.

Son şiirimi de bitirdim.

Seni kaybetmek korkusunda.

Son mısrasında yine gözlerin, 

O Kahrolasıca.

Bir susmayı öğrenmedi yüreğim, 

Birde konuşmayı gönlünce.

Arada bir sustu, 

O da arada bir yalnızca. 

Yine kapattım perdeleri.

Biliyormusun? 

Yüreğimi mahkum ettiğin, 

Benimse çoktan tükendiğim 

O sonsuz karanlıklara.

Yalnızca gözlerin girsin, 

Kahrolasıca gözlerin yalnızca.

Kurtulmaya çalışan, 

Bir kuş çırpınışındayım.

Tükenen bu şehrin 

Koskoca bakışlarında.

Sense hala yoksun

Kahrolasıca gözlerinin 

O bomboş sokaklarında.

Çok sevdiğin deli kahkahalarımı, 

Artık hiç duymayacaksın.

Çınlatsada ortalığı.

Ben senden çoktan vazgeçtim.

Hadi sende dilediğince yaşa, 

Kendini mahkum ettiğin, 

Kahrolasıca yalnızlıkları yalnızca.

27.12.2001 - 03: 50', 'Bu gecede sensizliği tükettim,  Yüreğimin başucunda. Bomboş hayallerimle. Ne sen vardın,  Ne o kahrolasıca gözlerin. Yalnızca yalnızlıklar, ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Mişe']::text[], 8.5, '{"poet":"Cengiz Mişe","poet_slug":"cengiz-mise","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yalnizca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul; Ne Olur', 'i-stanbul-ne-olur-hilmi-tanrikulu-y3cjs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul...gerçeklerin yalanlara karıştığı büyük şehir...sevdiklerimi yutan ama kavuşmamıza arasıra izin veren girdap...istanbul nerdesin yada ne kadarsın? kim anladı ki bu güne kadar? her ağlayan ve hiç kopulamayan şehir...seni mi seviyorum, içindekileri mi? dünyanın en yalnız şehri...içindekileri saklama bizden ki sadece üzülmeyelim yüzünü görünce...şehir yüzlü aşıkları al yine götür kendine...kendi cennetine...ayır onları diğerlerinden...farklı olduklarını yaşat...hissetir sevdayı...avuçlarını doldur bembeyaz güllerle...

İstanbul, sev beni ne olur! ! !', 'İstanbul...gerçeklerin yalanlara karıştığı büyük şehir...sevdiklerimi yutan ama kavuşmamıza arasıra izin veren girdap...istanbul nerdesin ya...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/istanbul-ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çek Vur', 'cek-vur-cengiz-mise-m1tey', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurşunsuz gecelerimin, 

Acımasız silahı.

Hadi çek vur, 

Çek vurda bitir işimi.

Masum, deli deli, 

Sana bakarken, 

Hadi biranda sil, 

Silde dondur gülüşümü.

Karala adımı posta kutundan.

Yok diye yan.

Hadi nolur, 

Acımasız hayatımın tek tanığı, 

Daya, daya alnımın tam ortasına 

Yüreğini.

Bişey olmaz korkma.

Gözlerimin içine baka baka, 

Çek vur, çek vurda 

Kes şu yüreğimin sesini.

Sonra; 

Arkana bile bakmadan çek git.

Ne olursam olayım, 

Acıyıp dönme sakın.

Sereserpe çamurlara bulanmış, 

Kan revan içinde yüreğim, 

Kaskatı taş kesilsin.

Hadi, hadi nolur 

Onbir mısralık şiirim, 

Daya, daya bakışlarıma 

O melek bakışlarını.

Çek vur, çek vurda

Biranda devir aşkımı.

Ama unutma birgün, 

Ben gibi, senide, bir daha

Yüreğinin tam ortasından

Vururlar ey sevda! 

22.12.2001', 'Kurşunsuz gecelerimin,  Acımasız silahı. Hadi çek vur,  Çek vurda bitir işimi. Masum, deli deli,  Sana bakarken,  Hadi biranda sil,  Silde d...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Mişe']::text[], 8.5, '{"poet":"Cengiz Mişe","poet_slug":"cengiz-mise","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/cek-vur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve O Ölüm Gelirde', 've-o-olum-gelirde-harun-kesik-sp01h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve o ölüm gelirde çalarsa kapımı

İnandıramazsam evdeki yokluğuma

Git diyemezsem geriye ki desemde

O gitmezse

Bir adım daha attıysam geriye düşmediysem 

Rüya değil ise 

Bekle senin geleceğin yere gidiyorum...', 'Ve o ölüm gelirde çalarsa kapımı İnandıramazsam evdeki yokluğuma Git diyemezsem geriye ki desemde O gitmezse Bir adım daha attıysam geriye d...', ARRAY['Türk Edebiyatı','Şiir','Harun Kesik']::text[], 8.5, '{"poet":"Harun Kesik","poet_slug":"harun-kesik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ve-o-olum-gelirde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehri Sana Bıraktım', 'bu-sehri-sana-biraktim-cengiz-mise-z5kou', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece, bu şehirde.

Yapayalnız dolaştım, 

Bomboş sokakları.

Sensizliğin tadını çıkardım.

Keyfine vardım, üzülmenin.

Ağlamanın doyasıya.

Keyfine vardım, göz yaşlarımın, 

Hıçkıra hıçkıra.

Bu gece, 

Ben, Bu şehrin boş sokaklarını, 

Çoktan sana bıraktım.

Yürürken gözlerimle adını yazdığım, 

Kaldırımları söktüm yüreğimden.

Kaldırıp attım.

Ardımda, 

Bembeyaz karda, 

Ayak izlerimi bırakacaktım, 

Sürünmeden, 

Dimdik başım.

Bu gece, 

Ben bu şehri, 

Sana bıraktım. 

14.12.2001 - 02: 03', 'Bu gece, bu şehirde. Yapayalnız dolaştım,  Bomboş sokakları. Sensizliğin tadını çıkardım. Keyfine vardım, üzülmenin. Ağlamanın doyasıya. Key...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Mişe']::text[], 8.5, '{"poet":"Cengiz Mişe","poet_slug":"cengiz-mise","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bu-sehri-sana-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-ahmet-hani-piydd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay mehreban öz nenem,

Gözlerime göz nenem.

Her ne dedim demedi,

Gülden ağır söz nenem.

---

Gül üzü torpaq oldu,

Saraldı yarpaq oldu.

Anam seferde öldü,

Yaylağım qışlaq oldu.

--

Dumanlı dağlar qaldı,

Saralmış bağlar qaldı.

Anam öldü saraldım,

Ürekde dağlar qaldı.

--

Sözleri yaz, buludu,

Gözleri yaz buludu.

Anam öldü ay qelem,

Qan ile yaz buludu.

september  2000', 'Ay mehreban öz nenem, Gözlerime göz nenem. Her ne dedim demedi, Gülden ağır söz nenem. --- Gül üzü torpaq oldu, Saraldı yarpaq oldu. Anam se...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkınla Öleceğim', 'askinla-olecegim-selami-ozturk-58mj0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretinle yaşayıp

Aşkınla Öleceğim

Mutluluk istersen

İnanki vereceğim

Yeterki sen iste

Evet diyeceğim

Terk etme beni sevdiğim

            Hep Seni Seveceğim....', 'Hasretinle yaşayıp Aşkınla Öleceğim Mutluluk istersen İnanki vereceğim Yeterki sen iste Evet diyeceğim Terk etme beni sevdiğim             H...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askinla-olecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığa Bulandı Tüm Aşklar', 'ayriliga-bulandi-tum-asklar-orhan-tufan-e1gv1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılığa bulandı tüm aşklar

Aşıkları vurdu gece kaldırımlarında

Orospu bir eylemdi aşkı vurmak

Hainceydi

Saçma sapandı

Ve müsebbibi vardı senin gibi

Tüm aşklara tecavüz edildi kendi şahsımda

Aşkı yaladım yuttum ciltli çok sayfalı kitaplar gibi

Ve benliğin tek harfe kilitlenmişti tek kelimeye

Cümleleri eksik kaldı ne yazık ki

Aşk beni vuruyor zamana

Yarın çok erken 

Vuslat başka benlerin baharına..', 'Ayrılığa bulandı tüm aşklar Aşıkları vurdu gece kaldırımlarında Orospu bir eylemdi aşkı vurmak Hainceydi Saçma sapandı Ve müsebbibi vardı se...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tufan']::text[], 8.5, '{"poet":"Orhan Tufan","poet_slug":"orhan-tufan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayriliga-bulandi-tum-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancıların Ne Zaman Bitecek', 'sancilarin-ne-zaman-bitecek-orhan-tufan-qcxr3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sancıların ne zaman bitecek

Güneşi göremez oldum karanlığında

Bırakalım öyle kalsın yaşam

Ve son kez gülümsesin gece varlığımıza

En son doğum günümdü seninle

Çiçeklerin arasına yazılmış nottu sevişlerin

Ve önce yazdığın aşk kurudu oysa sen bile vardın daha

Adama koyuyor yaşanırken hala...

Gel demiyorum

Sakın yanlış anlama beni

Gittiğin yerde mutlu kal ne olur

Dönme terk etmeye tekrar beni..

Alışkanlığım yok sigaradan

Ve senin terk etmelerinden başka

Bugün bıraktım sigarayı

Devrettim yeni aşka...

Ne yaşadıysam aşk adına değil

Sadece mevsimlerin hatırı vardı 

Ve görevdi üzerime

Sen olsaydın da yapardın

Hatta babanda yapardı

Biliyorum eminsin buna

Ne gel artık ne git 

Sana bu son veda....', 'Sancıların ne zaman bitecek Güneşi göremez oldum karanlığında Bırakalım öyle kalsın yaşam Ve son kez gülümsesin gece varlığımıza En son doğu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tufan']::text[], 8.5, '{"poet":"Orhan Tufan","poet_slug":"orhan-tufan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sancilarin-ne-zaman-bitecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-omer-kutlu-2q02z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elveda sana ey şehir, 

ey kara sevdam

ve ey “dul bakirem” elveda...

Elveda ey  gözyaşlarımla yıkanmış toprak, 

Ey koku, ey renk ve ey damağımda kalan tat...

Ey boğazımda düğümlenen hasretin türküsü, 

Ve ey beni çağıran sessizliğin çığlığı.

Yerdeki karınca, yuvadaki kuş, 

Otlayan ceylanların korkusu, 

Bir aslan vakarı ile gelp içime oturan 

Ve şimdi elimden kayıp giden düş.

Hepinize elveda...

Elveda sana güzel yüzlü sokak çocuğu, 

Yolumu kesen hırsız, 

Şehrin varoşlarında bitip tükenen hayat, 

Acılarla yoğrulan gecelerdeki günah

Açların sinesindeki binlerce ah! 

Size de elveda...

Tuzlu sularında hayallerimi saklayan okyanus

Beni uzaktan selamlayan yunus, 

Ey yosun kokulu sahillerin serinliği, 

Ve ey kızgın güneşlere bağrını siper eden kıta, 

Elveda demek yetiyorsa eğer

Elveda...

Ve sana da elveda ey geri gelen çocukluğum

Artık ben uzaklaşıyorum.

Yaşadığım çocuksu hatıralar, 

Tırmandığım ağaç, 

Koştuğum yeşil tepeler, 

Taş attığım göl, 

Ölü gönlümü sürükleyen bir yelkenli gibi uzakta

Çok uzakta kaldınız.

Ben artık adam(!)   oldum

Gidiyorum, 

Herkese elveda.

El ve dağ! 

Elveda.

Sana diyorum ey dağ, 

Sana sallıyorum elimi 

Heybetini bırakıp selamımı aldığın o gün ki gibi, 

sana sallıyorum içimdeki elimi, 

sana sunuyorum içimdeki  elemi, 

ve elveda...

Elveda hava, 

Elveda toprak, 

Elveda su

Ve ateş

Yani herşeye elveda! ..

Bak şimdi sırası geldi; 

Elveda çamurlu yollar, 

Elveda karanlık sokaklar

Akmayan sular, 

Kesik elektrikler, 

Olmayan belediye hizmetleri, 

Abus çehreli memurlar, 

Ve iki işi sığıştıramadığım resmi günler, 

Elveda.

Çöp kokuları, 

Olsun sıze de elveda...

Ey hayatı sıkıp boğduğum şiirlerim

Aslında böyle yazmayacaktım, 

Hasret değil, sevgi ve aşk türküleri söyleyecektim....

Ey sabahlarının kızıllığında

Ve güneş yüklü öğlelerinde

Sonra o yemyeşil günlerinin ardından 

akıp gelen karanlık soğuğunda

binlerce derdin ahu efganını 

duymaya çalıştığım şehir! 

Haydi çok uzatmayayım

Artık veda vakti

Elveda ey bitmeyen tutkum

Kara bahtlım

Kara sevdam

Kara kıtam

Afrika..

      Ve.. ben henüz ağlamaya başlamadım...                                       

                          Nairobi         13 mayıs 2001', 'Elveda sana ey şehir,  ey kara sevdam ve ey “dul bakirem” elveda... Elveda ey  gözyaşlarımla yıkanmış toprak,  Ey koku, ey renk ve ey damağı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Kutlu']::text[], 8.5, '{"poet":"Ömer Kutlu","poet_slug":"omer-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/elveda-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarını Uzat Rüzgara', 'saclarini-uzat-ruzgara-orhan-tufan-d6ggp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'saçlarını uzat rüzgara

fısıltıyla karışık essin rüzgar

ve sen serinliğini yaşa nefretin

adını sorma rüzgarın 

bende bilmiyorum çünkü

bildiğim onca şey gibi beni yanıltan

bir esinti mi şimdi

sıcak meltemler sadece isim olarak var

tüm esintiler üşütür seni artık çıkma pencerene

bir sevda değil ki söylemim

ısıtsın da hedonist kaygılarına bir çalgı olsun

ben susma hakkımı kullandım aşka

içimde demem o olmasa da

her suskunluk çoğalış olurmuş bilirim

varlığımdan çekinme artık...

saçlarını uzat rüzgara

ve kalsın tüm yaşanmamış şarkılar başka aşklara....', 'saçlarını uzat rüzgara fısıltıyla karışık essin rüzgar ve sen serinliğini yaşa nefretin adını sorma rüzgarın  bende bilmiyorum çünkü bildiği...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tufan']::text[], 8.5, '{"poet":"Orhan Tufan","poet_slug":"orhan-tufan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/saclarini-uzat-ruzgara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün..', 'bir-gun-orhan-tufan-p01jm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir gün yine

o aynı umtu yakalr bizi avuçlarımızdan

elleri hala sıcaktır

biz hala sıcağızdır geçen kışlara

ve yaşanmamış baharlara rağmen

kıtalardan çalınıp da gelmiş utangaç bir güneş

kulağına beni fısıldar

sevinirsin

sevinirim

bir gün yine

o aynı umuttaki aşk yakalr bizi yüreğimizden

bir keyif sigarası tüttürürüz keder sigaraları kendini içerken

tanıdıktır yeni de olsa yüzlerimiz birbirine

şarkılar söyleriz nazara gelmeyelim diye içimizden

bir gün yine

tüm ayrılıklara inat

aşık oluruz

ve o gün yine

yeni ayrılıklar doğururuz...', 'bir gün yine o aynı umtu yakalr bizi avuçlarımızdan elleri hala sıcaktır biz hala sıcağızdır geçen kışlara ve yaşanmamış baharlara rağmen kı...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tufan']::text[], 8.5, '{"poet":"Orhan Tufan","poet_slug":"orhan-tufan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-gun-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz...', 'yaz-orhan-tufan-u7u1k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gülümserdi yaz bize

sen ona göz kırpardın

bende seni seyrederdim

ve yaz gelirdi..

bildiğimiz yaz gelmesi olağan olan

mucizelerden uzak varlığı yazın

ama biz yazı hiç hesaba katmamışız

ve yaz geldi

yine bir yerlerde göz kırpıyorsun yaza biliyorum

ama ben seni seyretmek yerine bu kez

yazlık giysilerimi hazırlıyorum..', 'gülümserdi yaz bize sen ona göz kırpardın bende seni seyrederdim ve yaz gelirdi.. bildiğimiz yaz gelmesi olağan olan mucizelerden uzak varlı...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tufan']::text[], 8.5, '{"poet":"Orhan Tufan","poet_slug":"orhan-tufan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Bitince...', 'gun-bitince-orhan-tufan-7i5cq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bazı zamanlar içindi anlar

zamanı kenetlemek içindi nefes alışım

bahara ulaşmak için değil

sayfaların arasına bırakılan güllerin arasından yıllar nasılda geçti

sen nasılda geçtin

kalır sandığımız takvim yaprakları

kullanılmış ve faydalınılmış eşyalar arasında..

ve sen yokken de varım olmasada takvimlere sinmiş yalnızlığım

ve sen yokken de varım şarkılardan uzak..

sabahı uyandırmayalı kaç yıl oldu 

kaç gece oldu yıla kavuşturamadığım

gülümse acılar da olsa içinde

sakla bakalım sakla, 

yarına ne kalır ki gün bitince...', 'bazı zamanlar içindi anlar zamanı kenetlemek içindi nefes alışım bahara ulaşmak için değil sayfaların arasına bırakılan güllerin arasından y...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tufan']::text[], 8.5, '{"poet":"Orhan Tufan","poet_slug":"orhan-tufan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gun-bitince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığına Vuruldun..', 'ay-isigina-vuruldun-orhan-tufan-vh8v5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay ışığına vuruldun güneşi beklemeden

Uyandığımda yoktun

Ve diğer uyanışlarımda..

Gelirsin diye ümit etmedim inan

Git...bu benim söylemime dönüştü

Varlığınla ısıtman gereken yüreğim

Gölgesine yenik düşmüştü..

Ne adını duymak şimdi

Nede yaşadıklarımı anımsamak

Ve varlığınla geçen yılları yaşanmış saymak, 

Rüyalarımda haykırışım sana ve boyun büküşündür.

Defol daima ihanetten iyidir 

Sen git gülüm 

Varlığın tükenişimdir..

10mayıs2001', 'Ay ışığına vuruldun güneşi beklemeden Uyandığımda yoktun Ve diğer uyanışlarımda.. Gelirsin diye ümit etmedim inan Git...bu benim söylemime d...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tufan']::text[], 8.5, '{"poet":"Orhan Tufan","poet_slug":"orhan-tufan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ay-isigina-vuruldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Değil', 'sana-degil-orhan-tufan-sxzt5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana değil 

aynada söyleşim bu benim ayrılıktan sonra

kendi adıma

madem neden? 

sorum belli

cevap belli değil işte takılıyorum burda

ben yokum herşey süt liman olmuştur umarım

öyle unuttum ki seni; 

aynada tükürsem kendime sen ıslanırsın diye korkarım..', 'sana değil  aynada söyleşim bu benim ayrılıktan sonra kendi adıma madem neden?  sorum belli cevap belli değil işte takılıyorum burda ben yok...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tufan']::text[], 8.5, '{"poet":"Orhan Tufan","poet_slug":"orhan-tufan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Ok', 'kirik-ok-mine-ozdemirtas-2on4n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hafif bir ses... yeşermiş bir koku 

Ritmini kaybetti ayak izleri 

Yarınlara göz koyan gizli bir korku 

Dünler; alıp gitti çoktan bizleri 

Bağladık... bağlandık. O gene koptu 

Akort ttumuyor işte paslı telleri 

Yaydan fırlayan kırık bir oktu 

Şimdi limanda... dalga sesleri.', 'Hafif bir ses... yeşermiş bir koku  Ritmini kaybetti ayak izleri  Yarınlara göz koyan gizli bir korku  Dünler; alıp gitti çoktan bizleri  Ba...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kirik-ok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cips', 'cips-mine-ozdemirtas-bkup8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki kişilik yalnızlıklara bilet aldım, benimle gelir misin? 

Ben söyleyip, ben dinleyeceğim sana söz. 

Sorular cevapsız, cevaplar anlamsız olabilir. 

Ama bir düşün... Kabul edersen 

Aynı perdeye bakarak seyredeceğiz oyunu 

Sen ve ben 

Yanyana ve karanlıklarda... birbirimizi hiç görmeden 

Ne dersin? 

Perde aralarında birbirimize...... kibarca gülümseriz. 

Pardon! Cips ister misin?', 'İki kişilik yalnızlıklara bilet aldım, benimle gelir misin?  Ben söyleyip, ben dinleyeceğim sana söz.  Sorular cevapsız, cevaplar anlamsız o...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cips-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim bilir', 'kim-bilir-gokhan-oktem-1b60s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yıpranışta yüreğim

Yazgımız okunmaz artık	

Sabır taşı eskidi bir hayli

Ellerimizin nasırından fazla

Örselenmiş yüreğimizin kabuğu 

Bir hayli yaşamışlığımız var geride

Gençliği devirme çağlarındayız

Sorsan sorgun asılsız kalır 

Yürek yetmez dillendirmeye 

Ne sen sor ne ben söyleyim hallerine 

Umutlarımız vardı kantar çekmez

Kayıp sevgiler yüklü yitik sevgililerde

Bir gelecek, bir gün gelecekler vardı elbet

Elbetler devir teslim töreninde belkilerle

Neye baksak bulanık, buğulu camlar gerisinde

Hayatlarımız artık bir hayal gerçekliğinde 

Bir yok oluş girdabındayız

Savrulan bir yüreğin terkisinde

Kaçan fırsatlar kaçan hayatlardır artık

Kalanlarla yetinme çabasındayız

Bir hayal bir gerçek arasında 

Çok şükür, varoluşumuzun ayırdında

Ellerimizi ovuşturmaktayız, ne yazık...

İstanbul,10,04,2002', 'Bir yıpranışta yüreğim Yazgımız okunmaz artık	 Sabır taşı eskidi bir hayli Ellerimizin nasırından fazla Örselenmiş yüreğimizin kabuğu  Bir h...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Öktem']::text[], 8.5, '{"poet":"Gökhan Öktem","poet_slug":"gokhan-oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kim-bilir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yaman Gecikib Bu Sevda, Allah', 'ne-yaman-gecikib-bu-sevda-allah-rustem-behrudi-quz3t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu  éşgin  sonu yoh! Niye görüşdük? ! 

Niye doğmalaşdıg , néce  ayrılag?

Bu néce sévgidir ölecek, gülüm, 

Hatire -kederi galacag  ancag.

           Tanrım, günahım ne, bu ceza nedir? 

           Neler göreceyem, yazıg   gözlerim? 

           Danışdım  , sözümde gem çiçekledi , 

           Danışdım, dilimde yandı sözlerim.

Dé görüm béle mi gelir mehebbet , 

Bu sévda içimi göyneden  yara .

Bu günden men gerek özümden gaçam, 

Üz tutub yol géden ayrılıglara.

              Üz tutub yol gédim, görüm gem nedi, 

              O '' yazıg ''Fuzuli ne çekib -görüm .

              Nakam   sévgilerin heykeli kimi

              Bir gün mezarımdan dikelib -görüm...

Görüm, min il kéçir yéne dünyada, 

Her şeyden ucada éşg var, sevda var.

Yéne Eslilerin   donu   sirlidir

Sévsem Kerem éyler meni sévdalar.

Umulmaz  bu sévda, darıhma   könlüm, 

Gel bu gem içinde temizlen, arın 

Meni men éyledi bu ayrılıglar

Néylim, yolcusuyam, ayrılıgların.

                Déyirsen  ayrılag, ayrılag - ne  gem? 

                Bu  éşgi  sirr    kimi  gelbinde  gizde

                Bu günden  başlayır  seadetimiz, 

                Bu  günden  başlayır  faciemiz   de.

                                                                  1988', 'Bu  éşgin  sonu yoh! Niye görüşdük? !  Niye doğmalaşdıg , néce  ayrılag? Bu néce sévgidir ölecek, gülüm,  Hatire -kederi galacag  ancag.    ...', ARRAY['Türk Edebiyatı','Şiir','Rüstem Behrudi']::text[], 8.5, '{"poet":"Rüstem Behrudi","poet_slug":"rustem-behrudi","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ne-yaman-gecikib-bu-sevda-allah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-asli-kasapoglu-flb7u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanlara bakıyorum, boş, boş, 

Belki de seni arıyorum 

Onların yüzünde, 

Hiç birinde ve hiç bir yerde 

Yoksun sen artık.

Bunu ne kadar istesem de, 

Seni ne kadar özlesem de, 

Biliyorum, gelemezsin artık geri, 

Giremezsin hayatıma.

Ama yine de, seni arıyorum işte, 

Baktığım ve duyduğum herşeyin içinde.

Bir kez daha doğdu güneş

Sensizliğin karanlığına, 

Bir kez daha başladı gün

Sensizliğin boşluğunda, 

Ve bir kez daha herşey aynı

Yokluğunun süslediği hayatımda.

Haziran 2001', 'İnsanlara bakıyorum, boş, boş,  Belki de seni arıyorum  Onların yüzünde,  Hiç birinde ve hiç bir yerde  Yoksun sen artık. Bunu ne kadar iste...', ARRAY['Türk Edebiyatı','Şiir','Aslı Kasapoğlu']::text[], 8.5, '{"poet":"Aslı Kasapoğlu","poet_slug":"asli-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sensizlik-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Masum Günahım', 'en-masum-gunahim-asli-kasapoglu-boa5n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En masum günahımdın benim

Kendimce aşık olduğum, 

Kalbimden bir türlü söküp atamadığım

En masum günahım.

Nerden ve neden çıktın karşıma bilmiyorum

Niçin seni unutamıyorum anlamıyorum.

Belki acılarımız birleştirdi bizi,

Belki de hüzünlerimiz

İkisi de aynı değil mi zaten. 

Sonuç kalbim sende, 

Sense aklımın bir köşesinde.

Sen yanımda otururken

Elimi sana uzatamıyorum, 

Sen aşkından bahsederken 

Ben sana seni anlatamıyorum.

Sığınmak istiyorum senin limanına

Ama yapamıyorum, 

Biliyorum benim yerim yok orda

Ama nafile

Anlatamıyorum, söz dinlemiyor duygularım.

En masum günahımdın benim

Uzaktan izlediğim, 

Rüyalarımda hasret giderdiğim

En masum günahım.

Kasım 2001', 'En masum günahımdın benim Kendimce aşık olduğum,  Kalbimden bir türlü söküp atamadığım En masum günahım. Nerden ve neden çıktın karşıma bilm...', ARRAY['Türk Edebiyatı','Şiir','Aslı Kasapoğlu']::text[], 8.5, '{"poet":"Aslı Kasapoğlu","poet_slug":"asli-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/en-masum-gunahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Başka Ben', 'benden-baska-ben-hulya-arisan-zndpi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimde 

benden başka, 

bir ben var şimdi.

Seninle var olmanın, 

tadını çıkarıyorum...

İstanbul,2001', 'İçimde  benden başka,  bir ben var şimdi. Seninle var olmanın,  tadını çıkarıyorum... İstanbul,2001...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/benden-baska-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim', 'sensizim-asli-kasapoglu-kayop', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SENSİZİM

Şu an yatağımın üstünde yatmış seni düşünüyorum, 

Elimde kalem duygularımı kağıda döküyorum.

Keşke diyorum her gün, keşke yanımda olsan, 

Sana ihtiyacım varken bana sarılsan.

Biliyor musun omuzuna ihtiyacım var

Omuzunda ağlamaya ve sana sarılmaya.

Biliyorum söz verdin bana, 

Her zaman yanımda olacağına, 

Ama yoksun işte

Sensizim şu anda.', 'SENSİZİM Şu an yatağımın üstünde yatmış seni düşünüyorum,  Elimde kalem duygularımı kağıda döküyorum. Keşke diyorum her gün, keşke yanımda o...', ARRAY['Türk Edebiyatı','Şiir','Aslı Kasapoğlu']::text[], 8.5, '{"poet":"Aslı Kasapoğlu","poet_slug":"asli-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensizim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum Farzet', 'unuttum-farzet-sema-senel-hg42c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artik kirik dökük siirlerimde kendini arama

Unuttum artik seni vicdansiz, unuttum hayirsiz

Sen degilmiydin böyle olmasini isteyen

Bir cirpida askimizi silip süpüren

Simdi sakin kendini virane yüregimde arama

Ben seni mazilere gömdüm

Ben seni hoyrat rüzgarlara saldim

Ben seni coktan unuttum

Geri dönmen artik imkansiz 

Imkansiz artik kor olan yüregimi alevlendirmen

Artik hersey icin cok gec

Mechullere biraktim yüregimi

Birak orda kalsin, birak desme yaralarimi

Kirdin kolumu kanadimi

Son bir umut bile birakmadin giderken

Saclarima karlar yagdi senden sonra

Yüzümdeki her cizgi acimasiz bir hatira

Kallesce birakip gitmelerin ardindan, kac kez öldüm biliyormusun

Kac kez ugruna kahroldum, kac kez deli divane

Oysa ben sana hic kiyamadim

Oysa ben sensiz yapamadim

Oysa ben sana hayatimi adadim

Senden se bana kalan tek hatira, o ayrilik mühürünü basip gittigin kara sayfa

Söyle bumuydu vefa, söyle bumuydu eda

Söyle bumuydu sende ki merhamet, bumuydu senden kalan fazilet

Artik unuttum seni insafsiz, 

Unuttum farzet

(08.02.02)', 'Artik kirik dökük siirlerimde kendini arama Unuttum artik seni vicdansiz, unuttum hayirsiz Sen degilmiydin böyle olmasini isteyen Bir cirpid...', ARRAY['Türk Edebiyatı','Şiir','Sema Senel']::text[], 8.5, '{"poet":"Sema Senel","poet_slug":"sema-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/unuttum-farzet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretlik', 'hasretlik-duahan-hanci-0xfhu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecelerin sükutu dopdoluyken dünyamda

İçimde fırtınalar kopar sanki coşarcasına

Deli gibi atar yüreğim adını her andığımda

Heyecan dolarım, yüzünü her hatırladığımda...

Varlığın huzur taşır sen cansın canıma

Parlak bir umutsun sen uzaktaki ufkuma

Gözlerin mutluluğum bana her bakışında

Neş''e dolar ruhum, sen aydınlıksın bana...

Ama yoksun şimdi hasretlik her yanımda

Vuslatın uğramaz hiç o şimdi çok uzakta

Çağırsam gelmiyorsun gözyaşları dünyamda

Sen olmasanda burada, aşkın benim ruhumda...', 'Gecelerin sükutu dopdoluyken dünyamda İçimde fırtınalar kopar sanki coşarcasına Deli gibi atar yüreğim adını her andığımda Heyecan dolarım, ...', ARRAY['Türk Edebiyatı','Şiir','Duahan Hancı']::text[], 8.5, '{"poet":"Duahan Hancı","poet_slug":"duahan-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasretlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Bayramda Sensiz Geçti Anne', 'bu-bayramda-sensiz-gecti-anne-zulkuf-cengiz-2hhfa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kücücükken sensiz kaldım 

Ne yaparsın ne çare

Çok aradım bulamadım 

Bu bayramda sensiz geçti anne 

Biliyorum gelemedim diye kızgınsın bana 

Elini öpemedim diye dargınmısın 

İşte gelemedim 

Bende pişmanım 

Çünkü; burda ne elini öpecegim bir annem 

Nede sarılıp oglum diyen bir şefkat 

Biliyormusun kimse bana harçlık vermedi

Belki sen şeker toplayan çocuklara 

Zülküf diye sarıldın 

Ama ben annem diye kimseyi öpemedim 

Biliyormusun ben seni çok seviyorum 

Ama bu bayramda sensiz geçti anne 

Aynı yıldızlar altında

Aramızda kilometreler olsada 

Hiç yalnız degiliz 

Yüregimiz hep birlikte atarken 

Ben seni yine hasretle kucaklıyorum

Ve sensiz gecen bu bayrama inat 

Bayramın kutlu olsun güzel annem', 'Kücücükken sensiz kaldım  Ne yaparsın ne çare Çok aradım bulamadım  Bu bayramda sensiz geçti anne  Biliyorum gelemedim diye kızgınsın bana  ...', ARRAY['Türk Edebiyatı','Şiir','Zülküf Cengiz']::text[], 8.5, '{"poet":"Zülküf Cengiz","poet_slug":"zulkuf-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bu-bayramda-sensiz-gecti-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtaç', 'muhtac-duahan-hanci-gp1f1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan nasıl muhtaçsa kanarak su içmeye

Öylesine muhtaçtır, sevilmeye ve sevmeye

Dünya nasıl muhtaçsa yaşanan her günün dönmesine

İnsan da öyle muhtaçtır mutlulukla gülmeye...

Dostlar korumaz bizi, atar yaban ellere

Yalan dolan dolanır, ''Canım'' diyen dillere

Gözyaşları coşar hep, nispet yapar sellere

Canlı fere muhtaçtır, ne diyelim gözlere...

Senelerce savrulduk, esir olduk yellere

İstemeden kucak açtık, çekilmeyen dertlere

Çekti huzur elini, sürükledi meçhule

Biz hepimiz muhtacız, sıcacık bir dost eline...

Gülmeyi unuttuk, selam verdik kedere

Efkar dolu geceler kucak açtı bizlere

Sitem etmek ne demek, kahrettik gecelere

Acılar mutlu etmez, muhtacız sevilmeye...', 'İnsan nasıl muhtaçsa kanarak su içmeye Öylesine muhtaçtır, sevilmeye ve sevmeye Dünya nasıl muhtaçsa yaşanan her günün dönmesine İnsan da öy...', ARRAY['Türk Edebiyatı','Şiir','Duahan Hancı']::text[], 8.5, '{"poet":"Duahan Hancı","poet_slug":"duahan-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/muhtac-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kürşat', 'kursat-hakki-hakan-kaya-6pqb7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgun mahallenin, bezgin savaşçısı

Hayat kavgasında zorlu bir gün daha

Ürkek adımlar, ağzında bafra sigarası

Belki bugün farklı olurdu herşey, belki kazanırdı 

Sonra uyandırdı onu bu hayalden

Cebindeki bir tek otobüs parası...

Neden herşey bu kadar ters gidiyordu 

Neden herşey bu kadar yanlıştı

Oysa şimdiye kadarki hayatında hep doğru davranmış, 

Hep iyi şeyler yapmış, hiç yanlışa sapmamıştı

Sonra düşündü Kürşat, demek ki hata kendisinde değil

Hata bu kahpe hayattaydı

Kendi kendine söz verdi, yenilmeyecekti bu hayata

Pes etmeyecek galip çıkacaktı...

İşte herşey bu kadar ümitsizken

O çıkıverdi karşısına

Deli yüreği kendisine bile yetmezken

Meydan okuyordu dünyaya tek başına

Birbirlerini o kadar çok sevmişlerdi

Bu kahpe hayatın çirkin tuzaklarına 

Alay edip gülebilmişlerdi...

Sonra kaderin çarkına itildiler

Yetmedi sevgileri, sıcak tutmaya elleri

Batan bir güneş gibi, için için yanan sigara gibi

Bir günde kalan anı gibi yitildiler...

Hani pes etmeyecekti ya Kürşat, 

Hani galip çıkacaktı ya olmadı

Vurdu alnının şakına ihanetin tokadı

Dağ gibi bir adam böylesine yıkılırmıydı

Hakmıydı bu revamıydı

Bir ceset buldular sabahın onunda

Gözünde iki damla yaş, ve bir papatya

Denizin kıyısında yosunlar arasında.

Yenilmişti Kürşat başaramamıştı

Fakat bu filmin her karesinde

Şerefi ve onuruyla yer almıştı...', 'Yorgun mahallenin, bezgin savaşçısı Hayat kavgasında zorlu bir gün daha Ürkek adımlar, ağzında bafra sigarası Belki bugün farklı olurdu herş...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kursat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berivan', 'berivan-metin-arifogullari-w5yjk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzaklarda can ile canan gördüm

Dostluk için alev alev yanan gördüm

İsmi ile güzelleşmiş yaren gördüm

Gel ey dağ kokulu nazlı çiçeğim Berivan

Bak kollarım seni bekliyor heran.

Öyle bir can ki kömür gözlü

Bal akıyor ağzından doğru sözlü

Ceylan bakışlı tatlı dilli

Sırma saçlı ince belli

Yeter gel artık nazlı çiçeğim Berivan.

Bu can sana sende bana kurban.', 'Uzaklarda can ile canan gördüm Dostluk için alev alev yanan gördüm İsmi ile güzelleşmiş yaren gördüm Gel ey dağ kokulu nazlı çiçeğim Berivan...', ARRAY['Türk Edebiyatı','Şiir','Metin Arifoğulları']::text[], 8.5, '{"poet":"Metin Arifoğulları","poet_slug":"metin-arifogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/berivan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Düşte Yiter', 'zaman-duste-yiter-metin-arifogullari-t61lh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde hüzünler biriktirdim, sevinçlerin yerine, 

Nicedir uzaklarda gözlerim, gözlerinin hapsinde.

Tutunmak istediğim dallar şimdi elimde, 

Sen sus, gözlerin konuşsun benimle.

Çırpınır durur çocuk yüreğim

Engin maviliklerinde denizin kaybolur giderim.

Bir sitem değil bu, çaresizliğim! 

Sen sus, yüreğin konuşsun benimle.

Sevginin tatlı telaşıyla yorgun kalbim, 

Huzur arıyor huzur dolu göğsünde.

Minnetler biriktirdim sana sunmak için, 

Sen sus, ellerin konuşsun benimle

Severken pembeydi tüm renkler

Pembe pembe yazardı seni kalemim

Pembeydi senin için kurduğum düşler

Sen sus, hayalin konuşsun benimle.

Çok istedim tutamadım sözümü

Hayat bir bilmece, yokmu onun çözümü

Sarıldım çarelere, kaptırmadım özümü

Sen sus, suskunluğun dertleşsin benimle.', 'İçimde hüzünler biriktirdim, sevinçlerin yerine,  Nicedir uzaklarda gözlerim, gözlerinin hapsinde. Tutunmak istediğim dallar şimdi elimde,  ...', ARRAY['Türk Edebiyatı','Şiir','Metin Arifoğulları']::text[], 8.5, '{"poet":"Metin Arifoğulları","poet_slug":"metin-arifogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaman-duste-yiter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ehli Beyt-2', 'ehli-beyt-2-murat-i-nan-8g95c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fatıma''nın gözyaşları

Serveri alem için

Cennet kadınlarının hanımefendisi

Yangın yürekli ana

Rasul''ün firakından bağrı dağlanan ana

Ve Aliyyel Murtaza

Zülfikarı şimşeği sakındıran

Hayber fatihi Ali

Merhab''ın korkulu rüyası

Mertliğin kalesi

Veliliğin bahçesi

Fakirlerin babası

Sultanı evliya Ali

Ve Hasan-ı Mücteba

Heybet ülkesinin prensi

Cesaretin hilmin bağı bahçesi

Nası da dağladılar 

Kin tutmaz ciğerlerini? 

Ve Hüseyin

Fırat mazlumu

Şehzadeler şehzadesi

Al kan içinde yüzü

Binbir elemde gönlü

Susuz dudakları

N''ola yerinde ben olaydım! 

Şehadeti tarih yazdı

Kıyamete bir yol çizdi

İmandan ve onurdan

Kerbela

Ne gamlı bir gündü o gün

Şehitlerin kanları

Yüreklere akıyordu

Tüm heybetiyle Şehzade 

Gönülleri yakıyordu

Gözünde imanın ışığı

Hak yolunun aşığı

Ne yazardı ki O''na

Susuzluğun yangını? ? 

Sarmıştı o pak gönülü

Muhabbetin yangını

Nebi''nin torunu

Arslanın oğlu

Kerbu Bela demişti

Belaların yurduna

Şehadeti istemişti

Dedesinin yoluna

Öyle büyüktü ki Hazret

Kanıyla destan yazıldı

Kerbela''nın çöllerine

Hasret azap yazıldı

Gün gece oldu

Güneşler soldu

Ehli Beyt dostu gözler

Kanlı yaşlarla doldu

Zulme boyun eğmedi

Rabbe kul oldu sade

Yalnız Rabbi dinledi

Şehit oldu o günde

O Yiğit

Hz. Ali

Rabbin aslanı

Çölde aşk seli

Çağlar fidanı

Gecede ışık

Vahada pınar

Ne şüphe ne şek

Devrilmez çınar

Korkuyu bilmez

Sevgidir yolu

Kula kul olmaz

Tek Rabbin kulu

Cenk

Elinde yalın kılıç

Kalbinde katıksız aşk

Ali''siz olur mu hiç

Onur için yapılan cenk? ? 

Zehir

Ali''nin yoluna diken serdiler

Hasan''a su değil zehir verdiler

Hüseyin''im susamış içi yanıyor

Fırat''ın önüne duvar gerdiler

Çile-Hüseyin

Çekmediği gam kalmadı

Dünyadan murad almadı

Çileli hayatında

Bağrına gün çalmadı

Hz. Ali

Yüreği mangal

Pençesi çengel

Sade bakışı bile

Zulüme engel

Fırat

Gün güneşe doyunca

Fırat nehri boyunca

Hüseyin''im yanıyor

Zalim O''na kıyınca

Matem

Erenler çayındayım

Muharrem ayındayım

İçimde kara bağlı

Ben matem ayındayım

Yas

Yeşil otlar sarardı

Yalan dünya karardı

Ali şehit olunca 

Kızıl güller bozardı

Dumanda gözyaşı var

Şehit olmuş Ali yar

Nerelere gidelim

Bu dünya bizlere dar

Ağıt-Kerbela

Karanfilim ağlama

Ciğerimi dağlama

Bu dert asıl benimdir

Hele dur sen çağlama

Savaş-Kerbela

Kızıl gülle doldu dere

Nere gitsin bu can nere

Birden kılıçlar çekildi

Nice başlar düştü yere

Kan sel olmuş akıyor

Şu bahtsız Kerbela''da

Hasreti can yakıyor

Figan yüklü sılada

Meydan

Dörtnala gelir atlılar

Şimşek kanatlılar

Istıraba dalarlar

Yiğitler çatık kaşlılar

Müslim Akil

Yolları toza kesti

Kufe''ye doğru esti

O şehrin ufukları

Geçit vermez bir sisti

Kufe bir zindan idi

Ateşlerle ışıdı

Müslim bir arslan idi

Ateşleri taşıdı

Dev başlı ordu geldi

Sanki veba yeliydi

Müslim Rabbi''ni bildi

Sanki aşkın seliydi

Ufuk

Nereden bulacaksın

Ali gibi yiğiti? 

Kadrini yazamazsın

Alsan kalemi diviti

Renk

Cesaret arıyorsan

Ali sana örnektir

Letafet arıyorsan

Ali sana bir renktir

Sitem

Ehli Beyt''i sevmez misin

Kadirlerin bilmez misin

Ali gibi yiğit var mı

Cahil misin görmez misin? 

Vefa-Hüseyin

Geçmiş dünya malından 

Yürür Hakk''ın yolundan

Koparmaz ham meyvayı

Ağacından dalından

Ehli Beyt''e Selam

Göçmen kuşlar geliyor

Yüreğimi diliyor

İçimdeki şu derdi

Sade Allah biliyor

Patika yokuşlara

Dağlar ile taşlara

Benden selam söyleyin

Asaletli başlara

Yine Çile-Hüseyin

Katar gözyaşını kuru aşkına

Kardelenler dolar garip başına

Derdini anar da  unutur vakti

Katar kanlı yaşı gönül yaşına

Huşu

Bir ok geldi ayağına

Durdu Hakk''ın divanına

Oku fark bile etmedi

Kattı iman imanına

İlim

İlmin kapısı Ali

Açar kilidi Ali

Kalbime pek sevgili

Hayber yiğidi Ali

Şüphesiz

Kim ki senden Ali''yi sual ederse

De ki yiğitlerin şahıdır Ali

Kim bu açık gerçekten şüphe ederse

Nur balçıkla sıvanmaz artık bilmeli

Hasret

Bir iş var bugün gökte

Acep n''oldu bilemedim

Ali yok mu bugün cenkte? 

Gelmedi mi bilemedim

Soru

Aşkın sancağını yüceltmedi mi

Kalbimizde yatan İmamı Ali

Zulmün bıçağını köreltmedi mi

İmana haz katan İmamı Ali? ? 

Hareket

Tozlar toza karıştı

Atlar çölle yarıştı

Şahı Merdan''ı gören

Göğün gözü kamaştı

Vuslat

Ali''m varır Hayber''e

Atılır kor çembere

Bak yürüyor burçlara

Göğsünü gere gere

Savaş

Merhap atıldı meydana

İçinde hiddet alevi

Saldırdı Şahı Merdan''a

Tir tir titrer gönül evi

Yas

Yankı verir yalçın dağlar

Cnevinde bir kız ağlar

Şahı Merdan şehit olmuş

Çağlar boyu dağlar ağlar

Sevgi-Hüseyin

Aşkı beni dağdan atar

Yüreğime ateş katar

Bu kapkara sevda her dem

Benim canevimde yatar

Ali''dir O

Bilmez misin Ali''yi

Denizdeki inciyi

Duru güneşe çeken

Kara şallı geceyi? 

Fakirleri doyurdu

Adaleti buyurdu

Ömür boyu her daim

Mazlumları kayırdı

Hayber

Hayber''in ufukları

Kesilir solukları

Ali''nin heybetinden

Ter dolar şakakları

Kerbela Çölü

Güneş sılaya iniyor

Kafam kalbimi dinliyor

Hüseyin''in gamıyla

Kerbu bela inliyor

Peygamber''in duası

Kerbela''nın havası

Yüreğe hançer çalar

Hüseyin''in sedası

Acılar

Ehli Beyt''in acıları

Elem keder hancıları

Tarihlerde sızlıyor

Kalplerinin sancıları

Nebi''nin kutlu yolu

Biz bilmeyiz sağı solu

Başımıza tac etmeyiz

Kara akçeyi pulu

Aşığız Ehli Beyt''e

Zerafete heybete

Canımız hasret kalır

Affa hem merhamete

Nergis dolmuş tarlalar

Okunuyor salalar

Ehli Beyt ruhun vermiş

Salınıyor dualar

Ali-Heybet

Gök yıkılsa korkmazdı

Yer yarılsa korkmazdı

Binler üstüne gelse

Sayısına bakmazdı

Bulsa dört dirhem akçe

Gizli açık gündüz gece

Dağıtırdı hepsini

Sakata yaşlıya gence

Doyururdu yetimi

Hem yoksulu esiri

Evlatlar yetiştirdi

Pek kahraman her biri

Çile-Hasan

Zaman hiç durmuyor ki

Gönül durulmuyor ki

Acı dolu bu ilde 

Artık durulmuyor ki

Dalgalanıyor nehir

Ateş oluyor zehir

Zalimin kalbi donmuş

Hem pas bağlamış hem kir

Zeynep

Kase kase dert içti

Acılar bağrın biçti

Altı dumansız ateş

İnce köprüden geçti

Sesine çöl yankı verir

Zalimler peşpeşe gelir

Ehlinin acısını

Bilir O kesin bilir

Zeynelabidin

Çocuktu içi yanan

Gönlün acıya banan

Mevsim alev de olsa

Bir yanıp bir de donan

Elveda

Elveda dostlarıma

Onlara yurtlarına

Doyamadan gittiler

Kısa hayatlarına

Son

D', 'Fatıma''nın gözyaşları Serveri alem için Cennet kadınlarının hanımefendisi Yangın yürekli ana Rasul''ün firakından bağrı dağlanan ana Ve Aliyy...', ARRAY['Türk Edebiyatı','Şiir','Murat İnan']::text[], 8.5, '{"poet":"Murat İnan","poet_slug":"murat-i-nan","theme":"Türk Şiiri","is_hero":false,"total_lines":309,"source_url":"https://www.antoloji.com/ehli-beyt-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış', 'baris-hakki-hakan-kaya-j348o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Solar yine gönül bahçemin gülleri

Esince rüzgarları karamsarlığımın

Hasret kalır güle aşk bülbülleri

Sebebimidir yare yandığımın

Çöker üstüme yanlızlığımda gecenin karanlığı

Bir çare bir umar arar dururum

Kurtuluşumdur tek bir hüzme mum ışığı

Umudumu rüzgarlara savururum

Kalınca gönüller susuz açmadan solar

Yeniden dirilmeye yaşamaya çalışırım

Ne zaman yorgun bedenim toprakla dolar

İşte o zaman affeder sevdiğimle barışırım', 'Solar yine gönül bahçemin gülleri Esince rüzgarları karamsarlığımın Hasret kalır güle aşk bülbülleri Sebebimidir yare yandığımın Çöker üstüm...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/baris-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-umut-gul-qxipk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu akşam her yer karanlık, 

Sokaklarsa bomboş, 

Sokak lambaları yanıp, sönüyor; 

Belli ki onlarda benim gibi sarhoş...

Bu akşam yüreğim sıkıntıda, 

Odam ise sessiz, 

Bir gün daha geçti ömrümden, 

Bir gün daha sensiz...

Bu akşam inceden bir yağmur yağıyor, 

Duvarda ki resmin sanki ağlıyor, 

Bu akşam başka bir akşam, 

Sanki dünya tersine dönüyor...', 'Bu akşam her yer karanlık,  Sokaklarsa bomboş,  Sokak lambaları yanıp, sönüyor;  Belli ki onlarda benim gibi sarhoş... Bu akşam yüreğim sıkı...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-aksam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babem', 'babem-adem-gunes-hnzwp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '**Dünyanın dört bir yanında bayramlık elbiselerine aldırılmadan öldürülen çocuklara ithafen....***

Aramayın boşuna, kainatın tek suçlusu benim! ..

Bayramlık elbiselerine aldırmadan, çocukları vuran benim! ..

Benim! ... Benim diyorum size duymuyormusunuz, tek suçlu benim...

Babey, babey ağıtlarına kulaklarını tıkayıp bayram yapan benim! ...

Babem, biliyorum daha ölmedin ölmeyeceksin...

Sabah kalkıp, bayramlık elbiselerini giyeceksin, 

Bir banyo yaptırır anen sana, 

Çıkar yüzündeki kan izi göreceksin! 

Yarın bayram unuttun mu? 

Şeker torbanla mahalleleri gezeceksin...

Sabah ezanı okunuyor, siz hala uyuyor musunuz? 

''''Suçlu benim'''' diyorum, beni neden asmıyor sunuz? 

Babam sokaklarda yatıyor, hala mı görmüyor sunuz? 

O şeker toplamadan, siz nasıl bayram yapıyor sunuz? 

Babey! Babey... İki elim yakanda babey! ..

Bayramlar hani benimdi? Sen nasıl gülersin babey! 

Elim kolum tutmaz, al kucağına beni babey! 

Mahalleleri birlikte gezelim babey! 

Babem sus babem, çatlayacağım! ...

Çocuk olup, sokak sokak zıplayacağım, 

Gözlerimi yitirdim, ben nasıl ağlayacağım...

Oyuncaklarınla gayri ben oynayacağım...

Babem biliyorum daha ölmedin ölmeyeceksin...

Sabah kalkıp bayramlık elbiselerini giyeceksin...

Bir banyo yaptırır annen san, 

Çıkar yüzündeki kan izi göreceksşn

Yarın bayram unuttun mu? 

Şeker torbanla mahalleleri gezeceksin...', '**Dünyanın dört bir yanında bayramlık elbiselerine aldırılmadan öldürülen çocuklara ithafen....*** Aramayın boşuna, kainatın tek suçlusu ben...', ARRAY['Türk Edebiyatı','Şiir','Adem Güneş']::text[], 8.5, '{"poet":"Adem Güneş","poet_slug":"adem-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/babem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-adem-gunes-vz52o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koca elli... Koca koca ayaklı.. Saçları ak''lı bir bebeyim...

Uzat göğsünü anne uzat, son bir kez daha emeyim...

Çıkart, neredeyse bilyalarım, oyuncaklarım, arabalarım...

Sen kazak örerken ben yerlerde emekleyeyim...

Büyütme anne, sakın büyütüp büyük adam etme beni, 

Küçült, öyle bir küçült ki, iğne deliğinde uyut beni, 

Aman kimselere gösterme, koynunda getir götür beni, 

Dünyada bir sen bir de benden başka k, mse yok sanayım...

Ağlarsam zannetme, yüreğime bir sızı indi, 

Ya karnım acıktı, ya gözlerime uyku girdi, 

Deme sakın yaşın yetişti, konuşma vaktin geldi, 

Öğrendiğim tek kelime ALLAH, bırak ben onu kekeleyeyim', 'Koca elli... Koca koca ayaklı.. Saçları ak''lı bir bebeyim... Uzat göğsünü anne uzat, son bir kez daha emeyim... Çıkart, neredeyse bilyalarım...', ARRAY['Türk Edebiyatı','Şiir','Adem Güneş']::text[], 8.5, '{"poet":"Adem Güneş","poet_slug":"adem-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zaman-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar Bayram Ola - 3', 'bayramlar-bayram-ola-3-abdurrahim-karakoc-1p1r5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalkarım her sabah kötü bir günde

Yüreğim zindanda, sevgim sürgünde

Engeller yol vermez, gelemem oğul! 

Taşırım başımda başıboşları

Konuşur karşımda mezar taşları

Diriler dil vermez, bilemem oğul! 

Tecellim çiledir, çeker giderim

Gözyaşı selinde akar giderim

Dostlarım el vermez, kalamam oğul! 

Hasretim göl göldür, hicranım nehir

Toprağım kor ateş, havam som zehir

Arılar bal vermez, alamam oğul! 

Ben aşka koşarım, aşk beni vurur

Yaklaştığım deniz içimde kurur

Bahçeler gül vermez, gülemem oğul! 

Bayramlar kurşundur, canımda kalır

Yazdığım tebrikler yanımda kalır

Postacı pul vermez, salamam oğul! 

(Suları Islatamadım)', 'Kalkarım her sabah kötü bir günde Yüreğim zindanda, sevgim sürgünde Engeller yol vermez, gelemem oğul!  Taşırım başımda başıboşları Konuşur ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bayramlar-bayram-ola-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırınız İçin', 'hatiriniz-i-cin-adem-gunes-t9qe4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zannetmeyin dünyanız çok hoşuma gitti diye yaşıyorum, 

Gidecek yerim olmadığı için aranızda dolaşıyorum, 

Gözlerinize dikkatli dikkatli baktığıma sakın aldanmayın, 

Bir kelimenizi bile anlamıyorum, hatırınız için kafa sallıyorum

Bazen, kendimden şüphe ediyorum, ''''benle aynı dili mi konuşuyorsunuz? ! ''''

Akşam olunca neden ölü taklidi yapıyor, sabah olunca diriliyorsunuz? ! 

Biliyorum, hepiniz el birilği ettiniz benimle alay ediyorsunuz! 

Neye gülüp ağlıyorsunuz anlamıyorum, hatırınız için sizin gibi yapıyorum...

Hadi diyelim ki, ölü taklidi yapmıyor da, gerçekten ölüyorsunuz! ..

Sonra bir parça toprak kazıp, birbirinizi gömüyorsunuz, 

Gündüzleri anladım da, geceleri mezarda yatmaya hiç mi korkmuyor sunuz? 

Durduk yere niye ölüyorsunuz anlamıyorum, hatırınız için sizi dinliyorum...

Milyarlarca insanın arasında yabancılık çekmeden nasıl yaşıyorsunuz? 

Bunca insan, birbirinin içinden çıkıyor! İç içe nasıl sığıyorsunuz? 

Hadi hepsini anladık diyelim, kaşınızı gözünüzü kime çizdiriyor sunuz? 

Söylediklerinize inanmıyor, hatırınız için sesimi çıkartmıyorum...', 'Zannetmeyin dünyanız çok hoşuma gitti diye yaşıyorum,  Gidecek yerim olmadığı için aranızda dolaşıyorum,  Gözlerinize dikkatli dikkatli bakt...', ARRAY['Türk Edebiyatı','Şiir','Adem Güneş']::text[], 8.5, '{"poet":"Adem Güneş","poet_slug":"adem-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatiriniz-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar Bayram Ola - 4', 'bayramlar-bayram-ola-4-abdurrahim-karakoc-1pxpp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağma var yukarı katta

Benim canım çıkar altta

Çabalarım, akar terim

Allah kerim.

Zulüm köklendi, dallandı

İşkenceler “yasal”landı

Küfür içer, zılgıt yerim

Allah kerim.

Yokluk kırıyor dizimi

Zamlar güldürür yüzümü(!)     

Sıkıntıdan kalkmaz serim

Allah kerim.

Bayram gelmiş.. gelir belki

Ben tebrik-mebrik bilmem ki

“Bayram bayram ola” derim

Allah kerim.

Suları Islatamadım', 'Yağma var yukarı katta Benim canım çıkar altta Çabalarım, akar terim Allah kerim. Zulüm köklendi, dallandı İşkenceler “yasal”landı Küfür içe...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bayramlar-bayram-ola-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaflet', 'gaflet-adem-gunes-o6egz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dilim! ... Seni dilim dilim doğrararım! ...

Kainat, Allah derken sen nasıl susarsın! 

Boğazım, seni gırtlağınan tutar boğarım, 

Komşun aç yatarken, sen nasıl tok yatarsın? ! ...', 'Dilim! ... Seni dilim dilim doğrararım! ... Kainat, Allah derken sen nasıl susarsın!  Boğazım, seni gırtlağınan tutar boğarım,  Komşun aç ya...', ARRAY['Türk Edebiyatı','Şiir','Adem Güneş']::text[], 8.5, '{"poet":"Adem Güneş","poet_slug":"adem-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gaflet-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Şiir', 'son-siir-ahmet-tacyildiz-iybrs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sana yazdığım son şiir olsun

Seni anlatan aşkımı anlatan

Bu sana yazdığım son şiir olsun

Ümitsizce yaşanan günleri anlatan

Kimbilir şimdi nerdesin

Kimlesin söyle kimlerlesin

Ben burada acı çekerken

Acaba hangi sevgilinlesin

Evimin kadını olsa idin yolumun yoldaşı

Derdimin ortağı sırrımın sırdaşı

Kimseye göstermez saklardım seni

Çocuğumun annesi canımın candaşı

Şimdi süzüldü gözümden iki damla yaş

Sana kurban olayım ey çatık kaş

Akşam olunca hazırlasa idin iki lokma aş

Kocam geliyor diye bir acele bir telaş

Hatamı ediyorum yoksa bilmiyorum

Seni severken sevmiyorum diyemiyorum

Çaresizim seviyorum özlüyorum

Genede bu şiir son şiir diyorum', 'Bu sana yazdığım son şiir olsun Seni anlatan aşkımı anlatan Bu sana yazdığım son şiir olsun Ümitsizce yaşanan günleri anlatan Kimbilir şimdi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Taçyıldız']::text[], 8.5, '{"poet":"Ahmet Taçyıldız","poet_slug":"ahmet-tacyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-siir-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kürşat', 'kursat-ergun-yildirim-aaeyi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yorgun mahallenin, bezgin savaşçısı 

Hayat kavgasında zorlu bir gün daha 

Ürkek adımlar ağzında bafra sigarası 

Belki bugün farklı olurdu herşey belki kazanırdı 

Sonra uyandırdı onu bu hayalden 

Cebindeki bir tek otobüs parası 

Neden herşey bu kadar ters gidiyordu 

Neden herşey bu kadar yanlıştı 

Oysa şimdiye kadarki hayatında hep doğru davranmış, 

Hep iyi şeyler yapmış, hiç yanlışa sapmamıştı 

Sonra düşündü kürşat demekki hata kendisinde değil 

Hata bu kahpe hayattaydı 

Kendi kendine söz verdi yenilmeyecekti bu hayata 

Pes etmeyecek galip çıkacaktı. 

İşte herşey bu kadar ümitsizken 

O çıkıverdi karşısına 

Deli yüreği kendisine bile yetmezken 

Meydan okuyordu dünyaya tek başına 

Birbirlerini okadar çok sevmişlerdi 

Bu kahpe hayatın çirkin tuzaklarına 

Alay edip gülebilmişlerdi 

Hani pes etmeyecekti ya Kürşat, 

Hani galip çıkacaktı ya olmadı 

Vurdu alnının şakına ihanetin tokadı 

Dağ gibi bir adam böylesine yıkılırmıydı 

Hakmıydı bu revamıydı 

Sonra bir ceset buldular sabahın onunda 

Gözünde iki damla yaş, ve bir papatya 

Denizin kıyısında yosunlar arasında. 

Yenilmişti kürşat başaramamıştı 

Fakat bu filmin her karesinde 

Şerefi ve onuruyla yer almıştı. 

.', 'Yorgun mahallenin, bezgin savaşçısı  Hayat kavgasında zorlu bir gün daha  Ürkek adımlar ağzında bafra sigarası  Belki bugün farklı olurdu he...', ARRAY['Türk Edebiyatı','Şiir','Ergün Yıldırım']::text[], 8.5, '{"poet":"Ergün Yıldırım","poet_slug":"ergun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kursat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar Bayram Ola - 6', 'bayramlar-bayram-ola-6-abdurrahim-karakoc-ma9sy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alem-i İslam''a rahmet su gibi

Aksın bayram olsun bayramlarınız.

Evleriniz cennet kokusu gibi

Koksun bayram olsun bayramlarınız.

Zindan medresedir gam yayla size

Farkı yok bin yılın bir ayla size

Melekler yukardan gıptayla size

Baksın bayram olsun bayramlarınız.

Uygur Kazak Kırgız Azeri''nizden

Gitmesin gardaşlık nazarınızdan

Zalimler zulmünü üzerinizden

Çeksin bayram olsun bayramlarınız.

Süleyman esir de Simon neden hür

Hiç durma dünyanın yüzüne tükür

Müslümanın sesi münafıktan gür

Çıksın bayram olsun bayramlarınız.

Serilsin gönüller döşek misali

Patlasın sevgiler fişek misali

Hakikat durmadan şimşek misali

Çaksın bayram olsun bayramlarınız.

Haksızlık almasın Hak''kın yerini

Aşsın boyunuzdan aşkın derini

Kimi gözyaşını kimi terini

Döksün bayram olsun bayramlarınız.

Kök bir dallar ayrı ki İslam bir gül

Afganistan bir gül Türkistan bir gül

Vahdet bahçesine her insan bir gül

Diksin bayram olsun bayramlarınız.

Mağdurlar mazlumlar ersin felaha

Vuslata varanlar varsın bir daha

İrfan tohumunu gece sabaha

Eksin bayram olsun bayramlarınız.

Kandır zalimlerin zulüm çiçeği

Öldürür cehalet ölüm çiçeği

Gençler yakasına ilim çiçeği

Taksın bayram olsun bayramlarınız.

Şehide toprağın hürmet-i aşkı

Anadan fazladır şefkat-i aşkı

Rab''bim yüreklere ülfeti aşkı

Soksun bayram olsun bayramlarınız.

Hazreti Resul''ün nurlu katına

Gitmek isteyenler binsin atına

Küfrün saltanatı yerin altına

Çöksün bayram olsun bayramlarınız.

Ne makam ne para olamaz ölçek

Kurtuluş İslam''da vallahi gerçek

Bu mübarek sevda bizleri tek tek

Yaksın bayram olsun bayramlarınız.

(Beşinci Mevsim)', 'Alem-i İslam''a rahmet su gibi Aksın bayram olsun bayramlarınız. Evleriniz cennet kokusu gibi Koksun bayram olsun bayramlarınız. Zindan medre...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bayramlar-bayram-ola-6-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayacağım', 'unutmayacagim-hakan-guner-osizw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vurabilirsen ayağını sertçe yere 

Haykırabilirsen beni sevmediğini herkese

Girebilirsen yüreğinin götürdüğü yere 

Sana söz seni unutacağım

Çözebilirsen kalbimin pranga kilidini 

Durdurabilirsen içimdeki gözyaşı selini

Görebilirsen içi kan ağlarken gülenleri

Sana söz kalbimi kapatacağım

Çizebilirsen hayalinde sevginin resmini

Anlayabilirsen kelimelerin kifayetsizliğini

Dokunup çıkarabilirsen içimdeki seni

O zaman seni unutacağım', 'Vurabilirsen ayağını sertçe yere  Haykırabilirsen beni sevmediğini herkese Girebilirsen yüreğinin götürdüğü yere  Sana söz seni unutacağım Ç...', ARRAY['Türk Edebiyatı','Şiir','Hakan Güner']::text[], 8.5, '{"poet":"Hakan Güner","poet_slug":"hakan-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutmayacagim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmayacağım', 'seni-unutmayacagim-hakan-guner-lnta7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vurabilirsen ayağını sertçe yere 

Haykırabilirsen beni sevmediğini herkese

Girebilirsen yüreğinin götürdüğü yere 

Sana söz seni unutacağım

Çözebilirsen kalbimin pranga kilidini 

Durdurabilirsen içimdeki gözyaşı selini

Görebilirsen içi kan ağlarken gülenleri

Sana söz kalbimi kapatacağım

Çizebilirsen hayalinde sevginin resmini

Anlayabilirsen kelimelerin kifayetsizliğini

Dokunup çıkarabilirsen içimdeki seni

O zaman seni unutacağım', 'Vurabilirsen ayağını sertçe yere  Haykırabilirsen beni sevmediğini herkese Girebilirsen yüreğinin götürdüğü yere  Sana söz seni unutacağım Ç...', ARRAY['Türk Edebiyatı','Şiir','Hakan Güner']::text[], 8.5, '{"poet":"Hakan Güner","poet_slug":"hakan-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-unutmayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendeki sen', 'sendeki-sen-erol-sen-tuech', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sendeki seni istiyorum 

Bana koşulsuz gelmeni istiyorum

Bana sorgusuz sualsiz gelmeni

Ben sendeki seni istiyorum kendime

Sorgulamadan düşünmeden istiyorum

Nasıl olursa olsun benim olmanı 

Yada elin olmanı

İstiyorum bekliyorum olacaksan

Düşümde değil gerçek seni

Verilen sözlerin bile anlamı kalmıyor

Siliyorum hafızamdan hepsini

İstediğinde neler yapıyorsun ben yokken

Affetmek zor olsada sevginin gücüyle

Uzatılan eller tutuluyorsa çıkarsız

Beklentisiz vede sevgi saygıyla

Arkadaşlarına sor bakalım sıkıntıyla

İstediğinde yapıyorsan amaçsız

Bir amacın var düşüncelerinde

Kabullenmek zor çok zor olsada

Benim istediğim sendeki sen 

Boşluk yaşamın parçası yaşananlarda

Yokken yaşananlara maya tutsa yok olacak sevgiler

Yok olacak çok sevilen sevgili öylemi

İstenmeyen benim anladım sonunda

Söylendi bu akşam son defa son sözler

Söylendi bu akşam beklentiler umutlar

Ya devam edecek yada bitecek

Devamı sendeki seni istiyorum...

11.04.2002', 'Sendeki seni istiyorum  Bana koşulsuz gelmeni istiyorum Bana sorgusuz sualsiz gelmeni Ben sendeki seni istiyorum kendime Sorgulamadan düşünm...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sendeki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-alparslan-aydin-2ggjd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıl bilinmezde, 

Yol dönülmezde iken, 

Bir masal oldu hayat...

Öyle bir masal ki ne kaf dağı var.

Ne ardında zümrüdü anka; 

Yalnız hüzün kaldı, 

Yalnız gözyaşı...

Gökten elma değil düşen; 

Koskoca üç dert taşı.

Biri benim başıma, bir benim...

Biri de... Yine benim...

Bu masalda mutlu son yok; 

Bu masalda kırk gün kırk gece düğün...

Bu masalda hasret var, 

Bu masalda kırk yıl kırk asır hüzün...', 'Yıl bilinmezde,  Yol dönülmezde iken,  Bir masal oldu hayat... Öyle bir masal ki ne kaf dağı var. Ne ardında zümrüdü anka;  Yalnız hüzün kal...', ARRAY['Türk Edebiyatı','Şiir','Alparslan Aydın']::text[], 8.5, '{"poet":"Alparslan Aydın","poet_slug":"alparslan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/masal-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nezih Guzelliklerin essiz Timsaline', 'nezih-guzelliklerin-essiz-timsaline-yavuz-nufel-n0miw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(Sevgili Sezen Aksuya) 

korsan sloganlarını

yasak aşkının 

pankart pankart yazmasan da, 

diren; 

teslim olma. 

SEVDA DÜŞMEMİŞ YÜREKTE, 

Rh POZİTİF DE OLSA KAN; 

PASAKTIR! 

töre midir, tabu mudur, 

namus mudur bilinmez; 

bazı aşklar YASAKTIR! 

Belki, 

eylül sarısı ruhunun 

zamansız açmış kardelenidir 

ya da; 

çeyrek yamalak yaşanmış 

ömrünün son yeşilidir 

devşir! ... 

o sevda ki, 

sevdasını ''dava'' yamış 

yürektir 

ve o yürek 

anarşist aşkına 

kapılarını açmış 

hücre evidir 

Durma gir! ...

 Yavuz Nufel

Rotterdam Hollanda (siirmatik''den)', '(Sevgili Sezen Aksuya)  korsan sloganlarını yasak aşkının  pankart pankart yazmasan da,  diren;  teslim olma.  SEVDA DÜŞMEMİŞ YÜREKTE,  Rh P...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Nufel']::text[], 8.5, '{"poet":"Yavuz Nufel","poet_slug":"yavuz-nufel","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/nezih-guzelliklerin-essiz-timsaline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkına Varmadan', 'farkina-varmadan-sinan-mujdeci-t7wdo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben başında saç olsaydım, 

Her gün ellerine dokunabilirdim.

Her gün ben savrulurdum 

Senin yerine.

Her gün seninle olurdum.

Gözlerinde sakladığın damla olamak 

Olmak isterdim.

En hüzünlü anlarında dokunurdum

Yanağına

Ve birazım tadardı dudaklarından

Sen anlamada.

Ben kahkahaların olmak isterdim.

Ta yüreğinden kopup gelirdim o zaman

Ve kulaklarını çınlatarak

Tekrar sığınırdım yüreğine

Sen farkına varmadan.

Baktığın ayna olmak her sabah, 

Seni seyretmek

Bensiz geçen her gecenin sabahında

Umutlu görmek ve farkıma varmadan

Gözlerinde seni dilemek.

Sana hiç tatmadığın duyguları 

Yaşatmak, 

Aklının en  deli yerlerinde var olmak

Ve utandıran düşlere götürmek 

Gecenin bir vakti uyandırarak

Sonra, 

Tekrar hatırlatmak beni sana

Ve hüzünlendirmek

İsyan ettirmek

Dünyayı hiçe saydırmak

Çıldırtmak isterdim seni

Ve günahlarıma ulaşmadan 

Önce

İkimizden yeşerecek o selvi çam

Ağacının

Hayat kaynağı olmak isterdim senle

Sonsuz olmak isterdim

Hiç sarartmadan yapraklarımızı

Her gün biz diye doğardık

Farkına varmadan

O bir avuç kara topraktan.    

(İst.11/04/2002)', 'Ben başında saç olsaydım,  Her gün ellerine dokunabilirdim. Her gün ben savrulurdum  Senin yerine. Her gün seninle olurdum. Gözlerinde sakla...', ARRAY['Türk Edebiyatı','Şiir','Sinan Müjdeci']::text[], 8.5, '{"poet":"Sinan Müjdeci","poet_slug":"sinan-mujdeci","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/farkina-varmadan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanılmaz Alev', 'dayanilmaz-alev-i-rfan-topcu-bh3pw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sevda ateşine düşünce bir bak, 

sonun yavaş yavaş bir köz olacak.

inan bu aleve hiç dayanılmaz, 

güvendiğin su''mu su''da yanacak.', 'sevda ateşine düşünce bir bak,  sonun yavaş yavaş bir köz olacak. inan bu aleve hiç dayanılmaz,  güvendiğin su''mu su''da yanacak....', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dayanilmaz-alev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-i-rfan-topcu-fg9v4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayakkabı boyayan küçük çocuk,

Kalbi ne kadar temiz, 

Elleride öyle,

Hemde, 

Müşterisinin yüzünden.

Belli,

Her ikisininde gözünden', 'Ayakkabı boyayan küçük çocuk, Kalbi ne kadar temiz,  Elleride öyle, Hemde,  Müşterisinin yüzünden. Belli, Her ikisininde gözünden...', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cocuk-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırklar''ın Duâsı', 'kirklar-in-du-si-mustafa-engin-karatay-6964j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Bu bir rüyâ değildir!)   

Uykumun ortasında, sayhâ ile uyandım 

Gâibden nidâ geldi, kalk! Fırla döşeğinden! 

Ürpertiyle işittim; kan-terlere boyandım 

Nûr yumağı süzüldü, kapının eşiğinden... 

Titreme sardı birden; 

.............................Dedim: 

........................................-Mahvoldum, yandım... 

Fer gitti gözlerimden, şeklim kaskatı oldu 

Rengi uçtu benzimin, isfirâr üzre soldu 

Kuşattı bir sessizlik, hükmetti her tarafa 

Korkudan bakamadım, göz ucuyla etrâfa 

Tüylerim diken diken, kalbim güp-güp vuruyor 

Kapı aralığında, sanki gölge duruyor 

Pür-dikkat bekliyorum; aceb ne ola şimdi? 

Bir yandan da merâkım; sesin sâhibi kimdi? 

Hayâlimde, Bin türlü düşünceler oluştu 

Beynime hücûm edip, hepsi orda buluştu... 

İkinci bir komutla geldi yeni bir emir; 

Buzdağının içinde, kestim âdetâ demir... 

-Düş peşime! Tâkib et! Kalk bakalım yerinden! 

-Üstündeki örtüyü, at çabuk üzerinden! 

Peri kızı şekline, bir nûrânî bürünmüş 

Ne hoş koktu ortalık; anber tozu sürünmüş 

Tütsülüyor etrâfı, sağ elinde buhûr var 

Altı-Yedi renk dizdi, buhûrdaki dumanlar 

Gözlerimin ucuyla, iliştim ki yüzüne; 

Siyah sürmeler çekmiş, gökmâvisi gözüne 

Sol elinde âsâsı, zebercet işlemeli 

Zümrüt gibi parlıyor, ona ne demeli? 

Kaldırdı sağa doğru, işâret etti yönü; 

Tüm mekânlar kayboldu, yol oluverdi önü 

Yürüdük yavaş yavaş, istikâmet üzere 

Gidiyoruz birlikte, bilinmeyen bir yere... 

O kadar yoldan sonra, nereye varsak heyhât? 

Dâr-ül Bekâ eyleyen; önümde, Kırkbir Zevât 

Kabristân''a gelmişiz daha Türkçe''si yâni, 

İrkildim birdenbire, görüverince ânî... 

Bir grup kalabalık, mezârlığın başında 

Biri sohbet hâlinde, çün musallâ taşında 

Durakladı ve baktı; dikkatle süzdü beni, 

-Muştulu haber için getirdik bizler, seni... 

-Mahzûn olma! Üzülme! Arkandayız biz senin, 

-Kırklar, bundan böyle bil; oldu duâ edenin! .. 

15.11.2001   Münih    03: 05', '(Bu bir rüyâ değildir!)    Uykumun ortasında, sayhâ ile uyandım  Gâibden nidâ geldi, kalk! Fırla döşeğinden!  Ürpertiyle işittim; kan-terler...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kirklar-in-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Damla', 'son-damla-ensar-aktas-6yivo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyorum bugün kulakların bir başka çınlayacak

Anlayacaksın seni yine nasıl andığımı, özlediğimi

Ellerin titreyecek, gözlerin yollarda kalacak

Sende hissedeceksin yüreğimde neler hissettiğimi

Haykıracaksın hadi yap bir delilik daha çık gel diye

Kahredeceksin kaderin bize paylaştırdığı hasretliğe

Bense isyanlardayım elimi kolumu bağlayan engellere

Anlayacaksın yanındayken zamanı durdurmak isteyişimi

Daldıkça dalacak, batacaksın anılarımızın denizinde

Hissedeceksin saf bir nisan yağmuru taneciği gibi

Gözlerimden düşen damlaların soğukluğunu yüzünde

Son damlaydı bu bardağı taşıran diyeceksin ve 

Bu kez sen bir delilik yapıp dindireceksin hasretimi

Rotterdam,12.03.2002', 'Biliyorum bugün kulakların bir başka çınlayacak Anlayacaksın seni yine nasıl andığımı, özlediğimi Ellerin titreyecek, gözlerin yollarda kala...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/son-damla-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutursun', 'unutursun-aysun-aksu-86trz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutamam deme unutursun

Kimleri unutmadıkki geçmişte

Dostlar, arkadaşlar, şimdi nerede

Kaybettiklerimiz gökyüzündeyken

Biz gülmedikmi eğlenmedikmi

Yazları neşeyle karşılayıp 

Kışları, karları hiç sevmedikmi

Baharla yeşerip baharla solan

Yaprakları, hüzünle seyretmedikmi

Unutamam deme unutursun

Nerde ilk sevgilin, nerde sonraki', 'Unutamam deme unutursun Kimleri unutmadıkki geçmişte Dostlar, arkadaşlar, şimdi nerede Kaybettiklerimiz gökyüzündeyken Biz gülmedikmi eğlenm...', ARRAY['Türk Edebiyatı','Şiir','Aysun Aksu']::text[], 8.5, '{"poet":"Aysun Aksu","poet_slug":"aysun-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/unutursun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Şiir Daha Yazılmadı', 'en-guzel-siir-daha-yazilmadi-muhtesem-oksel-y5k7o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O en güzel şiir, daha yazılmadı.

Bir gün gelecek, biliyorum

Ve bekliyorum, 

Kimselerin hissedemediği o ilhamı.

Bu dünyadan ötekine göçen, 

Her şairin ardından söylenir.

“Onunla bitti” diye şiir.

Diyebilirler, 

Desinler inanmıyorum.

Daha yazılmadı o en güzel şiir.

Biliyorum, daha yazılmadı

Kimi şairler çok yaklaştı, 

Ama anlatamadı.

Ben daha yaklaşamadım, 

Duyamadım.

Ama biliyorum, 

Daha yazılmadı o şiir.

O şiir, “El Dorado” gibi, 

Kayıp bir altın şehir.

Anlatıyor efsaneler varlığını.

Çok şairler, gezginler aradı, 

Ama halâ onu bulamadı.

Cennetten bize kalan, 

Bu dünyaya getirdiğimiz, 

Tek miras aşk gibi, 

Coşturan ruhları, 

Dinleyip de geçenin, asla olmayacağı, 

Biliyorum, o şiir daha yazılmadı.

Yürüyorum onu bulmak için, 

Elimde bir harita olmadan.

Yazık ki, bana yön göstermiyor yıldızlar.

Ve hiçbir şey söylemiyor kuşlar.

Kelimeler dans ediyor kafamda.

Yanımda ne bir kılavuz, ne bir pusula

Ben o şiiri arıyorum.

Yeterse bu ömür, 

Boşalana dek kum saati, 

Nerede bulurum bilmiyorum.

Sevdiğimin gözlerinde mi? 

Bir annenin şefkatli elinde mi? 

Bir yağmurun ardından mı? 

Ya da dökülen iki damla gözyaşında mı? 

Nerede bulurum bilmiyorum.

Ama o şiir var, biliyorum.

Düşmüş gözlerim bir kalem ve kağıda

O en güzel şiiri, ben yazmak istiyorum.

Kelimeler dans ediyor kafamda.

Yanımda ne bir kılavuz, ne bir pusula

Ben o şiiri arıyorum.', 'O en güzel şiir, daha yazılmadı. Bir gün gelecek, biliyorum Ve bekliyorum,  Kimselerin hissedemediği o ilhamı. Bu dünyadan ötekine göçen,  H...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/en-guzel-siir-daha-yazilmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağlar Gurbet El', 'baglar-gurbet-el-ensar-aktas-s1d4t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşam olup güneş batınca

Hava kararıp ışıklar yanınca

Gece olup alem uykuya dalınca

Elimi kolumu bağlar gurbet el

Hiç kimseyle dertleşemem

Ne olur sonum hiç bilemem

Annemi babamı yıllardır göremem

Ağzımı gözümü bağlar gurbet el

Hayal etmek bile zor yurdumu

Karanlığa bağlamışım umudumu

Kim çözecek şu kördüğümü

Aklımı fikrimi bağlar gurbet el

Canımın kıymetini bilemiyorum

Artık hasretliğe dayanamıyorum

Cennet vatanıma dönemiyorum

Yolumu sonumu bağlar gurbet el

Rotterdam,06-01-1988', 'Akşam olup güneş batınca Hava kararıp ışıklar yanınca Gece olup alem uykuya dalınca Elimi kolumu bağlar gurbet el Hiç kimseyle dertleşemem N...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baglar-gurbet-el-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hem Ağlarım Hem Giderim', 'hem-aglarim-hem-giderim-ensar-aktas-ydodh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ahh, neden seni bu kadar çok sevdimki ben

Ellerimle seven kalbimi yakıp dağlamak için mi

Ahh, neden sana bu kadar çok bağlandımki ben

Hasretinden ağlayıp gözyaşımı kurutmak için mi

Ahh, senin de beni çok sevdiğini bildiğim halde

Neden korkuyorum ayrılmaktan kaybetmekten seni

Ahh, her fırsatta bana canım, bebeğim dediğin halde

Neden kıskanıyor ve kırıyorum ki ben hep seni

Ahh, sen üzülme sevgilim ben çekip giderim

Yeterki sen ölünceye dek hep sevildiğini bil

Ahh, senin yüzünde tebessümler olsun isterim

Ben hem ağlarım hem giderim sen gözyaşını sil

Rotterdam,27.02.2002', 'Ahh, neden seni bu kadar çok sevdimki ben Ellerimle seven kalbimi yakıp dağlamak için mi Ahh, neden sana bu kadar çok bağlandımki ben Hasret...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hem-aglarim-hem-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamadım', 'bulamadim-ensar-aktas-n7l24', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni ellerimle yolcu ederken

Gitme diye haykıracak ses bulamadım

Gidişine içim kan ağlıyorken

Ardından akıtacak yaş bulamadım

Şu gönlüm sevginle öyle dolmuşki

Aşkına çekecek rest bulamadım

Hasretine dayanmak öyle zormuşki

Bağrıma basacak taş bulamadım

Ağlamaya razıydım sen yanımda olunca

Yokluğunda mutluluğa heves bulamadım

Yaşamak neye yarar sen olmayınca

Uğrunda vurduracak baş bulamadım

Rotterdam,04.08.1990', 'Seni ellerimle yolcu ederken Gitme diye haykıracak ses bulamadım Gidişine içim kan ağlıyorken Ardından akıtacak yaş bulamadım Şu gönlüm sevg...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bulamadim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istırap Yağmuru', 'istirap-yagmuru-ensar-aktas-bthhy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben yalnız halime

Seni düşünürken bakıp resmine

Cama vuran damlalar

Gittiğin yollara yağan yağmurlar

Rahmet degil sevgilim

Istırap yağmuru

Ağlayarak daldım maziye

Hatırladım ikimizi elele

Şimdi ellerim boş gözümde yaşlar

Yanağımdan akan damlalar

Gözyaşı değil sevgilim

Istırap yağmuru

Rotterdam,04.11.1988', 'Ben yalnız halime Seni düşünürken bakıp resmine Cama vuran damlalar Gittiğin yollara yağan yağmurlar Rahmet degil sevgilim Istırap yağmuru A...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istirap-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayamam', 'aglayamam-ensar-aktas-o77o5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittiğin gün beni öldü sandılar

Aşkını mezara gömdü sandılar

Sel gibi gözyaşı döktü sandılar

Bir vefasız için ağlayamam ben

İçimi yalnızlık sarmış olsada

Kalbimi hasretin yakmış olsada

Gidişin dünyamı yıkmış olsada

Bir vefasız için ağlayamam ben

Rotterdam,02.06.1989', 'Gittiğin gün beni öldü sandılar Aşkını mezara gömdü sandılar Sel gibi gözyaşı döktü sandılar Bir vefasız için ağlayamam ben İçimi yalnızlık ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aglayamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-ensar-aktas-72ue2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Samanyolunu alıp ayaklarına sersem

Yol yapıpta bana gelir misin bu gece

Bütün yıldızları tutup avucuna saysam

Seni ne çok sevdiğimi anlar mısın bu gece

Dünyanın tüm romanlarını okusam hece hece

Anlatabilir miyim seni nasıl sevdiğimi bu gece

Aşkımın tarifi imkansız, sanki bir bilmece

Gelipte çözüver desem, çözer misin bu gece

Dağları üst üste koysam, denizleri iç içe

Anlatabilirler mi seni nasıl özlediğimi bu gece

Kalbime düşmüştü bu yangın beni öpünce

Gelipte nefesinle söndürür müsün bu gece

Rotterdam,02.03.2002', 'Samanyolunu alıp ayaklarına sersem Yol yapıpta bana gelir misin bu gece Bütün yıldızları tutup avucuna saysam Seni ne çok sevdiğimi anlar mı...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-gece-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşksızlıktan', 'asksizliktan-ensar-aktas-8c02u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlümün boşluğundan yakınıyordum

Mutsuzluğum aşksızlıktan zannediyordum

Neden benim de bir sevgilim olmasın diyordum

Öyle bir aşka düştüm ki bin pişman oldum

Rotterdam,10.04.1990', 'Gönlümün boşluğundan yakınıyordum Mutsuzluğum aşksızlıktan zannediyordum Neden benim de bir sevgilim olmasın diyordum Öyle bir aşka düştüm k...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asksizliktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Cumartesi', 'her-cumartesi-ensar-aktas-yhdaq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bana bakma

Sen bana aldırma arkadaşım

Ben her cumartesi

Her cumartesi böyleyim

Şu gördüğün koca dünya

Bir açıkhava meyhanesi

Şu aldığım her soluk

Her nefesim

Şarapların en yıllanmışı 

Kadehlerin en zehiri

Şu gördüğün kirli deniz

Şu ürkütücü yağmur

Gözlerimden akan

Yüreğimden çağlayan

Kan sağanakları 

Şu üzerinde yürüdüğüm topraklar

Bedenimden dökülmüş sanki

Kırılmış kalbimin 

Yüreğimin parçaları 

Korkma sende çiğne

Bas üzerine çekinme

Bana artık acı değil

Keder değil

Mutluluk veriyor çiğnenmek

Ayaklar altında

Acılar ayakta tutuyor beni

Uyandırıyor hayallerden

Her cumartesi

Sebebini ne sen sor, ne de ben söyliyeyim

Zaten bende bilmiyorum

Bilemiyorumki

Eğer biliyorsan sen söyle

Ama yok boşver

Boşver birşey söyleme

Sende başlama şimdi

Kırık dökük bir aşk hikayesi mi diye

Yoksa kara sevda, melankoli mi

Ben böyleyim işte

Böyleyim her cumartesi

Hani çok sevdiğin birini kaybedersin

Yıllarca göremezsin

Sonra bir gün ansızın

Karşına dikiliverir

Kollarını açar sana

Uzansan tutacaksın

Dokunacaksın ona

Kavuşacaksın

Ama ne fayda

Dokunmak istediğin anda

Yokoluverir

Uçuverir avuçlarının arasından

Bir kere daha kaybettiğini anlarsın

Bir kere daha yıkılırsın

Bir kere daha kahrolursun

İşte ben her cumartesi böyleyim

Biliyorum

Biliyorum onunda elinden bir şey gelmiyor

Seviyor çok seviyor beni

O da çok özlüyor 

Üzmek istemiyor asla

Kırmak istemiyor biliyorum

Zaten üzülmüyorum da artık

Alıştım

Alıştım ben buralarda

Sahibi tarafından terkedilmiş 

Sokak köpekleri gibi

Avunmaya her cumartesi

Ondan bir iz aramaya

Bir nefeslik kokusunu bulmaya

Sen aldırma

Acıma bu halime arkadaşım

Bak martılar bile alıştı 

Alıştılar benim bu hallerime

Her cumartesi 

Ben her cumartesi böyleyim

Sebepsiz avareyim

Çaresiz hasretlerdeyim

En derin kuyularda

Karanlık kuytularda

Diplerdeyim

Yenilmekteyim

Yenilmekteyim kaderime

Her cumartesi

Ben her cumartesi böyleyim

Ne yaşarım ne ölürüm

Düşünür düşünür üzülürüm

Ben her cumartesi

Sonra bir haber

Bir güzel söz

Bir gülümseme

Unutturur hepsini

Geçiverir bu hallerim

Açıverir yanağımda

Gonca gonca güllerim

Güler yüzüm, sevinirim

Ben her cumartesi böyleyim

Böyleyim her cumartesi ben

Rotterdam,06.04.2002', 'Sen bana bakma Sen bana aldırma arkadaşım Ben her cumartesi Her cumartesi böyleyim Şu gördüğün koca dünya Bir açıkhava meyhanesi Şu aldığım ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/her-cumartesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Yeli', 'seher-yeli-ensar-aktas-wrti0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seher yeli gibi araladım bu sabah perdelerini

Süzülüverdim odanın penceresinden içeri

Körpe bebeklerden daha masum uyuyordun

Güzelliğin melekleri kıskandıracak gibiydi

Kıyamadım uykunu bölüp seni uyandırmaya

Düzeltiverdim yanağına yapışmış birkaç telini

Koklayıp, okşadığım pamuk saçlarının doya doya

İçime çektim mis gibi kokusunu teninin kana kana

Başını kaldırıp usulca göğsüme yaslamak istedim

Çok istedim o kiraz dudaklarından doyasıya öpeyim

Avuçlarımın arasına alıpta o ay ondördü yüzünü

Belki rüyandayımdır diye bölmek istemedim düşünü

Odanın her yerine, her köşesine serpiştiriverdim 

Bahar kokularını kırçiçeklerinin ve sümbüllerin

Yatağına düzdüm bir bir seher vakti ötüşlerini

Ninniler söylesin diye sana sevda bülbüllerinin

Uyanmanı bekleyip ellerimle yedirmek isterdim

Yanıbaşında ki masaya hazırladığım kahvaltıyı 

Biliyorsun canım, seher vakti geçmeden dönmeliyim

Yemeyi unutma sen çok seversin rafadan yumurtayı 

Hüzünlenmesin kardelensi göz bebeklerin uyandığında

Beni göremeyince yanında, yatağının başucunda 

Söz yine geleceğim bir dahaki seher vaktinde, ve...

Yeminler olsun, bu defa sonsuza dek ayrılmamacasına

Rotterdam,30.03.2002', 'Seher yeli gibi araladım bu sabah perdelerini Süzülüverdim odanın penceresinden içeri Körpe bebeklerden daha masum uyuyordun Güzelliğin mele...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seher-yeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Cehennem', 'i-cimdeki-cehennem-ensar-aktas-3ojzd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçimde bir cehennem var 

Sanki yanıyorum 

Yanıyor, eriyorum 

Bu, aşktan mı 

Yoksa aşksızlıktan mı 

Bilmiyorum 

Lakin, seviyorum 

Deliler gibi seviyorum 

İçimde bir cehennem var 

Sanki yanıyorum 

Yanıyor, eriyorum 

Bu, kederden mi 

Yoksa sevinçten mi 

Bilmiyorum 

Lakin, özlüyorum 

Deliler gibi özlüyorum 

İçimde bir cehennem var 

Sanki yanıyorum 

Yanıyor, eriyorum 

Bu, senden mi 

Yoksa benden mi 

Bilmiyorum 

Lakin, seni benden 

Bir parça gibi görüyorum 

Rotterdam,21.11.1991', 'İçimde bir cehennem var  Sanki yanıyorum  Yanıyor, eriyorum  Bu, aşktan mı  Yoksa aşksızlıktan mı  Bilmiyorum  Lakin, seviyorum  Deliler gib...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/icimdeki-cehennem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Bir Dostum Gelecek', 'bugun-bir-dostum-gelecek-i-smail-cem-ozkan-3hb85', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bugün bir dostum gelecek

uzaklardan

yalnız

sade

temiz...

yalnızlığıma

dost olacak, 

o olduğu sürece

yalnızlığım

uzaklara gidecek!', 'bugün bir dostum gelecek uzaklardan yalnız sade temiz... yalnızlığıma dost olacak,  o olduğu sürece yalnızlığım uzaklara gidecek!...', ARRAY['Türk Edebiyatı','Şiir','İsmail Cem Özkan']::text[], 8.5, '{"poet":"İsmail Cem Özkan","poet_slug":"i-smail-cem-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bugun-bir-dostum-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Bir Gece', 'uzun-bir-gece-i-smail-cem-ozkan-rbsne', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzun bir gecede aydınlandı

oturduğum şehir

    projektör tarıyordu

        gökyüzünü

uzun bir ses

    çığlık

        sonra

yıllardır kulağımdan

gitmeyen sesler

dışardaydı

ses

    ışık

        ve ben

hepimiz yalnızdık

    uzun bir gece

        sürüyordu dışarda

uzakta birileri

bizi seyrediyordu

    yalnızlığımızı

        kendi yalnızlığı

            içinde

oturduğum şehir

yalnızdı şimdi

bizler gibi

uzun bir gecede

gölgelerimizi bırakıyorduk.





1 7.1 2.1 998 Köln/ Düsseldorf', 'Uzun bir gecede aydınlandı oturduğum şehir     projektör tarıyordu         gökyüzünü uzun bir ses     çığlık         sonra yıllardır kulağım...', ARRAY['Türk Edebiyatı','Şiir','İsmail Cem Özkan']::text[], 8.5, '{"poet":"İsmail Cem Özkan","poet_slug":"i-smail-cem-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/uzun-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Bir Usta Gördüm', 'bugun-bir-usta-gordum-i-smail-cem-ozkan-jcuqh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bugün bir usta gördüm

ağaçlara baktıkça

onlara nasıl ses vereceğini

düşünüyordu.

Usta, 

ağaca bakınca

nasıl ses vereceğini

buldu.

Ve

o’na ses verdi.

Aşıkların elinde

yaptığı

konuştu.

Bugün, bir usta gördüm, 

ağaçlara bakarken.

Bugün bir aşık gördüm, 

ustanın

yaptığını konuştururken.



3 1.03.1 990 / Schwäbisch Hall', 'bugün bir usta gördüm ağaçlara baktıkça onlara nasıl ses vereceğini düşünüyordu. Usta,  ağaca bakınca nasıl ses vereceğini buldu. Ve o’na se...', ARRAY['Türk Edebiyatı','Şiir','İsmail Cem Özkan']::text[], 8.5, '{"poet":"İsmail Cem Özkan","poet_slug":"i-smail-cem-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bugun-bir-usta-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyormusun?', 'biliyormusun-berfin-canan-0fefy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ask Nedir Biliyormusun? 

Neden Ask Vardir, 

Neden Baska Bir Insan Seni Senin Kadar Sevsin? 

Sana Senin Kadar Deger Versin? 

Kendin Bu Dunya ya Tek Basina Gelmedinmi Sen? 

Oyle ise... neden? 

Bu Hisler, Bu Izdirhap Neden? 

Insanoglunun derdi az degil.

Dertleri yasamasi icin onemli ama bu dert neden? 

Insan Asksiz yasayamazmi? 

Onu dusunmeden, 

Onu hissetmeden, 

Onu sevmeden... yasayamazmi?', 'Ask Nedir Biliyormusun?  Neden Ask Vardir,  Neden Baska Bir Insan Seni Senin Kadar Sevsin?  Sana Senin Kadar Deger Versin?  Kendin Bu Dunya ...', ARRAY['Türk Edebiyatı','Şiir','Berfin Canan']::text[], 8.5, '{"poet":"Berfin Canan","poet_slug":"berfin-canan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/biliyormusun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Cilem', 'benim-cilem-berfin-canan-0mdzf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim Cilem Bitmemis daha, 

Belki sonsuza, 

Belki Yarine kadar...

Bildigim tek sey var; 

Seni sevdigim!', 'Benim Cilem Bitmemis daha,  Belki sonsuza,  Belki Yarine kadar... Bildigim tek sey var;  Seni sevdigim!...', ARRAY['Türk Edebiyatı','Şiir','Berfin Canan']::text[], 8.5, '{"poet":"Berfin Canan","poet_slug":"berfin-canan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/benim-cilem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demek Sende Beni?', 'demek-sende-beni-berfin-canan-vvftm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni Nezaman Dusunsem, 

Icimde Garip Bir Duygu, 

Seni gorunce... bu duygu seninle eriyor, 

yok oluyor.

Sen demekki beni; Ben ise seni

Ve seviyoruz birbirmizi

Sozler degilki anlam tasiyan, 

Sadece gozler.', 'Seni Nezaman Dusunsem,  Icimde Garip Bir Duygu,  Seni gorunce... bu duygu seninle eriyor,  yok oluyor. Sen demekki beni; Ben ise seni Ve sev...', ARRAY['Türk Edebiyatı','Şiir','Berfin Canan']::text[], 8.5, '{"poet":"Berfin Canan","poet_slug":"berfin-canan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/demek-sende-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dusunce', 'dusunce-berfin-canan-74b8f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dusunmek bos bir kelime.

Insan sevince dusuncenin anlamini anliyor.

Seni sadece dusunmek yetmiyor.

Herzaman icimdeymis gibi hissediyorum.

Ben sanki senmisin gibi...', 'Dusunmek bos bir kelime. Insan sevince dusuncenin anlamini anliyor. Seni sadece dusunmek yetmiyor. Herzaman icimdeymis gibi hissediyorum. Be...', ARRAY['Türk Edebiyatı','Şiir','Berfin Canan']::text[], 8.5, '{"poet":"Berfin Canan","poet_slug":"berfin-canan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dusunce-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siir Yazdim', 'siir-yazdim-berfin-canan-0s266', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak bir siir yazdim.

Senin icin, 

Sadece senin icin.

Icimdeki bu duygu dunyalara sigmaz, 

Ve senin sevgin bana yetmez, 

Yoksa yetermi? 

Sen okadar sevdinmi? 

Sen olesiye sevdinmi? 

Ne olur soyle! 

Soyleki, bende seni senin beni sevdigin kadar seveyim...

Soyle...!', 'Bak bir siir yazdim. Senin icin,  Sadece senin icin. Icimdeki bu duygu dunyalara sigmaz,  Ve senin sevgin bana yetmez,  Yoksa yetermi?  Sen ...', ARRAY['Türk Edebiyatı','Şiir','Berfin Canan']::text[], 8.5, '{"poet":"Berfin Canan","poet_slug":"berfin-canan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siir-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben, ; Kahraman sın', 'ben-kahraman-sin-i-brahim-teke-voogh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerim, bu akşam çekemem sizi

Biri bir yamuk geometri gibi dizimde

Ötekisi sinmiş kahpe belimde

Kaçacakmış gibi cesur duruyor

Ha desem vuracak bir diğerine

Dur desem dururmu acaba, sinsi ve kahpe

Ötecekmiş gibi duruyor başka bedene

Böylemi söz vermiştin ya böyle mi kavil? 

Bitecekmiş gibi girdin kanıma

Ha desem çekecek namluyu zavil.', 'Ellerim, bu akşam çekemem sizi Biri bir yamuk geometri gibi dizimde Ötekisi sinmiş kahpe belimde Kaçacakmış gibi cesur duruyor Ha desem vura...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Teke']::text[], 8.5, '{"poet":"İbrahim Teke","poet_slug":"i-brahim-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-kahraman-sin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaıdn Hissi Geçidi', 'kaidn-hissi-gecidi-ertan-tanoba-9dz9f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi kadın bir türkü

Kimi bir şarkı bırakıp gitti benden

Kimi ne türkü ne şarkı severdi

Kimisi sırf usulca birkaç mısrama düşüverdi

Kiminin ayakları rüyalarıma ansızın girerdi

Kiminin sırf gözü aklımın en yumuşak yerine 

							Kuruluverdi

Kimi bir öykü kısalığında, 

			telaşında, 

konuk oldu parmaklarıma

Kimini roman tadında ağır ağır okumaya çabaladım

Kısacık ömrüne rağmen

				İnadım üzre

Kimine “bu iş burada bitmiştir” demesine dedim.

Evet, dedim! 

Dedim de naramın sonunu bir türlü getiremedim.

Kimi Edgar usta misali, 

Gitmeden azgın sahillerde bekletti beni, 

Kimi ölü bir denizin kıyıcığında, 

					Sabahlattığıyla kaldı.

Kimi “gecenin yarısında buluşuruz” dediğimle kalmadı, 

Uzun bir “anlaşmanın”, “kırmızı gül” döşeli yolunda, 

“rüyaların kadını”, hayatımın “sarı gelini” oldu.

Sayısız evimin kadınıydı, 

		Lakin evime bir türlü giremedi.

Sevecendi, 

		Evecendi, 

				Everdi çok, 

Evime de yakışırdı hani

				Ama bir türlü evlenemedi.

Velhasıl kelam

Eskiden olsa üç kız tanırdım esaslı

Biri beni sevmezdi, 

Biri sever de varılmazdı, 

Biri ne sever ne varılırdı, 

Varlığı bilinmezdi.

Şimdilerde çok koz tanıdım

Kimi sırf esanslı

Kimi cidden esaslı.

Kiminin biraz ucundan tutsam

				Hep yanımda kalırdı

Kimini keşke hiç tutmasaydım, 

				Tatlı bir anımda kalırdı.

Sözün kısası dostlar! 

Kimi bir ucuz sevişme

	Bir uyuz bakışma, 

	Bir vakitsiz delişme, 

	Bir tekinsiz gelişme, 

	Bir beter çelişme, 

	Bir sonrasız erişme tadında

Hepsi iyi kötü kadındı.

Kimini ne gördüm ne görmedim.

Kiminin ne elinden tuttum ne tutmadım.

Kimini ne sevdim ne sevmedim.

Kimi ne vardı ne yoktu.

4 Şubat’02, K.Köy', 'Kimi kadın bir türkü Kimi bir şarkı bırakıp gitti benden Kimi ne türkü ne şarkı severdi Kimisi sırf usulca birkaç mısrama düşüverdi Kiminin ...', ARRAY['Türk Edebiyatı','Şiir','Ertan Tanoba']::text[], 8.5, '{"poet":"Ertan Tanoba","poet_slug":"ertan-tanoba","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/kaidn-hissi-gecidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bakımlık Aşk', 'bir-bakimlik-ask-ertan-tanoba-kko0o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bakımlık otobüs aşklarına 

Sevdalanır oldum durduk yerde.

Bir elim cigaralıkta 

			Bir elim cebimde, 

Rüzgara karşı duman üfürür oldum

Soğuk bir mevsimde.

Durak pek kalabalık değil.

Kiminin işi gücünde

Kiminin gücü işinde

Benimse derdim tasam

İşlerden arta kalan gündeliklerde

Rüzgara karşı okuduğum bela

Yüzüme geri vuruyor

Neyin peşindeyim ki ben

Ne gücüm işime yarıyor

Ne de işim gücümden geliyor

Ama yalnızlık yok mu yalnızlık

İşte bu

	Gücüme gidiyor.

Yaşamasızın birini daha yeni savuşturdum

Şimdi kuru ayazın en arsız tozuttuğu yerlerin birinde

Boş kollarımı birbirine kavuşturdum.

Öyle cansız durmayayım diye

Gah saçlarımı uçuşturuyor, 

Gah ellerimi ovuşturuyorum.

Bak sen! 

Bak sen de vurulma bu poza! 

Aklımda son karasaçlının telkarisi, 

Tamiri, tahmini, telafisi

Mümkün olmaz bir aşkın

İflah olmaz yürek mahkumu gibi

Kör uykuların horultusu

				kulaklarımda çınlayıp, 

				yüzümü tırmalarken, 

Yollara düşüyorum.

Haklısın kaptan –hani şu gardiyanın arkadaşı olan-

Bir bilinmez çukura düşüyorum.

Kapamayın perdeleri, 

Yalanı yok, 

		üşüyorum! 

Nihayet biri daha geliyor.

Dur biraz yavaşla, 

Keyfim karşıdan karşıya geçiyor.

Onu sakın ezme kaptan, 

				bozuşuruz.

İyi ama kaptan bu boş.

Bırak bir bakımlık aşkı, 

Koltukların arasında bir sıkımlık meşk bile yok! 

Kaptan, sen böyle gelmezdin.

Çok uzak değil, 

			daha düne kadar, 

Buğuladıkları camın ardından, 

Adamakıllı şiş gözleriyle, 

Belli belirsiz aşklarıyla bakan, 

Kızları taşırdın işlerine.

Yapma be, işler bu kadar kötü mü? 

Olmadı be! 

Bir iler tutar otobüs aşklarım kalmıştı, 

						elceğizimde.

Şimdi beni kim tutar! 

Çıkmalı sokaklara, 

Bağırmalı var gücünle: 

Kahrolsun kapitalizm

	ve onun uşakları! 

Dur, ağır ol biraz.

Kapitalizmin suçu yok, 

Bence katil uşaklar! 

27 Şubat’02-Taksim', 'Bir bakımlık otobüs aşklarına  Sevdalanır oldum durduk yerde. Bir elim cigaralıkta  			Bir elim cebimde,  Rüzgara karşı duman üfürür oldum S...', ARRAY['Türk Edebiyatı','Şiir','Ertan Tanoba']::text[], 8.5, '{"poet":"Ertan Tanoba","poet_slug":"ertan-tanoba","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/bir-bakimlik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dar Mekana Ağıt', 'bir-dar-mekana-agit-ertan-tanoba-o7174', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Burayı çok iyi anımsarsam bana kızmazsın değil mi? 

Evet, burayı çok iyi anımsıyorum.

Ama sandığın gibi değil, 

		Burayı andığım yok.

Sadece o geceye yanarım.

Burası benim keşfile bayıldığım, 

Nice sonra suratımda patlayan, 

Buz gibi bir birayla ayıldığım

					yer.

Yeni bir yerdi.

Daha her masasına dirseğim, 

Her oturağına kıçım değmemişti.

Geleceği vardı, 

Buranın aklıma bir talihsiz, 

			Bir tarifsiz, 

Geceyle kazınacağı gün geldi.

Mekan birden bir kuş yuvası kadardı.

Anla be işte, birden o kadar dardı! 

Ben oturuyordum.

Üst kattaydım.

Birileri daha vardı.

Yok, imkanı yoktu, 

Mümkünü bile yoktu, 

Burası hepimizi almazdı.

Anla be işte, o kadar dardı! 

 Evet, hatırlıyorum.

Benim dışımda herkes konuşuyordu.

Sevdiğimin biri gidiyor biri geliyordu.

Ortalık sevdiğimden geçilmiyor, 

Yalnız kimsenin yüzü seçilmiyordu.

Ben çok uzak bir tarihten sırtımda getirdiğim yükü, 

Masanın birine yıkmıştım.

Bir başkasını daha sırtıma almaktan, 

Bir yenisini taşımaya kalkmaktan yılmıştım.

Anla be işte, o kadar bıkmıştım! 

Şimdi buradayım.

Bir şeyler anımsamaya çalışır gibi, 

Sandalyelere, masalara, tahtalara, 

Tablolara, kısık ışıklara, yastıklara bakıyorum.

Her şey aynı, 

Şu bana bakan sandalye 

Bana daha önce hiç, 

Tango sevdiğini söylemiş miydi? 

Peki bu tahta döşemeye, 

Daha ağır bastığım bir zaman oldu mu? 

Şu mor bozması yastık, 

Bana kaç kez uyku sırdaşı, 

			Fıtık yoldaşı oldu peki? 

Ya şu bardaktaki bira, 

Yüzümde patlamadan önce de beni sever miydi? 

Bu dondurucu müzik, 

Kanımı kaynatır mıydı bir zamanlar? 

İyi kötü her şeyi anımsıyorum da, 

Peki ya buranın adı neydi? 

Bu yukarısı hep böyle boş, 

				loş mu olurdu?  

Şu asılı akvaryumun balığı ne zaman öldü? 

Bunların yanıtını bulmak zor da, 

Peki ya, katiller cinayet yerine son bir kez gelmezler mi? 

27 Şubat’02, Taksim', 'Burayı çok iyi anımsarsam bana kızmazsın değil mi?  Evet, burayı çok iyi anımsıyorum. Ama sandığın gibi değil,  		Burayı andığım yok. Sadece...', ARRAY['Türk Edebiyatı','Şiir','Ertan Tanoba']::text[], 8.5, '{"poet":"Ertan Tanoba","poet_slug":"ertan-tanoba","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/bir-dar-mekana-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey Üzeri', 'bir-sey-uzeri-ertan-tanoba-w38xf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevmiştim bir akşamüzeri 

Kış gelmek üzereydi, 

Hızlı adımlarla geçip her şeyi, 

Yakalarımı kaldırıp seni aramıştım.

Ne vardı sesinde, 

On bin yılın kadınlığından başka? 

Seni görmüştüm bir sabahüzeri

Yanımda yatıyordun

Sol yanım sıcacıktı.

Hiç benden olmadığın halde, 

Sol yanım sımsıcak

			tenimde atıyordun! 

Sana dokunmuştum bir yazüzeri, 

Her şey gelmek üzereydi, 

Tok bakışlarla geçip her şeyi, 

Bakışlarımı kaldırıp seni aramıştım.

Ne vardı yatışında, 

On bin yılın kadınlığından başka? 

Sana tapmıştım bir sabaha karşı, 

Ben sana karşı, 

Sen bana karşı, 

Ben dünyaya, 

Dünya bana karşı.

Ne vardı sesinde, 

Bir şeylere karşı? 

Sana takmıştım bir sözüzeri, 

Bir şey gelmek üzereydi, 

Hatırlıyorum.

Sana son bir kez bakmıştım.

Ama nasıl bakmıştım, 

		yakmıştım, 

		akmıştım, 

		…mıştım, 

		…tım.

4 Şubat’02, K.Köy', 'Seni sevmiştim bir akşamüzeri  Kış gelmek üzereydi,  Hızlı adımlarla geçip her şeyi,  Yakalarımı kaldırıp seni aramıştım. Ne vardı sesinde, ...', ARRAY['Türk Edebiyatı','Şiir','Ertan Tanoba']::text[], 8.5, '{"poet":"Ertan Tanoba","poet_slug":"ertan-tanoba","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-sey-uzeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-ertan-tanoba-ab2vm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mektubundan önce sesi geldiğinde, 

Uyuyordum.

Rüyasız bir gündüz sayıklamasının 

                                Huzursuzluğunu duyuyordum.

Uyuzluk içinde kıvranıp kendimi

Vakitsiz bir düş görmeye zorluyordum.

Karanlık çadırın kapısı aralandı önce

Sesi bildik silüeti tanıdık bir şey geldi üzerime

Üzerime senden önce mektubunun gölgesi vurdu.

Ağır ağır geldiler.

Mektubunu getirdiler, 

Gelmemiş gibi oldum.

6 Şubat’02, Teras

KARALTI

Şu karlı yolun sonunda 

Parkın göbeğinde uzanmış karaltı, 

Evet, evet, O! 

Bir çocuk mu

Yoksa içi alelacele

                Peştenkerani doldurulmuş

Bir gocuk mu? 

N’olur gözlerim beni bir kerecik

                                 Bu defalık yanılt! 

6 Şubat’02-Teras-K.Köy

KARADENİZ

Sahile kıvrılıvermişim

Karadenizde bir yerde

Ama öyle bir zyerdeyim! 

Uzaktan hırs yüklü gemiler

Geçit resmini süslüyor

Azmaktan bezgin karadeniz suyu

                             Vuruyor ayaklarıma

Vurdukça bir ürperti sarıyor bedenimi

Şu kısacık geminin makine dairesi

Kaç derecedir kimbilir? 

O serin güverte kimbilir

Kaç sevişmeye tanıklık etmiştir

                                      Utanarak

Kaç denizin anası

Kaç denizi emzirmiştir kimbilir? 

Ah, şu deniz atlı karıncaya bineydim, 

çocuklar gibi şen.

Bir sıçramada aşaydım 

Şu sörf görmemiş dalgaları bir bir

Uzanıp tutaydım

Şu demir topu heyyulanın bir ucundan

Uzanaydım güvertesinin

                    Bir küskün bir ırak

                    Bir ıssız bir sessiz, 

                    bir ayaza dargın

                                             köşesine, 

Beyler! 

Hey, sizler! 

Evet, size söylüyorum

                                   Kıçı karaya yapışıklar! 

Bak bunun adı üstünde, 

                                      Deniz! 

Onu lütfen seviniz! 

6 Şubat’02, Teras-K.Köy

COĞRAFYA

Ben senin en çok coğrafyanı SEVDİM

Bana bakıp bakıp kalbimin ağırlığını

                                            Hesap edişini değil, 

Pamik çarşaflar üzeri endamlı yatışını sevdim.

Durup şimşek gibi çakışını değil

Çağlayan gibi coşkun

 Nehir gibi durgun akışını sevdim

Şöyle orta yerde salınıp

Nice canlar yakışını sevdim.

Ben senin en çok coğrafyanı sevdim

Mis kokulu kardeş tepelerinden aşağı

Ilık bir dere gibi sakin

Sıcak bir rüzgar kadar nazlı süzülen

Bir anda coşkuyla göbeğiyle buluşan

Cilve yüklü gülücüklerini

Su yüklü damlacıklarını

                                     Çok sevdim! 

Uzun gecelerin sonunu beklemeden

Kendine günler doğuran

Yatağımın ortasında

Yumuşak geceyi hamarat kadınlar gibi

                                                             Yoğuran

Hep neşeyle

Hep çocuksu

Bas bas bağıran sesini değil, 

Gündüz sevişmelerindoe sınırları kaldırışını çok sevdim! 

Ben senin en çok coğrafyanı sevdim! 

6 Şubat’02, Teras-K.Köy

Kimi kadın bir türkü

Kimi bir şarkı bırakıp gitti benden

Ki ni türkü, ne şarkı severdi.

Kimisi sırf usulca bin kaç mısrama düşüverdi

Kiminin ayakları rüyalarıma ansızın girerdi

Kiminin sırf gözü 

Aklımın en yumuşak köşesine kuruluverdi

Kimi bir öykü kısalığında

                                      Telaşında

Konuk oldu parmaklarıma

Kimini roman tadında ağır ağır

Okumaya çabaladım

Kıszacık ömrüne rağmen

                                       Inadım üz’re.

Kimine « bu iş burada bitmiştir » demesine dedim, 

Evet, dedim! 

Dedim de naramın sonunu bir türlü getiremedim.Kimi Edgar usta misali gitmeden

Azgın sahillerde bekletti beni

Kimi ölü bir denizin kıyıcığında

                               Sabahlattığıyla kaldı.

Kimi « gecenin yarısında buluşuruz » dediğimle kalmadı, 

Uzun bir « anlaşma »nın

« Kırmızı gül » döşeli yolunda « rüyaların kadın », 

Hayatımın  « sarı gelin »i oldu.

Kimi sayısız evimin kadını oldu

Lakin evime bir türlü giremedi.

Aslında sevecendi

                            Evecendi

                                          Everdi çok.

Evime de yakışırdı hani

Ama bir türlü evlenemedi.

Velhasıl kelam

Eskiden olsa üç kız tanırdım esaslı

Biri beni sevmezdi

Biri sever de varılmazdı

Biri ne sever ne varılırdı

Varlığı bilinmezdi.

Şimdilerde çok kız tanıdım

                         Kimi sırf esanslı

                         Kimi cidden esaslı.

Kiminin biraz ucundan tutsam

                                    Hep yanımda kalırdı.

Kimini keşke hiç tutmasaydım

                                    Tatlı bir anımda kalırdı.

Daha ufacıkken bir zaman

Düşlerimde bir acem kızına vuruldum

Nice sonra rastgeldim bir acem kızına

Lakin artık kadındı.

Sözün kısası dostlar, 

Kimi bir ucuz sevişme

        Bir uyuz bakışma

        Bir vakitsiz delişme

        Bir tekinsiz gelişme

        Bir beter çelişme

        Bir sonrasız erişme

Hepsi iyi kötü kadındı

Kimini ne gördüm ne görmedim

Kiminin ne elinden tutum ne tutmadım

Ne sevdim ne sevmedim

Kimi ne vardı ne yoktu! 

4 Şubat’02, Güğüm-K.Köy

MATEMATİK

Nasıl pişmanım

Ner’den bilirdim bunun

Benim yaşamım olacağını

O gece orada

                     Oracıkta

Yanlış adama bakmışım

Yaşamımı bir yanlış açıya yakmışım

Nerden bilirdim

Ben matematik okumadım ki! 

4 Şubat’02, Güğüm-K.Köy

BİR ŞEY ÜZERİ

Seni aramıştım bir akşam üzeri

Kış gelmek üzereydi

Hızlı adımlarla geçip herşeyi

Yakalarımı kaldırıp

                             Seni aramıştım.

Ne vardı sesinde

On bin yılın kadınlığından başka? 

Seni görmüştüm bir sabah üzeri

Yanımda yatıyordun

Sol yanım sıcacıktı

Hiç benden olmadığın halde

Sol yanım sımsıcak

                               Tenimde atıyordun.

Sana dokunmuştum bir yaz üzeri

Her şey gelmek üzereydi

Tok bakışlarla geçip herşeyi

Bakışlarımı kaldırıp seni aramıştım

Ne vardı yatışında

On bin yılın kadınlığından başka? 

Sana tapmıştım bir sabaha karşı

Ben sana karşı

Sen bana karşı

Ben dünyaya

Dünya bana karşı

Ne vardı sesinde

Bir şeylere karşı? 

Sana takmıştım bir söz üzeri

Bir şey gelmek üzereydi

Hatırlıyorum

Sana son bir kez bakmıştım

Ama nasıl bakmıştım

                 Yakmıştım

                   Akmıştım

                  ...mıştım

                     ...tım.

4 Şubat’02 - K.Köy', 'Mektubundan önce sesi geldiğinde,  Uyuyordum. Rüyasız bir gündüz sayıklamasının                                  Huzursuzluğunu duyuyordum. ...', ARRAY['Türk Edebiyatı','Şiir','Ertan Tanoba']::text[], 8.5, '{"poet":"Ertan Tanoba","poet_slug":"ertan-tanoba","theme":"Türk Şiiri","is_hero":false,"total_lines":197,"source_url":"https://www.antoloji.com/mektup-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansız Konuk', 'ansiz-konuk-ertan-tanoba-59j4y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Övgüler düzdüğüm, şiirler döktüğüm, 

Öyküler kurduğum geçmişimin kağıt yığını, 

Karşıdan öyle boş boş bana bakıyordu

			Kısık mum ışığının altında.

Nicedir eimi bile sürmediğim, 

Tozlarını bile üflemediğim solgun kağıtlar, 

Kendilerini bir anda yok edip, 

Beni çıkpak bırakmanın planlarını kuruyor, 

İki camın açık kaldığı bir anda, 

Teker teker cereyana kapılıp şehrin sokaklarına savrulmanın, 

Fırsatını kolluyor gibiydiler.

Uykuma aldırış etmeden, 

Bir bira daha açmıştım.

Merhametimin apansız gelip beni dürtmesini, 

Uyandırmasını, 

Azdırmasını, 

Bekliyordum

		Yarı kapalı gözlerimle.

Gök bulutlanmaya yüz tutmuş, 

Ayın üstü çoktan örtülmüştü.

Salonda içimi açacak bir şeylerin olmasını bekliyordum.

Şarabı dün bitirmiştim.

Sadece iki biram vardı.

Tekel iki gündür hastaydı.

Mum bitmek üzereydi.

Karnım acıkmıştı.

Ev soğuktu.

Kedim dün ölmüştü.

Azıcık mutluluk için, 

Bir mucize gerekliydi.

Birden onu gördüm. 

Geçmişimin pasaklı sayfalarının yanıbaşında, 

Soğuktan büzüşmüş, 

Beyaz ellerini ovuşturuyordu.

İçimin aydınlandığını hissettim.

Hemen şu anda kapı açılsa, 

Beni terk eden kadınların yarısı

Ellerinde beyaz şaraplarla

					İçeri dalsa, 

Bu kadar mutlu olmazdım.

Onu oraya ben koymamıştım.

Ne zaman, ner’den, nasıl gelmişti? 

Bana bakmadan üşüyordu.

Soracak sorusuzluktan, 

“Üşüyor musun” dedim.

Gülmekten beter yüzüme baktı

“Üşüyorum” dedi usulca.

“Yanıma gel, şuna sarın”

“Bak ayakların çıplak, üstün ince

						titriyorsun”

Yüzüme bakmadı.

Ellerini, sönmeye yüz tutmuş muma götürdü.

Yandaki kağıtlara gözü ilişti.

Işıltılı gözlerle 

Birkaç sayfayı karıştırdı.

Bana bir an baktı, 

Gülümsedi sanki.

Yavaşça yerinden kalktı.

Yanıma geldi, 

Battaniyeme sarındı.

Bana gerçekten gülümsedi.

“Seni iyi gördüm”

“Şimdi hoşça kal, 

			büyüyünce yine gelirim”

Sonra kalktığı, geldiği gibi

Sessiz sedasız

Gitti.

Bir yerlere yetişmem gerekiyormuş gibi yerimden fırladım.

Geçmişimin kağıtlarının tozunu aldım.

Onları düzene koydum.

Evin bütün camlarını açtım.

Kağıtların hiçbiri, 

Yerinden kıpırdamadı.

Bu gece geçmişimin pasaklı sayfalarının yanıbaşında, 

Geleceğimin yalnız çocuğu, 

	Yalın ayaklarıyla, 

Bana konuk oldu.

.

26 Mart’02 - Taksim', 'Övgüler düzdüğüm, şiirler döktüğüm,  Öyküler kurduğum geçmişimin kağıt yığını,  Karşıdan öyle boş boş bana bakıyordu 			Kısık mum ışığının a...', ARRAY['Türk Edebiyatı','Şiir','Ertan Tanoba']::text[], 8.5, '{"poet":"Ertan Tanoba","poet_slug":"ertan-tanoba","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/ansiz-konuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Son Bahar Geldi', 'yine-son-bahar-geldi-nurdogan-aydogan-kgxs7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine son bahar geldi güzelim.

Ve yine yeniden ben, 

Hüzün ve hüsran ile arkadaşım.

Arkama dönüp bakıyorum, 

Ne çok sevilmişim vay diyorum.

Önüme bakıyorum ne çok üzüleceğim

Vay diyorum.

Vay ki bana vay güzelim

Adam olmam ben

Sen gelirsen eğer

Yazması bile kötü

Dedim ya adam olmam ben.

Baktıkça maziye hatırla beni

Unuttukça beni bakma geriye.

Kimim ki zaten ben 

Bir zamanların yani

Senli zamanların adamı.

Geldi geçti işte aynı zaman gibi.

Olmasaydı belki daha iyi olurdu 

Diyebilirsin güzelim.

Belki de, 

Aslında belki de si de yok güzelim

Biten bir şeyin ardında da belki de si de

Olmaz zaten. 

1999 yılana ait.', 'Yine son bahar geldi güzelim. Ve yine yeniden ben,  Hüzün ve hüsran ile arkadaşım. Arkama dönüp bakıyorum,  Ne çok sevilmişim vay diyorum. Ö...', ARRAY['Türk Edebiyatı','Şiir','Nurdoğan Aydoğan']::text[], 8.5, '{"poet":"Nurdoğan Aydoğan","poet_slug":"nurdogan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yine-son-bahar-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Pişmanlık Neye Yarar', 'son-pismanlik-neye-yarar-nurdogan-aydogan-q5sj2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazılası sona her geçen gün yaklaşıyorum

Kafamda sen ve senin gibilerin eserleri

Kalbimde aynı sen gibi bir çok mezar

Neye yarar şimdi bunlar.

Bir çok şey söylenebilirdi belki

Her son gibi senin ardından. 

Neydi, ne olabilirdi ki zaten, 

Son pişmanlık neye yarar.

2000 yılına ait.', 'Yazılası sona her geçen gün yaklaşıyorum Kafamda sen ve senin gibilerin eserleri Kalbimde aynı sen gibi bir çok mezar Neye yarar şimdi bunla...', ARRAY['Türk Edebiyatı','Şiir','Nurdoğan Aydoğan']::text[], 8.5, '{"poet":"Nurdoğan Aydoğan","poet_slug":"nurdogan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/son-pismanlik-neye-yarar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kimin-umrunda', 'kimin-umrunda-sair-beyazit-38hmx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sokak ortasında 

Gün batımında

Ellerim tutsak kalsada bagrımda

Seni sevmidiğim

Kimin umrunda

Olabildiğine yalnız 

Alabildiğine sessiz

Ve sensiz

Kimsesiz 

Kalsada bu sokaklar

Kimin umrunda

Günün birinde herşey

Sensiz kalacak

Ama

Ben zaten kimsesizim 

Birde sensiz kalmışım

Kimin umrunda', 'Sokak ortasında  Gün batımında Ellerim tutsak kalsada bagrımda Seni sevmidiğim Kimin umrunda Olabildiğine yalnız  Alabildiğine sessiz Ve sen...', ARRAY['Türk Edebiyatı','Şiir','Şair Beyazıt']::text[], 8.5, '{"poet":"Şair Beyazıt","poet_slug":"sair-beyazit","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kimin-umrunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidanlar Yeşeriyor', 'fidanlar-yeseriyor-nurdogan-aydogan-cunr2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamanın anlamsızca zamanda kaybolması

Geçmişin gelecekte var olmaması

Şimdinin yarın olmaması

Nedir ulan bu...

İnsanı her gördüğünde aptal eden 

Bir daha asla yaşanmayacak denilen 

Her tövbeden sonra insanın kafasına giren

Nedir ulan bu...

Kahrolası geçen günler 

Ah ilen biten ömürler

Acı ile uyanan gözler

Nedir ulan bu...

Sarsılan değerler

Yıkılan umutlar

Biten aşklar

Nedir ulan bu...

Her şeyin sonu olduğunu bildiğinden 

Başlangıçları unutan gözlerim

Uyan! Uyan! 

Fidanlar yeşeriyor. 

20.11.2001', 'Yaşamanın anlamsızca zamanda kaybolması Geçmişin gelecekte var olmaması Şimdinin yarın olmaması Nedir ulan bu... İnsanı her gördüğünde aptal...', ARRAY['Türk Edebiyatı','Şiir','Nurdoğan Aydoğan']::text[], 8.5, '{"poet":"Nurdoğan Aydoğan","poet_slug":"nurdogan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/fidanlar-yeseriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman mı? İlaç! Yoksa Zamansızlık mı?', 'zaman-mi-i-lac-yoksa-zamansizlik-mi-nurdogan-aydogan-wc7yb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gelen ve giden den ne istedi ki bu gönül

Kalmayı mı? Gitmeyi mi? 

Var olmayı mı? Yok olmayı mı? 

Ne dersen de sonu hep aynıydı.

Hata bende değil deme buna sakın yemezler

Her defasın da baş rolde oynayanı affetmezler

Ve buna rağmen ısrarcı oluyorsan eğer

Sen aslında baştan kabullenmişsin sonunu.

İnsan her yaşta her şeyi bilemiyor, 

Her yeni bilinmeyen şey 

Yeni şeyleri ders veriyor.

Acımadı gönül değil mi? 

Sen aslında aslın da baştan kabullenmiştin sonunu.17.01.02', 'Gelen ve giden den ne istedi ki bu gönül Kalmayı mı? Gitmeyi mi?  Var olmayı mı? Yok olmayı mı?  Ne dersen de sonu hep aynıydı. Hata bende d...', ARRAY['Türk Edebiyatı','Şiir','Nurdoğan Aydoğan']::text[], 8.5, '{"poet":"Nurdoğan Aydoğan","poet_slug":"nurdogan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zaman-mi-ilac-yoksa-zamansizlik-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dene Bilirdiki Daha?', 'ne-dene-bilirdiki-daha-nurdogan-aydogan-kxe1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erkek, kıza masum fakat anlamlı baktı.

Kız, erkeğe masum fakat utanır baktı.

İkisi de biliyordu aslında, 

Bu işin bir sonu vardı o da yoktu.

Bir çok anlamsız şey konuşuldu

Her defasında bir yerlere varılmaya, 

Çalışıldı.

Gelinecek tek bir yol vardı o da yoktu. 

Sus dedi erkek ‘’haklısın’’

Kadın sustu haksız olduğu halde.

Erkek cevap istemedi, kızda istemedi.

O vakit ayrıldılar, birleşemedikleri gibi.

01.04.2002', 'Erkek, kıza masum fakat anlamlı baktı. Kız, erkeğe masum fakat utanır baktı. İkisi de biliyordu aslında,  Bu işin bir sonu vardı o da yoktu....', ARRAY['Türk Edebiyatı','Şiir','Nurdoğan Aydoğan']::text[], 8.5, '{"poet":"Nurdoğan Aydoğan","poet_slug":"nurdogan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-dene-bilirdiki-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Felsefe?', 'nedir-felsefe-huseyin-erdol-cd9ow', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Felsefe

İnsandır

Edebiyat, yazı, şiir

İnsandır

Tarih, fizik, kimya 

akıl, düşünce, inanış

İnsandır

Peki ya insan?

Ne biliyorsa söylesin 

İnsanı insana sorar gibi söylesin 

Korkusunu unutup

Düşünüp iyice öyle söylesin

_____________________________', 'Felsefe İnsandır Edebiyat, yazı, şiir İnsandır Tarih, fizik, kimya  akıl, düşünce, inanış İnsandır Peki ya insan? Ne biliyorsa söylesin  İns...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdöl']::text[], 8.5, '{"poet":"Hüseyin Erdöl","poet_slug":"huseyin-erdol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siz-ne-gunessiniz-oyle-bergama-koyleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nefessin', 'bir-nefessin-sureyya-turkmenli-pndym', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir nefessin sen

bedenime hapsettiğim

bir nefessin sen

duman duman çektiğim

bir nefessin sen

su içerken aldığım

gözlerindeki nehire

pervasızca daldığım

bir nefessin sen

yanağımda dolaşan

sakalıma dokunup

saçlarımı okşayan

bana şefkat ve sevgiyle 

dokunan son nefessin

son nefesimi verirken

nefesin nefesime deysin...', 'Bir nefessin sen bedenime hapsettiğim bir nefessin sen duman duman çektiğim bir nefessin sen su içerken aldığım gözlerindeki nehire pervasız...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Türkmenli']::text[], 8.5, '{"poet":"Süreyya Türkmenli","poet_slug":"sureyya-turkmenli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-nefessin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar Bayram Ola - 5', 'bayramlar-bayram-ola-5-abdurrahim-karakoc-9fw45', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giden Bayramlardan almadık bir tad

Gardaş bu senenin bayramı nasıl? 

Şenay’larda bayram her gün, her saat

Elif’in, Döne’nin bayramı nasıl? 

İçinde boğulduk derdin, acının

Uykusu bitmedi şeyhin, hacının

Üç gardaşı şehit veren bacının

Oğulsuz ananın bayramı nasıl? 

Neşe topuğumda, elem boyumda

Sen çoğunu anla, ben az deyim de

Kim öldü, kim kaldı garip köyümde

Ya bizim hanenin bayramı nasıl? 

Dert deşmek değildir gayem, niyetim

Düşündükçe sızlar kemiğim, etim

Gelini dul kalmış, torunu yetim

Ak saçlı ninenin bayramı nasıl? 

Hangi eller sürer suçluyu suça

Güdümlü başların destesi kaça

Kimler zorlanıyor gönülsüz göçe

Boş kalan binanın bayramı nasıl? 

İşkence altında ezilir canlar

Masum yiğitlerle dolu zindanlar

Ses verin mezardan ulu sultanlar

Yusuf-u Kenan’ın bayramı nasıl? 

Bizden sandığımız bize yabancı

Görünen simalar göze yabancı

Kabukta bayram var, öze yabancı

Söyleyin, mânânın bayramı nasıl? 

Sabahtan haber yok, ufuklar kara

Semerkant kan ağlar, yanar Buhara

Keşmir, Kâbil, Kerkük hasret bahara

Kudüs’ün, Sina’nın bayramı nasıl? 

Ayşe’nin bayramı gözyaşı, firak

Sultan’ı derdiyle baş başa bırak

Sormadan geçemem, etmişim merak

Nükhet’in, Nana’nın bayramı nasıl? 

Mücahit, maddeye yapar akını

Devrimci, soygundan tutar yükünü

Biz toprağa verdik Hikmet Tekin’i

Kotil’in, Zana’nın bayramı nasıl? 

Doğduğundan beri çamlar deviren

Ekranda iftira, yalan savuran

Salyası, ülkeyi göle çeviren

Boynuzlu dananın bayramı nasıl? 

(Suları Islatamadım)', 'Giden Bayramlardan almadık bir tad Gardaş bu senenin bayramı nasıl?  Şenay’larda bayram her gün, her saat Elif’in, Döne’nin bayramı nasıl?  ...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bayramlar-bayram-ola-5-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay Bardağı', 'cay-bardagi-ozgur-kayim-tlmeh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çay bardağı, 

Her yudumda, biraz daha eksilen 

Eksildikçe tüm çıplaklığını gösteren

Dibe yaklaştıkça yavaş yavaş bitirilen 

Çay bardağı, 

Bardağın şekli, sinüs eğrisi, 

Bardağın şekli, hayat denizi

Bardağı doldur, bardağı doldur, dolduuuuuuur! ! ! 

Mavi hayat içilesi

Mavi bardak sevilesi…', 'Çay bardağı,  Her yudumda, biraz daha eksilen  Eksildikçe tüm çıplaklığını gösteren Dibe yaklaştıkça yavaş yavaş bitirilen  Çay bardağı,  Ba...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kayım']::text[], 8.5, '{"poet":"Özgür Kayım","poet_slug":"ozgur-kayim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cay-bardagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Fil', 'kucuk-fil-ozgur-kayim-v1ry5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün dünyanın bir köşesinde

Küçük bir fil annesini kaybetti sıcak toz rüzgarları yüzünden

Daha ağzı süt kokarken, daha su içmeyi bile bilmezken

Önce boş boş gezindi annesini bulmak için

Bir grup erkek fille karşılaştı yolda, 

Karnı acıkmıştı, süt için yaklaştı onlara

Emmeye çalıştı, nafile, 

Kızdırdı büyükleri boş yere

Bir su ve çamur birikintisine kadar takip etti onları

Biraz serinledi, acı acı bağırdı annesine

Hava bunaltıcı, gölgede kırk sekiz derece

Dinlenmeye çalıştı büyüklerin gölgesinde

İtelendi, kovalandı saatlerce

Yoruldu, sıkıldı, gizlendi bir çalılığın içine

Derken küçük yavrulu bir grup geldi birikintiye, 

Heyecanla koştu bizimkisi, 

Anne file yaklaştı süt için, “küt” bir tokat, bir hortum darbesi

Az kalsın ezilecekti, 

Hiçbir zaman öğrenemeyecekti olanların sebebini

Bir tas süttü istediği, 

Hava kararmak üzereydi, “tik tak tik tak”, 

Vakit cehennem gözlü cellatları gösterdi, 

Son  bağırışlar, son haykırışlar  da fayda etmedi, 

Bugün, dünyanın bir köşesinde küçük bir fil

Filliğini kaybetti…', 'Bugün dünyanın bir köşesinde Küçük bir fil annesini kaybetti sıcak toz rüzgarları yüzünden Daha ağzı süt kokarken, daha su içmeyi bile bilme...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kayım']::text[], 8.5, '{"poet":"Özgür Kayım","poet_slug":"ozgur-kayim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kucuk-fil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğduğum Evin Penceresi', 'dogdugum-evin-penceresi-asaf-halet-celebi-a3gqj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir çam vardı önünde

        doğduğum odanın

çöpten yapraklarında

güneşi

        rüzgârla sallayıp

        kafesten

içeri dolduran bir çam

sedirinde iskambilden kuleler yıkılmış odada

loş ve sessiz ikindilerin acısıydı

                                        sızan

gözlerim dalardı

                kafesten

                        duvara

ve duvardan

                kafese

seyretmeyi

                güneşi

yüz bir güneşti

kafesin her deliginden

                giren

susmuş bir çocukla şaka eden

                        yüz ikindi güneşi', 'bir çam vardı önünde         doğduğum odanın çöpten yapraklarında güneşi         rüzgârla sallayıp         kafesten içeri dolduran bir çam s...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dogdugum-evin-penceresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Davası', 'hayat-davasi-ozgur-kayim-swqdj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karar açıklandı...

Biraz umut, 

                    biraz sorumluluk satın alındı, 

Üzerine bir tutam yaşanmışlık katıldı.

Bir aşk, ağız dolusu küfürlere bile aldırmadan

                    haraç mezat satıldı.

Karar açıklandı...

Ömür boyu ağır sızı, 

                   dava sessizce kapatıldı.', 'Karar açıklandı... Biraz umut,                      biraz sorumluluk satın alındı,  Üzerine bir tutam yaşanmışlık katıldı. Bir aşk, ağız dol...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kayım']::text[], 8.5, '{"poet":"Özgür Kayım","poet_slug":"ozgur-kayim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayat-davasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün Üstüne İşenen Yaralı Yüzler', 'her-gun-ustune-i-senen-yarali-yuzler-ozgur-kayim-ob6p4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaralı yüzleri var bu şehrin

                                  üstüne her gün işenen

Hiç bitmeyen bir kan davasını hatırlatır sanki

Boş odalar içindeki yürek sallantılarına

Ölmek yetmezmiş gibi öldürmeyi de öğretir

adsız çocuklarına

Hem de acımamayı, hem de çıplak deride

diğerlerinden miras izleri taşımayı

Yaralı yüzleri var bu şehrin

                                  üstüne her gün işenen

Hep birisi gelecek  ve asitin o kronik tadını

diliyle yoklayacak

sonra  sokaktaki sidik lekelerini emecek hayvanca

ölü bir çocuğun çıplak düşlerinin

son izlerini silecek anılardan yavaşça

Yaralı yüzleri var bu şehrin

                                  üstüne her gün işenen

Hiç sevilmemiş, hep horlanmış

Sevaba gidilen mesih mezarlarında bile

Şeytan diye taşlanmış

Artık ne boş sokaklar, ne ölü çocuklar

ne kan, ne de düşler

İnsan etinden hoşlanır olmuşlar

Yaralı yüzleri var bu şehrin

                                  üstüne her gün işenen

İşendikçe içten içe çürüyen...', 'Yaralı yüzleri var bu şehrin                                   üstüne her gün işenen Hiç bitmeyen bir kan davasını hatırlatır sanki Boş odal...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kayım']::text[], 8.5, '{"poet":"Özgür Kayım","poet_slug":"ozgur-kayim","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/her-gun-ustune-isenen-yarali-yuzler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Ki Hiç', 'ne-ki-hic-oruc-aruoba-0a489', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi gelecek

Sana bahar yeniden: 

Bırak, bilme, ne—

Ne bil, ne bilme: 

Gelsin hepsi yeniden

Sen bilmeden, hiç…', 'Şimdi gelecek Sana bahar yeniden:  Bırak, bilme, ne— Ne bil, ne bilme:  Gelsin hepsi yeniden Sen bilmeden, hiç…...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ne-ki-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Artık', 'simdi-artik-oruc-aruoba-tw3zo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi, dinginlik: 

Olmamış da olsaydın

Vardın gene de—

Artık huzur: 

Oldun ve oldun gene: 

Varsın, burada.', 'Şimdi, dinginlik:  Olmamış da olsaydın Vardın gene de— Artık huzur:  Oldun ve oldun gene:  Varsın, burada....', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/simdi-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Ellerin', 'i-nce-ellerin-oruc-aruoba-2j7co', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl ince, ellerin, parmakların

Coşkuyla ağırlığını kavrarken yaşamın, 

Nasıl katı, nasıl soğuk, kurşunların

Sessiz ve dingin dünyanda yaşaman için.

Orada mısın? 

Göremiyorum seni—

Öylesine yoğun bir karanlık 

Uzanıyor ki benden sana

Gözlerim

Delinmiş gibi.

Orada mısın? 

Densiz gülüşlerden uzak—

Kuruyor musun beni? 

Ben ki

Yılların yağmurlarıyla çürümüş 

Tahta gibiyim: 

Dokusu grileşmiş, 

Artık yalnız, 

Ateşe atılabilen.

Beni 

Kuruyor musun—

Arsız gürültülerden uzak

Orada? 

Sessizliğim: 

Orada

Duyuruyor mu beni sana

Buradan, 

Rüzgarın dalları 

Bir an 

Bıraktığı aralarda?', 'Nasıl ince, ellerin, parmakların Coşkuyla ağırlığını kavrarken yaşamın,  Nasıl katı, nasıl soğuk, kurşunların Sessiz ve dingin dünyanda yaşa...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ince-ellerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgünüm', 'uzgunum-hakan-sengun-9psge', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidenlerin içinde

Ardından ağladığım, 

Gidenlerin içinde

Bir tek el salladığım aşkım

Üzgünüm; 

Şimdi artık yürüdüğüm bütün yollar yokuş.

Ne yanımda bir yoldaş, 

Ne de sıcak bir dokunuş.

Kalıplaşmış hayatım da

Birbirinden kopya çeker oldu her günüm

Üzgünüm; 

Gözlerimde yorgunluğun verdiği uyku hali

Gözlerimde yaş, gözümde telaş

Anıların ardı sıra giderken yavaş yavaş

Seni tutamadığım için gülüm

Üzgünüm;', 'Gidenlerin içinde Ardından ağladığım,  Gidenlerin içinde Bir tek el salladığım aşkım Üzgünüm;  Şimdi artık yürüdüğüm bütün yollar yokuş. Ne ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzgunum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun', 'gidiyorsun-oruc-aruoba-pw676', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun: 

Bütün ışıklarımı göndersem seninle 

Aydınlanır mısın? 

Gidiyorsun: 

Bütün sevinçlerimi göndersem seninle 

Mutlanır mısın? 

Gidiyorsun: 

Bütün hüzünlerimi göndersem seninle 

Üzülür müsün? 

Gidiyorsun: 

Bütün acılarımı göndersem seninle 

Yıkılır mısın? 

Ben 

Üzüntülü ve yıkık 

Kalırken 

Sen 

Aydınlık ve mutlu 

Git 

Işıklarımla ve sevinçlerimle: 

Üzülme 

Yıkılma 

Aydınlan 

Mutlu ol. 

Bırak bana, 

Hüzünleri, üzüntüleri 

Acıları, yıkımı? 

Al götür 

Işıkları, aydınlığı 

Sevinçleri, mutluluğu. 

Gidiyorsun: 

Bütün kendimi göndersem seninle 

Götürür müsün?', 'Gidiyorsun:  Bütün ışıklarımı göndersem seninle  Aydınlanır mısın?  Gidiyorsun:  Bütün sevinçlerimi göndersem seninle  Mutlanır mısın?  Gidi...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gidiyorsun-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyu Artık', 'uyu-artik-oruc-aruoba-m15uv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorgun musun? 

Yattın mı? 

Uyu—

Düşünme beni.

Ben ki 

Hiç düşünülmedim senden önceleri.

Senden öncesi: 

Düşüncesi kızgın kumlara serpilen 

Azgın yellerle savrulan 

Bir damla gibi—

Bir söz gibi: 

Sağır kağıtlara serilen

Sessiz dudaklardan dökülen.

Ben, zaten

Hiç söylenmedimki senden öncesi.

Uyu artık—

Söyleme beni.

Yattın mı? 

Yorgun musun? 

Biraz kıpırdasan uyumadan önce—

Bilemesen

Nereye koyacağını ellerini, 

Biraz oynatsan bileklerini

Düşünürken beni

Uyuyamadan önce—

Bilsen

Nasıl özlediğimi ellerini

Bileklerini.', 'Yorgun musun?  Yattın mı?  Uyu— Düşünme beni. Ben ki  Hiç düşünülmedim senden önceleri. Senden öncesi:  Düşüncesi kızgın kumlara serpilen  A...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uyu-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Gelmiştir', 'guz-gelmistir-oruc-aruoba-4a0jd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geri getirecek misin güneşlerini? 

Donuk gözlerim özlüyor seni.

Ne yaparım ki güneşsiz, sensiz? 

Kopuk köklerim bekliyor seni.

Geri getirecek misin ellerimi? 

Güdük bileklerim özlüyor seni.

Ne yaparım ki elsiz, sensiz? 

Çürük isteklerim bekliyor seni.

Geri getirecek misin ışıklarını? 

Soğuk kağıtlarım özlüyor seni.

Ne yazarım ki ışıksız, sensiz? 

Boğuk harflerim bekliyor seni.

Geri getirecek misin ellerimi? , 

Kırık sözcüklerim özlüyor seni.

Ne yazarım ki elsiz, sensiz? 

Yıkık tümcelerim bekliyor seni.

Bekleyeceğim 

Gene de

Hiçbir tekne getirmese de seni—

Getirene dek 

Hiçbir tekne.

Gene de…', 'Geri getirecek misin güneşlerini?  Donuk gözlerim özlüyor seni. Ne yaparım ki güneşsiz, sensiz?  Kopuk köklerim bekliyor seni. Geri getirece...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guz-gelmistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akan Kan', 'akan-kan-oruc-aruoba-zpob7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne çok 

Ölü

Düşün var senin

Kırık 

Dökük

Gerçeklerin üşüşünce düşüncene

Ne çok 

Canlı 

Acın var senin.

Bölük pörçük

Gerçeklerin inince içine

Ne çok

Katı 

Kanın var senin.

Ne çok 

Diri

Ölün var senin.

Param parça

Yaşamın bastırınca bakışına

Ne çok 

Akan 

Kanın var senin.

Ne çok

Yiten

Anın var senin.

Delik deşik

Yaşamın ulaşınca durağına

Ne çok 

Biten anın var senin.

Ne çok 

Halin 

Var senin…', 'Ne çok  Ölü Düşün var senin Kırık  Dökük Gerçeklerin üşüşünce düşüncene Ne çok  Canlı  Acın var senin. Bölük pörçük Gerçeklerin inince içine...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/akan-kan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşitilmeyen', 'i-sitilmeyen-oruc-aruoba-51nhv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yuvarlanarak geçtim buradan: 

Görmediniz.

Güneş bile yumdu gözlerini

Kapattı kulaklarını

İşitmedi

Sözlerimi.

Yaralanarak geçtim buradan: 

Sağaltmadınız.

Gök bile örtündü bulutlarını

Sakladı yıldızlarını

Dinlemedi

Umutlarımı.

Yok olarak geçtim buradan: 

Yaşatmadınız.

Ölüm bile çekti aldı anlarını

Tuttu attı anılarımı

Dindirmedi

Acılarımı…', 'Yuvarlanarak geçtim buradan:  Görmediniz. Güneş bile yumdu gözlerini Kapattı kulaklarını İşitmedi Sözlerimi. Yaralanarak geçtim buradan:  Sa...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isitilmeyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Düşleri', 'yagmur-dusleri-hakan-sengun-8dc6n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir benmiyim ağlayan tek başıma! 

Yıldızlı gecelerde; yağmur düşleri altında

Islandınmı hiç yüreğim? 

Söyle bende bileyim.

Bir kuytu saçak altında

Sol yanımdan vururken titrek bir ışık

Gölgem uzayıp giderken karanlığa

Dur gitme, diyebildinmi yüreğim? 

Söyle bileyim.

Yıldızlar göz kırpıyordu nedensiz, 

Ayaklarım üşümüş, bedenim halsiz.

Rüyalarda gördüğüm o yeri bilsem bile

Gidemem, yürüyemem sensiz.

Haydi kalk gidelim dedinmi hiç yüreğim? 

Söyle bileyim.

O günün telaşında uyuya kalmış takvim

Duvardaki yatağında.

Vakit aynı gece vakti

Hayallerimi oynattığım sıcak nefesim

Isıtmak için çabalarken ellerimi

Kopar şu takvim yapraklarını

Diyebildinmi yüreğim? 

Söyle bileyim.', 'Bir benmiyim ağlayan tek başıma!  Yıldızlı gecelerde; yağmur düşleri altında Islandınmı hiç yüreğim?  Söyle bende bileyim. Bir kuytu saçak a...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yagmur-dusleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamyam', 'yamyam-asaf-halet-celebi-ic8n0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zaman zamanına dönsün

hasta çocukları yiyen

kromanyon adam

                kovuklarındaki yılanları ye

                taşların altındaki böcekleri ye

yalnız

sakın beni yemekten

mağaranın hasta çocuğu zehirlidir

zaman bu zamandır

ihtiyarları ağaçlara çıkaran

silken

        düşüren

                ve yiyen ostralya adamı

                        kokmus leşleri ye

aşina kafaların bitlerini ye

yalnız

sakın beni yemekten

acıların ihtiyar adamı zehirlidir

zaman zamana uymuyor

doğurduğunu yiyen

                yamyam kadını

çocuğun aşkımdı

pişirmeden yemişe benziyorsun', 'zaman zamanına dönsün hasta çocukları yiyen kromanyon adam                 kovuklarındaki yılanları ye                 taşların altındaki bö...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yamyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Ne oldu', 'bana-ne-oldu-ahmet-rasim-uog83', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başı karlı, yüce dağlar gibiydim.

Coşup çağlayan ırmak gibiydim.

Çok sert esen rüzgar gibiydim.

Bir sözün yaktı kül etti beni.

Denizde köpüren dalda gibiydim.

Temmuzda gökteki güneş gibiydim.

Çiçeğin üstündeki arı gibiydim.

Bir sözün yaktı kül etti beni.', 'Başı karlı, yüce dağlar gibiydim. Coşup çağlayan ırmak gibiydim. Çok sert esen rüzgar gibiydim. Bir sözün yaktı kül etti beni. Denizde köpür...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Rasim']::text[], 8.5, '{"poet":"Ahmet Rasim","poet_slug":"ahmet-rasim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bana-ne-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Olmayan Sevgili', 'var-olmayan-sevgili-ahmet-tacyildiz-vuww8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Var olmayan bir dünyada tanıdım seni

Hiç olmamış, olmayacak bir dünyada

Var olmayan dünyanın 

Var olmayan sevgilisi

Gerçekle hayalin bir birine karıştığı

Neyin gerçek 

Neyin hayal olduğunun bilinmediği 

Kaoslarla dolu bir dünyada yaşıyorum

Sen ise kendi boyutunda

Gerçek bir yaşamda yaşıyorsun

Bir hayal dünyasındaki 

Hayal ürünü bir karakterim senin için

Hangimiz gerçeğiz

Ben mi yoksa sen mi 

Var olmayan dünyanın

Var olmayan sevgilisi

Bir portren var zihnimde şekillenen

Hayalimde canlanan

Ne derece gerçeğe yakın

Ne derece gerçekten uzak

Bilinmez

Bilemeyiz

Var olmayan dünyanın

Var olmayan sevgilisi

Gerçek dünyamda var olsa idin

Seni bu denli sevebilirmiydim

İnce belini böyle tutabilirmiydim

Kalın dudaklarını böyle öpebilirmiydim

Bir volkanın akması gibi akarmıydı

İçimdekiler içine

Var olmayan dünyanın 

Var olmayan sevgilisi

Senin yokluğunu

Senin hayalini seviyorum ben', 'Var olmayan bir dünyada tanıdım seni Hiç olmamış, olmayacak bir dünyada Var olmayan dünyanın  Var olmayan sevgilisi Gerçekle hayalin bir bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Taçyıldız']::text[], 8.5, '{"poet":"Ahmet Taçyıldız","poet_slug":"ahmet-tacyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/var-olmayan-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gözler', 'gozler-ayhan-koc-nhgsk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '....

Meraklı gözlerle süzdüm

Dün yine seni

Farkında değildin gözlerimin', '.... Meraklı gözlerle süzdüm Dün yine seni Farkında değildin gözlerimin...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Koç']::text[], 8.5, '{"poet":"Ayhan Koç","poet_slug":"ayhan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozler-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'iskele', 'iskele-ayhan-koc-ywvxk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dönüp bakmadın bile 

öylece bekledim iskelede 

bir vapur düdüğüydü

ayrılığımızı belgeleyen

7 ağustos 00', 'dönüp bakmadın bile  öylece bekledim iskelede  bir vapur düdüğüydü ayrılığımızı belgeleyen 7 ağustos 00...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Koç']::text[], 8.5, '{"poet":"Ayhan Koç","poet_slug":"ayhan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/iskele-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih 3 şubat', 'tarih-3-subat-ayhan-koc-7ojzx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tarih 3 şubat

Günlerden cumartesi

Zaman aynı zaman

Saatler yine aynı

Değişen 

sen 

ben

...

yağmur

3 şubat 2000', 'Tarih 3 şubat Günlerden cumartesi Zaman aynı zaman Saatler yine aynı Değişen  sen  ben ... yağmur 3 şubat 2000...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Koç']::text[], 8.5, '{"poet":"Ayhan Koç","poet_slug":"ayhan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tarih-3-subat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-ayhan-koc-c32qo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlıktan ışığı çaldım

Bir ağmadan gözlerini

Ve seni 

Kendimden

Çaldım

...

4 şubat 2000', 'Karanlıktan ışığı çaldım Bir ağmadan gözlerini Ve seni  Kendimden Çaldım ... 4 şubat 2000...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Koç']::text[], 8.5, '{"poet":"Ayhan Koç","poet_slug":"ayhan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seni-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davetsiz Misafirler', 'davetsiz-misafirler-ayhan-koc-3smhe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sahile terkedilmiş 

yorgun sandal gibi

merdivenin trabzanları 

yankılanmıyor artık sesler

loş merdivenlerinden

duvarlarında o kadar kızmalarına rağmen 

yazdığım yazılar hâlâ duruyor

daha yen sökmüşüm okumayı 

artık yok trabzanlarında

birkaç dakika nefes almak için

bekleyen davetsiz misafirler', 'sahile terkedilmiş  yorgun sandal gibi merdivenin trabzanları  yankılanmıyor artık sesler loş merdivenlerinden duvarlarında o kadar kızmalar...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Koç']::text[], 8.5, '{"poet":"Ayhan Koç","poet_slug":"ayhan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/davetsiz-misafirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı İsim Dilber', 'ayni-i-sim-dilber-ayhan-koc-hxdh7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sahile bakardı

buğulu olmadığında pencerem

tüm çıplaklığıyla güneşi sunardı 

nasılda hohohlayıp

yazardım ismini

yazmayı yeni öğrenmiş gibiydim sanki 

hep aynı ismi', 'sahile bakardı buğulu olmadığında pencerem tüm çıplaklığıyla güneşi sunardı  nasılda hohohlayıp yazardım ismini yazmayı yeni öğrenmiş gibiyd...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Koç']::text[], 8.5, '{"poet":"Ayhan Koç","poet_slug":"ayhan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayni-isim-dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-gurcan-kaya-braks', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben kimim bilirmisin sen 

Hayatı kendisine zehir eden 

Gülmeyi bırakalımda; 

Ağlamayı bile unutan.

Yaşatmayı değilde; 

Öldürmeyi planlayan.

Aklında her zaman her yerde, 

Binbir şeytanlık olan

Sosuza dek kimseye güvenmeyen 

Tek başına yalnız yaşayan

Sadece kadere karşı gelen 

Sonu olmayan biriyim ben', 'Ben kimim bilirmisin sen  Hayatı kendisine zehir eden  Gülmeyi bırakalımda;  Ağlamayı bile unutan. Yaşatmayı değilde;  Öldürmeyi planlayan. ...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Kaya']::text[], 8.5, '{"poet":"Gürcan Kaya","poet_slug":"gurcan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem', 'bilmem-hakki-hakan-kaya-806n2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine söndü gönlümün ışıkları bu akşam

Bilmem acep sebep nedir

Ölüm kolay zor olandır yaşam

Aşk kadri kıymetin bilendir

Sorarlar beyhude niçin hep ağlarsın

Bilmem acep sebep nedir

Boşuna sevda iplerin bağlarsın

Aşk hasret çekmesini bilendir

Elbet birgün dolacaktır bu beden

Yaşama yaşam katan kara toprakla

İşte o zaman belli olacak ağlayan ve gülen

Değiştiremeyeceksin, geriye dönüp bakmakla', 'Yine söndü gönlümün ışıkları bu akşam Bilmem acep sebep nedir Ölüm kolay zor olandır yaşam Aşk kadri kıymetin bilendir Sorarlar beyhude niçi...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilmem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Bir Şair', 'garip-bir-sair-ali-gencay-vfu6z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben garip bir şairim; 

yağız atlar kalem olup, 

koşuyor mısralarımda.

kelimelerim şimşek olup, 

çakar tepemde.

sevda türküleri söyler, 

bam telin de gamlanırım.

ben garip bir şairim; 

sevdayı hüzne bular, 

pişiririm yalnızlıkla.

işte benim mısralarım, 

işte benim sevdam.

ben gamlı garip bir şairim; 

hayatı yorumlarken mısralarımda, 

kalememi kırarım, 

ağır ceza reisi edasıyla.

idamımı sunuyorum, 

her kırılan kalem de.

yağlı imlek boynuma

ben garip bir şairim; 

yalnızlığı seviyorum, 

severken de acı çekiyorum.

sonra yine, 

yeniden doğuyorum.

yalnızlıkla...

kin kusuyor mısralarım.

yazarken sevdayı, 

kalemimi kırıp idamımı istiyorum.

 a.gençay', 'ben garip bir şairim;  yağız atlar kalem olup,  koşuyor mısralarımda. kelimelerim şimşek olup,  çakar tepemde. sevda türküleri söyler,  bam ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/garip-bir-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-erol-sen-m6qc0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Avunmak güzeldir yaşanan hatıralarla

Ama aldatmak büyük ihanet

Nice ömürler nice hayatlar sona erer

Değmezsin ki

Onurla yaşamak buysa yaşa 

Ben daha önce bitirdim gönlümde

Ama kalbim istemedi üzmeyi

Değmezsin ki

Hala kırıcı söz mü söyleyeceksin

Ne söyleyebilirsinki ne gördün ki

Hadi git var nasıl olsa bir sürü alıştın zaten

Değmezsin ki

Makaslarını ayır yoluna devam et

Acarlar macarlar haydi yoluna

Kaybettiğim maddiyat benim

Değmezsin ki

12.04.2002', 'Avunmak güzeldir yaşanan hatıralarla Ama aldatmak büyük ihanet Nice ömürler nice hayatlar sona erer Değmezsin ki Onurla yaşamak buysa yaşa  ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ihanet-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müzelik Şiir - Akıl Karaya Vurdu', 'muzelik-siir-akil-karaya-vurdu-abdurrahim-karakoc-n7w08', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yürüyen heykellerle aynı müzedeyim ben

Konuşan mumyalara kimden söz edeyim ben

Fikren işkencedeyim, ruhen cezadayım ben

     Korkaklığın sükûtu kol geziyor her yerde

     Sanki tek başımayım, tek kişilik mahşerde.

Putların gölgesinde dans eder akbabalar

Söz sokakta dolaşır, öz zindanda çabalar

Atılan ucuz safra selâmlar, merhabalar

     En temiz topraklara gül eksem mantar biter

     Yollar sırat köprüsü, durmak düşmekten beter.

Kaybettim mesafeyi, zamandan uzaklaştım

Sevgi diye sarıldım, isyanla kucaklaştım

Ne kendimden kurtuldum, ne kendime yaklaştım

     Toprağın üstü mezar, zevke dalmış ölüler

     Can sıkmaya yetiyor canlı kalmış ölüler.

Fuhuş yuvası sanki en görkemli binalar

Çamur evlât doğurur taş yürekli analar

Resmen hak tevzi eder hakkı boğan canavar

     Koşanlar, yarışanlar.. dehşet ötesi dehşet

     Akıl karaya vurdu, gırtlağı geçti vahşet.

Meydanlar tıklım tıklım, caddeler salkım-saçak

Kölelik histerisi yayılmış köşe-bucak

Elli tane hokkabaz, elli milyon oyuncak

     Müdür ve müdüriçe müzenin bekçileri

     Aferine çalışır düzenin bekçileri.

Mülkü kazanan ayrı, tasarruf eden ayrı

Hisseler neden farklı, hak, hukuk neden ayrı? 

Hasta yaşar deniyor, baş ile beden ayrı

     Mantık yürütmek yasak, itiraz eylemek suç

     Neşe-eğlence cinnet! ..  Yatıp uyumak korkunç! 

Güvenmek aldanmaktır.. ölçü-tartı izafî

Mert-namert, güzel-çirkin, eksi-artı izafî

Çoğunun cebindeki kimlik kartı izafî

     Kim kimdir? Kim kim değil? Anlamak ve bilmek zor

     Oynanan komediye gül diyorlar, gülmek zor.

Figüran heykeller var kül tablası boyunda

Beş yüz göbek atarlar dakikalık oyunda

İşlenen her günaha kurtta ortak, koyun da...

     Kalmışım ara yerde, tozdayım, dumandayım

     Kirli bir mekândayım, iğrenç bir zamandayım.

24.7.1991

(Akıl Karaya Vurdu)', 'Yürüyen heykellerle aynı müzedeyim ben Konuşan mumyalara kimden söz edeyim ben Fikren işkencedeyim, ruhen cezadayım ben      Korkaklığın sük...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/muzelik-siir-akil-karaya-vurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-aysun-aksu-oqorv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiirler yazılmış, babaların ardından

Kimi sevgiyle anmış, kimiyse hüzünle

Vermedikleri, yada almadıkları, sevgiye yanmışlar

Ama ben, şimdi yazıyorum baba

Seni kaybetmeden, yanımdayken şimdi

Sıcak gülüşünü, tatlı bakışını yazıyorum.

Arkamda, hep arkamda, duruşunu yazıyorum.

Almadan, daima verişini yazıyorum.

Sen sevmeyi öğrettin bana, çıkarsızca sevmeyi

Başımı dik tutmayı, eğmemeyi öğrettin

Mutlu çocukluğum için, teşekkürler baba

Seni, şimdi seviyorum, geç olmadan şimdi...', 'Şiirler yazılmış, babaların ardından Kimi sevgiyle anmış, kimiyse hüzünle Vermedikleri, yada almadıkları, sevgiye yanmışlar Ama ben, şimdi y...', ARRAY['Türk Edebiyatı','Şiir','Aysun Aksu']::text[], 8.5, '{"poet":"Aysun Aksu","poet_slug":"aysun-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/babama-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akılla Yürek Gibi', 'akilla-yurek-gibi-sukru-erbas-ca9ly', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben olmasaydım -dedi-

gülüşümün güzelliğini yaşayamazdın

biliyorum verdiğim mutluluğun değerini

ne anlama geldiğini senin için

günlerinin güze dönen hayal çizgisinden

i
..........
..........', 'ben olmasaydım -dedi- gülüşümün güzelliğini yaşayamazdın biliyorum verdiğim mutluluğun değerini ne anlama geldiğini senin için günlerinin gü...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/akilla-yurek-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanoğlu', 'i-nsanoglu-cahit-sitki-taranci-9i83d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adem''le Havva''dan geldiğim doğru; 

Vuruldum bir kere elma dalına 

Hala aklımda o Tufan yağmuru; 

Şükür çıktığıma Nuh''un salına.

Ölmek varsa günün birinde gayri, 

Göz nuru, el emeği, alın teri

Yaşadığım iyi kötü günleri

Değişmem hiçbir cennet masalına.', 'Adem''le Havva''dan geldiğim doğru;  Vuruldum bir kere elma dalına  Hala aklımda o Tufan yağmuru;  Şükür çıktığıma Nuh''un salına. Ölmek varsa ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/insanoglu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-cenap-sahabettin-ifd0d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sesin işler gibi bir şûh kanat gamlarıma 

Seni dinlerken olur kalbim uçan kuşlara eş 

Gün batarken sanırım gölgeni bir başka güneş 

Sarışınlık getirir gözlerin akşamlarıma. 

Doğuyor ömrüme bir yirmi sekiz yaş güneşi 

Bir kuş okşar gibi sen saçlarımı okşarken 

Koklarım ellerini gülleri koklar gibi ben 

Avucundan alırım kış günü bir yaz ateşi 

Gönlüme avdet eder her unutulmuş nisan 

Ne zaman gençliğini yolda hırâman görsem 

Eskiden pembe dudaklarda dağılmış bûsem 

Toplanır leblerime bir gece dalgın dursan 

Seni zambak gibi gördükçe açık pencerede 

Gül açar bahtımın evvelki hazanlık korusu 

Genç eder ufkumu hülyâlarımın genç kokusu 

Sorarım ak saçımın örttüğü yıllar nerede 

Çehremi varsın o solgun seneler soldursun 

Yeni yıldız gibi doğdukça güzel her akşam 

Gençliğin böyle benimken kocamam hiç kocamam 

Ruhum, ölsem bile ben, sen yaşayan ruhumsun', 'Sesin işler gibi bir şûh kanat gamlarıma  Seni dinlerken olur kalbim uçan kuşlara eş  Gün batarken sanırım gölgeni bir başka güneş  Sarışınl...', ARRAY['Türk Edebiyatı','Şiir','Cenap Şahabettin']::text[], 8.5, '{"poet":"Cenap Şahabettin","poet_slug":"cenap-sahabettin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senin-icin-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamadan Yazamassın', 'yasamadan-yazamassin-ahmet-yilmaz-ans-9zsp1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yine serin sularda yüreğim

ve derin düşüncelerdeyim

yaşadıklarımı yazıyorum

şuanda paylaşamadıklarımı yazıyorum

geçen güzel günlerim kar taneleri gibi eriyor 

gözlerimin önünde

acılarım ise hep iğneliyor yüreğimi

gölgem misali hep ardım sıra

ve ben haykıramıyorum bunları

sayfalara hapsediyorum 

kendimi kendime bırakıyor ve yine çekiliyorum

kabuğuma uzun bir aradan sonra

seni yaşamadan yazıyorum...', 'yine serin sularda yüreğim ve derin düşüncelerdeyim yaşadıklarımı yazıyorum şuanda paylaşamadıklarımı yazıyorum geçen güzel günlerim kar tan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yılmaz Ans']::text[], 8.5, '{"poet":"Ahmet Yılmaz Ans","poet_slug":"ahmet-yilmaz-ans","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasamadan-yazamassin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın Orda', 'sen-varsin-orda-asik-veysel-satiroglu-hsnqe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saklarım gözümde güzelliğini 

Her neye bakarsam sen varsın orda 

Kalbimde gizlerim muhabbetini 

Koymam yabancıyı sen varsın orda 

Aşkımın temeli sen bir alemsin 

Sevgi muhabbetsin dilde kelamsın 

Merhabasın dosttan gelen selamsın 

Duyarak alırım sen varsın orda 

Çeşitli çiçekler yeşil yapraklar 

Renklerin içinde nakşını saklar 

Karanlık geceler aydın şafaklar 

Uyanır cümlâlem sen varsın orda 

Mevcudatta olan kudreti kuvvet 

Senden hasıl oldu sen verdin hayat 

Yoktur senden başka ilânihayet 

İnanıp kanmışım sen varsın orda 

Hu çeker iniler çalınan sazlar 

Kükremiş dalgalar coşar denizler 

Güneş doğar perdelenir yıldızlar 

Saçar kıvılcımlar sen varsın orda 

Veysel’i söyleten sen oldun mutlak 

Gezer daldan dala yorulur ahmak 

Sen ağaç misali biz dalda yaprak 

Meyva çekirdeksin sen varsın orda', 'Saklarım gözümde güzelliğini  Her neye bakarsam sen varsın orda  Kalbimde gizlerim muhabbetini  Koymam yabancıyı sen varsın orda  Aşkımın te...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatıroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatıroğlu","poet_slug":"asik-veysel-satiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-varsin-orda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Ağacım', 'umut-agacim-hikmet-tugrul-tekeli-qtqk5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umut ağacım ol

Büyü olabildiğince

Yüreğime at köklerini

Bütün gücüm varlığım senin olsun

Büyü olabildiğince

Ben yok olmuşum ne çıkar

Sen umut agacı ol

Anlatılamayan duyguların ifadesi ol

Gözlerimin derinliklerinde yaşa

Hissettiklerimi anlat güzelliğinle

Sen umut ağacım ol

Büyü olabildiğince

Yalnız kaldığımda sığınacak dalım ol

Terkedildiğimde tesellisi ol yüreğimin

Ve dünyadaki tek yadigarım ol

Sen umut ağacım ol

Büyü olabildiğince 

Ben yok olmuşum ne çıkar', 'Umut ağacım ol Büyü olabildiğince Yüreğime at köklerini Bütün gücüm varlığım senin olsun Büyü olabildiğince Ben yok olmuşum ne çıkar Sen umu...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Tuğrul Tekeli']::text[], 8.5, '{"poet":"Hikmet Tuğrul Tekeli","poet_slug":"hikmet-tugrul-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umut-agacim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir İçin Cevaplar', 'siir-i-cin-cevaplar-ulku-tamer-n717v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1

Şiir gecenin kardeşidir, 

gündüzün annesi.

Yürekteki büyükbabadır şiir.



     2

Şiir örümceğin sesidir, 

duvarın şarkısı.

Duvarcının türküsüdür şiir.



     3

Şiir yağmurun deresidir, 

saç diplerinin teri.

Teknelerin taze sancağıdır şiir.

     4

Şiir afişlerin çerçevesidir, 

harflerin çizgisi.

Çıngırağın içindeki madendir şiir.

   

     5

Şiir kamyonetlerin mavisidir, 

kamyonların yiğitliği.

Faytonların yazılmamış tarihidir şiir.



     6

Şiir bakracın çeşmesidir, 

kuyunun yolcusu.

Kaynağın bekçisidir şiir.



     7    	   

Şiir cambazların dengesidir, 

hokkabazların seyircisi.

Sihirbazların rüyasıdır şiir.



     8  	  

Şiir üzümün güneşidir, 

elmanın kurdu.

Böğürtlenlerin tozudur şiir.

     9   

Şiir gümüşün simgesidir, 

çeliğin yapılışı.

Kurşunun çıkışıdır şiir.

     10    

Şiir çitlerin dikenidir, 

tarlanın sürülmesi.

Rençberin dalgınlığıdır şiir.



     11    

Şiir tatarcıkların saatidir, 

ateş böceklerinin saniyesi.

Tabiatın yıllarıdır şiir.



     12   

Şiir ölümün gölgesidir, 

yaşamanın örtüsü.

Çocuğun savunmasıdır şiir.

   

     13 

Şiir kumsalın eleğidir, 

kayanın tortusu.

Mermerin sunduğu damardır şiir.

   

     14

Şiir uykusuzluğun şiltesidir, 

uykunun haritası.

Balkonun uyanışıdır şiir.

     15   

Şiir ateşin habercisidir, 

yangının kundakçısı.

Yanardağın üstündeki kuştur şiir.', '1 Şiir gecenin kardeşidir,  gündüzün annesi. Yürekteki büyükbabadır şiir.      2 Şiir örümceğin sesidir,  duvarın şarkısı. Duvarcının türküs...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/siir-icin-cevaplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12-4-02/00: 17', '12-4-02-00-17-gozde-cangazi-l5kqb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaktasın

            -biliyorum-

Yüzümü göremeyecek

               sesimi duyamayacak

                  elime dokunamayacak

                                              kadar

                                                   uzakta...

Ama

          -onu da biliyorum ki-

yakınımdasın

ağladığımda gözyaşlarımı silecek

         kahkahamı paylaşabilecek

              yüreğimi ısıtabilecek

                           kadar

                                     yakınımda...', 'Uzaktasın             -biliyorum- Yüzümü göremeyecek                sesimi duyamayacak                   elime dokunamayacak                ...', ARRAY['Türk Edebiyatı','Şiir','Gözde Cangazi']::text[], 8.5, '{"poet":"Gözde Cangazi","poet_slug":"gozde-cangazi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/12-4-02-00-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dul Yetim Maaşı', 'dul-yetim-maasi-fatih-cinar-2v6a1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölüler dirilere bakıyor kardeşim

diriler bir yudum su vermesede

ölüler dirilere bakıyor kardeşim

diriler bir karanfil ekmesede

birisi babasının maaşını alıyor

birisi kocasının

ölüler dirilere bakıyor

diriler aç sefil yaşıyor

birisi ssk lı

birisi bağkurlu

birisi emekli sandığı

ama hepsi yarıtok

ama hepsinin pantolonu eteği yamalı

allah vermiyor kardeşim

yüksektekilerin belasını

zirveler sıcak 

zirveler güneşli

inadına yamaçlar soğuk

yamaçlar karlı

vermiyor kardeşim vermiyor allah belalarını

yukarıdan bakınca görünmüyor

aşağıdaki insancıkların hali

sormuyorlar hiç bir zaman nedir bu insanların ahvali

kendi cüzdanları kendi banka hesapları

kendi nefisleri onların derdi

onlar gülüp oynadıkça

allah belalarını versin

başbakanlığın merdivenleri

meclisin sandalyeleri

gitarımın telleri miktarınca....', 'ölüler dirilere bakıyor kardeşim diriler bir yudum su vermesede ölüler dirilere bakıyor kardeşim diriler bir karanfil ekmesede birisi babası...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dul-yetim-maasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Cefalar Etsen Almam Üstüme', 'bin-cefalar-etsen-almam-ustume-pir-sultan-abdal-t7g9e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bin cefâlar etsen almam üstüme

Gayet şirin geldi dillerin dostum

Varıp yad ellere meyil verirsen

Kış ola bağlana yolların dostum

İlâhi onmaya yardan ayıran

Bahçede bülbüller ötüyor uyan

Kula gölge olsa Allah’a ayan

Senden ayrılalı gülmedim dostum

Pir Sultan Abdal’ım gülüm dermişler

Bu şirin canıma nasıl kıymışlar

İster isem dünya malın vermişler

Sensiz dünya malın neylerim dostum', 'Bin cefâlar etsen almam üstüme Gayet şirin geldi dillerin dostum Varıp yad ellere meyil verirsen Kış ola bağlana yolların dostum İlâhi onmay...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bin-cefalar-etsen-almam-ustume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı sın Sen Yalancı', 'yalanci-sin-sen-yalanci-hulya-arisan-o9qu2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni yaşamak istiyorum, 

merak ediyorum.

Kalbinin derinliklerini, 

açabilecekmisin bana.

Yalnız benimle olup, 

yalnız beni sevebilecek misin.

Arsız ruhuna gem vurabilecek, 

sonsuza kadar benimle

olabilecek misin.

Yalancısın sen, 

yalancı. 

Çoşkuna hakim olamıyor, 

beni yok sayıyor, 

bir kenara atıyorsun.

Yok artık, 

hata yapmak istemiyorum, 

Sensiz yaşamayı, öğrenmeli

seni hayatımdan çıkartmalı, 

kendimi sensiz

YAŞAMALIYIM...

Istanbul,1993', 'Seni yaşamak istiyorum,  merak ediyorum. Kalbinin derinliklerini,  açabilecekmisin bana. Yalnız benimle olup,  yalnız beni sevebilecek misin...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalanci-sin-sen-yalanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Senin Derdinden Derbeder Oldum', 'yar-senin-derdinden-derbeder-oldum-asik-davut-sulari-5v1d4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yar senin derdinden derbeder oldum

Derd-i derunumu sor da sonra git

Hasretinden mecnun misâli oldum

Ne hale düşmüşem sor da sonra git

Aşık olan mâşukunu atar mı

Gül yerinde kara çalı biter mi

Aslan yatağında tilki yatar mı

Gözle on ikiden vur da sonra git

Argın dağının Çaput yaylası

Hangi gün inersen hoştur havası

Gel ey bülbülüm gel çektirme yası

Sulari kulunu sor da öyle git', 'Yar senin derdinden derbeder oldum Derd-i derunumu sor da sonra git Hasretinden mecnun misâli oldum Ne hale düşmüşem sor da sonra git Aşık o...', ARRAY['Türk Edebiyatı','Şiir','Aşık Davut Sulari']::text[], 8.5, '{"poet":"Aşık Davut Sulari","poet_slug":"asik-davut-sulari","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yar-senin-derdinden-derbeder-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Bayram Günü', 'bugun-bayram-gunu-asik-davut-sulari-xzage', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün bayram günü âlem eğlenir 

Sen bizim yaylaya gel başın için 

Dertliler oturmuş derdin söyleşir 

Etme intizarı gül başın için 

Hayran oldum bakakaldım yüzüne

Sürme değil rastık çekmiş gözüne

Hıçkırarak başım koysam dizine 

Saçım okşa gönlüm al başın için 

Davut Sulari''yem ahd-ı amanda 

Bir yıldız doğmuştur devr-i zamanda 

Seher bülbülüyem ulu divanda 

Sen benim vekilim ol başın için', 'Bugün bayram günü âlem eğlenir  Sen bizim yaylaya gel başın için  Dertliler oturmuş derdin söyleşir  Etme intizarı gül başın için  Hayran ol...', ARRAY['Türk Edebiyatı','Şiir','Aşık Davut Sulari']::text[], 8.5, '{"poet":"Aşık Davut Sulari","poet_slug":"asik-davut-sulari","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bugun-bayram-gunu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Perçemini Dökmüş Yüzüne', 'siyah-percemini-dokmus-yuzune-asik-davut-sulari-8jhh1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siyah perçemini dökmüş yüzüne

Salınarak gelen hümaya bakın

Kimden söz işitmiş düşmüş hüzüne

Keder yakışmayan simaya bakın 

Ak göksün üstüne  bir bağ dikilmiş

Bin bir çeşit çiçeklerden ekilmiş

Dün uğradım bir ücraya çekilmiş

Bulut mu kaplamış şu aya bakın

Elin sitemini ağlarken gördüm

Gül dibinde gül sararken gördüm

Bir seher akşamı çağlarken gördüm

Davut Sulari''deki sevdaya bakın', 'Siyah perçemini dökmüş yüzüne Salınarak gelen hümaya bakın Kimden söz işitmiş düşmüş hüzüne Keder yakışmayan simaya bakın  Ak göksün üstüne ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Davut Sulari']::text[], 8.5, '{"poet":"Aşık Davut Sulari","poet_slug":"asik-davut-sulari","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siyah-percemini-dokmus-yuzune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksan Ben Yokum', 'sen-yoksan-ben-yokum-hulya-arisan-xuy0t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni her düşündüğümde

arzularım beni benden alıyor,

bana hükmediyor...

Yanımda yoksan yıkılıyor,

 boşluğa itiliyorum.

Duygularım aklımın önünde, 

beni yönetiyor..

Sen,

 kalbimi çalmakla kalmadın,

beni benden aldın.

Ellerim ellerini, 

tenim tenini, 

dudaklarım dudaklarını, 

kalbim kalbini ÖZLÜYOR.

Sen yoksan ben yokum, 

sevdiğim tek EŞİM...

İstanbul, 2002', 'Seni her düşündüğümde arzularım beni benden alıyor, bana hükmediyor... Yanımda yoksan yıkılıyor,  boşluğa itiliyorum. Duygularım aklımın önü...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-yoksan-ben-yokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkeler Yanlızken Ağlar', 'erkeler-yanlizken-aglar-abdullah-yildiz-qf1c1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göremezsin gözyaşlarını, silemezsin 

İçten içten ağlar, köşelerde ağlar 

Duyamazsın hıçkırıklarını 

Bilemezsin neden ağladığını 

Anlayamazsın senin için ağladığını 

Bak şu kançanağı gözlere 

Hissediyormusun seni sensiz yaşamanın acısını 

Yıkılmış umutların içinde 

Virane gezen şu sarhoşun 

Söyleyemediği aşk sözcükleriyle boşutuğunu 

Görebiliyormusun kançanağı gözlerimde... 

Yine ağlıyorum 

Yapayalnız karanlık gecemde 

Sensiz geçen sensizliğimde 

Sen hala görmüyorsun 

Çünkü; ben yanlızken ağlarım', 'Göremezsin gözyaşlarını, silemezsin  İçten içten ağlar, köşelerde ağlar  Duyamazsın hıçkırıklarını  Bilemezsin neden ağladığını  Anlayamazsı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yıldız']::text[], 8.5, '{"poet":"Abdullah Yıldız","poet_slug":"abdullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erkeler-yanlizken-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatt-ı Aşk', 'hatt-i-ask-muhammet-sunar-7lw8n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen yine yeşil anka ol

sen yine şiir

ben yine buradayım

çınarın altında

ellerimde yağmur toplayıp

mayalıyorum

sonra şaribülleylünnehhar

sonra istanbul

ben sislerin ardından

açılan her kapıdan

girerim şol dem

yalnız sen

sen yutkunduruyorsun şiirlerimi

sislerin ardından 

bir tek yüzünü seçemiyorum

hercai kayışını

ama

sabah namazı peşi sıra geçen

boyacı çocukların ayak sesleri boyu

rayihanı topluyorum

mushafımın arasında kurutup

cüz başlarını ebruluyorum 

bununla

ki râkım koksun

talik koksun

hocam başını eğip 

uzun uzun düşünsün

birde kuş kanadı saçının her teli

martımı desem

yoksa bir ud telimi

ardından çıkan nağmemi bilmem

bilmem tayyı zamanmı

oysa sonbaharları aşık olmazdım

üsküdarada uğramazdım

ne kayık ne mehtap

nede aziz hüdayi

sen yine yeşil anka

sülüste öyle kalsın

(istanbul mart 91)', 'sen yine yeşil anka ol sen yine şiir ben yine buradayım çınarın altında ellerimde yağmur toplayıp mayalıyorum sonra şaribülleylünnehhar sonr...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hatt-i-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Resim Yazısı', 'bir-resim-yazisi-muhammet-sunar-kbh98', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zaman ona bir sevda türküsüdür

bir kısır kadın gülüşü

döner bir karınca yürüyüşü

...

yiyip bitiren beyni 

boş ve kutsaldır

sana resimler diliyorum

anlamsız

arada kaldığımı söylemek istiyorum

fotoğrafımı

kitap kapağına oturtmuşluğumu

bir duaya başlamış olmak saydım

çingenelerin iz düşürdüğü

bir kış vakti

iç çekişler

ve kesik anlamsızlık

söylevlerdir aynaya vuran

ve hayata vuran

(istanbul haziran 91)', 'zaman ona bir sevda türküsüdür bir kısır kadın gülüşü döner bir karınca yürüyüşü ... yiyip bitiren beyni  boş ve kutsaldır sana resimler dil...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-resim-yazisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinin Yokuşu', 'gozlerinin-yokusu-muhammet-sunar-dx3t4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'müzikler ne kadar isyankâr

hissiyatın okyanusu 

ne kadar derin

gözlerinin yokuşunda her akşam

ne kadar yoruluyorum

bak işte sözlerimide kaybettim

bitap bakışlarım

nasıl ufkun sensizliğinde

batıp batıp çıkıyorsa

ruhumda

öyle hezeyan

öyle fırtınalı

ve uzak kelâmı

her akşam beynime yürüyüp

beni sessizliğin senliğine

yalnızlığın şenliğine 

götürmekte

(istanbul nisan 92)', 'müzikler ne kadar isyankâr hissiyatın okyanusu  ne kadar derin gözlerinin yokuşunda her akşam ne kadar yoruluyorum bak işte sözlerimide kayb...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Sunar']::text[], 8.5, '{"poet":"Muhammet Sunar","poet_slug":"muhammet-sunar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gozlerinin-yokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-abdurrahman-sahin-kc1vx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatımı gülüşünle aydınlatıyorum bu akşam

Ay ışığını söndürdüm; Artık sen varsın bu akşam.', 'Hayatımı gülüşünle aydınlatıyorum bu akşam Ay ışığını söndürdüm; Artık sen varsın bu akşam....', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Şahin']::text[], 8.5, '{"poet":"Abdurrahman Şahin","poet_slug":"abdurrahman-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bu-aksam-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maziye Özlem', 'maziye-ozlem-abacan-askisev-senkal-vb3yy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzeldir yaşamak bir bahar günü, 

Geleceğe bakarak anmak dünü.

Pırıldayan yıldızlarda dolaşmak tek tek, 

Gece mehtabın ışıltısını seyretmek...

Yalnız ama mutlu bir bahar akşamı; 

Rüzgarın fısıltısında bile sevinç olmalı! 

Karanlığın içindeki o ışık tarlası

Görenlere parlaklığından neşe katmalı.

Geçmişe dalarak hayaller kurmalı, 

Mazide varolan anıları yaşamalı.

Her birinin sevincini tatmalı yeniden, 

Veya hüznünü hissetmeli derinden...

Denize düşen mehtabın aksinde, 

Kıyıya vuran dalgaların sesinde, 

Ciğerine çektiğn her nefesinde, 

O anıları görmelisin içinde...

Her biri güzeldi o eski günlerin; 

Yaşamaya doyamadan geçti zaman! 

Kiminde çocukluk yıllarımdan, 

Kiminde aşklarımdan hisler saklı...

Ruhumun derinlerinde volkan olur, 

O karmaşık, gizemli duygular! 

Bazen kalbimde buruk bir sızı, 

Bazen gözümde yaş olur eski yıllar...', 'Güzeldir yaşamak bir bahar günü,  Geleceğe bakarak anmak dünü. Pırıldayan yıldızlarda dolaşmak tek tek,  Gece mehtabın ışıltısını seyretmek....', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/maziye-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Özlemler', 'yasak-ozlemler-salih-ozcelik-4yr26', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sayfasını çevirdiğimiz tüm kitaplar

Kuşkular düşürür yüregine onların

Ne zaman ki sevdalanırsak kızıl karanfilerine mezopotamyanın

Ve galeyana gelir köleci tanrılar

Zincirden duvarlar örerler özlemlerimizin dört bir yanına...', 'Sayfasını çevirdiğimiz tüm kitaplar Kuşkular düşürür yüregine onların Ne zaman ki sevdalanırsak kızıl karanfilerine mezopotamyanın Ve galeya...', ARRAY['Türk Edebiyatı','Şiir','Salih Özçelik']::text[], 8.5, '{"poet":"Salih Özçelik","poet_slug":"salih-ozcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yasak-ozlemler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-abacan-askisev-senkal-rme4r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlıklar içinde gizemli, 

Sessizliğe giden bir yol sanki.

Etraftaki sisli gölgeler, 

Hiç bilinmeyenin sırrı gibi! 

Ulaşılamayan bir soru, 

Kasvet kokan geceler...

Yıldızların ışığı altında, 

Kuytularda buluşur iki sevgili, 

Ama hiçbiri bilmez ki

Birçok beraberliğin sonu, 

Karanlıkların hüznüyle dolu...

Sevilmez soğuk geceler, 

Sevilmez gecenin sessizliği! 

Ürkütür yalnız geceler, 

Endişeyle düşündürür geleceği! 

Karanlıkla içiçe geceler, 

Uzayan yollara engel! 

Yorgun, uykusuz geceler, 

Duyguların coştuğu bir sel! 

Karamsarlığa gebe geceler, 

Hep eser o soğuk yel...

Rüzgarın ürperten ıslığına, 

Sallanan dalların hışırtısına, 

Baykuşların korkutan şarkısına, 

Yukardaki sonsuz boşluğa, 

Ufukta yeni gün doğana kadar

Hükmeder karanlık geceler...', 'Karanlıklar içinde gizemli,  Sessizliğe giden bir yol sanki. Etraftaki sisli gölgeler,  Hiç bilinmeyenin sırrı gibi!  Ulaşılamayan bir soru,...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/geceler-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan olmak..!', 'i-nsan-olmak-umut-gul-g4eew', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(insan olmanın değerini bilenlere ithaf olunur)      

İnsan olmak ne demek, 

İnsan gibi insan olmak, 

Tanımlarmısın, 

Anlatırmısın, 

İnsan  olmak için ne gerek; 

...

Gülmesini bilmeli, 

Yoksa konuşmasını mı? 

...

Yoksa yaşamısını mı? 

...

İnsan olmak için, 

Ağlamak mı gerek? 

Ağlatmak mı? 

...

Düşünmek mi gerek, 

Düşündüğünü söylemek mi? 

...

İnsan olmak için ne gerek; 

İnsan olmak ne demek, 

Daha doğrusu insan ne demek; 

Konuşan, yaşayan, yürüyen, yiyip, içen, 

Kirleten, aldatan, ağlatan....mı? 

İnsan...

İnsan olmak  demek, 

Yürek olmak demek, 

İnsan olmak demek, 

Sevmek demek, 

Yüreği güzel olanı, 

Kusurlarıyla sevmek demek, 

Karşılıksız, saf, tertemiz, 

Duygularla sevmek...sevmek

İnsan olmak demek...

Anlıyormusun..? 

(..04.2002 gecenin bir vakti)', '(insan olmanın değerini bilenlere ithaf olunur)       İnsan olmak ne demek,  İnsan gibi insan olmak,  Tanımlarmısın,  Anlatırmısın,  İnsan  ...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/insan-olmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şehrin Aşk Tarihi', 'bir-sehrin-ask-tarihi-ali-rodi-ozkan-o9nen', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın miladı, mavi gözlerin

Bir aşkı yormak gibi bir şey

Gözlerinde aramak şehri ve denizi

Tarih tek başlangıç kabul eder

İsadan ve çarmıhatan bu yana 

Bense zamansız bir gökgürültüsüyüm

Işığı vururken, yağmur bulutları

Kör olsan ne değişir ki 

Görmezken sen beni 

Biliyormusun..? 

Gözlerin her zamankinden daha mavi

Ve verdiğin her nefes 

Bir mezhebin yayılması 

Kör olası bir galakside 

Aşkın son havarisi olmak

Bana kısmet

Şimdi derim 

Neden seçildiysem isanın tarihinden 

Bilmiyorum 

Biliyorsam gözlerim aksın

Evet aksın 

Ve neden seçtiyse beni tanrılar 

Dağ başlarından bir ırmak gibi

Yolumuda göstersinler 

Çünkü ben deniz dedim gözlerinin mavisine.. 

 (mersin-07.03.2002)', 'Aşkın miladı, mavi gözlerin Bir aşkı yormak gibi bir şey Gözlerinde aramak şehri ve denizi Tarih tek başlangıç kabul eder İsadan ve çarmıhat...', ARRAY['Türk Edebiyatı','Şiir','Ali Rodi Özkan']::text[], 8.5, '{"poet":"Ali Rodi Özkan","poet_slug":"ali-rodi-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-sehrin-ask-tarihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Son', 'bu-gece-son-emre-altinok-pc3vq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece son

Bugün güneş doğduğunda, 

Bir sahilin kıyısında...

Dalgaların denize varmalarını seyredeceğim..

Bu gece son gitmeliyim..

Sevdanın çelmesine takıldık, pürüzlerle aşındık, aşkın pençesiyle yaralandık.

Kalbimin ta ortasına 

O geceden önceki anılarımı gömeceğim kalbime

Ya senin; Fırtınalar kopacak kalbinde biliyorum.

Kalbinin penceresi zincirlenmiş olacak biliyorum

Açamayacaksın, açmıyacaksın zaten o pencereyi

Sabah olduğunda pencerenden bak dışarı.

Çünkü sana kocaman bir ben bıraktım...    Elveda..', 'Bu gece son Bugün güneş doğduğunda,  Bir sahilin kıyısında... Dalgaların denize varmalarını seyredeceğim.. Bu gece son gitmeliyim.. Sevdanın...', ARRAY['Türk Edebiyatı','Şiir','Emre Altınok']::text[], 8.5, '{"poet":"Emre Altınok","poet_slug":"emre-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-gece-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk', 'sonsuzluk-emre-altinok-0wnjr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hergün kaybolup gidersin uzaklara benden habersiz

Gittiğin yerlerde hiç aramaz mısın beni? 

Beni de götür gittiğin yerlere

Kaynaşalım yeşillerin mavilerin arasında

Gidelim uzaklara sonsuzluğa...

Kıskançlık rüzgarından çıkalım

Gittiğimiz yerlerde her yer sen koksun ve sen koksun

Ölüm kıskacında çağıralım herkezi tüm insan alemi ve evreni

Duysun dünya sonsuzluğu...

 08.11.2001 01: 00', 'Hergün kaybolup gidersin uzaklara benden habersiz Gittiğin yerlerde hiç aramaz mısın beni?  Beni de götür gittiğin yerlere Kaynaşalım yeşill...', ARRAY['Türk Edebiyatı','Şiir','Emre Altınok']::text[], 8.5, '{"poet":"Emre Altınok","poet_slug":"emre-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sonsuzluk-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma Aşk', 'unutma-ask-emre-altinok-z4qdr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceler sesiz, soğuk, sakin.

Kendimi kaybettim, sensizliğe saatler kala...

Aşkım yüreğimde hala..

Gel sevincim ol, 

Gel hevesim ol, 

Gel ateşim ol

Gel benim ol

Yanar ellerim kor kor demirlerde

Islanır yüzüm sevincimin gözyaşları

Yağmurun pençesiyle.

Yaram kabuk bağladı taki kopana dek sen varsın..

Unutma ki aşk; yarası sanada vurur, 

Unutma aşk bir gün senide bulur....

 Emre Altınok', 'Geceler sesiz, soğuk, sakin. Kendimi kaybettim, sensizliğe saatler kala... Aşkım yüreğimde hala.. Gel sevincim ol,  Gel hevesim ol,  Gel ate...', ARRAY['Türk Edebiyatı','Şiir','Emre Altınok']::text[], 8.5, '{"poet":"Emre Altınok","poet_slug":"emre-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unutma-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkusuzca', 'korkusuzca-emre-altinok-16ngq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şişem dolu, keyfim dargın kendime ki, 

Ben kendimi kaybetmişim! 

O kadar mutsusuzum ki, onlar beni etkilemez

Deniz, mavi, aşkım; 

Hayallerde dolaşıyorum korkusuzca ki, ben daha

Hayatın farkında değilim sadece abimle farkında olurum

Anlatılırım ki; ben salakmıyım be! beni ne zannedersiniz ki! 

Çünkü ben sizin esirinizinim sizin kor ateşlerinizde

Yanar dururum

Saatler kaçar benden ama kendimi kaybetmeme saatler kala

Ben kendimden geçerim ve ben korkusuz olurum!', 'Şişem dolu, keyfim dargın kendime ki,  Ben kendimi kaybetmişim!  O kadar mutsusuzum ki, onlar beni etkilemez Deniz, mavi, aşkım;  Hayallerde...', ARRAY['Türk Edebiyatı','Şiir','Emre Altınok']::text[], 8.5, '{"poet":"Emre Altınok","poet_slug":"emre-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/korkusuzca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar', 'mektuplar-erkal-erk-l3l9z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dün gece oturdum seni çizdim

bir güzel

gözlerin, cam mavisi

saçların, sonbahar

öpüşün, ömre bedel', 'dün gece oturdum seni çizdim bir güzel gözlerin, cam mavisi saçların, sonbahar öpüşün, ömre bedel...', ARRAY['Türk Edebiyatı','Şiir','Erkal Erk']::text[], 8.5, '{"poet":"Erkal Erk","poet_slug":"erkal-erk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mektuplar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük', 'dortluk-erkal-erk-drm21', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dalda bir çiçek kırmızı mı kırmızı

ardında yol boyu yalnızlık durur

aklıma gelirde gitmek bazı

çeker kolumdan yalnızlık durdurur', 'dalda bir çiçek kırmızı mı kırmızı ardında yol boyu yalnızlık durur aklıma gelirde gitmek bazı çeker kolumdan yalnızlık durdurur...', ARRAY['Türk Edebiyatı','Şiir','Erkal Erk']::text[], 8.5, '{"poet":"Erkal Erk","poet_slug":"erkal-erk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Sonbahar', 'adim-sonbahar-erkal-erk-hkiq2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'adım, adım,

adım sonbahar

dalımdan düşmüşümde yere

birkaç kötü renkli bulutmuşum gökyüzünde

aslımı saklayıp adının maviliğine

suretimi cebimde taşırmışım', 'adım, adım, adım sonbahar dalımdan düşmüşümde yere birkaç kötü renkli bulutmuşum gökyüzünde aslımı saklayıp adının maviliğine suretimi cebim...', ARRAY['Türk Edebiyatı','Şiir','Erkal Erk']::text[], 8.5, '{"poet":"Erkal Erk","poet_slug":"erkal-erk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adim-sonbahar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük-Sevgi yeli', 'dortluk-sevgi-yeli-erkal-erk-vj3l7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'buğdaylar bizim orada şimdi

başak başaktır sevgili

sarı rüzgara karışır

derde derman bilinir

sarı sevgi yeli', 'buğdaylar bizim orada şimdi başak başaktır sevgili sarı rüzgara karışır derde derman bilinir sarı sevgi yeli...', ARRAY['Türk Edebiyatı','Şiir','Erkal Erk']::text[], 8.5, '{"poet":"Erkal Erk","poet_slug":"erkal-erk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortluk-sevgi-yeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük-Herhangi Bir', 'dortluk-herhangi-bir-erkal-erk-qzlr8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'herhangi bir gün, herhangi bir saat, herhangi bir şehir

kapıyı vurma / kapı açık içeri gir

bu kurutulmuş yalnızlık, bu da bakira keder 

ilaçları ellerindir', 'herhangi bir gün, herhangi bir saat, herhangi bir şehir kapıyı vurma / kapı açık içeri gir bu kurutulmuş yalnızlık, bu da bakira keder  ilaç...', ARRAY['Türk Edebiyatı','Şiir','Erkal Erk']::text[], 8.5, '{"poet":"Erkal Erk","poet_slug":"erkal-erk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-herhangi-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-mehmet-ali-cibikli-ix7hp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç günler yaşadım, geceler gördüm, 

Yalnızlık dost imiş, acılar kardeş.

Yalnız gecelerde, her zaman öldüm, 

Ne bir dost anladı, halimi ne eş.

Ruhum ruhsuz gibi, başıboş kaldı, 

Hep dolaşıp durdu, orta yerlerde.

Beni benden artık, birisi aldı, 

Aklım fikrim şimdi, bilinmezlerde.

Bir bilinmez denklem, çözülmesi zor, 

Ne kafalar yordum, ne düşünceler.

Uğraşıp dursam da, yine olmuyor, 

Ne gündüzler yetti, ne de geceler.

Geceler ki benim, en sadık dostum, 

Sırdaşım olurlar, sırrımı saklar.

Derdimi geceye söyler dururum, 

Gecelerde benim, anılarım var.

                                (11.08.2001-ULA/MUĞLA)', 'Kaç günler yaşadım, geceler gördüm,  Yalnızlık dost imiş, acılar kardeş. Yalnız gecelerde, her zaman öldüm,  Ne bir dost anladı, halimi ne e...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geceler-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrucuğum', 'yavrucugum-ensar-aktas-t56sm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir anne düşünki

Yavrusu için canını düşünmeden feda eder

Yemez yedirir, giymez giydirir

Hasta olsa kan ağlar içi

Saçını süpürge, gözyaşlarını ilaç eder

Elinden geleni yapar onu iyileştirir

Bir aşık düşünki

O annenin yavrusunu sevdiğinden çok sever

Her saniye düşünür, o aldığı nefesidir

Bir an görmezse yanar yüreği, içi

Yakar yıkar, şu alemi yerle bir eder

Kendini değil, sevdiğini yaşar sevinir

Yavrucuğum, 

Sana olan aşkımı tarife gerek yok biliyorum

Seni nasıl sevdiğimi sen çok iyi biliyorsun

Ama bilmediğin bir şey var ki …

Neyse, boşver yavrucuğum, 

Git bu akşam seninle tanıştığımız o sahile

Dolaş biraz seninle elele gezdiğimiz kumsalda

Bizim şarkımızı dinle

Güneşin batışını izle

Sonra gökyüzündeki yıldızlara bak

Hani şu kutup yıldızı varya

Bakmaya doyamadığımız

Parıltısıyla içimizi ısıttığımız

İşte onun hemen yanında bir yıldız var ki

O bu akşam yanında olmayacak

Çok ama çok istediği halde olamayacak

Seni çok uzaklardan

Özlemle seyredecek

Sevgine çok ihtiyacı var

Bir gülümsesen ona

Bir öpücük yollasan

Unutma, her an kayabilir gökyüzünden

Dileğini hazır tut, gözlerini açık

O an aklında ben olayım

Kalbinde olduğum gibi

Dudağında adım olsun

Düşlerinde, şiirlerinde olduğu gibi

Bak işte kayıyor

Hüzünleri arkada, 

Özlemini geldiği yerde bırakarak

Bak işte kayıyor

Kederlere elveda diyerek

Maziye sırtını dönmüş

Mutluluğa uçuyor

Sana, aşkına koşuyor

Kollarına düşüyor 

Aç kollarını çok üşüyor

Sar, onu ancak sen ısıtırsın

Sıkı sıkı sar

Bir daha bırakmamacasına sar

Sar, içi ısınsın

Bak işte sabah oluyor

Bak işte güneş doğuyor

Ve dalgalar ayaklarını okşuyor

Köpükleri tenini öpüyor

Uzan, uzan da

Bir avuç deniz suyu al eline

Bak işte ellerindeyim

Eğil bak avucuna

Bak işte gözlerindeyim

Susadıysan aşkıma

İç, iç bir yudumda

İç kana kana

Bak işte içindeyim

Çıkarma beni oradan bir daha

Dünyanın en güzel yerindeyim

Kalbinde, yüreğindeyim

Gül bahçelerinde, cennette

Cennetindeyim

Ve sonsuza dek…

Orada kalmak isterim, 

Hep senle olmak isterim

Yavrucuğum.

Rotterdam,10.03.2002', 'Bir anne düşünki Yavrusu için canını düşünmeden feda eder Yemez yedirir, giymez giydirir Hasta olsa kan ağlar içi Saçını süpürge, gözyaşları...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/yavrucugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamıyorum', 'bulamiyorum-duahan-hanci-c3xa8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne aradığımı bilmiyorum

Ne yazacağımıda 

Sallayım bi şeyler dedim

Ve aklıma şarkılar geldi

Sana bu şiiri yazan benmiyim

Yoksa ben delimiyim

Martılar uçuyor deniz kenarında

Uçuyor onlar ben sanki bir gemiyim

Aklıma daha bi şey gelmiyor

Ama emin ol gelse hiç tereddütsüz

Sorgusuz sualsiz...

Kalemler kağıtla birleşmiyor', 'Ne aradığımı bilmiyorum Ne yazacağımıda  Sallayım bi şeyler dedim Ve aklıma şarkılar geldi Sana bu şiiri yazan benmiyim Yoksa ben delimiyim ...', ARRAY['Türk Edebiyatı','Şiir','Duahan Hancı']::text[], 8.5, '{"poet":"Duahan Hancı","poet_slug":"duahan-hanci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulamiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamıyorum', 'dayanamiyorum-bahadir-bangi-2cd4f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dertli başıma dert eklendi, 

Yar beklemekten gına geldi, 

Tam sevdim dedim olmadı

Platonik aşk bu olsa gerek.

Dayanamıyorum, 

Her gece düşünmekten 

Onun hayalini görmekten 

üçüncü kişi olmaktan 

Derya evet seni seviyorum 

Ama sen değil

Sen onu seviyorsun

Beni değil 

Ne kadar katlanıcam 

Artık dayanamıyorum 

Anla beni 

SENİ SEVİYORUM', 'Dertli başıma dert eklendi,  Yar beklemekten gına geldi,  Tam sevdim dedim olmadı Platonik aşk bu olsa gerek. Dayanamıyorum,  Her gece düşün...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Bangı']::text[], 8.5, '{"poet":"Bahadır Bangı","poet_slug":"bahadir-bangi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dayanamiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır Eyle', 'sabir-eyle-ozan-arif-84750', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deli gönül isyan etme boşuna, 

Sabır eyle, Şükür eyle, Dua et. 

Kul olanın her şey gelir başına, 

Sabır eyle, Şükür eyle, Dua et. 

Düşün düşün hayal bitti düş bitti, 

Ağla ağla gözümdeki yaş bitti, 

‘Amentü’ ye iman ettim iş bitti, 

Sabır eyle, Şükür eyle, Dua et. 

Her dara düştüğün yerde Allah’tan, 

Hakkında hayırı ver de Allah’tan 

Hayır da Allah’tan şer de Allah’tan 

Sabır eyle, Şükür eyle, Dua et. 

Bazı zamanlarda bazı yerlerde, 

İnanırım derde derman derler de, 

Çünkü hayır varmış bazı şerlerde 

Sabır eyle, Şükür eyle, Dua et. 

Mevla çekirdeğe orman gizlemiş, 

Tahıl tanesine harman gizlemiş, 

Yılanın zehrine derman gizlemiş, 

Sabır eyle, Şükür eyle, Dua et. 

Gönül bizi bilmeyen var bilen var, 

Halimize ağlayan var gülen var, 

Bizden daha büyük derdi olan var, 

Sabır eyle, Şükür eyle, Dua et. 

Kaç ülkü gülünün şimdi şu anda, 

Kellesi bekliyor yağlı urganda, 

Hiç olmazsa gel onlardan utan da, 

Sabır eyle, Şükür eyle, Dua et. 

Gönül korkma; çok çok sürgün ölürsün 

Ne açıkta ne de düzde kalırsın, 

Bir mezarı nerde olsa bulursun, 

Sabır eyle, Şükür eyle, Dua et. 

Felek zulüm ediyorsa koy etsin, 

Duy ARİF’i çile bitsin dert bitsin. 

‘Tevvekeltü taalallah’ de gitsin. 

Sabır eyle, Şükür eyle, Dua et.', 'Deli gönül isyan etme boşuna,  Sabır eyle, Şükür eyle, Dua et.  Kul olanın her şey gelir başına,  Sabır eyle, Şükür eyle, Dua et.  Düşün düş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sabir-eyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-ender-cetinkaya-walf5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Martının kanadına

Takılmış merhabam

Süzülür sana doğru Kızkule’si üstünden, 

Değdi değecek tüyleri...

Karşı yakada, 

Minareler selam durur gibi.

Martı telaşlı, 

Tez getirsin, üşümesin rüzgardan merhabam diye...

Güneşin kızardığı yerde

Bırakıverir avuçlarına senin.

Gagasında mağrur tebessüm...

Martı yorgun, 

Martı mutlu...

Sonunda, 

Merhaba! ..', 'Martının kanadına Takılmış merhabam Süzülür sana doğru Kızkule’si üstünden,  Değdi değecek tüyleri... Karşı yakada,  Minareler selam durur g...', ARRAY['Türk Edebiyatı','Şiir','Ender Çetinkaya']::text[], 8.5, '{"poet":"Ender Çetinkaya","poet_slug":"ender-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/merhaba-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-baris-manco-ggx27', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerimle büyütüyüm

Solarıken diritiyim

Çiçeğimi kopardın sen 

Ellere verdin

Dağlar dağlar

Kurban olam yol ver geçem

Sevdiğimi son bir olsun

Yakından görem', 'Ellerimle büyütüyüm Solarıken diritiyim Çiçeğimi kopardın sen  Ellere verdin Dağlar dağlar Kurban olam yol ver geçem Sevdiğimi son bir olsun...', ARRAY['Türk Edebiyatı','Şiir','Barış Manço']::text[], 8.5, '{"poet":"Barış Manço","poet_slug":"baris-manco","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/daglar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık adına', 'i-nsanlik-adina-yuksel-arslan-x6sod', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'fare gözler

köpek dişler

köstebek kulaklar

yılan zehiri

akrep iğnesi ve  koca bir 

su aygırı ağzı...

ahtapot kollar

kirpi oklar

kanarya sesi

yarasa emiciliği ve yapışkan bir 

sülük...

bir insanda

ne ararsan var...', 'fare gözler köpek dişler köstebek kulaklar yılan zehiri akrep iğnesi ve  koca bir  su aygırı ağzı... ahtapot kollar kirpi oklar kanarya sesi...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Arslan']::text[], 8.5, '{"poet":"Yüksel Arslan","poet_slug":"yuksel-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/insanlik-adina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yanılsama', 'yanilsama-yuksel-arslan-9ln3l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'galiba 

yanılıyorum..

hiçte anlatıldığı 

ve anladığım gibi değil...

bazen, 

ellerimdeki titreme

açlıktan, soğuktan

ya da tansiyondan olabiliyor.

ve galiba

dünya gerçekten de yuvarlak..', 'galiba  yanılıyorum.. hiçte anlatıldığı  ve anladığım gibi değil... bazen,  ellerimdeki titreme açlıktan, soğuktan ya da tansiyondan olabili...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Arslan']::text[], 8.5, '{"poet":"Yüksel Arslan","poet_slug":"yuksel-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yanilsama-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ilham', 'ilham-yuksel-arslan-mf9o1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne bekliyordun

bazen böyle oluyor işte..

bir de bakmışsın, 

üstüne sıçratılan çamurlu su, 

sana ilham vermiş...', 'ne bekliyordun bazen böyle oluyor işte.. bir de bakmışsın,  üstüne sıçratılan çamurlu su,  sana ilham vermiş......', ARRAY['Türk Edebiyatı','Şiir','Yüksel Arslan']::text[], 8.5, '{"poet":"Yüksel Arslan","poet_slug":"yuksel-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ilham-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'paranoya ve olası rahatsızlıklar', 'paranoya-ve-olasi-rahatsizliklar-yuksel-arslan-ewg83', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanırım

iki hafta içinde üçüncü intihar denememdi

önce, iple asmak istemiştim kendimi

lanet tavan beni taşıyamamıştı

sonra

ilaçları yuvarlamıştım üç dört kutu..

içlerinden biri 

bulantı yapan türden

nerden bilebilirdim

kusmuştum heryere..

ve şimdi elimde, 

pas tutmuş kabzasıyla

eski bir 7 65

iki mermi hakkım var.

öyle bir nokta seçmeliyimki

anında bitmeli herşey.

tavana yükselip 

henüz soğumamış bedenimi

keyifle izlediğimi düşündüm bir an..

çenemin altına yerleştirdim

gözlerimi kapattım

Tanrım! 

biraz cesaret

biraz aptallık gerek bana..

bir kaç nefes daha çektim hayattan.

tetiğe bastığımı hatırlamıyorum

duyduğum gürültü acıdan beterdi

kulaklarımda  derin  uğultu

burnumda keskin barut kokusu, 

ellerim kan içinde...

birşey olmamıştı

sadece uğultudan kıvranıyordum

insan sağırlaşmışken

beyninin içinde sıkışan gürültü mahvediyor

kuru sıkı olduğunu anlayacak kadar iyi değilim bu işte

silah sesi, komşularımı harekete geçirmiş olmalıydı

komşularım! 

ne çok çektiler benden..

polis her an gelebilirdi

tavan arasına saklandım

böyle görmeleri hoşuma gitmezdi

bir süre sonra 

kapıyı zorlayıp içeri doluştular...

kimi elini ağzına götürmüş

kimi gözlerine..

duvarıma kusuyor biri, 

bir başkası göze girme sevdasında

ipucu olacak herşeyi değerlendirmeye başlamış bile şimdiden

ve ne gariptirki 

işe yatak odamdan başlamış..

ama hiç kimse akıl edip 

tavan arasına bakmıyordu.

öyle ya 

merdivensiz çıkılacak bir yer değildi

ve 

benim merdivenim yoktu...

olacakları izlemeye koyuldum.', 'Sanırım iki hafta içinde üçüncü intihar denememdi önce, iple asmak istemiştim kendimi lanet tavan beni taşıyamamıştı sonra ilaçları yuvarlam...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Arslan']::text[], 8.5, '{"poet":"Yüksel Arslan","poet_slug":"yuksel-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/paranoya-ve-olasi-rahatsizliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yokken', 'sen-yokken-cahit-kulebi-855z3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yokken gittim

Korkularımın üstüne

Hiç ardıma bakmadım

Gümüş şiirler yazdım sen yokken

Çok yangın çıktı yüreğimde

Küllerini bile savurmadım

Irak denizlerin fırtınasıydım

Uzak iklimlerin sert rüzgarları

Kulaçlarken denizinde gurbeti

Kanlı savaşlarım, 

Belalı sevdalarım olmadı hiç

Ama hep sustum, 

Hep ağladım, hep yandım sen yokken.

Bekliyorum dönüşünü yeniden, 

Bir gelsen, 

Hayatın önünden alsan beni

Bir gelsen, 

Sellerin önünden alsan beni

Bir gelsen, 

Ölümlü düşlerimden alsan beni.

Çok durdum güneşe karşı bir başıma

Savrulurdum rüzgarlarında sensizlik denizinin

Sen yokken, 

Az dolaşmadım gönlümün kuytularında

Üşüyen karanfilim şimdi buruşuk parmaklarda

Bir kırağı ayazıydım gecenin kollarında

Zifirlerinde sadece ben üşürdüm.

Hiç aldırmadım esen rüzgara

Hiç dinlenmiş bir yürekle çıkmadım ortaya

Yinede hiç yıkılmadım giden trenlerin ardından

Ama bütün yangınlar beni yaktı önce

Hep ortasında kaldım vurgunların

Vurgun nedir ki? deme

Bir babanın serzenişi nasılsa öyle

Bayrakları indirilmiş, 

Bozguna uğramış bir hisardım sen yokken

Hep sustum, 

Hep yandım, hep ağladım sen yokken.

Bir gelsen, 

Yangınlardan alsan beni, 

Bir gelsen, 

Dünyalarımdan alsan beni, 

Bir gelsen, 

Şafaksız gecelerden alsan beni, 

Ama ne zaman gelsen, 

Akşam kızılı gözlerimle bulacaksın beni.', 'Sen yokken gittim Korkularımın üstüne Hiç ardıma bakmadım Gümüş şiirler yazdım sen yokken Çok yangın çıktı yüreğimde Küllerini bile savurmad...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi']::text[], 8.5, '{"poet":"Cahit Külebi","poet_slug":"cahit-kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sen-yokken-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmez', 'bilinmez-oguz-atalay-jpfbk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlasam acep duyar mı feryatlarımı

Çağırsam gelir mi koşa koşa

Seni seviyorum desem

Ben de seni dermi...Bilinmez! 

O da sever mi beni

Benim onu sevdiğim kadar

Uzatsam ellerimi ona doğru

Tutar mı ellerimi hiç bırakmamacasına...Bilinmez! 

Gel desem, gidelim buralardan

Gelir mi benimle

Hiç arkasına bakmadan, 

Geçmişi bir kalemde silerek...Bilinmez! 

Gelse benimle, gitsek mutluluklar diyarına

Sevse o da beni, benim onu sevdiğim kadar

Silse bir kalemde geçmişi, hiç arkasına bakmadan

Vuslat bu aşkı öldürür mü...Bilinmez! 

                                       5 Şubat 2002', 'Ağlasam acep duyar mı feryatlarımı Çağırsam gelir mi koşa koşa Seni seviyorum desem Ben de seni dermi...Bilinmez!  O da sever mi beni Benim ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Atalay']::text[], 8.5, '{"poet":"Oğuz Atalay","poet_slug":"oguz-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilinmez-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun Yanımda', 'yoksun-yanimda-oguz-atalay-10k1z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yar yine yoksun yanımda

Yine sensiz, bir sigara daha

Yar yine yoksun yanımda

Gözlerim ufukta ve bir sigara daha

Yar yine yoksun yanımda

İşte sensiz bir gün daha

Yar yine yoksun yanımda

Sana hasret bedenim, yine isyanlarda

Yar yine yoksun yanımda

Ağlıyorum her dem, seni ana ana

Yar yine yoksun yanımda

Yine Güneş batıyor, sensiz bir gecenin başında

Yar yine yoksun yanımda

Tükeniyor ömrüm, sensizliğin kucağında

Yar yine yoksun yanımda

Sensizliğin kucağında, ÖLÜME BİR ADIM DAHA...

                               

                            5 Şubat 2002', 'Yar yine yoksun yanımda Yine sensiz, bir sigara daha Yar yine yoksun yanımda Gözlerim ufukta ve bir sigara daha Yar yine yoksun yanımda İşte...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Atalay']::text[], 8.5, '{"poet":"Oğuz Atalay","poet_slug":"oguz-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yoksun-yanimda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'R ve Ra', 'r-ve-ra-huseyin-erdol-p6vzv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüyorduk oralarda

Kurşun fistan

Sancılar değirmeninde

Ramses’le ben göz gözeydik

Aynı ayın aynı gecesinde

Kumda yürüyen ayaklarımız kayıp gidiyordu

Göğsümüzde taşımıştık saraylarının taşlarını

Güneşe uzanan bizdik

Güneşin oğlu onlar

Re bir notadan değildi

Sorup buldurulan

Kum dağının başına taş yığan başım

Aklından vurulmuş

Karıncalar gibi taş taşıyorduk

Göklere ulaşsınlar diye 

Şanları sürsün diye

Sular çekilip gidinceye dek

Çıkarıp göğsümüzden yıldızlarla dolu göğü

Ellerine döktüğümüzden sonradır

Acılar gölünde susuz kıvranışımız

Ra onlardı

Göklere taşları uzatan biz

Serinde uyuyan onlardı

Güneşte yanan biz

Ölmüştük orada bir taşın dibinde

Çıkarıp kuyudan suyu

Çatlak dudaklarla susuzluktan

Ra onlardı suyu taşıyan biz

___________________________________', 'Ölüyorduk oralarda Kurşun fistan Sancılar değirmeninde Ramses’le ben göz gözeydik Aynı ayın aynı gecesinde Kumda yürüyen ayaklarımız kayıp g...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdöl']::text[], 8.5, '{"poet":"Hüseyin Erdöl","poet_slug":"huseyin-erdol","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/r-ve-ra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bercesteler', 'bercesteler-fuzuli-jmt0l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Döğülmeye söğülmeye koğulmaya billâh

Hep râzıyım ammâ ki efendim senin olsam

Eylesen tûtîye tâlim-i edâ-yı kelîmât

Sözü insan olur ammâ özü insan olmaz

Ey dil ki hecre doymayıp istersin ol mehi

Şükr et bu hâle yoksa gelir yüz belâ sana

Cevr odı yaktı beni yanımda durma ey gönül

Bir tutuşmuş âteşem kurb-ı civârımdan sakın

Edemem terk Fuzûlî ser-i kûyın yârin

Vatanımdır vatanımdır vatanımdır vatanım

Ey Fuzûlî câna yetmişem gönülden şükr kim

Bağladım bir dil-bere kurtardım ancan cânımı

Cân u dil kaydını çekmekten özüm kurtardım

Cânı cânâneye ettim dili dildâra fedâ

Ah eylediğim serv-i hırâmânın içindir

Kan ağladığım gonce-i handânın içindir

Dostum âlem seninçün ger olur düşmen bana

Gam değil zîrâ yetersin dost ancak sen bana

Esîr-i gurbetiz biz senden özge âşinâmız yok

Ayağın kesme başınçin bizim mihnet-serâlardan

Kıldı zülfün tek perişan hâlimi hâlin senin

Bir gün ey bî-derd sormazsın nedir hâlin senin

Ne yanar kimse bana âteş- i dilden özge

Ne açar kimse kapım bâd-ı sabâdan gayrı

Cân u ten oldukça menden derd ü gam eksik değil

Çıksa can hâk olsa ten ne can gerek ne ten bana

Avâreler felekzedeler mübtelâlarız

Alemde bir muhabbete kalmış gedâlarız

Hâlî etmiştir mahabbet beni benden dostlar

Ayb kılman âlemde görseniz bî-pervâ beni

Demen kim adli yok yâ zulmü çok her hâl ile olsa	

Gönül tahtına andan özge sultân olmasın yâ Rab

Tutuştu gam oduna şâd gördüğün gönlüm

Mukayyed oldu ol âzâd gördüğün gönlüm', 'Döğülmeye söğülmeye koğulmaya billâh Hep râzıyım ammâ ki efendim senin olsam Eylesen tûtîye tâlim-i edâ-yı kelîmât Sözü insan olur ammâ özü ...', ARRAY['Türk Edebiyatı','Şiir','Fuzuli']::text[], 8.5, '{"poet":"Fuzuli","poet_slug":"fuzuli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bercesteler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-veli-altioglu-ay2gp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen içtiğim her kadehte 

Sen özlediğim tek sevgili 

Sen göz yaşlarımın sebebi 

Sen yalnızlığıma çaresi 

Sen sevgimin ölümsüzlüğü 

Sen her şeyiyle umudum 

Sen karamsarlıktan aydınlığa tek sebebim 

Sen dudaktaki tek tebessüm 

Sen karanlık gecelerin ışığı 

Ve sen benim hayata başlangıcın 

Ve sen benim hayatımın son noktası', 'Sen içtiğim her kadehte  Sen özlediğim tek sevgili  Sen göz yaşlarımın sebebi  Sen yalnızlığıma çaresi  Sen sevgimin ölümsüzlüğü  Sen her şe...', ARRAY['Türk Edebiyatı','Şiir','Veli Altıoğlu']::text[], 8.5, '{"poet":"Veli Altıoğlu","poet_slug":"veli-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-138-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bercesteler', 'bercesteler-na-ili-x6859', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne gamzeden ne gam-ı yâr-ı pür-cefâdandır

Bizim şikâyetimiz baht-ı bî-vefâdandır

                         * * * 

Gamınla ülfetimiz var sürûru neyleyelim

Safâ-yı hâtırımız yok huzûru neyleyelim

	          * * *

Hevâ-yı aşka uyup kûy-i yâre dek gideriz

Nesîm-i subha refîkız bahâre dek gideriz

	          * * *

Bahârı neyleriz ol gül-izâr-ı gonce-femin

Gülüp açılması bin nev-bahâra değmez mi', 'Ne gamzeden ne gam-ı yâr-ı pür-cefâdandır Bizim şikâyetimiz baht-ı bî-vefâdandır                          * * *  Gamınla ülfetimiz var sürûr...', ARRAY['Türk Edebiyatı','Şiir','Na''ili']::text[], 8.5, '{"poet":"Na''ili","poet_slug":"na-ili","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bercesteler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bercesteler', 'bercesteler-sair-nahif-uoyj8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göz gördü gönül sevdi seni ey yüzü mâhım

Kurbânın olam var mı benim bunda günâhım

                             * * *

Ölsün mü neylesin olan âşüfte hüsnüne

Kurbânın olduğum seni sevmek hatâ mıdır

                             * * *

Mir''ata bakma bir iki gün eyle tecrübe

Sabr eylemek firâkına müşkül değil midir', 'Göz gördü gönül sevdi seni ey yüzü mâhım Kurbânın olam var mı benim bunda günâhım                              * * * Ölsün mü neylesin olan ...', ARRAY['Türk Edebiyatı','Şiir','Şair Nahifî']::text[], 8.5, '{"poet":"Şair Nahifî","poet_slug":"sair-nahif","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bercesteler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Donlara Destan', 'donlara-destan-umit-yasar-oguzcan-4h66t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Don deyip de geçmeyelim

Hepimizin iyi kötü bir donu var

Yünlüsü pamuklusu

İpeklisi naylonu var

Ayşe hanımınki fıstıki yeşil

Durur yaprak misali tende

Fatma hanımınki patiskadan

Rengi havai pembe

Mühendisin karısı

Naylon donu tercih eder

Ayak ayak üstüne atıp

Komşulara caka satar

Mühendis beyi sorarsanız

Çifte don giyiyor kışın

Zırh gibi kalkan gibi bir şey

Vallahi işlemez kurşun

Siyatiği var Fitnat hanımın

Uzundur fanila donu

Zehra kadının ki bohça gibi

Yamalıdır her yanı

Leman hanımefendinin ise

Kâh mavi kâh gül kurusu renkli

Hepsi de avuç içi kadar

Kenarları işlemeli ipekli

Ya altın dişli Pakize hanımın donu

Bir gören bir şiir yazar

Ayıptır söylemesi

Pakize hanım donsuz gezer', 'Don deyip de geçmeyelim Hepimizin iyi kötü bir donu var Yünlüsü pamuklusu İpeklisi naylonu var Ayşe hanımınki fıstıki yeşil Durur yaprak mis...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/donlara-destan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'aldanmışım', 'aldanmisim-aydin-karatay-dpn4w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşamaya geldiğimi sanmıştım oysa

şu kranlık mahsenin karartılarında 

sevmeye geldiğimi sanmıştım insanları

anlaşılmaya anlamaya geldiğimi dünyayı 

aşkı yaşamaya geldiğimi sanmıştım oysa

yanılmışım 

hen an duygusuz`luk huysuzluk içimde 

saygısız direnmeler her an anlamsız 

dayanıksız dövüşmeler kişilik bölünmeleri

ay altında karartı martı sessizliği

ve ummadıgım çirkinlikler 

şaşkınlık üstüne uykusuz geceler 

anlamaya çalışmadıgım bir yaşam tarzı 

yalanmış

aramaya ara vermişim yılları

bulamamışım zaten hep kayıp yanımı 

bıkkınlık vermiş çok gercekler 

hayalmiş.....

bulunması gerekenler`miş aslı yalanlar

àldatmak gerekirmiş aslıda sevdayı

kırmak gerekirmiş dostlukları 

bedeli olmalıymış karşılığı kurlan yapıların

harcından demirinden tulasından çalmak gerekirmiş

yıkılması için çabalamak vurmak azarlamak aşalamak

yalanmış be düzen 

ve yalanlar üzerine yapılanmış bir hayal denizi güzellik adına 

yazık olmuş aslında 

harcanana emeklere emek değilmiş zaten 

anladım..........

15  -  03  -  02    yatağan/mula       12  :    12', 'yaşamaya geldiğimi sanmıştım oysa şu kranlık mahsenin karartılarında  sevmeye geldiğimi sanmıştım insanları anlaşılmaya anlamaya geldiğimi d...', ARRAY['Türk Edebiyatı','Şiir','Aydın Karatay']::text[], 8.5, '{"poet":"Aydın Karatay","poet_slug":"aydin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aldanmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçların İsyan', 'saclarin-i-syan-cafer-turac-pvamu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gün biterdi gözuçlarımda saçlarının şiddetine sokulurdum

gözlerine karşılık vermeye gelirdim ardımda şehirler bırakarak

eline hangi çiçeği alsan suyun hükmü kırılırdı, duyardım

hangi şekilde bıraksan da gövdeni uykusuz kalırdım.

adını ağzımda köz tutar gibi tutardım, ölüm

harfi harfine çınlardı akşamları alışırdım

alışırdım köpüklerini bir türlü anlatamayacağım denize,

hüzün ceketimin iç cebinde bir tütün yaprağı gibi

dalardı yüreğime öyle hafif öyle derin, hayat

yolculuklar sonrası sabun gibi azalırdı sanki, sen

ey bukleli saçlarında şairliğim ölen kız, kahrım

seninle kuleleri gençliğim olan o kente gidilmez mi? 

artık gözkapaklarımda zorlanan gözyaşlarını

anlatmayacağım sana

anlatmayacağım artık ağzmla kardığım papatyanın

her gün caddelerde üstüne basarak geçtiim ıssızlığımı

bir şeylerin kayıp gitmesini ellerimin arasından, umulmaz bir şekilde

soluk soluğa duyuyorum gırtlağıma yüklenen bu şarkıyı,

venasıl horlanıp geçildikse ölü gülüşlerle yıllar boyu

çocukken bir şarkısı söyler gibi ağlamanın sevinci

ağlamak istiyorum yeniden uçarı kitapları okuyarak

ellerime dikenler batsın istiyorum dizlerimin kanamasını

yeniden ağlamak istiyorum sesimin bütün hazinelerine dokunarak

ve sonra dağların gerisinde duruyorum, rüzgarın savurduğu derin

kalbimin görkemini bağırmak istiyorum şakıyan bir kuş gibi

benimle ölür müsün? sevgilim sevgilim.

(Aralık 1982)', 'gün biterdi gözuçlarımda saçlarının şiddetine sokulurdum gözlerine karşılık vermeye gelirdim ardımda şehirler bırakarak eline hangi çiçeği a...', ARRAY['Türk Edebiyatı','Şiir','Cafer Turaç']::text[], 8.5, '{"poet":"Cafer Turaç","poet_slug":"cafer-turac","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/saclarin-isyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biten Bir Şarkıya', 'biten-bir-sarkiya-cafer-turac-o1ksj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yeniden bir şeyler yazmak istiyorum, yeni şeyler

kargışlanmamış bir şeyler

nehrin kızını yazmak istiyorum nehri öpen dudaklarını

kaçak bir güvercin oluyor yüreğim, bir rüzgar

güz, hırkama altın ışıklar bırakıyor, kendimi şehre bırakıyorum

ve yüzümü çiğ düşmüş kelebek kanatları sarartıyor hasta kızlar, kör bekçiler

sonra alışıyorum ben de posta katarını gözleyip telefonların kırık diline

hoşça kalın çocuklarım hoşça kal karım ama beni unutmayın derken

bir tül çekiliyor gözlerimize, ıslak otlara atılmış sevgili resmi gibi

ey çocuk, ey nehrin kızı, bir dilek sun, bir kalp yarala, bir sepet

zerdali çiçeği taşı bu yaşlı gökyüzüne.

24 Ağustos 1983', 'yeniden bir şeyler yazmak istiyorum, yeni şeyler kargışlanmamış bir şeyler nehrin kızını yazmak istiyorum nehri öpen dudaklarını kaçak bir g...', ARRAY['Türk Edebiyatı','Şiir','Cafer Turaç']::text[], 8.5, '{"poet":"Cafer Turaç","poet_slug":"cafer-turac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biten-bir-sarkiya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amasya Mektupları', 'amasya-mektuplari-cafer-turac-bbwe3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I.

nasıl tanınabilir yüzüm seninle

böyle bırakıp gittin ya beni

dalgın bir kuğuydum, oyalanmadın

sesinin rengine hapsettin beni.

ve şimdi bir büyük anısın sokaklarımda.

nasıl tanınabilir yüzüm seninle

ıtır kokusu toprağındayım

kapılara paslı kilit vurmuşlar

sarıya boyamışlar evlerimizi

sanki güvercinsin, kanadındayım.

ve bir turuncu kandil kovalar beni.

nasıl tanınabilir yüzüm seninle

bir kış odasında vuruldum ağır

bu yaralar şu kalbime musallat

işte gidiyorum açıyor zakkum.

yüzüme baktıkça çağırıyorum seni.

II.

her şey seninle şimdi, masum ve dilsiz

öyle çıkıyoruz yukarılara

ağzın, ötelerin şelalesidir

saçlarına kar değmemiş daha ne? 

ellerinden tutayım bırakma beni.

sesin okunuyor su çırpıntısından.

her şey seninle şimdi, karanlık kışla

gömleğime değen berrak bir türkü

al, al götür beni akşamlarına

gideceğim adres yeni değil ki

oralarda selvi, bir kaç menekşe. 

ihanet sıçrıyor ak gerdanından.

her şey dağılıyor seninle şimdi.

ah! künhüne vardığım sırlarım bitti

yüzünle sınandım, senin yüzünle

yalnız tasan kaldı bana, hafifliğinden

bir su kenarında akan gözlerim.

ayrılık topluyor dudaklarından.

III.

derler ki imlası kırık kaderin

içinden geçermiş ferhatın kahrı

ya ben sana nasıl gelirim şirin

bulutun içinden rüzgar sesinden

ya ben sana nasıl gelirim ferhat

kalbimdeki ırmak sakinliğinden.

derler ki goncası açmaz bir aşkın

kapıları örtük olurmuş he mi? 

mermere yazılan harfler kaybolur

yağmur düşer sızlanırmış karanfil

ben böyle bekliyorum yollarda, gülüm

imlası kırık kalbimle seni.', 'I. nasıl tanınabilir yüzüm seninle böyle bırakıp gittin ya beni dalgın bir kuğuydum, oyalanmadın sesinin rengine hapsettin beni. ve şimdi bi...', ARRAY['Türk Edebiyatı','Şiir','Cafer Turaç']::text[], 8.5, '{"poet":"Cafer Turaç","poet_slug":"cafer-turac","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/amasya-mektuplari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl', 'akil-necip-fazil-kisakurek-1riwn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıl akıl olsaydı adı gönül olurdu

