INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Re Re Re Ra Ra Ra', 're-re-re-ra-ra-ra-ali-galip-2iffu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün bir taraftarın daha öldü

Yaz üstlerini postalamış sana

Sarı sarı madeni

Zaten yeni de değil bunlar

Pardösünü giy, pijamanı

Emekli ikramiyeni, piyango biletini al

Melankolini, mundar dediğin etleri de unutma 

 nasıl tahammül edilemezsen öyle 

Kuma gelecek

Dışarıda  arabalar yoksa

 Akrep ve yelkovan kapalım kasandan

 Senin hiç acelen oldu mu? 

Bırak artık bu lafları

Hiiç öylesine konuşuyorum dünyanın başka taraflarında da konuşuluyor hep konuşuluyor

Unutamam ben unutamam ama

Sokağa evet sokağa 

Bir de ceset beğenelim

Sokağa çıkıyoruz', 'Bu gün bir taraftarın daha öldü Yaz üstlerini postalamış sana Sarı sarı madeni Zaten yeni de değil bunlar Pardösünü giy, pijamanı Emekli ikr...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip']::text[], 8.5, '{"poet":"Ali Galip","poet_slug":"ali-galip","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/re-re-re-ra-ra-ra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Virgül Bugün', 'virgul-bugun-ali-galip-tc77u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1.

Bugün kulelerime intihar dalışı yaptım

Sarı çizgimi geçip

Salonlarımda elbisemi değiştirdim, futbol oynadım, kaleci ben santrfor ben

Toplarımı kestim, küfrettim

Kimseler duymadı yeten bir şeyim var mıydı

Hissettirmediğim bir şey  sanırım

Şu saatim için çaldırttığım kolumu bilmeyen

Kalmasın istediğimi anladım

2.

 Kelimeler icat ettirmezdi bu kadar  bir insana

Dünyanın sonsuz kadrajı olmasaydı kendini

Belki de  sırf  bundan

Senin  için 

En unutkan çağımı yaşıyorum

3.

İnfilakımdan önce

Çiçek bahçelerim

Çayım, dövüşlerim.ve bütün müritlerim

Size kalacak bir kılıcım olmasına inandım

Bütün eski düşmancıklarım bir keşif  borçlusunuz bana', '1. Bugün kulelerime intihar dalışı yaptım Sarı çizgimi geçip Salonlarımda elbisemi değiştirdim, futbol oynadım, kaleci ben santrfor ben Topl...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip']::text[], 8.5, '{"poet":"Ali Galip","poet_slug":"ali-galip","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/virgul-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-sair-esra-y8ykh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cocuktum seni tanıdıgımda

Hani ölsem, cennetliktim.

Gordugum en adam cocuktun sen.

Herkes ettigini cekermis ya, 

Etmedigini cekmen mi dokunurdu bana, 

Ne bulduysam sende...

Cocuk aklı iste.

Susuz bir topraga ektiler seni

Onca zaman, tek yesil yaprak acmadın.

Hala bir agzın var kunusmak icin

Kulaklarına kum dolmus olmalı ki senin

Haberi yok artık ettiginden agzının.

Simdi ici bosaltılmıs bir odun parcası, 

Herkes ettigini cekermis ya, 

Boylece bilinsin, 

Cocukken de, odunken de benimsin.', 'Cocuktum seni tanıdıgımda Hani ölsem, cennetliktim. Gordugum en adam cocuktun sen. Herkes ettigini cekermis ya,  Etmedigini cekmen mi dokunu...', ARRAY['Türk Edebiyatı','Şiir','Şair Esra']::text[], 8.5, '{"poet":"Şair Esra","poet_slug":"sair-esra","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-ensar-aktas-8cg26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani düşünceler vardır, haykırmak istersin de bazı engeller vardır haykıramazsın

Hani şiirler vardır, bir mısrayla romanlar dolusu duygular anlatır ama yazamazsın

Hani gözyaşları vardır, kan olur içine akar da tutamaz, durduramazsın

Hani özlemler vardır, içini burkar, yakar ama seni de onlar ayakta tutar

İşte beni ayakta tutan da senin sevgin, hasretin, gülüşün, öpüşün ve sensin

Rotterdam,14.02.2002', 'Hani düşünceler vardır, haykırmak istersin de bazı engeller vardır haykıramazsın Hani şiirler vardır, bir mısrayla romanlar dolusu duygular ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hani-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzeller Gördüm', 'ne-guzeller-gordum-zubeyir-sasmaz-rzc09', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne güzeller gördüm, 

Bu dünyada neleri gördüm.

Kimleri gördüm, Ne güzeller gördüm.

Senin gibi güzel güleni görmedim.

''Gülünce gözlerinin içi gülüyor'' 

senin için söylenmiş biliyorum.

Gülünce güller açıyor, yüzünde.

Sen gülünce,  neşe  geliyor  bizlere, 

Sen gülünce, bahar geliyor, çevrene.

Güzelleşiyor her şey sen gülünce', 'Ne güzeller gördüm,  Bu dünyada neleri gördüm. Kimleri gördüm, Ne güzeller gördüm. Senin gibi güzel güleni görmedim. ''Gülünce gözlerinin içi...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-guzeller-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Çıktın Karşıma', 'sen-ciktin-karsima-zubeyir-sasmaz-v2tug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen çıktın karşıma

Bir güneş gibi, doğdun yaşantıma.

Üstelik mevsim, Sonbahardı.

Tüm yapraklar dökülürken ağacımdan

Sen yeni açan bir güldün dalımdan.

Sen çıktın karşıma

Bir umut  gibi, doğdun yaşantıma.

Üstelik mevsim, Sonbahardı.

Benim dünya işlerim artık tamamdı.

o tatlı sözlerin beni hayat bağladı.', 'Sen çıktın karşıma Bir güneş gibi, doğdun yaşantıma. Üstelik mevsim, Sonbahardı. Tüm yapraklar dökülürken ağacımdan Sen yeni açan bir güldün...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ciktin-karsima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Anladım', 'simdi-anladim-zubeyir-sasmaz-1byu4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çok sevdiğim oldu, 

Kimleri sevmedim  ki, 

Kiminin, hizmetini, ev kadınlığını, 

Kiminin, Toplumla uygun adımlılığını

Kiminin, şiirini, hikayesini, edebiyatını

Kiminin, engin kültürünü, akıldanlığını.

Kimleri sevmedim  ki, 

Şimdi anladım,     en çok

Tatlı sözleri, 

Gülen gözleri,

SENİ SEVİYORMUŞUM.

canım benim', 'Bir çok sevdiğim oldu,  Kimleri sevmedim  ki,  Kiminin, hizmetini, ev kadınlığını,  Kiminin, Toplumla uygun adımlılığını Kiminin, şiirini, h...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/simdi-anladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek Ne Güzel', 'seni-dusunmek-ne-guzel-zubeyir-sasmaz-7p3vu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle aynı dünyada,  olduğumuzu düşünmek

Varlığını ruhumun derinlerinde hissedebilmek

Seninle aynı havayı soluduğumuzu

Aynı şarkıları dinlediğimizi  düşünmek, 

                                                                ne güzel.

Hiç gelmesen de, 

Hayatta olduğunu, yaşadığını bilmek bile, güzel.

Hele mutlu olduğunu, 

Arada bir, beni de hatırladığını düşünmek. 

                                                                ne güzel.', 'Seninle aynı dünyada,  olduğumuzu düşünmek Varlığını ruhumun derinlerinde hissedebilmek Seninle aynı havayı soluduğumuzu Aynı şarkıları dinl...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-dusunmek-ne-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN ...san ..sin CANIM', 'sen-san-sin-canim-zubeyir-sasmaz-voiqw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer benimle aynı fikri paylaşıyorsan

Aynı amaç uğrunda çabalıyorsan

Aynı yolda yılmadan yol alıyorsan

Kendi için değilde, vatan için çalışıyorsan

Kötülere, kötülüklere bayrak açmış savaşıyorsan

Anlamak için zavallıları arasına karışıyorsan

Yersiz, yurtsuz kimsesizler için  ağlıyorsan

Dünyayı korumak adına yel değirmenleriyle dalaşıyorsan

Doğruları, dürüstleri çalışkanları övüyor, alkışlıyorsan

Hırsızı, dolandırıcıyı, üç kağıtçıyı, yeriyor, kargışlıyorsan

Atanı, Vatanı, dünyayı, insanlığı seviyorsan.

Yeşili, çiçeği ağacı seviyor onları koruyorsan

Bildiklerini insanlığın hizmetine sunuyorsan

Nefesin yetmese de, maraton koşmayı göze alıyorsan

Halkının, yarınının güvence altına alınmasını istiyorsan.

Bunun için silahların üstüne, silahsız yürüyorsan.

Beceremezsin diyenlere; 

'' Olsun uğruna ölürüm ya '' diyorsan

Eğer benimle aynı fikri paylaşıyorsan.

Sanıyorum ki SEN; 

Anamın, babamın  yerindesin.

Belki de eşimden daha öndesin.

Çocuklarımla eşit yerdesin.

Sana artık canım diyebilirim.', 'Eğer benimle aynı fikri paylaşıyorsan Aynı amaç uğrunda çabalıyorsan Aynı yolda yılmadan yol alıyorsan Kendi için değilde, vatan için çalışı...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-san-sin-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyücü', 'buyucu-zubeyir-sasmaz-k20e1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyücülere inanmıyorum biliyor musun.

Her türlü, hurafelik inanca, savaş açtım.

Bilsen kimlerle, nerede,  nasıl dalaştım.

Onlar benle, ben onlarla, nasıl uğraştım.

Ama senin gibi biriyle hiç karşılaşmadım.

Seninki büyü değil de nedir  anlayamadım.

Benim nasıl, gülmekten,  yanaklarımı ağırttın.

Hayalinle bile mutluluğun en güzelini yaşattın.

Her gece kulağımda rodrigo, gözümde sen vardın.

Sana bir şey yazmadıysam, o geceyi yok saydım.

Ahh, Senin için nasıl yandığımı, bir anlasaydın.

Gecelerce, yaban ellerde beni yalnız koymasaydın.

Büyü ''düyse bu,  aman sakın  kimseler bozmasın.

Bırakın bir şikayetim yok, hep böyle, böyle  kalsın.

İsterse, yanıma yaklaşmasın, ellerimi hiç tutmasın, 

Ama uzaklaşmasın, güzel gözlerini benden ayırmasın', 'Büyücülere inanmıyorum biliyor musun. Her türlü, hurafelik inanca, savaş açtım. Bilsen kimlerle, nerede,  nasıl dalaştım. Onlar benle, ben o...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/buyucu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendin O Benim Sevdiğim', 'sendin-o-benim-sevdigim-hanife-yasemin-ixstz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sendin  benim sevdiğim

Hayatımı uğruna verdiğim

Gecemi gündüzümü hiç acımadan uğruna serdiğim

Sendin  ela gözlüm sendin benim sevdiğim

Gecelerdi seni bana getiren

Bir yıldızdı belki, bir çocuğun mahsumiyeti

Seni içimde ölümsüs kılan 

Sendin  ela gözlüm sendin benim sevdiğim

Mesafeler yalan, ayrılıklar yalan 

İçimde yanan bir avuç kül

Senden miras kalan

Çarpan kalbime aldırmadan 

Gecenin karanlığında kaybolup gidiyorsun

Bir bebek nidasında, bir yıldız kayışında

Sendin  ela gözlüm sendin benim sevdiğim', 'Sendin  benim sevdiğim Hayatımı uğruna verdiğim Gecemi gündüzümü hiç acımadan uğruna serdiğim Sendin  ela gözlüm sendin benim sevdiğim Gecel...', ARRAY['Türk Edebiyatı','Şiir','Hanife Yasemin']::text[], 8.5, '{"poet":"Hanife Yasemin","poet_slug":"hanife-yasemin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sendin-o-benim-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekarlık', 'bekarlik-mehmet-peker-hh12r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gördüğün her güzel sana aşıktır

Gördüğün her güzel yar bekarlıkta

Her minitebessüm aşka çağrıdır

Küçük tebessümler har bekarlıkta

Önüne gelene sevgilim dersin

Kusursuz sevdalar hayal edersin

Her yeni sevdayla uçar gidersin

Gönüle dünyalar dar bekarlıkta

Başına buyruksun, keyfe kedersin

Canın nerye derse orya gidersin

Nerde akşam orda sabah edersin

Gezdiğin tozduğun kar bekarlıkta

Uyudun uyandın hesap sormazlar

Manavmış bakkalmış kasap sormazlar

Harcarsın bol kese nisap sormazlar

Biraz da özgürlük var bekarlıkta...

                                  10 Mart 2002', 'Gördüğün her güzel sana aşıktır Gördüğün her güzel yar bekarlıkta Her minitebessüm aşka çağrıdır Küçük tebessümler har bekarlıkta Önüne gele...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Peker']::text[], 8.5, '{"poet":"Mehmet Peker","poet_slug":"mehmet-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bekarlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak', 'cikmaz-sokak-ozgur-kale-ftmd5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayalime dogru yuruyorum, 

Diye kandiriyorum hep kendimi, 

Aslinda bos bir kagit parcasi bu hayat, 

Yani anlayacagin sonu belli, 

Dogmakla bos yere imza attirdilar bana

Yani bana kalsaydi kacardim imzadan, 

Peki hayali yaratan dogum degil mi? 

Hayali olduren ne peki? 

Tabiki hayali yaratan dogum, olduren de o...

Kesinlike o.....', 'Hayalime dogru yuruyorum,  Diye kandiriyorum hep kendimi,  Aslinda bos bir kagit parcasi bu hayat,  Yani anlayacagin sonu belli,  Dogmakla b...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kale']::text[], 8.5, '{"poet":"Özgür Kale","poet_slug":"ozgur-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cikmaz-sokak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '12 Eylül', '12-eylul-arif-altunbas-5g76f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oniki eylül bindokuzyüz seksen

Gece dört sularında korkular kolgeziyordu

Issızdı Ankara sokakları gibi ülkem

Gölgeler ürkek ürkek yürüyordu

Taşları bağlasalar bile

Kaldırımlarda aç köpekler uluyordu

Kuşluk vakti doğacak  güneşimize

Meydan işgalcileri ve yarasalar

İçlerinden sinsi sinsi gülüyordu

Nice gece baskınlarından sonra

Vurgunlar,soygunlar,işgaller ve idamlar gördüm 

Bilirim hepsi alın  yazımın coğrafyasıdır

Anladım şimdi kimlermiş zulmün taşaronları

inkarın virüslerini taşıyan kanlarında

Her yerde gölgeler yürüyordu

Sessiz kalabalıkların damarlarında 

Öfkem ve sevdam direniyordu

İşgence operası filistin askısı

Zindanlarda nice çiçeklerim soldu

İtiraf tiyatrosu dibçik baskısı

Dörtyol ve kavşaklarda çörekleniyordu 

Milleti kurtarmak istiyenlerden

Millet de kurtulmak istiyordu

Gençliğimi katlettiler aşikar

Katiller ülkemde kahraman oldu

Ankara,12.09.1990', 'Oniki eylül bindokuzyüz seksen Gece dört sularında korkular kolgeziyordu Issızdı Ankara sokakları gibi ülkem Gölgeler ürkek ürkek yürüyordu ...', ARRAY['Türk Edebiyatı','Şiir','Arif Altunbaş']::text[], 8.5, '{"poet":"Arif Altunbaş","poet_slug":"arif-altunbas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/12-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandaki Yurek', 'kandaki-yurek-ozgur-kale-4f6sj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yuregime akan  kanlar, 

Bir volkandan cikan son lavlar gibi, 

Ama biliyorum ki.

Yuregimdeki depremler  beni sarsmaya devam etmekte, 

Belli etmek elde mi? 

Tabiki degil...

Nedeni ise  bende....', 'Yuregime akan  kanlar,  Bir volkandan cikan son lavlar gibi,  Ama biliyorum ki. Yuregimdeki depremler  beni sarsmaya devam etmekte,  Belli e...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kale']::text[], 8.5, '{"poet":"Özgür Kale","poet_slug":"ozgur-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kandaki-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lidia Adasi', 'lidia-adasi-ozgur-kale-yotye', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaklarda bir nedenim var artik, 

Atlantik ona cok yakin, 

Sanirim okyanusun icindeki bir ada o, 

Adanin adi Lidia...

Aramizda denizler, okyanuslar var ve de dahasi daglar, 

Ama ben onu biliyorum, 

Ona mutlaka ulasacagim..

Kisacasi, umut.....', 'Uzaklarda bir nedenim var artik,  Atlantik ona cok yakin,  Sanirim okyanusun icindeki bir ada o,  Adanin adi Lidia... Aramizda denizler, oky...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kale']::text[], 8.5, '{"poet":"Özgür Kale","poet_slug":"ozgur-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lidia-adasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızgınım Halkıma', 'kizginim-halkima-kamil-aydemir-eqp91', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her köprüden geçişimde

eğilir altına bakarım

bilirim sokak çocuklarının 

köprü altlarında yattığını

ve yüreğimi örterim

her sokak çocuğunun üstüne

ne zaman bir cezaevine ilişsem

hasret kokarım

bilirim mapustakilerinin hasret büyüttüğünü

ve mahkum çocuklarının boynunu büktüğünü

oracıkta bölünürüm parçalara

ellerinden tutmak için

boynu bükük çocuklarının

isterim ki boynunu bükmesin yarın

karşılaşınca bir politikacıyla

kulaklarımı tıkarım

bilirim politikacıların yalanlarıyla

halkını uyuttuğunu

uyumalarının ağır faturasını

çocuklara ödettikleri için

kızarım halkıma

halkı için ölen fidanlar dizilir yanıma', 'her köprüden geçişimde eğilir altına bakarım bilirim sokak çocuklarının  köprü altlarında yattığını ve yüreğimi örterim her sokak çocuğunun ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kizginim-halkima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşandım İnsan Yanımı', 'kusandim-i-nsan-yanimi-kamil-aydemir-tqacq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bana cemre cemre bakma dedim

alışık değilim

karakışın ortasında baharlara

gözlerimin kıyısından

                         yüreğime düştün

ısındı içim

ve anladım ki

sevgisiz

      aşksız ben bir hiçim

bana öyle bakma dedim

aşkın sardı bedenimi

yıldızları giyinmiş geceler

çocukları mutlu ülkeler

yalçın dağlar sandım kendimi

kuda kuşa

başı dara düşmüşe

insan sıcaklığına gereksimi olan herkese

                 açtım kollarımı

kuşandım insan yanımı

bana öyle bakma dedim

iyiki dinlemedin

sevginde mutluluğu öğrendim

sevdim kendimi

ve anladım ki

kendisiyle barışık olan insan

barışık olur yaşamla

bana öyle bakma dedim

içime sevgi sevgi aktın

karanlıklarımı aydınlattın

ve anladım ki

yaşam denen keskin dişli

                inişli çıkışlı yolda

insanlığım kadar varım', 'bana cemre cemre bakma dedim alışık değilim karakışın ortasında baharlara gözlerimin kıyısından                          yüreğime düştün ısı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kusandim-insan-yanimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yürek Atışında', 'her-yurek-atisinda-arslan-alp-5th7p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar getirse bana kokunu, 

 Hissederim o an tenimde yumuşak tenini, 

 Mesafeler kısalsa kollarımı uzattığımda, 

 Sana kavuşurdum her yürek atışında.', 'Bir rüzgar getirse bana kokunu,   Hissederim o an tenimde yumuşak tenini,   Mesafeler kısalsa kollarımı uzattığımda,   Sana kavuşurdum her y...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/her-yurek-atisinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya Hüzün Düştü', 'sevdaya-huzun-dustu-hayati-yavuzer-h62ok', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buruk tebessümlerle aynaya yüzün düştü

Sazlar suzinaktadır, sevdaya hüzün düştü

Aşk her mevsimde gelir, her âşık başka yaşar

Talihim yar olmadı bana da güzün düştü

Özlemler biriktirip yarınlara saklarken

Günüme, saatime, ânıma sızın düştü

Aylar, haftalar boyu yürüdüm ardınsıra

Ne yana döndü isem yoluma izin düştü

Kâh çöllerde kavruldum, kâh kutuplarda dondum

Hangi rüzgâr estiyse ateşin, buzun düştü

Neyleyim sensizliği kabul eylemez içim

Sustu ney, sustu tanbur, perdesi sazın düştü

Ay ninnileri sustu, geceyi sardı hüzün

Suzinak bir yalnızlık gelip ansızın düştü

 (14 Nisan 2002 Üsküp)', 'Buruk tebessümlerle aynaya yüzün düştü Sazlar suzinaktadır, sevdaya hüzün düştü Aşk her mevsimde gelir, her âşık başka yaşar Talihim yar olm...', ARRAY['Türk Edebiyatı','Şiir','Hayati Yavuzer']::text[], 8.5, '{"poet":"Hayati Yavuzer","poet_slug":"hayati-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevdaya-huzun-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtimal', 'i-htimal-cem-gumus-bx4l9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni dusundum de bu gece

 agladim hep sabaha kadar

 duvarda duran resmin guluyordu 

bana ama sen yoktun ki yanimda', 'seni dusundum de bu gece  agladim hep sabaha kadar  duvarda duran resmin guluyordu  bana ama sen yoktun ki yanimda...', ARRAY['Türk Edebiyatı','Şiir','Cem Gümüş']::text[], 8.5, '{"poet":"Cem Gümüş","poet_slug":"cem-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ihtimal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-cem-gumus-6jbtz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'oyle yabanci gibi uzak durma bana 

ne cabuk unuttun beni

az bisey sakalim uzadi 

yaklasta saril bana 

ben yabanci degilim sana 

biliyorsun ve taniyorsun beni

bak gozlerin yasardi 

sende beni seviyorsun

kacgun gecti sensiz biliyormusun 

ben sayamadim ya sen 

kac gunes batti sensiz biliyormusun 

ve kac cicek soldu sensiz

sokul biraz tut ellerimi 

op serinlesin catlak dudaklarim

sil gozlerimdeki yaslari

ve bir daha his yasarmasinlar

oyle uzaktan bakmakla olmaz sevmek 

birazda sevismek gerek

ditremeli bedenin 

sevmek icin de yurek gerek', 'oyle yabanci gibi uzak durma bana  ne cabuk unuttun beni az bisey sakalim uzadi  yaklasta saril bana  ben yabanci degilim sana  biliyorsun v...', ARRAY['Türk Edebiyatı','Şiir','Cem Gümüş']::text[], 8.5, '{"poet":"Cem Gümüş","poet_slug":"cem-gumus","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Kaldın', 'gec-kaldin-hakan-sengun-dhnsq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş olup doğma sakın şimdi ömrüme

Bende şafak çoktan söktü

Neden geç kaldın? 

Yeşermeye çalışma kurak topraklarımda

Mevsim bende güze döndü

Neden geç kaldın? 

Bir sen vardın aklımın bir köşesinde

Bir zamanlar deli gibi arayan bir ben.

Bir kum saati gibi yaşama umudum

Zamanı yitirmekten yana endişem

Ne sevincim kaldı ne neşem.

Birzamanlarlar bende bir sen vardın.

Neden kaçtın, neden saklandın, 

Senet yaptı ecel bana son günlerimi

Ardından karşıma çıkıp

Ben öderim deme şimdi.

Yıldız olup kayıp gitme gözlerimin önünde

Nice yıldız kayıp geçti ben aldırmadım.

Söylemeyi unuttuğum o hüzzam şarkı; 

Şimdi çalma boşyere

Neden geç kaldın?', 'Güneş olup doğma sakın şimdi ömrüme Bende şafak çoktan söktü Neden geç kaldın?  Yeşermeye çalışma kurak topraklarımda Mevsim bende güze dönd...', ARRAY['Türk Edebiyatı','Şiir','Hakan Şengün']::text[], 8.5, '{"poet":"Hakan Şengün","poet_slug":"hakan-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gec-kaldin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçluyum', 'sucluyum-ahmet-rasim-n28vo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin kasveti çöksede bana, 

Kelepçe vurulsa şah damarıma, 

Tek kelime söylemese ağzında, 

Bu işin suçlusu benim galiba.

Bende istemezdim böyle olmasın, 

Ay yüzün kederli mahsun durmasın, 

Gözünden damlayan yaşlar olmasın, 

Bu işin suçlusu benim galiba.

Mutluluk dilerim kalan ömründe, 

Gülümseme eksilmesin yüzünden, 

Bilmem görmek istermisin yeniden, 

Bu işin suçlusu benim galiba.', 'Gecenin kasveti çöksede bana,  Kelepçe vurulsa şah damarıma,  Tek kelime söylemese ağzında,  Bu işin suçlusu benim galiba. Bende istemezdim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Rasim']::text[], 8.5, '{"poet":"Ahmet Rasim","poet_slug":"ahmet-rasim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sucluyum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir iflas İlamı', 'bir-iflas-i-lami-abdulkadir-karaman-le42q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözü dönmüş 

Kana susamış kâtiller

Bırakmış bir tarafa insanlığı, aklı

-Kim bilir içlerinde ne hınçlar saklı

Kinle demlemiş vicdânı 

-Olduğu şüpheli vicdânın

Her kötülüğü yapmakta

Ne zaman, nasıl isterse canı

-Hiç insanlığı kalmaz mıymış insanın? 

Ava çıkmış 

Gece/gündüz, büyük/küçük ayırt etmeden

İnsan avına 

Her cephede

Yetişin imdada yetişin! 

Can çekişen değerler bitmeden

Vatan yok

Özgürlük yok 

Yiyecek, içecek, giyecek

Tutan yok

Mâsum, mağdur, mazlum bir cephede

-Niye kan, barut, acımasızlık, zulüm emeller? 

Bugün ona

Yarın sana

İlişme deme bana

Tarihte çok yaşandı bu haller

Ne olmuş ki bunların sevgisine? 

Sevgi dağıtması gerekirken 

Tetik çeker hemcinsine

Bir merhametsiz gölgesine sine sine

Hani, nerde bunlara dur diyecek eller? 

Talan eder sızlamadan 

Canı, malı, vatanı 

Kininde ölmüş kâtiller

Seyredin 

Kanı donduracak umarsızlıkla seyredin siz

Sızlamadan içiniz

Târihin görmediği bu talan katliâmı 

-Niye, böylesine acımasızlık

Böylesine insafsızlık 

Niye böylesine kısırlaşmış îzan, anlayış? 

-İşte en büyük yanlış

 En büyük aldanış

Hiç kin ve garazdan başka

Filiz veriri mi, boy atar mı

Kan ile sulanan temeller? 

Binmiş tarihi  bir zâlim korumasız 

Tarihi gariban bir milletin ensesine

Olan bitenden 

Tuzu kuruların nesine

Bu duyguların kangren olduğunun 

Umutların öldüğünün 

Belgesi değil de, ne? 

Bir çöküş başlamış ki

Yok oluş olacak devâmı

Kesmiş herkes birbiriden yardımı, ikramı

Bir düşünün

Nîmet mi bu, belâ mı? 

Değil, elbette değil

Ne yazık! ne acı ki! 

Bu insan ve insanlığın iflasının îlamı. 

10/04/02', 'Gözü dönmüş  Kana susamış kâtiller Bırakmış bir tarafa insanlığı, aklı -Kim bilir içlerinde ne hınçlar saklı Kinle demlemiş vicdânı  -Olduğu...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/bir-iflas-ilami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın (2)', 'kadin-2-mustafa-ozke-k5hre', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadın baş

