INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime Yeniden Sesleniş', 'kendime-yeniden-seslenis-muharrem-aslan-ee73z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgide tek kural var

Seveceksin

Hem de tüm varlığınla

Sevgin sana dönüyorsa

Çoğaldığını göreceksin

Dönmüyorsa

Azaldığını hissedeceksin

Anlamalısın ki

Yanlış adresdesin

Kendini bırakmıyacaksın

Haa hüzne de gireceksin

Hem de derinliğine aldırmadan

Korkma boğulmassın

Her yanın yakın kıyı

Unutma

Yenisini de aramayacaksın

Beklemiyeceksin de

Ama özleyeceksin

Zamanı gelince

O seni bulur

Hem de adres sormadan

Haydi

Kendinle söyleşmeyi bırak da

Yakınlaşan

Ayak seslerine dön

Bakalım ne göreceksin

Kurt mu ceylan mı

Ceylan değil mi

Sanırım

Bekle yüreğini açsın

      Londra,20 Ekim l999







3.

Hiç durmadan

Altı saat  göz göze

On beş saat dış-içe

Yani yirmi bir saat

Artsız hesapsız borçsuz

Seviştiğimizi bilseler

Hastir çekecekler

Bırak çeksinler

Seviştik işte

Ah bir de

O ısrarlı telefon  olmasaydı

Biz de

O andan

Ayrılmak zorunda kalmasaydık

Özleyeceğim seni

Onurlu birlikteliğim

Eylül Peri’si

Tuttuğun aşk olsun

Özgürlük olsun

Kadınca bastığın her kıtanın

Şairi olayım

   Londra,9.9.1999

