INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak - Yakın', 'uzak-yakin-muharrem-aslan-ow6aw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzak

Yakının içinde büyürken

Yakın

Uzağın bukalemunudur

Sana 

Ne uzak

Ne de yakınım

Senim

Ben olduğun kadar

Londra,8 Mayıs ’99', 'Uzak Yakının içinde büyürken Yakın Uzağın bukalemunudur Sana  Ne uzak Ne de yakınım Senim Ben olduğun kadar Londra,8 Mayıs ’99...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Aslan']::text[], 8.5, '{"poet":"Muharrem Aslan","poet_slug":"muharrem-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uzak-yakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suna', 'suna-muharrem-aslan-5737v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Londra,12-13 Agustos ’98

Yalnızlık rüzgarıma nefes oldun

İki yarım ay  bir şafak

Şimdi

Hüznün iki ucu açık yol

Bırakmadığın tozlar eskidikçe

Şarap daha güzel olacak

Duyumsayabiliyor sessizliğim 

Sessizliğinin  ardını

Umut kutusunda korudukların

İzlerime dokunuyor

Varacağın kapıların anahtarı elindeyken

Her özlem ‘ U’ dönüşüne gebe

Bir zilzurna kavuşma çok ayrılık

Bir daha adres sormana gerek yok

Londra cehenneminde 

Aşk şeytanı olmak gerek

Yaktığın ateşle kavrulman için

…

Bovington,4 Eylül ’98

Burkuldum sözlerine

Bölük pörçük duyguların

Can çekişip de 

Dönüşemeyen  sancıların olsa gerek

İç fırtınan dindiğinde

Dön savrulduğun yerden

İlk öpücüğüne imge yüklediğim yerdeyim

Ten kokunu unutmam mümkün değil

…





Bovingtoni,29 Eylül ’98 (gözyaşların üzerine) 

Ayrılıklarımız 

Saat gibi dilimliyor gerçeğimizi

Oysa

Zamanı yaratan saat değil

Aynı evrenin  yangını içindeyken

Bir fırsat daha vermeliyim

Şekerpare öpüşmelere

…

Swanage, Ekim ’98

Her şey

İç güzelliğin

Hak ettiğin kadar olsun

En güzel yerlerinden  öperim

…

Londra,15  Kasım ‘ 98

Aşkla alışkanlık arasında

Zehirli

İnce bir yüzey varken

Sen aşkı dinamitledin

Ben arta kalan alışkanlığı

Şimdi

Yıkıntının olası yerinde ayaktayız

Zehirlenmedik

Çevremizi zehirlemedik

Gülümseyelim

Direnen yönümüzle yenilenmiş

Uzun soluklu dostluğa

…', 'Londra,12-13 Agustos ’98 Yalnızlık rüzgarıma nefes oldun İki yarım ay  bir şafak Şimdi Hüznün iki ucu açık yol Bırakmadığın tozlar eskidikçe...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Aslan']::text[], 8.5, '{"poet":"Muharrem Aslan","poet_slug":"muharrem-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/suna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-bilgehan-acar-nu6ko', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimde her anımızın izi kalmış, 

İzi kalmış gözyaşımın yanaklarımda.

Gururum beni benden almış, 

Almış gözlerin ruhumu, 

Ruhum senin dudaklarında. 

Senin sevgini çok özledim, 

Özlemek bana suçluluk hissettirse de, 

Seni deliler gibi özledim, 

Dünyanın en suçlu insanı gibi titretse de.

Bizim aşkımız hatıra olamaz asla! 

Biz hatıra olmalıyız bu aşkta! 

O da ancak ölümle mümkün, 

Ben inan ölürüm senin uğruna.', 'Yüreğimde her anımızın izi kalmış,  İzi kalmış gözyaşımın yanaklarımda. Gururum beni benden almış,  Almış gözlerin ruhumu,  Ruhum senin duda...', ARRAY['Türk Edebiyatı','Şiir','Bilgehan Acar']::text[], 8.5, '{"poet":"Bilgehan Acar","poet_slug":"bilgehan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozledim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzzam Tadında', 'huzzam-tadinda-ali-gencay-awjzy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hüznümün doruğa ulaştığı

yalnızlık duygularımın depreştiği

ve dilimin lanet kustuğu

günün daha ışıma noktasındayım

şehrin ışıkları var uzaklarda

her kıpraşan ışık huzmesinde

bir ritim var hüzzam tadında

aydınlanmasın diye gecem

gözlerimi kapatıyorum

nafile..

güneş sokak lambaları ile anlaşmada

biri yumuyor gözlerini 

diğeri uyuyor ona

ve o lanetli şehrime

gün doğuyor

sıyrılıp 

kara gecenin içinden

yeni den kutsuyor 

sanki yeni doğan sabicesine

hüzün bulutları sarıyor etrafını

sonra sıyrılıp kurtuluyor

kuşatmayı yaracasına

inat mı bu..

hayır diyor kalbim düşün! 

eğer ki..

hüznün yaşatsaydı geceyi

ya da lanetin ile yıksaydın  şehri

yaşanır mıydı hayat tekrar 

hüzzam tadın da...?', 'hüznümün doruğa ulaştığı yalnızlık duygularımın depreştiği ve dilimin lanet kustuğu günün daha ışıma noktasındayım şehrin ışıkları var uzakl...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/huzzam-tadinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-ali-gencay-pxwed', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'adın sonbahardı

hatırlıyorum da 

her mevsim değişen

tadın vardı mısralarında 

her sevda sonu dökülü verirlerdi 

hüzzam tadında sari yaprakların 

hatırlıyorum seni 

o hiyabanda

her şeyi ardında bırakıp terk ederken 

sevdalarınla 

o sari mekanları 

unutma... 

bu yaşanan 

son sonbahar değil 

son değil bu acılar 

terk etsen de ardına bakmadan 

terk etmez o sarı odaların 

ki... gönlü insanin 

rahmidir sevdaların 

her sonunda sonbaharın  yeşerir, 

yeniden yorumlar sevdayı yeniden 

yudumlar hayati 

sanma ki kök saldığı bu yeni mekan

yaşatmaz sonbaharı 

iste o zaman 

yeniden terk edersin o sari odaları 

farklı bu 

yasamak adına yaşanan

hayat değil 

hayellerdir... 

farklı bu 

sevmek adına sevilen 

sevgililer değil duygulardır...

farklı bu 

her sararıp dökülen yaprakta 

kaybolan sevdalar 

değil mekanlardır..... 

SONBAHAR a.gençay', 'adın sonbahardı hatırlıyorum da  her mevsim değişen tadın vardı mısralarında  her sevda sonu dökülü verirlerdi  hüzzam tadında sari yaprakla...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sonbahar-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Türküsü', 'yalnizlik-turkusu-ali-gencay-zhas9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dilimde yalnızlık türküsü

elimde kırık mı kırık bir kalem

yalnızlığı yazıyorum

yaşanan ardından acılar bırakan

yalnızlığı yazıyorum

ilahi bir sıfat tanrıya ait

yalnızlık

kelimelerimin yetişemediği

tarifsiz bir acı

yalnızlık

kimi zaman eş tutarsın kendine

şehrin en kalabalık yerinde

o sogukdan demir heykeli

kimi zaman eş tutarsın kendine

anlaşılamaz mantıkla

görünmez olan çizgi filim

kahramanlarını

yalnızken 

hiç bir şeyin

anlamını taşımadığını

hiç bir şeyin

sana ait olmadığını

ve hiç bir şeyin

onu tamamlamadığını

anlarsın 

yalnızken', 'dilimde yalnızlık türküsü elimde kırık mı kırık bir kalem yalnızlığı yazıyorum yaşanan ardından acılar bırakan yalnızlığı yazıyorum ilahi bi...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalnizlik-turkusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-nilgun-marmara-gdalf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çok yalnızım, mutsuzum

göründüğüm gibi degilim aslında

karanlıklarda kaybolmuşum

...bir ışık arıyorum, bir umut arıyorum uzun zamandır

aradıkça batıyorum karanlik kuyulara

kimse duymuyor çığlıklarımı

duyan aldırış etmiyor çekip kurtarmak istemiyor

bense insanların bu ilgisizligi karşısında ilgiye susamışım

ümidimi yitirmişim

biliyorum bir gün dayanamayacak küçük kalbim

arkamı dönüp inandığım ve güvendiğim herşeye

veda edeceğim

"en yakın yabancı sendin,

daha sürülmemişken ışığın biberi

yaramıza,

yaslanırken boşlukta duran bir merdivene

henüz.

...

güzdü sonsuz bir çöle takılan bakışımız,

ilkyaz derken -kışı gözden kaçıran

yüzlerce eller yukarı, saygı duruşlarımız

en güçsüz kollarla-

çözüldü aşkın zarif ilmeği

bulandı aynalar duruluğu.

çok gizli bir doğru gecenin toyluğunda

bilmedik çekenin yanlış bir uzaklık

olduğunu...

yabancıların en yakınıydın sen! "

ey iki adımlık yerküre

senin bütün arka bahçelerini gördüm ben!', 'çok yalnızım, mutsuzum göründüğüm gibi degilim aslında karanlıklarda kaybolmuşum ...bir ışık arıyorum, bir umut arıyorum uzun zamandır aradı...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Marmara']::text[], 8.5, '{"poet":"Nilgün Marmara","poet_slug":"nilgun-marmara","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yalnizlik-1687-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Çocukları', 'eylul-cocuklari-cem-veysel-gul-gk63f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eylül çocukları onlar.

Aşklarını yarım bırakıp gittiler.

Öğrenciliklerini yarım bıraktılar, 

Öğretmenliklerini yapamadılar, 

Hatta aşık bile olamadılar.

Eylül çocukları onlar; 

Hem özgür insan olamadılar, 

Hemde özgür ve çoğulcu bir ülke kuramadılar.

Emek düşüncesini topluma veremediler.

Daha özgür daha güzel ülkeyi kuramadılar.

Eylül çocukları onlar.

Onlar aşklarını ve umutlarını yarım bıraktılar.

Yada yarım bıraktırıldı onlara, 

Onlar 68 li, onlar 78 liler, 

Onlar eylül çocukları.

Cem Veysel Gül

16.09.2000/saat: 18.00

İstanbul/taksim.motif cafe.', 'Eylül çocukları onlar. Aşklarını yarım bırakıp gittiler. Öğrenciliklerini yarım bıraktılar,  Öğretmenliklerini yapamadılar,  Hatta aşık bile...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eylul-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek Düştü Bana', 'beklemek-dustu-bana-i-smail-ozabaci-wc16a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir cehennemi andırıyordu yokluğun 

ve gözlerimden okunuyordu sensizlik

bahar diyordum sana

bahar geldi işte yine yoksun yanımda..

bu kent tüm yılgınlığını yıktı üstüme

geceleri yürüyemez oldum caddelerinde

yalnızca yağmurlarında ıslandım seni düşleyerek

ve beklemek düştü yine 

mektuplar, şiirler gönderdim sana

anlattım durdum; 

belki seni de üzdüm bir nebze

belki seni de derdime ortak ettim

bir yurt odasına

dağlara bakan bir pencerenin aydınlığında

hani geçmiyor degil aklımdan

çekip gitsem diyorum

ama hayal kurdum o aydınlıkta

oysa sen sevmiyordun hayalleri

sana da anlatamazdım

ve ağlayamazdım da

içime attım 

belki o yüzden böyle

çatık yüzüm belki o yüzden

üzgünüm

tebessümümse yine sensin

sesini duysam, o gül resmine baksam

bir tebessüm gelir oturur yüzüme

gözlerim yıldız yıldız olur

içimde bir serinlik

bir rüzgar eser senden

kokunu getirir bana

ve sana bir ses gönderirim o rüzgarla

''seni seviyorum'' diye

ve başlarım seni düşünmeye

her pazartesi, 

salı, 

çarşamba, 

perşembe, 

cuma, 

cumartesi, 

pazar, 

ve pazartesi....', 'bir cehennemi andırıyordu yokluğun  ve gözlerimden okunuyordu sensizlik bahar diyordum sana bahar geldi işte yine yoksun yanımda.. bu kent t...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/beklemek-dustu-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evleniyormuş', 'evleniyormus-fatih-cinar-ggvqe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'saçlarım bir anda aklaştı

bu acı haberi alınca

yüreğim birden sancıdı

hayatımın aşkı evleniyormuş

onunla çok mutlu günlerim vardı

zaman onunla su gibi akardı

şimdi o günler mazide kaldı

hayatımın aşkı evleniyormuş

sanki acele edecek ne vardı

o güzel günlerden ne kar kaldı

yüreğimde sevgim nefret olup aktı 

hayatımın aşkı evleniyormuş', 'saçlarım bir anda aklaştı bu acı haberi alınca yüreğim birden sancıdı hayatımın aşkı evleniyormuş onunla çok mutlu günlerim vardı zaman onun...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/evleniyormus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Mahkum', 'i-ki-mahkum-fatih-cinar-k01d4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dışarı çıkınca benim içinde dolaş

serseri caddelerde

simitleride unutma ha

en çok neyi özledim biliyormusun

güzel kadınların güzel seslerini

benim içinde bak öyle boş boş

öyle öküz gibi güzel kadınlara

arkada deniz manzarası olursa

birde rakı

ne hoş olur ha

of ulan of sanki ben çıkacağım dışarı

dışarı çıkınca 

benim içinde yem at güvercinlere sultanahmette

otur bir çay bahçesine 

birde benim için söyle

bir sigara yak mehtaba karşı

yıldızlarıda ben say karanlık gecelerde

nankörlük edip unutma sakın

unutma oturup birlikte ağladık 

mahpusun soğuk pencerelerinde

of ulan of sanki ben çıkacağım dışarı

iyice uzattık lafı biliyormusun

sigaralar gibi körük yaptık

dertleri muhabbetleri

haydi kalk 

yarın çıkıyorsun bak

allah nasip ederse

allah nasip ederse', 'dışarı çıkınca benim içinde dolaş serseri caddelerde simitleride unutma ha en çok neyi özledim biliyormusun güzel kadınların güzel seslerini...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/iki-mahkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Durak Daha', 'bir-durak-daha-i-smail-ozabaci-2zwjb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'herkes gidipte bir başımıza kaldığımızda yaşamda, özlemle anlamlandıracagımız nice anımız olacak geride..

uzaklarda bir doğu kentinde yaşanacak benzeri bir aşk, ve

konu olacak her filme, o elini tutamayışımın kızıllığı..

buydu işte benim dramım; 

güçsüzlüğümdü aynalardaki suretim

ve ıslak sokaklarda kayboluşlarımdı, her yağmurda 

sele kapılan yüreğim..

karanlık odalarda  daha bir özlüyordum seni, o kesik, 

o sıradan

o yıldızsız gecelerde

rüyalarımda yargılanıyordum oysa

kopuk bir mahkemede

umulmaz bir sevinçle seni arıyordum..

pencereme dayadığım  yüzüm ve sana ait mahrem duygularım oldu ara sıra..

ve hep o kaybettikçe artan yenilgi duygusunu gördüm

 su birikintilerinde, 

yüzün ki aklımda

ki soluğun gülü reyhan...sonra

her volkanda patladı yüreğim, yandı

anladım seni özledim..

oysa o çok eski masalın kahramanı gibi beklemeliydim

akıp giden zaman bir treni andırıryordu, 

her durakta durduğunda yeniden başlıyordu

sana kavuşma özlemi

sonra bir durak daha, 

bir durak daha duruyordu..', 'herkes gidipte bir başımıza kaldığımızda yaşamda, özlemle anlamlandıracagımız nice anımız olacak geride.. uzaklarda bir doğu kentinde yaşana...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-durak-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gelir', 'gun-gelir-fatih-cinar-0lgfo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gün gelir

ıssız bir evde tek başına kalırsın

kadehler arkadaşın olur

duvarlarla konuşur

içer içer ağlarsın

bahçede köpekler vardır ve o kahreden sessizlik

gün gelir köpeklerle arkadaş olur

sessizliği paylaşırsın

gün gelir

yiğitlik serde dolaşırsın

bir dağ başında

aslında korkuların ser vermez ama

yinede korkarsın

ormanda rüzgara meydan okuyan ağçlar vardır

ve deli yiğitliğin

gün gelir ağaçlarla arkadaş olur

yiğitliği paylaşırsın

gün gelir

üstü yamalı bir garibanla tanışırsın

ye kürküm ye davasını unutup

ve dost bir yürek sayıp kaynaşırsın

yanında bir somun ekmek vardır ve o gariban

gün gelir bir garibanla rakadaş olup

bir somun ekmeği paylaşırsın

gün gelir

bir güzel kızı seversin

sevdan uğruna hayatını kaydırırsın

beni çok hemde çok seviyor diye kendini kandırırsın

o güzel yoktur yanında kederlerin vardır

gün gelir kederlerle arkadaş olup

bir güzel yari paylaşırsın

gün gelir

yolda bir han

yollar ve sen yolcu konaklarsın

akşam olur karanlık içine çeker seni

ve sen buğulu han pencerelerine hatıra yazarsın ismini

dört duvar arasında

suskun bir hancı vardır ve sinsi karanlık

gün gelir bir hancıyla arkadaş olup

karanlığı paylaşırsın

gün gelir

kırık dökük bir radyoda

eskilerden bir şarkı çalar dinlersin

kaybolan yıllar gelir aklına

gençliğini anarsın ararsın

yanında eski bir radyo ve inleyen nağmeler

gün gelir bir radyoyla arkadaş olup

hüzzamı paylaşırsın

gün gelir

başın annenin dizlerinde

avucundaki sevgi darbeleriyle rahatlarsın

tüm dünyayı silip aklından o an

sanki başka yerlere varırsın

yanında annen vardır ve bir avuç mutluluk

gün gelir annenle arkadaş olup

mutluluğu paylaşırsın

gün gelir

şehirlerarası bir otobüste

yoldaki çizgilere bakar

özlenmeyi özlersin

o an sinsice sabahı bekleyen gece

içine çeker seni

yanında otobüsün muavini

ve bindiğinde söylenen bilmemkaç kilometre yol vardır

gün gelir bir muavinle arkadaş olup

yolları paylaşırsın

gün gelir 

azrail kapını çalar

canlanır gözünde bir bir anılar

damla damla gözyaşı olur kat kat günahlar

ve geç gelen pişmanlık  kalbinde duraklar

baş ucunda azrail vardır

ve yanında getirdiği soğuk ölüm

gün gelir azraille arkadaş olur

fakat ölümü paylaşamassın', 'gün gelir ıssız bir evde tek başına kalırsın kadehler arkadaşın olur duvarlarla konuşur içer içer ağlarsın bahçede köpekler vardır ve o kahr...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/gun-gelir-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanizligima', 'yanizligima-seref-gunenc-souqi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yalnizlik kaderimdir 

dertler sevgilim

güller ellerindir

dikenler benim

yine birakip gitti 

beni o zalim

hayatta degil ben 

ona yenildim

kan dolar yüregim

aglar gözlerim

kapildim askina

mecnun gibiyim

dertleri kederi 

kardes bilirim

söyleyin bana 

dostlar nasil güleyim', 'yalnizlik kaderimdir  dertler sevgilim güller ellerindir dikenler benim yine birakip gitti  beni o zalim hayatta degil ben  ona yenildim kan...', ARRAY['Türk Edebiyatı','Şiir','Seref Günenç']::text[], 8.5, '{"poet":"Seref Günenç","poet_slug":"seref-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanizligima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-seref-gunenc-apbqj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni yalniz kaldigim

günlerde, dost

seni umutsuz kaldigim 

günlerde, umut

seni aç kaldigim 

günlerde, ekmek

seni susuz kaldigim

günlerde, su diye

düsünmedim

çünkü bunlarin hiçbirinin

eksikligi sarsmiyor beni

senin yoklugun kadar', 'seni yalniz kaldigim günlerde, dost seni umutsuz kaldigim  günlerde, umut seni aç kaldigim  günlerde, ekmek seni susuz kaldigim günlerde, su...', ARRAY['Türk Edebiyatı','Şiir','Seref Günenç']::text[], 8.5, '{"poet":"Seref Günenç","poet_slug":"seref-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim', 'hasretim-arslan-alp-c3t3s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cuma ve cumartesileri akşam vardiyaları

Saat 6 da başlıyor

Şu anda işe doğru yürüyorum.

Attığım her adımda

Sana olan hasretim artıyor, 

Seni özlüyorum....

12 Nisan 2002, İstanbul', 'Cuma ve cumartesileri akşam vardiyaları Saat 6 da başlıyor Şu anda işe doğru yürüyorum. Attığım her adımda Sana olan hasretim artıyor,  Seni...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hasretim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmaşık Duygular İçerisindeyim', 'karmasik-duygular-i-cerisindeyim-arslan-alp-m68hi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hava serince biraz

Üstümde hediye ettiğin takım var,

Yürüyorum eve doğru,

İstanbul’un ara sokaklarında,

Sokakta yalnız ben,

		Bir de ayak seslerim.

Karmaşık duygular içerisindeyim,

Aslında eve gitmek istemiyor canım,

Bir kaldırımın kenarında 

İçtiği şaraptan sızıp kalan,

Bir serseri  olmak istiyor canım.

İçimde yalnızlığın korkusu.

Yaşam ve ölüm arasındaki 

İnce hattı düşünüyorum.

Sonra fark ederek irkiliyorum.

Sen olmasaydın, ben neylerdim? 

Okul bahçesinin önünde 

Geç kalmış annesini bekleyen çocuğun

Gözyaşları var gözümde.

Korkuyorum...

İçli içli hıçkırıklar içindeyim

Yüreğim buruk, ellerim soğuk,

Hayalinle içimi ısıtıyorum.

18 Nisan 2002, İstanbul', 'Hava serince biraz Üstümde hediye ettiğin takım var, Yürüyorum eve doğru, İstanbul’un ara sokaklarında, Sokakta yalnız ben, 		Bir de ayak se...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/karmasik-duygular-icerisindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-arslan-alp-0p6gy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum sırılsıklam, 

Seni özlüyorum çaresiz, 

Elimde bir kadeh şarap

En sevdiğin şarkıları dinliyorum

Kulaklarımda sesin tütüyor, 

Burnumda kokun.

Gözümde nedendir bilmem

En duru güzelliğin 

Kalın duvarlar arkasındaki.

Bir şeylerden kaçar gibi.

‘Sensiz olmaz’ ile başladım

‘Sensiz olmaz’ ile devam ediyorum

Her sabah sensiz uyanıyorum

Tanıdık kokular yok etrafımda

Pek anlamsız kahvaltılarım....

Bir elimde sevgim

Bir elimde gözyaşlarım

Her anımda seni arıyorum.

20 Nisan 2002, İstanbul', 'Seni seviyorum sırılsıklam,  Seni özlüyorum çaresiz,  Elimde bir kadeh şarap En sevdiğin şarkıları dinliyorum Kulaklarımda sesin tütüyor,  B...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-ariyorum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-seyhan-yilmaz-hkgrv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'diyelim ki siper başındasın

     hiç ölmeyecekmiş gibi 

          savaşacaksın

diyelim ki ölüm döşeğindesin

    bir kelebek gibi

	bir ömrü bir güne sığdıracaksın

diyelim ki ıssız bir adadasın

tüm dostların yanındaymış gibi 

     eğleneceksin

diyelim ki mahpussun 

     özgür bir martı gibi 

                düşleyeceksin umutlarını

	        hayattan hiç geri kalmadan

		zamana hiç teslim olmadan', 'diyelim ki siper başındasın      hiç ölmeyecekmiş gibi            savaşacaksın diyelim ki ölüm döşeğindesin     bir kelebek gibi 	bir ömrü b...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasamak-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü', 'turku-seyhan-yilmaz-gpvkl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir türkü dinliyorum

	gecenin ayazında

dışarısı buz kesmiş

                içim yangın yeri

bir türkü dinliyorum

	dağlarıın yamacında

dışarısı rüzgar 

                içim kasırga

bir türkü dinliyorum

	sensiz kimsesiz

tenhaydı her yer 

	içim sen dolu

bir türkü dinliyorum 

	sevda türküsü

sevda ezgili mısralarda değil

	içime işleyen sevdan

bir türkü dinliyorum

               seni anlatan

sensiz geçen günlere inat

	her mısrası sen

bir türkü dinliyorum

	elmayı anlatan

yarısı sen yarısı ben', 'bir türkü dinliyorum 	gecenin ayazında dışarısı buz kesmiş                 içim yangın yeri bir türkü dinliyorum 	dağlarıın yamacında dışarı...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/turku-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-seyhan-yilmaz-ibfw1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaşamak; 

     hissedebilmektir en güzel kokuyu, 

uçabilmektir bir kuş gibi 

      rüzgara karşı yürüyebilmek, 

        	avazın çıktığı kadar bağırmak, 

                  iskelede hiç gelmeyeceğini bildiğin, 

gemiyi beklemek, 

            	     hayalin peşinden koşabilmektir

hiç yetişmeyeceğini bilerek, 

            		      veya hayaline hayat vermektir, 

gökkuşağı renklerinin                               

      altından gecebilmektir, 

ya da

      gökkuşağı renklerini yaşamaktır, 

yaşanılmış zamandan, hiç pişman olmamaktır, 

                  her zaman kendin olabilmektir, 

            	hiç bir kılıfa girmeden yaşayabilmektir, 

yaşamak, bir çiçeği severcesine

      hiç karşılık beklemeden, 

            hiç doğmayacak bebeği 

                  umutla bekleyip, sevebilmektir

yaşamak umuttur, 

      yaşanacak en güzel günleri 

            umutla beklemektir, 

yaşamak sevmektir kara gözlüm, 

            yaşamak sevmektir', 'yaşamak;       hissedebilmektir en güzel kokuyu,  uçabilmektir bir kuş gibi        rüzgara karşı yürüyebilmek,          	avazın çıktığı kada...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yasam-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-seyhan-yilmaz-770lr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seninle kalktım güne, 

     senin gözünle gördüm dünyayı, 

         senin yüreğinde yasadım, 

senki 

     dağların yücesinde kar tanesi, 

senki 

     toprağa düşen ilk su damlası, 

filizlenen çiçeklerde senin tohumun, 

kokularını senden alıyor çiçekler, 

şairler seni yazmış tüm şiirlerinde

her yıldızda senin gözlerin, 

sen varsın söylenen her türküde, 

sen varsın hayatın her soluğunda, 

her kuşun ötüşünde sen varsın yine

her adımda sen, 

her ezgide sen

her an seni yaşıyorum, 

her yerde yine sen, 

sen sevdamsın

seninle çektim en güzel acıyı, 

seninle yaşadıklarım 

en güzeli oldu yaşamın, 

gözlerine baktığımda 

derinliğinde kayboldum, 

baharı yaşadım 

        	gül yüzün güldüğünde, 

en güzel ezgiyi duydum sesinde, 

en mutlu anları yaşadım 

      seni düşündüğümde

bilmezdim senden önce 

     gökyüzünün bu kadar mavi, 

         denizin bu kadar coşkulu, 

              yıldızların bu kadar parlak olduğunu

tohumların en güzeliydi yüreğimdeki, 

   su oldun suladın, 

        güneş oldun ışıdın, 

tomurcuk oldu tohum, 

çiçeklerin en güzeli yeşerdi yüreğimde, 

çiçek 

      umut ister, 

çiçek su ister, 

      çiçek sevda ister 

        		sürdürmek için yaşamı

su oldun, 

umut oldun

sen sevdamsın

çiçek seninle güzel 

çiçek seninle sonsuz

sevdam seninle gürleşip 

     	en güzel çiçek olacak yüreğimde

seninle coştu deniz

seninle mavi gökyüzü, 

seninle ışıldadı yıldızlar

seninle attı yüreğim, 

uyudum sen uyandım sen

sen varsın artık her soluk alışımda

bir gün öldüğümde, 

avuçlarımdaki sıcaklığınla, 

yüreğimdeki sevdanla 

sen olacaksın yine yanımda

gülerek hoş geldin diyeceğim ölüme, 

gözlerimde parıltı, 

dudağımda gülücükler olacak

ölürken yine seni yaşayacağım 

ölüme inat 

hemde sapına kadar', 'seninle kalktım güne,       senin gözünle gördüm dünyayı,           senin yüreğinde yasadım,  senki       dağların yücesinde kar tanesi,  se...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/sevdam-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül İle Bülbül', 'gul-i-le-bulbul-seyhan-yilmaz-3bpdp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün 

gördüler birbirlerini 

g ü l   ile   b ü l b ü l

ışıktan daha hızlı, 

güneşten daha sıcak bir sevdayla

tutuldular birbirlerine

            	gül ile bülbül, 

ne olmuş yani demeyin sakın, 

öyle bir sevda ki 

        	karanın en karası, 

ne varki altın bir kafesteydi bülbül, 

dışardaki bahçededeydi gül, 

ne uçabildi gülün yanına bülbül, 

ne bülbülün yanına gidebildi ayaklanıp gül, 

bülbül uçmak için özgürce güle, 

vurdu kendini altın kafesin parmaklıklarına, 

ölene kadar denedi 

         	kaçarım diye çırpınmaya, 

ölünce bülbül 

          	gömdüler onu dağların yamaçlarına

karlı dağların rüzgarındaydı mezarı, 

mezarı başında 

       	açtı en güzel kırmızı gül, 

sevdaları efsane oldu, dolaştı dilden dile

o gunden beridir  ki, 

bülbüller en güzel sevda türkülerini 

      	söyler güllere

o günden beridir ki 

     	tüm bülbüller sevdalıdır güllere', 'Birgün  gördüler birbirlerini  g ü l   ile   b ü l b ü l ışıktan daha hızlı,  güneşten daha sıcak bir sevdayla tutuldular birbirlerine      ...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gul-ile-bulbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık', 'karanlik-seyhan-yilmaz-8jccg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bilirmisin 

karanlığın ne olduğunu gözüm, 

zifri karanlığı 

bir mum ışığına hasretken

ararken ufacık bir ışık hüzmesinin 

biraralıktan süzülmesini

                ışık sızan deliklerin 

            	bir bir kapanmasını bilirmisin, 

bilirmissin yıldızla 

            ayın karanlıkla işbirliği yapmasını, 

bilirmissin karanlığın nasıl boğduğunu, 

            bir yudum ışığa hasretken, 

karanlıkta susuz kalır gibi aydınlığa, 

            hasretle ölmenin ne olduğunu, 

bende bilmezdim

karanlığın içinde yuzerken

            kendimi güneşin ortasında sanırdım

şimdi aydınlanmaya başladı karanlık

mesele karanlığı içimizde olması dostlar

içim kapkaranlıkken farketmemişim 

            çevremdeki aydınlığı meğer

şimdi aydınlığın ortasındayım, 

ateşte yanar gibi, 

güneşin sofrasındayım şimdi, 

yıldızlar karanlığın ortassında, 

karanlığı yırtarcasına 

            karanlığa inat, 

alev alev yanıyor yüreğim

karanlığı yırtan aydınlık, 

ay parçası yüzün

	yıldız pırıltısı gözlerin

		güneşten sıcak 

aydınlık yüreğin

aydınlığı seviyorum, 

geceyi yırtan aydınlığı, 

kışın ortasında yanan güneşi, 

seni seviyorum 

ayım, 

yıldızım 

güneşim

karanlığa inat 

seni seviyorum, 

çaresizliğe inat 

sende şekillenen umudu seviyorum

seni seviyorum', 'bilirmisin  karanlığın ne olduğunu gözüm,  zifri karanlığı  bir mum ışığına hasretken ararken ufacık bir ışık hüzmesinin  biraralıktan süzül...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/karanlik-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-seyhan-yilmaz-wvt4k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dostum

seni unutmak için 

silmeliyim bütün yıldızları gökten

her gün bir yıldız silsem

ömür yetmiyor inan

ve ben baştan pes etttim 

dün gökteki yıldızları saydıktan sonra

seni unutmaktan vazgeçtim', 'dostum seni unutmak için  silmeliyim bütün yıldızları gökten her gün bir yıldız silsem ömür yetmiyor inan ve ben baştan pes etttim  dün gökt...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dostum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çılgın Yüzler', 'cilgin-yuzler-seyhan-yilmaz-p1el3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tek yaşam amaçları

          bekaret bozmaktı

çok didindiler 

         sonunda becerdiler

ama hızlarını alamadılar

bu hızla gidip 

          ozonu da deldiler', 'tek yaşam amaçları           bekaret bozmaktı çok didindiler           sonunda becerdiler ama hızlarını alamadılar bu hızla gidip           ...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cilgin-yuzler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-seyhan-yilmaz-ikakf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kırsalda 

     eksik olmaz sırtından sopa

	karnından sıpa

ne çektiyse kocasından çekti

ama ne yapsın ki bir ekmeğe muhtaç

hani parayı veren düdüğü çalardı her zaman

bu yüzden sesi çıkmıyordu hiç bir zaman

ve düdük gibi çalınıyordu uzun zaman

kentlerde

      işten sonra 

	evde işleri yapar

erkek herşeyi düşünür tabi

       bir yanında erkekliği

bir elinde çiçeği

oturduğu koltuktan

dünya emekçi kadınlar gününü kutlar

dul olacak 

kocasından boşanırsa eğer

toplumda dul ile hayat kadını

	eş anlamlıymış meğer

bu yüzden dul olmak yerine

dayak yemeyi de

	gerekirse ölmeyi de seçer', 'kırsalda       eksik olmaz sırtından sopa 	karnından sıpa ne çektiyse kocasından çekti ama ne yapsın ki bir ekmeğe muhtaç hani parayı veren ...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kadin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Tutkusu', 'ozgurluk-tutkusu-seyhan-yilmaz-jbnrt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yıllanmış bir sevda bu sevgilim

zamanın ötesinde

sevda 

amansız bir coşku 

sonsuz yolculuk 

yıllanmış bir sevda bu

aynı yerde kalmışım

kaç gündür

kaç gündür

susamışım

kaç gündür acıkmışım

açlık karın açlığı değil sevgilim

susamışlıksa su değil

özgürlüğe susadım

acıkmışım insanca bir yaşama

susamışım

yaşamın yaşam olduğu bir ülkeye

acıkmışım

dünyanın kardeşçe özgür olmasına

doymak için yatmışım ölüme 

ölüm getirecek bana

düşlediğim mavilikleri

         düşlediğim özgürlüğü', 'yıllanmış bir sevda bu sevgilim zamanın ötesinde sevda  amansız bir coşku  sonsuz yolculuk  yıllanmış bir sevda bu aynı yerde kalmışım kaç g...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ozgurluk-tutkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sevdam', 'sen-sevdam-seyhan-yilmaz-lj7og', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sabah kalktığımda 

güneşte senin sıcaklığın

gökyüzünde senin göz rengin

gecemde yıldızlarda senin gözlerin

okuduğum her kitapta yine sen

şiirlerde sen 

türkülerimizde senin sesin

sanki tüm şaiirler seni yazmış

tüm yazarlar seni anlatmış

tüm müzisyenler 

senin sesinden aldıkları notayla 

       bestelemiş türkülerini

sen sen sen

hayatın her soluğunda sen

ben seni yaşar seni solurum

sağır oldum 

           sesini duyamadım

bir buket kır çiçeği gibi 

           dalga dalga saçlarını 

           		deremedim

gökyüzündeki yıldızlar gibi

           pırıl pırıl gözlerini göremedim

en güzel renkler gibi

        	gökkuşağı duygularını

        		hissedemedim

cennet meyvessi gibi

         	al dudaklarını 

         		tadamadım

kadife misali

         	yumuşak tenine 

         		dokunamadım

yuzyılların açlığı gibi

dilim tutuldu gibi

en güzel sözü sana 

        	diyemedim

en güzeli canım 

        	hiç bir şeyine 

        		doyamadım', 'sabah kalktığımda  güneşte senin sıcaklığın gökyüzünde senin göz rengin gecemde yıldızlarda senin gözlerin okuduğum her kitapta yine sen şii...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sen-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saflık', 'saflik-seyhan-yilmaz-6gwnw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ya çiçek olacaksın

rengi keskin 

kokusu saf

dimdik

yada

çiçek olacaksın

solgun

hangi renkte olduğu belirsiz

ve çürümüş bir koku

sence hangisi güzel

ama

güzel çiçek hep koparılmaya çalışılır

kötü bir çiçek ise 

diğer kötülerin arasında

            	kimsenin dikkatini çekmeden çürür

ya denize gireceksin 

yada denizden uzak kalacaksın

kumsalda dolaşmakta neymiş

bir yanın

denize girmek ister

bir yanın da boğulmaktan korkar

boğulursan boğul be

hiç olmazsa

sevdiğin bir şeyi yaparken 

        boğulursun

sevdiğin şeyleri yapmadan ölmekten 

daha mutlu ve daha güzel', 'ya çiçek olacaksın rengi keskin  kokusu saf dimdik yada çiçek olacaksın solgun hangi renkte olduğu belirsiz ve çürümüş bir koku sence hangis...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/saflik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durak', 'durak-seyhan-yilmaz-qo27c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni bekledim 

    kaç yıl oldu 

       sayamadım

kaç bahar kaç kış

ama inan sevgilim

bahar sensiz kara kış

kış sensiz cehennem

davam yaşamaksa eğer 

ben seninle yaşamak isterim

yaşam sensiz yaşamsa eğer 

bu acıya dayanamam 

ölmek isterim', 'seni bekledim      kaç yıl oldu         sayamadım kaç bahar kaç kış ama inan sevgilim bahar sensiz kara kış kış sensiz cehennem davam yaşama...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/durak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın İçinde Sevda', 'zamanin-i-cinde-sevda-seyhan-yilmaz-59vg3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'mevsimlerden sonbahar

her yan ölüm sarısı

beni bırakma çalmasın yüreğime 

          	zülmün karası

mevsimlerden zemheri

her  yan boran, kar

ya oldur beni ya yüreğinle sar

mevsimlerden ilkbahar

her yan çiçek ve kuş cıvıltısı

gel 

         	yüreğime ol yıldız pırıltısı

mevsimlerden yaz

her yan gökyüzü ve deniz

al kalemi sevdamı yüreğine diz

günlerden pazar

       	sevdama yasak koysan ne yazar

günlerden pazartesi 

            gel koynuma gir gönlümün perisi

günlerden salı 

            gel de yaslan sevdama 

            	aramıza girmeden kara çalı

günlerden çarşamba

            sevdalıyım ne anne dinlerim ne baba

günlerden perşembe

            günler sevdama gebe

günlerden cuma

            ömür boyu  ne beni ne sevdamı unutma

günlerden cumartesi 

            senden ayrılamam 

            	varırım sana kırarak çelik kafesi', 'mevsimlerden sonbahar her yan ölüm sarısı beni bırakma çalmasın yüreğime            	zülmün karası mevsimlerden zemheri her  yan boran, kar ...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/zamanin-icinde-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-seyhan-yilmaz-g4b6n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hayatın kendisiysem ben, 

            mutluluğu sen

gökyüzüysem ben, 

            yıldızla ayım sen

kuşsam ben, 

            kanatlarım sen

gökkuşağıysam ben, 

            renklerim sen

bir bedensem sadece ben, 

            canı sen

bir uçsuz denizsem ben, 

            mavisi sen

seni kitaplara yazsam 

            dünyadaki kağıtlar yetmez

senin her güzellğini bir yıldıza versem

            gökyüzündeki yıldızlar yetmez

anlatmaya kalksam sevdamın büyüklüğünü

            anlatmaya ömrüm yetmez', 'hayatın kendisiysem ben,              mutluluğu sen gökyüzüysem ben,              yıldızla ayım sen kuşsam ben,              kanatlarım sen ...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozlem-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Ezgi Sevda', 'bir-baska-ezgi-sevda-seyhan-yilmaz-4q7d3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu başka ezgi

başka bir zamanın ezgisi

ne bügünün ne yarının

bu sevda ezgisi

başka bir zamandan gelen

bilinmeyen zamana giden

notasını hiç bir müzisyen çalamadı

notası sevda notası

gökkuşağı renkleri çizmiş seni

ne dünyaya ait ne başka bir yere

bilinmeyenden gelip

bilinmeyene giden

bir rengi farklı gökkuşağından 

sevdanın rengi, 

ne tarifi mümkün 

ne resme dökebilmek

seni farklı kılan

bu nota ve bu renk

notayı hiç bir müzisyen bulamadı

rengiyse hiç bir ressam çizemedi

tek yüreğin söylediği nota

tek yüreğin görebildiği renk

ne tarifi mümkün ne söylemesi

var mısın yok musun

bu da belli değil aslında

ölümle yasam arasında

öyle bir yerdesin ki 

varla yok arasında

öyle bir zamandasın ki

         	binlerce yıl öncesi

         		binlerce yıl sonrası zaman

bilemedim sevdam

         	var mısın yok musun

öptüm hasretle 

hasret ki kan kırmızısı

sevda ki gökyüzü mavisi

sen düşünce aklıma 

gökkuşağını çizerim her gün', 'bu başka ezgi başka bir zamanın ezgisi ne bügünün ne yarının bu sevda ezgisi başka bir zamandan gelen bilinmeyen zamana giden notasını hiç b...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bir-baska-ezgi-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkülerimiz', 'turkulerimiz-seyhan-yilmaz-dsbdb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'türkülerimiz türkülerimiz

türkülerimiz yosmanın süt sağışını söyler

mehmetin aşkı

ya da 

sevdalıların ayrılığını 

asinin 

diclenin 

fıratın sevdaları ayırmasını 

türkülerimiz türkülerimiz

ayrılık ezgileri içeren 

yada sevda ezgileri

denizlerin fırtınalarını içeren

doğasını ülkenin

kardeşliğini halklarımızın

türkülerimiz türkülerimiz

gözyaşıyla yoğrulan

hamuru sevda olan

suyu özlem türkülerimiz

türkülerimiz türkülerimiz

saf katıksız sevda türkülerimiz

sudan temiz 

gökkuşağından renkli

bahardan güzel kokan

işte türkülerimiz 

sevda hasret ve yaşam

yaşamın ta kendisi türkülerimiz

işte bizim türkülerimiz', 'türkülerimiz türkülerimiz türkülerimiz yosmanın süt sağışını söyler mehmetin aşkı ya da  sevdalıların ayrılığını  asinin  diclenin  fıratın ...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/turkulerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Kayboldum', 'gozlerinde-kayboldum-seyhan-yilmaz-ipwcm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ellerim ellerinde

kaybolan gözlerim 

yolunu aramakta gözlerinde

bir sevda türküsü dilimde

hayalin beynimde

umut olan sevdansa 

yüreğimde', 'ellerim ellerinde kaybolan gözlerim  yolunu aramakta gözlerinde bir sevda türküsü dilimde hayalin beynimde umut olan sevdansa  yüreğimde...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gozlerinde-kayboldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Duraktayım', 'son-duraktayim-seyhan-yilmaz-g776s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir an geçti sensiz 

          sanki ölüm anı 

bir gün geçti sensiz

         ölüm gibi karanlık

baharlar geçti sensiz

karakış gibi soğuk

sonbahar gibi ölüm

bir tanem

bir ömür geçiyor sensiz

boş bir sayfa gibi 

hiç bir anı yaşanmamış', 'bir an geçti sensiz            sanki ölüm anı  bir gün geçti sensiz          ölüm gibi karanlık baharlar geçti sensiz karakış gibi soğuk son...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-duraktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan', 'vatan-seyhan-yilmaz-tdkk4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'rüyamda görürüm seni 

dokunsalar donarım

gözlerimde dolusun 

dokunsalar akacak gözyaşım

yüreğimde dolusun

dokunsalar kanayacak

sevdanla doluyum 

bitirseler sevdanı

hayat son bulacak', 'rüyamda görürüm seni  dokunsalar donarım gözlerimde dolusun  dokunsalar akacak gözyaşım yüreğimde dolusun dokunsalar kanayacak sevdanla dolu...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vatan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoldaş', 'yoldas-seyhan-yilmaz-n47wo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'birgün öldüğümü 

          	duyarsan eğer

bil ki sensizlikten ölmüşüm, 

birgün umudun tukendiğini 

düşünürsen eğer

bil ki umudum senindir, 

birgün karanlıkta kaldığını 

düşünürsen eğer

al yüreğimi 

güneşin olsun', 'birgün öldüğümü            	duyarsan eğer bil ki sensizlikten ölmüşüm,  birgün umudun tukendiğini  düşünürsen eğer bil ki umudum senindir,  ...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yoldas-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-seyhan-yilmaz-dgkbx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şiir bazen gül olur

derilip sevgiliye verilir

şiir bazen ağıt olur

ayrılıkta yakılır

şiir bazen türkü olur

sevdalara umut dokur

şiir bazen kurşun olur

zulme sıkılır', 'şiir bazen gül olur derilip sevgiliye verilir şiir bazen ağıt olur ayrılıkta yakılır şiir bazen türkü olur sevdalara umut dokur şiir bazen k...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siir-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Elma', 'yasak-elma-seyhan-yilmaz-44llz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni görmek istiyorum, 

            göremem

seni duymak istiyorum, 

            duyamam

seni koklamak istiyorum, 

            koklayamam

seni düşünmek istiyorum, 

            düşünemem

sana dokunmak istiyorum, 

            dokunamam

seni yaşamak istiyorum, 

            yaşayamam

seni öpmek istiyorum, 

            öpemem

çünkü sen, 

sürekli peşinden koştuğum, 

yaklaştikca uzaklaşan

            hayalimsin, 

senin gözyaşın, 

            göz pınarlarından akan, 

senin düşüncen, 

            beyninde şekillenen, 

senin kokun, 

            sürekli bedeninle taşıdığın

ve sevdamla süren 

yaşamın olmak istiyorum, 

ama olamam, 

çünkü sen benim içimde yaşattığım

Y A S A K    E L M A M S I N!', 'seni görmek istiyorum,              göremem seni duymak istiyorum,              duyamam seni koklamak istiyorum,              koklayamam sen...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yasak-elma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sen-benim', 'sen-benim-seyhan-yilmaz-3ae4i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen benim denizim, 

ormanım 

            	akarsuyum

sen benim doğamsın

sen benim kelebeğim 

            ceylanım, 

                        martım

sen benim yaşamımsın

sen benim yıldızım, 

            güneşim, 

            	gökyüzüm

sen benim umudumsun

sen benim kırmızım, 

            yeşilim, 

            	mavim

sen benim hayat rengimsin

sen benim aşım, 

            ekmeğim, 

            	suyum 

sen benim hayat nedenimsin

sen benim kanım, 

            yüreğim

            	akciğerim

sen benim bedenimsin

senki benim düşüncem, 

            hissettiğim, 

            	gördüğüm

sen benim beynimsin

senki benim hayatımda

            yaşam kadar gerçek 

senki 

benim hayatımda düş kadar hayalsin

ama senki benim sevdam 

ve yaşama sevincimsin', 'sen benim denizim,  ormanım              	akarsuyum sen benim doğamsın sen benim kelebeğim              ceylanım,                          m...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sen-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyeyim Diye', 'sevmeyeyim-diye-ozgur-kizilkaya-hdklp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlık sokaklara çığlıklar savurdum 

Yankılarını sakladım ceplerimde 

Tüm ateşini sulara gömdüm aşkımın

Ve bir kalp öldürdüm benliğimde 

Sırf seni sevmeyeyim diye', 'Karanlık sokaklara çığlıklar savurdum  Yankılarını sakladım ceplerimde  Tüm ateşini sulara gömdüm aşkımın Ve bir kalp öldürdüm benliğimde  S...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kızılkaya']::text[], 8.5, '{"poet":"Özgür Kızılkaya","poet_slug":"ozgur-kizilkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevmeyeyim-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martiya', 'martiya-seyhan-yilmaz-zq6er', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir yanım deniz 

            engin ve masmavi 

bir yanım kasırga

bir yanim berrak akarsu

            tertemiz

bir yanım lağım

bir yanım orman 

            yeşil ve sessiz

bir yanım fırtına

bir yanım hayat dolu 

            bir yanım ölü

bir yanım hayal

            bir yanım gerçek

bir yanım umut

            bir yanım yorgunluk

bir yanım mutluluk 

            bir yanım keder

bir yanımda özgürlük

            bir yanımda hücrem

bir yanım özgürlüğe

            ve sonsuz maviliğe uçan bir MARTI

            	bir yanım zindan

bir yanım aydınlık 

            bir yanım karanlık ve zulüm

BİR YANIMDA SEN 

                              BİR YANIMDA BEN', 'bir yanım deniz              engin ve masmavi  bir yanım kasırga bir yanim berrak akarsu             tertemiz bir yanım lağım bir yanım orma...', ARRAY['Türk Edebiyatı','Şiir','seyhan YILMAZ']::text[], 8.5, '{"poet":"seyhan YILMAZ","poet_slug":"seyhan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/martiya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderimin Oyunu', 'kaderimin-oyunu-orhan-gencebay-6flzh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne sevenim var, Ne soranım var

Öyle yalnızım ki

Çilesiz günüm yok, dert ararsan çok

Öyle dertliyim ki

Bana kaderimin bir oyunumu bu

Aldı sevdiğimi verdi zulümu

Dünyaya doymadan geçip gideceğim 

Yoksa yaşamanın kanunumu bu

Bıktım artık yaşamaktan

Çekmekle bitermi bu hayat yolu ah...

Bu yalnızlık, bu dertler

Bekleyeceğim, bekleyeceğim

Geri dönmese bile

Alıştım karderin zulumüne artık

Bana gülmese bile 

Geri dönmez artık giden sevgililer

Her ümit uğrunda ağlıyor gözler

Bitmeyen çilenin, derdin sarhoşuyum

Kahredip geçiyor en güzel günler', 'Ne sevenim var, Ne soranım var Öyle yalnızım ki Çilesiz günüm yok, dert ararsan çok Öyle dertliyim ki Bana kaderimin bir oyunumu bu Aldı sev...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kaderimin-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonu Olmayan Bir Sevda Bu', 'sonu-olmayan-bir-sevda-bu-yusuf-kaya-j54ql', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonu olmayan bir sevda''ya tutuldum, 

Bir başkasını kalbime yazamaz oldum. 

Senin ismini haykırdım, 

Gündüzleri güneşe, bulutlara 

gökyüzünün maviliğine

Sonu olmayan bir sevdaya tutuldum 

Sabahları seher rüzgarında aradım seni, 

Geceleri karanlık sokaklarda. 

Seni düşündüğümde, 

ruhumda hissettim sıcaklığını, 

tenimde hissettim bedenini', 'Sonu olmayan bir sevda''ya tutuldum,  Bir başkasını kalbime yazamaz oldum.  Senin ismini haykırdım,  Gündüzleri güneşe, bulutlara  gökyüzünün...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sonu-olmayan-bir-sevda-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeyin Hakkınız', 'yeyin-hakkiniz-i-lhan-yuksel-s47ug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boşaltın içini bu günlük istihakınız 

Kaldi millet bir deri varsa iştiyakınız 

Atıştırın bu fırsat sonra açız dersiniz 

Soyun bu yağma sizin nesil boyu yersiniz 

Uyuttunuz millet uyanmaz bin yıl uyanmaz 

Bin yıl uyuklayan şu bizden bir kıl uyanmaz 

Portup kaçar gümrük açık beynelmilelsiniz 

En son evrakınız gelir önce siz gidersiniz 

Ne hoş şu aheng sizin basın para pul sizin 

Bu vurgun bu yağma sizin o çapul sizin 

Yeraltında bu milleti gizli güdersiniz 

Kiminiz cıfıt kiminiz mason pedersiniz 

Beyler helal pıskırmayın helal şu sütümüz 

Yeyin etimiz binin ağır olsa yükümüz 

Semiz semiz göbeklenir yeyip şişersiniz 

Soyun hakkınızı bin deve yükü yersin', 'Boşaltın içini bu günlük istihakınız  Kaldi millet bir deri varsa iştiyakınız  Atıştırın bu fırsat sonra açız dersiniz  Soyun bu yağma sizin...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeyin-hakkiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Ölüm, Çocuk Ölüm', 'baba-olum-cocuk-olum-sukru-ozmen-mhybp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Su çağıltıda, 

Gönül melalde...

Kimbilir hangi diyarda

Kaç derece ateşle 

Kaç çocuk ölür.

Bilinir bazı yerlerde 

Çocuklara ateş edildiği de.

Elleri karıncalanır bir militanın

Epeydir tetik çekmemiş

Parmakları kaşınır

Gökyüzüne bir su berraklığı ile

Bakabilmektir, der dedesi çocuğa...

Yinede apoletsiz bir hayatı seçemez

Marifetsiz çocuklar.

Ve yine su çağıldar

Ve yine gönle melal dolar

Ve yine karıncalanır

Militanın parmağı

Ama hayat

Bir su berraklığıyla

Bakar gökyüzüne

Gelinciklerin arasında

Bir gelincik gezinir

Harareti alınmış bir çocuğun

Gönlüne dirlik

Ruhuna ferahlık

Kalbine ipekler salar.

Boşver hayat bir gemi

Yürüt onu diyen şairin

Hayatını yürütür 

Gece zebanileri

Dolu alıp boş verirler

Sarardı gökyüzüne bakan adam

Gözlerine kıraç tarlalar gibi

Ve gözlerine gök ekinler kadar

Güvenirdi çünkü

Bu hiç bir şey mağarası gök

Şu her şey denizi gök

Ateşini hangisi düşürecek 

Bu ağlayan çocuğun? ...', 'Su çağıltıda,  Gönül melalde... Kimbilir hangi diyarda Kaç derece ateşle  Kaç çocuk ölür. Bilinir bazı yerlerde  Çocuklara ateş edildiği de....', ARRAY['Türk Edebiyatı','Şiir','Şükrü Özmen']::text[], 8.5, '{"poet":"Şükrü Özmen","poet_slug":"sukru-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/baba-olum-cocuk-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Yazmaları', 'el-yazmalari-yavuz-basak-xkyk4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Esnektir yalnızlığın baygınlığı 

ulu orta karanlık çağrılır şimdi

Yırtılası bir şilte göstermez gecenin nefesini

ikiye durur bir göz

yarım atımlık kurşun dökülür kem gözlere

açıl desen güneşin soluğuna

bir bulutla düşer ellere ince bir mısra

ince bir mısra arıyorum şimdilik

içinde esans kokusu olan

unutmuşuz çoktan sayı saymayı

sayılmak bizim işimiz

alnımızda kışın bekareti

erimek için yağmur yemeliymişiz

Çıplak bir ayakla toprağa basmak

postalları sabahla boyanmış adama yakışmaz

geçmez burdan süslü cümleler

bir duruş bozar kitapların arasında ne varsa

ne yoksa... anlarız

Gel ve geç törpülenmiş yanımdan

asık bir yüzle cilalanmış adımı söyle

ya da sus

bil ki pahalı gözler görmeyecektir

çünkü tutulmaz suyun açtığı kapı

tutarsan; bir damlaya bir parçanı

salacaksın demektir.', 'Esnektir yalnızlığın baygınlığı  ulu orta karanlık çağrılır şimdi Yırtılası bir şilte göstermez gecenin nefesini ikiye durur bir göz yarım a...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Başak']::text[], 8.5, '{"poet":"Yavuz Başak","poet_slug":"yavuz-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/el-yazmalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nenni Bebek Oy', 'nenni-bebek-oy-edip-cangonul-qh9ey', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu dağlarda kar olsaydım

Yüzümü güneşe çalardım

Erirdim

Su olur akmazdım

Ve yine yalvar yakar...

Güneşe yüz sürerdim, 

Buhar olur, bulut olurdum

Yağmura döner yağardım

Bir evin çatısına

Bir yerlerde

Her düşmem bir ninni olurdu

Uyurdun

Ama gülüm

Ez gurbaney

Ne kar olabildim

         Bir sokak lambası sarılığında

Ne yağmurluğu becerebildim

         Şıpır şıpır

“Nenni bebek oyy”', 'Şu dağlarda kar olsaydım Yüzümü güneşe çalardım Erirdim Su olur akmazdım Ve yine yalvar yakar... Güneşe yüz sürerdim,  Buhar olur, bulut olu...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/nenni-bebek-oy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '“Yüksek Minarede Kandiller Yanar” türküsü üstüne', 'yuksek-minarede-kandiller-yanar-turkusu-ustune-edip-cangonul-nu2ng', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekleyeceksin

Şavkını kandilin

Yüksek bir minarede

Sanki vurunca şavkı

Vuslata ereceksin

Minare olmayacak ama

Yazı da, yaban da olmayacak

Şavkı da minarenin

Sen olacaksın

Birde yazı 

ve şiir

Yazacaksın

Kör gibi

Okumasan da

Bileceksin

Okuyacaklar', 'Bekleyeceksin Şavkını kandilin Yüksek bir minarede Sanki vurunca şavkı Vuslata ereceksin Minare olmayacak ama Yazı da, yaban da olmayacak Şa...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuksek-minarede-kandiller-yanar-turkusu-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'He Gülüm', 'he-gulum-edip-cangonul-sg0um', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'He gülüm

Dağ başında bir yüreğidim

            Ürkek

            Kartalın zulmünü bilir

Eridim

            Yağan yağmur düşman

            Doğan güneş hayın

He gurban

Ez kurbane 

Ben yanmışım kime ne

           Su söndürmez

           Merhem tutmaz yaralarım

Bir uzunhava ile sevdalanmışım, 

           Yanık.

 Mamoşum, Harput’ta

           Kizirin oğlu', 'He gülüm Dağ başında bir yüreğidim             Ürkek             Kartalın zulmünü bilir Eridim             Yağan yağmur düşman             D...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/he-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burada Ölmek Var', 'burada-olmek-var-ugur-sari-hapiu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Burada gece olur

Ama bir karanlık çöker üstüme

Burada hayınlık

Burada intikam

Burada intihar

Burada küfürler bağlaç olur

Anlamsız cümlelere

Burada sözcükler prangalı

Kalpler yama üstüne yamalı

Gönüllerde haç var

Hem de çifte gamalı

Burada sevmek parayla

Burada hayınlık sırayla

Diller sus pus olur

Gönüller taş olur

Burada türküler küfür makamında

Yıldızlar sönük

Burada güneşi çamurla sıvamışlar

Hakikati dar ağacına asmışlar

Burada bütün yalanlar baş tacı

Burada lokmalar daha bir acı 

Anne bari sen söyle

Kim doğru kim yalancı

Anne ben buradayım

Sen yoksun ya

Ben yine buradayım

Belki şimdi 



Belki yarın

Belki seneye

Bil ki ben de mutlaka oradayım

Anne burada ölmek var

Dualarda sevgiliye dönmek var

Burada yaprak ölür

Ağaç ölür

Kuş ölür

Oğul, oğul, oğul

Oğul ölür', 'Burada gece olur Ama bir karanlık çöker üstüme Burada hayınlık Burada intikam Burada intihar Burada küfürler bağlaç olur Anlamsız cümlelere ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Sarı']::text[], 8.5, '{"poet":"Uğur Sarı","poet_slug":"ugur-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/burada-olmek-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasemen Diyemedim', 'yasemen-diyemedim-ugur-sari-e2wki', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adını küflü paslı harflerle kazıdım

Gönlümün en temiz yerine

Geceler boyu dua ettim

Yüreğim kangren olsun da

Benden söküp alsınlar dedim

Bitmek tükenmek bilmeyen kâbuslarda

Adını ezberledim

Adınla uyudum

Adınla uyandım

Sana benzettiğim herkese

Adınla hitap ettim de

Bir sana diyemedim

Adını her yağan yağmur sonrası

Penceremin buğulu camlarına yazdım

Sonra karaladım

Bir daha

Bir daha yazdım

Adına şiirler yazdım

Adına ağıtlar yaktım

Adını dipsiz kuyuya atar gibi

Attım yüreğimin en derin yerine

Sana benzettiğim herkese

Adınla hitap ettim de

Bir sana Yasemen diyemedim', 'Adını küflü paslı harflerle kazıdım Gönlümün en temiz yerine Geceler boyu dua ettim Yüreğim kangren olsun da Benden söküp alsınlar dedim Bit...', ARRAY['Türk Edebiyatı','Şiir','Uğur Sarı']::text[], 8.5, '{"poet":"Uğur Sarı","poet_slug":"ugur-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yasemen-diyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit Alevinde', 'kibrit-alevinde-ugur-sari-howx2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kahvehanedeyim

Kuytu ve soğuk

Yüreğimde hırıltılı bir ses

Ve biraz da boğuk

Önümde zengin bir iftariyelik

Bir paket sigara

Beklemiş bir bardak çay

Ve biraz da peynir

Sana naz makamında

Şiirler biriktiriyorum

Radyoda kederli şarkılar

Ve ağlıyorum

Dört duvar hücum ediyor üzerime

Sanki dizlerim felçli

Sanki eziliyor

Sanki kaçamıyorum

Sen olmasan da

Sen bilmesen de

Hani sen bu hakkı vermesen de

Belki de ilk defa

Sevmek hakkımı kullanıyorum

Derken bir kibrit yakıyorum

Hani biraz soğuğa 

Hani birazda umuda

Yaktığım kibritle ısınmıyor ellerim

Umutlar biraz daha devrik

Hayaller biraz daha yenik

Derken kalem de düşüyor ellerimden

Zaten kibritte söndü yani', 'Bir kahvehanedeyim Kuytu ve soğuk Yüreğimde hırıltılı bir ses Ve biraz da boğuk Önümde zengin bir iftariyelik Bir paket sigara Beklemiş bir ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Sarı']::text[], 8.5, '{"poet":"Uğur Sarı","poet_slug":"ugur-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kibrit-alevinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sevdim', 'ben-sevdim-ugur-sari-uotpw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden en çok kışı sevdim

Saflığı hatırlattığı için beyazı

Rengi beyaz olduğu için karı daha çok sevdim

Eskiden insanları severdim

Şimdi yalnız, adamları

Nedendir bilmiyorum

Hüzünlü şarkıları

Daha çok sevdim

Çiçeklerden kardeleni

Zemheride ana kucağını

Ayrılık vakti çatınca 

Karanlık ve soğuk odamı daha çok sevdim

Yokluğunda beğenmediğim

Kuru ekmek ve acı soğanı

Çok, daha çok sevdim

Gurbette geride bıraktığım

Her şeyi sevdim

Bana bir kez olsun

Sevdiğini söylemeyen

Babamı bile sevdim

Gurbette gece yarısı

Sigara izmariti toplamayı sevdim

Her parasız kalışımda

Ağlamayı sevdim

Kuytu bir karanlıkta

Geceleyin penceresinde sevdiğimin

Bana el sallayan hayalini sevdim

Her şeyi sevdim de

Parayı bir türlü sevemedim

Aslında beyazı hiç sevmemiştim

Çünkü beyaz diye bir şey yoktu

Ya da beyaz eskiden beyazdı

Oysaki ben hiçbir şeyi de sevmemiştim

Sevdiğim aynada koca bir yalan

Ya da karanlık odamın penceresinde ürettiğim

Anlamsız bir hayalden ibaretti', 'Mevsimlerden en çok kışı sevdim Saflığı hatırlattığı için beyazı Rengi beyaz olduğu için karı daha çok sevdim Eskiden insanları severdim Şim...', ARRAY['Türk Edebiyatı','Şiir','Uğur Sarı']::text[], 8.5, '{"poet":"Uğur Sarı","poet_slug":"ugur-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ben-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey Var', 'bir-sey-var-ugur-sari-gdpd5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şey var dilimin ucunda

Sanki biliyorum

Var bir şey var dilimin ucunda

Ama söyleyemiyorum

Sara nöbetlerim tutuyor

Kuduruyorum,

Ölüyorum

Ve haykırıyorum

Seni seviyorum

Hayır hayır

Ama bu değil

Başka bir şey var dilimin ucunda

Çok yabancı değil

Çok uzak değil

Biliyorum

Bir şey var dilimin ucunda

Sözlüğe bakıyorum

Karıştırıyorum karıştırıyorum

Bulamıyorum, 

Kafamı taşlara vuruyorum

Hayır hayır

Bu benim suçum değil

Bu senin de suçun değil biliyorum

Bir şey var dilimin ucunda

Biraz kopuk

Biraz anlamsız

Her bakışımda yıldırımlara çarpılıyorum

Ama korkmuyorum

Bir daha 

Bir daha bakıyorum

Bir şey var dilimin ucunda

Adını koyamıyorum

İfade edemiyorum

Heceler çok basit

Cümleler çok yalın

Elimden tut korkuyorum

Hayır hayır

Dokunma! ! !

Bir gören olur

Bari sen söyle ne olur

Bir şey var dilimin ucunda

Bir şey var

Şizofren gecelerimde

Hatırlayamadığım

Sen yani ikinci tarafım

Yani anlam veremediğim

Hani şekerle tuzu karıştırıp

Yemek gibi

Hani ağlarken

Gülmek gibi

Hani vururken

Okşamak gibi

Ateşin içinde

Üşümek gibi

Anlamsız bir şey var

Dilimin ucunda

Bir şey var dilimin ucunda

Bir şey

Aşk gibi

Düş gibi

Sevda gibi

Bir şey var 

Bir şey', 'Bir şey var dilimin ucunda Sanki biliyorum Var bir şey var dilimin ucunda Ama söyleyemiyorum Sara nöbetlerim tutuyor Kuduruyorum, Ölüyorum V...', ARRAY['Türk Edebiyatı','Şiir','Uğur Sarı']::text[], 8.5, '{"poet":"Uğur Sarı","poet_slug":"ugur-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/bir-sey-var-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-sair-senturk-yfd6a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aylardan eylül günlerden Pazar

Beklemekteyim yer istanbul

Bir ben vardım sanki bekleyen

Ve Bir ben vardım sanki özleyen

Dedim ya günlerden Pazar yer istanbul

Zaman tükenmekte korkuyorum

Acaba zaman mıydı sadece tükenen

Yoksa ben miydim istanbul....

Ahhh  İstanbul..........

Sende,  sende aynısın

Kalabalıklar içinde 

Yalnız yürekleri bekleten

Her şehir gibisin sende özleten

Ve sevenleri hapseden

Mavi, yeşil gözlü kız; istanbul

Söylenmemiş sözlerim

Anlatamadığım duygularım kaldı sende

Sevdaların şehri istanbul

Yüreğimi bıraktım sana

Yeşilinde yeşil denizinde mavi

Hasret  gözlü bir kız bıraktım sana

Sevdamın şehri istanbul

Gülleri sevenler adına

Onu, sakla bana

Beni de almayı unutma

O mavi yeşil koynuna 

Ve ne olur bırakma 

Canım İstanbul', 'Aylardan eylül günlerden Pazar Beklemekteyim yer istanbul Bir ben vardım sanki bekleyen Ve Bir ben vardım sanki özleyen Dedim ya günlerden P...', ARRAY['Türk Edebiyatı','Şiir','Şair senturk']::text[], 8.5, '{"poet":"Şair senturk","poet_slug":"sair-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/istanbul-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızım', 'kizim-sair-senturk-ftqdd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlümün  narin çiçeği, ay yüzlü kızım

Yalnız yüreğimin sevgi tomurcuğu, gül kızım

Gece karanlığında ağlayan sesi ile

İçime su sepen can kızım

Tek mutluluğum canım, birtanem kızım

Saçları ipek, gözleri zeytin kızım

Gülüşü dünyalara, öpüşü ömrüme bedel kızım

Babam benim deyişine kurban olduğum cannnn  kızım

Seni bensiz beni sensiz 

Bırakmasın

Seni bana beni sana sevdiren 

En sevdiğimiz varlığa

Ömrümce hep niyazım

Her şey ama herşey senin için unutma

Canımmm, can kızım', 'Gönlümün  narin çiçeği, ay yüzlü kızım Yalnız yüreğimin sevgi tomurcuğu, gül kızım Gece karanlığında ağlayan sesi ile İçime su sepen can kız...', ARRAY['Türk Edebiyatı','Şiir','Şair senturk']::text[], 8.5, '{"poet":"Şair senturk","poet_slug":"sair-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kizim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-sair-senturk-znno9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu karanlık ve yalnız gecede

Yine günahların pençesinde

Ruhumu saran bir karanlık var içimde

Cehennemin sıcaklığını 

Ve ümidin tükenişini  hissettiren

Bir garip burukluk var içimde

Bin kere tövbe etsem de

Bin kere affımı istesem de

İsyankar ruhumun kara rengi var yüreğimde

Cehennemin sıcaklığını

Ve inancın tükenişini göstermeyen

Bir garip körlük var gözlerimde 

İsyan var

Yalan var

Düşüncelerimi zincire vuran

Ve beni cehenneme sürükleyen

Bir garip şeytan var içimde', 'Bu karanlık ve yalnız gecede Yine günahların pençesinde Ruhumu saran bir karanlık var içimde Cehennemin sıcaklığını  Ve ümidin tükenişini  h...', ARRAY['Türk Edebiyatı','Şiir','Şair senturk']::text[], 8.5, '{"poet":"Şair senturk","poet_slug":"sair-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/celiski-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Oluyor Bize', 'neler-oluyor-bize-i-lhan-sesen-z3ltc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İster sev ister sevme ama dön artık, 

Uyanır uyanmaz düşüncemdesin, 

Islak ekmek attığın kuşlar, alıştılar eve, 

Onlarla beraber penceremdesin, 

Ah be bitanem, nerelerdesin.

Neler oluyor bize, yine neler oluyor gülüm, 

Neler oluyor sana, bana neler oluyor.

Gittiğin günden beri, yüzüm hiç gülmedi, 

Doğum günümde bile, iyiki doğudun demedin, 

Ayrıntılara takılmak istemem ama elimde değil, 

Şimdi kim bilir kimlerdesin, ah be bitanemnerelerdesin, 

Nazlı bebeğim ne alemdesin.

Neler oluyor bize, yine neler oluyor gülüm 

Neler oluyor sana, bana neler oluyor', 'İster sev ister sevme ama dön artık,  Uyanır uyanmaz düşüncemdesin,  Islak ekmek attığın kuşlar, alıştılar eve,  Onlarla beraber penceremdes...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şeşen']::text[], 8.5, '{"poet":"İlhan Şeşen","poet_slug":"i-lhan-sesen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/neler-oluyor-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-selcuk-cusum-r1hzv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çağladım akmak istedim mavi denizlere

İsterim ömrüm geçsin, yalnız seninle

Severmisin beni derdimle, herşeyimle                         

 Girmek istiyorum artık senin gönlüne.

Üzme beni, hadi ne olur dön sevgili

Gönlüm aşkınla yanmış, yetmiyor yağmur seli

Uzattığım elimi böyle çevirme geri

Sevmek istiyorum artık seni, deli.

Gel bana derdin, kederin, günahınla

Yer etmişsin şu garibin gönül bahtında

Bekliyorum seni şu güzelim mehtapta

Bekliyorum aşıkların aşk yuvasında.

Kıskanıyorum seni yürüdüğün yollardan

Uçan kuştan, konuştuğun insanlardan

İnan bir gün kendime hakim olamadan

Kıracağım dostu arkadaşı, gözyaşlarına bakmadan

Elimde değil senin için üzülüp kahrolmamak

Yüreğime seslenip kendi kendime avunmak

Zor geliyor artık sensizliğe dayanmak

Küstürürmüş insanı hayata, sevgisiz yaşamak.

Eminim ki bir gün beni anlarsın

Geç oldu diye için için yanarsın

Dayanamayıp acılara belkide ağlarsın

O zaman, eski günleri hatırlar, beni anarsın.', 'Çağladım akmak istedim mavi denizlere İsterim ömrüm geçsin, yalnız seninle Severmisin beni derdimle, herşeyimle                           Gi...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Cüsüm']::text[], 8.5, '{"poet":"Selçuk Cüsüm","poet_slug":"selcuk-cusum","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgili-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oh Olsun', 'oh-olsun-i-lhan-sesen-viwc9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeni bir aşk yaşıyorum, haberin olsun, 

Seni çoktan unuttum, işte laf olsun.

Ben her aşkta, seni yeniden yaşıyorum, 

Bir aşka sahip çıkamadık.

Bize oh olsun, bana oh olsun, sana oh olsun, 

Oh olsun, oh olsun, oh olsun, 

Bize oh olsun, yine bir aşk yaşıyorum, 

Haberin olsun.', 'Yeni bir aşk yaşıyorum, haberin olsun,  Seni çoktan unuttum, işte laf olsun. Ben her aşkta, seni yeniden yaşıyorum,  Bir aşka sahip çıkamadı...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şeşen']::text[], 8.5, '{"poet":"İlhan Şeşen","poet_slug":"i-lhan-sesen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oh-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ünlemler', 'unlemler-mehmet-tan-dna26', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nice acılar gördüm ben

Nice dertler yaşadım

Gözlerim kanlanıncaya kadar içtiğim de oldu

Ama böylesini görmedim 

Gülerken içim acımadı hiç

Yarınımdan korkmadım bu kadar

Günübirlik aşklarım olmuştu 

Ve günübirlik dertlerim

Hepimiz yarın ölmeyecekmiydik? 

O zaman niyeydi bunca dert, bunca tasa

Yarını bir ayağı çukurda olan dünyada? 

Böyle düşünür, böyle bilirdim

Nokta kadar dert

Virgül kadar tasa varken

Günün çeyreğini ağlayarak geçireceğimi 

Nereden bilebilirdim? 

Artık bakışlarım daha bir donuk

Gülüşüm içimi actıyor

Olsun be boşver

Ben yine de ünlemler koyuyorum

Kurduğum her cümlenin sonuna!', 'Nice acılar gördüm ben Nice dertler yaşadım Gözlerim kanlanıncaya kadar içtiğim de oldu Ama böylesini görmedim  Gülerken içim acımadı hiç Ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/unlemler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehir Zemberek Hayat', 'zehir-zemberek-hayat-mehmet-tan-cw8dr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne zaman oynatsam kalemimi 

karanlık kusuyor

damla damla kahır birikiyor ucunda

bir damla hayata

bir damla insanlara

bir damla da sana

hayat zehir zemberek ne zamandır

içilesi gibi değil

hele yanilesi gibi

hiç değil...', 'ne zaman oynatsam kalemimi  karanlık kusuyor damla damla kahır birikiyor ucunda bir damla hayata bir damla insanlara bir damla da sana hayat...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zehir-zemberek-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-mehmet-tan-6vztw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o geceyi unutamam gülüm

kimseye anlatamam 

söylemeye varmaz dilim

yazmak bile çok zor inan

titriyor kalem tutan elim

tutmam kendimi

bırakırım kollarına

varsın

gelirse senden gelsin ölüm', 'o geceyi unutamam gülüm kimseye anlatamam  söylemeye varmaz dilim yazmak bile çok zor inan titriyor kalem tutan elim tutmam kendimi bırakırı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gulum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Adam', 'buyuk-adam-mehmet-tan-urn2l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'büyük adamdım ben

şiirler yazar

şarkılar söyler

büyük laflar ederdim.

bunu herkes biliyordu

bazen hüzünlenir

kadere isyan eder

ağlardım

işte bunu kimse bilmiyordu', 'büyük adamdım ben şiirler yazar şarkılar söyler büyük laflar ederdim. bunu herkes biliyordu bazen hüzünlenir kadere isyan eder ağlardım işte...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/buyuk-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-mehmet-tan-5pn1q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bizim sahillerimiz vardı

denizden gelen rüzgarımız

mis gibi okyanus kokardı

platonik te olsa aşklarımız

yapay da olsa gözyaşlarımız

yavan da olsa gülüşlerimiz

bir de ölesiye dostluğumuz vardı

gençliğimiz

serzenişimiz

sarhoş rollerimiz

kısa da olsa

bir hikayemiz vardı

bir yel esti 

bir yağmur yağdı

geriye koskoca bir hiç kaldı', 'bizim sahillerimiz vardı denizden gelen rüzgarımız mis gibi okyanus kokardı platonik te olsa aşklarımız yapay da olsa gözyaşlarımız yavan da...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biz-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezbere', 'ezbere-mehmet-tan-5ky4p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'eabere yaşadık biz

ezbere güldük

ezbere ağladık

ve; 

ezbere sevdik', 'eabere yaşadık biz ezbere güldük ezbere ağladık ve;  ezbere sevdik...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ezbere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şarkı', 'bir-sarki-mehmet-tan-b33if', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben bir şarkı söyledim

dalgındın, duymadın

kuşları seyrediyordun

yüreğim kanatlanmıştı kuşlarla birlikte

bilmeden onu da seviyordun

sen duymadın

şarkının ortasında ben 

seni seviyorum dedim

ben bir şarkı söyledim

dalgındın, duymadın', 'ben bir şarkı söyledim dalgındın, duymadın kuşları seyrediyordun yüreğim kanatlanmıştı kuşlarla birlikte bilmeden onu da seviyordun sen duym...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-sarki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem', 'cehennem-mehmet-tan-chvju', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bizim yıldızlarımız vardı cehennem

her gece olmasa da arada bir

yüzünü gösterip gülümseyen aydedemiz

boşaltmaya korktuğumuz viski şişemiz

bir de hiç bitmeyen serzenişimiz

aşklarımız da oldu bizim

intikamlarımız da

ya da biz öyle sanıyorduk

ne dersin ha? 

biz dağa küsmüştük

dağın haberi olmamıştı oysa

dağ da suçsuzdu belki

biz orda burda zıplarken

ne zaman diken batsa ayağımıza

hep dağa küfrederdik

yine de severdik onu

değil mi cehenem? 

severmiydik gerçekten, 

yoksa sevdiğimizi mi zannederdik? 

biz aşkı da ya geç

ya zamansız tanırdık

sanki bir uykudaydık

uyandığımızda çırılçıplaktık

utanırdık

ama severdik be cehennem

yanlış ta olsa

zamansız da olsa

severdik

gece yarılarına kadar içer

yıldızlar bile uyuduğunda

sevdiğimizi rahatsız ederdik

hep geç kalırdık

telefon ederken bile

seni seviyorum derken bile_

hatalarımız olurdu bizim

boşver biz iyi ayık numarsı yapardık

tiyatrocuyduk ne de olsa

solucanı her yerde

her zaman yaşatmak gibi

cehennemin ateşini söndürmek gibi

tanrıyı kendimizce yorumlamak gibi

sevmek gibi...

geç te olsa

zamansız da olsa

sevmek gibi hünerlerimiz de vardı şüphesiz

herkesin aynı fabrika ürünü olduğu dünyada

farklı iki yıldız gibiydik

iki pırıltı

iki kor ateş

CEHENNEM! ! !', 'bizim yıldızlarımız vardı cehennem her gece olmasa da arada bir yüzünü gösterip gülümseyen aydedemiz boşaltmaya korktuğumuz viski şişemiz bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/cehennem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci El İnsan', 'i-kinci-el-i-nsan-mehmet-tan-8xpv3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'acı veriyor artık

gerçekleri görmek

en acı olanı da

onların bir parçası olmak

gülerken ağlamak

yaşarken ölmek

beş parasız kalmak

sevgiyi arayıp

sonunda hep hüzün bulmak

acı veriyor

insanlar içinde

ikinci el insan olmak', 'acı veriyor artık gerçekleri görmek en acı olanı da onların bir parçası olmak gülerken ağlamak yaşarken ölmek beş parasız kalmak sevgiyi ara...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ikinci-el-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Kalan', 'bana-kalan-mehmet-tan-dvuhn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bahar hep ellerin olur

bana kavurucu yaz kalır

mevsimler hisleri anlatsa

bahar sevgi

kış nefret

yaz aşk olsa

bana hüzünlü güz kalır

kimine ud

kimine keman

kimine davul

bana dertli saz kalır

kimine saten

kimine keten

kimine pamuklu

bana ne idiği belirsiz bez kalır

kimine nisan 

kimine eylül

kimine temmuz

bana acımasız mart kalır

kimine sevgi

kimine aşk

kimine para

bana dağlar kadar dert kalır', 'bahar hep ellerin olur bana kavurucu yaz kalır mevsimler hisleri anlatsa bahar sevgi kış nefret yaz aşk olsa bana hüzünlü güz kalır kimine u...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bana-kalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuzluğa Bir Başlık', 'mutsuzluga-bir-baslik-cafer-turac-akiam', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir geyik aşkımızı genişletmişti

gölgemize uyanan leylaklar

eteğine işlediğim saka

elim var mıydı sana bakan kör kuşlar gibi

seni alan bu gözler/kaç trahom geçirdi

kaç kırlangıç besledim balkonumda sevgili.

ya da seni üç filmle feseden

o mahalle aşklarına aykırı

ne uykular uyudum ne sular

kirlettim/sakar atlar misali

ama gelmedin.

şimdi koynumda ucu yanık son mektup

havuzlu bir posteri parkımızın

üşengeç bir çocuk gibi ayrılık

ve halimden anlayan bir ayna

durmaz da konuşmaz da.

7 Nisan 1982', 'bir geyik aşkımızı genişletmişti gölgemize uyanan leylaklar eteğine işlediğim saka elim var mıydı sana bakan kör kuşlar gibi seni alan bu gö...', ARRAY['Türk Edebiyatı','Şiir','Cafer Turaç']::text[], 8.5, '{"poet":"Cafer Turaç","poet_slug":"cafer-turac","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mutsuzluga-bir-baslik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairliğin Suyu', 'sairligin-suyu-mehmet-tan-4b73h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir şiir yazayım dedim

ortaya bu çıktı

ben de şiir yazıyorum ya

bu şairliğin

gerçekten suyu çıktı', 'bir şiir yazayım dedim ortaya bu çıktı ben de şiir yazıyorum ya bu şairliğin gerçekten suyu çıktı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sairligin-suyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bacım Ah', 'ah-bacim-ah-bayram-tunca-lpt4c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah nasıl sevmem, ben seni bacım

Anamın yokluğunda sendin ilâcım

Sen olmasaydın nasıl dinerdi acım

Sensin benim cihandaki tek ilacım

Çilen, dağlardan bile ağırdır senin

Yüreğin, volkan gibi yanıktır senin

Verilseydi çilen, dağları kavururdu

Atılsaydı kahrın, deryayı kuruturdu

Senin de ezelden yazılmış alın yazın

Hep gamlı yaslı söylerdi gönül sazın

Bilirim, ne baharın belliydi, ne yazın

Arş-ı âlâyı titretirdi ağlayışın/niyazın

Değirmen taşlarını öğütürdü sabrın

Metanet ve cesaret verirdi o tavrın

Acılarımı  unuttururdu ana şefkatin

Nedense olmazdı kimseye nefretin 

Anadolu gibi bereketliydi, ak ellerin

Tatlıydı dilin, Ay gibi güleçti cemalin

Anamın ak sütü gibi paktı o yüreğin

Damarımdaki kanım gibi de sıcaktın

Sen dekorunla bir Anadolu anasıydın 

Sen ekolünle de bir Yörük güzeliydin

İsminle köylü kızlarımızı anımsatırdın

Cisminle de canım anamı hatırlatırdın

Örme saçların, hilal kaçlarınla o nazlımı

Kınalı ellerin, ince belinle yine o edalımı

Tatlı dilin, güler yüzünle, o canım anamı

Hisli oluşunla hatırlatırdın tüm analarımı

Hiç unutmadım, unutmam ki asla iyiliğini

Yemeyip yedirip, giymeyip giydirdiklerini

Beni bir anne gibi, koruyup kollamalarını

Hem dahi kendin muhtaçken yaptıklarını

Ne vakit görsem seni, anam gelir aklıma

O gelemese de hayalı dikilir tam karşıma

Eğer seni anam deyip sarılırsam şaşırma

Hisli hisli ağlayıp da şu sineme dağlama

Sen ağlarsan, hazan olur benim bağlarım

Ta o günden beri, ana hasretiyle yanarım

O gün bu gündür, seni hep anam sanırım

Seni anam gibi sever başıma taç yaparım

Her özlem duyduğumda yarama ilaç yaparım 

Sen de olmasan ben şu dünyada ne yaparım

O an, ben şu dünyayı beş kuruşa bile satarım

Ben seni anam gibi sever başıma taç yaparım

www.baysab.com/11.04.2002-14.30', 'Ah nasıl sevmem, ben seni bacım Anamın yokluğunda sendin ilâcım Sen olmasaydın nasıl dinerdi acım Sensin benim cihandaki tek ilacım Çilen, d...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ah-bacim-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Olmak', 'asik-olmak-mehmet-tan-3f1xz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dudağımdan ıslık eksilmez oldu

saçlarımı taramaya başladım yine

aşık oluyorum galiba

be salak herif

aşık olmak senin neyine? 

akşamları düşünmeden yatamıyorum

uzaklara dalıp gidiyor gözlerim

unut onu diyorum kendime

söz dinlemiyor imansız kalp

bu fikri aklımdan atamıyorum

seveceğim tuttu yine

nerden geldiyse

aşık olmak kim

ben kim diyorum bazen

içimdeki canavar söz dinlemiyor

dinletemiyorum kendime

verimli olmuyor değil şu aşk

şiir yazmayı öğrendim

içmeyi

ağlamayı

hikayeler düzmeyi öğrendim

yalanlara kanmayı

kandıkça dert yanmayı

biraz zor da olsa

ıslık çalmayı öğrendin

çok şey de çaldı benden

gülüşümü

dostlarımı

uykumu...

o çaldıkça ben de çaldım

o beni çaldı benden

ben ıslık...

aşık oluyorum yine

herşeye inat

dudağımda acemi bir ıslık!', 'dudağımdan ıslık eksilmez oldu saçlarımı taramaya başladım yine aşık oluyorum galiba be salak herif aşık olmak senin neyine?  akşamları düşü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/asik-olmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Gibi Olaydım', 'su-gibi-olaydim-bayram-tunca-tj93u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ateşin korkulu rüyası ben olaydım

Hidrojen gibi sana eş ben olaydım

Vücut dengeni saylayan ben olaydım

Vazgeçemeyeceğin yar, ben olaydım

Senin akvaryumundaki su ben olaydım

Senin inci mercanlarını ben saklaydım

Seni her gün sayısız kere paklasaydım

Seni o derin denizlerimde saklasaydım

Olaydım olaydım sular gibi aziz olaydım

Her canlının bedeninde ben bulunaydım

Hasretle yolları gözetlenen ben olaydım

Herkes tarafından sevilen birisi olaydım

Kirleten değil, temizleyen biri olsaydım

Dilde zikir, gönülde şükür, ben olsaydım

Şairlerin de ilham kaynağı ben olsaydım

Her kez tarafından aranan biri olsaydım

Hasret çekenlerin itfaiyecisi ben olsaydım

Yaratılış ve son nefesteki, o ben olsaydım 

Kendini rahmet olarak andıran o olsaydım

Her yerde ve her zaman aranılan olsaydım

Savaşlara barışlara konu olan ben olsaydım

Türkülere, şarkılara konu olan ben olaydım

Aşıkların hararetini söndüren ben olsaydım

Kendini rahmet olarak andıran ben olaydım

[email protected]

19.04.2002-15.06', 'Ateşin korkulu rüyası ben olaydım Hidrojen gibi sana eş ben olaydım Vücut dengeni saylayan ben olaydım Vazgeçemeyeceğin yar, ben olaydım Sen...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/su-gibi-olaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirle Sınanmış Yürekten', 'siirle-sinanmis-yurekten-cafer-turac-z2gbs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bulvarda bir zambak uyanıyor

usulca küsüyor bir yaprak dalına

ağzının yarısı tütüne kesmiş bir işçinin adımları

kardeşimin gülkurusuna boyadığı kundura

sevdiğimin ağlatan mektupları ve adı

üzerimde bir emanet gibi duruyor.

şehir ve sara

hüzünle işliyor kandillerini yakarak çakşayan yerlerime 

sancıyor artık.

terk-i diyar bir onbeşlinin alnacında durup

geçiyorum ilkyazın alıngan bir akşamı şark

ekspresinde, gözüm sonuna kadar ilikli

çizgili göynekte, bir düğme koparır gibi yakamdan

ben de çekip giderim diyorum anam babam olmasa

çekip giderim buralardan/sırtımda mührüm ve tasa

ama bulvarda bir zambak uyanıyor ve suratım

donuk ışıltılarla kargışlamadı beni

ne büyük uykulara yatmışlığım var, 

ne büyük aşklara yol veren itirazım (daha bir şeyler... bir veda) 

çünkü acılara eyvallahımı

daha gür duymaktadır

içimdeki o insan

şimdi kim yazabilir

kahvelere sıkışan gençliğimi

övünçle taşıdığım bir demet

mektuplarına karşılık veremediğim çocukları yani o yaralı

günlerimi.

bir iskelede bıraktığım resmin

haydarpaşa garında bir tutam saçı

mahsus unutmuş bir kızın yüreğine değmeden

geçirdiğim pazarları

kim yazabilir artık

maaşı bir balıkçı kazağına denk gelmeyen adamın

gücenik dudaklarını ve bir oğulun her zaman tutuklu

olarak sevebilme hünerini ve leyla sayarı gördüğünde

bir hoş olan inşaatçı mardinlinin

fazla üstelemeyen bu şehirde yalnızım der gibi duruşunu

kim yazabilir ödünçsüz ve usta.

ve sen elimdeki imkanı sulara çalan umutsevdiğimiz zambak gibi açan yüzü

beş vakit gövdeme konan kumrum

ruhsatım, geceleri kırgın şarkım

dinliyor musun? 

21 Mart 1982', 'bulvarda bir zambak uyanıyor usulca küsüyor bir yaprak dalına ağzının yarısı tütüne kesmiş bir işçinin adımları kardeşimin gülkurusuna boyad...', ARRAY['Türk Edebiyatı','Şiir','Cafer Turaç']::text[], 8.5, '{"poet":"Cafer Turaç","poet_slug":"cafer-turac","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/siirle-sinanmis-yurekten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Yalnız Bırak', 'beni-yalniz-birak-mehmet-tan-vvn8p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bana öyle bakma ne olur

içimdekileri okumaya çalışma

bırak ben hep böyle kalayım

git kendi derdinle uğraş

işime karışma

bana öyle gülme ne olur

içimi karıştırma

beni yalnızlığıma terket

sevmekten korkuyorum anlamıyormusun

bana sevgiyi değil, nefreti zerket

defol git başımdan

benim kanım nefretle yoğrulmuş

bırak hep onunla kalayım

sevgiden, aşktan bahsetme

nefretimle doğdum

yine onunla öleyim', 'bana öyle bakma ne olur içimdekileri okumaya çalışma bırak ben hep böyle kalayım git kendi derdinle uğraş işime karışma bana öyle gülme ne o...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-yalniz-birak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nehrin Kızı, Kırmızı Gül ve Kış Odası', 'nehrin-kizi-kirmizi-gul-ve-kis-odasi-cafer-turac-3u7l0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çıplak ve yorgun atların kesik soluyuşları

gecede kırgın bir süvariye neler anlatırsa

bir kış odasında, doğrulan kırmızı güle

ve utanan akarsuya eğilerek, sevgilim sana

uğultumu sundum, ağladım, dilimde sarsılmış kırağılar

çıplak ve yorgun atların alınları kırmızı güle

dokunuca ve kırgın süvari yeni bir şarkıya

12 Eylül 1983', 'çıplak ve yorgun atların kesik soluyuşları gecede kırgın bir süvariye neler anlatırsa bir kış odasında, doğrulan kırmızı güle ve utanan akar...', ARRAY['Türk Edebiyatı','Şiir','Cafer Turaç']::text[], 8.5, '{"poet":"Cafer Turaç","poet_slug":"cafer-turac","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nehrin-kizi-kirmizi-gul-ve-kis-odasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-mehmet-tan-6eqj1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bilirim acı çekmemi istemezdin

ama mutsuzum anne

her günüm daha beter

geleceğimden umutsuzum anne

toprağım

çayırlarım kurumaya yüz tutmuş

bir damla yağmura hasretim

ama bulutsuzum anne

gülmeyi unutmuş gözlerim

çıkmazlara uzanır yollarım

yorgunum, dermansız kollarım

sensiz ben kutsuzum anne

sevemedim hayatı

ölümü de

kapı çalınır her akşam

azrail sanır ürkerim anne

yine de intiharlar kurarım her gece

sessiz sedasız

kansız olsun isterim

bilirsin kandan korkarım anne', 'bilirim acı çekmemi istemezdin ama mutsuzum anne her günüm daha beter geleceğimden umutsuzum anne toprağım çayırlarım kurumaya yüz tutmuş bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tan']::text[], 8.5, '{"poet":"Mehmet Tan","poet_slug":"mehmet-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anne-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zarif Efendim, Buğular Girdi Aramıza', 'zarif-efendim-bugular-girdi-aramiza-cafer-turac-ivkeh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'mutsuzun biriyim işte.

tek parça kaldı sandalım, 

sağır balıklar gibiyim denizin uğultulu yüzünde 

(efendim eğiliyor aramıza bir değirmen gülü/küskünüm.)

sahi beni biliyor musun? 

bir gençlik sayıyor musun gözyaşlarımı? 

efendim, muttasıl gülüşmüştük sizinle oralarda; gemilerin yorgun durduğu gecede

farkında olmak için ilk sesimle bağırıyorum size; çarpıntılı leylaklar uyumunda

ne çare, üzgün geyiklerin akşam ettiği sahiller yine boş diyorum

kızıl bir gergedan sayılıyor gece başlarken ay

efendim diyorum burdayız, mavi bir şizofreni dolaşıyor aramızda

ne çare, mutsuzum işte, abanızın sırılsıklam beyazlığına tutun beni

solgun bir düş olamadıktan sonra.

alın beni bu beyaz söz saltanatından, çıkarın

işaretinizin derinselahiyetinden

ve tek parça sesiniz kalsın bana, üzgün geyiklerini bıraktığı gökkuşağından.

mutsuzun biriyim işte, efendim, efendim zarif efendim

pabuçlarımda yenik savaşçı buğuları ve kalbim malihülya.', 'mutsuzun biriyim işte. tek parça kaldı sandalım,  sağır balıklar gibiyim denizin uğultulu yüzünde  (efendim eğiliyor aramıza bir değirmen gü...', ARRAY['Türk Edebiyatı','Şiir','Cafer Turaç']::text[], 8.5, '{"poet":"Cafer Turaç","poet_slug":"cafer-turac","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zarif-efendim-bugular-girdi-aramiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Annem...', 'guzel-annem-haydar-karayunlu-cgwi5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen değilmisin ki bizi doğuran, 

Sen değilmisin ki açken doyuran, 

Şimdi şu karşımda çaresiz yatan, 

Kapatma gözünü aç güzel annem.

Bize kanat olup uçuran sensin, 

Bizi ninni ile büyüten sensin, 

Ne kadar özleriz yüzünü senin, 

Yumma gözlerini aç güzel annem.

Felek göstermedi dünyada bir gün, 

Babamla birlikte zaten sen öldün, 

Çok acılar çektin, gülmedin birgün, 

Kapatma gözünü, gül güzel annem.

Varmıdır dileğin, neyleyim sana? 

Çevirde yüzünü bak nolur bana, 

Nasıl isyan etmem kara yazıya, 

Bakta bir yüzüme gül güzel annem.

Dünya fani gelen birgün gidecek, 

Sensizde evrende açacak çiçek, 

Karlar yağıp, güneş yine batacak, 

Yumma gözlerini, aç güzel annem.

Kadrini bilirmi anne olmayan, 

Dizide oturup, sütün emmeyen, 

Hergün acı çekip, bir gün gülmeyen, 

Kaldır da başını gül güzel annem.

Karamıdır bizim yazımız böyle, 

Neler istiyorsun? Ne olur söyle, 

Kusurumuz varsa nolur affeyle, 

Yumma gözlerini aç güzel annem.

Anne gibi varmı, dünya tatlısı

İşte can veriyor insanın hası, 

Kader denilesi olmaz olası, 

Bakta gözlerime gül güzel annem.

Ne bahtsızsın, onbir çocuk doğurdun, 

Yemedin, içmedin bizi doyurdun, 

Yem mi edeceğiz kuşun ve kurdun, 

Vermem topraklara kalk güzel annem...

                       (Bütün annelere sevgiyle...)

 09.10.2001 Sungurlu/Çorum', 'Sen değilmisin ki bizi doğuran,  Sen değilmisin ki açken doyuran,  Şimdi şu karşımda çaresiz yatan,  Kapatma gözünü aç güzel annem. Bize kan...', ARRAY['Türk Edebiyatı','Şiir','Haydar Karayünlü']::text[], 8.5, '{"poet":"Haydar Karayünlü","poet_slug":"haydar-karayunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/guzel-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçime Ağlıyo Gözlerim', 'i-cime-agliyo-gozlerim-mahmut-bingul-j66dp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim gözlerini özledi

Tenim sıcaklığını 

Üşüyorum! 

Gel! 

Sende ısınsım yüreğim 

İçimde ateşini yak 

Karları buzları erit üzerimden

Donlarımı çöz! 

Çözümsüzlüğümsün 

Çözümsüzlüğümü çöz

Gözlerim gözlerini gözlüyor 

bana seni soruyorlar

Onlara kalbini gösterdim

İçime ağladı gözlerim!', 'Gözlerim gözlerini özledi Tenim sıcaklığını  Üşüyorum!  Gel!  Sende ısınsım yüreğim  İçimde ateşini yak  Karları buzları erit üzerimden Donl...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/icime-agliyo-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-i-hsan-deniz-8xzk8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben durgun ruhları taşıyamadım

anlatamadım vaktin dolduğunu

bulutu unutulmuş bir gökle sırdaş olup

anlatamadım suların kabardığını, fırtınanın taştığını

toprağın kıvrıldığını, çatladığını taşların

her gece paylaşılan bir yüzden

sarardığını uykularımın

binlerce kez yanılmanın yorgunluğu

artık sönmüş bir fenerden

sislerden, peşpeşe yükselen bir kentlerden

kentlerin kemirilen evlerinden

bir yabancının ruhunu alkışlayıp

okşayarak, akarsu havuzlarına

karlı yamaçlara, sarnıçlara

yeniden parıldayacak bir hayatın ateşini yakmaya yetmiyordu

yetmiyordu bir gün bir falcıyı kandırmanın kurnazlığına

ama sen, ilk kez bulmanın sarhoşluğu

taşkın bir hayatın

ürkek ve zamansız yolculuğu

o kadar uzak

ve o kadar korkulu mutluluğu

evet, taşıyamadım durgun ruhları

taşıyamazdım

tanıyamadım bir böceğe yaslı adımları yankılayan kapıları

(adım ve kapı ve yankı bendim gerçi) 

filiz süren, kabuk değiştiren

yenilenen her ağaca yanaşamadım, 

beni bilen bir bakıcı çıksa

bir sahtekar tutup yaşadığımı haykırsa

ortaya konsa benden artan bana

şaşırmazdım, hatırlanmaz aldanmazdım

bütün sözlerin yanılacağını

hangi yöne sapılsa

ölüm figürlerinden kurulu yapılar karşısında susulacağını

............

zamansız bir kuşkuya düştüm ben

aldandım pencereye vuran gürültülerde

aklım karıştı, rehber olamadım örümceklere

bir ejder ritmi kolladım hep sana ulaşan kıyılarda

anla, kendime kurulan bir tuzağım ben

yetişemem taş kemerleri aşan yorgancıya

silemem, gözümden gitmez o dağın yolculukları

her sabah önüme düşen bir hayalin simsiyah olmuş kurumları

işte yalnız sana söylenen bir sözüm ben

bak, günlerdir güneşi utandıran bir yangınla örtülü içim dışım

ah, çıkar artık geceyi beni ayıltan ağzından

geçeyim toz zerreleri

altında mantar kokulu ülkenden

ah, yalnız sana söylenmiş bir sözdüm ben.......', 'ben durgun ruhları taşıyamadım anlatamadım vaktin dolduğunu bulutu unutulmuş bir gökle sırdaş olup anlatamadım suların kabardığını, fırtınan...', ARRAY['Türk Edebiyatı','Şiir','İhsan Deniz']::text[], 8.5, '{"poet":"İhsan Deniz","poet_slug":"i-hsan-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/soz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecemden Önce', 'gecemden-once-ayse-altan-neef6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kokun denizin kokusu

sesin denizin sesi

gül rengi bir akşamla

ıhlamur buğulu mektuplar gibi

bana günlerini gönder

uğultuyla büyür yürek

bir ırmaktır aramızda gidip gelen

akar ellerinle akşam sabah

hangi dağın rüzgarısın? 

yıldızlar

dağılmış bilyalarım mı

uçurtmam geçiyor yağmurlardan

kırmızı ve yalnız günler gibi', 'kokun denizin kokusu sesin denizin sesi gül rengi bir akşamla ıhlamur buğulu mektuplar gibi bana günlerini gönder uğultuyla büyür yürek bir ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Altan']::text[], 8.5, '{"poet":"Ayşe Altan","poet_slug":"ayse-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gecemden-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelmedin', 'sen-gelmedin-selim-erdogan-2-lan6m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ay doğdu, ay battı, sen gelmedin

mevsimler devrildi birbiri ardınca, 

nevruzu söküldü dağların, sen gelmedin

aklıma korkunç şeyler takıldı, 

gökyüzünü görmeden öldü kuşlar

dayanılmaz bir yarya dönüştü göğsüme bastırdığım yaşamak

denizi çakıl taşlarından tanıdım, mızıka sesleri büyüttüm içimde hep

tutup haberin aldım, hasret yapışıp kaldı garlara, 

sen gelmedin.

ben şimdi yağmurdan geliyorum, 

ıslak kampana sesi kulaklarımda

bitiyor sırtıma sarılan hırkanın sihri, 

koyu bir hüzün asılı kalbime

bir ırmağın kurumasını yaşıyor damarlarım, 

yanlış cinayetler takılıyor aklıma sevdiğim, 

kimleri bağışlayacak göğe asılı bıraktığım bu sağnak

bu delisaçması beklemekliğim; 

parklarda, kırık masalarda bıraktığım bu hayat

bu ebemkuşağı, 

bu gökyüzü, bu muhteşem renkler- tanrım bizi koru

bizi koru- bu karbeyaz bulutları giymiş dağlar, bu dağ rengi sevda

kimleri bağışlayacak

ayça bak gözlerim doluktu, yine ağlamak geçti içimden

alabildiğine kar yağdı caddelere, 

soluk kadın fotoğrafları çıktı cebimden

efsane bir yelkendir sürüldü dünyanın ortasına, 

sen gelmedin.

ne akşamlar oldu ellerime yansıyan kasabadan ilk

upuzun yitiren çığlıklarıyla parçalandı ellerim her akşam

hayatsa kırmızı bir çingene oldu, dolaşıp durdu etrafımda, sen gelmedin.

ay doğdu, ay battı, sen gelmedin

kırmızı yelkenli gemiler geçti gözümün önünden yağmur dedim, kar dedim, bir gün dönecektir sevdiğim

sen gelmedin.', 'ay doğdu, ay battı, sen gelmedin mevsimler devrildi birbiri ardınca,  nevruzu söküldü dağların, sen gelmedin aklıma korkunç şeyler takıldı, ...', ARRAY['Türk Edebiyatı','Şiir','Selim Erdoğan 2']::text[], 8.5, '{"poet":"Selim Erdoğan 2","poet_slug":"selim-erdogan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-gelmedin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elvedam', 'elvedam-ozan-cetinkaya-2p9ne', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinin rüzgarına takılmış sürüklendiğim köşeleri bilmeden

Her defasında mutluluk yalvarışlarımı duymadığını düşünmeden

Yine seni delice istediğimi, kendimi inandırmadan

Her ayrılığın öncesinde, defalarca, kalbimi kırarak söylediğim

Gözlerimi kapatırken gönülden söylemediğim

Sende nasibini al, bu son elvedamdan', 'Gözlerinin rüzgarına takılmış sürüklendiğim köşeleri bilmeden Her defasında mutluluk yalvarışlarımı duymadığını düşünmeden Yine seni delice ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Çetinkaya']::text[], 8.5, '{"poet":"Ozan Çetinkaya","poet_slug":"ozan-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/elvadam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Ekim 1945', '1-ekim-1945-nazim-hikmet-ran-62jbz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağın üstünde: 

akşam güneşiyle yüklü olan bir bulut var dağın üstünde.

Bugün de: 

s
..........
..........', 'Dağın üstünde:  akşam güneşiyle yüklü olan bir bulut var dağın üstünde. Bugün de:  s .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/1-ekim-1945-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoldan Geçen Yabancı', 'yoldan-gecen-yabanci-walt-whitman-u3l1a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoldan geçen yabancı! Sana nasıl istekle baktığımı bilemezsin, 

Sen aradığım erkeksin, ya da aradığım kadın, (sanki bir düş görüyorum.) 

Bir yerde, tatlı bir yaşam geçirmiş olacağız seninle, 

Her şeyi hatırlıyorum, hepsi yeniden canlanıyor gözümde, yan yana yürüyoruz, 

        akıcı, sevgi dolu, içi dışı tertemiz, olgun, 

Benimle büyüdün sen, küçük bir oğlan ya da küçük bir kızdın benimle, 

Ben yemek yedim seninle, ben uyudum seninle, senin vücudun senin olarak 

        kalmadı yalnızca, benim vücudumu benim olarak bırakmadı yalnızca, 

Gözlerinin, yüzünün, etinin tadını veriyorsun bana, birlikte yürüyoruz, 

        karşılığında sakalımın, göğsümün, ellerimin tadını alıyorsun, 

Seninle konuşmasam da bir şey değişmiyor, tek başıma oturduğum, ya da gece tek 

        başıma uyandığım zamanlar seni düşünüyorum, 

Bekliyorum, seninle gene buluşacağız, kuşkum yok bundan, 

Seni hiçbir zaman yitirmemeye bakıyorum.', 'Yoldan geçen yabancı! Sana nasıl istekle baktığımı bilemezsin,  Sen aradığım erkeksin, ya da aradığım kadın, (sanki bir düş görüyorum.)  Bir...', ARRAY['Türk Edebiyatı','Şiir','Walt Whitman']::text[], 8.5, '{"poet":"Walt Whitman","poet_slug":"walt-whitman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yoldan-gecen-yabanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Kaptanım! Canım Kaptanım!', 'ey-kaptanim-canim-kaptanim-walt-whitman-odw93', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey Kaptan! canım Kaptanım! korkulu yolculuğumuz sona erdi

Bütün tehlikeleri atlattı gemi, kavuştuk isteğimize kavuştuk, 

Liman şuracıkta, bak, çan sesleri geliyor, sevinç içinde halkımız, 

Gözler dümdüz ilerleyen teknemizde, teknemiz gururlu, korkusuz; 

            Ama ey yürek! yürek! yürek! 

            Ey kanayan kırmızı damlalar, 

            Orada- güvertede Kaptanım yatıyor, 

            Buz gibi olmuş, ölmüş.

Ey Kaptan! canım Kaptanım! ayağa kalk, çanları dinle, dinle; 

Ayağa kalk -bayrak senin için çekildi- senin için dolup taşıyor kıyılar, 

Herkes seni çağırıyor, yerinde duramıyor kalabalık, herkes seni görmek istiyor; 

            Gel Kaptan! sevgili babacığım! 

            Koluma daya başını, koluma daya! 

            Bu bir düş, bu bir yalan, böyle güvertede, 

            Senin buz gibi olman, ölmen.

Kaptanım ses vermiyor, dudakları soluk, cansız, 

Babam kolumun dokunuşunu duymuyor, nabzı atmıyor artık, 

Gemi demirledi, güvenli, görev sona erdi, tamam, 

Korkulu yolculuğundan, şanlı gemi, amacına ulaşmış olarak dönüyor; 

            Sevinin ey kıyılar, çalın ey çanlar! 

            Ama ben üzüntülü adımlarla, 

            Kaptanımın yattığı güvertede dolaşıyorum, 

            Buz gibi olmuş, ölmüş.', 'Ey Kaptan! canım Kaptanım! korkulu yolculuğumuz sona erdi Bütün tehlikeleri atlattı gemi, kavuştuk isteğimize kavuştuk,  Liman şuracıkta, ba...', ARRAY['Türk Edebiyatı','Şiir','Walt Whitman']::text[], 8.5, '{"poet":"Walt Whitman","poet_slug":"walt-whitman","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ey-kaptanim-canim-kaptanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadın Bekliyor Beni', 'bir-kadin-bekliyor-beni-walt-whitman-9furm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kadın bekliyor beni, her şey bulunuyor onda, hiçbir eksiği yok

eğer seks yoksa ya da ıslaklığı yoksa doğru erkeğin hala eksiktir her şey.

Seks dahil her şeye

bedenlere, canlara, anlamlara, kanıtlara, saflığa, inceliklere, sonuçlara, 

çığlıklara

şarkılara, emirlere, sağlığa, gurura, analığın gizine, doğuştan gelen süte

Bütün umutlara, iyiliklere, bağışlanmışlara

bütün arzulara, aşklara, güzelliklere ve dünyanın tatlarına

bütün devletlere, yargıçlara, tanrılara, dünyayı anlamış insanlara

onun parçasıymış gerekçesiymiş gibi dahildir seks

Tanıdığım her erkek utanmaksızın bildiğini itiraf eder cinsiyetinin tadını

ve her kadın bilir ve itiraf eder kendininkini

Şimdi duygusuz kadınlardan uzaklaştırıyorum kendimi

kalmaya gidiyorum beni bekleyen kadına, 

doyduğum sıcakkanlı kadınlara

görüyorum beni anladıklarını ve reddetmediklerini

değer verdiklerini bana-güçlü bir koca olabilirim onlara

Benden eksik yanları yok

Güneşle ve esen rüzgarla bronzlaşmış yüzleri

Kutsal, yumuşak ve güçlü vücutları

biliyorlar nasıl yüzeceklerini, kürek çekmeyi

ata binmeyi, güreşmeyi, ateş etmeyi

Nasıl koşacaklarını, öldüreceklerini, çekilmeyi, 

yol almayı, direnmeyi, savunmayı

mükemmel hepsi sakin ve berrak sahipler dişiliklerine

Sıkıca çekiyorum sizi kendime ey kadınlar

izin veremem gitmenize, yeterliyim ben size

Ben sizler içinim sizler de benim ve

yalnızca benim iyiliğim için değil bu

başkalarının iyiliği için de

Uykularınızı daha yüce kahramanlar, şairler kaplamış

ve izin vermiyorlar kimsenin dokunmasına

ama yalnızca ben dokunabilirim size

Bu benim ey kadınlar- kendi yolumu çizdim

Acımasızım ben, sert, geniş ve inatçıyım

-ama sevdiğim için

artık gerekenden fazla incitmeyeceğim sizi

Akıyorum size, sıkarak kaba gücümle sıhhatli

kız ve erkek çocuklar getirmek için bu ülkeye

Hiç bir yakarışı dinlemeden, kendimi güçlendiriyorum yeterince

ve biriktirdiğimi size geri vermeden

kararlıyım geri çekilmemeye

Gizli ırmağına akarım senin

içine ilerleyen binlerce yılı sarıyorum

sahip olduğum en önemli şeyimi

ve Amerika''yı aşılıyorum sana

Sana akan damlalarımdan vahşi ve atletik kızlar

yeni sanatçılar, müzisyenler ve şarkıcılar yetişecek

senden döllediğim bebekler sırası geldiğinde bebekler dölleyecekler

Ben mükemmel erkekler isteyeceğim aşkımın tohumlarından

Çiftleşmelerini bekleyeceğim başkalarıyla

benim seninle çiftleştiğim gibi şimdi

Fışkıran yağmurlarımın meyvelerini sayacağım

sana geldiğimde yağmurların meyvelerini saydığım gibi şimdi

doğumda, yaşamda ölümde ve ölümsüzlükte arayacağım aşkın ürünlerini

öylesine severek yetiştiriyorum ki onları şimdi.', 'Bir kadın bekliyor beni, her şey bulunuyor onda, hiçbir eksiği yok eğer seks yoksa ya da ıslaklığı yoksa doğru erkeğin hala eksiktir her şey...', ARRAY['Türk Edebiyatı','Şiir','Walt Whitman']::text[], 8.5, '{"poet":"Walt Whitman","poet_slug":"walt-whitman","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/bir-kadin-bekliyor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Olmak', 'anne-olmak-barbaros-mustafa-guner-97il4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anne, gözlerinden akan seffaf beyaz bir pırıltı denizidir.

bizleri umutlara boğan.

Oysa bizler senin sevginde yüzen küçük birer yaprağız, 

seninle beraber  heryere gelmeye hazır olan.

Gittiğin yerde senin gibi binlercesi olacak ama

yokluğunda bizim gibi onlarcası yaprak yol olmaya

yüz tutacak.

Bu yüzden bir kavgadır yaşamak, 

                              Bir kavgadır anne olmak.

Ekilen fidanlar yeşermeden bir gökkuşağının altında

çöküp ağlamak.

Bir savaştır her isyanda karşı kıyıya geçip

gökkuşağını baştan boyamak.

Her renginde evladını farklı farklı yollarda aramak.

İşte bu yüzden bir kavgadır anne! 

Evladının her yoldan senin kapına çıktığı anda

vazgeçmiyor olmak.

Bu yüzden bir kavgadır anne olmak.

 				Nisan 2001-İstanbul', 'Anne, gözlerinden akan seffaf beyaz bir pırıltı denizidir. bizleri umutlara boğan. Oysa bizler senin sevginde yüzen küçük birer yaprağız,  s...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Mustafa Güner']::text[], 8.5, '{"poet":"Barbaros Mustafa Güner","poet_slug":"barbaros-mustafa-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anne-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-bilgehan-acar-9rdxa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bir kör göz, sense yaşım

Göz yaşı durmaz süzülür gözlerden, 

Son bir kez söz arkadaşım, 

Kalbim barışmaz, üzülür sözlerden!', 'Ben bir kör göz, sense yaşım Göz yaşı durmaz süzülür gözlerden,  Son bir kez söz arkadaşım,  Kalbim barışmaz, üzülür sözlerden!...', ARRAY['Türk Edebiyatı','Şiir','Bilgehan Acar']::text[], 8.5, '{"poet":"Bilgehan Acar","poet_slug":"bilgehan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/soz-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ceyhun-yilmaz-vdamh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Islak bir sokakta bulursun kendini

Yüreğin taş, dudakların yok

Yaşadığını zannedip yürümek istersin

Ellerin titrer, gözlerin dolar

Yüreğinde ne varsa yaş olup akar gözlerinden

Üşüdüğünü zannedersin; ölmektesindir

Sıkı dur bebeğim buna AYRILIK derler.....', 'Islak bir sokakta bulursun kendini Yüreğin taş, dudakların yok Yaşadığını zannedip yürümek istersin Ellerin titrer, gözlerin dolar Yüreğinde...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayrilik-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-onur-hanic-ymwkb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gece soğuk, ayaz

ince bir yağmur

bir ben, bir martın ayazı

bir de yalnızlık 

sokakta

sarılıyorum hatıralara.

ısınmak istiyorum; üşüyorum.

Üşüdüğümden fazla

Seni özlüyorum.', 'gece soğuk, ayaz ince bir yağmur bir ben, bir martın ayazı bir de yalnızlık  sokakta sarılıyorum hatıralara. ısınmak istiyorum; üşüyorum. Üş...', ARRAY['Türk Edebiyatı','Şiir','Onur Haniç']::text[], 8.5, '{"poet":"Onur Haniç","poet_slug":"onur-hanic","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/usuyorum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen II', 'gidersen-ii-sema-gulser-keser-lqqba', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adın dudaklarıma çiselerken, 

Belki yine gelirsin! 

Kana kana içerim gözlerini, 

     Ve yine susarız.

Kim bilir belki konuşuruz, 

   Düşlerden, havadan, sudan, aykırılıklardan...

Yada ay kırıklarından.

Bakarsın çocuk sevdalarda güleriz, 

Ararız kendimizi körebe oynarken, 

 Ve sen, 

      yine mızıkçılık yapar, alırsın oyunu.

Yada ne bileyim, sakin bir kasabada, 

Çay içeriz tan atımında.

Dağlar şahidimdir der, 

Belki konaklarız bir mezar başında.

Umutlarımız törpülenirse ansızın bir akşam! 

Susarız.....

    Susarız.....

          Veya  su/sarız....



                                                          (19-04-2002)', 'Adın dudaklarıma çiselerken,  Belki yine gelirsin!  Kana kana içerim gözlerini,       Ve yine susarız. Kim bilir belki konuşuruz,     Düşler...', ARRAY['Türk Edebiyatı','Şiir','Sema Gülser Keser']::text[], 8.5, '{"poet":"Sema Gülser Keser","poet_slug":"sema-gulser-keser","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidersen-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Denizdeyken Ben', 'sen-denizdeyken-ben-i-rfan-mutluer-gh3rk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen denizdeyken ben

Kumdan kaleler yaptım.

Ellerimi sakladım kumlar içine

Ellerim nerede diye kızımıza sordum.

Ellerim nerede? 

Ellerim...

Sen denizdeyken ben

Güneş’e inat, 

Doğuya gittim.

Dalgaların sesini dinledim.

Balıkların çığlıklarını.

Yeni bir paket daha açtım, 

Dumanını sana gönderdim.

Sen denizdeyken ben

Kızımıza süt verdim, 

Suyla serinlettim, 

Ayaklarımda uyuttum.

Minicik ellerini avucuma aldım, 

Öptüm, okşadım.

Sen denizdeyken ben

Uzaktan seni izledim.

Haydi dön artık diye seslendim sana

Her açılışında.

Dön artık! ..

Yanında olmak istedim.

Sen denizdeyken ben

Seni ne kadar çok sevdiğimi

Bir kez daha anladım.

Sen denizdeyken ben

Cesaretini gördüm.

Yüzme yarışındaki hızını, 

Dalgalarla kucaklaşmalarını.

Her şey çok güzeldi belki? ..

Ben kenardaydım.

Sen denizdeyken ben

Dayanamadım, ağladım.', 'Sen denizdeyken ben Kumdan kaleler yaptım. Ellerimi sakladım kumlar içine Ellerim nerede diye kızımıza sordum. Ellerim nerede?  Ellerim... S...', ARRAY['Türk Edebiyatı','Şiir','İrfan Mutluer']::text[], 8.5, '{"poet":"İrfan Mutluer","poet_slug":"i-rfan-mutluer","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sen-denizdeyken-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zakkumlar Açardı Yüreğimde Bilmezdin', 'zakkumlar-acardi-yuregimde-bilmezdin-i-rfan-mutluer-ljxo3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün solardı, ağlardın, 

Geceler dökülürdü parmaklarından.

Sabahlara yelken açardın, 

Rüzgarsız gecelerden.

Zakkumlar açardı yüreğimde bilmezdin.

Belki de sen beni, böyle sevmezdin.

Eylüldü yaşadığın 

Nisan ortasında.

Kuşlardan kırlangıcı severdin.

Zakkumlar açardı yüreğimde bilmezdin.

İlkyazda kendini terketmezdin.

Çığlığın sesinde kalırdı, duymazdın, 

Çiy yağardı saçlarına, görmezdin, 

Dökülen yapraklara, 

Hep yenisini verdin.

Zakkumlar açardı yüreğimde bilmezdin, 

Zakkumlar açardı yüreğimde, 

Bilmezdin...', 'Gün solardı, ağlardın,  Geceler dökülürdü parmaklarından. Sabahlara yelken açardın,  Rüzgarsız gecelerden. Zakkumlar açardı yüreğimde bilmez...', ARRAY['Türk Edebiyatı','Şiir','İrfan Mutluer']::text[], 8.5, '{"poet":"İrfan Mutluer","poet_slug":"i-rfan-mutluer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zakkumlar-acardi-yuregimde-bilmezdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni', 'yeni-i-rfan-mutluer-4vs0w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabah yeni kalktım, 

Elim ve yüzüm yeni, 

Urbalarım yeni, 

Düşüncelerim yeni.

Karşımdakiler yeni

Otlar, ağaçlar, 

Kuşlar  yeni.

Dağlar yeni, insanlar yeni.

Ben yeniyim.', 'Sabah yeni kalktım,  Elim ve yüzüm yeni,  Urbalarım yeni,  Düşüncelerim yeni. Karşımdakiler yeni Otlar, ağaçlar,  Kuşlar  yeni. Dağlar yeni,...', ARRAY['Türk Edebiyatı','Şiir','İrfan Mutluer']::text[], 8.5, '{"poet":"İrfan Mutluer","poet_slug":"i-rfan-mutluer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmuşum', 'unutmusum-ahmet-selcuk-i-lkan-br4va', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Değişen ben miyim öyle

Ben miyim eski sevdalara mendil sallayan

Şu eller

Şu gözler

Şu kalp benim mi yoksa

Ya şu gülen adam ben miyim? ..

Demek ki unutmuşum

Demek ki kurtulmuşum bütün acılarda

Geceler karanlık değil, uzun değil

Anlamsız değil şu dünya

Yaşamamak elde değil...

Ağaç ağaca benziyor artık

Deniz denize

Çiçek çiçeğe

Şiirler yazmıyorum artık bak

Gözlerinin güzelliğine...

Ohh! Ne iyi unutmuşum

Unutmuşum yıllanmış elbiselerim gibi seni

Çıkarıp atmışım sandık sandık kalbimden

Bütün kederlerden

Bütün üzüntülerden

Nihayet kurtulmuşum...', 'Değişen ben miyim öyle Ben miyim eski sevdalara mendil sallayan Şu eller Şu gözler Şu kalp benim mi yoksa Ya şu gülen adam ben miyim? .. Dem...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/unutmusum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosun Gözlüm', 'yosun-gozlum-ahmet-selcuk-i-lkan-0az2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bakma gözlerime

Dağılmışım yosun gözlüm

Hasretinin denizinde

Boğulmuşum yosun gözlüm

Bir bendesin bir uzakta

Bir özgürsün bir yasakta

Arada bir sarılsak da

Yetmiyor ki yosun gözlüm

Dağlar gibi özlesem de

Hasretinden delirsem de

Bir mum gibi erisem de

Gelmiyorsun yosun gözlüm

Anlatılmaz bir duygu bu

Vazgeçilmez bir tutku bu

Unutulmak tek korkum bu

Bilmiyorsun yosun gözlüm', 'Öyle bakma gözlerime Dağılmışım yosun gözlüm Hasretinin denizinde Boğulmuşum yosun gözlüm Bir bendesin bir uzakta Bir özgürsün bir yasakta A...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yosun-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Vermiştim YIldızlara', 'soz-vermistim-yildizlara-aydin-karatay-4x9t7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bi haziran akşamı 

meydan okumuştun ölüme

direnmişti gözlerin

masum bir gülüşün vardı uyurken 

sessizce ağlamıştım ben 

başucunda sılana sokulmuştum 

sensizligi düşünmüştüm

o zaman

üşümüştü tenim bu gibi yüregimle 

bir haziran akşamı 

baş kaldırmıştın acılara 

masum bir gülüşün vardı uyurken 

sessizdi bedenin sıcaktı ellerin 

yüzümü gökyüzüne cevirip

yıldızlarla dertleştim o gece 

bir dilek tut demiştin başını kaldırıp

ve yüregim parçalandı adeta

sen dönünce

oturup sabaha kadar anlattığın 

gözlerini karartıp ağladığın 

güneşi görsem diye yalvardıgın 

o gece 

getiremezdimki sana güneşi 

beceremezdim ki

bir haziran akşamı

meyden okudugunda ölüme 

ağlamıştım 

aslında nekadar içsemde artık 

kadehi alacak kimse yok elimden

sen giderken yanlız degildin 

unutma....

göz yaşlarımıda aldın benden 

artık ne kadar ağlamak istesemde 

beni terketmişti göz yaşlarım 

unutma......

giderken yanlız değildin 

yüreğimide kopardın bagrımdan 

ruhumuda aldın yanına

bir haziran akşamı 

giderken sensizlige 

bir tek şu bedeni bıraktın

çünkü bir tek yeminim vardı

vebir tek dilegim

bir haziran akşamı 

giderse demiştim yıldızlara

benide alsın yanına 

söz vermiştim...........

05     -02     -01        İZMİR', 'bi haziran akşamı  meydan okumuştun ölüme direnmişti gözlerin masum bir gülüşün vardı uyurken  sessizce ağlamıştım ben  başucunda sılana sok...', ARRAY['Türk Edebiyatı','Şiir','Aydın Karatay']::text[], 8.5, '{"poet":"Aydın Karatay","poet_slug":"aydin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/soz-vermistim-yildizlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ahmet-selcuk-i-lkan-oh9nh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırak ellerimi 

Üç satır yazacağım

Üç satırda sen! ...

Bırak gözlerimi

Dört yana bakacağım

Dört yanda sen! ...

Bırak yüreğimi

Bin kere seveceğim

Bin kerede sen! ...', 'Bırak ellerimi  Üç satır yazacağım Üç satırda sen! ... Bırak gözlerimi Dört yana bakacağım Dört yanda sen! ... Bırak yüreğimi Bin kere sevec...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usanmadan Seveceğiz Birbirimizi', 'usanmadan-sevecegiz-birbirimizi-ahmet-selcuk-i-lkan-3nmdw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayır! Bu sana son şiirim olmayacak

Ne de son şarkım... Asla! 

Yazacağım hergün yeniden

Hergün bir öncekinden fazla...

Bir gün seni anlatacağım

Bir gün aşkını...

Belki sonuncu şiirimde bulacağım

En sıcak bakışını! ...

Sonra kendimden bahsedeceğim

Mısralarda titreyeceğim ılık ılık.

''''Bu şarkı var ya! '''' diyeceğim

Anlayacaksın ve güleceksin ışık ışık...

Z'' ye gelmeyeceğim hiç

Hep A'' larda demirleyeceğim

Sen özlemler açacaksın sabırsızlığında

Bense fırtınalarda serinleyeceğim! ...

Ve böyle sürüp gidecek aşkımız usanmadan

Usanmadan seveceğiz birbirimizi

Sen bana, ben sana doymadan

Ancak ölüm yenebilecek ikimizi...', 'Hayır! Bu sana son şiirim olmayacak Ne de son şarkım... Asla!  Yazacağım hergün yeniden Hergün bir öncekinden fazla... Bir gün seni anlataca...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/usanmadan-sevecegiz-birbirimizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Başkasın', 'sen-baskasin-ahmet-selcuk-i-lkan-4wlmu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen başkasın

Gülerken başka

Küserken başka

Susarken başka

Sen başkasın

Konuşurken başka

Öpüşürken başka

Sevişirken başka

Hem de herkesten başka

Ama benim aşkım 

Bambaşka!', 'Sen başkasın Gülerken başka Küserken başka Susarken başka Sen başkasın Konuşurken başka Öpüşürken başka Sevişirken başka Hem de herkesten ba...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-baskasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Aşkı', 'sair-aski-ahmet-selcuk-i-lkan-g8si2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölürsem bir gün

Ağlayacaksın! 

Belki kara gözlerime

Belki sıcak dizlerime

Belki de artık seni saramayacak ellerime

Oysa isterim

Ağlayasın

Yazmadığım şiirlere! ...', 'Ölürsem bir gün Ağlayacaksın!  Belki kara gözlerime Belki sıcak dizlerime Belki de artık seni saramayacak ellerime Oysa isterim Ağlayasın Ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sair-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İkimiz', 'biz-i-kimiz-tahsin-dagli-sn96x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karşılıklı yazarak paylaştık

        Severek harcadık zamanlarımızı

   Bazen dargın, bazen barışık, bazen ten ten.

      Büyüttüğümüz yavrumuzu severcesine

            İçten gelerek, tiksinmeden. 

    O karabulut, o şimşek, o sağnak yağış

 O talihsiz an, o bizi sarsan deprem, o yakarış

       O kemiren, o kaçınılmaz kıskançlık

           O değilmiydi kıs kıs gülerek

              O bir gün galip gelerek

                 Semeresini alacaktı

                   Perişan ederek...

                Bizler öylesine sadık, 

       Öylesine yaradana yemin ederken

    İmkansızı çaresizce ispata çabalarken

 Çaresizlikte çaresizliğin gizemini keşfederken

       Gördük ki, aşkın bedduası ayrılıkmış...

         Gözlerde alev, bedende ölü bir can, 

             Damarlarda dolaşmayan kan.

                  Yaşamak alışmak mış

                         Ve bir gün, 

                  Yalnız kalmakmış.

         Birdenbire uzakların başlaması

   Hasret, özlem, yalnızlık, keder, neden, niçinler

          Yalnızlık paylaşılmaz belki ama

              Duygular hisler hep aynıdır.

                    Acılar ortaktır hep.

                Yollar bitmez deseler de, 

         Her yolun bir başı, bir sonu varmış.

    Yaşamak, alışmalardan sonra yaşayabilmek

           Alıştığın her şeyle savaşmakmış.

              Kendimize duyuramadık ki, 

                   Dünyaya duyuralım

                     Yasak sevgimizi...

           Şimdi dertler içimizde dizi dizi

     Ölümden önce de ayrılık olabiliyormuş

 Aklıma sokmuyordum, ölüm yetecekti ayrılığa.

     Hep diyordum, kimse bilmez ayrılığımızı

            Ben bile bilmedikten sonra! 

               Ayrımıyız, birliktemiyiz, 

                     Belli bile değil...

                     Kimse bilmez, 

          Sevişirmiyiz, sevişmez miyiz? 

   Kim ne bilir, biz bile bilmedikten sonra.

 Uzaklarda olsan da, yüreceğimdeyken sen.

   Ben böyle çaresiz, ifadesiz savrulurken.

           Tüm hüzünlü şarkılar, filmler

              Seni anlatır, andırır şimdi.

                 Nur yüzünü görürüm

                     Boş duvarlarda.

                           Yine de, 

             Seninle uyanırım sabahları

         Hani mutlu günler yaşasak tekrar

 Ama tekrar başlamak, terkar ayrılık getirir mi? 

   Dayanabilirmiyiz bu acıya, düşlerin ateşinde? 

      Gönüllerde ılık bir rüzgar gibi eserken.

        Sevgiyle anmak, canlandırmak hayali

          Dayanamayıp, bir gün sana gelmek, 

                Seni görmeden ölmemek...

                     Nisanın yirmi üçü, 

             Kadere bak! .doğum günün.

          Kolum kanadım kırık bir tanem! 

   İstesem de oralara uçamam, uçamam canım

      Arada bir de azgın kıskançlık denizi

           Yunus da değilim ki yüzemem.

             Mutluluk olsun gözyaşların

                Ne olur onları sil artık.

                      Bak yanındayım, 

                 Cümlelerimle  satır satır.

           Canım zor günlerdi yaşadıkların

   Ama kederli, ama neşeli, bak bir yıl daha geçti.

 Hep böyle değilmiydi dertler, biri gelir, öbürü gider.

    Bak! ...yüreğimde, gönlümde hep aklımdasın

       Her şeyinle bende bir parçasın, yarımsın...

         Bitse de farketmez ki, sen tanıdığım, 

           Sen gördüğüm son ''Nur''sun.

                        Gönlüm der ki; 

    ''YAŞ GÜNÜN KUTLU OLSUN GÖNLÜNCE''

             Sevgiyle kal, esen kal, şen şakrak! 

                   Sevdiklerinle ömrünce...

                       Hiç istemem mi? 

                       Yanında olmak.

                          Bir damla! 

       Bir  damlacık gözyaşıyla gülümsemek, 

  Ellerini sımsıkı tutup, gözlerinde gizlenmek.

      Günün hediyesi olmak isterdim inan, 

            Tozpembe bir paketten çıkıp, 

                Tüm benliğini içime alıp, 

                   Güzelliğini çalıp, 

           Tekrar paketlenmek isterdim...

            Sonsuzlukta birlikte anılmak, 

          Mezar taşına siyah siyah kazınıp, 

           Hafif yağmur yağdığında ıslanıp, 

                   Yağmur dindiğinde

                   O kimsesiz seherde, 

           Seninle buharlaşmak isterdim...

             Kıskançlık ayırsa da ikimizi, 

        Biz bile anlayamadıysak sevgimizi, 

                 HAYKIRIYORUM! ...

     TÜM DÜNYANIN HABERİ OLSUN

 BİZ YİNE DE SEVİYORUZ BİRBİRİMİZİ...

       

                  21.04.2002', 'Karşılıklı yazarak paylaştık         Severek harcadık zamanlarımızı    Bazen dargın, bazen barışık, bazen ten ten.       Büyüttüğümüz yavrum...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Dağlı']::text[], 8.5, '{"poet":"Tahsin Dağlı","poet_slug":"tahsin-dagli","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/biz-ikimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman..', 'ne-zaman-aylin-fakili-vpupy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlasam, 

Haykırsam, yoksun.

Şehirde iz var gülüşünden

şehirde yaz var, 

içimde bir soğuk rüzgar...

Ağlasam, 

Haykırsam, yoksun

Şarkılar söylüyorum 

İçten içe yokluk şarkıları

Ne zaman güler yeşil gözlü kız?', 'Ağlasam,  Haykırsam, yoksun. Şehirde iz var gülüşünden şehirde yaz var,  içimde bir soğuk rüzgar... Ağlasam,  Haykırsam, yoksun Şarkılar söy...', ARRAY['Türk Edebiyatı','Şiir','Aylin Fakılı']::text[], 8.5, '{"poet":"Aylin Fakılı","poet_slug":"aylin-fakili","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-zaman-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu', 'anadolu-ahmed-arif-qhqlf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beşikler vermişim Nuh''a

Salıncaklar, hamaklar, 

Havva Ana''n dünkü çocuk sayılır, 

Anadoluyum ben, 

Tanıyor musun? 

Utanırım, 

Utanırım fıkaralıktan, 

Ele, güne karşı çıplak...

Üşür fidelerim, 

Harmanım kesat.

Kardeşliğin, çalışmanın, 

Beraberliğin, 

Atom güllerinin katmer açtığı, 

Şairlerin, bilginlerin dünyalarında,        

Kalmışım bir başıma, 

Bir başıma ve uzak.

Biliyor musun? 

Binlerce yıl sağılmışım, 

Korkunç atlılarıyla parçalamışlar

Nazlı, seher-sabah uykularımı

Hükümdarlar, saldırganlar, haydutlar, 

Haraç salmışlar üstüme.

Ne İskender takmışım, 

Ne şah ne sultan

Göçüp gitmişler, gölgesiz! 

Selam etmişim dostuma

Ve dayatmışım...

Görüyor musun? 

Nasıl severim bir bilsen.

Köroğlu''yu, 

Karayılanı, 

Meçhul Askeri...

Sonra Pir Sultanı ve Bedrettini.

Sonra kalem yazmaz, 

Bir nice sevda...

Bir bilsen, 

Onlar beni nasıl severdi.

Bir bilsen, Urfa''da kurşun atanı

Minareden, barikattan, 

Selvi dalından, 

Ölüme nasıl gülerdi.

Bilmeni mutlak isterim, 

Duyuyor musun? 

Öyle yıkma kendini, 

Öyle mahzun, öyle garip...

Nerede olursan ol, 

İçerde, dışarda, derste, sırada, 

Yürü üstüne - üstüne, 

Tükür yüzüne celladın, 

Fırsatçının, fesatçının, hayının...

Dayan kitap ile

Dayan iş ile.

Tırnak ile, diş ile, 

Umut ile, sevda ile, düş ile

Dayan rüsva etme beni.

Gör, nasıl yeniden yaratılırım, 

Namuslu, genç ellerinle.

Kızlarım, 

Oğullarım var gelecekte, 

Herbiri vazgeçilmez cihan parçası.

Kaç bin yıllık hasretimin koncası, 

Gözlerinden, 

Gözlerinden öperim, 

Bir umudum sende, 

Anlıyor musun?', 'Beşikler vermişim Nuh''a Salıncaklar, hamaklar,  Havva Ana''n dünkü çocuk sayılır,  Anadoluyum ben,  Tanıyor musun?  Utanırım,  Utanırım fıkar...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Arif']::text[], 8.5, '{"poet":"Ahmed Arif","poet_slug":"ahmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/anadolu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Aşk', 'yasak-ask-ahmet-selcuk-i-lkan-7lthj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmezdim böylesine uzun olduğunu gecelerin

Umutsuz günlerin hüznünü duymamıştım hiç

Uykumu böleceğini bu mutsuz düşüncelerin

Bilmezdim sevda nedir tatmamıştım hiç

Kederlerin en insafsızı benimle şimdi

Suskunluğum öylesine ölümden zor ki...

Çağırsan en uzak iklimlerden koşup geleceğim

Bir gülüşün dünyamı aydınlatacak en azından

Ve kucak açacağım en güzeline mutlulukların

Bir duysam aşkımı gözlerinden, dudaklarından...

Oysa sen de ben gibi mahzunsun biliyorum

Biliyorum yasak aşkımız bizi böyle susturan

Ne olur artık yeter bu idamlık hasretimiz

Bin yıl seveceğim bir umut versen inan...', 'Bilmezdim böylesine uzun olduğunu gecelerin Umutsuz günlerin hüznünü duymamıştım hiç Uykumu böleceğini bu mutsuz düşüncelerin Bilmezdim sevd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasak-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ve Gurur', 'ask-ve-gurur-ahmet-selcuk-i-lkan-czfht', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nereden bilecektin seni sevdiğimi

Hiç fısıldamadım ki kulaklarına aşkımı

Senin için

Günlerce gecelerce ağladım

Nereden bilecektin

Hiç silmedim ki yanında gözyaşlarımı...', 'Nereden bilecektin seni sevdiğimi Hiç fısıldamadım ki kulaklarına aşkımı Senin için Günlerce gecelerce ağladım Nereden bilecektin Hiç silmed...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-ve-gurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namus Belası', 'namus-belasi-cem-karaca-2evta', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düştüm maphus damlarına 

Öğüt veren çok olur

Toplasam o öğütleri

Burdan köye yol olur

Ana baba bacı gardaş

Dar günümde el olur

Namus belasına gardaş

Döktüğümüz kan bizim

Biz hepimiz Turhallıyız

Biz Bize benzeriz

Yüz bin kere tövbe eder

Gene şarap içeriz

At bizim avrat bizim

Silah bizim şan bizim

Namus belasına gardaş

Yattığımız dam bizim

Kız gelinim suna boylum

Doyamadan biz bize

Besmeleyle yüzünü açıp

Oturmadan diz dize

Almış kaçırmışlar seni

Çökertmişler ıssızca

Namus belasına gardaş

Verdiğimiz can bizim

Ağam kurban begim kurban

Hallarımı neyleyim

Ne bir eksik ne bir fazla

Hepsi tamam tamam söyledim

Kır kalemi kes cezamı

Yaşamayı neyleyim

Namus belasına gardaş

Yattığımız dam bizim', 'Düştüm maphus damlarına  Öğüt veren çok olur Toplasam o öğütleri Burdan köye yol olur Ana baba bacı gardaş Dar günümde el olur Namus belasın...', ARRAY['Türk Edebiyatı','Şiir','Cem Karaca']::text[], 8.5, '{"poet":"Cem Karaca","poet_slug":"cem-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/namus-belasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Gideyim', 'soyle-gideyim-rezzan-kafali-70fww', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umutlarım seni yordu gibiyse

Şiirlerim yangınını körüklemiş gibiyse

Bağışla beni, seni sevdim gibiyse

Kumlarını savurma

                      Şarkılarla söyle gideyim

Geceler bitmez çağrı gibiyse

Suskunluk çekilmez dert gibiyse

Bağışla beni, seni sevdim gibiyse

Ateşini savurma

                   Irmaklarla söyle gideyim

Görmeden sevmek sana yalan gibiyse

Şiirlerim yüreğini yakar gibiyse

Bağışla beni, seni sevdim gibiyse

Yıldızları savurma

                 Bulutlarla söyle gideyim', 'Umutlarım seni yordu gibiyse Şiirlerim yangınını körüklemiş gibiyse Bağışla beni, seni sevdim gibiyse Kumlarını savurma                     ...', ARRAY['Türk Edebiyatı','Şiir','Rezzan Kafalı']::text[], 8.5, '{"poet":"Rezzan Kafalı","poet_slug":"rezzan-kafali","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/soyle-gideyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-eyup-altay-kboto', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni  her andığımda

İçime bir hüzün çöker, 

Güneşin   batıp

Karanlığın çöktüğü gib.i

Sensizken bu dünyada, 

Seni yaşamak ölüm misali zor.

Tıpkı gökyüzünde,                                                                     

Kayan yıldızı durdurmak gibi.', 'Seni  her andığımda İçime bir hüzün çöker,  Güneşin   batıp Karanlığın çöktüğü gib.i Sensizken bu dünyada,  Seni yaşamak ölüm misali zor. Tı...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Altay']::text[], 8.5, '{"poet":"Eyüp Altay","poet_slug":"eyup-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilime Bu Türkü...', 'dilime-bu-turku-tayfun-talipoglu-v7oi7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dilime bu türkü yüreğime bu sevda düştü düşeli yollardayım

 gönlüme çoktan cemre düşürdüm 

seni sevmek için baharı beklemeyeceğim', 'dilime bu türkü yüreğime bu sevda düştü düşeli yollardayım  gönlüme çoktan cemre düşürdüm  seni sevmek için baharı beklemeyeceğim...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Talipoğlu']::text[], 8.5, '{"poet":"Tayfun Talipoğlu","poet_slug":"tayfun-talipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/dilime-bu-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Türküsü', 'deniz-turkusu-huseyin-taskin-abgok', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'müzik, kitap ve dostlar 

masa başı söyleşileri

zaman binmiş hayali atına

çeker dizginleri

gider gözlerimiz önünde 

nereden nereye

bilinmez 

bildiğimiz birşey varsa

bir parçamız içerde

bir parçamız dışarda

yaşadığımızdır

yıkılmış sözcükler

belleğimizin satırlarında

''ayıp günah'' vesaire

ama nedense

gitmez gözlerimizden

sökülüp de gitmez yüreklerimizden

ayrılık üzüntüsü

ve arasıra uğrar limanımıza

umut gözlü deniz türküsü', 'müzik, kitap ve dostlar  masa başı söyleşileri zaman binmiş hayali atına çeker dizginleri gider gözlerimiz önünde  nereden nereye bilinmez  ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Taşkın']::text[], 8.5, '{"poet":"Hüseyin Taşkın","poet_slug":"huseyin-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deniz-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kovalamaca', 'kovalamaca-abdulkerim-capar-qfcyo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kör-topal

Kan-ter içinde kovalarken bir şiiri

Yalçın kayalıklardan

Uykusuz gecelerden geçerken

Birden

Bir kuytuda rastlayıveririm bir parçana

İhtimal gözlerinin ışıltısıdır bu, 

Ellerinin sıcaklığıdır belki; 

Ya da inceden bir rüzgardır

Saçlarından kopup gelen.

İşte o an rolleri değişiriz şiirle

Artık ben onu değil

O beni kovalar...', 'Kör-topal Kan-ter içinde kovalarken bir şiiri Yalçın kayalıklardan Uykusuz gecelerden geçerken Birden Bir kuytuda rastlayıveririm bir parçan...', ARRAY['Türk Edebiyatı','Şiir','Abdulkerim Çapar']::text[], 8.5, '{"poet":"Abdulkerim Çapar","poet_slug":"abdulkerim-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kovalamaca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye takıldık', 'nereye-takildik-tarkan-kalkan-ug1z6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nereye takıldık

Yağmurlara teslimiyet 

Başlamadan bitiş niye

Ağladığını gördüm

Sen göremedin

Rüzgarlı bir zamansızlıktaydık

Yok var oluyordu

Ve ağlıyordun

Ciğerlerin acıyordu

Yüreğim dondu kaldı sana

Ağlıyordun

Haberin yoktu varlığımdan

Üşümüştün 

Ellerin mosmordu canım

Onlar göremezken

Ben oradaydım

Seni öylesine sardımki 

Kan kokuyordu yanakların

Gözlerine dokundum ya

Sen göremedin

Canım dedim

Bitanem

Benim güzel bebeğim

Kolların düştü yana

Başın bir yana

Sustu acıyan ciğerin

Ağladım

Ağladım

Bu muydu tüm gerçeğin', 'Nereye takıldık Yağmurlara teslimiyet  Başlamadan bitiş niye Ağladığını gördüm Sen göremedin Rüzgarlı bir zamansızlıktaydık Yok var oluyordu...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Kalkan']::text[], 8.5, '{"poet":"Tarkan Kalkan","poet_slug":"tarkan-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/nereye-takildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlar', 'yarinlar-erkan-koc-006i5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni tekrar görme ihtimalim, 

yarınlarda saklı

belki şu an gözlerin kör, belki şu an ölüsün, 

bir mezar taşın bile olmadan, 

bilmediğim bir yerlerde gömülüsün

Asla söz veremedim sana

anılarımızı sonsuza kadar yaşatacağıma dair

çünkü ölümüm tanrının ebediyete gömdüğü bir sır

yarınlarda saklı

yaşamaya çalışıyoruz buyruklara uyarak

geleceklerini kurmaya çalışan şimdiden yorgun gençler

ve hep yarına ertelenen sevinçler

günahlardan korkarak sürer hayatlarımız

oysa gelecek kitaplarda değil

yarınlarda saklı

seni seviyorum

asla söylemediğim sözlerim 

bir ağaç kabuğuna kazılmış ve

yastığımın altında saklı

bir gün gelir okursan sakın sorma ne zaman gelirim diye

ne zaman okursun? ne zaman seversin beni? 

ne zaman ölürüz? bir daha ne zaman görürüm seni? 

bana hiç bir şey sorma

ellerim kollarım bağlı

ne olacağını bilemem 

hayat yarınlarda saklı', 'seni tekrar görme ihtimalim,  yarınlarda saklı belki şu an gözlerin kör, belki şu an ölüsün,  bir mezar taşın bile olmadan,  bilmediğim bir ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Koç']::text[], 8.5, '{"poet":"Erkan Koç","poet_slug":"erkan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yarinlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-erkan-koc-be57f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni seviyorum bir dostun olarak

Bunu birçok kez söyledim yüzüne

Sen de seviyorsun belki

Sana aşığım

ve yemin ederim mutluyum seni böyle uzaktan

kendime bile aşkını fısıldayamadan

ikinci bir yürek gibi içimde yaşatmaktan

Belki de aşk böyle olmalı zaten

Dost dokunuşları arasında aranıp da bulunamamalı

Birgün bana aşık olman umudum olmamalı

Şu an olduğu gibi umutsuz olmalıyım

Ve yalnız.... seni hayatımın her dakikasında

Hiçbir çamura bulandırmadan, 

gözlerinin, gülüşünün milyonlarca fotoğraflı albümüyle

Yaşatmak için.

Mutluyum aşık olmayı becerebildiğim

Seni sevebildiğim için

Ve seni bu kadar sevdiğim halde

Başkasını deli gibi sevdiğini, 

Hep onun olacağını

Ve belki de birgün beni albümlerle, ses kayıtlarıyla yapayalnız bırakıp

Asla gidemeyeceğim yollara gidebileceğini görecek kadar

Cesur olabildiğim için

Hem zaten benim olmamanan gerek

Dudakların asla benim hayal ettiğim gibi öpemez

Rüyalarımda, 

Gözlerimden fışkıracak gibi çarpan yüreğim kadar

Hiçbir yerde hiçkimse

Seni sevemez

Bazı rüyalarımda

Çok ama çok sessiz, ıssız bir şehirde

Yürürken bulurum kendimi

Rüyalarım gibi seni sevmek, 

Issız bir şehirde yürürken

Her takırtıyı, her çığlığı, her ayak sesini

Ve her ''Seni'' 

Beynimin içinde hissetmek', 'seni seviyorum bir dostun olarak Bunu birçok kez söyledim yüzüne Sen de seviyorsun belki Sana aşığım ve yemin ederim mutluyum seni böyle uza...', ARRAY['Türk Edebiyatı','Şiir','Erkan Koç']::text[], 8.5, '{"poet":"Erkan Koç","poet_slug":"erkan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/seni-sevmek-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Defa', 'son-defa-sair-raven-5m3si', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçime çektim son defa, yıllarca sürdüğüm hasreti, 

Kollarımı açtım ve geceye verdim bedeni.

Düşüncelerim gergin, sözlerim de gecenin, 

Bir aşkın çığlığı ki bu; bir o kadar keskin, 

Artık sözlerimin en kuytularına bırakıyorum adını...', 'İçime çektim son defa, yıllarca sürdüğüm hasreti,  Kollarımı açtım ve geceye verdim bedeni. Düşüncelerim gergin, sözlerim de gecenin,  Bir a...', ARRAY['Türk Edebiyatı','Şiir','Şair Raven']::text[], 8.5, '{"poet":"Şair Raven","poet_slug":"sair-raven","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-defa-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Yelleri', 'sonbahar-yelleri-ensar-aktas-slwc6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedir senin dünyaya küsmüş, 

Çıkmazlara düşmüş bu soğuk hallerin

Batırmışsın güneşi, 

Karanlığa bürünmüş kahverengi gözlerin

İçine kilitlemişsin tebessümlerini gülüşlerinin

Bir de bırak beni, bırakta öldüreyim

İçindeki beni, yüreğimdeki seni dersin

Bilmez misin anahtarı bendedir

Dibine sevdamızı, umutlarımızı hapsettiğin kafesin

Nedir esrarı şu güzelim bahar gününde estirdiğin

Ölüm soğuğuna meydan okuyan sonbahar yellerinin

Bilmez misin yüreğimden koparıp soldurduğunu

Dallarından koparıp ayaklar altına savurduğun

Her biri sayende yeşile küsmüş sarı yaprakların, çiçeklerin

Bilmez misin yetim bıraktığını beni, 

Aşkından, sevdandan, senden…

Seni ise benden, ve… 

Senden başkasına yar etmeyeceğim kadersiz sevgimden

Bu bana içini dökmek yerine, 

Suskunluğu seçmeye, 

İçine kapanmaya çalıştığın bahtlar karası hallerinin

Bilmez misin seni benden uzaklaştırmak bir yana

Beni sonumun arka kapısına yaklaştırdığını, 

Ölüm denen bilinmezin, meçhul dönülmezin

Bilmem eksi kaç derece soğukluğunu tattırdığını

Nedir sebebi şu güzelim bahar gününde estirdiğin

Ölüm ayazına meydan okuyan sonbahar yellerinin

Bu sevda böyle bitmez, bitmemeli, bitmeyecek

Sen bitirdikçe ben yeniden başlatacağım, 

Eskisinden daha sıcak, bir öncekinden daha ateşli

Ve bu ateşi söndürmeye gücü yetmeyecek

Ne senin, ne de…

Manasızca estirdiğin o cılız sonbahar yellerinin

Rotterdam,22.04.2002', 'Nedir senin dünyaya küsmüş,  Çıkmazlara düşmüş bu soğuk hallerin Batırmışsın güneşi,  Karanlığa bürünmüş kahverengi gözlerin İçine kilitlemi...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sonbahar-yelleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Oku', 'guzel-oku-hasan-feyzi-813or', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel oku! Her zerrede coşkun birer mânâ var, 

Derd ehline bu mânâda canlar sunan edâ var.

Vermek için parlaklığı, gamlı gönül evine, 

Bir bak hele, her cilâdan üstün olan cilâ var.

Derin, güzel düşünce ile incelersen bunu sen, 

Zaiflemiş ruhlar için dağlar gibi gıdâ var.

Hem dilersen, tükenmeyen sermaye-i serveti, 

Aç gözünü Nurlara bak, işte sana tûfan gibi gına var.

Beni tanı, yürü kulum, yürü diye bizlere, 

Her nefeste şefkat ile Rabbimizden nidâ var.

Duymuş isen bu nidâyı her zerrenin dilinden, 

Müjde olsun, artık sana Cennet denen safâ var! 

Uzaklara bakma! ''Nurlara bak, yürü! '' lem Onun âyinesi; 

Görmez misin, her yüzünde aynı renkte ziya var.

Bir güneştir her zerrede cilve yapıp parlayan; 

Bilmez misin, sende dahi o edâdan edâ var.

Eller açıp yürü bugün kana kana Risale-i Nurdan ışık al! 

Aşka uyan, nura kanan her zerrede rehâ var, 

Hüner değil; dostu, düşman; yârı, ağyâr eylemek; 

Yâdı biliş yapasın ki, ancak dostta vefa var.

Hünerdir ki; yaprak, atlas; toprak, elmas olmalı! 

Çünki bir bak, ne yaprakta ne toprakta beka var.

Kısa görüp denizleri damlalara çevirme; 

Hakikatta, her damlada gizli birer derya var.

Damla iken aslın senin, dağı taşı aşarsın, 

Hem gökleri keşfedersin, sende ey Nur, böyle dehâ var.

Bir noktayı bir cihan yap, o cihana hâkim ol, 

Zira senin bir noktanda, güneş kadar zekâ var! 

Her zerrenin kâbesidir kalbi, yine kendine, 

Dikkat eyle, herbirinde yine ancak Huda var.

Sakın Feyzî! . Sen gözünü hak yüzünden ayırma, 

Hakkı gören gerçeklere, hakkı kadar atâ var.', 'Güzel oku! Her zerrede coşkun birer mânâ var,  Derd ehline bu mânâda canlar sunan edâ var. Vermek için parlaklığı, gamlı gönül evine,  Bir b...', ARRAY['Türk Edebiyatı','Şiir','Hasan Feyzi']::text[], 8.5, '{"poet":"Hasan Feyzi","poet_slug":"hasan-feyzi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/guzel-oku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Şiiri', 'ayrilik-siiri-hasan-feyzi-lhver', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çekilip nur-u hidayet yine zindan olacak! 

Yine firkat, yine hasret, yine hüsran olacak.

Yine sen, yaş yerine kan akıtıp ağla gözüm..

Çünki hicran dolu kalbim yine hicran olacak.

Yine göç var diye mecnûna haber verme sakın! 

Yine matem, yine zâri, yine efgan olacak.

Açılan ol gül-ü tevhid, sararıp solsa gerek; 

Kapanıp Kâbe-i irfan, yine vîran olacak.

Haber aldım ki yarın yad olacakmış bize yâr, 

Ne büyük yâre ki, kimler buna derman olacak? 

Bu büyük derd-i elemden kime şekva edeyim? 

İşiten nâlemi, hep ben gibi nâlân olacak.

O şifa-bahş olan envarını sen çeksen eğer, 

Bana kim nur verecek, kim bana Lokman olacak? 

O temiz pak nefsin, âb-ı hayatı bu çölün; 

Onu, dûr etme ki her ferd ona reyyan olacak.

Hele ol nur-u şerifin kime değmişse eğer, 

Küçücük zerre de olsa, mehî taban olacak.

O lütufkâr, o keremkâr eli öptükçe, benim

Bu küçük kalb-i hazinim yine handan olacak.

Bab-ı feyzinden ırak olmayı asla çekemem, 

Dahi nezrim bu ki canım sana kurban olacak.

Nazarın erse garib başıma ey nur-u Hüda, 

Bu gün artık bu hakir bendede umman olacak.

Bu anasır, yüzüne her ne kadar çekse hicab; 

Yine haksın, buna şahid yine Kur''an olacak.

Kab-ı Kavseynden alıp dersimi bildim ki ayân, 

O güzel nur-u bedi'', mânevî sultan olacak.

Sakınıp, Feyzi-i bîçareye bahs açma bu gün; 

Yeni baştan yine şeyda, yine giryan olacak.', 'Çekilip nur-u hidayet yine zindan olacak!  Yine firkat, yine hasret, yine hüsran olacak. Yine sen, yaş yerine kan akıtıp ağla gözüm.. Çünki ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Feyzi']::text[], 8.5, '{"poet":"Hasan Feyzi","poet_slug":"hasan-feyzi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ayrilik-siiri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin Telaşı', 'guvercin-telasi-nevzat-gurmen-78qw6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'güvercin telaşıyla

tüketiyoruz yaşamı.

adımlar ürkek, 

yürekler kıpır kıpır.

tomurcuklanıyor

günbatımı geceye.

kimbilir nerede, 

gündoğumu nelere gebe.

örselenmiş hayatların

güvensizliğinde

ürkek bir güvercin telaşı

yaşadığımız.', 'güvercin telaşıyla tüketiyoruz yaşamı. adımlar ürkek,  yürekler kıpır kıpır. tomurcuklanıyor günbatımı geceye. kimbilir nerede,  gündoğumu n...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guvercin-telasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Günlerim', 'cocuk-gunlerim-oguzkan-bolukbasi-om1s6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nisan yağmurları kısa sürerdi

Karabulutlar sarmazdı gökyüzünü

Güneş ağlıyor gibi olurdu, sıcak günlerdi

Tek çiçekli, çok çocuklu bahçelerdi bizim evler

Basma entarili teyzeler, akşamüstleri çay içerlerdi evönlerinde

Dantel işlerlerdi, 

En uzun günlerdi pazarları

O güne sarkardı bebelerin yıkanmaları

Hasta olmamak için evhapsinde sokaklar boş

Sizi ne çok sevmiştim çocuk günlerim

Henüz yürümemişken damarlarıma hoyrat sürgünlerim

Yok oldunuz o nisan yağmurları gibi

Ayıp ettiniz

Dedelerimi, ninelerimi, dayımı alıp gittiniz

Ne oldu sanki herşey daha mı güzel

Dantellerde, nakışlarda renkler daha mı parlak

Dünya daha mı yuvarlak

Hadi canım sen de………', 'Nisan yağmurları kısa sürerdi Karabulutlar sarmazdı gökyüzünü Güneş ağlıyor gibi olurdu, sıcak günlerdi Tek çiçekli, çok çocuklu bahçelerdi ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cocuk-gunlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçilmiyor', 'vazgecilmiyor-bunyamin-eroglu-07yvr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretinden dolan göz yaşlarımı

Gönlüme dökerek vazgeçilmiyor

Vazgeçilmiyor vazgeçilmiyor

Aşkımın şahidi bakışlarını

Hülyaya vererek vazgeçilmiyor

Vazgeçilmiyor vazgeçilmiyor

Aşkından olmuşum deli

Sen istersen bitir beni

Düşündükçe bu can seni

Vazgeçilmiyor

Vazgeçilmiyor vazgeçilmiyor

Aramakla bulunmaz sen gibi canlar

Hasretin içimi köz gibi dağlar

Köz gibi dağlar köz gibi dağlar

Sen gül oyna, bense giyem karalar

İnan senin için vazgeçilmiyor

Vazgeçilmiyor vazgeçilmiyor', 'Hasretinden dolan göz yaşlarımı Gönlüme dökerek vazgeçilmiyor Vazgeçilmiyor vazgeçilmiyor Aşkımın şahidi bakışlarını Hülyaya vererek vazgeçi...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Eroğlu']::text[], 8.5, '{"poet":"Bünyamin Eroğlu","poet_slug":"bunyamin-eroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vazgecilmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Sabahının Serinliğini...', 'eylul-sabahinin-serinligini-ataol-behramoglu-pxl3g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'eylül sabahının serinliğini

Yaprakların serinliğini

Ciğerlerime dolduruyorum

Sessizlik ve serinlik

Birleşiyor

Yıkanmış güvercinler

Ve çok uzakta bir tren sesi

Her zaman yeniden başlamak duygusu

Doğuyor içimde

Her uyanışımda

Düşmanlarımı bağışlıyorum

Daha çok seviyorum dostlarımı

Her uyanışımda

Eylül sabahının serinliğini 

Yaprakların serinliğini

Yüreğime dolduruyorum

(1976)', 'eylül sabahının serinliğini Yaprakların serinliğini Ciğerlerime dolduruyorum Sessizlik ve serinlik Birleşiyor Yıkanmış güvercinler Ve çok uz...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eylul-sabahinin-serinligini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Öyle Sevdim Sevdim Seni', 'i-ste-oyle-sevdim-sevdim-seni-murat-gogebakan-q12sj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir hayalin var bende 

Bir sen varsın içimde

Bırakıp gitsen beni böyle

sen varsın hala içimde

Kar altında buz gibi

Cehennemde tuz gibi

Yürekte ateş gibi

İşte öyle sevdim seni', 'Bir hayalin var bende  Bir sen varsın içimde Bırakıp gitsen beni böyle sen varsın hala içimde Kar altında buz gibi Cehennemde tuz gibi Yürek...', ARRAY['Türk Edebiyatı','Şiir','Murat Göğebakan']::text[], 8.5, '{"poet":"Murat Göğebakan","poet_slug":"murat-gogebakan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iste-oyle-sevdim-sevdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlı', 'delikanli-sair-nurican-671zv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdi o hep, yürekten sevdi

İhanete uğradı

Bıraktı tek kalemde boynunu eğdi.

Parası yoktu belki; 

Parasıyla değil yüreği ile sevdi, sevildi

Hem de çok sevildi

Belki sevdiğini cafelere götüremedi

Ama satmadı sevdasını yüreğine attı

Haklının  yanında idi

Haksıza demir bir yürekti yıkılmadı

Delikanlıydı  O...

Üç şeyi çok severdi bırakamadı 

Yarini, sigarısını birde silahını...

Kısa Camel  içerdi parası varken, yokken nadiren maltepe

İki mekanı çok severdi

Biri her  zaman gittiği çay ocağı

Biri onunla durduğu ağacın altı

Dostları vardı delikanlısın 

Belki kendisinden çok daha delikanlılardı onlar 

Çok severdi dostlarını 

Yağmurda yürümeyi birde O’nu çok severdi

O iki alışkanlığı hiç bırakamadı

Duygusaldı, ağlamayı çok severdi

Ama hep yalnız ağlardı.

O’ndan başka kimse görmedi delikanlının  ağladığını 

O’ndan başkası silmedi, gözlerinden dökülen yaşları

Öyle büyük bir aşkla seviyordu ki unutamadı

Ne birkaç günlük nede birkaç günlüktü onunkisi

Bir ömür adını kalbine yazmıştı

Satmadı asla sevdasını 

Çok acı çekti ama hiç ezilmedi 

Belki boynu bükük gezerdi

Ama yüreği hiç bükülmedi 

Her zaman dimdik ayakta idi 

Dik yürüyüp yürekten olmaktansa

Boynun bükük yürüyüp, demir bir yürek taşımayı arzu etti.

Hep unutulmak korkusu ile yaşadı

Ve hep sevdiğini düşünüp ağladı

Korkma delikanlı, O seni unutmadı

Hiç unutmayacak.

Çünkü O da seni sevdi, sevecek

O büyük aşkını kalbinden hiç silmeyecek', 'Sevdi o hep, yürekten sevdi İhanete uğradı Bıraktı tek kalemde boynunu eğdi. Parası yoktu belki;  Parasıyla değil yüreği ile sevdi, sevildi ...', ARRAY['Türk Edebiyatı','Şiir','Şair Nurican']::text[], 8.5, '{"poet":"Şair Nurican","poet_slug":"sair-nurican","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/delikanli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmiyor Sevgilim', 'yetmiyor-sevgilim-sair-nurican-3wlvf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cebimde resmine bakıp avunmak

Yazdığın mektupları okuyup durmak

Her gece seni düşlerimde yaşamak

Yetmiyor sevgilim yetmiyor bana

Yaz günüm dağlarım tek sevgilim 

Hasretim fırtınam özler bedenim

Bir anlık yokluğun ölüm nedenin 

Günde bir kez görmek yetmiyor sevgilim.

Kolların boynumu sarmadıkça 

Nefesim yüzümü okşamadıkça 

Her gece koynumda uyumadıkça

Yetmiyor sevgilim yetmiyor bana', 'Cebimde resmine bakıp avunmak Yazdığın mektupları okuyup durmak Her gece seni düşlerimde yaşamak Yetmiyor sevgilim yetmiyor bana Yaz günüm d...', ARRAY['Türk Edebiyatı','Şiir','Şair Nurican']::text[], 8.5, '{"poet":"Şair Nurican","poet_slug":"sair-nurican","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yetmiyor-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-sair-nurican-wj5ag', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elleri cebinde hali perişan 

Birini görürsen beni hatırla

Feleğe küsmüş hali perişan 

Birini görürsen beni hatırla 

Umudu hayata kaybolup sönen 

Neşesi acıyla nefrete dönen 

İnliye inliye ölmeden ölen

Bir mecnunu görürsen beni hatırla 

Hayata küsüp her gün ağlayan 

Çaresi derdine derman arayan 

Üzerine dikenli teller bağlayan 

Bir dertli görürsen beni hatırla', 'Elleri cebinde hali perişan  Birini görürsen beni hatırla Feleğe küsmüş hali perişan  Birini görürsen beni hatırla  Umudu hayata kaybolup sö...', ARRAY['Türk Edebiyatı','Şiir','Şair Nurican']::text[], 8.5, '{"poet":"Şair Nurican","poet_slug":"sair-nurican","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beni-hatirla-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunluk', 'yorgunluk-can-yucel-akzu9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuşlar vardır, cana benzer havalarda: 

Soğuksa kar, baharsa yaprak; 

Bir başına büyür toprakta ömrümüz, 

Güneşle yeşil elleriyle çıplak; 

-Uslu ayaklarla başlamış yolculuk-

Yürünmez öyle, bazen durulur, 

Ve iner erenler katına yorgunluk; 

Kapanır sükun üzre kitaplar.

Nefeslerle sürüp giden yaşamamız

Bir su kenarına gelir durur; 

Ekmekten, şaraptan öte nimetler vardır; 

Yürünmez öyle hep, bazen susulur.', 'Kuşlar vardır, cana benzer havalarda:  Soğuksa kar, baharsa yaprak;  Bir başına büyür toprakta ömrümüz,  Güneşle yeşil elleriyle çıplak;  -U...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yorgunluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emelim', 'emelim-yasar-aksit-1o3by', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl olsa gidecegim bu yerden, 

Emelim seninle gitmek, 

Var gücümle gitmek için direnecegim, 

Rahat ol, sen kal dersen kalacagım, 

İncitmek, kırmak istemem seni, 

Yalvarırım allaha affetsin beni, 

Emelim ömür boyu sevmektir seni...', 'Nasıl olsa gidecegim bu yerden,  Emelim seninle gitmek,  Var gücümle gitmek için direnecegim,  Rahat ol, sen kal dersen kalacagım,  İncitmek...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akşit']::text[], 8.5, '{"poet":"Yaşar Akşit","poet_slug":"yasar-aksit","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/emelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naze', 'naze-murat-gogebakan-x2f5e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beklerem yollarını

Hey naze, hey hey naze

Darda koyma canımı

Hey naze, hey hey naze

Hayırsızın gelini

Hey naze, hey hey naze

Darda koyma canımı

Hey naze, hey hey naze

Hey naze, vay naze, oy naze, can naze

Nazeeeeeeee

Naze gözün karası

Hey naze, hey hey naze

A bu Gönül yarası

Hey naze, hey hey naze

Darda koyma canımı

Hey naze, hey hey naze

Hayırsızın gelini

Hey naze, hey hey naze

Hey naze, vay naze, oy naze, can naze

Nazeeeeeeeeeeeee', 'Beklerem yollarını Hey naze, hey hey naze Darda koyma canımı Hey naze, hey hey naze Hayırsızın gelini Hey naze, hey hey naze Darda koyma can...', ARRAY['Türk Edebiyatı','Şiir','Murat Göğebakan']::text[], 8.5, '{"poet":"Murat Göğebakan","poet_slug":"murat-gogebakan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/naze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-murat-gogebakan-7fnrm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne günahım vardı yar

Ne kusur işledim söyle kurban

Ne günahım vardı yar

Ne kusur işledim söyle kurban

Ey yüreğimin sahibi

Ciğer parem, ciğer gözlümsün sen

Gitme, gitme yokluğuna alışamam ben

Gitme, gitme ayrılığa dayanamam ben

Gitme, gitme yokluğuna alışamam ben

Gitme, gitme ayrılığa dayanamam ben', 'Ne günahım vardı yar Ne kusur işledim söyle kurban Ne günahım vardı yar Ne kusur işledim söyle kurban Ey yüreğimin sahibi Ciğer parem, ciğer...', ARRAY['Türk Edebiyatı','Şiir','Murat Göğebakan']::text[], 8.5, '{"poet":"Murat Göğebakan","poet_slug":"murat-gogebakan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gitme-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turnalar', 'turnalar-murat-gogebakan-vwlve', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda tünelinde

Ah ne acılar çektim ben

Bu aşk uğruna ben

Ne ölümler gördüm ben

Oy bir aşk uğruna ben

Ne ölümler gördüm ben

Turnalardan haber verin

Yari çok özledim ben

Gecenin sessizliği

Dağların ıssızlığı

Bir de senin yokluğun koy üstüne

Gör benim neler çektiğimi

Bir de senin yokluğun koy üstüne

Duy benim neler çektiğimi

Turnalardan haber verin 

Yari çok özledim ben', 'Sevda tünelinde Ah ne acılar çektim ben Bu aşk uğruna ben Ne ölümler gördüm ben Oy bir aşk uğruna ben Ne ölümler gördüm ben Turnalardan habe...', ARRAY['Türk Edebiyatı','Şiir','Murat Göğebakan']::text[], 8.5, '{"poet":"Murat Göğebakan","poet_slug":"murat-gogebakan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turnalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün', 'bu-gun-murat-gogebakan-ojsey', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün yari gördüm ben

Elinde başka bir el var

Bugün yari gördüm ben

Yüreğinde başka bir yürek var

Bugün yari gördüm ben

Gitmiş elin olmuş

Bugün yari gördüm ben

Gitmiş elin olmuş

Azrail kapım dayansın

Dostlarım yas tutsun

Azrail kapım dayansın

Dostlar yas tutsun

Ölüm haberim gelsin

Yar gitmiş elin olmuş

Ölüm haberim gelsin

Yar gitmiş elin olmuş', 'Bugün yari gördüm ben Elinde başka bir el var Bugün yari gördüm ben Yüreğinde başka bir yürek var Bugün yari gördüm ben Gitmiş elin olmuş Bu...', ARRAY['Türk Edebiyatı','Şiir','Murat Göğebakan']::text[], 8.5, '{"poet":"Murat Göğebakan","poet_slug":"murat-gogebakan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-gun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Tanımasaydım Seni', 'keske-tanimasaydim-seni-murat-gogebakan-bodxi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Keşke tanımasaydım seni

Omuzlarıma bu kadar yük binmezdi ozaman

Gözlerim ağlamayı bilmezdi

O kadar sık kalbim çarpmazdı böyle delicesine, 

Benim de ellerim sım sıcak olurdu mutlaka

Geceleri asla uykusuzluk çekmezdim sabaha kadar

Rüyalarım hatta tatlı hayellerim olurdu 

duygusuzca düşünmezdim yokluğunda günlerimi saatleri hep

Hiç üşümezdim böylesine ölü soğukluğunda

Hırsım takip etmezdi beni, kötü kader

kan çanağında dönmezdi gözlerimin ta içi.

Kayan yıldızlardın bende farklı dilekler tutardım, 

Duyardım, anlardım yanımda konuşulanı, 

Hayretim bu kadar artmazdı ozaman 

bende gülerdim zaman zaman

Deniz ve mehtap benim için önemli olurdu.

Hele kara saplı bıçak dostum olmazdı sırtımda

Güneşsiz dünyamda kavrulmazdı ciğerim

Beynim ise böylesine hırçın ağlamazdı.

kar yüreğime damla damla vurmazdı.

Göz yaşım ruhumu daraltmazdı, benliğimi sıkıştırmazdı.

En tiz sesiyle çığlıklar atmazdı göysüm.

Sim siyah yankılar oluşmazdı uykumda.

Saçıma sakalıma bende bakardım.

Delicesine bütün gücümle sigaramı çekmezdim.

Ya da keşke tanımasaydım seni...

Keşke...

kara saplı dostum olmazdı

Kar yüreğimde damla damla vurmazdı göz yaşlarım.

Dedim ya ulan 

KEŞKE TANIMASAYDIM SENİ...', 'Keşke tanımasaydım seni Omuzlarıma bu kadar yük binmezdi ozaman Gözlerim ağlamayı bilmezdi O kadar sık kalbim çarpmazdı böyle delicesine,  B...', ARRAY['Türk Edebiyatı','Şiir','Murat Göğebakan']::text[], 8.5, '{"poet":"Murat Göğebakan","poet_slug":"murat-gogebakan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/keske-tanimasaydim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek İstedim', 'olmek-i-stedim-erkan-koc-86u7x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün ölmek istedim

Utandım kendimden ve sizden

Taktığım maskelerden

Oynadığım oyunlardan

Dünyadan utandım

Bugün ölmek istedim

Durakta bir çocuk ilişti yanıma

Bir ekmek parası dedi

Başka param yoktu ki vereyim

Gözlerimi kaçırdım ve sustum

Bugün ölmek istedim

Nefretim fışkırıyordu gözlerimden

Gözlerinize bakamadım

Aşkını bile bir kenara attım

Utandım senden

Bu kadar sevdiğim halde

Başkasının olduğun için

Bugün ölmek istedim

Hava kapalıydı, yağmur vardı

Maskeler yerine yüzünüzü gizleyen

Şemsiyeler vardı

Zabıtadan kaçarken döküldü

Bir küçüğün sattıkları

Nefret ettim kendimden ve sizden

Islak bir çocuğun yüreğini ezdiler

Ben bakakaldım

Bugün ölmek istedim

Küçük bir not sıkıştırıp kapıya

Ve birkaç küfür edip tanrıya

Kesip boğazımı

Bağıra bağıra boşaltmak istedim

İçimdeki şeytanın kanını', 'Bugün ölmek istedim Utandım kendimden ve sizden Taktığım maskelerden Oynadığım oyunlardan Dünyadan utandım Bugün ölmek istedim Durakta bir ç...', ARRAY['Türk Edebiyatı','Şiir','Erkan Koç']::text[], 8.5, '{"poet":"Erkan Koç","poet_slug":"erkan-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/olmek-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ter Beni', 'ter-beni-asik-sefai-fgvtf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül dünyasına gidip dönenlerden sor beni 

Belki aktır belki kara tutar söyler der beni 

Muhabbetin sofrasında kurduk büyük kaleyi 

Şu nefsime fırsat verme, fırsat bulup yer beni. 

Gece gündüz her dakika senin için harabım 

Beni böyle susuz koyan içmediğim şarabım 

İster taş de, ister kaya senin için turabım 

Kapılara, eşiklere, yollarına ser beni. 

Dizlerimde dermanım var biraz zaman ver gayrı 

Yüce dağlar belli olsun başa duman ver gayrı 

Aşık Sefam yalvarıyor yarab iman ver gayrı 

Her dem Allah derim amma niye basmaz ter beni.', 'Gönül dünyasına gidip dönenlerden sor beni  Belki aktır belki kara tutar söyler der beni  Muhabbetin sofrasında kurduk büyük kaleyi  Şu nefs...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ter-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim Diyebilsem', 'sevgilim-diyebilsem-i-rfan-topcu-en9kd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dilimin yok hecesi, 

gözlerim şimdi asi.

bu ses gönlümün sesi, 

sevgilim diyebilsem.

kırılmış kalbimin içi, 

çekilmez bu gidişi.

hücremin diriişi, 

sevgilim diyebilsem.

uzattım ellerimi, 

sana versin kalbimi.

anlasan bir halimi, 

sevgilim diyebilsem.

matem ömrün yerısı, 

ah bu gönül ağrısı.

şimdiki yaygarası, 

sevgilim diyebilsem.

sabır ile çekerim, 

bitecekse kederim.

muradım ise benim, 

sevgilim diyebilsem.

eren olup uçmayıp, 

diyar, diyar kaçmayıp.

cesareti toplayıp, 

sevgilim diyebilsem.', 'dilimin yok hecesi,  gözlerim şimdi asi. bu ses gönlümün sesi,  sevgilim diyebilsem. kırılmış kalbimin içi,  çekilmez bu gidişi. hücremin di...', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgilim-diyebilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus', 'yunus-asik-sefai-pa5sy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dergahı şah olan Taptuk Gönlüne 

Varmayan yollarda olur mu Yunus, 

Tek bir ses ile seher vaktinde 

Esmiyen yollarda olur mu Yunus. 

Namert insanların gece düşünde 

Haram sofralarında ekmek aşında 

Suları kurumuş pınar başında 

Turnasız göllerde olur mu Yunus 

Kibirli gönülde, görmeyen gözde 

Kırılmış kabukta, bozulmuş özde 

Destursuz mekanda, manasız sözde 

Şükürsüz dillerde olur mu Yunus. 

Fitnede, fesatta, yuva bozanda 

Ham olanı pişirmeyen kazanda 

Ustasız aşıkta, cahil ozanda 

İnançsız tellerde olur mu Yunus. 

Aşık Sefa-i''yem anında ara 

Yanında, canında, kanında ara 

Aşk Ocağında yananda ara 

Savrulan küllerde olur mu Yunus.', 'Dergahı şah olan Taptuk Gönlüne  Varmayan yollarda olur mu Yunus,  Tek bir ses ile seher vaktinde  Esmiyen yollarda olur mu Yunus.  Namert i...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yunus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Hesap Sorulacak', 'bu-hesap-sorulacak-asik-sefai-cz1se', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yiğit olanın lokması cana azıktır beyler 

Kimse bana söylemesin buna yazıktır beyler 

Soyu soysuz olanın sütü bozuktur beyler 

Bunların soyu bozulmuş Türk''e düşman göbekten 

Bu hesap sorulacak Apo denen köpekten! 

Kan istediniz canlardan bitmedi inadınız 

Oğuz size yar olmadı budüz idi adınız 

Senelerdir bu vatanın ekmeğini yediniz 

Suyunuzu keseceğiz dağlardaki gölekten 

Bu hesap sorulacak Apo denen köpekten! 

Dağlar, taşlar bu ovalar bilin ki Türk''ün yurdu 

Aslımız insan neslidir Türk''e semboldür Kurd''u 

Soyu ermeni olanlar nerden bilecek Kürd''ü 

İhaneti seyreyleyin perdedeki delikten 

Bu hesap sorulacak Apo denen köpekten! 

Alperenler şehadeti seslenirken çağrına 

İbrahim''in dedikleri nişan oldu bağrına 

Mehmetçik''ler şehit düştü bu vatanın uğruna 

Vatan mı istediniz lan beşikteki bebekten? 

Bu hesap sorulacak Apo denen köpekten! 

Başı bozuk yaylalarda bol keseden savurdun 

Ne dinin var, ne imanın sen ne biçim gavurdun? 

Hem korkaksın, hem zavallı zoru gördün kıvırdın! 

Urgan bile dava eder boynundaki ilmekten! 

Bu hesap sorulacak Apo denen köpekten!', 'Yiğit olanın lokması cana azıktır beyler  Kimse bana söylemesin buna yazıktır beyler  Soyu soysuz olanın sütü bozuktur beyler  Bunların soyu...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-hesap-sorulacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkmen Ağam', 'turkmen-agam-niyazi-yildirim-gencosmanoglu-oagb2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlar dağımdır benim

Gam ortağımdır benim

Söyletme çok ağlarım

Yaman çağımdır benim.''

Dündar Taşer''in büyük hâtırasına...

İşit beni, dinle beni, duy beni...

Eylendirmez dügün, dernek, toy... beni.

Yar beni hey... dil beni hey..oy beni...

Dündar Ağam, bizi koyup gitti bil! ...

Uçmağ içre bir menzile yetti bil! ...

Ülkü yolu diken olur, taş, olur, 

Yağsız ayran, kuru ekmek aş olur...

Kim derdi ki, Ağama bir iş olur? ? ? 

Kahpe felek bize oyun etti bil! ...

Attıgı taş bağrımıza battı bil! ...

Uluna da Bozkurtlarım, uluna...

Uluna da ince aylar doluna...

Gafil durup güvenirsen soluna

Başın üzre sefil baykuş öttü bil! ...

Vatanını iki pula sattı bil! ...

Tanrı bilir, dün de bizim, yarın da...

Bir gün olur; bir sabah tan yerinde, 

Dalgalanır dokuz tuğ gönderinde...

Türkmen Ağam nağrasını attı bil! ...

Otağ kurup gölgesine yattı bil! ...

Yol demeyem, yel demeyem, yürüyem...

Göğüs verem, şu dağları kürüyem...

Ben Oğuz''un dediği Gök Börü''yem...

Yine doğum sancılarım tuttu bil! ...

Tanrıdağ''da ''kalk'' borusu öttü bil! ...

Sanmayın bu, ağlama ya ağıttır.

Bu, Ağamın kavlince bir ögüttür.

Ağlamak ne? Dündar Ağam şehiddir

Ağlar olsan kaşlarını çattı bil! ...

Oraları birbirine kattı bil! ...', 'Dağlar dağımdır benim Gam ortağımdır benim Söyletme çok ağlarım Yaman çağımdır benim.'' Dündar Taşer''in büyük hâtırasına... İşit beni, dinle ...', ARRAY['Türk Edebiyatı','Şiir','Niyazi Yıldırım Gençosmanoğlu']::text[], 8.5, '{"poet":"Niyazi Yıldırım Gençosmanoğlu","poet_slug":"niyazi-yildirim-gencosmanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/turkmen-agam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Döneceğim', 'sana-donecegim-i-rfan-topcu-ixdcg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nasıl olsa geleceğim, 

kadir kıymet bileceğim, 

sen öldürme öleceğim, 

birgün sana döneceğim.

firar değil benimkisi, 

kalbimde isyanın sesi.

inanki en önemlisi, 

birgün sana döneceğim.

saklı yanımız kalmadı, 

herkes duydu sır olmadı, 

gözlerinmi yolda kaldı.

birgün sana döneceğim.

neden böyle kaçak göçek, 

sebebini kim bilecek, 

olsem bile dirilerek, 

birgün sana döneceğim.

suya yazı yazmak için, 

acıdan vaz geçmek için, 

nasıl olsa allah için, 

birgün sana döneceğim.', 'nasıl olsa geleceğim,  kadir kıymet bileceğim,  sen öldürme öleceğim,  birgün sana döneceğim. firar değil benimkisi,  kalbimde isyanın sesi....', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-donecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevin Büyükler', 'sevin-buyukler-ahmet-sivri-x0ygo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlık var olup sürene kadar

bütün çocukları sevin büyükler

yaşı   onbeşine  erene kadar 

bütün çocukları sevin büyükler

İsmine  rengine  ülke ırkına

yırtık papucuna samur kürküne

zengin fakir deyip bakma farkına

bütün çocukları sevin büyükler 

ister köylü olsun isterse  kentli 

avrupa   afrika   asyalı   hintli 

hepsi pırıl pırıl tertemiz tatlı 

bütün çocukları sevin büyükler 

kimi yavru ceylan kimisi koçtur 

derde  deva  en  şifalı  ilaçtır

eşleri yuvaya baglayan güçtür

bütün çocukları sevin büyükler 

meyvesiz agaçtır çocuksuz aile 

çölleşmiş bir kumsal çiçeksiz yayla

böyle gelmiş deyip gitmesin böyle 

bütün çocukları sevin büyükler 

şevkate  muhtaçtır  sevgi  pınarı 

göklerde melektir cennette peri

 garip ahmetim der düşünme gayrı

 bütün çocukları sevin büyükler', 'İnsanlık var olup sürene kadar bütün çocukları sevin büyükler yaşı   onbeşine  erene kadar  bütün çocukları sevin büyükler İsmine  rengine  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sivri']::text[], 8.5, '{"poet":"Ahmet Sivri","poet_slug":"ahmet-sivri","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevin-buyukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Bir Türkü’ye', 'yine-bir-turku-ye-edip-cangonul-6kwtj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'He Celal’im

        Diyarbakırlım

                Sesigüzelim

“bülbülün kanadı sarı”

da

benim yok

kenar dursun uçmak

lal olmuşum

        diyemiyorum

çolak olmuşum

         yazamıyorum

hele ki

nasıl aşılsın dağlar

     bu topal ayaklarla 

           ve bu korkak yürekle

“bülbülün kanadı yeşil”

yürek kızıla boyalı

benzim solmuş

kül olmuşam caney

umutlar Van Gogh sarısı', 'He Celal’im         Diyarbakırlım                 Sesigüzelim “bülbülün kanadı sarı” da benim yok kenar dursun uçmak lal olmuşum         diy...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yine-bir-turku-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorumm İştee', 'i-stiyorumm-i-stee-mehmet-karakulak-9nyq4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ağlamak istiyorum.

yok yok gülmek, 

bilmem belki de; 

ağlarken gülmek

içmek istiyorum.

sarhoş olmak, 

yok yok içmeden; 

kendimi kaybetmek

yaşamak istiyorum.

sarhoş olmak, 

yok yok ölmek; 

ölüm nedir ki

sevmek istiyorum.

yok yok sevilmek, 

severken sevilmek; 

ne bileyim işteee...', 'ağlamak istiyorum. yok yok gülmek,  bilmem belki de;  ağlarken gülmek içmek istiyorum. sarhoş olmak,  yok yok içmeden;  kendimi kaybetmek ya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karakulak']::text[], 8.5, '{"poet":"Mehmet Karakulak","poet_slug":"mehmet-karakulak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istiyorumm-istee-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yanlız olmak', 'yanliz-olmak-mehmet-karakulak-ejej3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dünya  olmuş kaç milyon

ne çıkar

ben

ben yine yalnız

yalnız

yalnız olduğumu

bile bile yalnız olmak

değil koyan

hınç

a

hınç 

doluyken etraf

yalnız olmak; işte asıl koyan...', 'dünya  olmuş kaç milyon ne çıkar ben ben yine yalnız yalnız yalnız olduğumu bile bile yalnız olmak değil koyan hınç a hınç  doluyken etraf y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karakulak']::text[], 8.5, '{"poet":"Mehmet Karakulak","poet_slug":"mehmet-karakulak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanliz-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hü', 'hu-edip-cangonul-2k4op', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda işareti mi? 

Duyarga misali özümsüyorum

           Hü deyişini

           Türkülerin

Sevdalanıyorum

Hü leb

Hü Hızır

Hü darağacı

Ezildikçe artıyor

Yüreğimin beğenmişliği

                Pir Sultan’ı

Sevdikçe sebil oluyor

           Dinledikçe Elifini, 

Elifini

Karacaoğlanın

Sevda lorke oluyor

Bir uzunhava yükleme dozu

Bir türkü idame', 'Sevda işareti mi?  Duyarga misali özümsüyorum            Hü deyişini            Türkülerin Sevdalanıyorum Hü leb Hü Hızır Hü darağacı Ezildi...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '4'' lükler.', '4-lukler-mehmet-karakulak-y8enj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '4'' lükler

Bak bir damla daha aktı, 

İçinde geleceğim saklıydı. 

umutlarım UMUTLARIM vardı; 

geçmişimin üzerine aktı...', '4'' lükler Bak bir damla daha aktı,  İçinde geleceğim saklıydı.  umutlarım UMUTLARIM vardı;  geçmişimin üzerine aktı......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karakulak']::text[], 8.5, '{"poet":"Mehmet Karakulak","poet_slug":"mehmet-karakulak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/4-lukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Aralık 2001 ve Gece', '10-aralik-2001-ve-gece-edip-cangonul-4s985', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günlerden hergün yine

Sabahın körü hem

Elinin körü gibi

Ayaz  ve sümüklü

Daha günaydın bile değil

Çay bayatlamış 

Kül tablası bayram ediyor

Western filmlerdeki mezarcı misali

Ve uzundu gece

Her yatılmayan gece gibi

Sahursuz

Ve bu gece de boş geçti

Sevdasız

Sevgisiz

12 saat sonra başlar karanlık

“oy akşamlar akşamlar

yine geldi akşamlar

evli evine gider

garip nerde akşamlar”', 'Günlerden hergün yine Sabahın körü hem Elinin körü gibi Ayaz  ve sümüklü Daha günaydın bile değil Çay bayatlamış  Kül tablası bayram ediyor ...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/10-aralik-2001-ve-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-sair-harun-0pm80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlatamıyorum., bakıyorum sadece

Yaşayamıyorum, hissediyorum sadece

Göremiyorum, duyuyorum sadece

Sen böyle birisin işte

Yaşayamadan seviyorum seni

Bana bir bakışın yetiyor

Her gün vazgeçiyorum seni sevmekten

Her vazgeçiş bir başlangıç oluyor benim için

Her başlangıç sevgimi katlıyor

Bir gün dayanamacağımdan korkuyorum

Aslında dayanamamaktan değil

Seni bulmadan kaybetmekten korkuyorum.

(09.12.2002)', 'Anlatamıyorum., bakıyorum sadece Yaşayamıyorum, hissediyorum sadece Göremiyorum, duyuyorum sadece Sen böyle birisin işte Yaşayamadan seviyor...', ARRAY['Türk Edebiyatı','Şiir','Şair Harun']::text[], 8.5, '{"poet":"Şair Harun","poet_slug":"sair-harun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/korkuyorum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Diye', 'ne-diye-mevlana-celaleddin-rumi-vjbia', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beri gel, daha beri, daha beri. 

Bu yol vuruculuk nereye dek böyle? 

Bu hır gür, bu savaş nereye dek? 

Sen bensin işte, ben senim işte. 

Ne diye bu direnme böyle, ne diye? 

Ne diye aydınlıktan kaçar aydınlık, ne diye? 

Topumuz bir tek olgun kişiyiz, bir tek, 

Ne diye böyle şaşı olmuşuz, ne diye? 

Zengin yoksulu hor görür, ne diye? 

Sağ soluna yan bakar, ne diye? 

İkisi de senin elin, ikiside, 

Peki, kutlu ne, kutsuz ne? 

Topumuz bir tek inciyiz, bir tek. 

Başımız da tek, aklımız da tek. 

Ne diye iki görür olup kalmışız 

İki büklüm gökkubbenin altında, ne diye? 

Sen habire gevele dur bakalım, 

Habire ''Usul boylu birlik çam ağacı'' de, 

Sonu nereye varır bunun, nereye? 

Şu beş duyudan, altı yönden 

Varını yoğunu birliğe çek, birliğe. 

Kendine gel, benlikten çık, uzak dur, 

İnsanlara katıl, insanlara, 

İnsanlarla bir ol. 

İnsanlarla bir oldun mu bir madensin, bir ulu deniz. 

Kendinde kaldın mı bir damlasın, bir dane. 

Erkek arslan dilediğini yapar, dilediğini. 

Köpek köpekliğini ede durur, köpekliğini. 

Tertemiz can canlığını işler, canlığını. 

Beden de bedenliğini yapar, bedenliğini. 

Ama sen canı da bir bil, bedeni de, 

Yalnız sayıda çoktur onlar, alabildiğine, 

Hani bademler gibi, bademler gibi. 

Ama hepsindeki yağ bir. 

Dünyada nice diller var, nice diller, 

Ama hepsin de anlam bir. 

Sen kapları, testileri hele bir kır, 

Sular nasıl bir yol tutar, gider. 

Hele birliğe ulaş, hır gürü, savaşı bırak, 

Can nasıl koşar, bunu canlara iletir.', 'Beri gel, daha beri, daha beri.  Bu yol vuruculuk nereye dek böyle?  Bu hır gür, bu savaş nereye dek?  Sen bensin işte, ben senim işte.  Ne ...', ARRAY['Türk Edebiyatı','Şiir','Mevlana Celaleddin Rumi']::text[], 8.5, '{"poet":"Mevlana Celaleddin Rumi","poet_slug":"mevlana-celaleddin-rumi","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ne-diye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SOL YANIM', 'sol-yanim-oropa-seni-t4eei', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vurgun haa vurgun

geceden kalan..

Bir beden dedikleri ayakta

bir de senden kalan 

Katran karası gibi

kurşun yarası gibi

sol yanımda 

taa şuramda

yanar haa yanar 

ölümüne sevdan...', 'Vurgun haa vurgun geceden kalan.. Bir beden dedikleri ayakta bir de senden kalan  Katran karası gibi kurşun yarası gibi sol yanımda  taa şur...', ARRAY['Türk Edebiyatı','Şiir','Oropa Seni']::text[], 8.5, '{"poet":"Oropa Seni","poet_slug":"oropa-seni","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sol-yanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senbizinutamazsın Palas', 'senbizinutamazsin-palas-ali-galip-b5ubn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendimi getiremedim diyorum size

Bir haber kimsesiz  bu aynalı dolabın kalabalığında

Hep yalvaçların ağzında halbuki

Yükte hafif pahada ağır

Tüm saatlerle

Sana bir sorudan daha zor işte

                          Bombanın arkasında

Olan nedir 

Sahi sonraki nedir

Cumhuriyetlerimizi kanatan militanlığımızdan

Kaba gün artığı  bohçamda

Bir bohçayla gitmek kadar yorulmamıştır

Günlüğümüz

Yani buraya kadar her şey açık

Her şey dosdoğru 

Ancak nereden anlaşılacak

Mendilimizin ucunun  bir kadında kilitlendiği

Nikah düşmüyor nedense meydanlara

Çeyizsiz kaçırıp bir yerlerinden dünyanın

Akşam mayhoşluğuyla apoletli  sabahın bir kırmasıyla

Yaşlandığımı

Salkım saçak bir 

Kölenin doğduğunu

Biliyorsunuz artık

Haince eskiniyor

Bir ahırın koynunda

Sarı fotoğrafların, akşam ezanlarının

Dam üstlerinin, 

Burası ki  yaza en erken tutunan yerdir

Sonunu yürüyemeden kaybolanlarıyla tanınır 

Asyanın bir kızı senin yüzünden

Bir zarfa ikna ettiğim gökkuşağı

Bekleme gerisini 

Artık

Tutup tutup 

Kırmızı gözlü toprağı

Bu utangaç çocuğu 

Kendi maskemle getirmek istemiyorum lanetli ayine

İşte yanımıza çoğaldığımızca

Çelenklerimizi topluyoruz kapılarımızdan 

Her yaprağımla denize şirk koşuyorum

Ellerim

Daha panayırsız ‘kaldı’ların

Artık bitti

Siz de söyleyin artık değil mi

Bitti artık mesela söyleyebiliyorum

Hiçbir noktalama işaretinin

Üstüme vebal kalmayacağını 

Olmalıdır aslında

Evimize konup kalkan

Her asma bahçesinin

Yosun kokulu bir müjdesi

Ayrıca bir müjdenin her şeyden önce

Bir tebaası 

Kaba etleriyle yağmalıdır

İşte ben

Çünkü bu kentin  muskasıysam anlıyorsun....



Sana kendimi getiremedim

İster kadıköyünde olayım artık

İster kemaliyende

Rahlene sonra

Ülkemin en unutulan çöplüklerine

Al götür

Oku getir.', 'Kendimi getiremedim diyorum size Bir haber kimsesiz  bu aynalı dolabın kalabalığında Hep yalvaçların ağzında halbuki Yükte hafif pahada ağır...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip']::text[], 8.5, '{"poet":"Ali Galip","poet_slug":"ali-galip","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/senbizinutamazsin-palas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahta At', 'tahta-at-sezai-karakoc-bk0r2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostlarımız geldi hafif danslar geldi

Şeker verdik aslan yeleleri aldık kırk kapı açtık

Kırk kapı açtık Mavi Sakal öldü

Kırk odanın içinde güzel aslanlar güldü

Sen güldün Asya güldü hafif danslar geldi

Gel kalbini saat yap odamıza

Saatin içine kutsal sözler yaz

Güneş yap aşka güzel ölümleri uslu ölümleri

Gel mesut odalar içinde çözül güzel bulmaca

Güzel ve mağrur ve katil

İç dünyamı ikili susmalarla bölme

Şiir günlük konuşma dilimiz

Kıskançlığımdan örülme bir perde

Perdeye çarpan beş deniz

Kuvveti yok bende itham etmek hakkından önce

                          II

Dostlarımız geldi sağlam izleri var karda

Yapacaklarının yapılabileceği iyi öğretildi onlara

Ve sağlam kutular içine koydular gölgelerini

Karışık bir ses teller üzerinde Londra

Gel bu gece görülmemiş bir şey olacak

Yanlış bir dağın altından yanlış bir su çıkarsa

Kaybolursa taşlar içinde taşlar getiren taş bir bulut

Eşkiya heybesinde çizgili kayığa asıl

Merhametin bildik kaynağı eşkiyalar

Kıldan ince çarpık bilgileri unut

Sessiz derin sonsuz yaslı duvarlar önünde

Türküler içinde en şen en senin olanı söyle

                        III

Aşk kadar nazlı saat kadar gerçek

Bir bülbül bakıyor bana doğru

Boş oda kadar tedirgin tehlike kadar güzel

Bir bülbül içimde sedefle kaplanıyor

Payıma korkarım eşsiz bir azap düşecek

Dostlarımız geldi öldü büyücüler

İnsanla peygamber arası basık bir gürültü içinde

Korkunç ilgiler döner dolaplar

Sedef gurur ve inat içinde

Seni bana getirsin ölüm yatağımdayken

Kırık ayaklı tahta at.', 'Dostlarımız geldi hafif danslar geldi Şeker verdik aslan yeleleri aldık kırk kapı açtık Kırk kapı açtık Mavi Sakal öldü Kırk odanın içinde g...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/tahta-at-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-utku-oguz-871ch', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öceleri bakamadığım güneş, 

Şimdi görünmez oldu gözüme.

Aradabir çıksada bulutların ardından, 

Yakmıyor artık gözlerimi, sönmüş sanki.

-

Her gece beni çağıran parıltılı yıldızlar, 

Galiba haber bile vermiyorlar artık.

Ya beni aldatıyorlar, 

Yada hepsini kandırmış kıskanç bulutlar...

-

Çok rahat uyuyorum gecelerdir..

Ne beni uyandırmaya çalışan ağustos böcekleri, 

Ne de sayemde yaşamaya çalışan sivri sinekler var...

Onları bile özlüyorum..

-

Her zaman, zamanı geri çevirmek istemiştim, 

Bu akşam yemeğini zamanla birlikte yedim.

Dilediğim gibi oynayabileceğimi söyledi bana..

Dokunmadım saniyelere bile, istediğim bir bardak su sadece..

-

Koca bir yangın ararken, sönmüş bir kibrit bulur gibi, 

Saatler sürecek bir yolu, göz açıp kapayana kadar bitirmek gibi, 

Zorlu bir sınavdan şarkı söyleyerek çıkmak gibi, 

Beni düşündürecek hiç birşey olmadan yaşar gibiyim..

-

Olanları yitirmekten, olamayacakları istiyorum artık.

İlk defa boş yere harcadığımı hissediyorum gücümü.

Meğer haksızlık ediyormuşum ağustos böceklerine, 

Ekimin ortasında, neden ötüşsünler ki boş yere? ....', 'Öceleri bakamadığım güneş,  Şimdi görünmez oldu gözüme. Aradabir çıksada bulutların ardından,  Yakmıyor artık gözlerimi, sönmüş sanki. - Her...', ARRAY['Türk Edebiyatı','Şiir','Utku Oğuz']::text[], 8.5, '{"poet":"Utku Oğuz","poet_slug":"utku-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bosluk-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Sevil''di', 'adi-sevil-di-suat-oktay-4x7ui', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'daha çok güneşli günler istiyorum

onu gün yüzüyle görmek için

onun adı sevildi

aşkı nefret

nefreti aşk bilirdi

ama yinede gözeldi, 

hem de özel...

beni nedense hep üzerdi

daha çok yağmurlu günler istiyorum

gözyaşlarımı kimse anlamasın diye 

adı sevildi

saçları kumral, bazan meçli

gözleri bir gün mavi bir gün yeşildi

güneşe göre değişir(di)

yamura göre pekişirdi.

Hem güneş hem yağmur olsun isterdim her gün

Gök kuşağı gibi yanıma süzülsün

İsterdim bir gün

o sevildi

ama beni sevmedi sevemedi

bakışı ömre bedel kaçışı ölümdü

çünkü aşkı nefret, nefreti aşk bildi

güneşti yaktı

yağmurdu gözyaşım oldu aktı

geceydi sır dolu

yüzü ay gibi paktı.

sevildi

sevmek nedir bilemedi

hem asildi, hem de ürkek

onda yoktu zaten aşkı yaşayacak tadacak yürek...

23/02/98

SUAT OKTAY', 'daha çok güneşli günler istiyorum onu gün yüzüyle görmek için onun adı sevildi aşkı nefret nefreti aşk bilirdi ama yinede gözeldi,  hem de ö...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/adi-sevil-di-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İs', 'i-s-suat-oktay-j8n2k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'is 

bulaşmış dünyanın bi tarafına 

bulaşmış yasak aşkların en güzeli ruhuma

is bulaşmış

kara bir leke gibi

yalan dünya bulaşmış

onun eline 

bunun diline 

benim gönlüme

saplanmış kor bir mermi gibi

yasak aşkın karanlık olan dibi

bilinmeyen nedeni 

yüzüme gözüme bulaşmış 

ayağım elime dilim belime dolanmış

yasakta olsa bu bir meyve

seyreyle gönül aşkı seyreyle 

dünya bu dostlar

değişmez gitti de, 

yine gider böyle.

Suat''ın alnında ki leke kara değil

Yüreğinde ki bildiğiniz yara değil, 

O bunu anlatamaz

Lakin anlatsa da kimse anlayamaz

Salt aşk, sevgi de değil

Dünyaya bakışı meşk değil 

Hele bir kulağını eğil

Fısıldasın sana, sende başkasına

Çünkü sır değil, 

Sırdaş yokki dünyada

Sır kalsın tek ağızda.

suat oktay / 14 mayıs 2000', 'is  bulaşmış dünyanın bi tarafına  bulaşmış yasak aşkların en güzeli ruhuma is bulaşmış kara bir leke gibi yalan dünya bulaşmış onun eline  ...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/is-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadım', 'unutmadim-suat-oktay-8z7y6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutmadım aklımda

Buralara artık kar yağmıyor

Saçlarımı ak bürüdüğünden

Bahar gelmek bilmiyor 

ruhumdaki sonbahardan

Yağmur da yağmıyor

Gözlerim kurumayalı

Ne güneş, ne de ateş yakıyor

Bakışın yaktığı gibi

Çiçeklerse anlamsız artık

Teninin kokusu yanında

Omuzuna dökülen saçların

Yaprak gibi dalında

Unutmadım bebeğim hepsi aklımda

Nur yüzünü ay kıskanır da 

Ben kalırmıyım

Karanlık gecemin

Aydınlık yüzüydün

Ne yazık

Ömrümün güzüydün

Nasıl unuturum, hep aklımda.', 'Unutmadım aklımda Buralara artık kar yağmıyor Saçlarımı ak bürüdüğünden Bahar gelmek bilmiyor  ruhumdaki sonbahardan Yağmur da yağmıyor Gözl...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/unutmadim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dengeler', 'dengeler-suat-oktay-w8jq2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dengeler bozulmasın diyorsun

iyi ama denge dediğin de

bozulur be güzelim. 

duygu, duyguya

sevgi sevgiye, 

denge dengeye

davul dengine çalsa

dünya bir teksana kalsa

istermisin? 

Oysa ne bir çift bakış 

ne tek bir

yakış, haykırıştır, 

bağrımdan kopan,

sen gönlünü hoş tut, 

dengeleri

bozanın iki dengesi 

biraraya gelmez, 

gelse de kimse bilmez...16/05/2000', 'dengeler bozulmasın diyorsun iyi ama denge dediğin de bozulur be güzelim.  duygu, duyguya sevgi sevgiye,  denge dengeye davul dengine çalsa ...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dengeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ki', 'ben-ki-suat-oktay-rng6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben ki, 

beni iyi tanırım, 

bazan aldanırım

acep, ben ben miyim, 

yoksa içimde ki 

bir başka ben mi? 

bu nedenle 

tanıyamam kendimi

yaşamak dedin de

W.SHAEKSPEARE''den esinlenerek, 

bu ülkede yaşamak, 

benliğini yitirmeden 

ayakta kalmak

kolay mı be kadim dostum

sende kendine

kendi ''beni''ni sor

sor bakalım, tanıyor mu, 

yoksa gizli, bilinmeyen 

bir yerde saklanıyor mu? 

yaşam dediğin, bir sıkımlık

diş macunu, 

bitince atılıveriyor

insanda öyle, 

ölünce

gömülüveriyor

kalanlara selamet olsun...19/05/2000', 'ben ki,  beni iyi tanırım,  bazan aldanırım acep, ben ben miyim,  yoksa içimde ki  bir başka ben mi?  bu nedenle  tanıyamam kendimi yaşamak ...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Evrim Geçirmez', 'gonul-evrim-gecirmez-suat-oktay-v4gy7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gönül evrim geçirmez

sana bir şiir yazmak istedim 

tanrım ne kadar zormuş

istemek yetmiyor yazmak için

biraz kızmak, 

biraz ısınmak, 

gülmek ağlamak...

kim bilir belki mutlu olmak

lazımmış...

sana bir şiir yazmak istedim

seni anlatmasa da dizeleri, sana olsun

ne kadar zormuş

yürek yorgun

gözler bıkmış, usanmış...

biraz yalanmış belki

anlaşılamamak mı, 

yoksa yabana atılmak mı? 

Gerçeği bulamamış

Bu şiir sana inanan

İlk değilsin sen, yazdığım

Biliyorsun

Peki, beni hala seviyor musun? 

Yoksa, ''o bir rüzgar, tatlı dudağımda 

Hoş bir meltem di'' diyorsan eğer...

Birkaç damla gözyaşı, 

Sorarım sana neye değer...

Bu şiir sana, biliyorsun artık

Avizenin bir ucunda sen, diğerinde ben...

''nereden çıktın karşıma'' desem de

nerede olursan ol, sev, hep sev...

beni bu evrende...

evet evet, eminimin artık, bu şiir sana...

çünkü sen varsın her anımda, 

acımda tatlımda, gözyaşımda

köşe bucak kaçışında

beni eski acılara atışında.

İnan bu şiir sana, sadece sana...

Gönül evrim geçirmez

Sakın unutma! ..21/01/97', 'gönül evrim geçirmez sana bir şiir yazmak istedim  tanrım ne kadar zormuş istemek yetmiyor yazmak için biraz kızmak,  biraz ısınmak,  gülmek...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gonul-evrim-gecirmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Evrim Geçirdi.', 'gonul-evrim-gecirdi-suat-oktay-yyzdv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözün aydın! 

Gönül evrim geçirdi.

''gözden uzak, gönülden ırak'' derler ya...

ondan mı ne? 

Hissetmiyor artık acıyı-sızıyı

Uyuştu mu acep gönül, 

Ondan mı yoksa, yoksa özlemiyor

Dudağının tadını, dudağım 

Başka sihirli dudaklar arayalı.

Sakın ''buldu mu? '' diye sorma

Söylemem asla, ne sana, ne de

Bir başkasına, bulamadığımı...

Lakin keramet dudakta değil

Salt unutabilmekte marifet

Ne dudağının tadı

Ne o ilk gecenin adı

Senden arta, yalanların yadigar kaldı

Hadi gözün aydın bi daha

Gönül evrim geçirdi.

Yalanların da olmasa, 

Çekilmezdi vallaha sensizliğin

Sensizlik dediğim, hiç düşünmemek seni

Yaşamamış, yaşanmamışsın gibi...

Gözün aydın hadi, 

Artık gönül evrim geçirdi...

Mayıs 2000', 'Gözün aydın!  Gönül evrim geçirdi. ''gözden uzak, gönülden ırak'' derler ya... ondan mı ne?  Hissetmiyor artık acıyı-sızıyı Uyuştu mu acep gön...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gonul-evrim-gecirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Şubat', '14-subat-suat-oktay-kszz6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşünme hiç neden diye

Seni artık sevmiyorum

Biliyorum nefret etmem gerek

Ama yapamıyorum

Yalan değil duygularım

Düş ya da hayal da değil

Aşk çemberini sen kırdın

Göz yaşlarıma aldırmadan

Çektin gittin, nefret için her şeyi yaptın da

Nasıl nefret edileceğini anlatmadın.

Bıraktın öylece, yüz üstü...

Baharın başında, cehennem sıcağında

Kış ortasında, güz üstü...

Gönlüm küstü, 

Sana küstü, 

Bana, ona, şuna, küstü

14 şubat sevgililer günüydü

Küs gönlüm buruk

Aklım duruk, düşünemiyorum.

Sabaha başladı, akşama bitti

14 şubat gitti

Elim titredi

Gözüm seğirdi

Ufukta bir gemi belirdi.

İçi boş yazık.

Bağırdım kalabalıkta

Yapayalnız.

Yalan inan yalan, 

Seni sevmediğim yalan

14 şubat gelince oyalan

Sensiz geçmiyor, güzelim

An be an, zaman

Olmayan, aşk...

14 şubatta olmayan 

Sen ve ben...

21/01/1997', 'Düşünme hiç neden diye Seni artık sevmiyorum Biliyorum nefret etmem gerek Ama yapamıyorum Yalan değil duygularım Düş ya da hayal da değil Aş...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/14-subat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekler', 'gercekler-suat-oktay-3z2y8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gerçekler düşlerden de güzeldir bazen 

gerçekleri düş gibi yaşayabiliyorsan

bazen da kabus gibidir gerçekler 

uyanmayı(eğer)  bilmiyorsan 

/ 15/07/2000', 'gerçekler düşlerden de güzeldir bazen  gerçekleri düş gibi yaşayabiliyorsan bazen da kabus gibidir gerçekler  uyanmayı(eğer)  bilmiyorsan  /...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gercekler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhun Gıdası', 'ruhun-gidasi-suat-oktay-ihrj6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sevgi dediğin ruhun gıdası, 

ruhunu gıdasız bırakma, 

arada bir aşk''la sula ki, 

daha da kusursuz olsun, 

sevgi ve aşk, 

insanı sarhoş eder deselerde 

inanma, 

insanı sarhoş eden insandır, 

sakın kanma! 24/07/2000', 'sevgi dediğin ruhun gıdası,  ruhunu gıdasız bırakma,  arada bir aşk''la sula ki,  daha da kusursuz olsun,  sevgi ve aşk,  insanı sarhoş eder ...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruhun-gidasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Olana', 'adam-olana-suat-oktay-97xtz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'zenginlik eğer gönlünde yoksa, 

cebin şişkin olsa ne yazar... 

kızar bozar, herşeyin yitip gider azar azar.. 

5/8/2000', 'zenginlik eğer gönlünde yoksa,  cebin şişkin olsa ne yazar...  kızar bozar, herşeyin yitip gider azar azar..  5/8/2000...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/adam-olana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Sırrı Nedir?', 'yasamin-sirri-nedir-suat-oktay-mi6w5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''yaşamın sırrı nedir? '' diye sorsam, 

biliyorum yanıt veremeyeceksin.

yaşamın sırrı 

insan be güzelim.

hani şu elleri kolları, 

iki gözü, iki kulağı, 

saçı kaşı, kirpikleri, 

cinsel organı, ayakları, 

tırnakları olan, 

hani bazan düşünebilen canlı türü varya, 

o işte, insan! .. 

Kendisine zarar verebilen, 

tek canlı türü, yaşam formu.

sır o işte inan, günün birinde 

aynaya bakarken

bunu ayrımsayacak, 

insanlığından utanacaksın.

seni bilmem ama 

ben artık utanıyorum 

31 07 2000...', '''yaşamın sırrı nedir? '' diye sorsam,  biliyorum yanıt veremeyeceksin. yaşamın sırrı  insan be güzelim. hani şu elleri kolları,  iki gözü, ik...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasamin-sirri-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Bir Kalp', 'kirik-bir-kalp-suat-oktay-4unqn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unut gitsin be yavrum 

bak film bitti, 

sinema boşalıyor

her hayat bir roman derler ya

her roman bir hayat mı, bilinmez ama? 

her film bir hayat olabilir, 

yaşadığımız hayat hayat olsun da

inan bayat olmasın

bayat bir hayat, 

hayatta çekilmez valla

dediğim gibi

unut gitsin be yavrum

oysa güzellikler unutulur da

acılar iz bırakır değil mi? 

unutulmaz istesen de elbet.

Bak sinemada kimse kalmadı artık, 

beyaz bir perde, 

boş koltuklar, 

yerlerde kuruyemiş kabukları, 

çiğnenip tükürülmüş çiklet artıkları, 

gazoz kapakları, 

gözyaşları, 

ve kırık bir kalp...

çıkarken üzerine basmayasın sakın! 

14/10/2000(02: 02)', 'Unut gitsin be yavrum  bak film bitti,  sinema boşalıyor her hayat bir roman derler ya her roman bir hayat mı, bilinmez ama?  her film bir h...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kirik-bir-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Filiz', 'bir-filiz-suat-oktay-w6dqi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sanal alemde bir filiz, 

Yüregime filizlendi 

Bir ates filizi

Bir filiz atesi...

Adı filiz mi

Yoksa filiz mi adı

Ne farkeder ki

Ne tatlı ne hoş bir anı

Sanal böyle

Gercek kimbilir nasil

Ah filiz ah..

Öyle bir sevgiye sahibiz, 

Sahibim, 

Sahipsin ki, 

Yürekteki sevgi filizlense 

Bir dile gelse 

Ah bir gelse...

Gelsen de görsen bel filiz ah...

09/06/2000', 'Bir sanal alemde bir filiz,  Yüregime filizlendi  Bir ates filizi Bir filiz atesi... Adı filiz mi Yoksa filiz mi adı Ne farkeder ki Ne tatlı...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-filiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acelesi Olan Önden Buyursun', 'acelesi-olan-onden-buyursun-suat-oktay-7uwoq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu akşam hava ölmek için çok güzel, 

ölmek, hani toprağa gömülmeden önce yıkanıp

ardından kefenlenme varya ondan...

Gökyüzünde yıldızlar ışıldıyor, 

rüzgar sert esiyor, dudakları çatlatıyor bu gece

caddelerde kimse yok, yollar boş, bom boş...

Hava ölmeye müsait, ölüp gitmeye, 

dertlerden, sorunlardan, sıkıntılardan ve

düşmanlardan kurtulmaya...

Benim mücadele edecek gücüm var hala, 

hava varsın ölmeye uygun olsun, 

acelesi olan varsa önden buyursun! 

4 kasım 2001', 'Bu akşam hava ölmek için çok güzel,  ölmek, hani toprağa gömülmeden önce yıkanıp ardından kefenlenme varya ondan... Gökyüzünde yıldızlar ışı...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/acelesi-olan-onden-buyursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-suat-oktay-mm4px', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kaç durakta mola verdim saymadım

hem kaç yıl oldu ki yola çıkalı.

ne zaman sollamak istedimse yaşamı

olmadı beceremedim.

beceremedim de değil

şerit hep düzdü çünkü.

ne zaman hız sınırını aşmak istedim

yakıtım bitti, yolda kaldım

ne el uzatan oldu

ne de omuzveren

her durakta bir sır bıraktım oysa

sır oysa, hani kişiye özel

sır dedeğim, 

bir ben, bir sen 

bir de allah bilsinlerden.

bir kadının gönlü sırlar okyanusuydu hani

yalanmış meğerse

yine bir duraktayım şimdilerde.

lakin birazdan yola koyulacam

dümdüz bir şerit uzanacak yine önümde.

yeminle bukez basacam gaza

sollayacağım önümde gideni

bilmem kaç milyonluk

şu yeditepeli dev değirmeni.

ne radar saptayacak, 

ne trafik görecek

ne de yalancı sırdaşlar.

durmayacam

gerçek bir sırdaş

otostop yapıncaya dek.

gidecem gidebildiğimce

sevecem ölebildiğimce

ölecem, sevebildiğimce

gerçi yol bitmezmiş 

ömür bitse de

tekerlek de patlasa farketmez be

ben jant üzerinde de giderim

ters yola sapmadıktan sonra.

14.4.1999', 'kaç durakta mola verdim saymadım hem kaç yıl oldu ki yola çıkalı. ne zaman sollamak istedimse yaşamı olmadı beceremedim. beceremedim de deği...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yolcu-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla', 'agla-suat-oktay-wsbd7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağla ey dağ, 

Ey ova, göl deniz...

Yağmur, kar, çamur

Ağla yol, tarla, bağ...

Ağla ki rahatlayasın

Sen sen değilsin artık bunu bil; 

Kim ki sana sen derse 

Sen değilsin sen, 

Ben zaten değilim ben, 

Ne sen, sen, ne de ben, ben! 

Ağla ey utanmaz, arlanmaz, 

Küflenmez, paslanmaz.

Ağla ki, utancın utansın! 

Bak ben ağlıyorum, 

Sıkıyorsa sen de ağla...

(8.02.2002)', 'Ağla ey dağ,  Ey ova, göl deniz... Yağmur, kar, çamur Ağla yol, tarla, bağ... Ağla ki rahatlayasın Sen sen değilsin artık bunu bil;  Kim ki ...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agla-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Dürüst!', 'ey-durust-suat-oktay-3en3b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Selamlıyorum seni ey dürüst.

Nerdesin? 

Ayağa kalk! 

Görsün seni bakan körler! 

Seviyorum demek ne kadar gerçek? 

Para, pul, mal, mülk insanı dinden 

imandan çıkarmaz mı? 

Dürüst, neredesin? 

Göster kendini hadi, 

ver elini.

Korkma benden! 

Elini veren, kolunu kurtaramaz 

deseler de korkma ne benden, 

ne de benim gibi neferden! 

Dürüst benim, ey dürüst! 

Doğru bildiği yoldan şaşmayan, 

yalakalara eyvallah etmeyen.

Seven, ama sevilmeyen, 

bilen fakat bilinmeyen, 

güldüren, lakin gülmeyen...

Selam olsun sana ey dürüst! 

Ben beni iyi bilirim de, 

Bilmeyen beni ne bilir, onu bilmem! 

Seviyorum yine de, 

sevilmesem de, 

görüyorum yine 

kimse beni görmese de.

16 kasım 2001', 'Selamlıyorum seni ey dürüst. Nerdesin?  Ayağa kalk!  Görsün seni bakan körler!  Seviyorum demek ne kadar gerçek?  Para, pul, mal, mülk insan...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ey-durust-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru Ol, Canımı Ye!', 'dogru-ol-canimi-ye-suat-oktay-ra9p1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana sevgin gerek, 

seviyorsan gel, 

öp, sar sarmala kucakla

yalana lüzum yok.

bana sen gerek, 

saçın, dudağın

elin, ayağın.

yalana lüzum yok.

bana aşk gerek, 

yeterki senden olsun, 

zehir olsan içerim yine

yalana lüzum yok

bana tenin gerek

yeterki koklayayım

hassedeyim sıcaklığını

gitmeye ne gerek 

bana sözün gerek

dudaklarını göreyim yeter

kor olsa dudakların, 

yaksan içimi

ateşe ne gerek

bana sesin gerek

duysam bir kez kafi gelir

susmana lüzum yok

bana nefesin gerek

yılandan olsan 

adın da engerek

koynumda beslerim

zehire lüzum yok

bana sen gerek

gerisi neme gerek

bağrıma taş diye

basarım seni.

yalana en gerek.

doğru ol, canımı ye! 

05/01/02', 'Bana sevgin gerek,  seviyorsan gel,  öp, sar sarmala kucakla yalana lüzum yok. bana sen gerek,  saçın, dudağın elin, ayağın. yalana lüzum yo...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dogru-ol-canimi-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-suat-oktay-r8gv7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün Kapılar kapanırken yüzüme

bekliyorum, 

umut doğusun, 

ışık çaksın, 

rüzgar arkamdan essin diye

oysa somut bir yalan kadar acı, gerçek

yüreğimde kopan fırtınaysa yırtıyor, kanatıyor...

acı, içimde derin bir sancı...

yüreğimde bir han, içinde hancı

gelecek diye bekliyor, ıslak dudaklı meçhul bir yabancı! 

kapılar kapalıyken, 

umutlar da yaralı...

içinde bir sır saklı, 

düşünmesi, söylemesi yasak! 

tüm kapılar yüzüme kapanmış, 

eşikte kala kalmışken, 

sevgi ve sevgili, 

huzur ve mutluluk 

çoook ama çok uzaklardaymış! 

eylül 2001', 'Bütün Kapılar kapanırken yüzüme bekliyorum,  umut doğusun,  ışık çaksın,  rüzgar arkamdan essin diye oysa somut bir yalan kadar acı, gerçek ...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bekliyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpüşme', 'opusme-suat-oktay-7fmsg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dudaklarının titrediğini gördüm.

kafamda kusursuz bir sevgili ördüm.

nakış nakış işledim, gözlerini, saçlarından, 

kaşlarını ve dudak...

elbet, dudak titrer, göz seğirir, 

el terler, parmaklar kasılır.

sonra bakışlar kesişir

ve titreyen dudaklar, 

yelken açarken biribirine doğru

nefesler karışır önce, 

ardından dudaklar yanaşır

aşk limanına.

Demir atar aşkın tam da bağrına

vücut sek, dudak-lar yek

bir sihir ortaya çıkar adı tek..

öpüşme...

herşeyin başı, çok şeyin faili, 

koydum adını, 

solukların dansı, 

İtirazı olan var mı? 

29 kasım 2001', 'Dudaklarının titrediğini gördüm. kafamda kusursuz bir sevgili ördüm. nakış nakış işledim, gözlerini, saçlarından,  kaşlarını ve dudak... elb...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/opusme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudakların Şiiri', 'dudaklarin-siiri-suat-oktay-a47kw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kasım sabahı karaladım

dudakların şiirini

şiir de değil

bir saptama bu...

yasak bir duygunun

gizli kalıp ta açığa çıkan

yalanı.

giz artık sır değil

sır, giz değil.

bu böyle biline, 

Mühür dudaklar

açıla, diller çözüle.

Nefesler nefes olup

titerişmleri titrete dursun.

iki sevgili birbirine yumulsun, 

bırakın da sevgili olduklarını anlasınlar.

sevgiliye en güzel hediye öpüşme olsun! 

29 kasım 01

***

Seni öpmek istiyorum

ey kara kaşlı, kara saçlı yar.

Başıma yağsa da aktan da ak kar, 

sar beni kollarına al, 

sıkı sıkkıya sar

bana bu hayat öyle dar

geliyor ki bilimezsin yar, 

yar yar seni içime attım, 

öpemeden gittim gezdim 

dolandım her diyar

ne meyhane, ne bar

beni sen sarhoş edersin 

ey kara vicdanlı yar

değil yağmur, yağsada kar

dudaklarım yanıyor ateş gibi

söndürmek için gerekli  sen gibi yar! 

29/11/01', 'Bir kasım sabahı karaladım dudakların şiirini şiir de değil bir saptama bu... yasak bir duygunun gizli kalıp ta açığa çıkan yalanı. giz artı...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dudaklarin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görsün Dünya Alem', 'gorsun-dunya-alem-suat-oktay-9oca8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni öpmeyi öyle özledimki? 

Uzat dudaklarını hadi, 

uzat dünyanın öbür yanından, 

uzat ki uzaklık kalksın ortadan.

telefonun bir ucunda sen, 

diğer ucunda ben.

Öpüşmek nasıl olur

görsün dünya alem

29/11/01', 'Seni öpmeyi öyle özledimki?  Uzat dudaklarını hadi,  uzat dünyanın öbür yanından,  uzat ki uzaklık kalksın ortadan. telefonun bir ucunda sen...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gorsun-dunya-alem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdil: LXXXVIII', 'i-dil-lxxxviii-hasan-i-zzettin-dinamo-cbywt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiirin güneşine bulayarak parmaklarımı

Sevmek okşamak istiyorum seni güzel kadın.

Yıkmak, kurduğun dayanakların son duvarlarını

Girmek ölümsüzlüğüne etindeki tadın.

Sen çiğneyerek yalınayak ilkyazın halısını

Bana özlemin kızgın şiirini tattırmaktasın.

Toplayıp gitti yaban lalesi tasını tarağını

Sabrımın kapısını tekmelerinle kırmaktasın.

Gece, yüzünde ayışığının gümüş tülleri

Beni birde romantik oyunlara mı düşüreceksin? 

Ne zaman içimdeki özlem cehennemini göreceksin? 

Bak açtı bahçemizin karınca kararınca bütün gülleri

Hepsi örneği sanki ateşten bir yüreğin.

Gel, ışık yaksınlar bize sabahlara değin.', 'Şiirin güneşine bulayarak parmaklarımı Sevmek okşamak istiyorum seni güzel kadın. Yıkmak, kurduğun dayanakların son duvarlarını Girmek ölüms...', ARRAY['Türk Edebiyatı','Şiir','Hasan İzzettin Dinamo']::text[], 8.5, '{"poet":"Hasan İzzettin Dinamo","poet_slug":"hasan-i-zzettin-dinamo","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/idil-lxxxviii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşa Görünme', 'kusa-gorunme-asaf-halet-celebi-jadfp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her sabah nafakamı getirir bir kuş

nereye kaçayım

                o kuşun elinden

kuyulara saklansam

kuyulara girer

tavan aralarına kaçsam

tavan aralarını bilir

tabutlukta yatsam

gelir beni bulur sabahları

gel kız

tabutluğa gir benimle

memelerin kan içinde

bacakların yaralı

nafakamı beraber yiyelim

ve paçavraların ısıtmıyor diye bana sokul

gel kız

tabutluğun içinde yat benimle

yalnız kuşa görünme sabahları', 'her sabah nafakamı getirir bir kuş nereye kaçayım                 o kuşun elinden kuyulara saklansam kuyulara girer tavan aralarına kaçsam t...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kusa-gorunme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halayıklarım', 'halayiklarim-asaf-halet-celebi-6ws98', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'iki taşı birbirine vurup

acayip âleminden çıkardın

ağzı var

                dili yok

                        halayıklarımı

zebercetten sarayımdaki halayıklarım

saz benizli

                badem gözlüdürler

saçları salkım salkım

                        omuzlarındadır

ve yaptıklari işi sessiz yaparlar

zebercetten sarayımda hamamlar yaptırdım

tepe camları zümrütten

                        ve akîki yemâniden

ve kurnası var

                necef taşından', 'iki taşı birbirine vurup acayip âleminden çıkardın ağzı var                 dili yok                         halayıklarımı zebercetten saray...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/halayiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanlık', 'uyanlik-asaf-halet-celebi-8ttkh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'uykum geliyor

uykum geliyor

uzaklaşıyorum

                yaklaşıyorum

kendimden

                kendime

sevdiğim havaları rahat dinliyorum

şekil keskinlikleri körleşiyor

ağırlıklar kalkıyor

çıkıyorum

        bu âlemlerden

uykum geliyor

uykum geliyor

uyanık yollar yürüyorum

uykuda yollar yürüyorum

uykuda insanlar görüyorum

niçin gördüğümü bilemiyorum

                                uykum geliyor

                                uykum geliyor', 'uykum geliyor uykum geliyor uzaklaşıyorum                 yaklaşıyorum kendimden                 kendime sevdiğim havaları rahat dinliyorum ...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi']::text[], 8.5, '{"poet":"Asaf Halet Çelebi","poet_slug":"asaf-halet-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uyanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışına', 'bakisina-necip-duru-kjr61', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çok sağanak bakıyorsun

taşımaz dallarım, ağır

öyle bakma kıyametim olacak

eriyor buzullarım

çok harlı nazarın

sabrımsa

küçük bir nehir', 'çok sağanak bakıyorsun taşımaz dallarım, ağır öyle bakma kıyametim olacak eriyor buzullarım çok harlı nazarın sabrımsa küçük bir nehir...', ARRAY['Türk Edebiyatı','Şiir','Necip Duru']::text[], 8.5, '{"poet":"Necip Duru","poet_slug":"necip-duru","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bakisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
